Uint8List _prepareMyAvatarPngOnWorker(Uint8List bytes) {
  final decoded = img.decodeImage(bytes);
  if (decoded == null) {
    throw StateError('Unsupported image');
  }

  final side = decoded.width < decoded.height ? decoded.width : decoded.height;
  final x = (decoded.width - side) ~/ 2;
  final y = (decoded.height - side) ~/ 2;
  final cropped = img.copyCrop(decoded, x: x, y: y, width: side, height: side);
  final resized = img.copyResize(
    cropped,
    width: 512,
    height: 512,
    interpolation: img.Interpolation.average,
  );
  return Uint8List.fromList(img.encodePng(resized));
}

Uint8List? _encodeProfileMetaAvatarPngOnWorker(Uint8List bytes) {
  return AppController.encodeProfileMetaAvatarPngForTesting(bytes);
}

Uint8List? _encodeProfileMetaAvatarPngLegacyOnWorker(Uint8List bytes) {
  return AppController._encodeProfileMetaAvatarPngInternal(
    bytes,
    maxAvatarPngBytes: 120000,
  );
}

String _pushRegistrationDiagnosticsErrorSummary(Object error) {
  final raw = error.toString().trim().replaceAll(RegExp(r'\s+'), ' ');
  if (raw.isNotEmpty) {
    return raw.length <= 240 ? raw : raw.substring(0, 240);
  }
  return error.runtimeType.toString();
}

String _pushDiagnosticsIsoLabel(int ms) {
  if (ms <= 0) {
    return 'never';
  }
  return DateTime.fromMillisecondsSinceEpoch(ms).toIso8601String();
}

class PushRegistrationDiagnostics {
  const PushRegistrationDiagnostics({
    required this.platform,
    required this.firebaseReady,
    required this.lastFirebaseInitAtMs,
    this.firebaseInitError,
    this.permissionStatus,
    this.permissionError,
    required this.lastPermissionAtMs,
    required this.currentTokenPresent,
    required this.lastTokenFetchAtMs,
    this.lastTokenFetchError,
    required this.runtimeTokenPresent,
    required this.lastSyncedTokenPresent,
    required this.syncInFlight,
    required this.lastSyncAttemptAtMs,
    required this.lastSyncSuccessAtMs,
    this.lastSyncError,
    required this.nativePushDiagnosticsAvailable,
    this.iosFirebaseConfigured,
    required this.lastApnsRegisterRequestedAtMs,
    this.apnsTokenPresent,
    required this.lastApnsTokenAtMs,
    this.lastApnsRegisterError,
    this.nativePushDiagnosticsError,
  });

  final String platform;
  final bool firebaseReady;
  final int lastFirebaseInitAtMs;
  final String? firebaseInitError;
  final String? permissionStatus;
  final String? permissionError;
  final int lastPermissionAtMs;
  final bool currentTokenPresent;
  final int lastTokenFetchAtMs;
  final String? lastTokenFetchError;
  final bool runtimeTokenPresent;
  final bool lastSyncedTokenPresent;
  final bool syncInFlight;
  final int lastSyncAttemptAtMs;
  final int lastSyncSuccessAtMs;
  final String? lastSyncError;
  final bool nativePushDiagnosticsAvailable;
  final bool? iosFirebaseConfigured;
  final int lastApnsRegisterRequestedAtMs;
  final bool? apnsTokenPresent;
  final int lastApnsTokenAtMs;
  final String? lastApnsRegisterError;
  final String? nativePushDiagnosticsError;

  String get statusCode {
    if ((firebaseInitError ?? '').trim().isNotEmpty) {
      return 'firebase_init_failed';
    }
    if (!firebaseReady) {
      return 'firebase_not_ready';
    }
    if (platform.isEmpty) {
      return 'unsupported_platform';
    }
    if (platform == 'ios') {
      if ((nativePushDiagnosticsError ?? '').trim().isNotEmpty) {
        return 'apns_diag_unavailable';
      }
      if (nativePushDiagnosticsAvailable && iosFirebaseConfigured == false) {
        return 'ios_firebase_not_configured';
      }
      if ((lastApnsRegisterError ?? '').trim().isNotEmpty) {
        return 'apns_register_failed';
      }
      if (nativePushDiagnosticsAvailable && apnsTokenPresent == false) {
        return 'apns_token_missing';
      }
    }
    if ((permissionStatus ?? '').trim() == 'denied') {
      return 'permission_denied';
    }
    if ((permissionStatus ?? '').trim() == 'request_error') {
      return 'permission_request_failed';
    }
    if (!currentTokenPresent) {
      if ((lastTokenFetchError ?? '').trim().isNotEmpty) {
        return 'token_fetch_failed';
      }
      return 'token_missing';
    }
    if (!runtimeTokenPresent) {
      return 'runtime_token_missing';
    }
    if (syncInFlight) {
      return 'sync_in_progress';
    }
    if ((lastSyncError ?? '').trim().isNotEmpty) {
      return 'sync_failed';
    }
    if (lastSyncedTokenPresent && lastSyncSuccessAtMs > 0) {
      return 'synced';
    }
    return 'pending_sync';
  }

  List<String> technicalLines() {
    return <String>[
      'Push status: $statusCode',
      'Push platform: ${platform.isEmpty ? 'unknown' : platform}',
      'Push firebase ready: ${firebaseReady ? 'true' : 'false'}',
      'Push native diagnostics available: ${nativePushDiagnosticsAvailable ? 'true' : 'false'}',
      if ((firebaseInitError ?? '').trim().isNotEmpty)
        'Push firebase init error: ${firebaseInitError!.trim()}',
      if (platform == 'ios' && iosFirebaseConfigured != null)
        'Push iOS Firebase configured: ${iosFirebaseConfigured! ? 'true' : 'false'}',
      if (platform == 'ios' && apnsTokenPresent != null)
        'Push APNs token present: ${apnsTokenPresent! ? 'true' : 'false'}',
      if ((permissionStatus ?? '').trim().isNotEmpty)
        'Push permission status: ${permissionStatus!.trim()}',
      if ((permissionError ?? '').trim().isNotEmpty)
        'Push permission error: ${permissionError!.trim()}',
      'Push current token present: ${currentTokenPresent ? 'true' : 'false'}',
      'Push runtime token present: ${runtimeTokenPresent ? 'true' : 'false'}',
      'Push last synced token present: ${lastSyncedTokenPresent ? 'true' : 'false'}',
      'Push sync in flight: ${syncInFlight ? 'true' : 'false'}',
      'Push firebase init at: ${_pushDiagnosticsIsoLabel(lastFirebaseInitAtMs)}',
      if (platform == 'ios')
        'Push APNs registration requested at: ${_pushDiagnosticsIsoLabel(lastApnsRegisterRequestedAtMs)}',
      if (platform == 'ios')
        'Push APNs token registered at: ${_pushDiagnosticsIsoLabel(lastApnsTokenAtMs)}',
      'Push permission checked at: ${_pushDiagnosticsIsoLabel(lastPermissionAtMs)}',
      'Push token fetched at: ${_pushDiagnosticsIsoLabel(lastTokenFetchAtMs)}',
      if ((lastTokenFetchError ?? '').trim().isNotEmpty)
        'Push token fetch error: ${lastTokenFetchError!.trim()}',
      'Push last sync attempt: ${_pushDiagnosticsIsoLabel(lastSyncAttemptAtMs)}',
      'Push last sync success: ${_pushDiagnosticsIsoLabel(lastSyncSuccessAtMs)}',
      if ((lastApnsRegisterError ?? '').trim().isNotEmpty)
        'Push APNs register error: ${lastApnsRegisterError!.trim()}',
      if ((nativePushDiagnosticsError ?? '').trim().isNotEmpty)
        'Push native diagnostics error: ${nativePushDiagnosticsError!.trim()}',
      if ((lastSyncError ?? '').trim().isNotEmpty)
        'Push last sync error: ${lastSyncError!.trim()}',
    ];
  }
}

