enum SharedAudioTrackKind { attachment, profile }

class AttachmentFileSendRequest {
  const AttachmentFileSendRequest({
    required this.filePath,
    this.mime,
    this.caption,
    this.fileName,
    this.width,
    this.height,
    this.durationMs,
    this.thumbB64,
    this.musicTitle,
    this.musicArtist,
  });

  final String filePath;
  final String? mime;

  /// Optional caption shown inside the same bubble (Telegram-style). For an
  /// album only the first request's caption is used.
  final String? caption;

  /// Original file name (e.g. the picked "report.pdf"). Null means NO name:
  /// the attachment renders as a photo/video, not a document (there is no
  /// basename fallback — see `_validateAttachmentFileRequests`).
  final String? fileName;

  /// Подсказки от окна отправки компьютера — для того, что контроллер сам
  /// из файла не достаёт: размеры и длительность ролика, миниатюра по его
  /// кадру. У снимков размеры и миниатюра по-прежнему считаются из самих
  /// байтов, подсказка нужна только когда этого не вышло. Телефон их не
  /// передаёт — для него ничего не меняется.
  final int? width;
  final int? height;
  final int? durationMs;
  final String? thumbB64;

  /// Название и исполнитель песни, прочитанные окном отправки. Контроллер
  /// тегов сам не читает.
  final String? musicTitle;
  final String? musicArtist;
}

