class SharedAudioPlaybackState {
  const SharedAudioPlaybackState({
    this.currentTrack,
    this.queue = const <SharedAudioTrack>[],
    this.queueIndex = -1,
    this.loadingTrackId,
    this.playing = false,
    this.position = Duration.zero,
    this.duration = Duration.zero,
    this.speed = 1.0,
  });

  final SharedAudioTrack? currentTrack;
  final List<SharedAudioTrack> queue;
  final int queueIndex;
  final String? loadingTrackId;
  final bool playing;
  final Duration position;
  final Duration duration;

  /// Скорость воспроизведения, 1.0 — обычная.
  ///
  /// 🔴 ДОБАВОЧНОЕ (15.09.2026), умолчание прежнее. Мобильные экраны поля не
  /// читают и о нём не знают — их вид не меняется ни на точку. Ускорение нужно
  /// голосовым на компьютере: их слушают за работой, и минутное сообщение на
  /// полутора скоростях — это сорок секунд, а не минута.
  final double speed;

  bool get hasTrack => currentTrack != null;

  SharedAudioPlaybackState copyWith({
    SharedAudioTrack? currentTrack,
    bool clearCurrentTrack = false,
    List<SharedAudioTrack>? queue,
    int? queueIndex,
    String? loadingTrackId,
    bool clearLoadingTrackId = false,
    bool? playing,
    Duration? position,
    Duration? duration,
    double? speed,
  }) {
    return SharedAudioPlaybackState(
      currentTrack: clearCurrentTrack
          ? null
          : (currentTrack ?? this.currentTrack),
      queue: queue ?? this.queue,
      queueIndex: queueIndex ?? this.queueIndex,
      loadingTrackId: clearLoadingTrackId
          ? null
          : (loadingTrackId ?? this.loadingTrackId),
      playing: playing ?? this.playing,
      position: position ?? this.position,
      duration: duration ?? this.duration,
      speed: speed ?? this.speed,
    );
  }
}

