  static const _prefsDeviceIdKey = 'device_id';
  static const _prefsProfileIdKey = 'profile_id';
  // FIX-C2 (zombie device_id durability): a DURABLE ledger of device_ids we
  // abandoned during a self-heal rotation but have not yet confirmed deleted on
  // the keys server. The in-memory `abandonedDeviceIds` list is lost if the
  // delete call fails (offline / 5xx) or the app dies mid-rotation, which leaks
  // the zombie forever. This survives restarts and is drained on every keys
  // setup until each delete confirms. JSON list of {pid, did, at} maps.
  static const _prefsPendingDeviceDeletesKey = 'pending_device_deletes_v1';
  static const _prefsI1RotationEnabledKey = 'i1_rotation_enabled_v1';
  static const _prefsI1AnnouncePendingKey = 'i1_announce_pending_v1';
  // Old device_id a state-loss rotation replaced; sent as the eviction hint
  // with the next register_proof and cleared once registration succeeds.
  static const _prefsI1ReplacesHintKey = 'i1_replaces_hint_v1';
  // Key inside the DB-side local_kv table (NOT prefs): the stamp must live in
  // the database FILE so it travels with quarantine/restore.
  static const _dbKvOwnDeviceIdKey = 'own_device_id_v1';
  // FIX-C1: marks that this install has completed its first-launch identity
  // hygiene pass. Absent on a genuinely fresh install (prefs are wiped on
  // uninstall/data-clear on both iOS and Android), present forever after.
  static const _prefsInstallSentinelKey = 'install_sentinel_v1';
  // Sticky "this profile has had a paid entitlement at least once". Set the
  // first time the tier resolves to paid and NEVER cleared, so the premium
  // upsell can be shown ONLY to users who have never subscribed (the current
  // tier alone can't tell a lapsed subscriber apart from a never-subscriber).
  static const _prefsEverHadEntitlementKey = 'premium_ever_had_entitlement_v1';
  static const _prefsRelayNextSeqKey = 'relay_next_seq';
  static const _prefsKeysPublishedKeyPrefix = 'keys_published_v1';
  static const _prefsAllowMissingCurrentDeviceRepairOnceKey =
      'allow_missing_current_device_repair_once_v1';
  static const _prefsServerBindingKey = 'server_binding_v1';
  static const _prefsLastKeysPublishAtMsKey = 'last_keys_publish_at_ms_v1';
  static const _keysPublishRefreshIntervalMs = 12 * 60 * 60 * 1000;
  static const _prefsLastMetaPublishAtMsKey = 'last_meta_publish_at_ms_v1';
  static const _prefsLastMetaRefreshAtMsKey = 'last_meta_refresh_at_ms_v1';
  static const _prefsDemoSeededKey = 'demo_seeded_v1';
  static const _prefsDemoSeedVersionKey = 'demo_seed_version_v1';
  // Set once after a demo-disabled build has swept the local store clean, so
  // the deep contact scan only runs when there is actually something to purge.
  static const _prefsDemoPurgedKey = 'demo_purged_v1';
  // 7 -> 8 (13.09.2026): у показательных комнат убрано поддельное «фото» —
  // квадрат с белым кругом. Без поднятия версии правка не дошла бы до уже
  // заполненных установок: путь к картинке лежит в базе, и повторного
  // заполнения без смены версии не происходит.
  static const int _demoSeedVersion = 8;
  static const _prefsBlockUnverifiedKey = 'block_unverified_v1';
  static const _prefsScreenPrivacyKey = 'screen_privacy_v1';
  static const _prefsHideAddressInCallsKey = 'hide_address_in_calls_v1';
  static const _prefsDarkModeKey = 'dark_mode_v1';
  static const _prefsAppLocaleKey = 'app_locale_v1';
  static const _prefsMyNicknameKey = 'my_nickname_v1';
  static const _prefsMyBioKey = 'settings_account_bio_v1';
  // Optional cosmetic (unsigned) profile fields.
  static const _prefsMyFrameIdKey = 'secretly_my_frame_id';
  static const _prefsMyEmojiStatusKey = 'secretly_my_emoji_status';
  static const _prefsMyCoverIdKey = 'secretly_my_cover_id';
  static const _prefsMyCoverImageKey = 'secretly_my_cover_image_path';
  static const _prefsMyCoverVideoKey = 'secretly_my_cover_video_path';
  static const _prefsShareNicknameInQrKey = 'share_nickname_in_qr_v1';
  static const _prefsDiscoverableByNicknameKey = 'discoverable_by_nickname_v1';
