  static const _prefsPendingStartupWarningKey = 'pending_startup_warning_v1';
  static const _prefsCallsEnabledKey = 'calls_enabled_v1';
  static const _prefsIncomingCallsEnabledKey = 'incoming_calls_enabled_v1';
  static const _prefsIncomingScreenShareEnabledKey =
