  static const _prefsChatWallpaperAnimModeKey = 'chat_wallpaper_anim_mode_v1';
  static const _prefsChatWallpaperConductKey = 'chat_wallpaper_conduct_v1';
  // ── Power / heat settings (2026-07-31) ────────────────────────────────────
  //
  // Both default to ON so nothing changes for anyone who does not go looking.
  // They exist because the iOS look has a real, continuous cost that the user
  // could not previously opt out of: the bubble glass was a compile-time
  // `!Platform.isAndroid`, so a phone that ran hot had no lever at all.
  static const _prefsBubbleGlassKey = 'power_bubble_glass_enabled_v1';
  static const _prefsFrostedPanelsKey = 'power_frosted_panels_enabled_v1';

  bool _bubbleGlassEnabled = true;
  bool _frostedPanelsEnabled = true;

  /// Glass incoming bubbles (a window into the pre-blurred wallpaper).
  ///
  /// The heaviest of the two: it keeps a live blurred wallpaper texture alive
  /// and samples it per bubble. Android never built it at all.
  bool get bubbleGlassEnabled => _bubbleGlassEnabled;

  /// Frosted (blurred) panels — the composer island, headers, sheets.
  ///
  /// Cheaper per element than the bubbles but there are many of them, and each
  /// is a real blur of whatever is behind it.
  bool get frostedPanelsEnabled => _frostedPanelsEnabled;

  Future<void> setBubbleGlassEnabled(bool enabled) async {
    if (_bubbleGlassEnabled == enabled) return;
    _bubbleGlassEnabled = enabled;
    _changed.add(null);
    final prefs = await SharedPreferences.getInstance();
    await prefs.setBool(_prefsBubbleGlassKey, enabled);
  }

  Future<void> setFrostedPanelsEnabled(bool enabled) async {
    if (_frostedPanelsEnabled == enabled) return;
    _frostedPanelsEnabled = enabled;
    // Islands live all over the tree and most never see this controller, so the
    // notifier is what actually reaches them (see PanelPrefs). Keeping the two
    // in step HERE — one setter, one loader — is what stops half the app from
    // staying blurred after a toggle.
    PanelPrefs.frostedEnabled.value = enabled;
    _changed.add(null);
    final prefs = await SharedPreferences.getInstance();
    await prefs.setBool(_prefsFrostedPanelsKey, enabled);
  }

  void _loadPowerSettings(SharedPreferences prefs) {
    _bubbleGlassEnabled = prefs.getBool(_prefsBubbleGlassKey) ?? true;
    _frostedPanelsEnabled = prefs.getBool(_prefsFrostedPanelsKey) ?? true;
    PanelPrefs.frostedEnabled.value = _frostedPanelsEnabled;
  }

