  Future<void> setAppHapticsEnabled(bool value) async {
    _appHapticsEnabled = value;
    final prefs = _prefs ?? await SharedPreferences.getInstance();
    await prefs.setBool(_prefsAppHapticsKey, value);
    await prefs.setBool(_settingsAppHapticsKey, value);
    if (!_changed.isClosed) {
      _changed.add(null);
    }
  }

  Future<void> triggerUiHaptic() async {
    if (!_appHapticsEnabled || kIsWeb) {
      return;
    }
    if (Platform.isAndroid) {
      try {
        final didVibrate = await _nativeHapticsChannel.invokeMethod<bool>(
          'keyboardTap',
        );
        if (didVibrate == true) {
          return;
        }
      } catch (_) {}
      try {
        final didVibrate = await _nativeHapticsChannel.invokeMethod<bool>(
          'shortTap',
          const <String, dynamic>{'durationMs': 10, 'amplitude': 24},
        );
        if (didVibrate == true) {
          return;
        }
      } catch (_) {}
    }
    try {
      await HapticFeedback.selectionClick();
    } catch (_) {}
  }

  void _handleSharedAudioPlayerState(PlayerState state) {
    final processingState = state.processingState;
    if (processingState == ProcessingState.completed) {
      if (_sharedAudioAdvancing) {
        return;
      }
      final nextIndex = _sharedAudioQueueIndex + 1;
      if (nextIndex >= 0 && nextIndex < _sharedAudioQueue.length) {
        _sharedAudioAdvancing = true;
        unawaited(() async {
          try {
            await playSharedAudioQueue(
              queue: _sharedAudioQueue,
              index: nextIndex,
            );
          } finally {
            _sharedAudioAdvancing = false;
          }
        }());
      } else {
        unawaited(_sharedAudioPlayer.pause());
        unawaited(_sharedAudioPlayer.seek(Duration.zero));
        _sharedAudioPlayback.value = _sharedAudioPlayback.value.copyWith(
          playing: false,
          position: Duration.zero,
          clearLoadingTrackId: true,
        );
        unawaited(_syncNativeMediaPlayback(force: true));
      }
      return;
    }

    final isLoading =
        processingState == ProcessingState.loading ||
        processingState == ProcessingState.buffering;
    _sharedAudioPlayback.value = _sharedAudioPlayback.value.copyWith(
      playing: state.playing,
      clearLoadingTrackId: !isLoading,
    );
    unawaited(_syncNativeMediaPlayback(force: true));
  }

  Future<void> _initNativeMediaControls() async {
    if (!_supportsNativeMediaControls) {
      return;
    }
    await _nativeMediaActionsSub?.cancel();
    _nativeMediaActionsSub = _nativeMediaActionsChannel
        .receiveBroadcastStream()
        .listen((event) {
          unawaited(_handleNativeMediaAction(event));
        });
    unawaited(_syncNativeMediaPlayback(force: true));
  }

  Future<void> _handleNativeMediaAction(dynamic event) async {
    String action = '';
    if (event is String) {
      action = event.trim().toLowerCase();
    } else if (event is Map) {
      action = '${event['action'] ?? ''}'.trim().toLowerCase();
    }
    if (action.isEmpty) {
      return;
    }
    switch (action) {
      case 'play':
        if (!_sharedAudioPlayer.playing) {
          await toggleSharedAudioPlayback();
        }
        return;
      case 'pause':
        if (_sharedAudioPlayer.playing) {
          await toggleSharedAudioPlayback();
        }
        return;
      case 'play_pause':
      case 'toggle':
        await toggleSharedAudioPlayback();
        return;
      case 'previous':
        await playPreviousSharedAudio();
        return;
      case 'next':
        await playNextSharedAudio();
        return;
      case 'stop':
      case 'close':
        await stopSharedAudio();
        return;
    }
  }

  Future<void> _syncNativeMediaPlayback({bool force = false}) async {
    if (!_supportsNativeMediaControls) {
      return;
    }
    final playback = _sharedAudioPlayback.value;
    final current = playback.currentTrack;
    if (current == null) {
      if (!force && _lastNativeMediaSyncSignature == '__clear__') {
        return;
      }
      _lastNativeMediaSyncSignature = '__clear__';
      try {
        await _nativeMediaNotifChannel.invokeMethod<void>('clear');
      } on MissingPluginException {
        return;
      } catch (_) {
        return;
      }
      return;
    }

    final durationMs = math.max(0, playback.duration.inMilliseconds);
    final positionMs = durationMs > 0
        ? playback.position.inMilliseconds.clamp(0, durationMs)
        : math.max(0, playback.position.inMilliseconds);
    final artworkPath = current.artworkPath?.trim();
    final normalizedArtworkPath =
        artworkPath != null &&
            artworkPath.isNotEmpty &&
            File(artworkPath).existsSync()
        ? artworkPath
        : null;
    final canSkipPrevious = _sharedAudioQueueIndex > 0;
    final canSkipNext =
        _sharedAudioQueueIndex >= 0 &&
        _sharedAudioQueueIndex < _sharedAudioQueue.length - 1;
    final signature = [
      current.trackId,
      playback.playing,
      playback.queueIndex,
      durationMs,
      positionMs ~/ 1000,
      canSkipPrevious,
      canSkipNext,
      normalizedArtworkPath ?? '',
    ].join('|');
    if (!force && signature == _lastNativeMediaSyncSignature) {
      return;
    }
    _lastNativeMediaSyncSignature = signature;

    try {
      await _nativeMediaNotifChannel.invokeMethod<void>('update', {
        'trackId': current.trackId,
        'title': current.title,
        'artist': current.artist,
        'album': 'Secretly',
        'artworkPath': normalizedArtworkPath,
        'playing': playback.playing,
        'positionMs': positionMs,
        'durationMs': durationMs,
        'canSkipPrevious': canSkipPrevious,
        'canSkipNext': canSkipNext,
      });
    } on MissingPluginException {
      return;
    } catch (_) {
      return;
    }
  }

  Future<void> playSharedAudioQueue({
    required List<SharedAudioTrack> queue,
    required int index,
  }) async {
    if (queue.isEmpty || index < 0 || index >= queue.length) {
      return;
    }
    final normalizedQueue = List<SharedAudioTrack>.unmodifiable(queue);
    final track = normalizedQueue[index];
    final previousState = _sharedAudioPlayback.value;
    final previousQueue = _sharedAudioQueue;
    final previousQueueIndex = _sharedAudioQueueIndex;

    _sharedAudioQueue = normalizedQueue;
    _sharedAudioQueueIndex = index;
    _sharedAudioPlayback.value = previousState.copyWith(
      currentTrack: track,
      queue: normalizedQueue,
      queueIndex: index,
      loadingTrackId: track.trackId,
      position: Duration.zero,
      duration: Duration.zero,
      playing: false,
    );
    unawaited(_syncNativeMediaPlayback(force: true));

    try {
      final resolvedPath = (await track.resolveFilePath()).trim();
      if (resolvedPath.isEmpty) {
        throw StateError('Missing audio file path');
      }
      await _sharedAudioPlayer.stop();
      final duration = await _sharedAudioPlayer.setFilePath(resolvedPath);
      _sharedAudioPlayback.value = _sharedAudioPlayback.value.copyWith(
        currentTrack: track,
        queue: normalizedQueue,
        queueIndex: index,
        clearLoadingTrackId: true,
        position: Duration.zero,
        duration: duration ?? Duration.zero,
      );
      unawaited(_syncNativeMediaPlayback(force: true));
      await _sharedAudioPlayer.play();
    } catch (_) {
      _sharedAudioQueue = previousQueue;
      _sharedAudioQueueIndex = previousQueueIndex;
      _sharedAudioPlayback.value = previousState;
      unawaited(_syncNativeMediaPlayback(force: true));
      rethrow;
    }
  }

  Future<void> toggleSharedAudioTrack({
    required List<SharedAudioTrack> queue,
    required int index,
  }) async {
    if (queue.isEmpty || index < 0 || index >= queue.length) {
      return;
    }
    final track = queue[index];
    final current = _sharedAudioPlayback.value.currentTrack;
    if (current != null && current.trackId == track.trackId) {
      _sharedAudioQueue = List<SharedAudioTrack>.unmodifiable(queue);
      _sharedAudioQueueIndex = index;
      _sharedAudioPlayback.value = _sharedAudioPlayback.value.copyWith(
        queue: _sharedAudioQueue,
        queueIndex: index,
      );
      unawaited(_syncNativeMediaPlayback(force: true));
      if (_sharedAudioPlayer.playing) {
        await _sharedAudioPlayer.pause();
      } else {
        final duration = _sharedAudioPlayback.value.duration;
        final position = _sharedAudioPlayback.value.position;
        if (duration > Duration.zero && position >= duration) {
          await _sharedAudioPlayer.seek(Duration.zero);
        }
        await _sharedAudioPlayer.play();
      }
      return;
    }
    await playSharedAudioQueue(queue: queue, index: index);
  }

  Future<void> toggleSharedAudioPlayback() async {
    final current = _sharedAudioPlayback.value.currentTrack;
    if (current == null) return;
    if (_sharedAudioPlayer.playing) {
      await _sharedAudioPlayer.pause();
      return;
    }
    final duration = _sharedAudioPlayback.value.duration;
    final position = _sharedAudioPlayback.value.position;
    if (duration > Duration.zero && position >= duration) {
      await _sharedAudioPlayer.seek(Duration.zero);
    }
    await _sharedAudioPlayer.play();
  }

  /// Скорость воспроизведения голосовых и аудио. Добавочное: мобильные экраны
  /// её не зовут и не меняются.
  ///
  /// Зажата в 0.5…3.0 — за этими границами речь перестаёт быть речью, а
  /// движок на некоторых системах просто отказывает.
  Future<void> setSharedAudioSpeed(double speed) async {
    final next = speed.clamp(0.5, 3.0);
    if ((next - _sharedAudioPlayback.value.speed).abs() < 0.001) return;
    try {
      await _sharedAudioPlayer.setSpeed(next);
    } catch (_) {
      // Движок отказал — оставляем прежнюю скорость, а не врём подписью.
      return;
    }
    _sharedAudioPlayback.value = _sharedAudioPlayback.value.copyWith(
      speed: next,
    );
  }

  /// Громкость общего плеера, 0..1.
  ///
  /// ДОБАВОЧНОЕ (24.09.2026): зовёт только компьютер — ползунок громкости в
  /// островке «сейчас играет». Мобильные экраны громкость не трогают, и их
  /// поведение не меняется ни на слог.
  Future<void> setSharedAudioVolume(double volume) async {
    final v = volume.isFinite ? volume.clamp(0.0, 1.0).toDouble() : 1.0;
    await _sharedAudioPlayer.setVolume(v);
  }

  Future<void> seekSharedAudio(Duration position) async {
    final duration = _sharedAudioPlayback.value.duration;
    final clamped = duration > Duration.zero
        ? (position > duration
              ? duration
              : (position < Duration.zero ? Duration.zero : position))
        : (position < Duration.zero ? Duration.zero : position);
    await _sharedAudioPlayer.seek(clamped);
    unawaited(_syncNativeMediaPlayback(force: true));
  }

  Future<void> playPreviousSharedAudio() async {
    final previousIndex = _sharedAudioQueueIndex - 1;
    if (previousIndex < 0 || previousIndex >= _sharedAudioQueue.length) {
      return;
    }
    await playSharedAudioQueue(queue: _sharedAudioQueue, index: previousIndex);
  }

  Future<void> playNextSharedAudio() async {
    final nextIndex = _sharedAudioQueueIndex + 1;
    if (nextIndex < 0 || nextIndex >= _sharedAudioQueue.length) {
      return;
    }
    await playSharedAudioQueue(queue: _sharedAudioQueue, index: nextIndex);
  }

  Future<void> stopSharedAudio() async {
    _sharedAudioQueue = const <SharedAudioTrack>[];
    _sharedAudioQueueIndex = -1;
    await _sharedAudioPlayer.stop();
    _sharedAudioPlayback.value = const SharedAudioPlaybackState();
    unawaited(_syncNativeMediaPlayback(force: true));
  }

  final Map<String, int> _contactVerifyRefreshAtMs = <String, int>{};
  final Map<String, _RecipientDevicesCacheEntry>
  _recipientDevicesCacheByProfileId = <String, _RecipientDevicesCacheEntry>{};
  final Set<String> _knownOwnDeviceIds = <String>{};
  final Map<String, int> _recipientDevicesRateLimitUntilMsByProfileId =
      <String, int>{};

  /// Messages queued because the recipient had no registered devices yet,
  /// mapped by peer profile ID.  Retried in background by the watchdog.
  final Map<String, List<_PendingNoDeviceEntry>> _pendingNoDeviceSend =
      <String, List<_PendingNoDeviceEntry>>{};

  /// Last time (ms) we tried the device-lookup retry for each profile.
  final Map<String, int> _noDeviceRetryLastCheckMs = <String, int>{};

  /// Consecutive retries that still resolved ZERO devices, per profile. Drives
  /// the exponential backoff in [_retryPendingNoDeviceSend] — see
  /// [_noDeviceRetryMaxIntervalMs] for why a fixed interval is not safe here.
  final Map<String, int> _noDeviceRetryAttempts = <String, int>{};
  final Map<String, Future<void>> _outboundEncryptQueueByPeerDevice =
      <String, Future<void>>{};
  final Map<String, Future<RelayRoomCallSnapshot?>> _roomCallRefreshInFlight =
      <String, Future<RelayRoomCallSnapshot?>>{};
  final Map<String, int> _deviceProfileLookupAtMs = <String, int>{};
  // Per-msgId counter of failed `_handleDelivered` attempts. After
  // `_deliveredDecryptMaxAttempts` we ack-and-drop unconditionally to break
  // the relay reorder buffer deadlock when a peer is stuck in a bad ratchet
  // state.
  //
  // This map is now only a same-process mirror; the budget that decides is
  // persisted (`AppDb.inboundDecryptFailureBump`). Keeping the count in memory
  // alone was reasoned as "a restart grants a few more retries, which is the
  // desired behaviour" — true on Android, false on iOS, where the OS kills the
  // app seconds after each background wake. There the count restarted at zero
  // every push and NEVER reached three, so the wire was never parked and never
  // NACKed, and the sender was never told to rekey. Messages stayed in the
  // relay mailbox for hours, invisible. Field-confirmed 2026-07-22.
  final Map<String, int> _deliveredDecryptAttempts = <String, int>{};
  static const int _deliveredDecryptMaxAttempts = 3;
  // Wall-clock half of the budget: a session heal is a round trip, so give it
  // minutes before parking, and park even if attempts never accumulate.
  static const int _deliveredDecryptMaxFailingForMs = 10 * 60 * 1000;

  /// The same budget when there is NO ratchet session with the sender at all.
  ///
  /// 🔴 FIELD (2026-08-01): "a notification arrived but the chat is empty",
  /// and the message appeared ten minutes later. Ten minutes IS this budget —
  /// the wire could not be opened, and the client patiently retried before
  /// parking it and asking the sender to re-handshake.
  ///
  /// The wait is sound while a session EXISTS: a heal is a round trip, and
  /// tearing sessions down on the first miss is what produced the reset storms
  /// of И-4. But with no session row for this sender, no amount of waiting can
  /// help — nothing on this device can ever open that ciphertext until the peer
  /// sends a fresh handshake. Every extra second is a person staring at a
  /// notification for a message that is not there.
  ///
  /// So: session present ⇒ keep the patient budget. No session ⇒ ask for the
  /// handshake within a minute.
  static const int _deliveredDecryptNoSessionFailingForMs = 60 * 1000;

  /// Test windows onto the two budgets. Exposed so the split is pinned by a
  /// test instead of by a comment — the field symptom it fixes is invisible in
  /// code review.
  @visibleForTesting
  static int get deliveredDecryptMaxFailingForMsForTest =>
      _deliveredDecryptMaxFailingForMs;

  @visibleForTesting
  static int get deliveredDecryptNoSessionFailingForMsForTest =>
      _deliveredDecryptNoSessionFailingForMs;

  /// How long a failing wire may keep retrying before it is parked and the
  /// sender is asked to re-establish.
  ///
  /// Answers the short budget only when we hold NO session for this sender —
  /// the one case where waiting provably cannot help. Any doubt (missing
  /// sender id, storage error) falls back to the long, patient budget: parking
  /// too eagerly costs a session reset, which is the churn И-4 exists to stop.
  Future<int> _decryptFailingBudgetMsFor(AppDb db, String? senderDeviceId) async {
    final dev = (senderDeviceId ?? '').trim();
    if (dev.isEmpty) return _deliveredDecryptMaxFailingForMs;
    try {
      final row = await db.sessionV3Get(dev);
      if (row == null) return _deliveredDecryptNoSessionFailingForMs;
    } catch (_) {
      // Storage hiccup: prefer the patient budget. See the fallback rule above.
    }
    return _deliveredDecryptMaxFailingForMs;
  }

  // И-4a (2026-07-24): the
  // receiver-side reactive session reset in _handleDelivered used to fire on the
  // FIRST decrypt miss of ANY class — a transient out-of-order / DB-lock /
  // too-many-skipped miss tore the session down just like a genuine chain
  // divergence, bypassing the decrypt budget entirely. That is the root of the
  // "сессия вдруг поменялась" churn (and its glare, since both peers do it to
  // each other). Under this gate a receiver-side reactive reset becomes a LAST
  // resort: only a PERSISTENT genuine-MAC divergence (the chain truly diverged,
  // seen ≥ _i4ReactiveResetMinConsecutiveFailures times in a row with NO
  // successful decrypt in between), never a transient miss, and never an
  // epoch-ahead wire (the peer's rekey is already inbound → A4). Everything else
  // recovers the Signal way: quarantine + NACK + the sender's one-directional
  // resend (f62738fe). Mutable + fromEnvironment for tests + a kill-switch;
  // ships default ON (field-proven 1.7.4+403 2026-07-24: 31 suppressions, 0
  // spurious resets). Pass --dart-define=SECRETLY_I4A_REACTIVE_RESET_GATE=false to
  // force the legacy pre-И-4 behavior back (fail-safe kill-switch).
  // NOTE: `bool.fromEnvironment` only substitutes the --dart-define value in a
  // CONST context. A mutable `static bool = bool.fromEnvironment(...)` compiles to
  // a runtime call that returns the DEFAULT (false) — which is exactly why the
  // 1.7.4+401 field-proof build ran with this gate OFF despite the define being
  // passed. Read the define into a `const`, then seed the mutable (test-overridable)
  // field from it.
  static const bool _i4aReactiveResetGateEnabledEnv =
      bool.fromEnvironment('SECRETLY_I4A_REACTIVE_RESET_GATE', defaultValue: true);
  @visibleForTesting
  static bool i4aReactiveResetGateEnabled = _i4aReactiveResetGateEnabledEnv;
  static const int _i4ReactiveResetMinConsecutiveFailures = 3;

  // И-4h (2026-07-24, cause C1): the keys server only lists devices
  // seen (register/publish, NOT receive) within a 14-day RELATIVE liveness window,
  // so a companion device opened less than ~once/14 days relative to a busy
  // primary drops off the list. contactDevicesDeleteMissing then RAW-deleted that
  // device's session — forcing a fresh X3DH + "safety number changed" the moment
  // the idle device returned, a spontaneous session change with NO decrypt miss
  // at all. Under this gate we KEEP the session when pruning a merely-omitted
  // device: a returning idle device reuses it (no re-handshake); a genuinely
  // reinstalled device still resets via the authoritative identity-rotation path
  // (#9/#10). Ships default ON (field-proven 1.7.4+403 2026-07-24: relay device-
  // churn empty). Pass --dart-define=SECRETLY_I4H_KEEP_SESSION_ON_DEVICE_PRUNE=false
  // to force the legacy delete back (fail-safe kill-switch).
  // Same const-context requirement as i4aReactiveResetGateEnabled above.
  static const bool _i4hKeepSessionOnDevicePruneEnv =
      bool.fromEnvironment('SECRETLY_I4H_KEEP_SESSION_ON_DEVICE_PRUNE',
          defaultValue: true);
  @visibleForTesting
  static bool i4hKeepSessionOnDevicePrune = _i4hKeepSessionOnDevicePruneEnv;

  // И-4k (2026-07-24): the FIRST-MESSAGE-to-a-brand-new-account
  // orphan. When two devices establish sessions to each other for the very first
  // time (fresh account), BOTH directions race X3DH bootstrap: the first message
  // can land before the receiver's session settles → genuine-MAC undecryptable.
  // The receiver quarantines + NACKs, but in that same window the REVERSE session
  // isn't ready either, so the NACK never reaches the sender → the sender never
  // resends → the message's content is lost. Proven in the field 2026-07-24 (wire
  // 844d8103 dropped, "started arriving only from the 2nd message"). The sender
  // DOES reset its own session to heal the inbound direction, but that reset only
  // re-encrypts HELD scheduled wires (_refreshHeldScheduledWires) — never the
  // already-sent-undelivered ones. Under this gate, the two sender-side session-
  // CHANGE points also resend undelivered outbound to the peer under the fresh
  // session: (1) _dispatchSessionResetPing (WE reset — archived+deleted the old
  // session), and (2) _scheduleSessionConfirmPing (WE adopted the peer's reset —
  // our send session was replaced). So when EITHER side resets to heal inbound,
  // it ALSO recovers its orphaned outbound → the pair converges the Signal way.
  // Idempotent (the receiver dedups by payload_event_id, so a re-encrypt is never
  // a visible duplicate) and bounded (the resend has a re-entrancy guard +
  // per-event debounce + per-pass cap). Ships default ON alongside i4a/i4h
  // (1.7.4+404 2026-07-24: no regression in the field — new-account traffic
  // delivered 16/16 clean; the resend path stands ready for the race). Pass
  // --dart-define=SECRETLY_I4K_RESEND_ON_RESET=false to disable (fail-safe kill-
  // switch). Same const-context requirement as i4aReactiveResetGateEnabled above.
  static const bool _i4kResendUndeliveredOnResetEnv =
      bool.fromEnvironment('SECRETLY_I4K_RESEND_ON_RESET', defaultValue: true);
  @visibleForTesting
  static bool i4kResendUndeliveredOnReset = _i4kResendUndeliveredOnResetEnv;

  /// Сколько ждать перешифровку, прежде чем считать, что её не будет.
  ///
  /// Два реальных окна задают этот порог снизу и сверху. Снизу — законный
  /// случай: prekey-провод лежит в том же ящике и применяется за один проход
  /// насоса, то есть за секунды. Сверху — подметание карантина, которое идёт
  /// раз в 90 секунд и берёт запись не моложе 60 секунд: порог должен быть
  /// достижим в пределах одного сеанса, иначе лечение не запустится никогда.
  ///
  /// Две минуты лежат между ними с запасом: законный случай сюда не доходит,
  /// а застрявший доходит на первом же подметании.
  static const int _i4EpochAheadStuckGraceMs = 2 * 60 * 1000;

  /// Pure predicate for И-4a: may a receiver-side REACTIVE session reset fire for
  /// this inbound decrypt failure? When the gate is OFF this always returns true
  /// (exact pre-И-4 behavior). When ON, a reset is allowed ONLY for a persistent
  /// genuine-MAC divergence — never transient/out-of-order, never epoch-ahead,
  /// and not before the failure has repeated [minConsecutive] times without an
  /// intervening success. [consecutiveFailures] is the caller's per-peer
  /// counter, which resets to 0 on any successful decrypt.
  @visibleForTesting
  static bool i4ReactiveResetAllowed({
    required bool gateEnabled,
    required bool isEpochAhead,
    required bool isGenuineMac,
    required int consecutiveFailures,
    bool isBackground = false,
    int minConsecutive = _i4ReactiveResetMinConsecutiveFailures,
    /// How long this device has been stuck epoch-ahead WITHOUT a single
    /// successful decrypt. Zero means the streak just started.
    int epochAheadStuckMs = 0,
    int minEpochAheadStuckMs = _i4EpochAheadStuckGraceMs,
  }) {
    if (!gateEnabled) return true; // gate off → unchanged legacy behavior
    // И-4i: the background inbox isolate cannot COMPLETE a reset — the reset-ping
    // and NACK are both suppressed in _backgroundInboundMode — so a background
    // reset only DELETES the session and never heals it. Leave the wire parked
    // and let the foreground drive the (full) recovery.
    if (isBackground) return false;
    if (isEpochAhead) {
      // A4 said "the peer's rekey is already inbound", and refused a reset on
      // that basis — unconditionally, forever.
      //
      // 🔴 ПРЕДПОЛОЖЕНИЕ БЕЗ СРОКА ГОДНОСТИ (11.09.2026, живой аккаунт).
      //
      // Оно верно, когда перешифровка действительно лежит в том же ящике:
      // тогда она применяется за один проход насоса, то есть за секунды. Когда
      // её там нет — а в разобранном случае prekey-проводов не было НИ ОДНОГО
      // за весь запуск — каждое сообщение под новой эпохой парковалось, сброс
      // подавлялся 30 раз подряд (все с reason=epoch_ahead), и расклинить было
      // нечем. Сообщения не приходили третий запуск подряд.
      //
      // Это тот же класс ошибки, что уже ловили рядом: ветка replay ниже
      // описывает, как предположение «NACK всегда чинит» точно так же
      // запирало восстановление. Лечение то же — не отменять предположение, а
      // дать ему СРОК.
      //
      // Порог по стенным часам, а не только по числу попыток: повторы могут
      // идти пачкой за секунду, и счётчик сам по себе не отличает «насос ещё
      // не дошёл до prekey» от «prekey не существует». Ожидание же ограничено
      // тем, что перешифровка в том же ящике применяется за секунды.
      if (epochAheadStuckMs < minEpochAheadStuckMs) return false;
      return consecutiveFailures >= minConsecutive;
    }
    if (!isGenuineMac) return false; // transient → quarantine + relay redeliver
    return consecutiveFailures >= minConsecutive;
  }

  /// Forget a message's decrypt-failure budget once it is settled — decrypted,
  /// recovered from the journal, or parked. Both halves must go: leaving the
  /// persisted row behind would spend a later message's budget for it.
  void _clearDeliveredDecryptBudget(String msgId) {
    _deliveredDecryptAttempts.remove(msgId);
    final d = _db;
    if (d != null) unawaited(d.inboundDecryptFailureClear(msgId));
  }
  // Debounce session-reset ping per peer device (avoid hammering when many
  // backlog messages with the same broken state arrive). Stores wall-clock ms
  // of the last enqueued reset ping for that device.
  final Map<String, int> _sessionResetPingAtMs = <String, int>{};
  static const int _sessionResetPingDebounceMs = 30 * 1000;

  // ───────────────────────── журнал причин сброса ─────────────────────────
  //
  // 🔴 ЗАЧЕМ (23.08.2026, шаг ① плана из
