  /// Wire a headless controller for the background inbox isolate: exactly the
  /// runtime `_handleDelivered` needs (db, crypto, ratchet, keys, identity),
  /// and nothing else — no relay, no timers, no UI. The background fetcher owns
  /// the cross-isolate decrypt lease around every call, so this controller is
  /// the sole ratchet writer while it lives. Mirrors the shape of the testing
  /// seeds deliberately: that headless path is already exercised by the suite.
  Future<void> bootstrapForBackgroundInbound({
    required AppDb db,
    required CryptoProvider crypto,
    required RatchetSessionManagerV3 ratchetV3,
    required KeysClient keys,
    required SharedPreferences prefs,
    required String profileId,
    required String deviceId,
    Iterable<String> ownDeviceIds = const <String>[],
    bool initNotifications = true,
  }) async {
    _backgroundInboundMode = true;
    _db = db;
    _crypto = crypto;
    _ratchetV3 = ratchetV3;
    _keys = keys;
    _prefs = prefs;
    _profileId = profileId;
    _deviceId = deviceId;
    _knownOwnDeviceIds
      ..clear()
      ..addAll(
        ownDeviceIds.map((v) => v.trim()).where((v) => v.isNotEmpty),
      );
    // The whole point of background decrypt is to post a real notification with
    // the decrypted preview. `_handleDelivered` already calls
    // `_maybeNotifyIncomingConvo`, which needs the local-notifications plugin
    // live in THIS isolate — the foreground engine's init does not carry over.
    if (initNotifications) {
      try {
        await _initLocalNotifications();
      } catch (_) {
        // best-effort: without it the message is still decrypted + stored, it
        // just won't raise a banner from the background isolate.
      }
    }
  }

  @visibleForTesting
  void seedKnownOwnDeviceIdsForTesting(Iterable<String> deviceIds) {
    _knownOwnDeviceIds
      ..clear()
      ..addAll(
        deviceIds
            .map((value) => value.trim())
            .where((value) => value.isNotEmpty),
      );
  }

