  final _CoalescedChangedController _changed = _CoalescedChangedController();
  int _changeVersion = 0;

  // ── Background attachment-upload engine (survives chat navigation) ─────────
  // In-progress uploads keyed by convoId so a bubble stays visible with live
  // progress when the user leaves and re-enters the chat. A SINGLE global
  // worker drains the queue one-at-a-time — the double-ratchet is stateful and
  // must never see overlapping sends (that races the chain → "no deliverable
  // target devices" → loss). Progress/list changes are signalled on a DEDICATED
  // stream (`_pendingUploadsChanged`) that does NOT bump `_changeVersion`, so a
  // 12fps progress tick never re-queries sqlite for the timeline.
  final Map<String, List<PendingPhotoUpload>> _pendingPhotosByConvo = {};
  final Map<String, List<PendingPhotoAlbumUpload>> _pendingPhotoAlbumsByConvo =
      {};
  final Map<String, List<PendingAudioUpload>> _pendingAudioByConvo = {};
  // One serialized worker PER CONVERSATION: within a convo, sends run strictly
  // one-at-a-time (the double-ratchet for that peer/group is stateful and must
  // never see overlapping sends). Different convos upload concurrently — they
  // target different ratchets — matching the old one-worker-per-chat-screen
  // behaviour, but now owned by the controller so it survives navigation.
  final Map<String, List<Future<void> Function()>> _uploadJobsByConvo = {};
  final Set<String> _uploadWorkersRunning = <String>{};
  final StreamController<String> _pendingUploadsChanged =
      StreamController<String>.broadcast();
  final StreamController<AttachmentUploadErrorEvent> _attachmentUploadErrors =
      StreamController<AttachmentUploadErrorEvent>.broadcast();

  final StreamController<void> _restartRequested = StreamController.broadcast();
  final StreamController<CallSignalEvent> _callSignals =
      StreamController<CallSignalEvent>.broadcast();
  final StreamController<RoomCallMediaSignalEvent> _roomCallMediaSignals =
      StreamController<RoomCallMediaSignalEvent>.broadcast();
  final StreamController<bool> _relayConnectionChanges =
      StreamController<bool>.broadcast();
  // Ring-buffer of recent call signals so CallManager can drain on late subscribe.
  final List<CallSignalEvent> _callSignalBuffer = [];
  final List<RoomCallMediaSignalEvent> _roomCallMediaSignalBuffer = [];
  static const int _callSignalBufferMax = 20;

  /// Сколько держим сигнал звонка в очереди для главного изолята.
  static const int _pendingCallSignalTtlMs = 24 * 60 * 60 * 1000;
  static const int _roomCallMediaSignalBufferMax = 32;
  static const int _recentInboundCallSignalDedupTtlMs = 3 * 60 * 1000;
  static const int _recentInboundRoomCallMediaSignalDedupTtlMs = 3 * 60 * 1000;
  static const int _recentInboundCallSignalDedupMax = 512;
  static const int _recentInboundRoomCallMediaSignalDedupMax = 512;
  final Map<String, _CallTargetCacheEntry> _callTargetCache =
      <String, _CallTargetCacheEntry>{};
  final Map<String, _CallTargetCacheEntry> _callTargetCacheByCallId =
      <String, _CallTargetCacheEntry>{};
  CallIceConfigSnapshot _cachedCallIceConfig =
      const CallIceConfigSnapshot.empty();

  /// Last-known ICE config snapshot without triggering a refresh. May be
  /// expired or empty — callers must check `isExpired()` before relying on
  /// the credentials. Used by `CallManager` to decide whether to block a
  /// recovery on a fresh fetch.
  CallIceConfigSnapshot get cachedCallIceConfig => _cachedCallIceConfig;
  Future<CallIceConfigSnapshot>? _callIceConfigRefreshInFlight;

  // BUG-FIX (ICE-STALE-CACHE 2026-05-29) — backoff after a failed refresh.
  // Without this, the post-fix `pruneExpiredCredentials` would invite every
  // single `getCallIceConfig` call to retry the keys round-trip while
  // relay is unreachable — turning an outage into spam. We cool down for
  // `_callIceConfigRefreshFailBackoffMs` and serve the (pruned) cached
  // snapshot during the cooldown.
  int _callIceConfigLastRefreshFailedAtMs = 0;
  static const int _callIceConfigRefreshFailBackoffMs = 30 * 1000;
  final Map<String, int> _recentInboundCallSignalIds = <String, int>{};
  final Map<String, int> _recentInboundRoomCallMediaSignalIds = <String, int>{};
  final Map<String, int> _typingExpiresAtMsByConvo = <String, int>{};
  // Profile id of the member whose typing signal is currently active for a
  // conversation (room display: "<name> Пишет"). Lifecycle mirrors
  // `_typingExpiresAtMsByConvo` exactly: set on start, cleared on stop/expiry.
  final Map<String, String> _typingSenderProfileIdByConvo = <String, String>{};

  /// Everyone currently typing, per conversation: convo → {profileId: expiry}.
  ///
  /// The single-sender map above only ever remembered the LATEST typer, which
  /// is all a 1:1 chat can have. A room can have several at once, and the
  /// header is supposed to name them — so typing has to be tracked per person,
  /// with its own expiry each, or one member going quiet would wipe the rest.
  final Map<String, Map<String, int>> _typingSendersByConvo =
      <String, Map<String, int>>{};
  final Map<String, Completer<RoomInvitePreview>> _roomInvitePreviewWaiters =
      <String, Completer<RoomInvitePreview>>{};
  final Map<String, Completer<_RoomInviteJoinResult>> _roomInviteJoinWaiters =
      <String, Completer<_RoomInviteJoinResult>>{};
  Timer? _typingSweepTimer;

  Stream<void> get changed => _changed.stream;
  int get changeVersion => _changeVersion;

  // ── Background attachment-upload engine: public surface ────────────────────
  /// Fires (with a convoId) on any pending-upload change — enqueue, throttled
  /// progress tick, or removal. Distinct from [changed] so the chat screen can
  /// repaint the progress ring WITHOUT re-querying the timeline from sqlite.
  Stream<String> get pendingUploadsChanged => _pendingUploadsChanged.stream;

  /// Fires when a background upload fails, so the owning chat screen can surface
  /// the error (too-large upsell / snackbar) just like the old in-screen path.
  Stream<AttachmentUploadErrorEvent> get attachmentUploadErrors =>
      _attachmentUploadErrors.stream;

  List<PendingPhotoUpload> pendingPhotoUploadsFor(String convoId) =>
      _pendingPhotosByConvo[convoId] ?? const <PendingPhotoUpload>[];
  List<PendingPhotoAlbumUpload> pendingPhotoAlbumUploadsFor(String convoId) =>
      _pendingPhotoAlbumsByConvo[convoId] ??
      const <PendingPhotoAlbumUpload>[];
  List<PendingAudioUpload> pendingAudioUploadsFor(String convoId) =>
      _pendingAudioByConvo[convoId] ?? const <PendingAudioUpload>[];

  void _pokePendingUploads(String convoId) {
    if (!_pendingUploadsChanged.isClosed) {
      _pendingUploadsChanged.add(convoId);
    }
  }

  void _enqueueUploadJob(String convoId, Future<void> Function() job) {
    (_uploadJobsByConvo[convoId] ??= <Future<void> Function()>[]).add(job);
    if (!_uploadWorkersRunning.contains(convoId)) {
      unawaited(_runUploadWorker(convoId));
    }
  }

  Future<void> _runUploadWorker(String convoId) async {
    if (_uploadWorkersRunning.contains(convoId)) return;
    _uploadWorkersRunning.add(convoId);
    try {
      final jobs = _uploadJobsByConvo[convoId] ??= <Future<void> Function()>[];
      while (jobs.isNotEmpty) {
        final job = jobs.removeAt(0);
        try {
          await job();
        } catch (_) {
          // Each job reports its own error via _attachmentUploadErrors; keep
          // draining the rest so one failure can't stall the queue.
        }
      }
    } finally {
      _uploadWorkersRunning.remove(convoId);
    }
  }

  /// Enqueue a single photo/video/document upload. The bubble is registered
  /// immediately (so it renders) and the send runs on the serialized worker.
  void enqueuePhotoUpload(PendingPhotoUpload pending) {
    (_pendingPhotosByConvo[pending.convoId] ??= <PendingPhotoUpload>[]).insert(
      0,
      pending,
    );
    _pokePendingUploads(pending.convoId);
    _enqueueUploadJob(pending.convoId, () => _runPendingPhotoUpload(pending));
  }

  /// Batch enqueue of independent photo/file uploads (gallery-as-files): the
  /// FIRST item ends up topmost (index 0) while the uploads run in picked order.
  void enqueuePhotoUploads(List<PendingPhotoUpload> pendings) {
    if (pendings.isEmpty) return;
    final convoId = pendings.first.convoId;
    final list = _pendingPhotosByConvo[convoId] ??= <PendingPhotoUpload>[];
    for (final p in pendings.reversed) {
      list.insert(0, p);
    }
    _pokePendingUploads(convoId);
    for (final p in pendings) {
      _enqueueUploadJob(convoId, () => _runPendingPhotoUpload(p));
    }
  }

  void enqueuePhotoAlbumUpload(PendingPhotoAlbumUpload album) {
    (_pendingPhotoAlbumsByConvo[album.convoId] ??= <PendingPhotoAlbumUpload>[])
        .insert(0, album);
    _pokePendingUploads(album.convoId);
    _enqueueUploadJob(album.convoId, () => _runPendingPhotoAlbumUpload(album));
  }

  // ── Пачки из окна отправки компьютера ────────────────────────────────────
  // Отдельно от альбомов телефона: у пачки свои правила (имена документов,
  // подсказки по роликам — см. [PendingAttachmentBatchUpload]),
  // а телефонный путь остаётся ровно таким, каким выпущен. Очередь при этом
  // ОБЩАЯ: внутри одной переписки отправки идут строго по одной.
  final Map<String, List<PendingAttachmentBatchUpload>>
  _pendingAttachmentBatchesByConvo = {};

  /// Пачки, которые ещё грузятся, — новые первыми.
  List<PendingAttachmentBatchUpload> pendingAttachmentBatchUploadsFor(
    String convoId,
  ) =>
      _pendingAttachmentBatchesByConvo[convoId] ??
      const <PendingAttachmentBatchUpload>[];

  void enqueueAttachmentBatchUpload(PendingAttachmentBatchUpload batch) {
    (_pendingAttachmentBatchesByConvo[batch.convoId] ??=
            <PendingAttachmentBatchUpload>[])
        .insert(0, batch);
    _pokePendingUploads(batch.convoId);
    _enqueueUploadJob(
      batch.convoId,
      () => _runPendingAttachmentBatchUpload(batch),
    );
  }

  /// Отменить пачку целиком. Подпись и ответ принадлежат всей пачке, поэтому
  /// половину альбома не отменяем: он ушёл бы без подписи или без ответа.
  void cancelPendingAttachmentBatchUpload(String convoId, String batchId) {
    final list = _pendingAttachmentBatchesByConvo[convoId];
    if (list == null) return;
    for (final batch in list) {
      if (batch.id == batchId) batch.cancel();
    }
    list.removeWhere((batch) => batch.id == batchId);
    _pokePendingUploads(convoId);
  }

  void _dropPendingAttachmentBatch(PendingAttachmentBatchUpload batch) {
    _pendingAttachmentBatchesByConvo[batch.convoId]?.removeWhere(
      (x) => x.id == batch.id,
    );
    _pokePendingUploads(batch.convoId);
  }

  void enqueueAudioUpload(PendingAudioUpload pending) {
    (_pendingAudioByConvo[pending.convoId] ??= <PendingAudioUpload>[]).insert(
      0,
      pending,
    );
    _pokePendingUploads(pending.convoId);
    _enqueueUploadJob(pending.convoId, () => _runPendingAudioUpload(pending));
  }

  /// Remove a still-pending upload (cancel button) — cancels the token and drops
  /// the bubble immediately. The worker's in-flight send, if any, unwinds via
  /// the cancel token and its removal becomes a no-op.
  void removePendingPhotoUpload(String convoId, String id) {
    _pendingPhotosByConvo[convoId]?.removeWhere((x) => x.id == id);
    _pokePendingUploads(convoId);
  }

  void removePendingPhotoAlbumUpload(String convoId, String id) {
    _pendingPhotoAlbumsByConvo[convoId]?.removeWhere((x) => x.id == id);
    _pokePendingUploads(convoId);
  }

  /// Cancel ONE photo of a still-uploading album (per-photo ✕). The item is
  /// marked cancelled + its token fired so the worker skips it, while the other
  /// photos keep uploading. If it was the last remaining photo, the whole album
  /// is dropped. Safe to call whether or not the worker has reached this item.
  void cancelPendingPhotoAlbumItem(
    String convoId,
    String albumId,
    String itemId,
  ) {
    final album = _pendingPhotoAlbumsByConvo[convoId]?.firstWhere(
      (a) => a.id == albumId,
      orElse: () => PendingPhotoAlbumUpload(id: '', items: const []),
    );
    if (album == null || album.id.isEmpty) return;
    final index = album.items.indexWhere((i) => i.id == itemId);
    if (index < 0) return;
    final allCanceled = album.cancelItem(index);
    if (allCanceled) {
      _pendingPhotoAlbumsByConvo[convoId]?.removeWhere((x) => x.id == albumId);
    }
    _pokePendingUploads(convoId);
  }

  void removePendingAudioUpload(String convoId, String id) {
    _pendingAudioByConvo[convoId]?.removeWhere((x) => x.id == id);
    _pokePendingUploads(convoId);
  }

  void _dropPendingPhoto(PendingPhotoUpload p) {
    _pendingPhotosByConvo[p.convoId]?.removeWhere((x) => x.id == p.id);
    _pokePendingUploads(p.convoId);
  }

  void _dropPendingPhotoAlbum(PendingPhotoAlbumUpload a) {
    _pendingPhotoAlbumsByConvo[a.convoId]?.removeWhere((x) => x.id == a.id);
    _pokePendingUploads(a.convoId);
  }

  void _dropPendingAudio(PendingAudioUpload a) {
    _pendingAudioByConvo[a.convoId]?.removeWhere((x) => x.id == a.id);
    _pokePendingUploads(a.convoId);
  }

  /// Keep the pending bubble alive until the freshly-sent event is queryable, so
  /// there is no one-frame gap between the pending bubble and the real one.
  Future<void> _waitForPendingUploadEventVisible(
    String convoId,
    String payloadEventId,
  ) async {
    if (payloadEventId.trim().isEmpty) return;
    final deadline = DateTime.now().add(const Duration(milliseconds: 1800));
    while (DateTime.now().isBefore(deadline)) {
      final events = await loadEvents(convoId);
      if (events.any((e) => e.payloadEventId == payloadEventId)) return;
      await Future<void>.delayed(const Duration(milliseconds: 110));
    }
  }

  Future<void> _runPendingPhotoUpload(PendingPhotoUpload pending) async {
    try {
      // Telegram-style: the caption rides INSIDE the same attachment bubble
      // (AttachmentEventV1.caption) instead of a separate trailing message.
      final cap = pending.caption.trim();
      final captionArg = cap.isEmpty ? null : cap;

      // A re-encoded VIDEO has TWO phases the user waits through — compress then
      // upload. The old code showed 0% for the whole (long) compress and then
      // retargeted the total to the SMALLER compressed size, so the MB readout
      // sat at "0/140" and later jumped/shrank ("работает в убыток"). Instead we
      // keep the ORIGINAL byte total fixed and map compress→0..W, upload→W..1
      // onto it, so the ring/MB only ever grows and never freezes at zero.
      final isVideo =
          !pending.asFile &&
          !pending.videoNote &&
          VideoCompressor.isVideoMime(pending.mime);
      final originalTotal = pending.totalBytes;
      const compressWeight = 0.5;
      // Whether a compress phase will actually RUN (drives the first half of the
      // ring). Keyed on the size threshold — NOT on whether the re-encode shrank
      // the file — so the ring never jumps backward if it didn't shrink.
      final willCompress = isVideo && originalTotal > VideoCompressor.skipBelowBytes;

      void reportVideoFraction(double fraction) {
        final sent = (originalTotal * fraction.clamp(0.0, 1.0)).round();
        if (pending.updateProgress(sent, originalTotal)) {
          _pokePendingUploads(pending.convoId);
        }
      }

      void onProgress(int sent, int total) {
        if (isVideo) {
          final frac = total > 0 ? (sent / total).clamp(0.0, 1.0) : 0.0;
          reportVideoFraction(
            willCompress ? compressWeight + (1 - compressWeight) * frac : frac,
          );
        } else if (pending.updateProgress(sent, total)) {
          _pokePendingUploads(pending.convoId);
        }
      }

      // Telegram-style: re-encode a VIDEO (sent inline, not as a file) to a
      // capped-resolution H.264 before upload so a raw 4K/50Mbps capture isn't
      // sent at full bitrate — much faster on a slow uplink, ~same look. No-op
      // for photos, small clips, or videos sent AS FILES (keep those original).
      var sendPath = pending.filePath;
      if (isVideo && willCompress) {
        reportVideoFraction(0.01); // immediate activity, not a dead 0%
        sendPath = await VideoCompressor.compressForSend(
          pending.filePath,
          onProgress: (f) => reportVideoFraction(compressWeight * f),
        );
        if (pending.cancelToken.isCanceled) {
          _dropPendingPhoto(pending);
          return;
        }
      }

      // No wall-clock timeout: large media may upload for a while on a slow
      // link. Sends are serialized (single worker) so this never overlaps
      // another send; cancellation is explicit via cancelToken.
      final payloadEventId = await (pending.isGroup
          ? sendGroupAttachmentFile(
              groupId: pending.convoId,
              filePath: sendPath,
              mime: pending.mime,
              replyToPayloadEventId: pending.replyToPayloadEventId,
              mediaGroupId: pending.mediaGroupId,
              cancelToken: pending.cancelToken,
              topicId: pending.topicId,
              caption: captionArg,
              filename: pending.filename,
              onUploadProgress: onProgress,
              musicTitle: pending.musicTitle,
              musicArtist: pending.musicArtist,
              waveform: pending.waveform,
              durationMs: pending.durationMs,
              videoNote: pending.videoNote,
            )
          : sendAttachmentFile(
              peerProfileId: pending.targetId,
              filePath: sendPath,
              mime: pending.mime,
              replyToPayloadEventId: pending.replyToPayloadEventId,
              mediaGroupId: pending.mediaGroupId,
              cancelToken: pending.cancelToken,
              caption: captionArg,
              filename: pending.filename,
              onUploadProgress: onProgress,
              reuseBlobFrom: pending.reuseBlobFrom,
              musicTitle: pending.musicTitle,
              musicArtist: pending.musicArtist,
              waveform: pending.waveform,
              durationMs: pending.durationMs,
              videoNote: pending.videoNote,
            ));

      pending.payloadEventId = payloadEventId;
      await _waitForPendingUploadEventVisible(pending.convoId, payloadEventId);
      _dropPendingPhoto(pending);
    } catch (e) {
      _dropPendingPhoto(pending);
      if (!_attachmentUploadErrors.isClosed) {
        _attachmentUploadErrors.add(
          AttachmentUploadErrorEvent(convoId: pending.convoId, error: e),
        );
      }
    }
  }

  Future<void> _runPendingPhotoAlbumUpload(PendingPhotoAlbumUpload album) async {
    try {
      // Album caption (if any) rides inside the FIRST item's bubble.
      final albumCaption = album.items.isEmpty
          ? null
          : (album.items.first.caption.trim().isEmpty
                ? null
                : album.items.first.caption.trim());

      // Per-item smooth progress across compress→upload, mapped onto each item's
      // ORIGINAL byte total so the ring never freezes at 0 nor shrinks when the
      // compressed file turns out smaller (see the single-photo worker note).
      const compressWeight = 0.5;
      final originalTotals = <int>[
        for (final item in album.items) item.totalBytes,
      ];
      // Which items will run a compress phase (video over the size threshold) —
      // keyed on size, not the shrink result, so a ring never jumps backward.
      final willCompress = <bool>[
        for (final item in album.items)
          VideoCompressor.isVideoMime(item.mime) &&
              item.totalBytes > VideoCompressor.skipBelowBytes,
      ];

      void reportItemFraction(int index, double fraction) {
        if (index < 0 || index >= album.items.length) return;
        final total = originalTotals[index];
        final sent = (total * fraction.clamp(0.0, 1.0)).round();
        if (album.updateProgress(index, sent, total)) {
          _pokePendingUploads(album.convoId);
        }
      }

      void onProgress(int index, int sent, int total) {
        if (index < 0 || index >= album.items.length) return;
        final frac = total > 0 ? (sent / total).clamp(0.0, 1.0) : 0.0;
        reportItemFraction(
          index,
          willCompress[index]
              ? compressWeight + (1 - compressWeight) * frac
              : frac,
        );
      }

      // Compress any VIDEO items (Telegram-style) before the batch upload.
      final files = <AttachmentFileSendRequest>[];
      for (var i = 0; i < album.items.length; i++) {
        final item = album.items[i];
        var path = item.filePath;
        if (willCompress[i]) {
          reportItemFraction(i, 0.01); // immediate activity, not a dead 0%
          path = await VideoCompressor.compressForSend(
            item.filePath,
            onProgress: (f) => reportItemFraction(i, compressWeight * f),
          );
        }
        files.add(AttachmentFileSendRequest(filePath: path, mime: item.mime));
      }
      final eventIds = await (album.isGroup
          ? sendGroupAttachmentFiles(
              groupId: album.convoId,
              files: files,
              replyToPayloadEventId: album.items.first.replyToPayloadEventId,
              mediaGroupId: album.mediaGroupId,
              cancelTokens: album.cancelTokens,
              caption: albumCaption,
              onUploadProgress: onProgress,
              // 🔴 Тема, открытая при отправке (17.09.2026). Экран кладёт её в
              // альбом, а здесь она терялась — и альбом из темы уходил в
              // «Общий», хотя одиночный снимок из той же темы шёл куда надо.
              topicId: album.topicId,
            )
          : sendAttachmentFiles(
              peerProfileId: album.targetId,
              files: files,
              replyToPayloadEventId: album.items.first.replyToPayloadEventId,
              mediaGroupId: album.mediaGroupId,
              cancelTokens: album.cancelTokens,
              caption: albumCaption,
              onUploadProgress: onProgress,
            ));

      album.payloadEventIds = eventIds;
      for (final eventId in eventIds) {
        await _waitForPendingUploadEventVisible(album.convoId, eventId);
      }
      _dropPendingPhotoAlbum(album);
    } catch (e) {
      _dropPendingPhotoAlbum(album);
      if (!_attachmentUploadErrors.isClosed) {
        _attachmentUploadErrors.add(
          AttachmentUploadErrorEvent(convoId: album.convoId, error: e),
        );
      }
    }
  }

  Future<void> _runPendingAttachmentBatchUpload(
    PendingAttachmentBatchUpload batch,
  ) async {
    // Отменили, пока пачка ждала своей очереди.
    if (batch.items.isEmpty || batch.allCanceled) {
      _dropPendingAttachmentBatch(batch);
      return;
    }
    try {
      final firstCaption = batch.items.first.caption.trim();
      // Ролик, отправляемый как видео (не файлом), сперва сжимается — как у
      // телефона; кольцо делится на сжатие и загрузку и только растёт.
      const compressWeight = 0.5;
      final originalTotals = <int>[
        for (final item in batch.items) item.totalBytes,
      ];
      final willCompress = <bool>[
        for (final item in batch.items)
          !item.asFile &&
              VideoCompressor.isVideoMime(item.mime) &&
              item.totalBytes > VideoCompressor.skipBelowBytes,
      ];

      void reportItemFraction(int index, double fraction) {
        if (index < 0 || index >= batch.items.length) return;
        final total = originalTotals[index];
        final sent = (total * fraction.clamp(0.0, 1.0)).round();
        if (batch.updateProgress(index, sent, total)) {
          _pokePendingUploads(batch.convoId);
        }
      }

      void onProgress(int index, int sent, int total) {
        if (index < 0 || index >= batch.items.length) return;
        final frac = total > 0 ? (sent / total).clamp(0.0, 1.0) : 0.0;
        reportItemFraction(
          index,
          willCompress[index]
              ? compressWeight + (1 - compressWeight) * frac
              : frac,
        );
      }

      final files = <AttachmentFileSendRequest>[];
      for (var i = 0; i < batch.items.length; i++) {
        final item = batch.items[i];
        var path = item.filePath;
        if (willCompress[i]) {
          reportItemFraction(i, 0.01);
          path = await VideoCompressor.compressForSend(
            item.filePath,
            onProgress: (f) => reportItemFraction(i, compressWeight * f),
          );
          if (batch.allCanceled) {
            _dropPendingAttachmentBatch(batch);
            return;
          }
        }
        final hint = batch.hints[i];
        files.add(
          AttachmentFileSendRequest(
            filePath: path,
            mime: item.mime,
            fileName: item.filename,
            width: hint.width,
            height: hint.height,
            durationMs: hint.durationMs,
            thumbB64: hint.thumbB64,
            musicTitle: hint.musicTitle,
            musicArtist: hint.musicArtist,
          ),
        );
      }
      final caption = firstCaption.isEmpty ? null : firstCaption;
      final replyTo = batch.items.first.replyToPayloadEventId;
      final eventIds = await (batch.isGroup
          ? sendGroupAttachmentFiles(
              groupId: batch.convoId,
              files: files,
              replyToPayloadEventId: replyTo,
              mediaGroupId: batch.mediaGroupId,
              cancelTokens: batch.cancelTokens,
              caption: caption,
              onUploadProgress: onProgress,
              topicId: batch.topicId,
            )
          : sendAttachmentFiles(
              peerProfileId: batch.targetId,
              files: files,
              replyToPayloadEventId: replyTo,
              mediaGroupId: batch.mediaGroupId,
              cancelTokens: batch.cancelTokens,
              caption: caption,
              onUploadProgress: onProgress,
            ));

      batch.payloadEventIds = eventIds;
      for (final eventId in eventIds) {
        await _waitForPendingUploadEventVisible(batch.convoId, eventId);
      }
      _dropPendingAttachmentBatch(batch);
    } catch (e) {
      _dropPendingAttachmentBatch(batch);
      // Отмена — решение человека, а не сбой: сообщать о ней нечего.
      final canceled =
          batch.allCanceled ||
          (e is AttachmentFailure &&
              e.code == AttachmentFailureCode.uploadCanceled);
      if (!canceled && !_attachmentUploadErrors.isClosed) {
        _attachmentUploadErrors.add(
          AttachmentUploadErrorEvent(convoId: batch.convoId, error: e),
        );
      }
    }
  }

  Future<void> _runPendingAudioUpload(PendingAudioUpload pending) async {
    try {
      void onProgress(int sent, int total) {
        if (pending.updateProgress(sent, total)) {
          _pokePendingUploads(pending.convoId);
        }
      }

      // Music tags were read off the ORIGINAL file when the upload was queued
      // (pending.title/artist). Carry them into the payload: the settled bubble
      // renders from the event, and re-reading tags from the blob cache is not
      // dependable — without this the track flips to the generic
      // "Music / Unknown artist" the moment the upload finishes, and the
      // recipient never learns them at all. Voice notes carry no tags.
      //
      // 🔴 Чтение тегов идёт параллельно с постановкой в очередь, а очередь
      // стартует сразу — ждём его здесь (17.09.2026), иначе первая песня
      // уходила с именем файла вместо названия и без исполнителя.
      final tagsReady = pending.isVoice ? null : pending.tagsReady;
      if (tagsReady != null) {
        try {
          await tagsReady.timeout(kMusicTagsWait);
        } catch (_) {
          // Не дождались или не прочлось — уходим без тегов.
        }
      }
      final withTags = !pending.isVoice && pending.tagsFromFile;
      final taggedTitle = withTags ? pending.title?.trim() : null;
      // В тегах бывает один исполнитель — тогда в [title] так и лежит имя
      // файла для заготовки, и названием оно не уходит.
      final musicTitle =
          (taggedTitle == null ||
              taggedTitle.isEmpty ||
              taggedTitle == p.basename(pending.filePath))
          ? null
          : taggedTitle;
      final musicArtist = withTags ? pending.artist : null;
      // Last-resort label: if the tags turn out to be unreadable, the bubble
      // should still say what the file is called instead of a generic "Music".
      // The audio path never sent a filename at all (PendingAudioUpload has no
      // such field and the picker throws the name away), which is why the
      // fallback could never fire.
      //
      // 🔴 Без имени уходят только голосовые с «голосовым» типом — как и до
      // 17.09.2026. Голосовое телефона пишется в AAC (`audio/mp4`), и выпущенная
      // версия отправляла его с именем `voice_….m4a`: по нему получатель
      // называет файл при сохранении, а без имени тот стал бы «music_…».
      // Голосовым пузырь делает волна, а не отсутствие имени.
      final musicFilename = isVoiceAttachmentMime(pending.mime)
          ? null
          : p.basename(pending.filePath);
      final payloadEventId = await (pending.isGroup
          ? sendGroupAttachmentFile(
              groupId: pending.convoId,
              filePath: pending.filePath,
              mime: pending.mime,
              replyToPayloadEventId: pending.replyToPayloadEventId,
              cancelToken: pending.cancelToken,
              waveform: pending.waveform,
              topicId: pending.topicId,
              musicTitle: musicTitle,
              musicArtist: musicArtist,
              filename: musicFilename,
              onUploadProgress: onProgress,
            )
          : sendAttachmentFile(
              peerProfileId: pending.targetId,
              filePath: pending.filePath,
              mime: pending.mime,
              replyToPayloadEventId: pending.replyToPayloadEventId,
              cancelToken: pending.cancelToken,
              waveform: pending.waveform,
              musicTitle: musicTitle,
              musicArtist: musicArtist,
              filename: musicFilename,
              onUploadProgress: onProgress,
            ));

      pending.payloadEventId = payloadEventId;
      await _waitForPendingUploadEventVisible(pending.convoId, payloadEventId);
      _dropPendingAudio(pending);
    } catch (e) {
      _dropPendingAudio(pending);
      if (!_attachmentUploadErrors.isClosed) {
        _attachmentUploadErrors.add(
          AttachmentUploadErrorEvent(convoId: pending.convoId, error: e),
        );
      }
    }
  }

  Stream<void> get restartRequested => _restartRequested.stream;
  Stream<CallSignalEvent> get callSignals => _callSignals.stream;
  Stream<RoomCallMediaSignalEvent> get roomCallMediaSignals =>
      _roomCallMediaSignals.stream;
  Stream<bool> get relayConnectionChanges => _relayConnectionChanges.stream;

  /// Force an immediate WS reconnect with the backoff counter reset to 0,
  /// so the next attempt fires on the minimum 400 ms delay. Used by
  /// `CallManager` during active calls when a network handoff has rendered
  /// the previous socket unrecoverable. Safe to call when no relay exists
  /// yet — it becomes a no-op.
  void requestUrgentRelayReconnect() {
    final relay = _relay;
    if (relay == null) return;
    DiagLog.event('relay', 'urgent_reconnect_requested', {});
    try {
      relay.markWsStaleAndReconnect(urgent: true);
    } catch (_) {}
  }

  final AppSecurityManager security = AppSecurityManager();
  StreamSubscription<void>? _securityChangedSub;
  StreamSubscription<void>? _changedCacheInvalidatorSub;

  // Connectivity watchdog — kicks the relay socket whenever the network path
  // changes (WiFi <-> cellular, VPN on/off, hotspot handoff). Independent of
  // CallManager so an idle relay socket also recovers on network switch.
  StreamSubscription<List<ConnectivityResult>>? _appConnectivitySub;
  StreamSubscription<dynamic>? _appNativeNetworkPathSub;
  String _appLastNetworkPathSignature = '';
  List<ConnectivityResult> _appLastConnectivityResults =
      const <ConnectivityResult>[];

  // Whether the device currently has any network path (wifi/mobile/etc.).
  // Optimistic default so the brand-logo fingerprint stays calm at startup;
  // updated by the connectivity watcher. Drives the offline-pulse indicator —
  // independent of the (flappy) keys/relay health flags.
  bool _networkOnline = true;
  bool get networkOnline => _networkOnline;
  Timer? _appNetworkReconnectDebounce;

  // Desktop wake-event watcher (Sprint 2 / PR2, TZ §21.x).
  // macOS suspends background activity on sleep/lid-close and Flutter's
  // connectivity_plus stream doesn't fire on resume — so an existing relay
  // WebSocket stays half-open until the next heartbeat times out, which can
  // leave the user waiting many seconds for fresh messages after unlock.
  // The native side (PowerStateBridge in MainFlutterWindow.swift) forwards
  // `NSWorkspace.didWakeNotification` over this channel; on wake we force
  // an urgent reconnect plus an outbox/inbox kick so the desktop catches up
  // immediately, matching the user's expectation of multi-device parity.
  StreamSubscription<dynamic>? _appPowerStateSub;
  static const EventChannel _appPowerStateChannel = EventChannel(
    'secretly/power_state',
  );
  // Debounce so a wake notification arriving alongside a connectivity change
  // doesn't double-kick the reconnect path. Coalesced with the existing
  // network reconnect debounce by routing through `_scheduleRelayReconnectKick`.
  int _appLastWakeKickMs = 0;

  /// Returns buffered signals dispatched before [CallManager] subscribed and
  /// clears the buffer. Must be called once from [CallManager.start()].
  List<CallSignalEvent> drainCallSignalBuffer() {
    final copy = List<CallSignalEvent>.unmodifiable(
      List<CallSignalEvent>.from(_callSignalBuffer),
    );
    _callSignalBuffer.clear();
    return copy;
  }

  /// Вычерпывает очередь сигналов звонка, записанную ФОНОВЫМ изолятом.
  ///
  /// Зовётся главным изолятом при запуске [CallManager] и на возобновлении
  /// приложения. Возвращённое обрабатывается ТЕМ ЖЕ путём, что и живые сигналы:
  /// второго обработчика у звонка быть не должно.
  Future<List<CallSignalEvent>> drainPersistedCallSignals() async {
    final db = _db;
    if (db == null) return const <CallSignalEvent>[];
    List<Map<String, Object?>> rows;
    try {
      rows = await db.pendingCallSignalsDrain();
    } catch (e) {
      callLog('AppCtrl', 'call signal queue drain failed: ${e.runtimeType}');
      return const <CallSignalEvent>[];
    }
    if (rows.isEmpty) return const <CallSignalEvent>[];
    final events = <CallSignalEvent>[];
    for (final row in rows) {
      final raw = ((row['payload_json'] as String?) ?? '').trim();
      if (raw.isEmpty) continue;
      try {
        final decoded = jsonDecode(raw);
        if (decoded is! Map) continue;
        final event = CallSignalEvent.fromJson(decoded.cast<Object?, Object?>());
        if (event != null) events.add(event);
      } catch (_) {
        // Испорченную строку лучше потерять поштучно, чем уронить всю очередь.
      }
    }
    // 🔴 Считаем И строки, И разобранные события. Счётчик, который не умеет
    // разойтись с делом, ничего не доказывает — 12.08 «acked=10» стояло при нуле
    // принятых, потому что рос до отправки.
    callOpLog(
      'AppCtrl',
      'call_signal_queue_drained',
      fields: <String, Object?>{'rows': rows.length, 'parsed': events.length},
    );
    return events;
  }

  List<RoomCallMediaSignalEvent> drainRoomCallMediaSignalBuffer() {
    final copy = List<RoomCallMediaSignalEvent>.unmodifiable(
      List<RoomCallMediaSignalEvent>.from(_roomCallMediaSignalBuffer),
    );
    _roomCallMediaSignalBuffer.clear();
    return copy;
  }

  Future<void> _dispatchCallSignal(CallSignalEvent event) async {
    final fromDeviceId = (event.fromDeviceId ?? '').trim();
    if (event.callId.isNotEmpty && fromDeviceId.isNotEmpty) {
      _rememberCallTargetDevicesForCall(event.callId, <String>[fromDeviceId]);
    }
    // 🔴 КАРТА СШИВКИ НУЖНА И НА ПРИЁМНИКЕ. У звонящего она печатается при
    // разрешении целей, а принимающий целей не разрешает — и по одному его
    // журналу серверный след звонка снова не найти. Печатаем РОВНО на
    // приглашение: остальные сигналы того же звонка ничего нового не добавят,
    // а строка на каждый сигнал утопила бы ленту.
    if (event.action == 'invite' && fromDeviceId.isNotEmpty) {
      _logCallDeviceRefMap(<String>[fromDeviceId]);
    }
    callOpLog(
      'AppCtrl',
      'call_signal_dispatched',
      fields: <String, Object?>{
        'action': event.action,
        'callId': event.callId,
        'callAttemptId': event.callAttemptId,
        'signalId': event.signalId,
        'fromProfileId': event.fromProfileId,
        'fromDeviceId': event.fromDeviceId,
      },
    );
    _callSignalBuffer.add(event);
    if (_callSignalBuffer.length > _callSignalBufferMax) {
      _callSignalBuffer.removeAt(0);
    }
    _callSignals.add(event);

    // 🔴 ОЧЕРЕДЬ ЧЕРЕЗ ГРАНИЦУ ИЗОЛЯТА (14.08.2026, замер звонка d41fdf11).
    //
    // Всё, что выше, — доставка ВНУТРИ этого изолята: поток слушает CallManager,
    // буфер держит сигналы до его подписки. В главном изоляте этого достаточно.
    //
    // В фоновом — нет. Фон расшифровал приглашение и предложение звонка, применил
    // их, подтвердил реле и тем очистил ящик; главный изолят поднялся через три
    // секунды на пустой ящик и о звонке не узнал НИКОГДА — экран остался пустым,
    // а звонящий сдался через 25 секунд. Буфер в ОЗУ границу изолята не переживает.
    //
    // Поэтому фон дополнительно кладёт сигнал в базу. Ждём записи, а не бросаем
    // её вдогонку: фоновый изолят выбрасывают сразу после прохода, и незавершённая
    // запись — это ровно тот же потерянный звонок, только тише.
    if (_backgroundInboundMode) {
      await _persistCallSignalForMainIsolate(event);
    }
  }

  /// Кладёт сигнал звонка в очередь для главного изолята.
  ///
  /// Никогда не бросает: сбой записи не имеет права уронить фоновый проход, в
  /// котором едут ещё и обычные сообщения.
  Future<void> _persistCallSignalForMainIsolate(CallSignalEvent event) async {
    final signalId = event.signalId.trim();
    if (signalId.isEmpty) return;
    final db = _db;
    if (db == null) return;
    try {
      final nowMs = DateTime.now().millisecondsSinceEpoch;
      // Очередь чистит за собой вычерпывание, но если главный изолят не
      // поднимался сутками, копить незачем: сигнал старше суток не поднимет
      // ни одного звонка.
      await db.pendingCallSignalsPrune(nowMs - _pendingCallSignalTtlMs);
      await db.pendingCallSignalUpsert(
        signalId: signalId,
        callId: event.callId,
        callAttemptId: event.callAttemptId,
        action: event.action,
        fromProfileId: event.fromProfileId,
        fromDeviceId: event.fromDeviceId,
        payloadJson: jsonEncode(event.toJson()),
        createdAtMs: event.createdAtMs,
        nowMs: nowMs,
      );
      callOpLog(
        'AppCtrl',
        'call_signal_persisted',
        fields: <String, Object?>{
          'action': event.action,
          'callId': event.callId,
          'signalId': signalId,
        },
      );
    } catch (e) {
      // Молчание здесь стоило бы следующего разбора: без этой строки «очередь
      // пуста» и «очередь не записалась» выглядят одинаково.
      callLog('AppCtrl', 'call signal persist failed: ${e.runtimeType}');
    }
  }

  void _dispatchRoomCallMediaSignal(RoomCallMediaSignalEvent event) {
    callLog(
      'AppCtrl',
      'room media signal dispatched action=${event.action} roomId=${event.roomId} callId=${event.callId} descriptorVersion=${event.descriptorVersion} fromDeviceId=${event.fromDeviceId}',
    );
    _roomCallMediaSignalBuffer.add(event);
    if (_roomCallMediaSignalBuffer.length > _roomCallMediaSignalBufferMax) {
      _roomCallMediaSignalBuffer.removeAt(0);
    }
    _roomCallMediaSignals.add(event);
  }

  void _pruneRecentInboundCallSignalIds(int nowMs) {
    if (_recentInboundCallSignalIds.isEmpty) return;
    final staleIds = <String>[];
    _recentInboundCallSignalIds.forEach((signalId, seenAtMs) {
      if ((nowMs - seenAtMs) > _recentInboundCallSignalDedupTtlMs) {
        staleIds.add(signalId);
      }
    });
    for (final signalId in staleIds) {
      _recentInboundCallSignalIds.remove(signalId);
    }
  }

  void _pruneRecentInboundRoomCallMediaSignalIds(int nowMs) {
    if (_recentInboundRoomCallMediaSignalIds.isEmpty) {
      return;
    }
    final staleIds = <String>[];
    _recentInboundRoomCallMediaSignalIds.forEach((signalId, seenAtMs) {
      if ((nowMs - seenAtMs) > _recentInboundRoomCallMediaSignalDedupTtlMs) {
        staleIds.add(signalId);
      }
    });
    for (final signalId in staleIds) {
      _recentInboundRoomCallMediaSignalIds.remove(signalId);
    }
  }

  bool _shouldDropDuplicateInboundCallSignal({
    required String signalId,
    required String action,
    required String callId,
    required String callAttemptId,
    required String fromProfileId,
    String? fromDeviceId,
  }) {
    final normalizedSignalId = signalId.trim();
    if (normalizedSignalId.isEmpty) return false;

    final nowMs = DateTime.now().millisecondsSinceEpoch;
    _pruneRecentInboundCallSignalIds(nowMs);
    if (_recentInboundCallSignalIds.containsKey(normalizedSignalId)) {
      callOpLog(
        'AppCtrl',
        'call_signal_dedup_dropped',
        fields: <String, Object?>{
          'action': action,
          'callId': callId,
          'callAttemptId': callAttemptId,
          'signalId': normalizedSignalId,
          'fromProfileId': fromProfileId,
          'fromDeviceId': fromDeviceId,
        },
      );
      return true;
    }

    _recentInboundCallSignalIds[normalizedSignalId] = nowMs;
    while (_recentInboundCallSignalIds.length >
        _recentInboundCallSignalDedupMax) {
      final oldestSignalId = _recentInboundCallSignalIds.keys.first;
      _recentInboundCallSignalIds.remove(oldestSignalId);
    }
    return false;
  }

  bool _shouldDropDuplicateInboundRoomCallMediaSignal({
    required String signalId,
    required String action,
    required String roomId,
    required String callId,
    required String sessionId,
    required String fromProfileId,
    String? fromDeviceId,
  }) {
    final normalizedSignalId = signalId.trim();
    if (normalizedSignalId.isEmpty) {
      return false;
    }

    final nowMs = DateTime.now().millisecondsSinceEpoch;
    _pruneRecentInboundRoomCallMediaSignalIds(nowMs);
    if (_recentInboundRoomCallMediaSignalIds.containsKey(normalizedSignalId)) {
      callLog(
        'AppCtrl',
        'drop duplicate room media signal action=$action roomId=$roomId callId=$callId sessionId=$sessionId signalId=$normalizedSignalId fromProfileId=$fromProfileId fromDeviceId=$fromDeviceId',
      );
      return true;
    }

    _recentInboundRoomCallMediaSignalIds[normalizedSignalId] = nowMs;
    while (_recentInboundRoomCallMediaSignalIds.length >
        _recentInboundRoomCallMediaSignalDedupMax) {
      final oldestSignalId = _recentInboundRoomCallMediaSignalIds.keys.first;
      _recentInboundRoomCallMediaSignalIds.remove(oldestSignalId);
    }
    return false;
  }

  List<String>? _callTargetDevicesForCall(String callId) {
    final cid = callId.trim();
    if (cid.isEmpty) return null;
    final cached = _callTargetCacheByCallId[cid];
    if (cached == null) return null;
    final now = DateTime.now().millisecondsSinceEpoch;
    if (cached.expiresAtMs <= now || cached.deviceIds.isEmpty) {
      _callTargetCacheByCallId.remove(cid);
      return null;
    }
    return cached.deviceIds;
  }

  void _rememberCallTargetDevicesForCall(
    String callId,
    Iterable<String> deviceIds,
  ) {
    final cid = callId.trim();
    if (cid.isEmpty) return;
    final normalized = deviceIds
        .map((d) => d.trim())
        .where((d) => d.isNotEmpty)
        .toSet()
        .toList(growable: false);
    if (normalized.isEmpty) return;
    _callTargetCacheByCallId[cid] = _CallTargetCacheEntry(
      deviceIds: normalized,
      expiresAtMs:
          DateTime.now().millisecondsSinceEpoch + _callSignalTargetCacheTtlMs,
    );
  }

  void setActiveConversation(String? convoId) {
    final normalized = (convoId ?? '').trim();
    _activeConvoId = normalized.isEmpty ? null : normalized;
    // Cancel any pending system notification for this conversation.
    if (normalized.isNotEmpty) {
      _nativeMsgNotifChannel
          .invokeMethod('cancel', <String, dynamic>{'convoId': normalized})
          .catchError((_) {});
    }
  }

  void clearActiveConversation(String convoId) {
    final normalized = convoId.trim();
    if (normalized.isEmpty) return;
    if (_activeConvoId == normalized) {
      _activeConvoId = null;
    }
  }

  /// Уведомления о сообщениях показывает приложение компьютера, а не
  /// контроллер (17.09.2026).
  ///
  /// Ставит ТОЛЬКО приложение компьютера — телефон флаг не трогает, и для него
  /// ничего не меняется. Когда окно скрыто, событие идёт в
  /// [inAppNotifications] вместо системного пути, которого на компьютере нет.
  /// См. [decideIncomingNotificationChannelsForTesting].
  bool _desktopHostedNotifications = false;

  void setDesktopHostedNotifications(bool value) {
    _desktopHostedNotifications = value;
  }

  void setAppInForeground(bool value) {
    if (_appInForeground == value) return;
    _appInForeground = value;
    if (value) {
      // Arm the in-app-banner grace window: the catch-up drain kicked just below
      // flushes the whole backlog while _appInForeground is already true, so its
      // messages would otherwise each pop a banner. _maybeNotifyIncomingConvo
      // treats anything inside this window as backlog, not "live".
      _foregroundSinceMs = DateTime.now().millisecondsSinceEpoch;
      unawaited(_publishPresenceHeartbeatBestEffort(force: true));
      unawaited(_syncProfileInactivityStatusBestEffort());
      refreshPushNotificationPolicy();
      // Значок поддержки: ответ мог прийти, пока приложение было свёрнуто, а
      // 15-минутный сторож — слишком долгое ожидание для «мне только что
      // ответили». Возврат в приложение — самый естественный момент проверить.
      unawaited(refreshSupportBadge());
      // Always drain inbox on foreground resume.  Catches messages missed
      // while the WS was stale (half-open TCP) or the app was suspended.
      if (!_transportBlocked) {
        unawaited(triggerPushWakeSync());
        // Keys recovery on resume: drop any stale (MIUI-frozen) keep-alive
        // socket and re-check keys health NOW, instead of waiting up to ~3s for
        // the next watchdog tick on a dead socket. Fixes the latched
        // "Keys is offline" banner that never cleared after background.
        unawaited(_recheckKeysHealthNow());
        // OUTBOUND catch-up (message-loss audit 2026-07-08, R1): on aggressive
        // vendors (MIUI/HyperOS) the app is frozen right after a send, so a
        // message can sit in the outbox / pending-no-device queue and its only
        // flush windows are the few seconds the user has the app open. Actively
        // flush BOTH the moment we resume — the outbox pump falls back to HTTP
        // while the WS reconnects, and the no-device retry force-re-resolves the
        // peer's CURRENT devices — instead of waiting for the ≤1-min watchdog.
        unawaited(_flushOutboundOnResume());
      }
      DiagLog.event('lifecycle', 'foreground', const <String, Object?>{});
    } else {
      unawaited(_publishPresenceHeartbeatBestEffort(force: true));
      DiagLog.event('lifecycle', 'background', const <String, Object?>{});
      // Best-effort flush of pending receipts and outbox before the OS may
      // freeze/kill us. This is critical on aggressive vendors (MIUI/Vivo)
      // that swipe-clean the process from recents shortly after backgrounding.
      unawaited(_flushBeforeBackgroundBestEffort());
    }
    unawaited(_applyBackgroundConnectionPolicy());
    // iOS app-icon unread badge: keep the subscription live and reconcile the
    // count on every foreground/background transition. This is authoritative and
    // corrects the server's push-time approximation (aps.badge = pending count).
    _ensureIconBadgeSubscription();
    unawaited(_refreshAppIconBadge());
  }

  // ===========================================================================
  // iOS app-icon unread badge (other messengers show the unread count on the
  // icon). While the app is alive the client sets the TRUE unread total here;
  // while it is killed the server's aps.badge keeps the number roughly current,
  // and the next foreground reconcile below corrects any drift. No-op on Android
  // (no icon-badge API in use there; the in-app nav badges cover it).
  // ===========================================================================
  Timer? _iconBadgeDebounce;
  StreamSubscription<void>? _iconBadgeSub;

  void _ensureIconBadgeSubscription() {
    if (!Platform.isIOS || _iconBadgeSub != null) return;
    // Any `changed` tick can move the unread total (new inbound, read, or a
    // cross-device sync). Debounced so a burst collapses into one COUNT + one
    // native call.
    _iconBadgeSub = _changed.stream.listen((_) {
      _iconBadgeDebounce?.cancel();
      _iconBadgeDebounce = Timer(const Duration(milliseconds: 500), () {
        unawaited(_refreshAppIconBadge());
      });
    });
  }

  Future<void> _refreshAppIconBadge() async {
    if (!Platform.isIOS) return;
    final db = _db;
    final did = _deviceId;
    if (db == null || did == null || did.isEmpty) return;
    try {
      final count = await db.countUnreadTotal(
        selfDeviceId: did,
        excludedSenderDeviceIds: _ownDeviceIdsForUnreadQueries(),
      );
      await _nativeMsgNotifChannel.invokeMethod('setBadge', {'count': count});
    } catch (_) {
      // best-effort; the next `changed` tick or foreground reconcile retries
    }
  }

  bool _flushOutboundOnResumeInFlight = false;

  /// Message-loss audit 2026-07-08 (R1): immediately drain any outbound work
  /// that may have been stranded while the app was frozen in the background —
  /// the sender's messages that "look sent but never left the phone". Best
  /// effort, guarded against re-entrancy; both operations dedup server-side so
  /// re-running is safe. Bounded so a dead network can't hang resume.
  Future<void> _flushOutboundOnResume() async {
    if (_flushOutboundOnResumeInFlight || _transportBlocked) return;
    _flushOutboundOnResumeInFlight = true;
    try {
      final relay = _relay;
      if (relay != null) {
        try {
          await relay.pumpOutbox().timeout(const Duration(seconds: 10));
        } catch (_) {}
      }
      if (_pendingNoDeviceSend.isNotEmpty) {
        try {
          await _retryPendingNoDeviceSend().timeout(const Duration(seconds: 12));
        } catch (_) {}
      }
    } finally {
      _flushOutboundOnResumeInFlight = false;
    }
  }

  /// Public hook used by the host application to force a best-effort flush of
  /// queued receipts and outbox messages before the process may be killed by
  /// the OS (e.g. MIUI swipe-clean, low-memory trim, app task removed).
  ///
  /// Safe to call repeatedly; bounded by an internal in-flight guard.
  Future<void> flushBeforeBackground() async {
    await _flushBeforeBackgroundBestEffort();
  }

  bool _flushBeforeBackgroundInFlight = false;
  Future<void> _flushBeforeBackgroundBestEffort() async {
    if (_flushBeforeBackgroundInFlight) return;
    _flushBeforeBackgroundInFlight = true;
    final startedAtMs = DateTime.now().millisecondsSinceEpoch;
    try {
      DiagLog.event('lifecycle', 'flush_start', const <String, Object?>{});
      // 1) Persist + queue any read/delivered receipts that may still be in RAM.
      try {
        await _flushPendingReceiptsBestEffort();
      } catch (_) {}
      // 2) Push outbox to the relay over whatever transport is currently up.
      final relay = _relay;
      if (relay != null && !_transportBlocked) {
        try {
          await relay.pumpOutbox().timeout(const Duration(seconds: 8));
        } catch (_) {}
      }
      DiagLog.event('lifecycle', 'flush_done', {
        'elapsed_ms': DateTime.now().millisecondsSinceEpoch - startedAtMs,
      });
    } finally {
      _flushBeforeBackgroundInFlight = false;
    }
  }

  /// Whether the app is currently in the foreground (used by CallManager).
  bool get appInForeground => _appInForeground;

  String _normalizeAppLocalePreference(String? value) {
    final raw = (value ?? '').trim();
    final rawLower = raw.toLowerCase();
    if (raw.isEmpty ||
        rawLower == 'system' ||
        rawLower == 'default' ||
        rawLower == 'device') {
      return '';
    }
    final normalized = raw.replaceAll('-', '_').toLowerCase();
    if (normalized == 'pt_br') return 'pt_BR';
    final languageCode = normalized.split('_').first;
    if (<String>{
      'de',
      'en',
      'es',
      'fr',
      'pt',
      'ru',
      'uk',
    }.contains(languageCode)) {
      return languageCode;
    }
    return '';
  }

  Locale? _parseAppLocalePreference(String? value) {
    switch (_normalizeAppLocalePreference(value)) {
      case 'de':
        return const Locale('de');
      case 'en':
        return const Locale('en');
      case 'es':
        return const Locale('es');
      case 'fr':
        return const Locale('fr');
      case 'pt':
        return const Locale('pt');
      case 'pt_BR':
        return const Locale('pt', 'BR');
      case 'ru':
        return const Locale('ru');
      case 'uk':
        return const Locale('uk');
      default:
        return null;
    }
  }

  /// Resolves the app UI locale from the ordered device-locale preferences.
  ///
  /// Priority: (1) an explicit user choice in Settings; else, walking the device
  /// locales in order, the FIRST one that yields (2a) an exact language+country
  /// match, or (2b) a language-only match; else (3) English.
  ///
  /// It deliberately NEVER returns `supportedLocales.first` (de) or a
  /// country/script "nearest language" guess — which is exactly what Flutter's
  /// default [basicLocaleListResolution] does for an unsupported device language
  /// (see the `matchesLanguageCode ?? matchesCountryCode ?? supportedLocales.first`
  /// tail). Wired into [MaterialApp.localeListResolutionCallback] (main.dart) so
  /// the widget-tree locale stays in lock-step with the locale this controller
  /// uses for its own strings — one source of truth.
  Locale resolveAppUiLocale(List<Locale> deviceLocales) {
    final override = appLocaleOverride;
    if (override != null) {
      return override;
    }
    for (final device in deviceLocales) {
      final deviceCode = device.languageCode.toLowerCase();
      final deviceCountry = device.countryCode?.toUpperCase();
      Locale? exactMatch;
      Locale? languageMatch;
      for (final candidate in AppLocalizations.supportedLocales) {
        if (candidate.languageCode.toLowerCase() != deviceCode) continue;
        if ((candidate.countryCode?.toUpperCase()) == deviceCountry) {
          exactMatch = candidate;
          break;
        }
        languageMatch ??= candidate;
      }
      final match = exactMatch ?? languageMatch;
      if (match != null) return match;
    }
    return const Locale('en');
  }

  Locale _effectiveAppLocaleForStrings() =>
      resolveAppUiLocale(<Locale>[PlatformDispatcher.instance.locale]);

  String _effectiveAppLocaleTagForStrings() {
    final locale = _effectiveAppLocaleForStrings();
    final languageCode = locale.languageCode.toLowerCase();
    final countryCode = locale.countryCode?.toUpperCase();
    if (languageCode == 'pt' && countryCode == 'BR') return 'pt_BR';
    return languageCode;
  }

  String _localizedText({
    required String ru,
    required String en,
    String? uk,
    String? es,
    String? pt,
    String? ptBr,
    String? fr,
