  /// Called by CallManager when a call becomes active/ends.
  void setActiveCallInProgress(bool active) {
    _activeCallInProgress = active;
  }

  /// Register a callback invoked when the user taps a background notification.
  void setOnNotificationTap(void Function(String convoId) callback) {
    _onNotificationTap = callback;
    final bufferedConvoId = _pendingNotificationTapConvoId?.trim() ?? '';
    if (bufferedConvoId.isNotEmpty) {
      _pendingNotificationTapConvoId = null;
      _emitNotificationTap(bufferedConvoId);
    }
    unawaited(() async {
      final pendingConvoId =
          await PushWakeService.consumeOpenedConversationId();
      if (pendingConvoId != null && pendingConvoId.trim().isNotEmpty) {
        _emitNotificationTap(pendingConvoId.trim());
      }
    }());
  }

  void _emitNotificationTap(String? convoId) {
    final normalized = (convoId ?? '').trim();
    if (normalized.isEmpty) {
      return;
    }
    final now = DateTime.now().millisecondsSinceEpoch;
    if (_lastNotificationTapConvoId == normalized &&
        now - _lastNotificationTapAtMs < 1500) {
      return;
    }
    _lastNotificationTapConvoId = normalized;
    _lastNotificationTapAtMs = now;
    final callback = _onNotificationTap;
    if (callback != null) {
      callback(normalized);
      return;
    }
    _pendingNotificationTapConvoId = normalized;
  }

  List<DarwinNotificationCategory> _buildDarwinNotificationCategories() {
    final l10n = _appL10n;
    final replyTitle = l10n.chatMenuReply;
    final sendTitle = l10n.send;
    final markReadTitle = l10n.notificationActionMarkRead;
    final replyPlaceholder = l10n.messageHint;
    return <DarwinNotificationCategory>[
      DarwinNotificationCategory(
        _darwinMessageCategoryId,
        actions: <DarwinNotificationAction>[
          DarwinNotificationAction.text(
            _darwinMessageReplyActionId,
            replyTitle,
            buttonTitle: sendTitle,
            placeholder: replyPlaceholder,
          ),
          DarwinNotificationAction.plain(
            _darwinMessageMarkReadActionId,
            markReadTitle,
          ),
        ],
      ),
    ];
  }

  String? _darwinCategoryIdForConvo(String convoId) {
    final normalized = convoId.trim();
    if (normalized.isEmpty || normalized.startsWith('req:')) {
      return null;
    }
    return _darwinMessageCategoryId;
  }

  Future<void> _handleLocalNotificationResponse(
    NotificationResponse response,
  ) async {
    final convoId = (response.payload ?? '').trim();
    final actionId = (response.actionId ?? '').trim();
    if (response.notificationResponseType ==
        NotificationResponseType.selectedNotificationAction) {
      if (actionId == _darwinMessageReplyActionId) {
        final text = (response.input ?? '').trim();
        if (convoId.isNotEmpty && text.isNotEmpty) {
          await _handleNotificationReply(convoId: convoId, text: text);
        }
        return;
      }
      if (actionId == _darwinMessageMarkReadActionId) {
        if (convoId.isNotEmpty) {
          await _handleNotificationMarkRead(convoId: convoId);
        }
        return;
      }
    }
    _emitNotificationTap(convoId);
  }

  /// Best-effort wake sync used by push callbacks/background wakeups.
  /// 🔴 Ш-3: НЕМЕДЛЕННЫЙ НАСОС ПО ПУШУ ЗВОНКА (13.08.2026).
  ///
  /// Замер 12.08: приглашение звонка едет обычным сообщением через ящик и в поле
  /// опоздало на 8 секунд, а звонящий бросает трубку через десять. При этом сам
  /// запрос быстрый — замер по фазам показал подпись в единицы миллисекунд и
  /// сеть около ста. Значит время уходило не на сеть, а на ОЖИДАНИЕ вызова:
  /// насос дёргался после общей синхронизации пробуждения, которая сначала лечит
  /// базу и обновляет значок поддержки.
  ///
  /// Здесь — только выборка, без всего остального. Звонок ждать не может.
  /// Профиль контакта по устройству — для заведения входящего звонка из пуша.
  /// Пуш несёт устройство звонящего, но не его профиль.
  Future<String> contactProfileIdForDevice(String deviceId) async {
    final db = _db;
    if (db == null) return '';
    try {
      final fromContacts = await db.contactProfileIdByDeviceId(deviceId) ?? '';
      if (fromContacts.isNotEmpty) return fromContacts;
      // 🔴 СВОЁ ВТОРОЕ УСТРОЙСТВО — ТОЖЕ ИЗВЕСТНЫЙ ЗВОНЯЩИЙ (23.08.2026).
      //
      // Поиск шёл только по `contact_devices`, то есть по устройствам КОНТАКТОВ.
      // Звонок с собственного второго устройства там не находится по
      // определению, и экран входящего оставался без имени и фотографии —
      // жалоба 23.08: «при закрытом приложении беру трубку, ни фото, ни имени;
      // при открытом всё правильно». При открытом звонок приходит приглашением,
      // где profile_id уже готов, — поэтому там и работало.
      if (isOwnDeviceId(deviceId)) {
        return (_profileId ?? '').trim();
      }
      return '';
    } catch (_) {
      return '';
    }
  }

  Future<void> pumpInboxForCallWake() async {
    if (_transportBlocked) return;
    final startedAtMs = DateTime.now().millisecondsSinceEpoch;
    try {
      // 🔴 СВОЙ ПРЕДЕЛ ПО ВРЕМЕНИ (22.08.2026). Раньше вызов держался ровно
      // столько, сколько HTTP-клиент, и на мёртвой сети это десятки секунд.
      // Пока он стоял ПЕРЕД показом экрана звонка, столько же длилась пустая
      // главная страница. Экран теперь поднимается раньше, но предел нужен:
      // предложение соединения, приехавшее через минуту, звонку уже не поможет.
      await _relay?.pumpInbox(force: true).timeout(
        const Duration(seconds: 12),
        onTimeout: () {
          DiagLog.event('relay', 'pump_for_call_wake_timeout', {
            'ms': DateTime.now().millisecondsSinceEpoch - startedAtMs,
          });
        },
      );
      DiagLog.event('relay', 'pump_for_call_wake', {
        'ms': DateTime.now().millisecondsSinceEpoch - startedAtMs,
      });
    } catch (e) {
      // Отказ не имеет права стоить звонка: общая синхронизация ниже повторит.
      DiagLog.event('relay', 'pump_for_call_wake_failed', {
        'reason': e.runtimeType.toString(),
      });
    }
  }

  Future<void> triggerPushWakeSync({
    Iterable<String> roomCallRoomIds = const <String>[],
  }) async {
    if (_transportBlocked) return;
    // ZOMBIE-DB SELF-HEAL (2026-07-18): heal a closed-out-from-under DB handle
    // BEFORE pumping — otherwise the force-pump below fetches the whole
    // mailbox and drops every row on `error_database_closed` (empty chat until
    // restart). Await so the pump runs against the healed handle.
    await _recoverUnexpectedlyClosedDb('push_wake_sync');
    // Ответ поддержки приходит веером пушей на устройства профиля, и побудка
    // — это ровно тот момент, когда о нём стало известно. Без этого значок
    // ждал бы своего сторожа до пятнадцати минут.
    unawaited(refreshSupportBadge());
    final targetedRoomIds = roomCallRoomIds
        .map((roomId) => roomId.trim())
        .where((roomId) => roomId.isNotEmpty)
        .toSet()
        .toList(growable: false);
    // 🔴 Ш-1: СНАЧАЛА ТО, ЧТО УЖЕ ЛЕЖИТ НА ДИСКЕ (23.08.2026,
    // docs/AUDIT_INSTANT_INBOX_2026-08-16.md).
    //
    // Порядок был обратный: сперва `connect()` и сетевой `pumpInbox`, и только
    // потом импорт того, что расширение уведомлений скачало ночью. Самое
    // быстрое, что у нас есть — готовые байты на диске — ждало самого
    // медленного: сети, которая на холодном старте ещё поднимается. Отсюда
    // «сообщения приходят как новые»: они не приходят, они ПРОЯВЛЯЮТСЯ, потому
    // что применяются позже сети.
    //
    // Обе операции локальные: импорт читает файлы расширения, переигровка
    // расшифровывает из базы. Двойного применения не будет — путь идемпотентен
    // (`inbox_seen`, дедуп по `msg_id`).
    await _importStagedNseInbox();
    // Переигровка теперь ЖДЁТСЯ (была `unawaited`): именно она превращает
    // импортированные байты в сообщения на экране, ради этого весь шаг.
    await _replayAllQuarantine();

    try {
      await _relay?.connect();
    } catch (_) {
      // ignore
    }
    try {
      _kickRelayOutbox();
      // Point 1: FORCE the inbox drain on resume / push-wake. Without force,
      // a freshly-connected WS makes pumpInbox short-circuit and skip the HTTP
      // backfill, so a message that arrived while we were backgrounded can be
      // missed when the user reopens the app.
      await _relay?.pumpInbox(force: true);
    } catch (_) {
      // ignore
    }
    // Сессии могли вылечиться, пока мы спали, а карантин — пополниться свежими
    // конвертами после сетевого прохода: повторяем переигровку.
    unawaited(_replayAllQuarantine());
    // Keep the NSE's config/cursor fresh for the next background push.
    unawaited(_syncNseConfig());
    // FIX E — app-resume / push-wake trigger for proactive silence recovery.
    // Background-suspended Dart timers don't fire while frozen, so the 90 s
    // sweep can be arbitrarily late after a long suspension; kick it on resume
    // so a peer that went one-way-silent heals as soon as the user returns.
    unawaited(_runSilenceRecoverySweep());
    for (final roomId in targetedRoomIds) {
      if (_transportBlocked) {
        return;
      }
      await _tryRefreshRoomCallFromRelayBestEffort(roomId);
    }
  }

  /// PR4 (SPRINT2_AUDIT §16, 2026-05-19): desktop boot-time + wake-time
  /// eager inbox backfill. Bypasses [RelayClient.pumpInbox]'s "WS is
  /// fresh → skip HTTP" short-circuit so there's no race where the chat
  /// thread panel renders an empty list from a stale DB snapshot while
  /// the `Welcome → FetchPending` reply is still in flight on the WS.
  ///
  /// Safe to call multiple times — the inner [pumpInbox] dedup'es via the
  /// per-device monotonic `seq` cursor (persisted in SharedPreferences),
  /// so the relay only replays what the local DB hasn't seen.
  ///
  /// Mobile callers should NOT use this — it's purely an additive
  /// affordance for desktop cold-boot UX. Mobile's continuous foreground
  /// pump-timer + WS handshake already covers the equivalent path.
  Future<void> forceDesktopInboxBackfill() async {
    if (_transportBlocked) return;
    final relay = _relay;
    if (relay == null) return;
    try {
      await relay.pumpInbox(force: true);
    } catch (_) {
      // best-effort; the inbox pump retries on its next tick (1-15 s, adaptive).
    }
  }

  bool _contactDisplayNameIsCustom(Map<String, Object?>? contactRow) {
    return ((contactRow?['display_name_is_custom'] as num?)?.toInt() ?? 0) != 0;
  }

  bool _contactDisplayNameLooksLikeProfileId(
    Map<String, Object?>? contactRow,
    String localName,
  ) {
    final profileId = _trimmedMetaString(contactRow, 'contact_profile_id');
    if (profileId == null) return false;
    return localName == profileId || localName == 'req:$profileId';
  }

  String? _resolvedContactDisplayName({
    required Map<String, Object?>? contactRow,
    required Map<String, Object?>? metaRow,
    bool preferLocalName = false,
  }) {
    final localName = _trimmedMetaString(contactRow, 'display_name');
    final metaName = _trimmedMetaString(metaRow, 'nickname');
    final localNameIsProfileId =
        localName != null &&
        _contactDisplayNameLooksLikeProfileId(contactRow, localName);
    if (preferLocalName && localName != null && !localNameIsProfileId) {
      return localName;
    }
    if (_contactDisplayNameIsCustom(contactRow) &&
        localName != null &&
        !localNameIsProfileId) {
      return localName;
    }
    if (metaName != null) {
      return metaName;
    }
    return localNameIsProfileId ? null : localName;
  }

  /// Resolve a human-readable title for a conversation, using contact data.
  /// Returns the resolved title or [convoId] as fallback.
  Future<String> resolveConvoTitle(String convoId) async {
    final db = _db;
    if (db == null) return convoId;
    final cid = convoId.trim();
    if (cid.isEmpty) return convoId;

    // Group chats — use the stored convo title.
    if (cid.startsWith('group:')) {
      final row = await db.convoGet(cid);
      final title = (row?['title'] as String?)?.trim();
      return (title != null && title.isNotEmpty) ? title : 'Room';
    }

    // Extract profile ID for name resolution.
    final profileId = cid.startsWith('req:') ? cid.substring(4) : cid;
    if (profileId.isEmpty) return convoId;

    final contact = await db.contactGet(profileId);
    final meta = await db.profileMetaGet(profileId);
    final resolved = _resolvedContactDisplayName(
      contactRow: contact,
      metaRow: meta,
      preferLocalName: isSavedMessagesConvo(convoId),
    );
    if (resolved != null && resolved.isNotEmpty) return resolved;

    return convoId;
  }

  Future<String?> resolveSenderProfileId(String senderDeviceId) async {
    if (isOwnDeviceId(senderDeviceId)) return null;
    return _resolveProfileIdForDevice(senderDeviceId);
  }

  Future<bool> canForwardFromProfile(String? senderProfileId) async {
    final pid = (senderProfileId ?? '').trim();
    if (pid.isEmpty) return true;
    final myPid = (_profileId ?? '').trim();
    if (myPid.isNotEmpty && pid == myPid) return true;
    return _doesPeerAllowCategory(pid, 'forwards');
  }

  Future<bool> canForwardFromSenderDevice(String senderDeviceId) async {
    if (isOwnDeviceId(senderDeviceId)) return true;
    final senderProfileId = await _resolveProfileIdForDevice(senderDeviceId);
    return canForwardFromProfile(senderProfileId);
  }

  /// Check if a convoId represents a pending contact request (not yet accepted).
  Future<bool> isContactRequest(String convoId) async {
    final db = _db;
    if (db == null) return false;
    if (convoId.startsWith('req:')) return true;
    // Check if the conversation kind is 'request'.
    final row = await db.convoGet(convoId);
    return (row?['kind'] as String?) == 'request';
  }

  bool _isConvoQuietNow({
    required bool quietHours,
    required int quietStartHour,
    required int quietEndHour,
    required DateTime now,
  }) {
    if (!quietHours) return false;
    final h = now.hour;
    if (quietStartHour == quietEndHour) return true;
    if (quietStartHour < quietEndHour) {
      return h >= quietStartHour && h < quietEndHour;
    }
    return h >= quietStartHour || h < quietEndHour;
  }

  _ChatNotificationPolicy _loadChatNotificationPolicy({
    required SharedPreferences prefs,
    required String convoId,
    required bool defaultEnabled,
  }) {
    final prefix = 'chat_notif_v1_${convoId.trim()}_';
    final enabled = prefs.getBool('${prefix}enabled') ?? defaultEnabled;
    final sound = prefs.getBool('${prefix}sound') ?? true;
    final vibration = prefs.getBool('${prefix}vibration') ?? true;
    final quietHours = prefs.getBool('${prefix}quiet_hours') ?? false;
    final quietStartHour = (prefs.getInt('${prefix}quiet_start_hour') ?? 22)
        .clamp(0, 23)
        .toInt();
    final quietEndHour = (prefs.getInt('${prefix}quiet_end_hour') ?? 8)
        .clamp(0, 23)
        .toInt();
    return _ChatNotificationPolicy(
      enabled: enabled,
      sound: sound,
      vibration: vibration,
      quietHours: quietHours,
      quietStartHour: quietStartHour,
      quietEndHour: quietEndHour,
    );
  }

  int _normalizeNotificationPrivacyLevel(int raw) {
    if (raw <= 0) return 0;
    if (raw >= 2) return 2;
    return 1;
  }

  int _readGlobalNotificationPrivacyLevel(SharedPreferences prefs) {
    final runtime = prefs.getInt(_prefsNotifPrivacyLevelKey);
    if (runtime != null) {
      return _normalizeNotificationPrivacyLevel(runtime);
    }
    final fromSettings = prefs.getInt(_settingsNotifPrivacyLevelKey);
    if (fromSettings != null) {
      final normalized = _normalizeNotificationPrivacyLevel(fromSettings);
      unawaited(prefs.setInt(_prefsNotifPrivacyLevelKey, normalized));
      return normalized;
    }
    final legacyPreviewEnabled = _readNotifBoolCompat(
      prefs,
      runtimeKey: _prefsNotifInAppPreviewKey,
      settingsKey: _settingsNotifInAppPreviewKey,
      // Default ON — must match settings_screen's default (it assumes true).
      // The old `false` here made notifications BUILD with "show text" off for
      // any user who never explicitly saved the setting, while the settings UI
      // showed it as on — the "message text keeps turning itself off" report.
      defaultValue: true,
    );
    return legacyPreviewEnabled ? 2 : 1;
  }

  /// Reads the effective global notification privacy level (0=hidden,
  /// 1=sender only, 2=sender+text). Exposed so the Settings screen shows the
  /// same value the notification code actually uses (runtime key first, then
  /// the legacy `settings_*` mirror).
  Future<int> getGlobalNotificationPrivacyLevel() async {
    final prefs = _prefs ?? await SharedPreferences.getInstance();
    _prefs = prefs;
    return _readGlobalNotificationPrivacyLevel(prefs);
  }

  /// Single writer for the global notification privacy level. Writes BOTH the
  /// runtime key (`notif_privacy_level_v1`, which the notification code reads
  /// first) and the legacy `settings_*` mirror, plus the derived
  /// show-sender / show-text booleans on both key families. This keeps all
  /// three notification entry points (in-chat, contact profile, global
  /// Settings) in agreement: previously the Settings screen wrote only the
  /// `settings_*` key, so once the runtime key had been populated by the
  /// compat-read migration, later changes from Settings were silently
  /// shadowed by the stale runtime value.
  Future<void> setGlobalNotificationPrivacyLevel(int level) async {
    final prefs = _prefs ?? await SharedPreferences.getInstance();
    _prefs = prefs;
    final normalized = _normalizeNotificationPrivacyLevel(level);
    final showSender = normalized >= 1;
    final showText = normalized >= 2;
    await Future.wait<void>(<Future<void>>[
      prefs.setInt(_prefsNotifPrivacyLevelKey, normalized),
      prefs.setInt(_settingsNotifPrivacyLevelKey, normalized),
      prefs.setBool(_prefsNotifInAppPreviewKey, showText),
      prefs.setBool(_settingsNotifInAppPreviewKey, showText),
      prefs.setBool(_prefsNotifPrivateShowSenderKey, showSender),
      prefs.setBool(_settingsNotifPrivateShowSenderKey, showSender),
      prefs.setBool(_prefsNotifPrivateShowTextKey, showText),
      prefs.setBool(_settingsNotifPrivateShowTextKey, showText),
      prefs.setBool(_prefsNotifGroupsShowSenderKey, showSender),
      prefs.setBool(_settingsNotifGroupsShowSenderKey, showSender),
      prefs.setBool(_prefsNotifGroupsShowTextKey, showText),
      prefs.setBool(_settingsNotifGroupsShowTextKey, showText),
    ]);
    refreshPushNotificationPolicy();
  }

  _CategoryNotificationPresentation _presentationFromPrivacyLevel(
    int privacyLevel, {
    required bool alerts,
  }) {
    final normalized = _normalizeNotificationPrivacyLevel(privacyLevel);
    return _CategoryNotificationPresentation(
      alerts: alerts,
      showSender: normalized >= 1,
      showText: normalized >= 2,
    );
  }

  _CategoryNotificationPresentation _loadCategoryNotificationPresentation({
    required SharedPreferences prefs,
    required bool isGroup,
  }) {
    final defaultPrivacyLevel = _readGlobalNotificationPrivacyLevel(prefs);
    final defaultShowSender = defaultPrivacyLevel >= 1;
    final defaultShowText = defaultPrivacyLevel >= 2;
    if (isGroup) {
      return _CategoryNotificationPresentation(
        alerts: _readNotifBoolCompat(
          prefs,
          runtimeKey: _prefsNotifGroupsMessagesKey,
          settingsKey: _settingsNotifGroupsMessagesKey,
          defaultValue: true,
        ),
        showText: _readNotifBoolCompat(
          prefs,
          runtimeKey: _prefsNotifGroupsShowTextKey,
          settingsKey: _settingsNotifGroupsShowTextKey,
          defaultValue: defaultShowText,
        ),
        showSender: _readNotifBoolCompat(
          prefs,
          runtimeKey: _prefsNotifGroupsShowSenderKey,
          settingsKey: _settingsNotifGroupsShowSenderKey,
          defaultValue: defaultShowSender,
        ),
      );
    }
    return _CategoryNotificationPresentation(
      alerts: _readNotifBoolCompat(
        prefs,
        runtimeKey: _prefsNotifPrivateMessagesKey,
        settingsKey: _settingsNotifPrivateMessagesKey,
        defaultValue: true,
      ),
      showText: _readNotifBoolCompat(
        prefs,
        runtimeKey: _prefsNotifPrivateShowTextKey,
        settingsKey: _settingsNotifPrivateShowTextKey,
        defaultValue: defaultShowText,
      ),
      showSender: _readNotifBoolCompat(
        prefs,
        runtimeKey: _prefsNotifPrivateShowSenderKey,
        settingsKey: _settingsNotifPrivateShowSenderKey,
        defaultValue: defaultShowSender,
      ),
    );
  }

  int? _readChatNotificationPrivacyOverride({
    required SharedPreferences prefs,
    required String convoId,
  }) {
    final prefix = 'chat_notif_v1_${convoId.trim()}_';
    final raw = prefs.getInt('${prefix}privacy_level');
    if (raw != null) {
      return _normalizeNotificationPrivacyLevel(raw);
    }
    final legacyPreview = prefs.getBool('${prefix}preview');
    if (legacyPreview != null) {
      return legacyPreview ? 2 : 1;
    }
    return null;
  }

  int? _readContactNotificationPrivacyOverride({
    required SharedPreferences prefs,
    required String profileId,
  }) {
    final pid = profileId.trim();
    if (pid.isEmpty) return null;
    final raw = prefs.getInt('$_prefsContactNotifPrivacyPrefix$pid');
    if (raw == null) return null;
    return _normalizeNotificationPrivacyLevel(raw);
  }

  /// Reads the per-conversation notification privacy override (0/1/2), or
  /// `null` when there is no override and the global default applies.
  ///
  /// For a 1:1 chat the conversation id IS the peer profile id, so this is the
  /// single source of truth shared by the in-chat menu and the contact-profile
  /// sheet. A legacy per-contact override (written by older builds of the
  /// contact sheet) is honoured as a fallback so existing settings still show.
  Future<int?> getChatNotificationPrivacyOverride(String convoId) async {
    final cid = convoId.trim();
    if (cid.isEmpty) return null;
    final prefs = _prefs ?? await SharedPreferences.getInstance();
    _prefs = prefs;
    final chatOverride = _readChatNotificationPrivacyOverride(
      prefs: prefs,
      convoId: cid,
    );
    if (chatOverride != null) return chatOverride;
    // 1:1 fallback: surface a legacy per-contact override if one exists.
    if (!cid.startsWith('group:') && !cid.startsWith('req:')) {
      return _readContactNotificationPrivacyOverride(
        prefs: prefs,
        profileId: cid,
      );
    }
    return null;
  }

  /// Writes (or clears) the per-conversation notification privacy override so
  /// the in-chat menu, the contact-profile sheet, and the notification code all
  /// agree. Passing `null` clears the override → the conversation falls back to
  /// the global default.
  ///
  /// Also clears the legacy per-contact key for 1:1 chats so it can no longer
  /// shadow (or be shadowed by) the per-conversation value.
  Future<void> setChatNotificationPrivacyOverride(
    String convoId,
    int? level,
  ) async {
    final cid = convoId.trim();
    if (cid.isEmpty) return;
    final prefs = _prefs ?? await SharedPreferences.getInstance();
    _prefs = prefs;
    final prefix = 'chat_notif_v1_${cid}_';
    if (level == null) {
      await prefs.remove('${prefix}privacy_level');
      await prefs.remove('${prefix}preview');
    } else {
      final normalized = _normalizeNotificationPrivacyLevel(level);
      await prefs.setInt('${prefix}privacy_level', normalized);
      await prefs.setBool('${prefix}preview', normalized >= 2);
    }
    // Drop any legacy per-contact override for this 1:1 so the per-conversation
    // value is unambiguous.
    if (!cid.startsWith('group:') && !cid.startsWith('req:')) {
      await prefs.remove('$_prefsContactNotifPrivacyPrefix$cid');
    }
    refreshPushNotificationPolicy();
  }

  _CategoryNotificationPresentation _resolveEffectiveNotificationPresentation({
    required SharedPreferences prefs,
    required String convoId,
    String? peerProfileId,
  }) {
    final basePresentation = _loadCategoryNotificationPresentation(
      prefs: prefs,
      isGroup: convoId.startsWith('group:'),
    );
    final chatOverride = _readChatNotificationPrivacyOverride(
      prefs: prefs,
      convoId: convoId,
    );
    if (chatOverride != null) {
      return _presentationFromPrivacyLevel(
        chatOverride,
        alerts: basePresentation.alerts,
      );
    }
    final peerId = peerProfileId?.trim();
    if (peerId != null && peerId.isNotEmpty) {
      final contactOverride = _readContactNotificationPrivacyOverride(
        prefs: prefs,
        profileId: peerId,
      );
      if (contactOverride != null) {
        return _presentationFromPrivacyLevel(
          contactOverride,
          alerts: basePresentation.alerts,
        );
      }
    }
    return basePresentation;
  }

  int _notificationPrivacyLevelFromPresentation(
    _CategoryNotificationPresentation presentation,
  ) {
    if (presentation.showText) return 2;
    if (presentation.showSender) return 1;
    return 0;
  }

  String? _sanitizePushTransportText(String? raw, {required int maxLength}) {
    final normalized = raw?.replaceAll(RegExp(r'\s+'), ' ').trim() ?? '';
    if (normalized.isEmpty) {
      return null;
    }
    if (normalized.length <= maxLength) {
      return normalized;
    }
    final end = maxLength <= 3 ? maxLength : maxLength - 3;
    return '${normalized.substring(0, end).trim()}...';
  }

  String _pushTransportPreviewForAttachment(String? mime) {
    final normalized = (mime ?? '').trim().toLowerCase();
    if (normalized.startsWith('image/')) {
      return 'Photo';
    }
    if (normalized.startsWith('video/')) {
      return 'Video';
    }
    if (normalized.startsWith('audio/')) {
      return normalized.contains('ogg') ||
              normalized.contains('opus') ||
              normalized.contains('wav')
          ? 'Voice message'
          : 'Audio';
    }
    if (normalized == 'application/pdf') {
      return 'PDF';
    }
    if (normalized.startsWith('text/')) {
      return 'Text file';
    }
    return 'Attachment';
  }

  String _pushTransportPreviewForSticker(SecretlyStickerDescriptor sticker) {
    final label = _sanitizePushTransportText(sticker.label, maxLength: 80);
    if (label != null && label.isNotEmpty) {
      return label;
    }
    final emojiHint = _sanitizePushTransportText(
      sticker.emojiHint,
      maxLength: 24,
    );
    if (emojiHint != null && emojiHint.isNotEmpty) {
      return emojiHint;
    }
    return 'Sticker';
  }

  String _buildChatTransportMetaJson({
    required String convoId,
    required bool isGroup,
    required String messageKind,
    required String payloadEventId,
    required int createdAtMs,
    String? senderProfileId,
    String? senderDisplayName,
    String? convoTitle,
    String? previewText,
  }) {
    final cleanedConvoId = convoId.trim();
    final cleanedMessageKind = messageKind.trim().toLowerCase();
    final cleanedPayloadEventId = payloadEventId.trim();
    final cleanedSenderProfileId = (senderProfileId ?? '').trim();
    final cleanedSenderDisplayName = _sanitizePushTransportText(
      senderDisplayName,
      maxLength: 120,
    );
    final cleanedConvoTitle = _sanitizePushTransportText(
      convoTitle,
      maxLength: 120,
    );
    final cleanedPreviewText = _sanitizePushTransportText(
      previewText,
      maxLength: 180,
    );
    return jsonEncode(<String, Object?>{
      'kind': 'chat_message_v1',
      'message': <String, Object?>{
        'convo_id': cleanedConvoId,
        'is_group': isGroup,
        'category': isGroup ? 'group' : 'direct',
        'message_kind': cleanedMessageKind.isEmpty
            ? 'message'
            : cleanedMessageKind,
        'payload_event_id': cleanedPayloadEventId,
        'created_at_ms': createdAtMs,
        if (cleanedSenderProfileId.isNotEmpty)
          'sender_profile_id': cleanedSenderProfileId,
        if (cleanedSenderDisplayName != null)
          'sender_display_name': cleanedSenderDisplayName,
        if (cleanedConvoTitle != null) 'convo_title': cleanedConvoTitle,
        if (cleanedPreviewText != null) 'preview_text': cleanedPreviewText,
      },
    });
  }

  String _sanitizeSoundAssetName(String raw) {
    final trimmed = raw.trim();
    if (trimmed.isEmpty) return '';
    final safe = trimmed.replaceAll(RegExp(r'[^a-zA-Z0-9_\-]'), '');
    return safe;
  }

  String _resolveNotificationSoundAssetPath({
    required SharedPreferences prefs,
    required bool inChat,
  }) {
    final prefKey = inChat
        ? _prefsNotifInAppChatSoundAssetKey
        : _prefsNotifInAppSoundAssetKey;
    final settingsPrefKey = inChat
        ? _settingsNotifInAppChatSoundAssetKey
        : _settingsNotifInAppSoundAssetKey;
    final fallback = inChat
        ? _defaultInChatSoundAssetName
        : _defaultNotifSoundAssetName;
    final folder = inChat ? 'inchat' : 'noti';
    final chosen = _sanitizeSoundAssetName(
      _readNotifStringCompat(
            prefs,
            runtimeKey: prefKey,
            settingsKey: settingsPrefKey,
          ) ??
          fallback,
    );
    final effective = chosen.isEmpty ? fallback : chosen;
    return AppAssetPaths.notificationSong(folder: folder, basename: effective);
  }

  bool _readNotifBoolCompat(
    SharedPreferences prefs, {
    required String runtimeKey,
    required String settingsKey,
    required bool defaultValue,
  }) {
    final runtime = prefs.getBool(runtimeKey);
    if (runtime != null) return runtime;
    final fromSettings = prefs.getBool(settingsKey);
    if (fromSettings != null) {
      unawaited(prefs.setBool(runtimeKey, fromSettings));
      return fromSettings;
    }
    return defaultValue;
  }

  int _readNotifIntCompat(
    SharedPreferences prefs, {
    required String runtimeKey,
    required String settingsKey,
    required int defaultValue,
  }) {
    final runtime = prefs.getInt(runtimeKey);
    if (runtime != null) return runtime;
    final fromSettings = prefs.getInt(settingsKey);
    if (fromSettings != null) {
      unawaited(prefs.setInt(runtimeKey, fromSettings));
      return fromSettings;
    }
    return defaultValue;
  }

  String? _readNotifStringCompat(
    SharedPreferences prefs, {
    required String runtimeKey,
    required String settingsKey,
  }) {
    final runtime = prefs.getString(runtimeKey);
    if (runtime != null && runtime.trim().isNotEmpty) return runtime;
    final fromSettings = prefs.getString(settingsKey);
    if (fromSettings != null && fromSettings.trim().isNotEmpty) {
      unawaited(prefs.setString(runtimeKey, fromSettings));
      return fromSettings;
    }
    return runtime;
  }

  @visibleForTesting
  static bool readBackgroundNotificationCardEnabledForTesting(
    SharedPreferences prefs,
  ) {
    final runtime = prefs.getBool(_prefsNotifBackgroundCardKey);
    if (runtime != null) return runtime;
    final fromSettings = prefs.getBool(_settingsNotifBackgroundCardKey);
    if (fromSettings != null) {
      unawaited(prefs.setBool(_prefsNotifBackgroundCardKey, fromSettings));
      return fromSettings;
    }

    final hadLegacyValue =
        prefs.getBool(_prefsNotifInAppPopupKey) != null ||
        prefs.getBool(_settingsNotifInAppPopupKey) != null;
    if (hadLegacyValue) {
      unawaited(prefs.setBool(_prefsNotifBackgroundCardKey, true));
    }
    return true;
  }

  @visibleForTesting
  static ({bool inAppCue, bool inAppBanner, bool systemNotification})
  decideIncomingNotificationChannelsForTesting({
    required bool appInForeground,
    required bool isActiveConvo,
    required bool foregroundNotificationUxEnabled,
    required bool playSound,
    required bool vibrate,
    required bool suppressSystemNotificationForRecentPushWake,
    required bool backgroundNotificationCardEnabled,
    bool desktopHostedNotifications = false,
  }) {
    if (appInForeground) {
      if (!foregroundNotificationUxEnabled || isActiveConvo) {
        return (inAppCue: false, inAppBanner: false, systemNotification: false);
      }
      return (
        inAppCue: playSound || vibrate,
        inAppBanner: true,
        systemNotification: false,
      );
    }

    // 🔴 Компьютер: окно скрыто или свёрнуто (17.09.2026). Системного пути у
    // контроллера там нет (на macOS он выключен), уведомление показывает
    // служба компьютера — по тому же потоку, что и баннер. Без этого скрытое
    // окно молчало обо всех сообщениях. Открытая переписка не исключение:
    // окна не видно, значит человек её не читает.
    if (desktopHostedNotifications) {
      return (
        inAppCue: false,
        inAppBanner:
            !suppressSystemNotificationForRecentPushWake &&
            backgroundNotificationCardEnabled,
        systemNotification: false,
      );
    }

    return (
      inAppCue: false,
      inAppBanner: false,
      systemNotification:
          !suppressSystemNotificationForRecentPushWake &&
          backgroundNotificationCardEnabled,
    );
  }

  bool _readBackgroundNotificationCardEnabled(SharedPreferences prefs) {
    return readBackgroundNotificationCardEnabledForTesting(prefs);
  }

  Future<void> _applyBackgroundConnectionPolicy() async {
    final prefs = _prefs;
    if (prefs == null) return;
    final allowBackgroundConnection = _readNotifBoolCompat(
      prefs,
      runtimeKey: _prefsNotifBackgroundConnectionKey,
      settingsKey: _settingsNotifBackgroundConnectionKey,
      defaultValue: true,
    );

    if (_appInForeground) {
      if (!_relayOnline) {
        try {
          await _relay?.connect();
        } catch (_) {
          // ignore
        }
      }
      return;
    }

    if (!allowBackgroundConnection) {
      try {
        await _relay?.disconnect();
      } catch (_) {
        // ignore
      }
      _relayOnline = false;
    }
  }

  Future<void> _playInAppNotificationCue({
    required bool playSound,
    required bool vibrate,
    required String soundAssetPath,
  }) async {
    if (playSound) {
      try {
        await _ensureNotificationCueAudioAttributes();
        await _notificationPlayer.setLoopMode(LoopMode.off);
        await _notificationPlayer.setVolume(0.24);
        await _notificationPlayer.setAsset(soundAssetPath);
        await _notificationPlayer.seek(Duration.zero);
        // 🔴 НЕ ЖДАТЬ ОКОНЧАНИЯ ЗВУКА. По документации пакета Future от play()
        // завершается, когда проигрывание ЗАКОНЧИЛОСЬ, а не когда началось.
        // Замер 12.08.2026: проход разбора вставал здесь на 11,4 секунды при
        // бюджете в 12 — успевал ровно одно сообщение из пачки и обрывался, а
        // остальные ждали следующего пуша. Звук — это следствие доставки, и
        // доставка не должна его дожидаться.
        unawaited(_notificationPlayer.play().catchError((Object _) {}));
      } catch (_) {}
    }
    if (vibrate) {
      try {
        await HapticFeedback.mediumImpact();
      } catch (_) {}
    }
  }

  Future<void> _initLocalNotifications() async {
    try {
      final darwinCategories = _buildDarwinNotificationCategories();
      final initSettings = InitializationSettings(
        android: AndroidInitializationSettings('@mipmap/ic_launcher'),
        iOS: DarwinInitializationSettings(
          requestAlertPermission: false,
          requestBadgePermission: false,
          requestSoundPermission: false,
          notificationCategories: darwinCategories,
        ),
        macOS: DarwinInitializationSettings(
          requestAlertPermission: false,
          requestBadgePermission: false,
          requestSoundPermission: false,
          notificationCategories: darwinCategories,
        ),
      );
      await _localNotifications.initialize(
        initSettings,
        onDidReceiveNotificationResponse: (NotificationResponse response) {
          unawaited(_handleLocalNotificationResponse(response));
        },
      );
      final launchDetails = await _localNotifications
          .getNotificationAppLaunchDetails();
      final launchResponse = launchDetails?.notificationResponse;
      if (launchDetails?.didNotificationLaunchApp == true &&
          launchResponse != null) {
        await _handleLocalNotificationResponse(launchResponse);
      }
      final androidImpl = _localNotifications
          .resolvePlatformSpecificImplementation<
            AndroidFlutterLocalNotificationsPlugin
          >();
      if (androidImpl != null) {
        await androidImpl.createNotificationChannel(
          const AndroidNotificationChannel(
            _notifChannelId,
            _notifChannelName,
            description: _notifChannelDescription,
            importance: Importance.high,
            playSound: true,
            enableVibration: true,
          ),
        );
        final granted = await androidImpl.requestNotificationsPermission();
        _localNotificationsPermissionGranted = granted ?? true;
      }
      final iosImpl = _localNotifications
          .resolvePlatformSpecificImplementation<
            IOSFlutterLocalNotificationsPlugin
          >();
      if (iosImpl != null) {
        final granted = await iosImpl.requestPermissions(
          alert: true,
          badge: true,
          sound: true,
        );
        _localNotificationsPermissionGranted = granted ?? true;
      }
      final macosImpl = _localNotifications
          .resolvePlatformSpecificImplementation<
            MacOSFlutterLocalNotificationsPlugin
          >();
      if (macosImpl != null) {
        _localNotificationsPermissionGranted = false;
      }
      _localNotificationsReady = true;
    } catch (e) {
      _localNotificationsReady = false;
      callLog('AppCtrl', 'local notifications init failed: $e');
    }

    _nativeNotifTapSub?.cancel();
    _nativeMsgActionsSub?.cancel();

    if (_supportsNativeNotificationActionChannels) {
      // Listen for native notification taps (MessagingStyle notifications).
      _nativeNotifTapSub = _nativeNotifTapChannel
          .receiveBroadcastStream()
          .listen((event) {
            if (event is String) {
              _emitNotificationTap(event);
            }
          }, onError: (_) {});

      // Listen for notification reply / mark-read actions.
      _nativeMsgActionsSub = _nativeMsgActionsChannel
          .receiveBroadcastStream()
          .listen((event) {
            if (event is Map) {
              final action = (event['action'] as String?) ?? '';
              final convoId = (event['convoId'] as String?) ?? '';
              if (convoId.isEmpty) return;
              if (action == 'reply') {
                final text = (event['text'] as String?) ?? '';
                if (text.isNotEmpty) {
                  _handleNotificationReply(convoId: convoId, text: text);
                }
              } else if (action == 'mark_read') {
                _handleNotificationMarkRead(convoId: convoId);
              }
            }
          }, onError: (_) {});
    } else {
      _nativeNotifTapSub = null;
      _nativeMsgActionsSub = null;
    }

    _pushWakeOpenedConvoSub?.cancel();
    _pushWakeOpenedConvoSub = PushWakeService.onOpenedConversation.listen((
      convoId,
    ) {
      final normalized = convoId.trim();
      if (normalized.isEmpty) {
        return;
      }
      _emitNotificationTap(normalized);
    });

    // DELIVERY FIX (2026-06-19): a push that lands while the app is ALREADY
    // foreground must still force-drain the inbox. Previously only the
    // background→foreground transition force-pumped; an in-foreground push only
    // marked a wake hint, so the message waited on the WS (which flaps) and the
    // non-force timer pump (which skips while the WS looks "fresh"). Result:
    // notification shows, message never lands. Debounce coalesces relay
    // re-push bursts into one forced pump.
    _pushWakeMsgSub?.cancel();
    _pushWakeMsgSub = PushWakeService.onMessageWake.listen((_) {
      _scheduleForegroundPushPump();
    });
  }

  void _scheduleForegroundPushPump() {
    if (_transportBlocked) return;
    // Coalesce a burst of pushes (relay re-pushes the same pending message
    // until it is fetched + ACKed) into a single forced drain.
    if (_foregroundPushPumpDebounce?.isActive ?? false) return;
    _foregroundPushPumpDebounce = Timer(const Duration(milliseconds: 400), () {
      if (_transportBlocked) return;
      // Nudge the WS to recover too, then force the HTTP /v1/pending drain
      // (independent of WS state, so a flapping WS can't starve it).
      final relay = _relay;
      if (relay == null) return;
      unawaited(relay.connect().catchError((_) {}));
      _kickRelayInbox(relay: relay, force: true);
    });
  }

  /// Who wrote the room message a notification is about.
  ///
  /// Prefers what the caller passed — the envelope carries the author's profile
  /// id (and its device id) for exactly this reason. The "latest unread in the
  /// room" query is a LAST resort: it answers "who wrote most recently", which
  /// is a different member the moment two people write at once, and naming the
  /// wrong author on a message is not a cosmetic defect in a messenger.
  /// Whether my stored copy of a message in [convoId] is byte-identical to what
  /// the peer should receive — i.e. whether it can be re-sent as-is to repair a
  /// lost delivery.
  ///
  /// True for 1:1 chats, where the local copy IS the peer wire. FALSE for
  /// rooms: members receive a `__secretly_group_msg_v1__:` control envelope
  /// (room id, roster, sender identity) while the local copy is the bare
  /// message, so replaying it would land the room's message in a private chat
  /// with its author. The sender key makes the room wire replayable and will
  /// flip this.
  @visibleForTesting
  static bool canReplayLocalCopyToPeer(String convoId) =>
      !convoId.trim().startsWith('group:');

  /// Whether an applied room frame owes its author a `delivered` receipt.
  ///
  /// This is the per-member delivery evidence rooms lacked entirely until
  /// 2026-07-30 — without it "9 of 10 members never got it" is invisible, and
  /// the convergence backstop has nothing to detect. Excluded:
  ///  * my own send arriving via self-mirror — acknowledging myself to myself;
  ///  * `system` frames (joins, renames) — not user messages, and receipting
  ///    them would multiply membership churn into receipt traffic;
  ///  * frames with no sender device or no payload event id — there is nobody
  ///    to answer, and a receipt referring to nothing cannot be matched.
  @visibleForTesting
  static bool shouldSendRoomDeliveredReceipt({
    required bool isOwnSend,
    required String kind,
    required String senderDeviceId,
    required String payloadEventId,
  }) =>
      !isOwnSend &&
      kind.trim() != 'system' &&
      senderDeviceId.trim().isNotEmpty &&
      payloadEventId.trim().isNotEmpty;

  @visibleForTesting
  static Future<String?> resolveRoomSenderProfileId({
    required AppDb db,
    required String selfDeviceId,
    required String convoId,
    required Iterable<String> ownDeviceIds,
    String? senderProfileId,
    String? senderDeviceId,
  }) async {
    final pid = (senderProfileId ?? '').trim();
    if (pid.isNotEmpty) return pid;
    final did = (senderDeviceId ?? '').trim();
    if (did.isNotEmpty) {
      final resolved = (await db.deviceProfileCached(did))?.trim();
      if (resolved != null && resolved.isNotEmpty) return resolved;
    }
    final latest = await db.latestUnreadIncomingForConvo(
      convoId: convoId,
      selfDeviceId: selfDeviceId,
      excludedSenderDeviceIds: ownDeviceIds,
    );
    final latestDid = latest?.senderDeviceId.trim();
    if (latestDid == null || latestDid.isEmpty) return null;
    return (await db.deviceProfileCached(latestDid))?.trim();
  }

  Future<String?> _resolveRoomSenderProfileId({
    required AppDb db,
    required String selfDeviceId,
    required String convoId,
    String? senderProfileId,
    String? senderDeviceId,
  }) => resolveRoomSenderProfileId(
    db: db,
    selfDeviceId: selfDeviceId,
    convoId: convoId,
    ownDeviceIds: _ownDeviceIdsForUnreadQueries(),
    senderProfileId: senderProfileId,
    senderDeviceId: senderDeviceId,
  );

  Future<String?> _resolveNotificationAvatarPath({
    required String convoId,
    required bool showAvatar,
    // The author of THIS message. Without it the room fallback below has to
    // guess from "the latest unread in the room", which is a different message
    // whenever two members write at once.
    String? senderProfileId,
    String? senderDeviceId,
  }) async {
    if (!showAvatar) return null;
    String? avatarPath;
    try {
      final db = _db;
      if (db != null) {
        // For 1:1 chats the convoId IS the peer's profileId.
        // For request chats convoId = "req:<profileId>" — strip the prefix.
        final isGroup = convoId.startsWith('group:');
        final isRequest = convoId.startsWith('req:');
        String? profileId;
        if (!isGroup) {
          profileId = isRequest ? convoId.substring(4) : convoId;
        }
        if (profileId != null && profileId.isNotEmpty) {
          final contact = await db.contactGet(profileId);
          final meta = await db.profileMetaGet(profileId);
          avatarPath = _visiblePeerAvatarPath(
            contactRow: contact,
            metaRow: meta,
          );
          if (avatarPath != null && avatarPath.isNotEmpty) {
            try {
              final f = File(avatarPath);
              if (!f.existsSync() || f.lengthSync() == 0) {
                callLog(
                  'AppCtrl',
                  'notification avatar file missing/empty: $avatarPath',
                );
                avatarPath = null;
              }
            } catch (_) {
              avatarPath = null;
            }
          }
        }
        // For groups, the notification icon should be the ROOM's own
        // avatar (the sender's name already appears in the title/body) —
        // this was previously missing entirely, so group notifications
        // fell through straight to the sender-avatar fallback below (wrong
        // avatar when found; no icon at all when the sender has no cached
        // contact photo, which is common for unverified/new members).
        if (isGroup) {
          final groupSettings = await db.groupSettingsGet(convoId);
          final groupAvatar = (groupSettings?['avatar_path'] as String?)
              ?.trim();
          if (groupAvatar != null && groupAvatar.isNotEmpty) {
            try {
              final f = File(groupAvatar);
              if (f.existsSync() && f.lengthSync() > 0) {
                avatarPath = groupAvatar;
              }
            } catch (_) {}
          }
        }
        // Fallback only if the room has no avatar set: try to resolve the
        // sender's avatar from the last incoming event's senderDeviceId ->
        // profileId -> contact avatar.
        if (isGroup && (avatarPath == null || avatarPath.isEmpty)) {
          final selfDid = _deviceId;
          if (selfDid != null && selfDid.isNotEmpty) {
            // Prefer the author this notification is actually about. The
            // latest-unread query is only a fallback for callers that could
            // not supply one — it names whoever wrote MOST RECENTLY, which is
            // a different member as soon as two people write at once.
            final senderPid = await _resolveRoomSenderProfileId(
              db: db,
              selfDeviceId: selfDid,
              convoId: convoId,
              senderProfileId: senderProfileId,
              senderDeviceId: senderDeviceId,
            );
            {
              if (senderPid != null && senderPid.isNotEmpty) {
                final senderContact = await db.contactGet(senderPid);
                final senderMeta = await db.profileMetaGet(senderPid);
                avatarPath = _visiblePeerAvatarPath(
                  contactRow: senderContact,
                  metaRow: senderMeta,
                );
                if (avatarPath != null && avatarPath.isNotEmpty) {
                  try {
                    final f = File(avatarPath);
                    if (!f.existsSync() || f.lengthSync() == 0) {
                      avatarPath = null;
                    }
                  } catch (_) {
                    avatarPath = null;
                  }
                }
                // Contact lookup only resolves saved/verified contacts — most
                // room members never go through that flow. Fall back to the
                // room's own membership roster, which has an avatar for any
                // member regardless of contact status (fixes the "sometimes
                // photo+name, sometimes neither" inconsistency in group
                // notifications).
                if (avatarPath == null || avatarPath.isEmpty) {
                  try {
                    final members = await listRoomMembersDetailed(convoId);
                    final member = members
                        .where((m) => m.profileId == senderPid)
                        .cast<RoomMember?>()
                        .firstOrNull;
                    final memberAvatar = member?.avatarPath?.trim();
                    if (memberAvatar != null && memberAvatar.isNotEmpty) {
                      final f = File(memberAvatar);
                      if (f.existsSync() && f.lengthSync() > 0) {
                        avatarPath = memberAvatar;
                      }
                    }
                  } catch (_) {}
                }
              }
            }
          }
        }
      }
    } catch (_) {}

    return avatarPath;
  }

  Future<void> _showSystemNotification({
    required String convoId,
    required String title,
    required String body,
    required bool playSound,
    required bool vibrate,
    required String? avatarPath,
  }) async {
    if (!_localNotificationsPermissionGranted) return;

    callLog(
      'AppCtrl',
      'notification avatar: convoId=$convoId avatarPath=$avatarPath',
    );

    // The custom native channel is only registered on the foreground engine.
    // From the background isolate go straight to flutter_local_notifications,
    // which is designed for exactly this and IS registered on the background
    // engine — the try below would otherwise fail into the same fallback but
    // after a wasted round trip that can hang a throwaway isolate.
    if (_backgroundInboundMode) {
      await _showSystemNotificationViaPlugin(
        convoId: convoId,
        title: title,
        body: body,
        playSound: playSound,
        vibrate: vibrate,
      );
      return;
    }

    try {
      await _nativeMsgNotifChannel.invokeMethod('show', <String, dynamic>{
        'convoId': convoId,
        'title': title,
        'body': body,
        'avatarPath': avatarPath,
        'playSound': playSound,
        'vibrate': vibrate,
      });
      DiagLog.event('notif', 'show_request', {
        'convo': DiagLog.pfx(convoId),
        'has_avatar': avatarPath != null && avatarPath.isNotEmpty,
        'sound': playSound,
        'vibrate': vibrate,
      });
    } catch (e) {
      callLog('AppCtrl', 'native message notification failed: $e');
      DiagLog.event('notif', 'show_fail', {
        'convo': DiagLog.pfx(convoId),
        'reason': _classifyShortReason(e),
      });
      // Fallback to flutter_local_notifications.
      await _showSystemNotificationViaPlugin(
        convoId: convoId,
        title: title,
        body: body,
        playSound: playSound,
        vibrate: vibrate,
      );
    }
  }

  /// Post a message banner directly through flutter_local_notifications. The
  /// foreground path uses this only as a fallback; the background isolate uses
  /// it as the primary, because the custom native channel is not registered
  /// there. Extracted verbatim so both callers stay identical.
  Future<void> _showSystemNotificationViaPlugin({
    required String convoId,
    required String title,
    required String body,
    required bool playSound,
    required bool vibrate,
  }) async {
    if (!_localNotificationsReady) return;
    try {
      final id = convoId.hashCode & 0x7fffffff;
      final details = NotificationDetails(
        android: AndroidNotificationDetails(
          _notifChannelId,
          _notifChannelName,
          channelDescription: _notifChannelDescription,
          importance: Importance.high,
          priority: Priority.high,
          playSound: playSound,
          enableVibration: vibrate,
          ticker: title,
        ),
        iOS: DarwinNotificationDetails(
          presentAlert: true,
          presentBanner: true,
          presentList: true,
          presentBadge: true,
          presentSound: playSound,
          categoryIdentifier: _darwinCategoryIdForConvo(convoId),
          threadIdentifier: convoId,
        ),
        macOS: DarwinNotificationDetails(
          presentAlert: true,
          presentBadge: true,
          presentSound: playSound,
          categoryIdentifier: _darwinCategoryIdForConvo(convoId),
          threadIdentifier: convoId,
        ),
      );
      await _localNotifications.show(id, title, body, details, payload: convoId);
    } catch (_) {}
  }

  /// Handle inline reply from a notification action.
  Future<void> _handleNotificationReply({
    required String convoId,
    required String text,
  }) async {
    try {
      // For 1:1 chats the convoId is the peerProfileId.
      final isGroup = convoId.startsWith('group:');
      final isRequest = convoId.startsWith('req:');
      if (isRequest) return; // Can't reply to request chats from notification.

      if (isGroup) {
        await sendGroupMessage(groupId: convoId, text: text);
      } else {
        await sendMessage(peerProfileId: convoId, text: text);
      }
    } catch (e) {
      callLog('AppCtrl', 'notification reply failed: $e');
    }
  }

  /// Handle mark-as-read from a notification action.
  Future<void> _handleNotificationMarkRead({required String convoId}) async {
    try {
      if (convoId.startsWith('req:')) return;
      await markChatRead(peerProfileId: convoId);
      await _nativeMsgNotifChannel.invokeMethod('cancel', <String, dynamic>{
        'convoId': convoId,
      });
    } catch (e) {
      callLog('AppCtrl', 'notification mark-read failed: $e');
    }
  }

  // BUG-3: hydrate the notified-message dedup set from disk exactly once, so a
  // message that already raised a notification before the app was killed cannot
  // notify again when the relay redelivers it after relaunch. Best-effort: any
  // failure leaves the in-memory map authoritative (same as before).
  Future<void> _ensureNotifiedDedupLoaded() async {
    if (_notifiedDedupLoaded) return;
    final prefs = _prefs;
    // Retry on a later call if prefs is not ready yet (do not mark loaded).
    if (prefs == null) return;
    _notifiedDedupLoaded = true;
    try {
      final raw = prefs.getString(_prefsNotifiedDedupKey);
      if (raw == null || raw.isEmpty) return;
      final decoded = jsonDecode(raw);
      if (decoded is! Map) return;
      final nowMs = DateTime.now().millisecondsSinceEpoch;
      final cutoff = nowMs - (24 * 60 * 60 * 1000);
      decoded.forEach((key, value) {
        final ts = value is num ? value.toInt() : null;
        if (key is String && key.isNotEmpty && ts != null && ts >= cutoff) {
          // Keep the freshest timestamp if the runtime already saw this id.
          final existing = _lastNotifiedMessageAtMs[key];
          if (existing == null || ts > existing) {
            _lastNotifiedMessageAtMs[key] = ts;
          }
        }
      });
    } catch (_) {
      // Corrupt/old payload — ignore and rely on the in-memory map.
    }
  }

  // BUG-3: persist the dedup map, throttled to at most once per 10s to keep the
  // notify path cheap. Caps the serialised size to the freshest 2500 entries.
  void _persistNotifiedDedupBestEffort(int nowMs) {
    final prefs = _prefs;
    if (prefs == null) return;
    if (nowMs - _notifiedDedupPersistedAtMs < 10000) return;
    _notifiedDedupPersistedAtMs = nowMs;
    try {
      final cutoff = nowMs - (24 * 60 * 60 * 1000);
      var entries = _lastNotifiedMessageAtMs.entries
          .where((e) => e.value >= cutoff)
          .toList(growable: false);
      if (entries.length > 2500) {
        entries = (entries.toList()..sort((a, b) => b.value.compareTo(a.value)))
            .sublist(0, 2500);
      }
      final map = <String, int>{for (final e in entries) e.key: e.value};
      unawaited(prefs.setString(_prefsNotifiedDedupKey, jsonEncode(map)));
    } catch (_) {
      // Best-effort only.
    }
  }

  Future<void> _maybeNotifyIncomingConvo({
    required String convoId,
    String? previewText,
    String? sourceMessageId,
    int? sourceCreatedAtMs,
    String? senderDeviceId,
    String? senderProfileId,
    bool mentionsMe = false,
  }) async {
    final cid = convoId.trim();
    if (cid.isEmpty) return;
    // Self-echo guard: if this delivered message originated from one of our
    // own device IDs (multi-device sync, or stale registration of a previous
    // install of THIS device on the keys server), never raise a system
    // notification — you should never be alerted about your own sent message.
    final sdid = (senderDeviceId ?? '').trim();
    if (sdid.isNotEmpty && isOwnDeviceId(sdid)) {
      DiagLog.event('notif', 'suppress_self_echo', {
        'convo': DiagLog.pfx(cid),
        'sender_dev': DiagLog.pfx(sdid),
      });
      return;
    }
    // Profile-level self-echo guard. A self-fanout from ANOTHER of my devices
    // can arrive before that device id is known locally (device→profile cache
    // empty / _transportBlocked), so the device-id guard above misses it and my
    // own room message raises a notification. The sender stamps its own profile
    // id in the envelope, which is present even when live device resolution
    // fails — if it equals mine, this is my own message. SUPPRESS-ONLY: an
    // unresolved/foreign profile id never forces a notification.
    final spid = (senderProfileId ?? '').trim();
    final selfPid = (_profileId ?? '').trim();
    if (spid.isNotEmpty && selfPid.isNotEmpty && spid == selfPid) {
      DiagLog.event('notif', 'suppress_self_profile', {
        'convo': DiagLog.pfx(cid),
        'sender_pid': DiagLog.pfx(spid),
      });
      return;
    }
    final nowMs = DateTime.now().millisecondsSinceEpoch;
    if (shouldSuppressNotificationForSourceAge(
      nowMs: nowMs,
      sourceCreatedAtMs: sourceCreatedAtMs,
    )) {
      return;
    }
    // 🔴 DEDUP KEYS (2026-08-01, field: "notifications for messages I already
    // read"). Keying on the relay `msg_id` alone is not enough: OUR OWN
    // recovery machinery — the convergence backstop and the answer to a NACK —
    // re-sends the same logical message as a NEW relay message with a NEW id.
    // That copy sails past the dedup and rings for text the person read
    // minutes ago. The resend traffic grew this week, which is why the symptom
    // showed up now.
    //
    // The logical identity that SURVIVES a resend is the message's own
    // creation time, stamped by the sender when it was composed. Two different
    // messages in one conversation sharing the same millisecond is not a real
    // scenario; the same message re-sent three times is.
    //
    // Deliberately an ADDITIONAL key, not a replacement: the msg_id key still
    // catches relay-level re-offers of the identical envelope.
    final srcMsgId = sourceMessageId?.trim();
    final createdKey = (sourceCreatedAtMs != null && sourceCreatedAtMs > 0)
        ? 'c:$cid@$sourceCreatedAtMs'
        : null;
    if (createdKey != null) {
      await _ensureNotifiedDedupLoaded();
      final prevByContent = _lastNotifiedMessageAtMs[createdKey];
      if (prevByContent != null &&
          (nowMs - prevByContent) < (24 * 60 * 60 * 1000)) {
        DiagLog.event('notif', 'suppress_resend_duplicate', {
          'convo': DiagLog.pfx(cid),
        });
        return;
      }
      _lastNotifiedMessageAtMs[createdKey] = nowMs;
    }
    if (srcMsgId != null && srcMsgId.isNotEmpty) {
      await _ensureNotifiedDedupLoaded();
      final prev = _lastNotifiedMessageAtMs[srcMsgId];
      if (prev != null && (nowMs - prev) < (24 * 60 * 60 * 1000)) {
        return;
      }
      _lastNotifiedMessageAtMs[srcMsgId] = nowMs;
      if (_lastNotifiedMessageAtMs.length > 2500) {
        final cutoff = nowMs - (24 * 60 * 60 * 1000);
        _lastNotifiedMessageAtMs.removeWhere((_, ts) => ts < cutoff);
      }
      _persistNotifiedDedupBestEffort(nowMs);
    }
    // Never interrupt the user with notification cues during an active call.
    if (_activeCallInProgress) return;
    final prefs = _prefs;
    final db = _db;
    final did = _deviceId;
    if (prefs == null || db == null || did == null || did.isEmpty) return;
    if (!_readNotifBoolCompat(
      prefs,
      runtimeKey: _prefsNotifAllAccountsKey,
      settingsKey: _settingsNotifAllAccountsKey,
      defaultValue: true,
    )) {
      return;
    }

    final isGroup = cid.startsWith('group:');
    if (isGroup) {
      if (!_readNotifBoolCompat(
        prefs,
        runtimeKey: _prefsNotifGroupsKey,
        settingsKey: _settingsNotifGroupsKey,
        defaultValue: true,
      )) {
        return;
      }
    } else {
      if (!_readNotifBoolCompat(
        prefs,
        runtimeKey: _prefsNotifPrivateChatsKey,
        settingsKey: _settingsNotifPrivateChatsKey,
        defaultValue: true,
      )) {
        return;
      }
    }

    final row = await db.convoGet(cid);
    // Evaluate timed mutes dynamically. The boolean `muted` column is only a
    // snapshot written when the mute was applied, so a "mute for 1 hour" that
    // has since expired would otherwise keep suppressing until the maintenance
    // sweep flips it. Re-derive the effective state from `muted_until_ms`:
    //   -1  => muted forever, >0 => muted until that epoch-ms,
    //    0  => no timed mute (fall back to the boolean flag).
    final mutedUntilMs = (row?['muted_until_ms'] as num?)?.toInt() ?? 0;
    final mutedFlag = ((row?['muted'] as num?)?.toInt() ?? 0) != 0;
    final muted = mutedUntilMs == -1
        ? true
        : (mutedUntilMs > 0 ? mutedUntilMs > nowMs : mutedFlag);
    if (muted) {
      // "Mentions only" still surfaces messages that @-mention me.
      final mentionsOnly =
          ((row?['muted_mentions_only'] as num?)?.toInt() ?? 0) != 0;
      if (!(mentionsOnly && mentionsMe)) return;
    }

    final chatPolicy = _loadChatNotificationPolicy(
      prefs: prefs,
      convoId: cid,
      defaultEnabled: true,
    );
    if (!chatPolicy.enabled) return;
    final now = DateTime.fromMillisecondsSinceEpoch(nowMs);
    if (_isConvoQuietNow(
      quietHours: chatPolicy.quietHours,
      quietStartHour: chatPolicy.quietStartHour,
      quietEndHour: chatPolicy.quietEndHour,
      now: now,
    )) {
      return;
    }

    String? peerProfileIdForPrivacy;
    if (cid.startsWith('req:')) {
      final reqPid = cid.substring(4).trim();
      if (reqPid.isNotEmpty) {
        peerProfileIdForPrivacy = reqPid;
      }
    } else if (!cid.startsWith('group:')) {
      peerProfileIdForPrivacy = cid;
    }
    final notificationPresentation = _resolveEffectiveNotificationPresentation(
      prefs: prefs,
      convoId: cid,
      peerProfileId: peerProfileIdForPrivacy,
    );
    if (!notificationPresentation.alerts) {
      return;
    }
    final l10n = _appL10n;

    // Build title from the conversation/contact name.
    String notifTitle = l10n.appTitle;
    String conversationTitle = cid.startsWith('group:')
        ? l10n.notificationTitleRoom
        : l10n.appTitle;
    // Автор сообщения в комнате — когда заголовок баннера стал его именем.
    String? bannerSenderPid;
    try {
      final convoTitle = ((row?['title'] as String?) ?? '').trim();
      if (convoTitle.isNotEmpty) {
        notifTitle = convoTitle;
        conversationTitle = convoTitle;
      } else if (cid.startsWith('group:')) {
        notifTitle = l10n.notificationTitleRoom;
        conversationTitle = notifTitle;
      } else if (cid.startsWith('req:')) {
        // For incoming requests, resolve the sender's nickname.
        final reqPid = cid.substring(4);
        final meta = await db.profileMetaGet(reqPid);
        final nick = (meta?['nickname'] as String?)?.trim();
        if (nick != null && nick.isNotEmpty) {
          notifTitle = nick;
        } else {
          notifTitle = l10n.notificationTitleRequest;
        }
      } else {
        // 1:1 chat — resolve contact display name.
        final contact = await db.contactGet(cid);
        final meta = await db.profileMetaGet(cid);
        final resolvedTitle = _resolvedContactDisplayName(
          contactRow: contact,
          metaRow: meta,
          preferLocalName: isSavedMessagesConvo(cid),
        );
        if (resolvedTitle != null && resolvedTitle.isNotEmpty) {
          notifTitle = resolvedTitle;
        } else {
          notifTitle = l10n.notificationTitleChat;
        }
      }

      if (cid.startsWith('group:')) {
        // The author of THIS message, not "whoever wrote last" — see
        // _resolveRoomSenderProfileId.
        final senderPid = await _resolveRoomSenderProfileId(
          db: db,
          selfDeviceId: did,
          convoId: cid,
          senderProfileId: spid,
          senderDeviceId: sdid,
        );
        {
          if (senderPid != null && senderPid.isNotEmpty) {
            final senderContact = await db.contactGet(senderPid);
            final senderMeta = await db.profileMetaGet(senderPid);
            var senderTitle = _resolvedContactDisplayName(
              contactRow: senderContact,
              metaRow: senderMeta,
            );
            // Same fallback as the avatar resolution above: most room
            // members are never added as a saved contact, so fall back to
            // the room's own membership roster for a display name.
            if (senderTitle == null || senderTitle.isEmpty) {
              try {
                final members = await listRoomMembersDetailed(cid);
                final member = members
                    .where((m) => m.profileId == senderPid)
                    .cast<RoomMember?>()
                    .firstOrNull;
                final memberName = member?.displayName.trim();
                if (memberName != null && memberName.isNotEmpty) {
                  senderTitle = memberName;
                }
              } catch (_) {}
            }
            if (senderTitle != null && senderTitle.isNotEmpty) {
              notifTitle = senderTitle;
              bannerSenderPid = senderPid;
            }
          }
        }
      }
    } catch (_) {}

    // Build body from decrypted preview text if available.
    String notifBody = l10n.notificationBodyNewMessage;
    if (notificationPresentation.showText &&
        previewText != null &&
        previewText.trim().isNotEmpty) {
      final t = previewText.trim();
      notifBody = t.length > 100 ? '${t.substring(0, 100)}...' : t;
    }

    if (!notificationPresentation.showSender) {
      notifTitle = cid.startsWith('group:') ? conversationTitle : l10n.appTitle;
    }
    if (!notificationPresentation.showText) {
      notifBody = l10n.notificationBodyNewMessage;
    }

    final backgroundNotificationCardEnabled =
        _readBackgroundNotificationCardEnabled(prefs);

    final activeConvo = _activeConvoId;
    final isActiveConvo = activeConvo != null && activeConvo == cid;
    final globalSoundEnabled = _readNotifBoolCompat(
      prefs,
      runtimeKey: _prefsNotifInAppSoundKey,
      settingsKey: _settingsNotifInAppSoundKey,
      defaultValue: true,
    );
    final inChatSoundEnabled = _readNotifBoolCompat(
      prefs,
      runtimeKey: _prefsNotifInAppChatSoundKey,
      settingsKey: _settingsNotifInAppChatSoundKey,
      defaultValue: true,
    );
    final globalVibrationEnabled = _readNotifBoolCompat(
      prefs,
      runtimeKey: _prefsNotifInAppVibrateKey,
      settingsKey: _settingsNotifInAppVibrateKey,
      defaultValue: true,
    );

    final playSound =
        chatPolicy.sound &&
        (isActiveConvo ? inChatSoundEnabled : globalSoundEnabled);
    final vibrate = chatPolicy.vibration && globalVibrationEnabled;
    final soundAssetPath = _resolveNotificationSoundAssetPath(
      prefs: prefs,
      inChat: isActiveConvo,
    );
    final suppressSystemNotificationForRecentPushWake = !_appInForeground
        ? await _shouldSuppressSystemNotificationForRecentPushWake(
            sourceMessageId: srcMsgId,
            nowMs: nowMs,
          )
        : false;
    final delivery = decideIncomingNotificationChannelsForTesting(
      appInForeground: _appInForeground,
      isActiveConvo: isActiveConvo,
      foregroundNotificationUxEnabled: _foregroundNotificationUxEnabled,
      playSound: playSound,
      vibrate: vibrate,
      suppressSystemNotificationForRecentPushWake:
          suppressSystemNotificationForRecentPushWake,
      backgroundNotificationCardEnabled: backgroundNotificationCardEnabled,
      desktopHostedNotifications: _desktopHostedNotifications,
    );
    final shouldInAppCue = delivery.inAppCue;
    final shouldInAppBanner = delivery.inAppBanner;
    final shouldSystemNotification = delivery.systemNotification;
    if (!shouldInAppCue && !shouldSystemNotification && !shouldInAppBanner) {
      return;
    }

    // A single inbound envelope can carry several MsgEventV1 entries (batched
    // delivery after being offline, albums, multi-attachment sends) — each
    // one calls this method with a different sourceMessageId, so the
    // per-message dedup above never collapses them. These windows widen the
    // per-convo/global throttle so a burst reads as one notification instead
    // of a flood of near-simultaneous banners for the same room.
    if (nowMs - _lastInAppNotificationAtMs < 1200) return;
    final lastConvoAtMs = _lastConvoNotificationAtMs[cid] ?? 0;
    if (nowMs - lastConvoAtMs < 2500) return;

    _lastInAppNotificationAtMs = nowMs;
    _lastConvoNotificationAtMs[cid] = nowMs;
    _lastUnreadReminderAtMsByConvo[cid] = nowMs;

    final avatarPath = (shouldInAppBanner || shouldSystemNotification)
        ? await _resolveNotificationAvatarPath(
            convoId: cid,
            showAvatar: notificationPresentation.showSender,
            senderProfileId: spid,
            senderDeviceId: sdid,
          )
        : null;

    // Telegram-style "live only" gate for the in-app banner. A banner should
    // pop only for a message that arrives WHILE you are actively using the app —
    // not for the flood the resume-drain catches up the instant you open it.
    // Two independent signals mark a message as backlog rather than live:
    //   (a) it landed inside the short grace window right after we resumed to
    //       the foreground (setAppInForeground flips _appInForeground true and
    //       THEN kicks the catch-up pump, so the whole backlog passes the
    //       foreground gate in a burst), or
    //   (b) the message itself is older than the live window (belt-and-braces
    //       for a slow drain that outruns the grace, and for cold launches
    //       where the grace never armed).
    // This suppresses ONLY the foreground banner — the system/background push
    // (shouldSystemNotification, below) and the in-app cue are untouched, so
    // nothing that reaches you when the app is closed is affected.
    final bool bannerIsBacklog = shouldSuppressInAppBannerAsBacklog(
      nowMs: nowMs,
      foregroundSinceMs: _foregroundSinceMs,
      sourceCreatedAtMs: sourceCreatedAtMs,
    );
    if (shouldInAppBanner && !bannerIsBacklog) {
      _inAppNotifsController.add(
        ChatNotifEvent(
          convoId: cid,
          title: notifTitle,
          body: notifBody,
          avatarPath: avatarPath,
          avatarSeed: inAppBannerAvatarSeed(
            convoId: cid,
            showSender: notificationPresentation.showSender,
            peerProfileId: peerProfileIdForPrivacy,
            senderProfileId: bannerSenderPid,
          ),
        ),
      );
    } else if (shouldInAppBanner && bannerIsBacklog) {
      DiagLog.event('notif', 'suppress_backlog_banner', {
        'convo': DiagLog.pfx(cid),
        'since_fg_ms': _foregroundSinceMs > 0 ? nowMs - _foregroundSinceMs : -1,
        'msg_age_ms':
            sourceCreatedAtMs != null ? nowMs - sourceCreatedAtMs : -1,
      });
    }
    // 🔴 Ш-2: ДОГОНЯЮЩЕЕ СООБЩЕНИЕ НЕ ЗВУЧИТ КАК ЖИВОЕ (23.08.2026).
    //
    // Баннер для «догона» гасился с 12.08, а звук и вибрация — нет: открываешь
    // приложение после ночи, и вчерашние сообщения отзваниваются так, будто
    // пришли сию секунду. Признак тот же, что у баннера, поэтому поведение
    // согласовано: тихо и без всплытия — либо и то, и другое. Живое сообщение
    // в открытом приложении не задето: у него оба признака ложны.
    if (shouldInAppCue && !bannerIsBacklog) {
      await _playInAppNotificationCue(
        playSound: playSound,
        vibrate: vibrate,
        soundAssetPath: soundAssetPath,
      );
    } else if (shouldInAppCue && bannerIsBacklog) {
      DiagLog.event('notif', 'suppress_backlog_cue', {
        'convo': DiagLog.pfx(cid),
        'msg_age_ms':
            sourceCreatedAtMs != null ? nowMs - sourceCreatedAtMs : -1,
      });
    }
    if (shouldSystemNotification) {
      await _showSystemNotification(
        convoId: cid,
        title: notifTitle,
        body: notifBody,
        playSound: playSound,
        vibrate: vibrate,
        avatarPath: avatarPath,
      );
    }
  }

  Future<bool> _shouldSuppressSystemNotificationForRecentPushWake({
    required String? sourceMessageId,
    required int nowMs,
  }) async {
    final normalizedMessageId = sourceMessageId?.trim();
    if (normalizedMessageId == null || normalizedMessageId.isEmpty) {
      return false;
    }
    final prefs = _prefs;
    if (prefs == null) {
      return false;
    }
    try {
      final wakeReceivedAtMs =
          await PushWakeService.recentMessageWakeReceivedAtMs(
            normalizedMessageId,
            prefs: prefs,
          );
      if (wakeReceivedAtMs == null || wakeReceivedAtMs <= 0) {
        return false;
      }
      final ageMs = nowMs - wakeReceivedAtMs;
      return ageMs >= 0 && ageMs < _recentPushWakeNotificationSuppressionMs;
    } catch (_) {
      return false;
    }
  }

  Future<void> _notificationReminderTick({required int nowMs}) async {
    // Product decision: no in-app reminder notifications/cues.
    if (!_inAppReminderNotificationsEnabled) return;
    if (!_appInForeground) return;
    if (nowMs - _lastReminderSweepAtMs < 60 * 1000) return;
    _lastReminderSweepAtMs = nowMs;

    final prefs = _prefs;
    final db = _db;
    final did = _deviceId;
    if (prefs == null || db == null || did == null || did.isEmpty) return;
    if (!_readNotifBoolCompat(
      prefs,
      runtimeKey: _prefsNotifAllAccountsKey,
      settingsKey: _settingsNotifAllAccountsKey,
      defaultValue: true,
    )) {
      return;
    }

    final repeatHours = _readNotifIntCompat(
      prefs,
      runtimeKey: _prefsNotifRepeatHoursKey,
      settingsKey: _settingsNotifRepeatHoursKey,
      defaultValue: 1,
    ).clamp(1, 8).toInt();
    final repeatMs = repeatHours * 60 * 60 * 1000;

    final convos = await db.convoList(limit: 250);
    final convoIds = convos
        .map((r) => (r['convo_id'] as String?)?.trim() ?? '')
        .where((id) => id.isNotEmpty)
        .toList(growable: false);
    if (convoIds.isEmpty) return;

    await _applyConversationRetentionForConvos(convoIds);

    final unreadByConvo = await db.countUnreadForConvos(
      convoIds: convoIds,
      selfDeviceId: did,
      excludedSenderDeviceIds: _ownDeviceIdsForUnreadQueries(),
    );

    for (final row in convos) {
      final convoId = ((row['convo_id'] as String?) ?? '').trim();
      if (convoId.isEmpty) continue;
      if (convoId == _activeConvoId) continue;
      final unread = unreadByConvo[convoId] ?? 0;
      if (unread <= 0) {
        _lastUnreadReminderAtMsByConvo.remove(convoId);
        continue;
      }

      final muted = ((row['muted'] as num?)?.toInt() ?? 0) != 0;
      if (muted) continue;

      final isGroup = convoId.startsWith('group:');
      final categoryPresentation = _loadCategoryNotificationPresentation(
        prefs: prefs,
        isGroup: isGroup,
      );
      if (!categoryPresentation.alerts) {
        continue;
      }
      if (isGroup) {
        if (!_readNotifBoolCompat(
          prefs,
          runtimeKey: _prefsNotifGroupsKey,
          settingsKey: _settingsNotifGroupsKey,
          defaultValue: true,
        )) {
          continue;
        }
      } else {
        if (!_readNotifBoolCompat(
          prefs,
          runtimeKey: _prefsNotifPrivateChatsKey,
          settingsKey: _settingsNotifPrivateChatsKey,
          defaultValue: true,
        )) {
          continue;
        }
      }

      final chatPolicy = _loadChatNotificationPolicy(
        prefs: prefs,
        convoId: convoId,
        defaultEnabled: true,
      );
      if (!chatPolicy.enabled) continue;
      final now = DateTime.fromMillisecondsSinceEpoch(nowMs);
      if (_isConvoQuietNow(
        quietHours: chatPolicy.quietHours,
        quietStartHour: chatPolicy.quietStartHour,
        quietEndHour: chatPolicy.quietEndHour,
        now: now,
      )) {
        continue;
      }

      final playSound =
          chatPolicy.sound &&
          _readNotifBoolCompat(
            prefs,
            runtimeKey: _prefsNotifInAppSoundKey,
            settingsKey: _settingsNotifInAppSoundKey,
            defaultValue: true,
          );
      final vibrate =
          chatPolicy.vibration &&
          _readNotifBoolCompat(
            prefs,
            runtimeKey: _prefsNotifInAppVibrateKey,
            settingsKey: _settingsNotifInAppVibrateKey,
            defaultValue: true,
          );
      final soundAssetPath = _resolveNotificationSoundAssetPath(
        prefs: prefs,
        inChat: false,
      );
      if (!playSound && !vibrate) continue;

      final lastReminderAtMs = _lastUnreadReminderAtMsByConvo[convoId] ?? 0;
      if (lastReminderAtMs > 0 && (nowMs - lastReminderAtMs) < repeatMs) {
        continue;
      }

      _lastUnreadReminderAtMsByConvo[convoId] = nowMs;
      _lastConvoNotificationAtMs[convoId] = nowMs;
      _lastInAppNotificationAtMs = nowMs;
      await _playInAppNotificationCue(
        playSound: playSound,
        vibrate: vibrate,
        soundAssetPath: soundAssetPath,
      );
      break;
    }
  }

  bool isConversationTyping(String convoId) {
    final cid = _normalizeTypingConvoId(convoId);
    if (cid.isEmpty) return false;
    final now = DateTime.now().millisecondsSinceEpoch;
    _purgeExpiredTyping(now, notify: false);
    final expiresAt = _typingExpiresAtMsByConvo[cid] ?? 0;
    return expiresAt > now;
  }

  /// Fans a typing signal out to every member of [groupId] except me.
  ///
  /// Rooms never sent this at all — the composer's typing hook returned null
  /// for group chats — so the room header had nothing to display no matter what
  /// the receiving side did. The wire is the SAME `typing_v1` command a 1:1
  /// chat uses, addressed once per member with the ROOM as its convoId, so an
  /// older peer understands it without any change.
  ///
  /// Best-effort by construction: the signal carries a few seconds of TTL, is
  /// never queued for an offline member (a typing state that arrives late is
  /// worse than none), and a member we cannot reach is simply skipped. The
  /// composer already debounces start/stop, so this costs one small control
  /// message per member per typing burst — not per keystroke.
  Future<void> sendRoomTypingState({
    required String groupId,
    required bool typing,
  }) async {
    final gid = groupId.trim();
    if (!gid.startsWith('group:')) return;
    final me = (_profileId ?? '').trim();
    List<String> members;
    try {
      members = await listGroupMembers(gid);
    } catch (_) {
      return;
    }
    for (final member in members) {
      final pid = member.trim();
      if (pid.isEmpty || pid == me) continue;
      // Deliberately not awaited as a group: one slow member must not delay
      // the signal to the rest, and a failure is not worth reporting.
      unawaited(
        sendTypingState(peerProfileId: pid, convoId: gid, typing: typing),
      );
    }
  }

  Future<void> sendTypingState({
    required String peerProfileId,
    required String convoId,
    required bool typing,
  }) async {
    final pid = peerProfileId.trim();
    var cid = _normalizeTypingConvoId(convoId);
    if (!cid.startsWith('group:')) {
      final myPid = (_profileId ?? '').trim();
      if (myPid.isNotEmpty) {
        cid = myPid;
      } else if (cid.startsWith('dev:')) {
        cid = pid;
      }
    }
    if (pid.isEmpty || cid.isEmpty) return;
    final payload = <String, Object?>{
      'v': 1,
      'action': typing ? 'start' : 'stop',
      'convoId': cid,
      'createdAtMs': DateTime.now().millisecondsSinceEpoch,
    };
    final text =
        '$_typingCmdPrefix${base64Url.encode(utf8.encode(jsonEncode(payload)))}';
    try {
      await sendControlMessage(
        peerProfileId: pid,
        controlText: text,
        ttlSeconds: _typingSignalTtlSeconds,
        strict: false,
        forceRelayFlush: true,
      );
    } catch (_) {
      // Best-effort typing signal.
    }
  }

  void _setConversationTyping({
    required String convoId,
    required bool typing,
    int? expiresAtMs,
    String? senderProfileId,
    bool notify = true,
  }) {
    final cid = _normalizeTypingConvoId(convoId);
    if (cid.isEmpty) return;
    final now = DateTime.now().millisecondsSinceEpoch;
    final before = _typingExpiresAtMsByConvo[cid] ?? 0;
    var changed = false;
    if (!typing) {
      if (before > 0) {
        _typingExpiresAtMsByConvo.remove(cid);
        _typingSenderProfileIdByConvo.remove(cid);
        changed = true;
      }
      // Only the member who said "stop" leaves; the others keep typing.
      final stopper = (senderProfileId ?? '').trim();
      final roster = _typingSendersByConvo[cid];
      if (roster != null) {
        if (stopper.isEmpty) {
          _typingSendersByConvo.remove(cid);
          changed = true;
        } else if (roster.remove(stopper) != null) {
          if (roster.isEmpty) _typingSendersByConvo.remove(cid);
          changed = true;
        }
      }
    } else {
      final nextExpiry = expiresAtMs ?? (now + _typingVisibleMs);
      if (nextExpiry > before) {
        _typingExpiresAtMsByConvo[cid] = nextExpiry;
        changed = true;
      }
      // Retain the typing member locally so a room can show "<name> Пишет".
      // Independent of the expiry-extension guard above so the latest typer
      // wins even when the timestamp was already in the future.
      final sender = (senderProfileId ?? '').trim();
      if (sender.isNotEmpty && _typingSenderProfileIdByConvo[cid] != sender) {
        _typingSenderProfileIdByConvo[cid] = sender;
        changed = true;
      }
      if (sender.isNotEmpty) {
        final roster = _typingSendersByConvo.putIfAbsent(
          cid,
          () => <String, int>{},
        );
        // Per-person expiry: each keystroke extends only its own author.
        if ((roster[sender] ?? 0) < nextExpiry) {
          roster[sender] = nextExpiry;
          changed = true;
        }
      }
    }
    _refreshTypingSweepTimer();
    if (changed && notify) {
      _changed.add(null);
    }
  }

  void _refreshTypingSweepTimer() {
    final now = DateTime.now().millisecondsSinceEpoch;
    _purgeExpiredTyping(now, notify: false);
    if (_typingExpiresAtMsByConvo.isEmpty) {
      _typingSweepTimer?.cancel();
      _typingSweepTimer = null;
      return;
    }
    _typingSweepTimer ??= Timer.periodic(const Duration(seconds: 1), (_) {
      final ts = DateTime.now().millisecondsSinceEpoch;
      _purgeExpiredTyping(ts, notify: true);
      if (_typingExpiresAtMsByConvo.isEmpty) {
        _typingSweepTimer?.cancel();
        _typingSweepTimer = null;
      }
    });
  }

  void _purgeExpiredTyping(int nowMs, {required bool notify}) {
    // Roster first: it can hold entries for a convo whose aggregate expiry has
    // already gone, and each member expires on their own clock.
    var rosterChanged = false;
    if (_typingSendersByConvo.isNotEmpty) {
      for (final convoId in _typingSendersByConvo.keys.toList()) {
        final roster = _typingSendersByConvo[convoId]!;
        roster.removeWhere((_, expiresAt) {
          if (expiresAt > nowMs) return false;
          rosterChanged = true;
          return true;
        });
        if (roster.isEmpty) _typingSendersByConvo.remove(convoId);
      }
    }
    if (_typingExpiresAtMsByConvo.isEmpty) {
      if (rosterChanged && notify) _changed.add(null);
      return;
    }
    final expired = <String>[];
    _typingExpiresAtMsByConvo.forEach((convoId, expiresAt) {
      if (expiresAt <= nowMs) {
        expired.add(convoId);
      }
    });
    if (expired.isEmpty) return;
    for (final convoId in expired) {
      _typingExpiresAtMsByConvo.remove(convoId);
      _typingSenderProfileIdByConvo.remove(convoId);
    }
    if (notify) {
      _changed.add(null);
    }
  }

  /// Everyone currently typing in [convoId], newest signal first.
  ///
  /// A room can have several typists at once; the header names them. Expiry is
  /// per person, so one member stopping never hides the others.
  List<String> conversationTypingProfileIds(String convoId) {
    final cid = _normalizeTypingConvoId(convoId);
    if (cid.isEmpty) return const <String>[];
    final now = DateTime.now().millisecondsSinceEpoch;
    _purgeExpiredTyping(now, notify: false);
    final roster = _typingSendersByConvo[cid];
    if (roster == null || roster.isEmpty) return const <String>[];
    final me = (_profileId ?? '').trim();
    final entries = roster.entries
        .where((e) => e.value > now && e.key.isNotEmpty && e.key != me)
        .toList()
      ..sort((a, b) => b.value.compareTo(a.value));
    return entries.map((e) => e.key).toList(growable: false);
  }

  /// Room members seen recently enough to count as online, excluding me.
  ///
  /// Uses the same freshness window as the 1:1 indicator, so "online" means the
  /// same thing everywhere in the app.
  Future<List<String>> onlineRoomMemberProfileIds(String groupId) async {
    final db = _db;
    if (db == null) return const <String>[];
    final gid = groupId.trim();
    if (!gid.startsWith('group:')) return const <String>[];
    final me = (_profileId ?? '').trim();
    List<String> members;
    try {
      members = await listGroupMembers(gid);
    } catch (_) {
      return const <String>[];
    }
    final now = DateTime.now().millisecondsSinceEpoch;
    // ОДИН запрос на всю комнату вместо запроса на участника.
    //
    // Шапка группы вызывает это на каждый тик `changed`, а тиков в активной
    // комнате — очередями (печатает, прочитано, присутствие). Комната на
    // пятьдесят человек давала полсотни последовательных обращений к базе на
    // каждый такой тик и забивала очередь, от которой зависит прокрутка ленты.
    // Батч-метод уже существовал и применялся при загрузке списка чатов.
    final candidates = <String>[
      for (final m in members)
        if (m.trim().isNotEmpty && m.trim() != me) m.trim(),
    ];
    if (candidates.isEmpty) return const <String>[];
    Map<String, int> lastSeenByProfileId;
    try {
      lastSeenByProfileId = await db.profileMetaGetLastSeenForProfiles(
        candidates,
      );
    } catch (_) {
      // Не смогли прочитать присутствие — никто не показывается онлайн.
      // Прежнее поведение при ошибке было тем же, только по одному участнику.
      return const <String>[];
    }
    final out = <String>[];
    for (final pid in candidates) {
      final ts = lastSeenByProfileId[pid];
      if (ts != null && now - ts < kPeerOnlineFreshMs) out.add(pid);
    }
    return out;
  }

  /// Profile id of the member whose typing signal is currently active for
  /// [convoId], or null when nobody is typing (or it expired). Additive helper
  /// for the room "name + Пишет" display — does not affect typing
  /// wire/lifecycle.
  String? conversationTypingProfileId(String convoId) {
    final cid = _normalizeTypingConvoId(convoId);
    if (cid.isEmpty) return null;
    final now = DateTime.now().millisecondsSinceEpoch;
    final expiresAt = _typingExpiresAtMsByConvo[cid] ?? 0;
    if (expiresAt <= now) return null;
    final pid = (_typingSenderProfileIdByConvo[cid] ?? '').trim();
    return pid.isEmpty ? null : pid;
  }

  /// Resolved display name of the current typing member for [convoId], or null.
  /// Reuses the existing contact/room name resolution. Best-effort; returns the
  /// raw profile id only when no friendlier name is known.
  Future<String?> conversationTypingDisplayName(String convoId) async {
    final pid = conversationTypingProfileId(convoId);
    if (pid == null || pid.isEmpty) return null;
    final db = _db;
    if (db == null) return pid;
    try {
      final contact = await db.contactGet(pid);
      final meta = await db.profileMetaGet(pid);
      final resolved = _resolvedContactDisplayName(
        contactRow: contact,
        metaRow: meta,
      );
      if (resolved != null && resolved.trim().isNotEmpty) {
        return resolved.trim();
      }
    } catch (_) {
      // Best-effort resolution; fall back to the raw profile id below.
    }
    return pid;
  }

  /// Whether [convoId] is currently muted. Synchronous; reads the same in-memory
  /// conversation snapshot the chat list uses for its muted badge (the `muted`
  /// flag on the cached [Conversation] rows). Returns false when unknown.
  bool isConversationMuted(String convoId) {
    final cid = convoId.trim();
    if (cid.isEmpty) return false;
    final cached = _listConversationsCache;
    if (cached == null) return false;
    for (final convo in cached) {
      if (convo.convoId == cid) return convo.muted;
    }
    return false;
  }

  String _normalizeTypingConvoId(String convoId) {
    final cid = convoId.trim();
    if (cid.isEmpty) return '';
    if (cid.startsWith('req:') && cid.length > 4) {
      return cid.substring(4).trim();
    }
    return cid;
  }

  String? _deviceId;
  String get deviceId => _deviceId ?? 'unknown';

  String? _profileId;
  String get profileId => _profileId ?? 'unknown';

  /// True when the device is running on an UNREGISTERED local-only profile
  /// (`LOCAL-<uuid>`) because keys-server registration failed. In this state the
  /// device cannot publish prekeys or use the relay mailbox → it is invisible to
  /// peers and inbound/outbound messages will NOT be delivered. Surfaced in
  /// System settings so it never silently strands a user; "Reset profile"
  /// recreates a real server-backed ID.
  bool get isUnregisteredLocalProfile =>
      (_profileId ?? '').startsWith('LOCAL-');

  /// Ключ, под которым хранится история своих device_id.
  ///
  /// 🔴 НЕ в чёрном списке переноса настроек — намеренно. Это собственная
  /// история человека, и именно в восстановлении она и нужна: без неё копия
  /// возвращает переписку, в которой все свои сообщения выглядят чужими.
  /// 🔴 ЗДЕСЬ НЕТ ПОМЕТКИ ВЛАДЕЛЬЦА, И ЭТО ОДНАЖДЫ ВЫСТРЕЛИЛО (16.09.2026).
  /// Список общий на установку, а не на аккаунт, поэтому после смены аккаунта
  /// он приписывался новому профилю. Держат его теперь двое: выгрузка аккаунта
  /// стирает ключ, а старт выбрасывает устройства, про которые переписка знает,
  /// что они чужие (`_dropForeignOwnDeviceIds`).
  static const _prefsKnownOwnDeviceIdsKey = 'known_own_device_ids_v1';

  /// Потолок истории. Больше держать незачем, а расти без предела список не
  /// имеет права: он читается на каждом запуске.
  static const int _kKnownOwnDeviceIdsMax = 32;

  static List<String> _loadPersistedOwnDeviceIds(SharedPreferences prefs) {
    final raw = prefs.getStringList(_prefsKnownOwnDeviceIdsKey);
    if (raw == null) return const <String>[];
    return raw
        .map((v) => v.trim())
        .where((v) => v.isNotEmpty)
        .toList(growable: false);
  }

  /// Запоминает device_id как свой — навсегда, а не до перезапуска.
  ///
  /// 🔴 Только СВОИ идентификаторы. `isOwnDeviceId` управляет не только стороной
  /// пузыря, но и гейтом приёма: чужой id здесь означал бы, что чужие сообщения
  /// считаются своими. Поэтому зовётся ровно из трёх мест, где принадлежность
  /// доказана: текущее устройство, перечень устройств профиля с сервера и
  /// device_id из СВОЕЙ копии.
  Future<void> _rememberOwnDeviceIds(Iterable<String> deviceIds) async {
    final prefs = _prefs;
    if (prefs == null) return;
    final incoming = deviceIds
        .map((v) => v.trim())
        .where((v) => v.isNotEmpty)
        .toSet();
    if (incoming.isEmpty) return;

    final existing = _loadPersistedOwnDeviceIds(prefs);
    if (incoming.every(existing.contains)) return; // ничего нового

    // Свежие в конце: при переполнении отрезаем самые старые, а не текущие.
    final merged = <String>[
      ...existing.where((v) => !incoming.contains(v)),
      ...incoming,
    ];
    final capped = merged.length <= _kKnownOwnDeviceIdsMax
        ? merged
        : merged.sublist(merged.length - _kKnownOwnDeviceIdsMax);
    _knownOwnDeviceIds.addAll(capped);
    await prefs.setStringList(_prefsKnownOwnDeviceIdsKey, capped);
  }

  bool isOwnDeviceId(String senderDeviceId) {
    final did = senderDeviceId.trim();
    if (did.isEmpty) return false;
    final myDid = (_deviceId ?? '').trim();
    if (myDid.isNotEmpty && did == myDid) return true;
    return _knownOwnDeviceIds.contains(did);
  }

  List<String> _ownDeviceIdsForUnreadQueries() {
    final deviceIds = <String>{};
    final currentDeviceId = (_deviceId ?? '').trim();
    if (currentDeviceId.isNotEmpty) {
      deviceIds.add(currentDeviceId);
    }
    for (final deviceId in _knownOwnDeviceIds) {
      final clean = deviceId.trim();
      if (clean.isNotEmpty) {
        deviceIds.add(clean);
      }
    }
    return deviceIds.toList(growable: false);
  }

  bool _desktopAuthRequired = false;
  AuthFlowState _authFlowState = AuthFlowState.unauthenticated;
  DesktopLinkFailure? _authFlowFailure;
  String? _authFlowError;

  AuthFlowState get authFlowState => _authFlowState;
  DesktopLinkFailure? get authFlowFailure => _authFlowFailure;
  String? get authFlowError => _authFlowFailure?.message ?? _authFlowError;

  String? _startupWarning;
  String? get startupWarning => _startupWarning;

  ServiceHealthStatus? _keysHealthStatus;
  ServiceHealthStatus? get keysHealthStatus => _keysHealthStatus;

  ServiceHealthStatus? _relayHealthStatus;
  ServiceHealthStatus? get relayHealthStatus => _relayHealthStatus;

  bool _keysOnline = false;
