  String _summarizeDiagnosticError(Object error) {
    final raw = error.toString().trim().replaceAll(RegExp(r'\s+'), ' ');
    if (raw.isEmpty) return error.runtimeType.toString();
    return raw.length <= 240 ? raw : raw.substring(0, 240);
  }

