  Future<void> forceOutboxPump() async {
    final relay = _relay;
    if (relay == null) return;
    await _kickRelayOutboxAndWait(relay);
    _changed.add(null);
  }

  Future<int> recoverStuckOutgoingForDiagnostics() async {
    final now = DateTime.now().millisecondsSinceEpoch;
    final db = _db;
    if (db == null) return 0;
    final recovered = await db.outboxRescheduleStalledSends(
      nowMs: now,
      stalledBeforeMs: now - _outgoingSendStallMs,
      retryAtMs: now + _outgoingSendRecoveryDelayMs,
      reasonCode: MessageFailureReason.sendStallTimeout,
    );
    if (recovered > 0) {
      _kickRelayOutbox();
      _changed.add(null);
    }
    return recovered;
  }

