  DesktopLinkFailure _desktopLinkFailureFromKeysPolicy(
    KeysPolicyFailure failure,
  ) {
    switch (failure.code) {
      case KeysPolicyFailureCode.desktopCompanionEntitlementRequired:
        return DesktopLinkFailure(
          DesktopLinkFailureCode.desktopCompanionEntitlementRequired,
          message: failure.message,
          cause: failure,
        );
      case KeysPolicyFailureCode.desktopCompanionLimitReached:
        return DesktopLinkFailure(
          DesktopLinkFailureCode.desktopCompanionLimitReached,
          message: failure.message,
          cause: failure,
        );
      default:
        return DesktopLinkFailure(
          DesktopLinkFailureCode.desktopPrimaryDeviceRequired,
          message: failure.message,
          cause: failure,
        );
    }
  }

  /// Translate a `register_device_proof` failure code into a user-facing
  /// message. The goal is to replace the historical
  /// `Bad state: registerDeviceProof returned ok=false` (which gave the user
  /// no actionable information) with concrete next steps that map 1:1 to the
  /// server-side [KeysPolicyFailureCode] families.
  String _friendlyRegisterProofMessage(KeysPolicyFailure failure) {
    switch (failure.code) {
      case KeysPolicyFailureCode.clockSkew:
        return 'Clock drift detected between this device and the Secretly server '
            '(>5 minutes). Enable automatic date/time and retry sign-in. '
            '(${failure.message})';
      case KeysPolicyFailureCode.challengeMissing:
      case KeysPolicyFailureCode.challengeExpired:
      case KeysPolicyFailureCode.challengeNonceMismatch:
        return 'Secretly server-issued challenge expired before the device '
            'could reply. The app will retry automatically; if this keeps '
            'happening, check the network latency to Keys. '
            '(${failure.message})';
      case KeysPolicyFailureCode.signatureInvalid:
        return 'Device identity-key signature did not verify on the Secretly '
            'server. The app rotated device keys and retried. If this persists, '
            'reset the device from Settings → Devices. (${failure.message})';
      case KeysPolicyFailureCode.profileSecretMissing:
      case KeysPolicyFailureCode.profileSecretInvalidFormat:
      case KeysPolicyFailureCode.profileSecretMismatch:
      case KeysPolicyFailureCode.profileSecretRequired:
        return 'This device no longer holds a valid profile secret for the '
            'current Secretly ID. Restore from Recovery Kit or re-link from '
            'your primary device. (${failure.message})';
      case KeysPolicyFailureCode.profileNotFound:
        return 'This Secretly ID is no longer present on the Keys server. '
            'Create a new profile from Settings, or restore from Recovery Kit. '
            '(${failure.message})';
      case KeysPolicyFailureCode.deviceIdentityKeyMismatch:
        return 'Device registration key mismatch: this device_id was '
            'previously pinned to a different identity key on the server. The '
            'app rotated the device_id and retried. (${failure.message})';
      case KeysPolicyFailureCode.invalidProfileId:
      case KeysPolicyFailureCode.invalidDeviceId:
      case KeysPolicyFailureCode.invalidIdentityKey:
        return 'Secretly server rejected malformed registration fields. '
            'Reset profile from Settings and try again. (${failure.message})';
      case KeysPolicyFailureCode.storeError:
        return 'Secretly server-side storage error during device registration. '
            'Retry in a few seconds; if it persists, contact support. '
            '(${failure.message})';
      default:
        return failure.message;
    }
  }

