  Future<void> _setDesktopAuthRequired(
    SharedPreferences prefs,
    bool value,
  ) async {
    _desktopAuthRequired = value;
    await prefs.setBool(_prefsDesktopAuthRequiredKey, value);
  }

  Future<void> _applyDesktopTestStartupMode(SharedPreferences prefs) async {
    if (!_desktopTestStartupMode) return;
    _profileId = _desktopTestProfileId;
    _deviceId = _desktopTestDeviceId;
    _desktopAuthRequired = false;
    _desktopLinkRequests = const <DesktopLinkRequest>[];
    await prefs.setString(_prefsProfileIdKey, _desktopTestProfileId);
    await prefs.setString(_prefsDeviceIdKey, _desktopTestDeviceId);
    await prefs.setBool(_prefsDesktopAuthRequiredKey, false);
    await prefs.remove(_prefsDesktopLinkRequestsKey);
    if ((prefs.getString(_prefsMyNicknameKey) ?? '').trim().isEmpty) {
      await prefs.setString(_prefsMyNicknameKey, _desktopTestNickname);
    }
    await markOnboardingComplete(prefs: prefs);
  }

  Future<void> _enterDesktopUnauthenticatedMode(
    SharedPreferences prefs, {
    String? warning,
    String? error,
  }) async {
    await _setDesktopAuthRequired(prefs, true);
    _applyDesktopUnauthenticatedModeResult(
      AppRuntimeLifecycleCoordinator.desktopUnauthenticatedMode(
        warning: warning,
        error: error,
      ),
    );
  }

  void _applyDesktopUnauthenticatedModeResult(
    DesktopUnauthenticatedModeResult result,
  ) {
    _setAuthFlowState(result.authFlowState, error: result.authFlowError);
    if (result.startupWarning != null) {
      _startupWarning = result.startupWarning;
    }
  }

  /// True while this desktop's device id is gone from the account on the keys
  /// server. Read by the pairing screen to offer the one recovery that exists
  /// — see [resetDesktopDeviceIdentityForRepair].
  bool _desktopDeviceRemovedFromAccount = false;

  bool get desktopDeviceRemovedFromAccount => _desktopDeviceRemovedFromAccount;

  Future<void> _enterDesktopCurrentDeviceRemovedMode({
    required SharedPreferences prefs,
    required DesktopUnauthenticatedModeResult result,
  }) async {
    _desktopDeviceRemovedFromAccount = true;
    _pumpTimer?.cancel();
    _mainAliveHeartbeatTimer?.cancel();
    _pumpTimer = null;
    _serviceWatchdogTimer?.cancel();
    _serviceWatchdogTimer = null;
    _quarantineRecoverySweepTimer?.cancel();
    _quarantineRecoverySweepTimer = null;

    await _closeRuntimeNetworkClientsForDiscard();
    _attachments = null;
    _ratchetV1 = null;
    _ratchetV3 = null;
    _keysOnline = false;
    _relayOnline = false;

    await _setDesktopAuthRequired(prefs, true);
    _applyDesktopUnauthenticatedModeResult(result);
    _changed.add(null);
  }

  Future<void> _closeRuntimeNetworkClientsForDiscard() async {
    final relay = _relay;
    final keys = _keys;
    final blob = _blob;
    final stickerCatalogClient = _stickerCatalogClient;
    _relay = null;
    _keys = null;
    _blob = null;
    _stickerCatalogClient = null;

    try {
      await relay?.close();
    } catch (_) {}
    try {
      keys?.close();
    } catch (_) {}
    try {
      blob?.close();
    } catch (_) {}
    try {
      stickerCatalogClient?.close();
    } catch (_) {}
  }

  void _applyRuntimeResetResult(AppRuntimeResetResult result) {
    unawaited(_closeRuntimeNetworkClientsForDiscard());
    _profileId = result.profileId;
    _deviceId = result.deviceId;
    _attachments = null;
    _ratchetV1 = null;
    _ratchetV3 = null;
    _keysOnline = result.keysOnline;
    _relayOnline = result.relayOnline;
    _startupWarning = result.startupWarning;
    _transportBlocked = result.transportBlocked;
    _transportBlockedReason = result.transportBlockedReason;
    _serverBindingMismatch = result.serverBindingMismatch;
    _desktopLinkRequests = List<DesktopLinkRequest>.from(
      result.desktopLinkRequests,
    );
    _knownOwnDeviceIds
      ..clear()
      ..addAll(result.knownOwnDeviceIds);
  }

  Future<void> _clearDesktopLocalOnlyProfileState(
    SharedPreferences prefs,
  ) async {
    if (!_isDesktopOrWebPlatform) return;
    final pid = (_profileId ?? '').trim();
    if (pid.isNotEmpty && _isServerBackedProfileId(pid)) return;
    _profileId = null;
    // Кто стёр личность — записать ДО стирания: потом улики нет.
    await IdentityJournal.recordProfileIdCleared(
      by: 'desktop_local_only_scrub',
      nowMs: DateTime.now().millisecondsSinceEpoch,
      previousProfileId: prefs.getString(_prefsProfileIdKey),
      previousDeviceId: prefs.getString(_prefsDeviceIdKey),
      deviceIdClearedToo: false,
    );
    await prefs.remove(_prefsProfileIdKey);
  }

  Future<bool> hasServerProfileLocally() async {
    final prefs = _prefs ?? await SharedPreferences.getInstance();
    _prefs = prefs;
    if (_isDesktopOrWebPlatform &&
        (prefs.getBool(_prefsDesktopAuthRequiredKey) ?? false)) {
      return false;
    }
    final pid = (prefs.getString(_prefsProfileIdKey) ?? '').trim();
    if (!_isServerBackedProfileId(pid)) return false;

    final savedBinding = (prefs.getString(_prefsServerBindingKey) ?? '').trim();
    if (savedBinding.isEmpty) return true;
    return savedBinding == _environmentServerBindingString();
  }

  Future<bool> _waitForProfileExistsOnServer(
    String profileId, {
    Duration timeout = const Duration(seconds: 12),
  }) async {
    final pid = profileId.trim();
    if (pid.isEmpty || pid.startsWith('LOCAL-')) return false;

    final keys = _keys ?? KeysClient(baseUrl: keysBaseUrl);
    _keys = keys;
    final deadline = DateTime.now().add(timeout);
    while (DateTime.now().isBefore(deadline)) {
      try {
        if (await keys.profileExists(pid)) return true;
      } catch (_) {
        // ignore transient network errors while waiting.
      }
      await Future.delayed(const Duration(milliseconds: 700));
    }
    return false;
  }

  Future<bool> _waitForDeviceVisibleOnServer(
    String profileId,
    String deviceId, {
    Duration timeout = const Duration(seconds: 15),
  }) async {
    final pid = profileId.trim();
    final did = deviceId.trim();
    if (pid.isEmpty || did.isEmpty || pid.startsWith('LOCAL-')) return false;

    final keys = _keys ?? KeysClient(baseUrl: keysBaseUrl);
    _keys = keys;
    final deadline = DateTime.now().add(timeout);
    while (DateTime.now().isBefore(deadline)) {
      try {
        final devices = await _listDevicesAuthed(pid);
        if (devices.contains(did)) return true;
      } catch (_) {
        // ignore transient network errors while waiting.
      }
      await Future.delayed(const Duration(milliseconds: 700));
    }
    return false;
  }

  // ===== FIX-C2: durable pending-device-delete ledger ======================
  // A rotation that abandons a device_id MUST eventually delete it from the
  // keys server, or peers keep fanning to the dead ("zombie") mailbox forever.
  // The delete is best-effort and can fail (offline / 5xx) or never run (app
  // killed mid-rotation), so we persist abandoned device_ids here and drain
  // them on every keys setup until each one confirms. Entries are scoped to a
  // profile_id because the cross-device delete must be signed by a LIVE device
  // of the SAME profile (server forbids cross-profile deletes).

  List<Map<String, dynamic>> _readPendingDeviceDeletes(
    SharedPreferences prefs,
  ) {
    try {
      final raw = (prefs.getString(_prefsPendingDeviceDeletesKey) ?? '').trim();
      if (raw.isEmpty) return <Map<String, dynamic>>[];
      final decoded = jsonDecode(raw);
      if (decoded is! List) return <Map<String, dynamic>>[];
      return decoded
          .whereType<Map>()
          .map((e) => e.cast<String, dynamic>())
          .where((e) => ((e['did'] as String?) ?? '').trim().isNotEmpty)
          .toList();
    } catch (_) {
      return <Map<String, dynamic>>[];
    }
  }

  Future<void> _writePendingDeviceDeletes(
    SharedPreferences prefs,
    List<Map<String, dynamic>> entries,
  ) async {
    try {
      // Cap to the most-recent 64 so a pathological churn loop can't grow prefs
      // unbounded; the keys-server last_seen TTL is the backstop for the rest.
      final capped = entries.length > 64
          ? entries.sublist(entries.length - 64)
          : entries;
      await prefs.setString(_prefsPendingDeviceDeletesKey, jsonEncode(capped));
    } catch (_) {
      // ignore
    }
  }

  Future<void> _recordPendingDeviceDelete({
    required String profileId,
    required String deviceId,
  }) async {
    final pid = profileId.trim();
    final did = deviceId.trim();
    if (pid.isEmpty || did.isEmpty || pid.startsWith('LOCAL-')) return;
    final prefs = _prefs;
    if (prefs == null) return;
    final entries = _readPendingDeviceDeletes(prefs);
    final exists = entries.any(
      (e) =>
          ((e['pid'] as String?) ?? '') == pid &&
          ((e['did'] as String?) ?? '') == did,
    );
    if (exists) return;
    entries.add(<String, dynamic>{
      'pid': pid,
      'did': did,
      'at': DateTime.now().millisecondsSinceEpoch,
      'tries': 0,
    });
    await _writePendingDeviceDeletes(prefs, entries);
  }

  /// Drains the durable ledger: deletes every queued device_id that belongs to
  /// [currentProfileId] from the keys server, signed by the current LIVE device
  /// [requesterDeviceId]. Confirmed deletes (and entries we can no longer act on
  /// or that are too old/too-retried) are removed. Best-effort, time-boxed, must
  /// never throw into keys setup.
  Future<void> _drainPendingDeviceDeletes({
    required String currentProfileId,
    required String requesterDeviceId,
  }) async {
    final prefs = _prefs;
    final pid = currentProfileId.trim();
    final liveDid = requesterDeviceId.trim();
    if (prefs == null || pid.isEmpty || liveDid.isEmpty) return;
    final entries = _readPendingDeviceDeletes(prefs);
    if (entries.isEmpty) return;
    final nowMs = DateTime.now().millisecondsSinceEpoch;
    const maxAgeMs =
        30 * 24 * 60 * 60 * 1000; // server TTL is the real backstop
    const maxTries = 12;
    final kept = <Map<String, dynamic>>[];
    for (final entry in entries) {
      final entryPid = ((entry['pid'] as String?) ?? '').trim();
      final entryDid = ((entry['did'] as String?) ?? '').trim();
      final entryAt = (entry['at'] as num?)?.toInt() ?? nowMs;
      final entryTries = (entry['tries'] as num?)?.toInt() ?? 0;
      if (entryDid.isEmpty) continue;
      // Already gone: the live device id can never be a zombie.
      if (entryDid == liveDid) continue;
      // We can only sign deletes for the CURRENT profile; an entry for a
      // different (abandoned) profile is unreachable — drop it and rely on the
      // server last_seen TTL prune. Same for give-up by age / attempts.
      if (entryPid != pid ||
          (nowMs - entryAt) > maxAgeMs ||
          entryTries >= maxTries) {
        continue;
      }
      // FIX-2 (one-way blackout recovery): BEFORE deleting the abandoned device
      // (A1) from keys, migrate its relay mailbox to the live device (A2), so
      // messages a peer queued for A1 while we were offline are recovered. The
      // rebind's same-profile gate needs A1 still present on keys, so we do NOT
      // delete A1 from keys until its mailbox has been rebound. If the relay
      // isn't ready / the call fails, keep A1 (in keys + the ledger) and retry on
      // a later drain — never forfeit the recovery by deleting first.
      final relay = _relay;
      var rebound = false;
      if (relay != null) {
        try {
          final moved = await relay
              .rebindDevice(oldDeviceId: entryDid)
              .timeout(const Duration(seconds: 8));
          rebound = true;
          if (moved > 0) {
            DiagLog.event('relay', 'mailbox_rebind_ok', {
              'old': DiagLog.pfx(entryDid),
              'moved': moved,
            });
          }
        } catch (e) {
          // И-1 §Д-7: after a hinted cap-eviction the old id is already gone
          // from the keys server, so the rebind's same-profile gate answers
          // 401 "unknown old device" (unless the relay's in-memory mapping
          // still remembers it — a relay restart loses that). The gate cannot
          // be satisfied ever again, so retrying 12 drains is pure churn:
          // treat the mailbox as unrecoverable-through-rebind and let the
          // entry converge to the keys-delete below. In-flight wires in that
          // mailbox rot by relay TTL; the sender-side convergence resend
          // remains the recovery for un-receipted messages.
          final raw = e.toString().toLowerCase();
          if (raw.contains('unknown old device')) {
            rebound = true;
            DiagLog.event('relay', 'mailbox_rebind_skipped_gone', {
              'old': DiagLog.pfx(entryDid),
            });
          } else {
            rebound = false;
          }
        }
      }
      if (!rebound) {
        kept.add(<String, dynamic>{
          'pid': entryPid,
          'did': entryDid,
          'at': entryAt,
          'tries': entryTries + 1,
        });
        continue;
      }

      var deleted = false;
      try {
        deleted = await _deleteDeviceRegistrationFromServer(
          profileId: pid,
          deviceId: entryDid,
          requesterDeviceId: liveDid,
        ).timeout(const Duration(seconds: 6));
      } catch (_) {
        deleted = false;
      }
      if (deleted) {
        DiagLog.event('keys', 'zombie_delete_ok', {
          'did': DiagLog.pfx(entryDid),
          'src': 'ledger',
        });
        continue; // drop on success
      }
      kept.add(<String, dynamic>{
        'pid': entryPid,
        'did': entryDid,
        'at': entryAt,
        'tries': entryTries + 1,
      });
    }
    await _writePendingDeviceDeletes(prefs, kept);
  }

  Future<bool> _deleteDeviceRegistrationFromServer({
    required String profileId,
    required String deviceId,
    String? profileSecretB64,
    // PR-C: optional requester identity. When null (default), the caller
    // signs the request itself (self-delete during re-bind / unlink). When
    // non-null and different from [deviceId], the request becomes a
    // cross-device end-session — used by the «Завершить сеанс» UI on mobile
    // and the desktop Settings → Devices pane. The keys server allows this
    // as long as both devices share the same profile (see
    // server/keys/src/main.rs::delete_device + verify_requester_device_auth).
    String? requesterDeviceId,
  }) async {
    final pid = profileId.trim();
    final did = deviceId.trim();
    final requesterDid = (requesterDeviceId ?? did).trim().isNotEmpty
        ? (requesterDeviceId ?? did).trim()
        : did;
    if (pid.isEmpty || did.isEmpty || pid.startsWith('LOCAL-')) {
      return false;
    }

    final normalizedProfileSecret = (profileSecretB64 ?? '').trim().isNotEmpty
        ? profileSecretB64!.trim()
        : ((await SecureSecrets.create().getProfileSecretB64(pid)) ?? '')
              .trim();
    if (normalizedProfileSecret.isEmpty) {
      return false;
    }

    final keys = _keys ?? KeysClient(baseUrl: keysBaseUrl);
    _keys = keys;

    try {
      final identityKeyPair = await DeviceKeys.create().loadIdentityKeyPair(
        profileId: pid,
        deviceId: requesterDid,
      );
      // Время сервера, а не устройства — см. пояснение выше по файлу.
      final tsMs = ServerClock.instance.nowMs();
      final nonceB64 = AuthSigner.randomNonceB64(bytes: 16);
      final message = AuthSigner.keysDeleteDeviceMessage(
        requesterDeviceId: requesterDid,
        profileId: pid,
        targetDeviceId: did,
        tsMs: tsMs,
        nonceB64: nonceB64,
      );
      final signatureB64 = await AuthSigner.signEd25519B64(
        identityKeyPair: identityKeyPair,
        message: message,
      );
      return await keys.deleteDevice(
        profileId: pid,
        deviceId: did,
        profileSecretB64: normalizedProfileSecret,
        requesterDeviceId: requesterDid,
        tsMs: tsMs,
        nonceB64: nonceB64,
        signatureB64: signatureB64,
      );
    } catch (_) {
      return false;
    }
  }

  /// UI-facing entitlement snapshot (TZ-MONETIZE-01 §C-1). Null until the R1
  /// bootstrap has constructed the repository. Defaults to fully-open; never
  /// gates security features.
  ValueListenable<EntitlementState>? get entitlements => _entitlements?.state;

  /// Current resolved entitlement (fail-open default before bootstrap).
  EntitlementState get entitlementStateNow =>
      _entitlements?.current ?? EntitlementState.open;

  /// Advisory "a newer build exists" hint from /v1/config (for the dismissible
  /// update nudge). Defaults to "none" (no nudge) until config is fetched.
  AppUpdateInfo get appUpdateInfo =>
      _entitlements?.updateInfo ?? AppUpdateInfo.none;

  /// Server-signed in-app Support config (feature flag + X25519 public key to
  /// seal tickets to). Defaults to OFF until a VERIFIED /v1/config block arrives
  /// — the Support page stays hidden and the e-mail fallback is used.
  SupportConfig get supportConfig =>
      _entitlements?.supportConfig ?? SupportConfig.defaults;

  /// Submit an E2EE support message:
  /// seals `{text, tech-info}` to the support public key (from signed config)
  /// and posts it to the relay. Throws if support isn't configured or the send
  /// fails — the UI surfaces that.
  /// Потолок ОТКРЫТОГО текста (JSON до шифрования) одного сообщения поддержки.
  ///
  /// 🔴 Поднято 03.08.2026 с 90 КБ. Вложение шифруется целиком и едет одним
  /// телом, проходя base64 ДВАЖДЫ: внутри JSON и затем как шифртекст. Реле
  /// принимает 12 МБ base64 шифртекста (SUPPORT_CIPHERTEXT_MAX_B64), что даёт
  /// ~9 МБ открытого текста; берём 7.5 МБ, чтобы вложение в 5 МБ (6.67 МБ
  /// после base64) плюс текст и тех-инфо гарантированно проходили с запасом.
  static const int supportPayloadMaxBytes = 7 * 1024 * 1024 + 512 * 1024;

  /// Потолок СЫРОГО вложения, который видит человек. Именно это число стоит
  /// показывать в сообщениях об ошибке — остальные пределы производны от него.
  static const int supportAttachmentMaxBytes = 5 * 1024 * 1024;

  // ── ЗНАЧОК ПОДДЕРЖКИ (03.08.2026) ─────────────────────────────────────────
  //
  // Запрос владельца: «если открыта сессия тех поддержки — красный кружок на
  // странице настроек; если пришёл ответ — кружок с числом».
  //
  // ЧТО ЗНАЧИТ КАЖДОЕ СОСТОЯНИЕ (правило выбрано так, чтобы значок гас сам, а
  // не висел вечно после любого давнего обращения):
  //   * число  — есть НЕПРОЧИТАННЫЕ ответы поддержки;
  //   * точка  — обращение в работе: последнее слово ваше, ответа ещё нет;
  //   * пусто  — переписки нет либо последний ответ прочитан.
  //
  // ПОЧЕМУ ОТДЕЛЬНЫЙ КУРСОР. У экрана поддержки свой курсор
  // (`support_cursor_v1_<pid>`), которым он вычерпывает ленту в свою историю.
  // Считать значок тем же курсором нельзя: опрос значка съел бы ответы, и
  // экран их уже не увидел бы. Поэтому у значка своя отметка высшей воды.
  static const _prefsSupportBadgeSeqKey = 'support_badge_seq_v1';
  static const _prefsSupportUnreadKey = 'support_unread_v1';
  static const _prefsSupportAwaitingKey = 'support_awaiting_reply_v1';

  int _supportUnread = 0;
  bool _supportAwaitingReply = false;

  /// Сколько ответов поддержки не прочитано.
  int get supportUnreadCount => _supportUnread;

  /// Обращение в работе: вы написали, ответа ещё нет.
  bool get supportAwaitingReply => _supportAwaitingReply;

  /// Нужно ли вообще что-то рисовать.
  bool get supportBadgeVisible => _supportUnread > 0 || _supportAwaitingReply;

  String _supportPrefKey(String base) => '${base}_${_profileId ?? ''}';

  Future<void> _loadSupportBadge(SharedPreferences prefs) async {
    _supportUnread = prefs.getInt(_supportPrefKey(_prefsSupportUnreadKey)) ?? 0;
    _supportAwaitingReply =
        prefs.getBool(_supportPrefKey(_prefsSupportAwaitingKey)) ?? false;
  }

  /// Тянет новые ответы поддержки и обновляет значок.
  ///
  /// Дёшево и молча: если обращений не было (`awaiting` = false и счётчик = 0
  /// и отметка нулевая), не ходит в сеть вовсе. Любая ошибка оставляет значок
  /// как есть — счётчик поддержки не тот повод, чтобы шуметь пользователю.
  Future<void> refreshSupportBadge() async {
    final relay = _relay;
    if (relay == null || !supportConfig.supportEnabled) return;
    final prefs = _prefs ?? await SharedPreferences.getInstance();
    _prefs = prefs;
    final seqKey = _supportPrefKey(_prefsSupportBadgeSeqKey);
    final lastSeq = prefs.getInt(seqKey) ?? 0;
    // Опрашивать нечего только если переписки с поддержкой НЕ БЫЛО ВООБЩЕ.
    //
    // 🔴 Раньше здесь стояло `lastSeq == 0 && !awaiting && unread == 0`, и это
    // был тупик: у переписки, заведённой ДО появления значка, все три значения
    // нулевые — значит опрос выходил сразу и значок не мог зажечься НИКОГДА.
    // Поймано в поле сразу же: ответ из админки пришёл, а кружок не появился.
    //
    // Признак «переписка есть» берём у самого экрана поддержки: он пишет свой
    // курсор в prefs при первом же сохранении ленты. Ключ существует —
    // разговор был, независимо от того, когда он начался.
    final cursorKey = _supportPrefKey('support_cursor_v1');
    final hasThread = prefs.containsKey(cursorKey);
    if (!hasThread &&
        lastSeq == 0 &&
        !_supportAwaitingReply &&
        _supportUnread == 0) {
      return;
    }

    // 🔴 ПЕРВЫЙ ЗАПУСК НАД СУЩЕСТВУЮЩЕЙ ПЕРЕПИСКОЙ. Своей отметки у значка ещё
    // нет, и опрос «с нуля» вернул бы ВСЕ прошлые ответы — человек увидел бы
    // кружок с числом давно прочитанных сообщений. Поэтому один раз
    // перенимаем то, что экран поддержки уже вычерпал, и ничего не считаем:
    // значок начинает жизнь с чистого листа, как и положено.
    if (!prefs.containsKey(seqKey)) {
      final seenByScreen = prefs.getInt(cursorKey) ?? 0;
      await prefs.setInt(seqKey, seenByScreen);
      if (seenByScreen > 0) return;
    }
    try {
      final fetched = await fetchSupportReplies(lastSeq);
      if (await _applySupportClearedIfNewer(fetched.clearedAtMs)) return;
      if (fetched.replies.isEmpty) return;
      final maxSeq = fetched.cursor > lastSeq ? fetched.cursor : lastSeq;
      _supportUnread += fetched.replies.length;
      // Ответ пришёл — ждать больше нечего, теперь слово за пользователем.
      _supportAwaitingReply = false;
      await prefs.setInt(seqKey, maxSeq);
      await prefs.setInt(_supportPrefKey(_prefsSupportUnreadKey), _supportUnread);
      await prefs.setBool(_supportPrefKey(_prefsSupportAwaitingKey), false);
      _changed.add(null);
    } catch (_) {
      // Значок — не повод шуметь; следующий заход попробует снова.
    }
  }

  static const _prefsSupportClearedSeenKey = 'support_cleared_seen_v1';

  /// Переписку стёрли из админки — стираем и у себя.
  ///
  /// 🔴 Отметка времени приходит с сервера, потому что удаление НЕ ВИДНО на
  /// опросе: пустой ответ после очистки неотличим от «нового ничего нет».
  ///
  /// Сравниваем с тем, что уже применили: иначе каждая проверка заново стирала
  /// бы ленту, и человек не смог бы написать в поддержку снова — его новое
  /// обращение исчезало бы на следующем опросе.
  Future<bool> _applySupportClearedIfNewer(int clearedAtMs) async {
    if (clearedAtMs <= 0) return false;
    final prefs = _prefs ?? await SharedPreferences.getInstance();
    _prefs = prefs;
    final seenKey = _supportPrefKey(_prefsSupportClearedSeenKey);
    if ((prefs.getInt(seenKey) ?? 0) >= clearedAtMs) return false;
    await prefs.setInt(seenKey, clearedAtMs);

    // Значок гаснет целиком, а отметки обнуляются: следующая переписка начнётся
    // с чистого листа, а не продолжит счёт стёртой.
    _supportUnread = 0;
    _supportAwaitingReply = false;
    await prefs.setInt(_supportPrefKey(_prefsSupportUnreadKey), 0);
    await prefs.setBool(_supportPrefKey(_prefsSupportAwaitingKey), false);
    await prefs.setInt(_supportPrefKey(_prefsSupportBadgeSeqKey), 0);
    await prefs.remove(_supportPrefKey('support_cursor_v1'));

    // Сама лента лежит файлом (в prefs она раздувала бы старт приложения).
    try {
      final dir = await getApplicationDocumentsDirectory();
      final f = File('${dir.path}/support_thread_${_profileId ?? ''}.json');
      if (await f.exists()) await f.delete();
    } catch (_) {
      // Не смогли удалить файл — счётчики уже сброшены, лента подтянется
      // пустой при следующем открытии экрана.
    }
    _changed.add(null);
    return true;
  }

  /// Последняя применённая отметка очистки — экран поддержки сверяется с ней,
  /// чтобы не показывать стёртую ленту из своей памяти.
  int get supportClearedSeenAtMs =>
      _prefs?.getInt(_supportPrefKey(_prefsSupportClearedSeenKey)) ?? 0;

  /// Пользователь отправил обращение: с этого момента ждём ответа.
  Future<void> noteSupportMessageSent() async {
    final prefs = _prefs ?? await SharedPreferences.getInstance();
    _prefs = prefs;
    _supportAwaitingReply = true;
    await prefs.setBool(_supportPrefKey(_prefsSupportAwaitingKey), true);
    _changed.add(null);
  }

  /// Экран поддержки открыт и прочитан: гасим число и синхронизируем отметку,
  /// чтобы уже показанные ответы не посчитались снова.
  Future<void> markSupportRead({int? seenSeq}) async {
    final prefs = _prefs ?? await SharedPreferences.getInstance();
    _prefs = prefs;
    if (_supportUnread == 0 && seenSeq == null) return;
    _supportUnread = 0;
    await prefs.setInt(_supportPrefKey(_prefsSupportUnreadKey), 0);
    if (seenSeq != null && seenSeq > 0) {
      final seqKey = _supportPrefKey(_prefsSupportBadgeSeqKey);
      final known = prefs.getInt(seqKey) ?? 0;
      if (seenSeq > known) await prefs.setInt(seqKey, seenSeq);
    }
    _changed.add(null);
  }

  Future<void> submitSupportMessage(
    String text, {
    String? attachmentName,
    String? attachmentMime,
    Uint8List? attachmentBytes,
  }) async {
    final cfg = supportConfig;
    final pubB64 = cfg.supportPubB64.trim();
    final relay = _relay;
    if (!cfg.isUsable || pubB64.isEmpty || relay == null) {
      throw StateError('support unavailable');
    }
    final seed = await SecureSecrets.create().getOrCreateSupportSeed();
    final replyPub = await SupportSeal.publicKeyFromSeed(seed);
    final tech = 'Build marker: $buildMarker\n'
        'Device ID: $deviceId\n'
        'Profile ID: $profileId';
    final map = <String, Object?>{'text': text, 'tech': tech};
    if (attachmentBytes != null && attachmentBytes.isNotEmpty) {
      map['attachment'] = <String, Object?>{
        'name': (attachmentName ?? 'file').trim().isEmpty
            ? 'file'
            : attachmentName!.trim(),
        'mime': (attachmentMime ?? 'application/octet-stream'),
        'b64': base64Encode(attachmentBytes),
      };
    }
    final payload = utf8.encode(jsonEncode(map));
    if (payload.length > supportPayloadMaxBytes) {
      throw StateError('support payload too large: ${payload.length} bytes');
    }
    final sealed = await SupportSeal.seal(
      plaintext: payload,
      recipientPublicKey: Uint8List.fromList(base64Decode(pubB64)),
    );
    await relay.submitSupport(
      ticketId: _uuid.v4(),
      replyPubkeyB64: base64Encode(replyPub),
      ciphertextB64: sealed,
    );
  }

  /// Fetch + decrypt admin support replies newer than [fromSeq]. Returns the
  /// plaintext replies (text + timestamp + seq) and the advanced cursor. An
  /// undecryptable reply is skipped but still advances the cursor.
  Future<
      ({
        List<({String text, int tsMs, int seq})> replies,
        int cursor,
        int clearedAtMs,
      })> fetchSupportReplies(int fromSeq) async {
    final relay = _relay;
    if (relay == null) {
      return (
        replies: const <({String text, int tsMs, int seq})>[],
        cursor: fromSeq,
        clearedAtMs: 0,
      );
    }
    final seed = await SecureSecrets.create().getOrCreateSupportSeed();
    final fetched = await relay.supportRepliesWithState(fromSeq: fromSeq);
    final raw = fetched.replies;
    var cursor = fromSeq;
    final out = <({String text, int tsMs, int seq})>[];
    for (final r in raw) {
      final seq = (r['seq'] as num?)?.toInt() ?? 0;
      if (seq > cursor) cursor = seq;
      final ctB64 = (r['ciphertext_b64'] as String?)?.trim() ?? '';
      final tsMs = (r['created_at_ms'] as num?)?.toInt() ??
          DateTime.now().millisecondsSinceEpoch;
      if (ctB64.isEmpty) continue;
      try {
        final opened =
            await SupportSeal.open(sealedB64: ctB64, recipientPrivateSeed: seed);
        final decoded = jsonDecode(utf8.decode(opened));
        final text = decoded is Map && decoded['text'] is String
            ? decoded['text'] as String
            : utf8.decode(opened);
        out.add((text: text, tsMs: tsMs, seq: seq));
      } catch (_) {
        // Undecryptable (key mismatch / tamper) — skip; cursor already advanced.
      }
    }
    return (replies: out, cursor: cursor, clearedAtMs: fetched.clearedAtMs);
  }

  /// Number of groups the current profile OWNS (monetization §C-3).
  Future<int> ownedGroupCount() async {
    final db = _db;
    final pid = profileId;
    if (db == null || pid.isEmpty) return 0;
    return db.groupOwnedCount(pid);
  }

  /// Number of groups the current profile is an active member of.
  Future<int> joinedGroupCount() async {
    final db = _db;
    final pid = profileId;
    if (db == null || pid.isEmpty) return 0;
    return db.groupJoinedActiveCount(pid);
  }

  /// Whether the profile may create one more group right now (UI pre-check;
  /// [createGroup] enforces the same rule as a backstop).
  Future<bool> canCreateGroupNow() async =>
      FeatureGate.canCreateGroup(entitlementStateNow, await ownedGroupCount());

  /// Whether the profile may join one more group right now.
  Future<bool> canJoinGroupNow() async =>
      FeatureGate.canJoinGroup(entitlementStateNow, await joinedGroupCount());

  /// R1 monetization bootstrap (TZ §C-1). Idempotent and fire-and-forget:
  ///   * builds the entitlement repository from the current profile/device,
  ///   * restores the cached snapshot,
  ///   * performs the one-shot legacy_claim grandfathering call,
  ///   * refreshes from the signed /v1/config + entitlement endpoint.
  /// Everything fails OPEN — any error leaves the app fully unlocked, exactly
  /// like the pre-freemium build. UI is NOT changed in R1.
  /// C-2: BillingService verify hook. Verifies a completed/restored purchase by
  /// redeeming the receipt with keys and applies the returned signed entitlement.
  /// Returns true if granted. Fails soft — never throws into the purchase stream.
  Future<bool> verifyAndApplyPurchase(PurchaseDetails pd) async {
    final repo = _entitlements;
    final pid = (_profileId ?? '').trim();
    if (repo == null || pid.isEmpty) return false;
    final receipt = pd.verificationData.serverVerificationData;
    if (receipt.isEmpty) return false;
    try {
      // iOS/macOS send the StoreKit2 signed-transaction JWS; Android sends the
      // purchase token + product id. (Exact iOS receipt shape to confirm during
      // live sandbox testing — see docs/MONETIZATION_AUDIT.)
      if (Platform.isIOS || Platform.isMacOS) {
        return await repo.redeemPurchase(
          profileId: pid,
          platform: 'appstore',
          jws: receipt,
        );
      }
      final product = pd.productID;
      if (product.isEmpty) return false;
      return await repo.redeemPurchase(
        profileId: pid,
        platform: 'play',
        purchaseToken: receipt,
        productId: product,
      );
    } catch (_) {
      return false;
    }
  }

  /// Forces a fresh pull of the server entitlement (signed /v1/config + signed
  /// entitlement blob) into the client and reports whether a PAID tier is now
  /// active. Used by "Restore" so a grant that never arrived through the store
  /// stream — an admin/comped grant, a webhook credit, or a purchase credited
  /// server-side in a past session — is surfaced without an app restart.
  Future<bool> refreshEntitlementsNow() async {
    final repo = _entitlements;
    final pid = (_profileId ?? '').trim();
    if (repo == null || pid.isEmpty) return false;
    try {
      await repo.refresh(profileId: pid);
      _applyReliabilityFlags(repo);
      _applyRoomFlags(repo);
      _rooms2Flags = repo.rooms2Flags;
      _applyHandshakeFlags(repo);
      await _applyHandshakeAuthSwitch(repo);
    } catch (_) {
      // best-effort; keep whatever state we already have
    }
    return repo.current.tier.isPaid;
  }

  /// Delivery-health counters for the diagnostics screen. Empty when the DB is
  /// not up yet, so the UI can render the section unconditionally.
  /// Убирает из карантина конверты, отправленные ЭТИМ ЖЕ устройством.
  ///
  /// 🔴 Почему отдельной уборкой (23.08.2026): фильтр на входе ловит только
  /// НОВЫЕ попытки, а уже припаркованные записи ждут переигровки — которая для
  /// них не наступает (`quarantine_replay_throttled`), поэтому счётчик «не
  /// удалось прочитать» висел бы вечно. Узнано из лога сборки 548, не из
  /// рассуждений.
  Future<void> _purgeSelfQuarantine() async {
    final db = _db;
    final selfDid = (_deviceId ?? '').trim();
    if (db == null || selfDid.isEmpty) return;
    try {
      final rows = await db.inboxQuarantineListAll();
      var removed = 0;
      for (final row in rows) {
        final sender = ((row['sender_device_id'] as String?) ?? '').trim();
        if (sender.isEmpty || sender != selfDid) continue;
        final msgId = ((row['msg_id'] as String?) ?? '').trim();
        if (msgId.isEmpty) continue;
        if (await db.inboxQuarantineDelete(msgId)) removed++;
      }
      // Лог БЕЗУСЛОВНЫЙ: «ничего не удалено» и «уборка не отработала вовсе»
      // обязаны выглядеть по-разному.
      DiagLog.event('inbox', 'self_quarantine_purge', {
        'removed': removed,
        'scanned': rows.length,
        'self_dev': DiagLog.pfx(selfDid),
      });
    } catch (_) {
      // Уборка не имеет права ломать запуск.
    }
  }

  Future<Map<String, int>> deliveryHealthCounters() async {
    final db = _db;
    if (db == null) return const <String, int>{};
    try {
      return await db.deliveryHealthCounters();
    } catch (_) {
      return const <String, int>{};
    }
  }

  /// Applies the server-signed delivery kill-switches (TZ §12) after a
  /// /v1/config refresh — the lever that lets a misbehaving heuristic be
  /// stopped in minutes instead of an App Store review.
  ///
  /// The repo only reports a non-default value for a block whose signature
  /// VERIFIED, so an unreachable server, an old server that sends no block, or
  /// a forged response all leave the machinery ON. Logged on an actual change
  /// so the flip is visible in delivery diagnostics.
  void _applyReliabilityFlags(EntitlementRepository repo) {
    // И-1 rotation switch rides the same refresh. Only a session that actually
    // received a config response may move the cached value — a network failure
    // must not overwrite a previously verified ON with the dormant default.
    if (repo.identityFlagsResolved) {
      final enabled = repo.identityFlags.rotationOnStateLossEnabled;
      if (enabled != _identityRotationOnStateLossEnabled) {
        _identityRotationOnStateLossEnabled = enabled;
        final prefs = _prefs;
        if (prefs != null) {
          unawaited(prefs.setBool(_prefsI1RotationEnabledKey, enabled));
        }
        DiagLog.event('i1', 'rotation_flag_applied', {'enabled': enabled});
      }
    }

    final flags = repo.reliabilityFlags;
    if (flags.nackReceiptsEnabled == _nackReceiptsEnabled &&
        flags.convergenceResendEnabled == _senderConvergenceBackstopEnabled) {
      return;
    }
    _nackReceiptsEnabled = flags.nackReceiptsEnabled;
    _senderConvergenceBackstopEnabled = flags.convergenceResendEnabled;
    DiagLog.event('delivery', 'reliability_flags_applied', {
      'nack': flags.nackReceiptsEnabled,
      'convergence_resend': flags.convergenceResendEnabled,
    });
  }

  /// Human-readable sender-key state per room, for the diagnostics report
  /// (F-ROOMSK-6).
  ///
  /// The line a field tester needs is `owed`: while it is non-zero the room
  /// sends over the PAIRWISE fanout, and only when it reaches zero does the
  /// sender key engage. Before this, answering "why is my room not using the
  /// new path?" meant reading `adb logcat` — which is not available to the
  /// person actually holding the phone.
  Future<String> roomSenderKeyDiagnosticsReport() async {
    final db = _db;
    if (db == null) return 'room_keys: (no database)';
    List<Map<String, Object?>> rows;
    try {
      rows = await db.roomSenderKeyDiagnostics();
    } catch (e) {
      return 'room_keys: (unavailable: ${_classifyShortReason(e)})';
    }
    if (rows.isEmpty) return 'room_keys: none (no room has a sender key yet)';
    final b = StringBuffer('room_keys:');
    for (final r in rows) {
      final room = ((r['room_id'] as String?) ?? '').trim();
      final epoch = (r['epoch'] as num?)?.toInt() ?? 0;
      final counter = (r['counter'] as num?)?.toInt() ?? 0;
      final delivered = (r['delivered'] as num?)?.toInt() ?? 0;
      final confirmed = (r['confirmed'] as num?)?.toInt() ?? 0;
      final owed = delivered - confirmed;
      b.write(
        '\n  ${DiagLog.pfx(room)} epoch=$epoch counter=$counter '
        'delivered=$delivered confirmed=$confirmed '
        '${owed > 0 ? 'owed=$owed → PAIRWISE' : '→ SEALED'}',
      );
    }
    return b.toString();
  }

  /// Applies the signed `rooms` block (F-ROOMSK-2).
  ///
  /// TWO INDEPENDENT KEYS turn room sending on, and EITHER turns it off: the
  /// compile-time build flag AND a signed server block. That is the lever we
  /// did not have on 1.7.4+416, when a build shipped sealing room messages a
  /// peer could not read and the only remedy was reinstalling the app.
  ///
  /// The server can never force this ON for a build that was not built for it,
  /// and an unverifiable answer leaves sending dormant — the room simply falls
  /// back to the pairwise fanout every build can read.
  void _applyRoomFlags(EntitlementRepository repo) {
    // No early return on "unresolved": that is a NO, and it must be able to
    // turn sending back OFF, not merely fail to turn it on. A config fetch that
    // stops verifying (key rotated, block stripped, server rolled back) has to
    // put us back on the pairwise path.
    final resolved = repo.roomFlagsResolved;
    final allowed = repo.roomFlags.senderKeySendEnabled;
    final effective = effectiveRoomSenderKeySend(
      builtWith: _roomSenderKeyEnabledEnv,
      serverResolved: resolved,
      serverAllows: allowed,
    );
    if (effective == roomSenderKeySendEnabled) return;
    roomSenderKeySendEnabled = effective;
    DiagLog.event('room_key', 'send_flag_applied', {
      'built_with': _roomSenderKeyEnabledEnv,
      'server_resolved': resolved,
      'server_allows': allowed,
      'effective': effective,
    });
  }

  /// Применяет серверный переключатель отправки повторного prekey (Э-4).
  ///
  /// Как и у комнат, «не удалось проверить» — это НЕТ, а не «оставить как
  /// было»: конфиг, переставший верифицироваться (ключ сменили, блок срезали,
  /// сервер откатили), обязан вернуть отправку в спящее состояние, а не просто
  /// не суметь её включить.
  ///
  /// Сборочный флаг остаётся ПЕРЕОПРЕДЕЛЕНИЕМ для полевых проверок: собрал с
  /// dart-define — отправка включена независимо от сервера. В обычной сборке
  /// его нет, и решает только сервер.
  /// С-2 (24.09.2026): выключатель отказов проверки подписи рукопожатия.
  ///
  /// Кладётся в базу, а не в память: менеджер сессий читает его и в фоновом
  /// изоляте. Пишется только ПРОВЕРЕННОЕ значение; молчащий сервер ничего не
  /// меняет. Ошибка записи не должна ломать применение остальных флагов.
  Future<void> _applyHandshakeAuthSwitch(EntitlementRepository repo) async {
    final disabled = repo.handshakeAuthEnforceDisabled;
    final db = _db;
    if (disabled == null || db == null) return;
    try {
      final want = disabled ? '1' : '0';
      final have = await db.localKvGet(AppDb.kvHandshakeAuthEnforceDisabled);
      if (have == want) return;
      await db.localKvSet(AppDb.kvHandshakeAuthEnforceDisabled, want);
      DiagLog.event('hs', 'enforce_switch_applied', <String, Object?>{
        'enforce_disabled': disabled,
      });
    } catch (_) {
      // best-effort, как и остальные флаги
    }
  }

  void _applyHandshakeFlags(EntitlementRepository repo) {
    final resolved = repo.handshakeFlagsResolved;
    final flags = repo.handshakeFlags;
    final did = (_deviceId ?? '').trim();
    final serverAllows = resolved && flags.allowsSendFor(did);
    final effective = _prekeyUntilConfirmedEnvOverride || serverAllows;
    if (effective == kPrekeyUntilConfirmedSend) return;
    kPrekeyUntilConfirmedSend = effective;
    DiagLog.event('handshake', 'prekey_send_flag_applied', {
      'built_with': _prekeyUntilConfirmedEnvOverride,
      'server_resolved': resolved,
      'server_enabled': flags.prekeyUntilConfirmedSendEnabled,
      'server_percent': flags.prekeyUntilConfirmedSendPercent,
      'in_rollout': serverAllows,
      'effective': effective,
    });
  }

  /// Сборочное переопределение: снимок значения на момент старта, ДО того как
  /// сервер что-либо сказал. Хранится отдельно, потому что сам
  /// [kPrekeyUntilConfirmedSend] дальше меняется сервером.
  static final bool _prekeyUntilConfirmedEnvOverride =
      kPrekeyUntilConfirmedSend;

  Future<void> runMonetizationR1Bootstrap() async {
    if (_monetizationR1BootstrapStarted) return;
    final pid = (_profileId ?? '').trim();
    final did = (_deviceId ?? '').trim();
    if (pid.isEmpty || did.isEmpty || pid.startsWith('LOCAL-')) {
      return;
    }
    _monetizationR1BootstrapStarted = true;
    try {
      final keys = _keys ?? KeysClient(baseUrl: keysBaseUrl);
      _keys = keys;
      final repo = EntitlementRepository(
        keysClient: keys,
        signer: DeviceKeyEntitlementSigner(profileId: pid, deviceId: did),
        cache: SecureStorageEntitlementCache(),
        // Self-heal a keys DEVICE-AUTH 401 on redeem / entitlements-fetch: a
        // churned/unregistered device_id (e.g. iOS reinstall wiped prefs but the
        // Keychain kept the identity key) gets re-registered here, then the call
        // retries. Reuses the same repair the send/bundle path uses.
        repairDeviceAuth: _repairKeysIdentityForSendOnce,
      );
      _entitlements = repo;
      // When cosmetic access flips (premium gained/lost), re-publish my profile
      // meta so peers gain/lose my frame & cover, and refresh local UI (the
      // myFrameId/myCoverId getters are gated on entitlement).
      bool? lastCosmeticUnlocked;
      bool? lastPaid;
      repo.state.addListener(() {
        final nowUnlocked = FeatureGate.isUnlocked(
          repo.current,
          GatedFeature.cosmetic,
        );
        final nowPaid = repo.current.tier.isPaid;
        // Latch the sticky "ever subscribed" flag the first time we see a paid
        // tier, so the premium upsell is never shown again to this profile even
        // after the subscription lapses. Best-effort persist.
        if (nowPaid && !_everHadEntitlement) {
          _everHadEntitlement = true;
          final prefs = _prefs;
          if (prefs != null) {
            unawaited(prefs.setBool(_prefsEverHadEntitlementKey, true));
          }
        }
        final cosmeticFlip =
            lastCosmeticUnlocked != null && lastCosmeticUnlocked != nowUnlocked;
        final paidFlip = lastPaid != null && lastPaid != nowPaid;
        // Re-publish meta when the premium badge changes (paid-tier flip — even
        // with no cosmetics set), or when cosmetic access flips and I have any
        // cosmetic (frame/cover/emoji status) to gain or lose for peers.
        if (paidFlip ||
            (cosmeticFlip &&
                (_myFrameId != null ||
                    _myCoverId != null ||
                    _myCoverImagePath != null ||
                    _myEmojiStatus != null))) {
          _scheduleMyProfileMetaPublish();
        }
        lastCosmeticUnlocked = nowUnlocked;
        lastPaid = nowPaid;
        _changed.add(null);
      });
      await repo.loadFromCache();
      await repo.maybeClaimLegacyOnce(profileId: pid);
      await repo.refresh(profileId: pid);
      _applyReliabilityFlags(repo);
      _applyRoomFlags(repo);
      _rooms2Flags = repo.rooms2Flags;
      _applyHandshakeFlags(repo);
      await _applyHandshakeAuthSwitch(repo);
      // Paid-but-not-credited recovery: now that the entitlement repo + verifier
      // are ready, re-deliver any owned/unfinished purchase so a grant lost on a
      // previous launch (or dropped by the bootstrap race before the repo
      // existed) is redeemed and credited in THIS session, not just on the next
      // cold start. Best-effort; idempotent server-side.
      unawaited(BillingService.instance.retryUnfinishedPurchases());
    } catch (_) {
      // Fail open: monetization must never block startup or messaging.
    }
  }

  /// Public API: end the session of another device registered under the
  /// current profile. Both mobile (Settings → Управление устройствами) and
  /// desktop (Settings → Devices) call this when the user taps «Завершить
  /// сеанс». The request is signed by the **caller's** identity key — the
  /// keys server then verifies that requester+target share the same profile
  /// (see server/keys/src/main.rs::delete_device).
  ///
  /// Returns `true` on a confirmed server-side removal. Throws [StateError]
  /// on configuration problems so the UI can surface a real reason instead
  /// of a silent «не получилось».
  Future<bool> endDeviceSession({required String targetDeviceId}) async {
    final pid = (_profileId ?? '').trim();
    final myDid = (_deviceId ?? '').trim();
    final tdid = targetDeviceId.trim();
    if (pid.isEmpty || myDid.isEmpty) {
      throw StateError(
        'Профиль ещё не инициализирован. Завершите подключение к серверу.',
      );
    }
    if (pid.startsWith('LOCAL-')) {
      throw StateError(
        'Профиль работает в локальном режиме — устройства не зарегистрированы на сервере.',
      );
    }
    if (tdid.isEmpty) {
      throw StateError('Не указан идентификатор устройства.');
    }
    if (tdid == myDid) {
      throw StateError(
        'Нельзя завершить сеанс текущего устройства из этого экрана. '
        'Используйте «Выйти из аккаунта» / «Сбросить устройство».',
      );
    }
    // PR-H bug 21: notify the evicted device BEFORE the keys-server delete
    // so it has a chance to wipe local state while its ratchet session is
    // still alive. After `_deleteDeviceRegistrationFromServer` succeeds the
    // server will refuse to issue new prekeys for that deviceId, so any
    // later attempt to send the revocation envelope would silently no-op.
    //
    // Best-effort: errors are logged but never block the eviction. If the
    // envelope fails to land, the evicted device will discover the eviction
    // on its next handshake (which will fail 401/403/404) and the desktop
    // periodic-check (Bug 21 fallback) will kick in.
    try {
      final payload = <String, Object?>{
        'profileId': pid,
        'targetDeviceId': tdid,
        'revokedAtMs': DateTime.now().millisecondsSinceEpoch,
        'requesterDeviceId': myDid,
        'reason': 'end_session',
      };
      final controlText = _encodeCommandPayload(
        _sessionRevokedCmdPrefix,
        payload,
      );
      await sendControlMessage(
        peerProfileId: pid,
        controlText: controlText,
        targetDeviceIds: [tdid],
        priority: 10,
        retryBucket: 'session_revoke',
      ).timeout(
        const Duration(seconds: 3),
        onTimeout: () {
          DiagLog.event('devices', 'end_session_revoke_envelope_timeout', {
            'target': tdid.length > 8 ? tdid.substring(0, 8) : tdid,
          });
        },
      );
      DiagLog.event('devices', 'end_session_revoke_envelope_sent', {
        'target': tdid.length > 8 ? tdid.substring(0, 8) : tdid,
      });
      // Give relay ~1.5 s to deliver before we delete the server-side
      // registration. The receiver only needs an inbox-flush round trip;
      // a longer wait would punish UX without measurable benefit.
      await Future<void>.delayed(const Duration(milliseconds: 1500));
    } catch (e) {
      callLog(
        'AppCtrl',
        'endDeviceSession revoke envelope failed (best-effort): $e',
      );
    }
    final ok = await _deleteDeviceRegistrationFromServer(
      profileId: pid,
      deviceId: tdid,
      requesterDeviceId: myDid,
    );
    if (!ok) {
      throw StateError(
        'Сервер не подтвердил удаление устройства. Попробуйте позже.',
      );
    }
    DiagLog.event('devices', 'end_session_ok', {
      'target': tdid.length > 8 ? tdid.substring(0, 8) : tdid,
    });
    return ok;
  }

  /// Когда спрашивать сервер ключей, снята ли регистрация этого устройства,
  /// после конверта «сеанс завершён». Отправитель удаляет её через 1,5 с после
  /// отправки (плюс до 3 с на саму отправку); дальше — запас на плохую сеть.
  @visibleForTesting
  static List<Duration> sessionRevokeConfirmDelays = const <Duration>[
    Duration.zero,
    Duration(seconds: 3),
    Duration(seconds: 10),
    Duration(seconds: 30),
    Duration(seconds: 90),
  ];

  @visibleForTesting
  Future<OwnDeviceRegistration> Function()? ownDeviceRegistrationProbeForTesting;

  @visibleForTesting
  Future<void> Function()? sessionRevokeResetForTesting;

  Future<void>? _sessionRevokeConfirmation;

  @visibleForTesting
  Future<void>? get sessionRevokeConfirmationForTesting =>
      _sessionRevokeConfirmation;

  bool _sessionRevokeConfirmInFlight = false;

  Future<void> _resetAfterServerConfirmsRevocation({
    required String requesterDeviceId,
    required String reason,
    required String senderDeviceId,
  }) async {
    if (_sessionRevokeConfirmInFlight) return;
    _sessionRevokeConfirmInFlight = true;
    try {
      var attempt = 0;
      for (final delay in sessionRevokeConfirmDelays) {
        attempt++;
        if (delay > Duration.zero) {
          await Future<void>.delayed(delay);
        }
        final registration = await _probeOwnDeviceRegistration();
        DiagLog.event('session_revoke', 'confirm_probe', {
          'attempt': attempt,
          'registration': registration.name,
        });
        if (registration != OwnDeviceRegistration.gone) continue;

        final myPid = (_profileId ?? '').trim();
        final myDid = (_deviceId ?? '').trim();
        DiagLog.event('session_revoke', 'self_evicted', {
          'requester': DiagLog.pfx(requesterDeviceId),
          'reason': reason,
        });
        final reset = sessionRevokeResetForTesting;
        if (reset != null) {
          await reset();
          return;
        }
        await IdentityJournal.record(
          reason: IdentityJournal.reasonSessionRevoked,
          nowMs: DateTime.now().millisecondsSinceEpoch,
          previousProfileId: myPid,
          previousDeviceId: myDid,
          detail: <String, Object?>{
            'by_device': DiagLog.pfx(senderDeviceId),
            'confirmed_by': 'keys_server',
          },
        );
        await resetProfileAndLocalData();
        return;
      }
      DiagLog.event('session_revoke', 'ignored_unconfirmed', {
        'sender_dev': DiagLog.pfx(senderDeviceId),
        'attempts': attempt,
      });
    } catch (e) {
      DiagLog.event('session_revoke', 'confirm_failed', {
        'reason': _classifyShortReason(e),
      });
    } finally {
      _sessionRevokeConfirmInFlight = false;
    }
  }

  /// У-1 (17.09.2026): регистрацию этого устройства сняли на сервере (другое
  /// устройство завершило сеанс, а конверт не дошёл). Приложение не знало об
  /// этом и бесконечно стучалось в реле. Теперь — признак и полоса в списке
  /// чатов. Данные сами НЕ стираются: решает человек.
  bool _ownDeviceRemoved = false;
  bool get ownDeviceRemoved => _ownDeviceRemoved;
  int _lastUnknownDeviceProbeAtMs = 0;
  static const int _unknownDeviceProbeEveryMs = 10 * 60 * 1000;

  void _onRelaySaysUnknownDevice() {
    final now = DateTime.now().millisecondsSinceEpoch;
    if (_ownDeviceRemoved ||
        now - _lastUnknownDeviceProbeAtMs < _unknownDeviceProbeEveryMs) {
      return;
    }
    _lastUnknownDeviceProbeAtMs = now;
    final probedDid = (_deviceId ?? '').trim();
    unawaited(() async {
      var registration = await _probeOwnDeviceRegistration();
      if (registration == OwnDeviceRegistration.gone) {
        // Свежий номер (восстановление, смена номера) регистрируется в фоне, а
        // реле подключается сразу: первое «неизвестно» честно лишь мгновение.
        // Полосу ставим, только если и после паузы устройства нет.
        await Future<void>.delayed(unknownDeviceConfirmDelay);
        if ((_deviceId ?? '').trim() != probedDid) return;
        registration = await _probeOwnDeviceRegistration();
      }
      DiagLog.event('devices', 'unknown_device_probe', {
        'registration': registration.name,
      });
      if (registration != OwnDeviceRegistration.gone) return;
      _ownDeviceRemoved = true;
      _changed.add(null);
    }());
  }

  /// Пауза перед повторной проверкой «устройства нет» (У-1).
  @visibleForTesting
  Duration unknownDeviceConfirmDelay = const Duration(minutes: 2);

  /// Отметка последней УДАЧНОЙ связи с сервером.
  ///
  /// По ней компьютер решает, не пора ли спросить пароль входа: потерянный
  /// компьютер команду «отключить» не получит, а срок без связи — получит.
  /// Пишем не чаще раза в час: это отметка, а не счётчик.
  static const String prefsLastServerContactAtMsKey =
      'last_server_contact_at_ms';
  int _lastServerContactWriteAtMs = 0;

  void _noteServerContact() {
    final now = DateTime.now().millisecondsSinceEpoch;
    if (now - _lastServerContactWriteAtMs < 60 * 60 * 1000) return;
    _lastServerContactWriteAtMs = now;
    unawaited(() async {
      try {
        final prefs = await SharedPreferences.getInstance();
        await prefs.setInt(prefsLastServerContactAtMsKey, now);
      } catch (_) {
        // Отметка — удобство, а не условие работы.
      }
    }());
  }

  /// Реле приняло запрос этого устройства — значит, оно зарегистрировано.
  void _onRelayAcceptedOwnDevice() {
    _noteServerContact();
    if (!_ownDeviceRemoved) return;
    _ownDeviceRemoved = false;
    DiagLog.event('devices', 'own_device_back', const {});
    _changed.add(null);
  }

  @visibleForTesting
  void noteRelayUnknownDeviceForTesting() => _onRelaySaysUnknownDevice();

  @visibleForTesting
  void noteRelayAcceptedOwnDeviceForTesting() => _onRelayAcceptedOwnDevice();

  /// С-1 + смена номера устройства (17.09.2026): провода в очереди зашифрованы
  /// со СТАРЫМ номером в заголовке, а реле назовёт новый — получатель 600+
  /// отбросит их как подмену, и сообщение пропадёт молча. Помечаем «не
  /// отправлено»: повтор пересобирает сообщение уже под новым номером.
  Future<void> _failOutboxEncryptedUnderOldDevice() async {
    final db = _db;
    if (db == null) return;
    try {
      final ids = await db.outboxUnsentMsgIds();
      for (final id in ids) {
        await db.outboxMarkFailed(
          id,
          reasonCode: MessageFailureReason.relayRejectedAuthFailed,
          errorCode: 'device_rotated',
        );
      }
      if (ids.isNotEmpty) {
        DiagLog.event('devices', 'outbox_failed_after_rotation', {
          'count': ids.length,
        });
        _changed.add(null);
      }
    } catch (_) {
      // Не хуже прежнего: провода уйдут как раньше.
    }
  }

  @visibleForTesting
  Future<void> failOutboxAfterDeviceRotationForTesting() =>
      _failOutboxEncryptedUnderOldDevice();

  /// Значение из ЗАШИФРОВАННОЙ базы по ключу.
  ///
  /// Для хранилищ компьютера, которым нужна та же защита, что и переписке
  /// (черновики). Телефон этим путём не пользуется; поведение его экранов не
  /// меняется.
  Future<String?> localValueGet(String key) async {
    final db = _db;
    if (db == null) return null;
    try {
      return await db.localKvGet(key);
    } catch (_) {
      return null;
    }
  }

  /// Записать значение в зашифрованную базу; пустое — стереть ключ.
  Future<void> localValueSet(String key, String value) async {
    final db = _db;
    if (db == null) return;
    try {
      if (value.isEmpty) {
        await db.localKvDelete(key);
      } else {
        await db.localKvSet(key, value);
      }
    } catch (_) {
      // Черновик не стоит падения приложения.
    }
  }

  Future<OwnDeviceRegistration> _probeOwnDeviceRegistration() async {
    final probe = ownDeviceRegistrationProbeForTesting;
    if (probe != null) return probe();
    final myPid = (_profileId ?? '').trim();
    final myDid = (_deviceId ?? '').trim();
    // `_lookupProfileForDeviceAuthed` отвечает null и тогда, когда ему нечем
    // подписать запрос, — это не «устройства нет», поэтому проверяем заранее.
    if (_keys == null ||
        myPid.isEmpty ||
        myDid.isEmpty ||
        myPid.startsWith('LOCAL-') ||
        _transportBlocked) {
      return OwnDeviceRegistration.unknown;
    }
    try {
      final owner = await _lookupProfileForDeviceAuthed(
        myDid,
      ).timeout(const Duration(seconds: 8));
      // Устройство, спросившее о себе, прошло проверку подписи — значит, оно
      // есть. «Нет» здесь бывает только при сбое сервера ключей; «удалено»
      // означает лишь 401 unknown requester device (см. ниже).
      if (owner == null) return OwnDeviceRegistration.unknown;
      return owner.trim() == myPid
          ? OwnDeviceRegistration.present
          : OwnDeviceRegistration.unknown;
    } catch (e) {
      return ownDeviceRegistrationFromLookupError(e);
    }
  }

  Future<void> _ensureDesktopLinkTargetReady({
    required SharedPreferences prefs,
  }) async {
    // Desktop pairing had no observability at all: when the QR failed to
    // appear, the screen showed a message and the log said nothing, so the
    // reason had to be guessed from source. Every exit of this function now
    // names itself. Read with: grep 'event=desktop_link'.
    DiagLog.event('desktop_link', 'target_ready_begin', {
      'transport_blocked': _transportBlocked,
      'has_profile': (_profileId ?? '').trim().isNotEmpty,
      'has_device': (_deviceId ?? '').trim().isNotEmpty,
    });
    if (_transportBlocked) {
      DiagLog.event('desktop_link', 'target_ready_fail', {
        'code': 'transport_blocked',
        'reason': _transportBlockedReason ?? '',
      });
      throw DesktopLinkFailure(
        DesktopLinkFailureCode.targetTransportBlocked,
        message:
            _transportBlockedReason ??
            'Transport is blocked for current server binding.',
      );
    }

    final keys = _keys ?? KeysClient(baseUrl: keysBaseUrl);
    _keys = keys;

    // 🔴 ОТКАЗ ПУБЛИКАЦИИ — ЭТО ОТДЕЛЬНЫЙ СЛУЧАЙ, А НЕ «ЧТО-ТО СЛОМАЛОСЬ».
    //
    // Раньше `StateError('publishKeys returned ok=false')` улетал наверх как
    // есть, и экран спаривания показывал человеку текст исключения Dart рядом
    // с надписью «QR недоступен». Понять из этого нельзя ничего, а сделать —
    // тем более.
    //
    // Сервер при этом ОТВЕТИЛ (не-2xx здесь бросает с кодом состояния), то
    // есть сеть цела и «сервер офлайн» — неправда. Он именно отказался принять
    // связку. Спаривание без неё невозможно: телефону нечем зашифровать ответ.
    try {
      await _ensureKeysSetup(
        prefs: prefs,
        keys: keys,
        allowServerProfileAutoCreate: true,
      );
    } on DesktopLinkFailure {
      rethrow;
    } catch (e) {
      DiagLog.event('desktop_link', 'keys_setup_failed', {
        'err': _shortErrorTag(e),
      });
      throw DesktopLinkFailure(
        DesktopLinkFailureCode.keysPublishRejected,
        cause: e,
      );
    }
    DiagLog.event('desktop_link', 'step', {'after': 'keys_setup'});
    await _persistServerBindingIfMissing(prefs);
    DiagLog.event('desktop_link', 'step', {'after': 'server_binding'});

    final pid = (_profileId ?? '').trim();
    final did = (_deviceId ?? '').trim();
    if (pid.isEmpty || did.isEmpty || pid.startsWith('LOCAL-')) {
      DiagLog.event('desktop_link', 'target_ready_fail', {
        'code': 'identity_not_server_backed',
        'pid_empty': pid.isEmpty,
        'did_empty': did.isEmpty,
        'pid_local': pid.startsWith('LOCAL-'),
      });
      throw DesktopLinkFailure(
        DesktopLinkFailureCode.targetIdentityNotServerBacked,
      );
    }

    var exists = false;
    try {
      exists = await keys.profileExists(pid);
    } catch (_) {
      exists = false;
    }
    DiagLog.event('desktop_link', 'step', {
      'after': 'profile_exists',
      'exists': exists,
    });
    if (!exists) {
      await _ensureKeysSetup(
        prefs: prefs,
        keys: keys,
        allowServerProfileAutoCreate: true,
        allowMissingCurrentDeviceRepair: true,
      );
      exists = await keys.profileExists((_profileId ?? '').trim());
      if (!exists) {
        DiagLog.event('desktop_link', 'target_ready_fail', {
          'code': 'profile_unavailable',
          'pid': DiagLog.pfx(_profileId),
        });
        throw DesktopLinkFailure(
          DesktopLinkFailureCode.targetProfileUnavailable,
          message:
              'Desktop profile is not registered on server yet. Please retry in a moment.',
        );
      }
    }

    var deviceIds = <String>[];
    try {
      deviceIds = await _listDevicesAuthed(pid);
    } catch (_) {
      deviceIds = const <String>[];
    }
    DiagLog.event('desktop_link', 'step', {
      'after': 'list_devices',
      'count': deviceIds.length,
      'has_self': deviceIds.contains(did),
    });
    if (!deviceIds.contains(did)) {
      await _ensureKeysSetup(
        prefs: prefs,
        keys: keys,
        allowServerProfileAutoCreate: true,
        allowMissingCurrentDeviceRepair: true,
      );
      deviceIds = await _listDevicesAuthed((_profileId ?? '').trim());
      if (!deviceIds.contains(did)) {
        DiagLog.event('desktop_link', 'target_ready_fail', {
          'code': 'device_unavailable',
          'self_dev': DiagLog.pfx(_deviceId),
          'server_devices': deviceIds.length,
        });
        throw DesktopLinkFailure(
          DesktopLinkFailureCode.targetDeviceUnavailable,
          message:
              'Desktop device is not visible on server yet. Keep desktop online and retry.',
        );
      }
    }

    DiagLog.event('desktop_link', 'target_ready_ok', {
      'self_dev': DiagLog.pfx(_deviceId),
    });
    _keysOnline = true;

    await _rebindRelayRuntimeForCurrentIdentity(prefs: prefs);
  }

  Future<void> _rebindRelayRuntimeForCurrentIdentity({
    required SharedPreferences prefs,
  }) async {
    if (_transportBlocked) return;
    final db = _db;
    final did = (_deviceId ?? '').trim();
    final pid = (_profileId ?? '').trim();
    if (db == null || did.isEmpty || pid.isEmpty || pid.startsWith('LOCAL-')) {
      return;
    }

    final currentRelay = _relay;
    final alreadyBound =
        currentRelay != null &&
        currentRelay.deviceId == did &&
        currentRelay.selfProfileId == pid;
    if (alreadyBound) return;

    try {
      await currentRelay?.close();
    } catch (_) {
      // ignore
    }
    _blob?.close();
    _stickerCatalogClient?.close();

    // BACKGROUND DRAIN (2026-07-16): snapshot the RESOLVED relay HTTP base
    // (incl. per-profile server-binding overrides) for the FCM background
    // fetcher, which runs in a separate isolate without this resolution logic.
    unawaited(
      prefs.setString(
        BackgroundInboxFetcher.prefsBaseUrlKey,
        relayHttpBaseUrl.toString(),
      ),
    );
    unawaited(
      prefs.setString(
        BackgroundInboxFetcher.prefsKeysBaseUrlKey,
        keysBaseUrl.toString(),
      ),
    );
    // iOS NSE (2026-07-17): mirror identity/config on bind too, so the NSE can
    // pre-fetch even before the first resume.
    unawaited(_syncNseConfig());
    late final RelayClient relay;
    relay = RelayClient(
      db: db,
      deviceId: did,
      selfProfileId: pid,
      deviceKeys: DeviceKeys.create(),
      clientBuild: AppPackageInfo.buildNumberFromEnv,
      wsUrl: relayWsUrl,
      httpBaseUrl: relayHttpBaseUrl,
      onConnectionChanged: (connected) =>
          _handleRelayConnectionChanged(relay, connected),
      // Только перерисовка: экран чата решает по этому признаку, показывать
      // «Загружаем сообщения…» или «переписки нет».
      onFirstDrainCompleted: () {
        if (!_changed.isClosed) _changed.add(null);
      },
      onServerError: (code, message) {
        _onRelayServerError(code: code, message: message);
      },
      onDelivered: _handleDelivered,
      loadNextSeq: () async => prefs.getInt(_prefsRelayNextSeqKey) ?? 1,
      saveNextSeq: (v) async => prefs.setInt(_prefsRelayNextSeqKey, v),
    );
    relay.readyAtMsProvider = () => _startupReadyAtMs;
    _relay = relay;
    relay.onUnknownDevice = _onRelaySaysUnknownDevice;
    relay.onDeviceAccepted = _onRelayAcceptedOwnDevice;
    _kickRelayOutbox(relay);

    _blob = BlobClient(
      baseUrl: relayHttpBaseUrl,
      deviceId: _deviceId,
      selfProfileId: _profileId,
      deviceKeys: DeviceKeys.create(),
    );
    _stickerCatalogClient = StickerCatalogClient(baseUrl: relayHttpBaseUrl);
    // Point the premium-cosmetics catalog (icons + wallpapers) at the relay so
    // server wallpapers render app-wide without needing a picker to be opened.
    CosmeticsCatalogService.instance.configure(relayHttpBaseUrl);
    _attachments = AttachmentService(blobClient: _blob!);

    // Sprint 2 PR8 (2026-05-19): also rebuild ratchet managers here.
    //
    // Before this, ratchet was only created inside the
    // `if (_canStartAuthenticatedRuntime)` block of init() — which is gated
    // on `desktop_auth_required == false`. During QR pairing the gate is
    // still on, so `_ratchetV1 == null` and `_ratchetV3 == null`. Mobile
    // ships the sync bundle as a `RatchetWireV3.prekey` (X3DH initial), and
    // `_handleDelivered` skips both ratchet branches because they are null,
    // falling through to the symmetric `crypto.decrypt(bytes)` legacy path.
    // That key was never used by mobile, so every inbound bundle dies with
    // `SecretBoxAuthenticationError (MAC mismatch)`, relay ACKs and drops,
    // and the desktop is permanently stuck on the QR screen.
    //
    // Initialising ratchet here is safe: the underlying state lives in the
    // encrypted SQLite DB keyed by (selfProfileId, selfDeviceId, peerDid).
    // After `_applyDesktopSyncBundle` mints the final device_id, the bundle
    // applier rebinds the runtime again and a fresh ratchet pair takes
    // over; nothing in the temp identity's sessions can leak to the real
    // identity.
    final keys = _keys;
    if (keys != null) {
      final ratchetAlreadyBound = _ratchetV3 != null && _ratchetV1 != null;
      if (!ratchetAlreadyBound) {
        _ratchetV1 = RatchetSessionManagerV1(
          db: db,
          deviceKeys: DeviceKeys.create(),
          keysClient: keys,
          fetchBundleAuthed: _fetchBundleAuthed,
        );
        _ratchetV3 = RatchetSessionManagerV3(
          db: db,
          deviceKeys: DeviceKeys.create(),
          keysClient: keys,
          fetchBundleAuthed: _fetchBundleAuthed,
        );
      }
    }

    try {
      await relay.connect();
      _relayOnline = true;
      _relayHttpReachable = true; // WS up => relay reachable (clear the banner)
      await _syncPushTokenBestEffort();
      unawaited(_syncVoipTokenBestEffort());
      unawaited(_syncStickerCatalog(force: true));
    } catch (_) {
      _relayOnline = false;
    }
  }

  Future<DesktopLinkRequest> createDesktopLinkRequest({
    String? deviceLabel,
  }) async {
    final prefs = _prefs ?? await SharedPreferences.getInstance();
    _prefs = prefs;
    await _setDesktopAuthRequired(prefs, true);
    _setAuthFlowState(AuthFlowState.qrSessionPending);
    try {
      await _ensureDesktopLinkTargetReady(prefs: prefs);
    } catch (e) {
      final failure = e is DesktopLinkFailure ? e : null;
      _setAuthFlowState(
        AuthFlowState.authError,
        error: failure == null ? e.toString() : null,
        failure: failure,
      );
      _changed.add(null);
      if (failure != null) {
        throw failure;
      }
      rethrow;
    }
    _loadDesktopLinkRequestsFromPrefs(prefs);

    final now = DateTime.now().millisecondsSinceEpoch;
    final pid = (_profileId ?? '').trim();
    final did = (_deviceId ?? '').trim();
    if (pid.isEmpty || did.isEmpty || pid.startsWith('LOCAL-')) {
      throw StateError('state not ready');
    }

    final request = DesktopLinkRequest(
      requestId: _uuid.v4().replaceAll('-', ''),
      targetProfileId: pid,
      targetDeviceId: did,
      requestNonce: _uuid.v4().replaceAll('-', ''),
      deviceLabel: (deviceLabel ?? 'Desktop/Web').trim().isEmpty
          ? 'Desktop/Web'
          : (deviceLabel ?? 'Desktop/Web').trim(),
      createdAtMs: now,
      expiresAtMs: now + _desktopLinkRequestTtlMs,
      status: 'pending',
    );

    _desktopLinkRequests = prepareDesktopLinkRequestsForNewRequest(
      existingRequests: _desktopLinkRequests,
      request: request,
    );
    await _saveDesktopLinkRequestsToPrefs();

    _changed.add(null);
    return request;
  }

  Future<bool> expireDesktopLinkRequestsIfNeeded() async {
    final result = DesktopLinkStateMachine.expireRequests(
      requests: _desktopLinkRequests,
      nowMs: DateTime.now().millisecondsSinceEpoch,
      authFlowState: _authFlowState,
      authFlowError: _authFlowError,
      authFlowFailure: _authFlowFailure,
    );
    if (!result.didExpire) return false;

    _desktopLinkRequests = result.requests;
    await _saveDesktopLinkRequestsToPrefs();

    if (result.authFlowState != _authFlowState ||
        result.authFlowError != authFlowError ||
        result.authFlowFailure?.code != _authFlowFailure?.code) {
      _setAuthFlowState(
        result.authFlowState,
        error: result.authFlowError,
        failure: result.authFlowFailure,
      );
    }

    _changed.add(null);
    return true;
  }

  String buildDesktopLinkQrPayload(DesktopLinkRequest request) {
    return [
      'type=$desktopLinkQrType',
      'request_id=${request.requestId}',
      'target_profile_id=${request.targetProfileId}',
      'target_device_id=${request.targetDeviceId}',
      'request_nonce=${request.requestNonce}',
      'device_label=${request.deviceLabel}',
      'issued_at_ms=${request.createdAtMs}',
      'expires_at_ms=${request.expiresAtMs}',
      'keys_base_url=$keysBaseUrl',
      'server_binding=${_environmentServerBindingString()}',
    ].join('\n');
  }

  Future<bool> _setDesktopLinkRequestStatus(
    String requestId,
    String status,
  ) async {
    final result = DesktopLinkStateMachine.updateRequestStatus(
      requests: _desktopLinkRequests,
      requestId: requestId,
      status: status,
    );
    if (!result.didUpdate) return false;
    _desktopLinkRequests = result.requests;
    await _saveDesktopLinkRequestsToPrefs();
    return true;
  }

  Future<void> cancelDesktopLinkRequest(String requestId) async {
    final updated = await _setDesktopLinkRequestStatus(requestId, 'cancelled');
    if (!updated) return;
    if (requiresDesktopProfileSelection) {
      _setAuthFlowState(AuthFlowState.unauthenticated);
    }
    _changed.add(null);
  }

  Future<void> rejectDesktopLinkRequest(String requestId) async {
    final updated = await _setDesktopLinkRequestStatus(requestId, 'rejected');
    if (!updated) return;
    if (requiresDesktopProfileSelection) {
      _setAuthFlowState(AuthFlowState.unauthenticated);
    }
    _changed.add(null);
  }

  Future<void> _sendDesktopLinkAttachmentPayload({
    required String targetProfileId,
    required String targetDeviceId,
    required Uint8List bytes,
    required String mime,
    required String profileUnavailableMessage,
    required String deviceUnavailableMessage,
  }) async {
    // Sprint 2 hotfix (2026-05-19): pass the explicit desktop device id so
    // `sendAttachment` skips its "send-to-self → save locally only" short
    // circuit. Without this the encrypted sync/decision bundle silently lands
    // in the phone's local DB and never reaches the desktop. Symptom: green
    // «Синхронизация отправлена» snackbar on the phone + zero `ws send` on
    // relay + desktop QR screen hangs forever.
    final explicitTargets = <String>[targetDeviceId];
    DiagLog.event('qr_pair', 'send_attach_start', {
      'target_pid': DiagLog.pfx(targetProfileId),
      'target_did': DiagLog.pfx(targetDeviceId),
      'bytes': bytes.length,
      'mime': mime,
    });
    try {
      await sendAttachment(
        peerProfileId: targetProfileId,
        bytes: bytes,
        mime: mime,
        includeInLocalHistory: false,
        targetDeviceIds: explicitTargets,
      );
      DiagLog.event('qr_pair', 'send_attach_done', {
        'target_pid': DiagLog.pfx(targetProfileId),
        'target_did': DiagLog.pfx(targetDeviceId),
      });
    } catch (e) {
      DiagLog.event('qr_pair', 'send_attach_fail', {
        'target_pid': DiagLog.pfx(targetProfileId),
        'target_did': DiagLog.pfx(targetDeviceId),
        'err': e.runtimeType.toString(),
        'msg': e.toString(),
      });
      final msg = e.toString().toLowerCase();
      final recipientMissing =
          msg.contains('recipient profile not found on server') ||
          msg.contains('peer_profile_id=');
      final noDevicesYet =
          msg.contains('no registered devices yet') ||
          msg.contains('no deliverable target devices');
      if (!recipientMissing && !noDevicesYet) rethrow;

      if (recipientMissing) {
        final becameVisible = await _waitForProfileExistsOnServer(
          targetProfileId,
        );
        if (!becameVisible) {
          throw DesktopLinkFailure(
            DesktopLinkFailureCode.targetProfileUnavailable,
            message: profileUnavailableMessage,
          );
        }
      }

      if (noDevicesYet) {
        final becameVisible = await _waitForDeviceVisibleOnServer(
          targetProfileId,
          targetDeviceId,
        );
        if (!becameVisible) {
          throw DesktopLinkFailure(
            DesktopLinkFailureCode.targetDeviceUnavailable,
            message: deviceUnavailableMessage,
          );
        }
      }

      await sendAttachment(
        peerProfileId: targetProfileId,
        bytes: bytes,
        mime: mime,
        includeInLocalHistory: false,
        targetDeviceIds: explicitTargets,
      );
    }
  }

  Future<void> rejectDesktopLinkFromQr({required String rawPayload}) async {
    final payload = DesktopLinkQrPayload.tryParse(rawPayload);
    if (payload == null) {
      throw DesktopLinkFailure(DesktopLinkFailureCode.invalidQrPayload);
    }

    final now = DateTime.now().millisecondsSinceEpoch;
    if (payload.isExpiredAt(now)) {
      throw DesktopLinkFailure(DesktopLinkFailureCode.qrExpired);
    }

    if (payload.serverBinding.isNotEmpty &&
        payload.serverBinding != _environmentServerBindingString()) {
      throw DesktopLinkFailure(DesktopLinkFailureCode.serverBindingMismatch);
    }

    final decision = <String, Object?>{
      'v': 1,
      'type': 'desktop_link_decision_v1',
      'request_id': payload.requestId,
      'request_nonce': payload.requestNonce,
      'target_profile_id': payload.targetProfileId,
      'target_device_id': payload.targetDeviceId,
      'decision': 'rejected',
      'reason': 'declined_by_primary',
      'decided_at_ms': now,
      'source_profile_id': (_profileId ?? '').trim(),
      'source_device_id': (_deviceId ?? '').trim(),
    };

    await _sendDesktopLinkAttachmentPayload(
      targetProfileId: payload.targetProfileId,
      targetDeviceId: payload.targetDeviceId,
      bytes: Uint8List.fromList(utf8.encode(jsonEncode(decision))),
      mime: desktopLinkDecisionAttachmentMime,
      profileUnavailableMessage:
          'Desktop profile is still not visible on server. Keep desktop app online and retry.',
      deviceUnavailableMessage:
          'Desktop device is still not visible on server. Regenerate QR and retry.',
    );
  }

  Future<void> approveDesktopLinkFromQr({
    required String rawPayload,
    required bool syncChats,
    required bool syncSettings,
    required bool syncMedia,
  }) async {
    DiagLog.event('qr_pair', 'approve_enter', {
      'raw_len': rawPayload.length,
      'sync_chats': syncChats,
      'sync_settings': syncSettings,
      'sync_media': syncMedia,
    });
    final payload = DesktopLinkQrPayload.tryParse(rawPayload);
    DiagLog.event('qr_pair', 'approve_parsed', {
      'ok': payload != null,
      'target_pid': DiagLog.pfx(payload?.targetProfileId),
      'target_did': DiagLog.pfx(payload?.targetDeviceId),
      'request_id': DiagLog.pfx(payload?.requestId),
      'server_binding_len': payload?.serverBinding.length ?? 0,
    });
    if (payload == null) {
      throw DesktopLinkFailure(DesktopLinkFailureCode.invalidQrPayload);
    }

    final requestId = payload.requestId;
    final targetProfileId = payload.targetProfileId;
    final targetDeviceId = payload.targetDeviceId;
    final requestNonce = payload.requestNonce;
    if (payload.isExpiredAt(DateTime.now().millisecondsSinceEpoch)) {
      DiagLog.event('qr_pair', 'approve_expired');
      throw DesktopLinkFailure(DesktopLinkFailureCode.qrExpired);
    }

    if (payload.serverBinding.isNotEmpty &&
        payload.serverBinding != _environmentServerBindingString()) {
      DiagLog.event('qr_pair', 'approve_server_binding_mismatch', {
        'qr_binding_len': payload.serverBinding.length,
      });
      throw DesktopLinkFailure(DesktopLinkFailureCode.serverBindingMismatch);
    }

    final keys = _keys ?? KeysClient(baseUrl: keysBaseUrl);
    _keys = keys;
    var targetExists = false;
    try {
      targetExists = await keys.profileExists(targetProfileId);
    } catch (e) {
      DiagLog.event('qr_pair', 'profile_exists_throw', {
        'err': e.runtimeType.toString(),
        'msg': e.toString(),
      });
      targetExists = false;
    }
    DiagLog.event('qr_pair', 'profile_exists_check', {'exists': targetExists});
    if (!targetExists) {
      targetExists = await _waitForProfileExistsOnServer(targetProfileId);
      DiagLog.event('qr_pair', 'profile_exists_wait', {'exists': targetExists});
    }
    if (!targetExists) {
      throw DesktopLinkFailure(
        DesktopLinkFailureCode.targetProfileUnavailable,
        message:
            'Desktop profile is not visible on server yet. Keep desktop app open and retry in a few seconds.',
      );
    }

    var targetDeviceVisible = false;
    try {
      final devices = await _listDevicesAuthed(targetProfileId);
      targetDeviceVisible = devices.contains(targetDeviceId);
      DiagLog.event('qr_pair', 'device_list', {
        'count': devices.length,
        'has_target': targetDeviceVisible,
      });
    } catch (e) {
      DiagLog.event('qr_pair', 'device_list_throw', {
        'err': e.runtimeType.toString(),
        'msg': e.toString(),
      });
      targetDeviceVisible = false;
    }
    if (!targetDeviceVisible) {
      targetDeviceVisible = await _waitForDeviceVisibleOnServer(
        targetProfileId,
        targetDeviceId,
      );
      DiagLog.event('qr_pair', 'device_wait', {'visible': targetDeviceVisible});
    }
    if (!targetDeviceVisible) {
      throw DesktopLinkFailure(
        DesktopLinkFailureCode.targetDeviceUnavailable,
        message:
            'Desktop device is not registered on server yet. Keep desktop app open and regenerate QR.',
      );
    }

    DiagLog.event('qr_pair', 'collect_backup_start', {
      'with_media': syncChats && syncMedia,
    });
    final plain = await _collectSafeBackupPlain(
      includeBinaryFiles: syncChats && syncMedia,
    );
    DiagLog.event('qr_pair', 'collect_backup_done', {
      'pid': DiagLog.pfx(plain.profileId),
      'has_db_snapshot': plain.dbSnapshot != null,
      'contacts': plain.contacts.length,
    });
    final cryptoKeyB64 = base64Encode(
      await SecureSecrets.create().requireExistingCryptoKey(),
    );
    final now = DateTime.now().millisecondsSinceEpoch;

    // Mobile's own _deviceId. Shipped so the desktop can seed its
    // `_knownOwnDeviceIds` set at apply time without waiting for the
    // keys-server refresh race. See docs/BUG_AUDIT.md §2026-05-19 ADDENDUM
    // and docs/FIX_TZ.md §2026-05-19 Bidirectional PC↔phone sync fix.
    //
    // Empty string is allowed for back-compat — older desktop builds will
    // ignore the unknown field. Empty here means we couldn't read our own
    // device id (degenerate case; the existing boot-time refresh still
    // converges within a few seconds).
    final senderDeviceId = (_deviceId ?? '').trim();

    final bundle = <String, Object?>{
      'v': 1,
      'type': 'desktop_sync_bundle_v1',
      'request_id': requestId,
      'request_nonce': requestNonce,
      'target_profile_id': targetProfileId,
      'target_device_id': targetDeviceId,
      'sender_device_id': senderDeviceId,
      'approved_at_ms': now,
      'profile_id': plain.profileId,
      'profile_secret_b64': plain.profileSecretB64,
      'crypto_key_b64': cryptoKeyB64,
      'server_binding': plain.serverBinding,
      'sync_chats': syncChats,
      'sync_settings': syncSettings,
      'sync_media': syncChats && syncMedia,
      if (syncSettings)
        'settings': {
          'dark_mode': plain.darkMode,
          'block_unverified': plain.blockUnverified,
          'share_nickname_in_qr': plain.shareNicknameInQr,
          'my_nickname': plain.myNickname,
          'profile_gallery_paths': plain.profileGalleryPaths,
          'profile_background_paths': plain.profileBackgroundPaths,
          'profile_music_paths': plain.profileMusicPaths,
        },
      if (syncChats)
        'pending_import': {
          'contacts': plain.contacts
              .map((c) => c.toJson())
              .toList(growable: false),
          'blocked_profiles': plain.blockedProfiles,
          if (plain.dbSnapshot != null) 'db_snapshot': plain.dbSnapshot,
        },
      if (syncChats && syncMedia && plain.filesB64ByRelativePath != null)
        'files_b64_by_relative_path': plain.filesB64ByRelativePath,
    };

    final bytes = Uint8List.fromList(utf8.encode(jsonEncode(bundle)));
    await _sendDesktopLinkAttachmentPayload(
      targetProfileId: targetProfileId,
      targetDeviceId: targetDeviceId,
      bytes: bytes,
      mime: desktopSyncAttachmentMime,
      profileUnavailableMessage:
          'Desktop profile is still not visible on server. Keep desktop app online and retry.',
      deviceUnavailableMessage:
          'Desktop device is still not visible on server. Regenerate QR and retry.',
    );

    // 2026-05-19 — close the post-pairing self-fanout gap on the mobile side.
    // The desktop will generate a new device id after applying this bundle
    // and re-register with the keys server. Refresh our own-device knowledge
    // a few times with backoff so subsequent self-mirror commands include the
    // freshly-paired desktop without waiting for the 3-minute recipient-cache
    // TTL to expire. See docs/FIX_TZ.md §2026-05-19 step 4.
    unawaited(_schedulePostPairingOwnDeviceRefresh().catchError((_) {}));
  }

  Future<bool> _maybeHandleDesktopLinkDecisionAttachment({
    required AttachmentEventV1 attachment,
  }) async {
    if ((attachment.mime ?? '').toLowerCase() !=
        desktopLinkDecisionAttachmentMime) {
      return false;
    }

    final myPid = (_profileId ?? '').trim();
    final myDid = (_deviceId ?? '').trim();
    if (myPid.isEmpty || myDid.isEmpty) return false;

    final rawBytes = await downloadAndDecryptAttachment(attachment);
    final raw = utf8.decode(rawBytes, allowMalformed: false);
    final decoded = jsonDecode(raw);
    if (decoded is! Map) return false;
    final json = decoded.map((k, v) => MapEntry(k.toString(), v));
    final reqId = (json['request_id'] as String?)?.trim() ?? '';
    final reqNonce = (json['request_nonce'] as String?)?.trim() ?? '';
    final targetProfileId =
        (json['target_profile_id'] as String?)?.trim() ?? '';
    final targetDeviceId = (json['target_device_id'] as String?)?.trim() ?? '';
    final decision = (json['decision'] as String?)?.trim().toLowerCase() ?? '';
    final resolution = resolveDesktopLinkDecision(
      requests: _desktopLinkRequests,
      requestId: reqId,
      requestNonce: reqNonce,
      controllerProfileId: myPid,
      controllerDeviceId: myDid,
      targetProfileId: targetProfileId,
      targetDeviceId: targetDeviceId,
      decision: decision,
    );
    if (!resolution.isHandled) {
      return false;
    }

    _desktopLinkRequests[resolution.requestIndex!] =
        resolution.replacementRequest!;
    await _saveDesktopLinkRequestsToPrefs();
    _setAuthFlowState(
      AuthFlowState.authError,
      error: resolution.error,
      failure: resolution.failure,
    );
    _changed.add(null);
    return true;
  }

  Future<bool> _maybeHandleDesktopSyncAttachment({
    required AttachmentEventV1 attachment,
  }) async {
    if ((attachment.mime ?? '').toLowerCase() != desktopSyncAttachmentMime) {
      return false;
    }
    callLog('AppCtrl', 'DesktopSync: mime match, entering apply path');
    final myPid = (_profileId ?? '').trim();
    final myDid = (_deviceId ?? '').trim();
    if (myPid.isEmpty || myDid.isEmpty) {
      callLog(
        'AppCtrl',
        'DesktopSync: pid/did empty (pid=$myPid did=$myDid), bailing',
      );
      return false;
    }

    callLog('AppCtrl', 'DesktopSync: downloading blob…');
    final rawBytes = await downloadAndDecryptAttachment(attachment);
    callLog('AppCtrl', 'DesktopSync: blob decoded, bytes=${rawBytes.length}');
    final raw = utf8.decode(rawBytes, allowMalformed: false);
    final payload = DesktopLinkSyncPayload.tryParseDecoded(jsonDecode(raw));
    callLog(
      'AppCtrl',
      'DesktopSync: payload parsed, null=${payload == null} '
          'requestId=${payload?.requestId} '
          'parseError=${DesktopLinkSyncPayload.lastParseError ?? '-'}',
    );
    // Sprint 2 PR8 (2026-05-19): mirror to DiagLog so the reason survives
    // even when callLog's native MethodChannel is missing (macOS desktop).
    DiagLog.event('qr_pair', 'desktop_sync_parsed', {
      'null': payload == null,
      'request_id_pfx': DiagLog.pfx(payload?.requestId),
      'parse_error': DesktopLinkSyncPayload.lastParseError ?? '-',
      'raw_bytes': rawBytes.length,
    });
    final preparation = DesktopLinkStateMachine.prepareSyncApply(
      requests: _desktopLinkRequests,
      controllerProfileId: myPid,
      controllerDeviceId: myDid,
      nowMs: DateTime.now().millisecondsSinceEpoch,
      payload: payload,
    );
    callLog(
      'AppCtrl',
      'DesktopSync: prepareSyncApply canApply=${preparation.canApply} didMutate=${preparation.didMutateRequests} failure=${preparation.failure}',
    );
    if (preparation.didMutateRequests) {
      _desktopLinkRequests = preparation.requests;
      await _saveDesktopLinkRequestsToPrefs();
    }
    if (!preparation.canApply) {
      _setAuthFlowState(
        AuthFlowState.authError,
        error: preparation.error,
        failure: preparation.failure,
      );
      _changed.add(null);
      return false;
    }

    _setAuthFlowState(AuthFlowState.qrScannedWaitConfirm);
    _changed.add(null);
    _setAuthFlowState(AuthFlowState.bundleApplying);
    _changed.add(null);

    final syncPayload = preparation.payload!;
    final prefs = _prefs ?? await SharedPreferences.getInstance();
    _prefs = prefs;
    try {
      await _applyDesktopSyncBundle(prefs: prefs, payload: syncPayload);
      return true;
    } catch (e) {
      final interrupted = DesktopLinkStateMachine.updateRequestStatus(
        requests: _desktopLinkRequests,
        requestId: syncPayload.requestId,
        status: 'interrupted',
      );
      if (interrupted.didUpdate) {
        _desktopLinkRequests = interrupted.requests;
        await _saveDesktopLinkRequestsToPrefs();
      }
      _setAuthFlowState(
        AuthFlowState.authError,
        failure: DesktopLinkFailure(DesktopLinkFailureCode.syncInterrupted),
      );
      _changed.add(null);
      rethrow;
    }
  }

  static bool _isDesktopLinkControlAttachmentMime(String? mime) {
    final normalized = (mime ?? '').trim().toLowerCase();
    return normalized == desktopLinkDecisionAttachmentMime ||
        normalized == desktopSyncAttachmentMime;
  }

  @visibleForTesting
  Future<bool> handleInboundAttachmentCommands(
    Iterable<AttachmentEventV1> attachments,
  ) async {
    var handledCommand = false;
    var sawControlAttachment = false;
    for (final att in attachments) {
      final isCtrl = _isDesktopLinkControlAttachmentMime(att.mime);
      if (isCtrl) {
        sawControlAttachment = true;
        // Sprint 2 PR8 (2026-05-19): surface what mime arrived so we can tell
        // decision-vs-sync attachments apart from a single inbox event log.
        callLog(
          'AppCtrl',
          'handleInboundAttachmentCommands: control mime='
              '${att.mime ?? 'null'} eventId=${att.eventId}',
        );
      }
      try {
        var handled = await _maybeHandleDesktopLinkDecisionAttachment(
          attachment: att,
        );
        handled =
            handled || await _maybeHandleDesktopSyncAttachment(attachment: att);
        if (handled) {
          handledCommand = true;
        }
      } catch (e, st) {
        // Sprint 2 PR8 (2026-05-19): never swallow silently. Used to be
        // `catch (_) {}` which hid every desktop-link apply failure (blob
        // 404, decryption error, etc.) and left the user stuck on the QR
        // screen with no diagnostic trail.
        callLog(
          'AppCtrl',
          'handleInboundAttachmentCommands threw for mime='
              '${att.mime ?? 'null'} eventId=${att.eventId}: $e',
        );
        callLog('AppCtrl', '$st');
      }
    }
    return handledCommand || sawControlAttachment;
  }

  Future<void> _applyDesktopSyncBundle({
    required SharedPreferences prefs,
    required DesktopLinkSyncPayload payload,
  }) async {
    final oldProfileId = _profileId;
    final oldDeviceId = _deviceId;

    final result = await _buildDesktopLinkSyncBundleApplier().apply(
      prefs: prefs,
      prefsKeys: _desktopLinkSyncApplyPrefsKeys,
      payload: payload,
      desktopLinkRequests: _desktopLinkRequests,
      newDesktopDeviceId: _uuid.v4(),
      oldProfileId: oldProfileId,
      oldDeviceId: oldDeviceId,
    );
    _desktopLinkRequests = result.desktopLinkRequests;
    await _saveDesktopLinkRequestsToPrefs();

    await _setDesktopAuthRequired(prefs, false);
    _setAuthFlowState(AuthFlowState.authenticated);
    // Seed `_knownOwnDeviceIds` with BOTH this new desktop's device id AND
    // the mobile sender's device id (if shipped in the QR bundle). This
    // closes the receive-gate race documented in
    // docs/BUG_AUDIT.md §2026-05-19 ADDENDUM cause A — the desktop accepts
    // mobile's self-mirror commands from the first millisecond after pairing
    // without waiting for `_refreshKnownOwnDeviceIdsFromServer`.
    final senderDid = payload.senderDeviceId.trim();
    final seededOwnDeviceIds = <String>[
      result.newDesktopDeviceId,
      if (senderDid.isNotEmpty) senderDid,
    ];
    _applyRuntimeResetResult(
      AppRuntimeLifecycleCoordinator.restartReset(
        desktopLinkRequests: _desktopLinkRequests,
        cancelAwaitingDesktopLinkRequests: false,
        nextDeviceId: result.newDesktopDeviceId,
        knownOwnDeviceIds: seededOwnDeviceIds,
      ),
    );

    _changed.add(null);
    _restartRequested.add(null);
  }

  DesktopLinkSyncBundleApplier _buildDesktopLinkSyncBundleApplier() {
    return DesktopLinkSyncBundleApplier(
      prepareRuntimeForSyncApply: () async {
        _pumpTimer?.cancel();
        _mainAliveHeartbeatTimer?.cancel();
    _mainAliveHeartbeatTimer?.cancel();
        _pumpTimer = null;
        _serviceWatchdogTimer?.cancel();
        _serviceWatchdogTimer = null;
        _quarantineRecoverySweepTimer?.cancel();
        _quarantineRecoverySweepTimer = null;

        await _closeRuntimeNetworkClientsForDiscard();

        try {
          await _db?.close();
        } catch (_) {}
        _db = null;
      },
      deleteLocalDatabaseFiles: AppDb.deleteLocalDatabaseFiles,
      decodeSafeBackupFiles: _decodeSafeBackupFiles,
      restoreSafeBackupFiles: _restoreSafeBackupFilesToDocuments,
      applyPendingImport: _tryApplyPendingSafeImportPayload,
      setProfileSecret: ({required profileId, required secretB64}) {
        return SecureSecrets.create().setProfileSecretB64(
          profileId: profileId,
          secretB64: secretB64,
        );
      },
      setCryptoKey: (cryptoKeyB64) {
        return SecureSecrets.create().setCryptoKeyB64(cryptoKeyB64);
      },
      deleteProfileSecret: (profileId) {
        return SecureSecrets.create().deleteProfileSecret(profileId);
      },
      deleteDeviceRegistration:
          ({required profileId, required deviceId, String? profileSecretB64}) {
            return _deleteDeviceRegistrationFromServer(
              profileId: profileId,
              deviceId: deviceId,
              profileSecretB64: profileSecretB64,
            );
          },
      deleteDeviceMaterial: ({required profileId, required deviceId}) {
        return DeviceKeys.create().deleteMaterial(
          profileId: profileId,
          deviceId: deviceId,
        );
      },
    );
  }

  Future<bool> _tryApplyPendingSafeImportPayload(
    Map<String, dynamic> pendingImport,
  ) async {
    try {
      final dbPass = await SecureSecrets.create().requireExistingDbPassphrase();
      final importDb = await AppDb.open(passphrase: dbPass);
      try {
        await _applyPendingSafeImportPayload(db: importDb, json: pendingImport);
        return true;
      } finally {
        await importDb.close();
      }
    } catch (_) {
      return false;
    }
  }

  Future<void> _rememberRestoredOwnDeviceIdsInDb({
    required String profileId,
    required Iterable<String> deviceIds,
  }) async {
    final pid = profileId.trim();
    final ids = deviceIds
        .map((deviceId) => deviceId.trim())
        .where((deviceId) => deviceId.isNotEmpty)
        .toSet();
    if (pid.isEmpty || ids.isEmpty) return;

    try {
      final dbPass = await SecureSecrets.create().requireExistingDbPassphrase();
      final db = await AppDb.open(passphrase: dbPass);
      try {
        for (final deviceId in ids) {
          await db.deviceProfileUpsert(deviceId: deviceId, profileId: pid);
        }
      } finally {
        await db.close();
      }
    } catch (_) {
      // The next runtime init also refreshes own device ids from the server.
    }
  }

  void _loadDesktopLinkRequestsFromPrefs(SharedPreferences prefs) {
    final raw = prefs.getString(_prefsDesktopLinkRequestsKey);
    if (raw == null || raw.trim().isEmpty) {
      _desktopLinkRequests = const <DesktopLinkRequest>[];
      return;
    }
    try {
      final decoded = jsonDecode(raw);
      if (decoded is! List) {
        _desktopLinkRequests = const <DesktopLinkRequest>[];
        return;
      }
      final now = DateTime.now().millisecondsSinceEpoch;
      _desktopLinkRequests = decoded
          .map(DesktopLinkRequest.fromJson)
          .whereType<DesktopLinkRequest>()
          .where((r) => r.expiresAtMs > now)
          .toList(growable: true);
    } catch (_) {
      _desktopLinkRequests = const <DesktopLinkRequest>[];
    }
  }

  Future<void> _saveDesktopLinkRequestsToPrefs() async {
    final prefs = _prefs ?? await SharedPreferences.getInstance();
    _prefs = prefs;
    final now = DateTime.now().millisecondsSinceEpoch;
    _desktopLinkRequests = _desktopLinkRequests
        .where((r) => r.expiresAtMs > now)
        .toList(growable: true);
    await prefs.setString(
      _prefsDesktopLinkRequestsKey,
      jsonEncode(
        _desktopLinkRequests.map((e) => e.toJson()).toList(growable: false),
      ),
    );
  }

  _ServerBindingEndpoints? _parseServerBinding(String? value) {
    final raw = (value ?? '').trim();
    if (raw.isEmpty) return null;
    final parts = raw.split(';');
    String? keysRaw;
    String? relayRaw;
    for (final part in parts) {
      final p = part.trim();
      if (p.startsWith('keys=')) {
        keysRaw = p.substring('keys='.length).trim();
      } else if (p.startsWith('relay=')) {
        relayRaw = p.substring('relay='.length).trim();
      }
    }
    if (keysRaw == null ||
        keysRaw.isEmpty ||
        relayRaw == null ||
        relayRaw.isEmpty) {
      return null;
    }
    try {
      return _ServerBindingEndpoints(
        keysBaseUrl: Uri.parse(keysRaw),
        relayHttpBaseUrl: Uri.parse(relayRaw),
      );
    } catch (_) {
      return null;
    }
  }

  void _throwIfTransportBlocked() {
    if (!_transportBlocked) return;
    throw StateError(_transportBlockedReason ?? 'Transport blocked by policy');
  }

  bool _hasOutgoingTransportRuntime({bool includeAttachments = false}) {
    return _db != null &&
        (_deviceId?.trim().isNotEmpty ?? false) &&
        _keys != null &&
        _ratchetV3 != null &&
        _relay != null &&
        (!includeAttachments || _attachments != null);
  }

  StateError _transportUnavailableStateError(String prefix) {
    final detail = (_startupWarning ?? _transportBlockedReason ?? '').trim();
    if (detail.isNotEmpty) {
      return StateError('$prefix: $detail');
    }
    return StateError('$prefix: transport is not ready');
  }

  @visibleForTesting
  Future<bool> ensureOutgoingTransportReady({
    bool includeAttachments = false,
  }) async {
    if (_hasOutgoingTransportRuntime(includeAttachments: includeAttachments)) {
      return true;
    }
    if (_transportBlocked) {
      return false;
    }

    final db = _db;
    final did = (_deviceId ?? '').trim();
    if (db == null || did.isEmpty) {
      return false;
    }

    final prefs = _prefs ?? await SharedPreferences.getInstance();
    _prefs = prefs;

    final keys = _keys ?? KeysClient(baseUrl: keysBaseUrl);
    _keys = keys;

    try {
      final ready =
          await _ensureKeysSetup(
            prefs: prefs,
            keys: keys,
            allowServerProfileAutoCreate: !requiresDesktopProfileSelection,
            allowMissingCurrentDeviceRepair: true,
          ).timeout(
            const Duration(seconds: 15),
            onTimeout: () =>
                throw TimeoutException('outgoing transport recovery timed out'),
          );
      if (!ready) {
        return false;
      }

      _keysOnline = true;
      _ratchetV1 ??= RatchetSessionManagerV1(
        db: db,
        deviceKeys: DeviceKeys.create(),
        keysClient: keys,
        fetchBundleAuthed: _fetchBundleAuthed,
      );
      _ratchetV3 ??= RatchetSessionManagerV3(
        db: db,
        deviceKeys: DeviceKeys.create(),
        keysClient: keys,
        fetchBundleAuthed: _fetchBundleAuthed,
      );
      await _rebindRelayRuntimeForCurrentIdentity(prefs: prefs);
    } on CurrentDeviceRelinkRequiredException catch (e) {
      if (!_isDesktopOrWebPlatform) {
        _startupWarning = e.message;
        _changed.add(null);
      }
      return false;
    } catch (e) {
      _startupWarning ??= 'Outgoing transport recovery failed: $e';
      _changed.add(null);
      return false;
    }

    final ready = _hasOutgoingTransportRuntime(
      includeAttachments: includeAttachments,
    );
    if (!ready) {
      _startupWarning ??=
          'Outgoing transport is not ready for authenticated sending.';
      _changed.add(null);
    }
    return ready;
  }

  @visibleForTesting
  Future<bool> ensureKeysSetupForTesting({
    required SharedPreferences prefs,
    required KeysClient keys,
    bool allowServerProfileAutoCreate = true,
    bool allowMissingCurrentDeviceRepair = false,
  }) {
    _prefs = prefs;
    _keys = keys;
    return _ensureKeysSetup(
      prefs: prefs,
      keys: keys,
      allowServerProfileAutoCreate: allowServerProfileAutoCreate,
      allowMissingCurrentDeviceRepair: allowMissingCurrentDeviceRepair,
    );
  }

  void _throwIfRoomMutationAuthoritativeRelayUnavailable() {
    if (_useAuthoritativeRoomRelay || _allowLocalRoomFallbackForTesting) {
      return;
    }
    final blockedReason = _transportBlockedReason?.trim();
    if (_transportBlocked) {
      throw RoomPolicyFailure(
        RoomPolicyFailureCode.transportBlocked,
        message: blockedReason?.isEmpty ?? true ? null : blockedReason,
      );
    }
    throw RoomPolicyFailure(RoomPolicyFailureCode.serviceUnavailable);
  }

  Map<String, dynamic>? _tryDecodeRelayErrorBody(String? rawBody) {
    final raw = (rawBody ?? '').trim();
    if (raw.isEmpty) return null;
    try {
      final decoded = jsonDecode(raw);
      if (decoded is Map<String, dynamic>) {
        return decoded;
      }
      if (decoded is Map) {
        return decoded.cast<String, dynamic>();
      }
    } catch (_) {
      // Ignore malformed or plain-text bodies.
    }
    return null;
  }

  ({RoomPolicyFailure failure, int? nextAllowedAtMs})
  _roomPostingFailureFromRelayHttp(RelayHttpException error) {
    final payload = _tryDecodeRelayErrorBody(error.responseBody);
    final code = ((payload?['code'] as String?) ?? '').trim();
    final retryAfterSeconds = (payload?['retry_after_seconds'] as num?)
        ?.toInt();
    final nextAllowedAtMs = (payload?['next_allowed_at_ms'] as num?)?.toInt();
    final serverMessage = ((payload?['message'] as String?) ?? '').trim();
    final failure = switch (code) {
      'not_member' => RoomPolicyFailure(
        RoomPolicyFailureCode.notMember,
        message: serverMessage.isEmpty ? null : serverMessage,
      ),
      'text_messages_disabled' => RoomPolicyFailure(
        RoomPolicyFailureCode.textMessagesDisabled,
        message: serverMessage.isEmpty ? null : serverMessage,
      ),
      'media_disabled' => RoomPolicyFailure(
        RoomPolicyFailureCode.mediaDisabled,
        message: serverMessage.isEmpty ? null : serverMessage,
      ),
      'slow_mode_active' => RoomPolicyFailure(
        RoomPolicyFailureCode.slowModeActive,
        retryAfterSeconds: retryAfterSeconds,
        message: serverMessage.isEmpty ? null : serverMessage,
      ),
      _
          when error.statusCode == 503 ||
              error.statusCode == 502 ||
              error.statusCode == 504 =>
        RoomPolicyFailure(
          RoomPolicyFailureCode.serviceUnavailable,
          message: serverMessage.isEmpty ? null : serverMessage,
        ),
      _ => RoomPolicyFailure(
        RoomPolicyFailureCode.generic,
        message: serverMessage.isEmpty
            ? (error.responseBody ?? error.toString())
            : serverMessage,
      ),
    };
    return (failure: failure, nextAllowedAtMs: nextAllowedAtMs);
  }

  RoomPolicyFailure _roomPinnedMessageFailureFromRelayHttp(
    RelayHttpException error,
  ) {
    final payload = _tryDecodeRelayErrorBody(error.responseBody);
    final code = ((payload?['code'] as String?) ?? '').trim();
    final serverMessage = ((payload?['message'] as String?) ?? '').trim();
    return switch (code) {
      'not_member' => RoomPolicyFailure(
        RoomPolicyFailureCode.notMember,
        message: serverMessage.isEmpty ? null : serverMessage,
      ),
      'pin_not_allowed' => RoomPolicyFailure(
        RoomPolicyFailureCode.pinMessagesDenied,
        message: serverMessage.isEmpty ? null : serverMessage,
      ),
      'message_not_found' => RoomPolicyFailure(
        RoomPolicyFailureCode.generic,
        message: serverMessage.isEmpty
            ? 'Message is not available for pinning in this room.'
            : serverMessage,
      ),
      _
          when error.statusCode == 503 ||
              error.statusCode == 502 ||
              error.statusCode == 504 =>
        RoomPolicyFailure(
          RoomPolicyFailureCode.serviceUnavailable,
          message: serverMessage.isEmpty ? null : serverMessage,
        ),
      _ => RoomPolicyFailure(
        RoomPolicyFailureCode.generic,
        message: serverMessage.isEmpty
            ? (error.responseBody ?? error.toString())
            : serverMessage,
      ),
    };
  }

  // Maps a relay HTTP error from /v1/rooms/{id}/settings or /v1/rooms/{id}/profile
  // to a structured RoomPolicyFailure so the UI can show a localized message
  // instead of a raw "RelayHttpException: HTTP 403: forbidden" string.
  // Handles both the new JSON-shaped error body ({code, message, retry_after_seconds})
  // and legacy plain-text bodies (server endpoints not yet migrated).
  RoomPolicyFailure _roomSettingsUpdateFailureFromRelayHttp(
    RelayHttpException error,
  ) {
    final payload = _tryDecodeRelayErrorBody(error.responseBody);
    final code = ((payload?['code'] as String?) ?? '').trim();
    final serverMessage = ((payload?['message'] as String?) ?? '').trim();
    final rawBody = (error.responseBody ?? '').trim();
    final isLegacyForbidden =
        code.isEmpty &&
        error.statusCode == 403 &&
        (rawBody.isEmpty || rawBody.toLowerCase() == 'forbidden');
    return switch (code) {
      'not_member' || 'not_active_member' => RoomPolicyFailure(
        RoomPolicyFailureCode.notMember,
        message: serverMessage.isEmpty ? null : serverMessage,
      ),
      'admin_only' || 'forbidden' => RoomPolicyFailure(
        RoomPolicyFailureCode.adminOnly,
        message: serverMessage.isEmpty ? null : serverMessage,
      ),
      'change_group_info_not_allowed' ||
      'group_info_change_denied' => RoomPolicyFailure(
        RoomPolicyFailureCode.groupInfoChangeDenied,
        message: serverMessage.isEmpty ? null : serverMessage,
      ),
      _
          when error.statusCode == 503 ||
              error.statusCode == 502 ||
              error.statusCode == 504 =>
        RoomPolicyFailure(
          RoomPolicyFailureCode.serviceUnavailable,
          message: serverMessage.isEmpty ? null : serverMessage,
        ),
      _ when isLegacyForbidden => RoomPolicyFailure(
        RoomPolicyFailureCode.adminOnly,
      ),
      _ => RoomPolicyFailure(
        RoomPolicyFailureCode.generic,
        message: serverMessage.isEmpty
            ? (error.responseBody ?? error.toString())
            : serverMessage,
      ),
    };
  }

  RoomPolicyFailure _roomMemberTagFailureFromRelayHttp(
    RelayHttpException error,
  ) {
    final payload = _tryDecodeRelayErrorBody(error.responseBody);
    final code = ((payload?['code'] as String?) ?? '').trim();
    final serverMessage = ((payload?['message'] as String?) ?? '').trim();
    return switch (code) {
      'not_member' || 'not_active_member' => RoomPolicyFailure(
        RoomPolicyFailureCode.notMember,
        message: serverMessage.isEmpty ? null : serverMessage,
      ),
      'change_tag_not_allowed' => RoomPolicyFailure(
        RoomPolicyFailureCode.changeOwnTagDenied,
        message: serverMessage.isEmpty ? null : serverMessage,
      ),
      'bad_tag' => RoomPolicyFailure(
        RoomPolicyFailureCode.invalidOwnTag,
        message: serverMessage.isEmpty ? null : serverMessage,
      ),
      _
          when error.statusCode == 503 ||
              error.statusCode == 502 ||
              error.statusCode == 504 =>
        RoomPolicyFailure(
          RoomPolicyFailureCode.serviceUnavailable,
          message: serverMessage.isEmpty ? null : serverMessage,
        ),
      _ => RoomPolicyFailure(
        RoomPolicyFailureCode.generic,
        message: serverMessage.isEmpty
            ? (error.responseBody ?? error.toString())
            : serverMessage,
      ),
    };
  }

  String? _normalizeRoomMemberTagInput(String? tag) {
    final normalized = (tag ?? '').trim();
    if (normalized.isEmpty) {
      return null;
    }
    final hasControlChars = normalized.runes.any(
      (value) => value < 0x20 || value == 0x7f,
    );
    if (hasControlChars || normalized.runes.length > 32) {
      throw RoomPolicyFailure(RoomPolicyFailureCode.invalidOwnTag);
    }
    return normalized;
  }

  Future<void> _cacheLocalRoomPostingState({
    required String groupId,
    int? lastAdmittedAtMs,
    int? nextAllowedAtMs,
  }) async {
    final db = _db;
    final pid = profileId.trim();
    if (db == null || pid.isEmpty) return;
    await db.groupPostingStateUpsert(
      groupId: groupId,
      profileId: pid,
      lastAdmittedAtMs: lastAdmittedAtMs,
      nextAllowedAtMs: nextAllowedAtMs,
      updatedAtMs: DateTime.now().millisecondsSinceEpoch,
    );
  }

  Future<RelayRoomMessageAdmissionResult> _admitAuthoritativeRoomMessage({
    required String groupId,
    required String messageId,
    required String kind,
  }) async {
    _throwIfRoomMutationAuthoritativeRelayUnavailable();
    final relay = _relay;
    if (relay == null) {
      throw RoomPolicyFailure(RoomPolicyFailureCode.serviceUnavailable);
    }
    try {
      final result = await relay.admitRoomMessage(
        roomId: groupId,
        messageId: messageId,
        kind: kind,
      );
      await _cacheLocalRoomPostingState(
        groupId: groupId,
        lastAdmittedAtMs: result.admittedAtMs,
        nextAllowedAtMs: result.nextAllowedAtMs,
      );
      await _applyRelayRoomStateWithLocalMemberships(result.room);
      return result;
    } catch (error) {
      await _tryRefreshRoomFromRelayBestEffort(groupId);
      if (error is RelayHttpException) {
        final parsed = _roomPostingFailureFromRelayHttp(error);
        if (parsed.nextAllowedAtMs != null) {
          await _cacheLocalRoomPostingState(
            groupId: groupId,
            nextAllowedAtMs: parsed.nextAllowedAtMs,
          );
        }
        throw parsed.failure;
      }
      rethrow;
    }
  }

  bool _isSqliteBusyError(Object error) {
    final msg = error.toString().toLowerCase();
    return msg.contains('database is locked') ||
        msg.contains('sqlite_busy') ||
        msg.contains('code 5');
  }

  Future<T> _retryDbBusy<T>(Future<T> Function() fn, {int tries = 6}) async {
    Object? last;
    for (var i = 0; i < tries; i++) {
      try {
        return await fn();
      } catch (e) {
        last = e;
        if (!_isSqliteBusyError(e) || i == tries - 1) {
          rethrow;
        }
        await Future.delayed(Duration(milliseconds: 120 + i * 160));
      }
    }
    throw last ?? StateError('database busy retry failed');
  }

  void _kickRelayOutbox([RelayClient? relay]) {
    final r = relay ?? _relay;
    if (r == null) return;
    unawaited(
      _flushPendingReceiptsAndPumpOutbox(
        r,
      ).timeout(const Duration(seconds: 15)).catchError((_) {}),
    );
  }

  void _kickRelayInbox({RelayClient? relay, bool force = false}) {
    final r = relay ?? _relay;
    if (r == null) return;
    unawaited(
      r.pumpInbox(force: force).timeout(const Duration(seconds: 15)).catchError(
        (Object e) {
          // PR-D (Bug 12): record kick-level failures (typically the 15s
          // timeout when relay is misbehaving) so DebugConsole has the
          // breadcrumb. Inner pumpInbox already telemeters HTTP non-2xx
          // and per-call exceptions — this catches the outer timeout.
          DiagLog.event('relay', 'kick_inbox_failed', {
            'force': force,
            'reason': e.runtimeType.toString(),
          });
        },
      ),
    );
  }

  void _handleRelayConnectionChanged(RelayClient relay, bool connected) {
    if (!identical(_relay, relay)) return;
    _relayOnline = connected;
    DiagLog.event('relay', 'conn', {'online': connected});
    if (connected) {
      unawaited(_syncPushTokenBestEffort());
      unawaited(_syncVoipTokenBestEffort());
      _kickRelayOutbox(relay);
      // Point 1 (2026-06-12): FORCE the HTTP /v1/pending backfill on every relay
      // (re)connect — including cold start. The default pumpInbox short-circuits
      // when the WS looks "fresh", which races the WS Welcome->FetchPending
      // replay; on mobile cold-start that race meant a message queued while the
      // app was offline never got fetched ("opened the app, the message isn't
      // there"). The relay dedups by per-device seq cursor, so a forced fetch is
      // idempotent and cheap.
      _kickRelayInbox(relay: relay, force: true);
      // PR-S (BUG-S1): re-attempt any session-reset prekeys that couldn't be
      // dispatched earlier (profile lookup failure / network down at the time
      // of the decrypt drop).
      _drainSessionResetRetryQueue();
      unawaited(getCallIceConfig(forceRefresh: true));
      unawaited(_resyncKnownRelayStateBestEffort());
    }
    _relayConnectionChanges.add(connected);
    _maybeClearStartupWarning();
    _changed.add(null);
  }

  // ───────────────────────────────────────────────────────────────────────
  //   Connectivity watchdog — relay reconnect on network path changes
  // ───────────────────────────────────────────────────────────────────────

  /// Starts a global connectivity watcher that drops a stale relay WebSocket
  /// whenever the OS reports a new network path. Idempotent.
  /// Страховочный сторож значка поддержки.
  ///
  /// Основные поводы проверить — возвращение в приложение и пуш-побудка (ответ
  /// поддержки приходит веером пушей). Таймер лишь подстраховывает их раз в
  /// пять минут, и только если переписка с поддержкой уже заводилась: без неё
  /// [refreshSupportBadge] вообще не ходит в сеть.
  Timer? _supportBadgeTimer;

  void _startSupportBadgeWatcher() {
    _supportBadgeTimer?.cancel();
    _supportBadgeTimer = Timer.periodic(
      const Duration(minutes: 5),
      (_) => unawaited(refreshSupportBadge()),
    );
    unawaited(refreshSupportBadge());
  }

  void _startConnectivityReconnectWatcher() {
    if (kIsWeb) return;
    if (_appConnectivitySub != null || _appNativeNetworkPathSub != null) {
      return;
    }
    try {
      _appConnectivitySub = Connectivity().onConnectivityChanged.listen(
        (results) => _onConnectivityResultsChanged(results),
        onError: (_) {},
      );
    } catch (_) {
      _appConnectivitySub = null;
    }
    // The native EventChannel is a finer-grained signal (transport/metered
    // changes within the same connectivity_plus bucket), only available on
    // mobile platforms where the host registers it.
    if (defaultTargetPlatform == TargetPlatform.android ||
        defaultTargetPlatform == TargetPlatform.iOS) {
      try {
        // Общий поток с менеджером звонков: отдельный
        // `receiveBroadcastStream()` на то же имя оставался без событий
        // (N-2, `NativeNetworkPath`).
        _appNativeNetworkPathSub = NativeNetworkPath.events.listen(
          _onNativeNetworkPathEvent,
          onError: (_) {},
        );
      } catch (_) {
        _appNativeNetworkPathSub = null;
      }
    }
  }

  void _onConnectivityResultsChanged(List<ConnectivityResult> results) {
    final normalized = results
        .where((r) => r != ConnectivityResult.none)
        .toList(growable: false);
    final hasNetwork = normalized.isNotEmpty;
    final changed = !_listEquals(normalized, _appLastConnectivityResults);
    _appLastConnectivityResults = normalized;
    if (_networkOnline != hasNetwork) {
      _networkOnline = hasNetwork;
      // Repaint the brand-logo fingerprint (calm online, pulses when offline).
      _changed.add(null);
    }
    if (!changed) return;
    if (!hasNetwork) {
      // No connectivity — defer reconnect until a usable path returns.
      return;
    }
    _scheduleRelayReconnectKick();
  }

  void _onNativeNetworkPathEvent(Object? event) {
    if (event is! Map) return;
    final available = event['available'] == true;
    final signature = (event['signature'] as String?)?.trim() ?? '';
    if (signature.isEmpty) return;
    final previous = _appLastNetworkPathSignature;
    _appLastNetworkPathSignature = signature;
    if (!available) return;
    if (previous.isEmpty || previous == signature) {
      return;
    }
    _scheduleRelayReconnectKick();
  }

  void _scheduleRelayReconnectKick() {
    _appNetworkReconnectDebounce?.cancel();
    _appNetworkReconnectDebounce = Timer(const Duration(milliseconds: 350), () async {
      _appNetworkReconnectDebounce = null;
      final relay = _relay;
      if (relay == null) return;
      DiagLog.event('relay', 'net_change_reconnect_kick', {});
      try {
        relay.markWsStaleAndReconnect();
      } catch (_) {}
      _kickRelayOutbox(relay);
      // FIX (2026-07-24, docs/BUG_AUDIT.md "Разбор корня"): heal a zombie DB
      // BEFORE the forced inbox pump. A network flip is exactly when the shared
      // handle can be closed out from under us, and the pump WRITES the fetched
      // wires into `_db`; without this the pump wrote into a closed handle and
      // the rows were dropped — "relay online, yet messages vanish until a push"
      // (the connectivity path never called the reopen, only the latched
      // watchdog / a push did). Awaited so the reopen lands first; it is a cheap
      // no-op (probeClosed) when the DB is already healthy.
      try {
        await _recoverUnexpectedlyClosedDb('net_change');
      } catch (_) {}
      // PR4 (SPRINT2_AUDIT §16): after wake-from-sleep / network reconnect
      // we go via HTTP /v1/pending unconditionally — the WS may report
      // _wsReady=true momentarily during the reconnect dance and the
      // default pumpInbox short-circuit would skip the backfill we just
      // explicitly asked for. Mobile path also benefits (no behavioural
      // change in steady state — relay dedup is by per-device seq cursor).
      _kickRelayInbox(relay: relay, force: true);
    });
  }

  // ───────────────────────────────────────────────────────────────────────
  //   Desktop wake-event watcher — relay reconnect on system resume
  // ───────────────────────────────────────────────────────────────────────

  /// Starts the macOS sleep/wake bridge so the relay reconnects immediately
  /// when the system resumes from sleep. No-op on platforms that don't
  /// implement the `secretly/power_state` EventChannel (iOS, Android, web,
  /// Linux, Windows).
  ///
  /// Why this isn't redundant with `_startConnectivityReconnectWatcher`:
  ///   • connectivity_plus only fires when the network reachability bucket
  ///     itself changes. After a brief sleep on the same Wi-Fi network, the
  ///     OS reports the same path on wake, so no event arrives — but the
  ///     WebSocket has been killed by the kernel and won't deliver new
  ///     events until the next heartbeat times out (typically 30–60s).
  ///   • The native macOS path monitor (`NWPathMonitor`) isn't wired up on
  ///     desktop today, so we'd never get the fine-grained "interface
  ///     changed" signal even if it existed.
  /// The wake notification is the most reliable signal on macOS that we
  /// should aggressively re-test the relay connection.
  void _startDesktopPowerWakeWatcher() {
    if (kIsWeb) return;
    if (defaultTargetPlatform != TargetPlatform.macOS) return;
    if (_appPowerStateSub != null) return;
    try {
      _appPowerStateSub = _appPowerStateChannel.receiveBroadcastStream().listen(
        _onDesktopPowerStateEvent,
        onError: (_) {},
      );
    } catch (_) {
      _appPowerStateSub = null;
    }
  }

  void _onDesktopPowerStateEvent(Object? event) {
    if (event is! Map) return;
    final kind = (event['event'] as String?)?.trim() ?? '';
    if (kind.isEmpty) return;
    // We only act on wake. `sleep` is logged for diagnostics so we can
    // correlate gaps in event delivery with system sleep windows.
    // `screen_wake` (lid open / display unlock) is treated the same as
    // `wake` since the relay socket can have been killed without a full
    // system sleep on lid-close-then-quick-reopen.
    if (kind == 'sleep') {
      DiagLog.event('relay', 'desktop_power_sleep', {});
      return;
    }
    if (kind != 'wake' && kind != 'screen_wake') return;
    // Coalesce duplicate wake notifications (didWake + screensDidWake fire
    // within milliseconds of each other on a typical lid-open) into a
    // single kick. The reconnect path itself is also debounced 350ms by
    // `_scheduleRelayReconnectKick`, so this is a defense-in-depth check.
    final now = DateTime.now().millisecondsSinceEpoch;
    if (now - _appLastWakeKickMs < 1500) return;
    _appLastWakeKickMs = now;
    DiagLog.event('relay', 'desktop_power_wake_kick', {'kind': kind});
    _scheduleRelayReconnectKick();
  }

  bool _listEquals(List<ConnectivityResult> a, List<ConnectivityResult> b) {
    if (a.length != b.length) return false;
    for (var i = 0; i < a.length; i++) {
      if (a[i] != b[i]) return false;
    }
    return true;
  }

  Future<void> _recoverStuckOutgoingSends({required int nowMs}) async {
    final db = _db;
    if (db == null) return;
    final recovered = await db.outboxRescheduleStalledSends(
      nowMs: nowMs,
      stalledBeforeMs: nowMs - _outgoingSendStallMs,
      retryAtMs: nowMs + _outgoingSendRecoveryDelayMs,
      reasonCode: MessageFailureReason.sendStallTimeout,
    );
    if (recovered <= 0) return;
    // Drop the WS so the outbox falls back to HTTP while the socket reconnects.
    _relay?.markWsStaleAndReconnect();
    _kickRelayOutbox();
    _changed.add(null);
  }

  Future<void> _kickRelayOutboxAndWait(
    RelayClient relay, {
    Duration timeout = const Duration(seconds: 15),
  }) async {
    try {
      await _flushPendingReceiptsAndPumpOutbox(relay).timeout(timeout);
    } catch (_) {}
  }

  Future<void> _flushPendingReceiptsAndPumpOutbox(RelayClient relay) async {
    await _flushPendingReceiptsBestEffort();
    await relay.pumpOutbox();
  }

  Future<void> _persistPendingReceiptIntents({
    required Iterable<_PendingReceiptIntent> intents,
    required int nowMs,
  }) async {
    final db = _db;
    if (db == null) return;
    for (final intent in intents) {
      final peerDeviceId = intent.peerDeviceId.trim();
      final payloadEventId = intent.payloadEventId.trim();
      if (peerDeviceId.isEmpty || payloadEventId.isEmpty) {
        continue;
      }
      await db.pendingReceiptUpsert(
        peerDeviceId: peerDeviceId,
        peerProfileId: intent.peerProfileId,
        payloadEventId: payloadEventId,
        convoId: intent.convoId,
        status: intent.status,
        createdAtMs: nowMs,
        updatedAtMs: nowMs,
      );
    }
  }

  Future<int> _flushPendingReceiptsBestEffort() async {
    if (_pendingReceiptFlushInFlight) {
      _pendingReceiptFlushQueued = true;
      return 0;
    }

    final db = _db;
    final did = (_deviceId ?? '').trim();
    final ratchet = _ratchetV3;
    if (db == null || did.isEmpty || ratchet == null) {
      DiagLog.event('receipt', 'flush_skip', {
        'reason': db == null
            ? 'no_db'
            : (did.isEmpty ? 'no_device' : 'no_ratchet'),
      });
      return 0;
    }

    _pendingReceiptFlushInFlight = true;
    var queuedCount = 0;
    try {
      final pending = await db.pendingReceiptList(limit: 512);
      if (pending.isEmpty) {
        // Stay silent on the empty-queue fast path. The adaptive pump timer
        // calls us repeatedly; logging every tick floods logcat and obscures
        // real send/receive events.
        return 0;
      }
      DiagLog.event('receipt', 'flush_start', {
        'pending_count': pending.length,
      });

      final resolvedProfileIdByDeviceId = <String, String?>{};
      final currentDevicesByProfileId = <String, List<String>>{};
      final grouped = <String, List<PendingReceiptRecord>>{};
      final groupedConvoIds = <String, String?>{};
      final groupedProfileIds = <String, String>{};
      final groupedDeviceIds = <String, String>{};

      for (final record in pending) {
        final peerDeviceId = record.peerDeviceId.trim();
        final recordConvoId = (record.convoId ?? '').trim();
        var peerProfileId = (record.peerProfileId ?? '').trim();
        // A `dev:<id>` placeholder is NOT a real profile id (it means we never
        // resolved the sender) — treat it as unresolved so the fallbacks run.
        if (peerProfileId.startsWith('dev:')) {
          peerProfileId = '';
        }
        if (peerProfileId.isEmpty && peerDeviceId.isNotEmpty) {
          if (!resolvedProfileIdByDeviceId.containsKey(peerDeviceId)) {
            resolvedProfileIdByDeviceId[peerDeviceId] =
                await _resolveProfileIdForDevice(peerDeviceId);
          }
          peerProfileId = (resolvedProfileIdByDeviceId[peerDeviceId] ?? '')
              .trim();
        }
        // FIX-C3 (zombie device_id root): when device->profile resolution fails
        // — the sender rotated its device_id to a fresh id the directory can no
        // longer map back — fall back to the conversation id, which for a 1:1
        // chat IS the peer's profile_id. Without this the receipt is skipped on
        // every flush pass forever, so the sender stays on "delivered" and never
        // flips to "read". group:/dev:/empty convo ids do not qualify.
        if (peerProfileId.isEmpty &&
            recordConvoId.isNotEmpty &&
            !recordConvoId.startsWith('group:') &&
            !recordConvoId.startsWith('dev:')) {
          peerProfileId = recordConvoId;
        }
        if (peerProfileId.isEmpty) {
          continue;
        }
        // FIX-C3 (delivery): address the receipt to the peer's CURRENT live
        // devices, not only the (possibly stale/zombie) device that sent the
        // original message. learn-on-receive keeps `contact_devices` pointed at
        // the peer's live device after they rotate/recreate, so unioning it in
        // guarantees the receipt reaches the device they actually read on. The
        // stored sender device stays a target too (it may still be live and the
        // cached list may be stale). Capped to avoid fan-out blow-up. This is
        // the core fix for the "messages arrive but are never marked read"
        // symptom after multi-account churn.
        if (!currentDevicesByProfileId.containsKey(peerProfileId)) {
          try {
            final rows = await db.contactDevicesList(peerProfileId);
            currentDevicesByProfileId[peerProfileId] = rows
                .map((r) => ((r['device_id'] as String?) ?? '').trim())
                .where((d) => d.isNotEmpty)
                .toList(growable: false);
          } catch (_) {
            currentDevicesByProfileId[peerProfileId] = const <String>[];
          }
        }
        final targetDeviceIds = <String>{};
        if (peerDeviceId.isNotEmpty && !isOwnDeviceId(peerDeviceId)) {
          targetDeviceIds.add(peerDeviceId);
        }
        for (final d
            in currentDevicesByProfileId[peerProfileId] ?? const <String>[]) {
          if (isOwnDeviceId(d)) continue;
          targetDeviceIds.add(d);
          if (targetDeviceIds.length >= 8) break;
        }
        if (targetDeviceIds.isEmpty) {
          continue;
        }
        for (final targetDeviceId in targetDeviceIds) {
          final batchKey = '$peerProfileId\n$targetDeviceId';
          grouped
              .putIfAbsent(batchKey, () => <PendingReceiptRecord>[])
              .add(record);
          groupedProfileIds[batchKey] = peerProfileId;
          groupedDeviceIds[batchKey] = targetDeviceId;
          if (recordConvoId.isNotEmpty) {
            groupedConvoIds.putIfAbsent(batchKey, () => recordConvoId);
          }
        }
      }

      final now = DateTime.now().millisecondsSinceEpoch;
      for (final entry in grouped.entries) {
        final batchKey = entry.key;
        final records = entry.value;
        if (records.isEmpty) {
          continue;
        }
        final peerProfileId = groupedProfileIds[batchKey] ?? '';
        final peerDeviceId = groupedDeviceIds[batchKey] ?? '';
        if (peerProfileId.isEmpty || peerDeviceId.isEmpty) {
          continue;
        }
        final receiptEvents = records
            .map(
              (record) => ReceiptEventV1(
                eventId: _uuid.v4(),
                refEventId: record.payloadEventId,
                status: record.status,
                // TZ Epic A: a NACK's ref is the RELAY msg_id (decrypt never
                // happened → no payload event id exists). Inferred from the
                // status so the pending_receipts table needs no migration.
                refKind:
                    MessageReceiptState.normalize(record.status) ==
                        MessageReceiptState.nackUndecryptable
                    ? 'msg_id'
                    : null,
              ),
            )
            .toList(growable: false);
        if (receiptEvents.isEmpty) {
          continue;
        }

        final receiptPayload = E2ePayloadV1(
          senderDeviceId: did,
          createdAtMs: now,
          events: receiptEvents,
        );
        try {
          final wire = await _encryptToPeerSerialized(
            ratchet: ratchet,
            selfDeviceId: did,
            peerProfileId: peerProfileId,
            peerDeviceId: peerDeviceId,
            plaintext: Uint8List.fromList(receiptPayload.encode()),
          );
          await db.pendingReceiptQueueOutbox(
            msgId: _uuid.v4(),
            toDeviceId: peerDeviceId,
            ciphertextB64: base64Encode(wire),
            ttlSeconds: 24 * 60 * 60,
            nextRetryAtMs: now,
            createdAtMs: now,
            pendingReceipts: records,
            convoId: groupedConvoIds[batchKey],
          );
          queuedCount += records.length;
          DiagLog.event('receipt', 'queued', {
            'peer': DiagLog.pfx(peerProfileId),
            'to_dev': DiagLog.pfx(peerDeviceId),
            'count': records.length,
          });
        } catch (error) {
          _lastReceiptFlushFailureAtMs = DateTime.now().millisecondsSinceEpoch;
          _receiptFlushFailureCount += 1;
          _lastReceiptFlushFailureSummary = _summarizeDiagnosticError(error);
          DiagLog.event('receipt', 'queue_fail', {
            'peer': DiagLog.pfx(peerProfileId),
            'to_dev': DiagLog.pfx(peerDeviceId),
            'reason': _classifyShortReason(error),
          });
          continue;
        }
      }
      return queuedCount;
    } finally {
      _pendingReceiptFlushInFlight = false;
      if (queuedCount > 0) {
        _changed.add(null);
      }
      if (_pendingReceiptFlushQueued) {
        _pendingReceiptFlushQueued = false;
        unawaited(_flushPendingReceiptsBestEffort());
      }
    }
  }

  Future<String> identityFingerprint() async {
    final pid = _profileId;
    final did = _deviceId;
    if (pid == null || pid.isEmpty || did == null || did.isEmpty) return '—';

    final deviceKeys = DeviceKeys.create();
    final kp = await deviceKeys.loadIdentityKeyPair(
      profileId: pid,
      deviceId: did,
    );
    final pub = await kp.extractPublicKey();
    final h = await Sha256().hash(pub.bytes);
    final hex = h.bytes.map((b) => b.toRadixString(16).padLeft(2, '0')).join();
    // Display as short grouped fingerprint.
    final shortHex = hex.substring(0, 24);
    return '${shortHex.substring(0, 6)}-${shortHex.substring(6, 12)}-${shortHex.substring(12, 18)}-${shortHex.substring(18, 24)}';
  }

  Future<String> identityKeyPubB64() async {
    final pid = _profileId;
    final did = _deviceId;
    if (pid == null || pid.isEmpty || did == null || did.isEmpty) return '';

    final deviceKeys = DeviceKeys.create();
    final bundle = await deviceKeys.createOrLoadAndAllocateOtk(
      profileId: pid,
      deviceId: did,
      allocateOneTimePrekeys: 0,
    );
    return bundle.identityKeyPubB64;
  }

  void _maybeClearStartupWarning() {
    // Relay counts as up if EITHER the WS is connected OR HTTP is reachable — a
    // WS-only check latches the "Relay is offline" banner on MIUI/slow links
    // even though the inbox pump + calls keep working over HTTP.
    if (_keysOnline && (_relayOnline || _relayHttpReachable)) {
      _startupWarning = null;
    }
  }

  bool _keysRecheckInFlight = false;

  /// Foreground-resume keys recovery (Tier-A reliability fix for the latched
  /// "Keys is offline" banner). Drops any stale (MIUI-frozen) keep-alive socket,
  /// re-checks keys health immediately, runs keys setup if it came back, and
  /// clears the banner — without waiting up to ~3s for the periodic watchdog
  /// (which may itself be stuck on the dead socket). Best-effort; the watchdog
  /// remains the authoritative retry loop.
  Future<void> _recheckKeysHealthNow() async {
    if (_keysRecheckInFlight || _watchdogRunning || _transportBlocked) return;
    final keys = _keys;
    final prefs = _prefs;
    if (keys == null || prefs == null) return;
    _keysRecheckInFlight = true;
    final keysOnlineBefore = _keysOnline;
    final warnBefore = _startupWarning;
    try {
      keys.resetConnections();
      final health = await keys.healthStatus(
        clientProtocolVersion: clientProtocolVersion,
      );
      if (!health.isHealthy) return;
      if (!_keysOnline) {
        await _ensureKeysSetup(
          prefs: prefs,
          keys: keys,
          allowServerProfileAutoCreate: !requiresDesktopProfileSelection,
          allowMissingCurrentDeviceRepair: false,
        ).timeout(const Duration(seconds: 12));
        _keysOnline = true;
      }
      _maybeClearStartupWarning();
    } catch (_) {
      // Leave the periodic watchdog to keep retrying.
    } finally {
      _keysRecheckInFlight = false;
      if ((keysOnlineBefore != _keysOnline || warnBefore != _startupWarning) &&
          !_changed.isClosed) {
        _changed.add(null);
      }
    }
  }

  Future<
    ({
      String requesterDeviceId,
      int tsMs,
      String nonceB64,
      String signatureB64,
    })?
  >
  _buildKeysAuthEnvelope({
    required List<int> Function({
      required String requesterDeviceId,
      required int tsMs,
      required String nonceB64,
    })
    buildMessage,
  }) async {
    final myPid = _profileId;
    final myDid = _deviceId;
    if (myPid == null || myPid.isEmpty || myDid == null || myDid.isEmpty) {
      // Diagnostic (2026-06-19): a null envelope falls back to an UNAUTHENTICATED
      // keys request → server rejects "missing x-secretly-device-id" → bundle
      // fetch fails → sessions can't establish/recover. Surface WHY.
      DiagLog.event('keys', 'auth_envelope_null', {
        'reason': 'ids_empty',
        'pid_empty': myPid == null || myPid.isEmpty,
        'did_empty': myDid == null || myDid.isEmpty,
      });
      return null;
    }
    try {
      final deviceKeys = DeviceKeys.create();
      final kp = await deviceKeys.loadIdentityKeyPair(
        profileId: myPid,
        deviceId: myDid,
      );
      // 🔴 ВРЕМЯ СЕРВЕРА, А НЕ УСТРОЙСТВА. Сервер отвергает метку, разошедшуюся
      // с его часами больше чем на пять минут, — правильная защита от повтора
      // запроса. Но человеку со сбитыми часами она закрывает всё: подписанные
      // запросы не принимаются, список устройств собеседника не получить, а без
      // него сообщение некуда отправить. Поле 26.08: шесть устройств дали около
      // четырёх тысяч таких отказов за трое суток.
      //
      // `ServerClock` держит поправку, вычисленную по заголовку `Date` обычных
      // ответов; часы устройства при этом не трогаются. Без расхождения
      // поправка равна нулю, и ничего не меняется.
      final tsMs = ServerClock.instance.nowMs();
      final nonceB64 = AuthSigner.randomNonceB64(bytes: 16);
      final message = buildMessage(
        requesterDeviceId: myDid,
        tsMs: tsMs,
        nonceB64: nonceB64,
      );
      final signatureB64 = await AuthSigner.signEd25519B64(
        identityKeyPair: kp,
        message: message,
      );
      return (
        requesterDeviceId: myDid,
        tsMs: tsMs,
        nonceB64: nonceB64,
        signatureB64: signatureB64,
      );
    } catch (e) {
      DiagLog.event('keys', 'auth_envelope_null', {
        'reason': 'load_or_sign_threw',
        'pid': DiagLog.pfx(myPid),
        'did': DiagLog.pfx(myDid),
        'err': e.toString().replaceAll(RegExp(r'\s+'), '_').replaceAll("'", ''),
      });
      return null;
    }
  }

  Future<List<String>> _listDevicesAuthed(String targetProfileId) async {
    final keys = _keys;
    if (keys == null) {
      throw StateError(
        'Keys-клиент ещё не инициализирован. Подождите окончания подключения или перезайдите.',
      );
    }

    final myDid = _deviceId;
    if (myDid != null && myDid.isNotEmpty) {
      final auth = await _buildKeysAuthEnvelope(
        buildMessage:
            ({required requesterDeviceId, required tsMs, required nonceB64}) =>
                AuthSigner.keysListDevicesMessage(
                  requesterDeviceId: requesterDeviceId,
                  profileId: targetProfileId,
                  tsMs: tsMs,
                  nonceB64: nonceB64,
                ),
      );
      if (auth != null) {
        return keys.listDevices(
          targetProfileId,
          requesterDeviceId: auth.requesterDeviceId,
          tsMs: auth.tsMs,
          nonceB64: auth.nonceB64,
          signatureB64: auth.signatureB64,
        );
      }
    }

    // Device-auth envelope unavailable (device_id/identity material not ready,
    // or a transient secure-storage read). This keys endpoint REQUIRES auth, so
    // an unauthenticated call deterministically 401s ("missing
    // x-secretly-device-id"). Surface a retryable error instead of making the
    // doomed round-trip — keys_client throws on non-2xx anyway, so callers
    // already handle this; we just skip the wasted request + server log noise.
    throw StateError(
      'keys device-auth not ready (device_id/identity material unavailable)',
    );
  }

  Future<List<KeysDeviceStatus>> _listDeviceStatusesAuthed(
    String targetProfileId,
  ) async {
    final keys = _keys;
    if (keys == null) return const <KeysDeviceStatus>[];

    final myDid = _deviceId;
    if (myDid != null && myDid.isNotEmpty) {
      final auth = await _buildKeysAuthEnvelope(
        buildMessage:
            ({required requesterDeviceId, required tsMs, required nonceB64}) =>
                AuthSigner.keysListDevicesMessage(
                  requesterDeviceId: requesterDeviceId,
                  profileId: targetProfileId,
                  tsMs: tsMs,
                  nonceB64: nonceB64,
                ),
      );
      if (auth != null) {
        return keys.listDeviceStatuses(
          targetProfileId,
          requesterDeviceId: auth.requesterDeviceId,
          tsMs: auth.tsMs,
          nonceB64: auth.nonceB64,
          signatureB64: auth.signatureB64,
        );
      }
    }

    // See _listDevicesAuthed: this endpoint requires device-auth, so a null
    // envelope means "not ready" — fail retryably rather than firing a doomed
    // unauthenticated request that the server rejects with 401.
    throw StateError(
      'keys device-auth not ready (device_id/identity material unavailable)',
    );
  }

  Future<List<Map<String, Object?>>> _fetchBundleAuthed(
    String targetProfileId,
  ) async {
    final keys = _keys;
    if (keys == null) return const <Map<String, Object?>>[];

    // One bundle-fetch attempt with a freshly built device-auth envelope.
    // Returns null when we are not ready to sign (device_id/identity material
    // unavailable this instant) so the caller falls through to a retryable error
    // instead of firing a doomed unauthenticated request.
    Future<List<Map<String, Object?>>?> attempt() async {
      final myDid = _deviceId;
      if (myDid == null || myDid.isEmpty) return null;
      final auth = await _buildKeysAuthEnvelope(
        buildMessage:
            ({required requesterDeviceId, required tsMs, required nonceB64}) =>
                AuthSigner.keysFetchBundleMessage(
                  requesterDeviceId: requesterDeviceId,
                  profileId: targetProfileId,
                  tsMs: tsMs,
                  nonceB64: nonceB64,
                ),
      );
      if (auth == null) return null;
      return keys.fetchBundle(
        targetProfileId,
        requesterDeviceId: auth.requesterDeviceId,
        tsMs: auth.tsMs,
        nonceB64: auth.nonceB64,
        signatureB64: auth.signatureB64,
      );
    }

    // 🔴 429 НЕ ДОЛЖЕН УБИВАТЬ ЗВОНОК (24.08.2026).
    //
    // Бакет сервера ключей считается ПО IP, поэтому два устройства одного
    // человека за домашним Wi-Fi делят его на двоих, а фоновые перепроверки
    // бандлов его вычерпывают. Когда звонок принимают, сессии с устройством
    // звонящего может не быть — тогда для шифрования ОТВЕТА нужен бандл, и один
    // отказ по лимиту оставлял звонящего слушать гудки в пустоту: ответ не
    // шифровался, значит не уходил вовсе.
    //
    // Поле 24.08: `fetchBundle failed: 429 rate_limited` ⇒ «no deliverable
    // target devices» ⇒ звонок принят на одной стороне и звонит на другой.
    //
    // Бакет восстанавливается ДВА запроса в секунду, то есть повтор через
    // полсекунды почти наверняка проходит. Три короткие попытки дешевле одного
    // потерянного звонка и при этом не превращаются в шторм: только на 429, с
    // растущей паузой и жёстким потолком.
    const rateLimitRetryDelaysMs = <int>[400, 900, 1600];
    for (var attemptNo = 0; attemptNo <= rateLimitRetryDelaysMs.length; attemptNo++) {
      try {
        final result = await attempt();
        if (result != null) return result;
        break;
      } catch (error) {
        final msg = error.toString().toLowerCase();
        final rateLimited =
            msg.contains('429') || msg.contains('rate_limited');
        if (!rateLimited || attemptNo == rateLimitRetryDelaysMs.length) {
          rethrow;
        }
        DiagLog.event('keys', 'bundle_fetch_rate_limited', {
          'attempt': attemptNo + 1,
          'retry_in_ms': rateLimitRetryDelaysMs[attemptNo],
        });
        await Future<void>.delayed(
          Duration(milliseconds: rateLimitRetryDelaysMs[attemptNo]),
        );
      }
    }

    try {
      final result = await attempt();
      if (result != null) return result;
    } catch (error) {
      // Self-heal a device-identity desync — e.g. flutter_secure_storage seed
      // loss after a new-phone Android restore: the local signing key no longer
      // matches the server's pinned identity key for this device_id, so every
      // bundle fetch 401s ("bad signature"). Without this, the send/outbox retry
      // loop storms fetch_bundle for ~a minute (2026-06-20 incident). Run the
      // current-device repair — which rotates device_id on the server's
      // device_identity_key_mismatch — ONCE, then retry with the fresh identity.
      if (_isMissingCurrentKeysDeviceError(error) &&
          await _repairKeysIdentityForSendOnce()) {
        final retried = await attempt();
        if (retried != null) return retried;
      }
      rethrow;
    }

    // Device-auth envelope unavailable (device_id/identity material not ready,
    // or a transient secure-storage read). This endpoint REQUIRES auth, so an
    // unauthenticated call deterministically 401s — surface a retryable error
    // instead of the doomed round-trip; callers retry once auth is ready.
    throw StateError(
      'keys device-auth not ready (device_id/identity material unavailable)',
    );
  }

  Future<(bool exists, String? payload, int updatedAtMs)> backupGetFromServer(
    String targetProfileId, {
    bool useDeviceAuth = true,
    String? backupPassword,
  }) async {
    final keys = _keys;
    if (keys == null) return (false, null, 0);

    // Э-1 (SEC-01): на новом устройстве подписать запрос нечем — ключей ещё
    // нет. Зато у человека есть пароль архива: он его только что ввёл. Из
    // пароля выводится токен доступа, и именно он заменяет подпись.
    //
    // Сбой запроса соли НЕ обрывает восстановление: на этом этапе сервер токен
    // не требует, и клиент обязан уметь работать со сборкой сервера, где этого
    // пути ещё нет. Когда требование включат, отказ придёт от сервера — решение
    // принимает он, а не клиент.
    String? accessTokenB64;
    final pw = backupPassword?.trim() ?? '';
    if (pw.isNotEmpty) {
      try {
        final saltB64 = await keys.backupAccessChallenge(targetProfileId);
        if (saltB64.isNotEmpty) {
          final access = await BackupAccessV1.fromSalt(
            password: pw,
            saltB64: saltB64,
          );
          accessTokenB64 = access.tokenB64;
        }
      } catch (e) {
        DiagLog.event('backup', 'access_challenge_failed', {
          'reason': _classifyShortReason(e),
        });
      }
    }

    final myDid = _deviceId;
    if (useDeviceAuth && myDid != null && myDid.isNotEmpty) {
      final auth = await _buildKeysAuthEnvelope(
        buildMessage:
            ({required requesterDeviceId, required tsMs, required nonceB64}) =>
                AuthSigner.keysBackupGetMessage(
                  requesterDeviceId: requesterDeviceId,
                  profileId: targetProfileId,
                  tsMs: tsMs,
                  nonceB64: nonceB64,
                ),
      );
      if (auth != null) {
        return keys.backupGet(
          targetProfileId,
          requesterDeviceId: auth.requesterDeviceId,
          tsMs: auth.tsMs,
          nonceB64: auth.nonceB64,
          signatureB64: auth.signatureB64,
          accessTokenB64: accessTokenB64,
        );
      }
    }

    return keys.backupGet(targetProfileId, accessTokenB64: accessTokenB64);
  }

  int _keysSetupJobSeq = 0;

  Future<T> _serializeKeysSetup<T>(Future<T> Function() action) {
    final previous = _keysSetupQueue;
    final completer = Completer<T>();
    final job = ++_keysSetupJobSeq;
    DiagLog.event('keys_setup', 'enqueue', {'job': job});
    _keysSetupQueue = () async {
      try {
        await previous;
      } catch (_) {
        // Ignore previous failures so the next repair can still run.
      }
      DiagLog.event('keys_setup', 'start', {'job': job});

      try {
        completer.complete(await action());
        DiagLog.event('keys_setup', 'done', {'job': job});
      } catch (error, stackTrace) {
        DiagLog.event('keys_setup', 'error', {
          'job': job,
          'type': error.runtimeType,
          'msg': error.toString(),
        });
        completer.completeError(error, stackTrace);
      }
    }();
    return completer.future;
  }

  Future<bool> _ensureKeysSetup({
    required SharedPreferences prefs,
    required KeysClient keys,
    bool allowServerProfileAutoCreate = true,
    bool allowMissingCurrentDeviceRepair = false,
  }) async {
    // Keys challenges are one-shot per device id on the server. Serializing
    // setup avoids concurrent repair flows invalidating each other's nonce.
    final pidBefore = (_profileId ?? '').trim();
    final didBefore = (_deviceId ?? '').trim();
    final result = await _serializeKeysSetup(
      () => _ensureKeysSetupInternal(
        prefs: prefs,
        keys: keys,
        allowServerProfileAutoCreate: allowServerProfileAutoCreate,
        allowMissingCurrentDeviceRepair: allowMissingCurrentDeviceRepair,
      ),
    );
    // PR-D (Bug 13): re-register the push token whenever Keys setup
    // materially changed `_profileId` or `_deviceId`. Without this, a fresh
    // install (which assigns a server profile inside _ensureKeysSetup
    // AFTER the boot-time _syncPushTokenBestEffort already ran) leaves the
    // token registered under the previous/empty identity, so the device
    // never gets push notifications until the next cold start or token
    // rotation. Fire-and-forget so callers (which range from boot to QR
    // pairing) don't observe extra latency.
    final pidAfter = (_profileId ?? '').trim();
    final didAfter = (_deviceId ?? '').trim();
    final identityChanged = (pidAfter != pidBefore) || (didAfter != didBefore);
    if (identityChanged && pidAfter.isNotEmpty && didAfter.isNotEmpty) {
      DiagLog.event('push', 'resync_after_keys_setup', {
        'pid_changed': pidAfter != pidBefore,
        'did_changed': didAfter != didBefore,
      });
      unawaited(_syncPushTokenBestEffort());
      unawaited(_syncVoipTokenBestEffort());
    }
    return result;
  }

  Future<bool> _ensureKeysSetupInternal({
    required SharedPreferences prefs,
    required KeysClient keys,
    bool allowServerProfileAutoCreate = true,
    bool allowMissingCurrentDeviceRepair = false,
  }) async {
    Future<T> retry<T>(Future<T> Function() fn, {int tries = 3}) async {
      Object? last;
      for (var i = 0; i < tries; i++) {
        try {
          return await fn();
        } catch (e) {
          if (e is KeysPolicyFailure) {
            rethrow;
          }
          last = e;
          await Future.delayed(Duration(milliseconds: 250 + i * 350));
        }
      }
      throw last ?? StateError('retry failed');
    }

    final secrets = SecureSecrets.create();

    var pid = (_profileId ?? '').trim();
    final hasServerBackedProfile = _isServerBackedProfileId(pid);

    if (!hasServerBackedProfile && !allowServerProfileAutoCreate) {
      if (_isDesktopOrWebPlatform) {
        await _clearDesktopLocalOnlyProfileState(prefs);
      } else {
        if (pid.isEmpty) {
          pid = 'LOCAL-${_uuid.v4()}';
        }
        _profileId = pid;
        await prefs.setString(_prefsProfileIdKey, pid);
      }
      return false;
    }

    // Ensure we have a server-backed profile.
    if (!hasServerBackedProfile) {
      // A new identity is about to replace whatever was here. Record the TRACES
      // of the previous one FIRST: a fresh install leaves none, so leftovers
      // (a database file on disk, a device id still in preferences) mean local
      // state was PARTIALLY lost — the anomaly behind "the user became someone
      // else". Written before the change, because afterwards the evidence for
      // it is gone. See IdentityJournal.
      await IdentityJournal.record(
        reason: IdentityJournal.reasonNoLocalProfile,
        nowMs: DateTime.now().millisecondsSinceEpoch,
        previousProfileId: pid.isEmpty ? null : pid,
        previousDeviceId: prefs.getString(_prefsDeviceIdKey),
        detail: <String, Object?>{
          'db_file_present': await AppDb.localDatabaseFileExists(),
          'had_device_id': (prefs.getString(_prefsDeviceIdKey) ?? '').isNotEmpty,
          'had_local_profile': pid.isNotEmpty,
        },
      );
      final created = await retry(() => keys.createProfile());
      _profileId = created.profileId;
      await prefs.setString(_prefsProfileIdKey, _profileId!);
      await secrets.setProfileSecretB64(
        profileId: _profileId!,
        secretB64: created.profileSecretB64,
      );
      _debugRuntimeLog('Created server-backed profile');
    } else {
      final exists = await retry(() => keys.profileExists(_profileId!));
      if (!exists) {
        if (!allowServerProfileAutoCreate) {
          if (_isDesktopOrWebPlatform) {
            throw StateError(
              'Saved desktop profile is not available on the current Keys server. '
              'Re-link this desktop from your primary phone.',
            );
          }
          _profileId = 'LOCAL-${_uuid.v4()}';
          await prefs.setString(_prefsProfileIdKey, _profileId!);
          return false;
        }

        // The keys server said this profile does not exist. That answer costs
        // the person their identity, so record WHO decided it and which id was
        // discarded — today an event like this leaves no trace at all.
        await IdentityJournal.record(
          reason: IdentityJournal.reasonStartupProfileMissing,
          nowMs: DateTime.now().millisecondsSinceEpoch,
          previousProfileId: _profileId,
          previousDeviceId: prefs.getString(_prefsDeviceIdKey),
          detail: <String, Object?>{
            'db_file_present': await AppDb.localDatabaseFileExists(),
          },
        );
        final created = await retry(() => keys.createProfile());
        _profileId = created.profileId;
        await prefs.setString(_prefsProfileIdKey, _profileId!);
        await secrets.setProfileSecretB64(
          profileId: _profileId!,
          secretB64: created.profileSecretB64,
        );
        _debugRuntimeLog('Re-created server-backed profile after Keys reset');
      }
    }

    String profileSecretB64 =
        (await secrets.getProfileSecretB64(_profileId!)) ?? '';
    if (profileSecretB64.isEmpty) {
      throw StateError(
        'Missing profile secret for this Secretly ID. Use Settings → Reset profile, then recreate.',
      );
    }

    final currentDidBeforeRepairCheck = (_deviceId ?? '').trim();
    final currentHasServerBackedProfile = _isServerBackedProfileId(_profileId);
    if (currentHasServerBackedProfile &&
        currentDidBeforeRepairCheck.isNotEmpty) {
      try {
        final serverDeviceIds = await _listDevicesAuthed(_profileId!);
        final decision =
            AppRuntimeLifecycleCoordinator.resolveMissingCurrentDevice(
              isDesktopOrWebPlatform: _isDesktopOrWebPlatform,
              explicitUserInitiatedRepair: allowMissingCurrentDeviceRepair,
              currentDeviceId: currentDidBeforeRepairCheck,
              serverDeviceIds: serverDeviceIds,
            );
        if (!decision.allowAutoRepair) {
          final message =
              decision.desktopUnauthenticatedMode?.authFlowError ??
              decision.runtimeWarning ??
              'Current device repair is blocked.';
          if (decision.desktopUnauthenticatedMode != null) {
            await _enterDesktopCurrentDeviceRemovedMode(
              prefs: prefs,
              result: decision.desktopUnauthenticatedMode!,
            );
          } else if (decision.runtimeWarning != null) {
            _startupWarning = decision.runtimeWarning;
          }
          throw CurrentDeviceRelinkRequiredException(message);
        }
      } on CurrentDeviceRelinkRequiredException {
        rethrow;
      } catch (_) {
        // Ignore transient list-devices failures and continue with the normal repair path.
      }
    }

    // Register device with proof (bind device_id -> identity key).
    final deviceKeys = DeviceKeys.create();
    // Ключ личности аккаунта живёт рядом, но под СВОИМ ключом хранилища: блок
    // ключей устройства пишется перечислением полей, и откат сборки затёр бы
    // всё, что этот блок не знает. См. AccountIdentity.
    final accountIdentity = AccountIdentity.create();

    Future<bool> registerCurrentDevice() async {
      final currentDid = (_deviceId ?? '').trim();
      if (currentDid.isEmpty) {
        _deviceId = _uuid.v4();
        await prefs.setString(_prefsDeviceIdKey, _deviceId!);
      }

      final identityKp = await deviceKeys.loadIdentityKeyPair(
        profileId: _profileId!,
        deviceId: _deviceId!,
      );
      final identityPubB64 = await identityKeyPubB64();

      // Challenge-bound proofs are one-shot on the server, so a retry must
      // refresh the challenge and rebuild the signature instead of replaying
      // the same proof payload.
      return retry(() async {
        final ch = await keys.deviceChallenge(
          profileId: _profileId!,
          deviceId: _deviceId!,
          profileSecretB64: profileSecretB64,
        );
        // Время сервера, а не устройства — см. пояснение выше по файлу.
        final tsMs = ServerClock.instance.nowMs();
        final msg = AuthSigner.keysRegisterMessage(
          profileId: _profileId!,
          deviceId: _deviceId!,
          identityKeyPubB64: identityPubB64,
          tsMs: tsMs,
          nonceB64: ch.nonceB64,
        );
        final sigB64 = await AuthSigner.signEd25519B64(
          identityKeyPair: identityKp,
          message: msg,
        );
        return keys.registerDeviceProof(
          profileId: _profileId!,
          deviceId: _deviceId!,
          identityKeyPubB64: identityPubB64,
          tsMs: tsMs,
          nonceB64: ch.nonceB64,
          signatureB64: sigB64,
          profileSecretB64: profileSecretB64,
          deviceClass: _currentKeysDeviceClass,
          deviceLabel: _currentKeysDeviceLabel(),
          // И-1 §Д-7: present only after a state-loss rotation. Kept until a
          // registration SUCCEEDS (cleared below) so a crash mid-rotation
          // still frees the dead id's slot on the next attempt.
          replacesDeviceId: prefs.getString(_prefsI1ReplacesHintKey),
        );
      });
    }

    // register_device_proof can fail for a dozen reasons; see
    // `KeysPolicyFailureCode` / server `reg_proof_fail`. We classify each
    // failure into three buckets:
    //   1. Recoverable by device_id rotation (signature_invalid,
    //      device_identity_key_mismatch) — rotate material and retry.
    //   2. Transient (challenge_*, clock_skew, store_error) — retry with a
    //      fresh challenge; surface a clock-check hint on the last attempt.
    //   3. Hard policy (profile_device_limit_reached, desktop companion
    //      limits, profile_secret_*, profile_not_found, etc.) — break out
    //      and let the outer handler present the actual reason.
    // Device_ids we mint-and-abandon while rotating below. A rotation used to
    // leave the abandoned device_id REGISTERED on the keys server (a "zombie"),
    // and peers' list_devices kept returning it → they fanned messages out and
    // routed calls to a mailbox this app no longer reads = permanent one-way
    // loss + instant call failure until a full account recreate. We delete each
    // abandoned device after a successful re-registration (see below).
    final abandonedDeviceIds = <String>[];
    var registerOk = false;
    KeysPolicyFailure? registrationPolicyFailure;
    KeysPolicyFailure? transientRegisterFailure;
    for (var attempt = 0; attempt < 3; attempt++) {
      try {
        registerOk = await registerCurrentDevice();
      } on KeysPolicyFailure catch (error) {
        if (error.isRecoverableByDeviceRotation && attempt < 2) {
          // Wipe local key material, rotate device_id, retry with fresh
          // identity key + fresh challenge.
          final oldDid = (_deviceId ?? '').trim();
          if (oldDid.isNotEmpty) {
            try {
              await deviceKeys.deleteMaterial(
                profileId: _profileId!,
                deviceId: oldDid,
              );
            } catch (_) {
              // ignore
            }
          }
          if (oldDid.isNotEmpty) {
            abandonedDeviceIds.add(oldDid);
            // Persist BEFORE minting the replacement so a crash mid-rotation
            // still leaves a durable record to delete the zombie later.
            await _recordPendingDeviceDelete(
              profileId: _profileId!,
              deviceId: oldDid,
            );
          }
          _deviceId = _uuid.v4();
          await prefs.setString(_prefsDeviceIdKey, _deviceId!);
          await _failOutboxEncryptedUnderOldDevice();
          continue;
        }
        if (error.isTransientRetryable && attempt < 2) {
          transientRegisterFailure = error;
          // Brief backoff so the server challenge bucket doesn't immediately
          // replay the same failure pattern (e.g. right after a clock tick).
          await Future<void>.delayed(
            Duration(milliseconds: 400 * (attempt + 1)),
          );
          continue;
        }
        registrationPolicyFailure = error;
        break;
      }
      if (registerOk) break;
      // Should be unreachable now — every silent ok=false branch was
      // promoted to an error_code. Keep the defensive rotation path in
      // case a legacy Keys server is in front of us during a rolling
      // deploy.
      final oldDid = (_deviceId ?? '').trim();
      if (oldDid.isNotEmpty) {
        try {
          await deviceKeys.deleteMaterial(
            profileId: _profileId!,
            deviceId: oldDid,
          );
        } catch (_) {
          // ignore
        }
      }
      if (oldDid.isNotEmpty) {
        abandonedDeviceIds.add(oldDid);
        await _recordPendingDeviceDelete(
          profileId: _profileId!,
          deviceId: oldDid,
        );
      }
      _deviceId = _uuid.v4();
      await prefs.setString(_prefsDeviceIdKey, _deviceId!);
      await _failOutboxEncryptedUnderOldDevice();
    }

    // ROOT FIX (zombie devices): delete every device_id we abandoned while
    // rotating above from the keys server, so peers' `list_devices` stops
    // returning a dead device_id this app no longer listens on. Without this,
    // peers fan messages out and route calls to the zombie mailbox forever
    // (the "delivery suddenly dies one-way and never recovers after multiple
    // accounts on one device" cascade). Authenticated by the profile secret +
    // the freshly-registered LIVE device (cross-device end-session), so it
    // works even though the zombie is pinned to the old identity key. Each
    // delete is best-effort + time-boxed and must never block keys setup.
    //
    // FIX-C2: the durable ledger drain (deleting the abandoned A1 from keys) is
    // DEFERRED to AFTER the new device's bundle is published below. Deleting A1
    // here would drop A1's published bundle BEFORE A2's is live, leaving a window
    // where a peer's bundle-fetch returns ZERO live devices for this profile —
    // a total one-way blackout until a cold restart. The ledger is durable, so
    // deferring the execution one step is free.

    if (registrationPolicyFailure != null) {
      if (_isDesktopOrWebPlatform) {
        final failure = _desktopLinkFailureFromKeysPolicy(
          registrationPolicyFailure,
        );
        await _enterDesktopUnauthenticatedMode(
          prefs,
          warning: failure.message,
          error: failure.message,
        );
        _setAuthFlowState(_authFlowState, failure: failure);
        throw CurrentDeviceRelinkRequiredException(failure.message);
      }
      // Map a few common policy codes to user-friendly Russian/English
      // messages before the outer handler blasts them into the Settings
      // warning strip. Non-desktop only — desktop flow is above.
      final mappedMessage = _friendlyRegisterProofMessage(
        registrationPolicyFailure,
      );
      throw StateError(mappedMessage);
    }

    // И-1 §Д-7: the eviction hint is spent once a registration succeeded.
    if (registerOk && prefs.getString(_prefsI1ReplacesHintKey) != null) {
      await prefs.remove(_prefsI1ReplacesHintKey);
    }

    // If the first few attempts were transient (challenge_missing, clock_skew,
    // etc.) and eventually succeeded, surface a soft warning once so the
    // operator can correlate with device clock drift if it reappears.
    if (registerOk && transientRegisterFailure != null) {
      _debugRuntimeLog(
        'register_device_proof recovered after transient failure: '
        '${transientRegisterFailure.code} (${transientRegisterFailure.message})',
      );
    }

    // If the profile itself disappeared on the server (e.g. Keys DB was
    // reset by ops) and we are allowed to auto-recreate, do so exactly once
    // — same behaviour as before, now triggered explicitly by
    // `profile_not_found` rather than by an unlabeled `ok=false`.
    if (!registerOk &&
        allowServerProfileAutoCreate &&
        !hasServerBackedProfile) {
      final recreated = await retry(() => keys.createProfile());
      _profileId = recreated.profileId;
      await prefs.setString(_prefsProfileIdKey, _profileId!);
      await secrets.setProfileSecretB64(
        profileId: _profileId!,
        secretB64: recreated.profileSecretB64,
      );
      profileSecretB64 = recreated.profileSecretB64;
      _deviceId = _uuid.v4();
      await prefs.setString(_prefsDeviceIdKey, _deviceId!);
      await _failOutboxEncryptedUnderOldDevice();
      try {
        registerOk = await registerCurrentDevice();
      } on KeysPolicyFailure catch (error) {
        registrationPolicyFailure = error;
      }
    }

    if (registrationPolicyFailure != null) {
      if (_isDesktopOrWebPlatform) {
        final failure = _desktopLinkFailureFromKeysPolicy(
          registrationPolicyFailure,
        );
        await _enterDesktopUnauthenticatedMode(
          prefs,
          warning: failure.message,
          error: failure.message,
        );
        _setAuthFlowState(_authFlowState, failure: failure);
        throw CurrentDeviceRelinkRequiredException(failure.message);
      }
      throw StateError(
        _friendlyRegisterProofMessage(registrationPolicyFailure),
      );
    }

    if (!registerOk) {
      if (_isDesktopOrWebPlatform && hasServerBackedProfile) {
        _startupWarning =
            'Desktop device registration failed for current profile. '
            'Retry in a few seconds; your synced profile is preserved.';
      }
      throw StateError('registerDeviceProof returned ok=false');
    }

    _rememberOwnDeviceId(_deviceId);
    if (_db != null) {
      try {
        await _db!.deviceProfileUpsert(
          deviceId: _deviceId!,
          profileId: _profileId!,
        );
      } catch (_) {
        // ignore
      }
    }

    // Publish keys bundle. A registered device without a published bundle is
    // not deliverable to other peers, so we also repair bundle-missing states.
    final publishedKey =
        '$_prefsKeysPublishedKeyPrefix/${_profileId!}/${_deviceId!}';
    final published = prefs.getBool(publishedKey) ?? false;
    final nowMs = DateTime.now().millisecondsSinceEpoch;
    final lastKeysPublishAtMs = prefs.getInt(_prefsLastKeysPublishAtMsKey) ?? 0;

    // If server lost registration or current device exists without a bundle,
    // force republish even if our prefs say "published".
    //
    // FIX E (requirement #4): this is the idempotent re-publish-on-launch — it
    // is NOT first-registration-only. Every launch we re-query the keys server
    // for THIS device's bundle status and republish (same identity/signed
    // prekeys) whenever the server is missing it, plus a 12 h freshness cadence.
    // That guarantees a peer's fresh `refreshContactDevices` fetch always sees
    // our live device, so the silence sweep on the peer's side can re-handshake
    // to a real mailbox. We intentionally do NOT republish unconditionally on
    // every launch — that would burn one-time-prekeys for no correctness gain;
    // the server-presence check below is the safety net that actually matters.
    bool forcePublish = false;
    try {
      final deviceStatuses = await _listDeviceStatusesAuthed(_profileId!);
      final currentDeviceStatus = deviceStatuses
          .where((status) => status.deviceId == _deviceId)
          .firstOrNull;
      forcePublish =
          currentDeviceStatus == null || !currentDeviceStatus.hasBundle;
      if (forcePublish) {
        DiagLog.event('keys', 'republish_on_launch', {
          'reason': currentDeviceStatus == null ? 'absent' : 'no_bundle',
        });
      }
    } catch (_) {
      try {
        final deviceIds = await _listDevicesAuthed(_profileId!);
        forcePublish = !deviceIds.contains(_deviceId!);
      } catch (_) {}
    }

    if (!forcePublish &&
        published &&
        (lastKeysPublishAtMs <= 0 ||
            (nowMs - lastKeysPublishAtMs) >= _keysPublishRefreshIntervalMs)) {
      forcePublish = true;
    }

    if (!published || forcePublish) {
      final bundle = await deviceKeys.createOrLoadAndAllocateOtk(
        profileId: _profileId!,
        deviceId: _deviceId!,
        allocateOneTimePrekeys: 20,
      );

      final otkHashB64 = await AuthSigner.keysPublishMessageOtkHashB64(
        oneTimePrekeys: bundle.oneTimePrekeys,
      );
      final publishIdentityKp = await deviceKeys.loadIdentityKeyPair(
        profileId: _profileId!,
        deviceId: _deviceId!,
      );

      // ── Ключ личности АККАУНТА и сертификат этого устройства ──────────────
      //
      // Слой 2 модели Signal: номер безопасности перестаёт зависеть от
      // устройства. Устройство подписывает свою личность ключом аккаунта, и
      // получатель, увидев новое устройство контакта, проверяет подпись против
      // известного ему ключа: сошлось — тот же человек, номер не меняется.
      //
      // 🔴 ГЕНЕРАЦИЯ ИМЕННО ЗДЕСЬ, И ЭТО ГЛАВНОЕ УСЛОВИЕ. Публикация ключей идёт
      // из ГЛАВНОГО изолята, а фоновые изоляты (`background_decrypt`,
      // `background_inbox_fetcher`, `background_worker`) трогают ключи
      // устройства без всякого замка. Для нового ключа «его ещё нет» — норма
      // первого запуска после обновления, поэтому позволь мы создавать его где
      // угодно — главный и фоновый изолят сделали бы ДВА РАЗНЫХ ключа, то есть
      // расщепили бы личность человека. Это класс «два писателя» из И-3.
      //
      // 🔴 ОТКАЗ В ОТКРЫТУЮ. Любая беда с ключом аккаунта означает публикацию
      // БЕЗ него, а не отказ от публикации: публикация ключей — ещё и пульс
      // живости устройства, и сорвав её, мы стоили бы человеку доставки
      // сообщений ради косметики номера безопасности.
      String? publishAccountPubB64;
      String? publishDeviceCertB64;
      try {
        final accountSeedB64 = await accountIdentity.ensureSeedB64(
          profileId: _profileId!,
        );
        publishAccountPubB64 = await AccountIdentity.publicKeyB64FromSeed(
          accountSeedB64,
        );
        publishDeviceCertB64 = await accountIdentity.signDeviceCertificate(
          profileId: _profileId!,
          deviceId: _deviceId!,
          deviceIdentityPubB64: bundle.identityKeyPubB64,
        );
        DiagLog.event('acct', 'account_identity_ready', <String, Object?>{
          'has_cert': publishDeviceCertB64 != null,
        });
      } catch (e) {
        publishAccountPubB64 = null;
        publishDeviceCertB64 = null;
        DiagLog.event('acct', 'account_identity_unavailable', <String, Object?>{
          'reason': e.runtimeType.toString(),
        });
      }

      final ok = await retry(() async {
        // 🔴 ИСПРАВЛЕННОЕ ВРЕМЯ, А НЕ ЧАСЫ УСТРОЙСТВА.
        //
        // Сервер отвергает подпись, если штамп разошёлся с его временем больше
        // чем на пять минут. Публикация ключей была ЕДИНСТВЕННЫМ подписанным
        // запросом к серверу ключей, который брал сырое `DateTime.now()`, —
        // остальные восемь давно берут поправку. Поэтому у человека с уплывшими
        // часами (ноутбук поспал, батарея села) ломалась ровно она одна: всё
        // остальное работало, а спаривание упиралось в «QR недоступен» с
        // `publishKeys returned ok=false`. Именно это и выглядит как «работает
        // странно и непонятно».
        //
        // Тот же дефект на пути реле разобран 12.09.2026: там из 13 отказов 13
        // были «часы отстают», ни одного «спешат», — то есть причина
        // систематическая, а не в часах людей.
        final publishTsMs = ServerClock.instance.nowMs();
        final publishNonceB64 = AuthSigner.randomNonceB64(bytes: 16);
        final publishMsg = AuthSigner.keysPublishMessage(
          profileId: _profileId!,
          deviceId: _deviceId!,
          identityKeyPubB64: bundle.identityKeyPubB64,
          signedPrekeyPubB64: bundle.signedPrekeyPubB64,
          signedPrekeySigB64: bundle.signedPrekeySigB64,
          oneTimePrekeysSha256B64: otkHashB64,
          tsMs: publishTsMs,
          nonceB64: publishNonceB64,
        );
        final publishSigB64 = await AuthSigner.signEd25519B64(
          identityKeyPair: publishIdentityKp,
          message: publishMsg,
        );

        return keys.publishKeys(
          profileId: _profileId!,
          deviceId: _deviceId!,
          identityKeyPubB64: bundle.identityKeyPubB64,
          signedPrekeyPubB64: bundle.signedPrekeyPubB64,
          signedPrekeySigB64: bundle.signedPrekeySigB64,
          oneTimePrekeys: bundle.oneTimePrekeys,
          tsMs: publishTsMs,
          nonceB64: publishNonceB64,
          signatureB64: publishSigB64,
          profileSecretB64: profileSecretB64,
          accountIdentityPubB64: publishAccountPubB64,
          deviceCertB64: publishDeviceCertB64,
        );
      });
      await prefs.setBool(publishedKey, ok);
      if (!ok) {
        await prefs.remove(_prefsLastKeysPublishAtMsKey);
        throw StateError('publishKeys returned ok=false');
      }
      await prefs.setInt(_prefsLastKeysPublishAtMsKey, nowMs);
    }

    // ROOT FIX (one-way blackout): NOW that the current device (A2) is
    // registered AND its bundle is published — so peers can always resolve at
    // least one live published device for this profile — delete the abandoned
    // device_ids (A1...) from the keys server. Doing this AFTER publish (not
    // before) removes the window where A1's bundle was gone but A2's wasn't yet
    // live. Best-effort + durable (ledger); never blocks setup.
    {
      final liveDid = (_deviceId ?? '').trim();
      final pid = (_profileId ?? '').trim();
      if (pid.isNotEmpty && liveDid.isNotEmpty) {
        await _drainPendingDeviceDeletes(
          currentProfileId: pid,
          requesterDeviceId: liveDid,
        );
      }
    }

    if (allowMissingCurrentDeviceRepair) {
      await prefs.remove(_prefsAllowMissingCurrentDeviceRepairOnceKey);
    }

    // R1 monetization bootstrap: profile + device + keys are all live here.
    // Fire-and-forget, idempotent, fails open (TZ-MONETIZE-01 §C-1).
    unawaited(runMonetizationR1Bootstrap());

    // И-1 §Д-4: the rotated identity is registered & published — nudge recent
    // peers now instead of waiting for their pull heuristics.
    if (prefs.getBool(_prefsI1AnnouncePendingKey) ?? false) {
      unawaited(_runI1RotationAnnounceSweep());
    }

    return true;
  }

  /// И-1 §Д-4: one silent no-op control ("typing stop") to each recent 1:1
  /// peer after a rotation.
  ///
  /// Every shipped client consumes a stop-typing command silently (stopping a
  /// typing state that never started changes nothing), so the CONTENT is
  /// compatibility-free; the value is the TRANSPORT side effect — a fresh
  /// X3DH prekey wire from the NEW device_id, which fires the peer's
  /// learn-on-receive, refreshes their copy of our device list and prunes the
  /// dead id. Privacy holds: the announce is E2E like any message, the server
  /// learns nothing about the contact graph it did not already route.
  ///
  /// Trickled with pauses, best-effort per peer. The pending marker clears
  /// only after a completed sweep, so a crash retries next launch — the
  /// control is idempotent and invisible. After a DB-loss rotation the convo
  /// list is empty and this is a no-op by construction; it mainly serves
  /// restores, which bring conversations back.
  // Reentrancy guard: keys setup can run twice in quick succession (observed
  // in the 2026-07-21 field test — two sweeps 500 ms apart), and both would
  // pass the pending-marker check before either clears it.
  bool _i1AnnounceSweepInFlight = false;

  Future<void> _runI1RotationAnnounceSweep() async {
    final prefs = _prefs;
    final db = _db;
    final myPid = (_profileId ?? '').trim();
    if (prefs == null || db == null || myPid.isEmpty) return;
    if (_i1AnnounceSweepInFlight) return;
    _i1AnnounceSweepInFlight = true;
    try {
      // Let the just-published bundle settle before fanning out.
      await Future<void>.delayed(const Duration(seconds: 3));
      final rows = await db.convoList(limit: 200);
      final peers = <String>[];
      for (final row in rows) {
        final cid = ((row['convo_id'] as String?) ?? '').trim();
        if (cid.isEmpty ||
            cid == myPid ||
            cid.startsWith('group:') ||
            cid.startsWith('req:') ||
            cid.startsWith('dev:') ||
            _isDemoConvoId(cid)) {
          continue;
        }
        peers.add(cid);
        if (peers.length >= 50) break;
      }
      var sent = 0;
      for (final peer in peers) {
        try {
          await sendTypingState(
            peerProfileId: peer,
            convoId: peer,
            typing: false,
          );
          sent += 1;
        } catch (_) {
          // Best-effort per peer; the pull heuristics remain the backstop.
        }
        await Future<void>.delayed(const Duration(milliseconds: 250));
      }
      await prefs.remove(_prefsI1AnnouncePendingKey);
      DiagLog.event('i1', 'announce_swept', {'peers': sent});
    } catch (e) {
      DiagLog.event('i1', 'announce_failed', {'err': _shortErrorTag(e)});
    } finally {
      _i1AnnounceSweepInFlight = false;
    }
  }

  String _currentServerBindingString() {
    return _serverBindingString(keys: keysBaseUrl, relay: relayHttpBaseUrl);
  }

  String _environmentServerBindingString() {
    return _serverBindingString(
      keys: Uri.parse(_keysBaseUrlEnv),
      relay: Uri.parse(_resolvedRelayHttpBaseUrlEnv()),
    );
  }

  String _serverBindingString({required Uri keys, required Uri relay}) {
    String normalize(Uri u) {
      final port = u.hasPort ? u.port : (u.scheme == 'https' ? 443 : 80);
      return '${u.scheme}://${u.host}:$port';
    }

    return 'keys=${normalize(keys)};relay=${normalize(relay)}';
  }

  Future<void> _persistServerBindingIfMissing(SharedPreferences prefs) async {
    final v = prefs.getString(_prefsServerBindingKey);
    if (v != null && v.isNotEmpty) return;
    await prefs.setString(
      _prefsServerBindingKey,
      _currentServerBindingString(),
    );
  }

  Future<void> resetProfileAndLocalData() async {
    final oldProfileId = _profileId;
    final oldDeviceId = _deviceId;

    // Stop background tasks.
    _pumpTimer?.cancel();
    _mainAliveHeartbeatTimer?.cancel();
    _pumpTimer = null;
    _serviceWatchdogTimer?.cancel();
    _serviceWatchdogTimer = null;
    _quarantineRecoverySweepTimer?.cancel();
    _quarantineRecoverySweepTimer = null;

    await _closeRuntimeNetworkClientsForDiscard();

    // Close DB before deleting files.
    try {
      await _db?.close();
    } catch (_) {}
    _db = null;

    await AppDb.deleteLocalDatabaseFiles();

    await _clearLocalProfileMediaCaches();

    final prefs = _prefs ?? await SharedPreferences.getInstance();
    _prefs = prefs;

    // Кто стёр личность — записать ДО стирания: потом улики нет.
    await IdentityJournal.recordProfileIdCleared(
      by: 'reset_profile_and_local_data',
      nowMs: DateTime.now().millisecondsSinceEpoch,
      previousProfileId: prefs.getString(_prefsProfileIdKey),
      previousDeviceId: prefs.getString(_prefsDeviceIdKey),
      deviceIdClearedToo: true,
    );
    await prefs.remove(_prefsProfileIdKey);
    await prefs.remove(_prefsDeviceIdKey);
    await prefs.remove(_prefsServerBindingKey);
    await prefs.remove(_prefsRelayNextSeqKey);
    await prefs.remove(_prefsAllowMissingCurrentDeviceRepairOnceKey);
    await prefs.remove(_prefsMyAvatarPathKey);
    await prefs.remove(_prefsMyAvatarOriginalPathKey);
    await prefs.remove(_prefsProfileIconAssetPathKey);
    await prefs.remove(_prefsProfileAvatarGradientIndexKey);
    await prefs.remove(_prefsProfileAvatarIconScaleKey);
    await prefs.remove(_prefsMyNicknameKey);
    await prefs.remove(_prefsMyBioKey);
    await prefs.remove(_prefsShareNicknameInQrKey);
    await prefs.remove(_prefsDiscoverableByNicknameKey);
    await prefs.remove(_prefsAllowNicknameLookupKey);
    await prefs.remove(_prefsPrivacySyncContactsKey);
    await prefs.remove(_prefsPrivacyArchiveUnknownKey);
    await prefs.remove(_prefsPrivacyAudienceMapKey);
    await prefs.remove(_prefsPrivacyDeleteAccountMonthsKey);
    await prefs.remove(_prefsPendingSafeImportKey);
    await prefs.remove(_prefsPersonalConvoIdsKey);
    await prefs.remove(_prefsProfileGalleryPathsKey);
    await prefs.remove(_prefsProfileBackgroundPathsKey);
    await prefs.remove(_prefsProfileMusicPathsKey);
    await prefs.remove(_prefsSafeBackupAutoEnabledKey);
    await prefs.remove(_prefsSafeBackupAutoServerEnabledKey);
    await prefs.remove(_prefsSafeBackupAutoDeviceEnabledKey);
    await prefs.remove(_prefsSafeBackupIncludeMediaKey);
    await prefs.remove(_prefsSafeBackupAutoIntervalMinKey);
    await prefs.remove(_prefsSafeBackupLastAutoAttemptAtMsKey);
    await prefs.remove(_prefsSafeBackupLastAutoSuccessAtMsKey);
    await prefs.remove(_prefsSafeBackupLastAutoErrorKey);
    await prefs.remove(_prefsSafeBackupLastDevicePathKey);
    await prefs.remove(_prefsSafeBackupExternalFilePathKey);
    await prefs.remove(_prefsSafeBackupLastDeviceSavedAtMsKey);
    // A replaced account must not inherit the previous one's overwrite
    // bar: its backup lives under a different profile row, so there is
    // nothing to protect and the guard would block every backup forever.
    await prefs.remove(_prefsSafeBackupLastEventCountKey);
    await prefs.remove(_prefsPendingStartupWarningKey);
    await resetOnboardingComplete(prefs: prefs);
    await _setDesktopAuthRequired(prefs, _isDesktopOrWebPlatform);
    _setAuthFlowState(AuthFlowState.unauthenticated);
    _knownOwnDeviceIds
      ..clear()
      ..add((_deviceId ?? '').trim());
    // 🔴 И С ДИСКА ТОЖЕ (16.09.2026). Набор в памяти чистился, а список в
    // настройках оставался — и следующий запуск возвращал устройства ПРЕЖНЕГО
    // аккаунта уже новому. Смена аккаунта не наследует чужую историю устройств.
    await prefs.remove(_prefsKnownOwnDeviceIdsKey);

    final keysToRemove = prefs
        .getKeys()
        .where((k) => k.startsWith(_prefsKeysPublishedKeyPrefix))
        .toList(growable: false);
    for (final k in keysToRemove) {
      await prefs.remove(k);
    }

    try {
      if (oldProfileId != null &&
          oldProfileId.isNotEmpty &&
          oldDeviceId != null &&
          oldDeviceId.isNotEmpty) {
        await _deleteDeviceRegistrationFromServer(
          profileId: oldProfileId,
          deviceId: oldDeviceId,
        );
        // FIX-C2 (Z4): flush any still-pending zombie deletes for the OLD
        // profile NOW, while we still hold its secret + this device's signing
        // key. After the reset the profile changes and those entries become
        // un-signable (cross-profile delete is forbidden), so this is the last
        // chance to clean them client-side; the server last_seen TTL is the
        // backstop for whatever doesn't confirm here.
        await _drainPendingDeviceDeletes(
          currentProfileId: oldProfileId,
          requesterDeviceId: oldDeviceId,
        );
      }
    } catch (_) {
      // ignore
    }

    // Best-effort: remove profile secret + device key material for the previous identity.
    try {
      if (oldProfileId != null && oldProfileId.isNotEmpty) {
        final secrets = SecureSecrets.create();
        await secrets.deleteProfileSecret(oldProfileId);
        await secrets.deleteSafeBackupAutoPassword(oldProfileId);
      }
      if (oldProfileId != null &&
          oldProfileId.isNotEmpty &&
          oldDeviceId != null &&
          oldDeviceId.isNotEmpty) {
        await DeviceKeys.create().deleteMaterial(
          profileId: oldProfileId,
          deviceId: oldDeviceId,
        );
      }
    } catch (_) {
      // ignore
    }

    _applyRuntimeResetResult(
      AppRuntimeLifecycleCoordinator.restartReset(
        desktopLinkRequests: _desktopLinkRequests,
        cancelAwaitingDesktopLinkRequests: true,
        knownOwnDeviceIds: <String>[(_deviceId ?? '').trim()],
      ),
    );
    await _saveDesktopLinkRequestsToPrefs();

    _changed.add(null);
    _restartRequested.add(null);
  }

  Future<void> deleteAccountEverywhere() async {
    await IdentityJournal.record(
      reason: IdentityJournal.reasonUserInitiated,
      nowMs: DateTime.now().millisecondsSinceEpoch,
      previousProfileId: _profileId,
      previousDeviceId: _deviceId,
      detail: const <String, Object?>{'action': 'delete_account'},
    );
    final pid = (_profileId ?? '').trim();
    final did = (_deviceId ?? '').trim();
    if (pid.isEmpty || did.isEmpty || pid.startsWith('LOCAL-')) {
      await resetProfileAndLocalData();
      return;
    }

    final normalizedProfileSecret =
        ((await SecureSecrets.create().getProfileSecretB64(pid)) ?? '').trim();
    if (normalizedProfileSecret.isEmpty) {
      throw StateError('Profile secret is missing');
    }

    _pumpTimer?.cancel();
    _mainAliveHeartbeatTimer?.cancel();
    _pumpTimer = null;
    _serviceWatchdogTimer?.cancel();
    _serviceWatchdogTimer = null;
    _quarantineRecoverySweepTimer?.cancel();
    _quarantineRecoverySweepTimer = null;

    // FIX-C7 (Z5): unregister the push token BEFORE tearing the account down, so
    // the shared per-phone FCM token stops waking on behalf of this (about to be
    // deleted) device. Done while the relay is still connected; best-effort.
    try {
      await _relay
          ?.setPushToken(
            token: '',
            platform: _resolvePushPlatform().isEmpty
                ? 'android'
                : _resolvePushPlatform(),
            enabled: false,
          )
          .timeout(const Duration(seconds: 5));
    } catch (_) {
      // never block account deletion on push teardown
    }

    try {
      await _relay?.disconnect();
    } catch (_) {
      // ignore disconnect failures before deletion
    }

    final keys = _keys ?? KeysClient(baseUrl: keysBaseUrl);
    _keys = keys;

    final deviceIds = <String>{did}..removeWhere((id) => id.isEmpty);
    try {
      deviceIds.addAll(await _listDevicesAuthed(pid));
    } catch (_) {
      deviceIds.addAll(_knownOwnDeviceIds.map((id) => id.trim()));
      deviceIds.removeWhere((id) => id.isEmpty);
    }

    // FIX-C7 (Z5): the relay + keys deletes are now BEST-EFFORT (bounded retry)
    // and NEVER block the local wipe. Previously a single `ok=false` (transient
    // relay/keys hiccup, offline) threw and skipped resetProfileAndLocalData() —
    // leaving a half-deleted account: server data intact, local data intact, and
    // the user unable to retry cleanly. The user's intent is "remove me"; the
    // local identity wipe must always complete. Whatever does not delete server-
    // side is reaped by the keys last_seen TTL.
    var relayOk = false;
    final existingRelay = _relay;
    final relay =
        existingRelay ?? _temporaryRelayClientForAccountDeletion(pid, did);
    try {
      for (var attempt = 0; attempt < 3 && !relayOk; attempt++) {
        try {
          relayOk = await relay
              .deleteProfileData(
                profileId: pid,
                deviceIds: deviceIds.toList(growable: false),
              )
              .timeout(const Duration(seconds: 10));
        } catch (_) {
          await Future<void>.delayed(
            Duration(milliseconds: 400 * (attempt + 1)),
          );
        }
      }
    } finally {
      if (existingRelay == null) {
        try {
          await relay.close();
        } catch (_) {}
      }
    }

    var keysOk = false;
    try {
      final identityKeyPair = await DeviceKeys.create().loadIdentityKeyPair(
        profileId: pid,
        deviceId: did,
      );
      for (var attempt = 0; attempt < 3 && !keysOk; attempt++) {
        try {
          final tsMs = ServerClock.instance.nowMs();
          final nonceB64 = AuthSigner.randomNonceB64(bytes: 16);
          final message = AuthSigner.keysDeleteProfileMessage(
            requesterDeviceId: did,
            profileId: pid,
            tsMs: tsMs,
            nonceB64: nonceB64,
          );
          final signatureB64 = await AuthSigner.signEd25519B64(
            identityKeyPair: identityKeyPair,
            message: message,
          );
          keysOk = await keys
              .deleteProfile(
                profileId: pid,
                profileSecretB64: normalizedProfileSecret,
                requesterDeviceId: did,
                tsMs: tsMs,
                nonceB64: nonceB64,
                signatureB64: signatureB64,
              )
              .timeout(const Duration(seconds: 10));
        } catch (_) {
          await Future<void>.delayed(
            Duration(milliseconds: 400 * (attempt + 1)),
          );
        }
      }
    } catch (_) {
      // identity key load failed — fall through to the local wipe anyway
    }

    if (!relayOk || !keysOk) {
      DiagLog.event('keys', 'account_delete_partial', {
        'relay_ok': relayOk,
        'keys_ok': keysOk,
      });
    }

    await resetProfileAndLocalData();
  }

  RelayClient _temporaryRelayClientForAccountDeletion(
    String profileId,
    String deviceId,
  ) {
    final db = _db;
    if (db == null) {
      throw StateError('Local database is not ready');
    }
    return RelayClient(
      db: db,
      deviceId: deviceId,
      selfProfileId: profileId,
      deviceKeys: DeviceKeys.create(),
      clientBuild: AppPackageInfo.buildNumberFromEnv,
      wsUrl: relayWsUrl,
      httpBaseUrl: relayHttpBaseUrl,
      onDelivered: ({required msgId, required ciphertextB64}) async => false,
      loadNextSeq: () async => 1,
      saveNextSeq: (_) async {},
    );
  }

  Future<void> createNewServerProfileForCurrentDevice() async {
    await IdentityJournal.record(
      reason: IdentityJournal.reasonUserInitiated,
      nowMs: DateTime.now().millisecondsSinceEpoch,
      previousProfileId: _profileId,
      previousDeviceId: _deviceId,
      detail: const <String, Object?>{'action': 'new_profile'},
    );
    final prefs = _prefs ?? await SharedPreferences.getInstance();
    _prefs = prefs;

    if (_isDesktopOrWebPlatform) {
      await resetProfileAndLocalData();
      return;
    }

    final oldProfileId = (_profileId ?? '').trim();
    final oldDeviceId = (_deviceId ?? '').trim();

    _pumpTimer?.cancel();
    _mainAliveHeartbeatTimer?.cancel();
    _pumpTimer = null;
    _serviceWatchdogTimer?.cancel();
    _serviceWatchdogTimer = null;
    _quarantineRecoverySweepTimer?.cancel();
    _quarantineRecoverySweepTimer = null;

    await _closeRuntimeNetworkClientsForDiscard();

    try {
      await _db?.close();
    } catch (_) {
      // ignore
    }
    _db = null;

    await AppDb.deleteLocalDatabaseFiles();
    await _clearLocalProfileMediaCaches();
    final resetPrefs = _prefs ?? await SharedPreferences.getInstance();
    // The overwrite bar belongs to the account being replaced; keeping it
    // would block every backup of the new one (nothing to protect).
    await resetPrefs.remove(_prefsSafeBackupLastEventCountKey);

    if (oldProfileId.isNotEmpty) {
      try {
        if (oldDeviceId.isNotEmpty) {
          await _deleteDeviceRegistrationFromServer(
            profileId: oldProfileId,
            deviceId: oldDeviceId,
          );
          // FIX-C2 (Z4): flush pending zombie deletes for the OLD profile while
          // we can still sign for it (the new profile can't). Server last_seen
          // TTL backstops anything that doesn't confirm.
          await _drainPendingDeviceDeletes(
            currentProfileId: oldProfileId,
            requesterDeviceId: oldDeviceId,
          );
        }
      } catch (_) {
        // ignore
      }
      try {
        await SecureSecrets.create().deleteProfileSecret(oldProfileId);
      } catch (_) {
        // ignore
      }
      try {
        if (oldDeviceId.isNotEmpty) {
          await DeviceKeys.create().deleteMaterial(
            profileId: oldProfileId,
            deviceId: oldDeviceId,
          );
        }
      } catch (_) {
        // ignore
      }
    }

    _profileId = null;
    _deviceId = _uuid.v4();
    // Кто стёр личность — записать ДО стирания: потом улики нет.
    await IdentityJournal.recordProfileIdCleared(
      by: 'create_new_server_profile',
      nowMs: DateTime.now().millisecondsSinceEpoch,
      previousProfileId: prefs.getString(_prefsProfileIdKey),
      previousDeviceId: prefs.getString(_prefsDeviceIdKey),
      deviceIdClearedToo: false,
    );
    await prefs.remove(_prefsProfileIdKey);
    await prefs.remove(_prefsServerBindingKey);
    await prefs.remove(_prefsRelayNextSeqKey);
    await prefs.remove(_prefsAllowMissingCurrentDeviceRepairOnceKey);
    await prefs.remove(_prefsMyAvatarPathKey);
    await prefs.remove(_prefsMyAvatarOriginalPathKey);
    await prefs.remove(_prefsPrivacyDeleteAccountMonthsKey);
    await prefs.setString(_prefsDeviceIdKey, _deviceId!);
    _privacyDeleteAccountMonths = 24;

    final keysToRemove = prefs
        .getKeys()
        .where((k) => k.startsWith(_prefsKeysPublishedKeyPrefix))
        .toList(growable: false);
    for (final k in keysToRemove) {
      await prefs.remove(k);
    }

    final keys = _keys ?? KeysClient(baseUrl: keysBaseUrl);
    _keys = keys;
    await _ensureKeysSetup(
      prefs: prefs,
      keys: keys,
      allowServerProfileAutoCreate: true,
    );
    await _setDesktopAuthRequired(prefs, false);
    _setAuthFlowState(AuthFlowState.authenticated);
    await _persistServerBindingIfMissing(prefs);
    _applyRuntimeResetResult(
      AppRuntimeLifecycleCoordinator.restartReset(
        desktopLinkRequests: _desktopLinkRequests,
        cancelAwaitingDesktopLinkRequests: true,
        nextDeviceId: _deviceId,
        knownOwnDeviceIds: <String>[(_deviceId ?? '').trim()],
      ),
    );
    await _saveDesktopLinkRequestsToPrefs();

    _changed.add(null);
    _restartRequested.add(null);
  }

  Future<void> restoreFromRecoveryKit(RecoveryKitPlainV1 kit) async {
    final restoredKit = (() {
      try {
        return RecoveryKitPlainV1.fromJson(kit.toJson());
      } catch (error) {
        throw describeEncryptedRestoreError(error);
      }
    })();

    // И-1 stage c: the kit restore wipes the DB below — an empty session
    // store. Under the verified switch it comes up as a NEW device; the kit's
    // id is NOT ledgered for deletion (its writer may still be alive), same
    // reasoning as the safe-backup restore.
    final rotateOnRestore =
        !_isDesktopOrWebPlatform &&
        await _resolveIdentityRotationFlagBounded();
    final restoredKitDeviceId = restoredKit.deviceId.trim();
    final activeDeviceId = rotateOnRestore ? _uuid.v4() : restoredKitDeviceId;
    DiagLog.event('i1', 'state_loss', {
      'path': 'restore_kit',
      'new_device': rotateOnRestore,
    });

    // Stop background tasks.
    _pumpTimer?.cancel();
    _mainAliveHeartbeatTimer?.cancel();
    _pumpTimer = null;
    _serviceWatchdogTimer?.cancel();
    _serviceWatchdogTimer = null;
    _quarantineRecoverySweepTimer?.cancel();
    _quarantineRecoverySweepTimer = null;

    await _closeRuntimeNetworkClientsForDiscard();

    try {
      await _db?.close();
    } catch (_) {
      // ignore
    }
    _db = null;

    await AppDb.deleteLocalDatabaseFiles();

    await _clearLocalProfileMediaCaches();

    final prefs = _prefs ?? await SharedPreferences.getInstance();
    _prefs = prefs;

    // Clear profile-local state (keep UI prefs like darkMode/nickname settings).
    // Кто стёр личность — записать ДО стирания: потом улики нет.
    await IdentityJournal.recordProfileIdCleared(
      by: 'restore_from_recovery_kit',
      nowMs: DateTime.now().millisecondsSinceEpoch,
      previousProfileId: prefs.getString(_prefsProfileIdKey),
      previousDeviceId: prefs.getString(_prefsDeviceIdKey),
      deviceIdClearedToo: true,
    );
    await prefs.remove(_prefsProfileIdKey);
    await prefs.remove(_prefsDeviceIdKey);
    await prefs.remove(_prefsServerBindingKey);
    await prefs.remove(_prefsRelayNextSeqKey);
    await prefs.remove(_prefsAllowMissingCurrentDeviceRepairOnceKey);
    await prefs.remove(_prefsMyAvatarPathKey);
    await prefs.remove(_prefsMyAvatarOriginalPathKey);
    await prefs.remove(_prefsPrivacyDeleteAccountMonthsKey);

    final keysToRemove = prefs
        .getKeys()
        .where((k) => k.startsWith(_prefsKeysPublishedKeyPrefix))
        .toList(growable: false);
    for (final k in keysToRemove) {
      await prefs.remove(k);
    }

    await _setDesktopAuthRequired(prefs, false);

    // Apply recovered identity.
    await prefs.setString(_prefsProfileIdKey, restoredKit.profileId);
    await prefs.setString(_prefsDeviceIdKey, activeDeviceId);
    await prefs.setString(_prefsServerBindingKey, restoredKit.serverBinding);
    await prefs.setInt(_prefsRelayNextSeqKey, 1);
    if (rotateOnRestore) {
      await prefs.setBool(_prefsAllowMissingCurrentDeviceRepairOnceKey, true);
      await prefs.setBool(_prefsI1AnnouncePendingKey, true);
      DiagLog.event('i1', 'rotated', {
        'reason': 'restore_kit',
        'old': DiagLog.pfx(restoredKitDeviceId),
        'new': DiagLog.pfx(activeDeviceId),
      });
    }

    // Persist secrets + device key material.
    final secrets = SecureSecrets.create();
    await secrets.setProfileSecretB64(
      profileId: restoredKit.profileId,
      secretB64: restoredKit.profileSecretB64,
    );
    if (!rotateOnRestore) {
      await DeviceKeys.create().importMaterialJson(
        profileId: restoredKit.profileId,
        deviceId: restoredKit.deviceId,
        rawJson: restoredKit.deviceKeysMaterialJson,
      );
    }
    // 🔴 Ключ личности АККАУНТА переносится ВСЕГДА, снаружи условия про ротацию.
    // Ротация означает новое УСТРОЙСТВО, но человек тот же, и именно в этом весь
    // смысл слоя 2: номер безопасности принадлежит человеку. Импортируй мы сид
    // внутри `if (!rotateOnRestore)`, восстановление с ротацией теряло бы ключ,
    // на новом устройстве родился бы другой, и у ВСЕХ собеседников выскочило бы
    // «номер безопасности изменился» — то есть путь восстановления сам приносил
    // бы ту болезнь, от которой лечит эта работа.
    //
    // Отказ беззвучный: без сида клиент просто ведёт себя как старая сборка, а
    // сорвать здесь восстановление значило бы обменять доступ к аккаунту на
    // косметику номера.
    // 🔴 device_id ИЗ КОПИИ — свой, и его надо запомнить навсегда (08.08.2026,
    // поле: «после восстановления все пузыри стали как пузыри собеседника»).
    //
    // Все восстановленные сообщения подписаны ЭТИМ идентификатором. Текущее
    // устройство после восстановления другое, а старое с сервера вытесняется —
    // значит без этой строки узнать его больше НЕОТКУДА, и свои сообщения
    // навсегда остаются слева. Тот же приём уже применён при связке с десктопом
    // (`seededOwnDeviceIds`), просюда его просто не донесли.
    await _rememberOwnDeviceIds(<String>[restoredKit.deviceId]);

    final restoredAccountSeed = restoredKit.accountIdentitySeedB64;
    if (restoredAccountSeed != null && restoredAccountSeed.isNotEmpty) {
      try {
        await AccountIdentity.create().importSeedB64(
          profileId: restoredKit.profileId,
          seedB64: restoredAccountSeed,
        );
      } catch (e) {
        DiagLog.event('acct', 'account_identity_restore_failed', <String, Object?>{
          'reason': e.runtimeType.toString(),
        });
      }
    }
    // else: fresh identity material is minted on demand under activeDeviceId
    // by the keys setup — the kit's material belongs to the (possibly living)
    // old device.

    _applyRuntimeResetResult(
      AppRuntimeLifecycleCoordinator.restartReset(
        desktopLinkRequests: _desktopLinkRequests,
        cancelAwaitingDesktopLinkRequests: true,
        nextDeviceId: activeDeviceId,
        knownOwnDeviceIds: <String>[
          activeDeviceId,
          if (restoredKitDeviceId.isNotEmpty &&
              restoredKitDeviceId != activeDeviceId)
            restoredKitDeviceId,
        ],
      ),
    );
    await _saveDesktopLinkRequestsToPrefs();

    _changed.add(null);
    _restartRequested.add(null);
  }

  // ── ЗАМЕР ЗАПУСКА (03.08.2026) ─────────────────────────────────────────────
  //
  // 🔴 Полевой отчёт: «если полчаса-час не заходить, следующий вход занимает
  // 12-15 секунд». Проверить это было НЕЧЕМ: в `lifecycle` есть только
  // background/foreground/flush, и ни одного события о фазах запуска. Причину
  // оставалось угадывать, а угаданное не чинят.
  //
  // Здесь ровно измерение и ничего больше: `init()` расставляет отметки на
  // границах своих ожиданий, каждая печатает СВОЮ длительность и накопленный
  // итог. Стоимость — один Stopwatch и десяток строк в logcat за запуск.
  //
  // Смотреть так:  adb logcat -s Sly/Diag | grep startup.
  // Разница между `startup.begin` и меткой запуска активности в logcat даёт
  // время самого движка — то, на что наш код не влияет вовсе.
  final Stopwatch _startupWatch = Stopwatch();
  int _startupLastMarkUs = 0;

  /// Последний замер: «фаза=мс», в порядке прохождения. Показывается в
  /// диагностике, чтобы не заставлять человека снимать logcat.
  final List<String> _startupTrace = <String>[];

  String get startupTrace =>
      _startupTrace.isEmpty ? '—' : _startupTrace.join(', ');

  void _startupMark(String phase) {
    if (!_startupWatch.isRunning) return;
    final nowUs = _startupWatch.elapsedMicroseconds;
    final stepMs = ((nowUs - _startupLastMarkUs) / 1000).round();
    _startupLastMarkUs = nowUs;
    // В список берём только заметные фазы: он нужен, чтобы найти виновника,
    // а не чтобы перечислить всё, что заняло ноль. В logcat идёт всё.
    if (stepMs >= 20) {
      _startupTrace.add('$phase=${stepMs}ms');
    }
    DiagLog.event('startup', phase, {
      'ms': stepMs,
      'total_ms': (nowUs / 1000).round(),
    });
  }

  Future<void> init() async {
    _startupWatch
      ..reset()
      ..start();
    _startupLastMarkUs = 0;
    _startupTrace.clear();
    DiagLog.event('startup', 'begin', const <String, Object?>{});
    final prefs = await SharedPreferences.getInstance();
    _prefs = prefs;
    _startupMark('prefs');
    // И-4 (2026-07-24): surface the session-reset gate states at startup so a
    // field-proof build's flags are verifiable the moment the app opens — no
    // desync test needed. These read the --dart-define via a const (see the flag
    // declarations), so they reflect the ACTUAL compiled values.
    DiagLog.event('lifecycle', 'i4_flags', {
      'reactive_reset_gate': i4aReactiveResetGateEnabled,
      'keep_session_on_prune': i4hKeepSessionOnDevicePrune,
      'resend_on_reset': i4kResendUndeliveredOnReset,
      'min_consec': _i4ReactiveResetMinConsecutiveFailures,
    });
    // FIX-C1 (Z1 desync defense): on a genuinely fresh install (sentinel absent)
    // with NO profile_id in prefs, purge any identity material that survived in
    // the secure store from a prior install (iOS Keychain survives uninstall;
    // some Android OEM transfers copy the store but not the Keystore key). Left
    // in place, that orphaned material pairs with wiped prefs to drive the
    // device_id/identity desync that mints a zombie. Guarded so existing users
    // (profile_id present) are never touched — we only set the sentinel for
    // them. Best-effort; preserves the DB passphrase, crypto key, and app lock.
    if (!prefs.containsKey(_prefsInstallSentinelKey)) {
      final hasProfile = (prefs.getString(_prefsProfileIdKey) ?? '')
          .trim()
          .isNotEmpty;
      if (!hasProfile && !_isDesktopOrWebPlatform) {
        try {
          final purged = await SecureSecrets.create()
              .purgeOrphanedIdentityMaterial();
          if (purged > 0) {
            DiagLog.event('keys', 'fresh_install_purge', {'removed': purged});
          }
        } catch (_) {
          // never block boot on hygiene
        }
      }
      await prefs.setBool(_prefsInstallSentinelKey, true);
    }
    _everHadEntitlement = prefs.getBool(_prefsEverHadEntitlementKey) ?? false;
    // И-1: the rotation switch must be known BEFORE the database opens below —
    // that is where a state loss is detected. Cached from the last session
    // whose /v1/config response verified; absent → dormant.
    _identityRotationOnStateLossEnabled =
        prefs.getBool(_prefsI1RotationEnabledKey) ?? false;
    // Configure the premium-cosmetics catalog at the relay UP FRONT (the URL is a
    // build-time constant) so server icons/wallpapers resolve app-wide — pickers
    // AND applied chat backgrounds — without waiting for the deferred relay setup
    // (which is why server wallpapers showed as an empty list: configured=false).
    // configure() is idempotent, so the later relay-setup call is a no-op.
    CosmeticsCatalogService.instance.configure(relayHttpBaseUrl);
    // Restore deferred session-reset retry queue persisted before last exit.
    final pendingResets =
        prefs.getStringList(_prefsSessionResetPendingKey) ?? const [];
    for (final did in pendingResets) {
      if (did.isNotEmpty) _sessionResetRetryDeviceIds.add(did);
    }
    final pendingStartupWarning = prefs.getString(
      _prefsPendingStartupWarningKey,
    );
    if (pendingStartupWarning != null && pendingStartupWarning.isNotEmpty) {
      _startupWarning = pendingStartupWarning;
      await prefs.remove(_prefsPendingStartupWarningKey);
    }
    await security.init(prefs: prefs);
    _startupMark('security');
    _loadDesktopLinkRequestsFromPrefs(prefs);
    await _initLocalNotifications();
    await _initNativeMediaControls();
    _startConnectivityReconnectWatcher();
    _startDesktopPowerWakeWatcher();
    _appHapticsEnabled = _readNotifBoolCompat(
      prefs,
      runtimeKey: _prefsAppHapticsKey,
      settingsKey: _settingsAppHapticsKey,
      defaultValue: true,
    );
    // Sprint 2 PR8 (2026-05-19): one-shot scrub of stale test-mode prefs.
    //
    // Earlier desktop builds ran with `_desktopTestStartupMode == true`
    // unconditionally and persisted the mock identity into prefs. After we
    // flipped that gate to opt-in, a real production desktop can still wake
    // up with those mock values pinned, which silently breaks QR-pairing +
    // sync apply (real bundle decrypted under the mock identity is a no-op).
    // Wipe them once on startup so the next pairing mints fresh real IDs.
    //
    // PR-I (2026-05-20): the original scrub only removed `profile_id` and
    // `device_id`. That is enough to recover `_ensureKeysSetupInternal` *on
    // paper* — `hasServerBackedProfile` falls to false, server auto-creates
    // a fresh profile, fresh device_id is minted, and publishKeys signs with
    // the new (pid, did) identity keypair. In practice we still saw a
    // `publishKeys returned ok=false` wall on the QR screen because a bunch
    // of derived prefs survived from the mock run and confused the auto-heal
    // pipeline:
    //   - `keys_published_v1/<mock_pid>/<mock_did> = true` made
    //     `_ensureKeysPublished` think the bundle was already published.
    //   - `last_keys_publish_at_ms_v1` / `last_meta_publish_at_ms_v1` left a
    //     stale "refreshed recently" timestamp that suppressed re-publish.
    //   - `desktop_link_requests_v1` carried stale pending requests pinned to
    //     the mock identity — they'd flush through `_loadDesktopLinkRequestsFromPrefs`
    //     before the new identity was minted and corrupt the QR payload.
    //   - `server_binding_v1` froze the keys/relay binding the mock build
    //     wrote (often pointed at `127.0.0.1:8081`), so even after we move to
    //     prod endpoints, `hasServerProfileLocally()` could short-circuit.
    //   - `onboarding_complete_v1 = 1` skipped the onboarding gate, dropping
    //     the user straight into a shell with no real identity.
    // PR-I widens the scrub to remove all of these alongside the legacy
    // identity, so any desktop carrying the mock state self-heals on first
    // prod boot instead of camping forever on a red QR screen.
    if (!_desktopTestStartupMode && _isDesktopOrWebPlatform) {
      final stalePid = prefs.getString(_prefsProfileIdKey);
      final staleDid = prefs.getString(_prefsDeviceIdKey);
      if (stalePid == _desktopTestProfileId ||
          staleDid == _desktopTestDeviceId) {
        // Кто стёр личность — записать ДО стирания: потом улики нет.
        await IdentityJournal.recordProfileIdCleared(
          by: 'desktop_mock_state_scrub',
          nowMs: DateTime.now().millisecondsSinceEpoch,
          previousProfileId: prefs.getString(_prefsProfileIdKey),
          previousDeviceId: prefs.getString(_prefsDeviceIdKey),
          deviceIdClearedToo: true,
        );
        await prefs.remove(_prefsProfileIdKey);
        await prefs.remove(_prefsDeviceIdKey);
        await prefs.setBool(_prefsDesktopAuthRequiredKey, true);

        // Wipe any per-(pid, did) "keys published" markers — without this,
        // `_ensureKeysPublished` skips the publish call because prefs say
        // we already published under the mock identity.
        final purgedPublishedKeys = <String>[];
        for (final k in prefs.getKeys()) {
          if (k.startsWith(_prefsKeysPublishedKeyPrefix)) {
            purgedPublishedKeys.add(k);
          }
        }
        for (final k in purgedPublishedKeys) {
          await prefs.remove(k);
        }

        // Stale refresh timestamps and server binding pinned to the mock
        // build's transport endpoint. Removing these forces the next boot to
        // re-publish keys + meta and re-stamp the binding against whatever
        // endpoints the new build was compiled with.
        await prefs.remove(_prefsLastKeysPublishAtMsKey);
        await prefs.remove(_prefsLastMetaPublishAtMsKey);
        await prefs.remove(_prefsLastMetaRefreshAtMsKey);
        await prefs.remove(_prefsServerBindingKey);
        await prefs.remove(_prefsRelayNextSeqKey);

        // Drop any pending QR-pairing requests minted by the mock build —
        // their target_profile_id / target_device_id still point at the mock
        // identity, so re-minting fresh IDs leaves them as ghosts that block
        // a clean second attempt.
        await prefs.remove(_prefsDesktopLinkRequestsKey);

