      // device_id survives in prefs — the exact contradictory state the
      // invariant forbids. Provisional; cleared below if the second-chance
      // rescue puts the real database back.
      if (dbAlreadyExists) {
        _stateLossReasonThisLaunch = keyPermanentlyLost
            ? 'db_key_lost'
            : (recoverableSecureStorage ? 'db_key_unreadable' : 'db_open_error');
      }
    }
    // NEVER LEAVE THE USER IN AN EMPTY ACCOUNT (2026-07-20). A tester opened
    // the app to nothing while a 12.5 MB copy of their real database sat right
    // next to it: the live file opened fine (with a throwaway key), so the
    // rescue in the catch above never even ran.
    //
    // So it also runs here, on every launch, and needs no button: if the live
    // database is EMPTY and a quarantined copy opens with the key we hold, that
    // copy is the real one and it goes back automatically. Idempotent — once
    // restored there is nothing empty left to trigger it.
    final rescuedFromQuarantine = await _restoreQuarantinedDatabaseIfLocalIsEmpty(
      secrets,
    );

    // И-1 stage a (TZ_I1_IDENTITY_2026-07-21): count every launch that ends up
    // in the forbidden state — session store gone, device_id kept. The marker
    // from AppDb covers the quarantine that happens INSIDE open() (corrupt /
    // wrong-key file), which the catch above never sees. A successful rescue
    // means the real database is back and no state was lost after all.
    if (AppDb.consumeQuarantinedExistingDbDuringOpen() &&
        _stateLossReasonThisLaunch == null) {
      _stateLossReasonThisLaunch = 'db_corrupt';
    }
    if (rescuedFromQuarantine) {
      _stateLossReasonThisLaunch = null;
    }
    if (_stateLossReasonThisLaunch != null) {
      DiagLog.event('i1', 'state_loss', {
        'path': _stateLossReasonThisLaunch,
        'did': DiagLog.pfx(_deviceId ?? ''),
      });
    }

    // И-1 stage c: enforce the invariant — a session store lost involuntarily
    // costs the device its id. Runs only after every rescue has had its
    // chance, and never blocks boot: a failed rotation leaves the old
    // (pre-И-1) behaviour, not a broken account. Mobile only for now: a
    // desktop companion that lost its store re-pairs through the QR link flow,
    // which already mints a fresh desktop device_id.
    if (_stateLossReasonThisLaunch != null &&
        !_isDesktopOrWebPlatform &&
        _identityRotationEnabledEffective) {
      try {
        await _rotateDeviceIdentityForStateLoss(
          prefs: prefs,
          reason: _stateLossReasonThisLaunch!,
        );
      } catch (e) {
        DiagLog.event('i1', 'rotation_failed', {'err': _shortErrorTag(e)});
      }
    }

    // И-1: stamp the database with the identity it belongs to, and if this
    // FILE carries a stamp from a rotated-away identity (a quarantined copy
    // resurrected after a rotation), drop its ratchet rows — the history is
    // the user's, the sessions belong to the dead device.
    await _reconcileDbIdentityStamp();
    _startupMark('db_open');

    await _initContentCrypto();
    _startupMark('content_crypto');
    _debugRuntimeLog('Crypto provider: ${_crypto.runtimeType}');
    await _loadKnownOwnDeviceIdsFromDb();
    _startupMark('own_devices');
    unawaited(_purgeSelfQuarantine());
    // 🔴 РАЗОВАЯ АМНИСТИЯ БЮДЖЕТУ ПЕРЕОТПРАВКИ (15.08.2026). Сообщения, чьи
    // попытки сгорели в яме 429, иначе не уйдут никогда: бюджет исчерпан за
    // кадры, которых реле не видело. Вдогонку — старт не ждёт.
    unawaited(() async {
      try {
        final amnestyDb = _db;
        if (amnestyDb == null) return;
        final healed = await amnestyDb.resendBudgetAmnestyOnce(
          nowMs: DateTime.now().millisecondsSinceEpoch,
        );
        if (healed > 0) {
          DiagLog.event('send', 'resend_budget_amnesty', {'healed': healed});
        }
      } catch (_) {
        // разовая любезность не имеет права мешать запуску
      }
    }());
    await _loadPendingNoDeviceSendFromDb();
    await _loadStickerCatalogFromDb();
    _startupMark('sticker_catalog');
    await _loadCustomChatFoldersFromDb();
    _startupMark('chat_folders');

    // Best-effort: import safe-backup payload after restore.
    try {
      await _importPendingSafeBackupIfAny(prefs: prefs);
      _startupMark('backup_import');
    } catch (_) {
      // ignore
    }

    // 🔴 Перепривязка путей к фотографиям — НА КАЖДОМ запуске, а не только
    // сразу после восстановления. Установки, которые уже связались с
    // телефоном до этой починки, иначе так и остались бы с инициалами
    // навсегда: их восстановление прошло давно. Проход дешёвый — несколько
    // каталогов с аватарами, переписываются только мёртвые указатели.
    unawaited(() async {
      try {
        final rebaseDb = _db;
        if (rebaseDb == null) return;
        final rebased = await _rebaseRestoredImagePaths(rebaseDb);
        if (rebased > 0) {
          DiagLog.event('backup', 'image_paths_rebased', {'rows': rebased});
          _listConversationsCache = null;
          _changed.add(null);
        }
      } catch (_) {
        // ignore
      }
    }());

    if (_demoDataEnabled) {
      // Seed demo dataset (chats + groups) for UI testing.
      final demoSeedVersion = prefs.getInt(_prefsDemoSeedVersionKey) ?? 0;
      if (demoSeedVersion < _demoSeedVersion) {
        try {
          // Force a full reset on a version bump so refreshed demo content
          // (new text/language) replaces any previously seeded dataset.
          await _seedDemoChat(forceReset: demoSeedVersion > 0);
          await prefs.setInt(_prefsDemoSeedVersionKey, _demoSeedVersion);
          await prefs.setBool(_prefsDemoSeededKey, true);
        } catch (_) {
          // ignore demo seed errors
        }
      }

      // Self-heal: if chats were deleted and empty state is reached,
      // restore demo dataset automatically (without requiring UI button).
      try {
        final db = _db;
        if (db != null) {
          final existing = await db.convoList(limit: 1000);
          final demoConvoCount = existing
              .map((row) => ((row['convo_id'] as String?) ?? '').trim())
              .where(_isDemoConvoId)
              .length;
          if (existing.isEmpty || demoConvoCount < _demoEntries().length) {
            await _seedDemoChat();
            await prefs.setInt(_prefsDemoSeedVersionKey, _demoSeedVersion);
            await prefs.setBool(_prefsDemoSeededKey, true);
          }
        }
      } catch (_) {
        // ignore demo self-heal errors
      }
    } else {
      // Release safety net: a build that does NOT enable demo data must never
      // surface demo chats/contacts. They can survive from a previously
      // installed demo-enabled build or a restored backup — to a real user
      // this looks like an account takeover. Purge them on startup.
      await _purgeResidualDemoDataIfDisabled(prefs);
      _startupMark('demo_purge');
    }

    if (_contactSyncEnabled) {
      _scheduleManagedDeviceContactSync(delay: Duration.zero);
    }

    // Transport hardening: in release builds, block insecure http/ws by default.
    // This prevents accidental cleartext use when deploying behind TLS reverse proxy.
    try {
      final policy = TransportPolicy.evaluate(
        keysBaseUrl: keysBaseUrl,
        relayHttpBaseUrl: relayHttpBaseUrl,
        relayWsUrl: relayWsUrl,
        isReleaseMode: kReleaseMode,
        allowInsecureTransport: _allowInsecureTransportEnv,
      );
      if (!policy.allowed && !_serverBindingMismatch) {
        _transportBlocked = true;
        _transportBlockedReason = policy.warning;
        _startupWarning ??= policy.warning;
        _debugRuntimeLog('Transport policy: $_transportBlockedReason');
      }
    } catch (e) {
      if (!_serverBindingMismatch) {
        _transportBlocked = true;
      }
      _transportBlockedReason = 'Transport policy failed to parse URLs: $e';
      _startupWarning ??= _transportBlockedReason;
      _debugRuntimeLog('Transport policy error: $_transportBlockedReason');
    }

    var keysCompatibilityUnsupported = false;

    if (_desktopTestStartupMode) {
      _keysOnline = false;
      _relayOnline = false;
      _keys = null;
      _ratchetV1 = null;
      _ratchetV3 = null;
      _relay = null;
      _blob = null;
      _attachments = null;
    } else {
      // Keys service (dev): local machine via adb reverse on Android.
      final keys = KeysClient(baseUrl: keysBaseUrl);
      _keys = keys;

      // PERF(cold-start P0-1): for the 99% steady-state launch — an existing,
      // already-server-backed profile (the (pid, did) were loaded from prefs
      // above, the encrypted DB is open) — neither `keys.healthStatus()` nor
      // `_ensureKeysSetup()` is needed to reach a usable first frame:
      //   * Message send/receive runs on local Ed25519 device keys + cached
      //     ratchet sessions; the transport block below constructs with the
      //     already-loaded (pid, did) and does NOT depend on either network
      //     call's result (`_canStartAuthenticatedRuntime` is already true).
      //   * `healthStatus` (~8 s on cold MIUI radio) and `_ensureKeysSetup`
      //     (~10 s timeout) only RE-VERIFY an existing registration; they never
      //     mint a new profile for a server-backed id (see _ensureKeysSetupInternal:
      //     the createProfile branch is gated on `!hasServerBackedProfile`).
      // So we run BOTH in the background and let `_ready` flip as soon as the
      // local stack + transport objects are constructed. The 3 s service
      // watchdog (below) and RelayClient's own auto-reconnect already self-heal
      // connectivity and correct `_keysOnline` if the server is actually down —
      // exactly as they do today after a transient network blip — and they push
      // `_changed` to refresh the UI. This is the SAME treatment already applied
      // to `relay.connect()` and the relay health probe further down.
      //
      // FIRST-RUN safety: when the profile is NOT yet server-backed (fresh
      // install, first profile creation, post-reset, desktop awaiting QR) we
      // KEEP the original awaited path verbatim, because there `_ensureKeysSetup`
      // is what mints `_profileId`/`_deviceId` and the transport block cannot be
      // constructed until it completes.
      final existingServerBackedIdentity = _canStartAuthenticatedRuntime;

      if (_transportBlocked) {
        _keysOnline = false;
        _relayOnline = false;
        if (_isDesktopOrWebPlatform && !_shouldBootstrapAuthenticatedRuntime) {
          await _enterDesktopUnauthenticatedMode(
            prefs,
            warning: _transportBlockedReason,
          );
        }
      } else if (existingServerBackedIdentity) {
        // Steady-state fast path: do not block the first frame on the network.
        // Optimistically treat keys as online (transport delivery does not
        // depend on it; the watchdog corrects it within 3 s if wrong) and run
        // health + key re-verification fully in the background.
        _keysOnline = true;
        unawaited(
          _runBackgroundKeysSetupForExistingProfile(
            prefs: prefs,
            keys: keys,
            keysBaseUrl: keysBaseUrl,
            allowServerProfileAutoCreate: allowServerProfileAutoCreateOnStartup,
          ),
        );
      } else {
        final keysHealthStatus = await keys.healthStatus(
          clientProtocolVersion: clientProtocolVersion,
        );
        _keysHealthStatus = keysHealthStatus;
        keysCompatibilityUnsupported = keysHealthStatus.isUnsupported;
        if (keysCompatibilityUnsupported) {
          _keysOnline = false;
          _startupWarning = _serviceCompatibilityWarning(keysHealthStatus);
          _debugRuntimeLog('Keys compatibility warning: $_startupWarning');
          if (_isDesktopOrWebPlatform &&
              !_shouldBootstrapAuthenticatedRuntime) {
            await _enterDesktopUnauthenticatedMode(
              prefs,
              warning: _startupWarning,
            );
          }
        } else {
          try {
            final serverBackedIdentityReady =
                await _ensureKeysSetup(
                  prefs: prefs,
                  keys: keys,
                  allowServerProfileAutoCreate:
                      allowServerProfileAutoCreateOnStartup,
                  allowMissingCurrentDeviceRepair:
                      prefs.getBool(
                        _prefsAllowMissingCurrentDeviceRepairOnceKey,
                      ) ??
                      false,
                ).timeout(
                  const Duration(seconds: 10),
                  onTimeout: () => throw TimeoutException(
                    'keys setup timeout during startup',
                  ),
                );

            if (serverBackedIdentityReady) {
              await _persistServerBindingIfMissing(prefs);

              _keysOnline = true;
              // BUG-INIT-LATENCY: fire side-tasks without blocking relay connect.
              // These use authed HTTP but are NOT needed for message delivery —
              // relay connects with local Ed25519 device keys.  Running them
              // sequentially added up to 24 s of extra cold-start latency on
              // MIUI where the first TCP connection to the keys server is slow.
              unawaited(_refreshKnownOwnDeviceIdsFromServer());
              unawaited(
                _publishMyProfileMetaBestEffort().catchError((_) => false),
              );
              unawaited(
                _syncProfileInactivityStatusBestEffort(
                  force: true,
                  seedServerValueIfMissing: true,
                ).catchError((_) {}),
              );
            } else {
              _keysOnline = false;
              if (_isDesktopOrWebPlatform) {
                await _enterDesktopUnauthenticatedMode(prefs);
              }
            }
          } on CurrentDeviceRelinkRequiredException catch (e) {
            _keysOnline = false;
            if (!_isDesktopOrWebPlatform) {
              _startupWarning = e.message;
            }
          } catch (e) {
            _keysOnline = false;
            _startupWarning =
                '${_offlineHint(service: 'Keys', baseUrl: keysBaseUrl)} ($e)';
            _debugRuntimeLog('Keys init warning: $_startupWarning');

            if (_isDesktopOrWebPlatform &&
                !_shouldBootstrapAuthenticatedRuntime) {
              await _enterDesktopUnauthenticatedMode(
                prefs,
                warning: _startupWarning,
              );
            }
          }
        }
      }

      if (_canStartAuthenticatedRuntime) {
        _ratchetV1 = RatchetSessionManagerV1(
          db: _db!,
          deviceKeys: DeviceKeys.create(),
          keysClient: keys,
          fetchBundleAuthed: _fetchBundleAuthed,
        );

        _ratchetV3 = RatchetSessionManagerV3(
          db: _db!,
          deviceKeys: DeviceKeys.create(),
          keysClient: keys,
          fetchBundleAuthed: _fetchBundleAuthed,
        );

        // BACKGROUND DRAIN (2026-07-16): keep the background fetcher's base
        // URL snapshot in sync on this (re)bind path too.
        unawaited(
          prefs.setString(
            BackgroundInboxFetcher.prefsBaseUrlKey,
            relayHttpBaseUrl.toString(),
          ),
        );
        unawaited(
          prefs.setString(
            BackgroundInboxFetcher.prefsKeysBaseUrlKey,
            keysBaseUrl.toString(),
          ),
        );
        late final RelayClient relay;
        relay = RelayClient(
          db: _db!,
          deviceId: _deviceId!,
          selfProfileId: _profileId!,
          deviceKeys: DeviceKeys.create(),
          // On Android device, use adb reverse for local dev.
          wsUrl: relayWsUrl,
          httpBaseUrl: relayHttpBaseUrl,
          onConnectionChanged: (connected) =>
              _handleRelayConnectionChanged(relay, connected),
          onFirstDrainCompleted: () {
            if (!_changed.isClosed) _changed.add(null);
          },
          onServerError: (code, message) {
            _onRelayServerError(code: code, message: message);
          },
          onDelivered: _handleDelivered,
          loadNextSeq: () async => prefs.getInt(_prefsRelayNextSeqKey) ?? 1,
          saveNextSeq: (v) async => prefs.setInt(_prefsRelayNextSeqKey, v),
        );
        relay.readyAtMsProvider = () => _startupReadyAtMs;
        _relay = relay;
    relay.onUnknownDevice = _onRelaySaysUnknownDevice;
    relay.onDeviceAccepted = _onRelayAcceptedOwnDevice;
        _kickRelayOutbox(relay);

        // Attachments use Relay HTTP blob API.
        _blob = BlobClient(
          baseUrl: relayHttpBaseUrl,
          deviceId: _deviceId,
          selfProfileId: _profileId,
          deviceKeys: DeviceKeys.create(),
        );
        _stickerCatalogClient = StickerCatalogClient(baseUrl: relayHttpBaseUrl);
        _attachments = AttachmentService(blobClient: _blob!);

        if (!_transportBlocked && !keysCompatibilityUnsupported) {
          // BUG-INIT-LATENCY: skip blocking relay.healthStatus() on the critical
          // path — relay.connect() already handles server failures gracefully.
          // Protocol-version compat is checked in the background so it never
          // adds latency to the first message delivery.  Previous cost: ~10 s
          // on MIUI cold-start where the HTTP health probe timed out.
          //
          // PERF(cold-start): do NOT block the first usable frame on the relay
          // WebSocket handshake either.  relay.connect() is fired in the
          // background; the service watchdog below (every 3 s) and RelayClient's
          // own auto-reconnect both backstop a slow/failed connect, and message
          // delivery resumes the moment the socket is up.  Previously
          // `await relay.connect()` sat on the splash critical path and added the
          // full WS handshake latency (variable, up to seconds on a cold radio)
          // before the chat list could render.  Online-state changes notify the
          // UI via `_changed` exactly like the watchdog does (8756-8760).
          unawaited(() async {
            final relayOnlineBefore = _relayOnline;
            final startupWarningBefore = _startupWarning;
            try {
              await relay.connect();
              _relayOnline = true;
              _relayHttpReachable = true; // WS up => relay reachable
              unawaited(_syncPushTokenBestEffort());
              unawaited(_syncStickerCatalog(force: true));
              unawaited(
                relay
                    .healthStatus(clientProtocolVersion: clientProtocolVersion)
                    .then((hs) {
                      _relayHealthStatus = hs;
                      if (hs.isUnsupported) {
                        _relayOnline = false;
                        _startupWarning ??= _serviceCompatibilityWarning(hs);
                        _debugRuntimeLog(
                          'Relay compat warning (background): $_startupWarning',
                        );
                        unawaited(relay.disconnect());
                        if (!_changed.isClosed) _changed.add(null);
                      }
                    })
                    .catchError((_) {}),
              );
            } catch (e) {
              _relayOnline = false;
              // A WS connect/ready failure does NOT prove the relay is down —
              // MIUI/network can block the WS while plain HTTP (inbox pump +
              // call signalling) still works. Probe HTTP health first; only
              // surface "Relay is offline" if THAT also fails, so the banner
              // never contradicts working messaging + a static network finger-
              // print. (TimeoutException from the 6s WS-ready budget is exactly
              // the false positive the user reported.)
              try {
                final hs = await relay
                    .healthStatus(clientProtocolVersion: clientProtocolVersion)
                    .timeout(const Duration(seconds: 5));
                _relayHealthStatus = hs;
                _relayHttpReachable = hs.isHealthy && !hs.isUnsupported;
              } catch (_) {
                _relayHttpReachable = false;
              }
              if (!_relayHttpReachable) {
                _startupWarning ??=
                    '${_offlineHint(service: 'Relay', baseUrl: relayHttpBaseUrl)} ($e)';
              }
              _debugRuntimeLog(
                'Relay init: ws failed ($e); httpReachable=$_relayHttpReachable',
              );
            } finally {
              if ((relayOnlineBefore != _relayOnline ||
                      startupWarningBefore != _startupWarning) &&
                  !_changed.isClosed) {
                _changed.add(null);
              }
            }
          }());

          // Watchdog: self-heal when local dev services come back without requiring app restart.
          // Defensive: cancel any prior instance first — if init() were ever
          // re-entered on the same controller, an uncancelled timer here
          // would silently double all of its network/DB work every tick.
          _serviceWatchdogTimer?.cancel();
          _serviceWatchdogTimer = Timer.periodic(const Duration(seconds: 3), (
            _,
          ) async {
            // ZOMBIE-DB SELF-HEAL (2026-07-18; UNLATCHED 2026-07-24,
            // docs/BUG_AUDIT.md "Разбор корня"): fire the reopen probe on EVERY
            // 3 s tick, BEFORE the _watchdogRunning latch. The rest of the body
            // can hang for minutes on half-open sockets during an offline→online
            // flip (keys/relay health round-trips); while it does, _watchdogRunning
            // stays true and used to suppress the reopen for that whole window
            // (field: 3-minute gap — the DB healed only when a push happened to
            // fire the independent push-wake reopen). The reopen is fast,
            // unawaited, and self-guarded by _dbReopenInFlight + probeClosed()
            // (a no-op when the DB is healthy), so running it every tick
            // regardless of the body is safe and un-starves the self-heal.
            unawaited(_recoverUnexpectedlyClosedDb('watchdog'));
            if (_watchdogRunning) return;
            _watchdogRunning = true;
            final keysOnlineBefore = _keysOnline;
            final relayOnlineBefore = _relayOnline;
            final startupWarningBefore = _startupWarning;
            // BUG-INIT-LATENCY: kick relay reconnect immediately at the top of
            // each watchdog tick without waiting for the keys health round-trip.
            // Relay uses local Ed25519 device keys and can reconnect
            // independently of the Keys server.  On MIUI, OS-level network
            // throttling after force-stop blocks the first ~60 s of TCP
            // connections; as soon as the OS unblocks the app the very next
            // watchdog tick reconnects relay within 1-2 s instead of after
            // the full keys-health + relay-health chain (up to 18 s extra).
            // relay.connect() has a `_connecting` re-entry guard so this is
            // safe to fire every 3 s.
            if (!_relayOnline && !_transportBlocked) {
              unawaited(_relay?.connect().catchError((_) {}));
            }
            try {
              bool keysOk;
              try {
                final keysHealthStatus = await keys.healthStatus(
                  clientProtocolVersion: clientProtocolVersion,
                );
                _keysHealthStatus = keysHealthStatus;
                if (keysHealthStatus.isUnsupported) {
                  _keysOnline = false;
                  _startupWarning = _serviceCompatibilityWarning(
                    keysHealthStatus,
                  );
                  keysOk = false;
                } else {
                  keysOk = keysHealthStatus.isHealthy;
                }
              } catch (e) {
                keysOk = false;
                if (_keysOnline) {
                  _keysOnline = false;
                }
                // Banner is gated by the sustained-failure streak below, not
                // here — a transient health blip must not flash "Keys is offline".
              }
              if (keysOk && !_keysOnline) {
                try {
                  await _ensureKeysSetup(
                    prefs: prefs,
                    keys: keys,
                    allowServerProfileAutoCreate:
                        !requiresDesktopProfileSelection,
                    allowMissingCurrentDeviceRepair:
                        prefs.getBool(
                          _prefsAllowMissingCurrentDeviceRepairOnceKey,
                        ) ??
                        false,
                  ).timeout(
                    const Duration(seconds: 12),
                    onTimeout: () => throw TimeoutException(
                      'keys setup timeout during watchdog',
                    ),
                  );
                  _keysOnline = true;

                  // When Keys comes back, republish our profile meta so others can see it.
                  try {
                    await _publishMyProfileMetaBestEffort();
                  } catch (_) {
                    // ignore
                  }
                } on CurrentDeviceRelinkRequiredException catch (e) {
                  _keysOnline = false;
                  if (!_isDesktopOrWebPlatform) {
                    _startupWarning ??= e.message;
                  }
                } catch (e) {
                  _keysOnline = false;
                  _startupWarning ??=
                      '${_offlineHint(service: 'Keys', baseUrl: keysBaseUrl)} ($e)';
                }
              } else if (!keysOk && _keysOnline) {
                _keysOnline = false;
              }

              // Keys-offline banner: show only after a SUSTAINED outage (several
              // consecutive failed health checks), never on a transient blip, and
              // clear it the moment keys is healthy again — independent of relay.
              // Messaging keeps working over the relay + existing ratchet sessions
              // while keys briefly flaps, so an instant banner was pure noise.
              if (keysOk) {
                _keysHealthFailStreak = 0;
                final w = _startupWarning;
                if (w != null &&
                    w.contains(' is offline at ') &&
                    !w.endsWith(')')) {
                  _startupWarning = null;
                }
              } else {
                _keysHealthFailStreak++;
                if (_keysHealthFailStreak >= 3) {
                  _startupWarning ??= _offlineHint(
                    service: 'Keys',
                    baseUrl: keysBaseUrl,
                  );
                } else {
                  final w = _startupWarning;
                  if (w != null &&
                      w.contains(' is offline at ') &&
                      !w.endsWith(')')) {
                    _startupWarning = null;
                  }
                }
              }

              var relayCompatibilityUnsupported = false;
              try {
                final relayHealthStatus = await relay.healthStatus(
                  clientProtocolVersion: clientProtocolVersion,
                );
                _relayHealthStatus = relayHealthStatus;
                relayCompatibilityUnsupported = relayHealthStatus.isUnsupported;
                if (relayCompatibilityUnsupported) {
                  _relayOnline = false;
                  _startupWarning = _serviceCompatibilityWarning(
                    relayHealthStatus,
                  );
                  await _relay?.disconnect();
                }
              } catch (_) {
                // ignore relay health parsing/network failures here; websocket reconnect logic remains authoritative.
              }

              // Clear a stale "<service> is offline" banner once both services
              // are actually healthy again. The watchdog is the authoritative
              // recovery path; without this the warning latches forever after a
              // transient hiccup even though messaging works (only clears when
              // BOTH _keysOnline && _relayOnline, so real/compat warnings stay).
              _maybeClearStartupWarning();

              // Best-effort: encrypted safe auto-backup (server/device) according to user schedule.
              try {
                await _maybeRunAutoSafeBackup(force: false);
              } catch (_) {
                // ignore
              }

              // Relay: if offline, attempt reconnect (RelayClient also schedules reconnect internally).
              if (!_relayOnline && !relayCompatibilityUnsupported) {
                final allowBackgroundConnection = _readNotifBoolCompat(
                  prefs,
                  runtimeKey: _prefsNotifBackgroundConnectionKey,
                  settingsKey: _settingsNotifBackgroundConnectionKey,
                  defaultValue: true,
                );
                if (!_appInForeground && !allowBackgroundConnection) {
                  return;
                }
                if (!_appInForeground && allowBackgroundConnection) {
                  final nowMs = DateTime.now().millisecondsSinceEpoch;
                  if (nowMs - _lastBackgroundWatchdogAtMs < 12000) {
                    return;
                  }
                  _lastBackgroundWatchdogAtMs = nowMs;
                }
                try {
                  await _relay?.connect();
                } catch (_) {
                  // ignore
                }
                // The WS may still be failing to reach "ready" (MIUI / slow
                // link) while the relay is reachable over HTTP — the inbox pump
                // + call signalling use HTTP, so messaging works. Probe HTTP so
                // a stale "Relay is offline" banner CLEARS instead of latching
                // forever on a WS-only signal.
                if (!_relayOnline) {
                  try {
                    final hs = await _relay
                        ?.healthStatus(
                          clientProtocolVersion: clientProtocolVersion,
                        )
                        .timeout(const Duration(seconds: 5));
                    _relayHttpReachable =
                        hs != null && hs.isHealthy && !hs.isUnsupported;
                    if (hs != null) _relayHealthStatus = hs;
                  } catch (_) {
                    _relayHttpReachable = false;
                  }
                  _maybeClearStartupWarning();
                }
              }

              // Best-effort: refresh cached profile meta (nickname/avatar) so UI updates.
              final now = DateTime.now().millisecondsSinceEpoch;

              // Компьютер своё лицо не выбирает, а ПОЛУЧАЕТ: фотография,
              // никнейм и украшения приезжают из собственных метаданных
              // профиля. Забираем их до публикации — иначе первая же отправка
              // ушла бы с пустыми украшениями и стёрла их у всех, кто их
              // видит (`frame_id`/`cover_id`/`emoji_status` сервер
              // присваивает как есть, без COALESCE).
              // 🔴 СВОЁ ЛИЦО ЗАБИРАЕТ КАЖДОЕ УСТРОЙСТВО, А НЕ ТОЛЬКО
              // КОМПЬЮТЕР (15.09.2026).
              //
              // Здесь стояло `_isDesktopOrWebPlatform`, и телефон СВОИ
              // опубликованные метаданные не читал никогда. Владелец поменял
              // обложку и рамку на компьютере — собеседники увидели новые, а
              // на его собственном телефоне осталась старая картинка. Каждое
              // устройство держало свою копию и ничего не знало о чужой.
              //
              // Условия платформы тут быть не должно: «какое у меня лицо» —
              // вопрос аккаунта, а не устройства.
              if (keysOk &&
                  !_transportBlocked &&
                  (now - _lastMyMetaFetchAtMs) >= 10 * 60 * 1000) {
                _lastMyMetaFetchAtMs = now;
                try {
                  await refreshProfileMeta(profileId);
                  await _adoptMyPublishedProfileMeta();
                } catch (_) {
                  // ignore
                }
              }

              // Best-effort: periodically republish our own meta (helps after server restarts).
              if (keysOk &&
                  !_transportBlocked &&
                  (now - _lastMyMetaPublishAtMs) >= 10 * 60 * 1000) {
                try {
                  await _publishMyProfileMetaBestEffort();
                } catch (_) {
                  // ignore
                }
              }

              if (keysOk && !_transportBlocked && _appInForeground) {
                try {
                  await _publishPresenceHeartbeatBestEffort();
                } catch (_) {
                  // ignore
                }
              }

              // Best-effort: refresh cached profile meta for contacts/requests using a
              // throttled scheduler with per-profile backoff (prevents spamming Keys).
              try {
                await _metaRefreshTick(
                  keysOk: keysOk,
                  nowMs: now,
                  maxFetches: _appInForeground ? 3 : 1,
                );
              } catch (_) {
                // ignore
              }

              // Best-effort: pull the account's blocked list. Blocks are server
              // state that a second device never learned about — see
              // docs/SYNC_PARITY_AUDIT_2026-09-08.md. Self-throttled to five
              // minutes; never throws.
              try {
                await reconcileBlockedProfilesFromServer();
              } catch (_) {
                // ignore
              }

              // Best-effort: re-read our OWN nickname/bio. The meta refresh
              // above walks contacts and conversations, never the user's own
              // profile — so a rename on the phone never reached this device.
              try {
                await refreshOwnProfileMetaFromServer();
              } catch (_) {
                // ignore
              }

              try {
                await _notificationReminderTick(nowMs: now);
              } catch (_) {
                // ignore
              }

              try {
                await _recoverStuckOutgoingSends(nowMs: now);
                _startupMark('stuck_sends');
              } catch (_) {
                // ignore
              }

              // Flush pending receipts periodically (catches cases where a prior
              // flush failed due to transport being down or app restart).
              if (!_transportBlocked &&
                  (now - _lastWatchdogReceiptFlushAtMs) >= 30 * 1000) {
                _lastWatchdogReceiptFlushAtMs = now;
                try {
                  await _flushPendingReceiptsBestEffort();
                } catch (_) {
                  // ignore
                }
              }

              // Retry messages that were queued because the recipient had no
              // registered devices at send time.
              if (keysOk && _pendingNoDeviceSend.isNotEmpty) {
                try {
                  await _retryPendingNoDeviceSend();
                } catch (_) {
                  // ignore
                }
              }

              // Sprint 2 C1: piggy-back periodic bundle re-verification
              // on the existing 3-second watchdog tick. The watchdog
              // itself rate-limits to once per minute and at most a
              // handful of peers per pass, so the keys-server load
              // stays negligible.
              if (keysOk) {
                try {
                  await _bundleRevalidationWatchdogTick();
                } catch (_) {
                  // ignore
                }
              }

              // Sprint 2 C4: outbox-stuck watchdog. Independent of
              // keysOk so we still surface UI alerts when keys is
              // offline (offline is in fact when sends most often
              // accumulate). The recovery dispatch inside the tick
              // is itself best-effort and degrades cleanly.
              try {
                await _outboxStuckWatchdogTick();
              } catch (_) {
                // ignore
              }

              // FIX (2026-07-13, sender-side session convergence — TZ §20): heal
              // a silently-desynced 1:1 session (my messages relay-ACK but never
              // earn an end-to-end 'delivered' receipt from an alive peer) by
              // forcing a clean re-key. Best-effort, self-gated to ~30 s cadence,
              // conservative + kill-switchable.
              try {
                await _runSenderConvergenceBackstop();
                // Same sweep for ROOMS — 1:1 conversations are all the backstop
                // above can see. Self-gated and OFF by default (фаза 1 ТЗ).
                await _runRoomConvergenceBackstop();
                // Reader-side mirror of the above: rescue read receipts that
                // died undecryptable with no NACK, so the peer never stays stuck
                // showing half our messages read. Self-gated to a slow cadence.
                await _runReadReceiptReconcileBackstop();
                // Re-encrypt relay-held "send later" wires whose session
                // rotated after upload (catches rotations the peer initiated,
                // which have no local hook).
                await _refreshHeldScheduledWires();
              } catch (_) {
                // ignore
              }

              _maybeClearStartupWarning();
            } finally {
              _watchdogRunning = false;
              if (keysOnlineBefore != _keysOnline ||
                  relayOnlineBefore != _relayOnline ||
                  startupWarningBefore != _startupWarning) {
                _changed.add(null);
              }
            }
          });

          // Same defensive cancel-before-reassign as the watchdog above.
          _pumpTimer?.cancel();
        _mainAliveHeartbeatTimer?.cancel();
    _mainAliveHeartbeatTimer?.cancel();
          _pumpPrefs = prefs;
          _restartPumpTimer();
          _startHeartbeatTimer(prefs);

          // FIX D — durable periodic self-healing recovery sweep. Independent of
          // relay reconnects and of an (impossible) successful decrypt: every
          // 90 s it re-pings + refreshes devices for any peer with stuck
          // quarantined inbound, then replays the quarantine. Cancel-before-
          // create keeps it singleton across re-inits.
          //
          // FIX E — proactive silence-driven recovery rides the SAME timer but
          // runs UNCONDITIONALLY (not gated on quarantine being non-empty): it
          // force-refreshes devices + reset-pings any 1:1 peer we have sent to
          // that has gone silent, healing the upstream "sender glued to a dead
          // device_id" break that never reaches quarantine. Both are
          // independently try-guarded so neither can throw into the Timer.
          _quarantineRecoverySweepTimer?.cancel();
          _quarantineRecoverySweepTimer = Timer.periodic(
            _quarantineRecoverySweepInterval,
            (_) {
              unawaited(_runQuarantineRecoverySweep());
              unawaited(_runSilenceRecoverySweep());
            },
          );

          // 🔴 НЕ на критическом пути (03.08.2026). Раньше здесь стояло
          // `await`, и первый кадр ждал полного экспорта зашифрованной базы
          // ПЛЮС выгрузки её на сервер: внутри `_maybeRunAutoSafeBackup` есть
          // и `uploadSafeBackupToServer`, и `saveSafeBackupToDevice`.
          //
          // Резервная копия не имеет права держать интерфейс: её результат не
          // нужен ни одному экрану, а срабатывает она по расписанию — то есть
          // именно тогда, когда человек давно не заходил и ждёт дольше всего.
          //
          // Поведение самой копии не меняется: тот же вызов, те же проверки
          // интервала и защиты от перезаписи, просто рядом с запуском, а не
          // поперёк него. Ошибки по-прежнему глотаются — копия best-effort.
          unawaited(_maybeRunAutoSafeBackup(force: false).catchError((_) {}));
          _startupMark('auto_backup_dispatched');
        }
      } else {
        _ratchetV1 = null;
        _ratchetV3 = null;
        _relay = null;
        _blob = null;
        _attachments = null;
      }
    }

    if (requiresDesktopProfileSelection) {
      if (_authFlowState != AuthFlowState.authError) {
        _setAuthFlowState(AuthFlowState.unauthenticated);
      }
    } else {
      _setAuthFlowState(AuthFlowState.authenticated);
      unawaited(
        ensureFavoritesChat(
          title: _appL10n.favoritesTitle,
        ).catchError((_) => ''),
      );
    }

    _startupMark('transport');
    // Итог: сколько init() держал первый кадр. Всё, что до `begin`, — движок и
    // подгрузка кода системой; наш код на это не влияет.
    final totalMs = (_startupWatch.elapsedMicroseconds / 1000).round();
    DiagLog.event('startup', 'init_done', {'total_ms': totalMs});
    // 🔴 От init_done до первого ответа насоса в полевом замере ушло ПЯТЬ
    // секунд, и приглашение звонка всё это время лежало в ящике реле. Отмечаем
    // момент готовности, чтобы разрыв был виден числом.
    _startupReadyAtMs = DateTime.now().millisecondsSinceEpoch;
    _startupTrace.add('ИТОГО=${totalMs}ms');
    _startupWatch.stop();
    _changed.add(null);
  }

  /// PERF(cold-start P0-1): background completion of the keys health check +
  /// `_ensureKeysSetup` for an EXISTING server-backed profile. This is the work
  /// the steady-state launch used to `await` on the splash critical path
  /// (`keys.healthStatus()` ~8 s + `_ensureKeysSetup().timeout(10 s)`); moving
  /// it here lets the first frame paint as soon as the local stack + transport
  /// objects are ready while this re-verifies the server registration.
  ///
  /// Behaviour is intentionally the SAME as the inline success path: on success
  /// it persists the server binding (idempotent) and fires the same three
  /// best-effort side-tasks; on incompatibility it disconnects relay (mirroring
  /// the background relay-compat handler); on any failure it flips `_keysOnline`
  /// false with the standard offline hint. The 3 s service watchdog keeps
  /// retrying `_ensureKeysSetup` afterwards, so a slow/failed run self-heals
  /// exactly as a mid-session network blip already does. Every state transition
  /// pushes `_changed` so the UI (online dot / startup warning) stays correct.
  /// Never rethrows — it runs in an unawaited zone.
  Future<void> _runBackgroundKeysSetupForExistingProfile({
    required SharedPreferences prefs,
    required KeysClient keys,
    required Uri keysBaseUrl,
    required bool allowServerProfileAutoCreate,
  }) async {
    final keysOnlineBefore = _keysOnline;
    final startupWarningBefore = _startupWarning;
    try {
      final keysHealthStatus = await keys.healthStatus(
        clientProtocolVersion: clientProtocolVersion,
      );
      _keysHealthStatus = keysHealthStatus;
      if (keysHealthStatus.isUnsupported) {
        _keysOnline = false;
        _startupWarning = _serviceCompatibilityWarning(keysHealthStatus);
        _debugRuntimeLog(
          'Keys compatibility warning (background): $_startupWarning',
        );
        // Incompatible server: drop the relay socket like the background
        // relay-compat path does, so we don't keep talking to it.
        unawaited(_relay?.disconnect());
        return;
      }

      final serverBackedIdentityReady =
          await _ensureKeysSetup(
            prefs: prefs,
            keys: keys,
            // Same decision the foreground path would have made — for a normal
            // server-backed profile this is inert (the profile already exists,
            // so `_ensureKeysSetupInternal` skips createProfile regardless); it
            // only matters in the rare "server forgot my profile" edge case,
            // where we keep the original behaviour.
            allowServerProfileAutoCreate: allowServerProfileAutoCreate,
            allowMissingCurrentDeviceRepair:
                prefs.getBool(_prefsAllowMissingCurrentDeviceRepairOnceKey) ??
                false,
          ).timeout(
            const Duration(seconds: 10),
            onTimeout: () => throw TimeoutException(
              'keys setup timeout during background startup',
            ),
          );

      if (serverBackedIdentityReady) {
        await _persistServerBindingIfMissing(prefs);
        _keysOnline = true;
        unawaited(_refreshKnownOwnDeviceIdsFromServer());
        unawaited(_publishMyProfileMetaBestEffort().catchError((_) => false));
        unawaited(
          _syncProfileInactivityStatusBestEffort(
            force: true,
            seedServerValueIfMissing: true,
          ).catchError((_) {}),
        );
      } else {
        // Defensive: a server-backed id should report ready. If not, leave the
        // optimistic-online flag down so the watchdog re-attempts setup.
        _keysOnline = false;
      }
    } on CurrentDeviceRelinkRequiredException catch (e) {
      _keysOnline = false;
      if (!_isDesktopOrWebPlatform) {
        _startupWarning = e.message;
      }
    } catch (e) {
      _keysOnline = false;
      _startupWarning ??=
          '${_offlineHint(service: 'Keys', baseUrl: keysBaseUrl)} ($e)';
      _debugRuntimeLog('Keys init warning (background): $e');
    } finally {
      if ((keysOnlineBefore != _keysOnline ||
              startupWarningBefore != _startupWarning) &&
          !_changed.isClosed) {
        _changed.add(null);
      }
    }
  }

  void _onRelayServerError({required String code, required String message}) {
    if (code != 'auth_failed') return;
    final m = message.toLowerCase();
    final shouldRepair =
        m.contains('unknown device') || m.contains('bad signature');
    if (!shouldRepair) return;

    final now = DateTime.now().millisecondsSinceEpoch;
    if (_relayAuthRepairInFlight) return;
    if (now - _lastRelayAuthRepairAtMs < 30 * 1000) return;
    _lastRelayAuthRepairAtMs = now;
    _relayAuthRepairInFlight = true;

    unawaited(() async {
      try {
        final prefs = _prefs;
        final keys = _keys;
        final relay = _relay;
        final pid = _profileId;
        final did = _deviceId;

        if (prefs == null ||
            keys == null ||
            relay == null ||
            pid == null ||
            did == null) {
          return;
        }

        if (_transportBlocked) {
          return;
        }

        try {
          await _ensureKeysSetup(
            prefs: prefs,
            keys: keys,
            allowServerProfileAutoCreate: !requiresDesktopProfileSelection,
          ).timeout(
            const Duration(seconds: 15),
            onTimeout: () => throw TimeoutException(
              'keys setup timeout during relay auth repair',
            ),
          );
          _keysOnline = true;
        } on CurrentDeviceRelinkRequiredException catch (e) {
          if (!_isDesktopOrWebPlatform) {
            _startupWarning = e.message;
            _changed.add(null);
          }
          return;
        } catch (e) {
          if (_isDesktopOrWebPlatform) {
            _startupWarning =
                AppRuntimeLifecycleCoordinator.desktopAuthRepairRetryWarning();
            if (!requiresDesktopProfileSelection) {
              _setAuthFlowState(AuthFlowState.authenticated);
            }
            _changed.add(null);
            return;
          }
          _startupWarning =
              'Relay auth repair failed while refreshing Keys registration: $e';
          _changed.add(null);
          return;
        }

        var serverDeviceIds = const <String>[];
        bool deviceKnownInKeys = false;
        var devicesCheckCompleted = false;
        try {
          serverDeviceIds = await _listDevicesAuthed(pid);
          devicesCheckCompleted = true;
          deviceKnownInKeys = serverDeviceIds.contains(did);
        } catch (_) {
          // ignore
        }

        if (!devicesCheckCompleted) {
          _startupWarning =
              AppRuntimeLifecycleCoordinator.desktopVerificationRetryWarning();
          _changed.add(null);
          return;
        }

        if (!deviceKnownInKeys) {
          final decision =
              AppRuntimeLifecycleCoordinator.resolveMissingCurrentDevice(
                isDesktopOrWebPlatform: _isDesktopOrWebPlatform,
                explicitUserInitiatedRepair: false,
                currentDeviceId: did,
                serverDeviceIds: serverDeviceIds,
              );
          if (decision.desktopUnauthenticatedMode != null) {
            await _enterDesktopCurrentDeviceRemovedMode(
              prefs: prefs,
              result: decision.desktopUnauthenticatedMode!,
            );
            return;
          }
          if (_isDesktopOrWebPlatform) {
            _startupWarning =
                AppRuntimeLifecycleCoordinator.desktopRegistrationPendingWarning();
            if (!requiresDesktopProfileSelection) {
              _setAuthFlowState(AuthFlowState.authenticated);
            }
            _changed.add(null);
            return;
          }
          _startupWarning =
              'This device is not registered in Keys. Open Settings → Diagnostics, then reset profile and re-login.';
          _changed.add(null);
          return;
        }

        try {
          await relay.disconnect();
        } catch (_) {
          // ignore
        }

        try {
          await relay.connect().timeout(
            const Duration(seconds: 12),
            onTimeout: () => throw TimeoutException(
              'relay reconnect timeout during auth repair',
            ),
          );
          _relayOnline = true;
          _relayHttpReachable = true; // WS up => relay reachable
          unawaited(_syncStickerCatalog(force: true));
          _maybeClearStartupWarning();
          if (!requiresDesktopProfileSelection) {
            _setAuthFlowState(AuthFlowState.authenticated);
          }
        } catch (_) {
          _relayOnline = false;
          _startupWarning =
              'Relay rejects this device (auth_failed: $message). Check device registration/identity consistency and VPS config (keys/relay SECRETLY_INTERNAL_KEY, relay->keys internal URL).';
          if (_isDesktopOrWebPlatform && !requiresDesktopProfileSelection) {
            _setAuthFlowState(AuthFlowState.authenticated);
          }
        }

        _changed.add(null);
      } finally {
        _relayAuthRepairInFlight = false;
      }
    }());
  }

  Future<void> _importPendingSafeBackupIfAny({
    required SharedPreferences prefs,
  }) async {
    final raw = prefs.getString(_prefsPendingSafeImportKey);
    if (raw == null || raw.trim().isEmpty) return;
    final db = _db;
    if (db == null) return;

    Map<String, dynamic> json;
    try {
      json = jsonDecode(raw) as Map<String, dynamic>;
    } catch (_) {
      await prefs.remove(_prefsPendingSafeImportKey);
      return;
    }

    try {
      await _applyPendingSafeImportPayload(db: db, json: json);
      _changed.add(null);
    } finally {
      await prefs.remove(_prefsPendingSafeImportKey);
    }
  }

  Future<void> _applyPendingSafeImportPayload({
    required AppDb db,
    required Map<String, dynamic> json,
  }) async {
    final dbSnapshot = _decodeSafeBackupDbSnapshot(json['db_snapshot']);
    if (dbSnapshot.isNotEmpty) {
      await db.importTables(
        dbSnapshot,
        allowedColumnsByTable: kSafeBackupSnapshotColumnsByTable,
      );
      // 🔴 НАДГРОБИЯ — СРАЗУ ПОСЛЕ СНИМКА, и порядок здесь не стилистика.
      //
      // Снимок заливается ЦЕЛИКОМ и возвращает всё, что было живо на момент
      // копии, включая чаты, удалённые уже после неё. Надгробия живут вне
      // снимка (иначе их бы и затёрло) и снимают вернувшееся обратно.
      //
      // Полевая жалоба, ради которой это сделано: «восстанавливаются чаты,
      // которые я давно удалил».
      try {
        final removed = await db.applyDeletionTombstones();
        if (removed > 0) {
          DiagLog.event('backup', 'tombstones_applied', {'convos': removed});
        }
      } catch (e) {
        // Не роняем восстановление из-за уборки: лучше вернуть лишний чат,
        // чем потерять всё остальное. Человек удалит его ещё раз.
        DiagLog.event('backup', 'tombstones_failed', {
          'err': _shortErrorTag(e),
        });
      }

      // 🔴 ПУТИ СТИКЕРОВ — ПОСЛЕ снимка и обязательно (08.08.2026).
      //
      // `sticker_pack_stickers.local_path` абсолютный, и снимок приносит путь
      // ЧУЖОГО контейнера: на iOS каталог приложения меняет UUID при каждой
      // переустановке. Без перепривязки строки бы легли, файлы бы легли, а
      // набор всё равно выглядел бы пустым — то есть починка выглядела бы
      // сделанной, а болезнь осталась бы.
      //
      // Тот же класс, что фото профиля 13.07: абсолютный путь переживает
      // переустановку только по имени файла.
      try {
        final rebased = await _rebaseStickerLocalPaths(db);
        if (rebased > 0) {
          DiagLog.event('backup', 'sticker_paths_rebased', {'count': rebased});
        }
      } catch (e) {
        // Наборы важнее, чем аккуратность путей: пусть часть стикеров не
        // отрисуется, чем не восстановится ничего.
        DiagLog.event('backup', 'sticker_paths_rebase_failed', {
          'err': _shortErrorTag(e),
        });
      }

      // 🔴 ФОТОГРАФИИ — ТУТ ЖЕ И ПО ТОЙ ЖЕ ПРИЧИНЕ (13.09.2026).
      // Аватары собеседников, комнат и обложки хранятся абсолютными путями
      // чужого контейнера — см. [_rebaseRestoredImagePaths].
      try {
        final rebased = await _rebaseRestoredImagePaths(db);
        if (rebased > 0) {
          DiagLog.event('backup', 'image_paths_rebased', {'rows': rebased});
        }
      } catch (e) {
        DiagLog.event('backup', 'image_paths_rebase_failed', {
          'err': _shortErrorTag(e),
        });
      }
    }

    final contacts = (json['contacts'] as List<dynamic>? ?? const []);
    for (final it in contacts) {
      if (it is! Map) continue;
      final pid = (it['profile_id'] as String?) ?? '';
      if (pid.isEmpty) continue;
      final dn = (it['display_name'] as String?)?.trim();
      await db.contactUpsert(
        profileId: pid,
        displayName: (dn != null && dn.isNotEmpty) ? dn : null,
        displayNameIsCustom: dn != null && dn.isNotEmpty,
      );
      await db.convoEnsure1to1(peerProfileId: pid);
    }

    final blocked = (json['blocked_profiles'] as List<dynamic>? ?? const []);
    for (final it in blocked) {
      if (it is! String) continue;
      final pid = it.trim();
      if (pid.isEmpty) continue;
      await db.blockedProfileSet(profileId: pid, blocked: true);
    }
  }

  Map<String, List<Map<String, Object?>>> _decodeSafeBackupDbSnapshot(
    Object? raw,
  ) {
    if (raw is! Map) return const {};
    final out = <String, List<Map<String, Object?>>>{};
    raw.forEach((key, value) {
      final table = key.toString().trim();
      if (table.isEmpty || value is! List) {
        throw StateError('Safe backup invalid db_snapshot');
      }
      final rows = <Map<String, Object?>>[];
      for (final row in value) {
        if (row is Map<String, Object?>) {
          rows.add(Map<String, Object?>.from(row));
          continue;
        }
        if (row is Map) {
          rows.add(row.map((k, v) => MapEntry(k.toString(), v as Object?)));
          continue;
        }
        throw StateError('Safe backup invalid db_snapshot');
      }
      out[table] = rows;
    });
    validateSafeBackupDbSnapshot(payloadName: 'Safe backup', dbSnapshot: out);
    return out;
  }

  Map<String, String> _decodeSafeBackupFiles(Object? raw) {
    if (raw is! Map) return const {};
    final out = <String, String>{};
    raw.forEach((key, value) {
      if (value is! String) return;
      final rel = normalizeSafeBackupRelativePath(key.toString());
      if (rel == null) return;
      out[rel] = value;
    });
    return out;
  }

  Future<void> _restoreSafeBackupFilesToDocuments(
    Map<String, String> filesB64ByRelativePath,
  ) async {
    if (filesB64ByRelativePath.isEmpty) return;
    final docs = await getApplicationDocumentsDirectory();
    final docsPath = p.normalize(docs.path);
    for (final entry in filesB64ByRelativePath.entries) {
      final rel = normalizeSafeBackupRelativePath(entry.key);
      if (rel == null) {
        continue;
      }
      try {
        final bytes = base64Decode(entry.value);
        final outPath = p.normalize(
          p.joinAll(<String>[docsPath, ...p.posix.split(rel)]),
        );
        if (!p.isWithin(docsPath, outPath)) {
          continue;
        }
        final outFile = File(outPath);
        await outFile.parent.create(recursive: true);
        await outFile.writeAsBytes(bytes, flush: true);
      } catch (_) {
        // Best-effort for individual files.
      }
    }
  }

  Future<Map<String, List<Map<String, Object?>>>> _collectSafeBackupDbSnapshot(
    AppDb db,
  ) async {
    final out = <String, List<Map<String, Object?>>>{};
    for (final table in kSafeBackupSnapshotTables) {
      final part = await db.exportTables(<String>[
        table,
      ], allowedColumnsByTable: kSafeBackupSnapshotColumnsByTable);
      final rows = part[table] ?? const <Map<String, Object?>>[];
      out[table] = rows;
    }
    return out;
  }

  String? _safeBackupRelativePath({
    required String docsPath,
    required String absolutePath,
  }) {
    final abs = p.normalize(absolutePath.trim());
    if (abs.isEmpty || !p.isWithin(docsPath, abs)) return null;
    final rel = p.relative(abs, from: docsPath).replaceAll('\\', '/');
    if (rel.isEmpty || rel.startsWith('../') || rel.startsWith('/')) {
      return null;
    }
    return rel;
  }

  /// Потолок на ОДИН файл лица профиля, который едет даже в копию «без медиа».
  ///
  /// Аватар и обложка — это единицы мегабайт, и терять из-за них лицо профиля
  /// глупо. А вот видео-обложка премиума может весить десятки мегабайт, и её
  /// место рядом с медиа переписки, а не в маленькой серверной копии (там
  /// потолок 200 МБ на весь payload). Файл больше этого предела просто
  /// пропускается — путь к нему в копии останется, байты приедут со следующей
  /// полной копией.
  static const int _kSafeBackupCosmeticFileMaxBytes = 4 * 1024 * 1024;

  Future<void> _safeBackupAddFileIfExists({
    required String docsPath,
    required String absolutePath,
    required Map<String, String> out,
    int? maxBytes,
  }) async {
    final rel = _safeBackupRelativePath(
      docsPath: docsPath,
      absolutePath: absolutePath,
    );
    if (rel == null) return;
    if (out.containsKey(rel)) return;
    try {
      final f = File(absolutePath);
      if (!await f.exists()) return;
      if (maxBytes != null && await f.length() > maxBytes) {
        DiagLog.event('backup', 'cosmetic_file_too_big', {
          'rel': rel,
          'bytes': await f.length(),
        });
        return;
      }
      out[rel] = base64Encode(await f.readAsBytes());
    } catch (_) {
      // Best-effort for individual files.
    }
  }

  /// Лицо профиля: аватар и обложка. Едет в ЛЮБУЮ копию, включая серверную.
  ///
  /// 🔴 Полевой отказ 06.08.2026: после восстановления с сервера пропало фото
  /// профиля. Причина — серверная копия собирается с `includeBinaryFiles:
  /// false`, а под этим флагом лежали ВМЕСТЕ и медиа переписки (сотни мегабайт),
  /// и аватар (единицы). В копии оставался ПУТЬ к аватару, но не байты, и после
  /// восстановления путь указывал в пустоту.
  ///
  /// Разделение по размеру, а не по «важности»: то, что весит мегабайты, едет
  /// всегда; то, что весит сотни, — по выбору пользователя.
  Future<void> _collectSafeBackupProfileFaceFiles({
    required String docsPath,
    required List<String> avatarPaths,
    required List<String> cosmeticMediaPaths,
    required Map<String, String> out,
  }) async {
    await _safeBackupAddFileIfExists(
      docsPath: docsPath,
      absolutePath: p.join(docsPath, 'my_avatar.png'),
      out: out,
      maxBytes: _kSafeBackupCosmeticFileMaxBytes,
    );
    for (final path in <String>[...avatarPaths, ...cosmeticMediaPaths]) {
      await _safeBackupAddFileIfExists(
        docsPath: docsPath,
        absolutePath: path,
        out: out,
        maxBytes: _kSafeBackupCosmeticFileMaxBytes,
      );
    }
  }

  Future<void> _safeBackupAddDirectoryFiles({
    required String docsPath,
    required String subDir,
    required Map<String, String> out,
  }) async {
    final docs = Directory(docsPath);
    final dir = Directory(p.join(docs.path, subDir));
    if (!await dir.exists()) return;
    await for (final entity in dir.list(recursive: true, followLinks: false)) {
      if (entity is! File) continue;
      await _safeBackupAddFileIfExists(
        docsPath: docsPath,
        absolutePath: entity.path,
        out: out,
      );
    }
  }

  Future<Map<String, String>> _collectSafeBackupBinaryFiles({
    required List<String> avatarPaths,
    required List<String> galleryPaths,
    required List<String> backgroundPaths,
    required List<String> musicPaths,
    List<String> cosmeticMediaPaths = const <String>[],
  }) async {
    final docs = await getApplicationDocumentsDirectory();
    final docsPath = p.normalize(docs.path);
    final out = <String, String>{};

    await _safeBackupAddFileIfExists(
      docsPath: docsPath,
      absolutePath: p.join(docsPath, 'my_avatar.png'),
      out: out,
    );

    for (final path in avatarPaths) {
      await _safeBackupAddFileIfExists(
        docsPath: docsPath,
        absolutePath: path,
        out: out,
      );
    }

    for (final path in <String>[
      ...galleryPaths,
      ...backgroundPaths,
      ...musicPaths,
      // Custom cover/avatar media live at the docs root (not in the swept
      // subdirs), so add them explicitly by absolute path. The relative key
      // becomes their basename and is rebound to the new docs dir on restore.
      ...cosmeticMediaPaths,
    ]) {
      await _safeBackupAddFileIfExists(
        docsPath: docsPath,
        absolutePath: path,
        out: out,
      );
    }

    for (final sub in <String>[
      'attachments',
      'profile_media',
      'profile_avatars',
      'contact_avatars',
      // 🔴 Стикеры (08.08.2026, поле: «папка стикеров пустая после
      // восстановления»). Свои наборы существуют ТОЛЬКО здесь и в двух таблицах:
      // сервер их не хранит (каталог односторонний, выгрузки нет), поэтому копия
      // без них означала безвозвратную потерю. Восстановить набор из ничего
      // нельзя — картинки рисовал человек.
      'stickers',
    ]) {
      await _safeBackupAddDirectoryFiles(
        docsPath: docsPath,
        subDir: sub,
        out: out,
      );
    }

    return out;
  }

  Future<
    ({
      String profileId,
      String deviceId,
      String profileSecretB64,
      String deviceKeysMaterialJson,
      String serverBinding,
    })
  >
  _collectRestoreIdentityMaterial() async {
    final pid = _profileId;
    final did = _deviceId;
    if (pid == null || pid.isEmpty || did == null || did.isEmpty) {
      throw StateError('state not ready');
    }

    final secrets = SecureSecrets.create();
    final profileSecretB64 = await secrets.getProfileSecretB64(pid);
    if (profileSecretB64 == null || profileSecretB64.isEmpty) {
      throw StateError('missing profile secret');
    }

    final deviceKeysMaterialJson = await DeviceKeys.create().exportMaterialJson(
      profileId: pid,
      deviceId: did,
    );
    if (deviceKeysMaterialJson == null || deviceKeysMaterialJson.isEmpty) {
      throw StateError('missing device key material');
    }

    return (
      profileId: pid,
      deviceId: did,
      profileSecretB64: profileSecretB64,
      deviceKeysMaterialJson: deviceKeysMaterialJson,
      serverBinding: (savedServerBinding ?? currentServerBinding).trim(),
    );
  }

  Future<RecoveryKitPlainV1> _collectRecoveryKitPlain() async {
    final identity = await _collectRestoreIdentityMaterial();
    final plain = RecoveryKitPlainV1(
      profileId: identity.profileId,
      profileSecretB64: identity.profileSecretB64,
      deviceId: identity.deviceId,
      deviceKeysMaterialJson: identity.deviceKeysMaterialJson,
      serverBinding: identity.serverBinding,
    );
    plain.validateRestorePayload();
    return plain;
  }

  Future<SafeBackupPlainV1> _collectSafeBackupPlain({
    required bool includeBinaryFiles,
  }) async {
    _throwIfTransportBlocked();
    final identity = await _collectRestoreIdentityMaterial();
    final db = _db;
    if (db == null) {
      throw StateError('state not ready');
    }

    final contacts = await listContacts();
    final blocked = await listBlockedProfiles();
    final galleryPaths = _profileGalleryPaths
        .map((e) => e.trim())
        .where((e) => e.isNotEmpty)
        .toList(growable: false);
    final backgroundPaths = _profileBackgroundPaths
        .map((e) => e.trim())
        .where((e) => e.isNotEmpty)
        .toList(growable: false);
    final musicPaths = _profileMusicPaths
        .map((e) => e.trim())
        .where((e) => e.isNotEmpty)
        .toList(growable: false);
    final personalConvoIds =
        _personalConvoIds
            .map((e) => e.trim())
            .where((e) => e.isNotEmpty)
            .toList(growable: false)
          ..sort();
    final avatarPaths = <String>{
      if ((_myAvatarPath ?? '').trim().isNotEmpty) _myAvatarPath!.trim(),
      if ((_myAvatarOriginalPath ?? '').trim().isNotEmpty)
        _myAvatarOriginalPath!.trim(),
    }.toList(growable: false);
    final dbSnapshot = await _collectSafeBackupDbSnapshot(db);
    final cryptoKeyB64 = base64Encode(
      await SecureSecrets.create().requireExistingCryptoKey(),
    );
    // Custom cover/avatar media files (stored at the docs root) whose bytes ride
    // the file blob so the look survives a restore. Only the existing ones are
    // added by the collector; missing paths are silently skipped.
    final cosmeticMediaPaths = <String>{
      if ((_myCoverImagePath ?? '').trim().isNotEmpty)
        _myCoverImagePath!.trim(),
      if ((_myCoverVideoPath ?? '').trim().isNotEmpty)
        _myCoverVideoPath!.trim(),
      if ((_myAvatarVideoPath ?? '').trim().isNotEmpty)
        _myAvatarVideoPath!.trim(),
    }.toList(growable: false);
    // Лицо профиля едет ВСЕГДА, медиа переписки — по флагу. Раньше и то и
    // другое висело на одном флаге, и копия без медиа теряла аватар (см.
    // _collectSafeBackupProfileFaceFiles).
    final Map<String, String> filesB64ByRelativePath;
    if (includeBinaryFiles) {
      filesB64ByRelativePath = await _collectSafeBackupBinaryFiles(
        avatarPaths: avatarPaths,
        galleryPaths: galleryPaths,
        backgroundPaths: backgroundPaths,
        musicPaths: musicPaths,
        cosmeticMediaPaths: cosmeticMediaPaths,
      );
    } else {
      final docs = await getApplicationDocumentsDirectory();
      final faceOnly = <String, String>{};
      await _collectSafeBackupProfileFaceFiles(
        docsPath: p.normalize(docs.path),
        avatarPaths: avatarPaths,
        cosmeticMediaPaths: cosmeticMediaPaths,
        out: faceOnly,
      );
      filesB64ByRelativePath = faceOnly;
    }
    DiagLog.event('backup', 'files_collected', {
      'media': includeBinaryFiles,
      'count': filesB64ByRelativePath.length,
    });
    final cosmetics = _buildCosmeticsBackupMap(
      prefs: _prefs,
      includeMediaBasenames: includeBinaryFiles,
    );

    // Настройки — ЧЁРНЫМ списком: едет всё, кроме состояния этой установки.
    // Раньше в копию попадали семь значений, перечисленных вручную, при 77
    // ключах в приложении — терялись язык, тема, все уведомления, обои, звонки.
    final prefsForBackup = <String, Object?>{};
    final prefsSource = _prefs;
    if (prefsSource != null) {
      final raw = <String, Object?>{
        for (final key in prefsSource.getKeys()) key: prefsSource.get(key),
      };
      prefsForBackup.addAll(collectSafeBackupPrefs(raw));
    }

    return SafeBackupPlainV1(
      profileId: identity.profileId,
      profileSecretB64: identity.profileSecretB64,
      deviceId: identity.deviceId,
      deviceKeysMaterialJson: identity.deviceKeysMaterialJson,
      cryptoKeyB64: cryptoKeyB64,
      serverBinding: identity.serverBinding,
      contacts: contacts
          .map(
            (c) => SafeBackupContactV1(
              profileId: c.profileId,
              displayName: c.displayName,
            ),
          )
          .toList(growable: false),
      blockedProfiles: blocked,
      darkMode: _darkMode,
      blockUnverified: _blockUnverified,
      shareNicknameInQr: _shareNicknameInQr,
      myNickname: _myNickname,
      profileIconAssetPath: _profileIconAssetPath,
      profileAvatarGradientIndex: _profileAvatarGradientIndex,
      profileAvatarIconScale: _profileAvatarIconScale,
      profileGalleryPaths: galleryPaths,
      profileBackgroundPaths: backgroundPaths,
      profileMusicPaths: musicPaths,
      personalConvoIds: personalConvoIds,
      dbSnapshot: dbSnapshot,
      filesB64ByRelativePath: filesB64ByRelativePath,
      cosmetics: cosmetics,
      // Возраст копии — то, чего не хватало человеку, чтобы понять,
      // почему после восстановления вернулись давно удалённые чаты.
      createdAtMs: DateTime.now().millisecondsSinceEpoch,
      prefsAll: prefsForBackup.isEmpty ? null : prefsForBackup,
    );
  }

  /// Builds the optional cosmetics carrier for a safe-backup. Every entry is
  /// optional; an absent value means "stock / unset". Custom cover/avatar media
  /// are referenced by *basename* only (their bytes ride the file blob) and are
  /// rebound to the new docs dir on restore. Never includes entitlements.
  Map<String, Object?>? _buildCosmeticsBackupMap({
    required SharedPreferences? prefs,
    required bool includeMediaBasenames,
  }) {
    final out = <String, Object?>{};

    void putStr(String key, String? value) {
      final v = (value ?? '').trim();
      if (v.isNotEmpty) out[key] = v;
    }

    putStr('frame_id', _myFrameId);
    putStr('cover_id', _myCoverId);
    putStr('emoji_status', _myEmojiStatus);
    putStr('bio', _myBio);
    putStr('default_chat_wallpaper', _defaultChatWallpaperId);
    putStr('app_theme_preset_id', _appThemePresetId);
    putStr('chat_bubble_style_preset_id', _chatBubbleStylePresetId);
    out['bubble_color_is_manual'] = _bubbleColorIsManual;
    putStr('nickname_style_preset_id', _nicknameStylePresetId);
    putStr('indicator_color_preset_id', _indicatorColorPresetId);

    // Launcher icon (mirrored into prefs by AppIconService.setIcon).
    putStr('app_icon_key', prefs?.getString(_prefsAppIconKey));

    // Custom cover/avatar media — basenames only; bytes live in files_b64.
    if (includeMediaBasenames) {
      putStr('cover_image_basename', _basenameOrNull(_myCoverImagePath));
      putStr('cover_video_basename', _basenameOrNull(_myCoverVideoPath));
      putStr('avatar_video_basename', _basenameOrNull(_myAvatarVideoPath));
    }

    // Per-chat wallpaper overrides: '<prefix><convoId>' → wallpaper id.
    if (prefs != null) {
      final perChat = <String, Object?>{};
      for (final key in prefs.getKeys()) {
        if (!key.startsWith(_prefsChatWallpaperPrefix)) continue;
        final convoId = key.substring(_prefsChatWallpaperPrefix.length).trim();
        if (convoId.isEmpty) continue;
        final value = (prefs.getString(key) ?? '').trim();
        if (value.isEmpty) continue;
        perChat[convoId] = value;
      }
      if (perChat.isNotEmpty) out['chat_wallpapers'] = perChat;
    }

    return out.isEmpty ? null : out;
  }

  String? _basenameOrNull(String? path) {
    final v = (path ?? '').trim();
    if (v.isEmpty) return null;
    final base = p.basename(v).trim();
    return base.isEmpty ? null : base;
  }

  Future<String> createSafeBackupPayload({
    required String password,
    bool includeBinaryFiles = true,
  }) async {
    final plain = await _collectSafeBackupPlain(
      includeBinaryFiles: includeBinaryFiles,
    );
    return SafeBackupV1.encryptToPayload(plain: plain, password: password);
  }

  Future<String> createRecoveryKitPayload({required String password}) async {
    final plain = await _collectRecoveryKitPlain();
    return RecoveryKitV1.encryptToPayload(plain: plain, password: password);
  }

  Future<String> saveSafeBackupToDevice({
    required String password,
    bool? includeMedia,
  }) async {
    final payload = await createSafeBackupPayload(
      password: password,
      includeBinaryFiles: includeMedia ?? _safeBackupIncludeMedia,
    );
    final dir = await getApplicationDocumentsDirectory();
    final backupDir = Directory(p.join(dir.path, 'safe_backups'));
    if (!await backupDir.exists()) {
      await backupDir.create(recursive: true);
    }

    final ts = DateTime.now().millisecondsSinceEpoch;
    final stamp = DateTime.now().toUtc().toIso8601String().replaceAll(':', '-');
    final archivedFile = File(
      p.join(backupDir.path, 'safe_backup_$stamp.secretly'),
    );
    final latestFile = File(
      p.join(backupDir.path, 'safe_backup_latest.secretly'),
    );
    await archivedFile.writeAsString(payload, flush: true);
    await latestFile.writeAsString(payload, flush: true);
    // A device backup that silently fails to land is indistinguishable from
    // one that was never asked for — and the restore picker then finds
    // nothing, which is exactly what a user reported (2026-07-20). Record the
    // outcome so the next attempt is diagnosable instead of guessed at.
    DiagLog.event('backup', 'device_saved', {
      'bytes': payload.length,
      'media': includeMedia,
    });

    final prefs = _prefs ?? await SharedPreferences.getInstance();
    _prefs = prefs;
    await prefs.setString(_prefsSafeBackupLastDevicePathKey, latestFile.path);
    await prefs.setInt(_prefsSafeBackupLastDeviceSavedAtMsKey, ts);
    await _copySafeBackupToRememberedExternalPath(
      prefs: prefs,
      sourceFile: latestFile,
    );
    // The copy above lives in PRIVATE app storage: no file manager can see it
    // and uninstalling the app deletes it — exactly when a backup has to
    // survive (2026-07-21 report: "на телефоне найти её не могу"). Put a copy
    // in the public Downloads folder too. Best-effort: a failure here must
    // never fail the backup that already landed.
    await _copySafeBackupToPublicDownloads(prefs: prefs, sourceFile: latestFile);

    await _rememberBackedUpEventCount();
    return latestFile.path;
  }

  /// Android only: mirror the freshly written backup into public Downloads via
  /// MediaStore, so it is visible in Files and survives an uninstall. On iOS
  /// the app's Documents directory is already exposed to the Files app
  /// (UIFileSharingEnabled + LSSupportsOpeningDocumentsInPlace), so the copy
  /// written above is findable there without any extra step.
  Future<void> _copySafeBackupToPublicDownloads({
    required SharedPreferences prefs,
    required File sourceFile,
  }) async {
    if (!Platform.isAndroid) return;
    try {
      const channel = MethodChannel('secretly/media_store');
      final savedPath = await channel.invokeMethod<String>('saveToDownloads', {
        'fileName': 'secretly_backup_latest.secretly',
        'sourcePath': sourceFile.path,
      });
      if (savedPath != null && savedPath.trim().isNotEmpty) {
        await prefs.setString(_prefsSafeBackupPublicPathKey, savedPath);
        DiagLog.event('backup', 'public_copy_saved', const {});
      }
    } catch (e) {
      DiagLog.event('backup', 'public_copy_failed', {'err': _shortErrorTag(e)});
    }
  }

  /// Where the user-visible copy of the last device backup lives (Downloads on
  /// Android). Empty when there is none yet.
  String get safeBackupPublicPath =>
      _prefs?.getString(_prefsSafeBackupPublicPathKey) ?? '';

  Future<void> rememberSafeBackupExternalFilePath(String path) async {
    final normalized = path.trim();
    if (normalized.isEmpty) return;
    final prefs = _prefs ?? await SharedPreferences.getInstance();
    _prefs = prefs;
    await prefs.setString(_prefsSafeBackupExternalFilePathKey, normalized);
  }

  Future<void> _copySafeBackupToRememberedExternalPath({
    required SharedPreferences prefs,
    required File sourceFile,
  }) async {
    final externalPath =
        (prefs.getString(_prefsSafeBackupExternalFilePathKey) ?? '').trim();
    if (externalPath.isEmpty) return;
    if (p.normalize(externalPath) == p.normalize(sourceFile.path)) return;

    final targetFile = File(externalPath);
    final parent = targetFile.parent;
    if (!await parent.exists()) {
      await parent.create(recursive: true);
    }
    await sourceFile.copy(targetFile.path);
  }

  Future<String?> loadSafeBackupFromDevice() async {
    final prefs = _prefs ?? await SharedPreferences.getInstance();
    _prefs = prefs;
    var path = (prefs.getString(_prefsSafeBackupLastDevicePathKey) ?? '')
        .trim();
    if (path.isEmpty) {
      final dir = await getApplicationDocumentsDirectory();
      path = p.join(dir.path, 'safe_backups', 'safe_backup_latest.secretly');
    }
    final file = File(path);
    if (!await file.exists()) return null;
    final raw = (await file.readAsString()).trim();
    if (raw.isEmpty) return null;
    return raw;
  }

  bool get safeBackupAutoEnabled => _safeBackupAutoEnabled;
  bool get safeBackupAutoServerEnabled => _safeBackupAutoServerEnabled;
  bool get safeBackupAutoDeviceEnabled => _safeBackupAutoDeviceEnabled;
  bool get safeBackupIncludeMedia => _safeBackupIncludeMedia;
  int get safeBackupAutoIntervalMin => _safeBackupAutoIntervalMin;
  int get safeBackupLastAutoSuccessAtMs =>
      _prefs?.getInt(_prefsSafeBackupLastAutoSuccessAtMsKey) ?? 0;
  String get safeBackupLastAutoError =>
      (_prefs?.getString(_prefsSafeBackupLastAutoErrorKey) ?? '').trim();

  /// One-glance state of the only mechanism that can bring a user's history
  /// back. Surfaced in Settings so a backup that silently stopped working —
  /// no password set, an upload that keeps failing, a schedule that has not
  /// run in days — is visible where the user already looks, instead of only
  /// inside the backup screen they have no reason to open (2026-07-20).
  /// Loads just the safe-backup preferences, so the status logic can be tested
  /// without booting the whole controller (init opens the database, the relay
  /// and the network stack).
  @visibleForTesting
  Future<void> loadSafeBackupPrefsForTesting() async {
    final prefs = await SharedPreferences.getInstance();
    _prefs = prefs;
    _safeBackupAutoEnabled =
        prefs.getBool(_prefsSafeBackupAutoEnabledKey) ?? false;
    _safeBackupAutoServerEnabled =
        prefs.getBool(_prefsSafeBackupAutoServerEnabledKey) ?? true;
    _safeBackupAutoDeviceEnabled =
        prefs.getBool(_prefsSafeBackupAutoDeviceEnabledKey) ?? true;
    _safeBackupAutoIntervalMin =
        (prefs.getInt(_prefsSafeBackupAutoIntervalMinKey) ?? (24 * 60))
            .clamp(5, 7 * 24 * 60)
            .toInt();
  }

  /// When a backup of ANY kind last succeeded — auto run, manual cloud upload
  /// or manual device save.
  ///
  /// The header used to read only the AUTO success stamp, so a user who had
  /// just created a backup by hand was still told "Копия ещё не создана"
  /// (2026-07-21 report). Protection is protection, whoever triggered it.
  /// Лежит ли на сервере копия, сохранённая этим устройством.
  ///
  /// Э-1 (SEC-01), П-5а: после смены пароля такая копия остаётся зашифрованной
  /// ПРЕЖНИМ паролем — её нужно перезалить, иначе владелец при восстановлении
  /// введёт свой новый пароль и получит «неверный пароль» на собственный архив.
  bool get hasServerBackupCopy =>
      (_prefs?.getInt(_prefsSafeBackupLastServerSavedAtMsKey) ?? 0) > 0;

  /// Лежит ли на сервере копия БЕЗ опоры токена доступа — то есть такая, для
  /// скачивания которой достаточно знать идентификатор профиля.
  ///
  /// Опора выводится из пароля при сохранении, поэтому обновление приложения её
  /// не создаёт — нужно пересохранить копию. Владелец об этом знать не может:
  /// снаружи защищённый и незащищённый архив выглядят одинаково (сервер и
  /// отвечает одинаково — `backup_challenge` отдаёт обманную соль, чтобы
  /// посторонний не отличил одно от другого).
  ///
  /// Ложное срабатывание возможно у того, кто сохранил копию с опорой ещё до
  /// появления этого флага: он увидит подсказку один раз и она исчезнет после
  /// первого же пересохранения. Ошибка в эту сторону стоит лишнего нажатия,
  /// в обратную — архива, который владелец считает защищённым.
  bool get serverBackupNeedsAccessUpgrade {
    if (!hasServerBackupCopy) return false;
    return !(_prefs?.getBool(_prefsSafeBackupServerAccessBoundKey) ?? false);
  }

  int get safeBackupLastAnySuccessAtMs {
    final auto = safeBackupLastAutoSuccessAtMs;
    final device = safeBackupLastDeviceSavedAtMs;
    final server = _prefs?.getInt(_prefsSafeBackupLastServerSavedAtMsKey) ?? 0;
    var best = auto;
    if (device > best) best = device;
    if (server > best) best = server;
    return best;
  }

  SafeBackupHealth get safeBackupHealth {
    if (!_safeBackupAutoEnabled) return SafeBackupHealth.off;
    if (safeBackupLastAutoError.isNotEmpty) return SafeBackupHealth.failing;
    final lastOk = safeBackupLastAnySuccessAtMs;
    if (lastOk <= 0) return SafeBackupHealth.pending;
    // Three missed intervals is a schedule that is no longer running, not a
    // device that happened to be asleep.
    final staleAfterMs = _safeBackupAutoIntervalMin * 60 * 1000 * 3;
    final age = DateTime.now().millisecondsSinceEpoch - lastOk;
    return age > staleAfterMs ? SafeBackupHealth.stale : SafeBackupHealth.ok;
  }

  int get safeBackupLastDeviceSavedAtMs =>
      _prefs?.getInt(_prefsSafeBackupLastDeviceSavedAtMsKey) ?? 0;

  Future<void> setSafeBackupAutoEnabled(bool value) async {
    _safeBackupAutoEnabled = value;
    final prefs = _prefs ?? await SharedPreferences.getInstance();
    _prefs = prefs;
    await prefs.setBool(_prefsSafeBackupAutoEnabledKey, value);
    if (!value) {
      await prefs.remove(_prefsSafeBackupLastAutoErrorKey);
    } else {
      // Turning it ON must DO something now, not in up to 24 hours
      // (2026-07-21 report: "включил, указал пароль — и тишина").
      //
      // Two things conspired: nothing ever called the scheduler with
      // force:true, and the "password is not set" branch stamps the attempt
      // clock before bailing — so once the user fixed the password, the very
      // next tick saw a fresh attempt stamp and skipped for a whole interval.
      // Clearing the stamp + forcing one run makes enabling feel like what it
      // says: protection starts now.
      await prefs.remove(_prefsSafeBackupLastAutoAttemptAtMsKey);
      await prefs.remove(_prefsSafeBackupLastAutoErrorKey);
      unawaited(_kickImmediateAutoSafeBackup());
    }
    _changed.add(null);
  }

  /// Runs the auto-backup once, right now, ignoring the interval — used the
  /// moment the user enables auto-backup or supplies the password it was
  /// waiting on. Best-effort: any failure is recorded as the usual last-error
  /// and surfaced by the status header, never thrown at the caller.
  Future<void> _kickImmediateAutoSafeBackup() async {
    try {
      await _maybeRunAutoSafeBackup(force: true);
    } catch (e) {
      DiagLog.event('backup', 'immediate_kick_failed', {
        'err': _shortErrorTag(e),
      });
    }
  }

  Future<void> setSafeBackupAutoServerEnabled(bool value) async {
    _safeBackupAutoServerEnabled = value;
    final prefs = _prefs ?? await SharedPreferences.getInstance();
    _prefs = prefs;
    await prefs.setBool(_prefsSafeBackupAutoServerEnabledKey, value);
    _changed.add(null);
    await _clearSafeBackupError();
  }

  Future<void> setSafeBackupAutoDeviceEnabled(bool value) async {
    _safeBackupAutoDeviceEnabled = value;
    final prefs = _prefs ?? await SharedPreferences.getInstance();
    _prefs = prefs;
    await prefs.setBool(_prefsSafeBackupAutoDeviceEnabledKey, value);
    _changed.add(null);
    await _clearSafeBackupError();
  }

  Future<void> setSafeBackupIncludeMedia(bool value) async {
    _safeBackupIncludeMedia = value;
    final prefs = _prefs ?? await SharedPreferences.getInstance();
    _prefs = prefs;
    await prefs.setBool(_prefsSafeBackupIncludeMediaKey, value);
    _changed.add(null);
  }

  Future<void> setSafeBackupAutoIntervalMinutes(int minutes) async {
    final clamped = minutes.clamp(5, 7 * 24 * 60).toInt();
    _safeBackupAutoIntervalMin = clamped;
    final prefs = _prefs ?? await SharedPreferences.getInstance();
    _prefs = prefs;
    await prefs.setInt(_prefsSafeBackupAutoIntervalMinKey, clamped);
    _changed.add(null);
    await _clearSafeBackupError();
  }

  /// Clears the last auto-backup error.
  ///
  /// The header reads that string, so leaving it set after the user has FIXED
  /// the cause makes the app keep claiming "backups are failing" until the
  /// next successful run — up to a full interval later. Any change to the
  /// backup configuration is a fresh start (2026-07-20).
  Future<void> _clearSafeBackupError() async {
    final prefs = _prefs ?? await SharedPreferences.getInstance();
    if ((prefs.getString(_prefsSafeBackupLastAutoErrorKey) ?? '').isEmpty) {
      return;
    }
    await prefs.remove(_prefsSafeBackupLastAutoErrorKey);
    _changed.add(null);
  }

  Future<void> setSafeBackupAutoPassword(String password) async {
    final pid = (_profileId ?? '').trim();
    if (pid.isEmpty) throw StateError('profile not ready');
    BackupPasswordPolicy.validateOrThrow(password);
    await SecureSecrets.create().setSafeBackupAutoPassword(
      profileId: pid,
      password: password,
    );
    // The most common stale error is "password is not set" — the user has just
    // fixed exactly that.
    await _clearSafeBackupError();
    // The password WAS the blocker, and the failed attempt it caused also
    // stamped the interval clock. Clear that stamp and run once now, so
    // supplying the password produces a visible backup instead of silence.
    if (_safeBackupAutoEnabled) {
      final prefs = _prefs ?? await SharedPreferences.getInstance();
      _prefs = prefs;
      await prefs.remove(_prefsSafeBackupLastAutoAttemptAtMsKey);
      unawaited(_kickImmediateAutoSafeBackup());
    }
  }

  Future<void> clearSafeBackupAutoPassword() async {
    final pid = (_profileId ?? '').trim();
    if (pid.isEmpty) return;
    await SecureSecrets.create().deleteSafeBackupAutoPassword(pid);
  }

  Future<bool> hasSafeBackupAutoPassword() async {
    final pid = (_profileId ?? '').trim();
    if (pid.isEmpty) return false;
    final pw = await SecureSecrets.create().getSafeBackupAutoPassword(pid);
    return pw != null && BackupPasswordPolicy.validate(pw).isValid;
  }

  Future<void> _maybeRunAutoSafeBackup({required bool force}) async {
    if (_safeBackupAutoInFlight) return;
    if (!_safeBackupAutoEnabled) return;
    if (!_safeBackupAutoServerEnabled && !_safeBackupAutoDeviceEnabled) return;
    if (_transportBlocked) return;

    final pid = (_profileId ?? '').trim();
    if (pid.isEmpty || pid.startsWith('LOCAL-')) return;

    final prefs = _prefs ?? await SharedPreferences.getInstance();
    _prefs = prefs;

    final now = DateTime.now().millisecondsSinceEpoch;
    final lastAttempt =
        prefs.getInt(_prefsSafeBackupLastAutoAttemptAtMsKey) ?? 0;
    final intervalMs = _safeBackupAutoIntervalMin * 60 * 1000;
    if (!force && (now - lastAttempt) < intervalMs) return;

    final pw = await SecureSecrets.create().getSafeBackupAutoPassword(pid);
    if (pw == null || !BackupPasswordPolicy.validate(pw).isValid) {
      // Stamp the attempt BEFORE bailing out. Without it this branch is not
      // throttled by the interval at all: the 3-second service watchdog would
      // re-enter it forever, reading the keychain, writing prefs to disk and
      // firing a change event — which rebuilds every StreamBuilder in the app.
      await prefs.setInt(_prefsSafeBackupLastAutoAttemptAtMsKey, now);
      await prefs.setString(
        _prefsSafeBackupLastAutoErrorKey,
        pw == null
            ? 'Auto-backup password is not set'
            : 'Auto-backup password does not meet the current policy',
      );
      _changed.add(null);
      return;
    }

    _safeBackupAutoInFlight = true;
    try {
      await prefs.setInt(_prefsSafeBackupLastAutoAttemptAtMsKey, now);

      // OVERWRITE GUARD (2026-07-20). The server keeps ONE backup per profile,
      // so every upload destroys the previous copy. A device that has lost its
      // history — re-keyed, restored wrong, storage damaged — must not be
      // allowed to push that loss over the user's last good copy unattended.
      // `force` is the explicit "back up now" button, which may still proceed.
      final liveDb = _db;
      if (liveDb == null) {
        // Storage is not open yet. That is "not ready", not "history lost" —
        // reporting a shrink here would both scare the user and burn the
        // attempt timestamp.
        _safeBackupAutoInFlight = false;
        return;
      }
      final nextEvents = await liveDb.countEvents();
      final previousEvents = prefs.getInt(_prefsSafeBackupLastEventCountKey) ?? 0;
      if (!force &&
          !SafeBackupRegressionGuard.allowsOverwrite(
            previousEvents: previousEvents,
            nextEvents: nextEvents,
          )) {
        final reason = SafeBackupRegressionGuard.refusalReason(
          previousEvents: previousEvents,
          nextEvents: nextEvents,
        )!;
        await prefs.setString(_prefsSafeBackupLastAutoErrorKey, reason);
        DiagLog.event('backup', 'auto_skipped_shrink', {
          'prev': previousEvents,
          'next': nextEvents,
        });
        _safeBackupAutoInFlight = false;
        _changed.add(null);
        return;
      }

      var done = false;
      if (_safeBackupAutoServerEnabled) {
        final ok = await uploadSafeBackupToServer(password: pw);
        if (!ok) {
          throw StateError('Server backup upload returned false');
        }
        done = true;
      }
      if (_safeBackupAutoDeviceEnabled) {
        await saveSafeBackupToDevice(
          password: pw,
          includeMedia: _safeBackupIncludeMedia,
        );
        done = true;
      }
      if (done) {
        await prefs.setInt(_prefsSafeBackupLastAutoSuccessAtMsKey, now);
        await prefs.remove(_prefsSafeBackupLastAutoErrorKey);
      }
    } catch (e) {
      await prefs.setString(_prefsSafeBackupLastAutoErrorKey, e.toString());
    } finally {
      _safeBackupAutoInFlight = false;
      _changed.add(null);
    }
  }

  /// Records how much history the freshly-stored backup holds.
  ///
  /// The guard compares against this, so it MUST be updated by every path that
  /// successfully writes a backup — otherwise a legitimate mass-delete leaves
  /// the bar permanently above the device and blocks backups for good.
  Future<void> _rememberBackedUpEventCount() async {
    try {
      final db = _db;
      if (db == null) return;
      // 🔴 NOT `countEvents()`, which answers 0 on a query failure (2026-07-31).
      // This number becomes the bar the shrink guard compares against, and the
      // guard fails OPEN at zero — "nothing worth protecting yet". So one
      // transient database hiccup here would quietly DISARM the protection that
      // stops a damaged install from overwriting the user's last good backup.
      //
      // Leaving the previous bar in place is strictly better: it stays
      // conservative until a count we actually trust replaces it.
      final counted = await db.countEventsOrNull();
      if (counted == null) {
        DiagLog.event('backup', 'event_count_unavailable', const {});
        return;
      }
      final prefs = _prefs ?? await SharedPreferences.getInstance();
      await prefs.setInt(_prefsSafeBackupLastEventCountKey, counted);
    } catch (_) {
      // Never fail a completed backup over its bookkeeping.
    }
  }

  /// Э-1 (SEC-01): подпись сохранения архива вместе с опорой токена доступа.
  ///
  /// 🔴 Вынесено в одно место НАМЕРЕННО. Путей сохранения архива два, код
  /// подписи в них был одинаковым — а правка одного пути из двух в этом
  /// проекте случалась трижды и каждый раз молчала. Теперь пропустить путь
  /// нельзя: подпись и опора считаются только здесь.
  Future<({String sigB64, String accessSaltB64, String accessVerifierB64})>
  _signBackupSetWithAccess({
    required String profileId,
    required String deviceId,
    required String password,
    required String payloadSha256B64,
    required int tsMs,
    required String nonceB64,
  }) async {
    // Опора выводится из того же пароля, которым ТОЛЬКО ЧТО зашифрован архив,
    // и уходит вместе с ним. Иначе проверочное значение и содержимое разойдутся
    // по разным паролям, и владелец пройдёт проверку доступа, но не расшифрует
    // архив.
    final access = await BackupAccessV1.mint(password: password);
    final kp = await DeviceKeys.create().loadIdentityKeyPair(
      profileId: profileId,
      deviceId: deviceId,
    );
    final msg = AuthSigner.keysBackupSetMessageV2(
      profileId: profileId,
      deviceId: deviceId,
      payloadSha256B64: payloadSha256B64,
      accessSaltB64: access.saltB64,
      accessVerifierB64: access.verifierB64,
      tsMs: tsMs,
      nonceB64: nonceB64,
    );
    final sigB64 = await AuthSigner.signEd25519B64(
      identityKeyPair: kp,
      message: msg,
    );
    return (
      sigB64: sigB64,
      accessSaltB64: access.saltB64,
      accessVerifierB64: access.verifierB64,
    );
  }

  Future<bool> uploadSafeBackupToServer({required String password}) async {
    _throwIfTransportBlocked();
    final keys = _keys;
    final pid = _profileId;
    final did = _deviceId;
    final db = _db;
    if (keys == null ||
        pid == null ||
        pid.isEmpty ||
        did == null ||
        did.isEmpty ||
        db == null) {
      throw StateError('state not ready');
    }

    final plain = await _collectSafeBackupPlain(includeBinaryFiles: false);
    final profileSecretB64 = plain.profileSecretB64;

    final payload = await SafeBackupV1.encryptToPayload(
      plain: plain,
      password: password,
    );
    final payloadSha256B64 = await AuthSigner.sha256B64(utf8.encode(payload));
    final tsMs = ServerClock.instance.nowMs();
    final nonceB64 = AuthSigner.randomNonceB64(bytes: 16);

    final auth = await _signBackupSetWithAccess(
      profileId: pid,
      deviceId: did,
      password: password,
      payloadSha256B64: payloadSha256B64,
      tsMs: tsMs,
      nonceB64: nonceB64,
    );

    final ok = await keys.backupSet(
      profileId: pid,
      deviceId: did,
      payload: payload,
      payloadSha256B64: payloadSha256B64,
      tsMs: tsMs,
      nonceB64: nonceB64,
      signatureB64: auth.sigB64,
      profileSecretB64: profileSecretB64,
      accessSaltB64: auth.accessSaltB64,
      accessVerifierB64: auth.accessVerifierB64,
    );
    if (ok) {
      await _rememberBackedUpEventCount();
      // Stamp the server copy so the status header counts it. Every backup
      // path must leave a mark, or "protected" silently means "auto-protected".
      final prefs = _prefs ?? await SharedPreferences.getInstance();
      _prefs = prefs;
      await prefs.setInt(
        _prefsSafeBackupLastServerSavedAtMsKey,
        DateTime.now().millisecondsSinceEpoch,
      );
      // Записывается фактический результат, а не намерение: если по какой-то
      // причине опора не ушла, подсказка обязана остаться на экране.
      await prefs.setBool(
        _prefsSafeBackupServerAccessBoundKey,
        auth.accessSaltB64.isNotEmpty && auth.accessVerifierB64.isNotEmpty,
      );
      _changed.add(null);
    }
    return ok;
  }

  /// Uploads a server Safe Backup and then PROVES it landed by reading it back
  /// (device-authenticated) and comparing the SHA-256. Returns a rich result so
  /// callers can show the on-server timestamp + size instead of a bare boolean.
  ///
  /// Why this exists (2026-07-05 incident): the plain [uploadSafeBackupToServer]
  /// returns a boolean the server derives from `backup_set`, and the server
  /// silently answers `ok:false` for ~9 distinct reasons (payload over the
  /// 1.2 MB cap, clock skew > 5 min, profile-secret / signature / device-binding
  /// mismatch, …). A UI that only checks "did it throw" can show "success" while
  /// nothing was stored — exactly what stranded profile KWC7. This path fails
  /// LOUD: it pre-checks the size cap, treats `ok:false` as an error, and
  /// verifies the stored bytes before claiming success.
  Future<SafeBackupUploadResult> uploadSafeBackupToServerVerified({
    required String password,
  }) async {
    _throwIfTransportBlocked();
    final keys = _keys;
    final pid = _profileId;
    final did = _deviceId;
    final db = _db;
    if (keys == null ||
        pid == null ||
        pid.isEmpty ||
        did == null ||
        did.isEmpty ||
        db == null) {
      throw StateError('state not ready');
    }

    final plain = await _collectSafeBackupPlain(includeBinaryFiles: false);
    final profileSecretB64 = plain.profileSecretB64;

    final payload = await SafeBackupV1.encryptToPayload(
      plain: plain,
      password: password,
    );
    final payloadBytes = utf8.encode(payload);
    // Server rejects payloads over this cap (keys/src/main.rs
    // KEYS_BACKUP_MAX_PAYLOAD_BYTES) with a bare ok:false. Catch it here so the
    // user gets an actionable message instead of a mystery failure. Keep this in
    // lockstep with the server constant.
    const serverPayloadCapBytes = 200 * 1024 * 1024;
    if (payloadBytes.length > serverPayloadCapBytes) {
      throw StateError(
        'Резервная копия слишком большая для сервера: '
        '${(payloadBytes.length / 1024 / 1024).toStringAsFixed(2)} МБ '
        '(лимит ${(serverPayloadCapBytes / 1024 / 1024).toStringAsFixed(0)} МБ). '
        'Сохраните копию в файл на этом ПК.',
      );
    }

    final payloadSha256B64 = await AuthSigner.sha256B64(payloadBytes);
    final tsMs = ServerClock.instance.nowMs();
    final nonceB64 = AuthSigner.randomNonceB64(bytes: 16);

    final auth = await _signBackupSetWithAccess(
      profileId: pid,
      deviceId: did,
      password: password,
      payloadSha256B64: payloadSha256B64,
      tsMs: tsMs,
      nonceB64: nonceB64,
    );

    final ok = await keys.backupSet(
      profileId: pid,
      deviceId: did,
      payload: payload,
      payloadSha256B64: payloadSha256B64,
      tsMs: tsMs,
      nonceB64: nonceB64,
      signatureB64: auth.sigB64,
      profileSecretB64: profileSecretB64,
      accessSaltB64: auth.accessSaltB64,
      accessVerifierB64: auth.accessVerifierB64,
    );
    if (!ok) {
      // Server accepted the request shape but refused to store — profile-secret
      // mismatch, device not bound to this profile, bad signature, or clock
      // skew. Do NOT report success.
      throw StateError(
        'Сервер отклонил резервную копию (backup_set → ok:false). '
        'Проверьте, что это устройство привязано к профилю $pid, и повторите.',
      );
    }

    // PROOF: read the stored backup back with device auth and compare bytes.
    final (exists, storedPayload, updatedAtMs) = await backupGetFromServer(
      pid,
      useDeviceAuth: true,
    );
    if (!exists || storedPayload == null) {
      throw StateError(
        'Сервер подтвердил запись, но копия не читается обратно. '
        'Считайте загрузку НЕуспешной и повторите.',
      );
    }
    final storedSha = await AuthSigner.sha256B64(utf8.encode(storedPayload));
    if (storedSha != payloadSha256B64) {
      throw StateError(
        'Копия на сервере не совпадает с загруженной (хеш отличается). '
        'Считайте загрузку НЕуспешной и повторите.',
      );
    }

    // Отметки ставятся только здесь — после того, как копия прочитана обратно
    // и хеш сошёлся. Раньше этот путь (десктоп) не оставлял следа вовсе, и
    // статус-заголовок продолжал утверждать «копия ещё не создана» после
    // успешной проверенной загрузки; та же дыра оставила бы висеть подсказку
    // о пересохранении у того, кто уже всё пересохранил.
    final prefs = _prefs ?? await SharedPreferences.getInstance();
    _prefs = prefs;
    await prefs.setInt(
      _prefsSafeBackupLastServerSavedAtMsKey,
      DateTime.now().millisecondsSinceEpoch,
    );
    await prefs.setBool(
      _prefsSafeBackupServerAccessBoundKey,
      auth.accessSaltB64.isNotEmpty && auth.accessVerifierB64.isNotEmpty,
    );
    _changed.add(null);

    return SafeBackupUploadResult(
      profileId: pid,
      payloadBytes: payloadBytes.length,
      serverUpdatedAtMs: updatedAtMs,
    );
  }

  Future<void> restoreFromSafeBackupPayload({
    required String payload,
    required String password,
    bool completeOnboarding = false,
    bool restoreAsNewDevice = false,
  }) async {
    final plain = await decryptSafeBackupPayloadForRestore(
      payload: payload,
      password: password,
    );
    await restoreFromSafeBackup(
      plain,
      completeOnboarding: completeOnboarding,
      restoreAsNewDevice: restoreAsNewDevice,
    );
  }

  Future<SafeBackupPlainV1> decryptSafeBackupPayloadForRestore({
    required String payload,
    required String password,
  }) async {
    try {
      return await SafeBackupV1.decryptFromPayload(
        payload: payload,
        password: password,
      );
    } catch (error) {
      throw describeEncryptedRestoreError(error);
    }
  }

  Future<void> restoreFromSafeBackup(
    SafeBackupPlainV1 kit, {
    bool completeOnboarding = false,
    bool restoreAsNewDevice = false,
  }) async {
    final restoredKit = (() {
      try {
        return SafeBackupPlainV1.fromJson(kit.toJson());
      } catch (error) {
        throw describeEncryptedRestoreError(error);
      }
    })();
    final restoredDeviceId = restoredKit.deviceId.trim();
    // И-1 stage c (TZ_I1_IDENTITY_2026-07-21): a backup restore always
    // rebuilds an EMPTY session store (the snapshot deliberately carries no
    // ratchet tables), so reusing the restored device_id recreates the
    // forbidden "same id, clean sessions" state. Under the verified server
    // switch the restore therefore comes up as a NEW device. Unlike the
    // db-loss rotation, the restored id is NOT put into the delete ledger:
    // the device that wrote this backup may still be alive (second phone),
    // and the ledger's rebind would steal a living device's mailbox.
    final rotateOnRestore =
        restoreAsNewDevice ||
        (!_isDesktopOrWebPlatform &&
            await _resolveIdentityRotationFlagBounded());
    final activeDeviceId = rotateOnRestore ? _uuid.v4() : restoredDeviceId;
    DiagLog.event('i1', 'state_loss', {
      'path': 'restore_backup',
      'new_device': rotateOnRestore,
    });
    final knownOwnDeviceIds = <String>{
      activeDeviceId,
      restoredDeviceId,
    }.where((deviceId) => deviceId.trim().isNotEmpty).toList(growable: false);

    // Stop background tasks.
    _pumpTimer?.cancel();
    _mainAliveHeartbeatTimer?.cancel();
    _pumpTimer = null;
    _serviceWatchdogTimer?.cancel();
    _serviceWatchdogTimer = null;
    _quarantineRecoverySweepTimer?.cancel();
    _quarantineRecoverySweepTimer = null;

    await _closeRuntimeNetworkClientsForDiscard();

    try {
      await _db?.close();
    } catch (_) {}
    _db = null;

    await AppDb.deleteLocalDatabaseFiles();

    // MEDIA SAFETY (2026-07-20). Wiping the media directories is only correct
    // when the backup can put them back. The SERVER copy never carries media —
    // uploads are hardcoded `includeBinaryFiles: false` — so restoring from the
    // cloud used to delete every attachment, avatar and sticker with nothing to
    // replace them: a guaranteed loss on the very path a user reaches for after
    // losing a phone. Only clear what this backup actually restores.
    final restoresMedia =
        (restoredKit.filesB64ByRelativePath ?? const <String, String>{})
            .isNotEmpty;
    if (restoresMedia) {
      await _clearLocalProfileMediaCaches();
    } else {
      // Keep the attachment directories (this backup cannot replace them), but
      // the personal avatar must still go: it is keyed by a fixed filename, so
      // the restored account would otherwise inherit the PREVIOUS account's
      // photo and republish it as its own profile picture.
      try {
        final docs = await getApplicationDocumentsDirectory();
        final myAvatar = File(p.join(docs.path, 'my_avatar.png'));
        if (await myAvatar.exists()) await myAvatar.delete();
      } catch (_) {
        // Best-effort.
      }
      DiagLog.event('backup', 'restore_kept_media', const {});
    }

    final prefs = _prefs ?? await SharedPreferences.getInstance();
    _prefs = prefs;

    // Clear profile-local state (keep UI prefs like darkMode/nickname settings).
    // Restoring an older/smaller backup must not leave a bar above the
    // device: it would block backups from the first launch after a
    // restore — exactly when protection matters most.
    await prefs.remove(_prefsSafeBackupLastEventCountKey);
    // Кто стёр личность — записать ДО стирания: потом улики нет.
    await IdentityJournal.recordProfileIdCleared(
      by: 'restore_from_safe_backup',
      nowMs: DateTime.now().millisecondsSinceEpoch,
      previousProfileId: prefs.getString(_prefsProfileIdKey),
      previousDeviceId: prefs.getString(_prefsDeviceIdKey),
      deviceIdClearedToo: true,
    );
    await prefs.remove(_prefsProfileIdKey);
    await prefs.remove(_prefsDeviceIdKey);
    await prefs.remove(_prefsAllowMissingCurrentDeviceRepairOnceKey);
    await prefs.remove(_prefsServerBindingKey);
    await prefs.remove(_prefsRelayNextSeqKey);
    await prefs.remove(_prefsMyAvatarPathKey);
    await prefs.remove(_prefsMyAvatarOriginalPathKey);
    await prefs.remove(_prefsProfileIconAssetPathKey);
    await prefs.remove(_prefsProfileAvatarGradientIndexKey);
    await prefs.remove(_prefsProfileAvatarIconScaleKey);
    await prefs.remove(_prefsPrivacyDeleteAccountMonthsKey);

    final keysToRemove = prefs
        .getKeys()
        .where((k) => k.startsWith(_prefsKeysPublishedKeyPrefix))
        .toList(growable: false);
    for (final k in keysToRemove) {
      await prefs.remove(k);
    }

    // Apply recovered identity.
    await prefs.setString(_prefsProfileIdKey, restoredKit.profileId);
    await prefs.setString(_prefsDeviceIdKey, activeDeviceId);
    await prefs.setString(_prefsServerBindingKey, restoredKit.serverBinding);
    await prefs.setInt(_prefsRelayNextSeqKey, 1);
    if (rotateOnRestore) {
      await prefs.setBool(_prefsAllowMissingCurrentDeviceRepairOnceKey, true);
      // Post-restart, after keys setup: one no-op control per recent 1:1 peer
      // so their learn-on-receive converges to the new id immediately.
      await prefs.setBool(_prefsI1AnnouncePendingKey, true);
      DiagLog.event('i1', 'rotated', {
        'reason': 'restore_backup',
        'old': DiagLog.pfx(restoredDeviceId),
        'new': DiagLog.pfx(activeDeviceId),
      });
    }

    // Все переносимые настройки человека — ДО поимённых ниже.
    //
    // Порядок важен: поимённые семь идут после и перекрывают блок. Так копия,
    // снятая старой сборкой (без `prefs_all`), ведёт себя ровно как раньше, а
    // новая — восстанавливает и остальные ~65 настроек: язык, тему, все
    // уведомления, обои чатов, звонки, стиль ника.
    //
    // Чёрный список применяется и на приёме: состояние ЭТОЙ установки
    // (курсор ящика, разовые очереди) не имеет права приехать с чужого
    // устройства. См. safe_backup_prefs.dart.
    final restoredPrefsAll = restoredKit.prefsAll;
    if (restoredPrefsAll != null && restoredPrefsAll.isNotEmpty) {
      final decoded = decodeSafeBackupPrefs(restoredPrefsAll);
      var applied = 0;
      for (final entry in decoded.entries) {
        final value = entry.value;
        try {
          if (value is bool) {
            await prefs.setBool(entry.key, value);
          } else if (value is int) {
            await prefs.setInt(entry.key, value);
          } else if (value is double) {
            await prefs.setDouble(entry.key, value);
          } else if (value is String) {
            await prefs.setString(entry.key, value);
          } else if (value is List<String>) {
            await prefs.setStringList(entry.key, value);
          } else {
            continue;
          }
          applied++;
        } catch (_) {
          // Одна испорченная настройка не имеет права сорвать восстановление
          // всего остального — она просто останется со значением по умолчанию.
        }
      }
      DiagLog.event('backup', 'prefs_restored', {
        'applied': applied,
        'in_payload': restoredPrefsAll.length,
      });
    }

    // Restore UI prefs.
    await prefs.setBool(_prefsDarkModeKey, restoredKit.darkMode);
    await prefs.setBool(_prefsBlockUnverifiedKey, restoredKit.blockUnverified);
    await prefs.setBool(
      _prefsShareNicknameInQrKey,
      restoredKit.shareNicknameInQr,
    );
    await prefs.setString(_prefsMyNicknameKey, restoredKit.myNickname);
    final restoredIconAssetPath = restoredKit.profileIconAssetPath?.trim();
    if (restoredIconAssetPath != null && restoredIconAssetPath.isNotEmpty) {
      _profileIconAssetPath = restoredIconAssetPath;
      _profileAvatarGradientIndex = restoredKit.profileAvatarGradientIndex;
      _profileAvatarIconScale = restoredKit.profileAvatarIconScale;
      await prefs.setString(
        _prefsProfileIconAssetPathKey,
        restoredIconAssetPath,
      );
      await prefs.setInt(
        _prefsProfileAvatarGradientIndexKey,
        restoredKit.profileAvatarGradientIndex,
      );
      await prefs.setDouble(
        _prefsProfileAvatarIconScaleKey,
        restoredKit.profileAvatarIconScale,
      );
    } else {
      _profileIconAssetPath = null;
      _profileAvatarGradientIndex = 0;
      _profileAvatarIconScale = 1.0;
    }
    await prefs.setStringList(
      _prefsProfileGalleryPathsKey,
      restoredKit.profileGalleryPaths,
    );
    await prefs.setStringList(
      _prefsProfileBackgroundPathsKey,
      restoredKit.profileBackgroundPaths,
    );
    await prefs.setStringList(
      _prefsProfileMusicPathsKey,
      restoredKit.profileMusicPaths,
    );
    await prefs.setStringList(
      _prefsPersonalConvoIdsKey,
      restoredKit.personalConvoIds,
    );

    // Persist secrets + device key material.
    final secrets = SecureSecrets.create();
    await secrets.setProfileSecretB64(
      profileId: restoredKit.profileId,
      secretB64: restoredKit.profileSecretB64,
    );
    final restoredCryptoKeyB64 = restoredKit.cryptoKeyB64;
    if (restoredCryptoKeyB64 != null && restoredCryptoKeyB64.isNotEmpty) {
      await secrets.setCryptoKeyB64(restoredCryptoKeyB64);
    }
    if (!rotateOnRestore) {
      await DeviceKeys.create().importMaterialJson(
        profileId: restoredKit.profileId,
        deviceId: restoredKit.deviceId,
        rawJson: restoredKit.deviceKeysMaterialJson,
      );
    }
    // 🔴 Ключ личности АККАУНТА переносится ВСЕГДА, снаружи условия про ротацию.
    // Ротация означает новое УСТРОЙСТВО, но человек тот же, и именно в этом весь
    // смысл слоя 2: номер безопасности принадлежит человеку. Импортируй мы сид
    // внутри `if (!rotateOnRestore)`, восстановление с ротацией теряло бы ключ,
    // на новом устройстве родился бы другой, и у ВСЕХ собеседников выскочило бы
    // «номер безопасности изменился» — то есть путь восстановления сам приносил
    // бы ту болезнь, от которой лечит эта работа.
    //
    // Отказ беззвучный: без сида клиент просто ведёт себя как старая сборка, а
    // сорвать здесь восстановление значило бы обменять доступ к аккаунту на
    // косметику номера.
    // 🔴 device_id ИЗ КОПИИ — свой, и его надо запомнить навсегда (08.08.2026,
    // поле: «после восстановления все пузыри стали как пузыри собеседника»).
    //
    // Все восстановленные сообщения подписаны ЭТИМ идентификатором. Текущее
    // устройство после восстановления другое, а старое с сервера вытесняется —
    // значит без этой строки узнать его больше НЕОТКУДА, и свои сообщения
    // навсегда остаются слева. Тот же приём уже применён при связке с десктопом
    // (`seededOwnDeviceIds`), просюда его просто не донесли.
    await _rememberOwnDeviceIds(<String>[restoredKit.deviceId]);

    final restoredAccountSeed = restoredKit.accountIdentitySeedB64;
    if (restoredAccountSeed != null && restoredAccountSeed.isNotEmpty) {
      try {
        await AccountIdentity.create().importSeedB64(
          profileId: restoredKit.profileId,
          seedB64: restoredAccountSeed,
        );
      } catch (e) {
        DiagLog.event('acct', 'account_identity_restore_failed', <String, Object?>{
          'reason': e.runtimeType.toString(),
        });
      }
    }
    // else: a rotated restore is a NEW device — fresh identity material is
    // minted on demand under activeDeviceId by the keys setup. Importing the
    // kit's material here used to be keyed to the OLD id anyway (the dormant
    // restoreAsNewDevice=true bug: import under restoredKit.deviceId, active
    // id elsewhere), so nothing ever consumed it — now that is explicit.

    final restoredFiles = _decodeSafeBackupFiles(
      restoredKit.filesB64ByRelativePath,
    );
    await _restoreSafeBackupFilesToDocuments(restoredFiles);
    try {
      final docs = await getApplicationDocumentsDirectory();
      // FIX (2026-07-13, profile photo persistence, Defect A): the avatar still
      // is packed + restored under its TIMESTAMPED name (my_avatar_<micros>.png),
      // not the fixed 'my_avatar.png' this re-point used to look for — which is
      // never written — so the pointer was never rebound and the photo was lost
      // on EVERY safe-backup restore. Rebind to the actually-restored file using
      // the backup's own relative keys (falling back to the legacy fixed name).
      String? stillRel;
      String? originalRel;
      for (final rel in restoredKit.filesB64ByRelativePath?.keys ??
          const <String>[]) {
        final base = p.basename(rel.replaceAll('\\', '/'));
        if (base.startsWith('my_avatar_original_')) {
          originalRel = rel;
        } else if (base.startsWith('my_avatar_') && base.endsWith('.png')) {
          stillRel = rel;
        }
      }
      if (stillRel != null && File(p.join(docs.path, stillRel)).existsSync()) {
        final stillPath = p.join(docs.path, stillRel);
        await prefs.setString(_prefsMyAvatarPathKey, stillPath);
        final origPath = (originalRel != null &&
                File(p.join(docs.path, originalRel)).existsSync())
            ? p.join(docs.path, originalRel)
            : stillPath;
        await prefs.setString(_prefsMyAvatarOriginalPathKey, origPath);
      } else {
        final legacy = File(p.join(docs.path, 'my_avatar.png'));
        if (await legacy.exists()) {
          await prefs.setString(_prefsMyAvatarPathKey, legacy.path);
          await prefs.setString(_prefsMyAvatarOriginalPathKey, legacy.path);
        }
      }
    } catch (_) {
      // ignore
    }

    // Restore premium cosmetic selections (avatar frame, cover, emoji status,
    // wallpapers, theme/bubble/nickname/indicator presets, bio, launcher icon,
    // custom cover/avatar media). Prefs are written directly (the restart below
    // re-runs init() which re-reads them and re-publishes profile meta); media
    // paths are rebound to this device's docs dir. Everything is guarded so a
    // missing/old/partial cosmetics block (or a missing file) never throws.
    await _restoreCosmeticsFromSafeBackup(prefs: prefs, kit: restoredKit);

    // Store pending contact/block import to apply on next init.
    final pending = {
      'contacts': restoredKit.contacts
          .map((c) => c.toJson())
          .toList(growable: false),
      'blocked_profiles': restoredKit.blockedProfiles,
      if (restoredKit.dbSnapshot != null) 'db_snapshot': restoredKit.dbSnapshot,
    };
    await prefs.setString(_prefsPendingSafeImportKey, jsonEncode(pending));
    final importedNow = await _tryApplyPendingSafeImportPayload(pending);
    if (importedNow) {
      await prefs.remove(_prefsPendingSafeImportKey);
    }
    await _rememberRestoredOwnDeviceIdsInDb(
      profileId: restoredKit.profileId,
      deviceIds: knownOwnDeviceIds,
    );

    await _setDesktopAuthRequired(prefs, false);
    if (completeOnboarding) {
      await markOnboardingComplete(prefs: prefs);
    }

    _applyRuntimeResetResult(
      AppRuntimeLifecycleCoordinator.restartReset(
        desktopLinkRequests: _desktopLinkRequests,
        cancelAwaitingDesktopLinkRequests: true,
        nextDeviceId: activeDeviceId,
        knownOwnDeviceIds: knownOwnDeviceIds,
      ),
    );
    await _saveDesktopLinkRequestsToPrefs();

    _changed.add(null);
    _restartRequested.add(null);
  }

  /// Re-applies the optional cosmetics carrier from a safe-backup. Writes prefs
  /// directly + updates in-memory fields; the post-restore restart re-reads them
  /// via init() (which also re-publishes profile meta). Fully guarded: a missing
  /// cosmetics block, unknown values, or missing media files never throw, and an
  /// absent value clears any cosmetic left over from a previous install.
  Future<void> _restoreCosmeticsFromSafeBackup({
    required SharedPreferences prefs,
    required SafeBackupPlainV1 kit,
  }) async {
    final cosmetics = kit.cosmetics;

    String? readStr(String key) {
      if (cosmetics == null) return null;
      final v = cosmetics[key];
      if (v is String) {
        final t = v.trim();
        return t.isEmpty ? null : t;
      }
      return null;
    }

    Future<void> applyStr(
      String prefKey,
      String? value, {
      bool Function(String)? isValid,
    }) async {
      if (value != null && (isValid == null || isValid(value))) {
        await prefs.setString(prefKey, value);
      } else {
        await prefs.remove(prefKey);
      }
    }

    try {
      // Bio (sanitized on read by init()).
      await applyStr(_prefsMyBioKey, readStr('bio'));
      _myBio = _sanitizeProfileBio(prefs.getString(_prefsMyBioKey) ?? '');

      // Avatar frame + emoji status (free-form cosmetic ids).
      final frameId = _normalizeCosmeticId(readStr('frame_id'));
      await applyStr(_prefsMyFrameIdKey, frameId);
      _myFrameId = frameId;

      final emojiStatus = readStr('emoji_status');
      await applyStr(_prefsMyEmojiStatusKey, emojiStatus);
      _myEmojiStatus = emojiStatus;

      // Preset selections — validated with the same predicates init() uses so a
      // value the build no longer ships is dropped instead of persisted.
      await applyStr(
        _prefsDefaultChatWallpaperKey,
        readStr('default_chat_wallpaper'),
        isValid: (v) {
          final n = normalizeChatWallpaperId(v);
          return isValidChatWallpaperId(n) &&
              n != kGlobalChatWallpaperSelectionId;
        },
      );
      await applyStr(
        _prefsAppThemePresetIdKey,
        readStr('app_theme_preset_id'),
        isValid: isValidAppThemePresetId,
      );
      await applyStr(
        _prefsChatBubbleStylePresetIdKey,
        readStr('chat_bubble_style_preset_id'),
        isValid: (v) =>
            isValidChatBubbleStylePresetId(normalizeChatBubbleStylePresetId(v)),
      );
      await applyStr(
        _prefsNicknameStylePresetIdKey,
        readStr('nickname_style_preset_id'),
        isValid: isValidNicknameStylePresetId,
      );
      await applyStr(
        _prefsIndicatorColorPresetIdKey,
        readStr('indicator_color_preset_id'),
        isValid: isValidIndicatorColorPresetId,
      );

      // Whether the bubble style was manually chosen (vs. theme-derived).
      final bubbleManual = cosmetics?['bubble_color_is_manual'];
      await prefs.setBool(
        _prefsBubbleColorIsManualKey,
        bubbleManual is bool ? bubbleManual : false,
      );

      // Profile cover: catalog id and/or custom image/video files rebound to
      // this device's docs dir. Only rebind a media path when the file exists.
      String? docsPath;
      try {
        docsPath = p.normalize((await getApplicationDocumentsDirectory()).path);
      } catch (_) {
        docsPath = null;
      }

      Future<String?> reboundMediaPath(String? basename) async {
        if (docsPath == null) return null;
        final base = (basename ?? '').trim();
        if (base.isEmpty) return null;
        // Defend against any path component sneaking into the stored basename.
        final clean = p.basename(base).trim();
        if (clean.isEmpty) return null;
        final candidate = p.join(docsPath, clean);
        try {
          if (await File(candidate).exists()) return candidate;
        } catch (_) {}
        return null;
      }

      final coverId = _normalizeCosmeticId(readStr('cover_id'));
      final coverImagePath = await reboundMediaPath(
        readStr('cover_image_basename'),
      );
      final coverVideoPath = await reboundMediaPath(
        readStr('cover_video_basename'),
      );

      await applyStr(_prefsMyCoverIdKey, coverId);
      _myCoverId = coverId;
      await applyStr(_prefsMyCoverImageKey, coverImagePath);
      _myCoverImagePath = coverImagePath;
      await applyStr(_prefsMyCoverVideoKey, coverVideoPath);
      _myCoverVideoPath = coverVideoPath;

      // Avatar video (the still already rides my_avatar.png, rebound above).
      final avatarVideoPath = await reboundMediaPath(
        readStr('avatar_video_basename'),
      );
      await applyStr(_prefsMyAvatarVideoKey, avatarVideoPath);
      _myAvatarVideoPath = avatarVideoPath;

      // Per-chat wallpaper overrides → '<prefix><convoId>'.
      final perChat = cosmetics?['chat_wallpapers'];
      if (perChat is Map) {
        perChat.forEach((rawConvoId, rawValue) {
          final convoId = rawConvoId.toString().trim();
          final value = (rawValue is String) ? rawValue.trim() : '';
          if (convoId.isEmpty || value.isEmpty) return;
          // Best-effort; ignore individual bad entries.
          unawaited(
            prefs.setString('$_prefsChatWallpaperPrefix$convoId', value),
          );
        });
      }

      // Launcher app icon — re-apply via the platform channel after a restore.
      final iconKey = readStr('app_icon_key');
      if (iconKey != null) {
        await prefs.setString(_prefsAppIconKey, iconKey);
        if (AppIconService.isSupportedPlatform) {
          // Fire-and-forget; failures degrade to the stock icon.
          unawaited(AppIconService.setIcon(iconKey).catchError((_) => false));
        }
      } else {
        await prefs.remove(_prefsAppIconKey);
      }
    } catch (error) {
      _debugRuntimeLog('Cosmetics restore skipped (best-effort): $error');
    }
  }

  Future<void> restoreFromRecoveryKitPayload({
    required String payload,
    required String password,
  }) async {
    final kit = await (() async {
      try {
        return await RecoveryKitV1.decryptFromPayload(
          payload: payload,
          password: password,
        );
      } catch (error) {
        throw describeEncryptedRestoreError(error);
      }
    })();
    await restoreFromRecoveryKit(kit);
  }

  /// SEC-10③. Сбрасывает кэш конфигурации: без этого настройка вступила бы в
  /// силу только после истечения прежней, то есть человек включил бы её и
  /// следующий звонок всё равно ушёл бы напрямую.
  Future<void> setHideAddressInCalls(bool v) async {
    _hideAddressInCalls = v;
    final prefs = _prefs ?? await SharedPreferences.getInstance();
    _prefs = prefs;
    await prefs.setBool(_prefsHideAddressInCallsKey, v);
    _cachedCallIceConfig = const CallIceConfigSnapshot.empty();
    _changed.add(null);
  }

  /// SEC-11. Применяет к системе И сохраняет — именно в этом порядке.
  ///
  /// 🔴 Если система отказала, настройка НЕ сохраняется включённой. Иначе
  /// человек увидел бы включённый переключатель при незащищённом экране, а
  /// приватность, о которой соврали, хуже отсутствующей: она меняет поведение
  /// человека, ничего не меняя в защите.
  Future<bool> setScreenPrivacy(bool v) async {
    if (v && !await ScreenPrivacy.apply(enabled: true)) return false;
    if (!v) await ScreenPrivacy.apply(enabled: false);
    _screenPrivacy = v;
    final prefs = _prefs ?? await SharedPreferences.getInstance();
    _prefs = prefs;
    await prefs.setBool(_prefsScreenPrivacyKey, v);
    _changed.add(null);
    return true;
  }

  Future<void> setBlockUnverified(bool v) async {
    _blockUnverified = v;
    final prefs = _prefs ?? await SharedPreferences.getInstance();
    _prefs = prefs;
    await prefs.setBool(_prefsBlockUnverifiedKey, v);
    _changed.add(null);
  }

  String _contactCallAllowedPrefKey(String profileId) {
    return '$_prefsContactCallAllowedPrefix${profileId.trim()}';
  }

  Future<void> setCallsEnabled(bool v) async {
    _callsEnabled = v;
    final prefs = _prefs ?? await SharedPreferences.getInstance();
    _prefs = prefs;
    await prefs.setBool(_prefsCallsEnabledKey, v);
    _changed.add(null);
  }

  Future<void> setIncomingCallsEnabled(bool v) async {
    _incomingCallsEnabled = v;
    final prefs = _prefs ?? await SharedPreferences.getInstance();
    _prefs = prefs;
    await prefs.setBool(_prefsIncomingCallsEnabledKey, v);
    _changed.add(null);
    refreshPushNotificationPolicy();
  }

  Future<void> setIncomingScreenShareEnabled(bool v) async {
    _incomingScreenShareEnabled = v;
    final prefs = _prefs ?? await SharedPreferences.getInstance();
    _prefs = prefs;
    await prefs.setBool(_prefsIncomingScreenShareEnabledKey, v);
    _changed.add(null);
  }

  Future<bool> isContactCallsAllowed(String profileId) async {
    final pid = profileId.trim();
    if (pid.isEmpty) return false;
    final prefs = _prefs ?? await SharedPreferences.getInstance();
    _prefs = prefs;
    return prefs.getBool(_contactCallAllowedPrefKey(pid)) ?? true;
  }

  Future<void> setContactCallsAllowed({
    required String profileId,
    required bool allowed,
  }) async {
    final pid = profileId.trim();
    if (pid.isEmpty) return;
    final prefs = _prefs ?? await SharedPreferences.getInstance();
    _prefs = prefs;
    await prefs.setBool(_contactCallAllowedPrefKey(pid), allowed);
    _changed.add(null);
    refreshPushNotificationPolicy();
  }

  Future<String> sendCallInvite({
    required String peerProfileId,
    required bool video,
    bool screenShare = false,
    String? callId,
  }) async {
    final pid = peerProfileId.trim();
    if (pid.isEmpty) return '';
    if (!_callsEnabled) {
      throw ContactActionFailure(
        ContactActionFailureCode.callsDisabledGlobally,
      );
    }
    if (!await isContactCallsAllowed(pid)) {
      throw ContactActionFailure(
        ContactActionFailureCode.callsDisabledForContact,
      );
    }
    if (!await _doesPeerAllowCategory(pid, 'calls')) {
      throw ContactActionFailure(
        ContactActionFailureCode.callsDisabledForContact,
        message: 'Calls are disabled by this contact privacy settings.',
      );
    }
    final resolvedCallId = (callId ?? '').trim();
    final effectiveCallId = resolvedCallId.isEmpty
        ? _uuid.v4()
        : resolvedCallId;
    final callAttemptId = effectiveCallId;
    final payload = <String, Object?>{
      'v': 1,
      'action': 'invite',
      'callId': effectiveCallId,
      'callAttemptId': callAttemptId,
      'media': video ? 'video' : 'audio',
      'screenShare': screenShare,
      'createdAtMs': DateTime.now().millisecondsSinceEpoch,
      'fromProfileId': _profileId,
      'fromDisplayName': _myNickname.trim().isEmpty ? null : _myNickname.trim(),
    };
    callOpLog(
      'AppCtrl',
      'call_signal_prepare',
      fields: <String, Object?>{
        'action': 'invite',
        'callId': effectiveCallId,
        'callAttemptId': callAttemptId,
        'peerProfileId': pid,
        'media': video ? 'video' : 'audio',
        'screenShare': screenShare,
      },
    );
    try {
      await _sendCallSignalCommand(peerProfileId: pid, payload: payload);
    } catch (error) {
      throw describeContactActionFailure(error);
    }
    return effectiveCallId;
  }

  Future<void> sendCallDecline({
    required String peerProfileId,
    required String callId,
    String? callAttemptId,
  }) async {
    final pid = peerProfileId.trim();
    final cid = callId.trim();
    if (pid.isEmpty || cid.isEmpty) return;
    final payload = <String, Object?>{
      'v': 1,
      'action': 'decline',
      'callId': cid,
      'callAttemptId': (callAttemptId ?? cid).trim(),
      'createdAtMs': DateTime.now().millisecondsSinceEpoch,
    };
    await _sendCallSignalCommand(peerProfileId: pid, payload: payload);
  }

  /// Гасит звонок на ОСТАЛЬНЫХ устройствах собеседника после того, как на одном
  /// из них ответили.
  ///
  /// 🔴 ЗАЧЕМ (11.09.2026). До В-1 звонок уходил одному устройству, и вопрос не
  /// стоял. Теперь приглашение идёт всем — и без этой рассылки устройство, где
  /// не ответили, продолжало бы звонить до собственного таймаута. Владелец
  /// предупредил об этом прямо: «проверь, чтобы отбой гасил звонок везде».
  ///
  /// Шлём обычный `hangup`: принимающая сторона на него уже умеет гаснуть
  /// (`_endCall(remoteHangup)`), и он же корректно отрабатывает, если обгонит
  /// приглашение. Изобретать новое действие не нужно.
  ///
  /// 🔴 УСТРОЙСТВО, ГДЕ ОТВЕТИЛИ, ИСКЛЮЧАЕТСЯ. Послать отбой туда — значит
  /// оборвать начавшийся разговор. Поэтому [answeredDeviceId] вычитается, и при
  /// пустом остатке не отправляется ничего.
  Future<void> sendCallHangupToOtherDevices({
    required String peerProfileId,
    required String callId,
    required String answeredDeviceId,
    String? callAttemptId,
  }) async {
    final pid = peerProfileId.trim();
    final cid = callId.trim();
    final answered = answeredDeviceId.trim();
    if (pid.isEmpty || cid.isEmpty) return;
    final remembered = _callTargetDevicesForCall(cid);
    if (remembered == null || remembered.isEmpty) return;
    final others = remembered
        .where((d) => d.trim().isNotEmpty && d.trim() != answered)
        .toSet();
    if (others.isEmpty) return;
    callOpLog(
      'AppCtrl',
      'call_hangup_to_other_devices',
      fields: <String, Object?>{
        'callId': cid,
        'invited': remembered.length,
        'others': others.length,
      },
    );
    await _sendCallSignalCommand(
      peerProfileId: pid,
      payload: <String, Object?>{
        'v': 1,
        'action': 'hangup',
        'callId': cid,
        'callAttemptId': (callAttemptId ?? cid).trim(),
        'createdAtMs': DateTime.now().millisecondsSinceEpoch,
      },
      restrictToDeviceIds: others,
    );
  }

