  Future<void> sendCallIceCandidate({
    required String peerProfileId,
    required String callId,
    required String candidate,
    String? sdpMid,
    int? sdpMLineIndex,
    String? callAttemptId,
    bool recovery = false,
  }) async {
    final pid = peerProfileId.trim();
    final cid = callId.trim();
    final cleanCandidate = candidate.trim();
    if (pid.isEmpty || cid.isEmpty || cleanCandidate.isEmpty) return;
    final signalId = _uuid.v4();
    final payload = <String, Object?>{
      'v': 1,
      'action': 'ice',
      'callId': cid,
      'callAttemptId': (callAttemptId ?? cid).trim(),
      'signalId': signalId,
      'candidate': cleanCandidate,
      'sdpMid': (sdpMid ?? '').trim().isEmpty ? null : sdpMid!.trim(),
      'sdpMLineIndex': sdpMLineIndex,
      'createdAtMs': DateTime.now().millisecondsSinceEpoch,
    };
    final createdAtMs = (payload['createdAtMs'] as num).toInt();
    await _sendCallSignalCommand(
      peerProfileId: pid,
      payload: payload,
      deliveryPolicyOverride: CallSignalDeliveryPolicy.forAction(
        'ice',
        recovery: recovery,
      ),
      transportMetaJsonOverride:
          CallSignalDeliveryPolicy.buildTransportMetaJson(
            action: 'ice',
            callId: cid,
            callAttemptId: (callAttemptId ?? cid).trim(),
            signalId: signalId,
            createdAtMs: createdAtMs,
            deliveryMode: recovery ? 'recovery' : 'normal',
          ),
    );
  }

