  Future<CachedRoomCall?> getCachedRoomCall(String roomId) async {
    final db = _db;
    final cleanedRoomId = roomId.trim();
    if (db == null || cleanedRoomId.isEmpty) {
      return null;
    }
    final record = await db.roomCallSnapshotGet(cleanedRoomId);
    if (record == null) {
      return null;
    }
    return _cachedRoomCallFromRecord(record);
  }

  Future<List<CachedRoomCall>> listCachedActiveRoomCalls({
    bool selfJoinedOnly = false,
  }) async {
    final db = _db;
    if (db == null) {
      return const <CachedRoomCall>[];
    }
    final roomIds = await db.roomCallActiveGroupIdsList();
    final calls = <CachedRoomCall>[];
    for (final roomId in roomIds) {
      final record = await db.roomCallSnapshotGet(roomId);
      if (record == null) {
        continue;
      }
      final call = _cachedRoomCallFromRecord(record);
      if (!call.isActive) {
        continue;
      }
      if (selfJoinedOnly && !(call.selfParticipant?.isJoined ?? false)) {
        continue;
      }
      calls.add(call);
    }
    calls.sort((a, b) {
      final selfJoinedCompare =
          (b.selfParticipant?.isJoined ?? false ? 1 : 0) -
          (a.selfParticipant?.isJoined ?? false ? 1 : 0);
      if (selfJoinedCompare != 0) {
        return selfJoinedCompare;
      }
      final updatedCompare = b.updatedAtMs.compareTo(a.updatedAtMs);
      if (updatedCompare != 0) {
        return updatedCompare;
      }
      final participantCompare = b.joinedParticipantCount.compareTo(
        a.joinedParticipantCount,
      );
      if (participantCompare != 0) {
        return participantCompare;
      }
      return a.roomId.compareTo(b.roomId);
    });
    return calls;
  }

  Future<CachedRoomCall?> getPrimarySelfJoinedCachedRoomCall() async {
    final calls = await listCachedActiveRoomCalls(selfJoinedOnly: true);
    if (calls.isEmpty) {
      return null;
    }
    return calls.first;
  }

  CachedRoomCall _cachedRoomCallFromRecord(RoomCallStateRecord record) {
    final participants = record.participants
        .map(
          (participant) => CachedRoomCallParticipant(
            profileId: participant.profileId,
            deviceId: participant.deviceId,
            joinState: participant.joinState,
            supportsVideo: participant.supportsVideo,
            supportsScreenShare: participant.supportsScreenShare,
            muted: participant.muted,
            deafened: participant.deafened,
            videoEnabled: participant.videoEnabled,
            screenShareEnabled: participant.screenShareEnabled,
            speaking: participant.speaking,
            joinedAtMs: participant.joinedAtMs,
            leftAtMs: participant.leftAtMs,
            updatedAtMs: participant.updatedAtMs,
          ),
        )
        .toList(growable: false);
    final selfProfileId = profileId.trim();
    final selfDeviceId = deviceId.trim();
    CachedRoomCallParticipant? selfParticipant;
    for (final participant in participants) {
      if (selfDeviceId.isNotEmpty && participant.deviceId == selfDeviceId) {
        selfParticipant = participant;
        break;
      }
      if (selfParticipant == null &&
          selfProfileId.isNotEmpty &&
          participant.profileId == selfProfileId) {
        selfParticipant = participant;
      }
    }
    return CachedRoomCall(
      roomId: record.groupId,
      callId: record.callId,
      state: record.state,
      mediaType: record.mediaType,
      createdByProfileId: record.createdByProfileId,
      createdByDeviceId: record.createdByDeviceId,
      stateVersion: record.stateVersion,
      startedAtMs: record.startedAtMs,
      updatedAtMs: record.updatedAtMs,
      endedAtMs: record.endedAtMs,
      expiresAtMs: record.expiresAtMs,
      participants: participants,
      selfParticipant: selfParticipant,
    );
  }

