  /// SEC-10③ (26.08.2026). Единственное горло получения конфигурации звонка.
  ///
  /// 🔴 ОБЁРТКА, А НЕ ПРАВКА В ТЕЛЕ. У `_getCallIceConfigRaw` четыре точки
  /// возврата — свежая выборка, попадание в кэш, отсутствие релея и пауза
  /// после отказа. Применить настройку в каждой значило бы однажды забыть
  /// одну, и человек, попросивший скрыть адрес, звонил бы напрямую именно в
  /// тот раз, когда сеть подвела. Ровно так уже вырождалась проверка политики
  /// в SEC-10①.
  Future<CallIceConfigSnapshot> getCallIceConfig({
    bool forceRefresh = false,
  }) async {
    final raw = await _getCallIceConfigRaw(forceRefresh: forceRefresh);
    return applyCallAddressPrivacy(raw, hideAddress: _hideAddressInCalls);
  }

  /// Поднимает политику до «только через сервер», если человек этого попросил.
  ///
  /// Только ПОДНИМАЕТ: если сервер уже назначил `relayOnly`, настройка ничего
  /// не ослабляет. Снять защиту эта функция не может по построению.
  ///
  /// Проверять наличие TURN здесь НЕЛЬЗЯ: у проверки нет права молча
  /// вернуться к прямому соединению — это и была суть SEC-10①. Отсутствие
  /// TURN ловит `validateIceConfigForSession`, и звонок честно не состоится.
  @visibleForTesting
  static CallIceConfigSnapshot applyCallAddressPrivacy(
    CallIceConfigSnapshot config, {
    required bool hideAddress,
  }) {
    if (!hideAddress || config.policy == CallNetworkPolicy.relayOnly) {
      return config;
    }
    return CallIceConfigSnapshot(
      policy: CallNetworkPolicy.relayOnly,
      iceServers: config.iceServers,
      expiresAtMs: config.expiresAtMs,
    );
  }

  Future<CallIceConfigSnapshot> _getCallIceConfigRaw({
    bool forceRefresh = false,
  }) async {
    final nowMs = DateTime.now().millisecondsSinceEpoch;
    if (!forceRefresh && !_cachedCallIceConfig.isExpired(nowMs: nowMs)) {
      return _cachedCallIceConfig;
    }
    final inFlight = _callIceConfigRefreshInFlight;
    if (inFlight != null) {
      return inFlight;
    }
    final relay = _relay;
    if (relay == null) {
      return _cachedCallIceConfig.pruneExpiredCredentials(nowMs: nowMs);
    }
    // BUG-FIX (ICE-STALE-CACHE 2026-05-29) — honor the failure backoff.
    // If the previous refresh failed inside the last
    // `_callIceConfigRefreshFailBackoffMs`, serve the pruned cache directly
    // instead of hammering the relay with a fresh round-trip per call.
    // `forceRefresh` overrides the backoff so manual recovery
    // (e.g. `_autoRestartIce`) can always retry on demand.
    if (!forceRefresh &&
        _callIceConfigLastRefreshFailedAtMs > 0 &&
        (nowMs - _callIceConfigLastRefreshFailedAtMs) <
            _callIceConfigRefreshFailBackoffMs) {
      return _cachedCallIceConfig.pruneExpiredCredentials(nowMs: nowMs);
    }
    final refresh = () async {
      try {
        final fetched = await relay.getIceConfig();
        _cachedCallIceConfig = fetched;
        _callIceConfigLastRefreshFailedAtMs = 0; // success clears backoff
        callLog(
          'AppCtrl',
          'relay ice config refreshed policy=${fetched.policy.name} servers=${fetched.iceServers.length}',
        );
        return fetched;
      } catch (e) {
        _callIceConfigLastRefreshFailedAtMs =
            DateTime.now().millisecondsSinceEpoch;
        callLog('AppCtrl', 'relay ice config refresh failed: $e');
        return _cachedCallIceConfig.pruneExpiredCredentials(nowMs: nowMs);
      }
    }();
    _callIceConfigRefreshInFlight = refresh;
    try {
      return await refresh;
    } finally {
      if (identical(_callIceConfigRefreshInFlight, refresh)) {
        _callIceConfigRefreshInFlight = null;
      }
    }
  }

  Future<void> _sendCallSignalCommand({
    required String peerProfileId,
    required Map<String, Object?> payload,
    CallSignalDeliveryPolicy? deliveryPolicyOverride,
    String? transportMetaJsonOverride,
    // 🔴 АДРЕСНАЯ ОТПРАВКА (11.09.2026). Нужна ровно для одного случая: когда
    // на звонок ответили на одном устройстве, остальным надо послать отбой,
    // НЕ трогая то, где идёт разговор. Пусто — поведение прежнее, всем.
    Set<String>? restrictToDeviceIds,
  }) async {
    final normalizedPayload = CallSignalCommandCodec.normalizeOutgoingPayload(
      payload,
      fallbackSignalId: _uuid.v4(),
      createdAtMs: DateTime.now().millisecondsSinceEpoch,
    );
    final action =
        (normalizedPayload['action'] as String?)?.trim().toLowerCase() ?? '';
    final callId = (normalizedPayload['callId'] as String?)?.trim() ?? '';
    final callAttemptId =
        (normalizedPayload['callAttemptId'] as String?)?.trim() ?? callId;
    final signalId = CallSignalCommandCodec.resolveSignalId(normalizedPayload);
    final createdAtMs =
        (normalizedPayload['createdAtMs'] as num?)?.toInt() ??
        DateTime.now().millisecondsSinceEpoch;
    final policy =
        deliveryPolicyOverride ?? CallSignalDeliveryPolicy.forAction(action);
    final correlationId = 'call-signal:$signalId';
    final callerProfileId =
        (normalizedPayload['fromProfileId'] as String?)?.trim() ?? '';
    final callerDisplayName = (normalizedPayload['fromDisplayName'] as String?)
        ?.trim();
    final mediaKind =
        (normalizedPayload['media'] as String?)?.trim().toLowerCase() ?? '';
    final transportMetaJson =
        transportMetaJsonOverride ??
        CallSignalDeliveryPolicy.buildTransportMetaJson(
          action: action,
          callId: callId,
          callAttemptId: callAttemptId,
          signalId: signalId,
          createdAtMs: createdAtMs,
          callerProfileId: callerProfileId,
          callerDisplayName: callerDisplayName,
          isVideo: mediaKind == 'video',
          convoId: callerProfileId,
        );
    final maxAttempts = policy.maxQueueAttempts;
    Object? lastError;

    // CALL AUDIT 2026-07-08 F1 (зомби-устройства): an INVITE (including
    // resends) must never trust the frozen per-call set or a possibly
    // days-stale cache — the peer may have rotated devices (reinstall) and the
    // cached snapshot then points at a dead device_id with no push token, so
    // the call can never ring (observed in prod: 40 signals to a dead device,
    // 2 to the live one). Force a FRESH keys-server resolve for invites and
    // UNION it with the cached set (never fewer devices than before); the
    // union also refreshes the frozen list so offer/ice follow the corrected
    // set. Ringing a stale device is harmless (90s TTL mailbox); missing the
    // live one loses the call.
    final resolvedTargets = action == 'invite'
        ? await _resolveCallTargetDevicesFreshForInvite(peerProfileId)
        : (_callTargetDevicesForCall(callId) ??
              await _resolveCallTargetDevices(peerProfileId));
    // Сужение до заданных устройств — только когда его попросили явно. Если
    // пересечение пустое, отправлять НЕЧЕГО: это не повод разослать всем.
    final targetDevices = restrictToDeviceIds == null
        ? resolvedTargets
        : resolvedTargets
              .where(restrictToDeviceIds.contains)
              .toList(growable: false);
    if (restrictToDeviceIds != null) {
      callOpLog(
        'AppCtrl',
        'call_signal_restricted_targets',
        fields: <String, Object?>{
          'action': action,
          'callId': callId,
          'resolved': resolvedTargets.length,
          'restricted': targetDevices.length,
        },
      );
      if (targetDevices.isEmpty) return;
    }
    if (targetDevices.isEmpty) {
      // PR-G (bug 18): hangup/cancel must NEVER throw on empty target
      // devices — the caller has already torn down the call locally, and a
      // throw here would prevent the at-least-best-effort send and surface
      // as "iOS caller hangs up, callee keeps ringing". We log + return
      // (non-strict) for these two actions regardless of the policy's
      // strictQueueing flag. For all other critical actions we keep the
      // throw so the caller (offer/answer/ice/invite) can fail loud.
      final isCancelLike = action == 'hangup' || action == 'cancel';
      if (!policy.strictQueueing || isCancelLike) {
        callOpLog(
          'AppCtrl',
          'call_signal_skipped_no_targets',
          fields: <String, Object?>{
            'action': action,
            'callId': callId,
            'callAttemptId': callAttemptId,
            'signalId': signalId,
            'peerProfileId': peerProfileId,
            'deliveryPolicy': policy.name,
            'isCritical': policy.isCritical,
            'softenedForCancel': isCancelLike && policy.strictQueueing,
          },
        );
        callLog(
          'AppCtrl',
          'skip callSignal action=$action policy=${policy.name}: no target devices for $peerProfileId',
        );
        return;
      }
      throw CallTargetUnavailableException(
        peerProfileId: peerProfileId,
        action: action,
      );
    }
    // 🔴 ЗАПОМИНАЕМ ТОЛЬКО ПОЛНЫЙ НАБОР. Адресная отправка (отбой на прочие
    // устройства после ответа) — это подмножество, и записать его сюда значит
    // сузить память звонка навсегда: следующий отбой ушёл бы уже не всем.
    if (callId.isNotEmpty && restrictToDeviceIds == null) {
      _rememberCallTargetDevicesForCall(callId, targetDevices);
    }

    callOpLog(
      'AppCtrl',
      'call_signal_send_start',
      fields: <String, Object?>{
        'action': action,
        'callId': callId,
        'callAttemptId': callAttemptId,
        'signalId': signalId,
        'peerProfileId': peerProfileId,
        'deliveryPolicy': policy.name,
        'isCritical': policy.isCritical,
        'targetCount': targetDevices.length,
      },
    );

    final text = CallSignalCommandCodec.encode(normalizedPayload);
    for (var attempt = 1; attempt <= maxAttempts; attempt++) {
      try {
        await sendControlMessage(
          peerProfileId: peerProfileId,
          controlText: text,
          ttlSeconds: _callSignalTtlSeconds,
          strict: policy.strictQueueing,
          forceRelayFlush: policy.forceRelayFlush,
          relayFlushTimeout: policy.relayFlushTimeoutMs <= 0
              ? null
              : Duration(milliseconds: policy.relayFlushTimeoutMs),
          targetDeviceIds: targetDevices,
          priority: policy.priority,
          transportHint: policy.transportHint,
          retryBucket: policy.retryBucket,
          correlationId: correlationId,
          transportMetaJson: transportMetaJson,
        );
        callOpLog(
          'AppCtrl',
          'call_signal_send_success',
          fields: <String, Object?>{
            'action': action,
            'callId': callId,
            'callAttemptId': callAttemptId,
            'signalId': signalId,
            'attempt': attempt,
            'deliveryPolicy': policy.name,
            'isCritical': policy.isCritical,
          },
        );
        return;
      } catch (e) {
        lastError = e;
        callOpLog(
          'AppCtrl',
          'call_signal_send_retry',
          fields: <String, Object?>{
            'action': action,
            'callId': callId,
            'callAttemptId': callAttemptId,
            'signalId': signalId,
            'attempt': attempt,
            'deliveryPolicy': policy.name,
            'isCritical': policy.isCritical,
          },
        );
        final msg = e.toString().toLowerCase();
        final isRateLimited =
            msg.contains('429') || msg.contains('rate_limited');
        if (!isRateLimited || attempt >= maxAttempts) {
          break;
        }
        await Future.delayed(Duration(milliseconds: 220 * attempt));
      }
    }

    if (!policy.strictQueueing) {
      callOpLog(
        'AppCtrl',
        'call_signal_send_dropped',
        fields: <String, Object?>{
          'action': action,
          'callId': callId,
          'callAttemptId': callAttemptId,
          'signalId': signalId,
          'deliveryPolicy': policy.name,
          'isCritical': policy.isCritical,
        },
      );
      callLog(
        'AppCtrl',
        'drop callSignal action=$action after retries: $lastError',
      );
      return;
    }
    throw StateError(lastError?.toString() ?? 'call signal send failed');
  }

  Map<String, Object?> _buildRoomCallMediaDescriptorSignalPayload({
    required RelayRoomCallMediaSession session,
    required String reason,
  }) {
    return <String, Object?>{
      'v': 1,
      'action': 'descriptor_updated',
      'roomId': session.roomId,
      'callId': session.callId,
      'sessionId': session.sessionId,
      'descriptorVersion': session.descriptorVersion,
      'stateVersion': session.stateVersion,
      'reason': reason.trim().toLowerCase(),
    };
  }

  Future<void> _sendRoomCallMediaSignalCommand({
    required String peerProfileId,
    required String targetDeviceId,
    required Map<String, Object?> payload,
  }) async {
    final normalizedPayload =
        RoomCallMediaSignalCommandCodec.normalizeOutgoingPayload(
          payload,
          fallbackSignalId: _uuid.v4(),
          createdAtMs: DateTime.now().millisecondsSinceEpoch,
        );
    final action =
        (normalizedPayload['action'] as String?)?.trim().toLowerCase() ?? '';
    final roomId = (normalizedPayload['roomId'] as String?)?.trim() ?? '';
    final callId = (normalizedPayload['callId'] as String?)?.trim() ?? '';
    final sessionId = ((normalizedPayload['sessionId'] as String?) ?? callId)
        .trim();
    final signalId = RoomCallMediaSignalCommandCodec.resolveSignalId(
      normalizedPayload,
    );
    final descriptorVersion =
        (normalizedPayload['descriptorVersion'] as num?)?.toInt() ?? 0;
    final stateVersion =
        (normalizedPayload['stateVersion'] as num?)?.toInt() ?? 0;
    final createdAtMs =
        (normalizedPayload['createdAtMs'] as num?)?.toInt() ??
        DateTime.now().millisecondsSinceEpoch;
    final policy = RoomCallMediaSignalDeliveryPolicy.forAction(action);
    final correlationId = 'room-media-signal:$signalId';
    final transportMetaJson =
        RoomCallMediaSignalDeliveryPolicy.buildTransportMetaJson(
          action: action,
          roomId: roomId,
          callId: callId,
          sessionId: sessionId,
          descriptorVersion: descriptorVersion,
          stateVersion: stateVersion,
          signalId: signalId,
          createdAtMs: createdAtMs,
        );
    final text = RoomCallMediaSignalCommandCodec.encode(normalizedPayload);
    Object? lastError;

    for (var attempt = 1; attempt <= policy.maxQueueAttempts; attempt++) {
      try {
        await sendControlMessage(
          peerProfileId: peerProfileId,
          controlText: text,
          ttlSeconds: _roomCallMediaSignalTtlSeconds,
          strict: policy.strictQueueing,
          forceRelayFlush: policy.forceRelayFlush,
          targetDeviceIds: <String>[targetDeviceId],
          priority: policy.priority,
          transportHint: policy.transportHint,
          retryBucket: policy.retryBucket,
          correlationId: correlationId,
          transportMetaJson: transportMetaJson,
        );
        return;
      } catch (e) {
        lastError = e;
        final msg = e.toString().toLowerCase();
        final isRateLimited =
            msg.contains('429') || msg.contains('rate_limited');
        if (!isRateLimited || attempt >= policy.maxQueueAttempts) {
          break;
        }
        await Future<void>.delayed(Duration(milliseconds: 220 * attempt));
      }
    }

    callLog(
      'AppCtrl',
      'drop room media signal action=$action roomId=$roomId callId=$callId targetDeviceId=$targetDeviceId after retries: $lastError',
    );
  }

  Future<void> _broadcastRoomCallMediaDescriptorHintToParticipants({
    required RelayRoomCallMediaSession session,
    required String reason,
  }) async {
    if (session.participants.length <= 1) {
      return;
    }
    final payload = _buildRoomCallMediaDescriptorSignalPayload(
      session: session,
      reason: reason,
    );
    final sentTargets = <String>{};
    for (final participant in session.participants) {
      final profileId = participant.profileId.trim();
      final deviceId = participant.deviceId.trim();
      if (participant.isSelf || !participant.isJoined) {
        continue;
      }
      if (profileId.isEmpty || deviceId.isEmpty) {
        continue;
      }
      final targetKey = '$profileId::$deviceId';
      if (!sentTargets.add(targetKey)) {
        continue;
      }
      await _sendRoomCallMediaSignalCommand(
        peerProfileId: profileId,
        targetDeviceId: deviceId,
        payload: payload,
      );
    }
  }

  Future<void> _broadcastRoomCallMediaDescriptorHintToParticipantsBestEffort({
    required RelayRoomCallMediaSession session,
    required String reason,
  }) async {
    try {
      await _broadcastRoomCallMediaDescriptorHintToParticipants(
        session: session,
        reason: reason,
      );
    } catch (e) {
      callLog(
        'AppCtrl',
        'room media signal broadcast failed roomId=${session.roomId} callId=${session.callId}: $e',
      );
    }
  }

  /// CALL AUDIT 2026-07-08 F1: last successful FRESH device resolve per peer
  /// (anti-429 pacing for invite resends — see below).
  final Map<String, int> _lastFreshCallResolveAtMsByPeer = <String, int>{};

  /// CALL AUDIT 2026-07-08 F1: fresh device resolve for CALL INVITES.
  ///
  /// Forces one keys-server lookup (bypassing the 3-min recipient cache and
  /// the 15-s call-target cache) and UNIONS the result with whatever the
  /// cached path returns — the fanout may grow, never shrink. A failure of
  /// the fresh lookup silently degrades to the cached behaviour, so a dead
  /// keys server never blocks a call that the old path could place.
  Future<List<String>> _resolveCallTargetDevicesFreshForInvite(
    String peerProfileId,
  ) async {
    final did = _deviceId;
    final nowMs = DateTime.now().millisecondsSinceEpoch;
    // Invite RESENDS tick every ~3s — don't hammer the keys server (429!)
    // with a forced lookup each tick; one fresh resolve per ~12s per peer is
    // plenty to catch a device rotation, the ticks in between ride the cache.
    final lastFreshAtMs = _lastFreshCallResolveAtMsByPeer[peerProfileId] ?? 0;
    final skipFresh = nowMs - lastFreshAtMs < 12000;
    var fresh = const <String>[];
    if (did != null && did.isNotEmpty && !skipFresh) {
      try {
        fresh = await _listRecipientDevicesForSend(
          peerProfileId: peerProfileId,
          selfDeviceId: did,
          forceRefresh: true,
        );
        _lastFreshCallResolveAtMsByPeer[peerProfileId] = nowMs;
      } catch (e) {
        callLog(
          'AppCtrl',
          'invite fresh device resolve failed (fallback to cache) '
              'peer=$peerProfileId: $e',
        );
      }
    }
    final cached = await _resolveCallTargetDevices(peerProfileId);
    final mergedAll = <String>{...fresh, ...cached}.toList(growable: false);
    // 🔴 ЗВОНОК — ЭФЕМЕРЕН: зовём только тех, кто способен ответить сейчас.
    // Сообщения этой правкой НЕ затронуты: они по-прежнему идут всем.
    final merged = narrowCallTargetsByLiveness(
      targets: mergedAll,
      liveness: _activeDevicesCacheByProfileId[peerProfileId]?.liveness ??
          const <RelayDeviceLiveness>[],
      nowMs: DateTime.now().millisecondsSinceEpoch,
    );
    if (merged.length != mergedAll.length) {
      DiagLog.event('call', 'targets_narrowed', {
        'peer': DiagLog.pfx(peerProfileId),
        'from': mergedAll.length,
        'to': merged.length,
      });
    }
    if (merged.isNotEmpty) {
      _callTargetCache[peerProfileId] = _CallTargetCacheEntry(
        deviceIds: merged,
        expiresAtMs: DateTime.now().millisecondsSinceEpoch + 15000,
      );
    }
    callOpLog(
      'AppCtrl',
      'call_invite_targets_fresh',
      fields: <String, Object?>{
        'peerProfileId': peerProfileId,
        'freshCount': fresh.length,
        'cachedCount': cached.length,
        'mergedCount': merged.length,
        // 11.09.2026: перечни всех трёх списков — видно, что пришло с сервера
        // ключей, что лежало в кэше и что получилось после слияния.
        'freshList': fresh.map(DiagLog.pfx).join(','),
        'cachedList': cached.map(DiagLog.pfx).join(','),
        'mergedList': merged.map(DiagLog.pfx).join(','),
      },
    );
    return merged;
  }

  /// Печатает соответствие «префикс устройства → отпечаток реле» для СВОЕГО
  /// устройства и целей звонка.
  ///
  /// 🔴 БЕЗ ЭТОЙ СТРОКИ ДВА ЖУРНАЛА НЕ СШИВАЮТСЯ. Реле обозначает устройство
  /// хешем (`device_ref=sha256:…`), клиент — префиксом идентификатора
  /// (`peer_dev=baecdd9f`). Имея ОБА журнала, привязать серверную строку к
  /// устройству было нельзя — из-за этого разбор сбоя звонка 15.08 закончился
  /// ничем.
  ///
  /// Печатается один раз на разрешение целей, а не на каждый сигнал: одной
  /// строки на звонок достаточно, чтобы прочесть весь серверный след.
  void _logCallDeviceRefMap(List<String> targetDeviceIds) {
    final self = (_deviceId ?? '').trim();
    final fields = <String, Object?>{};
    if (self.isNotEmpty) {
      fields['self_dev'] = DiagLog.pfx(self);
      fields['self_ref'] = DiagLog.relayRef(self);
    }
    var n = 0;
    for (final did in targetDeviceIds) {
      final trimmed = did.trim();
      if (trimmed.isEmpty) continue;
      n += 1;
      if (n > 4) break; // потолок на строку: четырёх целей хватает
      fields['peer${n}_dev'] = DiagLog.pfx(trimmed);
      fields['peer${n}_ref'] = DiagLog.relayRef(trimmed);
    }
    if (fields.isEmpty) return;
    callOpLog('AppCtrl', 'call_devices_ref_map', fields: fields);
  }

  /// Сколько устройство должно молчать, чтобы не звать его в ЖИВОЙ звонок.
  ///
  /// Трое суток, а не сутки: ночь без сети, самолёт и выходные — это живое
  /// устройство, и лишать его звонков нельзя.
  ///
  /// ⚠️ БОЛЬШЕ НЕ ПРИМЕНЯЕТСЯ к отбору адресатов (11.09.2026, см.
  /// [narrowCallTargetsByLiveness]). Оставлено только для существующих тестов
  /// и как память о прежнем правиле.
  static const int _callTargetSilentCutoffMs = 3 * 24 * 60 * 60 * 1000;

  /// Потолок веера звонка.
  ///
  /// Отсечка по молчанию убрана (В-1), и вместо неё от лишних запросов
  /// защищает потолок: у человека может быть телефон, планшет и пара
  /// компьютеров, но не пятнадцать. Порядок — от самых свежих, чтобы при
  /// упоре в потолок первыми попали те, кто вероятнее ответит.
  static const int _callFanoutMaxDevices = 5;

  /// Сужает список получателей ЗВОНКА до тех, кто способен ответить сейчас.
  ///
  /// 🔴 ЗАЧЕМ (15.08.2026, замер звонка). Половина сигналов уходила на копию
  /// устройства, оставшуюся от переустановки: молчит пятые сутки, токена пушей
  /// нет, `superseded` не проставлен (пометка ставится лишь при захвате того же
  /// токена, а переустановка получает НОВЫЙ). Каждый её сигнал — запрос в лимит
  /// по IP, а лимит рвёт живой разговор.
  ///
  /// 🔴 ПОЧЕМУ ТОЛЬКО ДЛЯ ЗВОНКА. Сообщению копия не мешает: оно полежит в
  /// ящике семь дней и дождётся хозяина. Исключать её из ДОСТАВКИ нельзя —
  /// человек, вернувшийся из отпуска, получил бы пустой чат. Разница в сроке
  /// годности: звонок живёт 45 секунд, и устройство, молчащее пятые сутки, на
  /// него не ответит никогда.
  ///
  /// 🔴 НИКОГДА НЕ СУЖАЕТ ДО ПУСТОГО. Нет свежих — звоним всем, как раньше:
  /// иначе человек с единственным телефоном, не заходивший три дня, перестал бы
  /// принимать звонки вовсе.
  @visibleForTesting
  static List<String> narrowCallTargetsByLiveness({
    required List<String> targets,
    required List<RelayDeviceLiveness> liveness,
    required int nowMs,
  }) {
    // 🔴 ПЕРЕЧЕНЬ, А НЕ ЧИСЛО (11.09.2026). Разбор показал, что iPhone слал все
    // сигналы на устройство `0e09b901`, у которого нет push-токена, в очереди
    // 24 застрявших сообщения и `next_seq` 114 против 1216 у настоящего
    // телефона владельца. Сказать по журналу, откуда взялся такой адресат, было
    // НЕЧЕМ: писалось только `targetCount`. Ниже — сам список и решение по
    // каждому, иначе выбирать между «кэш устарел» и «отбор ошибся» невозможно.
    if (targets.length < 2 || liveness.isEmpty) {
      DiagLog.event('call', 'targets_no_narrowing', {
        'why': targets.length < 2 ? 'single_target' : 'no_liveness',
        'targets': targets.map(DiagLog.pfx).join(','),
        'liveness_rows': liveness.length,
      });
      return targets;
    }
    final lastSignal = <String, int>{};
    final superseded = <String>{};
    for (final row in liveness) {
      lastSignal[row.deviceId] = row.lastSignalMs;
      if (row.superseded) superseded.add(row.deviceId);
    }
    // 🔴 В-1 (11.09.2026): ОТСЕЧКА ПО МОЛЧАНИЮ УБРАНА.
    //
    // Прежнее правило «молчит дольше трёх суток — не звоним» исходило из того,
    // что давность равна недостижимости. Полевой разбор показал обратное:
    //
    //   * телефон владельца числился молчащим трое суток — он не ходит на реле
    //     сам, ему приходят пуши, и этого достаточно. Разбудить его можно
    //     мгновенно;
    //   * десктоп, запущенный накануне, выглядел «свежим» — но был закрыт, и
    //     разбудить его нечем вовсе.
    //
    // Отбор оставлял десктоп и выбрасывал телефон: звонок уходил в никуда.
    // Снаружи — «звоню с iPhone, на Android не приходит вообще».
    //
    // Требование владельца: звонить на ВСЕ подключённые устройства.
    //
    // Что осталось от прежней защиты:
    //   * `superseded` отсекается по-прежнему — это настоящая замена устройства
    //     и главный источник мусора, ради которого правка 15.08 и делалась;
    //   * от лишних запросов защищает ПОТОЛОК веера, а не выбор одного.
    //
    // Правильный признак — «есть push-токен или живое соединение» — клиенту
    // пока недоступен: `RelayDeviceLiveness` его не несёт. Это вариант В-2,
    // он требует правки реле и делается отдельно.
    final fresh = targets
        .where((id) => !superseded.contains(id))
        .toList(growable: false);
    // Решение по КАЖДОМУ устройству — чтобы было видно не только кого выбрали,
    // но и кого отбросили и почему.
    DiagLog.event('call', 'targets_verdicts', {
      'verdicts': targets.map((id) {
        final p = DiagLog.pfx(id);
        if (superseded.contains(id)) return '$p=superseded';
        final seen = lastSignal[id];
        if (seen == null || seen <= 0) return '$p=unknown_kept';
        final silentMs = nowMs - seen;
        if (silentMs < 0) return '$p=future_kept';
        return silentMs <= _callTargetSilentCutoffMs
            ? '$p=fresh(${(silentMs / 3600000).toStringAsFixed(1)}ч)'
            : '$p=stale(${(silentMs / 3600000).toStringAsFixed(1)}ч)';
      }).join(' '),
      'kept': fresh.map(DiagLog.pfx).join(','),
    });
    if (fresh.isEmpty) {
      // Все устройства помечены заменёнными — в пустоту звонить нельзя,
      // звоним всем, как и раньше.
      DiagLog.event('call', 'targets_all_superseded_fallback', {
        'targets': targets.map(DiagLog.pfx).join(','),
      });
      return targets;
    }
    if (fresh.length <= _callFanoutMaxDevices) return fresh;
    // Потолок веера. Режем по свежести: те, кого видели позже, вероятнее
    // ответят. Устройство без сведений о живости считаем самым свежим — мы про
    // него ничего плохого не знаем, а хоронить по незнанию нельзя.
    final ordered = fresh.toList()
      ..sort((a, b) {
        final sa = lastSignal[a] ?? 1 << 62;
        final sb = lastSignal[b] ?? 1 << 62;
        return sb.compareTo(sa);
      });
    final capped = ordered.take(_callFanoutMaxDevices).toList(growable: false);
    DiagLog.event('call', 'targets_capped', {
      'from': fresh.length,
      'to': capped.length,
      'kept': capped.map(DiagLog.pfx).join(','),
    });
    return capped;
  }

  Future<List<String>> _resolveCallTargetDevices(String peerProfileId) async {
    final keys = _keys;
    final did = _deviceId;
    if (keys == null || did == null || did.isEmpty) {
      return const <String>[];
    }

    final now = DateTime.now().millisecondsSinceEpoch;
    final cached = _callTargetCache[peerProfileId];
    if (cached != null &&
        cached.expiresAtMs > now &&
        cached.deviceIds.isNotEmpty) {
      callOpLog(
        'AppCtrl',
        'call_target_devices_cache_hit',
        fields: <String, Object?>{
          'peerProfileId': peerProfileId,
          'targetCount': cached.deviceIds.length,
          // 11.09.2026: без перечня было не понять, ЧЬИ это устройства.
          'devices': cached.deviceIds.map(DiagLog.pfx).join(','),
        },
      );
      return cached.deviceIds;
    }

    Object? lastError;
    for (var attempt = 1; attempt <= 3; attempt++) {
      try {
        final targets = await _listRecipientDevicesForSend(
          peerProfileId: peerProfileId,
          selfDeviceId: did,
        );
        if (targets.isNotEmpty) {
          _callTargetCache[peerProfileId] = _CallTargetCacheEntry(
            deviceIds: targets,
            expiresAtMs: now + 15000,
          );
        }
        callOpLog(
          'AppCtrl',
          'call_target_devices_resolved',
          fields: <String, Object?>{
            'peerProfileId': peerProfileId,
            'targetCount': targets.length,
            'attempt': attempt,
            // 11.09.2026: перечень адресатов. Без него разбор 11.09 упёрся в
            // «одно устройство» без возможности узнать, какое именно.
            'devices': targets.map(DiagLog.pfx).join(','),
          },
        );
        _logCallDeviceRefMap(targets);
        return targets;
      } catch (e) {
        lastError = e;
        final msg = e.toString().toLowerCase();
        final isRateLimited =
            msg.contains('429') || msg.contains('rate_limited');
        if (!isRateLimited || attempt >= 3) {
          break;
        }
        await Future.delayed(Duration(milliseconds: 180 * attempt));
      }
    }

    if (cached != null && cached.deviceIds.isNotEmpty) {
      return cached.deviceIds;
    }

    callLog(
      'AppCtrl',
      'resolveCallTargetDevices failed for $peerProfileId: $lastError',
    );
    callOpLog(
      'AppCtrl',
      'call_target_devices_failed',
      fields: <String, Object?>{'peerProfileId': peerProfileId},
    );
    return const <String>[];
  }

