  Future<DeviceContactSyncActionResult> setContactSyncEnabled(
    bool value,
  ) async {
    if (!value) {
      _contactSyncEnabled = false;
      _cancelManagedDeviceContactSync();
      final prefs = _prefs ?? await SharedPreferences.getInstance();
      _prefs = prefs;
      await prefs.setBool(_prefsPrivacySyncContactsKey, false);
      _changed.add(null);
      return const DeviceContactSyncActionResult(
        status: DeviceContactSyncActionStatus.disabled,
      );
    }

    if (!contactSyncSupported) {
      return const DeviceContactSyncActionResult(
        status: DeviceContactSyncActionStatus.unsupported,
      );
    }

    _cancelManagedDeviceContactSync();
    final result = await _syncManagedDeviceContactsInternal(
      promptForPermission: true,
    );
    if (result.status != DeviceContactSyncActionStatus.synced) {
      return result;
    }

    _contactSyncEnabled = true;
    final prefs = _prefs ?? await SharedPreferences.getInstance();
    _prefs = prefs;
    await prefs.setBool(_prefsPrivacySyncContactsKey, true);
    _changed.add(null);
    return result;
  }

  Future<DeviceContactSyncActionResult>
  clearSyncedDeviceContactsAndDisableSync() async {
    if (!contactSyncSupported) {
      return const DeviceContactSyncActionResult(
        status: DeviceContactSyncActionStatus.unsupported,
      );
    }

    final granted = await _deviceContactSyncService.requestPermission();
    if (!granted) {
      return const DeviceContactSyncActionResult(
        status: DeviceContactSyncActionStatus.permissionDenied,
      );
    }

    _cancelManagedDeviceContactSync();
    _contactSyncInFlight = true;
    _changed.add(null);
    try {
      final deletedCount = await _deviceContactSyncService
          .deleteManagedContacts();
      _contactSyncEnabled = false;
      final prefs = _prefs ?? await SharedPreferences.getInstance();
      _prefs = prefs;
      await prefs.setBool(_prefsPrivacySyncContactsKey, false);
      return DeviceContactSyncActionResult(
        status: DeviceContactSyncActionStatus.cleared,
        deletedCount: deletedCount,
      );
    } catch (error) {
      _debugRuntimeLog('Device contact cleanup failed: $error');
      return DeviceContactSyncActionResult(
        status: DeviceContactSyncActionStatus.failed,
        errorMessage: error.toString(),
      );
    } finally {
      _contactSyncInFlight = false;
      _changed.add(null);
    }
  }

  void _cancelManagedDeviceContactSync() {
    _contactSyncTimer?.cancel();
    _contactSyncTimer = null;
  }

  void _scheduleManagedDeviceContactSync({
    Duration delay = const Duration(seconds: 2),
  }) {
    if (!_contactSyncEnabled || !contactSyncSupported) return;
    _cancelManagedDeviceContactSync();
    _contactSyncTimer = Timer(delay, () {
      _contactSyncTimer = null;
      unawaited(
        _syncManagedDeviceContactsBestEffort(promptForPermission: false),
      );
    });
  }

  Future<void> _syncManagedDeviceContactsBestEffort({
    required bool promptForPermission,
  }) async {
    final result = await _syncManagedDeviceContactsInternal(
      promptForPermission: promptForPermission,
    );
    if (result.status == DeviceContactSyncActionStatus.failed) {
      _debugRuntimeLog(
        'Device contact sync failed: ${result.errorMessage ?? 'unknown error'}',
      );
    }
  }

  Future<DeviceContactSyncActionResult> _syncManagedDeviceContactsInternal({
    required bool promptForPermission,
  }) async {
    if (!contactSyncSupported) {
      return const DeviceContactSyncActionResult(
        status: DeviceContactSyncActionStatus.unsupported,
      );
    }
    if (_contactSyncInFlight) {
      return const DeviceContactSyncActionResult(
        status: DeviceContactSyncActionStatus.synced,
      );
    }

    final granted = promptForPermission
        ? await _deviceContactSyncService.requestPermission()
        : await _deviceContactSyncService.hasPermission();
    if (!granted) {
      return const DeviceContactSyncActionResult(
        status: DeviceContactSyncActionStatus.permissionDenied,
      );
    }

    _contactSyncInFlight = true;
    _changed.add(null);
    try {
      final entries = await _buildDeviceContactSyncEntries();
      final summary = await _deviceContactSyncService.syncContacts(
        entries: entries,
      );
      return DeviceContactSyncActionResult(
        status: DeviceContactSyncActionStatus.synced,
        createdCount: summary.createdCount,
        updatedCount: summary.updatedCount,
        deletedCount: summary.deletedCount,
      );
    } catch (error) {
      return DeviceContactSyncActionResult(
        status: DeviceContactSyncActionStatus.failed,
        errorMessage: error.toString(),
      );
    } finally {
      _contactSyncInFlight = false;
      _changed.add(null);
    }
  }

  Future<List<DeviceContactSyncEntry>> _buildDeviceContactSyncEntries() async {
    final contacts = await listContacts();
    return contacts
        .where(_shouldSyncContactToDeviceBook)
        .map(
          (contact) => DeviceContactSyncEntry(
            profileId: contact.profileId.trim(),
            displayName: _resolvedDeviceContactDisplayName(contact),
            avatarPath: contact.avatarPath,
          ),
        )
        .toList(growable: false);
  }

  bool _shouldSyncContactToDeviceBook(Contact contact) {
    final profileId = contact.profileId.trim();
    if (profileId.isEmpty) return false;
    if (profileId == (_profileId ?? '').trim()) return false;
    if (profileId.startsWith('LOCAL-')) return false;
    if (profileId.startsWith('demo:')) return false;
    return true;
  }

  String _resolvedDeviceContactDisplayName(Contact contact) {
    final displayName = (contact.displayName ?? '').trim();
    return displayName.isEmpty ? contact.profileId.trim() : displayName;
  }

