  Future<void> removeMyAvatar() async {
    final prefs = _prefs ?? await SharedPreferences.getInstance();
    _prefs = prefs;
    final old = _myAvatarPath;
    final oldOriginal = _myAvatarOriginalPath;
    final oldVideo = _myAvatarVideoPath;
    _myAvatarPath = null;
    _myAvatarOriginalPath = null;
    // Also drop a premium VIDEO avatar — "delete photo" must leave no avatar
    // at all, not a still-less video that keeps looping.
    _myAvatarVideoPath = null;
    _profileIconAssetPath = null;
    _profileAvatarGradientIndex = 0;
    _profileAvatarIconScale = 1.0;
    await prefs.remove(_prefsMyAvatarPathKey);
    await prefs.remove(_prefsMyAvatarOriginalPathKey);
    await prefs.remove(_prefsMyAvatarVideoKey);
    await prefs.remove(_prefsProfileIconAssetPathKey);
    await prefs.remove(_prefsProfileAvatarGradientIndexKey);
    await prefs.remove(_prefsProfileAvatarIconScaleKey);
    if (oldVideo != null && oldVideo.isNotEmpty) {
      try {
        final f = File(oldVideo);
        if (await f.exists()) await f.delete();
      } catch (_) {
        // ignore
      }
    }
    if (old != null && old.isNotEmpty) {
      try {
        final f = File(old);
        if (await f.exists()) await f.delete();
      } catch (_) {
        // ignore
      }
    }
    if (oldOriginal != null && oldOriginal.isNotEmpty && oldOriginal != old) {
      try {
        final f = File(oldOriginal);
        if (await f.exists()) await f.delete();
      } catch (_) {
        // ignore
      }
    }
    _changed.add(null);
    _scheduleMyProfileMetaPublish();
  }

  Future<void> setMyAvatarFromImageBytes(
    Uint8List bytes, {
    bool keepVideo = false,
  }) async {
    final png = await compute(_prepareMyAvatarPngOnWorker, bytes);

    final dir = await getApplicationDocumentsDirectory();
    final path = p.join(
      dir.path,
      'my_avatar_${DateTime.now().microsecondsSinceEpoch}.png',
    );
    final originalPath = p.join(
      dir.path,
      'my_avatar_original_${DateTime.now().microsecondsSinceEpoch}.img',
    );
    final previousPath = _myAvatarPath;
    final previousOriginalPath = _myAvatarOriginalPath;
    await File(originalPath).writeAsBytes(bytes, flush: true);
    await File(path).writeAsBytes(png, flush: true);

    final prefs = _prefs ?? await SharedPreferences.getInstance();
    _prefs = prefs;
    _myAvatarPath = path;
    if (!keepVideo) _myAvatarVideoPath = null;
    _myAvatarOriginalPath = originalPath;
    _profileIconAssetPath = null;
    _profileAvatarGradientIndex = 0;
    _profileAvatarIconScale = 1.0;
    await prefs.setString(_prefsMyAvatarPathKey, path);
    if (!keepVideo) await prefs.remove(_prefsMyAvatarVideoKey);
    await prefs.setString(_prefsMyAvatarOriginalPathKey, originalPath);
    await prefs.remove(_prefsProfileIconAssetPathKey);
    await prefs.remove(_prefsProfileAvatarGradientIndexKey);
    await prefs.remove(_prefsProfileAvatarIconScaleKey);
    if (previousPath != null &&
        previousPath.isNotEmpty &&
        previousPath != path) {
      try {
        final old = File(previousPath);
        if (await old.exists()) await old.delete();
      } catch (_) {
        // ignore
      }
    }
    if (previousOriginalPath != null &&
        previousOriginalPath.isNotEmpty &&
        previousOriginalPath != originalPath &&
        previousOriginalPath != previousPath) {
      try {
        final old = File(previousOriginalPath);
        if (await old.exists()) await old.delete();
      } catch (_) {
        // ignore
      }
    }
    _changed.add(null);
    _scheduleMyProfileMetaPublish();
  }

  /// Sets a premium animated (video) avatar. The video loops on the owner's own
  /// avatar; [stillBytes] (a frame grabbed from the video) becomes the synced
  /// avatar (avatar_png_b64) so interlocutors see a matching still image.
  Future<void> setMyAvatarVideo(String videoPath, Uint8List stillBytes) async {
    // Set the still as the regular avatar first (this syncs avatar_png_b64),
    // keeping the video path we set right after.
    await setMyAvatarFromImageBytes(stillBytes, keepVideo: true);
    final vp = videoPath.trim();
    if (vp.isEmpty) return;
    _myAvatarVideoPath = vp;
    final prefs = _prefs ?? await SharedPreferences.getInstance();
    _prefs = prefs;
    await prefs.setString(_prefsMyAvatarVideoKey, vp);
    _changed.add(null);
  }

  Future<Uint8List> buildAvatarBytesFromIconAsset({
    required String assetPath,
    required int gradientStartArgb,
    required int gradientEndArgb,
    double iconScale = 1.0,
  }) async {
    final iconBytes = await rootBundle.load(assetPath);
    return buildAvatarBytesFromIconBytes(
      iconBytes: iconBytes.buffer.asUint8List(),
      gradientStartArgb: gradientStartArgb,
      gradientEndArgb: gradientEndArgb,
      iconScale: iconScale,
      debugLabel: assetPath,
    );
  }

  /// Same compositing as [buildAvatarBytesFromIconAsset] but from raw icon bytes
  /// — used for server-hosted cosmetic icons downloaded to disk.
  Future<Uint8List> buildAvatarBytesFromIconBytes({
    required Uint8List iconBytes,
    required int gradientStartArgb,
    required int gradientEndArgb,
    double iconScale = 1.0,
    String debugLabel = 'icon',
  }) async {
    final decodedIcon = img.decodeImage(iconBytes);
    if (decodedIcon == null) {
      throw StateError('Unsupported icon image: $debugLabel');
    }

    const side = 512;
    final canvas = img.Image(width: side, height: side);

    final startA = (gradientStartArgb >> 24) & 0xFF;
    final startR = (gradientStartArgb >> 16) & 0xFF;
    final startG = (gradientStartArgb >> 8) & 0xFF;
    final startB = gradientStartArgb & 0xFF;
    final endA = (gradientEndArgb >> 24) & 0xFF;
    final endR = (gradientEndArgb >> 16) & 0xFF;
    final endG = (gradientEndArgb >> 8) & 0xFF;
    final endB = gradientEndArgb & 0xFF;

    for (var y = 0; y < side; y++) {
      final t = y / (side - 1);
      final a = (startA + ((endA - startA) * t)).round().clamp(0, 255);
      final r = (startR + ((endR - startR) * t)).round().clamp(0, 255);
      final g = (startG + ((endG - startG) * t)).round().clamp(0, 255);
      final b = (startB + ((endB - startB) * t)).round().clamp(0, 255);
      for (var x = 0; x < side; x++) {
        canvas.setPixelRgba(x, y, r, g, b, a);
      }
    }

    final trimmedIcon = _cropTransparentBounds(decodedIcon);
    final normalizedScale = iconScale.clamp(0.35, 1.25);
    final longestSide = trimmedIcon.width > trimmedIcon.height
        ? trimmedIcon.width
        : trimmedIcon.height;
    final targetLongest = (side * normalizedScale).round().clamp(1, (side * 2));
    final width = ((trimmedIcon.width * targetLongest) / longestSide)
        .round()
        .clamp(1, (side * 2));
    final height = ((trimmedIcon.height * targetLongest) / longestSide)
        .round()
        .clamp(1, (side * 2));
    final resizedIcon = img.copyResize(
      trimmedIcon,
      width: width,
      height: height,
      interpolation: img.Interpolation.average,
    );
    img.compositeImage(
      canvas,
      resizedIcon,
      dstX: (side - resizedIcon.width) ~/ 2,
      dstY: (side - resizedIcon.height) ~/ 2,
    );

    return Uint8List.fromList(img.encodePng(canvas));
  }

  Future<void> setMyAvatarFromIconAsset({
    required String assetPath,
    required int gradientIndex,
    required int gradientStartArgb,
    required int gradientEndArgb,
    double iconScale = 1.0,
  }) async {
    final png = await buildAvatarBytesFromIconAsset(
      assetPath: assetPath,
      gradientStartArgb: gradientStartArgb,
      gradientEndArgb: gradientEndArgb,
      iconScale: iconScale,
    );
    await _persistComposedAvatar(
      png: png,
      iconRefId: assetPath,
      gradientIndex: gradientIndex,
      iconScale: iconScale,
    );
  }

  /// Sets the user's avatar from a server-hosted cosmetic icon (raw full-res
  /// bytes). [iconRefId] is stored as the profile-icon reference — use a
  /// `server:<id>` token so the picker recognises the active selection.
  Future<void> setMyAvatarFromIconBytes({
    required Uint8List iconBytes,
    required String iconRefId,
    required int gradientIndex,
    required int gradientStartArgb,
    required int gradientEndArgb,
    double iconScale = 1.0,
  }) async {
    final png = await buildAvatarBytesFromIconBytes(
      iconBytes: iconBytes,
      gradientStartArgb: gradientStartArgb,
      gradientEndArgb: gradientEndArgb,
      iconScale: iconScale,
      debugLabel: iconRefId,
    );
    await _persistComposedAvatar(
      png: png,
      iconRefId: iconRefId,
      gradientIndex: gradientIndex,
      iconScale: iconScale,
    );
  }

  /// Writes a freshly-composed avatar PNG, updates the in-memory + persisted
  /// profile-icon state, and cleans up the previous avatar files.
  Future<void> _persistComposedAvatar({
    required Uint8List png,
    required String iconRefId,
    required int gradientIndex,
    required double iconScale,
  }) async {
    final dir = await getApplicationDocumentsDirectory();
    final path = p.join(
      dir.path,
      'my_avatar_${DateTime.now().microsecondsSinceEpoch}.png',
    );
    final previousPath = _myAvatarPath;
    final previousOriginalPath = _myAvatarOriginalPath;
    await File(path).writeAsBytes(png, flush: true);

    final prefs = _prefs ?? await SharedPreferences.getInstance();
    _prefs = prefs;
    _myAvatarPath = path;
    _myAvatarOriginalPath = null;
    _profileIconAssetPath = iconRefId;
    _profileAvatarGradientIndex = gradientIndex;
    _profileAvatarIconScale = iconScale;

    await prefs.setString(_prefsMyAvatarPathKey, path);
    await prefs.remove(_prefsMyAvatarOriginalPathKey);
    await prefs.setString(_prefsProfileIconAssetPathKey, iconRefId);
    await prefs.setInt(_prefsProfileAvatarGradientIndexKey, gradientIndex);
    await prefs.setDouble(_prefsProfileAvatarIconScaleKey, iconScale);
    if (previousPath != null &&
        previousPath.isNotEmpty &&
        previousPath != path) {
      try {
        final old = File(previousPath);
        if (await old.exists()) await old.delete();
      } catch (_) {
        // ignore
      }
    }
    if (previousOriginalPath != null && previousOriginalPath.isNotEmpty) {
      try {
        final old = File(previousOriginalPath);
        if (await old.exists()) await old.delete();
      } catch (_) {
        // ignore
      }
    }

    _changed.add(null);
    _scheduleMyProfileMetaPublish();
  }

  /// When this device last CHANGED its own nickname/bio, and when a publish of
  /// them last SUCCEEDED. Only when the second is not older than the first has
  /// everything local reached the server — and only then may a pull overwrite
  /// local values. Without this pair, a publish that quietly failed would let
  /// the next pull revert the rename the user just typed.
  int _myProfileMetaDirtyAtMs = 0;
  int _myProfileMetaPublishOkAtMs = 0;

  void _scheduleMyProfileMetaPublish() {
    _myProfileMetaDirtyAtMs = DateTime.now().millisecondsSinceEpoch;
    _myProfileMetaPublishRequested = true;
    if (_myProfileMetaPublishInFlight) {
      return;
    }
    unawaited(_drainMyProfileMetaPublishQueue());
  }

  Future<void> _drainMyProfileMetaPublishQueue() async {
    if (_myProfileMetaPublishInFlight) {
      return;
    }
    _myProfileMetaPublishInFlight = true;
    try {
      do {
        _myProfileMetaPublishRequested = false;
        final ok = await _publishMyProfileMetaBestEffort();
        if (ok) {
          _myProfileMetaPublishOkAtMs = DateTime.now().millisecondsSinceEpoch;
        }
      } while (_myProfileMetaPublishRequested);
    } finally {
      _myProfileMetaPublishInFlight = false;
    }
  }

  img.Image _cropTransparentBounds(img.Image source) {
    var minX = source.width;
    var minY = source.height;
    var maxX = -1;
    var maxY = -1;

    for (var y = 0; y < source.height; y++) {
      for (var x = 0; x < source.width; x++) {
        final pixel = source.getPixel(x, y);
        final alpha = pixel.a;
        if (alpha <= 0) continue;
        if (x < minX) minX = x;
        if (x > maxX) maxX = x;
        if (y < minY) minY = y;
        if (y > maxY) maxY = y;
      }
    }

    if (maxX < minX || maxY < minY) {
      return source;
    }

    return img.copyCrop(
      source,
      x: minX,
      y: minY,
      width: (maxX - minX + 1),
      height: (maxY - minY + 1),
    );
  }

  List<String> _cleanupExistingPaths(List<String> raw) {
    final unique = <String>{};
    for (final item in raw) {
      final path = item.trim();
      if (path.isEmpty) continue;
      if (!File(path).existsSync()) continue;
      unique.add(path);
    }
    return unique.toList(growable: true);
  }

  static String _sanitizeProfileBio(String raw) {
    final cleaned = raw
        .trim()
        .replaceAll(RegExp(r'[\r\n\t]'), ' ')
        .replaceAll(RegExp(r'\s{2,}'), ' ');
    return cleaned.length > 140 ? cleaned.substring(0, 140) : cleaned;
  }

  /// Normalizes a cosmetic (unsigned) id (frame/cover) to the shared contract:
  /// empty/null OR matches `^[a-z0-9_]{1,32}$`. Anything else collapses to null.
  static final RegExp _cosmeticIdPattern = RegExp(r'^[a-z0-9_]{1,32}$');
  static String? _normalizeCosmeticId(String? raw) {
    final v = raw?.trim();
    if (v == null || v.isEmpty) return null;
    return _cosmeticIdPattern.hasMatch(v) ? v : null;
  }

  static String _normalizePrivacyAudienceValue(
    String raw, {
    String fallback = 'everyone',
  }) {
    final normalized = raw.trim().toLowerCase();
    return normalized == 'nobody' ||
            normalized == 'contacts' ||
            normalized == 'everyone'
        ? normalized
        : fallback;
  }

  static Map<String, String> _parsePrivacyAudienceMap(
    String? raw, {
    required Map<String, String> fallback,
  }) {
    final out = <String, String>{};
    for (final key in _privacyAudienceKeys) {
      out[key] = fallback[key] ?? 'everyone';
    }
    final trimmed = (raw ?? '').trim();
    if (trimmed.isEmpty) {
      return out;
    }
    try {
      final decoded = jsonDecode(trimmed);
      if (decoded is Map) {
        for (final key in _privacyAudienceKeys) {
          final value = decoded[key];
          if (value is String) {
            out[key] = _normalizePrivacyAudienceValue(
              value,
              fallback: out[key] ?? 'everyone',
            );
          }
        }
      }
    } catch (_) {
      // Ignore malformed privacy payloads and fall back to safe defaults.
    }
    return out;
  }

  static String _encodePrivacyAudienceMap(Map<String, String> value) {
    final ordered = <String, String>{};
    for (final key in _privacyAudienceKeys) {
      ordered[key] = _normalizePrivacyAudienceValue(
        value[key] ?? _defaultPrivacyAudience[key] ?? 'everyone',
        fallback: _defaultPrivacyAudience[key] ?? 'everyone',
      );
    }
    return jsonEncode(ordered);
  }

  static bool _audienceAllows(String audience, {required bool isContact}) {
    switch (_normalizePrivacyAudienceValue(audience)) {
      case 'nobody':
        return false;
      case 'contacts':
        return isContact;
      default:
        return true;
    }
  }

  String _selfPrivacyAudienceValue(String key) {
    return _normalizePrivacyAudienceValue(
      _privacyAudience[key] ?? _defaultPrivacyAudience[key] ?? 'everyone',
      fallback: _defaultPrivacyAudience[key] ?? 'everyone',
    );
  }

  String _peerPrivacyAudienceValue(Map<String, Object?>? meta, String key) {
    final parsed = _parsePrivacyAudienceMap(
      meta?['privacy_audience_json'] as String?,
      fallback: _legacyPeerPrivacyAudience,
    );
    return parsed[key] ?? _legacyPeerPrivacyAudience[key] ?? 'everyone';
  }

  String? _trimmedMetaString(Map<String, Object?>? row, String key) {
    final value = (row?[key] as String?)?.trim();
    return (value != null && value.isNotEmpty) ? value : null;
  }

  String? _existingAvatarFilePath(String? rawPath) {
    final path = rawPath?.trim();
    if (path == null || path.isEmpty) {
      return null;
    }
    try {
      final file = File(path);
      if (!file.existsSync() || file.lengthSync() <= 0) {
        return null;
      }
      return path;
    } catch (_) {
      return null;
    }
  }

  /// FIX (2026-07-13, profile media persistence): own-profile media paths are
  /// persisted ABSOLUTE and rooted in the app documents directory, whose iOS
  /// container UUID changes on reinstall / device-migration / restore. When the
  /// stored absolute path no longer resolves, retry the SAME file relative to
  /// the CURRENT documents dir before giving up — so the avatar/cover/video is
  /// recovered instead of lost. Files at docs root rebase by basename; profile-
  /// media library files keep their `profile_media/<category>/` subpath. Returns
  /// the resolved existing path (rebased if needed) or null if truly gone. Pure
  /// resolver — never deletes.
  String? _rebaseOwnMediaPath(String? stored, String docsPath) {
    final raw = stored?.trim();
    if (raw == null || raw.isEmpty) return null;
    bool ok(String path) {
      try {
        final f = File(path);
        return f.existsSync() && f.lengthSync() > 0;
      } catch (_) {
        return false;
      }
    }

    if (ok(raw)) return raw;
    // Stale absolute path — rebase the relative portion under the live docs dir.
    try {
      final norm = raw.replaceAll('\\', '/');
      const anchor = '/profile_media/';
      final idx = norm.lastIndexOf(anchor);
      final rel = idx >= 0 ? norm.substring(idx + 1) : p.basename(raw);
      if (rel.isEmpty) return null;
      final rebased = p.join(docsPath, rel);
      if (ok(rebased)) return rebased;
    } catch (_) {}
    return null;
  }

  /// Rebases the own-profile scalar + list media pointers (cover image/video,
  /// avatar video, and the gallery/background/music libraries) against the
  /// current documents dir and re-persists any that moved. Runs early in init so
  /// the subsequent field reads + existence cleanup see the corrected paths.
  /// The avatar STILL is handled separately in
  /// [_restoreMyProfileIconAvatarIfNeeded]. Non-destructive: a pointer that
  /// cannot be resolved is left as-is (init cleanup decides), never wiped here.
  Future<void> _rebaseOwnMediaPointers(SharedPreferences prefs) async {
    final String docsPath;
    try {
      docsPath = (await getApplicationDocumentsDirectory()).path;
    } catch (_) {
      return;
    }
    for (final key in const [
      _prefsMyCoverImageKey,
      _prefsMyCoverVideoKey,
      _prefsMyAvatarVideoKey,
    ]) {
      final cur = prefs.getString(key);
      final rebased = _rebaseOwnMediaPath(cur, docsPath);
      if (rebased != null && rebased != cur) {
        await prefs.setString(key, rebased);
      }
    }
    for (final key in const [
      _prefsProfileGalleryPathsKey,
      _prefsProfileBackgroundPathsKey,
      _prefsProfileMusicPathsKey,
    ]) {
      final cur = prefs.getStringList(key);
      if (cur == null || cur.isEmpty) continue;
      var changed = false;
      final out = <String>[];
      for (final entry in cur) {
        final rebased = _rebaseOwnMediaPath(entry, docsPath);
        if (rebased != null) {
          out.add(rebased);
          if (rebased != entry) changed = true;
        } else {
          out.add(entry); // keep; existence cleanup drops it only if truly gone
        }
      }
      if (changed) await prefs.setStringList(key, out);
    }
  }

  Future<void> _restoreMyProfileIconAvatarIfNeeded() async {
    final currentAvatarPath = _existingAvatarFilePath(_myAvatarPath);
    if (currentAvatarPath != null) {
      _myAvatarPath = currentAvatarPath;
      return;
    }

    final prefs = _prefs ?? await SharedPreferences.getInstance();
    _prefs = prefs;

    final assetPath = (_profileIconAssetPath ?? '').trim();
    if (assetPath.isEmpty) {
      // FIX (2026-07-13, profile photo persistence): a real photo avatar whose
      // absolute path went stale after a container move (reinstall / device
      // migration / restore) — recover it by basename under the CURRENT docs dir
      // BEFORE erasing the pointer. Previously init deleted the pointer here,
      // turning a transient "file not found at old path" into permanent loss
      // even though the file was physically present under the new container.
      try {
        final docsPath = (await getApplicationDocumentsDirectory()).path;
        final rebased = _rebaseOwnMediaPath(_myAvatarPath, docsPath);
        if (rebased != null) {
          _myAvatarPath = rebased;
          await prefs.setString(_prefsMyAvatarPathKey, rebased);
          final rebasedOrig = _rebaseOwnMediaPath(
            prefs.getString(_prefsMyAvatarOriginalPathKey),
            docsPath,
          );
          if (rebasedOrig != null) {
            _myAvatarOriginalPath = rebasedOrig;
            await prefs.setString(_prefsMyAvatarOriginalPathKey, rebasedOrig);
          }
          return;
        }
      } catch (_) {}
      _myAvatarPath = null;
      _myAvatarOriginalPath = null;
      await prefs.remove(_prefsMyAvatarPathKey);
      await prefs.remove(_prefsMyAvatarOriginalPathKey);
      return;
    }

    final safeIndex = _profileAvatarGradientIndex < 0
        ? 0
        : (_profileAvatarGradientIndex >= kProfileIconAllGradients.length
              ? kProfileIconAllGradients.length - 1
              : _profileAvatarGradientIndex);
    final gradientPair = kProfileIconAllGradients[safeIndex];

    try {
      await setMyAvatarFromIconAsset(
        assetPath: assetPath,
        gradientIndex: safeIndex,
        gradientStartArgb: gradientPair.startArgb,
        gradientEndArgb: gradientPair.endArgb,
        iconScale: _profileAvatarIconScale,
      );
    } catch (_) {
      _myAvatarPath = null;
      _myAvatarOriginalPath = null;
      await prefs.remove(_prefsMyAvatarPathKey);
      await prefs.remove(_prefsMyAvatarOriginalPathKey);
    }
  }

  String? _visiblePeerAvatarPath({
    required Map<String, Object?>? contactRow,
    required Map<String, Object?>? metaRow,
  }) {
    final localAvatar = _existingAvatarFilePath(
      _trimmedMetaString(contactRow, 'avatar_path'),
    );
    if (localAvatar != null) {
      return localAvatar;
    }
    final metaAvatar = _trimmedMetaString(metaRow, 'avatar_path');
    if (metaAvatar == null) {
      return null;
    }
    final audience = _peerPrivacyAudienceValue(metaRow, 'photo');
    return _audienceAllows(audience, isContact: contactRow != null)
        ? _existingAvatarFilePath(metaAvatar)
        : null;
  }

  int? _visiblePeerLastSeenAtMs({
    required Map<String, Object?>? contactRow,
    required Map<String, Object?>? metaRow,
    required int? lastSeenAtMs,
  }) {
    if (lastSeenAtMs == null || lastSeenAtMs <= 0) {
      return null;
    }
    final audience = _peerPrivacyAudienceValue(metaRow, 'last_seen');
    return _audienceAllows(audience, isContact: contactRow != null)
        ? lastSeenAtMs
        : null;
  }

  bool _shouldPublishLastSeenPresence() {
    return _selfPrivacyAudienceValue('last_seen') != 'nobody';
  }

  /// Разовая уборка временных файлов отправки, оставшихся от прошлых запусков.
  ///
  /// 🔴 ПОЧЕМУ (02.09.2026, аудит передачи файлов). Путь отправки создаёт три
  /// вида временных файлов, и ни один из них не удалялся надёжно:
  ///
  ///   * `secretly_att_*.bin` — шифртекст вложения; удалялся только после
  ///     УСПЕШНОЙ заливки (теперь закрыто через `finally` в
  ///     `AttachmentService`, но старый мусор уже лежит на устройствах);
  ///   * `sendstrip_*` — копия снимка с вычищенными метаданными EXIF;
  ///     не удалялась никогда;
  ///   * `vsend/*_c.mp4` — сжатое видео; удалялось только в одном случае, если
  ///     оказалось БОЛЬШЕ оригинала.
  ///
  /// Каждый файл размером с само вложение. Три отменённые отправки
  /// двухсотмегабайтного видео — почти шестьсот мегабайт, которые не уберёт
  /// никто: свипера по этим префиксам в проекте не было вовсе.
  ///
  /// 🔴 УДАЛЯЕМ ТОЛЬКО СТАРОЕ. Отправка может идти в фоне и в момент запуска —
  /// свежий файл принадлежит живой заливке, и удалить его значит эту заливку
  /// сорвать. Шесть часов заведомо больше самой долгой заливки: потолок
  /// таймаута блоба — десять минут.
  ///
  /// Полностью best-effort: любая ошибка проглатывается. Не убранный временный
  /// файл — это место на диске, а сорванный запуск из-за уборки мусора — это
  /// приложение, которое не открылось.
  static const Duration _sendTempFileMaxAge = Duration(hours: 6);

  Future<void> _sweepStaleSendTempFiles() async {
    try {
      final tmp = await getTemporaryDirectory();
      if (!tmp.existsSync()) return;
      final cutoffMs =
          DateTime.now().millisecondsSinceEpoch -
          _sendTempFileMaxAge.inMilliseconds;
      var removed = 0;
      var freedBytes = 0;

      Future<void> removeIfStale(FileSystemEntity entity) async {
        if (entity is! File) return;
        try {
          final stat = await entity.stat();
          if (stat.modified.millisecondsSinceEpoch > cutoffMs) return;
          final size = stat.size;
          await entity.delete();
          removed++;
          freedBytes += size;
        } catch (_) {
          // Файл мог исчезнуть сам или быть занят — не наше дело.
        }
      }

      await for (final entity in tmp.list(followLinks: false)) {
        final name = p.basename(entity.path);
        if (name.startsWith('secretly_att_') || name.startsWith('sendstrip_')) {
          await removeIfStale(entity);
        }
      }

      final vsend = Directory(p.join(tmp.path, 'vsend'));
      if (vsend.existsSync()) {
        await for (final entity in vsend.list(followLinks: false)) {
          await removeIfStale(entity);
        }
      }

      if (removed > 0) {
        DiagLog.event('storage', 'send_temp_swept', {
          'files': removed,
          'freed_kb': (freedBytes / 1024).round(),
        });
      }
    } catch (_) {
      // Уборка мусора не имеет права мешать запуску.
    }
  }

  Future<void> _pruneCachedProfileMetaAvatars({
    required String profileId,
    String? keepPath,
  }) async {
    final dir = await getApplicationDocumentsDirectory();
    final avatarDir = Directory(p.join(dir.path, 'profile_avatars'));
    if (!await avatarDir.exists()) {
      return;
    }
    final safePrefix =
        '${profileId.replaceAll(RegExp(r'[^a-zA-Z0-9_-]'), '_')}_';
    await for (final entity in avatarDir.list(followLinks: false)) {
      if (entity is! File) continue;
      final filePath = entity.path;
      final fileName = p.basename(filePath);
      if (!fileName.startsWith(safePrefix)) continue;
      if (keepPath != null && p.equals(filePath, keepPath)) continue;
      try {
        await entity.delete();
      } catch (_) {
        // ignore
      }
    }
  }

  Future<String> _cacheProfileMetaAvatar({
    required String profileId,
    required Uint8List bytes,
  }) async {
    final dir = await getApplicationDocumentsDirectory();
    final avatarDir = Directory(p.join(dir.path, 'profile_avatars'));
    if (!await avatarDir.exists()) {
      await avatarDir.create(recursive: true);
    }
    final safe = profileId.replaceAll(RegExp(r'[^a-zA-Z0-9_-]'), '_');
    final hash = crypto.sha256.convert(bytes).toString().substring(0, 24);
    final path = p.join(avatarDir.path, '${safe}_$hash.png');
    final file = File(path);
    if (!await file.exists()) {
      await file.writeAsBytes(bytes, flush: true);
    }
    await _pruneCachedProfileMetaAvatars(profileId: profileId, keepPath: path);
    return path;
  }

  @visibleForTesting
  static Uint8List? encodeProfileMetaAvatarPngForTesting(Uint8List bytes) {
    return _encodeProfileMetaAvatarPngInternal(bytes);
  }

  static Uint8List? _encodeProfileMetaAvatarPngInternal(
    Uint8List bytes, {
    int maxAvatarPngBytes = 512000,
  }) {
    if (bytes.isEmpty) {
      return null;
    }

    final isPng =
        bytes.length >= 8 &&
        bytes[0] == 0x89 &&
        bytes[1] == 0x50 &&
        bytes[2] == 0x4E &&
        bytes[3] == 0x47 &&
        bytes[4] == 0x0D &&
        bytes[5] == 0x0A &&
        bytes[6] == 0x1A &&
        bytes[7] == 0x0A;

    img.Image? decoded;
    try {
      decoded = img.decodeImage(bytes);
    } catch (_) {
      decoded = null;
    }

    if (decoded == null) {
      return isPng && bytes.length <= maxAvatarPngBytes ? bytes : null;
    }

    if (isPng &&
        decoded.width == decoded.height &&
        bytes.length <= maxAvatarPngBytes) {
      return bytes;
    }

    final side = decoded.width < decoded.height
        ? decoded.width
        : decoded.height;
    final x = (decoded.width - side) ~/ 2;
    final y = (decoded.height - side) ~/ 2;
    final cropped = img.copyCrop(
      decoded,
      x: x,
      y: y,
      width: side,
      height: side,
    );

    Uint8List encodeCandidate(img.Image image) {
      return img.PngEncoder(
        filter: img.PngFilter.paeth,
        level: 9,
      ).encode(image, singleFrame: true);
    }

    final targetSizes =
        <int>{
              if (cropped.width <= 1024) cropped.width,
              for (var target = 1024; target >= 128; target -= 64) target,
            }
            .where((value) => value > 0 && value <= cropped.width)
            .toList(growable: false)
          ..sort((a, b) => b.compareTo(a));

    for (final target in targetSizes) {
      final candidate = cropped.width == target && cropped.height == target
          ? cropped
          : img.copyResize(
              cropped,
              width: target,
              height: target,
              interpolation: img.Interpolation.average,
            );
      final png = encodeCandidate(candidate);
      if (png.length <= maxAvatarPngBytes) {
        return png;
      }
    }

    return null;
  }

  Future<void> _publishPresenceHeartbeatBestEffort({bool force = false}) async {
    if (_presenceHeartbeatInFlight || !_shouldPublishLastSeenPresence()) {
      return;
    }
    final nowMs = DateTime.now().millisecondsSinceEpoch;
    if (!force &&
        (nowMs - _lastPresenceHeartbeatAtMs) < _presenceHeartbeatIntervalMs) {
      return;
    }
    _presenceHeartbeatInFlight = true;
    try {
      final status = await _heartbeatOwnProfileActivityBestEffort(
        force: force,
        minIntervalMs: _presenceHeartbeatIntervalMs,
      );
      if (status == null) {
        return;
      }
      if (!status.exists) {
        await _handleDeletedProfileFromServer();
        return;
      }
      await _applyProfileInactivityStatus(status);
      if (status.ok) {
        _lastPresenceHeartbeatAtMs = status.lastActiveAtMs > 0
            ? status.lastActiveAtMs
            : nowMs;
      }
    } finally {
      _presenceHeartbeatInFlight = false;
    }
  }

  Future<String?> cachedProfileBio(String profileId) async {
    final db = _db;
    final pid = profileId.trim();
    if (db == null || pid.isEmpty) return null;
    final meta = await db.profileMetaGet(pid);
    return _trimmedMetaString(meta, 'bio');
  }

  /// Своё фото на устройстве, которое СВОЕГО ФАЙЛА ИМЕТЬ НЕ МОЖЕТ.
  ///
  /// 🔴 ПОЧЕМУ ЭТО ПОНАДОБИЛОСЬ (13.09.2026, компьютер).
  ///
  /// `_myAvatarPath` — файл, выбранный НА ЭТОМ устройстве. Компьютер получает
  /// профиль по QR, а связка фотографию не везёт: в `settings` десктопного
  /// свёртка едут тема, никнейм и списки медиа — и всё. Значит на спаренном
  /// компьютере значение пустое ВСЕГДА, и владелец видит «YU» вместо своего
  /// лица в рейке, в собственных пузырях, в «Избранном» и в списке участников
  /// комнаты — при том что рядом, в кэше метаданных, лежит ровно та
  /// фотография, которую этот же компьютер исправно показывает собеседникам.
  ///
  /// Берём её оттуда же, откуда её берут все остальные, — из собственных
  /// опубликованных метаданных. Настройка приватности здесь НЕ применяется:
  /// «фото видно только контактам» ограничивает чужих, а не меня самого.
  ///
  /// 🔴 ТОЛЬКО ДЛЯ КОМПЬЮТЕРА, и это не осторожность, а требование. На
  /// телефоне пустой `_myAvatarPath` значит «фотографии нет» — в том числе
  /// сразу после удаления. Удаление сервер не принимает: пустое значение там
  /// читается как «мнения нет» (COALESCE в `profile_meta_set`), копия
  /// остаётся. Тот же откат на телефоне вернул бы на экран только что
  /// удалённую фотографию. Выпущенные сборки так себя не ведут.
  Future<String?> _pairedDeviceOwnAvatarPath() async {
    if (!_isDesktopOrWebPlatform) return null;
    final db = _db;
    final pid = (_profileId ?? '').trim();
    if (db == null || pid.isEmpty) return null;
    final meta = await db.profileMetaGet(pid);
    final cached = _existingAvatarFilePath(
      _trimmedMetaString(meta, 'avatar_path'),
    );
    // Кэша нет — значит свои метаданные сюда ещё ни разу не приезжали.
    // Запрос дросселирован, так что звать его из отрисовки списка безопасно.
    if (cached == null) _refreshProfileMetaSoon(pid);
    return cached;
  }

  /// Своё фото, годное к показу на этом устройстве: локальный файл, а если его
  /// быть не может — опубликованная копия. См. [_pairedDeviceOwnAvatarPath].
  Future<String?> resolvedOwnAvatarPath() async {
    final own = (_myAvatarPath ?? '').trim();
    if (own.isNotEmpty) return own;
    return _pairedDeviceOwnAvatarPath();
  }

  Future<String?> cachedProfileAvatarPath(String profileId) async {
    final db = _db;
    final pid = profileId.trim();
    if (db == null || pid.isEmpty) return null;
    // Своё фото лежит не в чужих метаданных, а в собственных настройках —
    // иначе звонок со второго своего устройства показывает пустой кружок.
    if (pid == (_profileId ?? '').trim()) {
      return resolvedOwnAvatarPath();
    }
    final contact = await db.contactGet(pid);
    final meta = await db.profileMetaGet(pid);
    return _visiblePeerAvatarPath(contactRow: contact, metaRow: meta);
  }

  /// Имя собеседника из ЛОКАЛЬНЫХ данных — контакт, а при его отсутствии
  /// никнейм из синхронизированных метаданных профиля.
  ///
  /// 🔴 Парная к [cachedProfileAvatarPath] (23.08.2026). Фото звонок брал
  /// отсюда с 13.07, а имя — только перебором сохранённых контактов, поэтому
  /// звонок от того, кого нет в контактах, показывал сырой profile_id
  /// («3XBC-F5DJ-…» на экране разговора) — при том что никнейм лежал в
  /// метаданных рядом с фотографией, которую тот же экран успешно показывал.
  Future<String?> cachedProfileDisplayName(String profileId) async {
    final db = _db;
    final pid = profileId.trim();
    if (db == null || pid.isEmpty) return null;
    // Свой профиль в контактах не лежит, а звонок со второго собственного
    // устройства — обычное дело: имя берём из своих настроек.
    if (pid == (_profileId ?? '').trim()) {
      final own = _myNickname.trim();
      return own.isEmpty ? null : own;
    }
    final contact = await db.contactGet(pid);
    final meta = await db.profileMetaGet(pid);
    return _resolvedContactDisplayName(contactRow: contact, metaRow: meta);
  }

  Future<String?> cachedPublishedProfileAvatarPath(String profileId) async {
    final db = _db;
    final pid = profileId.trim();
    if (db == null || pid.isEmpty) return null;
    final contact = await db.contactGet(pid);
    final meta = await db.profileMetaGet(pid);
    final metaAvatar = _trimmedMetaString(meta, 'avatar_path');
    if (metaAvatar == null) return null;
    final audience = _peerPrivacyAudienceValue(meta, 'photo');
    return _audienceAllows(audience, isContact: contact != null)
        ? _existingAvatarFilePath(metaAvatar)
        : null;
  }

  Future<bool> _doesPeerAllowCategory(
    String profileId,
    String category, {
    bool defaultIfUnknown = true,
  }) async {
    final db = _db;
    final pid = profileId.trim();
    if (db == null || pid.isEmpty) return defaultIfUnknown;
    if ((_profileId ?? '').trim() == pid) return true;
    final contact = await db.contactGet(pid);
    final meta = await db.profileMetaGet(pid);
    final audience = _peerPrivacyAudienceValue(meta, category);
    return _audienceAllows(audience, isContact: contact != null);
  }

  bool _myAudienceAllowsCategory(String category, {required bool isContact}) {
    return _audienceAllows(
      _selfPrivacyAudienceValue(category),
      isContact: isContact,
    );
  }

  List<String> _mediaListForCategory(String category) {
    switch (category) {
      case 'gallery':
        return _profileGalleryPaths;
      case 'backgrounds':
        return _profileBackgroundPaths;
      case 'music':
        return _profileMusicPaths;
      default:
        throw ArgumentError('Unknown profile media category: $category');
    }
  }

  bool isSupportedProfileMediaPath({
    required String category,
    required String sourcePath,
  }) {
    final normalizedCategory = category.trim();
    final normalizedPath = sourcePath.trim();
    if (normalizedPath.isEmpty) return false;
    final ext = p.extension(normalizedPath).trim().toLowerCase();
    if (ext.isEmpty) return false;
    switch (normalizedCategory) {
      case 'gallery':
      case 'backgrounds':
        return _profileImageMediaExtensions.contains(ext);
      case 'music':
        return _profileMusicMediaExtensions.contains(ext);
      default:
        return false;
    }
  }

  String _defaultProfileMediaExtension(String category) {
    switch (category) {
      case 'gallery':
      case 'backgrounds':
        return '.jpg';
      case 'music':
        return '.mp3';
      default:
        throw ArgumentError('Unknown profile media category: $category');
    }
  }

  Future<void> _saveProfileMediaLists() async {
    final prefs = _prefs ?? await SharedPreferences.getInstance();
    _prefs = prefs;
    await prefs.setStringList(
      _prefsProfileGalleryPathsKey,
      _profileGalleryPaths.toList(growable: false),
    );
    await prefs.setStringList(
      _prefsProfileBackgroundPathsKey,
      _profileBackgroundPaths.toList(growable: false),
    );
    await prefs.setStringList(
      _prefsProfileMusicPathsKey,
      _profileMusicPaths.toList(growable: false),
    );
  }

  Future<void> addProfileMediaFromPath({
    required String category,
    required String sourcePath,
  }) async {
    final normalizedPath = sourcePath.trim();
    if (!isSupportedProfileMediaPath(
      category: category,
      sourcePath: normalizedPath,
    )) {
      throw ArgumentError(
        'Unsupported profile media type for $category: $sourcePath',
      );
    }

    final source = File(normalizedPath);
    if (!await source.exists()) return;
    final list = _mediaListForCategory(category);

    final docs = await getApplicationDocumentsDirectory();
    final targetDir = Directory(p.join(docs.path, 'profile_media', category));
    if (!await targetDir.exists()) {
      await targetDir.create(recursive: true);
    }

    final extRaw = p.extension(source.path).trim().toLowerCase();
    final ext = extRaw.isEmpty
        ? _defaultProfileMediaExtension(category)
        : extRaw;
    final fileName =
        '${DateTime.now().millisecondsSinceEpoch}_${_uuid.v4().replaceAll('-', '').substring(0, 8)}$ext';
    final targetPath = p.join(targetDir.path, fileName);

    await source.copy(targetPath);
    list.insert(0, targetPath);
    await _saveProfileMediaLists();
    _changed.add(null);
  }

  Future<void> removeProfileMediaAt({
    required String category,
    required int index,
  }) async {
    final list = _mediaListForCategory(category);
    if (index < 0 || index >= list.length) return;
    final oldPath = list.removeAt(index);
    try {
      final f = File(oldPath);
      if (await f.exists()) {
        await f.delete();
      }
    } catch (_) {
      // ignore
    }
    await _saveProfileMediaLists();
    _changed.add(null);
  }

  String _newProfileRequestNonceB64() {
    return base64Encode(utf8.encode(_uuid.v4()));
  }

  Future<void> _applyProfileInactivityStatus(
    ProfileInactivityStatus status,
  ) async {
    if (!status.exists) {
      await _handleDeletedProfileFromServer();
      return;
    }
    final remoteMonths = status.deleteAfterInactivityMonths;
    if (remoteMonths == null) {
      return;
    }
    final normalizedMonths = remoteMonths.clamp(1, 24).toInt();
    if (_privacyDeleteAccountMonths == normalizedMonths) {
      return;
    }
    _privacyDeleteAccountMonths = normalizedMonths;
    final prefs = _prefs ?? await SharedPreferences.getInstance();
    _prefs = prefs;
    await prefs.setInt(_prefsPrivacyDeleteAccountMonthsKey, normalizedMonths);
    _changed.add(null);
  }

  Future<void> _handleDeletedProfileFromServer() async {
    if (_profileDeletionResetInFlight) return;
    _profileDeletionResetInFlight = true;
    try {
      final prefs = _prefs ?? await SharedPreferences.getInstance();
      _prefs = prefs;
      await IdentityJournal.record(
        reason: IdentityJournal.reasonServerSaysDeleted,
        nowMs: DateTime.now().millisecondsSinceEpoch,
        previousProfileId: _profileId,
        previousDeviceId: _deviceId,
      );
      await prefs.setString(
        _prefsPendingStartupWarningKey,
        'This account was deleted after inactivity.',
      );
      await resetProfileAndLocalData();
    } finally {
      _profileDeletionResetInFlight = false;
    }
  }

  Future<ProfileInactivityStatus?> _publishProfileInactivityPolicyBestEffort({
    bool force = false,
  }) async {
    final keys = _keys;
    final pid = _profileId;
    final did = _deviceId;
    if (keys == null ||
        pid == null ||
        pid.isEmpty ||
        did == null ||
        did.isEmpty ||
        _transportBlocked) {
      return null;
    }
    if (_profileInactivitySyncInFlight && !force) {
      return null;
    }

    _profileInactivitySyncInFlight = true;
    try {
      final profileSecretB64 = await SecureSecrets.create().getProfileSecretB64(
        pid,
      );
      if (profileSecretB64 == null || profileSecretB64.isEmpty) {
        return null;
      }
      final kp = await DeviceKeys.create().loadIdentityKeyPair(
        profileId: pid,
        deviceId: did,
      );
      final tsMs = ServerClock.instance.nowMs();
      final nonceB64 = _newProfileRequestNonceB64();
      final msg = AuthSigner.keysProfileInactivitySetMessage(
        profileId: pid,
        deviceId: did,
        deleteAfterInactivityMonths: _privacyDeleteAccountMonths,
        tsMs: tsMs,
        nonceB64: nonceB64,
      );
      final sigB64 = await AuthSigner.signEd25519B64(
        identityKeyPair: kp,
        message: msg,
      );
      final status = await keys.setProfileInactivity(
        profileId: pid,
        deviceId: did,
        deleteAfterInactivityMonths: _privacyDeleteAccountMonths,
        tsMs: tsMs,
        nonceB64: nonceB64,
        signatureB64: sigB64,
        profileSecretB64: profileSecretB64,
      );
      _lastProfileInactivitySyncAtMs = tsMs;
      await _applyProfileInactivityStatus(status);
      return status;
    } catch (_) {
      return null;
    } finally {
      _profileInactivitySyncInFlight = false;
    }
  }

  Future<ProfileInactivityStatus?> _heartbeatOwnProfileActivityBestEffort({
    bool force = false,
    int minIntervalMs = _profileInactivitySyncMinIntervalMs,
  }) async {
    final keys = _keys;
    final pid = _profileId;
    final did = _deviceId;
    if (keys == null ||
        pid == null ||
        pid.isEmpty ||
        did == null ||
        did.isEmpty ||
        _transportBlocked) {
      return null;
    }
    if (_profileInactivitySyncInFlight) {
      return null;
    }

    final nowMs = DateTime.now().millisecondsSinceEpoch;
    if (!force && (nowMs - _lastProfileInactivitySyncAtMs) < minIntervalMs) {
      return null;
    }

    _profileInactivitySyncInFlight = true;
    try {
      final profileSecretB64 = await SecureSecrets.create().getProfileSecretB64(
        pid,
      );
      if (profileSecretB64 == null || profileSecretB64.isEmpty) {
        return null;
      }
      final kp = await DeviceKeys.create().loadIdentityKeyPair(
        profileId: pid,
        deviceId: did,
      );
      final nonceB64 = _newProfileRequestNonceB64();
      // Подпись — временем сервера: у сбитых часов пульс отвергался молча.
      final signTsMs = ServerClock.instance.nowMs();
      final msg = AuthSigner.keysProfileInactivityHeartbeatMessage(
        profileId: pid,
        deviceId: did,
        tsMs: signTsMs,
        nonceB64: nonceB64,
      );
      final sigB64 = await AuthSigner.signEd25519B64(
        identityKeyPair: kp,
        message: msg,
      );
      final status = await keys.heartbeatProfileInactivity(
        profileId: pid,
        deviceId: did,
        tsMs: signTsMs,
        nonceB64: nonceB64,
        signatureB64: sigB64,
        profileSecretB64: profileSecretB64,
      );
      _lastProfileInactivitySyncAtMs = nowMs;
      return status;
    } catch (_) {
      return null;
    } finally {
      _profileInactivitySyncInFlight = false;
    }
  }

  Future<void> _syncProfileInactivityStatusBestEffort({
    bool force = false,
    bool seedServerValueIfMissing = false,
  }) async {
    final status = await _heartbeatOwnProfileActivityBestEffort(
      force: force,
      minIntervalMs: _profileInactivitySyncMinIntervalMs,
    );
    if (status == null) {
      return;
    }
    if (!status.exists) {
      await _handleDeletedProfileFromServer();
      return;
    }
    if (status.deleteAfterInactivityMonths == null &&
        seedServerValueIfMissing) {
      await _publishProfileInactivityPolicyBestEffort(force: true);
      return;
    }
    await _applyProfileInactivityStatus(status);
  }

  Future<bool> _publishMyProfileMetaBestEffort() async {
    final keys = _keys;
    final pid = _profileId;
    final did = _deviceId;
    if (keys == null ||
        pid == null ||
        pid.isEmpty ||
        did == null ||
        did.isEmpty) {
      return false;
    }
    if (_transportBlocked) return false;

    final nickname = _myNickname.trim();
    final bio = _sanitizeProfileBio(_myBio);

    // 🔴 УСТРОЙСТВО НЕ ДОЛЖНО СТИРАТЬ ТО, ЧЕГО ОНО НЕ ЗНАЕТ (13.09.2026).
    //
    // Никнейм, фото и описание сервер сливает через COALESCE: пустое значение
    // читается как «мнения нет» и старое сохраняется. А украшения и карту
    // видимости он присваивает КАК ЕСТЬ. Компьютер, получивший профиль по QR,
    // об украшениях не знает ничего (связка их не везёт) и карту видимости
    // держит умолчаниями — и каждые десять минут молча переписывал у всех
    // собеседников рамку, обложку и эмодзи-статус на пустоту, а выбор «кому
    // что видно» — на заводской.
    //
    // Поэтому: нет собственного мнения — публикуем то, что уже опубликовано.
    // Мнение здесь — это СЫРОЕ поле, а не его премиальная обёртка: когда
    // подписка кончилась, украшение выбрано, но публиковать его нельзя, и
    // пустота в этом случае осмысленна.
    String? frameIdToPublish = myFrameId;
    String? coverIdToPublish = myCoverId;
    String? emojiStatusToPublish = myEmojiStatus;
    var privacyAudienceJson = _encodePrivacyAudienceMap(_privacyAudience);
    if (_isDesktopOrWebPlatform) {
      Map<String, Object?>? publishedMeta;
      try {
        publishedMeta = await _db?.profileMetaGet(pid);
      } catch (_) {
        publishedMeta = null;
      }
      if (publishedMeta != null) {
        if (_myFrameId == null) {
          frameIdToPublish = _trimmedMetaString(publishedMeta, 'frame_id');
        }
        if (_myCoverId == null) {
          coverIdToPublish = _trimmedMetaString(publishedMeta, 'cover_id');
        }
        if (_myEmojiStatus == null) {
          emojiStatusToPublish = _trimmedMetaString(
            publishedMeta,
            'emoji_status',
          );
        }
        if (!_privacyAudienceChosenHere) {
          final published = _trimmedMetaString(
            publishedMeta,
            'privacy_audience_json',
          );
          if (published != null) privacyAudienceJson = published;
        }
      }
    }

    String avatarB64 = '';
    Uint8List? avatarSourceBytes;
    final sourcePaths = <String>[];
    final originalPath = _existingAvatarFilePath(_myAvatarOriginalPath);
    if (originalPath != null && originalPath.isNotEmpty) {
      sourcePaths.add(originalPath);
    }
    final localPath = _existingAvatarFilePath(_myAvatarPath);
    if (localPath != null &&
        localPath.isNotEmpty &&
        localPath != originalPath) {
      sourcePaths.add(localPath);
    }

    for (final sourcePath in sourcePaths) {
      try {
        final bytes = await File(sourcePath).readAsBytes();
        avatarSourceBytes = bytes;

        // Keep the locally displayed avatar intact; upload normalization is
        // transport-specific and may be lossy.
        final publishBytes = await compute(
          _encodeProfileMetaAvatarPngOnWorker,
          bytes,
        );
        if (publishBytes == null || publishBytes.isEmpty) {
          continue;
        }
        avatarB64 = base64Encode(publishBytes);
        break;
      } catch (_) {
        // ignore
      }
    }

    try {
      final profileSecretB64 = await SecureSecrets.create().getProfileSecretB64(
        pid,
      );
      if (profileSecretB64 == null || profileSecretB64.isEmpty) {
        return false;
      }
      final deviceKeys = DeviceKeys.create();
      final kp = await deviceKeys.loadIdentityKeyPair(
        profileId: pid,
        deviceId: did,
      );
      final avatarCandidates = <String>[avatarB64];
      if (avatarB64.isNotEmpty && avatarSourceBytes != null) {
        try {
          final legacyBytes = await compute(
            _encodeProfileMetaAvatarPngLegacyOnWorker,
            avatarSourceBytes,
          );
          if (legacyBytes != null && legacyBytes.isNotEmpty) {
            avatarCandidates.add(base64Encode(legacyBytes));
          }
        } catch (_) {
          // ignore
        }
        avatarCandidates.add('');
      }

      // Custom cover image (cover_id == 'custom') → base64 for cross-device sync.
      // Gated getters → a lapsed (non-premium) user publishes null = clears.
      String? coverPngB64ToPublish;
      if (myCoverId == 'custom') {
        final cp = myCoverImagePath;
        if (cp != null && cp.isNotEmpty) {
          try {
            final bytes = await File(cp).readAsBytes();
            if (bytes.isNotEmpty) {
              coverPngB64ToPublish = base64Encode(bytes);
            }
          } catch (_) {
            // ignore — cover file unreadable
          }
        }
      }

      final tried = <String>{};
      for (final candidateAvatarB64 in avatarCandidates) {
        if (!tried.add(candidateAvatarB64)) continue;
        try {
          final msg = AuthSigner.keysProfileMetaSetMessage(
            profileId: pid,
            deviceId: did,
            nickname: nickname,
            avatarPngB64: candidateAvatarB64,
            bio: bio,
            privacyAudienceJson: privacyAudienceJson,
            searchableByNickname: _discoverableByNickname,
          );
          final sigB64 = await AuthSigner.signEd25519B64(
            identityKeyPair: kp,
            message: msg,
          );
          final ok = await keys.setProfileMeta(
            profileId: pid,
            deviceId: did,
            nickname: nickname.isEmpty ? null : nickname,
            avatarPngB64: candidateAvatarB64.isEmpty
                ? null
                : candidateAvatarB64,
            bio: bio.isEmpty ? null : bio,
            privacyAudienceJson: privacyAudienceJson,
            searchableByNickname: _discoverableByNickname,
            frameId: frameIdToPublish,
            coverId: coverIdToPublish,
            coverPngB64: coverPngB64ToPublish,
            emojiStatus: emojiStatusToPublish,
            // Server-meaningful only for a genuine paid tier — never fail-open
            // (when monetization is off the tier is free, so no badge).
            premiumBadge: entitlementStateNow.tier.isPaid ? '1' : null,
            signatureB64: sigB64,
            profileSecretB64: profileSecretB64,
          );

          if (ok) {
            _lastMyMetaPublishAtMs = DateTime.now().millisecondsSinceEpoch;
            if (_shouldPublishLastSeenPresence()) {
              _lastPresenceHeartbeatAtMs = _lastMyMetaPublishAtMs;
            }
            final prefs = _prefs ?? await SharedPreferences.getInstance();
            _prefs = prefs;
            await prefs.setInt(
              _prefsLastMetaPublishAtMsKey,
              _lastMyMetaPublishAtMs,
            );
            return true;
          }
          _debugRuntimeLog('Profile meta publish rejected by Keys (ok=false).');
        } catch (e) {
          _debugRuntimeLog('Profile meta publish failed: $e');
        }
      }
    } catch (_) {
      // ignore
    }
    return false;
  }

  /// Забрать своё опубликованное лицо ПРЯМО СЕЙЧАС и принять его.
  ///
  /// Обход по таймеру ходит раз в десять минут — этого достаточно, чтобы
  /// устройство догнало остальные само, но мало, когда человек СМОТРИТ на свой
  /// профиль и ждёт, что увидит там правду. Экран профиля зовёт этот метод при
  /// открытии.
  Future<void> refreshMyProfileMetaNow() async {
    final pid = _profileId;
    if (pid == null || pid.isEmpty || _transportBlocked) return;
    try {
      await refreshProfileMeta(pid);
      await _adoptMyPublishedProfileMeta();
    } catch (_) {
      // Молча: это освежение, а не действие человека. Не вышло — останется
      // то, что было, и следующий обход попробует снова.
    }
  }

  /// Принять СВОИ опубликованные метаданные в состояние этого устройства.
  ///
  /// 🔴 ПОЧЕМУ БЕЗ ЭТОГО НЕ РАБОТАЛА СИНХРОНИЗАЦИЯ УКРАШЕНИЙ (15.09.2026).
  ///
  /// Никнейм, описание, рамка, обложка и эмодзи-статус — свойства АККАУНТА,
  /// но хранились у каждого устройства своей копией в `SharedPreferences`.
  /// Устройство публиковало свою копию и никогда не читало чужую. Итог,
  /// который и увидел владелец: обложку поменяли на компьютере, собеседники
  /// увидели новую, а на собственном телефоне осталась старая.
  ///
  /// Правило принятия — ПО ЗНАЧЕНИЮ, а не по времени.
  ///
  /// Сравнивать отметки времени нельзя: `updated_at_ms` приходит с сервера, а
  /// «когда я публиковал» — местное время устройства; расхождение часов
  /// превратило бы правило в лотерею. Поэтому:
  ///
  ///   • есть НЕОТПРАВЛЕННАЯ своя правка — не трогаем ничего. Иначе устройство
  ///     стёрло бы то, что человек только что выбрал, но не успел
  ///     опубликовать (выбрал рамку в самолёте);
  ///   • иначе принимаем опубликованное значение, если оно отличается.
  ///
  /// Это сходится: приняв чужое значение, устройство публикует уже его, и
  /// следующий обход находит совпадение. Два одновременных изменения на двух
  /// устройствах сойдутся на том, которое сервер записал последним.
  ///
  /// 🔴 НАСТРОЙКИ ПРИВАТНОСТИ ЗДЕСЬ НЕ ПРИНИМАЮТСЯ, и это НЕ недоделка.
  /// Менять собственное «кому что видно» по ответу сервера устройство не
  /// должно: цена ошибки там другая, чем у картинки рамки. Их синхронизация —
  /// отдельное решение, см. `docs/СИНХРОНИЗАЦИЯ_НАСТРОЕК_2026-09-15.md`.
  static bool _privacyAudienceMapsEqual(
    Map<String, String> a,
    Map<String, String> b,
  ) {
    for (final key in _privacyAudienceKeys) {
      if (a[key] != b[key]) return false;
    }
    return true;
  }

  Future<void> _adoptMyPublishedProfileMeta() async {
    final pid = _profileId;
    final db = _db;
    if (pid == null || pid.isEmpty || db == null) return;
    // Своя правка ещё в пути — чужое значение подождёт.
    if (_myProfileMetaPublishRequested || _myProfileMetaPublishInFlight) return;

    Map<String, Object?>? meta;
    try {
      meta = await db.profileMetaGet(pid);
    } catch (_) {
      return;
    }
    if (meta == null) return;
    final row = meta;

    final prefs = _prefs ?? await SharedPreferences.getInstance();
    _prefs = prefs;
    var changed = false;

    Future<void> adoptString({
      required String field,
      required String? current,
      required String prefsKey,
      required void Function(String? value) apply,
    }) async {
      final published = _trimmedMetaString(row, field);
      final next = (published ?? '').isEmpty ? null : published;
      if (next == current) return;
      apply(next);
      if (next == null) {
        await prefs.remove(prefsKey);
      } else {
        await prefs.setString(prefsKey, next);
      }
      changed = true;
    }

    await adoptString(
      field: 'frame_id',
      current: _myFrameId,
      prefsKey: _prefsMyFrameIdKey,
      apply: (v) => _myFrameId = v,
    );
    await adoptString(
      field: 'cover_id',
      current: _myCoverId,
      prefsKey: _prefsMyCoverIdKey,
      apply: (v) => _myCoverId = v,
    );
    await adoptString(
      field: 'emoji_status',
      current: _myEmojiStatus,
      prefsKey: _prefsMyEmojiStatusKey,
      apply: (v) => _myEmojiStatus = v,
    );
    // Никнейм и описание сервер сливает через COALESCE: пустое значение там
    // означает «мнения нет», а не «пусто». Очищать их по пустому ответу
    // нельзя — принимаем только непустое.
    final publishedNick = _trimmedMetaString(row, 'nickname') ?? '';
    if (publishedNick.isNotEmpty && publishedNick != _myNickname.trim()) {
      _myNickname = publishedNick;
      await prefs.setString(_prefsMyNicknameKey, publishedNick);
      changed = true;
    }
    final publishedBio = _sanitizeProfileBio(
      _trimmedMetaString(row, 'bio') ?? '',
    );
    if (publishedBio.isNotEmpty &&
        publishedBio != _sanitizeProfileBio(_myBio)) {
      _myBio = publishedBio;
      await prefs.setString(_prefsMyBioKey, publishedBio);
      changed = true;
    }

    // 🔴 «КОМУ ЧТО ВИДНО» ТОЖЕ ПРИНИМАЕМ — РЕШЕНИЕ ВЛАДЕЛЬЦА (15.09.2026).
    //
    // Эта карта — настройка ЧЕЛОВЕКА, а не аппарата: «последний вход виден
    // контактам» человек решает про себя, а не про телефон отдельно от
    // компьютера. Пока она не ехала, два устройства одного человека обещали
    // собеседникам разное, и какое из двух обещаний выполнится, зависело от
    // того, с какого устройства последним ушла публикация.
    //
    // Принимаем ровно то, что опубликовано этим же профилем: чужого сюда не
    // попадает, а своё уже прошло тот же путь, что рамка и обложка.
    //
    // Пустая строка — «мнения нет»: карту она не трогает, иначе первый же
    // ответ без поля сбросил бы выбор на заводской.
    final publishedPrivacy = _trimmedMetaString(row, 'privacy_audience_json');
    if (publishedPrivacy != null && publishedPrivacy.isNotEmpty) {
      final next = _parsePrivacyAudienceMap(
        publishedPrivacy,
        fallback: _defaultPrivacyAudience,
      );
      if (!_privacyAudienceMapsEqual(next, _privacyAudience)) {
        _privacyAudience = next;
        // Выбор сделан ЧЕЛОВЕКОМ (пусть и на другом устройстве) — значит
        // этому аппарату больше не нужно бояться затереть чужой: он публикует
        // ровно то, что принял.
        _privacyAudienceChosenHere = true;
        await prefs.setString(
          _prefsPrivacyAudienceMapKey,
          _encodePrivacyAudienceMap(next),
        );
        changed = true;
      }
    }

    if (changed) _changed.add(null);
  }

  Future<void> refreshProfileMeta(String profileId) async {
    await _refreshProfileMetaInternal(profileId);
  }

  void _refreshProfileMetaSoon(String profileId) {
    final pid = profileId.trim();
    if (pid.isEmpty || _transportBlocked) return;
    final nowMs = DateTime.now().millisecondsSinceEpoch;
    final st = _metaRefreshStateByProfileId.putIfAbsent(
      pid,
      () => _MetaRefreshState(),
    );
    if (nowMs < st.nextAttemptAtMs) return;
    st.nextAttemptAtMs = nowMs + 5000;
    unawaited(
      _refreshProfileMetaInternal(pid)
          .then((r) {
            final doneMs = DateTime.now().millisecondsSinceEpoch;
            if (r.ok) {
              st.failCount = 0;
              st.lastSuccessAtMs = doneMs;
              st.nextAttemptAtMs =
                  doneMs + ((r.hasNickname && r.hasAvatar) ? 20000 : 8000);
            } else {
              st.failCount = (st.failCount + 1).clamp(1, 10).toInt();
              st.nextAttemptAtMs = doneMs + _metaBackoffMs(st.failCount);
            }
          })
          .catchError((_) {}),
    );
  }

  Future<_ProfileMetaRefreshResult> _refreshProfileMetaInternal(
    String profileId,
  ) async {
    final keys = _keys;
    final db = _db;
    if (keys == null || db == null) {
      return const _ProfileMetaRefreshResult(
        ok: false,
        hasNickname: false,
        hasAvatar: false,
      );
    }
    if (_transportBlocked) {
      return const _ProfileMetaRefreshResult(
        ok: false,
        hasNickname: false,
        hasAvatar: false,
      );
    }

    try {
      // SEC-07: подписываем запрос, если можем. Сервер отвечает и без подписи —
      // так ходят выпущенные сборки, — но предъявившему её отдаёт точное время
      // присутствия вместо огрублённого до часа.
      final auth = await _buildKeysAuthEnvelope(
        buildMessage:
            ({required requesterDeviceId, required tsMs, required nonceB64}) =>
                AuthSigner.keysProfileMetaGetMessage(
                  requesterDeviceId: requesterDeviceId,
                  profileId: profileId,
                  tsMs: tsMs,
                  nonceB64: nonceB64,
                ),
      );
      final meta = await keys.getProfileMeta(
        profileId,
        requesterDeviceId: auth?.requesterDeviceId,
        tsMs: auth?.tsMs,
        nonceB64: auth?.nonceB64,
        signatureB64: auth?.signatureB64,
      );
      if (!meta.exists) {
        return const _ProfileMetaRefreshResult(
          ok: false,
          hasNickname: false,
          hasAvatar: false,
        );
      }

      final nick = (meta.nickname ?? '').trim();
      final bio = _sanitizeProfileBio(meta.bio ?? '');
      final privacyAudience = _parsePrivacyAudienceMap(
        meta.privacyAudienceJson,
        fallback: _legacyPeerPrivacyAudience,
      );
      final hasNick = nick.isNotEmpty;
      final normalizedNickname = hasNick ? nick : null;
      final normalizedBio = bio.isEmpty ? null : bio;
      final normalizedPrivacyAudienceJson =
          meta.privacyAudienceJson?.trim().isNotEmpty == true
          ? _encodePrivacyAudienceMap(privacyAudience)
          : null;
      // Cosmetic frame/cover from the peer's published profile (source of truth);
      // '' clears, so a peer removing their frame/cover propagates to us.
      final fetchedFrameId = _normalizeCosmeticId(meta.frameId) ?? '';
      final fetchedCoverId = _normalizeCosmeticId(meta.coverId) ?? '';
      final fetchedEmojiStatus = (meta.emojiStatus ?? '').trim();
      final fetchedPremiumBadge = (meta.premiumBadge ?? '').trim();
      final existingMeta = await db.profileMetaGet(profileId);
      final existingUpdatedAtMs =
          (existingMeta?['updated_at_ms'] as num?)?.toInt() ?? 0;
      final existingLastSeenAtMs =
          (existingMeta?['last_seen_at_ms'] as num?)?.toInt() ?? 0;
      final existingAvatarPath = _trimmedMetaString(
        existingMeta,
        'avatar_path',
      );

      // A peer changes published fields only by publishing a NEWER meta (bumped
      // updatedAtMs). A same-or-older fetch arriving WITHOUT a field (a partial
      // or stale server response, or a base64 decode hiccup) must NEVER wipe the
      // good cached value — that was the "photo / frame / cover suddenly
      // disappears" bug. Accept a clear only from a genuinely newer publish;
      // otherwise keep whatever we already have.
      final metaIsNewer = meta.updatedAtMs > existingUpdatedAtMs;
      String resolveField(String fetched, String field) => metaIsNewer
          ? fetched
          : (fetched.isNotEmpty
                ? fetched
                : (_trimmedMetaString(existingMeta, field) ?? ''));
      final resolvedFrameId = resolveField(fetchedFrameId, 'frame_id');
      final resolvedCoverId = resolveField(fetchedCoverId, 'cover_id');
      final resolvedEmojiStatus = resolveField(
        fetchedEmojiStatus,
        'emoji_status',
      );
      final resolvedPremiumBadge = resolveField(
        fetchedPremiumBadge,
        'premium_badge',
      );

      String? avatarPath;
      final avatarB64 = (meta.avatarPngB64 ?? '').trim();
      final hasAvatar = avatarB64.isNotEmpty;
      if (avatarB64.isNotEmpty) {
        try {
          final bytes = base64Decode(avatarB64);
          if (existingUpdatedAtMs == meta.updatedAtMs &&
              existingAvatarPath != null &&
              await File(existingAvatarPath).exists()) {
            avatarPath = existingAvatarPath;
          } else {
            avatarPath = await _cacheProfileMetaAvatar(
              profileId: profileId,
              bytes: bytes,
            );
          }
        } catch (_) {
          // Decode failed → keep the cached photo, don't wipe it.
          avatarPath = existingAvatarPath;
        }
      } else if (existingAvatarPath != null) {
        if (metaIsNewer) {
          // Genuine newer meta with no avatar → the peer removed it.
          try {
            await _pruneCachedProfileMetaAvatars(profileId: profileId);
          } catch (_) {
            // ignore
          }
        } else {
          // Stale/partial fetch missing the avatar → keep the cached photo.
          avatarPath = existingAvatarPath;
        }
      }

      // Custom cover image from the peer (cover_id == 'custom') → cache to a file.
      // '' clears, so a peer removing their cover propagates to us.
      String fetchedCoverPath = '';
      final coverB64 = (meta.coverPngB64 ?? '').trim();
      final existingCoverPath = _trimmedMetaString(existingMeta, 'cover_path');
      if (resolvedCoverId == 'custom' && coverB64.isNotEmpty) {
        try {
          final bytes = base64Decode(coverB64);
          if (bytes.isNotEmpty) {
            if (existingUpdatedAtMs == meta.updatedAtMs &&
                existingCoverPath != null &&
                existingCoverPath.isNotEmpty &&
                await File(existingCoverPath).exists()) {
              fetchedCoverPath = existingCoverPath;
            } else {
              final docs = await getApplicationDocumentsDirectory();
              final f = File(
                '${docs.path}/cover_cache_${profileId}_${meta.updatedAtMs}.png',
              );
              await f.writeAsBytes(bytes, flush: true);
              if (existingCoverPath != null &&
                  existingCoverPath.isNotEmpty &&
                  existingCoverPath != f.path) {
                try {
                  await File(existingCoverPath).delete();
                } catch (_) {}
              }
              fetchedCoverPath = f.path;
            }
          } else {
            // Empty decode → keep the cached cover, don't clear it.
            fetchedCoverPath = existingCoverPath ?? '';
          }
        } catch (_) {
          // Decode failed → keep the cached cover rather than wiping it.
          fetchedCoverPath = existingCoverPath ?? '';
        }
      } else if (existingCoverPath != null && existingCoverPath.isNotEmpty) {
        if (metaIsNewer && resolvedCoverId != 'custom') {
          // Peer genuinely switched away from a custom cover → drop the file.
          try {
            await File(existingCoverPath).delete();
          } catch (_) {}
        } else {
          // Stale/partial fetch (or still custom) → keep the cached cover file.
          fetchedCoverPath = existingCoverPath;
        }
      }

      final metaChanged =
          _trimmedMetaString(existingMeta, 'nickname') != normalizedNickname ||
          _trimmedMetaString(existingMeta, 'bio') != normalizedBio ||
          _trimmedMetaString(existingMeta, 'privacy_audience_json') !=
              normalizedPrivacyAudienceJson ||
          (_trimmedMetaString(existingMeta, 'frame_id') ?? '') !=
              resolvedFrameId ||
          (_trimmedMetaString(existingMeta, 'cover_id') ?? '') !=
              resolvedCoverId ||
          (_trimmedMetaString(existingMeta, 'cover_path') ?? '') !=
              fetchedCoverPath ||
          (_trimmedMetaString(existingMeta, 'emoji_status') ?? '') !=
              resolvedEmojiStatus ||
          (_trimmedMetaString(existingMeta, 'premium_badge') ?? '') !=
              resolvedPremiumBadge ||
          existingAvatarPath != avatarPath ||
          existingUpdatedAtMs != meta.updatedAtMs;
      final shouldUpdateLastSeen =
          meta.lastActiveAtMs > 0 && meta.lastActiveAtMs > existingLastSeenAtMs;

      if (metaChanged) {
        await db.profileMetaUpsert(
          profileId: profileId,
          nickname: normalizedNickname,
          avatarPath: avatarPath,
          bio: normalizedBio,
          privacyAudienceJson: normalizedPrivacyAudienceJson,
          frameId: resolvedFrameId,
          coverId: resolvedCoverId,
          coverPath: fetchedCoverPath,
          emojiStatus: resolvedEmojiStatus,
          premiumBadge: resolvedPremiumBadge,
          updatedAtMs: meta.updatedAtMs,
        );
      }
      if (shouldUpdateLastSeen) {
        await db.profileMetaUpdateLastSeen(
          profileId: profileId,
          lastSeenAtMs: meta.lastActiveAtMs,
        );
      }
      final prefs = _prefs ?? await SharedPreferences.getInstance();
      _prefs = prefs;
      await prefs.setInt(
        _prefsLastMetaRefreshAtMsKey,
        DateTime.now().millisecondsSinceEpoch,
      );
      if (metaChanged || shouldUpdateLastSeen) {
        _changed.add(null);
        _scheduleManagedDeviceContactSync();
      }
      return _ProfileMetaRefreshResult(
        ok: true,
        hasNickname: hasNick,
        hasAvatar: hasAvatar,
      );
    } catch (_) {
      return const _ProfileMetaRefreshResult(
        ok: false,
        hasNickname: false,
        hasAvatar: false,
      );
    }
  }

  /// Last time we said out loud why contact meta is NOT being refreshed.
  ///
  /// This tick is where contact nicknames and AVATARS come from, and it used to
  /// emit nothing at all — so "the desktop shows initials instead of photos"
  /// could not be told apart from "the desktop is fetching them right now",
  /// or from "keys health says no and it has not run once". Throttled hard: the
  /// watchdog calls this every three seconds.
  int _lastMetaRefreshGateLogAtMs = 0;

  Future<void> _metaRefreshTick({
    required bool keysOk,
    required int nowMs,
    int maxFetches = 1,
  }) async {
    if (!keysOk || _transportBlocked) {
      if (nowMs - _lastMetaRefreshGateLogAtMs > 60000) {
        _lastMetaRefreshGateLogAtMs = nowMs;
        DiagLog.event('meta', 'refresh_gated', {
          'keys_ok': keysOk,
          'transport_blocked': _transportBlocked,
        });
      }
      return;
    }
    final db = _db;
    if (db == null) return;
    if (maxFetches < 1) return;

    // Global throttle: collapse repeated refresh bursts while still allowing
    // a small batch of contacts to refresh on each watchdog cycle.
    if (nowMs < _metaRefreshNextFetchAllowedAtMs) return;

    // Rebuild targets periodically (contacts + pending requests).
    if (nowMs >= _metaRefreshTargetsNextRebuildAtMs ||
        _metaRefreshTargets.isEmpty) {
      final toRefresh = <String>{};

      final contactRows = await db.contactsList(limit: 200);
      for (final r in contactRows) {
        final pid = r['contact_profile_id'] as String?;
        if (pid == null || pid.isEmpty) continue;
        toRefresh.add(pid);
      }

      final reqRows = await db.requestsListPending(limit: 200);
      for (final r in reqRows) {
        final pid = r['contact_profile_id'] as String?;
        if (pid == null || pid.isEmpty) continue;
        toRefresh.add(pid);
      }

      // Also refresh peers we have an open 1:1 conversation with, even if the
      // contact/request relationship is missing or stale (e.g. a chat that
      // predates a contact row, or a peer re-bound after a server switch).
      // Without this, a chat peer's name/avatar/frame/cover never auto-fetch.
      try {
        final convoRows = await db.convoList(limit: 300);
        for (final r in convoRows) {
          final cid = ((r['convo_id'] as String?) ?? '').trim();
          if (cid.isEmpty) continue;
          if (cid.startsWith('group:') || cid.startsWith('dev:')) continue;
          toRefresh.add(cid);
        }
      } catch (_) {
        // best-effort
      }

      final next = toRefresh.toList()..sort();
      _metaRefreshTargets = next;
      _metaRefreshTargetCursor = 0;
      // Rebuild frequently so newly added contacts start refreshing quickly.
      _metaRefreshTargetsNextRebuildAtMs = nowMs + 10 * 1000;

      // Prune state for removed targets.
      final keep = toRefresh;
      _metaRefreshStateByProfileId.removeWhere((k, _) => !keep.contains(k));
    }

    if (_metaRefreshTargets.isEmpty) return;

    // Rotate over targets to find the next eligible profiles.
    final count = _metaRefreshTargets.length;
    var fetchedCount = 0;
    for (var i = 0; i < count; i++) {
      final idx = (_metaRefreshTargetCursor + i) % count;
      final pid = _metaRefreshTargets[idx];
      final st = _metaRefreshStateByProfileId.putIfAbsent(
        pid,
        () => _MetaRefreshState(),
      );

      if (nowMs < st.nextAttemptAtMs) continue;

      _metaRefreshTargetCursor = (idx + 1) % count;

      final r = await _refreshProfileMetaInternal(pid);
      fetchedCount++;
      DiagLog.event('meta', 'refreshed', {
        'pid': DiagLog.pfx(pid),
        'ok': r.ok,
        'has_nick': r.hasNickname,
        'has_avatar': r.hasAvatar,
      });

      if (r.ok) {
        st.failCount = 0;
        st.lastSuccessAtMs = nowMs;
        // If meta is incomplete (missing nick or avatar), retry sooner so changes propagate quickly.
        st.nextAttemptAtMs = (r.hasNickname && r.hasAvatar)
            ? (nowMs + 20 * 1000)
            : (nowMs + 8 * 1000);
      } else {
        st.failCount = (st.failCount + 1);
        if (st.failCount < 1) st.failCount = 1;
        if (st.failCount > 10) st.failCount = 10;
        final backoff = _metaBackoffMs(st.failCount);
        st.nextAttemptAtMs = nowMs + backoff;
      }
      if (fetchedCount >= maxFetches) {
        break;
      }
    }

    if (fetchedCount > 0) {
      _metaRefreshNextFetchAllowedAtMs =
          DateTime.now().millisecondsSinceEpoch + 1000;
    }
  }

  int _metaBackoffMs(int failCount) {
    // 15s, 30s, 60s, 120s... capped at 10 minutes.
    final base = 15000;
    final ms = base * (1 << (failCount - 1));
    final capped = ms > (10 * 60 * 1000) ? (10 * 60 * 1000) : ms;
    return capped;
  }

  // ── User-created (custom) chat folders ─────────────────────────────────────
  // Local-only chat-list organization. Never gates or touches messaging.

  Future<void> _loadCustomChatFoldersFromDb() async {
    final db = _db;
    if (db == null) return;
    try {
      final rows = await db.folderListCustom();
      _customChatFolders = rows
          .map(
            (r) => ChatFolder(
              id: (r['id'] as String?) ?? '',
              name: (r['name'] as String?) ?? '',
              emoji: (r['emoji'] as String?),
            ),
          )
          .where((f) => f.id.isNotEmpty)
          .toList(growable: false);
    } catch (_) {
      // Fail-safe: folders are an optional convenience; never block startup.
      _customChatFolders = const [];
    }
  }

  /// Reloads custom folders from the DB and notifies listeners.
  Future<void> _refreshCustomChatFolders() async {
    await _loadCustomChatFoldersFromDb();
    if (!_changed.isClosed) {
      _changed.add(null);
    }
  }

  /// Creates a custom folder containing [convoIds]. Returns the new folder id
  /// (empty string if the DB is unavailable).
  Future<String> createChatFolder({
    required String name,
    String? emoji,
    required List<String> convoIds,
  }) async {
    final db = _db;
    if (db == null) return '';
    final id = _uuid.v4();
    final trimmedEmoji = emoji?.trim();
    await db.folderUpsert(
      id: id,
      name: name.trim(),
      emoji: (trimmedEmoji == null || trimmedEmoji.isEmpty)
          ? null
          : trimmedEmoji,
      position: _customChatFolders.length,
    );
    await db.folderSetMembers(folderId: id, convoIds: convoIds);
    await _refreshCustomChatFolders();
    unawaited(
      _mirrorFolderToOwnDevices(
        folderId: id,
        name: name.trim(),
        emoji: (trimmedEmoji == null || trimmedEmoji.isEmpty)
            ? null
            : trimmedEmoji,
        position: _customChatFolders.length,
        convoIds: convoIds,
      ),
    );
    return id;
  }

  /// Updates an existing custom folder's name/emoji and membership set.
  Future<void> updateChatFolder({
    required String id,
    required String name,
    String? emoji,
    required List<String> convoIds,
  }) async {
    final db = _db;
    if (db == null) return;
    // Preserve the folder's existing position.
    final existingIndex = _customChatFolders.indexWhere((f) => f.id == id);
    final position = existingIndex >= 0
        ? existingIndex
        : _customChatFolders.length;
    final trimmedEmoji = emoji?.trim();
    await db.folderUpsert(
      id: id,
      name: name.trim(),
      emoji: (trimmedEmoji == null || trimmedEmoji.isEmpty)
          ? null
          : trimmedEmoji,
      position: position,
    );
    await db.folderSetMembers(folderId: id, convoIds: convoIds);
    await _refreshCustomChatFolders();
    unawaited(
      _mirrorFolderToOwnDevices(
        folderId: id,
        name: name.trim(),
        emoji: (trimmedEmoji == null || trimmedEmoji.isEmpty)
            ? null
            : trimmedEmoji,
        position: position,
        convoIds: convoIds,
      ),
    );
  }

  /// Deletes a custom folder (and its membership rows).
  Future<void> deleteChatFolder(String id) async {
    final db = _db;
    if (db == null) return;
    await db.folderDelete(id);
    await _refreshCustomChatFolders();
    unawaited(_mirrorFolderToOwnDevices(folderId: id, deleted: true));
  }

  /// Returns the convo ids that belong to a custom folder (for the UI filter).
  Future<List<String>> folderMemberConvoIds(String id) async {
    final db = _db;
    if (db == null) return const [];
    try {
      return await db.folderMemberConvoIds(id);
    } catch (_) {
      return const [];
    }
  }

  /// The conversation for [convoId] IF it is already in memory — synchronously,
  /// with no await.
  ///
  /// 🔴 WHY (2026-08-01, field: "opening a chat flashes the avatar in a moment
  /// later, as if a web page were reloading"). The header already had this data:
  /// the chats list rendered the very same avatar a frame earlier and left it in
  /// [_listConversationsCache]. But [listConversations] is `async`, so even a
  /// pure cache HIT resolves on a later microtask — and a `FutureBuilder` must
  /// therefore paint one frame with `data == null`. That empty frame is the
  /// flash. The data was never missing; only the synchronous door was.
  ///
  /// Used as `initialData`, so the async refresh still runs and still wins. Its
  /// TTL is deliberately NOT applied: for painting a header, a slightly stale
  /// avatar is indistinguishable to the eye and is corrected within a frame or
  /// two, whereas withholding it is exactly the defect being fixed. Failure
  /// direction is "show the last known face", never "show nothing".
  ///
  /// Returns null when nothing is cached yet (cold start) — callers must keep
  /// handling that, and the FutureBuilder does.
  /// Последний известный список бесед, без обращения к базе. `null`, пока
  /// ничего не загружено (холодный старт) или сразу после сброса кэша.
  ///
  /// Нужен как `initialData` для `FutureBuilder`. Причина та же, что у
  /// [cachedConversation] ниже: `listConversations` — асинхронный метод, и
  /// даже попадание в кэш разрешается на следующей микрозадаче, поэтому
  /// `FutureBuilder` обязан нарисовать один кадр с `data == null`. Для
  /// значков непрочитанного в панели навигации это означает, что при каждой
  /// смене версии значок на кадр ГАСНЕТ и загорается снова.
  ///
  /// Отдаётся неизменяемый ВИД, а не копия: геттер зовётся из `build()`, и при
  /// двух сотнях бесед копирование на каждой перестройке было бы заметным
  /// мусором на ровном месте. Обёртка стоит O(1) и защищает кэш от правок
  /// вызывающим.
  ///
  /// TTL здесь намеренно НЕ проверяется: показать чуть устаревшее число лучше,
  /// чем не показать ничего, а свежее значение приходит кадром позже. Провал
  /// направлен в «показать последнее известное», никогда — в «показать пусто».
  List<Conversation>? get cachedConversations {
    final cached = _listConversationsCache;
    if (cached == null) return null;
    return UnmodifiableListView<Conversation>(cached);
  }

  Conversation? cachedConversation(String convoId) {
    final id = convoId.trim();
    if (id.isEmpty) return null;
    final cached = _listConversationsCache;
    if (cached == null) return null;
    for (final c in cached) {
      if (c.convoId == id) return c;
    }
    return null;
  }

  Future<List<Conversation>> listConversations() async {
    final nowMs = DateTime.now().millisecondsSinceEpoch;
    final cached = _listConversationsCache;
    if (cached != null &&
        (nowMs - _listConversationsCacheAtMs) <= _listConversationsCacheTtlMs) {
      return cached;
    }
    final inFlight = _listConversationsInFlight;
    if (inFlight != null) {
      return inFlight;
    }
    final future = _loadConversationsFromDb();
    _listConversationsInFlight = future;
    try {
      final conversations = await future;
      _listConversationsCache = conversations;
      _listConversationsCacheAtMs = DateTime.now().millisecondsSinceEpoch;
      return conversations;
    } finally {
      _listConversationsInFlight = null;
    }
  }

  /// Сколько бесед показывать в списке.
  ///
  /// 🔴 ПОЧЕМУ БОЛЬШЕ ПРЕЖНИХ ДВУХСОТ. Двести первая беседа просто не
  /// появлялась в перечне: данные на месте и чат открывался по ссылке, но
  /// найти его в списке было нельзя. Сортировка ставит первыми
  /// неархивированные и закреплённые, поэтому выпадали самые старые по времени
  /// последнего события.
  ///
  /// Поднято, а не сделано постранично, намеренно: постраничная загрузка
  /// требует трогать сортировку, а она построена на выражениях `CASE WHEN` и
  /// ни одним индексом не покрыта — правка там ломает порядок закреплённых и
  /// архивных, что заметно глазу сразу. Тысяча строк `conversations` для
  /// SQLite — единицы миллисекунд, а перечень такой длины человек всё равно не
  /// пролистывает: для этого есть поиск.
  static const int _convoListRenderLimit = 1000;

  /// Сколько бесед обходить в фоновом обслуживании.
  ///
  /// Заведомо больше отображаемого предела: обслуживание отвечает за
  /// автоудаление, и пропустить беседу здесь значит не выполнить обещание из
  /// настроек приватности, а не просто не показать строку.
  static const int _convoMaintenanceScanLimit = 100000;

  Future<List<Conversation>> _loadConversationsFromDb() async {
    final db = _db;
    if (db == null) return const [];

    // Retention sweep + request auto-accept are time-based maintenance; running
    // them on every list render (each doing a DB round-trip per conversation)
    // is what made the first cold-start load take ~2s. Run them at most once a
    // minute, in the BACKGROUND, and refresh the list when they finish. The
    // render below uses whatever is already in the DB, so it appears instantly.
    final maintenanceNowMs = DateTime.now().millisecondsSinceEpoch;
    if (maintenanceNowMs - _lastConvoMaintenanceAtMs > 60000) {
      _lastConvoMaintenanceAtMs = maintenanceNowMs;
      unawaited(_runConversationMaintenance(db));
    }

    final rows = await db.convoList(limit: _convoListRenderLimit);
    final convoIds = <String>[];
    final peerProfileIds = <String>{};
    for (final r in rows) {
      final kind = r['kind'] as String?;
      if (kind != '1to1' && kind != 'request' && kind != 'group') continue;
      final convoId = r['convo_id'] as String;
      convoIds.add(convoId);
      if (kind != 'group') {
        final peerProfileId = r['peer_profile_id'] as String?;
        final pid = (peerProfileId != null && peerProfileId.isNotEmpty)
            ? peerProfileId
            : (convoId.startsWith('req:') ? convoId.substring(4) : convoId);
        if (pid.isNotEmpty) {
          peerProfileIds.add(pid);
        }
      }
    }
    final unreadByConvo = await db.countUnreadForConvos(
      convoIds: convoIds,
      selfDeviceId: deviceId,
      excludedSenderDeviceIds: _ownDeviceIdsForUnreadQueries(),
    );
    final sortedPeerProfileIds = peerProfileIds.toList(growable: false)..sort();
    final contactsByProfileId = await db.contactsGetForProfiles(
      sortedPeerProfileIds,
    );
    final profileMetaByProfileId = await db.profileMetaGetForProfiles(
      sortedPeerProfileIds,
    );
    final lastSeenByProfileId = await db.profileMetaGetLastSeenForProfiles(
      sortedPeerProfileIds,
    );
    final groupConvoIds =
        rows
            .where((row) => (row['kind'] as String?) == 'group')
            .map((row) => row['convo_id'] as String?)
            .whereType<String>()
            .toSet()
            .toList(growable: false)
          ..sort();
    final groupSettingsByGroupId = await db.groupSettingsGetForGroups(
      groupConvoIds,
    );
    final out = <Conversation>[];
    for (final r in rows) {
      final kind = r['kind'] as String?;
      if (kind != '1to1' && kind != 'request' && kind != 'group') continue;
      final convoId = r['convo_id'] as String;
      final peerProfileId = r['peer_profile_id'] as String?;
      final lastAtMs = (r['last_event_at_ms'] as num).toInt();
      final pinnedAt = (r['pinned_at_ms'] as num?)?.toInt();
      final muted = ((r['muted'] as num?)?.toInt() ?? 0) != 0;
      final archivedAt = (r['archived_at_ms'] as num?)?.toInt();
      final autoDeleteSeconds = (r['auto_delete_seconds'] as num?)?.toInt();
      final pid = (kind == 'group')
          ? ''
          : (peerProfileId != null && peerProfileId.isNotEmpty)
          ? peerProfileId
          : (convoId.startsWith('req:') ? convoId.substring(4) : convoId);

      String title = kind == 'group'
          ? ((r['title'] as String?) ?? convoId)
          : pid;
      String? avatarPath;
      String? contactEmoji;
      Map<String, Object?>? contactRow;
      Map<String, Object?>? metaRow;
      if (pid.isNotEmpty) {
        contactRow = contactsByProfileId[pid];
        contactEmoji = contactRow?['contact_emoji'] as String?;
        metaRow = profileMetaByProfileId[pid];
        final resolvedTitle = _resolvedContactDisplayName(
          contactRow: contactRow,
          metaRow: metaRow,
          preferLocalName: isSavedMessagesConvo(convoId),
        );

        if (resolvedTitle != null && resolvedTitle.isNotEmpty) {
          title = resolvedTitle;
        }

        avatarPath = _visiblePeerAvatarPath(
          contactRow: contactRow,
          metaRow: metaRow,
        );
        // «Избранное» — переписка с самим собой, и себя в контактах нет.
        // Поэтому общий разрешатель отбрасывает своё же фото по собственной
        // настройке «видно контактам»: настройка про чужих, а не про меня.
        if (avatarPath == null && pid == (_profileId ?? '').trim()) {
          avatarPath = await _pairedDeviceOwnAvatarPath();
        }
        if ((resolvedTitle == null ||
                resolvedTitle.isEmpty ||
                avatarPath == null) &&
            _keys != null &&
            !_transportBlocked) {
          _refreshProfileMetaSoon(pid);
        }
      } else if (kind == 'group') {
        final groupSettings = groupSettingsByGroupId[convoId];
        final groupAvatar = (groupSettings?['avatar_path'] as String?)?.trim();
        // Существование файла проверяем, а не верим строке: мёртвый путь — это
        // сломанная картинка вместо честных инициалов.
        avatarPath = _existingAvatarFilePath(groupAvatar);
        if (avatarPath == null) {
          final hash = (groupSettings?['avatar_hash'] as String?)?.trim();
          if (hash != null && hash.isNotEmpty) _refreshRoomAvatarSoon(convoId);
        }
      }
      final unread = unreadByConvo[convoId] ?? 0;
      final peerLastSeen = pid.isNotEmpty
          ? _visiblePeerLastSeenAtMs(
              contactRow: contactRow,
              metaRow: metaRow,
              lastSeenAtMs: lastSeenByProfileId[pid],
            )
          : null;
      final peerHasBadge =
          pid.isNotEmpty &&
          (_trimmedMetaString(metaRow, 'premium_badge') ?? '').isNotEmpty;
      out.add(
        Conversation(
          convoId: convoId,
          peerProfileId: peerProfileId,
          title: title,
          avatarPath: avatarPath,
          lastEventAtMs: lastAtMs,
          pinnedAtMs: pinnedAt,
          muted: muted,
          archivedAtMs: archivedAt,
          autoDeleteSeconds: autoDeleteSeconds,
          emoji: contactEmoji,
          unreadCount: unread,
          peerLastSeenAtMs: peerLastSeen,
          frameId: pid.isNotEmpty
              ? _gatedPeerCosmetic(
                  _trimmedMetaString(metaRow, 'frame_id'),
                  peerHasBadge: peerHasBadge,
                  kind: CosmeticKind.avatarFrame,
                )
              : null,
          coverId: pid.isNotEmpty
              ? _gatedPeerCosmetic(
                  _trimmedMetaString(metaRow, 'cover_id'),
                  peerHasBadge: peerHasBadge,
                  kind: CosmeticKind.profileCover,
                )
              : null,
          emojiStatus: pid.isNotEmpty
              ? _gatedPeerCosmetic(
                  _trimmedMetaString(metaRow, 'emoji_status'),
                  peerHasBadge: peerHasBadge,
                )
              : null,
          premiumBadge: peerHasBadge,
        ),
      );
    }
    return out;
  }

  Future<List<CallJournalEntry>> listCallJournalEntries({
    String? convoId,
    int limit = 100,
  }) async {
    final db = _db;
    if (db == null) return const [];
    final rows = await db.callJournalList(convoId: convoId, limit: limit);
    return rows
        .map(CallJournalEntry.fromDbRow)
        .where((entry) => entry.callId.isNotEmpty)
        .toList(growable: false);
  }

  Future<int> missedCallCount({String? convoId, int limit = 200}) async {
    final entries = await listCallJournalEntries(
      convoId: convoId,
      limit: limit,
    );
    return entries
        .where(
          (entry) =>
              entry.result == CallRecordResult.missed && !entry.isAcknowledged,
        )
        .length;
  }

  Future<Map<String, int>> missedCallCountsByConvoIds(
    Iterable<String> convoIds, {
    int limit = 400,
  }) async {
    final wanted = convoIds
        .map((id) => id.trim())
        .where((id) => id.isNotEmpty)
        .toSet();
    if (wanted.isEmpty) return const <String, int>{};
    final entries = await listCallJournalEntries(limit: limit);
    final out = <String, int>{};
    for (final entry in entries) {
      if (entry.result != CallRecordResult.missed || entry.isAcknowledged) {
        continue;
      }
      if (!wanted.contains(entry.convoId)) continue;
      out.update(entry.convoId, (value) => value + 1, ifAbsent: () => 1);
    }
    return out;
  }

  Future<void> acknowledgeMissedCalls({String? convoId}) async {
    final db = _db;
    if (db == null) return;
    await db.callJournalMarkMissedAcknowledged(convoId: convoId);
    _changed.add(null);
  }

  Future<String> createGroup({
    required String title,
    required List<String> memberProfileIds,
    int? autoDeleteSeconds,
  }) async {
    final db = _db;
    if (db == null) throw StateError('Database is not ready');
    final selfProfileId = profileId;
    if (selfProfileId.isEmpty) {
      throw StateError('Profile is not ready');
    }
    // Monetization §C-3: cap the number of groups a Free profile may OWN.
    // Inert while monetization is disabled (limit = unlimited). Existing groups
    // are never affected — only NEW creation past the cap is blocked.
    final ownedGroups = await db.groupOwnedCount(selfProfileId);
    if (!FeatureGate.canCreateGroup(entitlementStateNow, ownedGroups)) {
      throw const FeatureLockedException(
        GatedFeature.group,
        'group_create_limit',
      );
    }
    final cleanedTitle = title.trim().isEmpty ? 'Group' : title.trim();
    final groupId = 'group:${_uuid.v4().substring(0, 12)}';
    final members = memberProfileIds
        .map((m) => m.trim())
        .where((m) => m.isNotEmpty)
        .toSet()
        .toList(growable: true);
    if (!members.contains(selfProfileId)) {
      members.add(selfProfileId);
    }
    final now = DateTime.now().millisecondsSinceEpoch;

    if (_useAuthoritativeRoomRelay) {
      final relay = _relay!;
      try {
        final createResult = await relay.createRoom(
          roomId: groupId,
          title: cleanedTitle,
        );
        for (final memberId in members) {
          if (memberId == selfProfileId) continue;
          await relay.upsertRoomMembership(
            roomId: groupId,
            profileId: memberId,
            status: RoomMembershipStatus.active.value,
            role: RoomMemberRole.member.value,
          );
        }
        await _applyRelayRoomSnapshot(
          room: createResult.room,
          memberships: members
              .map(
                (memberId) => RelayRoomMembership(
                  roomId: groupId,
                  profileId: memberId,
                  status: RoomMembershipStatus.active.value,
                  role: memberId == selfProfileId
                      ? RoomMemberRole.owner.value
                      : RoomMemberRole.member.value,
                  sourceLinkId: null,
                  tag: null,
                  createdAtMs: createResult.room.createdAtMs > 0
                      ? createResult.room.createdAtMs
                      : now,
                  updatedAtMs: createResult.room.updatedAtMs > 0
                      ? createResult.room.updatedAtMs
                      : now,
                ),
              )
              .toList(growable: false),
          forceAuthoritative: true,
        );
        await _tryRefreshRoomFromRelayBestEffort(groupId);
        await _tryRefreshRoomFromRelayBestEffort(
          groupId,
          includeInviteLinks: true,
        );
      } catch (error) {
        await _tryRefreshRoomFromRelayBestEffort(
          groupId,
          includeInviteLinks: true,
        );
        throw StateError('Authoritative room create failed: $error');
      }
      if (autoDeleteSeconds != null) {
        await db.convoSetAutoDeleteSeconds(
          convoId: groupId,
          autoDeleteSeconds: autoDeleteSeconds,
        );
        await _applyAutoDeleteRetentionForConvo(groupId);
      }
      _changed.add(null);
      await _broadcastAuthoritativeRoomSyncHint(
        groupId,
        skipProfileId: selfProfileId,
      );
      return groupId;
    }

    _throwIfRoomMutationAuthoritativeRelayUnavailable();

    await db.convoEnsureGroup(groupId: groupId, title: cleanedTitle);
    await db.groupMembershipStatesReplace(
      groupId: groupId,
      states: members
          .map(
            (memberId) => (
              profileId: memberId,
              status: RoomMembershipStatus.active.value,
              role: memberId == selfProfileId
                  ? RoomMemberRole.admin.value
                  : RoomMemberRole.member.value,
              sourceLinkId: null,
              tag: null,
              createdAtMs: now,
              updatedAtMs: now,
            ),
          )
          .toList(growable: false),
    );
    await db.groupAdminsReplace(groupId: groupId, profileIds: [selfProfileId]);
    await _persistRoomSettingsRecord(
      db: db,
      groupId: groupId,
      settings: RoomSettings.defaults(
        ownerProfileId: selfProfileId,
        membershipVersion: 1,
        stateVersion: 1,
      ),
    );
    final primaryLinkSlug = _uuid.v4().replaceAll('-', '').substring(0, 16);
    await db.groupInviteLinkUpsert(
      linkId: _uuid.v4(),
      groupId: groupId,
      slug: primaryLinkSlug,
      createdByProfileId: selfProfileId,
      createdAtMs: now,
      updatedAtMs: now,
      expiresAtMs: null,
      maxUses: null,
      useCount: 0,
      requiresApproval: false,
      allowedRole: RoomMemberRole.member.value,
      revoked: false,
    );
    if (autoDeleteSeconds != null) {
      await db.convoSetAutoDeleteSeconds(
        convoId: groupId,
        autoDeleteSeconds: autoDeleteSeconds,
      );
      await _applyAutoDeleteRetentionForConvo(groupId);
    }
    _changed.add(null);
    await _broadcastRoomSnapshotToMembers(
      groupId,
      skipProfileId: selfProfileId,
    );
    return groupId;
  }

  Future<List<String>> listGroupMembers(String groupId) async {
    final states = await listRoomMembershipStates(
      groupId,
      statuses: <RoomMembershipStatus>{RoomMembershipStatus.active},
    );
    return states
        .map((state) => state.profileId)
        .where((memberId) => memberId.isNotEmpty)
        .toList(growable: false);
  }

  Future<RoomSettings> getRoomSettings(String groupId) async {
    final db = _db;
    final ownerId = profileId;
    if (db == null || ownerId.isEmpty) {
      return RoomSettings.defaults(ownerProfileId: ownerId);
    }

    final existing = await db.groupSettingsGet(groupId);
    if (existing == null) {
      final defaults = RoomSettings.defaults(ownerProfileId: ownerId);
      await _persistRoomSettingsRecord(
        db: db,
        groupId: groupId,
        settings: defaults,
      );
      return defaults;
    }

    return RoomSettings(
      ownerProfileId: (existing['owner_profile_id'] as String?) ?? ownerId,
      avatarPath: existing['avatar_path'] as String?,
      avatarHash: existing['avatar_hash'] as String?,
      pinnedMessageEventId: (existing['pinned_message_event_id'] as String?)
          ?.trim(),
      coverId: (existing['cover_id'] as String?)?.trim(),
      frameId: (existing['frame_id'] as String?)?.trim(),
      nameEmoji: (existing['name_emoji'] as String?)?.trim(),
      description: existing['description'] as String?,
      reactionsMode: RoomReactionsModeX.fromValue(
        (existing['reactions_mode'] as String?) ?? RoomReactionsMode.all.value,
      ),
      allowTextMessages: ((existing['allow_text'] as num?)?.toInt() ?? 1) != 0,
      allowMedia: ((existing['allow_media'] as num?)?.toInt() ?? 1) != 0,
      allowAddMembers:
          ((existing['allow_add_members'] as num?)?.toInt() ?? 1) != 0,
      allowPinMessages:
          ((existing['allow_pin_messages'] as num?)?.toInt() ?? 1) != 0,
      allowChangeGroupInfo:
          ((existing['allow_change_group_info'] as num?)?.toInt() ?? 1) != 0,
      allowChangeTag:
          ((existing['allow_change_tag'] as num?)?.toInt() ?? 0) != 0,
      joinApprovalRequired:
          ((existing['join_approval_required'] as num?)?.toInt() ?? 0) != 0,
      slowModeSeconds: (existing['slow_mode_seconds'] as num?)?.toInt() ?? 0,
      chatHistoryVisible:
          ((existing['chat_history_visible'] as num?)?.toInt() ?? 0) != 0,
      membershipVersion: (existing['membership_version'] as num?)?.toInt() ?? 0,
      stateVersion: (existing['state_version'] as num?)?.toInt() ?? 0,
    );
  }

  RoomInviteLink _roomInviteLinkFromRelay(RelayRoomInviteLink link) {
    return RoomInviteLink(
      linkId: link.linkId,
      groupId: link.roomId,
      slug: link.slug,
      createdByProfileId: link.createdByProfileId,
      expiresAtMs: _normalizeRoomInviteExpiresAtMs(link.expiresAtMs),
      maxUses: _normalizeRoomInviteMaxUses(link.maxUses),
      useCount: link.useCount < 0 ? 0 : link.useCount,
      requiresApproval: link.requiresApproval,
      allowedRole: _normalizeRoomInviteAllowedRole(
        RoomMemberRoleX.fromValue(link.allowedRole),
      ),
      revoked: link.revoked,
      createdAtMs: link.createdAtMs,
      updatedAtMs: link.updatedAtMs,
    );
  }

  Future<Map<String, Object?>> _buildRelayRoomSnapshotPayload({
    required RelayRoom room,
    required List<RelayRoomMembership> memberships,
    List<RelayRoomInviteLink>? inviteLinks,
  }) async {
    final normalizedMemberships = memberships
        .where((membership) => membership.profileId.trim().isNotEmpty)
        .toList(growable: false);
    final activeMemberships = normalizedMemberships
        .where(
          (membership) =>
              RoomMembershipStatusX.fromValue(membership.status) ==
              RoomMembershipStatus.active,
        )
        .toList(growable: false);
    final memberProfileIds = activeMemberships
        .map((membership) => membership.profileId)
        .toSet()
        .toList(growable: false);
    final adminProfileIds = activeMemberships
        .where(
          (membership) =>
              RoomMemberRoleX.fromValue(membership.role) ==
                  RoomMemberRole.owner ||
              RoomMemberRoleX.fromValue(membership.role) ==
                  RoomMemberRole.admin,
        )
        .map((membership) => membership.profileId)
        .toSet()
        .toList(growable: false);
    final payload = <String, Object?>{
      'v': 1,
      'action': 'snapshot',
      'groupId': room.roomId,
      'groupTitle': room.title.trim().isEmpty ? 'Room' : room.title.trim(),
      'avatarHash': room.avatarHash,
      'avatarImageB64': room.avatarImageB64,
      'description': room.description,
      'ownerProfileId': room.ownerProfileId,
      'reactionsMode': room.reactionsMode,
      'allowTextMessages': room.allowText,
      'allowMedia': room.allowMedia,
      'allowAddMembers': room.allowAddMembers,
      'allowPinMessages': room.allowPinMessages,
      'allowChangeGroupInfo': room.allowChangeGroupInfo,
      'allowChangeTag': room.allowChangeTag,
      'joinApprovalRequired': room.joinApprovalRequired,
      'slowModeSeconds': room.slowModeSeconds,
      'chatHistoryVisible': room.chatHistoryVisible,
      'pinnedMessageEventId': room.pinnedMessageId,
      'membershipVersion': room.membershipVersion > 0
          ? room.membershipVersion
          : (normalizedMemberships.isNotEmpty ? 1 : 0),
      'stateVersion': room.version > 0 ? room.version : 1,
      'memberProfileIds': memberProfileIds,
      'adminProfileIds': adminProfileIds,
      'membershipStates': normalizedMemberships
          .map(
            (membership) => <String, Object?>{
              'profileId': membership.profileId,
              'status': RoomMembershipStatusX.fromValue(
                membership.status,
              ).value,
              'role': membership.role.trim().isEmpty
                  ? RoomMemberRole.member.value
                  : membership.role.trim(),
              'sourceLinkId': membership.sourceLinkId,
              'tag': membership.tag,
              'createdAtMs': membership.createdAtMs,
              'updatedAtMs': membership.updatedAtMs,
            },
          )
          .toList(growable: false),
    };
    if (inviteLinks != null) {
      payload['inviteLinks'] = inviteLinks
          .map(_roomInviteLinkFromRelay)
          .map(
            (link) => <String, Object?>{
              'linkId': link.linkId,
              'groupId': link.groupId,
              'slug': link.slug,
              'createdByProfileId': link.createdByProfileId,
              'expiresAtMs': link.expiresAtMs,
              'maxUses': link.maxUses,
              'useCount': link.useCount,
              'requiresApproval': link.requiresApproval,
              'allowedRole': link.allowedRole.value,
              'revoked': link.revoked,
              'createdAtMs': link.createdAtMs,
              'updatedAtMs': link.updatedAtMs,
            },
          )
          .toList(growable: false);
    }
    return payload;
  }

  Future<void> _applyRelayRoomSnapshot({
    required RelayRoom room,
    required List<RelayRoomMembership> memberships,
    List<RelayRoomInviteLink>? inviteLinks,
    bool forceAuthoritative = false,
  }) async {
    final db = _db;
    if (db == null) return;
    final payload = await _buildRelayRoomSnapshotPayload(
      room: room,
      memberships: memberships,
      inviteLinks: inviteLinks,
    );
    await _applyRoomSnapshotPayload(
      db: db,
      payload: payload,
      forceAuthoritative: forceAuthoritative,
    );
  }

  Future<void> _refreshRoomFromRelay(
    String groupId, {
    bool includeInviteLinks = false,
    bool forceAuthoritative = false,
  }) async {
    final relay = _relay;
    if (relay == null) {
      throw StateError('Relay runtime is not ready');
    }
    final membersSnapshot = await relay.listRoomMembers(roomId: groupId);
    List<RelayRoomInviteLink>? inviteLinks;
    if (includeInviteLinks) {
      final inviteSnapshot = await relay.listRoomInviteLinks(roomId: groupId);
      inviteLinks = inviteSnapshot.inviteLinks;
    }
    await _applyRelayRoomSnapshot(
      room: membersSnapshot.room,
      memberships: membersSnapshot.members,
      inviteLinks: inviteLinks,
      forceAuthoritative: forceAuthoritative,
    );
  }

  /// Когда в следующий раз позволено спрашивать у реле фотографию комнаты.
  final Map<String, int> _roomAvatarRefreshNextAtMs = <String, int>{};

  /// Фотография комнаты есть в состоянии, а файла на диске нет.
  ///
  /// 🔴 ПОЧЕМУ ЭТО ОТДЕЛЬНЫЙ ПУТЬ (13.09.2026, поле: «у комнат нет фото»).
  ///
  /// Фотографии комнат живут в `room_avatars/` и в копию НЕ едут (в отличие от
  /// аватаров профилей). Связанный по QR компьютер получает строки — имя,
  /// хэш, версию — и не получает ни одного байта картинки. Хэш при этом
  /// совпадает, поэтому обычная синхронизация состояния считает, что всё на
  /// месте, и картинку не перезапрашивает.
  ///
  /// Реле хранит саму картинку рядом с состоянием комнаты, и обычный снимок её
  /// приносит. Значит лечится это ровно одним: увидели хэш без файла —
  /// спросили у реле. Повторяем не чаще раза в минуту, а если снимок фотографию
  /// не принёс (у комнаты её может и не быть) — раз в полчаса.
  void _refreshRoomAvatarSoon(String groupId) {
    final gid = groupId.trim();
    if (gid.isEmpty || _transportBlocked || _relay == null) return;
    final nowMs = DateTime.now().millisecondsSinceEpoch;
    if (nowMs < (_roomAvatarRefreshNextAtMs[gid] ?? 0)) return;
    _roomAvatarRefreshNextAtMs[gid] = nowMs + 60 * 1000;
    unawaited(() async {
      await _tryRefreshRoomFromRelayBestEffort(gid);
      final db = _db;
      if (db == null) return;
      final settings = await db.groupSettingsGet(gid);
      final path = _existingAvatarFilePath(
        (settings?['avatar_path'] as String?)?.trim(),
      );
      if (path == null) {
        // Картинки у реле нет — незачем спрашивать каждую минуту.
        _roomAvatarRefreshNextAtMs[gid] =
            DateTime.now().millisecondsSinceEpoch + 30 * 60 * 1000;
        return;
      }
      _listConversationsCache = null;
      _changed.add(null);
    }());
  }

  Future<void> _tryRefreshRoomFromRelayBestEffort(
    String groupId, {
    bool includeInviteLinks = false,
    bool forceAuthoritative = false,
  }) async {
    final relay = _relay;
    if (relay == null || _transportBlocked) return;
    try {
      await _refreshRoomFromRelay(
        groupId,
        includeInviteLinks: includeInviteLinks,
        forceAuthoritative: forceAuthoritative,
      );
    } catch (_) {
      // ignore
    }
  }

  Future<List<RelayRoomMembership>> _relayRoomMembershipsFromLocalState(
    String groupId, {
    Iterable<RelayRoomMembership> overrides = const <RelayRoomMembership>[],
  }) async {
    final membershipsByProfileId = <String, RelayRoomMembership>{};
    final localStates = await listRoomMembershipStates(groupId);
    for (final state in localStates) {
      final profileId = state.profileId.trim();
      if (profileId.isEmpty) continue;
      membershipsByProfileId[profileId] = RelayRoomMembership(
        roomId: groupId,
        profileId: profileId,
        status: state.status,
        role: state.role.trim().isEmpty
            ? RoomMemberRole.member.value
            : state.role.trim(),
        sourceLinkId: state.sourceLinkId,
        tag: state.tag,
        createdAtMs: state.createdAtMs,
        updatedAtMs: state.updatedAtMs,
      );
    }
    for (final membership in overrides) {
      final profileId = membership.profileId.trim();
      if (profileId.isEmpty) continue;
      membershipsByProfileId[profileId] = membership;
    }
    return membershipsByProfileId.values.toList(growable: false);
  }

  Future<void> _applyRelayRoomStateWithLocalMemberships(
    RelayRoom room, {
    Iterable<RelayRoomMembership> membershipOverrides =
        const <RelayRoomMembership>[],
    bool forceAuthoritative = false,
  }) async {
    final memberships = await _relayRoomMembershipsFromLocalState(
      room.roomId,
      overrides: membershipOverrides,
    );
    if (memberships.isEmpty) return;
    await _applyRelayRoomSnapshot(
      room: room,
      memberships: memberships,
      forceAuthoritative: forceAuthoritative,
    );
  }

  Future<void> _reconcileKnownRoomFromRelayBestEffort(
    String groupId, {
    Map<String, Object?>? localSettingsRow,
    bool includeInviteLinks = false,
  }) async {
    final relay = _relay;
    if (relay == null || _transportBlocked) return;
    try {
      final room = await relay.getRoom(roomId: groupId);
      final plan = planRoomRelayResync(
        hasLocalRoomState: localSettingsRow != null,
        localStateVersion:
            (localSettingsRow?['state_version'] as num?)?.toInt() ?? 0,
        localMembershipVersion:
            (localSettingsRow?['membership_version'] as num?)?.toInt() ?? 0,
        remoteStateVersion: room.version,
        remoteMembershipVersion: room.membershipVersion,
      );
      if (!plan.shouldRefresh) {
        return;
      }
      if (plan.refreshMemberships || includeInviteLinks) {
        await _refreshRoomFromRelay(
          groupId,
          includeInviteLinks: includeInviteLinks,
          forceAuthoritative: plan.forceAuthoritative,
        );
        return;
      }
      await _applyRelayRoomStateWithLocalMemberships(
        room,
        forceAuthoritative: plan.forceAuthoritative,
      );
    } catch (_) {
      // ignore
    }
  }

  // A1: last-successful authoritative-membership reconcile per room, triggered
  // when an inbound group message arrives from a sender missing from the local
  // roster. Rate-limits the relay fetch so a burst reconciles at most once.
  final Map<String, int> _roomStaleSenderResyncAtMs = <String, int>{};
  static const int _roomStaleSenderResyncCooldownMs = 30 * 1000;

  /// A1: an inbound group message arrived from [senderProfile], who is absent
  /// from our local roster for [groupId]. With durable membership snapshots (A5)
  /// and the relay's FIFO mailbox the add-snapshot almost always precedes the
  /// sender's first message, so this is a rare reorder race. Reconcile the
  /// room's AUTHORITATIVE membership from the relay (rate-limited per room) and
  /// return whether the sender is a genuine member afterwards.
  ///
  /// The caller must decide correctly HERE: an already-decrypted frame can't be
  /// replayed if dropped (its ratchet key is consumed), so quarantining is not
  /// an option. Returning true means "the relay confirms this sender is a member
  /// — apply the frame"; false means "genuinely not a member — drop".
  Future<bool> _senderIsRoomMemberAfterRelayReconcile(
    String groupId,
    String senderProfile,
    Map<String, Object?>? settingsRow,
  ) async {
    final db = _db;
    if (db == null) return false;
    final now = DateTime.now().millisecondsSinceEpoch;
    final last = _roomStaleSenderResyncAtMs[groupId] ?? 0;
    if (now - last >= _roomStaleSenderResyncCooldownMs &&
        _relay != null &&
        !_transportBlocked) {
      _roomStaleSenderResyncAtMs[groupId] = now;
      try {
        await _reconcileKnownRoomFromRelayBestEffort(
          groupId,
          localSettingsRow: settingsRow,
        ).timeout(const Duration(seconds: 6));
      } catch (_) {
        // best-effort — fall through to the local re-check either way.
      }
    }
    // Re-read the (possibly just-converged) local roster.
    final members = await db.groupMembersList(groupId);
    for (final row in members) {
      if ((((row['member_profile_id'] as String?) ?? '').trim()) ==
          senderProfile) {
        return true;
      }
    }
    return false;
  }

  Future<List<String>> _listKnownRoomIdsForRelayResync() async {
    final db = _db;
    if (db == null) return const <String>[];
    final rows = await db.convoList(limit: 1000);
    return rows
        .where((row) => (row['kind'] as String?) == 'group')
        .map((row) => ((row['convo_id'] as String?) ?? '').trim())
        .where((convoId) => convoId.startsWith('group:'))
        .toSet()
        .toList(growable: false)
      ..sort();
  }

  Future<void> _resyncKnownRelayStateBestEffort() async {
    try {
      await _resyncKnownRoomsFromRelayBestEffort();
    } catch (_) {
      // ignore
    }
    try {
      await _resyncKnownRoomCallsFromRelayBestEffort();
    } catch (_) {
      // ignore
    }
  }

  // A1 ZERO-LOSS deferred-inbound park: how long a parked (decrypted) group
  // frame waits for its sender to be confirmed a member before being pruned.
  // Matches the relay's own pending retention so a genuinely-removed sender's
  // frame ages out rather than lingering forever.
  static const int _deferredRoomInboundTtlMs = 7 * 24 * 60 * 60 * 1000;

  /// A1: persist a DECRYPTED group frame whose sender is not yet in our local
  /// roster, so it survives the ack-and-DELETE and is re-applied on convergence.
  Future<void> _storeDeferredRoomInbound({
    required AppDb db,
    required String groupId,
    required String senderProfile,
    required String? senderDeviceId,
    required String msgEventId,
    required String commandText,
    required String msgId,
    required String ciphertextB64,
    required int createdAtMs,
  }) async {
    final sdid = (senderDeviceId ?? '').trim();
    final syntheticEventId = 'grp:$msgEventId:$sdid';
    try {
      await _retryDbBusy(() async {
        await db.deferredRoomInboundUpsert(
          syntheticEventId: syntheticEventId,
          groupId: groupId,
          senderProfileId: senderProfile,
          senderDeviceId: sdid.isEmpty ? null : sdid,
          commandText: commandText,
          msgId: msgId,
          ciphertextB64: ciphertextB64,
          createdAtMs: createdAtMs,
        );
      });
      DiagLog.event('inbox', 'room_inbound_deferred', {
        'group': DiagLog.pfx(groupId),
        'sender': DiagLog.pfx(senderProfile),
      });
    } catch (e) {
      callLog('AppCtrl', '_storeDeferredRoomInbound failed group=$groupId: $e');
    }
  }

  /// A1: re-apply any parked frames for [groupId] whose sender is NOW a member.
  /// Called when membership converges (authoritative snapshot apply) and from
  /// the periodic recovery sweep. Idempotent — the events table dedups on the
  /// synthetic id, and applied rows are removed from the park.
  Future<void> _flushDeferredRoomInbound(AppDb db, String groupId) async {
    final gid = groupId.trim();
    if (gid.isEmpty) return;
    List<Map<String, Object?>> rows;
    try {
      rows = await db.deferredRoomInboundListForGroup(gid);
    } catch (_) {
      return;
    }
    if (rows.isEmpty) return;
    Set<String> members;
    try {
      members = (await db.groupMembersList(gid))
          .map((r) => ((r['member_profile_id'] as String?) ?? '').trim())
          .where((m) => m.isNotEmpty)
          .toSet();
    } catch (_) {
      return;
    }
    var applied = 0;
    for (final row in rows) {
      var senderProfile =
          ((row['sender_profile_id'] as String?) ?? '').trim();
      final parkedDid = ((row['sender_device_id'] as String?) ?? '').trim();
      if (senderProfile.isEmpty && parkedDid.isNotEmpty) {
        // Служебная команда от ещё не опознанного устройства (17.09.2026):
        // владелец — из кэша, а на переднем плане и у сервера ключей.
        try {
          final cached = (await db.deviceProfileCached(parkedDid) ?? '').trim();
          senderProfile = cached.isNotEmpty || _relay == null
              ? cached
              : (await _resolveProfileIdForDevice(parkedDid) ?? '').trim();
        } catch (_) {
          // остаётся в парковке до следующего прохода
        }
      }
      if (senderProfile.isEmpty || !members.contains(senderProfile)) {
        continue; // sender still not a member — keep parked (TTL prunes later)
      }
      final syntheticEventId =
          ((row['synthetic_event_id'] as String?) ?? '').trim();
      try {
        final commandText = (row['command_text'] as String?) ?? '';
        final senderDeviceId = (row['sender_device_id'] as String?)?.trim();
        final storedMsgId = ((row['msg_id'] as String?) ?? '').trim();
        final ciphertextB64 = (row['ciphertext_b64'] as String?) ?? '';
        final createdAtMs =
            (row['created_at_ms'] as num?)?.toInt() ??
            DateTime.now().millisecondsSinceEpoch;
        final payload = E2ePayloadV1(
          senderDeviceId: (senderDeviceId == null || senderDeviceId.isEmpty)
              ? 'unknown'
              : senderDeviceId,
          createdAtMs: createdAtMs,
          events: [MsgEventV1(eventId: _uuid.v4(), text: commandText)],
        );
        final ok = await _handleDecryptedInboundPayload(
          db: db,
          msgId: storedMsgId.isEmpty ? _uuid.v4() : storedMsgId,
          ciphertextB64: ciphertextB64,
          plainBytes: Uint8List.fromList(payload.encode()),
          payload: payload,
          now: DateTime.now().millisecondsSinceEpoch,
          senderDeviceId: senderDeviceId,
          senderProfileId: senderProfile,
          fromDeferredReplay: true,
        );
        if (ok && syntheticEventId.isNotEmpty) {
          await db.deferredRoomInboundDelete(syntheticEventId);
          applied++;
        }
      } catch (e) {
        callLog(
          'AppCtrl',
          '_flushDeferredRoomInbound replay failed id=$syntheticEventId: $e',
        );
        // leave the row; retried on the next convergence / sweep tick
      }
    }
    if (applied > 0) {
      DiagLog.event('inbox', 'room_inbound_deferred_applied', {
        'group': DiagLog.pfx(gid),
        'count': applied,
      });
      _changed.add(null);
    }
  }

  /// A1: TTL-prune expired parked frames, then re-attempt flush for every group
  /// that still has parked frames. Cheap no-op when the park is empty. Runs from
  /// the periodic quarantine-recovery sweep as the zero-loss backstop that
  /// converges regardless of which membership path caught up.
  Future<void> _flushAndPruneDeferredRoomInbound(AppDb db) async {
    final nowMs = DateTime.now().millisecondsSinceEpoch;
    try {
      await db.deferredRoomInboundPrune(
        olderThanMs: nowMs - _deferredRoomInboundTtlMs,
      );
    } catch (_) {}
    List<String> groupIds;
    try {
      groupIds = await db.deferredRoomInboundGroupIds();
    } catch (_) {
      return;
    }
    for (final gid in groupIds) {
      await _flushDeferredRoomInbound(db, gid);
    }
  }

  List<RoomCallParticipantStateRecord> _roomCallParticipantRecordsFromSnapshot(
    RelayRoomCallSnapshot snapshot,
  ) {
    final merged = <String, RelayRoomCallParticipant>{};

    void addParticipant(RelayRoomCallParticipant? participant) {
      if (participant == null) return;
      final cleanedProfileId = participant.profileId.trim();
      final cleanedDeviceId = participant.deviceId.trim();
      if (cleanedProfileId.isEmpty || cleanedDeviceId.isEmpty) {
        return;
      }
      merged['$cleanedProfileId|$cleanedDeviceId'] = participant;
    }

    for (final participant in snapshot.participants) {
      addParticipant(participant);
    }
    addParticipant(snapshot.selfParticipant);

    final orderedParticipants = merged.values.toList(growable: false)
      ..sort((left, right) {
        final byJoinedAt = left.joinedAtMs.compareTo(right.joinedAtMs);
        if (byJoinedAt != 0) {
          return byJoinedAt;
        }
        final byProfileId = left.profileId.compareTo(right.profileId);
        if (byProfileId != 0) {
          return byProfileId;
        }
        return left.deviceId.compareTo(right.deviceId);
      });

    return orderedParticipants
        .map(
          (participant) => (
            profileId: participant.profileId.trim(),
            deviceId: participant.deviceId.trim(),
            joinState: participant.joinState.trim().isEmpty
                ? 'joined'
                : participant.joinState.trim(),
            supportsVideo: participant.supportsVideo,
            supportsScreenShare: participant.supportsScreenShare,
            muted: participant.muted,
            deafened: participant.deafened,
            videoEnabled: participant.videoEnabled,
            screenShareEnabled: participant.screenShareEnabled,
            speaking: participant.speaking,
            joinedAtMs: participant.joinedAtMs,
            leftAtMs: participant.leftAtMs,
            updatedAtMs: participant.updatedAtMs,
          ),
        )
        .toList(growable: false);
  }

  Future<void> _applyRelayRoomCallSnapshot(
    RelayRoomCallSnapshot snapshot, {
    String? fallbackRoomId,
  }) async {
    final db = _db;
    if (db == null) {
      return;
    }
    final cleanedRoomId = snapshot.room.roomId.trim().isNotEmpty
        ? snapshot.room.roomId.trim()
        : (fallbackRoomId ?? '').trim();
    if (cleanedRoomId.isEmpty) {
      return;
    }
    final call = snapshot.call;
    final cleanedCallId = call?.callId.trim() ?? '';
    if (!snapshot.exists ||
        call == null ||
        cleanedCallId.isEmpty ||
        !call.isActive) {
      await db.roomCallSnapshotDelete(cleanedRoomId);
      _changed.add(null);
      return;
    }
    await db.roomCallSnapshotReplace(
      groupId: cleanedRoomId,
      callId: cleanedCallId,
      state: call.state,
      mediaType: call.mediaType,
      createdByProfileId: call.createdByProfileId,
      createdByDeviceId: call.createdByDeviceId,
      stateVersion: call.stateVersion,
      startedAtMs: call.startedAtMs,
      updatedAtMs: call.updatedAtMs,
      endedAtMs: call.endedAtMs,
      expiresAtMs: call.expiresAtMs,
      participants: _roomCallParticipantRecordsFromSnapshot(snapshot),
    );
    _changed.add(null);
  }

  bool _isTerminalRoomCallRelayHttpStatus(int? statusCode) {
    return statusCode == 403 || statusCode == 404 || statusCode == 409;
  }

  Future<void> _clearCachedRoomCallBestEffort(String roomId) async {
    final db = _db;
    final cleanedRoomId = roomId.trim();
    if (db == null || cleanedRoomId.isEmpty) {
      return;
    }
    try {
      await db.roomCallSnapshotDelete(cleanedRoomId);
      _changed.add(null);
    } catch (e) {
      callLog(
        'AppCtrl',
        'relay room call cache clear failed roomId=$cleanedRoomId: $e',
      );
    }
  }

  Future<void> _recoverRoomCallMutationFailureBestEffort(
    String roomId,
    Object error,
  ) async {
    if (error is! RelayHttpException ||
        !_isTerminalRoomCallRelayHttpStatus(error.statusCode)) {
      return;
    }
    try {
      await _refreshRoomCallFromRelay(roomId);
    } catch (_) {
      // _refreshRoomCallFromRelay clears terminal local state when appropriate.
    }
  }

  Future<RelayRoomCallSnapshot?> _refreshRoomCallFromRelayOnce(
    String cleanedRoomId,
  ) async {
    final relay = _relay;
    if (relay == null || cleanedRoomId.isEmpty) {
      return null;
    }
    try {
      final snapshot = await relay.getRoomCall(roomId: cleanedRoomId);
      if (!identical(_relay, relay)) {
        return snapshot;
      }
      await _applyRelayRoomCallSnapshot(
        snapshot,
        fallbackRoomId: cleanedRoomId,
      );
      return snapshot;
    } catch (error) {
      if (identical(_relay, relay) &&
          error is RelayHttpException &&
          _isTerminalRoomCallRelayHttpStatus(error.statusCode)) {
        await _clearCachedRoomCallBestEffort(cleanedRoomId);
      }
      rethrow;
    }
  }

  Future<RelayRoomCallSnapshot?> _refreshRoomCallFromRelay(
    String roomId,
  ) async {
    final cleanedRoomId = roomId.trim();
    if (cleanedRoomId.isEmpty || _relay == null) {
      return null;
    }
    final existing = _roomCallRefreshInFlight[cleanedRoomId];
    if (existing != null) {
      return existing;
    }
    late final Future<RelayRoomCallSnapshot?> future;
    future = _refreshRoomCallFromRelayOnce(cleanedRoomId).whenComplete(() {
      if (identical(_roomCallRefreshInFlight[cleanedRoomId], future)) {
        _roomCallRefreshInFlight.remove(cleanedRoomId);
      }
    });
    _roomCallRefreshInFlight[cleanedRoomId] = future;
    return future;
  }

  Future<void> _tryRefreshRoomCallFromRelayBestEffort(String roomId) async {
    try {
      await _refreshRoomCallFromRelay(roomId);
    } catch (e) {
      callLog(
        'AppCtrl',
        'relay room call refresh failed roomId=${roomId.trim()}: $e',
      );
    }
  }

  Future<void> _resyncKnownRoomsFromRelayBestEffort() async {
    final relay = _relay;
    final db = _db;
    if (relay == null || !_relayOnline || _transportBlocked || db == null) {
      return;
    }
    final roomIds = await _listKnownRoomIdsForRelayResync();
    final localSettingsByGroupId = await db.groupSettingsGetForGroups(roomIds);
    for (final roomId in roomIds) {
      if (!identical(_relay, relay) || !_relayOnline || _transportBlocked) {
        return;
      }
      await _reconcileKnownRoomFromRelayBestEffort(
        roomId,
        localSettingsRow: localSettingsByGroupId[roomId],
      );
    }
  }

  Future<void> _resyncKnownRoomCallsFromRelayBestEffort() async {
    final relay = _relay;
    final db = _db;
    if (relay == null || !_relayOnline || _transportBlocked || db == null) {
      return;
    }
    final roomIds = await db.roomCallActiveGroupIdsList();
    for (final roomId in roomIds) {
      if (!identical(_relay, relay) || !_relayOnline || _transportBlocked) {
        return;
      }
      await _tryRefreshRoomCallFromRelayBestEffort(roomId);
    }
  }

