  RoomSettings _nextRoomStateVersion(RoomSettings settings) {
    return settings.copyWith(
      stateVersion: settings.stateVersion > 0 ? settings.stateVersion + 1 : 1,
    );
  }

  RoomSettings _nextRoomMembershipVersion(RoomSettings settings) {
    return settings.copyWith(
      membershipVersion: settings.membershipVersion > 0
          ? settings.membershipVersion + 1
          : 1,
    );
  }

  RoomSettings _nextRoomStateAndMembershipVersion(RoomSettings settings) {
    return _nextRoomStateVersion(_nextRoomMembershipVersion(settings));
  }

  Future<String> _computeRoomAvatarHash(Uint8List bytes) async {
    final digest = await Sha256().hash(bytes);
    return base64UrlEncode(digest.bytes).replaceAll('=', '');
  }

  Future<String> _writeRoomAvatarBytes({
    required String groupId,
    required Uint8List bytes,
    required String hash,
  }) async {
    final dir = await getApplicationDocumentsDirectory();
    final avatarDir = Directory(p.join(dir.path, 'room_avatars'));
    if (!await avatarDir.exists()) {
      await avatarDir.create(recursive: true);
    }
    final safeGroupId = groupId.replaceAll(RegExp(r'[^a-zA-Z0-9_-]'), '_');
    final path = p.join(avatarDir.path, '${safeGroupId}_$hash.jpg');
    await File(path).writeAsBytes(bytes, flush: true);
    return path;
  }

  Future<void> _deleteLocalFileIfExists(String? path) async {
    if (path == null || path.trim().isEmpty) return;
    try {
      final file = File(path);
      if (await file.exists()) {
        await file.delete();
      }
    } catch (_) {
      // ignore
    }
  }

  Future<({Uint8List bytes, String hash})> _prepareRoomAvatarFromSourceBytes({
    required Uint8List sourceBytes,
  }) async {
    final decoded = img.decodeImage(sourceBytes);
    if (decoded == null) {
      throw StateError('Unsupported image');
    }

    final side = decoded.width < decoded.height
        ? decoded.width
        : decoded.height;
    final x = (decoded.width - side) ~/ 2;
    final y = (decoded.height - side) ~/ 2;
    final cropped = img.copyCrop(
      decoded,
      x: x,
      y: y,
      width: side,
      height: side,
    );

    Uint8List? encoded;
    const maxBytes = 90000;
    for (final target in const <int>[512, 384, 320, 256, 192]) {
      final resized = img.copyResize(
        cropped,
        width: target,
        height: target,
        interpolation: img.Interpolation.average,
      );
      for (final quality in const <int>[88, 82, 76, 70]) {
        final jpg = Uint8List.fromList(
          img.encodeJpg(resized, quality: quality),
        );
        if (jpg.length <= maxBytes) {
          encoded = jpg;
          break;
        }
      }
      if (encoded != null) {
        break;
      }
    }

    encoded ??= Uint8List.fromList(
      img.encodeJpg(
        img.copyResize(
          cropped,
          width: 160,
          height: 160,
          interpolation: img.Interpolation.average,
        ),
        quality: 68,
      ),
    );

    final hash = await _computeRoomAvatarHash(encoded);
    return (bytes: encoded, hash: hash);
  }

  Future<({Uint8List bytes, String hash, String path})>
  _storeRoomAvatarFromSourceBytes({
    required String groupId,
    required Uint8List sourceBytes,
  }) async {
    final normalizedAvatar = await _prepareRoomAvatarFromSourceBytes(
      sourceBytes: sourceBytes,
    );
    final path = await _writeRoomAvatarBytes(
      groupId: groupId,
      bytes: normalizedAvatar.bytes,
      hash: normalizedAvatar.hash,
    );
    return (
      bytes: normalizedAvatar.bytes,
      hash: normalizedAvatar.hash,
      path: path,
    );
  }

  Future<({String? avatarHash, String? avatarImageB64})>
  _buildRoomAvatarSnapshotFields(RoomSettings settings) async {
    final avatarPath = (settings.avatarPath ?? '').trim();
    final avatarHash = (settings.avatarHash ?? '').trim();
    if (avatarPath.isEmpty) {
      return (
        avatarHash: avatarHash.isEmpty ? null : avatarHash,
        avatarImageB64: null,
      );
    }
    try {
      final file = File(avatarPath);
      if (!await file.exists()) {
        return (
          avatarHash: avatarHash.isEmpty ? null : avatarHash,
          avatarImageB64: null,
        );
      }
      final bytes = await file.readAsBytes();
      if (bytes.isEmpty) {
        return (
          avatarHash: avatarHash.isEmpty ? null : avatarHash,
          avatarImageB64: null,
        );
      }
      final effectiveHash = avatarHash.isNotEmpty
          ? avatarHash
          : await _computeRoomAvatarHash(bytes);
      return (avatarHash: effectiveHash, avatarImageB64: base64Encode(bytes));
    } catch (_) {
      return (
        avatarHash: avatarHash.isEmpty ? null : avatarHash,
        avatarImageB64: null,
      );
    }
  }

  Future<({String? avatarPath, String? avatarHash})>
  _resolveIncomingRoomAvatar({
    required String groupId,
    required RoomSettings currentSettings,
    required String? incomingAvatarHash,
    required String? incomingAvatarImageB64,
  }) async {
    final cleanedHash = (incomingAvatarHash ?? '').trim();
    final currentPath = (currentSettings.avatarPath ?? '').trim();
    final currentHash = (currentSettings.avatarHash ?? '').trim();

    if (cleanedHash.isEmpty) {
      await _deleteLocalFileIfExists(currentPath.isEmpty ? null : currentPath);
      return (avatarPath: null, avatarHash: null);
    }

    if (currentHash == cleanedHash &&
        currentPath.isNotEmpty &&
        await File(currentPath).exists()) {
      return (avatarPath: currentPath, avatarHash: cleanedHash);
    }

    final cleanedImageB64 = (incomingAvatarImageB64 ?? '').trim();
    if (cleanedImageB64.isNotEmpty) {
      try {
        final bytes = base64Decode(cleanedImageB64);
        if (bytes.isNotEmpty) {
          final computedHash = await _computeRoomAvatarHash(bytes);
          if (computedHash == cleanedHash) {
            final path = await _writeRoomAvatarBytes(
              groupId: groupId,
              bytes: bytes,
              hash: cleanedHash,
            );
            if (currentPath.isNotEmpty && currentPath != path) {
              await _deleteLocalFileIfExists(currentPath);
            }
            return (avatarPath: path, avatarHash: cleanedHash);
          }
        }
      } catch (_) {
        // ignore malformed avatar payloads and fall back to initials.
      }
    }

    await _deleteLocalFileIfExists(currentPath.isEmpty ? null : currentPath);
    return (avatarPath: null, avatarHash: cleanedHash);
  }

  Future<List<GroupMembershipStateRecord>> listRoomMembershipStates(
    String groupId, {
    Set<RoomMembershipStatus>? statuses,
  }) async {
    final db = _db;
    if (db == null) return const <GroupMembershipStateRecord>[];
    final rows = await db.groupMembershipStatesList(
      groupId,
      statuses: statuses?.map((status) => status.value).toList(growable: false),
    );
    if (rows.isNotEmpty) {
      return rows;
    }
    if (statuses != null &&
        statuses.isNotEmpty &&
        !statuses.contains(RoomMembershipStatus.active)) {
      return const <GroupMembershipStateRecord>[];
    }

    final legacyRows = await db.groupMembersList(groupId);
    return legacyRows
        .map((row) {
          final profileId = ((row['member_profile_id'] as String?) ?? '')
              .trim();
          if (profileId.isEmpty) return null;
          final createdAtMs = (row['created_at_ms'] as num?)?.toInt() ?? 0;
          return (
            profileId: profileId,
            status: RoomMembershipStatus.active.value,
            role: RoomMemberRole.member.value,
            sourceLinkId: null,
            tag: null,
            createdAtMs: createdAtMs,
            updatedAtMs: createdAtMs,
          );
        })
        .whereType<GroupMembershipStateRecord>()
        .toList(growable: false);
  }

  Future<GroupMembershipStateRecord?> _roomMembershipStateOrLegacyActive(
    String groupId,
    String memberProfileId,
  ) async {
    final db = _db;
    final cleanedProfileId = memberProfileId.trim();
    if (db == null || cleanedProfileId.isEmpty) return null;
    final existing = await db.groupMembershipStateGet(
      groupId: groupId,
      profileId: cleanedProfileId,
    );
    if (existing != null) {
      return existing;
    }
    final legacyMembers = await db.groupMembersList(groupId);
    for (final row in legacyMembers) {
      final profileId = ((row['member_profile_id'] as String?) ?? '').trim();
      if (profileId != cleanedProfileId) continue;
      final createdAtMs = (row['created_at_ms'] as num?)?.toInt() ?? 0;
      return (
        profileId: cleanedProfileId,
        status: RoomMembershipStatus.active.value,
        role: RoomMemberRole.member.value,
        sourceLinkId: null,
        tag: null,
        createdAtMs: createdAtMs,
        updatedAtMs: createdAtMs,
      );
    }
    return null;
  }

  Future<List<String>> listGroupAdmins(String groupId) async {
    final db = _db;
    if (db == null) return const <String>[];
    final rows = await db.groupAdminsList(groupId);
    return rows
        .map((r) => (r['profile_id'] as String?) ?? '')
        .where((id) => id.isNotEmpty)
        .toList(growable: false);
  }

  RoomMemberRole _effectiveRoomMemberRole({
    required String profileId,
    required RoomSettings settings,
    required String? storedRole,
    required Set<String> legacyAdminIds,
  }) {
    final cleanedProfileId = profileId.trim();
    if (cleanedProfileId.isEmpty) {
      return RoomMemberRole.member;
    }
    if (cleanedProfileId == settings.ownerProfileId) {
      return RoomMemberRole.owner;
    }
    final normalizedStoredRole = (storedRole ?? '').trim();
    if (normalizedStoredRole.isNotEmpty) {
      final role = RoomMemberRoleX.fromValue(normalizedStoredRole);
      return role == RoomMemberRole.owner ? RoomMemberRole.admin : role;
    }
    if (legacyAdminIds.contains(cleanedProfileId)) {
      return RoomMemberRole.admin;
    }
    return RoomMemberRole.member;
  }

  String _persistedRoomMemberRoleValue(RoomMemberRole role) {
    return role == RoomMemberRole.owner
        ? RoomMemberRole.admin.value
        : role.value;
  }

  Future<RoomMemberRole?> getRoomMemberRole(
    String groupId, {
    String? profileIdOverride,
  }) async {
    final pid = (profileIdOverride ?? profileId).trim();
    if (pid.isEmpty) return null;
    final membershipState = await _roomMembershipStateOrLegacyActive(
      groupId,
      pid,
    );
    if (membershipState == null ||
        RoomMembershipStatusX.fromValue(membershipState.status) !=
            RoomMembershipStatus.active) {
      return null;
    }
    final settings = await getRoomSettings(groupId);
    final adminIds = (await listGroupAdmins(groupId)).toSet();
    return _effectiveRoomMemberRole(
      profileId: pid,
      settings: settings,
      storedRole: membershipState.role,
      legacyAdminIds: adminIds,
    );
  }

  Future<List<RoomMember>> listRoomMembersDetailed(
    String groupId, {
    Set<RoomMembershipStatus>? statuses,
  }) async {
    final membershipStates = await listRoomMembershipStates(
      groupId,
      statuses: statuses ?? <RoomMembershipStatus>{RoomMembershipStatus.active},
    );
    final settings = await getRoomSettings(groupId);
    final adminIds = (await listGroupAdmins(groupId)).toSet();
    final contacts = await listContacts();
    final byId = <String, Contact>{for (final c in contacts) c.profileId: c};
    final selfProfileId = profileId.trim();
    final selfDisplayName = myNickname.trim();
    // На компьютере своего файла нет — там своё лицо приезжает вместе с
    // остальными метаданными профиля (см. [_pairedDeviceOwnAvatarPath]).
    // На телефоне вызов возвращает null, и строка значит ровно то же, что и
    // раньше.
    final selfAvatarPath =
        _existingAvatarFilePath(_myAvatarPath) ??
        _myAvatarPath ??
        await _pairedDeviceOwnAvatarPath();

    final out = <RoomMember>[];
    for (final membershipState in membershipStates) {
      final memberId = membershipState.profileId;
      final contact = byId[memberId];
      final isSelfMember = memberId == selfProfileId;
      final contactDisplayName =
          (!isSelfMember &&
              contact?.displayName != null &&
              contact!.displayName!.trim().isNotEmpty)
          ? contact.displayName!.trim()
          : null;
      final resolvedDisplayName = (isSelfMember && selfDisplayName.isNotEmpty)
          ? selfDisplayName
          : contactDisplayName ??
                await _roomSystemParticipantDisplayName(memberId);
      final displayName =
          (resolvedDisplayName != null && resolvedDisplayName.trim().isNotEmpty)
          ? resolvedDisplayName.trim()
          : memberId;
      // A member whose name is still the raw profile id has never had their
      // published profile fetched (common for non-contacts). Kick off a
      // throttled refresh so the roster self-heals to real names/avatars on a
      // later rebuild instead of showing bare ids.
      if (!isSelfMember && displayName == memberId) {
        _refreshProfileMetaSoon(memberId);
      }
      final membershipStatus = RoomMembershipStatusX.fromValue(
        membershipState.status,
      );
      final role = _effectiveRoomMemberRole(
        profileId: memberId,
        settings: settings,
        storedRole: membershipState.role,
        legacyAdminIds: adminIds,
      );
      out.add(
        RoomMember(
          profileId: memberId,
          displayName: displayName,
          // FIX (2026-07-13, call/room avatar): resolve a non-self member's
          // photo through the SAME resolver the chat uses — contact avatar if
          // present, else the synced profile_meta photo — so room tiles and
          // group-call tiles show the photo for members who aren't saved
          // contacts instead of falling back to initials. Cheap when the
          // contact already carries a valid avatar file (no extra lookup).
          avatarPath: isSelfMember
              ? (selfAvatarPath ?? contact?.avatarPath)
              : (_existingAvatarFilePath(contact?.avatarPath) ??
                    await cachedProfileAvatarPath(memberId)),
          tag: membershipState.tag,
          role: role,
          isOnline: false,
          membershipStatus: membershipStatus,
          membershipCreatedAtMs: membershipState.createdAtMs,
          membershipUpdatedAtMs: membershipState.updatedAtMs,
        ),
      );
    }
    out.sort((a, b) {
      if (a.membershipStatus == RoomMembershipStatus.active &&
          b.membershipStatus == RoomMembershipStatus.active) {
        final ra = a.role.sortPriority;
        final rb = b.role.sortPriority;
        if (ra != rb) return ra.compareTo(rb);
      }
      final statusCompare = a.membershipStatus.index.compareTo(
        b.membershipStatus.index,
      );
      if (statusCompare != 0) return statusCompare;
      final createdCompare = a.membershipCreatedAtMs.compareTo(
        b.membershipCreatedAtMs,
      );
      if (createdCompare != 0) return createdCompare;
      return a.displayName.toLowerCase().compareTo(b.displayName.toLowerCase());
    });
    return out;
  }

  Future<List<RoomMember>> listRoomJoinRequestsDetailed(String groupId) {
    return listRoomMembersDetailed(
      groupId,
      statuses: <RoomMembershipStatus>{RoomMembershipStatus.pending},
    );
  }

  Future<List<RoomMember>> listRoomBannedMembersDetailed(String groupId) {
    return listRoomMembersDetailed(
      groupId,
      statuses: <RoomMembershipStatus>{RoomMembershipStatus.banned},
    );
  }

  bool get _isRussianSystemEventLocale {
    final override = appLocaleOverride;
    final code =
        (override?.languageCode ??
                PlatformDispatcher.instance.locale.languageCode)
            .toLowerCase();
    return code == 'ru' || code.startsWith('ru_');
  }

  Future<String?> _roomSystemParticipantDisplayName(String profileId) async {
    final cleanedProfileId = profileId.trim();
    if (cleanedProfileId.isEmpty) return null;
    final selfProfileId = this.profileId.trim();
    if (cleanedProfileId == selfProfileId) {
      final selfDisplayName = myNickname.trim();
      return selfDisplayName.isEmpty ? null : selfDisplayName;
    }
    final resolved = (await resolveConvoTitle(cleanedProfileId)).trim();
    if (resolved.isEmpty || resolved == cleanedProfileId) {
      return null;
    }
    return resolved;
  }

  List<String> _roomProfileChangedKeys({
    required bool titleChanged,
    required bool descriptionChanged,
    required bool avatarChanged,
  }) {
    final changedKeys = <String>[];
    if (titleChanged) changedKeys.add('title');
    if (descriptionChanged) changedKeys.add('description');
    if (avatarChanged) changedKeys.add('avatar');
    return changedKeys;
  }

  List<String> _roomSettingsChangedKeys({
    required RoomSettings before,
    required RoomSettings after,
  }) {
    final changedKeys = <String>[];
    if (before.reactionsMode != after.reactionsMode) {
      changedKeys.add('reactions_mode');
    }
    if (before.allowTextMessages != after.allowTextMessages) {
      changedKeys.add('allow_text');
    }
    if (before.allowMedia != after.allowMedia) {
      changedKeys.add('allow_media');
    }
    if (before.allowAddMembers != after.allowAddMembers) {
      changedKeys.add('allow_add_members');
    }
    if (before.allowPinMessages != after.allowPinMessages) {
      changedKeys.add('allow_pin_messages');
    }
    if (before.allowChangeGroupInfo != after.allowChangeGroupInfo) {
      changedKeys.add('allow_change_group_info');
    }
    if (before.allowChangeTag != after.allowChangeTag) {
      changedKeys.add('allow_change_tag');
    }
    if (before.joinApprovalRequired != after.joinApprovalRequired) {
      changedKeys.add('join_approval_required');
    }
    if (before.slowModeSeconds != after.slowModeSeconds) {
      changedKeys.add('slow_mode');
    }
    if (before.chatHistoryVisible != after.chatHistoryVisible) {
      changedKeys.add('chat_history_visible');
    }
    return changedKeys;
  }

  SystemEventV1 _buildRoomSystemEvent({
    required String eventId,
    required String action,
    String? actorProfileId,
    String? actorDisplayName,
    String? targetProfileId,
    String? targetDisplayName,
    List<String> changedKeys = const <String>[],
  }) {
    final normalizedActorProfileId = actorProfileId?.trim();
    final normalizedActorDisplayName = actorDisplayName?.trim();
    final normalizedTargetProfileId = targetProfileId?.trim();
    final normalizedTargetDisplayName = targetDisplayName?.trim();
    final normalizedChangedKeys = changedKeys
        .map((key) => key.trim())
        .where((key) => key.isNotEmpty)
        .toList(growable: false);
    final previewEvent = SystemEventV1(
      eventId: eventId,
      text: '',
      action: action,
      actorProfileId:
          normalizedActorProfileId == null || normalizedActorProfileId.isEmpty
          ? null
          : normalizedActorProfileId,
      actorDisplayName:
          normalizedActorDisplayName == null ||
              normalizedActorDisplayName.isEmpty
          ? null
          : normalizedActorDisplayName,
      targetProfileId:
          normalizedTargetProfileId == null || normalizedTargetProfileId.isEmpty
          ? null
          : normalizedTargetProfileId,
      targetDisplayName:
          normalizedTargetDisplayName == null ||
              normalizedTargetDisplayName.isEmpty
          ? null
          : normalizedTargetDisplayName,
      changedKeys: normalizedChangedKeys,
    );
    return SystemEventV1(
      eventId: eventId,
      text: formatSystemEventText(
        previewEvent,
        isRu: _isRussianSystemEventLocale,
        selfProfileId: _profileId?.trim(),
        localeTag: _effectiveAppLocaleTagForStrings(),
      ),
      action: previewEvent.action,
      actorProfileId: previewEvent.actorProfileId,
      actorDisplayName: previewEvent.actorDisplayName,
      targetProfileId: previewEvent.targetProfileId,
      targetDisplayName: previewEvent.targetDisplayName,
      changedKeys: previewEvent.changedKeys,
    );
  }

  Future<void> _insertLocalRoomSystemEvent({
    required String groupId,
    required String groupTitle,
    required SystemEventV1 event,
    required int createdAtMs,
  }) async {
    final db = _db;
    final did = _deviceId?.trim();
    final crypto = _crypto;
    if (db == null || did == null || did.isEmpty || crypto == null) {
      return;
    }
    final localEventId = 'local:grpsys:${event.eventId}';
    if (await db.eventGet(localEventId) != null) {
      return;
    }
    final normalizedTitle = groupTitle.trim().isEmpty
        ? 'Room'
        : groupTitle.trim();
    await db.convoEnsureGroup(groupId: groupId, title: normalizedTitle);
    final payload = E2ePayloadV1(
      senderDeviceId: did,
      createdAtMs: createdAtMs,
      events: <E2eEventV1>[event],
    );
    final localCipher = base64Encode(await crypto.encrypt(payload.encode()));
    await db.insertEvent(
      eventId: localEventId,
      convoId: groupId,
      type: 'sys',
      senderDeviceId: did,
      ciphertextB64: localCipher,
      createdAtMs: createdAtMs,
      localState: 'sent',
      payloadEventId: event.eventId,
    );
    await db.convoTouch(convoId: groupId, atMs: createdAtMs);
  }

  Future<void> _broadcastRoomSystemEvent({
    required String groupId,
    required String action,
    String? actorProfileId,
    String? actorDisplayName,
    String? targetProfileId,
    String? targetDisplayName,
    List<String> changedKeys = const <String>[],
    Iterable<String> extraProfileIds = const <String>[],
    String? skipProfileId,
  }) async {
    final db = _db;
    if (db == null) return;
    final convo = await db.convoGet(groupId);
    final groupTitle = ((convo?['title'] as String?) ?? 'Room').trim();
    final normalizedGroupTitle = groupTitle.isEmpty ? 'Room' : groupTitle;
    final event = _buildRoomSystemEvent(
      eventId: _uuid.v4(),
      action: action,
      actorProfileId: actorProfileId ?? profileId.trim(),
      actorDisplayName: actorDisplayName ?? myNickname.trim(),
      targetProfileId: targetProfileId,
      targetDisplayName: targetDisplayName,
      changedKeys: changedKeys,
    );
    final createdAtMs = DateTime.now().millisecondsSinceEpoch;
    await _insertLocalRoomSystemEvent(
      groupId: groupId,
      groupTitle: normalizedGroupTitle,
      event: event,
      createdAtMs: createdAtMs,
    );

    final members = await listGroupMembers(groupId);
    final recipients = <String>{
      ...members
          .map((profileId) => profileId.trim())
          .where((profileId) => profileId.isNotEmpty),
      ...extraProfileIds
          .map((profileId) => profileId.trim())
          .where((profileId) => profileId.isNotEmpty),
    };
    final command = <String, Object?>{
      'v': 1,
      'groupId': groupId,
      'groupTitle': normalizedGroupTitle,
      'kind': 'system',
      'msgEventId': event.eventId,
      'text': event.text,
      'createdAtMs': createdAtMs,
      'memberProfileIds': members,
      if (event.action != null && event.action!.trim().isNotEmpty)
        'action': event.action,
      if (event.actorProfileId != null) 'actorProfileId': event.actorProfileId,
      if (event.actorDisplayName != null)
        'actorDisplayName': event.actorDisplayName,
      if (event.targetProfileId != null)
        'targetProfileId': event.targetProfileId,
      if (event.targetDisplayName != null)
        'targetDisplayName': event.targetDisplayName,
      if (event.changedKeys.isNotEmpty) 'changedKeys': event.changedKeys,
    };
    final skip = (skipProfileId ?? '').trim();
    for (final recipient in recipients) {
      if (skip.isNotEmpty && recipient == skip) continue;
      await sendControlMessage(
        peerProfileId: recipient,
        controlText: _encodeCommandPayload(_groupMsgCmdPrefix, command),
        retryBucket: 'room_system_event',
        // A5: room system/membership envelopes must survive an offline recipient.
        // A lost membership envelope is what strands a member's roster (feeding
        // A1's stale-membership inbound drop), so make the fanout durable.
        queueIfNoDevices: true,
      );
    }
  }

  Future<void> updateRoomProfile({
    required String groupId,
    required String title,
    required String? description,
    Uint8List? avatarBytes,
    bool clearAvatar = false,
  }) async {
    final db = _db;
    if (db == null) return;
    await _ensureRoomActionAllowed(groupId, RoomAction.changeGroupInfo);

    final settings = await getRoomSettings(groupId);
    final convo = await db.convoGet(groupId);
    final storedTitle = ((convo?['title'] as String?) ?? '').trim();
    final effectiveCurrentTitle = storedTitle.isEmpty ? 'Group' : storedTitle;
    final cleanedTitle = title.trim().isEmpty ? 'Group' : title.trim();
    final effectiveCurrentDescription = (settings.description ?? '').trim();
    final cleanedDescription = (description ?? '').trim();
    final titleChanged = cleanedTitle != effectiveCurrentTitle;
    final descriptionChanged =
        cleanedDescription != effectiveCurrentDescription;

    var nextSettings = settings;
    final previousAvatarPath = settings.avatarPath;
    var avatarStateChanged = false;
    var avatarLocalPathChanged = false;
    String? relayAvatarHash;
    String? relayAvatarImageB64;

    if (avatarBytes != null) {
      if (_useAuthoritativeRoomRelay) {
        final preparedAvatar = await _prepareRoomAvatarFromSourceBytes(
          sourceBytes: avatarBytes,
        );
        relayAvatarHash = preparedAvatar.hash;
        relayAvatarImageB64 = base64Encode(preparedAvatar.bytes);
        avatarStateChanged = preparedAvatar.hash != (settings.avatarHash ?? '');
      } else {
        _throwIfRoomMutationAuthoritativeRelayUnavailable();
        final storedAvatar = await _storeRoomAvatarFromSourceBytes(
          groupId: groupId,
          sourceBytes: avatarBytes,
        );
        nextSettings = nextSettings.copyWith(
          avatarPath: storedAvatar.path,
          avatarHash: storedAvatar.hash,
        );
        avatarStateChanged = storedAvatar.hash != (settings.avatarHash ?? '');
        avatarLocalPathChanged =
            !avatarStateChanged &&
            storedAvatar.path != (settings.avatarPath ?? '');
      }
    } else if (clearAvatar) {
      avatarStateChanged =
          ((settings.avatarHash ?? '').isNotEmpty) ||
          ((settings.avatarPath ?? '').isNotEmpty);
      if (avatarStateChanged) {
        nextSettings = nextSettings.copyWith(clearAvatar: true);
      }
    }
    if (descriptionChanged) {
      nextSettings = nextSettings.copyWith(
        description: cleanedDescription.isEmpty ? null : cleanedDescription,
        clearDescription: cleanedDescription.isEmpty,
      );
    }
    final stateChanged =
        titleChanged || descriptionChanged || avatarStateChanged;
    final changedKeys = _roomProfileChangedKeys(
      titleChanged: titleChanged,
      descriptionChanged: descriptionChanged,
      avatarChanged: avatarStateChanged,
    );
    if (!stateChanged && !avatarLocalPathChanged) {
      return;
    }

    if (_useAuthoritativeRoomRelay) {
      final relay = _relay!;
      try {
        final result = await relay.updateRoomProfile(
          roomId: groupId,
          title: cleanedTitle,
          description: cleanedDescription.isEmpty ? null : cleanedDescription,
          avatarHash: clearAvatar ? null : relayAvatarHash,
          avatarImageB64: clearAvatar ? null : relayAvatarImageB64,
          clearAvatar: clearAvatar,
        );
        if (titleChanged) {
          await db.convoSetTitle(convoId: groupId, title: cleanedTitle);
        }
        try {
          await _refreshRoomFromRelay(groupId);
        } catch (_) {
          await _applyRelayRoomStateWithLocalMemberships(result.room);
        }
      } catch (error) {
        await _tryRefreshRoomFromRelayBestEffort(groupId);
        if (error is RelayHttpException) {
          throw _roomSettingsUpdateFailureFromRelayHttp(error);
        }
        rethrow;
      }
      _invalidateListConversationsCache();
      _changed.add(null);
      if (changedKeys.isNotEmpty) {
        await _broadcastRoomSystemEvent(
          groupId: groupId,
          action: RoomSystemEventAction.profileUpdated,
          changedKeys: changedKeys,
          skipProfileId: profileId.trim(),
        );
      }
      await _broadcastAuthoritativeRoomSyncHint(groupId);
      return;
    }

    _throwIfRoomMutationAuthoritativeRelayUnavailable();

    if (titleChanged) {
      await db.convoSetTitle(convoId: groupId, title: cleanedTitle);
    }

    final settingsToPersist = stateChanged
        ? _nextRoomStateVersion(nextSettings)
        : nextSettings;
    await _persistRoomSettingsRecord(
      db: db,
      groupId: groupId,
      settings: settingsToPersist,
    );

    final previousPath = (previousAvatarPath ?? '').trim();
    final nextPath = (settingsToPersist.avatarPath ?? '').trim();
    if (previousPath.isNotEmpty && previousPath != nextPath) {
      await _deleteLocalFileIfExists(previousPath);
    }

    _invalidateListConversationsCache();
    _changed.add(null);
    if (!stateChanged) {
      return;
    }
    if (changedKeys.isNotEmpty) {
      await _broadcastRoomSystemEvent(
        groupId: groupId,
        action: RoomSystemEventAction.profileUpdated,
        changedKeys: changedKeys,
        skipProfileId: profileId.trim(),
      );
    }
    await _broadcastRoomSnapshotToMembers(groupId);
  }

  /// Sets (or clears, with null/empty) the premium ROOM avatar FRAME id.
  ///
  /// Premium ROOM cosmetics are local-only string fields (a shared-catalog id)
  /// that the authoritative relay does not model, so — unlike title/avatar —
  /// they are persisted locally and propagated to members via the room snapshot
  /// fanout (which now carries `frameId`/`coverId`/`nameEmoji`). This mirrors the
  /// local description-edit tail: copyWith → bump stateVersion → persist →
  /// notify → broadcast snapshot. Gating lives in the UI (owner + premium); the
  /// controller intentionally does not gate so a kill-switch/fail-open state and
  /// snapshot-driven application behave identically.
  Future<void> setRoomFrame(String groupId, String? frameId) async {
    final db = _db;
    if (db == null) return;
    final settings = await getRoomSettings(groupId);
    final cleaned = (frameId ?? '').trim();
    final next = settings.copyWith(
      frameId: cleaned.isEmpty ? null : cleaned,
      clearFrameId: cleaned.isEmpty,
    );
    if (next.frameId == settings.frameId) return;
    await _persistRoomSettingsRecord(
      db: db,
      groupId: groupId,
      settings: _nextRoomStateVersion(next),
    );
    _invalidateListConversationsCache();
    _changed.add(null);
    await _broadcastRoomSnapshotToMembers(groupId);
  }

  /// Sets (or clears, with null/empty) the premium ROOM COVER id. See
  /// [setRoomFrame] for the local-only cosmetic sync rationale.
