  Future<void> updateRoomSettings({
    required String groupId,
    required RoomSettings settings,
  }) async {
    final db = _db;
    if (db == null) return;
    await _ensureRoomActionAllowed(groupId, RoomAction.manageSettings);
    final currentSettings = await getRoomSettings(groupId);
    final nextSettings = settings.copyWith(
      ownerProfileId: currentSettings.ownerProfileId,
    );
    final changedKeys = _roomSettingsChangedKeys(
      before: currentSettings,
      after: nextSettings,
    );
    if (_useAuthoritativeRoomRelay) {
      final relay = _relay!;
      try {
        final result = await relay.updateRoomSettings(
          roomId: groupId,
          reactionsMode: nextSettings.reactionsMode.value,
          allowText: nextSettings.allowTextMessages,
          allowMedia: nextSettings.allowMedia,
          allowAddMembers: nextSettings.allowAddMembers,
          allowPinMessages: nextSettings.allowPinMessages,
          allowChangeGroupInfo: nextSettings.allowChangeGroupInfo,
          allowChangeTag: nextSettings.allowChangeTag,
          joinApprovalRequired: nextSettings.joinApprovalRequired,
          slowModeSeconds: nextSettings.slowModeSeconds,
          chatHistoryVisible: nextSettings.chatHistoryVisible,
        );
        try {
          await _refreshRoomFromRelay(groupId);
        } catch (_) {
          await _applyRelayRoomStateWithLocalMemberships(result.room);
        }
      } catch (error) {
        await _tryRefreshRoomFromRelayBestEffort(groupId);
        if (error is RelayHttpException) {
          throw _roomSettingsUpdateFailureFromRelayHttp(error);
        }
        rethrow;
      }
      _changed.add(null);
      if (changedKeys.isNotEmpty) {
        await _broadcastRoomSystemEvent(
          groupId: groupId,
          action: RoomSystemEventAction.settingsUpdated,
          changedKeys: changedKeys,
          skipProfileId: profileId.trim(),
        );
      }
      await _broadcastAuthoritativeRoomSyncHint(groupId);
      return;
    }

    _throwIfRoomMutationAuthoritativeRelayUnavailable();

    await _persistRoomSettingsRecord(
      db: db,
      groupId: groupId,
      settings: _nextRoomStateVersion(nextSettings),
    );
    _changed.add(null);
    if (changedKeys.isNotEmpty) {
      await _broadcastRoomSystemEvent(
        groupId: groupId,
        action: RoomSystemEventAction.settingsUpdated,
        changedKeys: changedKeys,
        skipProfileId: profileId.trim(),
      );
    }
    await _broadcastRoomSnapshotToMembers(groupId);
  }

