  Future<void> setOwnRoomTag({required String groupId, String? tag}) async {
    await _ensureRoomActionAllowed(groupId, RoomAction.changeOwnTag);
    _throwIfRoomMutationAuthoritativeRelayUnavailable();
    final relay = _relay;
    if (relay == null) {
      throw RoomPolicyFailure(RoomPolicyFailureCode.serviceUnavailable);
    }
    final normalizedTag = _normalizeRoomMemberTagInput(tag);
    late final RelayRoomMembershipMutationResult result;
    try {
      result = await relay.setRoomMemberTag(
        roomId: groupId,
        tag: normalizedTag,
      );
      try {
        await _refreshRoomFromRelay(groupId);
      } catch (_) {
        await _applyRelayRoomStateWithLocalMemberships(
          result.room,
          membershipOverrides: <RelayRoomMembership>[result.membership],
        );
      }
    } catch (error) {
      await _tryRefreshRoomFromRelayBestEffort(groupId);
      if (error is RelayHttpException) {
        throw _roomMemberTagFailureFromRelayHttp(error);
      }
      rethrow;
    }
    _changed.add(null);
    if (!result.changed) {
      return;
    }
    final selfProfileId = profileId.trim();
    await _broadcastRoomSystemEvent(
      groupId: groupId,
      action: RoomSystemEventAction.memberTagUpdated,
      targetProfileId: selfProfileId,
      targetDisplayName: await _roomSystemParticipantDisplayName(selfProfileId),
      changedKeys: <String>['tag:${result.membership.tag ?? ''}'],
      skipProfileId: selfProfileId,
    );
    await _broadcastAuthoritativeRoomSyncHint(
      groupId,
      skipProfileId: selfProfileId,
    );
  }

  bool _canAssignRoomRole({
    required RoomMemberRole actorRole,
    required RoomMemberRole targetCurrentRole,
    required RoomMemberRole targetNextRole,
    required bool isTargetSelf,
  }) {
    if (isTargetSelf) {
      return false;
    }
    if (targetCurrentRole == RoomMemberRole.owner ||
        targetNextRole == RoomMemberRole.owner) {
      return false;
    }
    return switch (actorRole) {
      RoomMemberRole.owner => true,
      RoomMemberRole.admin =>
        targetCurrentRole != RoomMemberRole.admin &&
            targetNextRole != RoomMemberRole.admin,
      RoomMemberRole.moderator ||
      RoomMemberRole.member ||
      RoomMemberRole.restricted ||
      RoomMemberRole.guest => false,
    };
  }

  bool _canModerateRoomMember({
    required RoomMemberRole actorRole,
    required RoomMemberRole targetRole,
    required String actorProfileId,
    required String targetProfileId,
  }) {
    final cleanedActorProfileId = actorProfileId.trim();
    final cleanedTargetProfileId = targetProfileId.trim();
    if (cleanedActorProfileId.isEmpty ||
        cleanedTargetProfileId.isEmpty ||
        cleanedActorProfileId == cleanedTargetProfileId ||
        targetRole == RoomMemberRole.owner) {
      return false;
    }
    return switch (actorRole) {
      RoomMemberRole.owner => true,
      RoomMemberRole.admin => targetRole != RoomMemberRole.admin,
      RoomMemberRole.moderator =>
        targetRole == RoomMemberRole.member ||
            targetRole == RoomMemberRole.restricted ||
            targetRole == RoomMemberRole.guest,
      RoomMemberRole.member ||
      RoomMemberRole.restricted ||
      RoomMemberRole.guest => false,
    };
  }

  Future<void> setGroupAdmins({
    required String groupId,
    required List<String> profileIds,
    bool syncSnapshot = true,
    bool emitSystemEvents = true,
  }) async {
    final db = _db;
    if (db == null) return;
    final settings = await getRoomSettings(groupId);
    final actorProfileId = profileId.trim();
    if (actorProfileId != settings.ownerProfileId) {
      throw RoomMembershipFailure(RoomMembershipFailureCode.ownerOnly);
    }
    final activeStates = await listRoomMembershipStates(
      groupId,
      statuses: <RoomMembershipStatus>{RoomMembershipStatus.active},
    );
    final activeByProfileId = <String, GroupMembershipStateRecord>{
      for (final state in activeStates) state.profileId: state,
    };
    final cleaned = profileIds
        .map((p) => p.trim())
        .where((p) => p.isNotEmpty && activeByProfileId.containsKey(p))
        .where((p) => p != settings.ownerProfileId)
        .toSet();
    final currentAdmins = (await listGroupAdmins(groupId)).toSet();
    final comparableCurrentAdmins = currentAdmins
        .where((memberProfileId) => memberProfileId != settings.ownerProfileId)
        .toSet();
    final promotedAdmins = cleaned
        .difference(comparableCurrentAdmins)
        .toList(growable: false);
    final demotedAdmins = comparableCurrentAdmins
        .difference(cleaned)
        .toList(growable: false);
    if (promotedAdmins.isEmpty && demotedAdmins.isEmpty) {
      return;
    }

    if (_useAuthoritativeRoomRelay) {
      for (final adminProfileId in promotedAdmins) {
        await setRoomMemberRole(
          groupId: groupId,
          memberProfileId: adminProfileId,
          role: RoomMemberRole.admin,
          syncSnapshot: false,
          emitSystemEvents: false,
        );
      }
      for (final adminProfileId in demotedAdmins) {
        await setRoomMemberRole(
          groupId: groupId,
          memberProfileId: adminProfileId,
          role: RoomMemberRole.member,
          syncSnapshot: false,
          emitSystemEvents: false,
        );
      }
      if (emitSystemEvents) {
        for (final adminProfileId in promotedAdmins) {
          await _broadcastRoomSystemEvent(
            groupId: groupId,
            action: RoomSystemEventAction.adminGranted,
            targetProfileId: adminProfileId,
            targetDisplayName: await _roomSystemParticipantDisplayName(
              adminProfileId,
            ),
            skipProfileId: actorProfileId,
          );
        }
        for (final adminProfileId in demotedAdmins) {
          await _broadcastRoomSystemEvent(
            groupId: groupId,
            action: RoomSystemEventAction.adminRevoked,
            targetProfileId: adminProfileId,
            targetDisplayName: await _roomSystemParticipantDisplayName(
              adminProfileId,
            ),
            skipProfileId: actorProfileId,
          );
        }
      }
      if (!syncSnapshot) return;
      await _broadcastAuthoritativeRoomSyncHint(groupId);
      return;
    }

    _throwIfRoomMutationAuthoritativeRelayUnavailable();

    for (final membershipState in activeStates) {
      final memberProfileId = membershipState.profileId;
      if (memberProfileId == settings.ownerProfileId) {
        continue;
      }
      final nextRole = cleaned.contains(memberProfileId)
          ? RoomMemberRole.admin
          : (RoomMemberRoleX.fromValue(membershipState.role) ==
                    RoomMemberRole.admin
                ? RoomMemberRole.member
                : RoomMemberRoleX.fromValue(membershipState.role));
      await db.groupMembershipStateUpsert(
        groupId: groupId,
        profileId: memberProfileId,
        status: membershipState.status,
        role: _persistedRoomMemberRoleValue(nextRole),
        sourceLinkId: membershipState.sourceLinkId,
        tag: membershipState.tag,
        createdAtMs: membershipState.createdAtMs,
      );
    }

    await db.groupAdminsReplace(
      groupId: groupId,
      profileIds: <String>[settings.ownerProfileId, ...cleaned],
    );
    _changed.add(null);
    if (emitSystemEvents) {
      for (final adminProfileId in promotedAdmins) {
        await _broadcastRoomSystemEvent(
          groupId: groupId,
          action: RoomSystemEventAction.adminGranted,
          targetProfileId: adminProfileId,
          targetDisplayName: await _roomSystemParticipantDisplayName(
            adminProfileId,
          ),
          skipProfileId: actorProfileId,
        );
      }
      for (final adminProfileId in demotedAdmins) {
        await _broadcastRoomSystemEvent(
          groupId: groupId,
          action: RoomSystemEventAction.adminRevoked,
          targetProfileId: adminProfileId,
          targetDisplayName: await _roomSystemParticipantDisplayName(
            adminProfileId,
          ),
          skipProfileId: actorProfileId,
        );
      }
    }
    if (!syncSnapshot) return;
    await _persistRoomSettingsRecord(
      db: db,
      groupId: groupId,
      settings: _nextRoomStateAndMembershipVersion(settings),
    );
    await _broadcastRoomSnapshotToMembers(groupId);
  }

  Future<void> setRoomMemberRole({
    required String groupId,
    required String memberProfileId,
    required RoomMemberRole role,
    bool syncSnapshot = true,
    bool emitSystemEvents = true,
  }) async {
    final db = _db;
    if (db == null) return;
    final cleanedMemberProfileId = memberProfileId.trim();
    if (cleanedMemberProfileId.isEmpty) return;
    await _ensureRoomActionAllowed(groupId, RoomAction.manageMemberRoles);
    final settings = await getRoomSettings(groupId);
    if (cleanedMemberProfileId == settings.ownerProfileId ||
        role == RoomMemberRole.owner) {
      throw RoomMembershipFailure(RoomMembershipFailureCode.ownerOnly);
    }
    final actorProfileId = profileId.trim();
    final actorRole = await getRoomMemberRole(groupId);
    if (actorRole == null) {
      throw RoomMembershipFailure(RoomMembershipFailureCode.generic);
    }
    final activeStates = await listRoomMembershipStates(
      groupId,
      statuses: <RoomMembershipStatus>{RoomMembershipStatus.active},
    );
    final activeByProfileId = <String, GroupMembershipStateRecord>{
      for (final state in activeStates) state.profileId: state,
    };
    final targetState = activeByProfileId[cleanedMemberProfileId];
    if (targetState == null) {
      return;
    }
    final adminIds = (await listGroupAdmins(groupId)).toSet();
    final currentRole = _effectiveRoomMemberRole(
      profileId: cleanedMemberProfileId,
      settings: settings,
      storedRole: targetState.role,
      legacyAdminIds: adminIds,
    );
    if (currentRole == role) {
      return;
    }
    final isTargetSelf = cleanedMemberProfileId == actorProfileId;
    if (!_canAssignRoomRole(
      actorRole: actorRole,
      targetCurrentRole: currentRole,
      targetNextRole: role,
      isTargetSelf: isTargetSelf,
    )) {
      if (currentRole == RoomMemberRole.admin || role == RoomMemberRole.admin) {
        throw RoomMembershipFailure(RoomMembershipFailureCode.ownerOnly);
      }
      throw RoomMembershipFailure(RoomMembershipFailureCode.generic);
    }

    if (_useAuthoritativeRoomRelay) {
      final relay = _relay!;
      try {
        await relay.upsertRoomMembership(
          roomId: groupId,
          profileId: cleanedMemberProfileId,
          status: RoomMembershipStatus.active.value,
          role: _persistedRoomMemberRoleValue(role),
          sourceLinkId: targetState.sourceLinkId,
        );
        await _refreshRoomFromRelay(groupId);
      } catch (_) {
        await _tryRefreshRoomFromRelayBestEffort(groupId);
        rethrow;
      }
      _changed.add(null);
      if (emitSystemEvents) {
        if (role == RoomMemberRole.admin) {
          await _broadcastRoomSystemEvent(
            groupId: groupId,
            action: RoomSystemEventAction.adminGranted,
            targetProfileId: cleanedMemberProfileId,
            targetDisplayName: await _roomSystemParticipantDisplayName(
              cleanedMemberProfileId,
            ),
            skipProfileId: actorProfileId,
          );
        } else if (currentRole == RoomMemberRole.admin) {
          await _broadcastRoomSystemEvent(
            groupId: groupId,
            action: RoomSystemEventAction.adminRevoked,
            targetProfileId: cleanedMemberProfileId,
            targetDisplayName: await _roomSystemParticipantDisplayName(
              cleanedMemberProfileId,
            ),
            skipProfileId: actorProfileId,
          );
        } else {
          await _broadcastRoomSystemEvent(
            groupId: groupId,
            action: RoomSystemEventAction.roleChanged,
            targetProfileId: cleanedMemberProfileId,
            targetDisplayName: await _roomSystemParticipantDisplayName(
              cleanedMemberProfileId,
            ),
            changedKeys: <String>['role:${role.value}'],
            skipProfileId: actorProfileId,
          );
        }
      }
      if (!syncSnapshot) return;
      await _broadcastAuthoritativeRoomSyncHint(groupId);
      return;
    }

    _throwIfRoomMutationAuthoritativeRelayUnavailable();

    await db.groupMembershipStateUpsert(
      groupId: groupId,
      profileId: cleanedMemberProfileId,
      status: targetState.status,
      role: _persistedRoomMemberRoleValue(role),
      sourceLinkId: targetState.sourceLinkId,
      tag: targetState.tag,
      createdAtMs: targetState.createdAtMs,
    );

    final nextAdminProfileIds = <String>{settings.ownerProfileId};
    for (final membershipState in activeStates) {
      final memberId = membershipState.profileId;
      final effectiveRole = memberId == cleanedMemberProfileId
          ? role
          : _effectiveRoomMemberRole(
              profileId: memberId,
              settings: settings,
              storedRole: membershipState.role,
              legacyAdminIds: adminIds,
            );
      if (effectiveRole == RoomMemberRole.admin) {
        nextAdminProfileIds.add(memberId);
      }
    }
    await db.groupAdminsReplace(
      groupId: groupId,
      profileIds: nextAdminProfileIds.toList(growable: false),
    );
    _changed.add(null);
    if (emitSystemEvents) {
      if (role == RoomMemberRole.admin) {
        await _broadcastRoomSystemEvent(
          groupId: groupId,
          action: RoomSystemEventAction.adminGranted,
          targetProfileId: cleanedMemberProfileId,
          targetDisplayName: await _roomSystemParticipantDisplayName(
            cleanedMemberProfileId,
          ),
          skipProfileId: actorProfileId,
        );
      } else if (currentRole == RoomMemberRole.admin) {
        await _broadcastRoomSystemEvent(
          groupId: groupId,
          action: RoomSystemEventAction.adminRevoked,
          targetProfileId: cleanedMemberProfileId,
          targetDisplayName: await _roomSystemParticipantDisplayName(
            cleanedMemberProfileId,
          ),
          skipProfileId: actorProfileId,
        );
      } else {
        await _broadcastRoomSystemEvent(
          groupId: groupId,
          action: RoomSystemEventAction.roleChanged,
          targetProfileId: cleanedMemberProfileId,
          targetDisplayName: await _roomSystemParticipantDisplayName(
            cleanedMemberProfileId,
          ),
          changedKeys: <String>['role:${role.value}'],
          skipProfileId: actorProfileId,
        );
      }
    }
    if (!syncSnapshot) return;
    await _persistRoomSettingsRecord(
      db: db,
      groupId: groupId,
      settings: _nextRoomStateAndMembershipVersion(settings),
    );
    await _broadcastRoomSnapshotToMembers(groupId);
  }

  Future<void> addGroupMembers({
    required String groupId,
    required List<String> memberProfileIds,
  }) async {
    final db = _db;
    final selfProfileId = profileId;
    if (db == null || selfProfileId.isEmpty) return;
    await _ensureRoomActionAllowed(groupId, RoomAction.addMembers);
    final requestedMembers = <String>{
      ...memberProfileIds
          .map((memberId) => memberId.trim())
          .where((memberId) => memberId.isNotEmpty),
      selfProfileId,
    };
    final existingStates = await listRoomMembershipStates(groupId);
    final existingByProfileId = <String, GroupMembershipStateRecord>{
      for (final state in existingStates) state.profileId: state,
    };
    for (final memberId in requestedMembers) {
      final existingState = existingByProfileId[memberId];
      if (existingState == null) continue;
      if (RoomMembershipStatusX.fromValue(existingState.status) ==
          RoomMembershipStatus.banned) {
        throw RoomMembershipFailure(RoomMembershipFailureCode.memberBanned);
      }
    }

    if (_useAuthoritativeRoomRelay) {
      final relay = _relay!;
      var didChange = false;
      final addedMembers = <String>[];
      try {
        for (final memberId in requestedMembers) {
          final existingState = existingByProfileId[memberId];
          final existingStatus = existingState == null
              ? null
              : RoomMembershipStatusX.fromValue(existingState.status);
          if (existingStatus == RoomMembershipStatus.active) {
            continue;
          }
          final nextRoleValue =
              existingState != null && existingState.role.trim().isNotEmpty
              ? existingState.role.trim()
              : RoomMemberRole.member.value;
          await relay.upsertRoomMembership(
            roomId: groupId,
            profileId: memberId,
            status: RoomMembershipStatus.active.value,
            role: nextRoleValue,
            sourceLinkId: existingState?.sourceLinkId,
          );
          didChange = true;
          if (memberId != selfProfileId) {
            addedMembers.add(memberId);
          }
        }
        if (!didChange) {
          return;
        }
        await _refreshRoomFromRelay(groupId);
      } catch (_) {
        await _tryRefreshRoomFromRelayBestEffort(groupId);
        rethrow;
      }
      _changed.add(null);
      for (final memberId in addedMembers) {
        await _broadcastRoomSystemEvent(
          groupId: groupId,
          action: RoomSystemEventAction.memberAdded,
          targetProfileId: memberId,
          targetDisplayName: await _roomSystemParticipantDisplayName(memberId),
          skipProfileId: selfProfileId,
        );
      }
      await _broadcastAuthoritativeRoomSyncHint(
        groupId,
        extraProfileIds: requestedMembers,
      );
      return;
    }

    _throwIfRoomMutationAuthoritativeRelayUnavailable();

    var didChange = false;
    final addedMembers = <String>[];
    final joinedAtMs = DateTime.now().millisecondsSinceEpoch;
    for (final memberId in requestedMembers) {
      final existingState = existingByProfileId[memberId];
      final existingStatus = existingState == null
          ? null
          : RoomMembershipStatusX.fromValue(existingState.status);
      if (existingStatus == RoomMembershipStatus.active) {
        continue;
      }
      final nextRoleValue =
          existingState != null && existingState.role.trim().isNotEmpty
          ? existingState.role.trim()
          : RoomMemberRole.member.value;
      await db.groupMembershipStateUpsert(
        groupId: groupId,
        profileId: memberId,
        status: RoomMembershipStatus.active.value,
        role: nextRoleValue,
        sourceLinkId: existingState?.sourceLinkId,
        tag: existingState?.tag,
        createdAtMs: joinedAtMs,
        preserveExistingCreatedAt: false,
      );
      didChange = true;
      if (memberId != selfProfileId) {
        addedMembers.add(memberId);
      }
    }
    if (!didChange) {
      return;
    }
    final settings = await getRoomSettings(groupId);
    await _persistRoomSettingsRecord(
      db: db,
      groupId: groupId,
      settings: _nextRoomStateAndMembershipVersion(settings),
    );
    _changed.add(null);
    for (final memberId in addedMembers) {
      await _broadcastRoomSystemEvent(
        groupId: groupId,
        action: RoomSystemEventAction.memberAdded,
        targetProfileId: memberId,
        targetDisplayName: await _roomSystemParticipantDisplayName(memberId),
        skipProfileId: selfProfileId,
      );
    }
    await _broadcastRoomSnapshotToMembers(
      groupId,
      extraProfileIds: requestedMembers,
    );
  }

  Future<void> removeGroupMember({
    required String groupId,
    required String memberProfileId,
  }) async {
    final db = _db;
    if (db == null) return;
    final cleanedMemberProfileId = memberProfileId.trim();
    if (cleanedMemberProfileId.isEmpty) return;
    final selfProfileId = profileId.trim();
    RoomMemberRole? actorRole;
    if (cleanedMemberProfileId != selfProfileId) {
      await _ensureRoomActionAllowed(groupId, RoomAction.removeMembers);
      actorRole = await getRoomMemberRole(groupId);
    }
    final settings = await getRoomSettings(groupId);
    if (cleanedMemberProfileId == settings.ownerProfileId) {
      throw RoomMembershipFailure(RoomMembershipFailureCode.cannotRemoveOwner);
    }
    final existingState = await _roomMembershipStateOrLegacyActive(
      groupId,
      cleanedMemberProfileId,
    );
    final existingStatus = existingState == null
        ? null
        : RoomMembershipStatusX.fromValue(existingState.status);
    if (existingStatus != RoomMembershipStatus.active) {
      return;
    }
    final adminIds = (await listGroupAdmins(groupId)).toSet();
    final targetRole = _effectiveRoomMemberRole(
      profileId: cleanedMemberProfileId,
      settings: settings,
      storedRole: existingState?.role,
      legacyAdminIds: adminIds,
    );
    if (cleanedMemberProfileId != selfProfileId &&
        (actorRole == null ||
            !_canModerateRoomMember(
              actorRole: actorRole,
              targetRole: targetRole,
              actorProfileId: selfProfileId,
              targetProfileId: cleanedMemberProfileId,
            ))) {
      throw RoomMembershipFailure(RoomMembershipFailureCode.generic);
    }

    if (_useAuthoritativeRoomRelay && cleanedMemberProfileId != selfProfileId) {
      final relay = _relay!;
      late final RelayRoomMembershipMutationResult result;
      try {
        result = await relay.upsertRoomMembership(
          roomId: groupId,
          profileId: cleanedMemberProfileId,
          status: RoomMembershipStatus.removed.value,
          role: RoomMemberRole.member.value,
          sourceLinkId: existingState?.sourceLinkId,
        );
        await _refreshRoomFromRelay(groupId);
      } catch (_) {
        await _tryRefreshRoomFromRelayBestEffort(groupId);
        rethrow;
      }
      _changed.add(null);
      if (!result.changed) {
        return;
      }
      await _broadcastRoomSystemEvent(
        groupId: groupId,
        action: RoomSystemEventAction.memberRemoved,
        targetProfileId: cleanedMemberProfileId,
        targetDisplayName: await _roomSystemParticipantDisplayName(
          cleanedMemberProfileId,
        ),
        extraProfileIds: <String>[cleanedMemberProfileId],
        skipProfileId: selfProfileId,
      );
      await _broadcastAuthoritativeRoomSyncHint(groupId);
      await _sendAuthoritativeRoomMembershipStateToPeer(
        room: result.room,
        membership: result.membership,
      );
      return;
    }

    _throwIfRoomMutationAuthoritativeRelayUnavailable();

    final nextStatus = cleanedMemberProfileId == selfProfileId
        ? RoomMembershipStatus.left
        : RoomMembershipStatus.removed;
    final nextRoleValue =
        cleanedMemberProfileId == selfProfileId &&
            existingState != null &&
            existingState.role.trim().isNotEmpty
        ? existingState.role.trim()
        : RoomMemberRole.member.value;
    await db.groupMembershipStateUpsert(
      groupId: groupId,
      profileId: cleanedMemberProfileId,
      status: nextStatus.value,
      role: nextRoleValue,
      sourceLinkId: existingState?.sourceLinkId,
      tag: existingState?.tag,
    );
    final admins = await listGroupAdmins(groupId);
    if (admins.contains(cleanedMemberProfileId)) {
      await db.groupAdminsReplace(
        groupId: groupId,
        profileIds: admins
            .where((p) => p != cleanedMemberProfileId)
            .toList(growable: false),
      );
    }
    await _persistRoomSettingsRecord(
      db: db,
      groupId: groupId,
      settings: _nextRoomStateAndMembershipVersion(settings),
    );
    if (cleanedMemberProfileId == selfProfileId) {
      await db.convoSetArchived(convoId: groupId, archived: true);
      await db.roomCallSnapshotDelete(groupId);
    }
    _changed.add(null);
    await _broadcastRoomSystemEvent(
      groupId: groupId,
      action: cleanedMemberProfileId == selfProfileId
          ? RoomSystemEventAction.memberLeft
          : RoomSystemEventAction.memberRemoved,
      targetProfileId: cleanedMemberProfileId == selfProfileId
          ? null
          : cleanedMemberProfileId,
      targetDisplayName: cleanedMemberProfileId == selfProfileId
          ? null
          : await _roomSystemParticipantDisplayName(cleanedMemberProfileId),
      extraProfileIds: <String>[cleanedMemberProfileId],
      skipProfileId: selfProfileId,
    );
    await _broadcastRoomSnapshotToMembers(
      groupId,
      extraProfileIds: <String>[cleanedMemberProfileId],
    );
  }

