      groupId: groupId,
      profileId: cleanedMemberProfileId,
      status: RoomMembershipStatus.banned.value,
      role: RoomMemberRole.member.value,
      sourceLinkId: existingState?.sourceLinkId,
      tag: existingState?.tag,
    );
    final admins = await listGroupAdmins(groupId);
    if (admins.contains(cleanedMemberProfileId)) {
      await setGroupAdmins(
        groupId: groupId,
        profileIds: admins
            .where((profileId) => profileId != cleanedMemberProfileId)
            .toList(growable: false),
        syncSnapshot: false,
        emitSystemEvents: false,
      );
    }
    await _persistRoomSettingsRecord(
      db: db,
      groupId: groupId,
      settings: _nextRoomStateAndMembershipVersion(settings),
    );
    if (cleanedMemberProfileId == profileId.trim()) {
      await db.convoSetArchived(convoId: groupId, archived: true);
      await db.roomCallSnapshotDelete(groupId);
    }
    _changed.add(null);
    await _broadcastRoomSystemEvent(
      groupId: groupId,
      action: RoomSystemEventAction.memberBanned,
      targetProfileId: cleanedMemberProfileId,
      targetDisplayName: await _roomSystemParticipantDisplayName(
        cleanedMemberProfileId,
      ),
      extraProfileIds: <String>[cleanedMemberProfileId],
      skipProfileId: profileId.trim(),
    );
    await _broadcastRoomSnapshotToMembers(
      groupId,
      extraProfileIds: <String>[cleanedMemberProfileId],
    );
  }

  Future<void> unbanRoomMember({
    required String groupId,
    required String memberProfileId,
  }) async {
    final db = _db;
    if (db == null) return;
    await _ensureRoomActionAllowed(groupId, RoomAction.banMembers);
    final existingState = await _roomMembershipStateOrLegacyActive(
      groupId,
      memberProfileId,
    );
    if (existingState == null ||
        RoomMembershipStatusX.fromValue(existingState.status) !=
            RoomMembershipStatus.banned) {
      return;
    }

    if (_useAuthoritativeRoomRelay) {
      final relay = _relay!;
      late final RelayRoomMembershipMutationResult result;
      try {
        result = await relay.unbanRoomMember(
          roomId: groupId,
          profileId: memberProfileId,
        );
        await _refreshRoomFromRelay(groupId);
      } catch (_) {
        await _tryRefreshRoomFromRelayBestEffort(groupId);
        rethrow;
      }
      _changed.add(null);
      if (!result.changed) {
        return;
      }
      await _broadcastRoomSystemEvent(
        groupId: groupId,
        action: RoomSystemEventAction.memberUnbanned,
        targetProfileId: memberProfileId,
        targetDisplayName: await _roomSystemParticipantDisplayName(
          memberProfileId,
        ),
        extraProfileIds: <String>[memberProfileId.trim()],
        skipProfileId: profileId.trim(),
      );
      await _broadcastAuthoritativeRoomSyncHint(groupId);
      await _sendAuthoritativeRoomMembershipStateToPeer(
        room: result.room,
        membership: result.membership,
      );
      return;
    }

    _throwIfRoomMutationAuthoritativeRelayUnavailable();

    await db.groupMembershipStateUpsert(
      groupId: groupId,
      profileId: memberProfileId,
      status: RoomMembershipStatus.removed.value,
      role: RoomMemberRole.member.value,
      sourceLinkId: existingState.sourceLinkId,
      tag: existingState.tag,
    );
    final settings = await getRoomSettings(groupId);
    await _persistRoomSettingsRecord(
      db: db,
      groupId: groupId,
      settings: _nextRoomStateAndMembershipVersion(settings),
    );
    _changed.add(null);
    await _broadcastRoomSystemEvent(
      groupId: groupId,
      action: RoomSystemEventAction.memberUnbanned,
      targetProfileId: memberProfileId,
      targetDisplayName: await _roomSystemParticipantDisplayName(
        memberProfileId,
      ),
      extraProfileIds: <String>[memberProfileId.trim()],
      skipProfileId: profileId.trim(),
    );
    await _broadcastRoomSnapshotToMembers(
      groupId,
      extraProfileIds: <String>[memberProfileId.trim()],
    );
  }

  Future<void> transferRoomOwnership({
    required String groupId,
    required String nextOwnerProfileId,
  }) async {
    final db = _db;
    final selfProfileId = profileId.trim();
    final cleanedNextOwnerProfileId = nextOwnerProfileId.trim();
    if (db == null ||
        selfProfileId.isEmpty ||
        cleanedNextOwnerProfileId.isEmpty) {
      return;
    }
    final settings = await getRoomSettings(groupId);
    if (settings.ownerProfileId != selfProfileId) {
      throw RoomMembershipFailure(RoomMembershipFailureCode.ownerOnly);
    }
    if (cleanedNextOwnerProfileId == selfProfileId) {
      throw RoomMembershipFailure(
        RoomMembershipFailureCode.ownerTransferTargetInvalid,
      );
    }
    final activeMembers = (await listGroupMembers(groupId)).toSet();
    if (!activeMembers.contains(cleanedNextOwnerProfileId)) {
      throw RoomMembershipFailure(
        RoomMembershipFailureCode.ownerTransferTargetInvalid,
      );
    }

    if (_useAuthoritativeRoomRelay) {
      final relay = _relay!;
      try {
        await relay.transferRoomOwnership(
          roomId: groupId,
          nextOwnerProfileId: cleanedNextOwnerProfileId,
        );
        await _refreshRoomFromRelay(groupId);
      } catch (_) {
        await _tryRefreshRoomFromRelayBestEffort(groupId);
        rethrow;
      }
      _changed.add(null);
      await _broadcastRoomSystemEvent(
        groupId: groupId,
        action: RoomSystemEventAction.ownerTransferred,
        targetProfileId: cleanedNextOwnerProfileId,
        targetDisplayName: await _roomSystemParticipantDisplayName(
          cleanedNextOwnerProfileId,
        ),
        skipProfileId: selfProfileId,
      );
      await _broadcastAuthoritativeRoomSyncHint(groupId);
      return;
    }

    _throwIfRoomMutationAuthoritativeRelayUnavailable();

    final currentOwnerState = await _roomMembershipStateOrLegacyActive(
      groupId,
      selfProfileId,
    );
    if (currentOwnerState != null) {
      await db.groupMembershipStateUpsert(
        groupId: groupId,
        profileId: selfProfileId,
        status: currentOwnerState.status,
        role: RoomMemberRole.admin.value,
        sourceLinkId: currentOwnerState.sourceLinkId,
        tag: currentOwnerState.tag,
        createdAtMs: currentOwnerState.createdAtMs,
      );
    }
    final nextOwnerState = await _roomMembershipStateOrLegacyActive(
      groupId,
      cleanedNextOwnerProfileId,
    );
    if (nextOwnerState != null) {
      await db.groupMembershipStateUpsert(
        groupId: groupId,
        profileId: cleanedNextOwnerProfileId,
        status: nextOwnerState.status,
        role: RoomMemberRole.admin.value,
        sourceLinkId: nextOwnerState.sourceLinkId,
        tag: nextOwnerState.tag,
        createdAtMs: nextOwnerState.createdAtMs,
      );
    }
    final nextAdmins =
        <String>{
              ...await listGroupAdmins(groupId),
              selfProfileId,
              cleanedNextOwnerProfileId,
            }
            .where((profileId) => activeMembers.contains(profileId))
            .toList(growable: false);
    await db.groupAdminsReplace(groupId: groupId, profileIds: nextAdmins);
    await _persistRoomSettingsRecord(
      db: db,
      groupId: groupId,
      settings: _nextRoomStateAndMembershipVersion(
        settings.copyWith(ownerProfileId: cleanedNextOwnerProfileId),
      ),
    );
    _changed.add(null);
    await _broadcastRoomSystemEvent(
      groupId: groupId,
      action: RoomSystemEventAction.ownerTransferred,
      targetProfileId: cleanedNextOwnerProfileId,
      targetDisplayName: await _roomSystemParticipantDisplayName(
        cleanedNextOwnerProfileId,
      ),
      skipProfileId: selfProfileId,
    );
    await _broadcastRoomSnapshotToMembers(groupId);
  }

  Future<bool> isRoomAdmin(String groupId, {String? profileIdOverride}) async {
    final role = await getRoomMemberRole(
      groupId,
      profileIdOverride: profileIdOverride,
    );
    return role == RoomMemberRole.owner || role == RoomMemberRole.admin;
  }

  Future<RoomPolicyState> getRoomPolicyState(
    String groupId, {
    String? profileIdOverride,
    int? nowMs,
  }) async {
    final db = _db;
    final pid = (profileIdOverride ?? profileId).trim();
    final settings = await getRoomSettings(groupId);
    final membershipState = pid.isEmpty
        ? null
        : await _roomMembershipStateOrLegacyActive(groupId, pid);
    final isMember =
        membershipState != null &&
        RoomMembershipStatusX.fromValue(membershipState.status) ==
            RoomMembershipStatus.active;
    final adminIds = (await listGroupAdmins(groupId)).toSet();
    final role = isMember
        ? _effectiveRoomMemberRole(
            profileId: pid,
            settings: settings,
            storedRole: membershipState.role,
            legacyAdminIds: adminIds,
          )
        : RoomMemberRole.member;
    int? lastOwnMessageAtMs;
    int? nextAllowedAtMs;
    if (!role.canBypassPostingPolicy &&
        db != null &&
        _deviceId != null &&
        settings.slowModeSeconds > 0) {
      lastOwnMessageAtMs = await db.groupLatestOwnPostAtMs(
        groupId: groupId,
        senderDeviceId: _deviceId!,
      );
      if (pid.isNotEmpty) {
        nextAllowedAtMs = await db.groupPostingStateNextAllowedAtMs(
          groupId: groupId,
          profileId: pid,
        );
      }
    }
    return evaluateRoomPolicyState(
      settings: settings,
      isMember: isMember,
      role: role,
      lastOwnMessageAtMs: lastOwnMessageAtMs,
      nextAllowedAtMs: nextAllowedAtMs,
      nowMs: nowMs,
    );
  }

  Future<void> _ensureRoomActionAllowed(
    String groupId,
    RoomAction action, {
    String? emoji,
    String? profileIdOverride,
    int? nowMs,
  }) async {
    final policy = await getRoomPolicyState(
      groupId,
      profileIdOverride: profileIdOverride,
      nowMs: nowMs,
    );
    ensureRoomActionAllowed(policy, action, emoji: emoji);
  }

  int? _normalizeRoomInviteExpiresAtMs(int? value) {
    if (value == null || value <= 0) {
      return null;
    }
    return value;
  }

  int? _normalizeRoomInviteMaxUses(int? value) {
    if (value == null || value <= 0) {
      return null;
    }
    return value;
  }

  RoomMemberRole _normalizeRoomInviteAllowedRole(RoomMemberRole role) {
    return switch (role) {
      RoomMemberRole.member ||
      RoomMemberRole.restricted ||
      RoomMemberRole.guest => role,
      RoomMemberRole.owner ||
      RoomMemberRole.admin ||
      RoomMemberRole.moderator => RoomMemberRole.member,
    };
  }

  bool _roomInviteStatusCanBypassAvailability(
    RoomMembershipStatus? membershipStatus,
  ) {
    return membershipStatus == RoomMembershipStatus.active ||
        membershipStatus == RoomMembershipStatus.pending ||
        membershipStatus == RoomMembershipStatus.banned;
  }

  bool _effectiveRoomInviteJoinApprovalRequired(
    RoomSettings settings,
    RoomInviteLink link,
  ) {
    return settings.joinApprovalRequired || link.requiresApproval;
  }

  RoomInviteFailure? _roomInviteAvailabilityFailure(
    RoomInviteLink link, {
    int? nowMs,
  }) {
    if (link.revoked) {
      return const RoomInviteFailure(RoomInviteFailureCode.inviteRevoked);
    }
    final effectiveNowMs = nowMs ?? DateTime.now().millisecondsSinceEpoch;
    if (link.isExpiredAt(effectiveNowMs)) {
      return const RoomInviteFailure(RoomInviteFailureCode.inviteExpired);
    }
    if (link.isUsageLimitReached) {
      return const RoomInviteFailure(
        RoomInviteFailureCode.inviteUsageLimitReached,
      );
    }
    return null;
  }

  RoomInviteLink _roomInviteLinkFromRow(
    Map<String, Object?> row, {
    required String fallbackGroupId,
  }) {
    final allowedRole = _normalizeRoomInviteAllowedRole(
      RoomMemberRoleX.fromValue((row['allowed_role'] as String?) ?? 'member'),
    );
    return RoomInviteLink(
      linkId: (row['link_id'] as String?) ?? '',
      groupId: (row['group_id'] as String?) ?? fallbackGroupId,
      slug: (row['slug'] as String?) ?? '',
      createdByProfileId: (row['created_by_profile_id'] as String?) ?? '',
      expiresAtMs: _normalizeRoomInviteExpiresAtMs(
        (row['expires_at_ms'] as num?)?.toInt(),
      ),
      maxUses: _normalizeRoomInviteMaxUses((row['max_uses'] as num?)?.toInt()),
      useCount: ((row['use_count'] as num?)?.toInt() ?? 0) < 0
          ? 0
          : (row['use_count'] as num?)?.toInt() ?? 0,
      requiresApproval: ((row['requires_approval'] as num?)?.toInt() ?? 0) != 0,
      allowedRole: allowedRole,
      revoked: ((row['is_revoked'] as num?)?.toInt() ?? 0) != 0,
      createdAtMs: (row['created_at_ms'] as num?)?.toInt() ?? 0,
      updatedAtMs: (row['updated_at_ms'] as num?)?.toInt() ?? 0,
    );
  }

  String buildRoomInviteDeepLink(RoomInviteLink link) =>
      link.internalDeepLinkUrl;

  @visibleForTesting
  static String encodeRoomInviteCommandForTesting(
    Map<String, Object?> payload,
  ) {
    return _encodeCommandPayload(_roomInviteCmdPrefix, payload);
  }

  @visibleForTesting
  static String encodeGroupMessageCommandForTesting(
    Map<String, Object?> payload,
  ) {
    return _encodeCommandPayload(_groupMsgCmdPrefix, payload);
  }

  Future<List<RoomInviteLink>> listRoomInviteLinks(String groupId) async {
    final db = _db;
    if (db == null) return const <RoomInviteLink>[];
    final rows = await db.groupInviteLinksList(groupId);
    return rows
        .map((r) => _roomInviteLinkFromRow(r, fallbackGroupId: groupId))
        .where((link) => link.linkId.isNotEmpty && link.slug.isNotEmpty)
        .toList(growable: false);
  }

  Future<RoomInviteLink> createRoomInviteLink(
    String groupId, {
    int? expiresAtMs,
    int? maxUses,
    bool requiresApproval = false,
    RoomMemberRole allowedRole = RoomMemberRole.member,
  }) async {
    final db = _db;
    final selfProfileId = profileId;
    if (db == null || selfProfileId.isEmpty) {
      throw StateError('Profile is not ready');
    }
    await _ensureRoomActionAllowed(groupId, RoomAction.manageInviteLinks);
    final normalizedAllowedRole = _normalizeRoomInviteAllowedRole(allowedRole);
    final normalizedExpiresAtMs = _normalizeRoomInviteExpiresAtMs(expiresAtMs);
    final normalizedMaxUses = _normalizeRoomInviteMaxUses(maxUses);

    if (_useAuthoritativeRoomRelay) {
      final relay = _relay!;
      late final RelayRoomInviteLinkMutationResult result;
      try {
        result = await relay.createRoomInviteLink(
          roomId: groupId,
          expiresAtMs: normalizedExpiresAtMs,
          maxUses: normalizedMaxUses,
          requiresApproval: requiresApproval,
          allowedRole: normalizedAllowedRole.value,
        );
        await _refreshRoomFromRelay(groupId, includeInviteLinks: true);
      } catch (_) {
        await _tryRefreshRoomFromRelayBestEffort(
          groupId,
          includeInviteLinks: true,
        );
        rethrow;
      }
      _changed.add(null);
      await _broadcastAuthoritativeRoomSyncHint(
        groupId,
        includeInviteLinks: true,
        inviteManagersOnly: true,
      );
      return _roomInviteLinkFromRelay(result.inviteLink);
    }

    _throwIfRoomMutationAuthoritativeRelayUnavailable();

    final nowMs = DateTime.now().millisecondsSinceEpoch;
    final link = RoomInviteLink(
      linkId: _uuid.v4(),
      groupId: groupId,
      slug: _uuid.v4().replaceAll('-', '').substring(0, 16),
      createdByProfileId: selfProfileId,
      expiresAtMs: normalizedExpiresAtMs,
      maxUses: normalizedMaxUses,
      useCount: 0,
      requiresApproval: requiresApproval,
      allowedRole: normalizedAllowedRole,
      revoked: false,
      createdAtMs: nowMs,
      updatedAtMs: nowMs,
    );
    await db.groupInviteLinkUpsert(
      linkId: link.linkId,
      groupId: link.groupId,
      slug: link.slug,
      createdByProfileId: link.createdByProfileId,
      createdAtMs: link.createdAtMs,
      updatedAtMs: link.updatedAtMs,
      expiresAtMs: link.expiresAtMs,
      maxUses: link.maxUses,
      useCount: link.useCount,
      requiresApproval: link.requiresApproval,
      allowedRole: link.allowedRole.value,
      revoked: link.revoked,
    );
    final settings = await getRoomSettings(groupId);
    await _persistRoomSettingsRecord(
      db: db,
      groupId: groupId,
      settings: _nextRoomStateVersion(settings),
    );
    _changed.add(null);
    await _broadcastRoomSnapshotToMembers(groupId);
    return link;
  }

  Future<void> setRoomInviteLinkRevoked({
    required String linkId,
    required bool revoked,
  }) async {
    final db = _db;
    if (db == null) return;
    final existing = await db.groupInviteLinkGet(linkId);
    final groupId = (existing?['group_id'] as String?)?.trim();
    final alreadyRevoked =
        ((existing?['is_revoked'] as num?)?.toInt() ?? 0) != 0;
    if (existing != null && alreadyRevoked == revoked) {
      return;
    }
    if (groupId != null && groupId.isNotEmpty) {
      await _ensureRoomActionAllowed(groupId, RoomAction.manageInviteLinks);
    }

    if (_useAuthoritativeRoomRelay && groupId != null && groupId.isNotEmpty) {
      final relay = _relay!;
      try {
        await relay.setRoomInviteLinkRevoked(
          roomId: groupId,
          linkId: linkId,
          revoked: revoked,
        );
        await _refreshRoomFromRelay(groupId, includeInviteLinks: true);
      } catch (_) {
        await _tryRefreshRoomFromRelayBestEffort(
          groupId,
          includeInviteLinks: true,
        );
        rethrow;
      }
      _changed.add(null);
      await _broadcastAuthoritativeRoomSyncHint(
        groupId,
        includeInviteLinks: true,
        inviteManagersOnly: true,
      );
      return;
    }

    _throwIfRoomMutationAuthoritativeRelayUnavailable();

    await db.groupInviteLinkSetRevoked(linkId: linkId, revoked: revoked);
    if (groupId != null && groupId.isNotEmpty) {
      final settings = await getRoomSettings(groupId);
      await _persistRoomSettingsRecord(
        db: db,
        groupId: groupId,
        settings: _nextRoomStateVersion(settings),
      );
      await _broadcastRoomSnapshotToMembers(groupId);
    }
    _changed.add(null);
  }

  RoomInviteFailure? _roomInviteFailureFromRelayAvailability(
    String availability,
  ) {
    return switch (availability.trim()) {
      'revoked' => const RoomInviteFailure(RoomInviteFailureCode.inviteRevoked),
      'expired' => const RoomInviteFailure(RoomInviteFailureCode.inviteExpired),
      'usage_limit_reached' => const RoomInviteFailure(
        RoomInviteFailureCode.inviteUsageLimitReached,
      ),
      'banned' => const RoomInviteFailure(RoomInviteFailureCode.banned),
      _ => null,
    };
  }

  RoomInviteFailure _roomInviteFailureFromRelayHttp(Object error) {
    if (error is RoomInviteFailure) {
      return error;
    }
    if (error is RelayHttpException) {
      return switch (error.statusCode) {
        403 => const RoomInviteFailure(RoomInviteFailureCode.banned),
        404 => const RoomInviteFailure(RoomInviteFailureCode.inviteNotFound),
        409 => const RoomInviteFailure(
          RoomInviteFailureCode.inviteUsageLimitReached,
        ),
        410 => RoomInviteFailure(
          RoomInviteFailureCode.generic,
          message: error.responseBody ?? error.toString(),
        ),
        _ => RoomInviteFailure(
          RoomInviteFailureCode.generic,
          message: error.responseBody ?? error.toString(),
        ),
      };
    }
    return RoomInviteFailure(
      RoomInviteFailureCode.generic,
      message: error.toString(),
    );
  }

  Future<RoomInvitePreview> _buildRoomInvitePreviewFromRelay({
    required RoomInviteTarget target,
    required RelayRoomInvitePreview preview,
  }) async {
    final requesterMembership = preview.requesterMembership;
    final viewerMembershipStatus = requesterMembership == null
        ? null
        : RoomMembershipStatusX.fromValue(requesterMembership.status);
    Uint8List? avatarBytes;
    final avatarImageB64 = (preview.room.avatarImageB64 ?? '').trim();
    if (avatarImageB64.isNotEmpty) {
      try {
        final decoded = base64Decode(avatarImageB64);
        if (decoded.isNotEmpty) {
          avatarBytes = Uint8List.fromList(decoded);
        }
      } catch (_) {
        // ignore malformed avatar payloads
      }
    }
    final inviterDisplayName = (await resolveConvoTitle(
      target.inviterProfileId,
    )).trim();
    return RoomInvitePreview(
      target: target,
      groupId: preview.room.roomId,
      groupTitle: preview.room.title.trim().isEmpty
          ? 'Room'
          : preview.room.title.trim(),
      description: (preview.room.description ?? '').trim().isEmpty
          ? null
          : preview.room.description?.trim(),
      inviterDisplayName: inviterDisplayName.isEmpty
          ? target.inviterProfileId
          : inviterDisplayName,
      memberCount: preview.activeMemberCount < 0
          ? 0
          : preview.activeMemberCount,
      isAlreadyMember: viewerMembershipStatus == RoomMembershipStatus.active,
      joinApprovalRequired:
          preview.room.joinApprovalRequired ||
          preview.inviteLink.requiresApproval,
      viewerMembershipStatus: viewerMembershipStatus,
      chatHistoryVisible: preview.room.chatHistoryVisible,
      allowedRole: _normalizeRoomInviteAllowedRole(
        RoomMemberRoleX.fromValue(preview.inviteLink.allowedRole),
      ),
      expiresAtMs: _normalizeRoomInviteExpiresAtMs(
        preview.inviteLink.expiresAtMs,
      ),
      maxUses: _normalizeRoomInviteMaxUses(preview.inviteLink.maxUses),
      remainingUses: preview.inviteLink.remainingUses,
      avatarPath: null,
      avatarHash: preview.room.avatarHash,
      avatarBytes: avatarBytes,
    );
  }

  Future<void> _applyRelayRoomInviteRedeemResult(
    RelayRoomInviteRedeemResult result,
  ) async {
    try {
      await _refreshRoomFromRelay(result.room.roomId);
    } catch (_) {
      await _applyRelayRoomSnapshot(
        room: result.room,
        memberships: <RelayRoomMembership>[result.membership],
      );
    }
  }

  Future<RoomInvitePreview> resolveRoomInviteTarget(
    RoomInviteTarget target,
  ) async {
    final inviterProfileId = target.inviterProfileId.trim();
    final slug = target.slug.trim();
    if (inviterProfileId.isEmpty || slug.isEmpty) {
      throw const RoomInviteFailure(RoomInviteFailureCode.invalidLink);
    }

    final joinedPreview = await _buildJoinedRoomInvitePreview(target);
    if (joinedPreview != null) {
      return joinedPreview;
    }

    final localState = await _loadLocalRoomInviteState(target);
    if (localState != null) {
      final availabilityFailure = _roomInviteAvailabilityFailure(
        localState.link,
      );
      if (availabilityFailure != null &&
          !_roomInviteStatusCanBypassAvailability(
            localState.currentUserMembershipStatus,
          )) {
        throw availabilityFailure;
      }
      return _buildRoomInvitePreview(
        target: target,
        state: localState,
        inviterDisplayName: await resolveConvoTitle(inviterProfileId),
        isAlreadyMember: localState.isCurrentUserMember,
      );
    }

    if (inviterProfileId == profileId.trim()) {
      throw const RoomInviteFailure(RoomInviteFailureCode.inviteNotFound);
    }

    try {
      await refreshProfileMeta(inviterProfileId);
    } catch (_) {
      // ignore
    }

    final relay = _relay;
    if (relay != null && !_transportBlocked) {
      try {
        final relayPreview = await relay.previewRoomInvite(slug: slug);
        final preview = await _buildRoomInvitePreviewFromRelay(
          target: target,
          preview: relayPreview,
        );
        final availabilityFailure = _roomInviteFailureFromRelayAvailability(
          relayPreview.availability,
        );
        if (availabilityFailure != null &&
            !_roomInviteStatusCanBypassAvailability(
              preview.viewerMembershipStatus,
            )) {
          throw availabilityFailure;
        }
        return preview;
      } catch (error) {
        if (error is RelayHttpException &&
            <int>{403, 404, 409, 410}.contains(error.statusCode)) {
          throw _roomInviteFailureFromRelayHttp(error);
        }
        if (error is RoomInviteFailure) {
          rethrow;
        }
        throw const RoomInviteFailure(
          RoomInviteFailureCode.inviteCreatorUnavailable,
        );
      }
    }
    throw const RoomInviteFailure(
      RoomInviteFailureCode.inviteCreatorUnavailable,
    );
  }

  Future<RoomInviteJoinOutcome> joinRoomViaInvite(
    RoomInviteTarget target, {
    RoomInvitePreview? preview,
  }) async {
    final resolvedPreview = preview ?? await resolveRoomInviteTarget(target);
    if (resolvedPreview.isAlreadyMember) {
      return RoomInviteJoinOutcome(
        groupId: resolvedPreview.groupId,
        groupTitle: resolvedPreview.groupTitle,
        disposition: RoomInviteJoinDisposition.active,
      );
    }

    // Monetization §C-3: cap how many groups a Free profile may JOIN. Inert
    // while monetization is disabled (unlimited). Existing memberships are
    // never affected — the already-member case short-circuits above.
    final joinedNow = await joinedGroupCount();
    if (!FeatureGate.canJoinGroup(entitlementStateNow, joinedNow)) {
      throw const FeatureLockedException(
        GatedFeature.group,
        'group_join_limit',
      );
    }

    final relay = _relay;
    if (relay != null && !_transportBlocked) {
      try {
        final result = await relay.redeemRoomInvite(slug: target.slug);
        await _applyRelayRoomInviteRedeemResult(result);
        _changed.add(null);
        return RoomInviteJoinOutcome(
          groupId: result.room.roomId,
          groupTitle: result.room.title.trim().isEmpty
              ? 'Room'
              : result.room.title.trim(),
          disposition: result.disposition == 'pending_approval'
              ? RoomInviteJoinDisposition.pendingApproval
              : RoomInviteJoinDisposition.active,
        );
      } catch (error) {
        if (error is RelayHttpException &&
            <int>{403, 404, 409, 410}.contains(error.statusCode)) {
          throw _roomInviteFailureFromRelayHttp(error);
        }
        if (error is RoomInviteFailure) {
          rethrow;
        }
        throw const RoomInviteFailure(
          RoomInviteFailureCode.inviteCreatorUnavailable,
        );
      }
    }

    throw const RoomInviteFailure(
      RoomInviteFailureCode.inviteCreatorUnavailable,
    );
  }

  Future<_LocalRoomInviteState?> _loadLocalRoomInviteState(
    RoomInviteTarget target,
  ) async {
    final db = _db;
    if (db == null) return null;
    final row = await db.groupInviteLinkGetBySlug(
      slug: target.slug,
      createdByProfileId: target.inviterProfileId,
    );
    if (row == null) return null;
    final link = _roomInviteLinkFromRow(
      row,
      fallbackGroupId: target.groupIdHint ?? '',
    );
    if (link.linkId.isEmpty || link.groupId.isEmpty) {
      return null;
    }

    final convo = await db.convoGet(link.groupId);
    final convoTitle = ((convo?['title'] as String?) ?? '').trim();
    final settings = await getRoomSettings(link.groupId);
    final membershipStates = await listRoomMembershipStates(link.groupId);
    final membershipByProfileId = <String, GroupMembershipStateRecord>{
      for (final membershipState in membershipStates)
        membershipState.profileId: membershipState,
    };
    final memberProfileIds = membershipStates
        .where(
          (membershipState) =>
              RoomMembershipStatusX.fromValue(membershipState.status) ==
              RoomMembershipStatus.active,
        )
        .map((membershipState) => membershipState.profileId)
        .toSet()
        .toList(growable: false);
    final adminProfileIds = (await listGroupAdmins(
      link.groupId,
    )).toSet().toList(growable: false);
    final currentUserMembershipStatus = profileId.trim().isEmpty
        ? null
        : (membershipByProfileId[profileId.trim()] == null
              ? null
              : RoomMembershipStatusX.fromValue(
                  membershipByProfileId[profileId.trim()]!.status,
                ));
    return _LocalRoomInviteState(
      link: link,
      groupTitle: convoTitle.isEmpty ? 'Room' : convoTitle,
      description: settings.description,
      memberCount: memberProfileIds.length,
      settings: settings,
      membershipStates: membershipStates,
      memberProfileIds: memberProfileIds,
      adminProfileIds: adminProfileIds,
      currentUserMembershipStatus: currentUserMembershipStatus,
      isCurrentUserMember:
          currentUserMembershipStatus == RoomMembershipStatus.active,
    );
  }

  Future<RoomInvitePreview?> _buildJoinedRoomInvitePreview(
    RoomInviteTarget target,
  ) async {
    final groupId = (target.groupIdHint ?? '').trim();
    final selfProfileId = profileId.trim();
    if (groupId.isEmpty || selfProfileId.isEmpty) return null;
    final memberProfileIds = (await listGroupMembers(
      groupId,
    )).toSet().toList(growable: false);
    if (!memberProfileIds.contains(selfProfileId)) return null;
    final db = _db;
    if (db == null) return null;
    final convo = await db.convoGet(groupId);
    final convoTitle = ((convo?['title'] as String?) ?? '').trim();
    final settings = await getRoomSettings(groupId);
    final role = await getRoomMemberRole(
      groupId,
      profileIdOverride: selfProfileId,
    );
    return RoomInvitePreview(
      target: target,
      groupId: groupId,
      groupTitle: convoTitle.isEmpty ? 'Room' : convoTitle,
      description: settings.description,
      inviterDisplayName: await resolveConvoTitle(target.inviterProfileId),
      memberCount: memberProfileIds.length,
      isAlreadyMember: true,
      joinApprovalRequired: settings.joinApprovalRequired,
      viewerMembershipStatus: RoomMembershipStatus.active,
      chatHistoryVisible: settings.chatHistoryVisible,
      allowedRole: role ?? RoomMemberRole.member,
      expiresAtMs: null,
      maxUses: null,
      remainingUses: null,
      avatarPath: settings.avatarPath,
      avatarHash: settings.avatarHash,
      avatarBytes: null,
    );
  }

  RoomInvitePreview _buildRoomInvitePreview({
    required RoomInviteTarget target,
    required _LocalRoomInviteState state,
    required String inviterDisplayName,
    required bool isAlreadyMember,
  }) {
    return RoomInvitePreview(
      target: target,
      groupId: state.link.groupId,
      groupTitle: state.groupTitle,
      description: state.description,
      inviterDisplayName: inviterDisplayName.trim().isEmpty
          ? target.inviterProfileId
          : inviterDisplayName.trim(),
      memberCount: state.memberCount,
      isAlreadyMember: isAlreadyMember,
      joinApprovalRequired: _effectiveRoomInviteJoinApprovalRequired(
        state.settings,
        state.link,
      ),
      viewerMembershipStatus: state.currentUserMembershipStatus,
      chatHistoryVisible: state.settings.chatHistoryVisible,
      allowedRole: state.link.allowedRole,
      expiresAtMs: state.link.expiresAtMs,
      maxUses: state.link.maxUses,
      remainingUses: state.link.remainingUses,
      avatarPath: state.settings.avatarPath,
      avatarHash: state.settings.avatarHash,
      avatarBytes: null,
    );
  }

  Future<void> _sendRoomInviteControl({
    required String peerProfileId,
    required Map<String, Object?> payload,
    bool strict = false,
    bool queueIfNoDevices = false,
    bool forceRelayFlush = false,
    String? retryBucket,
    String? transportMetaJson,
  }) {
    return sendControlMessage(
      peerProfileId: peerProfileId,
      controlText: _encodeCommandPayload(_roomInviteCmdPrefix, payload),
      strict: strict,
      queueIfNoDevices: queueIfNoDevices,
      forceRelayFlush: forceRelayFlush,
      retryBucket: retryBucket,
      transportMetaJson: transportMetaJson,
    );
  }

  Future<Map<String, Object?>> _buildRoomSnapshotPayload(
    String groupId, {
    bool includeInviteLinks = false,
  }) async {
    final db = _db;
    if (db == null) throw StateError('Database is not ready');
    final convo = await db.convoGet(groupId);
    final convoTitle = ((convo?['title'] as String?) ?? '').trim();
    final settings = await getRoomSettings(groupId);
    final avatarSnapshot = await _buildRoomAvatarSnapshotFields(settings);
    final membershipStates = await listRoomMembershipStates(groupId);
    final legacyAdminIds = (await listGroupAdmins(groupId)).toSet();
    final members = membershipStates
        .where(
          (membershipState) =>
              RoomMembershipStatusX.fromValue(membershipState.status) ==
              RoomMembershipStatus.active,
        )
        .map((membershipState) => membershipState.profileId)
        .toSet()
        .toList(growable: false);
    final admins = membershipStates
        .where(
          (membershipState) =>
              RoomMembershipStatusX.fromValue(membershipState.status) ==
              RoomMembershipStatus.active,
        )
        .where(
          (membershipState) =>
              _effectiveRoomMemberRole(
                    profileId: membershipState.profileId,
                    settings: settings,
                    storedRole: membershipState.role,
                    legacyAdminIds: legacyAdminIds,
                  ) ==
                  RoomMemberRole.owner ||
              _effectiveRoomMemberRole(
                    profileId: membershipState.profileId,
                    settings: settings,
                    storedRole: membershipState.role,
                    legacyAdminIds: legacyAdminIds,
                  ) ==
                  RoomMemberRole.admin,
        )
        .map((membershipState) => membershipState.profileId)
        .toSet()
        .toList(growable: false);
    final payload = <String, Object?>{
      'v': 1,
      'action': 'snapshot',
      'groupId': groupId,
      'groupTitle': convoTitle.isEmpty ? 'Room' : convoTitle,
      'avatarHash': avatarSnapshot.avatarHash,
      'avatarImageB64': avatarSnapshot.avatarImageB64,
      'description': settings.description,
      'ownerProfileId': settings.ownerProfileId,
      'reactionsMode': settings.reactionsMode.value,
      'allowTextMessages': settings.allowTextMessages,
      'allowMedia': settings.allowMedia,
      'allowAddMembers': settings.allowAddMembers,
      'allowPinMessages': settings.allowPinMessages,
      'allowChangeGroupInfo': settings.allowChangeGroupInfo,
      'allowChangeTag': settings.allowChangeTag,
      'joinApprovalRequired': settings.joinApprovalRequired,
      'slowModeSeconds': settings.slowModeSeconds,
      'chatHistoryVisible': settings.chatHistoryVisible,
      'pinnedMessageEventId': settings.pinnedMessageEventId,
      // Premium ROOM cosmetics (additive; old clients ignore unknown keys).
      'coverId': settings.coverId,
      'frameId': settings.frameId,
      'nameEmoji': settings.nameEmoji,
      'membershipVersion': settings.membershipVersion > 0
          ? settings.membershipVersion
          : (membershipStates.isNotEmpty ? 1 : 0),
      'stateVersion': settings.stateVersion > 0 ? settings.stateVersion : 1,
      'memberProfileIds': members,
      'adminProfileIds': admins,
      'membershipStates': membershipStates
          .map(
            (membershipState) => <String, Object?>{
              'profileId': membershipState.profileId,
              'status': membershipState.status,
              'role': membershipState.role.trim().isEmpty
                  ? _persistedRoomMemberRoleValue(
                      _effectiveRoomMemberRole(
                        profileId: membershipState.profileId,
                        settings: settings,
                        storedRole: membershipState.role,
                        legacyAdminIds: legacyAdminIds,
                      ),
                    )
                  : membershipState.role,
              'sourceLinkId': membershipState.sourceLinkId,
              'tag': membershipState.tag,
              'createdAtMs': membershipState.createdAtMs,
              'updatedAtMs': membershipState.updatedAtMs,
            },
          )
          .toList(growable: false),
    };
    if (includeInviteLinks) {
      final inviteLinks = await listRoomInviteLinks(groupId);
      payload['inviteLinks'] = inviteLinks
          .map(
            (link) => <String, Object?>{
              'linkId': link.linkId,
              'groupId': link.groupId,
              'slug': link.slug,
              'createdByProfileId': link.createdByProfileId,
              'expiresAtMs': link.expiresAtMs,
              'maxUses': link.maxUses,
              'useCount': link.useCount,
              'requiresApproval': link.requiresApproval,
              'allowedRole': link.allowedRole.value,
              'revoked': link.revoked,
              'createdAtMs': link.createdAtMs,
              'updatedAtMs': link.updatedAtMs,
            },
          )
          .toList(growable: false);
    }
    return payload;
  }

  Future<void> _applyRoomSnapshotPayload({
    required AppDb db,
    required Map<String, Object?> payload,
    bool forceAuthoritative = false,
  }) async {
    final groupId = ((payload['groupId'] as String?) ?? '').trim();
    if (groupId.isEmpty) return;
    final groupTitle = ((payload['groupTitle'] as String?) ?? '').trim();
    final hasAvatarSection =
        payload.containsKey('avatarHash') ||
        payload.containsKey('avatarImageB64');
    final incomingAvatarHash = ((payload['avatarHash'] as String?) ?? '')
        .trim();
    final incomingAvatarImageB64 =
        ((payload['avatarImageB64'] as String?) ?? '').trim();
    final ownerProfileId = ((payload['ownerProfileId'] as String?) ?? '')
        .trim();
    final incomingStateVersion =
        ((payload['stateVersion'] as num?)?.toInt() ?? 1) <= 0
        ? 1
        : (payload['stateVersion'] as num?)!.toInt();
    final incomingMembershipVersion =
        ((payload['membershipVersion'] as num?)?.toInt() ?? 0) < 0
        ? 0
        : ((payload['membershipVersion'] as num?)?.toInt() ?? 0);
    final memberProfileIds = _readStringList(payload['memberProfileIds']);
    final membershipStates =
        ((payload['membershipStates'] as List?) ?? const <Object?>[])
            .whereType<Map>()
            .map((entry) => entry.cast<String, Object?>())
            .map((entry) {
              final profileId = ((entry['profileId'] as String?) ?? '').trim();
              if (profileId.isEmpty) return null;
              final status = RoomMembershipStatusX.fromValue(
                (entry['status'] as String?) ??
                    RoomMembershipStatus.active.value,
              );
              final createdAtMs = (entry['createdAtMs'] as num?)?.toInt() ?? 0;
              final updatedAtMs =
                  (entry['updatedAtMs'] as num?)?.toInt() ?? createdAtMs;
              return (
                profileId: profileId,
                status: status.value,
                role: ((entry['role'] as String?) ?? '').trim(),
                sourceLinkId: (entry['sourceLinkId'] as String?)?.trim(),
                tag: (entry['tag'] as String?)?.trim(),
                createdAtMs: createdAtMs,
                updatedAtMs: updatedAtMs,
              );
            })
            .whereType<GroupMembershipStateRecord>()
            .toList(growable: false);
    final adminProfileIds = _readStringList(payload['adminProfileIds']);
    final effectiveMembershipStates = membershipStates.isNotEmpty
        ? membershipStates
        : memberProfileIds
              .map(
                (profileId) => (
                  profileId: profileId,
                  status: RoomMembershipStatus.active.value,
                  role: adminProfileIds.contains(profileId)
                      ? RoomMemberRole.admin.value
                      : RoomMemberRole.member.value,
                  sourceLinkId: null,
                  tag: null,
                  createdAtMs: 0,
                  updatedAtMs: 0,
                ),
              )
              .toList(growable: false);
    final hasInviteLinksSection = payload.containsKey('inviteLinks');
    final inviteLinks = ((payload['inviteLinks'] as List?) ?? const <Object?>[])
        .whereType<Map>()
        .map((entry) => entry.cast<String, Object?>())
        .toList(growable: false);
    if (ownerProfileId.isEmpty || effectiveMembershipStates.isEmpty) return;

    final existingSettings = await db.groupSettingsGet(groupId);
    final existingConvo = await db.convoGet(groupId);
    final localStateVersion =
        (existingSettings?['state_version'] as num?)?.toInt() ?? 0;
    final localMembershipVersion =
        (existingSettings?['membership_version'] as num?)?.toInt() ?? 0;
    final effectiveIncomingMembershipVersion = incomingMembershipVersion > 0
        ? incomingMembershipVersion
        : incomingStateVersion;
    final effectiveLocalMembershipVersion = localMembershipVersion > 0
        ? localMembershipVersion
        : localStateVersion;
    final shouldApplyState =
        forceAuthoritative || incomingStateVersion >= localStateVersion;
    final shouldApplyMembership =
        forceAuthoritative ||
        effectiveIncomingMembershipVersion >= effectiveLocalMembershipVersion;
    if (!shouldApplyState && !shouldApplyMembership) {
      return;
    }

    final currentSettings = existingSettings == null
        ? RoomSettings.defaults(ownerProfileId: ownerProfileId)
        : RoomSettings(
            ownerProfileId:
                (existingSettings['owner_profile_id'] as String?) ??
                ownerProfileId,
            avatarPath: existingSettings['avatar_path'] as String?,
            avatarHash: existingSettings['avatar_hash'] as String?,
            pinnedMessageEventId:
                (existingSettings['pinned_message_event_id'] as String?)
                    ?.trim(),
            coverId: (existingSettings['cover_id'] as String?)?.trim(),
            frameId: (existingSettings['frame_id'] as String?)?.trim(),
            nameEmoji: (existingSettings['name_emoji'] as String?)?.trim(),
            description: existingSettings['description'] as String?,
            reactionsMode: RoomReactionsModeX.fromValue(
              (existingSettings['reactions_mode'] as String?) ??
                  RoomReactionsMode.all.value,
            ),
            allowTextMessages:
                ((existingSettings['allow_text'] as num?)?.toInt() ?? 1) != 0,
            allowMedia:
                ((existingSettings['allow_media'] as num?)?.toInt() ?? 1) != 0,
            allowAddMembers:
                ((existingSettings['allow_add_members'] as num?)?.toInt() ??
                    1) !=
                0,
            allowPinMessages:
                ((existingSettings['allow_pin_messages'] as num?)?.toInt() ??
                    1) !=
                0,
            allowChangeGroupInfo:
                ((existingSettings['allow_change_group_info'] as num?)
                        ?.toInt() ??
                    1) !=
                0,
            allowChangeTag:
                ((existingSettings['allow_change_tag'] as num?)?.toInt() ??
                    0) !=
                0,
            joinApprovalRequired:
                ((existingSettings['join_approval_required'] as num?)
                        ?.toInt() ??
                    0) !=
                0,
            slowModeSeconds:
                (existingSettings['slow_mode_seconds'] as num?)?.toInt() ?? 0,
            chatHistoryVisible:
                ((existingSettings['chat_history_visible'] as num?)?.toInt() ??
                    0) !=
                0,
            membershipVersion:
                (existingSettings['membership_version'] as num?)?.toInt() ?? 0,
            stateVersion:
                (existingSettings['state_version'] as num?)?.toInt() ?? 0,
          );

    final existingTitle = ((existingConvo?['title'] as String?) ?? '').trim();
    await db.convoEnsureGroup(
      groupId: groupId,
      title: shouldApplyState
          ? (groupTitle.isEmpty ? 'Room' : groupTitle)
          : (existingTitle.isEmpty ? 'Room' : existingTitle),
    );

    if (shouldApplyMembership) {
      await db.groupMembershipStatesReplace(
        groupId: groupId,
        states: effectiveMembershipStates,
      );
      // A1 ZERO-LOSS: membership just converged — immediately re-apply any
      // parked (decrypted) frames whose sender is now a confirmed member. The
      // periodic recovery sweep is the backstop that catches every other path.
      unawaited(_flushDeferredRoomInbound(db, groupId));
    }
    if (shouldApplyState || shouldApplyMembership) {
      final snapshotSettings = currentSettings.copyWith(
        ownerProfileId: ownerProfileId,
      );
      await db.groupAdminsReplace(
        groupId: groupId,
        profileIds: effectiveMembershipStates
            .where(
              (membershipState) =>
                  RoomMembershipStatusX.fromValue(membershipState.status) ==
                  RoomMembershipStatus.active,
            )
            .where((membershipState) {
              final effectiveRole = _effectiveRoomMemberRole(
                profileId: membershipState.profileId,
                settings: snapshotSettings,
                storedRole: membershipState.role,
                legacyAdminIds: adminProfileIds.toSet(),
              );
              return effectiveRole == RoomMemberRole.owner ||
                  effectiveRole == RoomMemberRole.admin;
            })
            .map((membershipState) => membershipState.profileId)
            .toSet()
            .toList(growable: false),
      );
    }

    var nextSettings = currentSettings;
    if (shouldApplyState) {
      final resolvedAvatar = hasAvatarSection
          ? await _resolveIncomingRoomAvatar(
              groupId: groupId,
              currentSettings: currentSettings,
              incomingAvatarHash: incomingAvatarHash,
              incomingAvatarImageB64: incomingAvatarImageB64,
            )
          : (
              avatarPath: currentSettings.avatarPath,
              avatarHash: currentSettings.avatarHash,
            );
      nextSettings = nextSettings.copyWith(
        ownerProfileId: ownerProfileId,
        avatarPath: hasAvatarSection ? resolvedAvatar.avatarPath : null,
        avatarHash: hasAvatarSection ? resolvedAvatar.avatarHash : null,
        clearAvatar:
            hasAvatarSection && ((resolvedAvatar.avatarPath ?? '').isEmpty),
        description: (payload['description'] as String?)?.trim(),
        reactionsMode: RoomReactionsModeX.fromValue(
          (payload['reactionsMode'] as String?) ?? RoomReactionsMode.all.value,
        ),
        allowTextMessages: payload['allowTextMessages'] != false,
        allowMedia: payload['allowMedia'] != false,
        allowAddMembers: payload['allowAddMembers'] != false,
        allowPinMessages: payload['allowPinMessages'] != false,
        allowChangeGroupInfo: payload['allowChangeGroupInfo'] != false,
        allowChangeTag: payload['allowChangeTag'] == true,
        joinApprovalRequired: payload.containsKey('joinApprovalRequired')
            ? payload['joinApprovalRequired'] == true
            : nextSettings.joinApprovalRequired,
        slowModeSeconds: (payload['slowModeSeconds'] as num?)?.toInt() ?? 0,
        chatHistoryVisible: payload['chatHistoryVisible'] == true,
        pinnedMessageEventId: payload.containsKey('pinnedMessageEventId')
            ? (payload['pinnedMessageEventId'] as String?)?.trim()
            : nextSettings.pinnedMessageEventId,
        clearPinnedMessageEventId:
            payload.containsKey('pinnedMessageEventId') &&
            (((payload['pinnedMessageEventId'] as String?)?.trim().isEmpty ??
                true)),
        // Premium ROOM cosmetics — additive. `containsKey` gates set vs clear;
        // when the key is absent (e.g. a relay-built snapshot that predates
        // cosmetics) the existing local value is preserved.
        coverId: payload.containsKey('coverId')
            ? (payload['coverId'] as String?)?.trim()
            : nextSettings.coverId,
        clearCoverId:
            payload.containsKey('coverId') &&
            (((payload['coverId'] as String?)?.trim().isEmpty ?? true)),
        frameId: payload.containsKey('frameId')
            ? (payload['frameId'] as String?)?.trim()
            : nextSettings.frameId,
        clearFrameId:
            payload.containsKey('frameId') &&
            (((payload['frameId'] as String?)?.trim().isEmpty ?? true)),
        nameEmoji: payload.containsKey('nameEmoji')
            ? (payload['nameEmoji'] as String?)?.trim()
            : nextSettings.nameEmoji,
        clearNameEmoji:
            payload.containsKey('nameEmoji') &&
            (((payload['nameEmoji'] as String?)?.trim().isEmpty ?? true)),
        stateVersion: incomingStateVersion,
      );
    }
    if (shouldApplyMembership) {
      nextSettings = nextSettings.copyWith(
        membershipVersion: effectiveIncomingMembershipVersion,
      );
    }
    await _persistRoomSettingsRecord(
      db: db,
      groupId: groupId,
      settings: nextSettings,
    );
    var canManageInviteLinks = false;
    final selfProfileId = profileId.trim();
    if (selfProfileId.isNotEmpty) {
      final selfMembershipState = await _roomMembershipStateOrLegacyActive(
        groupId,
        selfProfileId,
      );
      final selfIsActive =
          selfMembershipState != null &&
          RoomMembershipStatusX.fromValue(selfMembershipState.status) ==
              RoomMembershipStatus.active;
      if (selfIsActive) {
        final legacyAdminIds = (await listGroupAdmins(groupId)).toSet();
        final selfRole = _effectiveRoomMemberRole(
          profileId: selfProfileId,
          settings: nextSettings,
          storedRole: selfMembershipState.role,
          legacyAdminIds: legacyAdminIds,
        );
        canManageInviteLinks = evaluateRoomPolicyState(
          settings: nextSettings,
          isMember: true,
          role: selfRole,
          lastOwnMessageAtMs: null,
        ).canManageInviteLinks;
      }
    }
    if (shouldApplyState) {
      if (!canManageInviteLinks) {
        await db.groupInviteLinksDeleteForGroup(groupId);
      } else if (hasInviteLinksSection) {
        await db.groupInviteLinksDeleteForGroup(groupId);
        for (final invite in inviteLinks) {
          final linkId = ((invite['linkId'] as String?) ?? '').trim();
          final slug = ((invite['slug'] as String?) ?? '').trim();
          final createdByProfileId =
              ((invite['createdByProfileId'] as String?) ?? '').trim();
          if (linkId.isEmpty || slug.isEmpty || createdByProfileId.isEmpty) {
            continue;
          }
          await db.groupInviteLinkUpsert(
            linkId: linkId,
            groupId: ((invite['groupId'] as String?) ?? groupId).trim().isEmpty
                ? groupId
                : ((invite['groupId'] as String?) ?? groupId).trim(),
            slug: slug,
            createdByProfileId: createdByProfileId,
            createdAtMs: (invite['createdAtMs'] as num?)?.toInt() ?? 0,
            updatedAtMs: (invite['updatedAtMs'] as num?)?.toInt() ?? 0,
            expiresAtMs: _normalizeRoomInviteExpiresAtMs(
              (invite['expiresAtMs'] as num?)?.toInt(),
            ),
            maxUses: _normalizeRoomInviteMaxUses(
              (invite['maxUses'] as num?)?.toInt(),
            ),
            useCount: ((invite['useCount'] as num?)?.toInt() ?? 0) < 0
                ? 0
                : (invite['useCount'] as num?)?.toInt() ?? 0,
            requiresApproval: invite['requiresApproval'] == true,
            allowedRole: _normalizeRoomInviteAllowedRole(
              RoomMemberRoleX.fromValue(
                (invite['allowedRole'] as String?) ?? 'member',
              ),
            ).value,
            revoked: invite['revoked'] == true,
          );
        }
      }
    }
    if (shouldApplyMembership) {
      final selfProfileId = profileId.trim();
      if (selfProfileId.isNotEmpty) {
        final selfMembershipState = effectiveMembershipStates
            .where(
              (membershipState) => membershipState.profileId == selfProfileId,
            )
            .cast<GroupMembershipStateRecord?>()
            .firstOrNull;
        final selfStatus = selfMembershipState == null
            ? null
            : RoomMembershipStatusX.fromValue(selfMembershipState.status);
        await db.convoSetArchived(
          convoId: groupId,
          archived: selfStatus != RoomMembershipStatus.active,
        );
        if (selfStatus != RoomMembershipStatus.active) {
          await db.roomCallSnapshotDelete(groupId);
        }
      }
    }
    if (shouldApplyState || shouldApplyMembership) {
      await _applyRoomHistoryVisibilityRetentionForConvo(groupId);
    }
    _changed.add(null);
  }

  Future<void> _broadcastRoomSnapshotToMembers(
    String groupId, {
    String? skipProfileId,
    Iterable<String> extraProfileIds = const <String>[],
    bool includeInviteLinks = false,
  }) async {
    final snapshot = await _buildRoomSnapshotPayload(
      groupId,
      includeInviteLinks: includeInviteLinks,
    );
    final members = <String>{
      ..._readStringList(snapshot['memberProfileIds']),
      ...extraProfileIds
          .map((profileId) => profileId.trim())
          .where((profileId) => profileId.isNotEmpty),
    };
    final skip = (skipProfileId ?? '').trim();
    for (final member in members) {
      if (member == skip) continue;
      await _sendRoomInviteControl(
        peerProfileId: member,
        payload: snapshot,
        // A5 (root of A1): the authoritative room snapshot is what converges a
        // member's roster. If it is lost to an offline member their roster stays
        // stale and they permanently drop the added member's messages (A1). Make
        // it durable so it re-delivers once the member reconnects.
        queueIfNoDevices: true,
        retryBucket: 'room_snapshot',
      );
    }
  }

  Future<Set<String>> _roomSyncHintRecipientProfileIds(
    String groupId, {
    Iterable<String> extraProfileIds = const <String>[],
    bool inviteManagersOnly = false,
  }) async {
    final membershipStates = await listRoomMembershipStates(groupId);
    final settings = inviteManagersOnly ? await getRoomSettings(groupId) : null;
    final legacyAdminIds = inviteManagersOnly
        ? (await listGroupAdmins(groupId)).toSet()
        : const <String>{};
    final recipients = <String>{
      ...extraProfileIds
          .map((profileId) => profileId.trim())
          .where((profileId) => profileId.isNotEmpty),
    };
    for (final membershipState in membershipStates) {
      if (RoomMembershipStatusX.fromValue(membershipState.status) !=
          RoomMembershipStatus.active) {
        continue;
      }
      if (inviteManagersOnly) {
        final role = _effectiveRoomMemberRole(
          profileId: membershipState.profileId,
          settings: settings!,
          storedRole: membershipState.role,
          legacyAdminIds: legacyAdminIds,
        );
        if (role != RoomMemberRole.owner && role != RoomMemberRole.admin) {
          continue;
        }
      }
      recipients.add(membershipState.profileId);
    }
    return recipients;
  }

  Future<void> _broadcastAuthoritativeRoomSyncHint(
    String groupId, {
    String? skipProfileId,
    Iterable<String> extraProfileIds = const <String>[],
    bool includeInviteLinks = false,
    bool inviteManagersOnly = false,
  }) async {
    final recipients = await _roomSyncHintRecipientProfileIds(
      groupId,
      extraProfileIds: extraProfileIds,
      inviteManagersOnly: inviteManagersOnly,
    );
    final skip = (skipProfileId ?? '').trim();
    final db = _db;
    final settingsRow = db == null ? null : await db.groupSettingsGet(groupId);
    final stateVersion = (settingsRow?['state_version'] as num?)?.toInt() ?? 0;
    final membershipVersion =
        ((settingsRow?['membership_version'] as num?)?.toInt() ?? 0) > 0
        ? (settingsRow?['membership_version'] as num?)!.toInt()
        : stateVersion;
    final payload = <String, Object?>{
      'v': 1,
      'action': 'authoritative_sync',
      'groupId': groupId,
      if (stateVersion > 0) 'stateVersion': stateVersion,
      if (membershipVersion > 0) 'membershipVersion': membershipVersion,
      if (includeInviteLinks) 'includeInviteLinks': true,
    };
    for (final member in recipients) {
      if (member == skip) continue;
      await _sendRoomInviteControl(
        peerProfileId: member,
        payload: payload,
        // A5: authoritative membership sync must survive an offline member.
        queueIfNoDevices: true,
        retryBucket: 'room_authoritative_sync',
      );
    }
  }

  Future<void> _broadcastRoomDeletedControl({
    required String groupId,
    required String groupTitle,
    required String deletedByProfileId,
    required Iterable<String> recipientProfileIds,
  }) async {
    final cleanedGroupId = groupId.trim();
    final cleanedDeletedByProfileId = deletedByProfileId.trim();
    if (cleanedGroupId.isEmpty || cleanedDeletedByProfileId.isEmpty) {
      return;
    }
    final recipients = recipientProfileIds
        .map((profileId) => profileId.trim())
        .where((profileId) => profileId.isNotEmpty)
        .toSet();
    if (recipients.isEmpty) {
      return;
    }
    final normalizedTitle = groupTitle.trim().isEmpty
        ? 'Room'
        : groupTitle.trim();
    for (final peerProfileId in recipients) {
      await _sendRoomInviteControl(
        peerProfileId: peerProfileId,
        payload: <String, Object?>{
          'v': 1,
          'action': 'room_deleted',
          'groupId': cleanedGroupId,
          'groupTitle': normalizedTitle,
          'deletedByProfileId': cleanedDeletedByProfileId,
        },
        // A5: an offline member should still learn the room was deleted.
        queueIfNoDevices: true,
        retryBucket: 'room_deleted',
      );
    }
  }

  Map<String, Object?> _buildRoomCallSyncHintPayload({
    required String roomId,
    required RelayRoomCallSnapshot snapshot,
  }) {
    final cleanedRoomId = roomId.trim().isNotEmpty
        ? roomId.trim()
        : snapshot.room.roomId.trim();
    final call = snapshot.call;
    final cleanedCallId = call?.callId.trim() ?? '';
    final stateVersion = call?.stateVersion ?? 0;
    final callExists =
        snapshot.exists &&
        call != null &&
        cleanedCallId.isNotEmpty &&
        call.isActive;
    return <String, Object?>{
      'v': 1,
      'action': 'room_call_sync',
      'groupId': cleanedRoomId,
      'callExists': callExists,
      if (cleanedCallId.isNotEmpty) 'callId': cleanedCallId,
      if (stateVersion > 0) 'stateVersion': stateVersion,
    };
  }

  String _buildRoomCallSyncTransportMetaJson({
    required String roomId,
    required RelayRoomCallSnapshot snapshot,
  }) {
    final cleanedRoomId = roomId.trim().isNotEmpty
        ? roomId.trim()
        : snapshot.room.roomId.trim();
    final call = snapshot.call;
    final cleanedCallId = call?.callId.trim() ?? '';
    return RoomCallSyncTransportMeta.buildTransportMetaJson(
      roomId: cleanedRoomId,
      callId: cleanedCallId,
      stateVersion: call?.stateVersion ?? 0,
      callExists:
          snapshot.exists &&
          call != null &&
          cleanedCallId.isNotEmpty &&
          call.isActive,
      createdAtMs: DateTime.now().millisecondsSinceEpoch,
    );
  }

  Iterable<String> _roomCallSyncHintExtraProfileIds(
    RelayRoomCallSnapshot snapshot,
  ) sync* {
    final ownerProfileId = snapshot.room.ownerProfileId.trim();
    if (ownerProfileId.isNotEmpty) {
      yield ownerProfileId;
    }

    final createdByProfileId = snapshot.call?.createdByProfileId.trim() ?? '';
    if (createdByProfileId.isNotEmpty) {
      yield createdByProfileId;
    }

    final selfProfileId = snapshot.selfParticipant?.profileId.trim() ?? '';
    if (selfProfileId.isNotEmpty) {
      yield selfProfileId;
    }

    for (final participant in snapshot.participants) {
      final participantProfileId = participant.profileId.trim();
      if (participantProfileId.isEmpty) {
        continue;
      }
      yield participantProfileId;
    }
  }

  Future<void> _broadcastRoomCallSyncHintToMembers({
    required String roomId,
    required RelayRoomCallSnapshot snapshot,
    String? skipProfileId,
  }) async {
    final cleanedRoomId = roomId.trim().isNotEmpty
        ? roomId.trim()
        : snapshot.room.roomId.trim();
    if (cleanedRoomId.isEmpty) {
      return;
    }
    final recipients = await _roomSyncHintRecipientProfileIds(
      cleanedRoomId,
      extraProfileIds: _roomCallSyncHintExtraProfileIds(snapshot),
    );
    final payload = _buildRoomCallSyncHintPayload(
      roomId: cleanedRoomId,
      snapshot: snapshot,
    );
    final transportMetaJson = _buildRoomCallSyncTransportMetaJson(
      roomId: cleanedRoomId,
      snapshot: snapshot,
    );
    final skip = (skipProfileId ?? '').trim();
    for (final member in recipients) {
      if (member == skip) continue;
      await _sendRoomInviteControl(
        peerProfileId: member,
        payload: payload,
        retryBucket: 'room_call_sync',
        transportMetaJson: transportMetaJson,
      );
    }
  }

  Future<void> _broadcastRoomCallSyncHintToMembersBestEffort({
    required String roomId,
    required RelayRoomCallSnapshot snapshot,
    String? skipProfileId,
  }) async {
    try {
      await _broadcastRoomCallSyncHintToMembers(
        roomId: roomId,
        snapshot: snapshot,
        skipProfileId: skipProfileId,
      );
    } catch (e) {
      callLog(
        'AppCtrl',
        'room call sync hint broadcast failed roomId=$roomId: $e',
      );
    }
  }

  Future<void> _sendAuthoritativeRoomMembershipStateToPeer({
    required RelayRoom room,
    required RelayRoomMembership membership,
  }) async {
    final targetProfileId = membership.profileId.trim();
    if (targetProfileId.isEmpty) return;
    final normalizedTitle = room.title.trim().isEmpty
        ? 'Room'
        : room.title.trim();
    final normalizedRole = membership.role.trim().isEmpty
        ? RoomMemberRole.member.value
        : membership.role.trim();
    final normalizedStateVersion = room.version > 0 ? room.version : 1;
    final normalizedMembershipVersion = room.membershipVersion > 0
        ? room.membershipVersion
        : normalizedStateVersion;
    await _sendRoomInviteControl(
      peerProfileId: targetProfileId,
      payload: <String, Object?>{
        'v': 1,
        'action': 'authoritative_membership_state',
        'groupId': room.roomId,
        'groupTitle': normalizedTitle,
        'ownerProfileId': room.ownerProfileId,
        'profileId': targetProfileId,
        'status': membership.status,
        'role': normalizedRole,
        'sourceLinkId': membership.sourceLinkId,
        'tag': membership.tag,
        'createdAtMs': membership.createdAtMs,
        'updatedAtMs': membership.updatedAtMs,
        'stateVersion': normalizedStateVersion,
        'membershipVersion': normalizedMembershipVersion,
      },
      // A5: per-member authoritative membership state must survive offline.
      queueIfNoDevices: true,
      retryBucket: 'room_authoritative_membership_state',
    );
  }

  Future<void> _sendRoomInviteResponse({
    required String peerProfileId,
    required String action,
    required String requestId,
    RoomInviteFailure? failure,
    Map<String, Object?> extra = const <String, Object?>{},
    bool forceRelayFlush = false,
  }) async {
    final payload = <String, Object?>{
      'v': 1,
      'action': action,
      'requestId': requestId,
      'ok': failure == null,
      ...extra,
    };
    if (failure != null) {
      payload['failureCode'] = _roomInviteFailureCodeToWire(failure.code);
      if (failure.message != null && failure.message!.trim().isNotEmpty) {
        payload['message'] = failure.message!.trim();
      }
    }
    await _sendRoomInviteControl(
      peerProfileId: peerProfileId,
      payload: payload,
      forceRelayFlush: forceRelayFlush,
      retryBucket: action,
    );
  }

  Future<void> _handleRoomInviteCommand({
    required AppDb db,
    required Map<String, Object?> command,
    required String? senderProfileId,
  }) async {
    final action = ((command['action'] as String?) ?? '').trim();
    switch (action) {
      case 'preview_request':
        await _handleRoomInvitePreviewRequest(
          command: command,
          senderProfileId: senderProfileId,
        );
        return;
      case 'preview_response':
        _handleRoomInvitePreviewResponse(command);
        return;
      case 'join_request':
        await _handleRoomInviteJoinRequest(
          db: db,
          command: command,
          senderProfileId: senderProfileId,
        );
        return;
      case 'join_response':
        await _handleRoomInviteJoinResponse(db: db, command: command);
        return;
      case 'authoritative_membership_state':
        await _handleAuthoritativeRoomMembershipState(db: db, command: command);
        return;
      case 'authoritative_sync':
        await _handleRoomAuthoritativeSyncHint(command: command);
        return;
      case 'room_deleted':
        await _handleRoomDeletedCommand(
          db: db,
          command: command,
          senderProfileId: senderProfileId,
        );
        return;
      case 'room_call_sync':
        await _handleRoomCallSyncHint(command: command);
        return;
      case 'snapshot':
        await _applyRoomSnapshotPayload(db: db, payload: command);
        return;
      default:
        return;
    }
  }

  Future<void> _handleRoomAuthoritativeSyncHint({
    required Map<String, Object?> command,
  }) async {
    final groupId = ((command['groupId'] as String?) ?? '').trim();
    if (groupId.isEmpty) return;
    final includeInviteLinks = switch (command['includeInviteLinks']) {
      true => true,
      1 => true,
      '1' => true,
      'true' => true,
      _ => false,
    };
    final db = _db;
    final localSettingsRow = db == null
        ? null
        : await db.groupSettingsGet(groupId);
    final hintedPlan = planAuthoritativeRoomSyncHintResync(
      hasLocalRoomState: localSettingsRow != null,
      localStateVersion:
          (localSettingsRow?['state_version'] as num?)?.toInt() ?? 0,
      localMembershipVersion:
          (localSettingsRow?['membership_version'] as num?)?.toInt() ?? 0,
      hintedStateVersion: (command['stateVersion'] as num?)?.toInt() ?? 0,
      hintedMembershipVersion:
          (command['membershipVersion'] as num?)?.toInt() ?? 0,
      includeInviteLinks: includeInviteLinks,
    );
    if (hintedPlan == null) {
      await _tryRefreshRoomFromRelayBestEffort(
        groupId,
        includeInviteLinks: includeInviteLinks,
      );
      return;
    }
    if (!hintedPlan.shouldRefresh) {
      return;
    }
    if (hintedPlan.refreshMemberships) {
      await _tryRefreshRoomFromRelayBestEffort(
        groupId,
        includeInviteLinks: includeInviteLinks,
        forceAuthoritative: hintedPlan.forceAuthoritative,
      );
      return;
    }
    await _reconcileKnownRoomFromRelayBestEffort(
      groupId,
      localSettingsRow: localSettingsRow,
    );
  }

  Future<void> _handleRoomCallSyncHint({
    required Map<String, Object?> command,
  }) async {
    final groupId = ((command['groupId'] as String?) ?? '').trim();
    if (groupId.isEmpty) {
      return;
    }
    final callExists = switch (command['callExists']) {
      true => true,
      1 => true,
      '1' => true,
      'true' => true,
      _ => false,
    };
    final hintedStateVersion = switch (command['stateVersion']) {
      final int value => value,
      final num value => value.toInt(),
      final String value => int.tryParse(value) ?? 0,
      _ => 0,
    };
    final hintedCallId = ((command['callId'] as String?) ?? '').trim();
    final db = _db;
    final localCallState = db == null
        ? null
        : await db.roomCallSnapshotGet(groupId);
    final shouldRefresh = shouldRefreshRoomCallFromSyncHint(
      hasLocalCallState: localCallState != null,
      localStateVersion: localCallState?.stateVersion ?? 0,
      localCallId: localCallState?.callId,
      hintedCallExists: callExists,
      hintedStateVersion: hintedStateVersion,
      hintedCallId: hintedCallId,
    );
    if (!shouldRefresh) {
      return;
    }
    await _tryRefreshRoomCallFromRelayBestEffort(groupId);
  }

  Future<void> _handleAuthoritativeRoomMembershipState({
    required AppDb db,
    required Map<String, Object?> command,
  }) async {
    final groupId = ((command['groupId'] as String?) ?? '').trim();
    final selfProfileId = profileId.trim();
    final targetProfileId = ((command['profileId'] as String?) ?? '').trim();
    if (groupId.isEmpty ||
        selfProfileId.isEmpty ||
        targetProfileId != selfProfileId) {
      return;
    }
    final normalizedTitle = ((command['groupTitle'] as String?) ?? '').trim();
    final ownerProfileId = ((command['ownerProfileId'] as String?) ?? '')
        .trim();
    final normalizedRole = ((command['role'] as String?) ?? '').trim().isEmpty
        ? RoomMemberRole.member.value
        : ((command['role'] as String?) ?? '').trim();
    final status = RoomMembershipStatusX.fromValue(
      ((command['status'] as String?) ?? RoomMembershipStatus.removed.value)
          .trim(),
    );
    final stateVersion = ((command['stateVersion'] as num?)?.toInt() ?? 0) <= 0
        ? 0
        : (command['stateVersion'] as num?)!.toInt();
    final membershipVersion =
        ((command['membershipVersion'] as num?)?.toInt() ?? 0) <= 0
        ? stateVersion
        : (command['membershipVersion'] as num?)!.toInt();

    await db.convoEnsureGroup(
      groupId: groupId,
      title: normalizedTitle.isEmpty ? 'Room' : normalizedTitle,
    );
    await db.groupMembershipStateUpsert(
      groupId: groupId,
      profileId: selfProfileId,
      status: status.value,
      role: normalizedRole,
      sourceLinkId: (command['sourceLinkId'] as String?)?.trim(),
      tag: (command['tag'] as String?)?.trim(),
      createdAtMs: (command['createdAtMs'] as num?)?.toInt(),
      updatedAtMs: (command['updatedAtMs'] as num?)?.toInt(),
      preserveExistingCreatedAt: false,
    );
    final admins = await listGroupAdmins(groupId);
    if (admins.contains(selfProfileId) &&
        status != RoomMembershipStatus.active) {
      await db.groupAdminsReplace(
        groupId: groupId,
        profileIds: admins
            .where((profileId) => profileId != selfProfileId)
            .toList(growable: false),
      );
    }
    final currentSettings = await getRoomSettings(groupId);
    await _persistRoomSettingsRecord(
      db: db,
      groupId: groupId,
      settings: currentSettings.copyWith(
        ownerProfileId: ownerProfileId.isEmpty
            ? currentSettings.ownerProfileId
            : ownerProfileId,
        stateVersion: stateVersion > currentSettings.stateVersion
            ? stateVersion
            : currentSettings.stateVersion,
        membershipVersion: membershipVersion > currentSettings.membershipVersion
            ? membershipVersion
            : currentSettings.membershipVersion,
      ),
    );
    if (status != RoomMembershipStatus.active) {
      await db.convoSetArchived(convoId: groupId, archived: true);
      await db.roomCallSnapshotDelete(groupId);
      await db.groupInviteLinksDeleteForGroup(groupId);
    }
    _changed.add(null);
  }

  Future<void> _handleRoomDeletedCommand({
    required AppDb db,
    required Map<String, Object?> command,
    required String? senderProfileId,
  }) async {
    final groupId = ((command['groupId'] as String?) ?? '').trim();
    if (groupId.isEmpty) {
      return;
    }
    final senderId = (senderProfileId ?? '').trim();
    final deletedByProfileId =
        ((command['deletedByProfileId'] as String?) ?? senderId).trim();
    if (deletedByProfileId.isEmpty) {
      return;
    }
    if (senderId.isNotEmpty && senderId != deletedByProfileId) {
      return;
    }
    final settingsRow = await db.groupSettingsGet(groupId);
    final ownerProfileId = ((settingsRow?['owner_profile_id'] as String?) ?? '')
        .trim();
    if (ownerProfileId.isNotEmpty && ownerProfileId != deletedByProfileId) {
      return;
    }
    await _deleteRoomLocalState(groupId);
  }

  Future<void> _handleRoomInvitePreviewRequest({
    required Map<String, Object?> command,
    required String? senderProfileId,
  }) async {
    final requestId = ((command['requestId'] as String?) ?? '').trim();
    final requesterProfileId = (senderProfileId ?? '').trim();
    final inviterProfileId = profileId.trim();
    if (requestId.isEmpty ||
        requesterProfileId.isEmpty ||
        inviterProfileId.isEmpty) {
      return;
    }

    final target = RoomInviteTarget(
      slug: ((command['slug'] as String?) ?? '').trim(),
      inviterProfileId: inviterProfileId,
      groupIdHint: (command['groupIdHint'] as String?)?.trim(),
    );
    if (target.slug.isEmpty) return;
    await _sendRoomInviteResponse(
      peerProfileId: requesterProfileId,
      action: 'preview_response',
      requestId: requestId,
      failure: const RoomInviteFailure(
        RoomInviteFailureCode.inviteCreatorUnavailable,
      ),
      extra: <String, Object?>{
        'slug': target.slug,
        'createdByProfileId': inviterProfileId,
      },
      forceRelayFlush: true,
    );
  }

  void _handleRoomInvitePreviewResponse(Map<String, Object?> command) {
    final requestId = ((command['requestId'] as String?) ?? '').trim();
    if (requestId.isEmpty) return;
    final completer = _roomInvitePreviewWaiters[requestId];
    if (completer == null || completer.isCompleted) return;
    if (command['ok'] != true) {
      completer.completeError(
        _roomInviteFailureFromWire(command) ??
            const RoomInviteFailure(RoomInviteFailureCode.generic),
      );
      return;
    }

    final slug = ((command['slug'] as String?) ?? '').trim();
    final inviterProfileId = ((command['createdByProfileId'] as String?) ?? '')
        .trim();
    final groupId = ((command['groupId'] as String?) ?? '').trim();
    if (slug.isEmpty || inviterProfileId.isEmpty || groupId.isEmpty) {
      completer.completeError(
        const RoomInviteFailure(RoomInviteFailureCode.generic),
      );
      return;
    }
    Uint8List? avatarBytes;
    final avatarImageB64 = ((command['avatarImageB64'] as String?) ?? '')
        .trim();
    if (avatarImageB64.isNotEmpty) {
      try {
        avatarBytes = Uint8List.fromList(base64Decode(avatarImageB64));
      } catch (_) {
        avatarBytes = null;
      }
    }

    completer.complete(
      RoomInvitePreview(
        target: RoomInviteTarget(
          slug: slug,
          inviterProfileId: inviterProfileId,
          groupIdHint: groupId,
        ),
        groupId: groupId,
        groupTitle: ((command['groupTitle'] as String?) ?? '').trim().isEmpty
            ? 'Room'
            : ((command['groupTitle'] as String?) ?? '').trim(),
        description: (command['description'] as String?)?.trim(),
        inviterDisplayName:
            ((command['inviterDisplayName'] as String?) ?? '').trim().isEmpty
            ? inviterProfileId
            : ((command['inviterDisplayName'] as String?) ?? '').trim(),
        memberCount: (command['memberCount'] as num?)?.toInt() ?? 0,
        isAlreadyMember: command['isAlreadyMember'] == true,
        joinApprovalRequired: command['joinApprovalRequired'] == true,
        viewerMembershipStatus:
            (command['viewerMembershipStatus'] as String?)?.trim().isNotEmpty ==
                true
            ? RoomMembershipStatusX.fromValue(
                ((command['viewerMembershipStatus'] as String?) ?? '').trim(),
              )
            : null,
        chatHistoryVisible: command['chatHistoryVisible'] == true,
        allowedRole: _normalizeRoomInviteAllowedRole(
          RoomMemberRoleX.fromValue(
            (command['allowedRole'] as String?) ?? 'member',
          ),
        ),
        expiresAtMs: _normalizeRoomInviteExpiresAtMs(
          (command['expiresAtMs'] as num?)?.toInt(),
        ),
        maxUses: _normalizeRoomInviteMaxUses(
          (command['maxUses'] as num?)?.toInt(),
        ),
        remainingUses: _normalizeRoomInviteMaxUses(
          (command['remainingUses'] as num?)?.toInt(),
        ),
        avatarPath: null,
        avatarHash: ((command['avatarHash'] as String?) ?? '').trim().isEmpty
            ? null
            : ((command['avatarHash'] as String?) ?? '').trim(),
        avatarBytes: avatarBytes,
      ),
    );
  }

  Future<void> _handleRoomInviteJoinRequest({
    required AppDb db,
    required Map<String, Object?> command,
    required String? senderProfileId,
  }) async {
    final requestId = ((command['requestId'] as String?) ?? '').trim();
    final requesterProfileId = (senderProfileId ?? '').trim();
    final inviterProfileId = profileId.trim();
    if (requestId.isEmpty ||
        requesterProfileId.isEmpty ||
        inviterProfileId.isEmpty) {
      return;
    }

    final target = RoomInviteTarget(
      slug: ((command['slug'] as String?) ?? '').trim(),
      inviterProfileId: inviterProfileId,
      groupIdHint: (command['groupIdHint'] as String?)?.trim(),
    );
    if (target.slug.isEmpty) return;
    await _sendRoomInviteResponse(
      peerProfileId: requesterProfileId,
      action: 'join_response',
      requestId: requestId,
      failure: const RoomInviteFailure(
        RoomInviteFailureCode.inviteCreatorUnavailable,
      ),
      extra: <String, Object?>{'groupId': target.groupIdHint},
      forceRelayFlush: true,
    );
  }

  Future<void> _handleRoomInviteJoinResponse({
    required AppDb db,
    required Map<String, Object?> command,
  }) async {
    final requestId = ((command['requestId'] as String?) ?? '').trim();
    final completer = requestId.isEmpty
        ? null
        : _roomInviteJoinWaiters[requestId];
    if (command['ok'] != true) {
      if (completer != null && !completer.isCompleted) {
        completer.completeError(
          _roomInviteFailureFromWire(command) ??
              const RoomInviteFailure(RoomInviteFailureCode.generic),
        );
      }
      return;
    }

    final snapshotPayload = command['snapshot'] is Map
        ? (command['snapshot'] as Map).cast<String, Object?>()
        : null;
    if (snapshotPayload != null) {
      await _applyRoomSnapshotPayload(db: db, payload: snapshotPayload);
    }
    final membershipStatus = RoomMembershipStatusX.fromValue(
      ((command['joinState'] as String?) ?? RoomMembershipStatus.active.value)
          .trim(),
    );
    final groupId = snapshotPayload != null
        ? ((snapshotPayload['groupId'] as String?) ?? '').trim()
        : ((command['groupId'] as String?) ?? '').trim();
    final groupTitle = snapshotPayload != null
        ? (((snapshotPayload['groupTitle'] as String?) ?? '').trim().isEmpty
              ? 'Room'
              : ((snapshotPayload['groupTitle'] as String?) ?? '').trim())
        : (((command['groupTitle'] as String?) ?? '').trim().isEmpty
              ? 'Room'
              : ((command['groupTitle'] as String?) ?? '').trim());
    if (completer != null && !completer.isCompleted && groupId.isNotEmpty) {
      completer.complete(
        _RoomInviteJoinResult(
          groupId: groupId,
          groupTitle: groupTitle,
          membershipStatus: membershipStatus,
        ),
      );
    }
  }

  RoomInviteFailure? _roomInviteFailureFromWire(Map<String, Object?> payload) {
    final rawCode = ((payload['failureCode'] as String?) ?? '').trim();
    if (rawCode.isEmpty) return null;
    return RoomInviteFailure(switch (rawCode) {
      'invalid_link' => RoomInviteFailureCode.invalidLink,
      'invite_not_found' => RoomInviteFailureCode.inviteNotFound,
      'invite_revoked' => RoomInviteFailureCode.inviteRevoked,
      'invite_expired' => RoomInviteFailureCode.inviteExpired,
      'invite_usage_limit_reached' =>
        RoomInviteFailureCode.inviteUsageLimitReached,
      'invite_creator_unavailable' =>
        RoomInviteFailureCode.inviteCreatorUnavailable,
      'banned' => RoomInviteFailureCode.banned,
      'preview_timed_out' => RoomInviteFailureCode.previewTimedOut,
      'join_timed_out' => RoomInviteFailureCode.joinTimedOut,
      _ => RoomInviteFailureCode.generic,
    }, message: (payload['message'] as String?)?.trim());
  }

  String _roomInviteFailureCodeToWire(RoomInviteFailureCode code) {
    return switch (code) {
      RoomInviteFailureCode.invalidLink => 'invalid_link',
      RoomInviteFailureCode.inviteNotFound => 'invite_not_found',
      RoomInviteFailureCode.inviteRevoked => 'invite_revoked',
      RoomInviteFailureCode.inviteExpired => 'invite_expired',
      RoomInviteFailureCode.inviteUsageLimitReached =>
        'invite_usage_limit_reached',
      RoomInviteFailureCode.inviteCreatorUnavailable =>
        'invite_creator_unavailable',
      RoomInviteFailureCode.banned => 'banned',
      RoomInviteFailureCode.previewTimedOut => 'preview_timed_out',
      RoomInviteFailureCode.joinTimedOut => 'join_timed_out',
      RoomInviteFailureCode.generic => 'generic',
    };
  }

  List<String> _readStringList(Object? raw) {
    return (raw is List ? raw : const <Object?>[])
        .whereType<String>()
        .map((value) => value.trim())
        .where((value) => value.isNotEmpty)
        .toSet()
        .toList(growable: false);
  }

  Future<void> leaveRoom(String groupId) async {
    final db = _db;
    final selfProfileId = profileId.trim();
    if (db == null || selfProfileId.isEmpty) return;
    final settings = await getRoomSettings(groupId);
    if (_useAuthoritativeRoomRelay) {
      if (settings.ownerProfileId == selfProfileId) {
        final otherActiveMembers = (await listGroupMembers(groupId))
            .where((memberProfileId) => memberProfileId != selfProfileId)
            .toList(growable: false);
        if (otherActiveMembers.isNotEmpty) {
          throw RoomMembershipFailure(
            RoomMembershipFailureCode.ownerTransferRequired,
          );
        }
      }
      final relay = _relay!;
      late final RelayRoomMembershipMutationResult result;
      try {
        result = await relay.leaveRoom(roomId: groupId);
        await _applyRelayRoomStateWithLocalMemberships(
          result.room,
          membershipOverrides: <RelayRoomMembership>[result.membership],
        );
      } catch (error) {
        await _tryRefreshRoomFromRelayBestEffort(groupId);
        final refreshedMembershipState =
            await _roomMembershipStateOrLegacyActive(groupId, selfProfileId);
        if (refreshedMembershipState != null &&
            RoomMembershipStatusX.fromValue(refreshedMembershipState.status) !=
                RoomMembershipStatus.active) {
          return;
        }
        if (error is RelayHttpException && error.statusCode == 409) {
          final relayMessage = '${error.message}\n${error.responseBody ?? ''}'
              .toLowerCase();
          if (relayMessage.contains('owner transfer required')) {
            throw RoomMembershipFailure(
              RoomMembershipFailureCode.ownerTransferRequired,
              cause: error,
            );
          }
          throw RoomMembershipFailure(
            RoomMembershipFailureCode.generic,
            cause: error,
          );
        }
        rethrow;
      }
      _changed.add(null);
      if (!result.changed) {
        return;
      }
      await _broadcastRoomSystemEvent(
        groupId: groupId,
        action: RoomSystemEventAction.memberLeft,
        extraProfileIds: <String>[selfProfileId],
        skipProfileId: selfProfileId,
      );
      await _broadcastAuthoritativeRoomSyncHint(
        groupId,
        skipProfileId: selfProfileId,
      );
      return;
    }
    _throwIfRoomMutationAuthoritativeRelayUnavailable();
    if (settings.ownerProfileId == selfProfileId) {
      final otherActiveMembers = (await listGroupMembers(groupId))
          .where((memberProfileId) => memberProfileId != selfProfileId)
          .toList(growable: false);
      if (otherActiveMembers.isNotEmpty) {
        throw RoomMembershipFailure(
          RoomMembershipFailureCode.ownerTransferRequired,
        );
      }
      await deleteChat(convoId: groupId);
      return;
    }
    await removeGroupMember(groupId: groupId, memberProfileId: selfProfileId);
  }

  Future<void> deleteRoom(String groupId) async {
    final db = _db;
    final selfProfileId = profileId.trim();
    if (db == null || selfProfileId.isEmpty) return;
    final settings = await getRoomSettings(groupId);
    if (settings.ownerProfileId.trim() != selfProfileId) {
      throw RoomMembershipFailure(RoomMembershipFailureCode.ownerOnly);
    }
    final convo = await db.convoGet(groupId);
    final normalizedTitle = ((convo?['title'] as String?) ?? '').trim().isEmpty
        ? 'Room'
        : ((convo?['title'] as String?) ?? '').trim();

    if (_useAuthoritativeRoomRelay) {
      final relay = _relay!;
      late final RelayRoomDeleteResult result;
      try {
        result = await relay.deleteRoom(roomId: groupId);
      } catch (error) {
        if (error is RelayHttpException && error.statusCode == 403) {
          throw RoomMembershipFailure(
            RoomMembershipFailureCode.ownerOnly,
            cause: error,
          );
        }
        throw RoomMembershipFailure(
          RoomMembershipFailureCode.generic,
          cause: error,
        );
      }
      await _broadcastRoomDeletedControl(
        groupId: groupId,
        groupTitle: result.room.title,
        deletedByProfileId: selfProfileId,
        recipientProfileIds: result.deletedProfileIds.where(
          (profileId) => profileId.trim() != selfProfileId,
        ),
      );
      await _deleteRoomLocalState(groupId);
      return;
    }

    _throwIfRoomMutationAuthoritativeRelayUnavailable();

    final recipientProfileIds = (await listRoomMembershipStates(groupId))
        .where(
          (state) =>
              state.profileId.trim().isNotEmpty &&
              state.profileId.trim() != selfProfileId &&
              (RoomMembershipStatusX.fromValue(state.status) ==
                      RoomMembershipStatus.active ||
                  RoomMembershipStatusX.fromValue(state.status) ==
                      RoomMembershipStatus.pending),
        )
        .map((state) => state.profileId.trim())
        .toSet();
    await _broadcastRoomDeletedControl(
      groupId: groupId,
      groupTitle: normalizedTitle,
      deletedByProfileId: selfProfileId,
      recipientProfileIds: recipientProfileIds,
    );
    await _deleteRoomLocalState(groupId);
  }

  Future<void> _deleteRoomLocalState(String groupId) async {
    final db = _db;
    if (db == null) return;
    final groupSettingsRow = await db.groupSettingsGet(groupId);
    final avatarPath = ((groupSettingsRow?['avatar_path'] as String?) ?? '')
        .trim();
    await db.deleteRoomLocalData(groupId: groupId, keepConversationRow: false);
    if (avatarPath.isNotEmpty) {
      await _deleteLocalFileIfExists(avatarPath);
    }
    _invalidateListConversationsCache();
    _changed.add(null);
  }

  Future<void> renameContact({
    required String profileId,
    required String? displayName,
  }) async {
    final db = _db;
    if (db == null) return;
    final cleaned = (displayName ?? '').trim();
    await db.contactUpsert(
      profileId: profileId,
      displayName: cleaned.isEmpty ? null : cleaned,
      displayNameIsCustom: cleaned.isNotEmpty,
    );
    _changed.add(null);
    _scheduleManagedDeviceContactSync();
  }

  Future<void> setContactEmoji({
    required String profileId,
    required String? emoji,
  }) async {
    final db = _db;
    if (db == null) return;
    await db.contactSetEmoji(profileId: profileId, emoji: emoji);
    _changed.add(null);
  }

  Future<void> toggleMessageReaction({
    required String convoId,
    required String eventId,
    required String emoji,
  }) async {
    final db = _db;
    if (db == null) return;
    final pid = profileId;
    final cleanedEmoji = emoji.trim();
    if (cleanedEmoji.isEmpty || pid.isEmpty) return;

    final existing = await db.messageReactionGetForProfile(
      eventId: eventId,
      profileId: pid,
    );
    final existingEmoji = existing?['emoji'] as String?;
    if (convoId.startsWith('group:')) {
      final policy = await getRoomPolicyState(convoId);
      if (!policy.isMember) {
        throw RoomPolicyFailure(RoomPolicyFailureCode.notMember);
      }
      final isRemoval = existingEmoji != null && existingEmoji == cleanedEmoji;
      if (!isRemoval) {
        ensureRoomActionAllowed(policy, RoomAction.react, emoji: cleanedEmoji);
      }
    }
    if (existingEmoji != null && existingEmoji == cleanedEmoji) {
      await db.messageReactionDelete(eventId: eventId, profileId: pid);
    } else {
      final actorName = myNickname.trim().isEmpty ? null : myNickname.trim();
      await db.messageReactionUpsert(
        eventId: eventId,
        convoId: convoId,
        profileId: pid,
        emoji: cleanedEmoji,
        actorName: actorName,
        actorAvatarPath: _myAvatarPath,
      );
    }
    _changed.add(null);
  }

  Future<void> broadcastReactionUpdate({
    required String convoId,
    required String eventId,
    required String emoji,
    required bool removed,
  }) async {
    final actorProfileId = profileId;
    if (actorProfileId.isEmpty) return;
    if (convoId.startsWith('group:') && !removed) {
      await _ensureRoomActionAllowed(convoId, RoomAction.react, emoji: emoji);
    }
    final payload = <String, Object?>{
      'v': 1,
      'convoId': convoId,
      'eventId': eventId,
      'emoji': emoji,
      'removed': removed,
      'actorProfileId': actorProfileId,
      'actorName': myNickname.trim().isEmpty ? null : myNickname.trim(),
      'actorAvatarPath': _myAvatarPath,
    };
    final text =
        '$_reactionCmdPrefix${base64Url.encode(utf8.encode(jsonEncode(payload)))}';

    if (convoId.startsWith('group:')) {
      final members = await listGroupMembers(convoId);
      for (final member in members) {
        await sendControlMessage(peerProfileId: member, controlText: text);
      }
      return;
    }

    final peer = convoId.startsWith('req:') ? convoId.substring(4) : convoId;
    if (peer.isEmpty || peer.startsWith('group:')) return;
    await sendControlMessage(peerProfileId: peer, controlText: text);
    // Multi-device sync: mirror the reaction to my own other devices
    // (TZ §21.1). Best-effort, fire-and-forget — peer-send is the source of
    // truth for visible UX, mirror is purely cosmetic for the user's other
    // devices.
    unawaited(
      _mirrorReactionToOwnDevices(
        convoId: peer,
        targetPayloadEventId: eventId,
        emoji: emoji,
        removed: removed,
        createdAtMs: DateTime.now().millisecondsSinceEpoch,
        actorProfileId: actorProfileId,
        actorName: myNickname.trim().isEmpty ? null : myNickname.trim(),
        actorAvatarPath: _myAvatarPath,
      ),
    );
  }

  Future<void> sendControlMessage({
    required String peerProfileId,
    required String controlText,
    // ROOM SENDER KEY (фаза 3б): send THESE events instead of wrapping
    // [controlText]. The same sealed `gmsg` object goes to every member, so the
    // room content is encrypted ONCE instead of once per device — while the
    // pairwise wrapper stays, deliberately: without it the relay would learn
    // the room id, the generation and the full recipient set of every message.
    // Everything else on this path (per-device fanout, the no-device queue, the
    // outbox, transport meta, TTL, scheduled delivery) is reused untouched.
    List<E2eEventV1>? overrideEvents,
    int ttlSeconds = _controlMessageTtlSeconds,
    bool strict = false,
    bool queueIfNoDevices = false,
    bool forceRelayFlush = false,
    Duration? relayFlushTimeout,
    List<String>? targetDeviceIds,
    int? priority,
    String? transportHint,
    String? retryBucket,
    String? correlationId,
    String? transportMetaJson,
    String? eventIdRef,
    // SERVER-SIDE SCHEDULED DELIVERY (2026-07-17): relay release time carried
    // to the outbox row. 0 = immediate. Used by scheduled GROUP messages so a
    // sleeping/offline sender still delivers to the room at T (parity with 1:1).
    int deliverAtMs = 0,
  }) async {
    final db = _db;
    final relay = _relay;
    final did = _deviceId;
    final keys = _keys;
    final ratchet = _ratchetV3;
    if (db == null ||
        relay == null ||
        did == null ||
        keys == null ||
        ratchet == null) {
      final err =
          'sendControlMessage SKIPPED: infra not ready (db=${db != null} relay=${relay != null} did=${did != null} keys=${keys != null} ratchet=${ratchet != null})';
      callLog('AppCtrl', err);
      if (strict) {
        throw StateError(err);
      }
      return;
    }

    _throwIfTransportBlocked();

    // FIX (2026-07-13, delivery P0): group user/system content (text, media,
    // stickers, albums, room membership) is fanned out through this control
    // path, but it MUST survive an offline recipient exactly like a 1:1 message.
    // It was inheriting the 1-hour control TTL, so the relay mailbox expired it
    // for anyone offline > 1h (overnight / workday) — silent, permanent group
    // message loss on both ends. Promote any group-envelope send to the 24h
    // user-message TTL unless the caller explicitly picked a non-default TTL
    // (ephemeral 1:1 controls — typing/receipts — never carry this prefix, so
    // they keep the short TTL).
    if (ttlSeconds == _controlMessageTtlSeconds &&
        controlText.startsWith(_groupMsgCmdPrefix)) {
      ttlSeconds = _outboxUserMessageTtlSeconds;
    }

    final now = DateTime.now().millisecondsSinceEpoch;
    final payload = E2ePayloadV1(
      senderDeviceId: did,
      createdAtMs: now,
      events:
          overrideEvents ??
          [MsgEventV1(eventId: _uuid.v4(), text: controlText)],
      // Возможности этой сборки: по ним собеседники решают, выдавать ли ей
      // ключ комнаты (выпущенным сборкам — нет).
      caps: const <String>[E2ePayloadV1.capRoomKeyV2],
    );

    // Durable per-recipient backstop, mirroring the proven 1:1 pending-no-device
    // queue: when a recipient has no resolvable/usable devices right now (keys
    // lookup empty / rate-limited / stale cache, or every per-device encrypt
    // fails), persist the control payload keyed by that recipient so
    // _retryPendingNoDeviceSend re-encrypts + sends it once their devices/session
    // recover — instead of silently dropping it. Opt-in only (group message
    // fanout → A2; room membership/system/snapshot fanout → A5). 1:1 control
    // sends never pass queueIfNoDevices, so their behaviour is unchanged. Keyed
    // per recipient (`:$peerProfileId`) so one message queued for several members
    // does not collide on pending_no_device_send's single-column PK.
    Future<void> queueNoDeviceRetry() async {
      // Self-addressed controls are dropped by the guard inside
      // `_queuePendingNoDeviceEntry` — the single choke point, so every
      // queueing path inherits it. Room broadcasts reach here because
      // `_roomSyncHintRecipientProfileIds` includes US (correctly: our OTHER
      // devices need the sync), which on a single-device profile resolves to
      // nothing and used to park an undeliverable entry forever.
      await _queuePendingNoDeviceEntry(
        profileId: peerProfileId,
        entry: _PendingNoDeviceEntry(
          localEventId: '${eventIdRef ?? _uuid.v4()}:$peerProfileId',
          payloadBytes: Uint8List.fromList(payload.encode()),
          transportMetaJson: transportMetaJson,
          createdAtMs: now,
        ),
      );
    }

    List<String> targets;
    if (targetDeviceIds != null) {
      targets = targetDeviceIds
          .where((d) => d.isNotEmpty && d != did)
          .toList(growable: false);
    } else {
      try {
        targets = await _listRecipientDevicesForSend(
          peerProfileId: peerProfileId,
          selfDeviceId: did,
        );
      } catch (e) {
        // FIX (2026-07-13, delivery F6): a thrown device lookup (e.g. keys 429 /
        // network) must NOT silently drop a durable (group/room) fanout member.
        // For the durable path (queueIfNoDevices) leave targets empty so the
        // no-device retry backstop below persists the payload and re-sends it
        // once the peer's devices resolve — instead of throwing the member away
        // with the message shown as delivered. 1:1 control sends
        // (queueIfNoDevices == false) keep their original throw semantics.
        if (!queueIfNoDevices) rethrow;
        callLog(
          'AppCtrl',
          'sendControlMessage device lookup failed, queueing retry peer=$peerProfileId: $e',
        );
        targets = const <String>[];
      }
    }
    if (targets.isEmpty && targetDeviceIds == null) {
      try {
        targets = await _listRecipientDevicesForSend(
          peerProfileId: peerProfileId,
          selfDeviceId: did,
          forceRefresh: true,
        );
      } catch (e) {
        callLog(
          'AppCtrl',
          'sendControlMessage forceRefresh failed peer=$peerProfileId: $e',
        );
      }
    }
    if (targets.isEmpty) {
      if (queueIfNoDevices) {
        await queueNoDeviceRetry();
        _changed.add(null);
        return;
      }
      final err =
          'sendControlMessage SKIPPED: no target devices for peer=$peerProfileId';
      callLog('AppCtrl', err);
      if (strict) {
        throw StateError(err);
      }
      return;
    }

    var queuedTargets = 0;
    // Сколько целей отвалилось по ВРЕМЕННОЙ причине (лимит/сеть) — от этого
    // зависит, честно ли говорить «у собеседника нет устройств».
    var transientSkips = 0;
    for (final target in targets) {
      try {
        final wire = await _encryptToPeerSerialized(
          ratchet: ratchet,
          selfDeviceId: did,
          peerProfileId: peerProfileId,
          peerDeviceId: target,
          plaintext: Uint8List.fromList(payload.encode()),
        );
        await db.outboxUpsert(
          msgId: _uuid.v4(),
          toDeviceId: target,
          ciphertextB64: base64Encode(wire),
          ttlSeconds: ttlSeconds,
          state: 'pending',
          attemptCount: 0,
          // Upload NOW; the relay holds until deliverAtMs (0 = immediate).
          nextRetryAtMs: now,
          createdAtMs: now,
          correlationId: correlationId,
          transportMetaJson: transportMetaJson,
          priority: priority,
          transportHint: transportHint,
          retryBucket: retryBucket,
          eventIdRef: eventIdRef,
          deliverAtMs: deliverAtMs,
        );
        queuedTargets++;
      } catch (e) {
        // 🔴 «НЕТ УСТРОЙСТВ» И «СЕЙЧАС НЕ ДОСТУЧАЛИСЬ» — РАЗНЫЕ ВЕЩИ (24.08.2026).
        //
        // Поле 24.08: `fetchBundle failed: 429 rate_limited` пропускал цель, и
        // звонок получал «no deliverable target devices» — то есть сообщение о
        // ПОСТОЯННОЙ причине на месте временной. Повторять никто не пробовал:
        // текст ошибки говорил, что повторять бессмысленно.
        final msg = e.toString().toLowerCase();
        if (msg.contains('429') ||
            msg.contains('rate_limited') ||
            msg.contains('timeout') ||
            msg.contains('unavailable') ||
            msg.contains('socketexception') ||
            msg.contains('connection')) {
          transientSkips++;
        }
        callLog(
          'AppCtrl',
          'sendControlMessage fanout skip target=$target peer=$peerProfileId: $e',
        );
      }
    }

    if (queuedTargets == 0) {
      if (queueIfNoDevices) {
        await queueNoDeviceRetry();
        _changed.add(null);
        return;
      }
      final err = transientSkips > 0
          ? 'sendControlMessage SKIPPED: transient send failure '
                '($transientSkips target(s) temporarily unreachable) '
                'for peer=$peerProfileId'
          : 'sendControlMessage SKIPPED: no deliverable target devices for peer=$peerProfileId';
      callLog('AppCtrl', err);
      if (strict) {
        throw StateError(err);
      }
      return;
    }

    if (!_transportBlocked) {
      if (forceRelayFlush) {
        await _kickRelayOutboxAndWait(
          relay,
          timeout: relayFlushTimeout ?? const Duration(seconds: 15),
        );
      } else {
        _kickRelayOutbox(relay);
      }
    }
  }

  /// Public entry point for sending a text message into a group/room.
  ///
  /// When [scheduledAtMs] is set to a future instant the send is *deferred*:
  /// a local `scheduled` placeholder (carrying the encrypted [MsgEventV1]
  /// payload) is persisted and the actual authoritative admission + member
  /// fanout only happen once the scheduled time arrives (driven by
  /// [_sweepDueScheduledGroupMessages] off the adaptive pump timer (1-15 s), which also
  /// makes scheduling survive an app restart). This mirrors the 1:1 scheduled
  /// path — the difference is that group sends can't ride the outbox lease
  /// (authoritative admission must happen at fire time), so we run our own
  /// sweep instead.
  Future<void> sendGroupMessage({
    required String groupId,
    required String text,
    String? replyToPayloadEventId,
    List<MsgMentionV1> mentions = const <MsgMentionV1>[],
    int? scheduledAtMs,
    String? topicId,
    LinkPreviewV1? linkPreview,
  }) async {
    final db = _db;
    final did = _deviceId;
    final crypto = _crypto;
    if (db == null || did == null || crypto == null) return;
    final outgoingPreview = linkPreviewForOutgoing(linkPreview, text);

    // Demo rooms never touch the relay; route them through the local-only
    // simulator (which honours scheduled sends with a deferred timer too).
    if (_isDemoConvoId(groupId)) {
      if (!_demoDataEnabled) {
        throw StateError('Demo chats are disabled in this build.');
      }
      await _sendDemoGroupMessage(
        groupId: groupId,
        text: text,
        replyToPayloadEventId: replyToPayloadEventId,
        scheduledAtMs: scheduledAtMs,
        topicId: topicId,
      );
      return;
    }

    final now = DateTime.now().millisecondsSinceEpoch;
    if (scheduledAtMs != null && scheduledAtMs > now) {
      await _scheduleGroupMessage(
        groupId: groupId,
        text: text,
        replyToPayloadEventId: replyToPayloadEventId,
        mentions: mentions,
        scheduledAtMs: scheduledAtMs,
        topicId: topicId,
        linkPreview: outgoingPreview,
      );
      return;
    }

    await _dispatchGroupMessageNow(
      groupId: groupId,
      text: text,
      replyToPayloadEventId: replyToPayloadEventId,
      mentions: mentions,
      topicId: topicId,
      linkPreview: outgoingPreview,
    );
  }

  /// Persists a `scheduled` group placeholder and arms the sweep. The full
  /// outgoing [MsgEventV1] payload (text + reply + mentions) is encrypted with
  /// the local symmetric provider so the sweep can faithfully reconstruct the
  /// send at fire time — even across an app restart (the placeholder lives in
  /// the events table; the sweep re-discovers it on the next pump tick).
  /// SERVER-SIDE SCHEDULED DELIVERY for ROOMS (2026-07-17). Parity with 1:1
  /// (`_scheduleDirectMessage`): the room message is admitted + fanned out to
  /// every member's devices IMMEDIATELY (while the phone is awake), each outbox
  /// row tagged `deliver_at_ms = scheduledAtMs`, so the relay releases them at
  /// T even if the sender is asleep / offline. The wire `createdAtMs` is the
  /// scheduled time, so recipients see the intended moment.
  ///
  /// A local `scheduled` placeholder is written FIRST (survives a no-network
  /// schedule). On a successful server-side fanout it is flipped out of the
  /// client sweep (markScheduledDirectUploaded) so the sweep can't ALSO fire it
  /// — no duplicate. If admission/fanout fails (no network at schedule time),
  /// the placeholder stays `scheduled` and the legacy client sweep fires it on
  /// the next wake (degraded but never lost).
  Future<void> _scheduleGroupMessage({
    required String groupId,
    required String text,
    String? replyToPayloadEventId,
    required List<MsgMentionV1> mentions,
    required int scheduledAtMs,
    String? topicId,
    LinkPreviewV1? linkPreview,
  }) async {
    final db = _db;
    final did = _deviceId;
    final crypto = _crypto;
    if (db == null || did == null || crypto == null) return;
    await _ensureRoomActionAllowed(groupId, RoomAction.sendText);

    final group = await db.convoGet(groupId);
    final groupTitle = ((group?['title'] as String?) ?? 'Group').trim();
    await db.convoEnsureGroup(
      groupId: groupId,
      title: groupTitle.isEmpty ? 'Group' : groupTitle,
    );

    final msgEventId = _uuid.v4();
    final now = DateTime.now().millisecondsSinceEpoch;
    final normalizedTopicId = (topicId ?? '').trim().isEmpty ? null : topicId;
    // Room messages travel as a control envelope (built below with
    // createdAtMs=scheduledAtMs), NOT a per-peer E2ePayload — so recipients see
    // the scheduled time. Only the LOCAL history copy is a symmetric payload,
    // timestamped NOW so it sorts correctly (the badge shows T).
    final localPayload = E2ePayloadV1(
      senderDeviceId: did,
      createdAtMs: now,
      events: [
        MsgEventV1(
          eventId: msgEventId,
          text: text,
          replyToEventId: replyToPayloadEventId,
          mentions: mentions,
          topicId: normalizedTopicId,
          linkPreview: linkPreview,
        ),
      ],
    );
    final localCipher = await crypto.encrypt(localPayload.encode());
    final localEventId = 'local:grpsched:$msgEventId';
    await db.insertEvent(
      eventId: localEventId,
      convoId: groupId,
      type: 'msg',
      senderDeviceId: did,
      ciphertextB64: base64Encode(localCipher),
      createdAtMs: now,
      localState: MessageLocalState.scheduled,
      payloadEventId: msgEventId,
      scheduledAtMs: scheduledAtMs,
    );
    await db.convoTouch(convoId: groupId, atMs: now);
    _changed.add(null);

    // Server-side upload path (preferred). On any failure we simply leave the
    // scheduled placeholder for the legacy client sweep — nothing is lost.
    if (_transportBlocked) return;
    try {
      if (_useAuthoritativeRoomRelay) {
        // Occupy the room slot now; the message is "sent as of T".
        await _admitAuthoritativeRoomMessage(
          groupId: groupId,
          messageId: msgEventId,
          kind: 'text',
        );
      } else {
        return; // no authoritative relay → keep placeholder + sweep
      }

      final senderPid = profileId;
      var members = await listGroupMembers(groupId);
      var recipients = members
          .where((m) => m.isNotEmpty && m != senderPid)
          .toList(growable: false);
      if (recipients.isEmpty && members.isEmpty) {
        await _tryRefreshRoomFromRelayBestEffort(groupId);
        members = await listGroupMembers(groupId);
        recipients = members
            .where((m) => m.isNotEmpty && m != senderPid)
            .toList(growable: false);
      }

      final transportMetaJson = _buildChatTransportMetaJson(
        convoId: groupId,
        isGroup: true,
        messageKind: 'text',
        payloadEventId: msgEventId,
        createdAtMs: scheduledAtMs,
        senderProfileId: senderPid,
        senderDisplayName: myNickname,
        convoTitle: groupTitle,
        previewText: text,
      );
      final envelope = <String, Object?>{
        'v': 1,
        'kind': 'message',
        'groupId': groupId,
        'groupTitle': groupTitle,
        'msgEventId': msgEventId,
        'text': text,
        'replyToPayloadEventId': replyToPayloadEventId,
        if (mentions.isNotEmpty)
          'mentions':
              mentions.map((m) => m.toJson()).toList(growable: false),
        if (normalizedTopicId != null) 'topicId': normalizedTopicId,
        if (linkPreview != null) 'linkPreview': linkPreview.toJson(),
        'createdAtMs': scheduledAtMs,
        'memberProfileIds': members,
        'senderProfileId': senderPid,
        'senderName': myNickname.trim().isEmpty ? null : myNickname.trim(),
        'senderAvatarPath': _myAvatarPath,
      };
      final controlText =
          '$_groupMsgCmdPrefix${base64Url.encode(utf8.encode(jsonEncode(envelope)))}';

      var delivered = 0;
      for (final member in recipients) {
        try {
          await sendControlMessage(
            peerProfileId: member,
            controlText: controlText,
            transportMetaJson: transportMetaJson,
            eventIdRef: localEventId,
            strict: true,
            queueIfNoDevices: true,
            deliverAtMs: scheduledAtMs,
          );
          delivered++;
        } catch (e) {
          DiagLog.event('send', 'grpsched_fanout_failed', {
            'group': DiagLog.pfx(groupId),
            'member': DiagLog.pfx(member),
          });
        }
      }
      // Even a solo room (no recipients) is a valid server-side schedule — the
      // placeholder is the record; own-device mirror carries it. Flip out of
      // the client sweep whenever we got the message onto the relay path.
      if (delivered > 0 || recipients.isEmpty) {
        // Retry on SQLITE_BUSY: if this flip is swallowed the placeholder stays
        // `scheduled` and the client sweep ALSO fires it at T with a fresh
        // msg_id → duplicate (relay/recipient dedup can't match different ids).
        try {
          await _retryDbBusy(
            () => db.markScheduledDirectUploaded(localEventId),
          );
        } catch (_) {}
        unawaited(
          _mirrorGroupControlEnvelopeToOwnDevices(controlText: controlText),
        );
        _kickRelayOutbox();
        DiagLog.event('send', 'grpsched_server_side', {
          'group': DiagLog.pfx(groupId),
          'devices': delivered,
          'deliver_at': scheduledAtMs,
        });
      }
    } catch (e) {
      // Admission/network failure at schedule time → keep the scheduled
      // placeholder; the client sweep fires it on the next wake (degraded).
      DiagLog.event('send', 'grpsched_upload_deferred', {
        'group': DiagLog.pfx(groupId),
        'err': e.runtimeType.toString(),
      });
    }
  }

  Future<void> _dispatchGroupMessageNow({
    required String groupId,
    required String text,
    String? replyToPayloadEventId,
    List<MsgMentionV1> mentions = const <MsgMentionV1>[],
    String? topicId,
    LinkPreviewV1? linkPreview,
  }) async {
    final db = _db;
    final did = _deviceId;
    final crypto = _crypto;
    if (db == null || did == null || crypto == null) return;
    await _ensureRoomActionAllowed(groupId, RoomAction.sendText);

    final group = await db.convoGet(groupId);
    final groupTitle = ((group?['title'] as String?) ?? 'Group').trim();
    await db.convoEnsureGroup(
      groupId: groupId,
      title: groupTitle.isEmpty ? 'Group' : groupTitle,
    );

    final msgEventId = _uuid.v4();
    RelayRoomMessageAdmissionResult? admission;
    if (_useAuthoritativeRoomRelay) {
      admission = await _admitAuthoritativeRoomMessage(
        groupId: groupId,
        messageId: msgEventId,
        kind: 'text',
      );
    } else {
      _throwIfRoomMutationAuthoritativeRelayUnavailable();
    }
    final createdAt =
        admission?.admittedAtMs ?? DateTime.now().millisecondsSinceEpoch;
    final senderPid = profileId;
    final normalizedTopicId = (topicId ?? '').trim().isEmpty ? null : topicId;
    final payload = E2ePayloadV1(
      senderDeviceId: did,
      createdAtMs: createdAt,
      events: [
        MsgEventV1(
          eventId: msgEventId,
          text: text,
          replyToEventId: replyToPayloadEventId,
          mentions: mentions,
          topicId: normalizedTopicId,
          linkPreview: linkPreview,
        ),
      ],
    );
    final localCipher = await crypto.encrypt(payload.encode());
    final localEventId = 'local:grp:$msgEventId';
    final transportMetaJson = _buildChatTransportMetaJson(
      convoId: groupId,
      isGroup: true,
      messageKind: 'text',
      payloadEventId: msgEventId,
      createdAtMs: createdAt,
      senderProfileId: senderPid,
      senderDisplayName: myNickname,
      convoTitle: groupTitle,
      previewText: text,
    );
    await db.insertEvent(
      eventId: localEventId,
      convoId: groupId,
      type: 'msg',
      senderDeviceId: did,
      ciphertextB64: base64Encode(localCipher),
      createdAtMs: createdAt,
      localState: 'pending',
      payloadEventId: msgEventId,
    );
    await db.convoTouch(convoId: groupId, atMs: createdAt);

    var members = await listGroupMembers(groupId);
    var recipients = members
        .where((m) => m.isNotEmpty && m != senderPid)
        .toList(growable: false);
    if (recipients.isEmpty && members.isEmpty) {
      // Local cache is completely empty — pull authoritative state from relay
      // before assuming we have no recipients.
      await _tryRefreshRoomFromRelayBestEffort(groupId);
      members = await listGroupMembers(groupId);
      recipients = members
          .where((m) => m.isNotEmpty && m != senderPid)
          .toList(growable: false);
    }
    if (recipients.isEmpty) {
      callLog(
        'AppCtrl',
        'sendGroupMessage solo-room: no recipients to fan out (group=$groupId members=${members.length})',
      );
    }

    final envelope = <String, Object?>{
      'v': 1,
      'kind': 'message',
      'groupId': groupId,
      'groupTitle': groupTitle,
      'msgEventId': msgEventId,
      'text': text,
      'replyToPayloadEventId': replyToPayloadEventId,
      if (mentions.isNotEmpty)
        'mentions': mentions
            .map((mention) => mention.toJson())
            .toList(growable: false),
      if (normalizedTopicId != null) 'topicId': normalizedTopicId,
      // Превью в конверте комнаты: у комнаты по проводу едет только конверт.
      if (linkPreview != null) 'linkPreview': linkPreview.toJson(),
      'createdAtMs': createdAt,
      'memberProfileIds': members,
      'senderProfileId': senderPid,
      'senderName': myNickname.trim().isEmpty ? null : myNickname.trim(),
      'senderAvatarPath': _myAvatarPath,
    };
    final controlText =
        '$_groupMsgCmdPrefix${base64Url.encode(utf8.encode(jsonEncode(envelope)))}';

    // ROOM SENDER KEY (фаза 3б). Seal the envelope ONCE under the room key and
    // hand every member the same object; null means "not ready" and the
    // ordinary pairwise fanout below carries this message unchanged.
    final roomWireEvents = await _sealRoomMessageForSenderKey(
      db: db,
      roomId: groupId,
      controlText: controlText,
      createdAtMs: createdAt,
      memberProfileIds: recipients,
    );

    var delivered = 0;
    final failedRecipients = <String, Object>{};
    // К-3: конверт — для повтора тому, у кого пропуск.
    await _rememberRoomEnvelope(db: db, roomId: groupId, controlText: controlText);
    // К-2: один запрос к реле для тех, кто умеет сырой провод.
    final rawRemaining = await _roomRawBroadcast(
      db: db,
      roomId: groupId,
      events: roomWireEvents,
      recipients: recipients,
      transportMetaJson: transportMetaJson,
      localEventId: localEventId,
    );
    for (final member in recipients) {
      final rawTargets = rawRemaining?[member];
      if (rawTargets != null && rawTargets.isEmpty) {
        delivered++;
        continue;
      }
      try {
        await sendControlMessage(
          peerProfileId: member,
          controlText: controlText,
          overrideEvents: roomWireEvents,
          targetDeviceIds: rawTargets,
          transportMetaJson: transportMetaJson,
          eventIdRef: localEventId,
          strict: true,
          queueIfNoDevices: true,
        );
        delivered++;
      } catch (e) {
        failedRecipients[member] = e;
        // DiagLog, not callLog: callLog is COMPILED OUT of release builds, so
        // in the field "one member never got the message" — the single most
        // reported room symptom — left no trace at all. Same lesson as the 1:1
        // fanout on 2026-07-28.
        DiagLog.event('send', 'room_fanout_member_failed', {
          'group': DiagLog.pfx(groupId),
          'member': DiagLog.pfx(member),
          'reason': _classifyShortReason(e),
        });
      }
    }
    if (recipients.isNotEmpty && delivered == 0) {
      DiagLog.event('send', 'room_fanout_all_failed', {
        'group': DiagLog.pfx(groupId),
        'recipients': recipients.length,
      });
      throw RoomPolicyFailure(RoomPolicyFailureCode.allRecipientsUnavailable);
    }
    if (failedRecipients.isNotEmpty) {
      // A PARTIAL fanout is the dangerous case: the message looks sent (someone
      // got it) while a specific member silently has nothing, and the send path
      // itself never retries them. Repair belongs to the room convergence
      // backstop — which is why that backstop has to be ON, not merely written.
      DiagLog.event('send', 'room_fanout_partial', {
        'group': DiagLog.pfx(groupId),
        'delivered': delivered,
        'of': recipients.length,
        'failed': failedRecipients.length,
      });
    }

    // Sprint 2 / PR3: replicate the same envelope to my own OTHER devices so
    // they show this group message (and, crucially, apply delete-for-all
    // tombstones I issued from a different device). Best-effort.
    unawaited(
      _mirrorGroupControlEnvelopeToOwnDevices(controlText: controlText),
    );

    _changed.add(null);
  }

  /// Local-only demo room send. Mirrors the 1:1 demo path: the bubble shows
  /// the normal sending → delivered → read progression and a demo member auto-
  /// replies. Honours [scheduledAtMs] by deferring the whole sequence, so the
  /// "send later" clock looks identical to a real room.
  Future<void> _sendDemoGroupMessage({
    required String groupId,
    required String text,
    String? replyToPayloadEventId,
    int? scheduledAtMs,
    String? topicId,
  }) async {
    final db = _db;
    final did = _deviceId;
    final crypto = _crypto;
    if (db == null || did == null || crypto == null) return;

    final demoTitle = _demoDisplayName(groupId);
    await db.convoEnsureGroup(
      groupId: groupId,
      title: demoTitle.isEmpty ? 'Group' : demoTitle,
    );

    final eventId = _uuid.v4();
    final now = DateTime.now().millisecondsSinceEpoch;
    final payload = E2ePayloadV1(
      senderDeviceId: did,
      createdAtMs: now,
      events: [
        MsgEventV1(
          eventId: eventId,
          text: text,
          replyToEventId: replyToPayloadEventId,
          topicId: (topicId ?? '').trim().isEmpty ? null : topicId,
        ),
      ],
    );
    final cipher = await crypto.encrypt(payload.encode());

    final schedMs = scheduledAtMs;
    final isScheduledDemo = schedMs != null && schedMs > now;
    await db.insertEvent(
      eventId: 'local:grp:$eventId',
      convoId: groupId,
      type: 'msg',
      senderDeviceId: did,
      ciphertextB64: base64Encode(cipher),
      createdAtMs: now,
      localState: isScheduledDemo ? MessageLocalState.scheduled : 'sent',
      payloadEventId: eventId,
      scheduledAtMs: isScheduledDemo ? schedMs : null,
    );
    await db.convoTouch(convoId: groupId, atMs: now);
    _changed.add(null);

    void runDemoDelivery() {
      if (isScheduledDemo) {
        unawaited(() async {
          final dbS = _db;
          if (dbS == null) return;
          await dbS.updateLocalStateByPayloadEventId(
            payloadEventId: eventId,
            localState: 'sent',
          );
          await dbS.convoTouch(
            convoId: groupId,
            atMs: DateTime.now().millisecondsSinceEpoch,
          );
          _changed.add(null);
        }());
      }

      Future.delayed(const Duration(milliseconds: 900), () async {
        final db2 = _db;
        if (db2 == null) return;
        await db2.updateLocalStateByPayloadEventId(
          payloadEventId: eventId,
          localState: 'delivered',
        );
        _changed.add(null);
      });
      Future.delayed(const Duration(milliseconds: 1600), () async {
        final db2 = _db;
        if (db2 == null) return;
        await db2.updateLocalStateByPayloadEventId(
          payloadEventId: eventId,
          localState: 'read',
        );
        _changed.add(null);
      });

      // A demo room member echoes back so the thread feels alive — but NOT for
      // control texts (poll spec / hidden vote commands), which shouldn't draw
      // a chatty "👍" reply.
      if (isPollCommandText(text) ||
          isEventCommandText(text) ||
          isHiddenMessageControlText(text)) {
        return;
      }
      Future.delayed(const Duration(milliseconds: 700), () async {
        final db2 = _db;
        final crypto2 = _crypto;
        if (db2 == null || crypto2 == null) return;
        final members = _demoGroupMemberProfileIds(groupId);
        if (members.isEmpty) return;
        final replierProfileId = members.first;
        final replierDevice = _demoSenderDeviceForProfile(replierProfileId);
        final rid = _uuid.v4();
        final reply = E2ePayloadV1(
          senderDeviceId: replierDevice,
          createdAtMs: DateTime.now().millisecondsSinceEpoch,
          events: [
            MsgEventV1(eventId: rid, text: '👍 ${_demoAutoReply(groupId)}'),
          ],
        );
        final c2 = await crypto2.encrypt(reply.encode());
        final t2 = DateTime.now().millisecondsSinceEpoch;
        await db2.insertEvent(
          eventId: 'in:$rid',
          convoId: groupId,
          type: 'msg',
          senderDeviceId: replierDevice,
          ciphertextB64: base64Encode(c2),
          createdAtMs: t2,
          localState: 'received',
        );
        await db2.convoTouch(convoId: groupId, atMs: t2);
        _changed.add(null);
      });
    }

    if (isScheduledDemo) {
      Future.delayed(Duration(milliseconds: schedMs - now), runDemoDelivery);
    } else {
      runDemoDelivery();
    }
  }

  // ── Polls (room feature) ─────────────────────────────────────────────────
  // Polls ride entirely on the existing group-message pipeline: the poll spec
  // is a visible group message (rendered as an interactive card), votes are
  // hidden group messages. The chat tallies votes from the events it already
  // holds — no extra DB table or receive handler.

  /// Creates a poll in [groupId]. Reuses [sendGroupMessage] so fanout,
  /// self-mirror to my other devices, persistence and (demo) simulation all
  /// come for free.
  Future<void> sendGroupPoll({
    required String groupId,
    required String question,
    required List<String> options,
    bool multiple = false,
    bool anonymous = false,
    String? topicId,
  }) async {
    final cleanedQuestion = question.trim();
    final cleanedOptions = options
        .map((option) => option.trim())
        .where((option) => option.isNotEmpty)
        .toList(growable: false);
    if (cleanedQuestion.isEmpty || cleanedOptions.length < 2) {
      throw StateError('A poll needs a question and at least two options.');
    }
    await _ensureRoomActionAllowed(groupId, RoomAction.sendText);
    final pollId = _uuid.v4();
    final commandText = buildPollCommand(
      pollId: pollId,
      question: cleanedQuestion,
      options: cleanedOptions,
      multiple: multiple,
      anonymous: anonymous,
    );
    await sendGroupMessage(
      groupId: groupId,
      text: commandText,
      topicId: topicId,
    );
  }

  /// Casts (or replaces) my vote on [pollId] in [groupId]. The vote is a hidden
  /// group message reporting my profile id + chosen option indices; every
  /// member's timeline tallies the latest vote per voter.
  Future<void> voteGroupPoll({
    required String groupId,
    required String pollId,
    required List<int> optionIndices,
  }) async {
    final pid = _profileId;
    if (pid == null) return;
    await _ensureRoomActionAllowed(groupId, RoomAction.sendText);
    final normalized = optionIndices.toSet().toList(growable: false)..sort();
    final commandText = buildPollVoteCommand(
      pollId: pollId,
      optionIndices: normalized,
      voterProfileId: pid,
      voterName: myNickname.trim().isEmpty ? null : myNickname.trim(),
    );
    await sendGroupMessage(groupId: groupId, text: commandText);
  }

  /// Closes [pollId] in [groupId] to further votes. The receiving client only
  /// honours this if the caller's profile id matches the poll's resolved
  /// creator (see chat_screen.dart tally) — same client-derived trust model
  /// already used for pins/roles, no separate server-side check.
  Future<void> closeGroupPoll({
    required String groupId,
    required String pollId,
  }) async {
    final pid = _profileId;
    if (pid == null) return;
    await _ensureRoomActionAllowed(groupId, RoomAction.sendText);
    final commandText = buildPollCloseCommand(
      pollId: pollId,
      closerProfileId: pid,
      closedAtMs: DateTime.now().millisecondsSinceEpoch,
    );
    await sendGroupMessage(groupId: groupId, text: commandText);
  }

  // ── Events / RSVP (room feature) ─────────────────────────────────────────

  /// Creates an event in [groupId] (rendered as an RSVP card).
  Future<void> sendGroupEvent({
    required String groupId,
    required String title,
    required int startMs,
    String description = '',
    String location = '',
    String? topicId,
  }) async {
    final cleanedTitle = title.trim();
    if (cleanedTitle.isEmpty || startMs <= 0) {
      throw StateError('An event needs a title and a date.');
    }
    await _ensureRoomActionAllowed(groupId, RoomAction.sendText);
    final eventId = _uuid.v4();
    final commandText = buildEventCommand(
      eventId: eventId,
      title: cleanedTitle,
      startMs: startMs,
      description: description,
      location: location,
    );
    await sendGroupMessage(
      groupId: groupId,
      text: commandText,
      topicId: topicId,
    );
  }

  /// Records my RSVP ('going' | 'maybe' | 'no' | '' to clear) on [eventId]
  /// in [groupId].
  Future<void> rsvpGroupEvent({
    required String groupId,
    required String eventId,
    required String status,
  }) async {
    final pid = _profileId;
    if (pid == null) return;
    await _ensureRoomActionAllowed(groupId, RoomAction.sendText);
    final commandText = buildEventRsvpCommand(
      eventId: eventId,
      status: status,
      voterProfileId: pid,
      voterName: myNickname.trim().isEmpty ? null : myNickname.trim(),
    );
    await sendGroupMessage(groupId: groupId, text: commandText);
  }

  // ── Pinned-message sync (room feature) ───────────────────────────────────

  /// Broadcasts the room's full pinned-message set to every member. Reuses the
  /// group-message pipeline (hidden control message). Receivers derive their
  /// shared pin list from the latest such message. The room-level single pin
  /// (`pinnedMessageEventId`) is also updated to the newest pin so older
  /// clients that only understand one pin still show something sensible.
  Future<void> broadcastRoomPins({
    required String groupId,
    required List<({String eventId, String previewText, int pinnedAtMs})> pins,
  }) async {
    await _ensureRoomActionAllowed(groupId, RoomAction.pinMessage);
    final refs = pins
        .where((pin) => pin.eventId.trim().isNotEmpty)
        .map(
          (pin) => PinnedRef(
            eventId: pin.eventId.trim(),
            previewText: pin.previewText,
            pinnedAtMs: pin.pinnedAtMs,
          ),
        )
        .toList(growable: false);
    final commandText = buildPinSyncCommand(refs);
    await sendGroupMessage(groupId: groupId, text: commandText);
  }

  // ── Topics / threads (room feature) ──────────────────────────────────────

  /// Broadcasts the room's full topic set to every member (hidden control
  /// message, latest-wins). Receivers adopt the list; individual messages
  /// carry their `topicId` so the UI can filter. Gated on the group-info
  /// permission so only admins (or members the room allows) manage topics.
  // ───────────── Список тем комнаты: хранение и приём ──────────────────────

  /// Сохранённый список тем комнаты. Пусто — тем нет или мы о них не знаем.
  ///
  /// 🔴 ПОЧЕМУ ЭТО ВООБЩЕ ПОНАДОБИЛОСЬ (15.09.2026, по жалобе владельца).
  ///
  /// Список тем рассылается скрытым сообщением внутри переписки, а экраны
  /// собирали его заново из ЗАГРУЖЕННОГО ОКНА ленты — последних двухсот
  /// событий. Отсюда обе жалобы сразу: «на компьютере тем нет» (сообщение со
  /// списком не попало в окно) и «в теме пустой чат» (сообщения с неизвестным
  /// `topic_id` по правилу уезжают в «Общий»). Через двести сообщений темы
  /// пропадали у всех.
  ///
  /// Теперь список живёт в базе рядом с историей, а лента остаётся каналом
  /// доставки, а не хранилищем.
  Future<RoomTopicsState> loadRoomTopics(String groupId) async {
    final db = _db;
    if (db == null) return const RoomTopicsState();
    try {
      final row = await db.roomTopicsGet(groupId);
      if (row == null) return const RoomTopicsState();
      final state = decodeRoomTopicsState(row.topicsJson);
      final sorted = List<RoomTopicRef>.from(state.topics)
        ..sort((a, b) => a.createdAtMs.compareTo(b.createdAtMs));
      return RoomTopicsState(
        topics: List<RoomTopicRef>.unmodifiable(sorted),
        baseMark: state.baseMark,
      );
    } catch (_) {
      return const RoomTopicsState();
    }
  }

  /// Отметка времени сообщения, из которого принят сохранённый список.
  /// Экран сравнивает её с найденным в ленте, чтобы не принимать старое.
  Future<int> roomTopicsSyncedAtMs(String groupId) async {
    final db = _db;
    if (db == null) return 0;
    try {
      final row = await db.roomTopicsGet(groupId);
      return row?.syncedAtMs ?? 0;
    } catch (_) {
      return 0;
    }
  }

  /// Запоминает список тем комнаты. Побеждает более свежая отметка времени —
  /// та же «последний выиграл», что и у самой рассылки.
  Future<void> rememberRoomTopics({
    required String groupId,
    required List<RoomTopicRef> topics,
    required int syncedAtMs,
    String baseMark = '',
  }) async {
    final db = _db;
    if (db == null) return;
    try {
      await db.roomTopicsSet(
        roomId: groupId,
        topicsJson: encodeRoomTopicsState(
          RoomTopicsState(topics: topics, baseMark: baseMark),
        ),
        syncedAtMs: syncedAtMs,
      );
    } catch (_) {
      // Хранение — подстраховка поверх рассылки: не записалось, значит экран
      // соберёт список из ленты, как и раньше.
    }
  }

  /// 🔴 ПРИНИМАЕТ САМИ ТЕМЫ, А НЕ ИХ ПЕРЕСКАЗ (15.09.2026).
  ///
  /// Раньше здесь стоял набор полей — `(id, title, emoji, createdAtMs)`, — и
  /// каждый вызывающий пересобирал тему руками. Стоило добавить теме поле
  /// (знак), и десктоп начал БЕСШУМНО ТЕРЯТЬ его при любой правке: список
  /// уходил в рассылку без знака и стирал его у всех. Тип `RoomTopicRef`
  /// целиком не оставляет такой возможности.
  Future<void> broadcastRoomTopics({
    required String groupId,
    required List<RoomTopicRef> topics,
    String baseMark = '',
  }) async {
    await _ensureRoomActionAllowed(groupId, RoomAction.changeGroupInfo);
    final refs = topics
        .where(
          (topic) =>
              topic.id.trim().isNotEmpty && topic.title.trim().isNotEmpty,
        )
        .map(
          (topic) => RoomTopicRef(
            id: topic.id.trim(),
            title: topic.title.trim(),
            emoji: topic.emoji,
            mark: topic.mark,
            createdAtMs: topic.createdAtMs,
          ),
        )
        .toList(growable: false);
    final commandText = buildTopicsSyncCommand(refs, baseMark: baseMark);
    // 🔴 Запоминаем ДО отправки: список тем — уже решение человека, и он не
    // должен зависеть от того, дошло ли сообщение до релея. Отметка времени
    // местная: у рассылки она тоже местная (время создания сообщения).
    await rememberRoomTopics(
      groupId: groupId,
      topics: refs,
      syncedAtMs: DateTime.now().millisecondsSinceEpoch,
      baseMark: baseMark,
    );
    await sendGroupMessage(groupId: groupId, text: commandText);
  }

  // In-flight guard so the recurring sweep does not double-dispatch the same
  // scheduled group message while its (async) admission/fanout is running.
  final Set<String> _firingScheduledGroupEventIds = <String>{};
  // Per-event soft backoff: if a fire attempt fails (e.g. relay offline at the
  // scheduled instant) we don't want to retry every single tick. Keyed by the
  // placeholder event_id → earliest next attempt (epoch ms).
  final Map<String, int> _scheduledGroupRetryAfterMs = <String, int>{};
  bool _scheduledGroupSweepInFlight = false;

  /// Fires any group messages whose scheduled time has arrived. Driven by the
  /// adaptive pump timer, so it also restores scheduling after an app restart
  /// (the placeholders live in the events table). Demo rooms are skipped — they
  /// run their own deferred timer inside [_sendDemoGroupMessage].
  Future<void> _sweepDueScheduledGroupMessages() async {
    if (_scheduledGroupSweepInFlight) return;
    final db = _db;
    if (db == null) return;
    _scheduledGroupSweepInFlight = true;
    try {
      final nowMs = DateTime.now().millisecondsSinceEpoch;
      final due = await db.listDueScheduledGroupEvents(nowMs: nowMs, limit: 25);
      if (due.isEmpty) return;
      for (final row in due) {
        final eventId = ((row['event_id'] as String?) ?? '').trim();
        if (eventId.isEmpty) continue;
        final convoId = ((row['convo_id'] as String?) ?? '').trim();
        if (convoId.isEmpty || _isDemoConvoId(convoId)) continue;
        if (_firingScheduledGroupEventIds.contains(eventId)) continue;
        final retryAfter = _scheduledGroupRetryAfterMs[eventId];
        if (retryAfter != null && nowMs < retryAfter) continue;
        _firingScheduledGroupEventIds.add(eventId);
        unawaited(_fireScheduledGroupMessage(eventId: eventId));
      }
    } catch (_) {
      // best-effort; next tick retries.
    } finally {
      _scheduledGroupSweepInFlight = false;
    }
  }

  Future<void> _fireScheduledGroupMessage({required String eventId}) async {
    final db = _db;
    if (db == null) {
      _firingScheduledGroupEventIds.remove(eventId);
      return;
    }
    try {
      final row = await db.eventGet(eventId);
      if (row == null) {
        _scheduledGroupRetryAfterMs.remove(eventId);
        return;
      }
      // Already promoted out of `scheduled` (e.g. cancelled) — drop it.
      final state = ((row['local_state'] as String?) ?? '').trim();
      if (state != MessageLocalState.scheduled) {
        _scheduledGroupRetryAfterMs.remove(eventId);
        return;
      }
      final convoId = ((row['convo_id'] as String?) ?? '').trim();
      if (convoId.isEmpty) return;

      final plain = await _decryptStoredLocalPayloadBytes(eventId);
      if (plain == null) {
        // Can't reconstruct payload — back off and try again later.
        _scheduledGroupRetryAfterMs[eventId] =
            DateTime.now().millisecondsSinceEpoch + 30000;
        return;
      }
      final payload = E2ePayloadV1.decode(plain);
      final msgEvents = payload.events.whereType<MsgEventV1>();
      if (msgEvents.isEmpty) {
        // Malformed placeholder — remove so it doesn't loop forever.
        await db.deleteEventsByIds([eventId]);
        _scheduledGroupRetryAfterMs.remove(eventId);
        _changed.add(null);
        return;
      }
      final msgEvent = msgEvents.first;

      // SERVER-SIDE OWNERSHIP GUARD (2026-07-18) — same rationale as the 1:1
      // path: `_scheduleGroupMessage` fans the envelope out to the relay
      // EAGERLY (each member's row held until T) and flips this placeholder out
      // of the sweep only on a best-effort basis. If that flip lost to
      // SQLITE_BUSY we land here at T, and a fresh dispatch would emit a SECOND
      // copy under a new msgEventId alongside the relay's held release — so
      // members would see the message twice. Any outbox row tied to this
      // placeholder means the relay path already owns delivery.
      if (await db.outboxCountForEventRef(eventId) > 0) {
        try {
          await _retryDbBusy(() => db.markScheduledDirectUploaded(eventId));
        } catch (_) {}
        _scheduledGroupRetryAfterMs.remove(eventId);
        _changed.add(null);
        return;
      }

      // Dispatch FIRST (authoritative admission + member fanout) so a failure
      // here leaves the scheduled placeholder intact — no message is ever lost.
      // The real send inserts its own fresh `local:grp:<id>` bubble at the
      // admission time; we then drop the placeholder so only one bubble shows.
      await _dispatchGroupMessageNow(
        groupId: convoId,
        text: msgEvent.text,
        replyToPayloadEventId: msgEvent.replyToEventId,
        mentions: msgEvent.mentions,
        topicId: msgEvent.topicId,
        linkPreview: msgEvent.linkPreview,
      );
      await db.deleteEventsByIds([eventId]);
      _scheduledGroupRetryAfterMs.remove(eventId);
      _changed.add(null);
    } catch (e) {
      // Dispatch failed (e.g. relay momentarily unavailable). The placeholder
      // is still present, so back off and let the next sweep retry without
      // spamming admission attempts every second.
      _scheduledGroupRetryAfterMs[eventId] =
          DateTime.now().millisecondsSinceEpoch + 30000;
      callLog('AppCtrl', 'scheduled group fire failed event=$eventId: $e');
    } finally {
      _firingScheduledGroupEventIds.remove(eventId);
    }
  }

  // ── 1:1 scheduled ("send later") — mirrors the group scheduled path above ──
  // In-flight guard so the recurring sweep does not double-dispatch the same
  // scheduled 1:1 message while its (async) send is running.
  final Set<String> _firingScheduledDirectEventIds = <String>{};
  // Per-event soft backoff: if a fire attempt fails (relay offline at the
  // scheduled instant) we don't retry every single tick. Keyed by placeholder
  // event_id → earliest next attempt (epoch ms).
  final Map<String, int> _scheduledDirectRetryAfterMs = <String, int>{};
  bool _scheduledDirectSweepInFlight = false;

  /// Persists a `scheduled` 1:1 placeholder and lets the pump sweep fire it at
  /// its due time. The outgoing text (+reply) is encrypted with the LOCAL
  /// symmetric provider so the sweep can faithfully reconstruct the send at
  /// fire time — even across an app restart (the placeholder lives in the
  /// events table; the sweep re-discovers it on the next pump tick). No outbox
  /// row is created until it fires, which keeps the message editable/
  /// cancellable and is the root-cause fix for "scheduled 1:1 sends immediately"
  /// (a future-dated outbox row used to be re-armed to `now` by the
  /// stuck-pending watchdog).
  /// SERVER-SIDE SCHEDULED DELIVERY (2026-07-17). Overnight "send later" used to
  /// keep a local placeholder and rely on a 1-second client sweep to encrypt +
  /// enqueue at the due moment — which Doze freezes, so nothing left the phone
  /// until it woke (Igor: 8 scheduled 1–5am, 2 arrived both at 5:05, 5 lost).
  ///
  /// Now the message is encrypted-to-peer and uploaded to the relay IMMEDIATELY
  /// (while the phone is awake), tagged with `deliver_at_ms = scheduledAtMs`.
  /// The relay holds the ciphertext and releases it at T — the sender can sleep,
  /// power off, fly. The wire `createdAtMs` is the scheduled time, so the
  /// recipient sees the intended time, not the release/wake time.
  ///
  /// The durable outbox does the reliable upload (retry-until-relay-ack), so a
  /// flaky network at schedule time is fine as long as the phone is awake at
  /// some point before T. Fallback: if the peer has no registered devices yet,
  /// keep the legacy local placeholder + client sweep so the message is not
  /// lost — it fires when a device appears (rare edge).
  Future<void> _scheduleDirectMessage({
    required String peerProfileId,
    required String text,
    String? replyToPayloadEventId,
    required int scheduledAtMs,
    LinkPreviewV1? linkPreview,
  }) async {
    final db = _db;
    final did = _deviceId;
    final crypto = _crypto;
    final ratchet = _ratchetV3;
    if (db == null || did == null || crypto == null) return;

    final msgEventId = _uuid.v4();
    final now = DateTime.now().millisecondsSinceEpoch;
    final myPid = _profileId;

    // Wire payload the RECIPIENT decrypts: stamped with the SCHEDULED time so
    // they see the intended moment.
    final peerPayload = E2ePayloadV1(
      senderDeviceId: did,
      createdAtMs: scheduledAtMs,
      events: [
        MsgEventV1(
          eventId: msgEventId,
          text: text,
          replyToEventId: replyToPayloadEventId,
          linkPreview: linkPreview,
        ),
      ],
    );
    // Local history copy: symmetric, timestamped NOW so it sorts correctly in
    // this device's timeline (the scheduled badge shows T).
    final localPayload = E2ePayloadV1(
      senderDeviceId: did,
      createdAtMs: now,
      events: [
        MsgEventV1(
          eventId: msgEventId,
          text: text,
          replyToEventId: replyToPayloadEventId,
          linkPreview: linkPreview,
        ),
      ],
    );
    final localCipher = await crypto.encrypt(localPayload.encode());
    final localEventId = 'local:dirsched:$msgEventId';

    await db.convoEnsure1to1(peerProfileId: peerProfileId);
    await _retryDbBusy(() async {
      await db.insertEvent(
        eventId: localEventId,
        convoId: peerProfileId,
        type: 'msg',
        senderDeviceId: did,
        ciphertextB64: base64Encode(localCipher),
        createdAtMs: now,
        localState: MessageLocalState.scheduled,
        payloadEventId: msgEventId,
        scheduledAtMs: scheduledAtMs,
      );
      await db.convoTouch(convoId: peerProfileId, atMs: now);
    });
    _changed.add(null);

    // Server-side upload path (preferred). Needs a ready ratchet + resolvable
    // recipient devices; otherwise fall back to the local placeholder (already
    // written above) which the legacy client sweep will fire.
    if (ratchet == null || _transportBlocked) return;
    List<String> targets = const <String>[];
    try {
      targets = await _listRecipientDevicesForSend(
        peerProfileId: peerProfileId,
        selfDeviceId: did,
      );
    } catch (_) {
      return; // keep placeholder; sweep/retry handles it
    }
    if (targets.isEmpty) return; // no devices yet → placeholder fallback

    final transportMetaJson = _buildChatTransportMetaJson(
      convoId: peerProfileId,
      isGroup: false,
      messageKind: 'text',
      payloadEventId: msgEventId,
      createdAtMs: scheduledAtMs,
      senderProfileId: myPid ?? '',
      senderDisplayName: myNickname,
      previewText: text,
    );

    var uploaded = 0;
    for (final toDeviceId in targets) {
      try {
        final msgId = _uuid.v4();
        final wire = await _encryptToPeerSerialized(
          ratchet: ratchet,
          selfDeviceId: did,
          peerProfileId: peerProfileId,
          peerDeviceId: toDeviceId,
          plaintext: Uint8List.fromList(peerPayload.encode()),
        );
        await db.outboxUpsert(
          msgId: msgId,
          toDeviceId: toDeviceId,
          ciphertextB64: base64Encode(wire),
          ttlSeconds: _outboxUserMessageTtlSeconds,
          state: OutboxSendState.pending,
          attemptCount: 0,
          // Upload NOW (phone awake) — the relay, not this device, waits for T.
          nextRetryAtMs: now,
          createdAtMs: now,
          correlationId: localEventId,
          payloadEventId: msgEventId,
          convoId: peerProfileId,
          transportMetaJson: transportMetaJson,
          expiresAtMs: scheduledAtMs + _outboxUserMessageTtlMs,
          eventIdRef: localEventId,
          // The relay holds the ciphertext until this instant.
          deliverAtMs: scheduledAtMs,
        );
        uploaded++;
      } catch (e) {
        DiagLog.event('send', 'scheduled_upload_failed', {
          'peer': DiagLog.pfx(peerProfileId),
          'to_dev': DiagLog.pfx(toDeviceId),
          'err': e.runtimeType.toString(),
        });
      }
    }
    if (uploaded > 0) {
      // The message is now durably on its way to the relay; the local sweep
      // must NOT also fire it. Mark the placeholder as server-scheduled by
      // flipping it out of the sweep's due set: it keeps its scheduled badge
      // but is no longer a client-fire candidate (the outbox owns delivery).
      try {
        await _retryDbBusy(() => db.markScheduledDirectUploaded(localEventId));
      } catch (_) {
        // Best-effort; a double-fire is still deduped by the relay msg_id and
        // the recipient's inbox_seen, so this cannot duplicate a message.
      }
      _kickRelayOutbox();
      DiagLog.event('send', 'scheduled_server_side', {
        'peer': DiagLog.pfx(peerProfileId),
        'devices': uploaded,
        'deliver_at': scheduledAtMs,
      });
    }
  }

  /// Fires any 1:1 messages whose scheduled time has arrived. Driven by the
  /// adaptive pump timer, so it also restores scheduling after an app restart.
  /// Demo chats are skipped — they run their own deferred timer.
  Future<void> _sweepDueScheduledDirectMessages() async {
    if (_scheduledDirectSweepInFlight) return;
    final db = _db;
    if (db == null) return;
    _scheduledDirectSweepInFlight = true;
    try {
      final nowMs = DateTime.now().millisecondsSinceEpoch;
      final due = await db.listDueScheduledDirectEvents(nowMs: nowMs, limit: 25);
      if (due.isEmpty) return;
      for (final row in due) {
        final eventId = ((row['event_id'] as String?) ?? '').trim();
        if (eventId.isEmpty) continue;
        final convoId = ((row['convo_id'] as String?) ?? '').trim();
        if (convoId.isEmpty || _isDemoConvoId(convoId)) continue;
        if (_firingScheduledDirectEventIds.contains(eventId)) continue;
        final retryAfter = _scheduledDirectRetryAfterMs[eventId];
        if (retryAfter != null && nowMs < retryAfter) continue;
        _firingScheduledDirectEventIds.add(eventId);
        unawaited(_fireScheduledDirectMessage(eventId: eventId));
      }
    } catch (_) {
      // best-effort; next tick retries.
    } finally {
      _scheduledDirectSweepInFlight = false;
    }
  }

  Future<void> _fireScheduledDirectMessage({required String eventId}) async {
    final db = _db;
    if (db == null) {
      _firingScheduledDirectEventIds.remove(eventId);
      return;
    }
    try {
      final row = await db.eventGet(eventId);
      if (row == null) {
        _scheduledDirectRetryAfterMs.remove(eventId);
        return;
      }
      // Cancelled / already promoted out of `scheduled` — drop it.
      final state = ((row['local_state'] as String?) ?? '').trim();
      if (state != MessageLocalState.scheduled) {
        _scheduledDirectRetryAfterMs.remove(eventId);
        return;
      }
      final convoId = ((row['convo_id'] as String?) ?? '').trim();
      if (convoId.isEmpty) return;

      final plain = await _decryptStoredLocalPayloadBytes(eventId);
      if (plain == null) {
        // Can't reconstruct payload — back off and retry later.
        _scheduledDirectRetryAfterMs[eventId] =
            DateTime.now().millisecondsSinceEpoch + 30000;
        return;
      }
      final payload = E2ePayloadV1.decode(plain);
      final msgEvents = payload.events.whereType<MsgEventV1>();
      if (msgEvents.isEmpty) {
        // Malformed placeholder — remove so it doesn't loop forever.
        await db.deleteEventsByIds([eventId]);
        _scheduledDirectRetryAfterMs.remove(eventId);
        _changed.add(null);
        return;
      }
      final msgEvent = msgEvents.first;

      // SERVER-SIDE OWNERSHIP GUARD (2026-07-18): `_scheduleDirectMessage`
      // uploads the ciphertext to the relay EAGERLY (the relay holds it until
      // T) and flips this placeholder out of the sweep. That flip is
      // best-effort — if it lost to SQLITE_BUSY (which sending other messages
      // readily induces) the placeholder is still `scheduled` and we land here
      // at T. Dispatching then emits a SECOND copy under a FRESH msg_id while
      // the relay releases its held copy at the same instant; two different
      // msg_ids cannot dedup, so the recipient sees the message twice.
      //
      // An outbox row tied to this placeholder means the relay path owns
      // delivery: repair the missed flip and do NOT dispatch. (Deleting the
      // local row below would NOT cancel the ciphertext the relay already
      // holds — that is exactly why the old "delete then re-send" was wrong.)
      if (await db.outboxCountForEventRef(eventId) > 0) {
        try {
          await _retryDbBusy(() => db.markScheduledDirectUploaded(eventId));
        } catch (_) {}
        _scheduledDirectRetryAfterMs.remove(eventId);
        _changed.add(null);
        return;
      }

      // Defensively clear any legacy (pre-fix) outbox row tied to this
      // placeholder so the old eager row can't double-send alongside the fresh
      // dispatch. Only reached when no relay-owned row exists (so it is a
      // genuine no-op today, kept as belt-and-braces for legacy rows).
      await db.outboxDeleteForEventRef(eventId);

      // Dispatch FIRST (the real send inserts its own fresh `local:<id>` bubble
      // + outbox) so a failure here leaves the scheduled placeholder intact —
      // no message is ever lost. Then drop the placeholder so only one bubble
      // shows.
      await sendMessage(
        peerProfileId: convoId,
        text: msgEvent.text,
        replyToPayloadEventId: msgEvent.replyToEventId,
        linkPreview: msgEvent.linkPreview,
      );
      await db.deleteEventsByIds([eventId]);
      _scheduledDirectRetryAfterMs.remove(eventId);
      _changed.add(null);
    } catch (e) {
      // Dispatch failed (e.g. relay momentarily unavailable). The placeholder
      // is still present, so back off and let the next sweep retry.
      _scheduledDirectRetryAfterMs[eventId] =
          DateTime.now().millisecondsSinceEpoch + 30000;
      callLog('AppCtrl', 'scheduled direct fire failed event=$eventId: $e');
    } finally {
      _firingScheduledDirectEventIds.remove(eventId);
    }
  }

  /// Sends a `scheduled` ("send later") placeholder RIGHT NOW instead of at its
  /// planned time (the "Отправить сейчас" menu action). Routes to the group or
  /// 1:1 fire path by convo kind. Guards against a concurrent sweep firing the
  /// same placeholder (the fire methods clear the guard in their `finally`).
  Future<void> sendScheduledMessageNow({
    required String convoId,
    required String eventId,
  }) async {
    final id = eventId.trim();
    if (id.isEmpty) return;
    final isGroup = convoId.startsWith('group:');
    final firing = isGroup
        ? _firingScheduledGroupEventIds
        : _firingScheduledDirectEventIds;
    if (firing.contains(id)) return; // already being fired by the sweep
    firing.add(id);
    if (isGroup) {
      await _fireScheduledGroupMessage(eventId: id);
    } else {
      await _fireScheduledDirectMessage(eventId: id);
    }
  }

  Future<String> sendGroupSticker({
    required String groupId,
    required SecretlyStickerDescriptor sticker,
    String? replyToPayloadEventId,
    String? topicId,
  }) async {
    final db = _db;
    final did = _deviceId;
    final pid = _profileId;
    final crypto = _crypto;
    if (db == null || did == null || pid == null || crypto == null) {
      throw StateError('Sticker send unavailable: local state is not ready');
    }
    await _ensureRoomActionAllowed(groupId, RoomAction.sendMedia);
    final normalizedTopicId = (topicId ?? '').trim().isEmpty ? null : topicId;

    final group = await db.convoGet(groupId);
    final groupTitle = ((group?['title'] as String?) ?? 'Group').trim();
    await db.convoEnsureGroup(
      groupId: groupId,
      title: groupTitle.isEmpty ? 'Group' : groupTitle,
    );

    final msgEventId = _uuid.v4();
    RelayRoomMessageAdmissionResult? admission;
    if (_useAuthoritativeRoomRelay) {
      admission = await _admitAuthoritativeRoomMessage(
        groupId: groupId,
        messageId: msgEventId,
        kind: 'media',
      );
    } else {
      _throwIfRoomMutationAuthoritativeRelayUnavailable();
    }
    final createdAt =
        admission?.admittedAtMs ?? DateTime.now().millisecondsSinceEpoch;
    final payload = E2ePayloadV1(
      senderDeviceId: did,
      createdAtMs: createdAt,
      events: [
        StickerEventV1(
          eventId: msgEventId,
          packId: sticker.packId,
          packVersion: sticker.packVersion,
          stickerId: sticker.stickerId,
          emojiHint: sticker.emojiHint,
          label: sticker.label,
          animated: sticker.animated,
          format: sticker.format.wireValue,
          replyToEventId: replyToPayloadEventId,
          topicId: normalizedTopicId,
        ),
      ],
    );
    final localCipher = await crypto.encrypt(payload.encode());
    final localEventId = 'local:grpsticker:$msgEventId';
    final transportMetaJson = _buildChatTransportMetaJson(
      convoId: groupId,
      isGroup: true,
      messageKind: 'sticker',
      payloadEventId: msgEventId,
      createdAtMs: createdAt,
      senderProfileId: pid,
      senderDisplayName: myNickname,
      convoTitle: groupTitle,
      previewText: _pushTransportPreviewForSticker(sticker),
    );
    await db.insertEvent(
      eventId: localEventId,
      convoId: groupId,
      type: 'sticker',
      senderDeviceId: did,
      ciphertextB64: base64Encode(localCipher),
      createdAtMs: createdAt,
      localState: 'pending',
      payloadEventId: msgEventId,
    );
    await db.convoTouch(convoId: groupId, atMs: createdAt);

    // ── User-created sticker: ship its PIXELS to room members ───────────────
    // Catalog/bundled stickers need nothing — the recipient resolves them from
    // its own pack by packId/stickerId. A USER sticker's pixels live only on the
    // sender, so — exactly like the 1:1 sendSticker path — upload them as an
    // E2EE blob and carry the handle in the fanout envelope (or a small inline
    // PNG when the blob upload is blocked on this network). WITHOUT this the
    // room envelope carried metadata only and recipients rendered nothing —
    // that was "стикеры не показываются собеседникам в комнатах".
    final sendPackMeta = sticker.packId.startsWith('user:')
        ? SecretlyStickerCatalog.pickerPackById(sticker.packId)
        : null;
    String? wireBlobId = sticker.blobId;
    String? wireFileKeyB64 = sticker.fileKeyB64;
    String? wireAccessTokenB64 = sticker.blobAccessTokenB64;
    String? wireInlinePngB64;
    // 🔴 СНАЧАЛА КЭШ (08.08.2026, С-11 ТЗ по стикерам). До этого ссылка на
    // шифртекст создавалась заново на КАЖДУЮ отправку: человек платил полное
    // шифрование и выгрузку за стикер, который отправлял уже десятый раз. Кэш
    // отдаёт готовую ссылку, а просроченную считает отсутствующей — то есть
    // мёртвых ссылок собеседнику не достаётся.
    if (sticker.packId.startsWith('user:') &&
        (wireBlobId == null || wireBlobId.isEmpty)) {
      final db = _db;
      if (db != null) {
        try {
          final cached = await db.stickerCachedBlob(
            packId: sticker.packId,
            packVersion: sticker.packVersion,
            stickerId: sticker.stickerId,
          );
          if (cached != null) {
            wireBlobId = cached.blobId;
            wireFileKeyB64 = cached.fileKeyB64;
            if (cached.accessTokenB64.isNotEmpty) {
              wireAccessTokenB64 = cached.accessTokenB64;
            }
            DiagLog.event('stickers', 'blob_cache_hit', {
              'pack': DiagLog.pfx(sticker.packId),
            });
          }
        } catch (e) {
          // Кэш не имеет права мешать отправке: не прочитался — выгрузим заново.
          DiagLog.event('stickers', 'blob_cache_read_failed', {
            'err': _shortErrorTag(e),
          });
        }
      }
    }

    final needsBlobUpload =
        sticker.packId.startsWith('user:') &&
        (wireBlobId == null || wireBlobId.isEmpty) &&
        sticker.assetPath.isNotEmpty;
    if (needsBlobUpload) {
      final attachments = _attachments;
      EncryptedAttachment? enc;
      if (attachments != null) {
        Uint8List stickerBytes;
        try {
          stickerBytes = await File(sticker.assetPath).readAsBytes();
        } catch (_) {
          stickerBytes = Uint8List(0);
        }
        for (
          var attempt = 1;
          attempt <= 3 && enc == null && stickerBytes.isNotEmpty;
          attempt++
        ) {
          try {
            enc = await attachments
                .encryptAndUpload(
                  stickerBytes,
                  ttlSeconds: _userStickerBlobTtlSeconds,
                  mime: _stickerMimeFor(sticker.format),
                )
                .timeout(const Duration(seconds: 60));
          } catch (e) {
            DiagLog.event('stickers', 'group_blob_upload_fail', {
              'attempt': attempt.toString(),
              'err': e.toString(),
            });
            if (attempt < 3) {
              await Future<void>.delayed(const Duration(seconds: 3));
            }
          }
        }
      }
      if (enc != null) {
        wireBlobId = enc.blobId;
        wireFileKeyB64 = enc.fileKeyB64;
        wireAccessTokenB64 = enc.blobAccessTokenB64;
        // 🔴 Запоминаем ВМЕСТЕ СО СРОКОМ. Кэш без срока однажды начал бы отдавать
        // мёртвую ссылку, и собеседник увидел бы стикер, который не скачивается,
        // — то есть кэш без инвалидации хуже отсутствия кэша.
        final db = _db;
        if (db != null) {
          try {
            await db.stickerRememberBlob(
              packId: sticker.packId,
              packVersion: sticker.packVersion,
              stickerId: sticker.stickerId,
              blobId: enc.blobId,
              fileKeyB64: enc.fileKeyB64,
              accessTokenB64: enc.blobAccessTokenB64,
              expiresAtMs: enc.expiresAtMs,
            );
          } catch (e) {
            // Не записался кэш — просто заплатим за выгрузку в следующий раз.
            DiagLog.event('stickers', 'blob_cache_write_failed', {
              'err': _shortErrorTag(e),
            });
          }
        }
      } else {
        // Blob upload blocked → ship a small inline PNG over the WS path.
        wireInlinePngB64 = await _buildInlineStickerB64(sticker);
      }
    }

    var members = await listGroupMembers(groupId);
    var recipients = members
        .where((m) => m.isNotEmpty && m != pid)
        .toList(growable: false);
    if (recipients.isEmpty && members.isEmpty) {
      await _tryRefreshRoomFromRelayBestEffort(groupId);
      members = await listGroupMembers(groupId);
      recipients = members
          .where((m) => m.isNotEmpty && m != pid)
          .toList(growable: false);
    }
    if (recipients.isEmpty) {
      callLog(
        'AppCtrl',
        'sendGroupSticker solo-room: no recipients to fan out (group=$groupId members=${members.length})',
      );
    }

    final envelope = <String, Object?>{
      'v': 1,
      'kind': 'sticker',
      'groupId': groupId,
      'groupTitle': groupTitle,
      'msgEventId': msgEventId,
      'packId': sticker.packId,
      'packVersion': sticker.packVersion,
      'stickerId': sticker.stickerId,
      'emojiHint': sticker.emojiHint,
      'label': sticker.label,
      'animated': sticker.animated,
      'format': sticker.format.wireValue,
      // User-sticker pixels (null/absent for catalog stickers). The receiver's
      // generic blobId/fileKeyB64/blobAccessTokenB64/sizeBytes parse already
      // reads these keys; width/height/inline/pack use sticker-specific keys.
      if (wireBlobId != null && wireBlobId.isNotEmpty) 'blobId': wireBlobId,
      if (wireFileKeyB64 != null && wireFileKeyB64.isNotEmpty)
        'fileKeyB64': wireFileKeyB64,
      if (wireAccessTokenB64 != null && wireAccessTokenB64.isNotEmpty)
        'blobAccessTokenB64': wireAccessTokenB64,
      if (sticker.sizeBytes != null) 'sizeBytes': sticker.sizeBytes,
      if (sticker.width != null) 'stickerWidth': sticker.width,
      if (sticker.height != null) 'stickerHeight': sticker.height,
      if (wireInlinePngB64 != null && wireInlinePngB64.isNotEmpty)
        'inlinePngB64': wireInlinePngB64,
      if (sendPackMeta?.title != null) 'packTitle': sendPackMeta!.title,
      if (sendPackMeta != null) 'packStickerCount': sendPackMeta.stickers.length,
      if (sticker.packId.startsWith('user:')) 'packOriginPid': pid,
      'replyToPayloadEventId': replyToPayloadEventId,
      if (normalizedTopicId != null) 'topicId': normalizedTopicId,
      'createdAtMs': createdAt,
      'memberProfileIds': members,
      'senderProfileId': pid,
      'senderName': myNickname.trim().isEmpty ? null : myNickname.trim(),
      'senderAvatarPath': _myAvatarPath,
    };
    final controlText =
        '$_groupMsgCmdPrefix${base64Url.encode(utf8.encode(jsonEncode(envelope)))}';

    // ROOM SENDER KEY (фаза 3б): seal once, same object to everyone; null falls
    // back to the ordinary pairwise fanout.
    final roomWireEvents = await _sealRoomMessageForSenderKey(
      db: db,
      roomId: groupId,
      controlText: controlText,
      createdAtMs: createdAt,
      memberProfileIds: recipients,
    );

    var delivered = 0;
    // К-3: конверт — для повтора тому, у кого пропуск.
    await _rememberRoomEnvelope(db: db, roomId: groupId, controlText: controlText);
    // К-2: один запрос к реле для тех, кто умеет сырой провод.
    final rawRemaining = await _roomRawBroadcast(
      db: db,
      roomId: groupId,
      events: roomWireEvents,
      recipients: recipients,
      transportMetaJson: transportMetaJson,
      localEventId: localEventId,
    );
    for (final member in recipients) {
      final rawTargets = rawRemaining?[member];
      if (rawTargets != null && rawTargets.isEmpty) {
        delivered++;
        continue;
      }
      try {
        await sendControlMessage(
          peerProfileId: member,
          controlText: controlText,
          overrideEvents: roomWireEvents,
          targetDeviceIds: rawTargets,
          transportMetaJson: transportMetaJson,
          eventIdRef: localEventId,
          strict: true,
          queueIfNoDevices: true,
        );
        delivered++;
      } catch (e) {
        callLog(
          'AppCtrl',
          'sendGroupSticker fanout member=$member group=$groupId failed: $e',
        );
      }
    }
    if (recipients.isNotEmpty && delivered == 0) {
      throw RoomPolicyFailure(RoomPolicyFailureCode.allRecipientsUnavailable);
    }

    // Sprint 2 / PR3.5: mirror this sticker envelope to my own other
    // devices. The receive-side handler already understands `kind:
    // 'sticker'` group envelopes (app_controller ≈line 27200) and now
    // marks them `localState: 'sent'` when the sender device is mine.
    unawaited(
      _mirrorGroupControlEnvelopeToOwnDevices(controlText: controlText),
    );

    await _touchRecentSticker(sticker);
    return msgEventId;
  }

  Future<String> sendGroupAttachmentFile({
    required String groupId,
    required String filePath,
    String? mime,
    String? replyToPayloadEventId,
    String? mediaGroupId,
    void Function(String stage)? onStage,
    void Function(int sentBytes, int totalBytes)? onUploadProgress,
    BlobUploadCancelToken? cancelToken,
    List<int>? waveform,
    String? topicId,
    String? caption,
    String? filename,
    bool videoNote = false,
    int? durationMs,
    String? musicTitle,
    String? musicArtist,
  }) async {
    final normalizedTopicId = (topicId ?? '').trim().isEmpty ? null : topicId;
    final resolvedCaption = caption?.trim();
    final captionForPayload =
        (resolvedCaption == null || resolvedCaption.isEmpty)
        ? null
        : resolvedCaption;
    final String? resolvedFilename =
        (filename != null && filename.trim().isNotEmpty)
        ? filename.trim()
        : null;
    final db = _db;
    final did = _deviceId;
    final pid = _profileId;
    final crypto = _crypto;
    final attachments = _attachments;
    if (db == null ||
        did == null ||
        pid == null ||
        crypto == null ||
        attachments == null) {
      throw AttachmentFailure(AttachmentFailureCode.localUnavailable);
    }
    await _ensureRoomActionAllowed(groupId, RoomAction.sendMedia);

    final file = File(filePath);
    if (!await file.exists()) {
      throw AttachmentFailure(AttachmentFailureCode.fileMissing);
    }

    final size = await file.length();
    // §C-3: entitlement-aware ceiling (was a hardcoded 25 MB constant, so a paid
    // tier could not send large attachments to GROUPS even though direct chats
    // could). Mirrors the direct-chat send path.
    _throwIfAttachmentTooLarge(size);

    try {
      _throwIfTransportBlocked();
    } catch (error) {
      throw describeAttachmentFailure(
        error,
        fallbackCode: AttachmentFailureCode.transportBlocked,
      );
    }

    final group = await db.convoGet(groupId);
    final groupTitle = ((group?['title'] as String?) ?? 'Group').trim();
    await db.convoEnsureGroup(
      groupId: groupId,
      title: groupTitle.isEmpty ? 'Group' : groupTitle,
    );

    final now = DateTime.now().millisecondsSinceEpoch;
    final resolvedMime = (mime != null && mime.trim().isNotEmpty)
        ? mime.trim()
        : 'application/octet-stream';

    // Что уходит на самом деле: у снимка без метаданных байтов меньше, чем в
    // файле, а размеры и миниатюра описывают именно отправленные байты.
    var effectiveSize = size;
    ({int width, int height})? bufferedImageDims;
    String? inlineThumbB64;

    EncryptedAttachment uploaded;
    if (_shouldUseBufferedAttachmentUpload(
      sizeBytes: size,
      mime: resolvedMime,
    )) {
      if (cancelToken?.isCanceled == true) {
        throw AttachmentFailure(AttachmentFailureCode.uploadCanceled);
      }
      onStage?.call('uploading');
      final bytes = await file.readAsBytes().timeout(
        _attachmentReadTimeout,
        onTimeout: () =>
            throw AttachmentFailure(AttachmentFailureCode.uploadTimedOut),
      );
      if (cancelToken?.isCanceled == true) {
        throw AttachmentFailure(AttachmentFailureCode.uploadCanceled);
      }
      // 🔴 ТА ЖЕ ПОДГОТОВКА, ЧТО В ЛИЧНОМ ЧАТЕ (17.09.2026).
      //
      // Одиночный снимок в комнату уходил как есть — с геометкой и прочими
      // метаданными камеры, которые видит каждый участник. Тот же снимок в
      // личный чат и любой альбом очищались. Здесь ровно то, что делает
      // [sendAttachmentFile]: очистка (ориентация остаётся), размеры и
      // миниатюра по уходящим байтам. Это забота о приватности и виде, а не
      // условие отправки: любой сбой возвращает исходные байты, и снимок всё
      // равно уходит.
      var effectiveBytes = bytes;
      try {
        effectiveBytes = _maybeStripJpegMetadata(bytes, resolvedMime);
        bufferedImageDims = await _imagePixelDimsFromBytes(
          effectiveBytes,
          resolvedMime,
        );
        inlineThumbB64 = await _buildAttachmentInlineThumbB64(
          effectiveBytes,
          resolvedMime,
        );
      } catch (e) {
        effectiveBytes = bytes;
        bufferedImageDims = null;
        inlineThumbB64 = null;
        DiagLog.event('media', 'photo_enrich_failed', {
          'reason': _classifyShortReason(e),
        });
      }
      effectiveSize = effectiveBytes.length;
      try {
        uploaded = await attachments
            .encryptAndUpload(
              effectiveBytes,
              ttlSeconds: 7 * 24 * 60 * 60,
              mime: resolvedMime,
            )
            .timeout(
              _attachmentUploadTimeout,
              onTimeout: () =>
                  throw AttachmentFailure(AttachmentFailureCode.uploadTimedOut),
            );
      } catch (error) {
        throw describeAttachmentFailure(
          error,
          fallbackCode: AttachmentFailureCode.serviceUnavailable,
        );
      }
      await _cacheAttachmentBytes(
        blobId: uploaded.blobId,
        mime: uploaded.mime,
        plaintext: effectiveBytes,
      );
    } else {
      onStage?.call('encrypting');
      final tmp = await getTemporaryDirectory();
      try {
        uploaded = await attachments
            .encryptFileAndUpload(
              file,
              tempDir: tmp,
              ttlSeconds: 7 * 24 * 60 * 60,
              mime: resolvedMime,
              onUploadProgress: onUploadProgress,
              onStage: onStage,
              cancelToken: cancelToken,
            )
            .timeout(
              _attachmentUploadTimeout,
              onTimeout: () =>
                  throw AttachmentFailure(AttachmentFailureCode.uploadTimedOut),
            );
      } catch (error) {
        throw describeAttachmentFailure(
          error,
          fallbackCode: AttachmentFailureCode.serviceUnavailable,
        );
      }
      await _cacheAttachmentFileFromPath(
        blobId: uploaded.blobId,
        mime: uploaded.mime,
        sourcePath: filePath,
      );
    }

    // Cancel landed AFTER the upload finished (fast upload / cancel during the
    // server-response wait) but BEFORE we wrote the event — abort now so the
    // bubble the user just cancelled does NOT get inserted and "reappear".
    if (cancelToken?.isCanceled == true) {
      throw AttachmentFailure(AttachmentFailureCode.uploadCanceled);
    }

    await db.attachmentUpsert(
      blobId: uploaded.blobId,
      fileKeyB64: uploaded.fileKeyB64,
      accessTokenB64: uploaded.blobAccessTokenB64,
      mime: uploaded.mime,
      plaintextSizeBytes: effectiveSize,
      ciphertextSizeBytes: uploaded.ciphertextSizeBytes,
      expiresAtMs: uploaded.expiresAtMs,
      createdAtMs: now,
    );

    final msgEventId = _uuid.v4();
    RelayRoomMessageAdmissionResult? admission;
    if (_useAuthoritativeRoomRelay) {
      admission = await _admitAuthoritativeRoomMessage(
        groupId: groupId,
        messageId: msgEventId,
        kind: 'media',
      );
    } else {
      _throwIfRoomMutationAuthoritativeRelayUnavailable();
    }
    final createdAt = admission?.admittedAtMs ?? now;
    final payload = E2ePayloadV1(
      senderDeviceId: did,
      createdAtMs: createdAt,
      events: [
        AttachmentEventV1(
          eventId: msgEventId,
          blobId: uploaded.blobId,
          fileKeyB64: uploaded.fileKeyB64,
          blobAccessTokenB64: uploaded.blobAccessTokenB64,
          sizeBytes: effectiveSize,
          mime: uploaded.mime,
          replyToEventId: replyToPayloadEventId,
          mediaGroupId: mediaGroupId,
          waveform: waveform,
          topicId: normalizedTopicId,
          caption: captionForPayload,
          filename: resolvedFilename,
          videoNote: videoNote,
          durationMs: durationMs,
          musicTitle: musicTitle,
          musicArtist: musicArtist,
          width: bufferedImageDims?.width,
          height: bufferedImageDims?.height,
          thumbB64: inlineThumbB64,
        ),
      ],
    );
    final localCipher = await crypto.encrypt(payload.encode());
    final localEventId = 'local:grpatt:$msgEventId';
    final transportMetaJson = _buildChatTransportMetaJson(
      convoId: groupId,
      isGroup: true,
      messageKind: 'attachment',
      payloadEventId: msgEventId,
      createdAtMs: createdAt,
      senderProfileId: pid,
      senderDisplayName: myNickname,
      convoTitle: groupTitle,
      previewText: _pushTransportPreviewForAttachment(uploaded.mime),
    );
    await db.insertEvent(
      eventId: localEventId,
      convoId: groupId,
      type: 'att',
      senderDeviceId: did,
      ciphertextB64: base64Encode(localCipher),
      createdAtMs: createdAt,
      localState: 'pending',
      payloadEventId: msgEventId,
    );
    await db.convoTouch(convoId: groupId, atMs: createdAt);

    var members = await listGroupMembers(groupId);
    var recipients = members
        .where((m) => m.isNotEmpty && m != pid)
        .toList(growable: false);
    if (recipients.isEmpty && members.isEmpty) {
      await _tryRefreshRoomFromRelayBestEffort(groupId);
      members = await listGroupMembers(groupId);
      recipients = members
          .where((m) => m.isNotEmpty && m != pid)
          .toList(growable: false);
    }
    if (recipients.isEmpty) {
      callLog(
        'AppCtrl',
        'sendGroupAttachment solo-room: no recipients to fan out (group=$groupId members=${members.length})',
      );
    }

    final envelope = <String, Object?>{
      'v': 1,
      'kind': 'attachment',
      'groupId': groupId,
      'groupTitle': groupTitle,
      'msgEventId': msgEventId,
      'blobId': uploaded.blobId,
      'fileKeyB64': uploaded.fileKeyB64,
      'blobAccessTokenB64': uploaded.blobAccessTokenB64,
      'sizeBytes': effectiveSize,
      'mime': uploaded.mime,
      'replyToPayloadEventId': replyToPayloadEventId,
      'mediaGroupId': mediaGroupId,
      if (waveform != null && waveform.isNotEmpty) 'waveform': waveform,
      if (normalizedTopicId != null) 'topicId': normalizedTopicId,
      if (captionForPayload != null) 'caption': captionForPayload,
      'filename': resolvedFilename,
      if (videoNote) 'videoNote': true,
      if (durationMs != null) 'durationMs': durationMs,
      // 🔴 Название и исполнитель песни (17.09.2026). В событии они были и
      // раньше, а в конверт участникам не попадали: в комнате песня у всех,
      // кроме отправителя, была подписана именем файла.
      if ((musicTitle ?? '').trim().isNotEmpty) 'musicTitle': musicTitle!.trim(),
      if ((musicArtist ?? '').trim().isNotEmpty)
        'musicArtist': musicArtist!.trim(),
      // Размеры и размытый кадр — ключи те же, что у альбома
      // ([sendGroupAttachmentFiles]); выпущенные телефоны их уже читают.
      if (bufferedImageDims != null) 'width': bufferedImageDims.width,
      if (bufferedImageDims != null) 'height': bufferedImageDims.height,
      if (inlineThumbB64 != null) 'thumb_b64': inlineThumbB64,
      'createdAtMs': createdAt,
      'memberProfileIds': members,
      'senderProfileId': pid,
      'senderName': myNickname.trim().isEmpty ? null : myNickname.trim(),
      'senderAvatarPath': _myAvatarPath,
    };
    final controlText =
        '$_groupMsgCmdPrefix${base64Url.encode(utf8.encode(jsonEncode(envelope)))}';

    // ROOM SENDER KEY (фаза 3б): seal once, same object to everyone; null falls
    // back to the ordinary pairwise fanout.
    final roomWireEvents = await _sealRoomMessageForSenderKey(
      db: db,
      roomId: groupId,
      controlText: controlText,
      createdAtMs: createdAt,
      memberProfileIds: recipients,
    );

    var delivered = 0;
    // К-3: конверт — для повтора тому, у кого пропуск.
    await _rememberRoomEnvelope(db: db, roomId: groupId, controlText: controlText);
    // К-2: один запрос к реле для тех, кто умеет сырой провод.
    final rawRemaining = await _roomRawBroadcast(
      db: db,
      roomId: groupId,
      events: roomWireEvents,
      recipients: recipients,
      transportMetaJson: transportMetaJson,
      localEventId: localEventId,
    );
    for (final member in recipients) {
      final rawTargets = rawRemaining?[member];
      if (rawTargets != null && rawTargets.isEmpty) {
        delivered++;
        continue;
      }
      try {
        await sendControlMessage(
          peerProfileId: member,
          controlText: controlText,
          overrideEvents: roomWireEvents,
          targetDeviceIds: rawTargets,
          transportMetaJson: transportMetaJson,
          eventIdRef: localEventId,
          strict: true,
          queueIfNoDevices: true,
        );
        delivered++;
      } catch (e) {
        callLog(
          'AppCtrl',
          'sendGroupAttachment fanout member=$member group=$groupId failed: $e',
        );
      }
    }
    if (recipients.isNotEmpty && delivered == 0) {
      throw RoomPolicyFailure(RoomPolicyFailureCode.allRecipientsUnavailable);
    }

    // Sprint 2 / PR3.5: mirror this attachment envelope to my own other
    // devices. Receive-side does `db.attachmentUpsert` + synthetic
    // AttachmentEventV1 insert in the `kind == 'attachment'` branch
    // (app_controller ≈line 27286) so the file shows up in chat history
    // on my second device; bytes are downloaded on-demand when opened.
    unawaited(
      _mirrorGroupControlEnvelopeToOwnDevices(controlText: controlText),
    );

    _changed.add(null);
    return msgEventId;
  }

  Future<Map<String, List<MessageReaction>>> loadMessageReactions({
    required List<String> eventIds,
  }) async {
    final db = _db;
    if (db == null || eventIds.isEmpty) return const {};
    final rows = await db.messageReactionsForEventIds(eventIds);
    final out = <String, List<MessageReaction>>{};
    final avatarPathByProfileId = <String, String?>{};
    final displayNameByProfileId = <String, String?>{};
    // Профиль запрашивается ОДИН раз, а не на каждую его реакцию.
    //
    // Мемо-мапы ниже стояли после `await`, поэтому запросы уходили для каждой
    // строки, даже когда это тот же самый человек: в группе, где двадцать
    // участников отметили десять сообщений, получалось двести строк и
    // четыреста последовательных запросов — и всё это заново на каждый bump
    // changeVersion. Кэш ниже держит по два запроса на УЧАСТНИКА.
    final contactByProfileId = <String, Map<String, Object?>?>{};
    final metaByProfileId = <String, Map<String, Object?>?>{};
    for (final r in rows) {
      final eventId = r['event_id'] as String?;
      if (eventId == null || eventId.isEmpty) continue;
      final profileId = ((r['profile_id'] as String?) ?? '').trim();
      Map<String, Object?>? contact;
      Map<String, Object?>? meta;
      if (profileId.isNotEmpty) {
        if (contactByProfileId.containsKey(profileId)) {
          contact = contactByProfileId[profileId];
          meta = metaByProfileId[profileId];
        } else {
          contact = await db.contactGet(profileId);
          meta = await db.profileMetaGet(profileId);
          contactByProfileId[profileId] = contact;
          metaByProfileId[profileId] = meta;
        }
      }
      final resolvedAvatarPath = profileId.isEmpty
          ? null
          : avatarPathByProfileId.putIfAbsent(
              profileId,
              () => profileId == this.profileId
                  ? _existingAvatarFilePath(_myAvatarPath)
                  : _visiblePeerAvatarPath(contactRow: contact, metaRow: meta),
            );
      final rowActorName = (r['actor_name'] as String?)?.trim();
      final resolvedActorName = rowActorName != null && rowActorName.isNotEmpty
          ? rowActorName
          : profileId.isEmpty
          ? null
          : displayNameByProfileId.putIfAbsent(
              profileId,
              () => profileId == this.profileId
                  ? (myNickname.trim().isEmpty ? null : myNickname.trim())
                  : _resolvedContactDisplayName(
                      contactRow: contact,
                      metaRow: meta,
                    ),
            );
      out
          .putIfAbsent(eventId, () => <MessageReaction>[])
          .add(
            MessageReaction(
              eventId: eventId,
              convoId: (r['convo_id'] as String?) ?? '',
              profileId: profileId,
              actorName: resolvedActorName,
              // У-4 (17.09.2026): путь из строки реакции — это путь на ЧУЖОМ
              // устройстве; для чужих реакций он ничего не значит.
              actorAvatarPath:
                  resolvedAvatarPath ??
                  (profileId == this.profileId
                      ? _existingAvatarFilePath(r['actor_avatar_path'] as String?)
                      : null),
              emoji: (r['emoji'] as String?) ?? '',
              createdAtMs: (r['created_at_ms'] as num?)?.toInt() ?? 0,
              updatedAtMs: (r['updated_at_ms'] as num?)?.toInt() ?? 0,
            ),
          );
    }
    // Warm the cross-screen cache. See [cachedReactionsFor].
    _reactionsCache.addAll(out);
    // Ids that were asked for but came back with nothing have NO reactions —
    // record that too, or a message whose last reaction was removed would keep
    // painting the stale chip from cache on the next open.
    for (final id in eventIds) {
      if (!out.containsKey(id)) _reactionsCache.remove(id);
    }
    return out;
  }

  /// Reactions already loaded at least once, by event id. Survives leaving and
  /// re-entering a chat, unlike anything held on the chat screen's State.
  ///
  /// 🔴 WHY (2026-08-01, field: "reactions that were added long ago get placed
  /// again, visually, every time I open the chat — the bubbles jump").
  ///
  /// The chat screen already seeded its reaction `FutureBuilder` with a warm
  /// map so bubbles paint WITH their chips in one frame. But that map lived on
  /// the screen's State, which is destroyed on exit and rebuilt empty on the
  /// next open — so "what we already know" was only ever true WITHIN one visit.
  /// Frame one of every entry therefore had no chips, the async query dropped
  /// them in a frame or two later, and every bubble carrying a reaction grew
  /// after layout. That late growth is the jump.
  ///
  /// Same shape as [cachedConversation]: the data is already known, only the
  /// synchronous door across a screen boundary was missing.
  final Map<String, List<MessageReaction>> _reactionsCache =
      <String, List<MessageReaction>>{};

  /// Synchronous, no await: reactions for [eventIds] that are already known.
  /// Unknown ids are simply absent, so the async load still fills them in.
  Map<String, List<MessageReaction>> cachedReactionsFor(
    List<String> eventIds,
  ) {
    if (eventIds.isEmpty || _reactionsCache.isEmpty) {
      return const <String, List<MessageReaction>>{};
    }
    final out = <String, List<MessageReaction>>{};
    for (final id in eventIds) {
      final hit = _reactionsCache[id];
      if (hit != null && hit.isNotEmpty) out[id] = hit;
    }
    return out;
  }

