  /// Admin audit log: the room's system events (joins, removals, bans, role
  /// changes, settings edits, …) decoded + formatted, newest-first.
  Future<List<({int createdAtMs, String text})>> loadRoomAuditLog(
    String groupId, {
    int limit = 200,
  }) async {
    final db = _db;
    if (db == null) return const <({int createdAtMs, String text})>[];
    final rows = await db.listRoomSystemEvents(convoId: groupId, limit: limit);
    final out = <({int createdAtMs, String text})>[];
    for (final row in rows) {
      final eventId = ((row['event_id'] as String?) ?? '').trim();
      if (eventId.isEmpty) continue;
      final chatEvent = ChatEvent(
        eventId: eventId,
        createdAtMs: (row['created_at_ms'] as num?)?.toInt() ?? 0,
        type: (row['type'] as String?) ?? 'sys',
        ciphertextB64: (row['ciphertext_b64'] as String?) ?? '',
        localCiphertextB64: row['local_ciphertext_b64'] as String?,
        senderDeviceId: (row['sender_device_id'] as String?) ?? '',
        localState: (row['local_state'] as String?) ?? 'received',
        payloadEventId: row['payload_event_id'] as String?,
        scheduledAtMs: (row['scheduled_at_ms'] as num?)?.toInt(),
      );
      final payload = await payloadEventForChatEvent(chatEvent);
      if (payload is! SystemEventV1) continue;
      final text = formatSystemEventText(
        payload,
        isRu: _isRussianSystemEventLocale,
        selfProfileId: profileId,
      );
      if (text.trim().isEmpty) continue;
      out.add((createdAtMs: chatEvent.createdAtMs, text: text));
    }
    return out;
  }

