  Future<String?> searchChatFirstMatch({
    required String convoId,
    required String query,
  }) async {
    final q = query.trim();
    if (q.isEmpty) return null;
    final events = await loadEvents(convoId);
    for (final e in events) {
      final text = await decryptPlainAsync(e);
      if (text.toLowerCase().contains(q.toLowerCase())) {
        return text;
      }
    }
    return null;
  }

  /// Telegram-style in-chat search: returns EVERY occurrence of [query] across
  /// the conversation's decrypted message text, one [ChatSearchHit] per match
  /// (so a single message containing the query twice yields two hits), ordered
  /// CHRONOLOGICALLY (oldest → newest) so up/down navigation maps to time.
  ///
  /// Case-insensitive substring match. Undecryptable / empty rows are skipped.
  /// Capped at [limit] hits. Fail-soft: any per-row decrypt error is swallowed.
  Future<List<ChatSearchHit>> searchChatMatches({
    required String convoId,
    required String query,
    int limit = 1000,
  }) async {
    final q = query.trim();
    if (q.isEmpty || limit <= 0) return const <ChatSearchHit>[];
    final qLower = q.toLowerCase();
    // loadEvents returns newest-first (DB `ORDER BY created_at_ms DESC`); reverse
    // to chronological so hit index 0 is the OLDEST match.
    final events = (await loadEvents(convoId)).reversed.toList(growable: false);
    final db = _db;
    // Per-device sender cache so we resolve each distinct device at most once.
    // Local-only (`deviceProfileCached`) — never a network call — to keep search
    // fast and fail-soft; unresolved devices simply carry a null profile id.
    final senderCache = <String, String?>{};
    Future<String?> resolveSender(String senderDeviceId) async {
      final did = senderDeviceId.trim();
      if (did.isEmpty) return null;
      if (senderCache.containsKey(did)) return senderCache[did];
      String? pid;
      try {
        pid = await db?.deviceProfileCached(did);
      } catch (_) {
        pid = null;
      }
      final resolved = (pid != null && pid.trim().isNotEmpty)
          ? pid.trim()
          : null;
      senderCache[did] = resolved;
      return resolved;
    }

    final hits = <ChatSearchHit>[];
    for (final e in events) {
      String text;
      try {
        text = await decryptPlainAsync(e);
      } catch (_) {
        continue; // skip undecryptable rows
      }
      if (text.isEmpty) continue;
      // Resolve the author once per matching row. Outgoing → me (profile id);
      // inbound → the peer/group member's profile id (best-effort, local cache).
      bool outgoing = false;
      String? senderPid;
      try {
        outgoing = isOwnDeviceId(e.senderDeviceId);
        if (outgoing) {
          senderPid = _profileId;
        } else {
          senderPid = await resolveSender(e.senderDeviceId);
        }
      } catch (_) {
        outgoing = false;
        senderPid = null;
      }
      final lower = text.toLowerCase();
      var from = 0;
      while (true) {
        final idx = lower.indexOf(qLower, from);
        if (idx < 0) break;
        hits.add(
          ChatSearchHit(
            eventId: e.eventId,
            payloadEventId: e.payloadEventId,
            text: text,
            matchStart: idx,
            matchEnd: idx + q.length,
            createdAtMs: e.createdAtMs,
            senderProfileId: senderPid,
            isOutgoing: outgoing,
          ),
        );
        if (hits.length >= limit) return hits;
        from = idx + q.length; // non-overlapping occurrences
      }
    }
    return hits;
  }

  Future<List<UserLookupResult>> lookupUsers(
    String query, {
    int limit = 20,
  }) async {
    final q = query.trim();
    if (q.isEmpty) return const [];
    final keys = _keys;
    final db = _db;

    Future<List<UserLookupResult>> localFallback() async {
      if (db == null) return const [];
      final rows = await db.contactsList(limit: 200);
      final ql = q.toLowerCase();
      final out = <UserLookupResult>[];
      for (final row in rows) {
        final pid = (row['contact_profile_id'] as String? ?? '').trim();
        if (pid.isEmpty) continue;
        final nick = (row['display_name'] as String?)?.trim();
        final inPid = pid.toLowerCase().contains(ql);
        final inNick = (nick ?? '').toLowerCase().contains(ql);
        if (!inPid && !inNick) continue;
        out.add(
          UserLookupResult(
            profileId: pid,
            nickname: (nick != null && nick.isNotEmpty) ? nick : null,
            alreadyInContacts: true,
          ),
        );
      }
      return out;
    }

    if (_transportBlocked || keys == null) {
      return localFallback();
    }

    Future<bool> inContacts(String profileId) async {
      if (db == null) return false;
      final contact = await db.contactGet(profileId);
      return contact != null;
    }

    if (_isLikelyProfileId(q)) {
      try {
        final exists = await keys.profileExists(q);
        if (!exists) {
          return const [];
        }
        String? nickname;
        try {
          final meta = await keys.getProfileMeta(q);
          final nick = meta.nickname?.trim();
          if (nick != null && nick.isNotEmpty) {
            nickname = nick;
          }
        } catch (_) {
          // best effort
        }
        return [
          UserLookupResult(
            profileId: q,
            nickname: nickname,
            alreadyInContacts: await inContacts(q),
          ),
        ];
      } catch (_) {
        // Offline fallback: still let user add an explicit profile ID manually.
        return [
          UserLookupResult(
            profileId: q,
            nickname: null,
            alreadyInContacts: await inContacts(q),
          ),
        ];
      }
    }

    if (q.runes.length < 2) {
      return const [];
    }
    if (!_allowNicknameLookup) {
      return const [];
    }

    final myPid = _profileId;
    final myDid = _deviceId;
    if (myPid == null || myPid.isEmpty || myDid == null || myDid.isEmpty) {
      try {
        final hits = await keys.searchProfiles(query: q, limit: limit);
        final out = <UserLookupResult>[];
        final seen = <String>{};
        for (final hit in hits) {
          final pid = hit.profileId.trim();
          if (pid.isEmpty || seen.contains(pid)) continue;
          seen.add(pid);
          out.add(
            UserLookupResult(
              profileId: pid,
              nickname: hit.nickname?.trim().isNotEmpty == true
                  ? hit.nickname!.trim()
                  : null,
              alreadyInContacts: await inContacts(pid),
            ),
          );
        }
        return out;
      } catch (_) {
        return localFallback();
      }
    }
    int? tsMs;
    String? nonceB64;
    String? sigB64;
    try {
      final deviceKeys = DeviceKeys.create();
      final kp = await deviceKeys.loadIdentityKeyPair(
        profileId: myPid,
        deviceId: myDid,
      );
      // Исправленное время: подпись к серверу ключей проверяется с допуском в
      // пять минут — см. публикацию ключей выше.
      tsMs = ServerClock.instance.nowMs();
      nonceB64 = AuthSigner.randomNonceB64(bytes: 16);
      final msg = AuthSigner.keysProfileSearchMessage(
        requesterDeviceId: myDid,
        query: q,
        tsMs: tsMs,
        nonceB64: nonceB64,
      );
      sigB64 = await AuthSigner.signEd25519B64(
        identityKeyPair: kp,
        message: msg,
      );
    } catch (_) {
      // Search can fall back to unsigned queries or local matches.
    }

    List<ProfileSearchItem> hits;
    if (tsMs != null && nonceB64 != null && sigB64 != null) {
      try {
        hits = await keys.searchProfiles(
          query: q,
          limit: limit,
          requesterDeviceId: myDid,
          tsMs: tsMs,
          nonceB64: nonceB64,
          signatureB64: sigB64,
        );
      } catch (_) {
        try {
          hits = await keys.searchProfiles(query: q, limit: limit);
        } catch (_) {
          return localFallback();
        }
      }
    } else {
      try {
        hits = await keys.searchProfiles(query: q, limit: limit);
      } catch (_) {
        return localFallback();
      }
    }
    final out = <UserLookupResult>[];
    final seen = <String>{};
    for (final hit in hits) {
      final pid = hit.profileId.trim();
      if (pid.isEmpty || seen.contains(pid)) continue;
      seen.add(pid);
      out.add(
        UserLookupResult(
          profileId: pid,
          nickname: hit.nickname?.trim().isNotEmpty == true
              ? hit.nickname!.trim()
              : null,
          alreadyInContacts: await inContacts(pid),
        ),
      );
    }
    return out;
  }

  bool _isLikelyProfileId(String value) {
    if (value.length < 8 || value.length > 128) return false;
    final hasDash = value.contains('-');
    final allowed = RegExp(r'^[A-Za-z0-9_-]+$').hasMatch(value);
    return hasDash && allowed;
  }

