  Future<String> ensureFavoritesChat({required String title}) async {
    final db = _db;
    final pid = _profileId;
    if (db == null || pid == null || pid.isEmpty) {
      throw StateError('Profile is not ready');
    }
    final cleanedTitle = title.trim().isEmpty
        ? _appL10n.favoritesTitle
        : title.trim();
    await db.convoEnsure1to1(peerProfileId: pid);
    await db.contactUpsert(
      profileId: pid,
      displayName: cleanedTitle,
      displayNameIsCustom: true,
    );
    await db.convoSetPinned(convoId: pid, pinned: true);
    final changed = _personalConvoIds.add(pid);
    if (changed) {
      final prefs = _prefs ?? await SharedPreferences.getInstance();
      _prefs = prefs;
      await prefs.setStringList(
        _prefsPersonalConvoIdsKey,
        _personalConvoIds.toList(growable: false),
      );
    }
    _changed.add(null);
    return pid;
  }

  Future<void> setChatPersonal({
    required String convoId,
    required bool personal,
  }) async {
    final id = convoId.trim();
    if (id.isEmpty) return;
    if (personal) {
      _personalConvoIds.add(id);
    } else {
      _personalConvoIds.remove(id);
    }
    final prefs = _prefs ?? await SharedPreferences.getInstance();
    _prefs = prefs;
    await prefs.setStringList(
      _prefsPersonalConvoIdsKey,
      _personalConvoIds.toList(growable: false),
    );
    unawaited(
      _mirrorConvoStateToOwnDevices(convoId: id, personal: personal),
    );
    _changed.add(null);
  }

  Future<void> setManyChatsPersonal({
    required Iterable<String> convoIds,
    required bool personal,
  }) async {
    var changed = false;
    for (final raw in convoIds) {
      final id = raw.trim();
      if (id.isEmpty) continue;
      if (personal) {
        changed = _personalConvoIds.add(id) || changed;
      } else {
        changed = _personalConvoIds.remove(id) || changed;
      }
    }
    if (!changed) return;
    final prefs = _prefs ?? await SharedPreferences.getInstance();
    _prefs = prefs;
    await prefs.setStringList(
      _prefsPersonalConvoIdsKey,
      _personalConvoIds.toList(growable: false),
    );
    _changed.add(null);
  }

