  Future<void> _applyAutoDeleteRetentionForConvo(String convoId) async {
    final db = _db;
    if (db == null) return;
    final row = await db.convoGet(convoId);
    final secs = (row?['auto_delete_seconds'] as num?)?.toInt();
    if (secs != null && secs > 0) {
      final cutoff = DateTime.now().millisecondsSinceEpoch - (secs * 1000);
      await db.pruneConversationEventsOlderThan(
        convoId: convoId,
        cutoffCreatedAtMs: cutoff,
      );
    }
    await _applyRoomHistoryVisibilityRetentionForConvo(convoId);
  }

  // Background maintenance for the conversation list: retention sweep +
  // request auto-accept. Runs off the render path (see _loadConversationsFromDb)
  // and refreshes the list when finished so any deletions/accepts show up.
  Future<void> _runConversationMaintenance(AppDb db) async {
    try {
      // 🔴 БЕЗ ПОТОЛКА В ДВЕСТИ (02.09.2026, аудит масштабирования). Прежний
      // предел молча отключал автоудаление для всего, что не попало в первые
      // двести бесед по этой сортировке. Это не про скорость, а про обещание:
      // человек включил «удалять через неделю», а сообщения оставались лежать.
      // Выпадали при этом самые старые по времени последнего события — то есть
      // ровно те, где автоудаление нужнее всего.
      //
      // Проход идёт по строкам, а не по идентификаторам, поэтому цена беседы с
      // выключенным автоудалением — ноль запросов.
      final rows = await db.convoList(limit: _convoMaintenanceScanLimit);
      await _applyRetentionForConvoRows(rows);
      await _autoAcceptPendingRequestsFromDb(db);
      // Granular mute: flip any time-limited mutes whose deadline passed.
      final expiredMutes = await db.convoExpireMutes();
      if (expiredMutes.isNotEmpty) {
        refreshPushNotificationPolicy();
      }
      _invalidateListConversationsCache();
      if (!_changed.isClosed) {
        _changed.add(null);
      }
    } catch (_) {
      // best-effort maintenance — never blocks or breaks the list render
    }
  }

  /// Массовый проход автоудаления по УЖЕ полученным строкам бесед.
  ///
  /// 🔴 ПОЧЕМУ ОТДЕЛЬНО ОТ [_applyConversationRetentionForConvos] (02.09.2026,
  /// аудит масштабирования). Та функция принимает идентификаторы и для каждого
  /// зовёт `convoGet` — отдельный запрос ради одного поля со сроком
  /// автоудаления. В обслуживании списка это давало по запросу на КАЖДУЮ
  /// беседу раз в минуту, при том что `convoList` строкой выше уже вернул все
  /// поля всех бесед. Двести запросов за данными, которые лежат в руках.
  ///
  /// Точечная функция остаётся как есть: её зовут из десятка мест после
  /// отправки и приёма конкретного сообщения, где строки на руках нет.
  ///
  /// Обход комнат вызывается только для комнат: для личной беседы он и так
  /// возвращал пустоту, просто после лишнего ветвления.
  Future<void> _applyRetentionForConvoRows(
    Iterable<Map<String, Object?>> rows,
  ) async {
    final db = _db;
    if (db == null) return;
    final nowMs = DateTime.now().millisecondsSinceEpoch;
    final seen = <String>{};
    for (final row in rows) {
      final convoId = (row['convo_id'] as String?)?.trim() ?? '';
      if (convoId.isEmpty || !seen.add(convoId)) continue;
      final secs = (row['auto_delete_seconds'] as num?)?.toInt();
      if (secs != null && secs > 0) {
        await db.pruneConversationEventsOlderThan(
          convoId: convoId,
          cutoffCreatedAtMs: nowMs - (secs * 1000),
        );
      }
      if (convoId.startsWith('group:')) {
        await _applyRoomHistoryVisibilityRetentionForConvo(convoId);
      }
    }
  }

  Future<void> _applyConversationRetentionForConvos(
    Iterable<String> convoIds,
  ) async {
    final uniqueConvoIds = convoIds
        .map((convoId) => convoId.trim())
        .where((convoId) => convoId.isNotEmpty)
        .toSet()
        .toList(growable: false);
    for (final convoId in uniqueConvoIds) {
      await _applyAutoDeleteRetentionForConvo(convoId);
    }
  }

  Future<int?> _roomHistoryVisibilityCutoffCreatedAtMs(String convoId) async {
    final cleanedConvoId = convoId.trim();
    final selfProfileId = profileId.trim();
    if (!cleanedConvoId.startsWith('group:') || selfProfileId.isEmpty) {
      return null;
    }
    final settings = await getRoomSettings(cleanedConvoId);
    if (settings.chatHistoryVisible) {
      return null;
    }
    final membershipState = await _roomMembershipStateOrLegacyActive(
      cleanedConvoId,
      selfProfileId,
    );
    if (membershipState == null) {
      return null;
    }
    if (RoomMembershipStatusX.fromValue(membershipState.status) !=
        RoomMembershipStatus.active) {
      return null;
    }
    final cutoffCreatedAtMs = membershipState.createdAtMs;
    return cutoffCreatedAtMs > 0 ? cutoffCreatedAtMs : null;
  }

  Future<void> _applyRoomHistoryVisibilityRetentionForConvo(
    String convoId,
  ) async {
    final db = _db;
    if (db == null) return;
    final cutoffCreatedAtMs = await _roomHistoryVisibilityCutoffCreatedAtMs(
      convoId,
    );
    if (cutoffCreatedAtMs == null) {
      return;
    }
    await db.pruneConversationEventsOlderThan(
      convoId: convoId,
      cutoffCreatedAtMs: cutoffCreatedAtMs,
    );
  }

  String _conversationHistoryClearCutoffPrefKey(String convoId) {
    return 'convo_history_clear_cutoff_v1_${convoId.trim()}';
  }

  Future<SharedPreferences?> _prefsOrNull() async {
    if (_prefs != null) {
      return _prefs;
    }
    try {
      final prefs = await SharedPreferences.getInstance();
      _prefs = prefs;
      return prefs;
    } on MissingPluginException {
      return null;
    }
  }

  Future<int?> _conversationHistoryClearCutoffMs(String convoId) async {
    final cleanedConvoId = convoId.trim();
    if (cleanedConvoId.isEmpty) {
      return null;
    }
    final prefs = await _prefsOrNull();
    if (prefs == null) {
      return null;
    }
    final value = prefs.getInt(
      _conversationHistoryClearCutoffPrefKey(cleanedConvoId),
    );
    if (value == null || value <= 0) {
      return null;
    }
    return value;
  }

  Future<bool> _shouldDropConversationEventByClearCutoff({
    required String convoId,
    required int createdAtMs,
  }) async {
    if (createdAtMs <= 0) {
      return false;
    }
    final cutoffCreatedAtMs = await _conversationHistoryClearCutoffMs(convoId);
    return cutoffCreatedAtMs != null && createdAtMs <= cutoffCreatedAtMs;
  }

  Future<void> _applyConversationHistoryClear({
    required String convoId,
    required int cutoffCreatedAtMs,
  }) async {
    final cleanedConvoId = convoId.trim();
    if (cleanedConvoId.isEmpty || cutoffCreatedAtMs <= 0) {
      return;
    }
    final prefs = await _prefsOrNull();
    final key = _conversationHistoryClearCutoffPrefKey(cleanedConvoId);
    final existingCutoffCreatedAtMs = prefs?.getInt(key) ?? 0;
    final effectiveCutoffCreatedAtMs =
        cutoffCreatedAtMs > existingCutoffCreatedAtMs
        ? cutoffCreatedAtMs
        : existingCutoffCreatedAtMs;
    if (prefs != null) {
      await prefs.setInt(key, effectiveCutoffCreatedAtMs);
    }

    final db = _db;
    if (db != null) {
      await db.clearConversationHistoryUpTo(
        convoId: cleanedConvoId,
        cutoffCreatedAtMs: effectiveCutoffCreatedAtMs,
      );
    }
    _changed.add(null);
  }

  Map<String, Object?> _buildClearHistoryCommandPayload({
    required String convoId,
    required int cutoffCreatedAtMs,
    required bool isRoom,
  }) {
    return <String, Object?>{
      'v': 1,
      'convoId': convoId.trim(),
      'cutoffCreatedAtMs': cutoffCreatedAtMs,
      'scope': isRoom ? 'room' : 'direct',
    };
  }

  Future<void> clearChatHistory({required String convoId}) async {
    final cleanedConvoId = convoId.trim();
    if (cleanedConvoId.isEmpty) {
      return;
    }
    await _applyConversationHistoryClear(
      convoId: cleanedConvoId,
      cutoffCreatedAtMs: DateTime.now().millisecondsSinceEpoch,
    );
  }

  Future<void> clearChatHistoryEverywhere({
    required String convoId,
    String? directPeerProfileId,
  }) async {
    final cleanedConvoId = convoId.trim();
    if (cleanedConvoId.isEmpty) {
      return;
    }

    final selfProfileId = profileId.trim();
    if (cleanedConvoId.startsWith('group:')) {
      final policy = await getRoomPolicyState(cleanedConvoId);
      if (!policy.canManageSettings) {
        throw RoomPolicyFailure(RoomPolicyFailureCode.adminOnly);
      }

      final cutoffCreatedAtMs = DateTime.now().millisecondsSinceEpoch;
      await _applyConversationHistoryClear(
        convoId: cleanedConvoId,
        cutoffCreatedAtMs: cutoffCreatedAtMs,
      );

      final recipients = (await listGroupMembers(cleanedConvoId))
          .where((profileId) => profileId.trim().isNotEmpty)
          .map((profileId) => profileId.trim())
          .toSet();
      if (selfProfileId.isNotEmpty) {
        recipients.add(selfProfileId);
      }

      final controlText = _encodeCommandPayload(
        _clearHistoryCmdPrefix,
        _buildClearHistoryCommandPayload(
          convoId: cleanedConvoId,
          cutoffCreatedAtMs: cutoffCreatedAtMs,
          isRoom: true,
        ),
      );
      for (final recipientProfileId in recipients) {
        await sendControlMessage(
          peerProfileId: recipientProfileId,
          controlText: controlText,
          // A5: a room clear-history tombstone must reach an offline member too
          // (privacy — otherwise the cleared messages linger on their device).
          queueIfNoDevices: true,
        );
      }
      return;
    }

    final cutoffCreatedAtMs = DateTime.now().millisecondsSinceEpoch;
    await _applyConversationHistoryClear(
      convoId: cleanedConvoId,
      cutoffCreatedAtMs: cutoffCreatedAtMs,
    );

    final cleanedPeerProfileId = (directPeerProfileId ?? cleanedConvoId).trim();
    if (cleanedPeerProfileId.isEmpty) {
      return;
    }

    if (selfProfileId.isNotEmpty) {
      await sendControlMessage(
        peerProfileId: selfProfileId,
        controlText: _encodeCommandPayload(
          _clearHistoryCmdPrefix,
          _buildClearHistoryCommandPayload(
            convoId: cleanedPeerProfileId,
            cutoffCreatedAtMs: cutoffCreatedAtMs,
            isRoom: false,
          ),
        ),
      );
    }

    if (selfProfileId.isNotEmpty && cleanedPeerProfileId != selfProfileId) {
      await sendControlMessage(
        peerProfileId: cleanedPeerProfileId,
        controlText: _encodeCommandPayload(
          _clearHistoryCmdPrefix,
          _buildClearHistoryCommandPayload(
            convoId: selfProfileId,
            cutoffCreatedAtMs: cutoffCreatedAtMs,
            isRoom: false,
          ),
        ),
      );
    }
  }

  Future<void> deleteEventsLocal({
    required String convoId,
    required List<String> eventIds,
  }) async {
    final db = _db;
    if (db == null || eventIds.isEmpty) return;
    // 🔴 DF-1 (17.09.2026). Принадлежность чату проверялась по 5 000 САМЫХ
    // СТАРЫХ событий (`listEventsChronological` идёт по возрастанию): в
    // длинной переписке свежее сообщение не находилось, и «удалить у себя»
    // молча ничего не делало. Проверяем сами номера.
    final existing = (await db.eventIdsInConvo(
      convoId: convoId,
      eventIds: eventIds,
    )).toSet();
    final filtered = eventIds.where(existing.contains).toList(growable: false);
    if (filtered.isEmpty) return;
    await db.deleteEventsByIds(filtered);
    _changed.add(null);
  }

  Future<void> deleteChat({required String convoId}) async {
    final db = _db;
    if (db == null) return;

    // If it's a request conversation, also remove the request record.
    if (convoId.startsWith('req:')) {
      final pid = convoId.substring(4);
      if (pid.isNotEmpty) {
        try {
          await db.requestDelete(pid);
        } catch (_) {
          // ignore
        }
      }
    }

    await db.deleteConversationData(
      convoId: convoId,
      keepConversationRow: false,
    );
    // A deleted chat must leave any custom folders it belonged to. (The DB
    // delete above also clears membership; this is an explicit, idempotent
    // safeguard and refreshes the in-memory folder cache.)
    try {
      await db.folderRemoveConvoEverywhere(convoId);
    } catch (_) {
      // ignore folder cleanup failures
    }
    _changed.add(null);
  }

  Future<void> exportChatToClipboard({
    required String convoId,
    required String title,
  }) async {
    final db = _db;
    if (db == null) return;

    final rows = await db.listEventsChronological(convoId, limit: 500);
    final events = rows
        .map(
          (r) => ChatEvent(
            eventId: r['event_id'] as String,
            createdAtMs: (r['created_at_ms'] as num).toInt(),
            type: (r['type'] as String?) ?? 'msg',
            ciphertextB64: r['ciphertext_b64'] as String,
            localCiphertextB64: r['local_ciphertext_b64'] as String?,
            senderDeviceId: r['sender_device_id'] as String,
            localState: r['local_state'] as String? ?? 'received',
            payloadEventId: r['payload_event_id'] as String?,
          ),
        )
        .toList(growable: false);

    final b = StringBuffer();
    b.writeln('Secretly chat export');
    b.writeln('title=$title');
    b.writeln('convo_id=$convoId');
    b.writeln('exported_at=${DateTime.now().toIso8601String()}');
    b.writeln('---');

    for (final e in events) {
      final when = DateTime.fromMillisecondsSinceEpoch(
        e.createdAtMs,
      ).toIso8601String();
      final fromMe = e.senderDeviceId == deviceId;
      final who = fromMe ? 'me' : e.senderDeviceId;
      final text = await decryptPlainAsync(e);
      b.writeln('[$when] $who: $text');
    }

    await Clipboard.setData(ClipboardData(text: b.toString()));
  }

  Future<List<Contact>> listContacts() async {
    final db = _db;
    if (db == null) return const [];
    final rows = await db.contactsList(limit: 500);
    // PERF: batch the profile-meta fetch into ONE `IN (...)` query instead of an
    // N+1 loop. listContacts runs on hot paths (every group-timeline rebuild via
    // listRoomMembersDetailed), so the old per-contact `profileMetaGet` meant up
    // to 500 serialized DB round-trips per rebuild — a primary source of group
    // scroll/render stutter for users with large contact books.
    final metaByPid = await db.profileMetaGetForProfiles(<String>[
      for (final r in rows) (r['contact_profile_id'] as String),
    ]);
    final out = <Contact>[];
    for (final r in rows) {
      final pid = r['contact_profile_id'] as String;
      final localEmoji = r['contact_emoji'] as String?;
      final meta = metaByPid[pid];
      final resolvedName = _resolvedContactDisplayName(
        contactRow: r,
        metaRow: meta,
      );
      final avatarPath = _visiblePeerAvatarPath(contactRow: r, metaRow: meta);
      if ((resolvedName == null || avatarPath == null) &&
          _keys != null &&
          !_transportBlocked) {
        _refreshProfileMetaSoon(pid);
      }

      final peerHasBadge =
          (_trimmedMetaString(meta, 'premium_badge') ?? '').isNotEmpty;
      out.add(
        Contact(
          profileId: pid,
          displayName: resolvedName,
          avatarPath: avatarPath,
          emoji: localEmoji,
          frameId: _gatedPeerCosmetic(
            _trimmedMetaString(meta, 'frame_id'),
            peerHasBadge: peerHasBadge,
            kind: CosmeticKind.avatarFrame,
          ),
          coverId: _gatedPeerCosmetic(
            _trimmedMetaString(meta, 'cover_id'),
            peerHasBadge: peerHasBadge,
            kind: CosmeticKind.profileCover,
          ),
          coverImagePath: _gatedPeerCosmetic(
            _trimmedMetaString(meta, 'cover_path'),
            peerHasBadge: peerHasBadge,
            kind: CosmeticKind.profileCover,
          ),
          emojiStatus: _gatedPeerCosmetic(
            _trimmedMetaString(meta, 'emoji_status'),
            peerHasBadge: peerHasBadge,
          ),
          premiumBadge: peerHasBadge,
        ),
      );
    }
    return out;
  }

  /// Returns the list of device IDs registered to the current profile on the
  /// keys server. Used by the desktop devices subscreen (Slice 4).
  ///
  /// Now propagates errors instead of silently returning an empty list —
  /// otherwise a transient transport failure (or missing _keys client) was
  /// indistinguishable from a genuinely-empty server response and the UI
  /// rendered «Устройств не найдено» without a way to recover. The desktop
  /// _DevicesPane catches and shows a real error row + Retry button.
  Future<List<String>> listMyDeviceIds() async {
    final pid = (_profileId ?? '').trim();
    if (pid.isEmpty) {
      throw StateError(
        'Профиль ещё не инициализирован. Завершите подключение к серверу.',
      );
    }
    return _listDevicesAuthed(pid);
  }

