  /// Everyone who has actually READ this room message, newest-read first
  /// (the underlying query already orders by updated_at_ms DESC). Excludes
  /// delivered-but-unread receipts — this backs the "Who read" sheet, which
  /// is specifically about read status, not delivery.
  Future<List<({String profileId, int readAtMs})>> roomMessageReaders(
    String payloadEventId,
  ) async {
    final db = _db;
    if (db == null) return const [];
    final cleaned = payloadEventId.trim();
    if (cleaned.isEmpty) return const [];
    final rows = await db.roomMessageReceiptList(cleaned);
    return rows
        .where((r) => r.status == MessageReceiptState.read)
        .map((r) => (profileId: r.readerProfileId, readAtMs: r.updatedAtMs))
        .toList(growable: false);
  }

  Future<void> setContactAvatarFromImageBytes({
    required String profileId,
    required Uint8List bytes,
  }) async {
    final db = _db;
    if (db == null) return;

    final decoded = img.decodeImage(bytes);
    if (decoded == null) {
      throw StateError('Unsupported image');
    }

    final side = decoded.width < decoded.height
        ? decoded.width
        : decoded.height;
    final x = (decoded.width - side) ~/ 2;
    final y = (decoded.height - side) ~/ 2;
    final cropped = img.copyCrop(
      decoded,
      x: x,
      y: y,
      width: side,
      height: side,
    );
    const maxContactAvatarSide = 1024;
    final targetSide = side < maxContactAvatarSide
        ? side
        : maxContactAvatarSide;
    final resized = img.copyResize(
      cropped,
      width: targetSide,
      height: targetSide,
      interpolation: img.Interpolation.average,
    );
    final png = Uint8List.fromList(img.encodePng(resized));

    final dir = await getApplicationDocumentsDirectory();
    final avatarDir = Directory(p.join(dir.path, 'contact_avatars'));
    if (!await avatarDir.exists()) {
      await avatarDir.create(recursive: true);
    }
    final safe = profileId.replaceAll(RegExp(r'[^a-zA-Z0-9_-]'), '_');
    final path = p.join(avatarDir.path, '$safe.png');
    await File(path).writeAsBytes(png, flush: true);

    await db.contactSetAvatarPath(profileId: profileId, avatarPath: path);
    _changed.add(null);
    _scheduleManagedDeviceContactSync();
  }

  Future<String?> cachedProfileIdByDeviceId(String deviceId) async {
    final db = _db;
    if (db == null) return null;
    final did = deviceId.trim();
    if (did.isEmpty) return null;
    final profileId = await db.deviceProfileCached(did);
    if (profileId == null) return null;
