    return normalized.isEmpty ? null : normalized;
  }

  /// Resolves a device id to its owner's profile id, hitting the keys server
  /// (authenticated device lookup) when the local cache misses, and caching
  /// the result. Used by the group-message author tap so an unknown member —
  /// one who has never messaged us 1:1, so the device→profile cache is empty —
  /// still opens their profile instead of silently doing nothing.
  Future<String?> resolveProfileIdForDevice(String deviceId) =>
      _resolveProfileIdForDevice(deviceId);

  /// Fire-and-forget, throttled warm of the device→profile cache (5-min per
  /// device, same budget as the receive-path lookup) so an unknown group
  /// author's real name replaces the raw device fallback on a later rebuild.
  void warmProfileIdForDeviceSoon(String deviceId) {
    final did = deviceId.trim();
    if (did.isEmpty || _transportBlocked) return;
    final nowMs = DateTime.now().millisecondsSinceEpoch;
    final lastMs = _deviceProfileLookupAtMs[did] ?? 0;
    if (nowMs - lastMs < 5 * 60 * 1000) return;
    _deviceProfileLookupAtMs[did] = nowMs;
    unawaited(
      _resolveProfileIdForDevice(did).catchError((Object _) => null),
    );
  }

