  Future<List<RequestItem>> listRequests() async {
    final db = _db;
    if (db == null) return const [];
    await _autoAcceptPendingRequestsFromDb(db);
    final rows = await db.requestsListPending(limit: 200);
    final convoRows = await db.convoList(limit: 500);
    final lastByConvoId = <String, int>{
      for (final r in convoRows)
        (r['convo_id'] as String): (r['last_event_at_ms'] as num).toInt(),
    };
    final out = <RequestItem>[];
    for (final r in rows) {
      final profileId = r['contact_profile_id'] as String;
      final meta = await db.profileMetaGet(profileId);
      final nick = meta?['nickname'] as String?;
      final convoId = 'req:$profileId';
      final lastAt = lastByConvoId[convoId] ?? 0;
      out.add(
        RequestItem(
          profileId: profileId,
          convoId: convoId,
          lastEventAtMs: lastAt,
          nickname: nick,
          avatarPath: _visiblePeerAvatarPath(contactRow: null, metaRow: meta),
        ),
      );
    }
    return out;
  }

  Future<void> acceptRequest(String profileId) async {
    final db = _db;
    if (db == null) return;
    final normalizedProfileId = _stripRequestConvoPrefix(profileId);
    if (normalizedProfileId.isEmpty) return;
    DiagLog.event('request', 'accept_start', {
      'peer': DiagLog.pfx(normalizedProfileId),
    });
    await db.requestAccept(profileId: normalizedProfileId);
    await _finalizeAcceptedRequest(
      profileId: normalizedProfileId,
      markExistingIncomingRead: true,
    );
    DiagLog.event('request', 'accept_finalized', {
      'peer': DiagLog.pfx(normalizedProfileId),
    });
    _changed.add(null);
  }

  Future<void> _autoAcceptPendingRequestsFromDb(AppDb db) async {
    final rows = await db.requestsListPending(limit: 200);
    if (rows.isEmpty) return;
    var changed = false;
    for (final row in rows) {
      final profileId = ((row['contact_profile_id'] as String?) ?? '').trim();
      if (profileId.isEmpty) continue;
      if (await db.blockedProfileIsBlocked(profileId)) continue;
      await db.requestAccept(profileId: profileId);
      unawaited(refreshContactDevices(profileId).catchError((_) {}));
      unawaited(refreshProfileMeta(profileId).catchError((_) {}));
      changed = true;
      DiagLog.event('request', 'auto_accept_pending', {
        'peer': DiagLog.pfx(profileId),
      });
    }
    if (changed) {
      _listConversationsCache = null;
      _changed.add(null);
    }
  }

  String _stripRequestConvoPrefix(String value) {
    var normalized = value.trim();
    while (normalized.startsWith('req:') && normalized.length > 4) {
      normalized = normalized.substring(4).trim();
    }
    return normalized;
  }

  /// Compress an exception into a short, alphanumeric reason code suitable for
  /// `DiagLog` (no plaintext, no stack, no PII).
  static String _classifyShortReason(Object error) {
    final s = error.toString();
    final lower = s.toLowerCase();
    if (lower.contains('rate_limited') || lower.contains(' 429')) {
      return 'rate_limited';
    }
    if (lower.contains('socketexception') ||
        lower.contains('failed host lookup')) {
      return 'network';
    }
    if (lower.contains('timeout')) return 'timeout';
    if (lower.contains('handshake') || lower.contains('certificate')) {
      return 'tls';
    }
    if (lower.contains('blocked')) return 'blocked';
    if (lower.contains('unauthorized') || lower.contains(' 401')) {
      return 'unauthorized';
    }
    if (lower.contains('forbidden') || lower.contains(' 403')) {
      return 'forbidden';
    }
    if (lower.contains('not found') || lower.contains(' 404')) {
      return 'not_found';
    }
    if (lower.contains('statefulerror') || lower.contains('statelocked')) {
      return 'state_locked';
    }
    if (lower.contains('formatexception')) return 'bad_format';
    if (lower.contains('database') || lower.contains('sqlite')) {
      return 'db_error';
    }
    if (error is StateError) return 'state_error';
    if (error is FormatException) return 'bad_format';
    if (error is TypeError) return 'type_error';
    return 'other';
  }

  Future<String?> _normalizeDirectPeerProfileId(String value) async {
    var normalized = _stripRequestConvoPrefix(value);
    if (normalized.isEmpty) return null;

    final db = _db;
    if (db != null &&
        !normalized.startsWith('dev:') &&
        !normalized.startsWith('group:')) {
      final convo = await db.convoGet(normalized);
      final peerFromConvo = (convo?['peer_profile_id'] as String?)?.trim();
      if (peerFromConvo != null && peerFromConvo.isNotEmpty) {
        normalized = _stripRequestConvoPrefix(peerFromConvo);
      }
    }

    final resolved = await _resolvePeerProfileId(normalized) ?? normalized;
    DiagLog.event('send', 'normalize', {
      'in': DiagLog.pfx(value),
      'out': DiagLog.pfx(resolved),
      'is_req_prefix': value.startsWith('req:'),
    });
    return resolved;
  }

  Future<void> _finalizeAcceptedRequest({
    required String profileId,
    required bool markExistingIncomingRead,
  }) async {
    final db = _db;
    if (db == null) return;

    await db.convoEnsure1to1(peerProfileId: profileId);
    try {
      await db.convoMerge(fromConvoId: 'req:$profileId', toConvoId: profileId);
    } catch (_) {
      // ignore
    }

    try {
      await refreshContactDevices(profileId);
      final devices = await db.contactDevicesList(profileId);
      for (final row in devices) {
        final deviceId = (row['device_id'] as String?)?.trim() ?? '';
        if (deviceId.isEmpty) continue;
        final devConvoId = 'dev:$deviceId';
        if (devConvoId == profileId) continue;
        try {
          await db.convoMerge(fromConvoId: devConvoId, toConvoId: profileId);
        } catch (_) {
          // ignore
        }
      }
    } catch (_) {
      // ignore
    }

    try {
      await refreshProfileMeta(profileId);
    } catch (_) {
      // ignore
    }

    if (markExistingIncomingRead) {
      await _markAcceptedRequestHistoryRead(profileId);
    }
    _setConversationTyping(convoId: profileId, typing: false, notify: false);
  }

  Future<void> _markAcceptedRequestHistoryRead(String profileId) async {
    final db = _db;
    final did = _deviceId;
    if (db == null || did == null || did.trim().isEmpty) return;

    final unread = await db.listUnreadIncomingForConvo(
      convoId: profileId,
      selfDeviceId: did,
      excludedSenderDeviceIds: _ownDeviceIdsForUnreadQueries(),
      limit: 500,
    );
    if (unread.isEmpty) return;

    final now = DateTime.now().millisecondsSinceEpoch;
    final eventIds = <String>[];
    final deliveredIntents = <_PendingReceiptIntent>[];
    final readIntents = <_PendingReceiptIntent>[];
    for (final row in unread) {
      final eventId = ((row['event_id'] as String?) ?? '').trim();
      final senderDeviceId = ((row['sender_device_id'] as String?) ?? '')
          .trim();
      final payloadEventId = ((row['payload_event_id'] as String?) ?? '')
          .trim();
      if (eventId.isNotEmpty) {
        eventIds.add(eventId);
      }
      if (senderDeviceId.isNotEmpty &&
          !isOwnDeviceId(senderDeviceId) &&
          payloadEventId.isNotEmpty) {
        // Send delivered first so the sender sees "arrived" before "read".
        deliveredIntents.add((
          peerDeviceId: senderDeviceId,
          peerProfileId: profileId,
          payloadEventId: payloadEventId,
          convoId: profileId,
          status: MessageReceiptState.delivered,
        ));
        readIntents.add((
          peerDeviceId: senderDeviceId,
          peerProfileId: profileId,
          payloadEventId: payloadEventId,
          convoId: profileId,
          status: MessageReceiptState.read,
        ));
      }
    }

    if (deliveredIntents.isNotEmpty) {
      await _persistPendingReceiptIntents(
        intents: deliveredIntents,
        nowMs: now,
      );
      await _flushPendingReceiptsBestEffort();
    }
    if (readIntents.isNotEmpty) {
      await _persistPendingReceiptIntents(intents: readIntents, nowMs: now);
      await _flushPendingReceiptsBestEffort();
    }
    await db.markEventsReadByIds(eventIds, readAtMs: now);
    if (!_transportBlocked) {
      _kickRelayOutbox(_relay);
    }
  }

  Future<void> blockRequest(String profileId) async {
    final db = _db;
    final relay = _relay;
    if (db == null) return;
    await db.requestUpsert(profileId: profileId, status: 'blocked');

    // Also add to server-backed block list (best-effort; local block always applies).
    await db.blockedProfileSet(profileId: profileId, blocked: true);
    if (!_transportBlocked && relay != null) {
      try {
        await relay.setProfileBlocked(
          blockedProfileId: profileId,
          blocked: true,
        );
      } catch (_) {
        // ignore
      }
    }

    await db.convoEnsureRequest(peerProfileId: profileId);
    _changed.add(null);
  }

  Future<List<String>> listBlockedProfiles() async {
    final db = _db;
    if (db == null) return const [];
    final rows = await db.blockedProfilesList(limit: 2000);
    return rows
        .map((r) => r['blocked_profile_id'] as String)
        .where((s) => s.isNotEmpty)
        .toList(growable: false);
  }

  Future<void> setProfileBlocked({
    required String profileId,
    required bool blocked,
    required bool deleteChatHistory,
  }) async {
    final db = _db;
    final relay = _relay;
    if (db == null) return;

    // Best-effort server enforcement.
    if (!_transportBlocked && relay != null) {
      try {
        await relay.setProfileBlocked(
          blockedProfileId: profileId,
          blocked: blocked,
        );
      } catch (error) {
        throw describeContactActionFailure(
          error,
          fallbackCode: ContactActionFailureCode.serviceUnavailable,
        );
      }
    }

    await db.blockedProfileSet(profileId: profileId, blocked: blocked);

    // Keep Requests status in sync so unknown senders are ignored even before relay enforcement.
    if (blocked) {
      await db.requestUpsert(profileId: profileId, status: 'blocked');
    } else {
      final st = await db.requestStatus(profileId);
      if (st == 'blocked') {
        await db.requestDelete(profileId);
      }
    }

    if (deleteChatHistory) {
      try {
        await deleteChat(convoId: profileId);
      } catch (_) {
        // ignore
      }
      try {
        await deleteChat(convoId: 'req:$profileId');
      } catch (_) {
        // ignore
      }
    }

    _changed.add(null);
  }

  Future<void> addContact({
    required String profileId,
    String? displayName,
    bool displayNameIsCustom = false,
  }) async {
    final db = _db;
    if (db == null) return;
    final normalizedProfileId = profileId.trim();
    if (normalizedProfileId.isEmpty) {
      throw ContactActionFailure(ContactActionFailureCode.generic);
    }
    if (_transportBlocked) {
      throw ContactActionFailure(ContactActionFailureCode.transportBlocked);
    }

    // Best-effort validation (Telegram-like UX): when Keys is reachable, reject typos early.
    // This only runs when the user explicitly adds a contact by ID.
    final keys = _keys;
    if (keys != null) {
      try {
        final exists = await keys.profileExists(normalizedProfileId);
        if (!exists) {
          throw ContactActionFailure(ContactActionFailureCode.profileNotFound);
        }
      } on ContactActionFailure {
        rethrow;
      } catch (_) {
        // If Keys is temporarily unreachable, allow adding and fail later on send.
      }
    }

    await db.contactUpsert(
      profileId: normalizedProfileId,
      displayName: displayName,
      displayNameIsCustom: displayNameIsCustom,
    );
    await db.convoEnsure1to1(peerProfileId: normalizedProfileId);

    // Best-effort: cache current device list + identity keys for verification.
    try {
      await refreshContactDevices(normalizedProfileId);
    } catch (_) {
      // ignore
    }

    try {
      await refreshProfileMeta(normalizedProfileId);
    } catch (_) {
      // ignore
    }
    _changed.add(null);
    _scheduleManagedDeviceContactSync();
  }

  Future<String?> prepareSharedProfileConversation(String profileId) async {
    final db = _db;
    final normalizedProfileId = normalizeSharedProfileId(profileId);
    if (db == null || normalizedProfileId.isEmpty) {
      return null;
    }

    final keys = _keys;
    if (!_transportBlocked && keys != null) {
      try {
        final exists = await keys.profileExists(normalizedProfileId);
        if (!exists) {
          return null;
        }
      } catch (_) {
        // Allow offline fallback so an existing local chat can still open.
      }
    }

    final readyForDirectChat = await _ensureDirectConversationReadyForOutgoing(
      normalizedProfileId,
    );
    if (!readyForDirectChat) {
      await db.convoEnsureRequest(peerProfileId: normalizedProfileId);
    }

    try {
      await refreshProfileMeta(normalizedProfileId);
    } catch (_) {
      // ignore
    }

    _changed.add(null);
    return readyForDirectChat
        ? normalizedProfileId
        : 'req:$normalizedProfileId';
  }

  Future<bool> _ensureDirectConversationReadyForOutgoing(
    String peerProfileId,
  ) async {
    final db = _db;
    final normalizedProfileId =
        (await _normalizeDirectPeerProfileId(peerProfileId))?.trim() ?? '';
    if (db == null || normalizedProfileId.isEmpty) {
      return false;
    }

    final myPid = (_profileId ?? '').trim();
    if (myPid.isNotEmpty && normalizedProfileId == myPid) {
      await db.convoEnsure1to1(peerProfileId: normalizedProfileId);
      return true;
    }

    final requestStatus = (await db.requestStatus(normalizedProfileId) ?? '')
        .trim();
    if (requestStatus == 'blocked') {
      await db.convoEnsureRequest(peerProfileId: normalizedProfileId);
      return false;
    }

    final contact = await db.contactGet(normalizedProfileId);
    final requestConvo = await db.convoGet('req:$normalizedProfileId');
    final needsPromotion =
        requestStatus == 'pending' || contact == null || requestConvo != null;
    if (needsPromotion) {
      await db.requestAccept(profileId: normalizedProfileId);
      await _finalizeAcceptedRequest(
        profileId: normalizedProfileId,
        markExistingIncomingRead: true,
      );
      return true;
    }

    await db.convoEnsure1to1(peerProfileId: normalizedProfileId);
    return true;
  }

  Future<void> _cacheRecipientDeviceStatuses({
    required String peerProfileId,
    required List<KeysDeviceStatus> devices,
  }) async {
    final db = _db;
    if (db == null) return;

    // И-1 field fix (2026-07-21): a rotated peer shows up as a NEW device_id,
    // not as an identity change under the old id — so the safety-number notice
    // must also fire when a KNOWN contact grows a device we have never seen.
    // First discovery (no prior rows) and own profile stay silent.
    final hadDevicesBefore =
        (await db.contactDevicesList(peerProfileId)).isNotEmpty;
    var sawNewDevice = false;
    final freshDeviceIds = <String>[];
    final cachedDeviceIds = <String>{};
    for (final device in devices) {
      final deviceId = device.deviceId.trim();
      if (deviceId.isEmpty || !device.hasBundle || !device.hasBundleMetadata) {
        continue;
      }

      cachedDeviceIds.add(deviceId);
      // §3: server-authoritative statuses — accept a confirmed identity rotation
      // (reinstall under the same Secretly ID) instead of failing closed.
      final upsert = await db.contactDeviceUpsert(
        profileId: peerProfileId,
        deviceId: deviceId,
        identityKeyPubB64: device.identityKeyPubB64!.trim(),
        signedPrekeyPubB64: device.signedPrekeyPubB64!.trim(),
        signedPrekeySigB64: device.signedPrekeySigB64!.trim(),
        allowIdentityRotation: true,
      );
      sawNewDevice = sawNewDevice || upsert.insertedNewDevice;
      if (upsert.insertedNewDevice) freshDeviceIds.add(deviceId);
      if (upsert.identityRotated) {
        _contactIdentityChangedAtMs[peerProfileId] =
            DateTime.now().millisecondsSinceEpoch;
        _scheduleSessionResetPing(deviceId, _resetCauseIdentityRotated);
        DiagLog.event('peer', 'identity_rotated_accepted', {
          'peer': DiagLog.pfx(peerProfileId),
          'dev': DiagLog.pfx(deviceId),
        });
        unawaited(_insertSafetyNumberChangedNotice(peerProfileId));
      }
    }
    if (sawNewDevice &&
        hadDevicesBefore &&
        peerProfileId != (_profileId ?? '').trim()) {
      _contactIdentityChangedAtMs[peerProfileId] =
          DateTime.now().millisecondsSinceEpoch;
      DiagLog.event('peer', 'new_device_seen', {
        'peer': DiagLog.pfx(peerProfileId),
      });
      unawaited(_insertSafetyNumberChangedNotice(peerProfileId));
      _kickResendToFreshPeerDevices(peerProfileId, freshDeviceIds);
    }

    final deliverableDeviceIds = cachedDeviceIds.toList(growable: false);
    // ROOT FIX (one-way): if the peer has device rows but NONE carry a published
    // bundle yet (they are mid-rotation, A2 registered but bundle not published),
    // do NOT wipe our existing devices/sessions — that strands every send until
    // they republish. Keep the current set as a fallback; a later refresh with
    // real bundles prunes normally.
    if (deliverableDeviceIds.isEmpty && devices.isNotEmpty) {
      DiagLog.event('peer', 'statuses_no_bundle_keep', {
        'peer': DiagLog.pfx(peerProfileId),
        'count': devices.length,
      });
      return;
    }
    await db.contactDevicesDeleteMissing(
      profileId: peerProfileId,
      keepDeviceIds: deliverableDeviceIds,
      deleteSessions: !i4hKeepSessionOnDevicePrune, // И-4h (C1)
    );

    _recipientDevicesCacheByProfileId[peerProfileId] =
        _RecipientDevicesCacheEntry(
          deviceIds: deliverableDeviceIds,
          fetchedAtMs: DateTime.now().millisecondsSinceEpoch,
        );
  }

  // Per-peer debounce for the inbound device-learn refresh.
  final Map<String, int> _peerDeviceLearnAtMs = <String, int>{};

  /// When an inbound message/call arrives from a device_id we don't have cached
  /// for a known contact, refresh that contact's device list so our outbound
  /// (messages, calls, receipts) targets the peer's CURRENT device instead of a
  /// dead one — half of the root fix for the one-way break after a peer
  /// recreates/rotates their account/device. Debounced per peer; best-effort.
  void _maybeLearnPeerDeviceOnInbound(
    String peerProfileId,
    String senderDeviceId,
  ) {
    try {
      final cached = _recipientDevicesCacheByProfileId[peerProfileId];
      if (cached != null && cached.deviceIds.contains(senderDeviceId)) {
        return; // already known — nothing to learn
      }
      final nowMs = DateTime.now().millisecondsSinceEpoch;
      final last = _peerDeviceLearnAtMs[peerProfileId] ?? 0;
      if (nowMs - last < 15000) return; // debounce per peer
      _peerDeviceLearnAtMs[peerProfileId] = nowMs;
      unawaited(() async {
        try {
          await refreshContactDevices(peerProfileId);
        } catch (_) {}
      }());
    } catch (_) {}
  }

  Future<void> refreshContactDevices(String peerProfileId) async {
    final db = _db;
    final keys = _keys;
    if (db == null || keys == null) return;
    Object? deviceStatusesError;

    Future<bool> cacheDeviceStatusesIfComplete(
      List<KeysDeviceStatus> deviceStatuses,
    ) async {
      // Empty list is not authoritative right after pairing — Keys may not have
      // indexed the new device yet.  Fall through to _fetchBundleAuthed so we
      // don't wipe the local contact_devices cache with an empty keepDeviceIds
      // set (which would delete all known sessions and strand all outgoing
      // messages).
      if (deviceStatuses.isEmpty) {
        return false;
      }
      final needsLegacyBundleFetch = deviceStatuses.any(
        (device) => device.hasBundle && !device.hasBundleMetadata,
      );
      if (needsLegacyBundleFetch) {
        return false;
      }
      await _cacheRecipientDeviceStatuses(
        peerProfileId: peerProfileId,
        devices: deviceStatuses,
      );
      _changed.add(null);
      return true;
    }

    try {
      _throwIfTransportBlocked();
    } catch (error) {
      throw describeContactActionFailure(error);
    }

    try {
      final deviceStatuses = await loadRecipientDeviceStatuses(peerProfileId);
      if (await cacheDeviceStatusesIfComplete(deviceStatuses)) {
        return;
      }
    } catch (error) {
      deviceStatusesError = error;
      if (_isMissingCurrentKeysDeviceError(error) &&
          await repairMissingCurrentDeviceKeysRegistration()) {
        try {
          final repairedDeviceStatuses = await loadRecipientDeviceStatuses(
            peerProfileId,
          );
          if (await cacheDeviceStatusesIfComplete(repairedDeviceStatuses)) {
            return;
          }
        } catch (repairedError) {
          deviceStatusesError = repairedError;
        }
      }
    }

    List<Map<String, Object?>> devices;
    try {
      // Peer bundle fetch remains the compatibility fallback when status lookup
      // is unavailable or rejected by the current Keys deployment contract.
      devices = await _fetchBundleAuthed(peerProfileId);
    } catch (error) {
      throw describeContactActionFailure(
        deviceStatusesError ?? error,
        fallbackCode: ContactActionFailureCode.serviceUnavailable,
      );
    }
    // И-1 field fix: see _cacheRecipientDeviceStatuses — a rotated peer is a
    // NEW device_id, and that must raise the safety-number notice too.
    final hadDevicesBefore =
        (await db.contactDevicesList(peerProfileId)).isNotEmpty;
    var sawNewDevice = false;
    final freshDeviceIds = <String>[];
    final cachedDeviceIds = <String>[];
    for (final d in devices) {
      final deviceId = d['device_id'] as String?;
      final ik = d['identity_key_pub_b64'] as String?;
      final spk = d['signed_prekey_pub_b64'] as String?;
      final sig = d['signed_prekey_sig_b64'] as String?;
      if (deviceId == null || deviceId.isEmpty) continue;
      if (ik == null || ik.isEmpty) continue;
      if (spk == null || spk.isEmpty) continue;
      if (sig == null || sig.isEmpty) continue;

      cachedDeviceIds.add(deviceId);

      // §3 (identity rotation): these bundles come from the AUTHENTICATED keys
      // server, so a changed identity here means the contact reinstalled/
      // recreated under the same Secretly ID — accept the server-confirmed new
      // identity (re-pin + drop the stale session for a fresh X3DH) instead of
      // the old fail-closed throw that left the contact permanently broken. The
      // upsert clears verification; we raise a visible "safety number changed"
      // warning so acceptance is never silent.
      // Ш-1 слоя 2: смотрим на сертификат устройства и ТОЛЬКО ПИШЕМ В ЖУРНАЛ.
      // Ничего не решает, ни на что не влияет — см. _observeAccountCertificate.
      await _observeAccountCertificate(
        peerProfileId: peerProfileId,
        deviceId: deviceId,
        deviceIdentityPubB64: ik,
        accountIdentityPubB64: d['account_identity_pub_b64'] as String?,
        deviceCertB64: d['device_cert_b64'] as String?,
      );

      final upsert = await db.contactDeviceUpsert(
        profileId: peerProfileId,
        deviceId: deviceId,
        identityKeyPubB64: ik,
        signedPrekeyPubB64: spk,
        signedPrekeySigB64: sig,
        allowIdentityRotation: true,
      );
      sawNewDevice = sawNewDevice || upsert.insertedNewDevice;
      if (upsert.insertedNewDevice) freshDeviceIds.add(deviceId);
      if (upsert.identityRotated) {
        _contactIdentityChangedAtMs[peerProfileId] =
            DateTime.now().millisecondsSinceEpoch;
        // Proactively nudge the peer to rebuild their side of the ratchet too
        // (a fresh prekey ping), so recovery doesn't wait for the next organic
        // message in their direction.
        _scheduleSessionResetPing(deviceId, _resetCauseDeviceListChanged);
        DiagLog.event('peer', 'identity_rotated_accepted', {
          'peer': DiagLog.pfx(peerProfileId),
          'dev': DiagLog.pfx(deviceId),
        });
        unawaited(_insertSafetyNumberChangedNotice(peerProfileId));
      }
    }
    if (sawNewDevice &&
        hadDevicesBefore &&
        peerProfileId != (_profileId ?? '').trim()) {
      _contactIdentityChangedAtMs[peerProfileId] =
          DateTime.now().millisecondsSinceEpoch;
      DiagLog.event('peer', 'new_device_seen', {
        'peer': DiagLog.pfx(peerProfileId),
      });
      unawaited(_insertSafetyNumberChangedNotice(peerProfileId));
      _kickResendToFreshPeerDevices(peerProfileId, freshDeviceIds);
    }

    // §3 (account reset) — SAFETY GUARD. A known contact (we already hold their
    // devices) just resolved to ZERO devices. NEVER wipe their devices/sessions
    // here: that destroys the ratchet + chat session and strands every outgoing
    // message permanently (the observed "fanout count=0 forever" symptom). The
    // empty result is almost always (a) a reinstall Keys hasn't re-indexed, or
    // (b) a full account recreate. Preserve everything, record the reset so the
    // UI can prompt a re-add and the no-device retry can stop looping. A
    // non-empty result falls through to the normal prune below (zombie cleanup +
    // learn-on-receive remain intact).
    if (cachedDeviceIds.isEmpty) {
      final hadDevices = (await db.contactDevicesList(
        peerProfileId,
      )).isNotEmpty;
      if (hadDevices) {
        var recreated = false;
        try {
          recreated = !(await keys.profileExists(peerProfileId));
        } catch (_) {
          // network hiccup → treat as transient, do NOT mark recreated
        }
        _contactPossiblyResetAtMs[peerProfileId] =
            DateTime.now().millisecondsSinceEpoch;
        _contactRecreated[peerProfileId] = recreated;
        DiagLog.event('peer', 'devices_empty_keep', {
          'peer': DiagLog.pfx(peerProfileId),
          'recreated': recreated,
        });
        _changed.add(null);
        return;
      }
    }

    // Real device list resolved — clear any prior reset flag and prune normally.
    _contactPossiblyResetAtMs.remove(peerProfileId);
    _contactRecreated.remove(peerProfileId);

    await db.contactDevicesDeleteMissing(
      profileId: peerProfileId,
      keepDeviceIds: cachedDeviceIds,
      deleteSessions: !i4hKeepSessionOnDevicePrune, // И-4h (C1)
    );

    _recipientDevicesCacheByProfileId[peerProfileId] =
        _RecipientDevicesCacheEntry(
          deviceIds: cachedDeviceIds,
          fetchedAtMs: DateTime.now().millisecondsSinceEpoch,
        );

    // Sprint 2 C1/C8: stamp a successful refresh. Read by the
    // periodic bundle re-verification watchdog (C1) and by the
    // stale-bundle UI banner (C8).
    _lastContactDevicesRefreshOkAtMs[peerProfileId] =
        DateTime.now().millisecondsSinceEpoch;

    _changed.add(null);
  }

  // Sprint 2 C1/C8: per-peer timestamp of the last successful
  // `refreshContactDevices`. Used to drive the periodic bundle
  // re-verification watchdog (catches a peer that rotated their
  // identity key while we were idle) and the "stale bundle" UI banner.
  final Map<String, int> _lastContactDevicesRefreshOkAtMs = <String, int>{};

  // §3 (account reset): per-peer timestamp of when a KNOWN contact (we had
  // their devices) suddenly resolved to ZERO devices. Set instead of wiping
  // their session/history, so the UI can flag "контакт мог пересоздать аккаунт"
  // and the no-device retry stops looping for 24h. Cleared once they resolve to
  // a real device list again. true value = the old profile_id is GONE from the
  // server (a full recreate with a new Secretly ID — manual re-add needed);
  // false = profile still exists but 0 devices (likely a reinstall in progress).
  final Map<String, int> _contactPossiblyResetAtMs = <String, int>{};
  final Map<String, bool> _contactRecreated = <String, bool>{};

  /// §3: whether a known contact recently resolved to zero devices (possibly
  /// reset/recreated). The UI reads this to show a re-add hint; the no-device
  /// retry reads it to stop hammering an unreachable peer.
  bool contactPossiblyReset(String peerProfileId) =>
      _contactPossiblyResetAtMs.containsKey(peerProfileId);

  /// §3: true when the contact's OLD profile_id no longer exists on the server
  /// (a full account recreate — they have a NEW Secretly ID and must be re-added
  /// manually; there is no automatic link to the new identity).
  bool contactWasRecreated(String peerProfileId) =>
      _contactRecreated[peerProfileId] ?? false;

  // §3 (identity rotation): per-peer timestamp of when we ACCEPTED a server-
  // confirmed identity-key change (contact reinstalled under the same Secretly
  // ID). Drives the visible "номер безопасности изменился" warning — acceptance
  // is never silent. Cleared when the user re-verifies the contact.
  final Map<String, int> _contactIdentityChangedAtMs = <String, int>{};

  /// §3: whether the contact's safety number recently changed (a server-
  /// confirmed identity rotation we auto-accepted). UI shows a re-verify warning.
  bool contactSafetyNumberChanged(String peerProfileId) =>
      _contactIdentityChangedAtMs.containsKey(peerProfileId);

  /// §3: acknowledge the safety-number-changed warning for a contact (e.g. after
  /// the user re-verifies or dismisses it).
  void acknowledgeContactSafetyNumberChange(String peerProfileId) {
    if (_contactIdentityChangedAtMs.remove(peerProfileId) != null) {
      _changed.add(null);
    }
  }

  /// §3: drop a VISIBLE, Signal-style system notice into the 1:1 timeline when
  /// we accept a server-confirmed identity rotation, so acceptance is never
  /// silent. Deduped to ~one per 10 min per peer. Best-effort.
  /// A peer's NEW device just appeared (they rotated / added a device). Any
  /// message we already sent went to their PREVIOUS device_id — and if that one
  /// is now dead, it landed in a mailbox nobody reads.
  ///
  /// Why this trigger has to exist (2026-07-21 field report): the undelivered
  /// resend used to fire only on a NACK from the peer, or on the slow
  /// convergence backstop. A NACK is impossible here — nobody is reading the
  /// dead mailbox, so no one can ever say "I could not read this" — which left
  /// only the backstop, and a tester's four messages took ~30 minutes to land.
  /// Discovering the new device IS the signal, so resend on it: the messages
  /// are re-encrypted to the live device within seconds.
  ///
  /// Bounded by the existing guards inside _resendUndeliveredDirect
  /// (re-entrancy, 90 s per-event debounce, per-pass cap, per-peer cap), so
  /// this can add latency-cutting resends but never a storm.
  void _kickResendToFreshPeerDevices(
    String peerProfileId,
    List<String> freshDeviceIds,
  ) {
    final pid = peerProfileId.trim();
    if (pid.isEmpty || freshDeviceIds.isEmpty) return;
    if (pid == (_profileId ?? '').trim()) return;
    for (final dev in freshDeviceIds) {
      final d = dev.trim();
      if (d.isEmpty || isOwnDeviceId(d)) continue;
      DiagLog.event('send', 'resend_on_new_device', {
        'peer': DiagLog.pfx(pid),
        'to_dev': DiagLog.pfx(d),
      });
      unawaited(
        _resendUndeliveredDirect(
          peerProfileId: pid,
          peerDeviceId: d,
          // Everything already sent is eligible (same as the NACK path). The
          // scheduled guard in undeliveredDirectSentEvents still keeps a
          // not-yet-due "send later" out of this sweep.
          stuckBeforeMs: DateTime.now().millisecondsSinceEpoch,
        ),
      );
    }
  }

  /// Сколько раз этому человеку показали «номер безопасности изменился»
  /// за 7 и за 30 дней, и по скольким контактам.
  ///
  /// 🔴 ЭТО ТОТ САМЫЙ ЗАМЕР, КОТОРЫЙ ГАТИТ СЛОЙ 2
  ///. Работа отложена 06.08.2026 с
  /// условием «неделю считать события», а условие было неизмеримым: оба
  /// счётчика (`new_device_seen`, `identity_rotated_accepted`) живут только в
  /// логе устройства, а он кольцевой. Плашка же вставляется в переписку
  /// постоянным событием — история есть, ждать нечего.
  ///
  /// Порог решения из ТЗ: единицы за неделю — откладывать дальше; десятки —
  /// делать как защиту (растяжка, которая звенит постоянно, перестаёт быть
  /// растяжкой).
  /// Разбор строк `failed` в исходящих: потерянные смс или мусор?
  ///
  /// `failed` — конечное состояние, такая строка не уйдёт никогда. Но
  /// переотправка минтит НОВЫЙ msg_id при том же payload, поэтому содержимое
  /// могло уехать другим конвертом. Судим по состоянию САМОГО СОБЫТИЯ:
  /// `delivered` — мусор в таблице; `sent` — доставки не видели; события нет —
  /// строка осиротела.
  /// Готовность к Ш-3 модели Signal: доля контактов со слоем 2 и счётчики
  /// наблюдения за сертификатами.
  ///
  /// 🔴 ЭТО ГЕЙТ. Ш-3 (сертификат отменяет «номер изменился») нельзя включать,
  /// не зная доли. Измерять её событиями журнала нельзя — он кольцевой; 12.08.2026
  /// это был третий неизмеримый гейт за день.
  static const String _prefsPendingPurchaseKey = 'pending_purchase_notice_v1';

  /// Отметка «магазин ждёт доплаты», если она есть и ещё не истекла.
  ///
  /// 🔴 Прод 24.07.2026: заказ из Малайзии на secretly_premium_yearly висел со
  /// статусом «Ожидается оплата». Премиум мы правильно не выдали (проверено и на
  /// сервере, и на клиенте), но покупателю не сказали НИЧЕГО — событие уходило в
  /// поток, на который никто не подписан. Человек не заплатил, потому что не
  /// знал, что от него ждут.
  Future<PendingPurchaseNotice?> pendingPurchaseNotice() async {
    try {
      final prefs = _prefs ?? await SharedPreferences.getInstance();
      final notice = PendingPurchaseNotice.tryDecode(
        prefs.getString(_prefsPendingPurchaseKey),
      );
      if (notice == null) return null;
      if (notice.isExpired(DateTime.now().millisecondsSinceEpoch)) {
        await prefs.remove(_prefsPendingPurchaseKey);
        return null;
      }
      return notice;
    } catch (_) {
      return null;
    }
  }

  Future<void> notePendingPurchase(String productId) async {
    final pid = productId.trim();
    if (pid.isEmpty) return;
    try {
      final prefs = _prefs ?? await SharedPreferences.getInstance();
      final existing = PendingPurchaseNotice.tryDecode(
        prefs.getString(_prefsPendingPurchaseKey),
      );
      // Тот же заказ повторно — отметку НЕ обновляем, иначе «показано один раз»
      // сбрасывается при каждом отчёте магазина и подсказка полезет снова.
      if (existing != null && existing.productId == pid) return;
      await prefs.setString(
        _prefsPendingPurchaseKey,
        PendingPurchaseNotice(
          productId: pid,
          startedAtMs: DateTime.now().millisecondsSinceEpoch,
          toastShown: false,
        ).encode(),
      );
      DiagLog.event('billing', 'pending_noted', {'product': pid});
    } catch (_) {}
  }

  Future<void> markPendingPurchaseToastShown() async {
    try {
      final prefs = _prefs ?? await SharedPreferences.getInstance();
      final existing = PendingPurchaseNotice.tryDecode(
        prefs.getString(_prefsPendingPurchaseKey),
      );
      if (existing == null || existing.toastShown) return;
      await prefs.setString(
        _prefsPendingPurchaseKey,
        existing.markToastShown().encode(),
      );
    } catch (_) {}
  }

  Future<void> clearPendingPurchaseNotice(String productId) async {
    try {
      final prefs = _prefs ?? await SharedPreferences.getInstance();
      final existing = PendingPurchaseNotice.tryDecode(
        prefs.getString(_prefsPendingPurchaseKey),
      );
      if (existing == null) return;
      final pid = productId.trim();
      if (pid.isNotEmpty && existing.productId != pid) return;
      await prefs.remove(_prefsPendingPurchaseKey);
      DiagLog.event('billing', 'pending_cleared', {'product': existing.productId});
    } catch (_) {}
  }

  /// Момент окончания запуска. Нужен, чтобы измерить разрыв до первого ответа
  /// насоса: в поле он оказался пять секунд, и всё это время приглашение звонка
  /// лежало в ящике.
  int _startupReadyAtMs = 0;
  int get startupReadyAtMs => _startupReadyAtMs;

  Future<String> accountIdentityReadinessSummary() async {
    final db = _db;
    if (db == null) return 'account_identity: (нет базы)';
    try {
      final r = await db.accountIdentityReadinessStats();
      final ok = await db.localKvCounterGet(AppDb.kvAcctCertOk);
      final bad = await db.localKvCounterGet(AppDb.kvAcctCertBad);
      final absent = await db.localKvCounterGet(AppDb.kvAcctCertAbsent);
      final changed = await db.localKvCounterGet(AppDb.kvAcctKeyChanged);
      final share = r.contacts == 0
          ? '—'
          : '${(100 * r.pinned / r.contacts).round()}%';
      return 'account_identity: со слоем 2 ${r.pinned} из ${r.contacts} '
          'контактов ($share) · сертификат ок=$ok плох=$bad нет=$absent · '
          'ключ сменился=$changed';
    } catch (_) {
      return 'account_identity: (ошибка чтения)';
    }
  }

  static String _ageLabel(int ms) {
    final minutes = ms ~/ 60000;
    if (minutes < 60) return '$minutes мин назад';
    final hours = minutes ~/ 60;
    if (hours < 48) return '$hours ч назад';
    return '${hours ~/ 24} дн назад';
  }

  Future<String> outboxFailedSummary() async {
    final db = _db;
    if (db == null) return 'outbox_failed: (нет базы)';
    try {
      final rows = await db.outboxFailedWithEventState(limit: 30);
      return formatOutboxFailedSummary(
        rows,
        nowMs: DateTime.now().millisecondsSinceEpoch,
      );
    } catch (_) {
      return 'outbox_failed: (ошибка чтения)';
    }
  }

  /// Разбор строк неудачной очереди в строку отчёта.
  ///
  /// Вынесено из [outboxFailedSummary] чистой функцией ради одного:
  /// сторожевой тест обязан уметь проверить, что служебный конверт не выдают
  /// за потерянное сообщение, — а поднимать ради этого базу и контроллер
  /// значит не написать такой тест вовсе.
  @visibleForTesting
  static String formatOutboxFailedSummary(
    List<Map<String, Object?>> rows, {
    required int nowMs,
  }) {
    if (rows.isEmpty) return 'outbox_failed: 0';
    // 🔴 СЛУЖЕБНЫЙ КОНВЕРТ — НЕ ПОТЕРЯННОЕ СООБЩЕНИЕ (26.08.2026, MSG-02).
    //
    // Пинги сессии (`_dispatchSessionResetPing`,
    // `_scheduleSessionConfirmPing`) кладутся в очередь с `eventIdRef: null` и
    // сроком жизни в час: собеседник офлайн дольше — конверт истекает с
    // `ttl_expired`, попытки кончились — с `retry_exhausted`. Это норма.
    //
    // Раньше они шли в общий счёт, и строка `failed: 4` читалась как «четыре
    // сообщения не дошли». На разбор такой строки в поле ушёл час — при том
    // что ответ в ней уже был, записанный словами «без события».
    //
    // Различает `event_id_ref`, а НЕ отсутствие события: пустая ссылка значит
    // «сообщения и не было», а НЕПУСТАЯ ссылка на исчезнувшее событие —
    // осиротевшая строка, и вот она как раз тревожна.
    var service = 0;
    var delivered = 0, stillSent = 0, orphan = 0, other = 0;
    final errors = <String, int>{};
    for (final r in rows) {
      final ref = ((r['event_id_ref'] as String?) ?? '').trim();
      final st = ((r['event_state'] as String?) ?? '').trim();
      if (ref.isEmpty) {
        service++;
      } else if (st.isEmpty) {
        orphan++;
      } else if (st == 'delivered' || st == 'read') {
        delivered++;
      } else if (st == 'sent') {
        stillSent++;
      } else {
        other++;
      }
      final e = ((r['last_error_code'] as String?) ?? '—').trim();
      errors[e] = (errors[e] ?? 0) + 1;
    }
    final err = errors.entries.map((e) => '${e.key}×${e.value}').join(', ');

    // 🔴 ВОЗРАСТ РЕШАЕТ, ЧТО ЭТО ЗА ПРОБЛЕМА. Без него сводка не отличает
    // давний след от того, что ломается прямо сейчас: тридцать записей
    // выглядят одинаково тревожно и в том, и в другом случае. Запрос берёт
    // САМЫЕ СВЕЖИЕ (`ORDER BY created_at_ms DESC`), поэтому дата первой
    // строки — это дата последнего сбоя.
    final ages = rows
        .map((r) => (r['created_at_ms'] as num?)?.toInt() ?? 0)
        .where((v) => v > 0)
        .toList()
      ..sort();
    var ageText = '';
    if (ages.isNotEmpty) {
      final day = 24 * 60 * 60 * 1000;
      final freshest = ages.last;
      final oldest = ages.first;
      final last7 = ages.where((v) => nowMs - v <= 7 * day).length;
      final last24h = ages.where((v) => nowMs - v <= day).length;
      ageText =
          ' · возраст: самое свежее ${_ageLabel(nowMs - freshest)}, '
          'самое старое ${_ageLabel(nowMs - oldest)}'
          ' · за сутки $last24h, за 7 дней $last7';
    }

    // `limit` в запросе — предел выборки, а не число неудач: полное число
    // стоит строкой выше (`failed:`). Говорим об этом прямо, чтобы цифру не
    // читали как «всего тридцать».
    // `limit` в запросе — предел выборки, а не число неудач: полное число
    // стоит строкой выше (`failed:`). Говорим об этом прямо, чтобы цифру не
    // читали как «всего тридцать».
    final capped = rows.length >= 30 ? ' (показаны 30 самых свежих)' : '';

    // Тревожной строка становится ТОЛЬКО когда пострадали сообщения. Пока их
    // ноль — короткая форма, чтобы служебный трафик не изображал беду.
    final messages = rows.length - service;
    final head = messages == 0
        ? '(сообщений 0 · служебных $service)'
        : '(🔴 сообщений $messages: дошло другим конвертом $delivered · '
              'доставки не видели $stillSent · осиротело $orphan · '
              'прочее $other · служебных $service)';
    return 'outbox_failed: ${rows.length}$capped $head [$err]$ageText';
  }

  Future<String> safetyNumberNoticeSummary() async {
    final db = _db;
    if (db == null) return 'safety_number_notices: (нет базы)';
    final now = DateTime.now().millisecondsSinceEpoch;
    try {
      final w = await db.safetyNumberNoticeStats(
        windowMs: 7 * 24 * 60 * 60 * 1000,
        nowMs: now,
      );
      final m = await db.safetyNumberNoticeStats(
        windowMs: 30 * 24 * 60 * 60 * 1000,
        nowMs: now,
      );
      return 'safety_number_notices: 7д=${w.total} (пиров ${w.peers}) · '
          '30д=${m.total} (пиров ${m.peers})';
    } catch (e) {
      return 'safety_number_notices: (ошибка чтения)';
    }
  }

  Future<void> _insertSafetyNumberChangedNotice(String peerProfileId) async {
    final db = _db;
    final did = _deviceId?.trim();
    final crypto = _crypto;
    if (db == null || did == null || did.isEmpty || crypto == null) return;
    final pid = peerProfileId.trim();
    if (pid.isEmpty || pid.startsWith('group:') || pid.startsWith('dev:')) {
      return;
    }
    final now = DateTime.now().millisecondsSinceEpoch;
    final localEventId = 'local:safetynum:$pid:${now ~/ (10 * 60000)}';
    try {
      if (await db.eventGet(localEventId) != null) return;
      final text = _localizedText(
        ru: '🔒 Номер безопасности этого контакта изменился — вероятно, он переустановил приложение или сменил устройство. Если сомневаетесь, подтвердите контакт заново.',
        en: "🔒 This contact's safety number changed — they likely reinstalled the app or switched devices. If unsure, re-verify the contact.",
        uk: '🔒 Номер безпеки цього контакту змінився — імовірно, він перевстановив застосунок або змінив пристрій. Якщо сумніваєтесь, підтвердьте контакт знову.',
        es: '🔒 El número de seguridad de este contacto cambió: probablemente reinstaló la app o cambió de dispositivo. Si tienes dudas, vuelve a verificarlo.',
        pt: '🔒 O número de segurança deste contacto mudou — provavelmente reinstalou a app ou mudou de dispositivo. Em caso de dúvida, verifique novamente.',
        ptBr:
            '🔒 O número de segurança deste contato mudou — provavelmente reinstalou o app ou trocou de dispositivo. Na dúvida, verifique novamente.',
        fr: "🔒 Le numéro de sécurité de ce contact a changé — il a probablement réinstallé l'app ou changé d'appareil. En cas de doute, revérifiez le contact.",
        de: '🔒 Die Sicherheitsnummer dieses Kontakts hat sich geändert – wahrscheinlich App neu installiert oder Gerät gewechselt. Im Zweifel den Kontakt neu verifizieren.',
      );
      final ev = SystemEventV1(eventId: _uuid.v4(), text: text);
      final payload = E2ePayloadV1(
        senderDeviceId: did,
        createdAtMs: now,
        events: <E2eEventV1>[ev],
      );
      final localCipher = base64Encode(await crypto.encrypt(payload.encode()));
      await db.convoEnsure1to1(peerProfileId: pid);
      await db.insertEvent(
        eventId: localEventId,
        convoId: pid,
        type: 'sys',
        senderDeviceId: did,
        ciphertextB64: localCipher,
        createdAtMs: now,
        localState: 'sent',
        payloadEventId: ev.eventId,
      );
      await db.convoTouch(convoId: pid, atMs: now);
      _changed.add(null);
    } catch (_) {
      // best-effort — a notice must never break device refresh
    }
  }

  /// Sprint 2 C8: read by the UI to render the «не удалось обновить
  /// устройства собеседника» banner. Returns the age of the LAST
  /// successful `refreshContactDevices` for the given peer profile,
  /// or `null` if we have never successfully refreshed.
  Duration? contactDevicesRefreshAgeFor(String peerProfileId) {
    final at = _lastContactDevicesRefreshOkAtMs[peerProfileId];
    if (at == null || at == 0) return null;
    return Duration(milliseconds: DateTime.now().millisecondsSinceEpoch - at);
  }

  /// Sprint 2 C8: convenience predicate for «show stale-bundle banner».
  /// Returns true iff we have successfully refreshed at least once
  /// (so we're past the initial pairing window) and the last successful
  /// refresh is older than 24 h. Returning `false` for never-refreshed
  /// peers keeps the banner from flashing during onboarding.
  bool isPeerBundleStale(String peerProfileId) {
    final age = contactDevicesRefreshAgeFor(peerProfileId);
    if (age == null) return false;
    return age.inHours >= 24;
  }

  // ============================================================
  // Sprint 2 C4: outbox-stuck watchdog
  // ============================================================
  //
  // Periodically scans for outbox rows that have been sitting in
  // `pending`/`sending` for >5 min and surfaces them to the UI as
  // «message stuck». After 30 min we additionally fire a best-effort
  // ratchet recovery: refresh the peer's bundle (forces a key-server
  // round-trip), then schedule a session-reset ping for each stuck
  // destination device so the peer rebuilds its side of the ratchet.

  /// Surface threshold — rows older than this become visible to the UI.
  static const int _outboxStuckWarnThresholdMs = 5 * 60 * 1000; // 5 min

  /// Recovery threshold — rows older than this also trigger an
  /// automatic refreshContactDevices + session-reset ping per peer.
  static const int _outboxStuckRecoveryThresholdMs = 30 * 60 * 1000; // 30 min

  /// Throttle for the watchdog itself — at most once per minute.
  static const int _outboxWatchdogMinIntervalMs = 60 * 1000;
  int _outboxWatchdogLastTickAtMs = 0;

  /// S1 — re-arm an outbox row stuck in 'pending' this long (sender was frozen
  /// right after enqueue). Comfortably past a normal send (seconds) so it never
  /// races an in-flight pump, but well below the 5-min surface threshold.
  static const int _outboxPendingRekickThresholdMs = 90 * 1000; // 90 s

  /// Throttle for per-peer recovery so a row stuck at 31 min doesn't
  /// trigger a refresh tick on every watchdog cycle.
  final Map<String, int> _outboxStuckLastRecoveryAtMsByPeer = <String, int>{};
  static const int _outboxStuckRecoveryCooldownMs = 10 * 60 * 1000;

  /// Snapshot of «stuck» peer profile IDs and the per-peer count of
  /// rows still in pending/sending. Read by the UI to render badges /
  /// banners. Re-emitted via `_changed` whenever the set actually
  /// changes (no churn on identical re-snapshots).
  Map<String, int> _stuckOutboxCountByPeer = <String, int>{};

  /// Public read-only view for the UI.
  Map<String, int> get stuckOutboxCountByPeer =>
      Map<String, int>.unmodifiable(_stuckOutboxCountByPeer);

  /// `true` if there is at least one «stuck» outbox row anywhere.
  /// Convenience for top-level shell banners.
  bool get hasStuckOutbox => _stuckOutboxCountByPeer.isNotEmpty;

  /// Sprint 2 C4 — one pass of the outbox-stuck watchdog. Designed to
  /// run from the existing 3-second service watchdog so we don't add
  /// another timer. Self-throttled to once per minute.
  Future<void> _outboxStuckWatchdogTick() async {
    final db = _db;
    if (db == null) return;
    final now = DateTime.now().millisecondsSinceEpoch;
    if (now - _outboxWatchdogLastTickAtMs < _outboxWatchdogMinIntervalMs) {
      return;
    }
    _outboxWatchdogLastTickAtMs = now;

    // S1 (2026-06-29): re-arm outbox rows stuck in 'pending' that the normal
    // lease would skip (pushed to a future retry / left locked) — the
    // sender-was-asleep-at-send-time case. Cheap; only matches genuinely-stuck
    // rows, so a no-op in the common case. Pump immediately if any were freed.
    try {
      final rekicked = await db.outboxRekickStuckPending(
        nowMs: now,
        stuckBeforeMs: now - _outboxPendingRekickThresholdMs,
      );
      if (rekicked > 0) {
        DiagLog.event('outbox', 'pending_rekick', {'rows': rekicked});
        _kickRelayOutbox();
      }
    } catch (_) {
      // best-effort backstop; never let it abort the watchdog
    }

    final List<Map<String, Object?>> stuckRows;
    try {
      stuckRows = await db.outboxListStuck(
        olderThanMs: now - _outboxStuckWarnThresholdMs,
        limit: 200,
      );
    } catch (_) {
      return;
    }

    final newCountByPeer = <String, int>{};
    final recoveryNeededByPeer = <String, List<String>>{};
    for (final row in stuckRows) {
      final convoId = ((row['convo_id'] as String?) ?? '').trim();
      final isDirectPeer =
          convoId.isNotEmpty &&
          !convoId.startsWith('dev:') &&
          !convoId.startsWith('group:');
      if (isDirectPeer) {
        // 1:1 peer chats: convo_id IS the peer profile id. Count for the stuck
        // snapshot UI exactly as before.
        newCountByPeer[convoId] = (newCountByPeer[convoId] ?? 0) + 1;
      }
      final createdAtMs = (row['created_at_ms'] as num?)?.toInt() ?? now;
      if (now - createdAtMs < _outboxStuckRecoveryThresholdMs) continue;
      final toDeviceId = ((row['to_device_id'] as String?) ?? '').trim();
      if (toDeviceId.isEmpty) continue;

      if (isDirectPeer) {
        recoveryNeededByPeer
            .putIfAbsent(convoId, () => <String>[])
            .add(toDeviceId);
        continue;
      }
      if (convoId.startsWith('dev:')) {
        // Device-targeted self-fanout to our OWN devices — a session-reset ping
        // to ourselves is pointless, so leave these alone (unchanged).
        continue;
      }
      // A3: group / no-convo stuck rows. Group `sendControlMessage` stores a
      // NULL convo_id, so the old code skipped these — and a GROUP member whose
      // ratchet desynced looped on the SAME undecryptable ciphertext forever:
      // `outboxRekickStuckPending` only re-sends the stored wire (never
      // re-encrypts), and the healing (bundle refresh + session-reset ping) that
      // fixes 1:1 never ran for them. Attribute the stuck destination device
      // back to its owner (contact_devices holds every send target) and route it
      // through the SAME device-level recovery. If the owner can't be resolved,
      // still rebuild the ratchet at the device level — that alone unblocks a
      // desynced member; the reset ping is self-debounced per device.
      final selfPid = (_profileId ?? '').trim();
      var resolvedPeer =
          (await db.contactProfileForDeviceId(toDeviceId))?.trim() ?? '';
      if (resolvedPeer.isEmpty) {
        resolvedPeer = (await db.deviceProfileCached(toDeviceId))?.trim() ?? '';
      }
      if (resolvedPeer == selfPid) continue; // own device — nothing to reset
      if (resolvedPeer.isNotEmpty) {
        recoveryNeededByPeer
            .putIfAbsent(resolvedPeer, () => <String>[])
            .add(toDeviceId);
      } else {
        _scheduleSessionResetPing(toDeviceId, _resetCauseOutboxStuck);
      }
    }

    // Emit change only when the snapshot actually differs — avoids
    // unnecessary UI rebuilds when nothing moved.
    if (!_mapsEqualIntInt(_stuckOutboxCountByPeer, newCountByPeer)) {
      _stuckOutboxCountByPeer = newCountByPeer;
      DiagLog.event('outbox', 'stuck_snapshot', {
        'peers': newCountByPeer.length,
        'rows': newCountByPeer.values.fold<int>(0, (a, b) => a + b),
      });
      _changed.add(null);
    }

    // Recovery dispatch: refresh bundle (force) + schedule reset ping
    // per stuck destination, debounced per peer.
    for (final entry in recoveryNeededByPeer.entries) {
      final peerProfileId = entry.key;
      final stuckDeviceIds = entry.value;
      final lastRecoveryAt =
          _outboxStuckLastRecoveryAtMsByPeer[peerProfileId] ?? 0;
      if (now - lastRecoveryAt < _outboxStuckRecoveryCooldownMs) {
        continue;
      }
      _outboxStuckLastRecoveryAtMsByPeer[peerProfileId] = now;
      DiagLog.event('outbox', 'stuck_recovery_dispatch', {
        'peer': DiagLog.pfx(peerProfileId),
        'devices': stuckDeviceIds.length,
      });
      unawaited(() async {
        try {
          await refreshContactDevices(peerProfileId);
        } catch (_) {
          // identity-key rotation throws — sessions already wiped in
          // `contactDeviceUpsert`; the reset pings below will rebuild.
        }
        for (final did in stuckDeviceIds.toSet()) {
          _scheduleSessionResetPing(did, _resetCauseOutboxStuck);
        }
      }());
    }
  }

  bool _mapsEqualIntInt(Map<String, int> a, Map<String, int> b) {
    if (a.length != b.length) return false;
    for (final entry in a.entries) {
      if (b[entry.key] != entry.value) return false;
    }
    return true;
  }

  /// Sprint 2 C1 — interval between proactive bundle re-verifications
  /// for active peers. The verification itself is cheap (one keys-server
  /// fetch + a local identity-key comparison inside `contactDeviceUpsert`).
  static const _bundleRevalidationIntervalMs = 24 * 60 * 60 * 1000; // 24 h

  /// Sprint 2 C1 — minimum spacing between watchdog ticks. The watchdog
  /// itself runs from `_pumpTimer` so this is a per-process throttle.
  static const _bundleRevalidationWatchdogMinIntervalMs = 60 * 1000; // 1 min
  int _bundleRevalidationLastTickAtMs = 0;

  /// 🔴 ЗВОНОК ИМЕЕТ ПРАВО ПРОЙТИ ПЕРВЫМ (24.08.2026).
  ///
  /// Бакет сервера ключей считается ПО IP: два устройства одного человека за
  /// домашним Wi-Fi делят его на двоих. Фоновая перепроверка бандлов ходит за
  /// ключами пачкой раз в минуту с КАЖДОГО устройства — и когда звонок в этот
  /// момент просит бандл, чтобы зашифровать ОТВЕТ, он получает 429 и звонящий
  /// остаётся слушать гудки в пустоту.
  ///
  /// Пока окно открыто, необязательная фоновая работа уступает: перепроверка
  /// бандлов — обслуживание, её можно отложить на минуту, звонок — нельзя.
  int _callPriorityUntilMs = 0;

  /// Открыть окно приоритета звонка. Зовётся из `CallManager` на КАЖДОМ шаге
  /// звонка (набор, входящий, принятие), поэтому окно короткое: звонок сам
  /// продлевает его, пока жив, и оно закрывается само, если звонок оборвался.
  void markCallPriorityWindow({int ms = 60 * 1000}) {
    final until = DateTime.now().millisecondsSinceEpoch + ms;
    if (until > _callPriorityUntilMs) _callPriorityUntilMs = until;
  }

  /// Идёт ли сейчас звонок (в пределах открытого окна приоритета).
  bool get callPriorityActive =>
      DateTime.now().millisecondsSinceEpoch < _callPriorityUntilMs;

  /// Sprint 2 C1: walk the recent / active conversations, and for every
  /// 1-to-1 peer whose last successful bundle refresh is older than
  /// [_bundleRevalidationIntervalMs], silently kick off a refresh. The
  /// refresh itself uses the existing identity-key change detection in
  /// `AppDb.contactDeviceUpsert` to wipe ratchet state on rotation —
  /// see Restore Safety Contract INV-6.
  ///
  /// Designed to be cheap and best-effort. Errors are swallowed; the
  /// next watchdog tick will retry.
  Future<void> _bundleRevalidationWatchdogTick() async {
    final db = _db;
    if (db == null) return;
    final now = DateTime.now().millisecondsSinceEpoch;
    if (now - _bundleRevalidationLastTickAtMs <
        _bundleRevalidationWatchdogMinIntervalMs) {
      return;
    }
    // Звонок важнее обслуживания: пока он идёт, не тратим бакет сервера ключей
    // на фоновую перепроверку — иначе ответ на звонок нечем будет зашифровать.
    // Тик не отмечаем выполненным, чтобы перепроверка прошла сразу после.
    if (callPriorityActive) {
      DiagLog.event('peer', 'bundle_reverify_yield_to_call', const {});
      return;
    }
    _bundleRevalidationLastTickAtMs = now;

    List<Map<String, Object?>> convos;
    try {
      convos = await db.convoList();
    } catch (_) {
      return;
    }
    if (convos.isEmpty) return;

    var dispatched = 0;
    const maxPerTick = 4; // throttle keys-server load
    for (final c in convos) {
      if (dispatched >= maxPerTick) break;
      final convoId = (c['convo_id'] as String? ?? '').trim();
      // Skip groups and device-channels; C1 only applies to 1:1 peers.
      if (convoId.isEmpty ||
          convoId.startsWith('group:') ||
          convoId.startsWith('dev:')) {
        continue;
      }
      final lastOk = _lastContactDevicesRefreshOkAtMs[convoId] ?? 0;
      if ((now - lastOk) < _bundleRevalidationIntervalMs) {
        continue;
      }
      dispatched++;
      DiagLog.event('peer', 'bundle_reverify_dispatch', {
        'peer': DiagLog.pfx(convoId),
        'last_ok_age_ms': lastOk == 0 ? -1 : (now - lastOk),
      });
      unawaited(() async {
        try {
          await refreshContactDevices(convoId);
        } catch (e) {
          // Identity-key change throws StateError — that path already
          // wiped sessions inside `contactDeviceUpsert`. Schedule a
          // reset ping to the affected devices so the peer rebuilds
          // its side of the ratchet too.
          DiagLog.event('peer', 'bundle_reverify_fail', {
            'peer': DiagLog.pfx(convoId),
            'reason': _classifyShortReason(e),
            // Diagnostic (2026-06-19): 'other' hides the real cause of a
            // bundle fetch failure that blocks session recovery — capture a
            // short sanitized error so the field log is actionable.
            'err': e
                .toString()
                .replaceAll(RegExp(r'\s+'), '_')
                .replaceAll("'", ''),
          });
          try {
            final rows = await db.contactDevicesList(convoId);
            for (final row in rows) {
              final did = (row['device_id'] as String? ?? '').trim();
              if (did.isNotEmpty) {
                _scheduleSessionResetPing(did, _resetCauseBundleRevalidation);
              }
            }
          } catch (_) {
            // Best-effort.
          }
        }
      }());
    }
  }

  bool _isMissingCurrentKeysDeviceError(Object error) {
    final message = error.toString().toLowerCase();
    return message.contains('unknown requester device') ||
        message.contains('bad requester device_id') ||
        message.contains('missing x-secretly-device-id') ||
        message.contains('requester device missing identity key') ||
        message.contains('bad signature');
  }

  Future<List<KeysDeviceStatus>> loadRecipientDeviceStatuses(
    String peerProfileId,
  ) {
    return _listDeviceStatusesAuthed(peerProfileId);
  }

  Future<bool> repairMissingCurrentDeviceKeysRegistration() async {
    final prefs = _prefs;
    final keys = _keys;
    if (prefs == null || keys == null || _transportBlocked) {
      return false;
    }

    await _ensureKeysSetup(
      prefs: prefs,
      keys: keys,
      allowServerProfileAutoCreate: !requiresDesktopProfileSelection,
      allowMissingCurrentDeviceRepair: true,
    ).timeout(
      const Duration(seconds: 15),
      onTimeout: () => throw TimeoutException(
        'keys setup timeout during current device repair',
      ),
    );

    _keysOnline = true;
    return true;
  }

  // Re-entrancy + tight-loop guards for the send-path identity self-heal.
  bool _keysSendIdentityRepairInFlight = false;
  int _lastKeysSendIdentityRepairAtMs = 0;
  static const int _kKeysSendIdentityRepairCooldownMs = 20000;

  /// Runs [repairMissingCurrentDeviceKeysRegistration] (which rotates device_id
  /// when the keys server reports a pinned-identity mismatch) at most once per
  /// cooldown window, so a send that hits a "bad signature" desync heals instead
  /// of storming fetch_bundle. Guarded against re-entrancy and rapid loops; the
  /// repair path does not call back into _fetchBundleAuthed, so it cannot loop.
  Future<bool> _repairKeysIdentityForSendOnce() async {
    if (_keysSendIdentityRepairInFlight) return false;
    final nowMs = DateTime.now().millisecondsSinceEpoch;
    if (nowMs - _lastKeysSendIdentityRepairAtMs <
        _kKeysSendIdentityRepairCooldownMs) {
      return false;
    }
    _keysSendIdentityRepairInFlight = true;
    _lastKeysSendIdentityRepairAtMs = nowMs;
    try {
      return await repairMissingCurrentDeviceKeysRegistration();
    } catch (_) {
      return false;
    } finally {
      _keysSendIdentityRepairInFlight = false;
    }
  }

  Future<void> _refreshContactDevicesForVerification(
    String peerProfileId,
  ) async {
    final now = DateTime.now().millisecondsSinceEpoch;
    final lastRefreshAt = _contactVerifyRefreshAtMs[peerProfileId] ?? 0;
    if (now - lastRefreshAt < _verifyRefreshThrottleMs) {
      return;
    }
    _contactVerifyRefreshAtMs[peerProfileId] = now;
    try {
      await refreshContactDevices(peerProfileId);
    } catch (_) {
      // ignore
    }
  }

  // Step 3: throttle for the event-driven "learn the peer's device on first
  // sight" refresh (at most once per peer per 30 s).
  final Map<String, int> _peerDeviceRefreshOnNewAtMs = <String, int>{};

  // ============================================================
  // FIX E — proactive, silence-driven delivery recovery.
  //
  // Upstream of the reactive quarantine recovery (FIX A/D). Those only arm
  // when a wire reaches MY mailbox and fails to decrypt. The real break is
  // that the SENDER keeps targeting a stale/dead device_id for a SILENT peer,
  // so the wire lands where the peer never reads — nothing arrives, nothing
  // quarantines, and the reactive heal never fires. This pass force-refreshes
  // the peer's device list (fresh keys-server fetch) and reset-pings every
  // resolved device whenever a 1:1 peer we have SENT to has gone silent past
  // [SilenceRecoveryPlanner.defaultSilenceThresholdMs]. Decision logic lives in
  // the pure [SilenceRecoveryPlanner]; everything here is best-effort and
  // try-guarded so it never throws into a timer / resume / the send path.
  // ============================================================

  /// In-memory wall-clock ms of the last successful inbound from each peer
  /// profile. Seeded from `profile_meta.last_seen_at_ms` on first use and kept
  /// hot on every decrypted inbound. Read by the silence sweep.
  final Map<String, int> _peerLastInboundAtMs = <String, int>{};

  /// In-memory wall-clock ms of our last PROACTIVE silence-recovery attempt per
  /// peer profile (throttle ladder — [SilenceRecoveryPlanner.shouldRecover]).
  final Map<String, int> _peerSilenceRecoveryAtMs = <String, int>{};

  /// Per-process throttle for the foreground silence sweep itself. The sweep
  /// piggy-backs on the 90 s quarantine-recovery timer + resume + pre-send, so
  /// this just stops back-to-back triggers (resume right after a tick) from
  /// re-walking every conversation.
  static const int _silenceSweepMinIntervalMs = 60 * 1000;
  int _silenceSweepLastTickAtMs = 0;

  /// Cap on peers proactively recovered per sweep pass — bounds keys-server
  /// load exactly like the C1 bundle-revalidation watchdog.
  static const int _silenceSweepMaxPerTick = 4;

  /// After a successful inbound, if our last successful `refreshContactDevices`
  /// for this peer is older than this, fire ONE throttled refresh even when the
  /// sender device is already known (the reactive on-new-sender refresh only
  /// fires for an UNKNOWN device — this catches a peer that ADDED a device or
  /// rotated a signed prekey while a known device kept talking to us).
  static const int _inboundStaleRefreshThresholdMs = 10 * 60 * 1000;

  /// Record that we just received from [peerProfileId] (hot cache for the
  /// silence sweep) and, if our cached device bundle for them is stale, kick a
  /// single throttled `refreshContactDevices`. Best-effort; never throws.
  void _noteInboundFromPeerAndMaybeRefresh(String peerProfileId) {
    if (_backgroundInboundMode) return; // network refresh; foreground does it
    final pid = peerProfileId.trim();
    if (pid.isEmpty) return;
    if (!SilenceRecoveryPlanner.isEligibleConvoId(pid)) return;
    final now = DateTime.now().millisecondsSinceEpoch;
    _peerLastInboundAtMs[pid] = now;
    // Requirement #3: throttled refresh-on-stale-inbound, independent of whether
    // the sender device is new. Reuses the existing per-peer success stamp +
    // 30 s on-new throttle so we never spam the keys server.
    try {
      final lastOk = _lastContactDevicesRefreshOkAtMs[pid] ?? 0;
      if (lastOk != 0 && (now - lastOk) < _inboundStaleRefreshThresholdMs) {
        return;
      }
      final lastOnNew = _peerDeviceRefreshOnNewAtMs[pid] ?? 0;
      if (lastOnNew != 0 && (now - lastOnNew) < 30000) {
        return;
      }
      _peerDeviceRefreshOnNewAtMs[pid] = now;
      DiagLog.event('peer', 'inbound_stale_refresh', {
        'peer': DiagLog.pfx(pid),
        'last_ok_age_ms': lastOk == 0 ? -1 : (now - lastOk),
      });
      // Drop the in-memory send cache so the next send re-resolves devices.
      _recipientDevicesCacheByProfileId.remove(pid);
      unawaited(refreshContactDevices(pid).catchError((_) {}));
    } catch (_) {
      // best-effort
    }
  }

  /// Read the most recent inbound timestamp for [peerProfileId], preferring the
  /// hot in-memory value and falling back to the durable
  /// `profile_meta.last_seen_at_ms` (updated on every inbound + presence fetch).
  Future<int?> _resolveLastInboundAtMs(String peerProfileId) async {
    final hot = _peerLastInboundAtMs[peerProfileId];
    if (hot != null && hot > 0) return hot;
    final db = _db;
    if (db == null) return null;
    try {
      final meta = await db.profileMetaGet(peerProfileId);
      final seen = (meta?['last_seen_at_ms'] as num?)?.toInt();
      if (seen != null && seen > 0) {
        _peerLastInboundAtMs[peerProfileId] = seen;
        return seen;
      }
    } catch (_) {
      // best-effort
    }
    return null;
  }

  /// Run one proactive silence-driven recovery for a single peer: bypass the
  /// in-memory + DB caches with a fresh keys-server fetch, then session-reset
  /// ping EACH currently-resolved device. Throttle is the caller's
  /// responsibility (the planner). Best-effort; never throws.
  Future<void> _runSilenceRecoveryForPeer(String peerProfileId) async {
    final db = _db;
    if (db == null) return;
    final pid = peerProfileId.trim();
    if (!SilenceRecoveryPlanner.isEligibleConvoId(pid)) return;
    final now = DateTime.now().millisecondsSinceEpoch;
    _peerSilenceRecoveryAtMs[pid] = now;
    DiagLog.event('peer', 'silence_recovery_dispatch', {
      'peer': DiagLog.pfx(pid),
    });
    // (a) Forced fresh keys-server fetch. Dropping the in-memory cache makes the
    //     next send re-resolve; `refreshContactDevices` itself always hits the
    //     keys server (never the DB cache) and rewrites `contact_devices`.
    _recipientDevicesCacheByProfileId.remove(pid);
    try {
      await refreshContactDevices(pid);
    } catch (_) {
      // Identity-key rotation throws (sessions already wiped in
      // contactDeviceUpsert); the reset pings below rebuild the ratchet.
    }
    // (b) Session-reset ping EACH currently-resolved device of the peer. After
    //     the refresh above, `contact_devices` holds the peer's CURRENT set, so
    //     this re-handshakes the live device(s) and abandons the dead one.
    try {
      final rows = await db.contactDevicesList(pid);
      final all = <String>[
        for (final row in rows)
          if ((((row['device_id'] as String?) ?? '').trim()).isNotEmpty)
            ((row['device_id'] as String?) ?? '').trim(),
      ];
      // 🔴 «ABANDONS THE DEAD ONE» ВЫШЕ — ЭТО БЫЛО НАМЕРЕНИЕ, А НЕ ПОВЕДЕНИЕ
      // (15.08.2026, замер сборки 523).
      //
      // Сервер ключей продолжает перечислять копию, оставшуюся от
      // переустановки, поэтому «текущий набор устройств» включал мертвеца, и
      // этот заход слал ему лечение КАЖДЫЕ ЧЕТЫРЕ С ПОЛОВИНОЙ МИНУТЫ. Поле:
      // три подряд `reset_ping_enqueued peer_dev=7d1e2be2` в 17:28, 17:33,
      // 17:37 — при том, что устройство молчит пятые сутки и в его ящике на
      // реле 143 конверта, которых никто не заберёт.
      //
      // Отсев берёт данные РЕЛЕ (`fetchActiveDevices` заодно наполняет кэш
      // живости — без него проверка ниже слепа и всегда отвечает «лечим»).
      final narrowed = await _healTargetsForSilenceRecovery(
        peerProfileId: pid,
        deviceIds: all,
      );
      for (final did in narrowed) {
        _forceSessionResetPing(did, _resetCausePeerSilent);
      }
    } catch (_) {
      // best-effort — a later trigger retries (throttle permitting).
    }
  }

  /// Кого из устройств собеседника имеет смысл лечить этим заходом.
  ///
  /// 🔴 НИКОГДА не возвращает пустой список: если по данным реле «мертвы» все,
  /// лечим всех, как раньше. Пустой ответ означал бы, что собеседник, уехавший
  /// в отпуск, теряет починку сессии — а это потеря переписки, а не экономия
  /// запросов.
  Future<List<String>> _healTargetsForSilenceRecovery({
    required String peerProfileId,
    required List<String> deviceIds,
  }) async {
    if (deviceIds.length < 2) return deviceIds;
    try {
      // Побочный эффект здесь — главный: запрос наполняет кэш живости, по
      // которому судит проверка. Сам возвращённый набор нам не нужен.
      await _applyRelayActiveDevicesFilter(
        bundleDeviceIds: deviceIds,
        peerProfileId: peerProfileId,
      );
    } catch (_) {
      // Нет данных — судить не по чему, лечим всех.
      return deviceIds;
    }
    final alive = deviceIds
        .where((did) => !_healTargetLooksUnreachable(did))
        .toList(growable: false);
    if (alive.isEmpty || alive.length == deviceIds.length) return deviceIds;
    DiagLog.event('peer', 'heal_targets_narrowed', {
      'peer': DiagLog.pfx(peerProfileId),
      'from': deviceIds.length,
      'to': alive.length,
    });
    return alive;
  }

  /// Decide + run proactive silence recovery for one peer if eligible.
  /// `hasSentToPeer` / `lastOutboundAtMs` are resolved from the DB. Returns true
  /// iff a recovery was dispatched (so the sweep can honour its per-tick cap).
  Future<bool> _maybeRunSilenceRecoveryForPeer(
    String peerProfileId, {
    required int nowMs,
  }) async {
    final db = _db;
    if (db == null) return false;
    final pid = peerProfileId.trim();
    if (!SilenceRecoveryPlanner.isEligibleConvoId(pid)) return false;
    try {
      final selfDid = (_deviceId ?? '').trim();
      int? lastOutboundAtMs;
      var hasSent = false;
      if (selfDid.isNotEmpty) {
        lastOutboundAtMs = await db.latestOwnEventAtMsForConvo(
          convoId: pid,
          senderDeviceId: selfDid,
        );
        hasSent = lastOutboundAtMs != null && lastOutboundAtMs > 0;
      }
      // A stuck/unacked outbound also counts as "have sent" even if the local
      // event row is absent (e.g. send queued before the local echo persisted).
      if (!hasSent && (_stuckOutboxCountByPeer[pid] ?? 0) > 0) {
        hasSent = true;
      }
      final lastInboundAtMs = await _resolveLastInboundAtMs(pid);
      final fire = SilenceRecoveryPlanner.shouldRecover(
        hasSentToPeer: hasSent,
        lastInboundAtMs: lastInboundAtMs,
        lastOutboundAtMs: lastOutboundAtMs,
        lastRecoveryAttemptAtMs: _peerSilenceRecoveryAtMs[pid],
        nowMs: nowMs,
        // Don't blame the peer for silence caused by our own dead relay link.
        selfRelayReachable: _relayOnline || _relayHttpReachable,
      );
      if (!fire) return false;
      await _runSilenceRecoveryForPeer(pid);
      return true;
    } catch (_) {
      // best-effort — never throw into the sweep / resume / pre-send path.
      return false;
    }
  }

  /// Foreground sweep (requirement #1): walk active 1:1 conversations and run
  /// proactive silence recovery for any silent peer we have sent to. NOT gated
  /// on quarantine being non-empty — it runs unconditionally on each pass. Self-
  /// throttled and capped so keys-server load stays negligible. Never throws.
  Future<void> _runSilenceRecoverySweep() async {
    final db = _db;
    if (db == null) return;
    final now = DateTime.now().millisecondsSinceEpoch;
    if (now - _silenceSweepLastTickAtMs < _silenceSweepMinIntervalMs) {
      return;
    }
    _silenceSweepLastTickAtMs = now;
    List<Map<String, Object?>> convos;
    try {
      convos = await db.convoList();
    } catch (_) {
      return;
    }
    if (convos.isEmpty) return;
    var dispatched = 0;
    for (final c in convos) {
      if (dispatched >= _silenceSweepMaxPerTick) break;
      final convoId = (c['convo_id'] as String? ?? '').trim();
      if (!SilenceRecoveryPlanner.isEligibleConvoId(convoId)) continue;
      final fired = await _maybeRunSilenceRecoveryForPeer(convoId, nowMs: now);
      if (fired) dispatched++;
    }
    if (dispatched > 0) {
      DiagLog.event('peer', 'silence_recovery_sweep', {
        'recovered_peers': dispatched,
      });
    }
  }

  /// Cheap pre-send hook (requirement #2): when sending a 1:1 message to a peer
  /// that has gone silent since our last send, kick a proactive recovery BEFORE
  /// the wire goes out — so background-suspended Dart timers don't delay the
  /// heal. Fire-and-forget; never blocks or throws into the send path.
  void _maybeKickSilenceRecoveryBeforeSend(String peerProfileId) {
    final pid = peerProfileId.trim();
    if (!SilenceRecoveryPlanner.isEligibleConvoId(pid)) return;
    final now = DateTime.now().millisecondsSinceEpoch;
    unawaited(
      _maybeRunSilenceRecoveryForPeer(pid, nowMs: now).catchError((_) => false),
    );
  }

  /// When we receive a message from a peer device we have never targeted,
  /// refresh that peer's full device list from the keys server so our outbound
  /// fanout stops going to a stale/dead device (e.g. after the peer reinstalled
  /// or recreated their account). Best-effort, throttled, never throws.
  Future<void> _maybeRefreshPeerDevicesOnNewSenderDevice(
    String peerProfileId,
    String senderDeviceId,
  ) async {
    if (_backgroundInboundMode) return; // network refresh; foreground does it
    final db = _db;
    if (db == null) return;
    final pid = peerProfileId.trim();
    final sid = senderDeviceId.trim();
    if (pid.isEmpty || sid.isEmpty) return;
    if (pid.startsWith('group:') || pid.startsWith('dev:')) return;
    try {
      final rows = await db.contactDevicesList(pid);
      final known = rows.any(
        (r) => ((r['device_id'] as String?) ?? '').trim() == sid,
      );
      if (known) return; // already in our device list — nothing new to learn
      final now = DateTime.now().millisecondsSinceEpoch;
      final last = _peerDeviceRefreshOnNewAtMs[pid] ?? 0;
      if (now - last < 30000) return; // at most once per 30 s per peer
      _peerDeviceRefreshOnNewAtMs[pid] = now;
      // Drop the in-memory send cache so the next send re-resolves devices.
      _recipientDevicesCacheByProfileId.remove(pid);
      DiagLog.event('peer', 'device_refresh_on_new_sender', {
        'peer': DiagLog.pfx(pid),
        'sender_dev': DiagLog.pfx(sid),
      });
      await refreshContactDevices(pid);
    } catch (_) {
      // best-effort; identity-key drift / network failures handled elsewhere
    }
  }

  Future<List<String>> _listRecipientDevicesForSend({
    required String peerProfileId,
    required String selfDeviceId,
    bool forceRefresh = false,
  }) async {
    try {
      var effectiveForce = forceRefresh;
      var result = await _listRecipientDevicesForSendImpl(
        peerProfileId: peerProfileId,
        selfDeviceId: selfDeviceId,
        forceRefresh: effectiveForce,
      );
      // Sprint 2 R3: apply the relay-side staleness filter on top of the
      // keys-bundle-derived set. The wrapper is conservative — it NEVER
      // narrows the fanout when the relay reports `filter_applied=false`,
      // when the intersection with our bundle would be empty, or when
      // the request fails. See Restore Safety Contract INV-7 / R-T1..4.
      var filtered = await _applyRelayActiveDevicesFilter(
        bundleDeviceIds: result,
        peerProfileId: peerProfileId,
      );
      // Step 3 (2026-06-12): zero resolved targets from a cached/empty device
      // list almost always means the peer rotated their device (reinstall /
      // new account) and our cache is stale. Before giving up — which would
      // send the message into a dead mailbox / nowhere — force ONE fresh
      // keys-server lookup so we pick up the peer's CURRENT device(s).
      // 🔴 NOT FOR OUR OWN PROFILE (2026-07-31, field). The refetch below exists
      // because for a PEER, "zero devices" usually means they rotated device ids
      // and our cache is stale — worth one forced lookup. For OURSELVES that
      // reasoning is inverted: the list excludes our own device, so a
      // single-device profile answers zero every single time, correctly and
      // forever. The self-mirror paths (receipts, text, room envelopes) ask on
      // EVERY message, so this turned into a forced keys-server round trip per
      // message — measured on a device as a steady stream of
      // `fanout_refetch_on_empty peer=<self> count=0`, burning the shared
      // per-IP rate budget the send path needs.
      //
      // 🔴 «НИКОГДА» ОКАЗАЛОСЬ СЛИШКОМ СИЛЬНЫМ (09.09.2026, полевой разбор).
      //
      // Рассуждение выше верно ровно для профиля, у которого одно устройство.
      // Но у профиля, где устройство ВТОРОЕ ТОЛЬКО ЧТО ПОЯВИЛОСЬ, кэш пакетов
      // пуст — и запрет перезапроса означает, что он останется пустым навсегда.
      // Ни одно зеркало на свои устройства не уйдёт, потому что адресатов
      // всегда ноль.
      //
      // Наблюдалось на живом аккаунте: десктоп переподключили с новым
      // device_id, телефон о нём узнал (его зеркала доходили и применялись —
      // `selfsync.text_applied`), а обратно не уходило ничего:
      // `send.fanout_targets peer=<свой профиль> count=0 bundle_count=0`.
      // Снаружи это выглядело как «пишу на ПК — на телефоне пусто».
      //
      // Поэтому не «никогда», а «не чаще раза в пять минут». Это сохраняет
      // смысл прежней правки — round trip на КАЖДОЕ сообщение был реальной
      // проблемой и больше не повторится, — но оставляет пути узнать о новом
      // устройстве. Профиль с одним устройством платит один запрос в пять
      // минут только пока что-то отправляет.
      final ownPidForRefetch = (_profileId ?? '').trim();
      final askingAboutSelf =
          ownPidForRefetch.isNotEmpty &&
          peerProfileId.trim() == ownPidForRefetch;
      final nowMsForSelfRefetch = DateTime.now().millisecondsSinceEpoch;
      final selfRefetchAllowed =
          nowMsForSelfRefetch - _lastSelfFanoutRefetchAtMs >=
          _kSelfFanoutRefetchMinIntervalMs;
      if (askingAboutSelf && filtered.isEmpty && !effectiveForce &&
          selfRefetchAllowed) {
        _lastSelfFanoutRefetchAtMs = nowMsForSelfRefetch;
        effectiveForce = true;
        result = await _listRecipientDevicesForSendImpl(
          peerProfileId: peerProfileId,
          selfDeviceId: selfDeviceId,
          forceRefresh: true,
        );
        filtered = await _applyRelayActiveDevicesFilter(
          bundleDeviceIds: result,
          peerProfileId: peerProfileId,
        );
        DiagLog.event('send', 'self_fanout_refetch', {
          'count': filtered.length,
          'bundle_count': result.length,
        });
      }
      if (filtered.isEmpty && !effectiveForce && !askingAboutSelf) {
        effectiveForce = true;
        result = await _listRecipientDevicesForSendImpl(
          peerProfileId: peerProfileId,
          selfDeviceId: selfDeviceId,
          forceRefresh: true,
        );
        filtered = await _applyRelayActiveDevicesFilter(
          bundleDeviceIds: result,
          peerProfileId: peerProfileId,
        );
        DiagLog.event('send', 'fanout_refetch_on_empty', {
          'peer': DiagLog.pfx(peerProfileId),
          'count': filtered.length,
        });
      }
      DiagLog.event('send', 'fanout_targets', {
        'peer': DiagLog.pfx(peerProfileId),
        'count': filtered.length,
        'bundle_count': result.length,
        'force_refresh': effectiveForce,
      });
      return filtered;
    } catch (e) {
      DiagLog.event('send', 'fanout_lookup_fail', {
        'peer': DiagLog.pfx(peerProfileId),
        'reason': _classifyShortReason(e),
      });
      rethrow;
    }
  }

  // Sprint 2 R3 — relay active-devices cache. Short TTL (60 s) so we
  // bypass repeated round-trips inside a burst of sends, but pick up
  // any rapid changes in liveness on the next send.
  static const _activeDevicesCacheTtlMs = 60 * 1000;
  final Map<String, _ActiveDevicesCacheEntry> _activeDevicesCacheByProfileId =
      <String, _ActiveDevicesCacheEntry>{};

  /// Conservative wrapper around `RelayClient.fetchActiveDevices`.
  ///
  /// Returns the **same** `bundleDeviceIds` set unless ALL of the
  /// following are true:
  ///   1. Relay client is configured (not in tests / offline mode).
  ///   2. `fetchActiveDevices` returned a snapshot (not null).
  ///   3. The snapshot reports `filter_applied = true`.
  ///   4. Intersecting the bundle with the relay's active set leaves
  ///      a non-empty result.
  ///
  /// In every other case we propagate `bundleDeviceIds` verbatim so
  /// the relay can never silently narrow the fanout (INV-7).
  Future<List<String>> _applyRelayActiveDevicesFilter({
    required List<String> bundleDeviceIds,
    required String peerProfileId,
  }) async {
    final relay = _relay;
    if (relay == null || bundleDeviceIds.isEmpty) {
      return bundleDeviceIds;
    }
    final now = DateTime.now().millisecondsSinceEpoch;
    _ActiveDevicesCacheEntry? cached =
        _activeDevicesCacheByProfileId[peerProfileId];
    final cacheFresh =
        cached != null && (now - cached.fetchedAtMs) < _activeDevicesCacheTtlMs;
    // OFFLINE-SEND FIX (2026-07-24): this filter is a best-effort optimization
    // that NEVER grows the fanout — so it must never pay the full HTTP timeout
    // (_httpTimeout = 10 s) inline on the send path. Blocking here for 10 s while
    // offline is what froze the composer's `_sendInFlight` re-entrancy guard and
    // made the field "без сети можно отправить только одно смс" — the second tap
    // was ignored while the first send was still stuck fetching. Skip the fetch
    // entirely when the relay is known-unreachable (instant), and cap it with a
    // short backstop timeout otherwise (a flapping link can report reachable
    // while the request hangs). Either way we fall through to the cached / bundle
    // set — the outbox pump and the FIX-C4 refresh-on-skip re-run discovery once
    // connectivity returns, so no delivery correctness is lost.
    final relayMaybeReachable = _relayOnline || _relayHttpReachable;
    if (!cacheFresh && relayMaybeReachable) {
      try {
        final snapshot = await relay
            .fetchActiveDevices(peerProfileId: peerProfileId)
            .timeout(const Duration(seconds: 2), onTimeout: () => null);
        if (snapshot != null) {
          cached = _ActiveDevicesCacheEntry(
            activeDeviceIds: snapshot.deviceIds,
            filterApplied: snapshot.filterApplied,
            fetchedAtMs: now,
            liveness: snapshot.liveness,
          );
          _activeDevicesCacheByProfileId[peerProfileId] = cached;
        }
        // If snapshot is null (a real miss OR our short backstop timeout fired)
        // we intentionally do NOT bump fetchedAtMs so the next send re-tries.
      } catch (_) {
        // Network / parse failure: fall through with whatever (possibly
        // stale) cached entry we have. Never pessimistically narrow.
      }
    }
    // 🔴 ПЕРЕЧНИ, А НЕ СЧЁТЧИКИ (11.09.2026). Здесь решается, каким устройствам
    // контакта уйдёт сообщение или звонок, и именно здесь разбор 11.09 упёрся в
    // стену: в журнале были только количества, а вопрос стоял «есть ли живое
    // устройство в списке ВООБЩЕ». Ниже — три списка целиком.
    if (cached == null || !cached.filterApplied) {
      DiagLog.event('peer', 'active_devices_no_filter', {
        'peer': DiagLog.pfx(peerProfileId),
        'why': cached == null ? 'no_cache' : 'filter_not_applied',
        'bundle': bundleDeviceIds.map(DiagLog.pfx).join(','),
      });
      return bundleDeviceIds;
    }
    final activeSet = cached.activeDeviceIds.toSet();
    final intersection = bundleDeviceIds
        .where(activeSet.contains)
        .toList(growable: false);
    if (intersection.isEmpty) {
      // INV-7: never let the filter empty the fanout — fall back to bundle.
      DiagLog.event('peer', 'active_devices_filter_empty', {
        'peer': DiagLog.pfx(peerProfileId),
        'bundle_count': bundleDeviceIds.length,
        'bundle': bundleDeviceIds.map(DiagLog.pfx).join(','),
        'active': cached.activeDeviceIds.map(DiagLog.pfx).join(','),
      });
      return bundleDeviceIds;
    }
    if (intersection.length != bundleDeviceIds.length) {
      DiagLog.event('peer', 'active_devices_filter_applied', {
        'peer': DiagLog.pfx(peerProfileId),
        'bundle_count': bundleDeviceIds.length,
        'active_count': intersection.length,
        'bundle': bundleDeviceIds.map(DiagLog.pfx).join(','),
        'active': cached.activeDeviceIds.map(DiagLog.pfx).join(','),
        'kept': intersection.map(DiagLog.pfx).join(','),
      });
    }
    return intersection;
  }

  Future<List<String>> _listRecipientDevicesForSendImpl({
    required String peerProfileId,
    required String selfDeviceId,
    bool forceRefresh = false,
  }) async {
    bool isRateLimitedError(Object error) {
      final msg = error.toString().toLowerCase();
      return msg.contains('429') || msg.contains('rate_limited');
    }

    Future<List<String>> loadFromDbCache() async {
      final db = _db;
      if (db == null) return const <String>[];
      final rows = await db.contactDevicesList(peerProfileId);
      final ids = rows
          .map((r) => ((r['device_id'] as String?) ?? '').trim())
          .where((d) => d.isNotEmpty && d != selfDeviceId)
          .toSet()
          .toList(growable: false);
      if (ids.isNotEmpty) {
        _recipientDevicesCacheByProfileId[peerProfileId] =
            _RecipientDevicesCacheEntry(
              deviceIds: ids,
              fetchedAtMs: DateTime.now().millisecondsSinceEpoch,
            );
      }
      return ids;
    }

    final now = DateTime.now().millisecondsSinceEpoch;
    final cached = _recipientDevicesCacheByProfileId[peerProfileId];
    if (!forceRefresh &&
        cached != null &&
        (now - cached.fetchedAtMs) < _recipientDevicesCacheTtlMs) {
      return cached.deviceIds
          .where((d) => d.isNotEmpty && d != selfDeviceId)
          .toList(growable: false);
    }

    final rateLimitedUntilMs =
        _recipientDevicesRateLimitUntilMsByProfileId[peerProfileId] ?? 0;
    if (rateLimitedUntilMs > now) {
      if (cached != null) {
        return cached.deviceIds
            .where((d) => d.isNotEmpty && d != selfDeviceId)
            .toList(growable: false);
      }
      final dbCached = await loadFromDbCache();
      if (dbCached.isNotEmpty) return dbCached;
      throw RecipientDevicesUnavailable(
        'keys device lookup is in its rate-limit cooldown',
      );
    }

    final keys = _keys;
    if (keys == null) {
      if (cached != null) {
        return cached.deviceIds
            .where((d) => d.isNotEmpty && d != selfDeviceId)
            .toList(growable: false);
      }
      return loadFromDbCache();
    }

    // OFFLINE-SEND FIX (2026-07-24): when the relay/keys endpoint is unreachable,
    // do NOT pay the ~10 s keys HTTP timeout inline on the send path just to
    // refresh the recipient's device list — that stall freezes the composer's
    // `_sendInFlight` guard and is the other half of the "без сети можно
    // отправить только одно смс" bug. Use whatever device set we already have;
    // the background refresh and the outbox pump re-discover devices on
    // reconnect, and this filter/lookup never affects delivery correctness.
    final relayMaybeReachable = _relayOnline || _relayHttpReachable;
    if (!forceRefresh && !relayMaybeReachable) {
      if (cached != null) {
        return cached.deviceIds
            .where((d) => d.isNotEmpty && d != selfDeviceId)
            .toList(growable: false);
      }
      final dbCachedOffline = await loadFromDbCache();
      if (dbCachedOffline.isNotEmpty) return dbCachedOffline;
      // No cache at all AND offline: fall through to one bounded attempt below.
    }

    try {
      // Bounded so a stale "reachable" flag on a flapping link (e.g. an elevator)
      // can't hang the send path for the full _httpTimeout; on timeout we fall
      // through to the cache in the catch below.
      await refreshContactDevices(peerProfileId)
          .timeout(const Duration(seconds: 3));
      final fresh = await loadFromDbCache();
      _recipientDevicesRateLimitUntilMsByProfileId.remove(peerProfileId);
      _recipientDevicesCacheByProfileId[peerProfileId] =
          _RecipientDevicesCacheEntry(deviceIds: fresh, fetchedAtMs: now);
      return fresh
          .where((d) => d.isNotEmpty && d != selfDeviceId)
          .toList(growable: false);
    } catch (e) {
      if (isRateLimitedError(e)) {
        _recipientDevicesRateLimitUntilMsByProfileId[peerProfileId] =
            now + _recipientDevicesRateLimitCooldownMs;
      }
      if (cached != null) {
        return cached.deviceIds
            .where((d) => d.isNotEmpty && d != selfDeviceId)
            .toList(growable: false);
      }
      final dbCached = await loadFromDbCache();
      if (dbCached.isNotEmpty) return dbCached;
      if (isRateLimitedError(e)) {
        throw RecipientDevicesUnavailable(
          'keys server rate-limited the device lookup',
        );
      }
      rethrow;
    }
  }

  // ---------------------------------------------------------------------------
  // Background retry for messages queued because the recipient had no devices.
  // ---------------------------------------------------------------------------

  /// How long (ms) to keep retrying before giving up and marking as failed.
  static const _noDeviceRetryTtlMs = 24 * 60 * 60 * 1000; // 24 h

  /// Minimum gap (ms) between retry checks for the same profile.
  static const _noDeviceRetryIntervalMs = 10 * 1000; // 10 s

  /// Ceiling for the exponential backoff below.
  ///
  /// 🔴 FIELD BUG (2026-07-31): this retry used a FIXED 10 s interval with
  /// `forceRefresh: true`, and the entry lives for [_noDeviceRetryTtlMs] (24 h).
  /// A recipient that never resolves — a stale/ghost room member, a peer who
  /// reinstalled — therefore produced up to ~8600 FORCED keys-server lookups a
  /// day, each one deliberately bypassing every cache. The keys service is a
  /// per-IP token bucket (30 burst, ~1 req/s; `server/keys/src/main.rs`), and
  /// several of the user's own devices share one home IP, so this background
  /// loop drained the bucket the SEND path needs. The visible symptom was
  /// "rate_limit" on send every 2-3 messages: a lookup for a peer with no
  /// cached devices throws on 429 (see `_listRecipientDevicesForSendImpl`).
  ///
  /// Backoff makes an unreachable recipient cost ~6 lookups/hour instead of
  /// ~360, while a recipient who comes back is still picked up within minutes.
  static const _noDeviceRetryMaxIntervalMs = 10 * 60 * 1000; // 10 min

  /// How many early attempts may bypass the cache. The first tries are the ones
  /// that plausibly race a peer publishing their keys; after that a forced
  /// refresh only re-asks a question the cache already answered.
  static const _noDeviceRetryForceRefreshAttempts = 2;

  /// Retry delay for [profileId] given how many attempts already came back
  /// empty: 10 s, 20 s, 40 s … capped at [_noDeviceRetryMaxIntervalMs].
  @visibleForTesting
  static int noDeviceRetryDelayMs(int attempts) {
    if (attempts <= 0) return _noDeviceRetryIntervalMs;
    var delay = _noDeviceRetryIntervalMs;
    for (var i = 0; i < attempts && delay < _noDeviceRetryMaxIntervalMs; i++) {
      delay *= 2;
    }
    return delay > _noDeviceRetryMaxIntervalMs
        ? _noDeviceRetryMaxIntervalMs
        : delay;
  }

  /// Drains all pending-no-device entries for [profileId] into the outbox
  /// using the already-resolved [targets] list.  Must be called BEFORE the
  /// new message's outbox entry is created, so delivery order is old→new.
  /// Safe to call even when the queue is empty.
  Future<void> _flushPendingNoDeviceEntries({
    required String profileId,
    required List<String> targets,
    required String selfDeviceId,
    required dynamic db, // AppDatabase
    required dynamic ratchet, // RatchetV3Manager
    required dynamic relay, // RelayClient
    required int nowMs,
  }) async {
    final entries = _pendingNoDeviceSend[profileId];
    if (entries == null || entries.isEmpty) return;

    final initialTargets = targets
        .where((d) => d.isNotEmpty && d != selfDeviceId)
        .toList(growable: false);
    if (initialTargets.isEmpty) return;

    var validTargets = initialTargets;
    try {
      final blocking = await _sendGateBlockingDevices(profileId, initialTargets);
      if (blocking.isNotEmpty) {
        final blocked = blocking.toSet();
        validTargets = initialTargets
            .where((d) => !blocked.contains(d))
            .toList(growable: false);
      }
    } catch (e) {
      callLog(
        'AppCtrl',
        '_flushPendingNoDeviceEntries verify refresh failed '
            'profile=$profileId: $e',
      );
      return;
    }
    if (validTargets.isEmpty) return;

    final toProcess = List<_PendingNoDeviceEntry>.from(entries);

    callLog(
      'AppCtrl',
      '_flushPendingNoDeviceEntries: delivering ${toProcess.length} queued '
          'message(s) to profile=$profileId via ${validTargets.length} device(s)',
    );

    for (final entry in toProcess) {
      if (nowMs - entry.createdAtMs > _noDeviceRetryTtlMs) {
        try {
          await db.updateEventLocalState(
            eventId: entry.localEventId,
            localState: MessageLocalState.failed,
            reasonCode: MessageFailureReason.ttlExpired,
          );
        } catch (_) {}
        await _dropPendingNoDeviceEntry(
          profileId: profileId,
          localEventId: entry.localEventId,
        );
        continue;
      }

      // Avoid double-delivery if outbox entries already exist.
      final already = await db.outboxCountForEventRef(entry.localEventId);
      if (already > 0) {
        await _dropPendingNoDeviceEntry(
          profileId: profileId,
          localEventId: entry.localEventId,
        );
        continue;
      }

      var queued = 0;
      for (final toDeviceId in validTargets) {
        try {
          final msgId = _uuid.v4();
          final wire = await _encryptToPeerSerialized(
            ratchet: ratchet,
            selfDeviceId: selfDeviceId,
            peerProfileId: profileId,
            peerDeviceId: toDeviceId,
            plaintext: entry.payloadBytes,
          );
          await db.outboxUpsert(
            msgId: msgId,
            toDeviceId: toDeviceId,
            ciphertextB64: base64Encode(wire),
            ttlSeconds: _outboxUserMessageTtlSeconds,
            state: OutboxSendState.pending,
            attemptCount: 0,
            nextRetryAtMs: nowMs,
            createdAtMs: nowMs,
            correlationId: entry.localEventId,
            convoId: profileId,
            transportMetaJson: entry.transportMetaJson,
            eventIdRef: entry.localEventId,
            expiresAtMs: nowMs + _outboxUserMessageTtlMs,
          );
          queued++;
        } catch (e) {
          callLog(
            'AppCtrl',
            '_flushPendingNoDeviceEntries skip target=$toDeviceId: $e',
          );
        }
      }

      if (queued == 0) {
        try {
          await db.updateEventLocalState(
            eventId: entry.localEventId,
            localState: MessageLocalState.failed,
            reasonCode: MessageFailureReason.noDeliverableTarget,
          );
        } catch (_) {}
      }
      await _dropPendingNoDeviceEntry(
        profileId: profileId,
        localEventId: entry.localEventId,
      );
    }
    _changed.add(null);
    _kickRelayOutbox(relay);
  }

  /// Called by the service watchdog — fallback for when no new message was
  /// sent to a profile.  Calls [_flushPendingNoDeviceEntries] after fetching
  /// devices.
  Future<void> _retryPendingNoDeviceSend() async {
    final did = _deviceId;
    final ratchet = _ratchetV3;
    final relay = _relay;
    final db = _db;
    if (did == null || ratchet == null || relay == null || db == null) return;
    if (_pendingNoDeviceSend.isEmpty) return;

    final now = DateTime.now().millisecondsSinceEpoch;
    final profileIds = List<String>.from(_pendingNoDeviceSend.keys);

    for (final profileId in profileIds) {
      // Throttle per-profile checks to avoid hammering the key server. The
      // delay GROWS while the recipient keeps resolving to nothing — a fixed
      // interval here drained the shared keys-server rate budget and made the
      // user's own sends fail with 429 (see _noDeviceRetryMaxIntervalMs).
      final attempts = _noDeviceRetryAttempts[profileId] ?? 0;
      final lastCheck = _noDeviceRetryLastCheckMs[profileId] ?? 0;
      if (now - lastCheck < noDeviceRetryDelayMs(attempts)) continue;
      _noDeviceRetryLastCheckMs[profileId] = now;

      final entries = _pendingNoDeviceSend[profileId];
      if (entries == null || entries.isEmpty) {
        _pendingNoDeviceSend.remove(profileId);
        _noDeviceRetryAttempts.remove(profileId);
        continue;
      }

      try {
        final targets = await _listRecipientDevicesForSend(
          peerProfileId: profileId,
          selfDeviceId: did,
          // Only the early attempts bypass the cache. Later ones must not: the
          // lookup already forces ONE refresh of its own whenever the filtered
          // set comes back empty (`fanout_refetch_on_empty`), so forcing again
          // every tick only re-asks a question the cache just answered — at the
          // cost of the rate budget the send path needs.
          forceRefresh: attempts < _noDeviceRetryForceRefreshAttempts,
        );
        if (targets.isEmpty) {
          // Still nothing — widen the gap before the next attempt.
          _noDeviceRetryAttempts[profileId] = attempts + 1;
          continue;
        }
        // Resolved: the recipient is reachable again, so the next stall starts
        // from the fast interval instead of inheriting an hour-old backoff.
        _noDeviceRetryAttempts.remove(profileId);

        await _flushPendingNoDeviceEntries(
          profileId: profileId,
          targets: targets,
          selfDeviceId: did,
          db: db,
          ratchet: ratchet,
          relay: relay,
          nowMs: now,
        );
      } catch (e) {
        // A THROW is the rate-limited case (the lookup throws when it has no
        // cached devices to fall back on), so it must widen the gap too —
        // otherwise the one failure mode that caused the storm would be the
        // one that kept retrying at full speed.
        _noDeviceRetryAttempts[profileId] = attempts + 1;
        callLog(
          'AppCtrl',
          '_retryPendingNoDeviceSend error for profile=$profileId: $e',
        );
      }
    }
  }

  void _rememberOwnDeviceId(String? deviceId) {
    final did = (deviceId ?? '').trim();
    if (did.isEmpty) return;
    _knownOwnDeviceIds.add(did);
  }

  Future<void> _loadKnownOwnDeviceIdsFromDb() async {
    final db = _db;
    final pid = (_profileId ?? '').trim();
    if (db == null || pid.isEmpty || pid.startsWith('LOCAL-')) return;
    try {
      final ids = await db.deviceIdsForProfile(pid);
      _knownOwnDeviceIds.addAll(ids);
    } catch (_) {
      // ignore
    }
    await _dropForeignOwnDeviceIds(pid);
  }

  /// Выбрасывает из списка «своих устройств» те, что переписка ПРЯМО приписала
  /// другому человеку.
  ///
  /// 🔴 НАЙДЕНО 16.09.2026 ПО ЖАЛОБЕ ВЛАДЕЛЬЦА: «в пк версии все пузыри справа
  /// и нет половины чатов из комнаты».
  ///
  /// ПРИЧИНА. Список своих устройств лежит на диске в `known_own_device_ids_v1`
  /// — БЕЗ пометки, какому профилю он принадлежит. `resetProfileAndLocalData`
  /// («выгрузить аккаунт») чистил набор в памяти и стирал базу, но этот ключ
  /// оставлял. Следующий запуск поднимал его с диска и приписывал НОВОМУ
  /// профилю. На машине владельца так и вышло: окно линковали сначала к одному
  /// профилю, потом к другому, и устройства первого остались «своими».
  ///
  /// ЧЕМ ЭТО ОБЕРНУЛОСЬ. `isOwnDeviceId` решает не только сторону пузыря.
  /// `resolveSenderProfileId` возвращает для «своего» устройства `null` — имя и
  /// фотография автора не подставляются; уведомление гасится как собственное
  /// эхо. То есть чужие сообщения выглядели своими и молча.
  ///
  /// ПРАВИЛО ПРУНЫ — «ЧУЖОЕ ТОЛЬКО ПО ДОКАЗАТЕЛЬСТВУ». Устройство выбрасывается
  /// ТОЛЬКО если `contact_devices` называет владельцем чужой профиль, то есть
  /// мы сами разрешали это устройство как ПОЛУЧАТЕЛЯ. Отсутствие записи — это
  /// «неизвестно», и такое устройство остаётся своим: ровно на этом держится
  /// правка 08.08.2026, из-за которой список и завели (после восстановления из
  /// копии сервер уже не помнит старых устройств, и узнать их неоткуда).
  ///
  /// `device_profiles` для этого НЕ годится: туда попадает и прежний профиль
  /// самого владельца после смены удостоверения, и пруна по нему вернула бы
  /// ту самую беду 08.08 — свои сообщения слева.
  Future<void> _dropForeignOwnDeviceIds(String myProfileId) async {
    final db = _db;
    if (db == null) return;
    final myDeviceId = (_deviceId ?? '').trim();
    final suspects = _knownOwnDeviceIds
        .map((v) => v.trim())
        .where((v) => v.isNotEmpty && v != myDeviceId)
        .toList(growable: false);
    if (suspects.isEmpty) return;

    Map<String, String> owners;
    try {
      owners = await db.contactProfilesForDeviceIds(suspects);
    } catch (_) {
      return; // база занята — лучше ничего, чем наугад
    }
    final foreign = <String>{
      for (final e in owners.entries)
        if (e.value != myProfileId) e.key,
    };
    if (foreign.isEmpty) return;

    _knownOwnDeviceIds.removeAll(foreign);
    DiagLog.event('own_dev', 'foreign_dropped', {
      'n': foreign.length,
      'dev': DiagLog.pfx(foreign.first),
    });
    final prefs = _prefs;
    if (prefs != null) {
      final kept = _loadPersistedOwnDeviceIds(
        prefs,
      ).where((v) => !foreign.contains(v)).toList(growable: false);
      try {
        await prefs.setStringList(_prefsKnownOwnDeviceIdsKey, kept);
      } catch (_) {
        // память настроек недоступна — в памяти уже вычищено
      }
    }
    _changed.add(null);
  }

  Future<void> _loadPendingNoDeviceSendFromDb() async {
    final db = _db;
    if (db == null) return;

    final rows = await db.pendingNoDeviceSendListAll();
    _pendingNoDeviceSend.clear();
    _noDeviceRetryLastCheckMs.clear();
    _noDeviceRetryAttempts.clear();

    var restored = 0;
    for (final row in rows) {
      final profileId = (row['profile_id'] as String? ?? '').trim();
      final localEventId = (row['local_event_id'] as String? ?? '').trim();
      final payloadB64 = (row['payload_b64'] as String? ?? '').trim();
      final createdAtMs = (row['created_at_ms'] as num?)?.toInt() ?? 0;
      if (profileId.isEmpty || localEventId.isEmpty || payloadB64.isEmpty) {
        if (localEventId.isNotEmpty) {
          try {
            await db.pendingNoDeviceSendDelete(localEventId);
          } catch (_) {}
        }
        continue;
      }

      // SELF-HEAL for installs that already parked a self-addressed control
      // before the guard in `sendControlMessage.queueNoDeviceRetry` existed.
      // Such an entry can never be delivered (its only recipient is this very
      // device, which is excluded from its own device list), and while it sits
      // here the retry keeps asking the keys server about us — the storm that
      // broke sending with `rate_limit`. Purging on load fixes the device on
      // the next launch instead of waiting out the 24 h TTL.
      final ownPid = (_profileId ?? '').trim();
      if (ownPid.isNotEmpty && profileId == ownPid) {
        try {
          await db.pendingNoDeviceSendDelete(localEventId);
        } catch (_) {}
        DiagLog.event('send', 'self_no_device_entry_purged', {
          'peer': DiagLog.pfx(profileId),
        });
        continue;
      }

      try {
        final payloadBytes = Uint8List.fromList(base64Decode(payloadB64));
        final transportMetaJson = (row['transport_meta_json'] as String?)
            ?.trim();
        _pendingNoDeviceSend
            .putIfAbsent(profileId, () => <_PendingNoDeviceEntry>[])
            .add(
              _PendingNoDeviceEntry(
                localEventId: localEventId,
                payloadBytes: payloadBytes,
                transportMetaJson: transportMetaJson?.isEmpty == true
                    ? null
                    : transportMetaJson,
                createdAtMs: createdAtMs,
              ),
            );
        restored++;
      } catch (e) {
        callLog(
          'AppCtrl',
          '_loadPendingNoDeviceSendFromDb dropping corrupt entry '
              'profile=$profileId localEvent=$localEventId: $e',
        );
        try {
          await db.pendingNoDeviceSendDelete(localEventId);
        } catch (_) {}
      }
    }

    for (final entries in _pendingNoDeviceSend.values) {
      entries.sort((a, b) {
        final byCreated = a.createdAtMs.compareTo(b.createdAtMs);
        if (byCreated != 0) return byCreated;
        return a.localEventId.compareTo(b.localEventId);
      });
    }

    if (restored > 0) {
      callLog(
        'AppCtrl',
        '_loadPendingNoDeviceSendFromDb restored $restored queued message(s)',
      );
    }
  }

  Future<void> _queuePendingNoDeviceEntry({
    required String profileId,
    required _PendingNoDeviceEntry entry,
  }) async {
    // 🔴 IMMORTAL-QUEUE GUARD (2026-07-31) — lives HERE, at the single choke
    // point every queueing path funnels through, rather than at any one call
    // site. A control parked against our OWN profile can never be delivered
    // (our own device is excluded from our device list), nothing clears it, and
    // the 24 h retry keeps re-asking the keys server about us — the storm that
    // drained the shared rate budget and broke ordinary sending with 429.
    //
    // Dropping is correct, not merely cheaper: there is no recipient, and a
    // device paired later takes the full pairing sync — it never replays this
    // queue.
    final myPid = (_profileId ?? '').trim();
    if (myPid.isNotEmpty && profileId.trim() == myPid) {
      DiagLog.event('send', 'self_no_device_queue_skipped', {
        'peer': DiagLog.pfx(profileId),
      });
      return;
    }
    final db = _db;
    if (db != null) {
      await _retryDbBusy(() async {
        await db.pendingNoDeviceSendUpsert(
          localEventId: entry.localEventId,
          profileId: profileId,
          payloadBytes: entry.payloadBytes,
          transportMetaJson: entry.transportMetaJson,
          createdAtMs: entry.createdAtMs,
        );
      });
    }

    final entries = _pendingNoDeviceSend.putIfAbsent(
      profileId,
      () => <_PendingNoDeviceEntry>[],
    );
    entries.removeWhere((e) => e.localEventId == entry.localEventId);
    entries.add(entry);
    entries.sort((a, b) {
      final byCreated = a.createdAtMs.compareTo(b.createdAtMs);
      if (byCreated != 0) return byCreated;
      return a.localEventId.compareTo(b.localEventId);
    });
  }

  Future<void> _dropPendingNoDeviceEntry({
    required String profileId,
    required String localEventId,
  }) async {
    final db = _db;
    if (db != null) {
      await _retryDbBusy(() async {
        await db.pendingNoDeviceSendDelete(localEventId);
      });
    }

    final entries = _pendingNoDeviceSend[profileId];
    if (entries == null) return;
    entries.removeWhere((e) => e.localEventId == localEventId);
    if (entries.isEmpty) {
      _pendingNoDeviceSend.remove(profileId);
      _noDeviceRetryLastCheckMs.remove(profileId);
      _noDeviceRetryAttempts.remove(profileId);
    }
  }

  void _removePendingNoDeviceEntryFromMemory(String localEventId) {
    final emptyProfiles = <String>[];
    for (final entry in _pendingNoDeviceSend.entries) {
      entry.value.removeWhere((e) => e.localEventId == localEventId);
      if (entry.value.isEmpty) {
        emptyProfiles.add(entry.key);
      }
    }
    for (final profileId in emptyProfiles) {
      _pendingNoDeviceSend.remove(profileId);
      _noDeviceRetryLastCheckMs.remove(profileId);
      _noDeviceRetryAttempts.remove(profileId);
    }
  }

  Future<String> _resolvePeerProfileIdForConvoId(String convoId) async {
    final db = _db;
    if (db == null) {
      throw StateError(
        'Message retry unavailable: local database is not ready',
      );
    }

    var resolved = convoId.trim();
    if (resolved.isEmpty) {
      throw StateError('Message retry unavailable: missing conversation id');
    }

    final convo = await db.convoGet(resolved);
    final peerFromRow = (convo?['peer_profile_id'] as String?)?.trim();
    if (peerFromRow != null && peerFromRow.isNotEmpty) {
      resolved = peerFromRow;
    }

    if (resolved.startsWith('req:') && resolved.length > 4) {
      resolved = resolved.substring(4).trim();
    }

    if (resolved.isEmpty || resolved.startsWith('group:')) {
      throw StateError('Message retry unavailable for this conversation');
    }
    return resolved;
  }

  Future<Uint8List?> _decryptStoredLocalPayloadBytes(String eventId) async {
    final db = _db;
    final crypto = _crypto;
    if (db == null || crypto == null) return null;

    final row = await db.eventGet(eventId);
    if (row == null) return null;

    final localB64 = (row['local_ciphertext_b64'] as String?)?.trim();
    if (localB64 != null && localB64.isNotEmpty) {
      try {
        return Uint8List.fromList(await crypto.decrypt(base64Decode(localB64)));
      } catch (_) {
        // Fall through to legacy local ciphertext path below.
      }
    }

    final cipherB64 = (row['ciphertext_b64'] as String? ?? '').trim();
    if (cipherB64.isEmpty) return null;
    try {
      return Uint8List.fromList(await crypto.decrypt(base64Decode(cipherB64)));
    } catch (_) {
      return null;
    }
  }

  // ===========================================================================
  // PR5 peer-to-device history sync — responder + chunk-applier helpers.
  //
  // Two-direction protocol carried over the existing self-mirror ratchet
  // channel (see `lib/sync/peer_history_protocol.dart` for wire details and
  // security rationale). These helpers are intentionally additive: nothing
  // calls them outside the dispatch hook in `_handleDecryptedInboundPayload`
  // and the desktop-side orchestrator (`PeerHistoryService`).
  // ===========================================================================

  /// In-flight request guard. Keeps mobile from re-walking the events table
  /// if the desktop accidentally double-fires the same `requestId` (e.g.
  /// because the relay redelivered the control message after a WS hiccup).
  /// Entries are cleared after [_peerHistoryRequestTtl] regardless of
  /// success/failure so a long-lived process doesn't slowly leak memory.
  final Map<String, int> _peerHistoryInFlightRequests = <String, int>{};
  static const Duration _peerHistoryRequestTtl = Duration(minutes: 5);

  void _gcPeerHistoryInFlight(int nowMs) {
    final cutoff = nowMs - _peerHistoryRequestTtl.inMilliseconds;
    _peerHistoryInFlightRequests.removeWhere((_, ts) => ts < cutoff);
  }

  /// Mobile-side responder. Pages the local events table backwards from
  /// [PeerHistoryRequest.cursor] (or "now") and ships one or more
  /// [PeerHistoryChunk]s to the requesting device.
  ///
  /// Errors are swallowed — the desktop will simply time out and retry
  /// (or the user will trigger the boot path again next launch). We log
  /// to the diag channel so we can correlate "history button did nothing"
  /// bug reports.
  Future<void> _respondToPeerHistoryRequest({
    required PeerHistoryRequest request,
    required String requestingDeviceId,
    required String requestingProfileId,
  }) async {
    final db = _db;
    final crypto = _crypto;
    if (db == null || crypto == null) return;
    if (requestingDeviceId.isEmpty || requestingProfileId.isEmpty) return;

    final nowMs = DateTime.now().millisecondsSinceEpoch;
    _gcPeerHistoryInFlight(nowMs);
    final dedupeKey = '${request.requestId}@$requestingDeviceId';
    if (_peerHistoryInFlightRequests.containsKey(dedupeKey)) {
      return;
    }
    _peerHistoryInFlightRequests[dedupeKey] = nowMs;

    try {
      final limitPerChunk = request.limit.clamp(
        1,
        kPeerHistoryMaxEventsPerChunk,
      );
      int? beforeMs = (() {
        // Cursor format: decimal ms. We pick it up below if pagination
        // resumes; on the first chunk we honour `untilMs` if the caller
        // passed one (used by PR6 "load older" UX).
        final c = request.cursor;
        if (c != null && c.isNotEmpty) {
          return int.tryParse(c);
        }
        return request.untilMs;
      })();
      final sinceMs = request.sinceMs ?? 0;

      var chunksSent = 0;
      var done = false;
      // PR6: dedupe groupMeta across chunks within one request. The
      // metadata for a given group is identical every time we ship it,
      // so a 5-chunk response would otherwise transmit it 5×. We send
      // it on the first chunk that surfaces an event from that group
      // and skip it on subsequent chunks.
      final alreadyShippedGroupIds = <String>{};
      while (!done && chunksSent < kPeerHistoryMaxChunksPerRequest) {
        final rows = await db.listRecentEventsForPeerSync(
          beforeCreatedAtMs: beforeMs,
          convoId: request.convoId,
          limit: limitPerChunk,
          includeGroups: true,
        );
        final outgoing = <PeerHistoryChunkEvent>[];
        final groupIdsInChunk = <String>{};
        var oldestSeenMs = beforeMs ?? 0;
        for (final row in rows) {
          final createdAt = (row['created_at_ms'] as int?) ?? 0;
          if (createdAt <= 0) continue;
          if (sinceMs > 0 && createdAt < sinceMs) {
            // Past the user-requested floor — stop paging.
            done = true;
            break;
          }

          final eventId = (row['event_id'] as String?) ?? '';
          final convoId = (row['convo_id'] as String?) ?? '';
          final type = (row['type'] as String?) ?? '';
          final senderDid = (row['sender_device_id'] as String?) ?? '';
          if (eventId.isEmpty || convoId.isEmpty || type.isEmpty) continue;
          // Skip rows that are themselves history-sync artefacts: stops
          // a feedback loop where desktop later asks for "all events" and
          // gets back rows we synthesized from its earlier request.
          if (eventId.startsWith('peersync:') ||
              eventId.startsWith('selfsync:')) {
            continue;
          }

          final localB64 =
              (row['local_ciphertext_b64'] as String?)?.trim() ?? '';
          final cipherB64 = (row['ciphertext_b64'] as String? ?? '').trim();
          Uint8List? plainBytes;
          try {
            if (localB64.isNotEmpty) {
              plainBytes = Uint8List.fromList(
                await crypto.decrypt(base64Decode(localB64)),
              );
            }
          } catch (_) {
            plainBytes = null;
          }
          if (plainBytes == null && cipherB64.isNotEmpty) {
            try {
              plainBytes = Uint8List.fromList(
                await crypto.decrypt(base64Decode(cipherB64)),
              );
            } catch (_) {
              plainBytes = null;
            }
          }
          if (plainBytes == null || plainBytes.isEmpty) continue;

          outgoing.add(
            PeerHistoryChunkEvent(
              eventId: eventId,
              convoId: convoId,
              type: type,
              senderDeviceId: senderDid.isEmpty ? 'unknown' : senderDid,
              createdAtMs: createdAt,
              payloadB64: base64Encode(plainBytes),
              payloadEventId: (row['payload_event_id'] as String?)?.trim(),
              localState: (row['local_state'] as String?)?.trim(),
            ),
          );
          if (convoId.startsWith('group:')) {
            groupIdsInChunk.add(convoId);
          }
          oldestSeenMs = createdAt;
        }

        if (rows.length < limitPerChunk) {
          done = true;
        }
        // PR6: build per-group metadata for groups appearing for the
        // first time in this request. Each meta is fetched lazily so
        // 1-to-1-only chunks pay nothing extra.
        final groupMetas = <PeerHistoryGroupMeta>[];
        for (final gid in groupIdsInChunk) {
          if (alreadyShippedGroupIds.contains(gid)) continue;
          final meta = await _buildPeerHistoryGroupMeta(gid);
          if (meta != null) {
            groupMetas.add(meta);
            alreadyShippedGroupIds.add(gid);
          }
        }
        final nextCursor = done || oldestSeenMs <= 0
            ? null
            : oldestSeenMs.toString();
        if (outgoing.isEmpty && done) {
          // Nothing left to ship — still send a tail-marker chunk so the
          // requester knows we're done (and can drop the in-flight token).
          final chunk = PeerHistoryChunk(
            requestId: request.requestId,
            events: const <PeerHistoryChunkEvent>[],
            nextCursor: null,
            done: true,
          );
          await _sendPeerHistoryChunk(
            chunk: chunk,
            peerProfileId: requestingProfileId,
            targetDeviceId: requestingDeviceId,
          );
          break;
        }

        final chunk = PeerHistoryChunk(
          requestId: request.requestId,
          events: outgoing,
          nextCursor: nextCursor,
          done: done,
          groupMetas: groupMetas,
        );
        await _sendPeerHistoryChunk(
          chunk: chunk,
          peerProfileId: requestingProfileId,
          targetDeviceId: requestingDeviceId,
        );
        chunksSent++;
        beforeMs = oldestSeenMs;
      }
    } catch (e) {
      callLog('AppCtrl', '_respondToPeerHistoryRequest failed: $e');
    } finally {
      _peerHistoryInFlightRequests.remove(dedupeKey);
    }
  }

  Future<void> _sendPeerHistoryChunk({
    required PeerHistoryChunk chunk,
    required String peerProfileId,
    required String targetDeviceId,
  }) async {
    final encoded = encodePeerHistoryChunk(chunk);
    try {
      await sendControlMessage(
        peerProfileId: peerProfileId,
        controlText: encoded,
        strict: false,
        forceRelayFlush: false,
        targetDeviceIds: <String>[targetDeviceId],
      );
    } catch (e) {
      callLog('AppCtrl', '_sendPeerHistoryChunk failed: $e');
    }
  }

  /// PR6: assemble a [PeerHistoryGroupMeta] snapshot for [groupId].
  /// Returns null when we can't construct a coherent snapshot — typically
  /// because the group was wiped locally or we never finalized its
  /// settings (which means we shouldn't push it to the desktop either).
  ///
  /// Reads three sources:
  ///   • `conversations` (title)
  ///   • `group_settings` (room policies + owner)
  ///   • `group_memberships` (member roster)
  ///
  /// All reads are best-effort; partial failure short-circuits to null
  /// so we don't ship half-built rooms.
  Future<PeerHistoryGroupMeta?> _buildPeerHistoryGroupMeta(
    String groupId,
  ) async {
    final db = _db;
    if (db == null) return null;
    try {
      final convoRow = await db.convoGet(groupId);
      if (convoRow == null) return null;
      final title = (convoRow['title'] as String?)?.trim() ?? '';

      final settings = await db.groupSettingsGet(groupId);
      if (settings == null) return null;
      final owner = (settings['owner_profile_id'] as String?)?.trim() ?? '';
      if (owner.isEmpty) return null;

      bool flag(Object? v, bool fallback) {
        if (v is int) return v != 0;
        if (v is num) return v != 0;
        if (v is bool) return v;
        return fallback;
      }

      int toInt(Object? v, int fallback) {
        if (v is int) return v;
        if (v is num) return v.toInt();
        if (v is String) return int.tryParse(v) ?? fallback;
        return fallback;
      }

      int? toIntNullable(Object? v) {
        if (v is int) return v;
        if (v is num) return v.toInt();
        if (v is String) return int.tryParse(v);
        return null;
      }

      final memberRows = await db.groupMembershipsListForSync(groupId);
      final members = <PeerHistoryGroupMember>[];
      for (final row in memberRows) {
        final pid = (row['profile_id'] as String?)?.trim() ?? '';
        final status = (row['status'] as String?)?.trim() ?? '';
        if (pid.isEmpty || status.isEmpty) continue;
        members.add(
          PeerHistoryGroupMember(
            profileId: pid,
            status: status,
            role: ((row['role'] as String?)?.trim().isNotEmpty == true)
                ? (row['role'] as String).trim()
                : 'member',
            tag: (row['tag'] as String?)?.trim(),
            createdAtMs: toIntNullable(row['created_at_ms']),
            updatedAtMs: toIntNullable(row['updated_at_ms']),
          ),
        );
      }

      return PeerHistoryGroupMeta(
        groupId: groupId,
        title: title,
        ownerProfileId: owner,
        description: (settings['description'] as String?)?.trim(),
        pinnedMessageEventId: (settings['pinned_message_event_id'] as String?)
            ?.trim(),
        reactionsMode:
            ((settings['reactions_mode'] as String?)?.trim().isNotEmpty == true)
            ? (settings['reactions_mode'] as String).trim()
            : 'all',
        allowText: flag(settings['allow_text'], true),
        allowMedia: flag(settings['allow_media'], true),
        allowAddMembers: flag(settings['allow_add_members'], true),
        allowPinMessages: flag(settings['allow_pin_messages'], true),
        allowChangeGroupInfo: flag(settings['allow_change_group_info'], true),
        allowChangeTag: flag(settings['allow_change_tag'], false),
        joinApprovalRequired: flag(settings['join_approval_required'], false),
        slowModeSeconds: toInt(settings['slow_mode_seconds'], 0),
        chatHistoryVisible: flag(settings['chat_history_visible'], false),
        membershipVersion: toInt(settings['membership_version'], 0),
        stateVersion: toInt(settings['state_version'], 0),
        createdAtMs: toIntNullable(settings['created_at_ms']),
        updatedAtMs: toIntNullable(settings['updated_at_ms']),
        members: members,
      );
    } catch (e) {
      callLog('AppCtrl', '_buildPeerHistoryGroupMeta failed for $groupId: $e');
      return null;
    }
  }

  /// Desktop-side chunk applier. Each event in the chunk is decoded as a
  /// canonical [E2ePayloadV1] (to reject malformed payloads from a
  /// compromised own-device), re-encrypted with the local crypto key, and
  /// inserted via `db.insertEvent(..., ConflictAlgorithm.ignore)` so a
  /// later relay redelivery is a silent no-op.
  ///
  /// Called only from the dispatch hook above; gated on `senderIsOwn`
  /// there.
  Future<void> _applyPeerHistoryChunk({
    required PeerHistoryChunk chunk,
    required String senderDeviceId,
  }) async {
    final db = _db;
    final crypto = _crypto;
    if (db == null || crypto == null) return;

    // PR6: hydrate group rooms first, *before* their events arrive. The
    // responder ships a [PeerHistoryGroupMeta] snapshot for each group
    // appearing in this request — we materialize the conversation row,
    // settings, and membership roster so subsequent `db.insertEvent`
    // calls don't leave the chat list empty (no conversation row → the
    // event is unreachable from the sidebar).
    //
    // Each apply is best-effort: a failure for one group never blocks
    // events for *other* groups in the same chunk.
    for (final meta in chunk.groupMetas) {
      await _applyPeerHistoryGroupMeta(meta);
    }

    if (chunk.events.isEmpty) {
      _peerHistoryLastChunkAtMs = DateTime.now().millisecondsSinceEpoch;
      _changed.add(null);
      return;
    }

    final myPid = (_profileId ?? '').trim();
    var inserted = 0;
    for (final ev in chunk.events) {
      // Skip rows that already exist locally — cheap pre-check so we
      // don't burn CPU re-encrypting payloads that conflictAlgorithm
      // would just throw away.
      try {
        final existing = await db.eventGet(ev.eventId);
        if (existing != null) continue;
      } catch (_) {
        // Best-effort; fall through and let insertEvent dedup.
      }

      // 🔴 СВЕРКА ПО ЛОГИЧЕСКОМУ ID, А НЕ ТОЛЬКО ПО КЛЮЧУ СТРОКИ (24.09.2026).
      //
      // Входящее личное сообщение лежит под `event_id = msgId` — id КОНВЕРТА
      // реле, а у каждого устройства свой конверт. Одно и то же сообщение у
      // телефона и у ПК оказывалось под разными ключами, проверка выше его не
      // узнавала, и синхронизация истории — она просит «последние 250», то
      // есть ровно то, что уже пришло вживую, — клала второй экземпляр.
      // Владелец увидел это как «сообщения через какое-то время задвоились».
      //
      // Живой приём это правило соблюдал давно (`apply_dedup_payload` при
      // записи входящего); здесь оно просто не было применено. Сверяем с
      // ЭТОЙ перепиской: логический id от отправителя одинаков на всех
      // устройствах.
      final payloadId = (ev.payloadEventId ?? '').trim();
      if (payloadId.isNotEmpty) {
        try {
          if (await db.eventExistsForPayload(
            convoId: ev.convoId,
            payloadEventId: payloadId,
          )) {
            continue;
          }
        } catch (_) {
          // Без сверки лучше пропустить событие, чем задвоить его: история
          // догонится следующим циклом.
          continue;
        }
      }

      if (await _shouldDropConversationEventByClearCutoff(
        convoId: ev.convoId,
        createdAtMs: ev.createdAtMs,
      )) {
        continue;
      }

      final Uint8List plain;
      try {
        plain = base64Decode(ev.payloadB64);
      } catch (_) {
        continue;
      }

      // Defensive parse: confirm the bytes really are an E2ePayloadV1
      // before we encrypt+persist. Reject anything that doesn't decode
      // so a buggy responder can't dump arbitrary blobs into our table.
      try {
        E2ePayloadV1.decode(plain);
      } catch (_) {
        continue;
      }

      final String localCipher;
      try {
        localCipher = base64Encode(await crypto.encrypt(plain));
      } catch (_) {
        continue;
      }

      // Derive a local-state if the responder didn't pin one. A row that
      // originated from one of my devices renders as "sent"; otherwise
      // it's an incoming message.
      var localState = ev.localState;
      if (localState == null || localState.isEmpty) {
        localState = (myPid.isNotEmpty && isOwnDeviceId(ev.senderDeviceId))
            ? 'sent'
            : 'received';
      }

      try {
        // Ensure the convo row exists so the chat list reflects the
        // backfilled event.
        //   • 1-to-1 → upsert peer-keyed row.
        //   • group  → the meta loop above is the primary path; this is
        //     a defensive last-resort upsert with an empty title in case
        //     the responder shipped events without a meta (e.g. older
        //     PR5 build talking to a PR6 client). Title will be hydrated
        //     the next time settings sync happens.
        //   • dev:   → skip; managed by self-sync code.
        if (ev.convoId.startsWith('group:')) {
          try {
            final existing = await db.convoGet(ev.convoId);
            if (existing == null) {
              await db.convoEnsureGroup(groupId: ev.convoId, title: '');
            }
          } catch (_) {
            // ignore — insertEvent will still write the event row; UI
            // will hide it until the conversation row materializes.
          }
        } else if (!ev.convoId.startsWith('dev:')) {
          await db.convoEnsure1to1(peerProfileId: ev.convoId);
        }
        await db.insertEvent(
          eventId: ev.eventId,
          convoId: ev.convoId,
          type: ev.type,
          senderDeviceId: ev.senderDeviceId,
          ciphertextB64: localCipher,
          createdAtMs: ev.createdAtMs,
          localState: localState,
          payloadEventId:
              (ev.payloadEventId != null && ev.payloadEventId!.isNotEmpty)
              ? ev.payloadEventId
              : null,
        );
        await db.convoTouch(convoId: ev.convoId, atMs: ev.createdAtMs);
        inserted++;
      } catch (e) {
        callLog('AppCtrl', '_applyPeerHistoryChunk insert failed: $e');
      }
    }

    _peerHistoryLastChunkAtMs = DateTime.now().millisecondsSinceEpoch;
    _peerHistoryBackfilledCount += inserted;
    if (inserted > 0) {
      _changed.add(null);
    }
  }

  /// PR6: hydrate a single group room from a [PeerHistoryGroupMeta].
  /// Writes (in order):
  ///   1. `conversations` row via `convoEnsureGroup` (idempotent, preserves
  ///      `created_at_ms` and `last_event_at_ms` when the row already
  ///      existed),
  ///   2. `group_settings` via `groupSettingsUpsert` (full row replace —
  ///      mobile is the source of truth so a stale local row would only
  ///      ever be wrong; this resyncs reactions_mode, allow_* flags, and
  ///      membership_version),
  ///   3. one `group_memberships` row per `meta.members[i]` via
  ///      `groupMembershipStateUpsert` (which also rebuilds the legacy
  ///      `group_members` projection inside its transaction).
  ///
  /// Best-effort. Each step is wrapped in its own try/catch so a corrupt
  /// member row doesn't take down the whole snapshot apply.
  Future<void> _applyPeerHistoryGroupMeta(PeerHistoryGroupMeta meta) async {
    final db = _db;
    if (db == null) return;
    final groupId = meta.groupId.trim();
    if (groupId.isEmpty || !groupId.startsWith('group:')) return;

    // PR7: state_version race guard. If we already hold a newer or
    // equal snapshot locally (e.g. a real-time `group.settings_update`
    // landed between request and response, or a previous applier
    // already ran for this room) — do NOT overwrite.
    //
    // The comparison is two-axis: both `state_version` and
    // `membership_version` must be strictly older than what the
    // responder shipped. Either axis being older alone means we have
    // partial-fresh state and should still take the snapshot — mobile
    // is the source of truth for everything except things we'd lose.
    //
    // We still do the `convoEnsureGroup` because that row is needed
    // for events to render even when settings are already fresher.
    try {
      await db.convoEnsureGroup(groupId: groupId, title: meta.title);
    } catch (e) {
      callLog(
        'AppCtrl',
        '_applyPeerHistoryGroupMeta convoEnsureGroup failed: $e',
      );
    }

    var skipSettings = false;
    var skipMembers = false;
    try {
      final existing = await db.groupSettingsGet(groupId);
      if (existing != null) {
        final localState = (existing['state_version'] as num?)?.toInt() ?? 0;
        final localMembership =
            (existing['membership_version'] as num?)?.toInt() ?? 0;
        if (localState >= meta.stateVersion && localState > 0) {
          skipSettings = true;
        }
        if (localMembership >= meta.membershipVersion && localMembership > 0) {
          skipMembers = true;
        }
      }
    } catch (e) {
      callLog(
        'AppCtrl',
        '_applyPeerHistoryGroupMeta version probe failed (will apply): $e',
      );
    }

    if (!skipSettings) {
      try {
        await db.groupSettingsUpsert(
          groupId: groupId,
          ownerProfileId: meta.ownerProfileId,
          description: meta.description,
          pinnedMessageEventId: meta.pinnedMessageEventId,
          reactionsMode: meta.reactionsMode,
          allowText: meta.allowText,
          allowMedia: meta.allowMedia,
          allowAddMembers: meta.allowAddMembers,
          allowPinMessages: meta.allowPinMessages,
          allowChangeGroupInfo: meta.allowChangeGroupInfo,
          allowChangeTag: meta.allowChangeTag,
          joinApprovalRequired: meta.joinApprovalRequired,
          slowModeSeconds: meta.slowModeSeconds,
          chatHistoryVisible: meta.chatHistoryVisible,
          membershipVersion: meta.membershipVersion,
          stateVersion: meta.stateVersion,
        );
      } catch (e) {
        callLog(
          'AppCtrl',
          '_applyPeerHistoryGroupMeta groupSettingsUpsert failed: $e',
        );
      }
    } else {
      callLog(
        'AppCtrl',
        '_applyPeerHistoryGroupMeta: skipping settings for $groupId '
            '(local state_version is newer or equal)',
      );
    }

    if (!skipMembers) {
      for (final member in meta.members) {
        try {
          await db.groupMembershipStateUpsert(
            groupId: groupId,
            profileId: member.profileId,
            status: member.status,
            role: member.role,
            tag: member.tag,
            createdAtMs: member.createdAtMs,
            updatedAtMs: member.updatedAtMs,
          );
        } catch (e) {
          callLog(
            'AppCtrl',
            '_applyPeerHistoryGroupMeta member upsert failed: $e',
          );
        }
      }
    } else {
      callLog(
        'AppCtrl',
        '_applyPeerHistoryGroupMeta: skipping members for $groupId '
            '(local membership_version is newer or equal)',
      );
    }
    _peerHistoryGroupsHydrated += 1;
  }

  /// PR6 metrics — number of events successfully written by
  /// [_applyPeerHistoryChunk] this process. Exposed via getter for the
  /// debug console / future "Last sync: N events" affordance.
  int _peerHistoryBackfilledCount = 0;

  /// PR6 metrics — number of group rooms hydrated from a peer.
  int _peerHistoryGroupsHydrated = 0;

  /// Total events written to the local DB by all peer-history chunks
  /// this process. Useful for the debug console and the optional "Sync
  /// History" affordance in Settings.
  int get peerHistoryBackfilledCount => _peerHistoryBackfilledCount;

  /// Number of distinct group rooms whose metadata has been applied
  /// this process. A single request can ship multiple groups; we count
  /// each group exactly once (the responder dedupes).
  int get peerHistoryGroupsHydrated => _peerHistoryGroupsHydrated;

  /// Last time we ingested *any* peer-history chunk (success or empty
  /// tail). Read by `PeerHistoryService` to decide whether the request
  /// is making progress and to drop the in-flight token. Public via
  /// [peerHistoryLastChunkAtMs] getter below so the service doesn't
  /// have to reach into private state.
  int _peerHistoryLastChunkAtMs = 0;

  /// Public accessor for [PeerHistoryService] (see
  /// `lib/sync/peer_history_service.dart`). Returns 0 if we have never
  /// received a chunk in this process lifetime.
  int get peerHistoryLastChunkAtMs => _peerHistoryLastChunkAtMs;

  /// Build + ship a [PeerHistoryRequest] to all of my other devices
  /// (excluding this one). Called by the desktop orchestrator —
  /// keeping the actual `sendControlMessage` plumbing here means
  /// `PeerHistoryService` doesn't have to learn about device-id
  /// enumeration.
  Future<void> requestPeerHistory({
    required String requestId,
    int? sinceMs,
    int? untilMs,
    int limit = kPeerHistoryMaxEventsPerChunk,
    String? cursor,
    String? convoId,
  }) async {
    final pid = (_profileId ?? '').trim();
    final did = (_deviceId ?? '').trim();
    if (pid.isEmpty || did.isEmpty || pid.startsWith('LOCAL-')) return;

    var ownTargets = <String>[];
    try {
      ownTargets = await _listRecipientDevicesForSend(
        peerProfileId: pid,
        selfDeviceId: did,
      );
    } catch (_) {
      ownTargets = const <String>[];
    }
    if (ownTargets.isEmpty) return;

    final req = PeerHistoryRequest(
      requestId: requestId,
      convoId: convoId,
      sinceMs: sinceMs,
      untilMs: untilMs,
      limit: limit,
      cursor: cursor,
    );
    final cmd = encodePeerHistoryRequest(req);
    try {
      await sendControlMessage(
        peerProfileId: pid,
        controlText: cmd,
        strict: false,
        forceRelayFlush: false,
        targetDeviceIds: ownTargets,
      );
    } catch (e) {
      callLog('AppCtrl', 'requestPeerHistory send failed: $e');
    }
  }

  /// Устройства получателя, из-за которых отправку надо остановить и спросить
  /// человека. Пустой список — отправлять можно.
  ///
  /// Две политики, и путать их нельзя:
  ///
  ///  * **Строгий режим** ([blockUnverified], по умолчанию ВЫКЛЮЧЕН) — как было
  ///    всегда: любое неподтверждённое устройство запирает отправку. Осознанный
  ///    выбор пользователя, который готов сверять код с каждым.
  ///  * **Обычный режим** — модель Signal. Пока человека ни разу не проверяли,
  ///    смена ключей это СОБЫТИЕ В ПЕРЕПИСКЕ, а не преграда: предупреждать
  ///    некого и не о чем — сверять новый код не с чем, старый никто не видел.
  ///    Останавливаемся только у тех, кого пользователь однажды подтвердил
  ///    лично: там смена ключа означает, что подтверждённое перестало быть
  ///    подтверждённым, и сказать об этом надо — но РОВНО ОДИН РАЗ, потому что
  ///    «отправить всё равно» проставляет [approved_at_ms].
  ///
  /// Прежнее поведение (запирать всех подряд) при включённой ротации личности
  /// И-1 срабатывало постоянно: ротация выглядит как новое устройство, а новое
  /// устройство неподтверждено по определению.
  Future<List<String>> _sendGateBlockingDevices(
    String peerProfileId,
    Iterable<String> targets,
  ) async {
    final wanted = targets
        .map((d) => d.trim())
        .where((d) => d.isNotEmpty)
        .toList(growable: false);
    if (wanted.isEmpty) return const <String>[];
    final db = _db;
    if (db == null) return const <String>[];

    final strict = _blockUnverified;
    if (!strict) {
      // 🔴 Направление отказа выбрано осознанно. Это не проверка безопасности,
      // а проверка того, ПРИМЕНЯЕТСЯ ли проверка безопасности. Ошибка здесь,
      // истолкованная «в закрытую», поставила бы тревожное «проверьте, чтобы
      // продолжить» перед людьми, которые никогда ничего не проверяли, — то
      // есть превратила бы сбой БД ровно в тот испуг, который мы убираем. Цена
      // обратного истолкования — одно пропущенное предупреждение у одного
      // сообщения. Кому нужна жёсткая гарантия, включает строгий режим.
      bool everVerified;
      try {
        everVerified = await db.contactWasEverVerified(peerProfileId);
      } catch (e) {
        callLog(
          'AppCtrl',
          'verification-state lookup failed profile=$peerProfileId: $e',
        );
        return const <String>[];
      }
      if (!everVerified) return const <String>[];
    }

    // Дальше отказ ТОЛЬКО в закрытую: политика включена, и если не удаётся
    // доказать пригодность ключа — не отправляем. Исключение уходит наверх,
    // как и раньше.
    await _refreshContactDevicesForVerification(peerProfileId);
    final cached = await db.contactDevicesList(peerProfileId);
    final acceptable = <String>{
      for (final r in cached)
        if ((r['verified_at_ms'] as num?) != null ||
            (!strict && (r['approved_at_ms'] as num?) != null))
          (r['device_id'] as String),
    };
    return wanted.where((d) => !acceptable.contains(d)).toList(growable: false);
  }

  /// «Отправить всё равно»: помечает пригодными все ключи контакта, которые
  /// сейчас держат отправку. Отметка снимается сама, когда ключ снова сменится.
  Future<void> approveUnverifiedContactDevices(String peerProfileId) async {
    final db = _db;
    if (db == null) return;
    final cached = await db.contactDevicesList(peerProfileId);
    for (final r in cached) {
      if ((r['verified_at_ms'] as num?) != null) continue;
      final deviceId = (r['device_id'] as String?)?.trim() ?? '';
      if (deviceId.isEmpty) continue;
      await db.contactDeviceMarkApproved(
        profileId: peerProfileId,
        deviceId: deviceId,
      );
    }
    DiagLog.event('peer', 'unverified_devices_approved', {
      'peer': DiagLog.pfx(peerProfileId),
    });
  }

  /// Проверял ли пользователь этого человека хоть раз — от этого зависит, о чём
  /// вообще говорить в диалоге о смене номера.
  /// Ш-1 слоя 2 «номер безопасности на человека»: СМОТРИМ и ПИШЕМ В ЖУРНАЛ.
  ///
  /// 🔴 ЭТОТ МЕТОД НИЧЕГО НЕ РЕШАЕТ. Ни одно его наблюдение не меняет ни
  /// поведения предупреждения о смене номера, ни сессий, ни доставки. Так
  /// задумано: сначала измерить, потом решать. Ровно та дисциплина, которой не
  /// хватило 06.08, когда я поставил условие «неделю считать события», не
  /// проверив, есть ли чем считать (`DiagLog` — ограничитель частоты вывода, а не
  /// накопитель). Ш-1 и есть недостающий прибор.
  ///
  /// Что мы хотим узнать из журнала: как часто «новое устройство контакта»
  /// оказывается ТЕМ ЖЕ человеком. Каждое такое совпадение — предупреждение,
  /// которое слой 2 уберёт. Единицы за неделю — работу можно отложить; десятки —
  /// она обязательна.
  ///
  /// 🔴 Отказ полностью беззвучный: любое исключение съедается. Этот метод стоит
  /// на пути ОБНОВЛЕНИЯ УСТРОЙСТВ КОНТАКТА, то есть на пути доставки. Уронить её
  /// ради наблюдения было бы обменом непоправимого на любопытство.
  Future<void> _observeAccountCertificate({
    required String peerProfileId,
    required String deviceId,
    required String deviceIdentityPubB64,
    required String? accountIdentityPubB64,
    required String? deviceCertB64,
  }) async {
    try {
      final db = _db;
      if (db == null) return;
      final aik = accountIdentityPubB64?.trim() ?? '';
      final cert = deviceCertB64?.trim() ?? '';

      if (aik.isEmpty || cert.isEmpty) {
        // Сборка контакта старше слоя 2. Это большинство, и это нормально —
        // счётчик нужен, чтобы знать, когда большинство станет меньшинством.
        DiagLog.event('acct', 'account_cert_absent', <String, Object?>{
          'peer': DiagLog.pfx(peerProfileId),
        });
        await db.localKvCounterInc(AppDb.kvAcctCertAbsent);
        return;
      }

      final pinned = await db.contactAccountIdentityPinned(peerProfileId);
      if (pinned == null) {
        // Первое знакомство: закрепляем (TOFU). Проверять пока не с чем — любая
        // «проверка» против только что полученного ключа доказывала бы лишь то,
        // что сервер умеет складывать пару, а не что это тот же человек.
        final ok = await db.contactAccountIdentityPinIfAbsent(
          profileId: peerProfileId,
          accountIdentityPubB64: aik,
        );
        DiagLog.event('acct', 'account_key_pinned', <String, Object?>{
          'peer': DiagLog.pfx(peerProfileId),
          'stored': ok,
        });
        return;
      }

      if (pinned != aik) {
        // 🔴 Вот это и есть НАСТОЯЩАЯ смена номера безопасности — та, о которой
        // предупреждать стоит. Сегодня мы лишь считаем такие случаи, чтобы
        // понимать, сколько предупреждений останется после слоя 2.
        DiagLog.event('acct', 'account_key_changed', <String, Object?>{
          'peer': DiagLog.pfx(peerProfileId),
        });
        await db.localKvCounterInc(AppDb.kvAcctKeyChanged);
        return;
      }

      final verified = await AccountIdentity.verifyDeviceCertificate(
        accountPubB64: pinned,
        certificateB64: cert,
        profileId: peerProfileId,
        deviceId: deviceId,
        deviceIdentityPubB64: deviceIdentityPubB64,
      );
      // `account_cert_ok` — то самое число, ради которого всё это. Каждое такое
      // событие на НОВОМ устройстве контакта означает предупреждение, которое
      // слой 2 снимет, не ослабляя защиты.
      DiagLog.event(
        'acct',
        verified ? 'account_cert_ok' : 'account_cert_bad',
        <String, Object?>{'peer': DiagLog.pfx(peerProfileId)},
      );
      // 🔴 Считаем НА ДИСКЕ, а не только в журнале: журнал кольцевой, а именно
      // эта цифра решает, можно ли включать Ш-3. Плохой сертификат вдвойне —
      // он редкий и означает либо ошибку, либо подмену; терять его нельзя.
      await db.localKvCounterInc(
        verified ? AppDb.kvAcctCertOk : AppDb.kvAcctCertBad,
      );
    } catch (e) {
      // Наблюдение не имеет права стоить доставки.
      DiagLog.event('acct', 'account_cert_observe_failed', <String, Object?>{
        'reason': e.runtimeType.toString(),
      });
    }
  }

  Future<bool> contactWasEverVerified(String peerProfileId) async {
    final db = _db;
    if (db == null) return false;
    try {
      return await db.contactWasEverVerified(peerProfileId);
    } catch (_) {
      return false;
    }
  }

  /// Narrow [deviceIds] to the peer devices this send is allowed to reach.
  ///
  /// SECURITY (2026-07-28): the fanout refresh-retry re-resolves the peer's
  /// devices from the keys server after a per-device encrypt failure. A device
  /// discovered by that refresh is unverified BY DEFINITION, so enqueuing to it
  /// directly would bypass the very gate the pre-fanout check applied — that
  /// check only ever saw the ORIGINAL target list. Every retry path runs its
  /// fresh targets through here first. Gate not engaged ⇒ returns the list
  /// unchanged (identical behavior to before).
  Future<List<String>> _verifiedTargetsOnly(
    String peerProfileId,
    List<String> deviceIds,
  ) async {
    if (deviceIds.isEmpty) return deviceIds;
    try {
      final blocking = await _sendGateBlockingDevices(peerProfileId, deviceIds);
      if (blocking.isEmpty) return deviceIds;
      final blocked = blocking.toSet();
      return deviceIds
          .where((d) => !blocked.contains(d))
          .toList(growable: false);
    } catch (_) {
      // Fail CLOSED: if we cannot prove the targets are allowed, send nothing
      // new. This is the retry path — dropping the extra targets loses nothing
      // the original send did not already deliver.
      return const <String>[];
    }
  }

  Future<void> _enqueueExistingOutgoingPayload({
    required String localEventId,
    required String peerProfileId,
    required Uint8List payloadBytes,
    required int queueCreatedAtMs,
  }) async {
    final db = _db;
    if (db == null) {
      throw _transportUnavailableStateError('Message send unavailable');
    }
    if (!await ensureOutgoingTransportReady()) {
      throw _transportUnavailableStateError('Message send unavailable');
    }

    final relay = _relay;
    final keys = _keys;
    final ratchet = _ratchetV3;
    final did = _deviceId;
    if (relay == null || keys == null || ratchet == null || did == null) {
      throw _transportUnavailableStateError('Message send unavailable');
    }

    _throwIfTransportBlocked();

    final targets = await _listRecipientDevicesForSend(
      peerProfileId: peerProfileId,
      selfDeviceId: did,
    );
    if (targets.isEmpty) {
      var exists = false;
      try {
        exists = await keys.profileExists(peerProfileId);
      } catch (_) {
        // ignore
      }
      if (!exists) {
        throw StateError(
          'Recipient profile not found on server. Check Secretly ID / ensure both use the same server. (peer_profile_id=$peerProfileId)',
        );
      }

      await _queuePendingNoDeviceEntry(
        profileId: peerProfileId,
        entry: _PendingNoDeviceEntry(
          localEventId: localEventId,
          payloadBytes: Uint8List.fromList(payloadBytes),
          createdAtMs: queueCreatedAtMs,
        ),
      );
      _changed.add(null);
      return;
    }

    await _flushPendingNoDeviceEntries(
      profileId: peerProfileId,
      targets: targets,
      selfDeviceId: did,
      db: db,
      ratchet: ratchet,
      relay: relay,
      nowMs: queueCreatedAtMs,
    );

    final blocking = await _sendGateBlockingDevices(peerProfileId, targets);
    if (blocking.isNotEmpty) {
      throw StateError(
        'Contact is unverified (devices: ${blocking.take(3).join(', ')}${blocking.length > 3 ? '…' : ''}). Open chat → Verify.',
      );
    }
    final validTargets = targets;

    var queuedTargets = 0;
    var fanoutSkipped = 0;
    final queuedDeviceIds = <String>{};

    Future<void> enqueueToDevice(String toDeviceId) async {
      final msgId = _uuid.v4();
      final wire = await _encryptToPeerSerialized(
        ratchet: ratchet,
        selfDeviceId: did,
        peerProfileId: peerProfileId,
        peerDeviceId: toDeviceId,
        plaintext: Uint8List.fromList(payloadBytes),
      );
      await db.outboxUpsert(
        msgId: msgId,
        toDeviceId: toDeviceId,
        ciphertextB64: base64Encode(wire),
        ttlSeconds: _outboxUserMessageTtlSeconds,
        state: OutboxSendState.pending,
        attemptCount: 0,
        nextRetryAtMs: queueCreatedAtMs,
        createdAtMs: queueCreatedAtMs,
        correlationId: localEventId,
        convoId: peerProfileId,
        eventIdRef: localEventId,
        expiresAtMs: queueCreatedAtMs + _outboxUserMessageTtlMs,
      );
      queuedTargets++;
      queuedDeviceIds.add(toDeviceId);
    }

    for (final toDeviceId in validTargets) {
      try {
        await enqueueToDevice(toDeviceId);
      } catch (e) {
        fanoutSkipped++;
        // Was `callLog`, which is COMPILED OUT of release builds — in the field
        // the real per-target reason vanished and the user only ever saw the
        // generic "all fanout attempts failed" (2026-07-28 tester report).
        DiagLog.event('send', 'fanout_target_skip', {
          'peer': DiagLog.pfx(peerProfileId),
          'to_dev': DiagLog.pfx(toDeviceId),
          'reason': _classifyShortReason(e),
        });
      }
    }

    // FIX (2026-07-28): same refresh-retry the primary send path already has.
    // A per-device encrypt failure here is most often "peer device not found in
    // bundle" — our cached device_id rotated (reinstall / DB quarantine) and the
    // keys server no longer serves a bundle for it. Without a retry this path,
    // which is what REPAIRS a previously failed send, could never recover: the
    // message stayed failed forever. Re-resolve the peer's devices once and
    // enqueue to every live device we haven't reached yet.
    if (fanoutSkipped > 0 || queuedTargets == 0) {
      try {
        unawaited(refreshContactDevices(peerProfileId).catchError((_) {}));
        final freshTargets = await _verifiedTargetsOnly(
          peerProfileId,
          await _listRecipientDevicesForSend(
            peerProfileId: peerProfileId,
            selfDeviceId: did,
            forceRefresh: true,
          ),
        );
        for (final toDeviceId in freshTargets) {
          if (queuedDeviceIds.contains(toDeviceId)) continue;
          try {
            await enqueueToDevice(toDeviceId);
            DiagLog.event('send', 'fanout_retry_ok', {
              'peer': DiagLog.pfx(peerProfileId),
              'to_dev': DiagLog.pfx(toDeviceId),
            });
          } catch (e) {
            DiagLog.event('send', 'fanout_retry_skip', {
              'peer': DiagLog.pfx(peerProfileId),
              'to_dev': DiagLog.pfx(toDeviceId),
              'reason': _classifyShortReason(e),
            });
          }
        }
      } catch (_) {
        // best-effort refresh-retry; fall through to the queuedTargets check
      }
    }

    if (queuedTargets == 0) {
      throw StateError(
        'No deliverable target devices for recipient (all fanout attempts failed).',
      );
    }

    await db.updateEventLocalState(
      eventId: localEventId,
      localState: MessageLocalState.pending,
      reasonCode: MessageFailureReason.manualRetry,
    );
    _changed.add(null);
    _kickRelayOutbox(relay);
  }

  Future<void> cancelOutgoingEventSend({required String localEventId}) async {
    final db = _db;
    if (db == null) {
      throw StateError(
        'Message cancel unavailable: local database is not ready',
      );
    }

    await _retryDbBusy(() async {
      await db.outboxDeleteForEventRef(localEventId);
      await db.pendingNoDeviceSendDelete(localEventId);
      await db.updateEventLocalState(
        eventId: localEventId,
        localState: MessageLocalState.failed,
        reasonCode: MessageFailureReason.cancelled,
      );
    });
    _removePendingNoDeviceEntryFromMemory(localEventId);
    _changed.add(null);
  }

  Future<void> retryOutgoingEventSend({required String localEventId}) async {
    final db = _db;
    if (db == null) {
      throw StateError(
        'Message retry unavailable: local database is not ready',
      );
    }

    final row = await db.eventGet(localEventId);
    if (row == null) {
      throw StateError('Message retry unavailable: local event not found');
    }

    final senderDeviceId = (row['sender_device_id'] as String? ?? '').trim();
    if (!isOwnDeviceId(senderDeviceId)) {
      throw StateError('Only outgoing messages can be retried');
    }

    final convoId = (row['convo_id'] as String? ?? '').trim();

    // A4: a room/group message fans out per member, so it can't go through the
    // single-peer 1:1 retry (`_resolvePeerProfileIdForConvoId` throws for a
    // `group:` convo). Rebuild the fanout from the stored local payload — the
    // same proven re-dispatch the scheduled-group-retry path uses — instead of
    // leaving "tap to retry" dead in rooms.
    if (convoId.startsWith('group:')) {
      await _retryOutgoingGroupEventSend(
        localEventId: localEventId,
        groupId: convoId,
      );
      return;
    }

    final peerProfileId = await _resolvePeerProfileIdForConvoId(convoId);
    final payloadBytes = await _decryptStoredLocalPayloadBytes(localEventId);
    if (payloadBytes == null || payloadBytes.isEmpty) {
      throw StateError('Message retry unavailable: local payload is missing');
    }

    final now = DateTime.now().millisecondsSinceEpoch;
    await _retryDbBusy(() async {
      await db.outboxDeleteForEventRef(localEventId);
      await db.pendingNoDeviceSendDelete(localEventId);
      await db.updateEventLocalState(
        eventId: localEventId,
        localState: MessageLocalState.pending,
        reasonCode: MessageFailureReason.manualRetry,
      );
    });
    _removePendingNoDeviceEntryFromMemory(localEventId);

    await _enqueueExistingOutgoingPayload(
      localEventId: localEventId,
      peerProfileId: peerProfileId,
      payloadBytes: payloadBytes,
      queueCreatedAtMs: now,
    );
  }

  /// A4: manual "tap to retry" for a failed GROUP/room message. The 1:1 path
  /// re-enqueues a single peer's payload; a room message instead fans a control
  /// envelope out to every current member, so we rebuild that fanout from the
  /// stored local payload (mirroring the scheduled-group-retry path) rather than
  /// throwing "retry unavailable for this conversation".
  Future<void> _retryOutgoingGroupEventSend({
    required String localEventId,
    required String groupId,
  }) async {
    final db = _db;
    if (db == null) {
      throw StateError(
        'Message retry unavailable: local database is not ready',
      );
    }
    final payloadBytes = await _decryptStoredLocalPayloadBytes(localEventId);
    if (payloadBytes == null || payloadBytes.isEmpty) {
      throw StateError('Message retry unavailable: local payload is missing');
    }
    final payload = E2ePayloadV1.decode(payloadBytes);
    MsgEventV1? textEvent;
    for (final ev in payload.events) {
      if (ev is MsgEventV1) {
        textEvent = ev;
        break;
      }
    }

    if (textEvent != null) {
      // Clear the failed row's transport state, then re-fan through the
      // authoritative group path — which mints a fresh bubble — and drop the
      // stale failed bubble so only one remains. A dispatch failure (room policy
      // / relay admission) rethrows with the old bubble intact, so nothing is
      // lost and the user can retry again.
      await _retryDbBusy(() async {
        await db.outboxDeleteForEventRef(localEventId);
        await db.pendingNoDeviceSendDelete(localEventId);
      });
      _removePendingNoDeviceEntryFromMemory(localEventId);
      await _dispatchGroupMessageNow(
        groupId: groupId,
        text: textEvent.text,
        replyToPayloadEventId: textEvent.replyToEventId,
        mentions: textEvent.mentions,
        topicId: textEvent.topicId,
        linkPreview: textEvent.linkPreview,
      );
      await db.deleteEventsByIds([localEventId]);
      _changed.add(null);
      return;
    }

    // Attachment / sticker group message: its content lives in a blob the text
    // re-dispatch can't rebuild. Re-arm the event to pending and re-kick the
    // transport so the existing outbox rows + the durable no-device backstop
    // (A2) re-drive delivery to any members still lacking an ack.
    await _retryDbBusy(() async {
      await db.updateEventLocalState(
        eventId: localEventId,
        localState: MessageLocalState.pending,
        reasonCode: MessageFailureReason.manualRetry,
      );
    });
    _kickRelayOutbox();
    _changed.add(null);
  }

  Future<void> _refreshKnownOwnDeviceIdsFromServer() async {
    final db = _db;
    final pid = (_profileId ?? '').trim();
    if (db == null || pid.isEmpty || pid.startsWith('LOCAL-')) return;
    if (_transportBlocked) return;
    try {
      final ids = await _listDevicesAuthed(pid);
      for (final did in ids) {
        final clean = did.trim();
        if (clean.isEmpty) continue;
        _knownOwnDeviceIds.add(clean);
        await db.deviceProfileUpsert(deviceId: clean, profileId: pid);
      }
      // 🔴 Запоминаем НА ДИСК, а не только в памяти. Сервер помнит устройства
      // профиля лишь пока они не вытеснены; узнанный однажды свой id обязан
      // остаться своим и после вытеснения, иначе старые сообщения этого
      // устройства снова начнут выглядеть чужими.
      await _rememberOwnDeviceIds(ids);
    } catch (_) {
      // ignore transient network/rate-limit errors.
    }

    // ------------------------------------------------------------------------
    // 2026-05-19 — close the self-fanout gap documented in
    // docs/BUG_AUDIT.md §2026-05-19 ADDENDUM cause B.
    //
    // The block above populates `device_profiles` (used by the receive gate
    // `isOwnDeviceId`) and the in-memory set `_knownOwnDeviceIds`.
    // It does NOT populate `contact_devices` — the table read by
    // `_listRecipientDevicesForSend` on the send path.
    //
    // Without this extra refresh, `_mirrorTextMessageToOwnDevices` resolves
    // an empty target list when sending to own pid, the early-return at
    // line ~21684 trips, and the self-mirror control message is silently
    // dropped before it even reaches the relay outbox.
    //
    // `refreshContactDevices(myPid)` fetches our own profile's full key
    // bundles (identity_key, signed_prekey, sig) and upserts each device
    // into `contact_devices`. Future self-fanout resolves correctly without
    // a race.
    //
    // Wrapped in its own try/catch because this method is best-effort —
    // the previous block may have already populated some state; we must
    // not let a contact-devices error nuke the partial progress above.
    try {
      await refreshContactDevices(pid);
      // Invalidate the in-memory recipient cache for own pid so the next
      // send (which may run immediately after this call returns) re-reads
      // the freshly-populated `contact_devices` rows.
      _recipientDevicesCacheByProfileId.remove(pid);
    } catch (_) {
      // ignore — `_listRecipientDevicesForSend` retries on its own TTL when
      // a fanout actually needs the data.
    }
  }

  // ---------------------------------------------------------------------------
  // 2026-05-19 — mobile-side post-pairing nudge.
  //
  // After the mobile approves a QR pairing, the desktop's apply flow generates
  // a fresh `device_id` (uuid.v4) and re-registers with the keys server. That
  // registration is NOT visible to the mobile at the moment the bundle is sent
  // — there is a window of a few seconds where the keys server is being
  // populated.
  //
  // Without an explicit refresh, the mobile's next `_listRecipientDevicesForSend`
  // for its own profile would hit the 3-minute cache TTL with the stale (pre-
  // pairing) device set, and self-fanout to the freshly-paired desktop would
  // silently no-op until the cache expires or the user happens to send to the
  // peer profile (which forces a per-peer refresh, but not for own pid).
  //
  // This helper schedules a few delayed refresh attempts after pairing with an
  // exponential-ish backoff so we converge on the desktop's new device id
  // regardless of how slow the desktop is.
  //
  // Called best-effort (unawaited) from `approveDesktopLinkFromQr` after the
  // bundle is dispatched. See docs/FIX_TZ.md §2026-05-19 Bidirectional PC↔phone
  // sync fix step 4.
  Future<void> _schedulePostPairingOwnDeviceRefresh() async {
    const delaysMs = <int>[3000, 8000, 20000];
    for (final delayMs in delaysMs) {
      await Future<void>.delayed(Duration(milliseconds: delayMs));
      // _changed is closed on dispose — bail out so we don't fire timers
      // against a torn-down controller.
      if (_changed.isClosed) return;
      try {
        await _refreshKnownOwnDeviceIdsFromServer();
      } catch (_) {
        // best-effort
      }
    }
  }

  Future<void> _mirrorTextMessageToOwnDevices({
    required String convoId,
    required String messageText,
    required String payloadEventId,
    required int createdAtMs,
    String? replyToPayloadEventId,
    LinkPreviewV1? linkPreview,
  }) async {
    final pid = (_profileId ?? '').trim();
    final did = (_deviceId ?? '').trim();
    if (pid.isEmpty || pid.startsWith('LOCAL-') || did.isEmpty) return;
    final normalizedConvoId = convoId.trim();
    if (normalizedConvoId.isEmpty || normalizedConvoId.startsWith('group:')) {
      return;
    }

    var ownTargets = <String>[];
    try {
      ownTargets = await _listRecipientDevicesForSend(
        peerProfileId: pid,
        selfDeviceId: did,
      );
    } catch (_) {
      return;
    }
    if (ownTargets.isEmpty) return;

    final payload = <String, Object?>{
      'kind': 'msg',
      'convoId': normalizedConvoId,
      'msgEventId': payloadEventId,
      'text': messageText,
      'replyToPayloadEventId': replyToPayloadEventId,
      'createdAtMs': createdAtMs,
      // Своим устройствам — та же карточка, что ушла собеседнику.
      if (linkPreview != null) 'linkPreview': linkPreview.toJson(),
    };
    final cmd =
        '$_selfMirrorMsgCmdPrefix${base64Url.encode(utf8.encode(jsonEncode(payload)))}';

    try {
      await sendControlMessage(
        peerProfileId: pid,
        controlText: cmd,
        strict: false,
        forceRelayFlush: false,
        targetDeviceIds: ownTargets,
      );
    } catch (_) {
      // best-effort only
    }
  }

