  // ---------------------------------------------------------------------------
  // Read-receipt mirror — 2026-05-20 PR-B (BUG-10)
  //
  // Symptom this fixes: «I write from PC, peer reads → PC shows ✓✓, mobile
  // shows ✓ (and vice versa)». Receipts flow peer→me, but never me→my-other-
  // devices, so the read state is visible only on whichever of my devices
  // happened to be online when the peer's ReceiptEventV1 arrived.
  //
  // This helper is invoked from `_applyIncomingReceiptEvents` whenever the
  // peer's receipt actually flipped a local row. It bundles the impacted
  // payload-event-ids by status and ships a `kSelfMirrorReceiptCommandPrefix`
  // command to every other own device via the same self-fanout pattern as
  // `_mirrorTextMessageToOwnDevices`. Best-effort: failures must not block
  // the primary peer receipt-flush.
  //
  // The mirror is **terminal** — when an own device receives it, it applies
  // the state change locally and does NOT re-broadcast. That keeps the
  // (already proven-safe) `receiptFromOwnDevice` guard at line 27712 intact;
  // we use the prefix to carry the new direction instead of loosening the
  // existing gate.
  Future<void> _mirrorReceiptsToOwnDevices({
    required String status,
    required Iterable<String> refPayloadEventIds,
    String? peerProfileId,
  }) async {
    if (_backgroundInboundMode) return; // outbound fan-out; foreground mirrors
    final pid = (_profileId ?? '').trim();
    final did = (_deviceId ?? '').trim();
    if (pid.isEmpty || pid.startsWith('LOCAL-') || did.isEmpty) return;
    final normalizedRefs = refPayloadEventIds
        .map((id) => id.trim())
        .where((id) => id.isNotEmpty)
        .toSet()
        .toList(growable: false);
    if (normalizedRefs.isEmpty) return;
    final normalizedStatus = status.trim();
    if (normalizedStatus.isEmpty) return;

    var ownTargets = <String>[];
    try {
      ownTargets = await _listRecipientDevicesForSend(
        peerProfileId: pid,
        selfDeviceId: did,
      );
    } catch (_) {
      return;
    }
    if (ownTargets.isEmpty) return;

    final command = buildSelfMirrorReceiptCommand(
      refPayloadEventIds: normalizedRefs,
      status: normalizedStatus,
      appliedAtMs: DateTime.now().millisecondsSinceEpoch,
      peerProfileId: peerProfileId,
    );

    try {
      await sendControlMessage(
        peerProfileId: pid,
        controlText: command,
        strict: false,
        forceRelayFlush: false,
        targetDeviceIds: ownTargets,
      );
      DiagLog.event('selfsync', 'receipt_mirror_sent', {
        'status': normalizedStatus,
        'count': normalizedRefs.length,
        'targets': ownTargets.length,
        'peer': DiagLog.pfx(peerProfileId ?? ''),
      });
    } catch (error) {
      // best-effort only — peer receipt already landed at this point.
      DiagLog.event('selfsync', 'receipt_mirror_fail', {
        'status': normalizedStatus,
        'count': normalizedRefs.length,
        'reason': _classifyShortReason(error),
      });
    }
  }

  // ---------------------------------------------------------------------------
  // Group control envelope mirror (Sprint 2 / PR3, TZ §21.x multi-device parity).
  //
  // Group senders (`sendGroupMessage`, sticker, attachment) build a
  // `__secretly_group_msg_v1__:` envelope and fan it out to every group member
  // EXCLUDING the sender's own profile id. That means the sender's OTHER
  // devices never see the message via this fan-out, so my desktop won't show
  // a message I sent from mobile in the same group (and, critically,
  // delete-for-all commands issued from one device don't tombstone messages
  // on my other device).
  //
  // This helper re-uses the SAME control envelope and pushes it to my own
  // other devices over a 1:1 self-fanout (`sendControlMessage(peerProfileId:
  // self)`). The receive-side handler (`_parseGroupMessageCommand` branch
  // around app_controller line 27057) already understands these envelopes
  // and is updated in this PR to mark events as `localState: 'sent'` when
  // the sender device id matches one of my own — so the mirrored message
  // renders as "me sent this", not "received from me".
  //
  // PR3 wires this only into `sendGroupMessage` (which is also the path used
  // by group delete-for-all and group edit). Group sticker / attachment use
  // the same envelope shape and can adopt this helper in a follow-up
  // (Sprint 2 PR3.5) once we're happy with the text/delete behaviour.
  //
  // Best-effort: failures here MUST NOT block the primary peer fanout —
  // they're an enhancement, not a correctness gate.
  Future<void> _mirrorGroupControlEnvelopeToOwnDevices({
    required String controlText,
  }) async {
    final pid = (_profileId ?? '').trim();
    final did = (_deviceId ?? '').trim();
    if (pid.isEmpty || pid.startsWith('LOCAL-') || did.isEmpty) return;
    if (controlText.isEmpty) return;

    var ownTargets = <String>[];
    try {
      ownTargets = await _listRecipientDevicesForSend(
        peerProfileId: pid,
        selfDeviceId: did,
      );
    } catch (_) {
      return;
    }
    if (ownTargets.isEmpty) return;

    try {
      await sendControlMessage(
        peerProfileId: pid,
        controlText: controlText,
        strict: false,
        forceRelayFlush: false,
        targetDeviceIds: ownTargets,
      );
    } catch (_) {
      // best-effort only — primary peer fan-out has already happened.
    }
  }

  /// Кто на самом деле прислал служебную команду (17.09.2026).
  ///
  /// Свой аппарат — мой профиль. Иначе — профиль, установленный по номеру
  /// устройства при приёме (кэш или сервер ключей), а если его нет — владелец
  /// устройства по списку адресатов (`contact_devices`), который мы сами
  /// получали с сервера для отправки. Слова самой команды здесь не участвуют.
  Future<String?> _authenticatedCommandSenderProfileId({
    required AppDb db,
    required String? senderDeviceId,
    required String? senderProfileId,
  }) async {
    final myPid = (_profileId ?? '').trim();
    final did = (senderDeviceId ?? '').trim();
    if (did.isNotEmpty && isOwnDeviceId(did)) {
      return myPid.isEmpty ? null : myPid;
    }
    final resolved = (senderProfileId ?? '').trim();
    if (resolved.isNotEmpty) return resolved;
    if (did.isEmpty) return null;
    try {
      final owners = await db.contactProfilesForDeviceIds(<String>[did]);
      final owner = (owners[did] ?? '').trim();
      return owner.isEmpty ? null : owner;
    } catch (_) {
      return null;
    }
  }

  /// Права участника [senderPid] в комнате [groupId] — по моей копии состава,
  /// а если не хватило, то после досинхронизации у реле (как для сообщений:
  /// новый участник или админ, чей снимок состава ещё не дошёл). Незнакомую
  /// комнату не заводит: для неё прав нет.
  Future<({bool isMember, bool canManageSettings})> _inboundRoomSenderRights({
    required AppDb db,
    required String groupId,
    required String senderPid,
    required bool needManageSettings,
  }) async {
    if (await db.convoGet(groupId) == null) {
      return (isMember: false, canManageSettings: false);
    }
    Future<({bool isMember, bool canManageSettings})> evaluate() async {
      // Без строки настроек `getRoomSettings` создал бы её — со МНОЙ во
      // владельцах. Старую комнату оцениваем только чтением.
      if (await db.groupSettingsGet(groupId) == null) {
        final state = await _roomMembershipStateOrLegacyActive(
          groupId,
          senderPid,
        );
        final isMember =
            state != null &&
            RoomMembershipStatusX.fromValue(state.status) ==
                RoomMembershipStatus.active;
        final admins = (await listGroupAdmins(groupId)).toSet();
        return (
          isMember: isMember,
          canManageSettings: isMember && admins.contains(senderPid),
        );
      }
      final policy = await getRoomPolicyState(
        groupId,
        profileIdOverride: senderPid,
      );
      return (
        isMember: policy.isMember,
        canManageSettings: policy.canManageSettings,
      );
    }

    final rights = await evaluate();
    if (needManageSettings ? rights.canManageSettings : rights.isMember) {
      return rights;
    }
    final settingsRow = await db.groupSettingsGet(groupId);
    final stateVersion = (settingsRow?['state_version'] as num?)?.toInt() ?? 0;
    if (stateVersion <= 0) return rights;
    await _senderIsRoomMemberAfterRelayReconcile(
      groupId,
      senderPid,
      settingsRow,
    );
    return evaluate();
  }

  /// Где хранить пришедшую реакцию, или отказ (17.09.2026). Отказ «пока не
  /// знаем» в известной комнате откладывается, а не теряется.
  ///
  /// Автор — только сам отправитель. Комната — только если он в ней состоит.
  /// Личная переписка — всегда переписка С ОТПРАВИТЕЛЕМ (в команде он пишет
  /// свой взгляд: мой профиль). Сообщение, лежащее в другой переписке, чужое.
  /// Свои аппараты — как прежде: им доверяли и раньше, а корень подделки
  /// «своего» номера закрывается отдельно.
  Future<_InboundCommandVerdict> _authorizedInboundReactionConvoId({
    required AppDb db,
    required String commandConvoId,
    required String eventId,
    required String actorProfileId,
    required String? senderDeviceId,
    required String? senderProfileId,
  }) async {
    _InboundCommandVerdict reject(
      String why, {
      String senderPid = '',
      bool deferrable = false,
    }) {
      DiagLog.event('reaction', 'inbound_rejected', {
        'why': why,
        'deferred': deferrable,
        'sender_dev': DiagLog.pfx((senderDeviceId ?? '').trim()),
        'convo': DiagLog.pfx(commandConvoId),
      });
      return (convoId: null, senderPid: senderPid, deferrable: deferrable);
    }

    final senderPid = await _authenticatedCommandSenderProfileId(
      db: db,
      senderDeviceId: senderDeviceId,
      senderProfileId: senderProfileId,
    );
    // Права нового участника и связка «устройство → профиль» догоняют позже:
    // в известной комнате такой отказ откладывается (A1-парковка).
    final roomKnown =
        commandConvoId.startsWith('group:') &&
        await db.convoGet(commandConvoId) != null;
    if (senderPid == null) {
      return reject('sender_unknown', deferrable: roomKnown);
    }
    if (actorProfileId.trim() != senderPid) return reject('actor_mismatch');
    final myPid = (_profileId ?? '').trim();
    if (senderPid == myPid) {
      return (convoId: commandConvoId, senderPid: senderPid, deferrable: false);
    }

    final String target;
    if (commandConvoId.startsWith('group:')) {
      final rights = await _inboundRoomSenderRights(
        db: db,
        groupId: commandConvoId,
        senderPid: senderPid,
        needManageSettings: false,
      );
      if (!rights.isMember) {
        return reject(
          'not_room_member',
          senderPid: senderPid,
          deferrable: roomKnown,
        );
      }
      target = commandConvoId;
    } else {
      final requestConvoId = 'req:$senderPid';
      target =
          (await db.convoGet(senderPid) == null &&
              await db.convoGet(requestConvoId) != null)
          ? requestConvoId
          : senderPid;
    }

    final homes = await db.convoIdsForMessageKey(eventId);
    if (homes.isNotEmpty && !homes.contains(target)) {
      final senderDid = (senderDeviceId ?? '').trim();
      final sameChat = target.startsWith('group:')
          ? <String>{target}
          : <String>{
              senderPid,
              'req:$senderPid',
              if (senderDid.isNotEmpty) 'dev:$senderDid',
            };
      if (!homes.any(sameChat.contains)) return reject('foreign_message');
    }
    return (convoId: target, senderPid: senderPid, deferrable: false);
  }

  /// Какую переписку разрешено очистить по пришедшей команде, или отказ.
  ///
  /// Свои аппараты повторяют моё действие — любую. Собеседник — только нашу
  /// с ним (в команде он пишет свой профиль). Комната — только тот, кто вправе
  /// менять её настройки: так же проверяет отправка (`clearChatHistoryEverywhere`).
  Future<_InboundCommandVerdict> _authorizedInboundClearHistoryConvoId({
    required AppDb db,
    required String commandConvoId,
    required String? senderDeviceId,
    required String? senderProfileId,
  }) async {
    _InboundCommandVerdict reject(
      String why, {
      String senderPid = '',
      bool deferrable = false,
    }) {
      DiagLog.event('clear_history', 'inbound_rejected', {
        'why': why,
        'deferred': deferrable,
        'sender_dev': DiagLog.pfx((senderDeviceId ?? '').trim()),
        'convo': DiagLog.pfx(commandConvoId),
      });
      return (convoId: null, senderPid: senderPid, deferrable: deferrable);
    }

    final senderPid = await _authenticatedCommandSenderProfileId(
      db: db,
      senderDeviceId: senderDeviceId,
      senderProfileId: senderProfileId,
    );
    final roomKnown =
        commandConvoId.startsWith('group:') &&
        await db.convoGet(commandConvoId) != null;
    if (senderPid == null) {
      return reject('sender_unknown', deferrable: roomKnown);
    }
    _InboundCommandVerdict accept() =>
        (convoId: commandConvoId, senderPid: senderPid, deferrable: false);
    if (senderPid == (_profileId ?? '').trim()) return accept();
    if (commandConvoId.startsWith('group:')) {
      final rights = await _inboundRoomSenderRights(
        db: db,
        groupId: commandConvoId,
        senderPid: senderPid,
        needManageSettings: true,
      );
      return rights.canManageSettings
          ? accept()
          : reject(
              'not_room_admin',
              senderPid: senderPid,
              deferrable: roomKnown,
            );
    }
    if (commandConvoId != senderPid) return reject('foreign_chat');
    return accept();
  }

  Future<bool> _applyMessageEditCommand({
    required EditMessageCommand command,
    required String? senderDeviceId,
    required String? senderProfileId,
  }) async {
    final mentions = command.mentions
        .map(MsgMentionV1.fromJson)
        .whereType<MsgMentionV1>()
        .toList(growable: false);
    final senderIsOwn =
        isOwnDeviceId(senderDeviceId ?? '') ||
        (senderProfileId ?? '').trim() == profileId.trim();
    return _applyMessageEditLocal(
      convoId: command.convoId,
      payloadEventId: command.payloadEventId,
      text: command.text,
      mentions: mentions,
      editingSenderDeviceId: senderDeviceId,
      editingSenderProfileId: senderProfileId,
      requireOwnMessage: senderIsOwn,
    );
  }

  Future<bool> _applyMessageEditLocal({
    required String convoId,
    required String payloadEventId,
    required String text,
    List<MsgMentionV1> mentions = const <MsgMentionV1>[],
    String? editingSenderDeviceId,
    String? editingSenderProfileId,
    required bool requireOwnMessage,
  }) async {
    final db = _db;
    final crypto = _crypto;
    if (db == null || crypto == null) return false;
    final cleanedConvoId = convoId.trim();
    final cleanedPayloadEventId = payloadEventId.trim();
    if (cleanedConvoId.isEmpty || cleanedPayloadEventId.isEmpty) return false;

    final rows = await db.eventsByPayloadEventId(
      convoId: cleanedConvoId,
      payloadEventId: cleanedPayloadEventId,
    );
    if (rows.isEmpty) return false;

    final editingDid = (editingSenderDeviceId ?? '').trim();
    final editingPid = (editingSenderProfileId ?? '').trim();
    var changed = false;
    for (final row in rows) {
      final eventId = ((row['event_id'] as String?) ?? '').trim();
      final senderDid = ((row['sender_device_id'] as String?) ?? '').trim();
      final type = ((row['type'] as String?) ?? '').trim();
      if (eventId.isEmpty || senderDid.isEmpty || type != 'msg') continue;
      final isOwn = isOwnDeviceId(senderDid);
      if (requireOwnMessage) {
        if (!isOwn) continue;
      } else if (isOwn) {
        continue;
      } else if (cleanedConvoId.startsWith('group:')) {
        if (editingDid.isEmpty || senderDid != editingDid) continue;
      } else {
        if (editingPid.isEmpty || cleanedConvoId != editingPid) continue;
      }

      final chatEvent = ChatEvent(
        eventId: eventId,
        createdAtMs: (row['created_at_ms'] as num?)?.toInt() ?? 0,
        type: type,
        ciphertextB64: (row['ciphertext_b64'] as String?) ?? '',
        localCiphertextB64: row['local_ciphertext_b64'] as String?,
        senderDeviceId: senderDid,
        localState: (row['local_state'] as String?) ?? 'received',
        payloadEventId: row['payload_event_id'] as String?,
        scheduledAtMs: (row['scheduled_at_ms'] as num?)?.toInt(),
      );
      final payloadEvent = await payloadEventForChatEvent(chatEvent);
      if (payloadEvent is! MsgEventV1) continue;
      if (isHiddenMessageControlText(payloadEvent.text) ||
          isDeleteForAllCommandText(payloadEvent.text)) {
        continue;
      }

      final preservedCreatedAtMs = chatEvent.createdAtMs > 0
          ? chatEvent.createdAtMs
          : DateTime.now().millisecondsSinceEpoch;
      final updatedPayload = E2ePayloadV1(
        senderDeviceId: senderDid,
        createdAtMs: preservedCreatedAtMs,
        events: [
          MsgEventV1(
            eventId: payloadEvent.eventId,
            text: text,
            replyToEventId: payloadEvent.replyToEventId,
            mentions: mentions,
            // 🔴 ТЕМА ПЕРЕЖИВАЕТ ПРАВКУ (16.09.2026). Здесь её не было, и
            // исправленное сообщение из темы молча переезжало в «Общий»:
            // тема читается из payload, а payload собирался заново без неё.
            topicId: payloadEvent.topicId,
            // Карточка остаётся; если правка убрала ссылку, её не покажет
            // проверка при выводе (`acceptIncomingLinkPreview`).
            linkPreview: payloadEvent.linkPreview,
          ),
        ],
      );
      final localCipher = base64Encode(
        await crypto.encrypt(updatedPayload.encode()),
      );
      await db.updateEventEnvelope(
        eventId: eventId,
        ciphertextB64: localCipher,
        localCiphertextB64: localCipher,
        createdAtMs: preservedCreatedAtMs,
        localState: chatEvent.localState,
        payloadEventId: cleanedPayloadEventId,
      );
      changed = true;
    }
    if (changed) {
      // Bump the per-convo preview epoch: an edit preserves createdAtMs, so the
      // chat-list preview (keyed off lastEventAtMs) would otherwise keep serving
      // the pre-edit text from its cache for BOTH sides. The epoch feeds the
      // preview widget's cache key so the edited last message re-renders.
      _convoPreviewEpoch[cleanedConvoId] =
          (_convoPreviewEpoch[cleanedConvoId] ?? 0) + 1;
      _changed.add(null);
    }
    return changed;
  }

  /// Monotonic per-conversation "content revision" bumped whenever a message's
  /// stored text changes without changing event ordering (edit / delete-for-all).
  /// Chat-list preview widgets add this to their [lastEventAtMs]-based cache key
  /// so an in-place text change invalidates the cached preview.
  final Map<String, int> _convoPreviewEpoch = <String, int>{};
  int convoPreviewEpoch(String convoId) => _convoPreviewEpoch[convoId.trim()] ?? 0;

  Future<bool> editTextMessage({
    required String convoId,
    required String payloadEventId,
    required String text,
    List<MsgMentionV1> mentions = const <MsgMentionV1>[],
  }) async {
    final cleanedConvoId = convoId.trim();
    final cleanedPayloadEventId = payloadEventId.trim();
    final editedText = text.trim();
    if (cleanedConvoId.isEmpty ||
        cleanedPayloadEventId.isEmpty ||
        editedText.isEmpty) {
      return false;
    }
    // NOTE: editing your OWN already-sent message is intentionally NOT gated by
    // the room send-policy (slow mode / send-text permission). An edit is a
    // correction to an existing message, not new send activity — the old
    // `_ensureRoomActionAllowed(sendText)` here made every room edit throw
    // whenever slow mode was active. Membership isn't required either (you may
    // edit a message you left behind).

    final changed = await _applyMessageEditLocal(
      convoId: cleanedConvoId,
      payloadEventId: cleanedPayloadEventId,
      text: editedText,
      mentions: mentions,
      requireOwnMessage: true,
    );
    if (!changed) return false;

    // SCHEDULED ("send later") placeholder: the message has NOT been sent yet,
    // so there is nothing to broadcast — the local rewrite above IS the edit,
    // and the sweep will send the new text when it fires. Editing must stay
    // local-only; broadcasting an edit for a message the peer never received
    // would be meaningless (and, for a 1:1, would target a payloadEventId that
    // will differ from the id the real send finally uses).
    final targetRows = await _db?.eventsByPayloadEventId(
      convoId: cleanedConvoId,
      payloadEventId: cleanedPayloadEventId,
    );
    final isScheduledTarget = (targetRows ?? const <Map<String, Object?>>[]).any(
      (r) =>
          ((r['local_state'] as String?) ?? '') == MessageLocalState.scheduled,
    );
    if (isScheduledTarget) return true;

    final editedAtMs = DateTime.now().millisecondsSinceEpoch;
    final command = buildEditMessageCommand(
      convoId: cleanedConvoId.startsWith('group:')
          ? cleanedConvoId
          : profileId.trim(),
      payloadEventId: cleanedPayloadEventId,
      text: editedText,
      editedAtMs: editedAtMs,
      mentions: mentions.map((mention) => mention.toJson()).toList(),
    );

    // The local edit is the source of truth and has already been applied.
    // Remote fan-out is BEST-EFFORT: an unreachable room member or a transient
    // peer-session hiccup must NEVER make editTextMessage throw, otherwise the
    // UI reports failure and leaves the composer stuck in edit mode even though
    // the message did change locally. This was THE reason edits "never worked"
    // in rooms (one member without a direct session threw the whole fan-out).
    if (cleanedConvoId.startsWith('group:')) {
      final senderPid = profileId;
      final members = await listGroupMembers(cleanedConvoId);
      for (final member in members) {
        if (member == senderPid) continue;
        try {
          await sendControlMessage(
            peerProfileId: member,
            controlText: command,
          );
        } catch (_) {
          // Unreachable member re-syncs the edit on their next history fetch.
        }
      }
    } else {
      final peerProfileId =
          await _normalizeDirectPeerProfileId(cleanedConvoId) ?? cleanedConvoId;
      if (peerProfileId.isNotEmpty && !peerProfileId.startsWith('dev:')) {
        try {
          await sendControlMessage(
            peerProfileId: peerProfileId,
            controlText: command,
          );
        } catch (_) {
          // Best-effort; the local edit stands and the peer re-syncs later.
        }
      }
      unawaited(
        _mirrorMessageEditToOwnDevices(
          convoId: cleanedConvoId,
          payloadEventId: cleanedPayloadEventId,
          text: editedText,
          editedAtMs: editedAtMs,
          mentions: mentions,
        ),
      );
    }
    return true;
  }

  Future<int> unverifiedDeviceCount(String peerProfileId) async {
    final db = _db;
    if (db == null) return 0;
    final cached = await db.contactDevicesList(peerProfileId);
    if (cached.isEmpty) return 0;
    var n = 0;
    for (final r in cached) {
      final v = r['verified_at_ms'] as num?;
      if (v == null) n++;
    }
    return n;
  }

  Future<List<ContactDevice>> listContactDevices(String peerProfileId) async {
    final db = _db;
    if (db == null) return const [];
    final rows = await db.contactDevicesList(peerProfileId);
    return rows
        .map(
          (r) => ContactDevice(
            profileId: r['contact_profile_id'] as String,
            deviceId: r['device_id'] as String,
            identityKeyPubB64: r['identity_key_pub_b64'] as String,
            verifiedAtMs: (r['verified_at_ms'] as num?)?.toInt(),
          ),
        )
        .toList(growable: false);
  }

  Future<void> markContactDeviceVerified({
    required String peerProfileId,
    required String peerDeviceId,
  }) async {
    final db = _db;
    if (db == null) return;
    await db.contactDeviceMarkVerified(
      profileId: peerProfileId,
      deviceId: peerDeviceId,
    );
    _changed.add(null);
  }

  Future<String> _canonicalChatConvoIdForLoad(String convoId) async {
    final db = _db;
    final cid = convoId.trim();
    if (db == null || cid.isEmpty) return cid;
    if (cid.startsWith('group:') || isSavedMessagesConvo(cid)) {
      return cid;
    }

    final existingConvo = await db.convoGet(cid);
    if (existingConvo != null) {
      return cid;
    }

    if (cid.startsWith('req:')) {
      final peerProfileId = cid.substring(4).trim();
      if (peerProfileId.isEmpty) {
        return cid;
      }
      final directConvo = await db.convoGet(peerProfileId);
      return directConvo == null ? cid : peerProfileId;
    }

    if (cid.startsWith('dev:')) {
      final resolvedPeerProfileId = await _resolvePeerProfileId(cid);
      if (resolvedPeerProfileId != null && resolvedPeerProfileId.isNotEmpty) {
        return resolvedPeerProfileId;
      }
    }

    return cid;
  }

  /// Loads the recent events for [convoId].
  ///
  /// [applyRetention] controls whether the auto-delete / room-history-visibility
  /// retention sweep runs as part of this load. It defaults to `true` so every
  /// existing caller keeps its previous behaviour. The chat-screen render path
  /// passes `false` and drives retention out-of-band (on chat open + a periodic
  /// timer via [applyConversationRetention]) so the per-render `controller
  /// .changed` storm no longer triggers a DB retention sweep on every tick.
  Future<List<ChatEvent>> loadEvents(
    String convoId, {
    bool applyRetention = true,
    // TIMELINE WINDOW (2026-07-18): the newest-N query window. The mobile chat
    // GROWS this as the user scrolls toward the top (Telegram-style paging) —
    // previously the window was a fixed newest-200, so every new message
    // pushed the oldest visible one out ("старые смс исчезают сверху"). The
    // rows were never deleted — just outside the window.
    int limit = 200,
  }) async {
    final db = _db;
    if (db == null) return const [];
    final effectiveConvoId = await _canonicalChatConvoIdForLoad(convoId);
    if (applyRetention) {
      await _applyAutoDeleteRetentionForConvo(effectiveConvoId);
    }
    final rows = await db.listEvents(effectiveConvoId, limit: limit);
    return rows
        .map(
          (r) => ChatEvent(
            eventId: r['event_id'] as String,
            createdAtMs: (r['created_at_ms'] as num).toInt(),
            type: (r['type'] as String?) ?? 'msg',
            ciphertextB64: r['ciphertext_b64'] as String,
            localCiphertextB64: r['local_ciphertext_b64'] as String?,
            senderDeviceId: r['sender_device_id'] as String,
            localState: r['local_state'] as String? ?? 'received',
            payloadEventId: r['payload_event_id'] as String?,
            scheduledAtMs: (r['scheduled_at_ms'] as num?)?.toInt(),
          ),
        )
        .toList(growable: false);
  }

  /// Runs the auto-delete / room-history-visibility retention sweep for a single
  /// conversation. Public so the chat screen can drive retention out-of-band
  /// (on open + a periodic timer) instead of on every render — see [loadEvents]'s
  /// `applyRetention` flag. Best-effort; never throws to the caller.
  Future<void> applyConversationRetention(String convoId) async {
    if (_db == null) return;
    try {
      final effectiveConvoId = await _canonicalChatConvoIdForLoad(convoId);
      await _applyAutoDeleteRetentionForConvo(effectiveConvoId);
    } catch (_) {
      // best-effort — retention must never block or break the chat view.
    }
  }

  /// PR7: paged "load older" for the desktop chat thread. Returns the
  /// next [limit] events strictly older than [beforeCreatedAtMs] in
  /// DESC order (caller reverses to chronological the same way
  /// [loadEvents] does).
  ///
  /// `null` / empty result ⇒ no more local rows; the desktop UI should
  /// then optionally fire a [requestPeerHistory] with the same cursor
  /// to pull from the user's mobile.
  Future<List<ChatEvent>> loadOlderEvents(
    String convoId, {
    required int beforeCreatedAtMs,
    int limit = 100,
  }) async {
    final db = _db;
    if (db == null) return const [];
    if (beforeCreatedAtMs <= 0) return const [];
    final effectiveConvoId = await _canonicalChatConvoIdForLoad(convoId);
    final rows = await db.listEvents(
      effectiveConvoId,
      limit: limit,
      beforeCreatedAtMs: beforeCreatedAtMs,
    );
    return rows
        .map(
          (r) => ChatEvent(
            eventId: r['event_id'] as String,
            createdAtMs: (r['created_at_ms'] as num).toInt(),
            type: (r['type'] as String?) ?? 'msg',
            ciphertextB64: r['ciphertext_b64'] as String,
            localCiphertextB64: r['local_ciphertext_b64'] as String?,
            senderDeviceId: r['sender_device_id'] as String,
            localState: r['local_state'] as String? ?? 'received',
            payloadEventId: r['payload_event_id'] as String?,
            scheduledAtMs: (r['scheduled_at_ms'] as num?)?.toInt(),
          ),
        )
        .toList(growable: false);
  }

  Future<List<ChatEvent>> loadEventsAll(
    String convoId, {
    int limit = 5000,
  }) async {
    final db = _db;
    if (db == null) return const [];
    final effectiveConvoId = await _canonicalChatConvoIdForLoad(convoId);
    await _applyAutoDeleteRetentionForConvo(effectiveConvoId);
    final rows = await db.listEventsChronological(
      effectiveConvoId,
      limit: limit,
    );
    return rows
        .map(
          (r) => ChatEvent(
            eventId: r['event_id'] as String,
            createdAtMs: (r['created_at_ms'] as num).toInt(),
            type: (r['type'] as String?) ?? 'msg',
            ciphertextB64: r['ciphertext_b64'] as String,
            localCiphertextB64: r['local_ciphertext_b64'] as String?,
            senderDeviceId: r['sender_device_id'] as String,
            localState: r['local_state'] as String? ?? 'received',
            payloadEventId: r['payload_event_id'] as String?,
          ),
        )
        .toList(growable: false);
  }

  /// Masks `||spoiler||` markers for chat-list / notification previews so
  /// hidden content never leaks outside the chat (where it renders under an
  /// animated dot overlay instead). Other formatting markers are left as-is
  /// here — only spoiler content is a privacy concern.
  String _maskSpoilerMarkersForPreview(String text) {
    if (!text.contains('||')) return text;
    return text.replaceAllMapped(
      RegExp(r'\|\|(.+?)\|\|', dotAll: true),
      (m) => '•••',
    );
  }

  /// Идентификаторы сообщений, удалённых У ВСЕХ, по меткам в окне просмотра.
  ///
  /// 🔴 ЗАЧЕМ (16.08.2026, поле). Лента чата собирает такие метки и прячет
  /// удалённые строки, а предпросмотр в списке чатов про удаление не знал: он
  /// прятал саму метку, но продолжал показывать текст удалённого сообщения.
  /// Собеседник удалил три смс — в чате их не стало, в списке текст остался.
  /// Человек видел сообщение, заходил прочитать и не находил его.
  ///
  /// Предел честности: метки ищутся только в просмотренном окне строк. Если
  /// удаление старше окна, предпросмотр о нём не узнает — но такое сообщение
  /// уже и не было бы последним, то есть в предпросмотр не попало бы.
  Set<String> _deletedPayloadIdsFromDecoded(
    List<(ChatEvent, String)> decoded,
  ) {
    final out = <String>{};
    for (final (_, text) in decoded) {
      final trimmed = text.trim();
      if (!trimmed.startsWith(kDeleteForAllCommandPrefix)) continue;
      out.addAll(parseDeleteForAllCommand(trimmed));
    }
    return out;
  }

  /// Была ли эта строка удалена у всех.
  bool _isPayloadDeleted(ChatEvent event, Set<String> deletedPayloadIds) {
    if (deletedPayloadIds.isEmpty) return false;
    final pid = (event.payloadEventId ?? '').trim();
    if (pid.isEmpty) return false;
    return deletedPayloadIds.contains(pid);
  }

  Future<String?> lastMessagePreview(String convoId) async {
    final db = _db;
    if (db == null) return null;
    final effectiveConvoId = await _canonicalChatConvoIdForLoad(convoId);
    await _applyAutoDeleteRetentionForConvo(effectiveConvoId);
    final rows = await db.listEvents(effectiveConvoId, limit: 200);
    final decoded = <(ChatEvent, String)>[];
    for (final row in rows) {
      final e = ChatEvent(
        eventId: row['event_id'] as String,
        createdAtMs: (row['created_at_ms'] as num).toInt(),
        type: (row['type'] as String?) ?? 'msg',
        ciphertextB64: row['ciphertext_b64'] as String,
        localCiphertextB64: row['local_ciphertext_b64'] as String?,
        senderDeviceId: row['sender_device_id'] as String,
        localState: row['local_state'] as String? ?? 'received',
        payloadEventId: row['payload_event_id'] as String?,
      );
      decoded.add((e, await decryptPlainAsync(e)));
    }
    final deletedPayloadIds = _deletedPayloadIdsFromDecoded(decoded);
    for (final (e, decrypted) in decoded) {
      // 🔴 УДАЛЁННОЕ У ВСЕХ НЕ ИМЕЕТ ПРАВА ЖИТЬ В ПРЕДПРОСМОТРЕ (16.08.2026).
      //
      // Лента чата собирает метки `__secretly_delete__` и пропускает удалённые
      // строки; предпросмотр про удаление не знал ВОВСЕ — он лишь прятал саму
      // метку. Поле: собеседник удалил три сообщения, в чате их не стало, а в
      // списке чатов текст остался висеть. Человек видел сообщение, заходил
      // прочитать — и не находил его.
      if (_isPayloadDeleted(e, deletedPayloadIds)) continue;
      // Forwarded messages wrap their body in a control prefix — preview the
      // unwrapped text instead of skipping the message.
      final fwd = parseForwardCommand(decrypted);
      final text = _maskSpoilerMarkersForPreview(
        fwd != null ? fwd.text : decrypted,
      );
      final trimmed = text.trim();
      if (trimmed.isEmpty || trimmed == '…') continue;
      if (trimmed.startsWith('__secretly_') &&
          !trimmed.startsWith('__secretly_delete__:')) {
        continue;
      }
      if (trimmed.startsWith('__secretly_delete__:')) continue;
      if (text.startsWith('(') && text.endsWith(')')) continue;
      return text;
    }
    return null;
  }

  /// [applyRetention] — та же развилка, что и у [loadEvents], и по той же
  /// причине. Список чатов вызывает превью на КАЖДУЮ строку, то есть свип
  /// удаления по расписанию запускался столько раз, сколько чатов на экране, —
  /// притом что `listConversations` уже прогнал `_runConversationMaintenance`
  /// по всем чатам разом непосредственно перед отрисовкой. По умолчанию `true`,
  /// чтобы поведение всех существующих вызывающих не менялось.
  Future<ChatListPreview> lastMessagePreviewRich(
    String convoId, {
    bool applyRetention = true,
  }) async {
    final db = _db;
    if (db == null) return const ChatListPreview.empty();
    final effectiveConvoId = await _canonicalChatConvoIdForLoad(convoId);
    if (applyRetention) {
      await _applyAutoDeleteRetentionForConvo(effectiveConvoId);
    }
    final rows = await db.listEvents(effectiveConvoId, limit: 40);
    if (rows.isEmpty) return const ChatListPreview.empty();

    final events = rows
        .map(
          (r) => ChatEvent(
            eventId: r['event_id'] as String,
            createdAtMs: (r['created_at_ms'] as num).toInt(),
            type: (r['type'] as String?) ?? 'msg',
            ciphertextB64: r['ciphertext_b64'] as String,
            localCiphertextB64: r['local_ciphertext_b64'] as String?,
            senderDeviceId: r['sender_device_id'] as String,
            localState: r['local_state'] as String? ?? 'received',
            payloadEventId: r['payload_event_id'] as String?,
          ),
        )
        .toList(growable: false);

    // 🔴 См. [lastMessagePreview]: удалённое у всех обязано исчезнуть и здесь,
    // иначе список чатов показывает то, чего в чате уже нет.
    final decodedForDeletes = <(ChatEvent, String)>[
      for (final e in events) (e, await decryptPlainAsync(e)),
    ];
    final deletedPayloadIds = _deletedPayloadIdsFromDecoded(decodedForDeletes);

    bool hiddenControlText(String text) {
      final t = text.trim();
      if (t.isEmpty) return true;
      if (t.startsWith('__secretly_')) return true;
      if (t.startsWith('__secretly_delete__:')) return true;
      if (CallSignalCommandCodec.isEncodedText(t)) return true;
      return false;
    }

    bool looksLikeLink(String text) {
      final t = text.trim();
      if (t.isEmpty) return false;
      return t.contains('http://') ||
          t.contains('https://') ||
          t.contains('www.');
    }

    String stickerPreviewText(StickerEventV1 event) {
      final resolved = SecretlyStickerCatalog.resolveEvent(event);
      return SecretlyStickerCatalog.previewLabel(
        isRu: _isRussianSystemEventLocale,
        baseLabel: _localizedText(ru: 'Стикер', en: 'Sticker'),
        emojiHint: event.emojiHint.isNotEmpty
            ? event.emojiHint
            : resolved.emojiHint,
        label: event.label.isNotEmpty ? event.label : resolved.label,
      );
    }

    final isRoom = effectiveConvoId.startsWith('group:');
    final isRu = _isRussianSystemEventLocale;

    /// Resolve sender display-name for room preview (lazy, cached per call).
    final senderNameCache = <String, String?>{};
    Future<String?> resolveSenderName(String senderDeviceId) async {
      if (!isRoom) return null;
      if (senderDeviceId == deviceId) {
        return _localizedText(ru: 'Вы', en: 'You');
      }
      if (senderNameCache.containsKey(senderDeviceId)) {
        return senderNameCache[senderDeviceId];
      }
      final c = await contactByDeviceId(senderDeviceId);
      final name = c?.displayName;
      senderNameCache[senderDeviceId] = name;
      return name;
    }

    for (var i = 0; i < events.length; i++) {
      final event = events[i];
      if (_isPayloadDeleted(event, deletedPayloadIds)) continue;
      final payload = await payloadEventForChatEvent(event);

      if (payload is MsgEventV1) {
        // A forwarded message wraps its body in a control prefix; preview the
        // unwrapped text rather than hiding the message entirely.
        final fwd = parseForwardCommand(payload.text);
        final text = _maskSpoilerMarkersForPreview(
          (fwd != null ? fwd.text : payload.text).trim(),
        );
        if (hiddenControlText(text)) continue;
        final sName = await resolveSenderName(event.senderDeviceId);
        final myPid = (_profileId ?? '').trim();
        final mentionsMe =
            myPid.isNotEmpty &&
            payload.mentions.any(
              (m) => m.isAll || (m.isProfile && m.profileId == myPid),
            );
        if (looksLikeLink(text)) {
          return ChatListPreview(
            kind: ChatListPreviewKind.link,
            text: _localizedText(ru: 'Ссылка', en: 'Link'),
            senderName: sName,
            senderDeviceId: event.senderDeviceId,
            senderLocalState: event.localState,
            mentionsSelf: mentionsMe,
          );
        }
        return ChatListPreview(
          kind: ChatListPreviewKind.text,
          text: text,
          senderName: sName,
          senderDeviceId: event.senderDeviceId,
          senderLocalState: event.localState,
          mentionsSelf: mentionsMe,
        );
      }

      if (payload is AttachmentEventV1) {
        final mime = (payload.mime ?? '').toLowerCase();
        final sName = await resolveSenderName(event.senderDeviceId);
        if (mime.startsWith('image/')) {
          final imageBlobIds = <String>[payload.blobId];
          final groupId = (payload.mediaGroupId ?? '').trim();
          if (groupId.isNotEmpty) {
            for (
              var j = i + 1;
              j < events.length && imageBlobIds.length < 3;
              j++
            ) {
              final p2 = await payloadEventForChatEvent(events[j]);
              if (p2 is! AttachmentEventV1) break;
              final m2 = (p2.mime ?? '').toLowerCase();
              if (!m2.startsWith('image/')) break;
              if ((p2.mediaGroupId ?? '').trim() != groupId) break;
              imageBlobIds.add(p2.blobId);
            }
          }
          return ChatListPreview(
            kind: ChatListPreviewKind.photo,
            text: _localizedText(ru: 'Фотография', en: 'Photo'),
            imageBlobIds: imageBlobIds,
            senderName: sName,
            senderDeviceId: event.senderDeviceId,
            senderLocalState: event.localState,
          );
        }
        if (mime.startsWith('audio/')) {
          // Voice vs music: same rule as the audio bubble — dedicated voice
          // mimes, or an AAC/m4a recording carrying the captured waveform
          // envelope (only ever attached to in-app recordings, never to
          // picked music files).
          final isVoiceMessage =
              mime == 'audio/ogg' ||
              mime == 'audio/opus' ||
              mime.startsWith('audio/webm') ||
              mime == 'audio/3gpp' ||
              mime == 'audio/amr' ||
              (payload.waveform?.isNotEmpty ?? false);
          if (isVoiceMessage) {
            return ChatListPreview(
              kind: ChatListPreviewKind.voice,
              text: _localizedText(
                ru: 'Голосовое сообщение',
                en: 'Voice message',
                uk: 'Голосове повідомлення',
                es: 'Mensaje de voz',
                pt: 'Mensagem de voz',
                ptBr: 'Mensagem de voz',
                fr: 'Message vocal',
                de: 'Sprachnachricht',
              ),
              senderName: sName,
              senderDeviceId: event.senderDeviceId,
              senderLocalState: event.localState,
            );
          }
          return ChatListPreview(
            kind: ChatListPreviewKind.music,
            text: _localizedText(ru: 'Музыка', en: 'Music'),
            senderName: sName,
            senderDeviceId: event.senderDeviceId,
            senderLocalState: event.localState,
          );
        }
        return ChatListPreview(
          kind: ChatListPreviewKind.file,
          text: _localizedText(ru: 'Файл', en: 'File'),
          senderName: sName,
          senderDeviceId: event.senderDeviceId,
          senderLocalState: event.localState,
        );
      }

      if (payload is StickerEventV1) {
        final sName = await resolveSenderName(event.senderDeviceId);
        return ChatListPreview(
          kind: ChatListPreviewKind.text,
          text: stickerPreviewText(payload),
          senderName: sName,
          senderDeviceId: event.senderDeviceId,
          senderLocalState: event.localState,
        );
      }

      if (payload is CallEventV1) {
        final sName = await resolveSenderName(event.senderDeviceId);
        return ChatListPreview(
          kind: ChatListPreviewKind.text,
          isCall: true,
          text: buildCallEventPreviewText(
            l10n: _appL10n,
            isRu: isRu,
            result: payload.result,
            direction: payload.direction,
            isVideo: payload.hadVideo,
            durationMs: payload.durationMs,
          ),
          senderName: sName,
          senderDeviceId: event.senderDeviceId,
          senderLocalState: event.localState,
        );
      }

      if (payload is SystemEventV1) {
        final text = formatSystemEventText(
          payload,
          isRu: _isRussianSystemEventLocale,
          selfProfileId: _profileId?.trim(),
          localeTag: _effectiveAppLocaleTagForStrings(),
        ).trim();
        if (hiddenControlText(text)) continue;
        return ChatListPreview(kind: ChatListPreviewKind.text, text: text);
      }

      final text = (await decryptPlainAsync(event)).trim();
      if (hiddenControlText(text) || text.isEmpty || text == '…') continue;
      final sName = await resolveSenderName(event.senderDeviceId);
      if (looksLikeLink(text)) {
        return ChatListPreview(
          kind: ChatListPreviewKind.link,
          text: _localizedText(ru: 'Ссылка', en: 'Link'),
          senderName: sName,
          senderDeviceId: event.senderDeviceId,
          senderLocalState: event.localState,
        );
      }
      return ChatListPreview(
        kind: ChatListPreviewKind.text,
        text: text,
        senderName: sName,
        senderDeviceId: event.senderDeviceId,
        senderLocalState: event.localState,
      );
    }

    return const ChatListPreview.empty();
  }

  String _stickerPackOperationKey(String packId, int packVersion) =>
      '$packId@$packVersion';

  /// Перепривязывает пути стикеров к НЫНЕШНЕМУ каталогу приложения.
  ///
  /// Возвращает число исправленных строк.
  ///
  /// 🔴 Ищем по ИМЕНИ ФАЙЛА в дереве `stickers`, а не доверяем сохранённому
  /// пути: путь из копии принадлежит другому контейнеру. На iOS каталог
  /// приложения меняет UUID при каждой переустановке, поэтому «файл не найден»
  /// после восстановления означает не отсутствие файла, а устаревший указатель.
  ///
  /// 🔴 Строки, для которых файла действительно нет, оставляем как есть, а НЕ
  /// чистим. Пустой `local_path` — это потеря: набор перестанет отрисовываться
  /// навсегда, даже если файл появится позже (докачкой или второй копией).
  /// Устаревший указатель хотя бы можно перепривязать ещё раз.
  Future<int> _rebaseStickerLocalPaths(AppDb db) async {
    final rows = await db.stickerLocalPathRowsForRebase();
    if (rows.isEmpty) return 0;

    final root = await _stickerCatalogRootDirectory();
    // Один обход дерева вместо поиска на каждую строку: наборов бывает много.
    final byName = <String, String>{};
    await for (final entity in root.list(recursive: true, followLinks: false)) {
      if (entity is File) {
        byName.putIfAbsent(p.basename(entity.path), () => entity.path);
      }
    }
    if (byName.isEmpty) return 0;

    var fixed = 0;
    for (final row in rows) {
      final stored = ((row['local_path'] as String?) ?? '').trim();
      if (stored.isNotEmpty && await File(stored).exists()) continue;

      final fileName = ((row['file_name'] as String?) ?? '').trim();
      final found = fileName.isEmpty ? null : byName[fileName];
      // Пробуем и по имени из сохранённого пути: `file_name` мог разойтись с
      // тем, под которым файл лёг на диск.
      final fallback = stored.isEmpty ? null : byName[p.basename(stored)];
      final resolved = found ?? fallback;
      if (resolved == null || resolved == stored) continue;

      await db.stickerUpdateLocalPath(
        packId: (row['pack_id'] as String?) ?? '',
        packVersion: ((row['pack_version'] as num?) ?? 0).toInt(),
        stickerId: (row['sticker_id'] as String?) ?? '',
        localPath: resolved,
      );
      fixed += 1;
    }
    return fixed;
  }

  /// Каталоги, где лежат картинки, чьи пути хранит база.
  ///
  /// Корень документов тоже просматривается, но БЕЗ обхода вглубь: рядом
  /// лежат `attachments` — там бывают гигабайты, и обходить их ради аватарок
  /// незачем.
  static const List<String> _restorableImageSubDirs = <String>[
    'profile_avatars',
    'contact_avatars',
    'room_avatars',
    'profile_media',
  ];

  /// Перепривязка путей к фотографиям после восстановления из копии.
  ///
  /// 🔴 ЗАЧЕМ (13.09.2026, поле: «на компьютере нигде нет фотографий»).
  ///
  /// Копия и связка по QR переносят и строки, и сами файлы — но пути в строках
  /// остаются от ЧУЖОГО контейнера. На компьютере такого пути не существует
  /// физически, `File.existsSync()` отвечает «нет», и разрешатель фотографий
  /// честно возвращает null. В итоге всё восстановилось, файлы лежат на
  /// диске — а человек видит инициалы вместо лиц: и своих собеседников, и
  /// комнат.
  ///
  /// Чиним только то, что сломано: путь переписывается, лишь когда файла по
  /// нему НЕТ, а файл с тем же именем нашёлся в нынешнем каталоге.
  Future<int> _rebaseRestoredImagePaths(AppDb db) async {
    final Directory docs;
    try {
      docs = await getApplicationDocumentsDirectory();
    } catch (_) {
      return 0;
    }
    final byName = <String, String>{};
    Future<void> scan(Directory dir, {required bool recursive}) async {
      if (!await dir.exists()) return;
      await for (final entity in dir.list(
        recursive: recursive,
        followLinks: false,
      )) {
        if (entity is File) {
          byName.putIfAbsent(p.basename(entity.path), () => entity.path);
        }
      }
    }

    for (final sub in _restorableImageSubDirs) {
      await scan(Directory(p.join(docs.path, sub)), recursive: true);
    }
    await scan(docs, recursive: false);
    if (byName.isEmpty) return 0;

    return db.rebaseImagePaths((stored) {
      if (File(stored).existsSync()) return null;
      return byName[p.basename(stored)];
    });
  }

  Future<Directory> _stickerCatalogRootDirectory() async {
    final dir = await getApplicationDocumentsDirectory();
    final root = Directory(p.join(dir.path, 'stickers'));
    if (!await root.exists()) {
      await root.create(recursive: true);
    }
    return root;
  }

  String _stickerFallbackFileName(
    StickerPackStickerRecord sticker,
    SecretlyStickerFormat format,
  ) {
    final candidate = sticker.fileName.trim();
    if (candidate.isNotEmpty) return candidate;
    final ext = switch (format) {
      SecretlyStickerFormat.lottie => '.json',
      SecretlyStickerFormat.webp => '.webp',
      SecretlyStickerFormat.png => '.png',
    };
    return '${sticker.stickerId}$ext';
  }

  SecretlyStickerDescriptor _remoteStickerDescriptorFromRow(
    StickerPackStickerRecord sticker,
  ) {
    final format = SecretlyStickerFormatWire.fromWire(sticker.format);
    final normalizedLocalPath = sticker.localPath.trim();
    if (normalizedLocalPath.isNotEmpty) {
      return SecretlyStickerDescriptor.localFile(
        packId: sticker.packId,
        packVersion: sticker.packVersion,
        stickerId: sticker.stickerId,
        localFilePath: normalizedLocalPath,
        format: format,
        animated: sticker.animated,
        emojiHint: sticker.emojiHint,
        label: sticker.label,
        keywords: sticker.keywords,
      );
    }
    return SecretlyStickerDescriptor.placeholder(
      packId: sticker.packId,
      packVersion: sticker.packVersion,
      stickerId: sticker.stickerId,
      emojiHint: sticker.emojiHint,
      label: sticker.label,
      keywords: sticker.keywords,
      format: format,
      animated: sticker.animated,
    );
  }

  Future<void> _loadStickerCatalogFromDb() async {
    final db = _db;
    if (db == null) {
      SecretlyStickerCatalog.clearRemoteCatalog();
      return;
    }
    final packRows = await db.listStickerCatalogPacks();
    // 🔴 ОДИН ЗАПРОС НА ВЕСЬ КАТАЛОГ (02.09.2026, замер холодного старта).
    // Здесь стоял цикл, ходивший за содержимым КАЖДОГО набора отдельно: сорок
    // семь наборов давали сорок восемь последовательных обращений к SQLCipher,
    // и каждая страница ещё расшифровывалась. На устройстве это 339 мс из
    // 776 мс старта — сорок четыре процента, — при том что все двенадцать
    // тысяч строк поднимались в память в любом случае, просто по частям.
    final stickersByPack = await db.listAllStickerCatalogStickersByPack();
    final remotePacks = <SecretlyStickerPack>[];
    for (final pack in packRows) {
      final stickerRows =
          stickersByPack[(
            packId: pack.packId,
            packVersion: pack.packVersion,
          )] ??
          const <StickerPackStickerRecord>[];
      remotePacks.add(
        SecretlyStickerPack(
          id: pack.packId,
          version: pack.packVersion,
          title: pack.title,
          description: pack.description,
          iconStickerId: pack.iconStickerId,
          iconEmojiHint: pack.iconEmojiHint,
          featuredRank: pack.featuredRank,
          tags: pack.tags,
          installed: pack.installed,
          origin: SecretlyStickerPackOrigin.remote,
          stickers: stickerRows
              .map(_remoteStickerDescriptorFromRow)
              .toList(growable: false),
        ),
      );
    }
    SecretlyStickerCatalog.applyRemoteCatalog(remotePacks);
  }

  Future<void> _pruneStaleStickerCatalogPacks({
    required RemoteStickerCatalogManifest manifest,
  }) async {
    final db = _db;
    if (db == null || manifest.generatedAtMs <= 0) {
      return;
    }
    final manifestKeys = manifest.packs
        .map((pack) => '${pack.packId}@${pack.packVersion}')
        .toSet();
    final existingPacks = await db.listStickerCatalogPacks();
    for (final pack in existingPacks) {
      // NEVER prune the user's own «Мои стикеры» packs — they aren't in the
      // server manifest and must survive every catalog sync.
      if (pack.packId.startsWith('user:')) continue;
      final packKey = '${pack.packId}@${pack.packVersion}';
      if (manifestKeys.contains(packKey)) continue;
      final stickerRows = await db.listStickerCatalogStickers(
        packId: pack.packId,
        packVersion: pack.packVersion,
      );
      for (final sticker in stickerRows) {
        final localPath = sticker.localPath.trim();
        if (localPath.isEmpty) continue;
        try {
          final file = File(localPath);
          if (await file.exists()) {
            await file.delete();
          }
        } catch (_) {
          // Ignore stale file cleanup failures and continue pruning DB state.
        }
      }
      await db.deleteStickerCatalogPack(
        packId: pack.packId,
        packVersion: pack.packVersion,
      );
    }
  }

  Future<void> _syncStickerCatalog({bool force = false}) async {
    final db = _db;
    final client = _stickerCatalogClient;
    final now = DateTime.now().millisecondsSinceEpoch;
    if (db == null || client == null || _stickerCatalogSyncInFlight) return;
    if (!force && (now - _lastStickerCatalogSyncAtMs) < 10 * 60 * 1000) {
      return;
    }
    _stickerCatalogSyncInFlight = true;
    _lastStickerCatalogSyncAtMs = now;
    try {
      final manifest = await client.fetchManifest();
      await _pruneStaleStickerCatalogPacks(manifest: manifest);
      final effectiveUpdatedAtMs = manifest.generatedAtMs > 0
          ? manifest.generatedAtMs
          : now;
      for (final pack in manifest.packs) {
        await db.upsertStickerPackSummary(
          packId: pack.packId,
          packVersion: pack.packVersion,
          title: pack.title,
          description: pack.description,
          iconStickerId: pack.iconStickerId,
          iconEmojiHint: pack.iconEmojiHint,
          featuredRank: pack.featuredRank,
          tags: pack.tags,
          stickerCount: pack.stickers.length,
          updatedAtMs: effectiveUpdatedAtMs,
        );
        await db.replaceStickerPackStickers(
          packId: pack.packId,
          packVersion: pack.packVersion,
          stickers: pack.stickers
              .map(
                (sticker) => (
                  packId: pack.packId,
                  packVersion: pack.packVersion,
                  stickerId: sticker.stickerId,
                  fileName: sticker.fileName,
                  localPath: '',
                  format: sticker.format,
                  animated: sticker.animated,
                  emojiHint: sticker.emojiHint,
                  label: sticker.label,
                  keywords: sticker.keywords,
                  sha256B64: sticker.sha256B64,
                  sizeBytes: sticker.sizeBytes,
                  downloadedAtMs: null,
                  lastAccessedAtMs: null,
                ),
              )
              .toList(growable: false),
        );
      }
      await _loadStickerCatalogFromDb();
      if (!_changed.isClosed) {
        _changed.add(null);
      }
    } catch (_) {
      // Keep bundled catalog as a safe fallback when the relay is old/unavailable.
    } finally {
      _stickerCatalogSyncInFlight = false;
    }
  }

  Future<List<SecretlyStickerPack>> loadStickerPickerPacks({
    bool refresh = true,
  }) async {
    await _loadStickerCatalogFromDb();
    if (refresh) {
      await _syncStickerCatalog();
    }
    return SecretlyStickerCatalog.pickerPacks;
  }

  bool isStickerPackBusy({required String packId, required int packVersion}) {
    return _stickerPackOpsInFlight.contains(
      _stickerPackOperationKey(packId.trim(), packVersion),
    );
  }

  @visibleForTesting
  static void verifyStickerAssetIntegrityForTesting({
    required String stickerId,
    required String expectedSha256B64,
    required int expectedSizeBytes,
    required List<int> bytes,
  }) {
    _verifyStickerAssetIntegrity(
      stickerId: stickerId,
      expectedSha256B64: expectedSha256B64,
      expectedSizeBytes: expectedSizeBytes,
      bytes: bytes,
    );
  }

  static void _verifyStickerAssetIntegrity({
    required String stickerId,
    required String expectedSha256B64,
    required int expectedSizeBytes,
    required List<int> bytes,
  }) {
    if (expectedSizeBytes > 0 && bytes.length != expectedSizeBytes) {
      throw StateError('Sticker size mismatch for $stickerId');
    }
    final expectedHash = expectedSha256B64.trim();
    if (expectedHash.isEmpty) {
      return;
    }
    final actualHash = base64Encode(crypto.sha256.convert(bytes).bytes);
    if (actualHash != expectedHash) {
      throw StateError('Sticker checksum mismatch for $stickerId');
    }
  }

  Future<void> installStickerPack({
    required String packId,
    required int packVersion,
  }) async {
    final normalizedPackId = packId.trim();
    final operationKey = _stickerPackOperationKey(
      normalizedPackId,
      packVersion,
    );
    if (normalizedPackId.isEmpty || packVersion <= 0) {
      throw StateError('Sticker pack id is invalid');
    }
    if (!_stickerPackOpsInFlight.add(operationKey)) return;
    final db = _db;
    final client = _stickerCatalogClient;
    if (db == null || client == null) {
      _stickerPackOpsInFlight.remove(operationKey);
      throw StateError('Sticker catalog is unavailable');
    }
    try {
      await _syncStickerCatalog(force: true);
      final stickerRows = await db.listStickerCatalogStickers(
        packId: normalizedPackId,
        packVersion: packVersion,
      );
      if (stickerRows.isEmpty) {
        throw StateError('Sticker pack metadata is unavailable');
      }
      final rootDir = await _stickerCatalogRootDirectory();
      final installDir = Directory(
        p.join(rootDir.path, '$normalizedPackId@$packVersion'),
      );
      final tempDir = Directory('${installDir.path}.tmp');
      if (await tempDir.exists()) {
        await tempDir.delete(recursive: true);
      }
      await tempDir.create(recursive: true);
      final localPathsByStickerId = <String, String>{};
      final downloadedAtMs = DateTime.now().millisecondsSinceEpoch;
      try {
        for (final sticker in stickerRows) {
          final bytes = await client.downloadAsset(
            packId: normalizedPackId,
            packVersion: packVersion,
            stickerId: sticker.stickerId,
          );
          _verifyStickerAssetIntegrity(
            stickerId: sticker.stickerId,
            expectedSha256B64: sticker.sha256B64,
            expectedSizeBytes: sticker.sizeBytes,
            bytes: bytes,
          );
          final format = SecretlyStickerFormatWire.fromWire(sticker.format);
          final fileName = _stickerFallbackFileName(sticker, format);
          final filePath = p.join(tempDir.path, fileName);
          final file = File(filePath);
          await file.parent.create(recursive: true);
          await file.writeAsBytes(bytes, flush: true);
          localPathsByStickerId[sticker.stickerId] = p.join(
            installDir.path,
            fileName,
          );
        }
        if (await installDir.exists()) {
          await installDir.delete(recursive: true);
        }
        await tempDir.rename(installDir.path);
      } catch (_) {
        if (await tempDir.exists()) {
          await tempDir.delete(recursive: true);
        }
        rethrow;
      }
      for (final sticker in stickerRows) {
        final localPath = localPathsByStickerId[sticker.stickerId];
        if (localPath == null || localPath.isEmpty) continue;
        await db.updateStickerLocalAsset(
          packId: normalizedPackId,
          packVersion: packVersion,
          stickerId: sticker.stickerId,
          localPath: localPath,
          downloadedAtMs: downloadedAtMs,
          lastAccessedAtMs: downloadedAtMs,
        );
      }
      await db.setStickerPackInstalled(
        packId: normalizedPackId,
        packVersion: packVersion,
        installed: true,
        installedAtMs: downloadedAtMs,
      );
      await _loadStickerCatalogFromDb();
      if (!_changed.isClosed) {
        _changed.add(null);
      }
    } finally {
      _stickerPackOpsInFlight.remove(operationKey);
    }
  }

  Future<void> uninstallStickerPack({
    required String packId,
    required int packVersion,
  }) async {
    final normalizedPackId = packId.trim();
    final operationKey = _stickerPackOperationKey(
      normalizedPackId,
      packVersion,
    );
    if (normalizedPackId.isEmpty || packVersion <= 0) return;
    if (!_stickerPackOpsInFlight.add(operationKey)) return;
    final db = _db;
    if (db == null) {
      _stickerPackOpsInFlight.remove(operationKey);
      return;
    }
    try {
      final rootDir = await _stickerCatalogRootDirectory();
      final installDir = Directory(
        p.join(rootDir.path, '$normalizedPackId@$packVersion'),
      );
      if (await installDir.exists()) {
        await installDir.delete(recursive: true);
      }
      await db.resetStickerPackInstallState(
        packId: normalizedPackId,
        packVersion: packVersion,
      );
      await _loadStickerCatalogFromDb();
      if (!_changed.isClosed) {
        _changed.add(null);
      }
    } finally {
      _stickerPackOpsInFlight.remove(operationKey);
    }
  }

  Future<List<SecretlyStickerDescriptor>> loadRecentStickers({
    int limit = 20,
  }) async {
    final db = _db;
    final pid = (_profileId ?? '').trim();
    if (db == null || pid.isEmpty || limit <= 0) return const [];
    final rows = await db.listRecentStickers(profileId: pid, limit: limit);
    final stickers = <SecretlyStickerDescriptor>[];
    for (final row in rows) {
      final packId = (row['pack_id'] as String?)?.trim() ?? '';
      final packVersion = (row['pack_version'] as num?)?.toInt() ?? 1;
      final stickerId = (row['sticker_id'] as String?)?.trim() ?? '';
      if (packId.isEmpty || stickerId.isEmpty) continue;
      final sticker = SecretlyStickerCatalog.findSticker(
        packId: packId,
        packVersion: packVersion,
        stickerId: stickerId,
      );
      if (sticker != null) {
        stickers.add(sticker);
      }
    }
    return stickers;
  }

  Future<void> _touchRecentSticker(SecretlyStickerDescriptor sticker) async {
    final db = _db;
    final pid = (_profileId ?? '').trim();
    if (db == null || pid.isEmpty) return;
    await db.recentStickerTouch(
      profileId: pid,
      packId: sticker.packId,
      packVersion: sticker.packVersion,
      stickerId: sticker.stickerId,
      lastUsedAtMs: DateTime.now().millisecondsSinceEpoch,
    );
  }

  /// Недавно выбранные гифки, свежие первыми.
  ///
  /// Хранятся в `local_kv` шифрованной базы — см. `lib/gifs/gif_recents.dart`
  /// о том, почему именно там и почему без новой таблицы.
  Future<List<RecentGif>> loadRecentGifs({int limit = kRecentGifLimit}) async {
    final db = _db;
    final pid = (_profileId ?? '').trim();
    if (db == null || pid.isEmpty || limit <= 0) return const <RecentGif>[];
    try {
      final raw = await db.localKvGet(recentGifsKvKey(pid));
      final all = decodeRecentGifs(raw);
      if (all.length <= limit) return all;
      return List<RecentGif>.unmodifiable(all.take(limit));
    } catch (_) {
      // Недавние — украшение подборщика. Сбой чтения обязан стоить пустой
      // полосы, а не неоткрывающегося листа выбора.
      return const <RecentGif>[];
    }
  }

  /// Запоминает выбранную гифку.
  ///
  /// 🔴 НИКОГДА НЕ БРОСАЕТ И НИКОГДА НЕ ЗАДЕРЖИВАЕТ ОТПРАВКУ. Вызывается рядом
  /// с отправкой, и провал записи «недавних» не имеет права отменить отправку
  /// сообщения — это ровно тот класс, где обработчик сбоя разрешал бы
  /// разрушительное действие.
  Future<void> rememberPickedGif({
    required String previewUrl,
    required String fullUrl,
  }) async {
    final db = _db;
    final pid = (_profileId ?? '').trim();
    if (db == null || pid.isEmpty) return;
    try {
      final key = recentGifsKvKey(pid);
      final current = decodeRecentGifs(await db.localKvGet(key));
      final next = withRecentGif(
        current,
        RecentGif(previewUrl: previewUrl, fullUrl: fullUrl),
      );
      await db.localKvSet(key, encodeRecentGifs(next));
    } catch (_) {
      // см. выше
    }
  }

  Future<int?> lastConversationActivityMs(String convoId) async {
    final db = _db;
    if (db == null) return null;
    final row = await db.convoGet(convoId);
    final v = (row?['last_event_at_ms'] as num?)?.toInt();
    if (v == null || v <= 0) return null;
    return v;
  }

  Future<int?> peerLastSeenMsForConversation(String convoId) async {
    final db = _db;
    if (db == null) return null;

    var cid = convoId.trim();
    if (cid.isEmpty) return null;
    if (isSavedMessagesConvo(cid) || cid.startsWith('group:')) return null;

    if (cid.startsWith('req:') && cid.length > 4) {
      cid = cid.substring(4).trim();
    }
    if (cid.startsWith('dev:')) {
      return null;
    }

    String profileId = cid;
    final row = await db.convoGet(convoId);
    final peerFromRow = (row?['peer_profile_id'] as String?)?.trim();
    if (peerFromRow != null && peerFromRow.isNotEmpty) {
      profileId = peerFromRow;
    }

    if (profileId.startsWith('req:') && profileId.length > 4) {
      profileId = profileId.substring(4).trim();
    }
    if (profileId.isEmpty ||
        profileId.startsWith('group:') ||
        profileId.startsWith('dev:')) {
      return null;
    }

    final contact = await db.contactGet(profileId);
    final meta = await db.profileMetaGet(profileId);
    final ts = await db.profileMetaGetLastSeen(profileId);
    return _visiblePeerLastSeenAtMs(
      contactRow: contact,
      metaRow: meta,
      lastSeenAtMs: ts,
    );
  }

  Future<bool> isConversationPeerOnline(String convoId) async {
    final ts = await peerLastSeenMsForConversation(convoId);
    if (ts == null) return false;
    return DateTime.now().millisecondsSinceEpoch - ts < kPeerOnlineFreshMs;
  }

  void setForwardDraft(ForwardDraft draft) {
    _forwardDraft = draft;
    _changed.add(null);
  }

  void clearForwardDraft() {
    if (_forwardDraft == null) return;
    _forwardDraft = null;
    _changed.add(null);
  }

  String decodePlain(ChatEvent e) {
    try {
      // Decrypt on demand.
      // NOTE: This is for dev loopback. In real app we will decrypt into model
      // and handle errors/status.
      return '(decrypt in async)';
    } catch (_) {
      return '(decode error)';
    }
  }

  Future<String> decryptPlainAsync(ChatEvent e) async {
    try {
      String decodeAttachmentLabel(AttachmentEventV1 a) {
        final mime = (a.mime ?? '').toLowerCase();
        if (mime.startsWith('image/')) return '📷';
        if (mime.startsWith('video/')) return '🎬';
        if (mime.startsWith('audio/')) {
          final isVoice =
              mime == 'audio/ogg' ||
              mime == 'audio/opus' ||
              mime.startsWith('audio/webm') ||
              mime == 'audio/3gpp' ||
              mime == 'audio/amr' ||
              (a.waveform?.isNotEmpty ?? false);
          return isVoice ? '🎤' : '🎵';
        }
        return '📎';
      }

      String decodeStickerLabel(StickerEventV1 sticker) {
        final resolved = SecretlyStickerCatalog.resolveEvent(sticker);
        return SecretlyStickerCatalog.previewLabel(
          isRu: _isRussianSystemEventLocale,
          emojiHint: sticker.emojiHint.isNotEmpty
              ? sticker.emojiHint
              : resolved.emojiHint,
          label: sticker.label.isNotEmpty ? sticker.label : resolved.label,
        );
      }

      Future<void> cacheLocalPlain(Uint8List plainBytes) async {
        // Best-effort: persist a local display copy so we never need to decrypt the same ratchet
        // ciphertext twice (ratchet message keys are single-use).
        final existing = e.localCiphertextB64;
        if (existing != null && existing.isNotEmpty) return;
        final db = _db;
        final crypto = _crypto;
        if (db == null || crypto == null) return;
        try {
          final local = await crypto.encrypt(plainBytes);
          await db.updateEventLocalCiphertext(
            eventId: e.eventId,
            localCiphertextB64: base64Encode(local),
          );
        } catch (_) {
          // ignore
        }
      }

      // Preferred path: use cached local symmetric-encrypted plaintext.
      // Ratchet ciphertexts are stateful and cannot be decrypted multiple times.
      final localB64 = e.localCiphertextB64;
      if (localB64 != null && localB64.isNotEmpty) {
        final crypto = _crypto;
        if (crypto == null) return '…';
        final localBytes = base64Decode(localB64);
        final plainBytes = await crypto.decrypt(localBytes);
        final payload = E2ePayloadV1.decode(plainBytes);
        final first = payload.events.isNotEmpty ? payload.events.first : null;
        if (first is MsgEventV1) return first.text;
        if (first is SystemEventV1) {
          return formatSystemEventText(
            first,
            isRu: _isRussianSystemEventLocale,
            selfProfileId: _profileId?.trim(),
            localeTag: _effectiveAppLocaleTagForStrings(),
          );
        }
        if (first is AttachmentEventV1) return decodeAttachmentLabel(first);
        if (first is StickerEventV1) return decodeStickerLabel(first);
        if (first is CallEventV1) {
          return buildCallEventPreviewText(
            l10n: _appL10n,
            isRu: _isRussianSystemEventLocale,
            result: first.result,
            direction: first.direction,
            isVideo: first.hadVideo,
            durationMs: first.durationMs,
          );
        }
        return '…';
      }

      final cipherBytes = base64Decode(e.ciphertextB64);

      // Ratchet wire (v1.3): Double Ratchet (SKS2).
      final decodedV3 = RatchetWireV3.tryDecode(
        Uint8List.fromList(cipherBytes),
      );
      if (decodedV3 != null) {
        final db = _db;
        final pid = _profileId;
        final did = _deviceId;
        if (db == null || pid == null || did == null) return '…';
        final mgr = _ratchetV3;
        if (mgr == null) return '…';
        final plainBytes = await mgr.decryptFromWire(
          selfProfileId: pid,
          selfDeviceId: did,
          wireBytes: Uint8List.fromList(cipherBytes),
        );
        await cacheLocalPlain(Uint8List.fromList(plainBytes));
        final payload = E2ePayloadV1.decode(plainBytes);
        final first = payload.events.isNotEmpty ? payload.events.first : null;
        if (first is MsgEventV1) return first.text;
        if (first is SystemEventV1) {
          return formatSystemEventText(
            first,
            isRu: _isRussianSystemEventLocale,
            selfProfileId: _profileId?.trim(),
            localeTag: _effectiveAppLocaleTagForStrings(),
          );
        }
        if (first is AttachmentEventV1) return decodeAttachmentLabel(first);
        if (first is StickerEventV1) return decodeStickerLabel(first);
        if (first is CallEventV1) {
          return buildCallEventPreviewText(
            l10n: _appL10n,
            isRu: _isRussianSystemEventLocale,
            result: first.result,
            direction: first.direction,
            isVideo: first.hadVideo,
            durationMs: first.durationMs,
          );
        }
        return '…';
      }

      // Ratchet wire (v1.2): decrypt using per-peer session state.
      final decoded = RatchetWireV1.tryDecode(Uint8List.fromList(cipherBytes));
      if (decoded != null) {
        final db = _db;
        final pid = _profileId;
        final did = _deviceId;
        if (db == null || pid == null || did == null) return '…';
        final mgr = _ratchetV1;
        if (mgr == null) return '…';
        final plainBytes = await mgr.decryptFromWire(
          selfProfileId: pid,
          selfDeviceId: did,
          wireBytes: Uint8List.fromList(cipherBytes),
        );
        await cacheLocalPlain(Uint8List.fromList(plainBytes));
        final payload = E2ePayloadV1.decode(plainBytes);
        final first = payload.events.isNotEmpty ? payload.events.first : null;
        if (first is MsgEventV1) return first.text;
        if (first is SystemEventV1) {
          return formatSystemEventText(
            first,
            isRu: _isRussianSystemEventLocale,
            selfProfileId: _profileId?.trim(),
            localeTag: _effectiveAppLocaleTagForStrings(),
          );
        }
        if (first is AttachmentEventV1) return decodeAttachmentLabel(first);
        if (first is StickerEventV1) return decodeStickerLabel(first);
        return '…';
      }

      final crypto = _crypto;
      if (crypto == null) return '…';
      final plainBytes = await crypto.decrypt(cipherBytes);
      try {
        final payload = E2ePayloadV1.decode(plainBytes);
        final first = payload.events.isNotEmpty ? payload.events.first : null;
        if (first is MsgEventV1) return first.text;
        if (first is SystemEventV1) {
          return formatSystemEventText(
            first,
            isRu: _isRussianSystemEventLocale,
            selfProfileId: _profileId?.trim(),
            localeTag: _effectiveAppLocaleTagForStrings(),
          );
        }
        if (first is AttachmentEventV1) return decodeAttachmentLabel(first);
        if (first is StickerEventV1) return decodeStickerLabel(first);
        if (first is CallEventV1) {
          return buildCallEventPreviewText(
            l10n: _appL10n,
            isRu: _isRussianSystemEventLocale,
            result: first.result,
            direction: first.direction,
            isVideo: first.hadVideo,
            durationMs: first.durationMs,
          );
        }
        return '…';
      } catch (_) {
        // Fallback for older dev data.
        return utf8.decode(plainBytes);
      }
    } catch (_) {
      return '…';
    }
  }

  Future<AttachmentEventV1?> attachmentEventForChatEvent(ChatEvent e) async {
    final first = await payloadEventForChatEvent(e);
    return first is AttachmentEventV1 ? first : null;
  }

  Future<E2eEventV1?> payloadEventForChatEvent(ChatEvent e) async {
    final db = _db;
    final crypto = _crypto;
    if (db == null || crypto == null) return null;

    await decryptPlainAsync(e);

    final row = await db.eventGet(e.eventId);
    final localB64 = row?['local_ciphertext_b64'] as String?;
    if (localB64 != null && localB64.isNotEmpty) {
      try {
        final plainBytes = await crypto.decrypt(base64Decode(localB64));
        final payload = E2ePayloadV1.decode(plainBytes);
        return payload.events.isNotEmpty ? payload.events.first : null;
      } catch (_) {
        // fall through
      }
    }

    // Fallback for local outgoing events where ciphertext_b64 already contains
    // app-local encrypted payload and local cache was not written yet.
    try {
      final plainBytes = await crypto.decrypt(base64Decode(e.ciphertextB64));
      final payload = E2ePayloadV1.decode(plainBytes);
      return payload.events.isNotEmpty ? payload.events.first : null;
    } catch (_) {
      return null;
    }
  }

  /// Скачивает и расшифровывает стикер, приехавший в наборе ССЫЛКОЙ, а не
  /// пикселями.
  ///
  /// 🔴 `null` при любой неудаче, а не исключение. Это путь установки НАБОРА:
  /// один недоставшийся стикер не имеет права уронить установку остальных.
  /// Раньше такие стикеры вообще не приезжали, так что даже частичный набор —
  /// улучшение, а вот сорванная установка была бы ухудшением.
  Future<Uint8List?> _fetchSharedStickerBlob(
    StickerPackChunkSticker sticker,
  ) async {
    final blob = _blob;
    final attachments = _attachments;
    if (blob == null || attachments == null) return null;
    if (!sticker.hasBlob) return null;
    try {
      final ct = await blob
          .downloadCiphertext(
            sticker.blobId,
            accessTokenB64: sticker.accessTokenB64.isEmpty
                ? null
                : sticker.accessTokenB64,
          )
          .timeout(const Duration(seconds: 45));
      return await attachments.decryptDownloaded(
        ct,
        fileKeyB64: sticker.fileKeyB64,
      );
    } catch (e) {
      DiagLog.event('stickers', 'shared_blob_fetch_failed', {
        'err': _shortErrorTag(e),
      });
      return null;
    }
  }

  Future<Uint8List> downloadAndDecryptAttachment(AttachmentEventV1 a) async {
    final blob = _blob;
    final attachments = _attachments;
    if (blob == null || attachments == null) {
      throw StateError('Attachments not ready');
    }
    final accessTokenB64 = await _resolveAttachmentAccessTokenB64(a);
    final ct = await blob.downloadCiphertext(
      a.blobId,
      accessTokenB64: accessTokenB64,
    );
    return await attachments.decryptDownloaded(ct, fileKeyB64: a.fileKeyB64);
  }

  /// Готова ли подсистема вложений: клиент хранилища и служба расшифровки.
  ///
  /// 🔴 БЕЗ ЭТОГО ПРИЗНАКА ОТКАЗ БЫЛ НЕОТЛИЧИМ ОТ «НЕТ СВЯЗИ». Скачивание
  /// вложения бросает `StateError('Attachments not ready')`, когда транспорт
  /// ещё не поднят, — и снаружи это выглядело так же, как просроченный файл
  /// или обрыв сети. Признак читает галерея, чтобы сказать человеку правду.
  bool get attachmentsReady => _blob != null && _attachments != null;

  Future<File> downloadAndDecryptAttachmentToFile(
    AttachmentEventV1 a, {
    required File outputFile,
  }) async {
    final blob = _blob;
    final attachments = _attachments;
    if (blob == null || attachments == null) {
      throw StateError('Attachments not ready');
    }
    final accessTokenB64 = await _resolveAttachmentAccessTokenB64(a);
    await outputFile.parent.create(recursive: true);
    // 🔴 ИМЯ УНИКАЛЬНО (02.09.2026, аудит передачи файлов). Файл шифртекста
    // ниже получал уникальное имя по микросекундам, а этот — нет: он всегда
    // назывался `<blobId><расширение>.tmp`. Два скачивания одного вложения,
    // идущие одновременно, писали в ОДИН файл: содержимое перемешивалось, и
    // тот, кто добирался до переименования вторым, падал. Одновременность
    // здесь не редкость — предзагрузка и открытие пузыря стартуют из разных
    // мест и о существовании друг друга не знали.
    final tempOutput = File(
      '${outputFile.path}.${DateTime.now().microsecondsSinceEpoch}.tmp',
    );
    final tmpDir = await getTemporaryDirectory();
    final ciphertextFile = File(
      p.join(
        tmpDir.path,
        'att_cipher_${a.blobId}_${DateTime.now().microsecondsSinceEpoch}.bin',
      ),
    );
    try {
      if (await tempOutput.exists()) {
        await tempOutput.delete();
      }
      await blob.downloadCiphertextToFile(
        a.blobId,
        outputFile: ciphertextFile,
        accessTokenB64: accessTokenB64,
      );
      await attachments.decryptDownloadedFileToFile(
        ciphertextFile,
        fileKeyB64: a.fileKeyB64,
        outputFile: tempOutput,
      );
      if (await outputFile.exists()) {
        await outputFile.delete();
      }
      await tempOutput.rename(outputFile.path);
      return outputFile;
    } catch (_) {
      try {
        if (await tempOutput.exists()) {
          await tempOutput.delete();
        }
      } catch (_) {}
      rethrow;
    } finally {
      try {
        if (await ciphertextFile.exists()) {
          await ciphertextFile.delete();
        }
      } catch (_) {}
    }
  }

  Future<String?> _resolveAttachmentAccessTokenB64(AttachmentEventV1 a) async {
    var accessTokenB64 = a.blobAccessTokenB64?.trim();
    if ((accessTokenB64 == null || accessTokenB64.isEmpty) && _db != null) {
      final row = await _db!.attachmentGet(a.blobId);
      final stored = (row?['access_token_b64'] as String?)?.trim();
      if (stored != null && stored.isNotEmpty) {
        accessTokenB64 = stored;
      }
    }
    return accessTokenB64;
  }

  static String _extFromMime(String? mime) {
    final m = (mime ?? '').toLowerCase();
    if (m == 'image/jpeg') return '.jpg';
    if (m == 'image/png') return '.png';
    if (m == 'image/webp') return '.webp';
    if (m == 'image/gif') return '.gif';
    if (m == 'image/heic') return '.heic';
    if (m == 'image/heif') return '.heif';
    if (m == 'image/bmp') return '.bmp';
    if (m == 'video/mp4') return '.mp4';
    if (m == 'video/quicktime') return '.mov';
    if (m == 'video/x-matroska') return '.mkv';
    if (m == 'video/webm') return '.webm';
    if (m == 'video/x-msvideo') return '.avi';
    if (m == 'video/x-m4v') return '.m4v';
    if (m == 'video/3gpp') return '.3gp';
    if (m == 'audio/mpeg') return '.mp3';
    if (m == 'audio/mp4') return '.m4a';
    if (m == 'audio/aac') return '.aac';
    if (m == 'audio/wav') return '.wav';
    if (m == 'audio/ogg') return '.ogg';
    if (m == 'audio/opus') return '.opus';
    if (m == 'audio/flac') return '.flac';
    if (m == 'audio/x-ms-wma') return '.wma';
    if (m == 'audio/amr') return '.amr';
    if (m == 'application/pdf') return '.pdf';
    if (m == 'text/plain') return '.txt';
    return '.bin';
  }

  Future<File> cacheAttachmentToFile({
    required AttachmentEventV1 a,
    required Uint8List plaintext,
  }) async {
    final out = await _attachmentCacheFile(blobId: a.blobId, mime: a.mime);
    await out.writeAsBytes(plaintext, flush: true);
    return out;
  }

  Future<File?> cachedAttachmentFile(AttachmentEventV1 a) async {
    final out = await _attachmentCacheFile(blobId: a.blobId, mime: a.mime);
    if (await out.exists()) return out;
    return null;
  }

  /// Скачивания вложений, идущие прямо сейчас, по идентификатору блоба.
  ///
  /// 🔴 ПОЧЕМУ (02.09.2026, аудит передачи файлов). Дедупликация была
  /// разбросана по вызывающим, и у каждого своя: отдельный набор у
  /// предзагрузки, отдельный у ленты сообщений, отдельный у просмотра
  /// изображений — а галерея чата и её настольный вариант не имели никакой.
  /// Наборы не пересекались, поэтому предзагрузка и открытие пузыря спокойно
  /// начинали качать один и тот же блоб одновременно.
  ///
  /// Теперь дедупликация здесь, в единственной точке, через которую проходят
  /// все. Прежние наборы у вызывающих не мешают — они лишь отсекают часть
  /// лишних вызовов раньше.
  final Map<String, Future<File>> _attachmentFileDownloads =
      <String, Future<File>>{};

  Future<File> ensureCachedAttachmentFile(AttachmentEventV1 a) async {
    final cached = await cachedAttachmentFile(a);
    if (cached != null && await cached.exists()) {
      return cached;
    }
    final key = a.blobId.trim();
    if (key.isEmpty) {
      // Без идентификатора дедуплицировать нечего — прежний путь.
      final out = await _attachmentCacheFile(blobId: a.blobId, mime: a.mime);
      final file = await downloadAndDecryptAttachmentToFile(a, outputFile: out);
      unawaited(_pruneAttachmentCacheIfNeeded());
      return file;
    }
    final inflight = _attachmentFileDownloads[key];
    if (inflight != null) return inflight;

    final future = () async {
      final out = await _attachmentCacheFile(blobId: a.blobId, mime: a.mime);
      final file = await downloadAndDecryptAttachmentToFile(a, outputFile: out);
      unawaited(_pruneAttachmentCacheIfNeeded());
      return file;
    }();
    // Запись снимается в `finally`, иначе провалившееся скачивание навсегда
    // заняло бы ключ: повтор возвращал бы ту же ошибку, и вложение стало бы
    // недоступно до перезапуска.
    _attachmentFileDownloads[key] = future;
    try {
      return await future;
    } finally {
      _attachmentFileDownloads.remove(key);
    }
  }

  /// Record inbound attachment metadata so received media is in the prune's
  /// protected set (see the attachment-cache prune). The 1:1 receive path
  /// decrypts straight from the event, so without this received media would be
  /// treated as an orphan and evicted. Sizes/expiry aren't known here and are
  /// irrelevant to the protected set (it only reads blob_id) — pass 0.
  Future<void> _persistInboundAttachmentMetadata(E2ePayloadV1 payload) async {
    final db = _db;
    if (db == null) return;
    for (final ev in payload.events) {
      if (ev is! AttachmentEventV1) continue;
      final blobId = ev.blobId.trim();
      if (blobId.isEmpty) continue;
      try {
        await db.attachmentUpsert(
          blobId: blobId,
          fileKeyB64: ev.fileKeyB64,
          accessTokenB64: (ev.blobAccessTokenB64 ?? '').trim(),
          mime: ev.mime,
          plaintextSizeBytes: ev.sizeBytes,
          ciphertextSizeBytes: 0,
          expiresAtMs: 0,
          createdAtMs: DateTime.now().millisecondsSinceEpoch,
        );
      } catch (_) {
        // best-effort; the on-view download still works from the event's token
      }
    }
  }

  final Set<String> _attachmentPrefetchInFlight = <String>{};
  final List<AttachmentEventV1> _attachmentPrefetchQueue = <AttachmentEventV1>[];
  int _attachmentPrefetchActive = 0;
  static const int _attachmentPrefetchMaxConcurrent = 3;

  /// Fire-and-forget: eagerly cache every media blob in a freshly-applied
  /// inbound payload so photos/video/voice/files/music are READY without
  /// waiting for a lazy on-view fetch — the fix for media not appearing after
  /// the recipient was offline / in deep sleep. Bounded concurrency so a
  /// deep-sleep backlog can't launch a download/decrypt storm on the just-woken
  /// flaky network.
  void _prefetchInboundAttachmentBlobs(E2ePayloadV1 payload) {
    for (final ev in payload.events) {
      if (ev is AttachmentEventV1 && ev.blobId.trim().isNotEmpty) {
        _attachmentPrefetchQueue.add(ev);
      }
    }
    _pumpAttachmentPrefetchQueue();
  }

  void _pumpAttachmentPrefetchQueue() {
    while (_attachmentPrefetchActive < _attachmentPrefetchMaxConcurrent &&
        _attachmentPrefetchQueue.isNotEmpty) {
      final ev = _attachmentPrefetchQueue.removeAt(0);
      final blobId = ev.blobId.trim();
      if (blobId.isEmpty || _attachmentPrefetchInFlight.contains(blobId)) {
        continue;
      }
      _attachmentPrefetchActive++;
      unawaited(
        _prefetchOneAttachmentBlob(ev).whenComplete(() {
          _attachmentPrefetchActive--;
          _pumpAttachmentPrefetchQueue();
        }),
      );
    }
  }

  Future<void> _prefetchOneAttachmentBlob(AttachmentEventV1 a) async {
    final blobId = a.blobId.trim();
    if (blobId.isEmpty || _attachmentPrefetchInFlight.contains(blobId)) return;
    _attachmentPrefetchInFlight.add(blobId);
    try {
      final existing = await cachedAttachmentFile(a);
      if (existing != null) return; // already downloaded
      // The recipient often just woke on a flaky network — retry with backoff.
      for (var attempt = 0; attempt < 4; attempt++) {
        if (_transportBlocked) return;
        try {
          await ensureCachedAttachmentFile(a);
          // SCROLL-JANK FIX (2026-07-18): do NOT bump `_changed` here. It rebuilds
          // the WHOLE chat (fresh sliver delegate → every materialized row
          // re-runs) — the exact stutter upload progress was moved off the
          // changed stream to avoid. This prefetch is only a HEAD-START; the
          // media bubble resolves + repaints ITSELF the moment it scrolls into
          // view (the file is already cached), so no full rebuild is needed.
          return;
        } catch (_) {
          await Future<void>.delayed(Duration(seconds: 4 * (attempt + 1)));
        }
      }
    } catch (_) {
      // best-effort; the on-view fetch stays as the fallback
    } finally {
      _attachmentPrefetchInFlight.remove(blobId);
    }
  }

  Future<File?> cachedAttachmentFileByBlobId(String blobId) async {
    final db = _db;
    String? mime;
    if (db != null) {
      final row = await db.attachmentGet(blobId);
      mime = row?['mime'] as String?;
    }
    final out = await _attachmentCacheFile(blobId: blobId, mime: mime);
    if (await out.exists()) return out;
    return null;
  }

  /// PR7: prefetch attachment blobs for a conversation so they survive a
  /// fresh QR pair / restore / > 7-day offline window. Walks the most
  /// recent [maxEvents] rows for [convoId], decodes each payload, and
  /// triggers [ensureCachedAttachmentFile] for every [AttachmentEventV1]
  /// whose binary is not already on disk. Per-event errors are swallowed
  /// (best effort). Returns the number of *newly* downloaded blobs.
  ///
  /// Used by the desktop Settings → «Подкачать вложения» button.
  /// Mobile UX is untouched.
  Future<int> prefetchAttachmentsForConvo(
    String convoId, {
    int maxEvents = 500,
    int maxConcurrent = 2,
  }) async {
    final db = _db;
    final crypto = _crypto;
    final blob = _blob;
    final attachments = _attachments;
    if (db == null || crypto == null || blob == null || attachments == null) {
      return 0;
    }
    final effectiveConvoId = await _canonicalChatConvoIdForLoad(convoId);
    final rows = await db.listEvents(effectiveConvoId, limit: maxEvents);
    if (rows.isEmpty) return 0;

    final pending = <AttachmentEventV1>[];
    for (final r in rows) {
      final type = (r['type'] as String?) ?? 'msg';
      if (type != 'att') continue;

      Uint8List? plainBytes;
      final localB64 = (r['local_ciphertext_b64'] as String?)?.trim();
      if (localB64 != null && localB64.isNotEmpty) {
        try {
          plainBytes = Uint8List.fromList(
            await crypto.decrypt(base64Decode(localB64)),
          );
        } catch (_) {
          plainBytes = null;
        }
      }
      if (plainBytes == null) {
        final cipherB64 = (r['ciphertext_b64'] as String? ?? '').trim();
        if (cipherB64.isNotEmpty) {
          try {
            plainBytes = Uint8List.fromList(
              await crypto.decrypt(base64Decode(cipherB64)),
            );
          } catch (_) {
            plainBytes = null;
          }
        }
      }
      if (plainBytes == null) continue;

      try {
        final payload = E2ePayloadV1.decode(plainBytes);
        if (payload.events.isEmpty) continue;
        final ev = payload.events.first;
        if (ev is! AttachmentEventV1) continue;
        final cached = await cachedAttachmentFile(ev);
        if (cached != null) continue;
        pending.add(ev);
      } catch (_) {
        // Unknown / corrupt payload — skip.
      }
    }

    if (pending.isEmpty) return 0;

    var downloaded = 0;
    final lanes = math.max(1, maxConcurrent);
    for (var i = 0; i < pending.length; i += lanes) {
      final end = math.min(i + lanes, pending.length);
      final batch = pending.sublist(i, end);
      final results = await Future.wait(
        batch.map((a) async {
          try {
            await ensureCachedAttachmentFile(a);
            return true;
          } catch (_) {
            return false;
          }
        }),
      );
      for (final ok in results) {
        if (ok) downloaded++;
      }
    }
    return downloaded;
  }

  /// PR7: prefetch attachments across every recent conversation. Returns
  /// `(scannedConvos, downloadedBlobs)`. Best-effort; per-convo errors
  /// are swallowed.
  Future<({int convosScanned, int blobsDownloaded})>
  prefetchAttachmentsForAllConvos({
    int maxConvos = 200,
    int maxEventsPerConvo = 300,
  }) async {
    final db = _db;
    if (db == null) {
      return (convosScanned: 0, blobsDownloaded: 0);
    }
    final convos = await db.convoList(limit: maxConvos);
    var scanned = 0;
    var downloaded = 0;
    for (final row in convos) {
      final cid = row['convo_id'] as String?;
      if (cid == null || cid.isEmpty) continue;
      scanned++;
      try {
        final n = await prefetchAttachmentsForConvo(
          cid,
          maxEvents: maxEventsPerConvo,
        );
        downloaded += n;
      } catch (_) {
        // skip
      }
    }
    return (convosScanned: scanned, blobsDownloaded: downloaded);
  }

  Future<File> _attachmentCacheFile({
    required String blobId,
    String? mime,
  }) async {
    final dir = await getApplicationDocumentsDirectory();
    final attDir = Directory(p.join(dir.path, 'attachments'));
    if (!await attDir.exists()) {
      await attDir.create(recursive: true);
    }
    final ext = _extFromMime(mime);
    return File(p.join(attDir.path, '$blobId$ext'));
  }

  bool _attachmentCachePruneInFlight = false;

  Future<void> _clearLocalProfileMediaCaches() async {
    try {
      final dir = await getApplicationDocumentsDirectory();
      for (final sub in <String>[
        'attachments',
        'profile_media',
        'profile_avatars',
        'contact_avatars',
        'stickers',
      ]) {
        final cacheDir = Directory(p.join(dir.path, sub));
        if (await cacheDir.exists()) {
          await cacheDir.delete(recursive: true);
        }
      }
      final myAvatar = File(p.join(dir.path, 'my_avatar.png'));
      if (await myAvatar.exists()) {
        await myAvatar.delete();
      }
      await _db?.resetStickerPackInstallState();
      await _loadStickerCatalogFromDb();
    } catch (_) {
      // Best-effort local cache cleanup.
    }
  }

  /// TZ E0 (2026-07-18): blob ids whose cached file is the ONLY copy — chat
  /// history references them AND the relay can no longer serve the blob
  /// (`local:` id, expired TTL, or unknown expiry). The manual "Clear cache"
  /// action must never delete these; everything else in the attachments dir
  /// (orphans + still-fetchable remote blobs) is genuinely reclaimable.
  ///
  /// Returns null when the answer is unknowable (DB unavailable / query
  /// failure) — the caller must then treat the WHOLE attachments dir as
  /// protected, mirroring the prune's fail-safe (never guess with user data).
  Future<Set<String>?> irreplaceableAttachmentBlobIds() async {
    final db = _db;
    if (db == null) return null;
    try {
      final referenced = await db.attachmentAllBlobIds();
      // 1h margin so a blob about to expire mid-clear still counts as gone.
      final liveRemote = await db.attachmentLiveRemoteBlobIds(
        nowMs: DateTime.now().millisecondsSinceEpoch + 60 * 60 * 1000,
      );
      return referenced.difference(liveRemote);
    } catch (_) {
      return null;
    }
  }

  /// Не чаще одного обхода каталога в минуту.
  ///
  /// 🔴 ПОЧЕМУ (02.09.2026, аудит передачи файлов). Уборка запускается после
  /// КАЖДОГО скачанного вложения. Гейт «уже идёт» отсекал только совпавшие по
  /// времени вызовы, но обход каталога быстрый, и открытие чата с тридцатью
  /// картинками давало почти тридцать полных обходов подряд — со сложением
  /// размеров всех файлов и запросом в базу на каждом.
  ///
  /// Интервал не откладывает уборку «навсегда»: она реактивная и вызывается на
  /// каждом скачивании, поэтому первый же вызов после истечения минуты её и
  /// выполнит. Кэш за минуту прирастает на то, что человек успел открыть
  /// руками, — это заведомо меньше порога, ради которого уборка существует.
  static const int _attachmentCachePruneMinIntervalMs = 60 * 1000;
  int _attachmentCachePruneAtMs = 0;

  Future<void> _pruneAttachmentCacheIfNeeded() async {
    if (_attachmentCachePruneInFlight) return;
    final nowMs = DateTime.now().millisecondsSinceEpoch;
    final sinceLast = nowMs - _attachmentCachePruneAtMs;
    if (_attachmentCachePruneAtMs != 0 &&
        sinceLast >= 0 &&
        sinceLast < _attachmentCachePruneMinIntervalMs) {
      return;
    }
    _attachmentCachePruneAtMs = nowMs;
    _attachmentCachePruneInFlight = true;
    try {
      final db = _db;
      if (db == null) return;
      final dir = await getApplicationDocumentsDirectory();
      final attDir = Directory(p.join(dir.path, 'attachments'));
      if (!await attDir.exists()) return;

      // DATA-LOSS FIX (2026-07-17): chat media is NOT disposable cache. The
      // local file is the ONLY copy once the relay drops the blob past its TTL,
      // and own-sent media has no re-download path at all — so the old size/
      // count/age eviction silently deleted the user's videos and voice notes
      // ("3 дня назад отправлял видео и голосовые, сейчас их нет"). We now NEVER
      // evict a file whose blobId is referenced by chat history; only truly
      // ORPHANED files (failed/partial downloads, temp leftovers, media whose
      // message was deleted) are prunable. Fail-safe: if the protected set can't
      // be read, keep EVERYTHING rather than risk deleting real media.
      final Set<String> referencedBlobIds;
      try {
        referencedBlobIds = await db.attachmentAllBlobIds();
      } catch (_) {
        return;
      }

      final cutoffMs = DateTime.now()
          .subtract(_attachmentCacheMaxAge)
          .millisecondsSinceEpoch;
      final entries = <({File file, FileStat stat})>[];
      await for (final entity in attDir.list(followLinks: false)) {
        if (entity is! File) continue;
        // Filename is `<blobId><ext>` — protect referenced chat media, only
        // orphans (unknown blobIds) are eviction candidates.
        final blobId = p.basenameWithoutExtension(entity.path).trim();
        if (blobId.isEmpty || referencedBlobIds.contains(blobId)) continue;
        try {
          final stat = await entity.stat();
          if (stat.type != FileSystemEntityType.file) continue;
          entries.add((file: entity, stat: stat));
        } catch (_) {
          // ignore individual files
        }
      }
      if (entries.isEmpty) return;

      entries.sort(
        (a, b) => a.stat.modified.millisecondsSinceEpoch.compareTo(
          b.stat.modified.millisecondsSinceEpoch,
        ),
      );

      var totalBytes = entries.fold<int>(
        0,
        (sum, entry) => sum + entry.stat.size,
      );
      var remaining = entries.length;

      Future<void> deleteEntry(({File file, FileStat stat}) entry) async {
        try {
          await entry.file.delete();
          totalBytes -= entry.stat.size;
          remaining -= 1;
        } catch (_) {
          // ignore individual delete failures
        }
      }

      for (final entry in entries) {
        if (entry.stat.modified.millisecondsSinceEpoch < cutoffMs) {
          await deleteEntry(entry);
        }
      }

      if (remaining <= _attachmentCacheMaxFiles &&
          totalBytes <= _attachmentCacheMaxBytes) {
        return;
      }

      for (final entry in entries) {
        final stillExists = await entry.file.exists();
        if (!stillExists) continue;
        if (remaining <= _attachmentCacheMaxFiles &&
            totalBytes <= _attachmentCacheMaxBytes) {
          break;
        }
        await deleteEntry(entry);
      }
    } catch (_) {
      // Best-effort cache pruning.
    } finally {
      _attachmentCachePruneInFlight = false;
    }
  }

  Future<void> _cacheAttachmentBytes({
    required String blobId,
    required String? mime,
    required Uint8List plaintext,
  }) async {
    try {
      final out = await _attachmentCacheFile(blobId: blobId, mime: mime);
      await out.writeAsBytes(plaintext, flush: true);
      unawaited(_pruneAttachmentCacheIfNeeded());
    } catch (_) {
      // Best-effort local cache.
    }
  }

  Future<void> _cacheAttachmentFileFromPath({
    required String blobId,
    required String? mime,
    required String sourcePath,
  }) async {
    try {
      final src = File(sourcePath);
      if (!await src.exists()) return;
      final out = await _attachmentCacheFile(blobId: blobId, mime: mime);
      await src.copy(out.path);
      unawaited(_pruneAttachmentCacheIfNeeded());
    } catch (_) {
      // Best-effort local cache.
    }
  }

  // ── User-created stickers (F0): pixels travel as an E2EE blob ────────────
  // Within a session, dedup uploads by content hash so re-sending the same
  // cutout doesn't re-encrypt+upload it; dedup concurrent downloads on receipt.
  final Map<String, EncryptedAttachment> _userStickerBlobCache =
      <String, EncryptedAttachment>{};
  final Map<String, Future<SecretlyStickerDescriptor?>> _userStickerDownloads =
      <String, Future<SecretlyStickerDescriptor?>>{};
  static const int _userStickerBlobTtlSeconds = 7 * 24 * 60 * 60;

  String _stickerMimeFor(SecretlyStickerFormat format) => switch (format) {
    SecretlyStickerFormat.lottie => 'application/json',
    SecretlyStickerFormat.webp => 'image/webp',
    SecretlyStickerFormat.png => 'image/png',
  };

  Future<Directory> _userStickerCacheDir() async {
    final root = await _stickerCatalogRootDirectory();
    final dir = Directory('${root.path}/user');
    if (!await dir.exists()) {
      await dir.create(recursive: true);
    }
    return dir;
  }

  /// Upload a user-created sticker [stickerFile] as an E2EE blob (XChaCha20,
  /// the attachment scheme) and send it to [peerProfileId]. The pixels travel
  /// encrypted; the recipient downloads + decrypts + renders via
  /// [ensureUserStickerCached]. F0: per-send upload, deduped within a session.
  /// Copy a created sticker into the durable user-sticker cache keyed by its id
  /// (`${catalogRoot}/user/<stickerId>.<ext>`). This is the SAME path the chat's
  /// [_UserStickerResolver] looks at, so the sender's own mirror renders
  /// instantly with no self-download, and the file survives for later reuse.
  Future<String> _cacheUserStickerLocally(
    File stickerFile,
    String stickerId,
    SecretlyStickerFormat format,
  ) async {
    final ext = switch (format) {
      SecretlyStickerFormat.lottie => 'json',
      SecretlyStickerFormat.webp => 'webp',
      SecretlyStickerFormat.png => 'png',
    };
    final dir = await _userStickerCacheDir();
    final dest = File('${dir.path}/$stickerId.$ext');
    try {
      // Only the static PNG path is decoded + shrunk. Animated webp (and lottie)
      // MUST be copied byte-for-byte — re-encoding a webp as PNG would flatten it
      // to a single frame and kill the animation.
      if (format == SecretlyStickerFormat.png) {
        // Shrink for reliable upload on slow/flaky uplinks (the user's device
        // tops out near ~1 KB/s): cap the longest side at 256px and re-compress
        // (alpha preserved). A full 512 photo cutout is hundreds of KB — too big
        // to finish before the timeout; 256px is small enough to upload like the
        // text POSTs that already succeed, and still renders fine at the ~170px
        // chat size.
        final bytes = await stickerFile.readAsBytes();
        final decoded = img.decodeImage(bytes);
        if (decoded != null) {
          const maxSide = 256;
          final tall = decoded.height > decoded.width;
          final longest = tall ? decoded.height : decoded.width;
          final sized = longest > maxSide
              ? img.copyResize(
                  decoded,
                  width: tall ? null : maxSide,
                  height: tall ? maxSide : null,
                  interpolation: img.Interpolation.average,
                )
              : decoded;
          await dest.writeAsBytes(img.encodePng(sized, level: 9), flush: true);
          return dest.path;
        }
      }
      if (dest.path != stickerFile.path) {
        await stickerFile.copy(dest.path);
      }
    } catch (_) {
      try {
        if (dest.path != stickerFile.path) {
          await stickerFile.copy(dest.path);
        }
      } catch (_) {}
    }
    return dest.path;
  }

  /// Produce a SMALL base64 PNG to ship a user sticker INLINE inside the
  /// encrypted event over the WS (the fallback when the HTTP blob upload is
  /// blocked). Returns null for animated/lottie stickers or if it can't get
  /// under the inline budget (~32KB) even at 192px — callers then mark failed.
  /// Ссылка на шифртекст стикера для передачи набора: из кэша либо выгрузкой.
  ///
  /// 🔴 Кэш ПЕРВЫМ (схема v66). Набор в 50 стикеров без кэша означал бы 50
  /// выгрузок на каждый запрос набора, причём от разных людей — то есть чем
  /// популярнее набор, тем дороже он автору. С кэшем платится один раз на срок
  /// жизни блоба.
  ///
  /// 🔴 `null` при любой неясности: лучше отдать набор без одного стикера, чем
  /// ссылку, по которой ничего не скачается. Мёртвую ссылку получатель примет за
  /// поломку приложения, а не за неудачу выгрузки.
  Future<({String blobId, String fileKeyB64, String accessTokenB64})?>
  _stickerBlobForSharing(SecretlyStickerDescriptor sticker) async {
    final db = _db;
    if (db == null) return null;
    if (!sticker.packId.startsWith('user:')) return null;

    try {
      final cached = await db.stickerCachedBlob(
        packId: sticker.packId,
        packVersion: sticker.packVersion,
        stickerId: sticker.stickerId,
      );
      if (cached != null) return cached;
    } catch (e) {
      DiagLog.event('stickers', 'share_blob_cache_read_failed', {
        'err': _shortErrorTag(e),
      });
    }

    final attachments = _attachments;
    if (attachments == null || sticker.assetPath.isEmpty) return null;
    Uint8List bytes;
    try {
      bytes = await File(sticker.assetPath).readAsBytes();
    } catch (_) {
      return null;
    }
    if (bytes.isEmpty) return null;

    EncryptedAttachment? enc;
    try {
      enc = await attachments
          .encryptAndUpload(
            bytes,
            ttlSeconds: _userStickerBlobTtlSeconds,
            mime: _stickerMimeFor(sticker.format),
          )
          .timeout(const Duration(seconds: 60));
    } catch (e) {
      DiagLog.event('stickers', 'share_blob_upload_failed', {
        'err': _shortErrorTag(e),
      });
      return null;
    }

    try {
      await db.stickerRememberBlob(
        packId: sticker.packId,
        packVersion: sticker.packVersion,
        stickerId: sticker.stickerId,
        blobId: enc.blobId,
        fileKeyB64: enc.fileKeyB64,
        accessTokenB64: enc.blobAccessTokenB64,
        expiresAtMs: enc.expiresAtMs,
      );
    } catch (_) {
      // Не запомнилось — заплатим за выгрузку при следующем запросе.
    }
    return (
      blobId: enc.blobId,
      fileKeyB64: enc.fileKeyB64,
      accessTokenB64: enc.blobAccessTokenB64,
    );
  }

  Future<String?> _buildInlineStickerB64(
    SecretlyStickerDescriptor sticker,
  ) async {
    if (sticker.animated || sticker.format == SecretlyStickerFormat.lottie) {
      return null;
    }
    if (sticker.assetPath.isEmpty) return null;
    const maxBytes = 32 * 1024;
    try {
      final file = File(sticker.assetPath);
      if (!await file.exists()) return null;
      var bytes = await file.readAsBytes();
      if (bytes.isEmpty) return null;
      if (bytes.length > maxBytes) {
        // Re-shrink to 192px to fit the inline budget (alpha preserved).
        final decoded = img.decodeImage(bytes);
        if (decoded != null) {
          final tall = decoded.height > decoded.width;
          final longest = tall ? decoded.height : decoded.width;
          final small = longest > 192
              ? img.copyResize(
                  decoded,
                  width: tall ? null : 192,
                  height: tall ? 192 : null,
                  interpolation: img.Interpolation.average,
                )
              : decoded;
          bytes = Uint8List.fromList(img.encodePng(small, level: 9));
        }
      }
      if (bytes.length > maxBytes) {
        return null; // still too big — don't bloat WS
      }
      return base64Encode(bytes);
    } catch (_) {
      return null;
    }
  }

  /// Build a local `user:<pid>` descriptor for [stickerFile], caching a durable
  /// copy. If [upload] is true the bytes are encrypted + uploaded so a recipient
  /// can fetch them (needed for SENDING); otherwise it's a purely local
  /// descriptor (for saving to the user's own collection).
  Future<SecretlyStickerDescriptor> _buildUserStickerDescriptor(
    File stickerFile, {
    required SecretlyStickerFormat format,
    required String emoji,
    required bool animated,
    required bool upload,
  }) async {
    final pid = _profileId;
    if (pid == null) {
      throw StateError('Sticker unavailable: transport not ready');
    }
    final bytes = await stickerFile.readAsBytes();
    if (bytes.isEmpty) {
      throw StateError('Sticker file is empty');
    }
    final sha = crypto.sha256.convert(bytes).toString();
    final stickerId = sha.substring(0, 32);

    int? width;
    int? height;
    try {
      final decoded = img.decodeImage(bytes);
      if (decoded != null) {
        width = decoded.width;
        height = decoded.height;
      }
    } catch (_) {}

    final cachedPath = await _cacheUserStickerLocally(
      stickerFile,
      stickerId,
      format,
    );

    EncryptedAttachment? enc;
    if (upload) {
      final attachments = _attachments;
      if (attachments == null) {
        throw StateError('Sticker upload unavailable: transport not ready');
      }
      final nowMs = DateTime.now().millisecondsSinceEpoch;
      final cached = _userStickerBlobCache[sha];
      if (cached != null && cached.expiresAtMs > nowMs + 60000) {
        enc = cached;
      } else {
        final tmp = await getTemporaryDirectory();
        enc = await attachments.encryptFileAndUpload(
          stickerFile,
          tempDir: tmp,
          ttlSeconds: _userStickerBlobTtlSeconds,
          mime: _stickerMimeFor(format),
        );
        _userStickerBlobCache[sha] = enc;
      }
    }

    return SecretlyStickerDescriptor.localFile(
      packId: 'user:$pid',
      packVersion: 1,
      stickerId: stickerId,
      localFilePath: cachedPath,
      format: format,
      animated: animated,
      emojiHint: emoji,
      label: '',
      keywords: const <String>[],
      blobId: enc?.blobId,
      fileKeyB64: enc?.fileKeyB64,
      blobAccessTokenB64: enc?.blobAccessTokenB64,
      sizeBytes: bytes.length,
      width: width,
      height: height,
    );
  }

  Future<String> sendUserStickerFromFile({
    required String peerProfileId,
    required File stickerFile,
    SecretlyStickerFormat format = SecretlyStickerFormat.png,
    String emoji = '',
    bool animated = false,
    String? replyToPayloadEventId,
  }) async {
    // Self-chat («Избранное») renders from the local durable cache, so it needs
    // NO blob upload — uploading BEFORE the local insert was exactly why
    // self-chat sends showed nothing when the upload was slow/unavailable. Real
    // peers still get a blob so they can download the pixels.
    final selfChat = peerProfileId.trim() == (_profileId ?? '').trim();
    DiagLog.event('stickers', 'send_user_from_file', {
      'self': selfChat.toString(),
      'peer': DiagLog.pfx(peerProfileId),
    });
    // Always build a NO-BLOB descriptor — instant + cached. The blob is uploaded
    // later by sendSticker, AFTER the local mirror is already on screen (real
    // peers), or never (self-chat renders from the local cache). This keeps a
    // slow/unreachable blob endpoint from blocking the sticker from appearing.
    final descriptor = await _buildUserStickerDescriptor(
      stickerFile,
      format: format,
      emoji: emoji,
      animated: animated,
      upload: false,
    );
    // Keep it in the user's own collection so it's reusable from the picker.
    unawaited(_touchRecentSticker(descriptor));
    return sendSticker(
      peerProfileId: peerProfileId,
      sticker: descriptor,
      replyToPayloadEventId: replyToPayloadEventId,
    );
  }

  /// Persist a created sticker to one of the user's own packs WITHOUT sending it
  /// — backs the preview's «Сделать избранным» / «Добавить в набор». Purely
  /// local (no network). Defaults to the «Мои стикеры» pack.
  Future<void> persistUserStickerFromFile({
    required File stickerFile,
    SecretlyStickerFormat format = SecretlyStickerFormat.png,
    String emoji = '',
    bool animated = false,
    String? packId,
    String packTitle = 'Мои стикеры',
  }) async {
    final pid = _profileId;
    if (pid == null) {
      throw StateError('Sticker unavailable: profile not ready');
    }
    await addStickerToUserPack(
      stickerFile: stickerFile,
      packId: packId ?? 'user:$pid:default',
      packTitle: packTitle,
      format: format,
      emoji: emoji,
      animated: animated,
    );
  }

  /// Add a created sticker to a durable user pack (sticker_packs +
  /// sticker_pack_stickers), keyed `user:<pid>:<slug>`. Creates the pack on
  /// first use, refreshes the catalog so the picker shows it immediately, and
  /// adds it to recents. No network — the durable PNG is re-uploaded only when
  /// the sticker is actually sent (see [sendSticker]).
  Future<void> addStickerToUserPack({
    required File stickerFile,
    required String packId,
    required String packTitle,
    SecretlyStickerFormat format = SecretlyStickerFormat.png,
    String emoji = '',
    bool animated = false,
  }) async {
    final db = _db;
    if (db == null) {
      throw StateError('Stickers unavailable: storage not ready');
    }
    final bytes = await stickerFile.readAsBytes();
    if (bytes.isEmpty) {
      throw StateError('Sticker file is empty');
    }
    final sha = crypto.sha256.convert(bytes).toString();
    final stickerId = sha.substring(0, 32);
    int? width;
    int? height;
    try {
      final decoded = img.decodeImage(bytes);
      if (decoded != null) {
        width = decoded.width;
        height = decoded.height;
      }
    } catch (_) {}
    final cachedPath = await _cacheUserStickerLocally(
      stickerFile,
      stickerId,
      format,
    );
    final now = DateTime.now().millisecondsSinceEpoch;

    await db.upsertStickerPackSticker(
      sticker: (
        packId: packId,
        packVersion: 1,
        stickerId: stickerId,
        fileName: '$stickerId.png',
        localPath: cachedPath,
        format: format.wireValue,
        animated: animated,
        emojiHint: emoji,
        label: '',
        keywords: const <String>[],
        sha256B64: '',
        sizeBytes: bytes.length,
        downloadedAtMs: now,
        lastAccessedAtMs: now,
      ),
    );
    final count = (await db.listStickerCatalogStickers(
      packId: packId,
      packVersion: 1,
    )).length;
    await db.upsertStickerPackSummary(
      packId: packId,
      packVersion: 1,
      title: packTitle,
      iconStickerId: stickerId,
      iconEmojiHint: emoji,
      featuredRank: 0,
      stickerCount: count,
      updatedAtMs: now,
    );
    await _loadStickerCatalogFromDb();
    if (!_changed.isClosed) {
      _changed.add(null);
    }

    await _touchRecentSticker(
      SecretlyStickerDescriptor.localFile(
        packId: packId,
        packVersion: 1,
        stickerId: stickerId,
        localFilePath: cachedPath,
        format: format,
        animated: animated,
        emojiHint: emoji,
        label: '',
        keywords: const <String>[],
        sizeBytes: bytes.length,
        width: width,
        height: height,
      ),
    );
  }

  // ---- Sticker-pack share: recipient installs the sender's pack -----------
  // When a recipient taps a sticker someone sent them, they hold only that one
  // sticker. These let them pull + install the WHOLE pack from the sender over
  // the e2ee WS control channel (the path that works on upload-blocked nets).

  /// packIds we have an outstanding fetch request for — dedups repeat taps and
  /// gates unsolicited chunks. Cleared on install or give-up.
  final Set<String> _stickerPackInFlight = <String>{};

  /// Per-pack install progress while chunks arrive.
  final Map<String, int> _stickerPackReceived = <String, int>{};
  final Map<String, int> _stickerPackExpected = <String, int>{};

  /// Per-requester throttle on ANSWERING pack requests (DoS guard).
  final Map<String, int> _stickerPackAnsweredAtMs = <String, int>{};

  int _stickerPackLastChunkAtMs = 0;

  /// Last time we ingested ANY sticker-pack chunk — drives the sheet's progress
  /// + timeout. 0 if none this process lifetime.
  int get stickerPackLastChunkAtMs => _stickerPackLastChunkAtMs;

  /// Install progress for [packId] as (received, expected). expected 0 = unknown.
  (int, int) stickerPackInstallProgress(String packId) =>
      (_stickerPackReceived[packId] ?? 0, _stickerPackExpected[packId] ?? 0);

  /// True while a fetch for [packId] is outstanding.
  bool stickerPackFetchInFlight(String packId) =>
      _stickerPackInFlight.contains(packId);

  /// Recipient → author: ask for the rest of [packId]. [originPid] is the author
  /// (the sender of the tapped sticker). Inline-PNG chunks come back over the
  /// WS. No-op for our own pack (already local) or a fetch already in flight.
  Future<void> requestPeerStickerPack({
    required String packId,
    required String originPid,
  }) async {
    final myPid = (_profileId ?? '').trim();
    final origin = originPid.trim();
    if (packId.isEmpty || origin.isEmpty) return;
    if (origin == myPid) return; // our own pack — nothing to fetch
    if (_stickerPackInFlight.contains(packId)) return; // already requested
    _stickerPackInFlight.add(packId);
    _stickerPackReceived[packId] = 0;
    _stickerPackExpected[packId] = 0;
    if (!_changed.isClosed) _changed.add(null);
    final req = StickerPackRequest(requestId: _uuid.v4(), packId: packId);
    try {
      await sendControlMessage(
        peerProfileId: origin,
        controlText: encodeStickerPackRequest(req),
        strict: false,
      );
      DiagLog.event('stickers', 'pack_req_sent', {
        'pack': DiagLog.pfx(packId),
        'origin': DiagLog.pfx(origin),
      });
      // Give up after ~30s of silence (author offline / no inline-able stickers)
      // so the sheet's button falls back to «Установить» instead of hanging.
      Future.delayed(const Duration(seconds: 30), () {
        if (_stickerPackInFlight.remove(packId)) {
          DiagLog.event('stickers', 'pack_req_timeout', {
            'pack': DiagLog.pfx(packId),
            'received': (_stickerPackReceived[packId] ?? 0).toString(),
          });
          if (!_changed.isClosed) _changed.add(null);
        }
      });
    } catch (e) {
      _stickerPackInFlight.remove(packId);
      callLog('AppCtrl', 'requestPeerStickerPack send failed: $e');
      if (!_changed.isClosed) _changed.add(null);
    }
  }

  /// Author side: a peer asked for one of my user packs. Answer with inline-PNG
  /// chunks if I actually hold it (skips animated/lottie/oversized), throttled
  /// per requester. The transport ratchet already proves the requester is an
  /// established contact, so the gate here is ownership + rate-limit.
  Future<void> _respondToStickerPackRequest({
    required StickerPackRequest request,
    required String requestingProfileId,
    required String requestingDeviceId,
  }) async {
    final reqPid = requestingProfileId.trim();
    if (reqPid.isEmpty) return;
    if (!request.packId.startsWith('user:')) return;
    final pack = SecretlyStickerCatalog.pickerPackById(request.packId);
    if (pack == null || pack.stickers.isEmpty) return;
    final now = DateTime.now().millisecondsSinceEpoch;
    final last = _stickerPackAnsweredAtMs[reqPid] ?? 0;
    if (now - last < 3000) return; // one answer / 3s / requester
    _stickerPackAnsweredAtMs[reqPid] = now;

    final inlineables = <StickerPackChunkSticker>[];
    for (final s in pack.stickers) {
      final b64 = await _buildInlineStickerB64(s);
      if (b64 == null || b64.isEmpty) {
        // 🔴 РАНЬШЕ ЗДЕСЬ БЫЛО `continue`, и это был тихий дефект: вложить
        // инлайном нельзя анимированные, Lottie и крупные, поэтому они МОЛЧА
        // выбрасывались. Человек делился набором анимированных, получатель не
        // получал ничего, и никто не узнавал почему.
        //
        // Теперь отдаём ссылку на шифртекст: для анимированного стикера она
        // такая же маленькая, как для статичного. Кэш блоба (схема v66) делает
        // это почти бесплатным, а при промахе выгружаем один раз и запоминаем.
        final blob = await _stickerBlobForSharing(s);
        if (blob == null) continue;
        inlineables.add(
          StickerPackChunkSticker(
            stickerId: s.stickerId,
            inlinePngB64: '',
            format: s.format.wireValue,
            animated: s.animated,
            emojiHint: s.emojiHint,
            label: s.label,
            blobId: blob.blobId,
            fileKeyB64: blob.fileKeyB64,
            accessTokenB64: blob.accessTokenB64,
            sizeBytes: s.sizeBytes,
          ),
        );
        continue;
      }
      inlineables.add(
        StickerPackChunkSticker(
          stickerId: s.stickerId,
          inlinePngB64: b64,
          format: s.format.wireValue,
          animated: s.animated,
          emojiHint: s.emojiHint,
          label: s.label,
        ),
      );
    }
    if (inlineables.isEmpty) return;
    final total = inlineables.length;

    final chunks = <List<StickerPackChunkSticker>>[];
    var current = <StickerPackChunkSticker>[];
    var currentBytes = 0;
    for (final s in inlineables) {
      if (current.isNotEmpty &&
          (current.length >= kStickerPackMaxStickersPerChunk ||
              currentBytes + s.inlinePngB64.length >
                  kStickerPackMaxInlineBytesPerChunk)) {
        chunks.add(current);
        current = <StickerPackChunkSticker>[];
        currentBytes = 0;
        if (chunks.length >= kStickerPackMaxChunksPerRequest) break;
      }
      current.add(s);
      currentBytes += s.inlinePngB64.length;
    }
    if (current.isNotEmpty && chunks.length < kStickerPackMaxChunksPerRequest) {
      chunks.add(current);
    }

    for (var i = 0; i < chunks.length; i++) {
      final chunk = StickerPackChunk(
        requestId: request.requestId,
        packId: request.packId,
        packTitle: pack.title,
        totalCount: total,
        seq: i,
        done: i == chunks.length - 1,
        stickers: chunks[i],
      );
      try {
        await sendControlMessage(
          peerProfileId: reqPid,
          controlText: encodeStickerPackChunk(chunk),
          strict: false,
          targetDeviceIds: requestingDeviceId.isNotEmpty
              ? <String>[requestingDeviceId]
              : null,
        );
      } catch (e) {
        callLog('AppCtrl', '_respondToStickerPackRequest chunk $i failed: $e');
        return;
      }
    }
    DiagLog.event('stickers', 'pack_answered', {
      'pack': DiagLog.pfx(request.packId),
      'to': DiagLog.pfx(reqPid),
      'count': total.toString(),
      'chunks': chunks.length.toString(),
    });
  }

  /// Recipient side: apply one inline-PNG chunk of a pack we requested. Writes
  /// each sticker into the same durable cache [ensureUserStickerCached] reads,
  /// then installs the pack (so it shows in the picker) once the last chunk
  /// lands. Ignores chunks for packs we didn't ask for.
  Future<void> _applyStickerPackChunk({
    required StickerPackChunk chunk,
    required String fromProfileId,
  }) async {
    final db = _db;
    if (db == null) return;
    if (!_stickerPackInFlight.contains(chunk.packId)) return;

    final dir = await _userStickerCacheDir();
    final now = DateTime.now().millisecondsSinceEpoch;
    var written = 0;
    for (final s in chunk.stickers) {
      try {
        // 🔴 ДВА ИСТОЧНИКА, и порядок важен. Инлайн — быстрый путь (пиксели уже
        // в сообщении, сети не нужно). Ссылка на блоб — то, чем теперь приезжают
        // анимированные, Lottie и крупные стикеры: раньше они молча
        // выбрасывались на СТОРОНЕ ОТПРАВИТЕЛЯ, и набор доходил обрезанным.
        Uint8List bytes;
        if (s.hasInline) {
          bytes = Uint8List.fromList(base64Decode(s.inlinePngB64));
        } else if (s.hasBlob) {
          final fetched = await _fetchSharedStickerBlob(s);
          if (fetched == null) continue;
          bytes = fetched;
        } else {
          continue;
        }
        if (bytes.isEmpty) continue;
        // 🔴 Проверка «это PNG» применима ТОЛЬКО к инлайну. Через блоб приезжают
        // Lottie (JSON) и webp, и требовать от них подписи PNG значило бы
        // выбросить ровно то, ради чего блоб-путь и сделан.
        if (s.hasInline &&
            !stickerPackBytesLookLikePng(Uint8List.fromList(bytes))) {
          continue;
        }
        final ext = s.format == 'lottie'
            ? 'json'
            : (s.format == 'webp' ? 'webp' : 'png');
        final dest = File('${dir.path}/${s.stickerId}.$ext');
        await dest.writeAsBytes(bytes, flush: true);
        await db.upsertStickerPackSticker(
          sticker: (
            packId: chunk.packId,
            packVersion: 1,
            stickerId: s.stickerId,
            fileName: '${s.stickerId}.$ext',
            localPath: dest.path,
            format: s.format.isEmpty ? 'png' : s.format,
            animated: s.animated,
            emojiHint: s.emojiHint,
            label: s.label,
            keywords: const <String>[],
            sha256B64: '',
            sizeBytes: bytes.length,
            downloadedAtMs: now,
            lastAccessedAtMs: now,
          ),
        );
        written++;
      } catch (_) {}
    }
    _stickerPackReceived[chunk.packId] =
        (_stickerPackReceived[chunk.packId] ?? 0) + written;
    if (chunk.totalCount > 0) {
      _stickerPackExpected[chunk.packId] = chunk.totalCount;
    }
    _stickerPackLastChunkAtMs = now;

    if (chunk.done) {
      final stickers = await db.listStickerCatalogStickers(
        packId: chunk.packId,
        packVersion: 1,
      );
      if (stickers.isNotEmpty) {
        await db.upsertStickerPackSummary(
          packId: chunk.packId,
          packVersion: 1,
          title: chunk.packTitle.isNotEmpty ? chunk.packTitle : 'Стикеры',
          iconStickerId: stickers.first.stickerId,
          iconEmojiHint: '',
          featuredRank: 0,
          stickerCount: stickers.length,
          updatedAtMs: now,
        );
        await db.setStickerPackInstalled(
          packId: chunk.packId,
          packVersion: 1,
          installed: true,
          installedAtMs: now,
        );
        await _loadStickerCatalogFromDb();
      }
      _stickerPackInFlight.remove(chunk.packId);
      DiagLog.event('stickers', 'pack_installed', {
        'pack': DiagLog.pfx(chunk.packId),
        'count': stickers.length.toString(),
      });
    }
    if (!_changed.isClosed) _changed.add(null);
  }

  /// The user's own sticker packs currently offered in the picker (packId
  /// `user:…`), used by the «Добавить в набор» chooser.
  List<SecretlyStickerPack> listUserStickerPacks() {
    return SecretlyStickerCatalog.pickerPacks
        .where((pack) => pack.id.startsWith('user:'))
        .toList(growable: false);
  }

  /// Remove one sticker from a user pack («изменить»). Drops the pack entirely
  /// once it's empty. Refreshes the catalog + open UI.
  Future<void> deleteUserStickerFromPack({
    required String packId,
    required String stickerId,
  }) async {
    final db = _db;
    if (db == null) return;
    await db.deleteStickerPackSticker(
      packId: packId,
      packVersion: 1,
      stickerId: stickerId,
    );
    final remaining = await db.listStickerCatalogStickers(
      packId: packId,
      packVersion: 1,
    );
    if (remaining.isEmpty) {
      await db.deleteStickerCatalogPack(packId: packId, packVersion: 1);
    } else {
      await db.upsertStickerPackSummary(
        packId: packId,
        packVersion: 1,
        title: _userPackTitleFallback(packId),
        iconStickerId: remaining.first.stickerId,
        featuredRank: 0,
        stickerCount: remaining.length,
        updatedAtMs: DateTime.now().millisecondsSinceEpoch,
      );
    }
    await _loadStickerCatalogFromDb();
    if (!_changed.isClosed) {
      _changed.add(null);
    }
  }

  /// Set which sticker is the pack's cover/icon in the picker.
  Future<void> setUserStickerPackCover({
    required String packId,
    required String stickerId,
  }) async {
    final db = _db;
    if (db == null) return;
    final stickers = await db.listStickerCatalogStickers(
      packId: packId,
      packVersion: 1,
    );
    if (stickers.isEmpty) {
      return;
    }
    await db.upsertStickerPackSummary(
      packId: packId,
      packVersion: 1,
      title: _userPackTitleFallback(packId),
      iconStickerId: stickerId,
      featuredRank: 0,
      stickerCount: stickers.length,
      updatedAtMs: DateTime.now().millisecondsSinceEpoch,
    );
    await _loadStickerCatalogFromDb();
    if (!_changed.isClosed) {
      _changed.add(null);
    }
  }

  String _userPackTitleFallback(String packId) {
    final existing = SecretlyStickerCatalog.pickerPacks
        .where((pack) => pack.id == packId)
        .map((pack) => pack.title)
        .firstOrNull;
    return (existing == null || existing.isEmpty) ? 'Мои стикеры' : existing;
  }

  /// Resolve a received USER sticker (one carrying an E2EE blob) to a local-file
  /// descriptor, downloading + decrypting the blob into the sticker cache on
  /// first use. Returns null for catalog stickers (no blob). Concurrent calls
  /// for the same sticker share a single download.
  Future<SecretlyStickerDescriptor?> ensureUserStickerCached(
    StickerEventV1 event,
  ) async {
    // Resolve user-pack stickers (packId `user:…`) even with NO blob — the
    // sender's own created stickers carry no blob (esp. in self-chat) but live
    // in the durable cache. Non-user stickers without a blob have nothing local.
    final isUserPack = event.packId.startsWith('user:');
    if (!event.hasInlineBlob && !isUserPack && !event.hasInlinePng) return null;

    final format = SecretlyStickerFormatWire.fromWire(event.format);
    final ext = switch (format) {
      SecretlyStickerFormat.lottie => 'json',
      SecretlyStickerFormat.webp => 'webp',
      SecretlyStickerFormat.png => 'png',
    };
    final safeId = event.stickerId.replaceAll(RegExp(r'[^A-Za-z0-9_-]'), '');
    if (safeId.isEmpty) return null;
    final key = 'user-sticker:$safeId.$ext';

    final inflight = _userStickerDownloads[key];
    if (inflight != null) return inflight;

    final future = () async {
      try {
        // Durable cache hit FIRST — the sender's OWN created stickers (written
        // by _cacheUserStickerLocally) render instantly with no blob and no
        // self-download; received stickers land here after the download below.
        final dir = await _userStickerCacheDir();
        final outFile = File('${dir.path}/$safeId.$ext');
        if (await outFile.exists() && await outFile.length() > 0) {
          return _userStickerDescriptorForFile(event, outFile.path, format);
        }
        // INLINE fallback: the sticker shipped its pixels in the event (sent
        // over the WS when the sender's blob upload was blocked). Write them to
        // the same cache path and render — no download needed.
        if (event.hasInlinePng) {
          try {
            final inlineBytes = base64Decode(event.inlinePngB64!);
            if (inlineBytes.isNotEmpty) {
              await outFile.writeAsBytes(inlineBytes, flush: true);
              return _userStickerDescriptorForFile(event, outFile.path, format);
            }
          } catch (_) {}
        }
        // Not cached — need the E2EE blob to fetch it (a received sticker).
        final blobId = event.blobId;
        final fileKeyB64 = event.fileKeyB64;
        if (blobId == null || blobId.isEmpty || fileKeyB64 == null) return null;
        final blob = _blob;
        final attachments = _attachments;
        if (blob == null || attachments == null) return null;
        final tmp = await getTemporaryDirectory();
        final cipherFile = File('${tmp.path}/sticker_dl_$safeId.bin');
        await blob.downloadCiphertextToFile(
          blobId,
          outputFile: cipherFile,
          accessTokenB64: event.blobAccessTokenB64,
        );
        final out = await attachments.decryptDownloadedFileToFile(
          cipherFile,
          fileKeyB64: fileKeyB64,
          outputFile: outFile,
        );
        try {
          await cipherFile.delete();
        } catch (_) {}
        return _userStickerDescriptorForFile(event, out.path, format);
      } catch (e) {
        DiagLog.event('stickers', 'user_sticker_download_fail', {
          'err': e.toString(),
        });
        return null;
      } finally {
        _userStickerDownloads.remove(key);
      }
    }();
    _userStickerDownloads[key] = future;
    return future;
  }

  SecretlyStickerDescriptor _userStickerDescriptorForFile(
    StickerEventV1 event,
    String path,
    SecretlyStickerFormat format,
  ) {
    return SecretlyStickerDescriptor.localFile(
      packId: event.packId,
      packVersion: event.packVersion,
      stickerId: event.stickerId,
      localFilePath: path,
      format: format,
      animated: event.animated,
      emojiHint: event.emojiHint,
      label: event.label,
      keywords: const <String>[],
    );
  }

  Future<String> sendSticker({
    required String peerProfileId,
    required SecretlyStickerDescriptor sticker,
    String? replyToPayloadEventId,
  }) async {
    // Whether this is a user sticker whose blob must be uploaded lazily (after
    // the local mirror is shown) — true for a freshly created sticker and for a
    // reused one (from recents / «Мои стикеры») that has no live blob.
    final isSelfChat = peerProfileId.trim() == (_profileId ?? '').trim();

    final trimmedPeerId = peerProfileId.trim();
    if (trimmedPeerId.startsWith('group:')) {
      return sendGroupSticker(
        groupId: trimmedPeerId,
        sticker: sticker,
        replyToPayloadEventId: replyToPayloadEventId,
      );
    }

    final db = _db;
    final did = _deviceId;
    final pid = _profileId;
    final crypto = _crypto;
    if (db == null || did == null || pid == null || crypto == null) {
      throw StateError('Sticker send unavailable: local state is not ready');
    }

    final resolvedPeerProfileId =
        await _normalizeDirectPeerProfileId(peerProfileId) ?? peerProfileId;
    if (resolvedPeerProfileId.startsWith('dev:')) {
      throw StateError(
        'Waiting for contact identity sync. Ask the contact to send one more message and try again.',
      );
    }

    if (await db.blockedProfileIsBlocked(resolvedPeerProfileId)) {
      throw StateError('Contact is blocked');
    }

    final eventId = _uuid.v4();
    final now = DateTime.now().millisecondsSinceEpoch;
    // Pack metadata for the recipient's "open pack" sheet: the title + total so
    // they know this sticker belongs to a multi-sticker pack worth installing,
    // and the origin pid to address the pack-fetch request back to. Only for
    // user packs we hold locally; null otherwise (unchanged for catalog).
    final sendPackMeta = sticker.packId.startsWith('user:')
        ? SecretlyStickerCatalog.pickerPackById(sticker.packId)
        : null;
    final sendPackTitle = sendPackMeta?.title;
    final sendPackCount = sendPackMeta?.stickers.length;
    final sendPackOriginPid = sticker.packId.startsWith('user:') ? pid : null;
    final payload = E2ePayloadV1(
      senderDeviceId: did,
      createdAtMs: now,
      events: [
        StickerEventV1(
          eventId: eventId,
          packId: sticker.packId,
          packVersion: sticker.packVersion,
          stickerId: sticker.stickerId,
          emojiHint: sticker.emojiHint,
          label: sticker.label,
          animated: sticker.animated,
          format: sticker.format.wireValue,
          replyToEventId: replyToPayloadEventId,
          // User-created sticker: ship its pixels as an E2EE blob the recipient
          // downloads (null for catalog stickers — unchanged behaviour).
          blobId: sticker.blobId,
          fileKeyB64: sticker.fileKeyB64,
          blobAccessTokenB64: sticker.blobAccessTokenB64,
          sizeBytes: sticker.sizeBytes,
          width: sticker.width,
          height: sticker.height,
        ),
      ],
    );

    // Self-chat / «Избранное»: insert locally, NO relay (so it works even when
    // the relay is unreachable). Robust to id normalization — also matches the
    // raw self target so a normalized id never pushes us onto the relay path.
    if (resolvedPeerProfileId == pid || isSelfChat) {
      final selfConvoId = pid;
      DiagLog.event('stickers', 'send_self', {
        'resolved_is_pid': (resolvedPeerProfileId == pid).toString(),
        'is_self': isSelfChat.toString(),
      });
      final localCipher = await crypto.encrypt(payload.encode());
      await db.convoEnsure1to1(peerProfileId: selfConvoId);
      await _retryDbBusy(() async {
        await db.insertEvent(
          eventId: 'local:$eventId',
          convoId: selfConvoId,
          type: 'sticker',
          senderDeviceId: did,
          ciphertextB64: base64Encode(localCipher),
          createdAtMs: now,
          localState: 'sent',
          payloadEventId: eventId,
        );
        await db.convoTouch(convoId: selfConvoId, atMs: now);
      });
      await _touchRecentSticker(sticker);
      _changed.add(null);
      return eventId;
    }

    final demoConvoId = _isDemoConvoId(resolvedPeerProfileId)
        ? resolvedPeerProfileId
        : peerProfileId;
    if (_isDemoConvoId(demoConvoId)) {
      if (!_demoDataEnabled) {
        throw StateError('Demo chats are disabled in this build.');
      }
      final demoTitle = _demoDisplayName(demoConvoId);
      final cipher = await crypto.encrypt(payload.encode());
      if (demoConvoId.startsWith('group:')) {
        await db.convoEnsureGroup(groupId: demoConvoId, title: demoTitle);
      } else {
        await db.convoEnsure1to1(peerProfileId: demoConvoId);
        await db.contactUpsert(
          profileId: demoConvoId,
          displayName: demoTitle,
          displayNameIsCustom: true,
        );
      }
      await db.insertEvent(
        eventId: 'local:$eventId',
        convoId: demoConvoId,
        type: 'sticker',
        senderDeviceId: did,
        ciphertextB64: base64Encode(cipher),
        createdAtMs: now,
        localState: 'sent',
        payloadEventId: eventId,
      );
      await db.convoTouch(convoId: demoConvoId, atMs: now);
      _changed.add(null);
      await _touchRecentSticker(sticker);

      Future.delayed(const Duration(milliseconds: 900), () async {
        final db2 = _db;
        if (db2 == null) return;
        await db2.updateLocalStateByPayloadEventId(
          payloadEventId: eventId,
          localState: 'delivered',
        );
        _changed.add(null);
      });
      Future.delayed(const Duration(milliseconds: 1600), () async {
        final db2 = _db;
        if (db2 == null) return;
        await db2.updateLocalStateByPayloadEventId(
          payloadEventId: eventId,
          localState: 'read',
        );
        _changed.add(null);
      });

      Future.delayed(const Duration(milliseconds: 650), () async {
        final db2 = _db;
        final crypto2 = _crypto;
        if (db2 == null || crypto2 == null) return;
        final rid = _uuid.v4();
        final reply = E2ePayloadV1(
          senderDeviceId: demoDeviceId,
          createdAtMs: DateTime.now().millisecondsSinceEpoch,
          events: [
            MsgEventV1(eventId: rid, text: '👍 ${_demoAutoReply(demoConvoId)}'),
          ],
        );
        final c2 = await crypto2.encrypt(reply.encode());
        final t2 = DateTime.now().millisecondsSinceEpoch;
        await db2.insertEvent(
          eventId: 'in:$rid',
          convoId: demoConvoId,
          type: 'msg',
          senderDeviceId: demoDeviceId,
          ciphertextB64: base64Encode(c2),
          createdAtMs: t2,
          localState: 'received',
        );
        await db2.convoTouch(convoId: demoConvoId, atMs: t2);
        _changed.add(null);
      });

      return eventId;
    }

    if (!await ensureOutgoingTransportReady()) {
      throw _transportUnavailableStateError('Sticker send unavailable');
    }

    final readyRelay = _relay;
    final readyKeys = _keys;
    final readyRatchet = _ratchetV3;
    final readyDid = _deviceId;
    final readyPid = _profileId;
    if (readyRelay == null ||
        readyKeys == null ||
        readyRatchet == null ||
        readyDid == null ||
        readyPid == null) {
      throw _transportUnavailableStateError('Sticker send unavailable');
    }

    _throwIfTransportBlocked();
    final readyForDirectChat = await _ensureDirectConversationReadyForOutgoing(
      resolvedPeerProfileId,
    );
    if (!readyForDirectChat) {
      throw StateError('Contact is blocked');
    }

    // FIX E — cheap pre-send trigger for proactive silence recovery. If this
    // peer has gone silent since our last send (background timers may not have
    // fired while suspended), kick a forced device-refresh + reset-ping now so
    // this very message stops targeting a stale/dead device_id. Fire-and-forget
    // and per-peer throttled — it never blocks or throws into the send.
    _maybeKickSilenceRecoveryBeforeSend(resolvedPeerProfileId);

    final directPayload = E2ePayloadV1(
      senderDeviceId: readyDid,
      createdAtMs: now,
      events: [
        StickerEventV1(
          eventId: eventId,
          packId: sticker.packId,
          packVersion: sticker.packVersion,
          stickerId: sticker.stickerId,
          emojiHint: sticker.emojiHint,
          label: sticker.label,
          animated: sticker.animated,
          format: sticker.format.wireValue,
          replyToEventId: replyToPayloadEventId,
          // The wire copy the recipient actually decodes — carry the user
          // sticker's blob so they can download + render it.
          blobId: sticker.blobId,
          fileKeyB64: sticker.fileKeyB64,
          blobAccessTokenB64: sticker.blobAccessTokenB64,
          sizeBytes: sticker.sizeBytes,
          width: sticker.width,
          height: sticker.height,
        ),
      ],
    );

    final localCipher = await crypto.encrypt(directPayload.encode());
    final localB64 = base64Encode(localCipher);
    final localEventId = 'local:$eventId';
    final transportMetaJson = _buildChatTransportMetaJson(
      convoId: resolvedPeerProfileId,
      isGroup: false,
      messageKind: 'sticker',
      payloadEventId: eventId,
      createdAtMs: now,
      senderProfileId: readyPid,
      senderDisplayName: myNickname,
      previewText: _pushTransportPreviewForSticker(sticker),
    );
    await _retryDbBusy(() async {
      await db.insertEvent(
        eventId: localEventId,
        convoId: resolvedPeerProfileId,
        type: 'sticker',
        senderDeviceId: did,
        ciphertextB64: localB64,
        createdAtMs: now,
        localState: MessageLocalState.pending,
        payloadEventId: eventId,
      );
      await db.convoTouch(convoId: resolvedPeerProfileId, atMs: now);
    });
    _changed.add(null);

    // Deferred blob upload: the mirror is on screen now (it renders from the
    // local cache). Upload the pixels so the recipient can fetch them — with a
    // timeout so a slow/unreachable blob endpoint marks the message failed
    // instead of hanging forever and never showing the sticker at all.
    var fanoutPayload = directPayload;
    final needsBlobUpload =
        sticker.packId.startsWith('user:') &&
        !sticker.hasInlineBlob &&
        sticker.assetPath.isNotEmpty;
    if (needsBlobUpload) {
      final attachments = _attachments;
      EncryptedAttachment? enc;
      if (attachments != null) {
        final upStartMs = DateTime.now().millisecondsSinceEpoch;
        // Use the BUFFERED in-memory upload (encryptAndUpload → a plain
        // _http.post), NOT the streamed file upload (encryptFileAndUpload): the
        // streamed path closes its StreamedRequest sink BEFORE the request body
        // is consumed by send(), which stalls until the timeout on some networks
        // — exactly the 60s hang we saw, while plain text/buffered POSTs go
        // through. Stickers are tiny, so reading them into memory is fine.
        Uint8List stickerBytes;
        try {
          stickerBytes = await File(sticker.assetPath).readAsBytes();
        } catch (_) {
          stickerBytes = Uint8List(0);
        }
        for (
          var attempt = 1;
          attempt <= 3 && enc == null && stickerBytes.isNotEmpty;
          attempt++
        ) {
          try {
            enc = await attachments
                .encryptAndUpload(
                  stickerBytes,
                  ttlSeconds: _userStickerBlobTtlSeconds,
                  mime: _stickerMimeFor(sticker.format),
                )
                .timeout(const Duration(seconds: 60));
            DiagLog.event('stickers', 'send_blob_upload_ok', {
              'attempt': attempt.toString(),
              'ms': (DateTime.now().millisecondsSinceEpoch - upStartMs)
                  .toString(),
              'bytes': (sticker.sizeBytes ?? 0).toString(),
            });
          } catch (e) {
            DiagLog.event('stickers', 'send_blob_upload_fail', {
              'attempt': attempt.toString(),
              'err': e.toString(),
            });
            if (attempt < 3) {
              await Future<void>.delayed(const Duration(seconds: 3));
            }
          }
        }
      }
      if (enc == null) {
        // Blob upload is blocked on this device (HTTP file POSTs hang) — fall
        // back to shipping a SMALL inline copy over the WS message path, which
        // works (text delivers fine). Recipients render it with no download.
        final inlineB64 = await _buildInlineStickerB64(sticker);
        if (inlineB64 == null) {
          await db.updateEventLocalState(
            eventId: localEventId,
            localState: MessageLocalState.failed,
            reasonCode: MessageFailureReason.noDeliverableTarget,
          );
          _changed.add(null);
          return eventId;
        }
        DiagLog.event('stickers', 'send_inline_fallback', {
          'b64len': inlineB64.length.toString(),
        });
        fanoutPayload = E2ePayloadV1(
          senderDeviceId: readyDid,
          createdAtMs: now,
          events: [
            StickerEventV1(
              eventId: eventId,
              packId: sticker.packId,
              packVersion: sticker.packVersion,
              stickerId: sticker.stickerId,
              emojiHint: sticker.emojiHint,
              label: sticker.label,
              animated: sticker.animated,
              format: sticker.format.wireValue,
              replyToEventId: replyToPayloadEventId,
              inlinePngB64: inlineB64,
              sizeBytes: sticker.sizeBytes,
              width: sticker.width,
              height: sticker.height,
              packTitle: sendPackTitle,
              packStickerCount: sendPackCount,
              packOriginPid: sendPackOriginPid,
            ),
          ],
        );
      } else {
        fanoutPayload = E2ePayloadV1(
          senderDeviceId: readyDid,
          createdAtMs: now,
          events: [
            StickerEventV1(
              eventId: eventId,
              packId: sticker.packId,
              packVersion: sticker.packVersion,
              stickerId: sticker.stickerId,
              emojiHint: sticker.emojiHint,
              label: sticker.label,
              animated: sticker.animated,
              format: sticker.format.wireValue,
              replyToEventId: replyToPayloadEventId,
              blobId: enc.blobId,
              fileKeyB64: enc.fileKeyB64,
              blobAccessTokenB64: enc.blobAccessTokenB64,
              sizeBytes: sticker.sizeBytes,
              width: sticker.width,
              height: sticker.height,
              packTitle: sendPackTitle,
              packStickerCount: sendPackCount,
              packOriginPid: sendPackOriginPid,
            ),
          ],
        );
      }
    }

    try {
      final targets = await _listRecipientDevicesForSend(
        peerProfileId: resolvedPeerProfileId,
        selfDeviceId: did,
      );
      if (targets.isEmpty) {
        bool exists = false;
        try {
          exists = await readyKeys.profileExists(resolvedPeerProfileId);
        } catch (_) {
          // ignore
        }

        if (!exists) {
          throw StateError(
            'Recipient profile not found on server. Check Secretly ID / ensure both use the same server. (peer_profile_id=$peerProfileId)',
          );
        }

        await _queuePendingNoDeviceEntry(
          profileId: resolvedPeerProfileId,
          entry: _PendingNoDeviceEntry(
            localEventId: localEventId,
            payloadBytes: Uint8List.fromList(fanoutPayload.encode()),
            transportMetaJson: transportMetaJson,
            createdAtMs: now,
          ),
        );
        callLog(
          'AppCtrl',
          'sendSticker queued for retry: no devices yet for '
              'profile=$resolvedPeerProfileId, localEvent=$localEventId',
        );
        await _touchRecentSticker(sticker);
        _changed.add(null);
        return eventId;
      }

      await _flushPendingNoDeviceEntries(
        profileId: resolvedPeerProfileId,
        targets: targets,
        selfDeviceId: readyDid,
        db: db,
        ratchet: readyRatchet,
        relay: readyRelay,
        nowMs: now,
      );

      final blocking = await _sendGateBlockingDevices(
        resolvedPeerProfileId,
        targets,
      );
      if (blocking.isNotEmpty) {
        throw StateError(
          'Contact is unverified (devices: ${blocking.take(3).join(', ')}${blocking.length > 3 ? '…' : ''}). Open chat → Verify.',
        );
      }

      var queuedTargets = 0;
      var fanoutSkipped = 0;
      final queuedDeviceIds = <String>{};

      Future<void> enqueueToDevice(String toDeviceId) async {
        final msgId = _uuid.v4();
        final wire = await _encryptToPeerSerialized(
          ratchet: readyRatchet,
          selfDeviceId: readyDid,
          peerProfileId: resolvedPeerProfileId,
          peerDeviceId: toDeviceId,
          plaintext: Uint8List.fromList(fanoutPayload.encode()),
        );
        await db.outboxUpsert(
          msgId: msgId,
          toDeviceId: toDeviceId,
          ciphertextB64: base64Encode(wire),
          ttlSeconds: _outboxUserMessageTtlSeconds,
          state: OutboxSendState.pending,
          attemptCount: 0,
          nextRetryAtMs: now,
          createdAtMs: now,
          correlationId: localEventId,
          payloadEventId: eventId,
          convoId: resolvedPeerProfileId,
          transportMetaJson: transportMetaJson,
          expiresAtMs: now + _outboxUserMessageTtlMs,
          eventIdRef: localEventId,
        );
        queuedTargets++;
        queuedDeviceIds.add(toDeviceId);
      }

      for (final toDeviceId in targets) {
        try {
          await enqueueToDevice(toDeviceId);
        } catch (e) {
          fanoutSkipped++;
          // `callLog` is compiled out of release — log the real reason (2026-07-28).
          DiagLog.event('send', 'fanout_target_skip', {
            'peer': DiagLog.pfx(resolvedPeerProfileId),
            'to_dev': DiagLog.pfx(toDeviceId),
            'reason': _classifyShortReason(e),
          });
        }
      }

      // FIX (2026-07-28): same refresh-retry as the primary send path — a stale
      // cached device_id ("peer device not found in bundle") must not fail the
      // whole sticker send without one fresh device lookup.
      if (fanoutSkipped > 0 || queuedTargets == 0) {
        try {
          unawaited(
            refreshContactDevices(resolvedPeerProfileId).catchError((_) {}),
          );
          final freshTargets = await _verifiedTargetsOnly(
            resolvedPeerProfileId,
            await _listRecipientDevicesForSend(
              peerProfileId: resolvedPeerProfileId,
              selfDeviceId: readyDid,
              forceRefresh: true,
            ),
          );
          for (final toDeviceId in freshTargets) {
            if (queuedDeviceIds.contains(toDeviceId)) continue;
            try {
              await enqueueToDevice(toDeviceId);
              DiagLog.event('send', 'fanout_retry_ok', {
                'peer': DiagLog.pfx(resolvedPeerProfileId),
                'to_dev': DiagLog.pfx(toDeviceId),
              });
            } catch (e) {
              DiagLog.event('send', 'fanout_retry_skip', {
                'peer': DiagLog.pfx(resolvedPeerProfileId),
                'to_dev': DiagLog.pfx(toDeviceId),
                'reason': _classifyShortReason(e),
              });
            }
          }
        } catch (_) {
          // best-effort refresh-retry; fall through to the queuedTargets check
        }
      }

      if (queuedTargets == 0) {
        throw StateError(
          'No deliverable target devices for recipient (all fanout attempts failed).',
        );
      }

      await _touchRecentSticker(sticker);
      _changed.add(null);
      _kickRelayOutbox(readyRelay);
      // Multi-device sync: mirror sticker to my own other devices (TZ §21.1).
      unawaited(
        _mirrorStickerToOwnDevices(
          convoId: resolvedPeerProfileId,
          msgEventId: eventId,
          packId: sticker.packId,
          packVersion: sticker.packVersion,
          stickerId: sticker.stickerId,
          createdAtMs: now,
          emojiHint: sticker.emojiHint,
          label: sticker.label,
          animated: sticker.animated,
          format: sticker.format.wireValue,
          replyToPayloadEventId: replyToPayloadEventId,
        ),
      );
      return eventId;
    } catch (e) {
      final queued = await db.outboxCountForEventRef(localEventId);
      if (queued == 0) {
        await db.updateEventLocalState(
          eventId: localEventId,
          localState: MessageLocalState.failed,
          reasonCode: MessageFailureReason.noDeliverableTarget,
        );
      }
      _changed.add(null);
      rethrow;
    }
  }

  Future<void> sendMessage({
    required String peerProfileId,
    required String text,
    String? replyToPayloadEventId,
    int? scheduledAtMs,
    LinkPreviewV1? linkPreview,
  }) async {
    // The user is here and doing things — poll fast.
    noteInteractiveActivity();
    // Превью готовит отправитель (16.09.2026): только для первой ссылки
    // ЭТОГО текста и в пределах размера сообщения — см. политику.
    final outgoingPreview = linkPreviewForOutgoing(linkPreview, text);
    final db = _db;
    final did = _deviceId;
    final pid = _profileId;
    final crypto = _crypto;
    if (db == null || did == null || pid == null || crypto == null) {
      return;
    }

    final resolvedPeerProfileId =
        await _normalizeDirectPeerProfileId(peerProfileId) ?? peerProfileId;
    if (resolvedPeerProfileId.startsWith('dev:')) {
      throw StateError(
        'Waiting for contact identity sync. Ask the contact to send one more message and try again.',
      );
    }

    if (await db.blockedProfileIsBlocked(resolvedPeerProfileId)) {
      throw StateError('Contact is blocked');
    }

    if (resolvedPeerProfileId == pid) {
      final eventId = _uuid.v4();
      final now = DateTime.now().millisecondsSinceEpoch;
      final payload = E2ePayloadV1(
        senderDeviceId: did,
        createdAtMs: now,
        events: [
          MsgEventV1(
            eventId: eventId,
            text: text,
            replyToEventId: replyToPayloadEventId,
            linkPreview: outgoingPreview,
          ),
        ],
      );
      final localCipher = await crypto.encrypt(payload.encode());
      await db.convoEnsure1to1(peerProfileId: resolvedPeerProfileId);
      await _retryDbBusy(() async {
        await db.insertEvent(
          eventId: 'local:$eventId',
          convoId: resolvedPeerProfileId,
          type: 'msg',
          senderDeviceId: did,
          ciphertextB64: base64Encode(localCipher),
          createdAtMs: now,
          localState: 'sent',
          payloadEventId: eventId,
        );
        await db.convoTouch(convoId: resolvedPeerProfileId, atMs: now);
      });
      _changed.add(null);
      return;
    }

    // Demo chat: local-only send + simulated reply.
    final demoConvoId = _isDemoConvoId(resolvedPeerProfileId)
        ? resolvedPeerProfileId
        : peerProfileId;
    if (_isDemoConvoId(demoConvoId)) {
      if (!_demoDataEnabled) {
        throw StateError('Demo chats are disabled in this build.');
      }
      final demoTitle = _demoDisplayName(demoConvoId);
      final eventId = _uuid.v4();
      final payload = E2ePayloadV1(
        senderDeviceId: did,
        createdAtMs: DateTime.now().millisecondsSinceEpoch,
        events: [
          MsgEventV1(
            eventId: eventId,
            text: text,
            replyToEventId: replyToPayloadEventId,
          ),
        ],
      );
      final cipher = await crypto.encrypt(payload.encode());
      final now = DateTime.now().millisecondsSinceEpoch;
      if (demoConvoId.startsWith('group:')) {
        await db.convoEnsureGroup(groupId: demoConvoId, title: demoTitle);
      } else {
        await db.convoEnsure1to1(peerProfileId: demoConvoId);
        await db.contactUpsert(
          profileId: demoConvoId,
          displayName: demoTitle,
          displayNameIsCustom: true,
        );
      }
      // Demo chats honour scheduled sends too: a "send later" message is kept
      // as `scheduled` (with a clock in the UI) and only "sent" + delivered/read
      // + auto-replied once the scheduled time arrives — instead of firing
      // immediately, which made the feature look broken in the demo build.
      final schedMs = scheduledAtMs;
      final isScheduledDemo = schedMs != null && schedMs > now;
      await db.insertEvent(
        eventId: 'local:$eventId',
        convoId: demoConvoId,
        type: 'msg',
        senderDeviceId: did,
        ciphertextB64: base64Encode(cipher),
        createdAtMs: now,
        localState: isScheduledDemo ? MessageLocalState.scheduled : 'sent',
        payloadEventId: eventId,
        scheduledAtMs: isScheduledDemo ? schedMs : null,
      );
      await db.convoTouch(convoId: demoConvoId, atMs: now);
      _changed.add(null);

      void runDemoDelivery() {
        if (isScheduledDemo) {
          unawaited(() async {
            final dbS = _db;
            if (dbS == null) return;
            await dbS.updateLocalStateByPayloadEventId(
              payloadEventId: eventId,
              localState: 'sent',
            );
            await dbS.convoTouch(
              convoId: demoConvoId,
              atMs: DateTime.now().millisecondsSinceEpoch,
            );
            _changed.add(null);
          }());
        }

        // Simulate delivery/read progression.
        Future.delayed(const Duration(milliseconds: 900), () async {
          final db2 = _db;
          if (db2 == null) return;
          await db2.updateLocalStateByPayloadEventId(
            payloadEventId: eventId,
            localState: 'delivered',
          );
          _changed.add(null);
        });
        Future.delayed(const Duration(milliseconds: 1600), () async {
          final db2 = _db;
          if (db2 == null) return;
          await db2.updateLocalStateByPayloadEventId(
            payloadEventId: eventId,
            localState: 'read',
          );
          _changed.add(null);
        });

        // Simulated incoming reply.
        Future.delayed(const Duration(milliseconds: 600), () async {
          final db2 = _db;
          final crypto2 = _crypto;
          if (db2 == null || crypto2 == null) return;
          final rid = _uuid.v4();
          final reply = E2ePayloadV1(
            senderDeviceId: demoDeviceId,
            createdAtMs: DateTime.now().millisecondsSinceEpoch,
            events: [
              MsgEventV1(
                eventId: rid,
                text: '👍 ${_demoAutoReply(demoConvoId)}',
              ),
            ],
          );
          final c2 = await crypto2.encrypt(reply.encode());
          final t2 = DateTime.now().millisecondsSinceEpoch;
          await db2.insertEvent(
            eventId: 'in:$rid',
            convoId: demoConvoId,
            type: 'msg',
            senderDeviceId: demoDeviceId,
            ciphertextB64: base64Encode(c2),
            createdAtMs: t2,
            localState: 'received',
          );
          await db2.convoTouch(convoId: demoConvoId, atMs: t2);
          _changed.add(null);
        });
      }

      if (isScheduledDemo) {
        Future.delayed(Duration(milliseconds: schedMs - now), runDemoDelivery);
      } else {
        runDemoDelivery();
      }

      return;
    }

    // SCHEDULED SEND (send-later): write an editable local `scheduled`
    // placeholder AND (when transport allows) upload the ciphertext to the
    // relay eagerly, tagged `deliver_at_ms = T` so the RELAY — not this phone —
    // waits out the delay. Delivery therefore no longer depends on the sender
    // being awake at T. The placeholder remains the editable/cancellable record
    // and is the fallback that [_sweepDueScheduledDirectMessages] fires if that
    // upload never happened.
    //
    // NB: the eager outbox row is deferred by `deliver_at_ms`, NOT by
    // `next_retry_at_ms` — it uploads immediately and the relay holds it. Do
    // NOT future-date `next_retry_at_ms` instead: a future-dated outbox row got
    // re-armed to `now` by the stuck-pending watchdog, which was the original
    // "scheduled 1:1 message sends immediately" bug. The watchdog now also
    // skips scheduled-linked rows, and the relay refuses to release a held row
    // early even if a client re-submits it as immediate.
    final directScheduleMs = scheduledAtMs;
    if (directScheduleMs != null &&
        directScheduleMs > DateTime.now().millisecondsSinceEpoch) {
      await _scheduleDirectMessage(
        peerProfileId: resolvedPeerProfileId,
        text: text,
        replyToPayloadEventId: replyToPayloadEventId,
        scheduledAtMs: directScheduleMs,
        linkPreview: outgoingPreview,
      );
      return;
    }

    if (!await ensureOutgoingTransportReady()) {
      throw _transportUnavailableStateError('Message send unavailable');
    }

    final readyRelay = _relay;
    final readyKeys = _keys;
    final readyRatchet = _ratchetV3;
    final readyDid = _deviceId;
    final readyPid = _profileId;
    if (readyRelay == null ||
        readyKeys == null ||
        readyRatchet == null ||
        readyDid == null ||
        readyPid == null) {
      throw _transportUnavailableStateError('Message send unavailable');
    }

    _throwIfTransportBlocked();
    final readyForDirectChat = await _ensureDirectConversationReadyForOutgoing(
      resolvedPeerProfileId,
    );
    if (!readyForDirectChat) {
      throw StateError('Contact is blocked');
    }

    final eventId = _uuid.v4();

    final payload = E2ePayloadV1(
      senderDeviceId: readyDid,
      createdAtMs: DateTime.now().millisecondsSinceEpoch,
      events: [
        MsgEventV1(
          eventId: eventId,
          text: text,
          replyToEventId: replyToPayloadEventId,
          linkPreview: outgoingPreview,
        ),
      ],
    );

    // Local history copy: encrypt with local symmetric provider so this device can always display.
    final localCipher = await crypto.encrypt(payload.encode());
    final localB64 = base64Encode(localCipher);
    final now = DateTime.now().millisecondsSinceEpoch;
    final localEventId = 'local:$eventId';
    final transportMetaJson = _buildChatTransportMetaJson(
      convoId: resolvedPeerProfileId,
      isGroup: false,
      messageKind: 'text',
      payloadEventId: eventId,
      createdAtMs: payload.createdAtMs,
      senderProfileId: readyPid,
      senderDisplayName: myNickname,
      previewText: text,
    );
    await _retryDbBusy(() async {
      await db.insertEvent(
        eventId: localEventId,
        convoId: resolvedPeerProfileId,
        type: 'msg',
        senderDeviceId: did,
        ciphertextB64: localB64,
        createdAtMs: now,
        localState: scheduledAtMs != null
            ? MessageLocalState.scheduled
            : MessageLocalState.pending,
        payloadEventId: eventId,
        scheduledAtMs: scheduledAtMs,
      );
      await db.convoTouch(convoId: resolvedPeerProfileId, atMs: now);
    });
    _changed.add(null);

    try {
      // Fanout to all known devices of the peer profile.
      final List<String> targets;
      try {
        targets = await _listRecipientDevicesForSend(
          peerProfileId: resolvedPeerProfileId,
          selfDeviceId: did,
        );
      } on RecipientDevicesUnavailable catch (e) {
        // 🔴 TRANSIENT, NOT A FAILURE (2026-07-31). We could not ASK who to
        // send to — the recipient is fine. Falling through to the generic catch
        // marked the message `failed` and showed the user "rate_limit" for a
        // condition that clears in seconds; in the field that happened every
        // 2-3 messages while a background loop drained the shared budget.
        //
        // Treat it exactly like "the peer has no devices yet": park it durably
        // and stay `pending`, so the no-device retry delivers it and the bubble
        // keeps its normal sending state instead of turning red.
        await _queuePendingNoDeviceEntry(
          profileId: resolvedPeerProfileId,
          entry: _PendingNoDeviceEntry(
            localEventId: localEventId,
            payloadBytes: Uint8List.fromList(payload.encode()),
            transportMetaJson: transportMetaJson,
            createdAtMs: now,
          ),
        );
        DiagLog.event('send', 'devices_unavailable_queued', {
          'peer': DiagLog.pfx(resolvedPeerProfileId),
          'reason': e.reason,
        });
        _changed.add(null);
        return;
      }
      if (targets.isEmpty) {
        // Distinguish "typo / wrong server" from "recipient not set up yet".
        bool exists = false;
        try {
          exists = await readyKeys.profileExists(resolvedPeerProfileId);
        } catch (_) {
          // ignore
        }

        if (!exists) {
          throw StateError(
            'Recipient profile not found on server. Check Secretly ID / ensure both use the same server. (peer_profile_id=$peerProfileId)',
          );
        }

        // Profile exists but has no registered devices yet — keep message as
        // 'pending' and retry in the background when the contact opens the app.
        await _queuePendingNoDeviceEntry(
          profileId: resolvedPeerProfileId,
          entry: _PendingNoDeviceEntry(
            localEventId: localEventId,
            payloadBytes: Uint8List.fromList(payload.encode()),
            transportMetaJson: transportMetaJson,
            createdAtMs: now,
          ),
        );
        callLog(
          'AppCtrl',
          'sendMessage queued for retry: no devices yet for '
              'profile=$resolvedPeerProfileId, localEvent=$localEventId',
        );
        _changed.add(null);
        return; // message stays 'pending' in local DB; watchdog will retry
      }

      // Devices are available — flush any previously queued messages FIRST so
      // they arrive at the recipient before this new message (correct order).
      await _flushPendingNoDeviceEntries(
        profileId: resolvedPeerProfileId,
        targets: targets,
        selfDeviceId: readyDid,
        db: db,
        ratchet: readyRatchet,
        relay: readyRelay,
        nowMs: now,
      );

      final blocking = await _sendGateBlockingDevices(
        resolvedPeerProfileId,
        targets,
      );
      if (blocking.isNotEmpty) {
        throw StateError(
          'Contact is unverified (devices: ${blocking.take(3).join(', ')}${blocking.length > 3 ? '…' : ''}). Open chat → Verify.',
        );
      }

      var queuedTargets = 0;
      final queuedDeviceIds = <String>{};

      Future<void> enqueueToDevice(String toDeviceId) async {
        final msgId = _uuid.v4();
        final wire = await _encryptToPeerSerialized(
          ratchet: readyRatchet,
          selfDeviceId: readyDid,
          peerProfileId: resolvedPeerProfileId,
          peerDeviceId: toDeviceId,
          plaintext: Uint8List.fromList(payload.encode()),
        );
        await db.outboxUpsert(
          msgId: msgId,
          toDeviceId: toDeviceId,
          ciphertextB64: base64Encode(wire),
          ttlSeconds: _outboxUserMessageTtlSeconds,
          state: OutboxSendState.pending,
          attemptCount: 0,
          nextRetryAtMs: scheduledAtMs ?? now,
          createdAtMs: now,
          correlationId: localEventId,
          payloadEventId: eventId,
          convoId: resolvedPeerProfileId,
          transportMetaJson: transportMetaJson,
          expiresAtMs: scheduledAtMs != null
              ? scheduledAtMs + (7 * 24 * 60 * 60 * 1000)
              : now + _outboxUserMessageTtlMs,
          eventIdRef: localEventId,
        );
        queuedTargets++;
        queuedDeviceIds.add(toDeviceId);
        DiagLog.event('send', 'outbox_enqueued', {
          'kind': 'text',
          'peer': DiagLog.pfx(resolvedPeerProfileId),
          'msg': DiagLog.pfx(msgId),
          'to_dev': DiagLog.pfx(toDeviceId),
          'local_event': DiagLog.pfx(localEventId),
        });
      }

      var fanoutSkipped = 0;
      for (final toDeviceId in targets) {
        try {
          await enqueueToDevice(toDeviceId);
        } catch (e) {
          fanoutSkipped++;
          callLog(
            'AppCtrl',
            'sendMessage fanout skip target=$toDeviceId peer=$resolvedPeerProfileId: $e',
          );
          DiagLog.event('send', 'fanout_skip', {
            'kind': 'text',
            'peer': DiagLog.pfx(resolvedPeerProfileId),
            'to_dev': DiagLog.pfx(toDeviceId),
            'reason': _classifyShortReason(e),
          });
        }
      }

      // FIX-C4 (F4 / Z7): a per-device encrypt failure — most often "peer device
      // not found in bundle" for a stale/zombie device_id in our cached list, or
      // a transient bundle fetch — used to silently drop that device with no
      // retry, so a peer that rotated/added a device could miss the message
      // entirely (the "часть смс не дошла" symptom). If anything was skipped (or
      // nothing queued at all), force ONE fresh keys-server device lookup and
      // enqueue to every LIVE device we haven't already reached. This is the
      // outbound counterpart of learn-on-receive.
      if (fanoutSkipped > 0 || queuedTargets == 0) {
        try {
          unawaited(
            refreshContactDevices(resolvedPeerProfileId).catchError((_) {}),
          );
          // SECURITY (2026-07-28): run the refreshed list through the same
          // "block unverified" gate the pre-fanout check applied. A device this
          // refresh just discovered is unverified by definition, so enqueuing to
          // it here used to bypass that gate (it only ever saw the ORIGINAL
          // targets). No-op when the gate is off (its default).
          final freshTargets = await _verifiedTargetsOnly(
            resolvedPeerProfileId,
            await _listRecipientDevicesForSend(
              peerProfileId: resolvedPeerProfileId,
              selfDeviceId: did,
              forceRefresh: true,
            ),
          );
          for (final toDeviceId in freshTargets) {
            if (queuedDeviceIds.contains(toDeviceId)) continue;
            try {
              await enqueueToDevice(toDeviceId);
              DiagLog.event('send', 'fanout_retry_ok', {
                'peer': DiagLog.pfx(resolvedPeerProfileId),
                'to_dev': DiagLog.pfx(toDeviceId),
              });
            } catch (e) {
              DiagLog.event('send', 'fanout_retry_skip', {
                'peer': DiagLog.pfx(resolvedPeerProfileId),
                'to_dev': DiagLog.pfx(toDeviceId),
                'reason': _classifyShortReason(e),
              });
            }
          }
        } catch (_) {
          // best-effort refresh-retry; fall through to the queuedTargets check
        }
      }

      if (queuedTargets == 0) {
        throw StateError(
          'No deliverable target devices for recipient (all fanout attempts failed).',
        );
      }

      _changed.add(null);
      _kickRelayOutbox(readyRelay);
      DiagLog.event('send', 'kick_outbox', {
        'kind': 'text',
        'peer': DiagLog.pfx(resolvedPeerProfileId),
        'queued_targets': queuedTargets,
      });
      unawaited(
        _mirrorTextMessageToOwnDevices(
          convoId: resolvedPeerProfileId,
          messageText: text,
          payloadEventId: eventId,
          createdAtMs: payload.createdAtMs,
          replyToPayloadEventId: replyToPayloadEventId,
          linkPreview: outgoingPreview,
        ),
      );
    } catch (e) {
      final queued = await db.outboxCountForEventRef(localEventId);
      if (queued == 0) {
        await db.updateEventLocalState(
          eventId: localEventId,
          localState: MessageLocalState.failed,
          reasonCode: MessageFailureReason.noDeliverableTarget,
        );
      }
      _changed.add(null);
      rethrow;
    }
  }

  Future<void> recordCallOutcome({
    required String callId,
    required String callAttemptId,
    required String peerProfileId,
    required String peerName,
    required String? peerAvatarPath,
    required CallRecordDirection direction,
    required bool isVideo,
    required bool hadScreenShare,
    required int startedAtMs,
    required int? connectedAtMs,
    required int endedAtMs,
    required CallEndReason endReason,
    CallFailureCode? failureCode,
    CallQualitySummary? qualitySummary,
    bool onlyIfAbsent = false,
  }) async {
    final db = _db;
    final did = _deviceId;
    final pid = _profileId;
    final crypto = _crypto;
    if (db == null || did == null || pid == null || crypto == null) {
      return;
    }

    final resolvedPeerProfileId =
        await _normalizeDirectPeerProfileId(peerProfileId) ?? peerProfileId;
    if (resolvedPeerProfileId.startsWith('dev:')) return;

    final draft = CallRecordDraft(
      callId: callId,
      callAttemptId: callAttemptId,
      convoId: resolvedPeerProfileId,
      peerProfileId: resolvedPeerProfileId,
      peerDisplayName: peerName,
      peerAvatarPath: peerAvatarPath,
      direction: direction,
      isVideo: isVideo,
      hadScreenShare: hadScreenShare,
      startedAtMs: startedAtMs,
      connectedAtMs: connectedAtMs,
      endedAtMs: endedAtMs,
      endReason: endReason,
      failureCode: failureCode,
      qualitySummary: qualitySummary,
    );

    final existingJournal = await db.callJournalGetByAttemptId(callAttemptId);

    // 🔴 [onlyIfAbsent] — для записей, СОБРАННЫХ ЗАДНИМ ЧИСЛОМ (след пропущенных
    // звонков от натива, 07.08.2026). Обычный путь здесь ОБНОВЛЯЕТ уже
    // существующую запись, и это правильно, пока обновление приходит от самого
    // звонка. Но след знает про звонок меньше, чем машина состояний: он видел
    // только то, что плашка прозвонила. Разбуди он этот путь без флага —
    // ПРИНЯТЫЙ разговор переписался бы в «пропущенный» на ближайшем запуске.
    // То есть правка, чинящая одну ложь, породила бы другую, хуже прежней.
    if (onlyIfAbsent && existingJournal != null) return;

    final existingLocalEventId =
        existingJournal?.createdLocalEventId?.trim() ?? '';
    final existingPayloadEventId =
        existingJournal?.syncedChatEventId?.trim() ?? '';
    final eventId = existingPayloadEventId.isNotEmpty
        ? existingPayloadEventId
        : _uuid.v4();
    final payload = E2ePayloadV1(
      senderDeviceId: did,
      createdAtMs: endedAtMs,
      events: [
        CallEventV1(
          eventId: eventId,
          callId: callId,
          callAttemptId: callAttemptId,
          convoId: resolvedPeerProfileId,
          direction: direction,
          scope: CallRecordScope.oneToOne,
          mediaType: callRecordMediaTypeFromFlags(
            isVideo: isVideo,
            hadScreenShare: hadScreenShare,
          ),
          result: draft.result,
          startedAtMs: startedAtMs,
          connectedAtMs: connectedAtMs,
          endedAtMs: endedAtMs,
          durationMs: draft.durationMs,
          endReason: endReason.name,
          failureCode: failureCode,
          participantCount: 2,
          hadVideo: isVideo,
          hadScreenShare: hadScreenShare,
          qualitySummary: qualitySummary == null
              ? null
              : jsonDecode(qualitySummary.encode()),
        ),
      ],
    );

    final localCipher = await crypto.encrypt(payload.encode());
    final localEventId = existingLocalEventId.isNotEmpty
        ? existingLocalEventId
        : 'local:$eventId';
    final existingLocalEvent = await db.eventGet(localEventId);
    final existingLocalState =
        ((existingLocalEvent?['local_state'] as String?) ?? '').trim();
    final persistedLocalState =
        existingLocalState == MessageLocalState.sent ||
            existingLocalState == MessageLocalState.failed
        ? existingLocalState
        : MessageLocalState.pending;
    final outcomeAlreadyPersisted =
        existingJournal != null && existingLocalEvent != null;
    await db.convoEnsure1to1(peerProfileId: resolvedPeerProfileId);
    await _retryDbBusy(() async {
      if (existingLocalEvent == null) {
        await db.insertEvent(
          eventId: localEventId,
          convoId: resolvedPeerProfileId,
          type: 'call',
          senderDeviceId: did,
          ciphertextB64: base64Encode(localCipher),
          createdAtMs: endedAtMs,
          localState: persistedLocalState,
          payloadEventId: eventId,
        );
      } else {
        await db.updateEventEnvelope(
          eventId: localEventId,
          ciphertextB64: base64Encode(localCipher),
          localCiphertextB64: null,
          createdAtMs: endedAtMs,
          localState: persistedLocalState,
          payloadEventId: eventId,
        );
      }
      await db.convoTouch(convoId: resolvedPeerProfileId, atMs: endedAtMs);
      await db.callJournalUpsert(
        entry: draft.toJournalEntry(
          createdLocalEventId: localEventId,
          syncedChatEventId: eventId,
        ),
      );
    });
    _changed.add(null);

    if (outcomeAlreadyPersisted) {
      callLog(
        'AppCtrl',
        'recordCallOutcome deduped attempt=$callAttemptId localEvent=$localEventId',
      );
    }
    await db.updateEventLocalState(
      eventId: localEventId,
      localState: MessageLocalState.sent,
    );
    _changed.add(null);
  }

  // Free-tier baseline attachment cap (mirrors EntitlementLimits.free.
  // attachmentBytes). Only referenced by maxAttachmentBytesForTest — the live
  // ceiling is resolved via _effectiveAttachmentMaxBytes.
  static const int _maxAttachmentBytes = 100 * 1024 * 1024;
  static const int _bufferedAttachmentThresholdBytes = 8 * 1024 * 1024;
  static const int _bufferedVisualAttachmentThresholdBytes = 24 * 1024 * 1024;
  static const Duration _attachmentReadTimeout = Duration(minutes: 2);
  // Generous: large media on a slow uplink can take many minutes. The upload
  // streams with backpressure (bounded memory) + accurate progress and is
  // cancellable, so this only guards a genuinely dead connection (was 3 min,
  // which timed out ~100 MB files even on decent WiFi).
  static const Duration _attachmentUploadTimeout = Duration(minutes: 30);
  static const Duration _attachmentFinalizeTimeout = Duration(seconds: 45);

  int get _effectiveAttachmentMaxBytes {
    // Monetization §C-3: the client ceiling is the entitlement-resolved limit.
    // While monetization is disabled this returns the 25 MB free baseline
    // (FeatureGate keys size off a positive paid tier only), so behaviour is
    // byte-identical to the pre-freemium build. A paid tier raises it to 1 GB,
    // still clamped by whatever the relay will actually accept.
    final entitlementLimit = FeatureGate.attachmentBytesLimit(
      entitlementStateNow,
    );
    final relayLimit =
        _relayHealthStatus?.maxAttachmentBytes ??
        _relayHealthStatus?.maxRequestBodyBytes;
    if (relayLimit == null || relayLimit <= 0) {
      return entitlementLimit;
    }
    return math.min(entitlementLimit, relayLimit);
  }

  /// True when [sizeBytes] exceeds the current (free) ceiling but WOULD fit
  /// under the premium attachment limit — i.e. upgrading would let it send.
  /// The attachment-picker UI uses this to show the `file` paywall instead of a
  /// plain "too large" error. Returns false while monetization is disabled.
  bool attachmentWouldFitPremium(int sizeBytes) {
    final state = entitlementStateNow;
    if (!state.monetizationEnabled || state.tier.isPaid) return false;
    return sizeBytes > _effectiveAttachmentMaxBytes &&
        sizeBytes <= EntitlementLimits.premium.attachmentBytes;
  }

  /// True when an oversized [sizeBytes] file exceeds the current ceiling but
  /// WOULD fit under the premium cap — the trigger for the "file too large"
  /// upsell dialog. Unlike [attachmentWouldFitPremium], this is INDEPENDENT of
  /// the live `monetization_enabled` flag: the signed config may not have
  /// loaded yet on a fresh launch (it fails open to monetizationEnabled=false),
  /// which would otherwise suppress the dialog and leave the user with only a
  /// bare snackbar. A paid profile never reaches here — its ceiling is already
  /// the premium cap, so an oversized-but-≤premium file simply sends.
  bool attachmentTooLargeUpsell(int sizeBytes) {
    if (entitlementStateNow.tier.isPaid) return false;
    return sizeBytes > _effectiveAttachmentMaxBytes &&
        sizeBytes <= EntitlementLimits.premium.attachmentBytes;
  }

  void _throwIfAttachmentTooLarge(int sizeBytes) {
    if (sizeBytes > _effectiveAttachmentMaxBytes) {
      throw AttachmentFailure(AttachmentFailureCode.tooLarge, bytes: sizeBytes);
    }
  }

  /// Public read of the current effective attachment ceiling (entitlement ∧
  /// relay), for UI that needs to show the exact free limit (e.g. the
  /// too-large upsell dialog).
  int get effectiveAttachmentMaxBytes => _effectiveAttachmentMaxBytes;

  @visibleForTesting
  static int get maxAttachmentBytesForTest => _maxAttachmentBytes;

  @visibleForTesting
  void seedServiceHealthForTesting({
    ServiceHealthStatus? keysHealthStatus,
    ServiceHealthStatus? relayHealthStatus,
  }) {
    _keysHealthStatus = keysHealthStatus;
    _relayHealthStatus = relayHealthStatus;
  }

  bool _isBufferedVisualAttachmentMime(String? mime) {
    final normalized = (mime ?? '').trim().toLowerCase();
    return normalized.startsWith('image/') || normalized.startsWith('video/');
  }

  bool _shouldUseBufferedAttachmentUpload({
    required int sizeBytes,
    required String mime,
  }) {
    final threshold = _isBufferedVisualAttachmentMime(mime)
        ? _bufferedVisualAttachmentThresholdBytes
        : _bufferedAttachmentThresholdBytes;
    return sizeBytes <= threshold;
  }

  Future<String> sendAttachment({
    required String peerProfileId,
    required Uint8List bytes,
    String? mime,
    String? replyToPayloadEventId,
    String? mediaGroupId,
    bool includeInLocalHistory = true,
    List<String>? targetDeviceIds,
    List<int>? waveform,
    String? caption,
    String? filename,
    bool videoNote = false,
    int? durationMs,
    String? musicTitle,
    String? musicArtist,
    int? width,
    int? height,
    String? thumbB64,
  }) async {
    // Keep bytes-based API for web/tests/small payloads.
    _throwIfAttachmentTooLarge(bytes.length);

    final db = _db;
    final relay = _relay;
    final did = _deviceId;
    final pid = _profileId;
    final keys = _keys;
    final ratchet = _ratchetV3;
    final crypto = _crypto;
    final attachments = _attachments;
    if (db == null || did == null || pid == null || crypto == null) {
      throw AttachmentFailure(AttachmentFailureCode.localUnavailable);
    }

    final resolvedPeerProfileId =
        await _normalizeDirectPeerProfileId(peerProfileId) ?? peerProfileId;
    if (resolvedPeerProfileId.startsWith('dev:')) {
      throw AttachmentFailure(AttachmentFailureCode.contactSyncPending);
    }

    if (await db.blockedProfileIsBlocked(resolvedPeerProfileId)) {
      throw AttachmentFailure(AttachmentFailureCode.contactBlocked);
    }

    // Sprint 2 hotfix (2026-05-19): when `targetDeviceIds` is provided we
    // ALWAYS take the real upload+fanout path, even if the recipient profile
    // is our own. Without this guard the legacy "send-to-self" short-circuit
    // below silently saves the bytes only to local DB and returns success,
    // which breaks the desktop QR-pairing flow (mobile→desktop sync bundle
    // and decision attachments target the user's own profile but must reach
    // the desktop device, not stay on the phone). See `_sendDesktopLinkAttachmentPayload`.
    final explicitTargetDeviceIds = targetDeviceIds
        ?.map((d) => d.trim())
        .where((d) => d.isNotEmpty && d != did)
        .toSet()
        .toList(growable: false);
    final hasExplicitTargets =
        explicitTargetDeviceIds != null && explicitTargetDeviceIds.isNotEmpty;

    if (resolvedPeerProfileId == pid && !hasExplicitTargets) {
      final now = DateTime.now().millisecondsSinceEpoch;
      final resolvedMime = (mime != null && mime.trim().isNotEmpty)
          ? mime.trim()
          : 'application/octet-stream';
      final blobId = 'local:${_uuid.v4()}';

      await db.convoEnsure1to1(peerProfileId: resolvedPeerProfileId);
      await db.attachmentUpsert(
        blobId: blobId,
        fileKeyB64: '',
        accessTokenB64: '',
        mime: resolvedMime,
        plaintextSizeBytes: bytes.length,
        ciphertextSizeBytes: bytes.length,
        expiresAtMs: now + (3650 * 24 * 60 * 60 * 1000),
        createdAtMs: now,
      );
      await _cacheAttachmentBytes(
        blobId: blobId,
        mime: resolvedMime,
        plaintext: bytes,
      );

      final eventId = _uuid.v4();
      final payload = E2ePayloadV1(
        senderDeviceId: did,
        createdAtMs: now,
        events: [
          AttachmentEventV1(
            eventId: eventId,
            blobId: blobId,
            fileKeyB64: '',
            blobAccessTokenB64: null,
            sizeBytes: bytes.length,
            mime: resolvedMime,
            replyToEventId: replyToPayloadEventId,
            mediaGroupId: mediaGroupId,
            waveform: waveform,
            caption: caption,
            filename: filename,
            videoNote: videoNote,
            durationMs: durationMs,
            musicTitle: musicTitle,
            musicArtist: musicArtist,
            width: width,
            height: height,
            thumbB64: thumbB64,
          ),
        ],
      );
      final localCipher = await crypto.encrypt(payload.encode());
      if (includeInLocalHistory) {
        await _retryDbBusy(() async {
          await db.insertEvent(
            eventId: 'local:$eventId',
            convoId: resolvedPeerProfileId,
            type: 'att',
            senderDeviceId: did,
            ciphertextB64: base64Encode(localCipher),
            createdAtMs: now,
            localState: 'sent',
            payloadEventId: eventId,
          );
          await db.convoTouch(convoId: resolvedPeerProfileId, atMs: now);
        });
      }
      _changed.add(null);
      return eventId;
    }

    if (relay == null ||
        keys == null ||
        ratchet == null ||
        attachments == null) {
      throw AttachmentFailure(AttachmentFailureCode.transportUnavailable);
    }

    try {
      _throwIfTransportBlocked();
    } catch (error) {
      throw describeAttachmentFailure(
        error,
        fallbackCode: AttachmentFailureCode.transportBlocked,
      );
    }
    final readyForDirectChat = await _ensureDirectConversationReadyForOutgoing(
      resolvedPeerProfileId,
    );
    if (!readyForDirectChat) {
      throw AttachmentFailure(AttachmentFailureCode.contactBlocked);
    }
    if (includeInLocalHistory) {
      await db.convoEnsure1to1(peerProfileId: resolvedPeerProfileId);
    }

    final now = DateTime.now().millisecondsSinceEpoch;
    late final EncryptedAttachment uploaded;
    try {
      uploaded = await attachments
          .encryptAndUpload(bytes, ttlSeconds: 7 * 24 * 60 * 60, mime: mime)
          .timeout(
            _attachmentUploadTimeout,
            onTimeout: () =>
                throw AttachmentFailure(AttachmentFailureCode.uploadTimedOut),
          );
    } catch (error) {
      throw describeAttachmentFailure(
        error,
        fallbackCode: AttachmentFailureCode.serviceUnavailable,
      );
    }

    await db.attachmentUpsert(
      blobId: uploaded.blobId,
      fileKeyB64: uploaded.fileKeyB64,
      accessTokenB64: uploaded.blobAccessTokenB64,
      mime: uploaded.mime,
      plaintextSizeBytes: bytes.length,
      ciphertextSizeBytes: uploaded.ciphertextSizeBytes,
      expiresAtMs: uploaded.expiresAtMs,
      createdAtMs: now,
    );

    final eventId = _uuid.v4();
    final payload = E2ePayloadV1(
      senderDeviceId: did,
      createdAtMs: now,
      events: [
        AttachmentEventV1(
          eventId: eventId,
          blobId: uploaded.blobId,
          fileKeyB64: uploaded.fileKeyB64,
          blobAccessTokenB64: uploaded.blobAccessTokenB64,
          sizeBytes: bytes.length,
          mime: uploaded.mime,
          replyToEventId: replyToPayloadEventId,
          mediaGroupId: mediaGroupId,
          waveform: waveform,
          caption: caption,
          filename: filename,
          videoNote: videoNote,
          durationMs: durationMs,
          width: width,
          height: height,
          thumbB64: thumbB64,
        ),
      ],
    );

    await _cacheAttachmentBytes(
      blobId: uploaded.blobId,
      mime: uploaded.mime,
      plaintext: bytes,
    );

    String? localEventId;
    final transportMetaJson = _buildChatTransportMetaJson(
      convoId: resolvedPeerProfileId,
      isGroup: false,
      messageKind: 'attachment',
      payloadEventId: eventId,
      createdAtMs: now,
      senderProfileId: pid,
      senderDisplayName: myNickname,
      previewText: _pushTransportPreviewForAttachment(uploaded.mime),
    );
    if (includeInLocalHistory) {
      final localCipher = await crypto.encrypt(payload.encode());
      final localB64 = base64Encode(localCipher);
      localEventId = 'local:$eventId';
      await _retryDbBusy(() async {
        await db.insertEvent(
          eventId: localEventId!,
          convoId: resolvedPeerProfileId,
          type: 'att',
          senderDeviceId: did,
          ciphertextB64: localB64,
          createdAtMs: now,
          localState: 'pending',
          payloadEventId: eventId,
        );
        await db.convoTouch(convoId: resolvedPeerProfileId, atMs: now);
      });
      _changed.add(null);
    }

    try {
      // Sprint 2 hotfix (2026-05-19): when caller passed explicit target
      // device ids (desktop QR pairing path), bypass _listRecipientDevicesForSend
      // and aim straight at those devices. Self-fanout to my own other devices
      // requires this — keys.list_devices may not yet have caught up with the
      // freshly-registered desktop, but the caller already knows the device id
      // it wants to reach (it came in over the signed QR payload).
      final List<String> targets;
      if (hasExplicitTargets) {
        targets = explicitTargetDeviceIds;
      } else {
        try {
          targets = await _listRecipientDevicesForSend(
            peerProfileId: resolvedPeerProfileId,
            selfDeviceId: did,
          );
        } catch (e) {
          // Transient device-lookup failure (keys-server 429 rate-limit,
          // network blip). Under a 429 storm a GROUP send would otherwise fail
          // exactly the items whose lookup threw while their neighbours went
          // through — the "some files send, some don't" report. The blob is
          // already uploaded (7-day TTL): queue for background retry instead of
          // marking 'failed'. A genuinely missing profile is still decided on
          // the EMPTY (not thrown) branch below.
          final lid = localEventId;
          if (lid != null) {
            await _queuePendingNoDeviceEntry(
              profileId: resolvedPeerProfileId,
              entry: _PendingNoDeviceEntry(
                localEventId: lid,
                payloadBytes: Uint8List.fromList(payload.encode()),
                transportMetaJson: transportMetaJson,
                createdAtMs: now,
              ),
            );
            callLog(
              'AppCtrl',
              'sendAttachment queued for retry (device lookup failed: $e): '
                  'profile=$resolvedPeerProfileId, localEvent=$lid',
            );
            _changed.add(null);
            return eventId; // stays 'pending'; watchdog retries
          }
          rethrow;
        }
      }
      if (targets.isEmpty) {
        bool exists = false;
        try {
          exists = await keys.profileExists(resolvedPeerProfileId);
        } catch (_) {
          // ignore
        }
        if (!exists) {
          throw AttachmentFailure(
            AttachmentFailureCode.recipientProfileNotFound,
          );
        }
        // Profile exists but has no registered devices yet — keep attachment as
        // 'pending' and retry in the background when the contact opens the app.
        final lid = localEventId;
        if (lid != null) {
          await _queuePendingNoDeviceEntry(
            profileId: resolvedPeerProfileId,
            entry: _PendingNoDeviceEntry(
              localEventId: lid,
              payloadBytes: Uint8List.fromList(payload.encode()),
              transportMetaJson: transportMetaJson,
              createdAtMs: now,
            ),
          );
          callLog(
            'AppCtrl',
            'sendAttachment queued for retry: no devices yet for '
                'profile=$resolvedPeerProfileId, localEvent=$lid',
          );
        }
        _changed.add(null);
        return eventId; // attachment stays 'pending'; watchdog will retry
      }

      // Devices are available — flush any previously queued messages FIRST.
      await _flushPendingNoDeviceEntries(
        profileId: resolvedPeerProfileId,
        targets: targets,
        selfDeviceId: did,
        db: db,
        ratchet: ratchet,
        relay: relay,
        nowMs: now,
      );

      {
        final List<String> blocking;
        try {
          blocking = await _sendGateBlockingDevices(
            resolvedPeerProfileId,
            targets,
          );
        } on AttachmentFailure {
          rethrow;
        } catch (error) {
          throw describeAttachmentFailure(
            error,
            fallbackCode: AttachmentFailureCode.serviceUnavailable,
          );
        }
        if (blocking.isNotEmpty) {
          throw AttachmentFailure(AttachmentFailureCode.contactUnverified);
        }
      }

      var queuedTargets = 0;
      for (final toDeviceId in targets) {
        try {
          final msgId = _uuid.v4();
          final wire = await _encryptToPeerSerialized(
            ratchet: ratchet,
            selfDeviceId: did,
            peerProfileId: resolvedPeerProfileId,
            peerDeviceId: toDeviceId,
            plaintext: Uint8List.fromList(payload.encode()),
          );
          await db.outboxUpsert(
            msgId: msgId,
            toDeviceId: toDeviceId,
            ciphertextB64: base64Encode(wire),
            ttlSeconds: _outboxUserMessageTtlSeconds,
            state: 'pending',
            attemptCount: 0,
            nextRetryAtMs: now,
            createdAtMs: now,
            transportMetaJson: transportMetaJson,
            eventIdRef: localEventId,
          );
          queuedTargets++;
        } catch (e) {
          callLog(
            'AppCtrl',
            'sendAttachment fanout skip target=$toDeviceId peer=$resolvedPeerProfileId: $e',
          );
        }
      }

      if (queuedTargets == 0) {
        throw AttachmentFailure(
          AttachmentFailureCode.noDeliverableTargetDevices,
        );
      }

      _changed.add(null);
      _kickRelayOutbox(relay);
      // Multi-device sync: mirror to my own other devices so the attachment
      // shows up in their chat history (TZ §21.1). Best-effort, fire-and-forget.
      // Skipped when caller passed explicit `targetDeviceIds` — that path is
      // already a targeted control delivery (e.g. desktop sync bundle) and
      // re-broadcasting it to every other own device would amplify a 1-to-1
      // control message into accidental self-spam.
      if (!hasExplicitTargets) {
        unawaited(
          _mirrorAttachmentToOwnDevices(
            convoId: resolvedPeerProfileId,
            msgEventId: eventId,
            blobId: uploaded.blobId,
            fileKeyB64: uploaded.fileKeyB64,
            sizeBytes: bytes.length,
            createdAtMs: now,
            blobAccessTokenB64: uploaded.blobAccessTokenB64,
            mime: uploaded.mime,
            replyToPayloadEventId: replyToPayloadEventId,
            mediaGroupId: mediaGroupId,
            caption: caption,
            filename: filename,
            videoNote: videoNote,
            durationMs: durationMs,
            waveform: waveform,
            musicTitle: musicTitle,
            musicArtist: musicArtist,
          ),
        );
      }
      return eventId;
    } catch (e) {
      if (localEventId != null) {
        final queued = await db.outboxCountForEventRef(localEventId);
        if (queued == 0) {
          await db.updateEventLocalState(
            eventId: localEventId,
            localState: 'failed',
          );
        }
      }
      _changed.add(null);
      rethrow;
    }
  }

  /// Годен ли blob исходного вложения к повторной отдаче.
  ///
  /// Возвращает `null` — значит заливаем заново, как раньше.
  ///
  /// 🔴 СРОК ЖИЗНИ ПРОВЕРЯЕТСЯ ОБЯЗАТЕЛЬНО. Blob живёт на сервере семь дней.
  /// Переслать неделю спустя, отдав тот же идентификатор, значит вручить
  /// получателю ссылку в пустоту: у него появится файл, который не скачается
  /// НИКОГДА. Лучше залить заново, чем отдать битое.
  ///
  /// Запас в час — на случай, если получатель откроет чат не сразу.
  Future<EncryptedAttachment?> _reusableUploadForForward(
    AttachmentEventV1? source, {
    required String resolvedMime,
  }) async {
    if (source == null) return null;
    final blobId = source.blobId.trim();
    final fileKeyB64 = source.fileKeyB64.trim();
    if (blobId.isEmpty || fileKeyB64.isEmpty) return null;
    // Локальный blob («local:…») на сервере не существует: он заводится для
    // отправки самому себе на ОДНОМ устройстве. Отдать его другому устройству
    // нельзя — качать будет неоткуда.
    if (blobId.startsWith('local:')) return null;

    final db = _db;
    if (db == null) return null;
    Map<String, Object?>? row;
    try {
      row = await db.attachmentGet(blobId);
    } catch (_) {
      return null;
    }
    if (row == null) return null;
    final expiresAtMs = (row['expires_at_ms'] as num?)?.toInt() ?? 0;
    final nowMs = DateTime.now().millisecondsSinceEpoch;
    if (!canReuseBlobForForward(
      blobId: blobId,
      fileKeyB64: fileKeyB64,
      expiresAtMs: expiresAtMs,
      nowMs: nowMs,
    )) {
      DiagLog.event('media', 'forward_blob_reuse_skipped', <String, Object?>{
        'reason': 'expired_or_unknown',
      });
      return null;
    }
    final accessTokenB64 =
        ((row['access_token_b64'] as String?) ?? source.blobAccessTokenB64 ?? '')
            .trim();

    DiagLog.event('media', 'forward_blob_reused', <String, Object?>{
      'ttl_left_ms': expiresAtMs - nowMs,
    });
    return EncryptedAttachment(
      blobId: blobId,
      ciphertextSizeBytes: (row['ciphertext_size_bytes'] as num?)?.toInt() ?? 0,
      expiresAtMs: expiresAtMs,
      fileKeyB64: fileKeyB64,
      // Пустой токен — законное значение: часть блобов открывается без него.
      blobAccessTokenB64: accessTokenB64,
      mime: (source.mime ?? '').trim().isEmpty
          ? resolvedMime
          : source.mime!.trim(),
      debugTag: 'reuse',
    );
  }

  /// Сколько жизни blob должно остаться, чтобы отдавать его повторно.
  static const int _reusableBlobMinTtlMs = 60 * 60 * 1000;

  /// Правило «можно ли отдать этот blob повторно» — БЕЗ базы и без контроллера.
  ///
  /// 🔴 ЧИСТОЙ ФУНКЦИЕЙ НАМЕРЕННО. Первая версия теста поднимала целый
  /// `AppController`, и общий прогон начал ОБРЫВАТЬСЯ в разных местах: живой
  /// контроллер держит таймеры и подписки, которые тест не закрывает. Правило
  /// решает судьбу файла у получателя, поэтому проверяться оно обязано дёшево и
  /// без побочных эффектов.
  @visibleForTesting
  static bool canReuseBlobForForward({
    required String blobId,
    required String fileKeyB64,
    required int expiresAtMs,
    required int nowMs,
  }) {
    final id = blobId.trim();
    if (id.isEmpty || fileKeyB64.trim().isEmpty) return false;
    // «local:…» существует только на этом устройстве: на сервере его нет, и
    // второму устройству качать будет неоткуда.
    if (id.startsWith('local:')) return false;
    if (expiresAtMs <= 0) return false;
    // Запас: получатель может открыть чат не сразу, а blob, умерший по дороге,
    // оставит его с файлом, который не скачается никогда.
    return expiresAtMs - nowMs >= _reusableBlobMinTtlMs;
  }

  Future<String> sendAttachmentFile({
    required String peerProfileId,
    required String filePath,
    String? mime,
    /// Вложение, чей blob можно отдать повторно вместо новой заливки.
    /// Заполняется ТОЛЬКО пересылкой на свои устройства — см.
    /// [_reusableUploadForForward].
    AttachmentEventV1? reuseBlobFrom,
    String? replyToPayloadEventId,
    String? mediaGroupId,
    void Function(String stage)? onStage,
    void Function(int sentBytes, int totalBytes)? onUploadProgress,
    BlobUploadCancelToken? cancelToken,
    List<String>? targetDeviceIds,
    List<int>? waveform,
    String? caption,
    String? filename,
    bool videoNote = false,
    int? durationMs,
    String? musicTitle,
    String? musicArtist,
  }) async {
    final file = File(filePath);
    if (!await file.exists()) {
      throw AttachmentFailure(AttachmentFailureCode.fileMissing);
    }
    // Use ONLY a caller-provided file name (the file tab / gallery-as-files
    // paths pass one). Normal photos pass none → null filename → they render as
    // photos/albums, NOT document rows. (Auto-basename here previously turned
    // every sent photo into a document.)
    final String? resolvedFilename =
        (filename != null && filename.trim().isNotEmpty)
        ? filename.trim()
        : null;

    // Guardrail: keep MVP safe for both client and relay.
    final size = await file.length();
    _throwIfAttachmentTooLarge(size);

    final resolvedMime = (mime != null && mime.trim().isNotEmpty)
        ? mime.trim()
        : 'application/octet-stream';

    // Fast path for typical photos: avoid streamed file-encryption/upload path
    // that can stall on some Android OEM stacks.
    if (_shouldUseBufferedAttachmentUpload(
      sizeBytes: size,
      mime: resolvedMime,
    )) {
      if (cancelToken?.isCanceled == true) {
        throw AttachmentFailure(AttachmentFailureCode.uploadCanceled);
      }
      onStage?.call('uploading');
      final bytes = await file.readAsBytes().timeout(
        _attachmentReadTimeout,
        onTimeout: () =>
            throw AttachmentFailure(AttachmentFailureCode.uploadTimedOut),
      );
      if (cancelToken?.isCanceled == true) {
        throw AttachmentFailure(AttachmentFailureCode.uploadCanceled);
      }
      // TZ E1/E2 enrichment: metadata strip (GPS et al), sender-stamped pixel
      // dims (zero reflow) and the inline blurred preview.
      //
      // ALL of it is COSMETIC/privacy polish — none of it may be able to fail
      // the send. This guard is parity with the album path, which always had
      // one; its absence here is exactly what broke single-photo sends while an
      // album of the SAME photos went through (the helpers' `finally` cleanup
      // could throw straight past their own catch — see _disposeQuietly).
      var effectiveBytes = bytes;
      ({int width, int height})? bufferedImageDims;
      String? inlineThumbB64;
      try {
        effectiveBytes = _maybeStripJpegMetadata(bytes, resolvedMime);
        bufferedImageDims = await _imagePixelDimsFromBytes(
          effectiveBytes,
          resolvedMime,
        );
        inlineThumbB64 = await _buildAttachmentInlineThumbB64(
          effectiveBytes,
          resolvedMime,
        );
      } catch (e) {
        // Fall back to the ORIGINAL bytes: dims/thumb describe what the
        // recipient decodes (I15), so if enrichment half-failed we must not
        // ship a mismatched pair. The photo still sends.
        effectiveBytes = bytes;
        bufferedImageDims = null;
        inlineThumbB64 = null;
        DiagLog.event('media', 'photo_enrich_failed', {
          'reason': _classifyShortReason(e),
        });
      }
      return sendAttachment(
        peerProfileId: peerProfileId,
        bytes: effectiveBytes,
        mime: resolvedMime,
        replyToPayloadEventId: replyToPayloadEventId,
        mediaGroupId: mediaGroupId,
        targetDeviceIds: targetDeviceIds,
        waveform: waveform,
        caption: caption,
        filename: resolvedFilename,
        videoNote: videoNote,
        durationMs: durationMs,
        // Music tags MUST ride along here. This delegation is the path a normal
        // track actually takes (audio is not a "buffered visual" mime, so it
        // gets the 8 MB threshold and a typical 3-8 MB MP3 lands in this
        // branch). Dropping them here is what made a sent track fall back to
        // the generic "Music / Unknown artist" once the upload settled.
        musicTitle: musicTitle,
        musicArtist: musicArtist,
        width: bufferedImageDims?.width,
        height: bufferedImageDims?.height,
        thumbB64: inlineThumbB64,
      );
    }

    final db = _db;
    final relay = _relay;
    final did = _deviceId;
    final pid = _profileId;
    final keys = _keys;
    final ratchet = _ratchetV3;
    final crypto = _crypto;
    final attachments = _attachments;
    if (db == null || did == null || pid == null || crypto == null) {
      throw AttachmentFailure(AttachmentFailureCode.localUnavailable);
    }
    if (relay == null ||
        keys == null ||
        ratchet == null ||
        attachments == null) {
      throw AttachmentFailure(AttachmentFailureCode.transportUnavailable);
    }

    final resolvedPeerProfileId =
        await _normalizeDirectPeerProfileId(peerProfileId) ?? peerProfileId;
    if (resolvedPeerProfileId.startsWith('dev:')) {
      throw AttachmentFailure(AttachmentFailureCode.contactSyncPending);
    }

    if (await db.blockedProfileIsBlocked(resolvedPeerProfileId)) {
      throw AttachmentFailure(AttachmentFailureCode.contactBlocked);
    }

    // Sprint 2 hotfix (2026-05-19): same explicit-targets gate as
    // sendAttachment(). When caller specifies target devices we must skip
    // the self short-circuit and do a real upload+fanout. See `sendAttachment`
    // for the rationale.
    final explicitTargetDeviceIds = targetDeviceIds
        ?.map((d) => d.trim())
        .where((d) => d.isNotEmpty && d != did)
        .toSet()
        .toList(growable: false);
    final hasExplicitTargets =
        explicitTargetDeviceIds != null && explicitTargetDeviceIds.isNotEmpty;

    if (resolvedPeerProfileId == pid && !hasExplicitTargets) {
      final now = DateTime.now().millisecondsSinceEpoch;
      final blobId = 'local:${_uuid.v4()}';
      final eventId = _uuid.v4();

      await db.convoEnsure1to1(peerProfileId: resolvedPeerProfileId);
      await db.attachmentUpsert(
        blobId: blobId,
        fileKeyB64: '',
        accessTokenB64: '',
        mime: resolvedMime,
        plaintextSizeBytes: size,
        ciphertextSizeBytes: size,
        expiresAtMs: now + (3650 * 24 * 60 * 60 * 1000),
        createdAtMs: now,
      );
      await _cacheAttachmentFileFromPath(
        blobId: blobId,
        mime: resolvedMime,
        sourcePath: filePath,
      );

      final payload = E2ePayloadV1(
        senderDeviceId: did,
        createdAtMs: now,
        events: [
          AttachmentEventV1(
            eventId: eventId,
            blobId: blobId,
            fileKeyB64: '',
            blobAccessTokenB64: null,
            sizeBytes: size,
            mime: resolvedMime,
            replyToEventId: replyToPayloadEventId,
            mediaGroupId: mediaGroupId,
            waveform: waveform,
            caption: caption,
            filename: resolvedFilename,
            videoNote: videoNote,
            durationMs: durationMs,
            musicTitle: musicTitle,
            musicArtist: musicArtist,
          ),
        ],
      );
      final localCipher = await crypto.encrypt(payload.encode());
      await db.insertEvent(
        eventId: 'local:$eventId',
        convoId: resolvedPeerProfileId,
        type: 'att',
        senderDeviceId: did,
        ciphertextB64: base64Encode(localCipher),
        createdAtMs: now,
        localState: 'sent',
        payloadEventId: eventId,
      );
      await db.convoTouch(convoId: resolvedPeerProfileId, atMs: now);
      _changed.add(null);
      return eventId;
    }

    try {
      _throwIfTransportBlocked();
    } catch (error) {
      throw describeAttachmentFailure(
        error,
        fallbackCode: AttachmentFailureCode.transportBlocked,
      );
    }
    final readyForDirectChat = await _ensureDirectConversationReadyForOutgoing(
      resolvedPeerProfileId,
    );
    if (!readyForDirectChat) {
      throw AttachmentFailure(AttachmentFailureCode.contactBlocked);
    }
    await db.convoEnsure1to1(peerProfileId: resolvedPeerProfileId);

    final tmp = await getTemporaryDirectory();
    final now = DateTime.now().millisecondsSinceEpoch;
    _debugAttachmentFlow('start');
    onStage?.call('encrypting');
    // 🔴 ПЕРЕСЫЛКА СЕБЕ НЕ ЗАЛИВАЕТ ФАЙЛ ЗАНОВО (14.08.2026).
    //
    // Владелец: «оно ведь уже загружено, почему грузится по новой?». Для чужого
    // получателя ответ «иначе сервер свяжет два чата» — это метаданные. Но для
    // СВОИХ устройств связывать нечего: оба конца мои, и blob можно отдать тот
    // же самый вместе с его ключом.
    //
    // Содержимое от этого не становится уязвимее ни на бит: файл лежит на
    // сервере зашифрованным XChaCha20-Poly1305, ключ едет получателю внутри
    // E2EE-сообщения, и у сервера его нет ни в каком виде.
    final reusable = await _reusableUploadForForward(
      reuseBlobFrom,
      resolvedMime: resolvedMime,
    );
    late final EncryptedAttachment uploaded;
    if (reusable != null) {
      uploaded = reusable;
      _debugAttachmentFlow('upload.reused');
    } else {
      try {
        uploaded = await attachments
            .encryptFileAndUpload(
              file,
              tempDir: tmp,
              ttlSeconds: 7 * 24 * 60 * 60,
              mime: resolvedMime,
              onUploadProgress: onUploadProgress,
              onStage: onStage,
              cancelToken: cancelToken,
            )
            .timeout(
              _attachmentUploadTimeout,
              onTimeout: () =>
                  throw AttachmentFailure(AttachmentFailureCode.uploadTimedOut),
            );
      } catch (error) {
        throw describeAttachmentFailure(
          error,
          fallbackCode: AttachmentFailureCode.serviceUnavailable,
        );
      }
      _debugAttachmentFlow('upload.done');
    }

    // Cancel landed AFTER the upload finished but BEFORE the event was written
    // — abort so the cancelled bubble does not get inserted and "reappear".
    if (cancelToken?.isCanceled == true) {
      throw AttachmentFailure(AttachmentFailureCode.uploadCanceled);
    }

    await db.attachmentUpsert(
      blobId: uploaded.blobId,
      fileKeyB64: uploaded.fileKeyB64,
      accessTokenB64: uploaded.blobAccessTokenB64,
      mime: uploaded.mime,
      plaintextSizeBytes: size,
      ciphertextSizeBytes: uploaded.ciphertextSizeBytes,
      expiresAtMs: uploaded.expiresAtMs,
      createdAtMs: now,
    );

    final eventId = _uuid.v4();
    final payload = E2ePayloadV1(
      senderDeviceId: did,
      createdAtMs: now,
      events: [
        AttachmentEventV1(
          eventId: eventId,
          blobId: uploaded.blobId,
          fileKeyB64: uploaded.fileKeyB64,
          blobAccessTokenB64: uploaded.blobAccessTokenB64,
          sizeBytes: size,
          mime: uploaded.mime,
          replyToEventId: replyToPayloadEventId,
          mediaGroupId: mediaGroupId,
          waveform: waveform,
          caption: caption,
          filename: resolvedFilename,
          videoNote: videoNote,
          durationMs: durationMs,
          musicTitle: musicTitle,
          musicArtist: musicArtist,
        ),
      ],
    );

    await _cacheAttachmentFileFromPath(
      blobId: uploaded.blobId,
      mime: uploaded.mime,
      sourcePath: filePath,
    );

    final localCipher = await crypto.encrypt(payload.encode());
    final localB64 = base64Encode(localCipher);
    final localEventId = 'local:$eventId';
    final transportMetaJson = _buildChatTransportMetaJson(
      convoId: resolvedPeerProfileId,
      isGroup: false,
      messageKind: 'attachment',
      payloadEventId: eventId,
      createdAtMs: now,
      senderProfileId: pid,
      senderDisplayName: myNickname,
      previewText: _pushTransportPreviewForAttachment(uploaded.mime),
    );
    await db.insertEvent(
      eventId: localEventId,
      convoId: resolvedPeerProfileId,
      type: 'att',
      senderDeviceId: did,
      ciphertextB64: localB64,
      createdAtMs: now,
      localState: 'pending',
      payloadEventId: eventId,
    );
    await db.convoTouch(convoId: resolvedPeerProfileId, atMs: now);
    _changed.add(null);

    Future<void> queueForNoDeviceRetry(String reason) async {
      // The blob is already uploaded (7-day TTL). Instead of marking the whole
      // attachment 'failed', queue it for background retry — the watchdog
      // (`_retryPendingNoDeviceSend`) re-resolves devices with a forced refresh
      // and flushes once the transient condition clears.
      await _queuePendingNoDeviceEntry(
        profileId: resolvedPeerProfileId,
        entry: _PendingNoDeviceEntry(
          localEventId: localEventId,
          payloadBytes: Uint8List.fromList(payload.encode()),
          transportMetaJson: transportMetaJson,
          createdAtMs: now,
        ),
      );
      callLog(
        'AppCtrl',
        'sendAttachmentFile queued for retry ($reason): '
            'profile=$resolvedPeerProfileId, localEvent=$localEventId',
      );
      _changed.add(null);
    }

    Future<void> finalizeSend() async {
      _debugAttachmentFlow('finalize.start');
      final List<String> targets;
      if (hasExplicitTargets) {
        targets = explicitTargetDeviceIds;
      } else {
        try {
          targets = await _listRecipientDevicesForSend(
            peerProfileId: resolvedPeerProfileId,
            selfDeviceId: did,
          ).timeout(
            const Duration(seconds: 20),
            onTimeout: () =>
                throw AttachmentFailure(AttachmentFailureCode.finalizeTimedOut),
          );
        } catch (e) {
          // Transient device-lookup failure — keys-server 429 (rate-limit),
          // network blip, or the 20 s timeout. This is exactly what dropped
          // SOME files from a GROUP send: a 429 storm on the keys server made
          // per-file device lookups THROW, and each throw failed that one file
          // while its neighbours (whose lookups happened to succeed) went
          // through. Queue for retry instead of failing so the whole batch is
          // eventually delivered. `recipientProfileNotFound` is only decided on
          // an EMPTY (not thrown) result below, so a genuinely missing profile
          // still fails fast there.
          await queueForNoDeviceRetry('device lookup failed: $e');
          return; // stays 'pending'; watchdog retries
        }
      }
      if (targets.isEmpty) {
        bool exists = false;
        try {
          exists = await keys
              .profileExists(resolvedPeerProfileId)
              .timeout(const Duration(seconds: 12), onTimeout: () => false);
        } catch (_) {}
        if (!exists) {
          throw AttachmentFailure(
            AttachmentFailureCode.recipientProfileNotFound,
          );
        }
        // Recipient exists but has no resolvable devices right now (offline, or
        // their device list hasn't been cached yet). Queue for background retry
        // — SAME as the buffered `sendAttachment` path — so the attachment is
        // delivered when they next come online, instead of failing with "no
        // deliverable devices". The blob is already uploaded (7-day TTL). This
        // is why large files/videos previously only sent while the peer was
        // online: the streamed path threw here instead of queuing.
        await queueForNoDeviceRetry('no devices yet');
        return; // attachment stays 'pending'; the watchdog retries on presence
      }
      _debugAttachmentFlow('finalize.targets');

      {
        final List<String> blocking;
        try {
          blocking = await _sendGateBlockingDevices(
            resolvedPeerProfileId,
            targets,
          );
        } on AttachmentFailure {
          rethrow;
        } catch (error) {
          throw describeAttachmentFailure(
            error,
            fallbackCode: AttachmentFailureCode.serviceUnavailable,
          );
        }
        if (blocking.isNotEmpty) {
          throw AttachmentFailure(AttachmentFailureCode.contactUnverified);
        }
      }

      var queuedTargets = 0;
      for (final toDeviceId in targets) {
        try {
          final msgId = _uuid.v4();
          final wire = await _encryptToPeerSerialized(
            ratchet: ratchet,
            selfDeviceId: did,
            peerProfileId: resolvedPeerProfileId,
            peerDeviceId: toDeviceId,
            plaintext: Uint8List.fromList(payload.encode()),
          );
          await db.outboxUpsert(
            msgId: msgId,
            toDeviceId: toDeviceId,
            ciphertextB64: base64Encode(wire),
            ttlSeconds: _outboxUserMessageTtlSeconds,
            state: 'pending',
            attemptCount: 0,
            nextRetryAtMs: now,
            createdAtMs: now,
            transportMetaJson: transportMetaJson,
            eventIdRef: localEventId,
          );
          queuedTargets++;
        } catch (e) {
          callLog(
            'AppCtrl',
            'sendAttachmentFile fanout skip target=$toDeviceId peer=$resolvedPeerProfileId: $e',
          );
        }
      }

      if (queuedTargets == 0) {
        throw AttachmentFailure(
          AttachmentFailureCode.noDeliverableTargetDevices,
        );
      }

      _changed.add(null);
      _kickRelayOutbox(relay);
      _debugAttachmentFlow('finalize.enqueued');
    }

    try {
      await finalizeSend().timeout(
        _attachmentFinalizeTimeout,
        onTimeout: () =>
            throw AttachmentFailure(AttachmentFailureCode.finalizeTimedOut),
      );
      _debugAttachmentFlow('done');
      // Multi-device sync: mirror to my own other devices (TZ §21.1).
      // Skipped when caller passed explicit `targetDeviceIds` — that path is
      // already a targeted control delivery (e.g. desktop sync bundle) and
      // re-broadcasting it would amplify a 1-to-1 control message into
      // accidental self-spam.
      if (!hasExplicitTargets) {
        unawaited(
          _mirrorAttachmentToOwnDevices(
            convoId: resolvedPeerProfileId,
            msgEventId: eventId,
            blobId: uploaded.blobId,
            fileKeyB64: uploaded.fileKeyB64,
            sizeBytes: size,
            createdAtMs: now,
            blobAccessTokenB64: uploaded.blobAccessTokenB64,
            mime: uploaded.mime,
            replyToPayloadEventId: replyToPayloadEventId,
            mediaGroupId: mediaGroupId,
            caption: caption,
            filename: resolvedFilename,
            videoNote: videoNote,
            durationMs: durationMs,
            waveform: waveform,
            musicTitle: musicTitle,
            musicArtist: musicArtist,
          ),
        );
      }
      return eventId;
    } catch (e) {
      final queued = await db.outboxCountForEventRef(localEventId);
      if (queued == 0) {
        await db.updateEventLocalState(
          eventId: localEventId,
          localState: 'failed',
        );
      }
      _debugAttachmentFlow('fail', error: e);
      _changed.add(null);
      rethrow;
    }
  }

  /// Reads an image's pixel dimensions from its HEADER (no full pixel decode) so
  /// they can be stamped on the outgoing attachment and let the recipient
  /// reserve the exact bubble height. Best-effort: any failure returns null and
  /// the send proceeds unchanged (the recipient then measures on-device). Images
  /// only — a video's dimensions would need a full codec init.
  /// TZ E1 (2026-07-18, privacy): strip JPEG metadata (EXIF GPS, timestamps,
  /// device serials…) WITHOUT re-encoding pixels — `injectJpgExif` rewrites the
  /// APP1 segment only, so bytes stay pixel-identical (I15: sender-stamped
  /// dims/thumb keep matching what the recipient decodes). The Orientation tag
  /// is the ONE thing preserved: dropping it would visually rotate portrait
  /// photos on the receiving side.
  ///
  /// Best-effort by contract: ANY failure returns the ORIGINAL bytes —
  /// delivery always wins over metadata hygiene. JPEG only in this phase
  /// (Android camera default); HEIC/PNG/WebP are TZ E1 phase 2.
  Uint8List _maybeStripJpegMetadata(Uint8List bytes, String mime) {
    if (!kStripImageMetadataOnSend) return bytes;
    final m = mime.toLowerCase();
    if (m != 'image/jpeg' && m != 'image/jpg') return bytes;
    try {
      return stripJpegMetadataKeepOrientation(bytes);
    } catch (_) {
      DiagLog.event('media', 'exif_strip_failed', const {});
      return bytes;
    }
  }

  /// TZ E2 (2026-07-18): tiny inline preview for [AttachmentEventV1.thumbB64] —
  /// a ~32px JPEG (typically 0.4–1 KiB) decoded via the ui codec (hardware
  /// downscale, EXIF-orientation-correct) so the recipient's bubble shows a
  /// real blurred preview before the blob download even starts. Best-effort:
  /// null on any failure / oversized result / non-image.
  Future<String?> _buildAttachmentInlineThumbB64(
    Uint8List bytes,
    String mime,
  ) async {
    if (!mime.toLowerCase().startsWith('image/')) return null;
    ui.ImmutableBuffer? buffer;
    ui.Codec? codec;
    ui.Image? frame;
    try {
      buffer = await ui.ImmutableBuffer.fromUint8List(bytes);
      codec = await ui.instantiateImageCodecWithSize(
        buffer,
        getTargetSize: (w, h) => ui.TargetImageSize(
          width: w >= h ? 32 : null,
          height: h > w ? 32 : null,
        ),
      );
      frame = (await codec.getNextFrame()).image;
      final raw = await frame.toByteData(format: ui.ImageByteFormat.rawRgba);
      if (raw == null) return null;
      final small = img.Image.fromBytes(
        width: frame.width,
        height: frame.height,
        bytes: raw.buffer,
        numChannels: 4,
      );
      final jpg = img.encodeJpg(small, quality: 50);
      if (jpg.length > 3 * 1024) return null; // keep the payload tiny
      return base64Encode(jpg);
    } catch (_) {
      return null;
    } finally {
      // A throw in `finally` escapes the catch above — it would propagate out
      // of a helper documented as best-effort and fail the whole send (that is
      // exactly what broke single-photo sends: the album path happened to wrap
      // these calls in its own try/catch, the single-photo path did not).
      // Native handles can legitimately refuse a second release, so each
      // dispose is individually best-effort.
      _disposeQuietly(() => frame?.dispose());
      _disposeQuietly(() => codec?.dispose());
      _disposeQuietly(() => buffer?.dispose());
    }
  }

  /// Runs a native-handle release without ever letting it escape. See the
  /// `finally` blocks above: cleanup must not be able to fail a message send.
  void _disposeQuietly(void Function() release) {
    try {
      release();
    } catch (_) {
      // Best-effort: an already-released handle must never fail a send.
    }
  }

  Future<({int width, int height})?> _imagePixelDimsFromBytes(
    Uint8List bytes,
    String mime,
  ) async {
    if (!mime.toLowerCase().startsWith('image/')) return null;
    ui.ImmutableBuffer? buffer;
    ui.ImageDescriptor? descriptor;
    try {
      buffer = await ui.ImmutableBuffer.fromUint8List(bytes);
      descriptor = await ui.ImageDescriptor.encoded(buffer);
      final w = descriptor.width;
      final h = descriptor.height;
      if (w > 0 && h > 0) return (width: w, height: h);
      return null;
    } catch (_) {
      return null;
    } finally {
      // See _disposeQuietly: a throw here would escape the catch above and
      // fail the caller's send.
      _disposeQuietly(() => descriptor?.dispose());
      _disposeQuietly(() => buffer?.dispose());
    }
  }

  /// File variant of [_imagePixelDimsFromBytes]. The mime gate short-circuits
  /// before any I/O, so a non-image (video/voice/document) is never read.
  Future<({int width, int height})?> _readImagePixelDims(
    File file,
    String mime,
  ) async {
    if (!mime.toLowerCase().startsWith('image/')) return null;
    try {
      return await _imagePixelDimsFromBytes(await file.readAsBytes(), mime);
    } catch (_) {
      return null;
    }
  }

  static String? _nonEmptyTrimmed(String? value) {
    final trimmed = value?.trim();
    return (trimmed == null || trimmed.isEmpty) ? null : trimmed;
  }

  Future<List<_ValidatedAttachmentFile>> _validateAttachmentFileRequests(
    List<AttachmentFileSendRequest> requests,
  ) async {
    if (requests.isEmpty) {
      throw AttachmentFailure(AttachmentFailureCode.fileMissing);
    }

    final validated = <_ValidatedAttachmentFile>[];
    for (final request in requests) {
      final path = request.filePath.trim();
      if (path.isEmpty) {
        throw AttachmentFailure(AttachmentFailureCode.fileMissing);
      }
      final file = File(path);
      if (!await file.exists()) {
        throw AttachmentFailure(AttachmentFailureCode.fileMissing);
      }
      final sizeBytes = await file.length();
      _throwIfAttachmentTooLarge(sizeBytes);
      final resolvedMime =
          (request.mime != null && request.mime!.trim().isNotEmpty)
          ? request.mime!.trim()
          : 'application/octet-stream';
      // No auto-basename: only a caller-supplied name marks an attachment as a
      // document. Normal photo albums pass none → null → they render as photos.
      final resolvedFileName =
          (request.fileName != null && request.fileName!.trim().isNotEmpty)
          ? request.fileName!.trim()
          : '';
      final resolvedCaption = request.caption?.trim();
      // TZ E1+E2: for images small enough to buffer, read the bytes ONCE and
      // derive everything from them — metadata strip (JPEG, pixel-lossless),
      // pixel dims, and the inline thumb — so all three describe the exact
      // bytes that get uploaded (I15). Oversized/streamed images keep the old
      // header-only dims read; any failure falls back likewise (best-effort).
      var effectiveFile = file;
      var effectivePath = path;
      var effectiveSize = sizeBytes;
      ({int width, int height})? dims;
      String? thumbB64;
      final isImage = resolvedMime.toLowerCase().startsWith('image/');
      if (isImage && sizeBytes <= _bufferedVisualAttachmentThresholdBytes) {
        try {
          var bytes = await file.readAsBytes();
          final stripped = _maybeStripJpegMetadata(bytes, resolvedMime);
          if (!identical(stripped, bytes)) {
            final tmp = await getTemporaryDirectory();
            final scrubbed = File(
              p.join(tmp.path, 'sendstrip_${_uuid.v4()}${p.extension(path)}'),
            );
            await scrubbed.writeAsBytes(stripped, flush: true);
            effectiveFile = scrubbed;
            effectivePath = scrubbed.path;
            effectiveSize = stripped.length;
            bytes = stripped;
          }
          dims = await _imagePixelDimsFromBytes(bytes, resolvedMime);
          thumbB64 = await _buildAttachmentInlineThumbB64(bytes, resolvedMime);
        } catch (_) {
          effectiveFile = file;
          effectivePath = path;
          effectiveSize = sizeBytes;
          dims = await _readImagePixelDims(file, resolvedMime);
          thumbB64 = null;
        }
      } else {
        dims = await _readImagePixelDims(file, resolvedMime);
      }
      // Подсказки окна отправки (ролик: размеры и миниатюра по кадру) — только
      // там, где из самих байтов ничего не вышло.
      final hintW = request.width;
      final hintH = request.height;
      if (dims == null &&
          hintW != null &&
          hintH != null &&
          hintW > 0 &&
          hintH > 0) {
        dims = (width: hintW, height: hintH);
      }
      final hintThumb = request.thumbB64?.trim();
      if (thumbB64 == null && hintThumb != null && hintThumb.isNotEmpty) {
        thumbB64 = hintThumb;
      }
      final hintDuration = request.durationMs;
      validated.add(
        _ValidatedAttachmentFile(
          file: effectiveFile,
          filePath: effectivePath,
          mime: resolvedMime,
          sizeBytes: effectiveSize,
          caption: (resolvedCaption == null || resolvedCaption.isEmpty)
              ? null
              : resolvedCaption,
          fileName: resolvedFileName.isEmpty ? null : resolvedFileName,
          width: dims?.width,
          height: dims?.height,
          thumbB64: thumbB64,
          durationMs: (hintDuration != null && hintDuration > 0)
              ? hintDuration
              : null,
          musicTitle: _nonEmptyTrimmed(request.musicTitle),
          musicArtist: _nonEmptyTrimmed(request.musicArtist),
        ),
      );
    }
    return validated;
  }

  BlobUploadCancelToken? _cancelTokenAt(
    List<BlobUploadCancelToken>? cancelTokens,
    int index,
  ) {
    if (cancelTokens == null || index < 0 || index >= cancelTokens.length) {
      return null;
    }
    return cancelTokens[index];
  }

  Future<_PreparedAttachmentUpload> _uploadValidatedAttachmentFile({
    required _ValidatedAttachmentFile input,
    required AttachmentService attachments,
    required Directory tempDir,
    BlobUploadCancelToken? cancelToken,
    void Function(String stage)? onStage,
    void Function(int sentBytes, int totalBytes)? onUploadProgress,
  }) async {
    if (_shouldUseBufferedAttachmentUpload(
      sizeBytes: input.sizeBytes,
      mime: input.mime,
    )) {
      if (cancelToken?.isCanceled == true) {
        throw AttachmentFailure(AttachmentFailureCode.uploadCanceled);
      }
      onStage?.call('uploading');
      onUploadProgress?.call(0, input.sizeBytes);
      final bytes = await input.file.readAsBytes().timeout(
        _attachmentReadTimeout,
        onTimeout: () =>
            throw AttachmentFailure(AttachmentFailureCode.uploadTimedOut),
      );
      if (cancelToken?.isCanceled == true) {
        throw AttachmentFailure(AttachmentFailureCode.uploadCanceled);
      }
      late final EncryptedAttachment uploaded;
      try {
        uploaded = await attachments
            .encryptAndUpload(
              bytes,
              ttlSeconds: 7 * 24 * 60 * 60,
              mime: input.mime,
            )
            .timeout(
              _attachmentUploadTimeout,
              onTimeout: () =>
                  throw AttachmentFailure(AttachmentFailureCode.uploadTimedOut),
            );
      } catch (error) {
        throw describeAttachmentFailure(
          error,
          fallbackCode: AttachmentFailureCode.serviceUnavailable,
        );
      }
      await _cacheAttachmentBytes(
        blobId: uploaded.blobId,
        mime: uploaded.mime,
        plaintext: bytes,
      );
      onUploadProgress?.call(input.sizeBytes, input.sizeBytes);
      return _PreparedAttachmentUpload(input: input, uploaded: uploaded);
    }

    onStage?.call('encrypting');
    late final EncryptedAttachment uploaded;
    try {
      uploaded = await attachments
          .encryptFileAndUpload(
            input.file,
            tempDir: tempDir,
            ttlSeconds: 7 * 24 * 60 * 60,
            mime: input.mime,
            onUploadProgress: onUploadProgress,
            onStage: onStage,
            cancelToken: cancelToken,
          )
          .timeout(
            _attachmentUploadTimeout,
            onTimeout: () =>
                throw AttachmentFailure(AttachmentFailureCode.uploadTimedOut),
          );
    } catch (error) {
      throw describeAttachmentFailure(
        error,
        fallbackCode: AttachmentFailureCode.serviceUnavailable,
      );
    }
    await _cacheAttachmentFileFromPath(
      blobId: uploaded.blobId,
      mime: uploaded.mime,
      sourcePath: input.filePath,
    );
    return _PreparedAttachmentUpload(input: input, uploaded: uploaded);
  }

  Future<List<String>> sendAttachmentFiles({
    required String peerProfileId,
    required List<AttachmentFileSendRequest> files,
    String? replyToPayloadEventId,
    String? mediaGroupId,
    void Function(String stage)? onStage,
    void Function(int index, int sentBytes, int totalBytes)? onUploadProgress,
    List<BlobUploadCancelToken>? cancelTokens,
    String? caption,
  }) async {
    final validated = await _validateAttachmentFileRequests(files);
    // Album caption is attached to the FIRST item only (Telegram-style). An
    // explicit per-request caption on validated[0] takes precedence over the
    // method-level [caption] argument.
    String? captionForIndex(int index) {
      if (index != 0) return null;
      final perRequest = validated[index].caption;
      if (perRequest != null && perRequest.isNotEmpty) return perRequest;
      final trimmed = caption?.trim();
      return (trimmed == null || trimmed.isEmpty) ? null : trimmed;
    }

    final db = _db;
    final relay = _relay;
    final did = _deviceId;
    final pid = _profileId;
    final keys = _keys;
    final ratchet = _ratchetV3;
    final crypto = _crypto;
    final attachments = _attachments;
    if (db == null || did == null || pid == null || crypto == null) {
      throw AttachmentFailure(AttachmentFailureCode.localUnavailable);
    }

    final resolvedPeerProfileId =
        await _normalizeDirectPeerProfileId(peerProfileId) ?? peerProfileId;
    if (resolvedPeerProfileId.startsWith('dev:')) {
      throw AttachmentFailure(AttachmentFailureCode.contactSyncPending);
    }
    if (await db.blockedProfileIsBlocked(resolvedPeerProfileId)) {
      throw AttachmentFailure(AttachmentFailureCode.contactBlocked);
    }

    final effectiveGroupId =
        (mediaGroupId != null && mediaGroupId.trim().isNotEmpty)
        ? mediaGroupId.trim()
        : validated.length > 1
        ? _uuid.v4()
        : null;

    if (resolvedPeerProfileId == pid) {
      final eventIds = <String>[];
      final baseNow = DateTime.now().millisecondsSinceEpoch;
      await db.convoEnsure1to1(peerProfileId: resolvedPeerProfileId);
      for (var index = 0; index < validated.length; index++) {
        final input = validated[index];
        final createdAt = baseNow + index;
        final blobId = 'local:${_uuid.v4()}';
        final eventId = _uuid.v4();
        await db.attachmentUpsert(
          blobId: blobId,
          fileKeyB64: '',
          accessTokenB64: '',
          mime: input.mime,
          plaintextSizeBytes: input.sizeBytes,
          ciphertextSizeBytes: input.sizeBytes,
          expiresAtMs: createdAt + (3650 * 24 * 60 * 60 * 1000),
          createdAtMs: createdAt,
        );
        await _cacheAttachmentFileFromPath(
          blobId: blobId,
          mime: input.mime,
          sourcePath: input.filePath,
        );
        final payload = E2ePayloadV1(
          senderDeviceId: did,
          createdAtMs: createdAt,
          events: [
            AttachmentEventV1(
              eventId: eventId,
              blobId: blobId,
              fileKeyB64: '',
              blobAccessTokenB64: null,
              sizeBytes: input.sizeBytes,
              mime: input.mime,
              replyToEventId: index == 0 ? replyToPayloadEventId : null,
              mediaGroupId: effectiveGroupId,
              caption: captionForIndex(index),
              filename: input.fileName,
              width: input.width,
              height: input.height,
              thumbB64: input.thumbB64,
              durationMs: input.durationMs,
              musicTitle: input.musicTitle,
              musicArtist: input.musicArtist,
            ),
          ],
        );
        final localCipher = await crypto.encrypt(payload.encode());
        await db.insertEvent(
          eventId: 'local:$eventId',
          convoId: resolvedPeerProfileId,
          type: 'att',
          senderDeviceId: did,
          ciphertextB64: base64Encode(localCipher),
          createdAtMs: createdAt,
          localState: 'sent',
          payloadEventId: eventId,
        );
        eventIds.add(eventId);
      }
      await db.convoTouch(
        convoId: resolvedPeerProfileId,
        atMs: baseNow + validated.length,
      );
      _changed.add(null);
      return eventIds;
    }

    if (relay == null ||
        keys == null ||
        ratchet == null ||
        attachments == null) {
      throw AttachmentFailure(AttachmentFailureCode.transportUnavailable);
    }
    try {
      _throwIfTransportBlocked();
    } catch (error) {
      throw describeAttachmentFailure(
        error,
        fallbackCode: AttachmentFailureCode.transportBlocked,
      );
    }
    final readyForDirectChat = await _ensureDirectConversationReadyForOutgoing(
      resolvedPeerProfileId,
    );
    if (!readyForDirectChat) {
      throw AttachmentFailure(AttachmentFailureCode.contactBlocked);
    }

    final tempDir = await getTemporaryDirectory();
    // Nullable slots — a cancelled album item (per-photo ✕) leaves a null here
    // and is skipped downstream, so cancelling ONE photo never aborts the rest.
    final prepared = <_PreparedAttachmentUpload?>[];
    for (var index = 0; index < validated.length; index++) {
      final token = _cancelTokenAt(cancelTokens, index);
      if (token?.isCanceled == true) {
        prepared.add(null);
        continue;
      }
      try {
        prepared.add(
          await _uploadValidatedAttachmentFile(
            input: validated[index],
            attachments: attachments,
            tempDir: tempDir,
            cancelToken: token,
            onStage: onStage,
            onUploadProgress: (sentBytes, totalBytes) =>
                onUploadProgress?.call(index, sentBytes, totalBytes),
          ),
        );
      } on AttachmentFailure catch (e) {
        // This one item was cancelled mid-upload — drop it, keep the album.
        if (e.code == AttachmentFailureCode.uploadCanceled) {
          prepared.add(null);
          continue;
        }
        rethrow;
      }
    }
    // Everything got cancelled → treat as a full-album cancel.
    if (prepared.every((p) => p == null)) {
      throw AttachmentFailure(AttachmentFailureCode.uploadCanceled);
    }

    await db.convoEnsure1to1(peerProfileId: resolvedPeerProfileId);
    final baseNow = DateTime.now().millisecondsSinceEpoch;
    final eventIds = <String>[];
    final localEventIds = <String>[];
    final payloadBytesByEvent = <String, Uint8List>{};
    final transportMetaByEvent = <String, String?>{};

    for (var index = 0; index < prepared.length; index++) {
      final item = prepared[index];
      if (item == null) continue; // cancelled item — no event for it
      final input = item.input;
      final uploaded = item.uploaded;
      final createdAt = baseNow + index;
      await db.attachmentUpsert(
        blobId: uploaded.blobId,
        fileKeyB64: uploaded.fileKeyB64,
        accessTokenB64: uploaded.blobAccessTokenB64,
        mime: uploaded.mime,
        plaintextSizeBytes: input.sizeBytes,
        ciphertextSizeBytes: uploaded.ciphertextSizeBytes,
        expiresAtMs: uploaded.expiresAtMs,
        createdAtMs: createdAt,
      );
      final eventId = _uuid.v4();
      final payload = E2ePayloadV1(
        senderDeviceId: did,
        createdAtMs: createdAt,
        events: [
          AttachmentEventV1(
            eventId: eventId,
            blobId: uploaded.blobId,
            fileKeyB64: uploaded.fileKeyB64,
            blobAccessTokenB64: uploaded.blobAccessTokenB64,
            sizeBytes: input.sizeBytes,
            mime: uploaded.mime,
            replyToEventId: index == 0 ? replyToPayloadEventId : null,
            mediaGroupId: effectiveGroupId,
            caption: captionForIndex(index),
            filename: input.fileName,
            width: input.width,
            height: input.height,
            thumbB64: input.thumbB64,
            durationMs: input.durationMs,
            musicTitle: input.musicTitle,
            musicArtist: input.musicArtist,
          ),
        ],
      );
      final payloadBytes = Uint8List.fromList(payload.encode());
      final localCipher = await crypto.encrypt(payloadBytes);
      final localEventId = 'local:$eventId';
      final transportMetaJson = _buildChatTransportMetaJson(
        convoId: resolvedPeerProfileId,
        isGroup: false,
        messageKind: 'attachment',
        payloadEventId: eventId,
        createdAtMs: createdAt,
        senderProfileId: pid,
        senderDisplayName: myNickname,
        previewText: _pushTransportPreviewForAttachment(uploaded.mime),
      );
      await db.insertEvent(
        eventId: localEventId,
        convoId: resolvedPeerProfileId,
        type: 'att',
        senderDeviceId: did,
        ciphertextB64: base64Encode(localCipher),
        createdAtMs: createdAt,
        localState: 'pending',
        payloadEventId: eventId,
      );
      eventIds.add(eventId);
      localEventIds.add(localEventId);
      payloadBytesByEvent[localEventId] = payloadBytes;
      transportMetaByEvent[localEventId] = transportMetaJson;
    }
    await db.convoTouch(
      convoId: resolvedPeerProfileId,
      atMs: baseNow + prepared.length,
    );
    _changed.add(null);

    try {
      final targets =
          await _listRecipientDevicesForSend(
            peerProfileId: resolvedPeerProfileId,
            selfDeviceId: did,
          ).timeout(
            const Duration(seconds: 20),
            onTimeout: () =>
                throw AttachmentFailure(AttachmentFailureCode.finalizeTimedOut),
          );
      if (targets.isEmpty) {
        bool exists = false;
        try {
          exists = await keys
              .profileExists(resolvedPeerProfileId)
              .timeout(const Duration(seconds: 12), onTimeout: () => false);
        } catch (_) {}
        if (!exists) {
          throw AttachmentFailure(
            AttachmentFailureCode.recipientProfileNotFound,
          );
        }
        for (final localEventId in localEventIds) {
          final payloadBytes = payloadBytesByEvent[localEventId];
          if (payloadBytes == null) continue;
          await _queuePendingNoDeviceEntry(
            profileId: resolvedPeerProfileId,
            entry: _PendingNoDeviceEntry(
              localEventId: localEventId,
              payloadBytes: payloadBytes,
              transportMetaJson: transportMetaByEvent[localEventId],
              createdAtMs: baseNow,
            ),
          );
        }
        _changed.add(null);
        return eventIds;
      }

      await _flushPendingNoDeviceEntries(
        profileId: resolvedPeerProfileId,
        targets: targets,
        selfDeviceId: did,
        db: db,
        ratchet: ratchet,
        relay: relay,
        nowMs: baseNow,
      );

      {
        final List<String> blocking;
        try {
          blocking = await _sendGateBlockingDevices(
            resolvedPeerProfileId,
            targets,
          );
        } on AttachmentFailure {
          rethrow;
        } catch (error) {
          throw describeAttachmentFailure(
            error,
            fallbackCode: AttachmentFailureCode.serviceUnavailable,
          );
        }
        if (blocking.isNotEmpty) {
          throw AttachmentFailure(AttachmentFailureCode.contactUnverified);
        }
      }

      var queuedTargets = 0;
      for (final localEventId in localEventIds) {
        final payloadBytes = payloadBytesByEvent[localEventId];
        if (payloadBytes == null) continue;
        for (final toDeviceId in targets) {
          try {
            final msgId = _uuid.v4();
            final wire = await _encryptToPeerSerialized(
              ratchet: ratchet,
              selfDeviceId: did,
              peerProfileId: resolvedPeerProfileId,
              peerDeviceId: toDeviceId,
              plaintext: payloadBytes,
            );
            await db.outboxUpsert(
              msgId: msgId,
              toDeviceId: toDeviceId,
              ciphertextB64: base64Encode(wire),
              ttlSeconds: _outboxUserMessageTtlSeconds,
              state: 'pending',
              attemptCount: 0,
              nextRetryAtMs: baseNow,
              createdAtMs: baseNow,
              transportMetaJson: transportMetaByEvent[localEventId],
              eventIdRef: localEventId,
            );
            queuedTargets++;
          } catch (error) {
            callLog(
              'AppCtrl',
              'sendAttachmentFiles fanout skip target=$toDeviceId peer=$resolvedPeerProfileId: $error',
            );
          }
        }
      }
      if (queuedTargets == 0) {
        throw AttachmentFailure(
          AttachmentFailureCode.noDeliverableTargetDevices,
        );
      }
      _changed.add(null);
      _kickRelayOutbox(relay);
      // Multi-device sync: mirror each attachment to my own other devices
      // (TZ §21.1). Best-effort, per-file fire-and-forget. Cancelled items are
      // null in [prepared] and absent from [eventIds], so walk with a separate
      // counter into eventIds to keep them aligned.
      var mirrorEventIdx = 0;
      for (var index = 0; index < prepared.length; index++) {
        final item = prepared[index];
        if (item == null) continue; // cancelled item — nothing to mirror
        final msgEventId = eventIds[mirrorEventIdx];
        mirrorEventIdx++;
        unawaited(
          _mirrorAttachmentToOwnDevices(
            convoId: resolvedPeerProfileId,
            msgEventId: msgEventId,
            blobId: item.uploaded.blobId,
            fileKeyB64: item.uploaded.fileKeyB64,
            sizeBytes: item.input.sizeBytes,
            createdAtMs: baseNow + index,
            blobAccessTokenB64: item.uploaded.blobAccessTokenB64,
            mime: item.uploaded.mime,
            replyToPayloadEventId: index == 0 ? replyToPayloadEventId : null,
            mediaGroupId: effectiveGroupId,
            caption: captionForIndex(index),
            filename: item.input.fileName,
            durationMs: item.input.durationMs,
            musicTitle: item.input.musicTitle,
            musicArtist: item.input.musicArtist,
          ),
        );
      }
      return eventIds;
    } catch (error) {
      for (final localEventId in localEventIds) {
        final queued = await db.outboxCountForEventRef(localEventId);
        if (queued == 0) {
          await db.updateEventLocalState(
            eventId: localEventId,
            localState: 'failed',
          );
        }
      }
      _changed.add(null);
      rethrow;
    }
  }

  Future<List<String>> sendGroupAttachmentFiles({
    required String groupId,
    required List<AttachmentFileSendRequest> files,
    String? replyToPayloadEventId,
    String? mediaGroupId,
    void Function(String stage)? onStage,
    void Function(int index, int sentBytes, int totalBytes)? onUploadProgress,
    List<BlobUploadCancelToken>? cancelTokens,
    String? caption,
    // Тема комнаты — как у одиночной отправки ([sendGroupAttachmentFile]):
    // альбом телефона и пачка компьютера уходят в открытую тему.
    String? topicId,
  }) async {
    final normalizedTopicId = (topicId ?? '').trim().isEmpty
        ? null
        : topicId!.trim();
    final validated = await _validateAttachmentFileRequests(files);
    // Album caption is attached to the FIRST item only (Telegram-style).
    String? captionForIndex(int index) {
      if (index != 0) return null;
      final perRequest = validated[index].caption;
      if (perRequest != null && perRequest.isNotEmpty) return perRequest;
      final trimmed = caption?.trim();
      return (trimmed == null || trimmed.isEmpty) ? null : trimmed;
    }

    final db = _db;
    final did = _deviceId;
    final pid = _profileId;
    final crypto = _crypto;
    final attachments = _attachments;
    if (db == null ||
        did == null ||
        pid == null ||
        crypto == null ||
        attachments == null) {
      throw AttachmentFailure(AttachmentFailureCode.localUnavailable);
    }
    await _ensureRoomActionAllowed(groupId, RoomAction.sendMedia);
    try {
      _throwIfTransportBlocked();
    } catch (error) {
      throw describeAttachmentFailure(
        error,
        fallbackCode: AttachmentFailureCode.transportBlocked,
      );
    }

    final group = await db.convoGet(groupId);
    final groupTitle = ((group?['title'] as String?) ?? 'Group').trim();
    await db.convoEnsureGroup(
      groupId: groupId,
      title: groupTitle.isEmpty ? 'Group' : groupTitle,
    );

    final effectiveGroupId =
        (mediaGroupId != null && mediaGroupId.trim().isNotEmpty)
        ? mediaGroupId.trim()
        : validated.length > 1
        ? _uuid.v4()
        : null;

    final tempDir = await getTemporaryDirectory();
    // Nullable slots — a cancelled album item (per-photo ✕) leaves a null and is
    // skipped downstream, so cancelling ONE photo never aborts the rest.
    final prepared = <_PreparedAttachmentUpload?>[];
    for (var index = 0; index < validated.length; index++) {
      final token = _cancelTokenAt(cancelTokens, index);
      if (token?.isCanceled == true) {
        prepared.add(null);
        continue;
      }
      try {
        prepared.add(
          await _uploadValidatedAttachmentFile(
            input: validated[index],
            attachments: attachments,
            tempDir: tempDir,
            cancelToken: token,
            onStage: onStage,
            onUploadProgress: (sentBytes, totalBytes) =>
                onUploadProgress?.call(index, sentBytes, totalBytes),
          ),
        );
      } on AttachmentFailure catch (e) {
        if (e.code == AttachmentFailureCode.uploadCanceled) {
          prepared.add(null);
          continue;
        }
        rethrow;
      }
    }
    if (prepared.every((p) => p == null)) {
      throw AttachmentFailure(AttachmentFailureCode.uploadCanceled);
    }

    var members = await listGroupMembers(groupId);
    var recipients = members
        .where((m) => m.isNotEmpty && m != pid)
        .toList(growable: false);
    if (recipients.isEmpty && members.isEmpty) {
      await _tryRefreshRoomFromRelayBestEffort(groupId);
      members = await listGroupMembers(groupId);
      recipients = members
          .where((m) => m.isNotEmpty && m != pid)
          .toList(growable: false);
    }
    if (recipients.isEmpty) {
      callLog(
        'AppCtrl',
        'sendGroupAttachments solo-room: no recipients to fan out (group=$groupId members=${members.length})',
      );
    }
    final baseNow = DateTime.now().millisecondsSinceEpoch;
    final sends = <_PreparedGroupAttachmentSend>[];

    for (var index = 0; index < prepared.length; index++) {
      final item = prepared[index];
      if (item == null) continue; // cancelled item — no event for it
      final input = item.input;
      final uploaded = item.uploaded;
      final messageId = _uuid.v4();
      RelayRoomMessageAdmissionResult? admission;
      if (_useAuthoritativeRoomRelay) {
        admission = await _admitAuthoritativeRoomMessage(
          groupId: groupId,
          messageId: messageId,
          kind: 'media',
        );
      } else {
        _throwIfRoomMutationAuthoritativeRelayUnavailable();
      }
      final createdAt = admission?.admittedAtMs ?? (baseNow + index);
      await db.attachmentUpsert(
        blobId: uploaded.blobId,
        fileKeyB64: uploaded.fileKeyB64,
        accessTokenB64: uploaded.blobAccessTokenB64,
        mime: uploaded.mime,
        plaintextSizeBytes: input.sizeBytes,
        ciphertextSizeBytes: uploaded.ciphertextSizeBytes,
        expiresAtMs: uploaded.expiresAtMs,
        createdAtMs: createdAt,
      );
      final payload = E2ePayloadV1(
        senderDeviceId: did,
        createdAtMs: createdAt,
        events: [
          AttachmentEventV1(
            eventId: messageId,
            blobId: uploaded.blobId,
            fileKeyB64: uploaded.fileKeyB64,
            blobAccessTokenB64: uploaded.blobAccessTokenB64,
            sizeBytes: input.sizeBytes,
            mime: uploaded.mime,
            replyToEventId: index == 0 ? replyToPayloadEventId : null,
            mediaGroupId: effectiveGroupId,
            topicId: normalizedTopicId,
            caption: captionForIndex(index),
            filename: input.fileName,
            width: input.width,
            height: input.height,
            thumbB64: input.thumbB64,
            durationMs: input.durationMs,
            musicTitle: input.musicTitle,
            musicArtist: input.musicArtist,
          ),
        ],
      );
      final localCipher = await crypto.encrypt(payload.encode());
      final localEventId = 'local:grpatt:$messageId';
      final transportMetaJson = _buildChatTransportMetaJson(
        convoId: groupId,
        isGroup: true,
        messageKind: 'attachment',
        payloadEventId: messageId,
        createdAtMs: createdAt,
        senderProfileId: pid,
        senderDisplayName: myNickname,
        convoTitle: groupTitle,
        previewText: _pushTransportPreviewForAttachment(uploaded.mime),
      );
      await db.insertEvent(
        eventId: localEventId,
        convoId: groupId,
        type: 'att',
        senderDeviceId: did,
        ciphertextB64: base64Encode(localCipher),
        createdAtMs: createdAt,
        localState: 'pending',
        payloadEventId: messageId,
      );
      sends.add(
        _PreparedGroupAttachmentSend(
          messageId: messageId,
          localEventId: localEventId,
          transportMetaJson: transportMetaJson,
          envelope: <String, Object?>{
            'v': 1,
            'kind': 'attachment',
            'groupId': groupId,
            'groupTitle': groupTitle,
            'msgEventId': messageId,
            'blobId': uploaded.blobId,
            'fileKeyB64': uploaded.fileKeyB64,
            'blobAccessTokenB64': uploaded.blobAccessTokenB64,
            'sizeBytes': input.sizeBytes,
            'mime': uploaded.mime,
            'replyToPayloadEventId': index == 0 ? replyToPayloadEventId : null,
            'mediaGroupId': effectiveGroupId,
            if (captionForIndex(index) != null)
              'caption': captionForIndex(index),
            'filename': input.fileName,
            // Sender-stamped image dims → recipient reserves the exact bubble
            // height (zero reflow). Absent for older senders / non-images.
            if (input.width != null) 'width': input.width,
            if (input.height != null) 'height': input.height,
            if (input.thumbB64 != null) 'thumb_b64': input.thumbB64,
            if (input.durationMs != null) 'durationMs': input.durationMs,
            if (input.musicTitle != null) 'musicTitle': input.musicTitle,
            if (input.musicArtist != null) 'musicArtist': input.musicArtist,
            if (normalizedTopicId != null) 'topicId': normalizedTopicId,
            'createdAtMs': createdAt,
            'memberProfileIds': members,
            'senderProfileId': pid,
            'senderName': myNickname.trim().isEmpty ? null : myNickname.trim(),
            'senderAvatarPath': _myAvatarPath,
          },
        ),
      );
    }

    await db.convoTouch(convoId: groupId, atMs: baseNow + prepared.length);
    _changed.add(null);

    var anyDelivered = false;
    for (final send in sends) {
      final controlText =
          '$_groupMsgCmdPrefix${base64Url.encode(utf8.encode(jsonEncode(send.envelope)))}';
      // ROOM SENDER KEY (фаза 3б): sealed per media item, since each one is its
      // own message with its own position on the chain.
      final roomWireEvents = await _sealRoomMessageForSenderKey(
        db: db,
        roomId: groupId,
        controlText: controlText,
        // This loop is past the per-item scope where `createdAt` lived; the
        // value only feeds rotation-age checks, so "now" is the honest answer.
        createdAtMs: DateTime.now().millisecondsSinceEpoch,
        memberProfileIds: recipients,
      );
      var perSendDelivered = 0;
      // К-3: конверт — для повтора тому, у кого пропуск.
      await _rememberRoomEnvelope(db: db, roomId: groupId, controlText: controlText);
      // К-2: один запрос к реле для тех, кто умеет сырой провод.
      final rawRemaining = await _roomRawBroadcast(
        db: db,
        roomId: groupId,
        events: roomWireEvents,
        recipients: recipients,
        transportMetaJson: send.transportMetaJson,
        localEventId: send.localEventId,
      );
      for (final member in recipients) {
        final rawTargets = rawRemaining?[member];
        if (rawTargets != null && rawTargets.isEmpty) {
          perSendDelivered++;
          continue;
        }
        try {
          await sendControlMessage(
            peerProfileId: member,
            controlText: controlText,
            overrideEvents: roomWireEvents,
            targetDeviceIds: rawTargets,
            transportMetaJson: send.transportMetaJson,
            eventIdRef: send.localEventId,
            strict: true,
            queueIfNoDevices: true,
          );
          perSendDelivered++;
        } catch (e) {
          callLog(
            'AppCtrl',
            'sendGroupAttachments fanout member=$member group=$groupId msg=${send.messageId} failed: $e',
          );
        }
      }
      if (perSendDelivered > 0) {
        anyDelivered = true;
      }
    }
    if (recipients.isNotEmpty && !anyDelivered) {
      throw RoomPolicyFailure(RoomPolicyFailureCode.allRecipientsUnavailable);
    }

    _changed.add(null);
    return sends.map((send) => send.messageId).toList(growable: false);
  }

  Future<void> ensureDemoChat() async {
    if (!_demoDataEnabled) return;
    await _seedDemoChat();
    _changed.add(null);
  }

  Future<void> markChatRead({required String peerProfileId}) async {
    final db = _db;
    final did = _deviceId;
    if (db == null || did == null) {
      return;
    }

    final isGroupConvo = peerProfileId.startsWith('group:');
    var effectivePeerProfileId = peerProfileId;
    if (!isGroupConvo && effectivePeerProfileId.startsWith('dev:')) {
      final resolved = await _resolvePeerProfileId(effectivePeerProfileId);
      if (resolved == null || resolved.isEmpty || resolved.startsWith('dev:')) {
        final unreadLocal = await db.listUnreadIncomingForConvo(
          convoId: effectivePeerProfileId,
          selfDeviceId: did,
          excludedSenderDeviceIds: _ownDeviceIdsForUnreadQueries(),
          limit: 500,
        );
        if (unreadLocal.isNotEmpty) {
          final nowLocal = DateTime.now().millisecondsSinceEpoch;
          final ids = unreadLocal
              .map((r) => r['event_id'] as String)
              .toList(growable: false);
          await db.markEventsReadByIds(ids, readAtMs: nowLocal);
          try {
            await _nativeMsgNotifChannel.invokeMethod(
              'cancel',
              <String, dynamic>{'convoId': effectivePeerProfileId},
            );
          } catch (_) {}
          _changed.add(null);
        }
        return;
      }
      effectivePeerProfileId = resolved;
    }
    final isDemoConvo = _isDemoConvoId(effectivePeerProfileId);

    // Only for real 1:1 contacts (not requests/demo).
    if (!isGroupConvo &&
        (effectivePeerProfileId.startsWith('req:') || isDemoConvo)) {
      return;
    }
    final myPid = (_profileId ?? '').trim();
    final skipReadReceiptSend =
        isDemoConvo ||
        !isGroupConvo && myPid.isNotEmpty && effectivePeerProfileId == myPid;
    final unread = await db.listUnreadIncomingForConvo(
      convoId: effectivePeerProfileId,
      selfDeviceId: did,
      excludedSenderDeviceIds: _ownDeviceIdsForUnreadQueries(),
      limit: 500,
    );
    if (unread.isEmpty) return;

    final now = DateTime.now().millisecondsSinceEpoch;
    final eventIds = <String>[];
    // Highest SENDER timestamp among the rows being marked. This is what the
    // user's other devices are told, so it must come from the events, never
    // from this device's clock.
    var readUpToMs = 0;

    for (final r in unread) {
      // Always collect for local marking — even events without payloadEventId
      // must be cleared so they don't stay "unread" forever.
      final eventId = ((r['event_id'] as String?) ?? '').trim();
      if (eventId.isNotEmpty) {
        eventIds.add(eventId);
      }
      final createdAtMs = ((r['created_at_ms'] as num?) ?? 0).toInt();
      if (createdAtMs > readUpToMs) readUpToMs = createdAtMs;
    }
    if (eventIds.isEmpty) return;

    final pendingReceiptIntents = <_PendingReceiptIntent>[];
    if (!skipReadReceiptSend) {
      if (isGroupConvo) {
        final senderProfileIdByDeviceId = <String, String?>{};
        for (final row in unread) {
          final senderDeviceId = ((row['sender_device_id'] as String?) ?? '')
              .trim();
          if (senderDeviceId.isEmpty ||
              isOwnDeviceId(senderDeviceId) ||
              senderProfileIdByDeviceId.containsKey(senderDeviceId)) {
            continue;
          }
          senderProfileIdByDeviceId[senderDeviceId] =
              await _resolveProfileIdForDevice(senderDeviceId);
        }
        for (final row in unread) {
          final senderDeviceId = ((row['sender_device_id'] as String?) ?? '')
              .trim();
          final payloadEventId = ((row['payload_event_id'] as String?) ?? '')
              .trim();
          if (senderDeviceId.isEmpty ||
              isOwnDeviceId(senderDeviceId) ||
              payloadEventId.isEmpty) {
            continue;
          }
          pendingReceiptIntents.add((
            peerDeviceId: senderDeviceId,
            peerProfileId: senderProfileIdByDeviceId[senderDeviceId],
            payloadEventId: payloadEventId,
            convoId: effectivePeerProfileId,
            status: MessageReceiptState.read,
          ));
        }
      } else {
        for (final row in unread) {
          final senderDeviceId = ((row['sender_device_id'] as String?) ?? '')
              .trim();
          final payloadEventId = ((row['payload_event_id'] as String?) ?? '')
              .trim();
          if (senderDeviceId.isEmpty ||
              isOwnDeviceId(senderDeviceId) ||
              payloadEventId.isEmpty) {
            continue;
          }
          pendingReceiptIntents.add((
            peerDeviceId: senderDeviceId,
            peerProfileId: effectivePeerProfileId,
            payloadEventId: payloadEventId,
            convoId: effectivePeerProfileId,
            status: MessageReceiptState.read,
          ));
        }
      }
    }

    if (pendingReceiptIntents.isNotEmpty) {
      await _persistPendingReceiptIntents(
        intents: pendingReceiptIntents,
        nowMs: now,
      );
      await _flushPendingReceiptsBestEffort();
    }

    await db.markEventsReadByIds(eventIds, readAtMs: now);
    final relay = _relay;
    if (!_transportBlocked) {
      _kickRelayOutbox(relay);
    }
    try {
      await _nativeMsgNotifChannel.invokeMethod('cancel', <String, dynamic>{
        'convoId': effectivePeerProfileId,
      });
      DiagLog.event('notif', 'cancel_request', {
        'convo': DiagLog.pfx(effectivePeerProfileId),
        'reason': 'mark_read',
      });
    } catch (_) {}
    DiagLog.event('read', 'mark_chat_read', {
      'convo': DiagLog.pfx(effectivePeerProfileId),
      'group': isGroupConvo,
      'unread_count': eventIds.length,
      'receipts_queued': pendingReceiptIntents.length,
    });
    // Tell the user's OTHER devices. Without this the unread badge is a
    // per-device fact: reading on the phone left the desktop counting the same
    // messages forever. Best-effort by construction — a failure here must not
    // undo a read the user has already performed.
    unawaited(
      _mirrorReadWatermarkToOwnDevices(
        convoId: effectivePeerProfileId,
        readUpToMs: readUpToMs,
      ),
    );
    _changed.add(null);
  }

  /// Announces "everything in [convoId] up to [readUpToMs] is read" to the
  /// user's other devices.
  ///
  /// Terminal, exactly like [_mirrorReceiptsToOwnDevices]: a device that
  /// receives this applies it locally and never re-broadcasts, so two paired
  /// devices cannot ping-pong watermarks at each other.
  ///
  /// [readUpToMs] is a SENDER timestamp taken from the events themselves, not
  /// this device's clock — the receiving device compares it against the same
  /// field on its own copies of those events, so clock skew between devices
  /// cannot mark the wrong messages.
  Future<void> _mirrorReadWatermarkToOwnDevices({
    required String convoId,
    required int readUpToMs,
  }) async {
    if (readUpToMs <= 0) return;

    final command = buildSelfMirrorReadCommand(
      convoId: convoId,
      readUpToMs: readUpToMs,
      appliedAtMs: DateTime.now().millisecondsSinceEpoch,
    );
    try {
      final targets = await _sendSelfMirrorControl(command);
      if (targets > 0) {
        DiagLog.event('selfsync', 'read_mirror_sent', {
          'convo': DiagLog.pfx(convoId),
          'up_to_ms': readUpToMs,
          'targets': targets,
        });
      }
    } catch (e) {
      DiagLog.event('selfsync', 'read_mirror_failed', {
        'convo': DiagLog.pfx(convoId),
        'err': _shortErrorTag(e),
      });
    }
  }

  /// Sends [controlText] to every OTHER device of this account.
  ///
  /// The seven older mirrors each inline this block; the two added in
  /// September share it instead, so a fix to the fan-out lands once. Returns
  /// the number of devices addressed — 0 means there was nobody to tell, which
  /// is not a failure.
  Future<int> _sendSelfMirrorControl(String controlText) async {
    if (_backgroundInboundMode) return 0; // outbound fan-out; foreground mirrors
    final pid = (_profileId ?? '').trim();
    final did = (_deviceId ?? '').trim();
    if (pid.isEmpty || pid.startsWith('LOCAL-') || did.isEmpty) return 0;

    var ownTargets = <String>[];
    try {
      ownTargets = await _listRecipientDevicesForSend(
        peerProfileId: pid,
        selfDeviceId: did,
      );
    } catch (_) {
      return 0;
    }
    if (ownTargets.isEmpty) return 0;

    await sendControlMessage(
      peerProfileId: pid,
      controlText: controlText,
      strict: false,
      forceRelayFlush: false,
      targetDeviceIds: ownTargets,
    );
    return ownTargets.length;
  }

  /// Mirrors a per-conversation state change (mute / pin / archive / personal /
  /// disappearing timer) to the user's other devices.
  ///
  /// A PATCH: only the fields the caller actually changed travel, so a mirror
  /// can never overwrite a property the sending screen knew nothing about.
  ///
  /// Conflict handling is last-received-wins, deliberately. These are
  /// low-frequency toggles a person flips by hand; two devices racing on the
  /// same flag within one delivery round-trip is not a case worth a vector
  /// clock, and the cost of getting it wrong is a mute that has to be flipped
  /// again — not lost data.
  Future<void> _mirrorConvoStateToOwnDevices({
    required String convoId,
    bool? muted,
    bool? pinned,
    bool? archived,
    bool? personal,
    bool autoDeleteSet = false,
    int? autoDeleteSeconds,
  }) async {
    final id = convoId.trim();
    if (id.isEmpty) return;
    final command = buildSelfMirrorConvoStateCommand(
      convoId: id,
      appliedAtMs: DateTime.now().millisecondsSinceEpoch,
      muted: muted,
      pinned: pinned,
      archived: archived,
      personal: personal,
      autoDeleteSet: autoDeleteSet,
      autoDeleteSeconds: autoDeleteSeconds,
    );
    try {
      final targets = await _sendSelfMirrorControl(command);
      if (targets > 0) {
        DiagLog.event('selfsync', 'convo_state_mirror_sent', {
          'convo': DiagLog.pfx(id),
          'targets': targets,
        });
      }
    } catch (e) {
      DiagLog.event('selfsync', 'convo_state_mirror_failed', {
        'convo': DiagLog.pfx(id),
        'err': _shortErrorTag(e),
      });
    }
  }

  /// Applies a conversation-state patch from one of the user's own devices.
  ///
  /// Writes through the same storage the setters use, but deliberately does
  /// NOT call those setters — they would mirror again, and two paired devices
  /// would trade the same patch forever. Terminal, like every other mirror.
  Future<void> _applySelfMirrorConvoState(
    SelfMirrorConvoStateCommand cmd,
  ) async {
    final db = _db;
    if (db == null) return;
    final convoId = cmd.convoId;
    var touchedMute = false;

    final muted = cmd.muted;
    if (muted != null) {
      await db.convoSetMuted(convoId: convoId, muted: muted);
      touchedMute = true;
    }
    final pinned = cmd.pinned;
    if (pinned != null) {
      await db.convoSetPinned(convoId: convoId, pinned: pinned);
    }
    final archived = cmd.archived;
    if (archived != null) {
      await db.convoSetArchived(convoId: convoId, archived: archived);
    }
    final personal = cmd.personal;
    if (personal != null) {
      // Personal lives in prefs, not the database — mirror the setter's own
      // bookkeeping rather than inventing a second source of truth.
      final prefs = _prefs ?? await SharedPreferences.getInstance();
      _prefs = prefs;
      if (personal) {
        _personalConvoIds.add(convoId);
      } else {
        _personalConvoIds.remove(convoId);
      }
      await prefs.setStringList(
        _prefsPersonalConvoIdsKey,
        _personalConvoIds.toList(growable: false),
      );
    }
    if (cmd.autoDeleteSet) {
      await db.convoSetAutoDeleteSeconds(
        convoId: convoId,
        autoDeleteSeconds: cmd.autoDeleteSeconds,
      );
      // The timer is retention, not decoration: apply it to what is already
      // stored, exactly as the setter does.
      await _applyAutoDeleteRetentionForConvo(convoId);
    }

    if (touchedMute) refreshPushNotificationPolicy();
    DiagLog.event('selfsync', 'convo_state_applied', {
      'convo': DiagLog.pfx(convoId),
      'muted': cmd.muted,
      'pinned': cmd.pinned,
      'archived': cmd.archived,
      'personal': cmd.personal,
      'auto_delete_set': cmd.autoDeleteSet,
    });
    if (!_changed.isClosed) _changed.add(null);
  }

  int _lastBlockedReconcileAtMs = 0;
  bool _blockedReconcileInFlight = false;

  /// Pulls the account's blocked list from the relay and makes the local copy
  /// match it.
  ///
  /// **Why a pull and not a mirror.** Blocks are already server state: every
  /// `setProfileBlocked` writes them to the relay, which enforces them, and
  /// `/v1/blocks/{device_id}` resolves the device to its OWNER PROFILE and
  /// returns that profile's blocks — so a block made on the phone is visible to
  /// the desktop by construction. What was missing was anyone asking. A pull
  /// also heals a device that was simply offline when the block happened, which
  /// a broadcast mirror never can.
  ///
  /// The server is the authority here, deliberately: it is what actually
  /// enforces a block, so a local list that disagrees with it is the one that
  /// is wrong. `setProfileBlocked` throws when its relay write fails, so the
  /// local copy is never ahead of the server on purpose.
  ///
  /// Best-effort and throttled; never throws at the caller.
  Future<void> reconcileBlockedProfilesFromServer({bool force = false}) async {
    if (_blockedReconcileInFlight) return;
    final db = _db;
    final relay = _relay;
    if (db == null || relay == null || _transportBlocked) return;
    final nowMs = DateTime.now().millisecondsSinceEpoch;
    if (!force && nowMs - _lastBlockedReconcileAtMs < _kBlockedReconcileMinIntervalMs) {
      return;
    }
    _blockedReconcileInFlight = true;
    _lastBlockedReconcileAtMs = nowMs;
    try {
      final List<String> serverList;
      try {
        serverList = await relay.listBlockedProfiles();
      } catch (_) {
        return; // offline or refused — try again next cycle
      }
      final server = serverList
          .map((id) => id.trim())
          .where((id) => id.isNotEmpty)
          .toSet();
      final localRows = await db.blockedProfilesList(limit: 2000);
      final local = localRows
          .map((r) => ((r['blocked_profile_id'] as String?) ?? '').trim())
          .where((id) => id.isNotEmpty)
          .toSet();

      final toBlock = server.difference(local);
      final toUnblock = local.difference(server);
      if (toBlock.isEmpty && toUnblock.isEmpty) return;

      for (final profileId in toBlock) {
        await db.blockedProfileSet(profileId: profileId, blocked: true);
        await db.requestUpsert(profileId: profileId, status: 'blocked');
      }
      for (final profileId in toUnblock) {
        await db.blockedProfileSet(profileId: profileId, blocked: false);
        // Mirror the setter: a request row that exists only to carry the block
        // goes with it, anything else the user set is left alone.
        final status = await db.requestStatus(profileId);
        if (status == 'blocked') {
          await db.requestDelete(profileId);
        }
      }
      DiagLog.event('selfsync', 'blocked_reconciled', {
        'added': toBlock.length,
        'removed': toUnblock.length,
        'server_total': server.length,
      });
      if (!_changed.isClosed) _changed.add(null);
    } finally {
      _blockedReconcileInFlight = false;
    }
  }

  int _lastOwnMetaPullAtMs = 0;
  bool _ownMetaPullInFlight = false;

  /// Pulls THIS account's own nickname and bio back from the keys server.
  ///
  /// **Why it was missing.** Every device publishes its own meta with
  /// `keys.setProfileMeta`, so the server holds the truth — but the periodic
  /// meta refresh walks contacts, requests and conversations only. The user's
  /// own profile id is not in that list, so a rename on the phone reached
  /// every contact and never reached the user's own desktop, where the name
  /// stayed whatever the pairing snapshot said.
  ///
  /// **Why it cannot revert a rename.** A pull is skipped unless everything
  /// this device changed has already been published successfully
  /// ([_myProfileMetaDirtyAtMs] <= [_myProfileMetaPublishOkAtMs]) and no
  /// publish is pending or in flight. Otherwise the server would still be
  /// holding the old value and the pull would undo what the user just typed —
  /// the one failure that would be worse than the drift being fixed.
  ///
  /// Best-effort and throttled; never throws at the caller.
  Future<void> refreshOwnProfileMetaFromServer({bool force = false}) async {
    if (_ownMetaPullInFlight) return;
    if (_transportBlocked) return;
    if (_myProfileMetaPublishInFlight || _myProfileMetaPublishRequested) return;
    // Local edits that have not reached the server yet outrank it.
    if (_myProfileMetaDirtyAtMs > _myProfileMetaPublishOkAtMs) return;

    final keys = _keys;
    final pid = (_profileId ?? '').trim();
    if (keys == null || pid.isEmpty || pid.startsWith('LOCAL-')) return;
    final nowMs = DateTime.now().millisecondsSinceEpoch;
    if (!force && nowMs - _lastOwnMetaPullAtMs < _kOwnMetaPullMinIntervalMs) {
      return;
    }
    _ownMetaPullInFlight = true;
    _lastOwnMetaPullAtMs = nowMs;
    try {
      final auth = await _buildKeysAuthEnvelope(
        buildMessage:
            ({required requesterDeviceId, required tsMs, required nonceB64}) =>
                AuthSigner.keysProfileMetaGetMessage(
                  requesterDeviceId: requesterDeviceId,
                  profileId: pid,
                  tsMs: tsMs,
                  nonceB64: nonceB64,
                ),
      );
      final meta = await keys.getProfileMeta(
        pid,
        requesterDeviceId: auth?.requesterDeviceId,
        tsMs: auth?.tsMs,
        nonceB64: auth?.nonceB64,
        signatureB64: auth?.signatureB64,
      );
      if (!meta.exists) return;

      // Re-check the guard: the publish flags can have flipped while the
      // request was in the air, and a value fetched before the user's edge is
      // exactly as stale as one fetched before the request.
      if (_myProfileMetaPublishInFlight ||
          _myProfileMetaPublishRequested ||
          _myProfileMetaDirtyAtMs > _myProfileMetaPublishOkAtMs) {
        return;
      }

      final serverNick = (meta.nickname ?? '').trim();
      final serverBio = _sanitizeProfileBio(meta.bio ?? '');
      final prefs = _prefs ?? await SharedPreferences.getInstance();
      _prefs = prefs;

      // An empty server value is "not set", not "cleared": treating it as a
      // clear would wipe a nickname whenever the publish had not landed yet.
      final nickChanged = serverNick.isNotEmpty && serverNick != _myNickname;
      final bioChanged = serverBio.isNotEmpty && serverBio != _myBio;
      if (nickChanged) {
        _myNickname = serverNick;
        await prefs.setString(_prefsMyNicknameKey, serverNick);
      }
      if (bioChanged) {
        _myBio = serverBio;
        await prefs.setString(_prefsMyBioKey, serverBio);
      }
      if (!nickChanged && !bioChanged) return;
      DiagLog.event('selfsync', 'own_meta_pulled', {
        'nick_changed': nickChanged,
        'bio_changed': bioChanged,
      });
      if (!_changed.isClosed) _changed.add(null);
    } catch (_) {
      // offline, refused, or malformed — the next cycle tries again
    } finally {
      _ownMetaPullInFlight = false;
    }
  }

  /// Mirrors a chat-folder change to the user's other devices.
  ///
  /// Sends the WHOLE folder, not a delta: a folder is its membership, and
  /// "chat X joined folder F" is meaningless to a device that never heard of
  /// F. Folders have no server copy — unlike the nickname or the blocked list,
  /// there is nothing to fall back on, so the mirror is the only channel.
  Future<void> _mirrorFolderToOwnDevices({
    required String folderId,
    bool deleted = false,
    String name = '',
    String? emoji,
    int position = 0,
    List<String> convoIds = const <String>[],
  }) async {
    final id = folderId.trim();
    if (id.isEmpty) return;
    final command = buildSelfMirrorFolderCommand(
      folderId: id,
      appliedAtMs: DateTime.now().millisecondsSinceEpoch,
      deleted: deleted,
      name: name,
      emoji: emoji,
      position: position,
      convoIds: convoIds,
    );
    try {
      final targets = await _sendSelfMirrorControl(command);
      if (targets > 0) {
        DiagLog.event('selfsync', 'folder_mirror_sent', {
          'folder': DiagLog.pfx(id),
          'deleted': deleted,
          'members': convoIds.length,
          'targets': targets,
        });
      }
    } catch (e) {
      DiagLog.event('selfsync', 'folder_mirror_failed', {
        'folder': DiagLog.pfx(id),
        'err': _shortErrorTag(e),
      });
    }
  }

  /// Applies a chat-folder change from one of the user's own devices.
  ///
  /// Writes through the database directly and refreshes the cached list —
  /// never through [createChatFolder] / [deleteChatFolder], which would mirror
  /// straight back. Terminal, like every other mirror.
  Future<void> _applySelfMirrorFolder(SelfMirrorFolderCommand cmd) async {
    final db = _db;
    if (db == null) return;
    if (cmd.deleted) {
      await db.folderDelete(cmd.folderId);
    } else {
      await db.folderUpsert(
        id: cmd.folderId,
        name: cmd.name,
        emoji: cmd.emoji,
        position: cmd.position,
      );
      await db.folderSetMembers(
        folderId: cmd.folderId,
        convoIds: cmd.convoIds,
      );
    }
    await _refreshCustomChatFolders();
    DiagLog.event('selfsync', 'folder_applied', {
      'folder': DiagLog.pfx(cmd.folderId),
      'deleted': cmd.deleted,
      'members': cmd.convoIds.length,
    });
    if (!_changed.isClosed) _changed.add(null);
  }

  /// Applies a read watermark that arrived from one of the user's own devices.
  ///
  /// Marks every still-unread incoming event in the conversation whose sender
  /// timestamp is at or before the watermark. Idempotent: re-applying the same
  /// watermark finds nothing left to mark.
  Future<void> _applySelfMirrorReadWatermark(SelfMirrorReadCommand cmd) async {
    final db = _db;
    final did = (_deviceId ?? '').trim();
    if (db == null || did.isEmpty) return;

    List<Map<String, Object?>> unread;
    try {
      unread = await db.listUnreadIncomingForConvo(
        convoId: cmd.convoId,
        selfDeviceId: did,
        excludedSenderDeviceIds: _ownDeviceIdsForUnreadQueries(),
        limit: 500,
      );
    } catch (_) {
      return;
    }
    if (unread.isEmpty) return;

    final ids = <String>[];
    for (final row in unread) {
      final createdAtMs = ((row['created_at_ms'] as num?) ?? 0).toInt();
      if (createdAtMs <= 0 || createdAtMs > cmd.readUpToMs) continue;
      final eventId = ((row['event_id'] as String?) ?? '').trim();
      if (eventId.isNotEmpty) ids.add(eventId);
    }
    if (ids.isEmpty) return;

    await db.markEventsReadByIds(
      ids,
      readAtMs: cmd.appliedAtMs > 0
          ? cmd.appliedAtMs
          : DateTime.now().millisecondsSinceEpoch,
    );
    // The badge is gone; so should be the banner that announced it.
    try {
      await _nativeMsgNotifChannel.invokeMethod('cancel', <String, dynamic>{
        'convoId': cmd.convoId,
      });
    } catch (_) {}
    DiagLog.event('selfsync', 'read_mirror_applied', {
      'convo': DiagLog.pfx(cmd.convoId),
      'marked': ids.length,
      'up_to_ms': cmd.readUpToMs,
    });
    if (!_changed.isClosed) _changed.add(null);
  }

  bool _isDemoConvoId(String convoId) {
    final id = convoId.trim();
    if (id.isEmpty) return false;
    return id == demoProfileId ||
        id.startsWith('demo:') ||
        id.startsWith('group:demo:');
  }

  /// Removes any demo chats/contacts left over in the local store when this
  /// build does NOT ship demo data. Idempotent and cheap once clean: it only
  /// runs the deep contact scan while demo rows are present or the one-time
  /// sweep flag is unset. Guards against a tester seeing seeded "strangers"
  /// carried over from an old demo-enabled build or a restored backup.
  Future<void> _purgeResidualDemoDataIfDisabled(SharedPreferences prefs) async {
    if (_demoDataEnabled) return;
    final db = _db;
    if (db == null) return;
    final alreadyPurged = prefs.getBool(_prefsDemoPurgedKey) ?? false;
    try {
      final allConvos = await db.convoList(limit: 1000);
      final demoConvoIds = allConvos
          .map((row) => ((row['convo_id'] as String?) ?? '').trim())
          .where(_isDemoConvoId)
          .toSet();
      // Fast path: store is already clean and the deep sweep ran once before.
      if (demoConvoIds.isEmpty && alreadyPurged) return;

      var removed = false;
      for (final convoId in demoConvoIds) {
        await db.deleteConversationData(
          convoId: convoId,
          keepConversationRow: false,
        );
        removed = true;
      }
      final contacts = await db.contactsList(limit: 1000);
      for (final row in contacts) {
        final profileId = ((row['contact_profile_id'] as String?) ?? '').trim();
        if (!profileId.startsWith('demo:')) continue;
        await db.contactDelete(profileId);
        removed = true;
      }
      // Reset seed bookkeeping so a later opt-in demo build re-seeds cleanly.
      await prefs.remove(_prefsDemoSeededKey);
      await prefs.remove(_prefsDemoSeedVersionKey);
      await prefs.setBool(_prefsDemoPurgedKey, true);
      if (removed) {
        _debugRuntimeLog('Purged residual demo data (disabled in this build).');
        _changed.add(null);
      }
    } catch (_) {
      // best-effort cleanup; never block startup on it
    }
  }

  String _demoSenderDeviceForProfile(String profileId) {
    final safe = profileId.replaceAll(RegExp(r'[^a-zA-Z0-9]+'), '_');
    return '${demoDeviceId}_$safe';
