  Future<void> _seedDemoChat({bool forceReset = false}) async {
    final db = _db;
    final crypto = _crypto;
    final did = _deviceId;
    final selfProfileId = (_profileId ?? '').trim();
    if (db == null || crypto == null || did == null) return;

    final entries = _demoEntries();
    final directEntries = entries
        .where((entry) => !entry.$1.startsWith('group:'))
        .toList(growable: false);
    final roomEntries = entries
        .where((entry) => entry.$1.startsWith('group:'))
        .toList(growable: false);
    final targetConvoIds = entries.map((entry) => entry.$1).toSet();

    final keepDemoProfiles = <String>{
      for (final entry in directEntries)
        if (entry.$1.startsWith('demo:')) entry.$1,
    };
    for (final room in roomEntries) {
      keepDemoProfiles.addAll(_demoGroupMemberProfileIds(room.$1));
    }

    final allConvos = await db.convoList(limit: 1000);
    final existingDemoConvoIds = allConvos
        .map((row) => ((row['convo_id'] as String?) ?? '').trim())
        .where(_isDemoConvoId)
        .toSet();
    final needsReset =
        forceReset ||
        existingDemoConvoIds.any((id) => !targetConvoIds.contains(id));
    if (needsReset) {
      for (final convoId in existingDemoConvoIds) {
        await db.deleteConversationData(
          convoId: convoId,
          keepConversationRow: false,
        );
      }
      final contacts = await db.contactsList(limit: 1000);
      for (final row in contacts) {
        final profileId = ((row['contact_profile_id'] as String?) ?? '').trim();
        if (!profileId.startsWith('demo:')) continue;
        if (keepDemoProfiles.contains(profileId)) continue;
        await db.contactDelete(profileId);
      }
    }

    Future<void> ensureDemoPerson({
      required String profileId,
      required String displayName,
      required int seed,
      bool withAvatar = false,
    }) async {
      await db.contactUpsert(
        profileId: profileId,
        displayName: displayName,
        displayNameIsCustom: true,
      );
      // Only a small subset gets a generated avatar; the rest render with
      // initials for a natural-looking roster.
      if (withAvatar) {
        final avatarPath = await _writeDemoPortraitAvatar(
          profileId: profileId,
          seed: seed,
        );
        await db.contactSetAvatarPath(
          profileId: profileId,
          avatarPath: avatarPath,
        );
      }
      await db.deviceProfileUpsert(
        deviceId: _demoSenderDeviceForProfile(profileId),
        profileId: profileId,
      );
    }

    Future<void> addMsg({
      required String convoId,
      required String sender,
      required String text,
      required String state,
      required int atMs,
    }) async {
      final payloadEventId = _uuid.v4();
      final payload = E2ePayloadV1(
        senderDeviceId: sender,
        createdAtMs: atMs,
        events: [MsgEventV1(eventId: payloadEventId, text: text)],
      );
      final cipher = await crypto.encrypt(payload.encode());
      await db.insertEvent(
        eventId: 'seed:$payloadEventId',
        convoId: convoId,
        type: 'msg',
        senderDeviceId: sender,
        ciphertextB64: base64Encode(cipher),
        createdAtMs: atMs,
        localState: state,
        payloadEventId: payloadEventId,
      );
      await db.convoTouch(convoId: convoId, atMs: atMs);
    }

    Future<void> addAttachment({
      required String convoId,
      required String sender,
      required Uint8List bytes,
      required String mime,
      required String state,
      required int atMs,
      String? mediaGroupId,
      List<int>? waveform,
    }) async {
      final payloadEventId = _uuid.v4();
      final blobId = 'demo_blob_${_uuid.v4()}';
      await db.attachmentUpsert(
        blobId: blobId,
        fileKeyB64: '',
        accessTokenB64: '',
        mime: mime,
        plaintextSizeBytes: bytes.length,
        ciphertextSizeBytes: bytes.length,
        expiresAtMs: atMs + (3650 * 24 * 60 * 60 * 1000),
        createdAtMs: atMs,
      );
      await _cacheAttachmentBytes(blobId: blobId, mime: mime, plaintext: bytes);
      final payload = E2ePayloadV1(
        senderDeviceId: sender,
        createdAtMs: atMs,
        events: [
          AttachmentEventV1(
            eventId: payloadEventId,
            blobId: blobId,
            fileKeyB64: '',
            blobAccessTokenB64: null,
            sizeBytes: bytes.length,
            mime: mime,
            mediaGroupId: mediaGroupId,
            waveform: waveform,
          ),
        ],
      );
      final cipher = await crypto.encrypt(payload.encode());
      await db.insertEvent(
        eventId: 'seed:$payloadEventId',
        convoId: convoId,
        type: 'att',
        senderDeviceId: sender,
        ciphertextB64: base64Encode(cipher),
        createdAtMs: atMs,
        localState: state,
        payloadEventId: payloadEventId,
      );
      await db.convoTouch(convoId: convoId, atMs: atMs);
    }

    final now = DateTime.now().millisecondsSinceEpoch;

    for (var i = 0; i < directEntries.length; i++) {
      final convoId = directEntries[i].$1;
      final title = directEntries[i].$2;
      await ensureDemoPerson(
        profileId: convoId,
        displayName: title,
        seed: i,
        withAvatar: _demoAvatarProfileIds.contains(convoId),
      );
      await db.convoEnsure1to1(peerProfileId: convoId);

      final exists = await db.listEvents(convoId, limit: 1);
      if (exists.isNotEmpty) continue;

      final senderDeviceId = _demoSenderDeviceForProfile(convoId);
      final script = _demoDirectScript(convoId);
      if (script.isEmpty) continue;

      // Lay the thread out in the recent past (~90 s between bubbles); each
      // conversation ends a few minutes apart so the chat list looks lived-in.
      const stepMs = 90 * 1000;
      var t = now - (i * 11 * 60 * 1000) - (script.length * stepMs);
      for (var s = 0; s < script.length; s++) {
        final step = script[s];
        final sender = step.fromMe ? did : senderDeviceId;
        // My last bubble shows as read; my earlier ones delivered — natural ticks.
        final state = step.fromMe
            ? (s == script.length - 1
                  ? MessageLocalState.read
                  : MessageLocalState.delivered)
            : MessageLocalState.received;
        final media = step.media;
        if (media != null) {
          final (bytes, mime) = _demoMediaBytes(media, (i * 17) + s);
          await addAttachment(
            convoId: convoId,
            sender: sender,
            bytes: bytes,
            mime: mime,
            state: state,
            atMs: t,
            waveform: media == 'voice'
                ? _demoSyntheticWaveform((i * 17) + s)
                : null,
          );
        } else if ((step.text ?? '').isNotEmpty) {
          await addMsg(
            convoId: convoId,
            sender: sender,
            text: step.text!,
            state: state,
            atMs: t,
          );
        }
        t += stepMs;
      }
    }

    // Place a couple of demo chats into the "Personal" category so that tab
    // isn't empty for screenshots.
    for (final personalId in _demoPersonalConvoIds) {
      if (!_personalConvoIds.contains(personalId)) {
        await setChatPersonal(convoId: personalId, personal: true);
      }
    }

    for (var i = 0; i < roomEntries.length; i++) {
      final roomId = roomEntries[i].$1;
      final roomTitle = roomEntries[i].$2;
      final members = _demoGroupMemberProfileIds(roomId);

      await db.convoEnsureGroup(groupId: roomId, title: roomTitle);

      for (var m = 0; m < members.length; m++) {
        final memberId = members[m];
        await ensureDemoPerson(
          profileId: memberId,
          displayName: _demoDisplayName(memberId),
          seed: 1000 + (i * 16) + m,
          withAvatar: _demoAvatarProfileIds.contains(memberId),
        );
      }

      final memberProfileIds = <String>[
        if (selfProfileId.isNotEmpty) selfProfileId,
        ...members,
      ];
      await db.groupMembersReplace(
        groupId: roomId,
        memberProfileIds: memberProfileIds,
      );

      if (selfProfileId.isNotEmpty) {
        // 🔴 У показательных комнат НЕТ поддельного фото.
        //
        // Раньше здесь рисовался квадрат с градиентом и белым кругом
        // посередине — «значок группы», который выглядел ровно как кружок в
        // квадрате и ничего не сообщал. Настоящая комната без фотографии
        // показывает ПЕРВЫЕ ДВЕ БУКВЫ названия на цветной подложке, как и
        // личная переписка без фото; показательные комнаты обязаны выглядеть
        // так же, иначе демонстрация показывает то, чего в продукте нет.
        //
        // `clearAvatar` именно ОЧИЩАЕТ: путь мог быть записан прежней версией,
        // и без очистки поддельное фото осталось бы навсегда.
        final currentSettings = await getRoomSettings(roomId);
        await _persistRoomSettingsRecord(
          db: db,
          groupId: roomId,
          settings: currentSettings.copyWith(
            description: _demoRoomDescription(roomId),
            clearAvatar: true,
            chatHistoryVisible: true,
          ),
        );
      }

      final exists = await db.listEvents(roomId, limit: 1);
      if (exists.isNotEmpty) continue;

      if (members.isEmpty) continue;

      final script = _demoGroupScript(roomId);
      if (script.isEmpty) continue;

      const stepMs = 80 * 1000;
      var t =
          now -
          ((directEntries.length + i) * 13 * 60 * 1000) -
          (script.length * stepMs);
      for (var s = 0; s < script.length; s++) {
        final step = script[s];
        final sender = step.from == null
            ? did
            : _demoSenderDeviceForProfile(step.from!);
        final state = step.from == null
            ? (s == script.length - 1
                  ? MessageLocalState.read
                  : MessageLocalState.delivered)
            : MessageLocalState.received;
        await addMsg(
          convoId: roomId,
          sender: sender,
          text: step.text,
          state: state,
          atMs: t,
        );
        t += stepMs;
      }
    }

    // STORE-DEMO: seed a fake ACTIVE group call (8 participants) for the demo
    // "Weekend Crew" room so a populated group-call screen can be captured.
    try {
      await _seedDemoRoomCall();
    } catch (_) {
      // best-effort — demo only
    }
  }

  /// Seeds an active 8-person group-call snapshot for a demo room so the call
  /// screen renders a full participant grid (store screenshots). Demo-only.
  Future<void> _seedDemoRoomCall() async {
    final db = _db;
    if (db == null) return;
    // The demo seed can run before the local profile/device id is established;
    // fall back to a demo identity so the call still seeds 8 named participants.
    final rawPid = (_profileId ?? '').trim();
    final rawDid = (_deviceId ?? '').trim();
    final selfPid = rawPid.isEmpty ? 'demo:user:03' : rawPid;
    final selfDid = rawDid.isEmpty ? 'demo-dev-self' : rawDid;
    const groupId = 'group:demo:social'; // Weekend Crew (7 members + me = 8)
    final members = _demoGroupMemberProfileIds(groupId);
    if (members.isEmpty) return;
    // Ensure I'm an ACTIVE member (owner) so the call screen is reachable from
    // this room, and the demo members are active so the roster is populated.
    await db.groupMembershipStateUpsert(
      groupId: groupId,
      profileId: selfPid,
      status: 'active',
      role: 'owner',
    );
    for (final m in members) {
      await db.groupMembershipStateUpsert(
        groupId: groupId,
        profileId: m,
        status: 'active',
        role: 'member',
      );
    }
    final now = DateTime.now().millisecondsSinceEpoch;
    final startedAt = now - 7 * 60 * 1000;
    final participants = <RoomCallParticipantStateRecord>[
      (
        profileId: selfPid,
        deviceId: selfDid,
        joinState: 'joined',
        supportsVideo: true,
        supportsScreenShare: false,
        muted: false,
        deafened: false,
        videoEnabled: false,
        screenShareEnabled: false,
        speaking: false,
        joinedAtMs: startedAt,
        leftAtMs: null,
        updatedAtMs: now,
      ),
      for (var i = 0; i < members.length; i++)
        (
          profileId: members[i],
          deviceId: 'demo-dev-${members[i]}',
          joinState: 'joined',
          supportsVideo: true,
          supportsScreenShare: false,
          muted: i % 3 == 0,
          deafened: false,
          videoEnabled: false,
          screenShareEnabled: false,
          speaking: i == 1 || i == 4,
          joinedAtMs: startedAt + (i + 1) * 4000,
          leftAtMs: null,
          updatedAtMs: now,
        ),
    ];
    await db.roomCallSnapshotReplace(
      groupId: groupId,
      callId: 'demo-call-1',
      state: 'active',
      mediaType: 'video',
      createdByProfileId: members.first,
      createdByDeviceId: 'demo-dev-${members.first}',
      stateVersion: 1,
      startedAtMs: startedAt,
      updatedAtMs: now,
      endedAtMs: null,
      expiresAtMs: now + 6 * 60 * 60 * 1000,
      participants: participants,
    );
  }

  String _demoDisplayName(String peerProfileId) {
    return _demoPersonName(peerProfileId);
  }

  String _demoAutoReply(String peerProfileId) {
    if (peerProfileId.startsWith('group:demo:')) {
      return 'Added to the thread.';
    }
    return 'Got it, thanks!';
  }

  // Deterministic 48-bar amplitude envelope (0..100) for demo voice notes so
  // they render with the real waveform layout (matching live recordings).
  List<int> _demoSyntheticWaveform(int seed) {
    final rng = math.Random(seed + 9173);
    return List<int>.generate(48, (_) {
      final r = rng.nextDouble();
      return (12 + r * r * 88).round().clamp(0, 100);
    }, growable: false);
  }

  // Generates placeholder bytes + mime for a scripted media bubble.
  (Uint8List, String) _demoMediaBytes(String kind, int seed) {
    switch (kind) {
      case 'voice':
        return (_buildDemoWavToneBytes(seed: 300 + seed), 'audio/wav');
      case 'note':
        return (
          _buildDemoNoteBytes(title: 'Note', seed: 500 + seed),
          'text/plain',
        );
      case 'photo':
      default:
        return (_buildDemoPhotoBytes(seed: 100 + seed), 'image/png');
    }
  }

  // A single message in a scripted demo thread.
  // fromMe = sent by the local user; media: null | 'photo' | 'voice' | 'note'.
  // For groups, `memberProfileId` names the sender (null = me).

  // Scripted 1:1 conversations. The first three (avatar contacts) are long
  // (7-8 bubbles); the rest are short and natural.
  List<({bool fromMe, String? text, String? media})> _demoDirectScript(
    String convoId,
  ) {
    ({bool fromMe, String? text, String? media}) them(String t) =>
        (fromMe: false, text: t, media: null);
    ({bool fromMe, String? text, String? media}) me(String t) =>
        (fromMe: true, text: t, media: null);
    ({bool fromMe, String? text, String? media}) themMedia(String kind) =>
        (fromMe: false, text: null, media: kind);
    ({bool fromMe, String? text, String? media}) meMedia(String kind) =>
        (fromMe: true, text: null, media: kind);

    switch (convoId) {
      case 'demo:chat': // Saved Messages
        return [
          me('Remember to renew the subscription before month end'),
          me('Vacation ideas ✈️'),
          meMedia('photo'),
          me('Wi-Fi password for the cabin — see notes'),
        ];
      case 'demo:user:01': // Emma Carter — long
        return [
          them('Hey! Have you tried the new version yet?'),
          me('Hey 🙌 Yes, last night. It really is faster now'),
          them('Right, it opens instantly'),
          them('And messages don’t disappear anymore'),
          me('Best part — everything’s encrypted, I feel safe'),
          themMedia('photo'),
          them('Sent you the pics from the weekend 😍'),
          me('Love them, thanks! Saved'),
          me('Let’s catch up on a call this week'),
        ];
      case 'demo:user:02': // Daniel Brooks — long
        return [
          them('Hey, can you take on a job?'),
          me('Sure, send me the details'),
          themMedia('voice'),
          them('Sent a voice note, give it a listen'),
          me('Got it, all clear'),
          them('When could you have it done?'),
          me('I think by Thursday'),
          them('Perfect, thanks! 🙏'),
        ];
      case 'demo:user:03': // Mia Thompson — long
        return [
          them('Where are you? We’re already waiting 😅'),
          me('On my way! Traffic, 10 minutes'),
          them('Ok, we grabbed a table by the window'),
          me('Perfect'),
          them('Want me to send the menu?'),
          me('Yeah, I’ll take a look'),
          themMedia('note'),
        ];
      case 'demo:user:04': // Liam — short
        return [
          them('Hey! Left the keys with the concierge for you'),
          me('Thanks so much 🙏'),
        ];
      case 'demo:user:05': // Sophie — short
        return [
          them('Got the documents, all good ✅'),
