  Future<String> _writeDemoPortraitAvatar({
    required String profileId,
    required int seed,
  }) async {
    final dir = await getApplicationDocumentsDirectory();
    final avatarsDir = Directory(p.join(dir.path, 'demo_avatars'));
    if (!await avatarsDir.exists()) {
      await avatarsDir.create(recursive: true);
    }

    final safe = profileId.replaceAll(RegExp(r'[^a-zA-Z0-9_\-]'), '_');
    final out = File(p.join(avatarsDir.path, '${safe}_v4.png'));
    if (await out.exists()) return out.path;

    const w = 256;
    const h = 256;
    final image = img.Image(width: w, height: h);

    final hueA = (seed * 29 + 17) % 360;
    final hueB = (hueA + 44 + (seed % 7) * 6) % 360;
    final c1 = _hsvToRgb(hueA.toDouble(), 0.34, 0.96);
    final c2 = _hsvToRgb(hueB.toDouble(), 0.47, 0.72);

    for (var y = 0; y < h; y++) {
      final t = y / (h - 1);
      final r = (c1.$1 + (c2.$1 - c1.$1) * t).round();
      final g = (c1.$2 + (c2.$2 - c1.$2) * t).round();
      final b = (c1.$3 + (c2.$3 - c1.$3) * t).round();
      for (var x = 0; x < w; x++) {
        image.setPixelRgba(x, y, r, g, b, 255);
      }
    }

    const skinTones = <(int, int, int)>[
      (245, 209, 178),
      (232, 188, 149),
      (205, 155, 118),
      (171, 125, 93),
      (137, 99, 75),
    ];
    const hairTones = <(int, int, int)>[
      (34, 25, 23),
      (65, 45, 35),
      (94, 70, 48),
      (126, 96, 70),
      (24, 44, 62),
    ];
    const shirtTones = <(int, int, int)>[
      (38, 78, 150),
      (24, 117, 111),
      (140, 60, 126),
      (191, 108, 34),
      (76, 87, 108),
    ];

    final skin = skinTones[seed % skinTones.length];
    final hair = hairTones[seed % hairTones.length];
    final shirt = shirtTones[seed % shirtTones.length];
    final hairShadow = (
      (hair.$1 * 0.78).round(),
      (hair.$2 * 0.78).round(),
      (hair.$3 * 0.78).round(),
    );

    _fillEllipseRgb(
      image,
      cx: w ~/ 2,
      cy: (h * 0.84).round(),
      rx: (w * 0.44).round(),
      ry: (h * 0.25).round(),
      color: shirt,
    );
    _fillEllipseRgb(
      image,
      cx: w ~/ 2,
      cy: (h * 0.46).round(),
      rx: (w * 0.31).round(),
      ry: (h * 0.24).round(),
      color: hairShadow,
    );
    _fillEllipseRgb(
      image,
      cx: w ~/ 2,
      cy: (h * 0.63).round(),
      rx: (w * 0.08).round(),
      ry: (h * 0.09).round(),
      color: skin,
    );
    _fillEllipseRgb(
      image,
      cx: w ~/ 2,
      cy: (h * 0.54).round(),
      rx: (w * 0.22).round(),
      ry: (h * 0.21).round(),
      color: skin,
    );
    _fillEllipseRgb(
      image,
      cx: w ~/ 2,
      cy: (h * 0.42).round(),
      rx: (w * 0.29).round(),
      ry: (h * 0.17).round(),
      color: hair,
    );
    if (seed.isEven) {
      _fillEllipseRgb(
        image,
        cx: (w * 0.34).round(),
        cy: (h * 0.54).round(),
        rx: (w * 0.07).round(),
        ry: (h * 0.14).round(),
        color: hair,
      );
      _fillEllipseRgb(
        image,
        cx: (w * 0.66).round(),
        cy: (h * 0.54).round(),
        rx: (w * 0.07).round(),
        ry: (h * 0.14).round(),
        color: hair,
      );
    }

    const eye = (34, 28, 26);
    _fillEllipseRgb(
      image,
      cx: (w * 0.43).round(),
      cy: (h * 0.54).round(),
      rx: 7,
      ry: 5,
      color: eye,
    );
    _fillEllipseRgb(
      image,
      cx: (w * 0.57).round(),
      cy: (h * 0.54).round(),
      rx: 7,
      ry: 5,
      color: eye,
    );
    _fillEllipseRgb(
      image,
      cx: w ~/ 2,
      cy: (h * 0.62).round(),
      rx: 15,
      ry: 3,
      color: (159, 79, 92),
    );

    await out.writeAsBytes(img.encodePng(image), flush: true);
    return out.path;
  }


  void _fillEllipseRgb(
    img.Image image, {
    required int cx,
    required int cy,
    required int rx,
    required int ry,
    required (int, int, int) color,
  }) {
    if (rx <= 0 || ry <= 0) return;
    final r = color.$1.clamp(0, 255);
    final g = color.$2.clamp(0, 255);
    final b = color.$3.clamp(0, 255);
    for (var y = cy - ry; y <= cy + ry; y++) {
      if (y < 0 || y >= image.height) continue;
      final ny = (y - cy) / ry;
      final inside = 1 - ny * ny;
      if (inside < 0) continue;
      final span = (rx * math.sqrt(inside)).round();
      var startX = cx - span;
      var endX = cx + span;
      if (endX < 0 || startX >= image.width) continue;
      if (startX < 0) startX = 0;
      if (endX >= image.width) endX = image.width - 1;
      for (var x = startX; x <= endX; x++) {
        image.setPixelRgba(x, y, r, g, b, 255);
      }
    }
  }

  Uint8List _buildDemoPhotoBytes({required int seed}) {
    const w = 960;
    const h = 1280;
    final image = img.Image(width: w, height: h);

    final top = _hsvToRgb(((seed * 31) + 18).toDouble(), 0.36, 0.95);
    final bottom = _hsvToRgb(((seed * 31) + 102).toDouble(), 0.52, 0.60);
    for (var y = 0; y < h; y++) {
      final t = y / (h - 1);
      final r = (top.$1 + (bottom.$1 - top.$1) * t).round();
      final g = (top.$2 + (bottom.$2 - top.$2) * t).round();
      final b = (top.$3 + (bottom.$3 - top.$3) * t).round();
      for (var x = 0; x < w; x++) {
        image.setPixelRgba(x, y, r, g, b, 255);
      }
    }

    _fillEllipseRgb(
      image,
      cx: (w * 0.74).round(),
      cy: (h * 0.26).round(),
      rx: 180,
      ry: 180,
      color: _hsvToRgb(((seed * 23) + 44).toDouble(), 0.34, 0.98),
    );

    for (var i = 0; i < 7; i++) {
      final card = _hsvToRgb(
        ((seed * 17) + i * 27).toDouble(),
        0.30,
        0.88 - i * 0.06,
      );
      final x = ((seed * 73) + i * 111) % (w - 220);
      final y = ((seed * 41) + i * 137) % (h - 280);
      final width = 140 + ((seed + i * 19) % 90);
      final height = 170 + ((seed + i * 23) % 170);
      for (var yy = y; yy < y + height && yy < h; yy++) {
        final drift = ((yy - y) * 0.10).round();
        var startX = x + drift;
        var endX = startX + width;
        if (startX < 0) startX = 0;
        if (endX > w) endX = w;
        for (var xx = startX; xx < endX; xx++) {
          image.setPixelRgba(xx, yy, card.$1, card.$2, card.$3, 255);
        }
      }
    }

    final foreground = _hsvToRgb(((seed * 29) + 210).toDouble(), 0.40, 0.34);
    final inset = (w * 0.08).round();
    for (var y = (h * 0.78).round(); y < h; y++) {
      final sway = (math.sin((y + seed * 11) / 33.0) * 24).round();
      var startX = inset + sway;
      var endX = (w - inset) + sway;
      if (startX < 0) startX = 0;
      if (endX > w) endX = w;
      for (var x = startX; x < endX; x++) {
        image.setPixelRgba(
          x,
          y,
          foreground.$1,
          foreground.$2,
          foreground.$3,
          255,
        );
      }
    }

    return Uint8List.fromList(img.encodePng(image));
  }

  Uint8List _buildDemoWavToneBytes({required int seed, int durationMs = 3400}) {
    const sampleRate = 16000;
    final sampleCount = (sampleRate * durationMs) ~/ 1000;
    final dataBytes = sampleCount * 2;
    final out = ByteData(44 + dataBytes);

    void writeAscii(int offset, String value) {
      for (var i = 0; i < value.length; i++) {
        out.setUint8(offset + i, value.codeUnitAt(i));
      }
    }

    writeAscii(0, 'RIFF');
    out.setUint32(4, 36 + dataBytes, Endian.little);
    writeAscii(8, 'WAVE');
    writeAscii(12, 'fmt ');
    out.setUint32(16, 16, Endian.little);
    out.setUint16(20, 1, Endian.little);
    out.setUint16(22, 1, Endian.little);
    out.setUint32(24, sampleRate, Endian.little);
    out.setUint32(28, sampleRate * 2, Endian.little);
    out.setUint16(32, 2, Endian.little);
    out.setUint16(34, 16, Endian.little);
    writeAscii(36, 'data');
    out.setUint32(40, dataBytes, Endian.little);

    final baseFreq = 196.0 + (seed % 5) * 24.0;
    for (var i = 0; i < sampleCount; i++) {
      final t = i / sampleRate;
      final attack = (i / (sampleRate * 0.08)).clamp(0.0, 1.0);
      final release = ((sampleCount - i) / (sampleRate * 0.14)).clamp(0.0, 1.0);
      final envelope = attack < release ? attack : release;
      final tremolo = 1.0 + 0.08 * math.sin(2 * math.pi * 1.4 * t);
      final sample =
          (math.sin(2 * math.pi * baseFreq * t) * 0.62 +
              math.sin(2 * math.pi * baseFreq * 1.5 * t) * 0.28) *
          envelope *
          tremolo;
      final pcm = (sample * 26000).round().clamp(-32768, 32767);
      out.setInt16(44 + i * 2, pcm, Endian.little);
    }

    return out.buffer.asUint8List();
  }

  Uint8List _buildDemoNoteBytes({required String title, required int seed}) {
    final lines = <String>[
      '# $title',
      '',
      'Generated for Secretly demo screenshots.',
      'Version: $_demoSeedVersion',
      'Reference: DEMO-${seed.toString().padLeft(4, '0')}',
      'Status: Ready',
    ];
    return Uint8List.fromList(utf8.encode(lines.join('\n')));
  }

  (int, int, int) _hsvToRgb(double h, double s, double v) {
    final c = v * s;
    final hh = (h % 360) / 60.0;
    final x = c * (1 - ((hh % 2) - 1).abs());
    var r1 = 0.0;
    var g1 = 0.0;
    var b1 = 0.0;
    if (hh < 1) {
      r1 = c;
      g1 = x;
    } else if (hh < 2) {
      r1 = x;
      g1 = c;
    } else if (hh < 3) {
      g1 = c;
      b1 = x;
    } else if (hh < 4) {
      g1 = x;
      b1 = c;
    } else if (hh < 5) {
      r1 = x;
      b1 = c;
    } else {
      r1 = c;
      b1 = x;
    }
    final m = v - c;
    return (
      ((r1 + m) * 255).round().clamp(0, 255),
      ((g1 + m) * 255).round().clamp(0, 255),
      ((b1 + m) * 255).round().clamp(0, 255),
    );
  }

