  /// Decrypt + persist one wire from the background inbox isolate. Runs the
  /// real delivery path (so nothing diverges from the foreground); the
  /// foreground-only recovery machinery is suppressed by [_backgroundInboundMode].
  /// The caller MUST hold the cross-isolate decrypt lease. Returns true iff the
  /// wire was durably applied — the caller then marks it seen and may notify;
  /// on false the caller stages it to quarantine for the foreground to recover.
  Future<bool> handleDeliveredInBackground({
    required String msgId,
    required String ciphertextB64,
  }) {
    assert(_backgroundInboundMode,
        'handleDeliveredInBackground requires bootstrapForBackgroundInbound');
    return _handleDelivered(msgId: msgId, ciphertextB64: ciphertextB64);
  }

  Future<bool> _handleDelivered({
    required String msgId,
    required String ciphertextB64,
    bool fromQuarantineReplay = false,
  }) async {
    final db = _db;
    final did = _deviceId;
    final pid = _profileId;
    final keys = _keys;
    final ratchetV1 = _ratchetV1;
    final ratchetV3 = _ratchetV3;
    final crypto = _crypto;
    if (db == null || did == null || pid == null || keys == null) {
      // Diagnostic (2026-06-19): this silent bail blocks ALL inbound apply; if
      // it ever fires in the field, name which dependency was missing.
      DiagLog.event('inbox', 'delivered_bail_null_dep', {
        'db': db == null,
        'did': did == null,
        'pid': pid == null,
        'keys': keys == null,
        'ratchetV3': ratchetV3 == null,
        'crypto': crypto == null,
      });
      return false;
    }

    // Single-writer barrier: never advance the ratchet while a background pass
    // still holds the cross-isolate lease. No-op in the background isolate (it
    // owns the lease for its whole run) and a fast integer compare in the
    // steady state (the heartbeat keeps the foreground lease fresh).
    await _ensureForegroundRatchetLease();

    DiagLog.event('inbox', 'delivered', {
      'msg': DiagLog.pfx(msgId),
      'ciphertext_len': ciphertextB64.length,
    });

    String? senderDeviceId;
    Uint8List? plainBytes;
    E2ePayloadV1? payload;
    // ИД-1 / С-1: who the RELAY says sent this wire (null = it did not say).
    final attestedSenderDid = AttestedSenders.lookup(msgId);
    try {
      final bytes = base64Decode(ciphertextB64);
      final wireBytes = Uint8List.fromList(bytes);
      Object? lastDecryptError;
      // 🔴 THE RATCHET'S OWN VERDICT, kept separate (2026-07-31, field: 317
      // discards on one device in minutes).
      //
      // Below, three decryptors are tried in turn and each overwrote
      // `lastDecryptError`. The LAST one is the local symmetric fallback, which
      // exists for legacy/self-encrypted wires and can NEVER open a peer's
      // ratchet wire — so for peer traffic it always failed with
      // `rust open failed`, and that meaningless error was the one thrown.
      //
      // It is not merely a bad log line. `isGenuineMacFailure` matches
      // `rust-open`, so a TRANSIENT ratchet condition — "session not found",
      // "missing recv chain key", the things that heal the moment the session
      // re-establishes — was reported as permanent, ACKed to the relay and the
      // message DESTROYED. The real verdict has to survive the fallback.
      Object? ratchetDecryptError;

      // 🔴 ПРОВОД ОТ ИМЕНИ ЭТОГО ЖЕ УСТРОЙСТВА НЕ ПРИНИМАЕТСЯ (17.09.2026).
      //
      // Номер отправителя в заголовке — слова самого провода: рукопожатие
      // подписи отправителя не несёт, а реле его не сообщает. Себе устройство
      // не пишет никогда (`sendControlMessage` исключает текущий аппарат), так
      // что такой провод — только подделка. Принятый, он проходил проверку
      // «своё устройство» (`isOwnDeviceId` верно для своего номера), а с ней —
      // команду «сеанс завершён», то есть стирание приложения, и самокопии
      // сообщений. Отбрасываем до расшифровки: ратчет не трогается.
      final claimedSenderDid = claimedWireSenderDeviceId(wireBytes);
      if (claimedSenderDid != null && claimedSenderDid == did.trim()) {
        DiagLog.event('inbox', 'self_named_wire_dropped', {
          'msg': DiagLog.pfx(msgId),
        });
        _clearDeliveredDecryptBudget(msgId);
        return true;
      }

      // 🔴 С-1 (17.09.2026): the relay authenticated the real sender at send
      // time. A header that names somebody else is a forgery — the handshake
      // does not bind the name to a key. Dropped before the ratchet sees it.
      if (attestedSenderDid != null &&
          claimedSenderDid != null &&
          attestedSenderDid != claimedSenderDid) {
        DiagLog.event('inbox', 'sender_mismatch', {
          'msg': DiagLog.pfx(msgId),
          'claimed': DiagLog.pfx(claimedSenderDid),
          'attested': DiagLog.pfx(attestedSenderDid),
        });
        AttestedSenders.forget(msgId);
        _clearDeliveredDecryptBudget(msgId);
        return true;
      }

      // К-2 (17.09.2026): сырой провод комнаты, разосланный реле. Отправитель —
      // только со слов реле; без них провод не принимается.
      if (RoomRawWire.looksLike(wireBytes)) {
        return _applyRawRoomWire(
          db: db,
          keys: keys,
          msgId: msgId,
          ciphertextB64: ciphertextB64,
          wireBytes: wireBytes,
          attestedSenderDid: attestedSenderDid,
        );
      }

      final decodedV3 = RatchetWireV3.tryDecode(wireBytes);
      if (decodedV3 != null && ratchetV3 != null) {
        try {
          senderDeviceId = decodedV3.header['sender_device_id'] as String?;
