        final decodedV1 = RatchetWireV1.tryDecode(wireBytes);
        if (decodedV1 != null && ratchetV1 != null) {
          try {
            senderDeviceId = decodedV1.header['sender_device_id'] as String?;
            final pb = await ratchetV1.decryptFromWire(
              selfProfileId: pid,
              selfDeviceId: did,
              wireBytes: wireBytes,
            );
            plainBytes = pb;
            payload = E2ePayloadV1.decode(pb);
            if ((senderDeviceId ?? '').isEmpty) {
              senderDeviceId = payload.senderDeviceId;
            }
          } catch (e) {
            ratchetDecryptError ??= e;
            lastDecryptError = e;
          }
        }
      }

      if (payload == null && crypto != null) {
        try {
          final pb = Uint8List.fromList(await crypto.decrypt(bytes));
          plainBytes = pb;
          payload = E2ePayloadV1.decode(pb);
          senderDeviceId = payload.senderDeviceId;
        } catch (e) {
          lastDecryptError = e;
        }
      }

      if (payload == null) {
        // Prefer the ratchet's verdict: it describes the actual session state
        // and drives the transient-vs-permanent decision. The local fallback's
