      // the process dies between background wakes. See the policy's doc.
      final budgetNowMs = DateTime.now().millisecondsSinceEpoch;
      final budget = await db.inboundDecryptFailureBump(msgId, budgetNowMs);
      final attempts = budget.attempts;
      final failingForMs = budgetNowMs - budget.firstFailedAtMs;
      _deliveredDecryptAttempts[msgId] = attempts;
      DiagLog.event('inbox', 'decrypt_fail', {
        'msg': DiagLog.pfx(msgId),
        'reason': _classifyShortReason(e),
        'err_tag': _shortErrorTag(e),
        'attempts': attempts,
