      int failingBudgetMs = 0;
      try {
        failingBudgetMs = await _decryptFailingBudgetMsFor(db, senderDeviceId);
      } catch (budgetErr) {
        DiagLog.event('inbox', 'ack_decide_escape', {
          'msg': DiagLog.pfx(msgId),
          'sender_dev': DiagLog.pfx(senderDeviceId),
          'at': 'failing_budget',
          'err': _shortErrorTag(budgetErr),
