      // конверт ушёл в карантин, или удержан ради журнала, или отброшен как
      // свой. Если эта запись есть, а ни одного из трёх нет — обрыв ниже.
      DiagLog.event('inbox', 'ack_decided', {
        'msg': DiagLog.pfx(msgId),
        'ack': ackAndQuarantine,
        'genuine_mac': genuineMac,
        'attempts': attempts,
      });
