        try {
          await db.inboxQuarantineUpsert(
            attestedFromDeviceId: AttestedSenders.lookup(msgId),
            msgId: msgId,
            senderDeviceId: senderDeviceId,
            ciphertextB64: ciphertextB64,
            nowMs: DateTime.now().millisecondsSinceEpoch,
          );
