          // wait progressively longer (30 s → 60 s → 120 s → 5 min cap).
          _lastForcedResetAtMs[senderDeviceId] = nowMs;
          _forcedResetCount[senderDeviceId] =
              (_forcedResetCount[senderDeviceId] ?? 0) + 1;
          _consecutiveDecryptFailuresSinceReset[senderDeviceId] = 0;
          _replayDecryptFailuresSinceReset[senderDeviceId] = 0;
          DiagLog.event('inbox', 'reset_ping_forced', {
            'peer_dev': DiagLog.pfx(senderDeviceId),
            'step': _forcedResetCount[senderDeviceId],
          });
        }
      }
      if (ackAndQuarantine) {
        // ACK + advance: a genuine permanent failure (or exhausted retries).
        // Stops the relay re-offering it; the parked ciphertext stays lost.
        DiagLog.event('inbox', 'decrypt_dropped', {
          'msg': DiagLog.pfx(msgId),
          'sender_dev': DiagLog.pfx(senderDeviceId),
          'reason': _classifyShortReason(e),
          'err_tag': _shortErrorTag(e),
          'attempts': attempts,
          'exhausted': exhausted,
          'genuine_mac': genuineMac,
        });
        callLog(
          'AppCtrl',
          '_handleDelivered dropping (acked) msgId=$msgId attempts=$attempts genuineMac=$genuineMac sender=${senderDeviceId ?? '?'}: $e',
        );
        _clearDeliveredDecryptBudget(msgId);
        return true;
      }
      // Transient/recoverable AND retry budget NOT yet exhausted: do NOT ack.
      // Return false so the relay's reorder buffer / orphan sweep re-offers
      // this exact wire — it should decrypt once the reset ping above
      // re-establishes the session. The per-msg attempt counter is kept (not
      // cleared) so it accrues toward the exhaustion backstop.
      DiagLog.event('inbox', 'decrypt_retry_unacked', {
        'msg': DiagLog.pfx(msgId),
        'sender_dev': DiagLog.pfx(senderDeviceId),
        'reason': _classifyShortReason(e),
        'err_tag': _shortErrorTag(e),
        'attempts': attempts,
      });
      return false;
    }

    if (payload == null || plainBytes == null) {
      // Ignore undecryptable envelope to avoid storing broken/opaque events.
      DiagLog.event('inbox', 'decrypt_empty', {'msg': DiagLog.pfx(msgId)});
      return false;
    }
    DiagLog.event('inbox', 'decrypt_ok', {
      'msg': DiagLog.pfx(msgId),
      'sender_dev': DiagLog.pfx(senderDeviceId),
      'events': payload.events.length,
    });
    _clearDeliveredDecryptBudget(msgId);
    // FIX A — a successful decrypt from this device means the ratchet healed.
    // Clear the consecutive-failure counter and escalation state so the next
    // genuine failure starts the ladder fresh (and we never force-reset a
    // working session).
    if (senderDeviceId != null && senderDeviceId.isNotEmpty) {
      _consecutiveDecryptFailuresSinceReset.remove(senderDeviceId);
      _replayDecryptFailuresSinceReset.remove(senderDeviceId);
      // 🔴 ПОЛОСУ ЗАКРЫВАЕТ НЕ ЛЮБОЙ УСПЕХ (12.09.2026). Успешный конверт идёт
      // под СТАРОЙ эпохой, припаркованные — под НОВОЙ; успех по старой ничего
      // не доказывает про новую. Закрываем только если отказов не было дольше
      // разрыва — см. [_noteEpochAheadStreakSuccess].
      //
      // Счётчики ниже остаются на прежнем правиле: для лестницы сбросов
      // успешная расшифровка ДЕЙСТВИТЕЛЬНО означает, что сессия жива.
      _noteEpochAheadStreakSuccess(senderDeviceId);
      _lastForcedResetAtMs.remove(senderDeviceId);
      _forcedResetCount.remove(senderDeviceId);
    }

    // Apply the decrypted payload (shared by the fresh-decrypt path here and the
    // journal-recovery path in the catch above). Extracted verbatim so both
    // entry points route the device→profile lookup, storage, and quarantine
    // replay through exactly one code path.
    return _applyDecryptedInbound(
      db: db,
      keys: keys,
      msgId: msgId,
      ciphertextB64: ciphertextB64,
      plainBytes: plainBytes,
      payload: payload,
      senderDeviceId: senderDeviceId,
      fromQuarantineReplay: fromQuarantineReplay,
      senderAttested:
          attestedSenderDid != null && attestedSenderDid == senderDeviceId,
    );
  }

  /// К-2: приём сырого провода комнаты `SKR1`.
  ///
  /// Возвращает true — провод обработан или отброшен навсегда (подтверждаем
  /// реле); false — пока не можем (реле повторит).
  Future<bool> _applyRawRoomWire({
    required AppDb db,
    required KeysClient keys,
    required String msgId,
    required String ciphertextB64,
    required Uint8List wireBytes,
    required String? attestedSenderDid,
  }) async {
    final event = RoomRawWire.tryDecode(wireBytes);
    final sender = (attestedSenderDid ?? '').trim();
    String? reject;
    if (event == null) {
      reject = 'malformed_or_unsigned';
    } else if (sender.isEmpty) {
      reject = 'sender_not_attested';
    } else if (sender == (_deviceId ?? '').trim()) {
      reject = 'self';
    }
    if (reject == null && event != null) {
      // Подпись обязательна: поколение без ключа подписи сырым не принимаем.
      final keyRow = await db.roomRecvKeyGet(
        roomId: event.roomId,
        senderDeviceId: sender,
        epoch: event.epoch,
      );
      if (keyRow != null && keyRow['signing_pub'] == null) {
        reject = 'generation_unsigned';
      }
    }
    if (reject != null || event == null) {
      DiagLog.event('room_key', 'raw_wire_rejected', {
        'msg': DiagLog.pfx(msgId),
        'why': reject ?? 'unknown',
      });
      _clearDeliveredDecryptBudget(msgId);
      return true;
    }
    if (!roomSenderKeyReceiveEnabled) return false;
    final payload = E2ePayloadV1(
      senderDeviceId: sender,
      createdAtMs: DateTime.now().millisecondsSinceEpoch,
      events: <E2eEventV1>[event],
    );
    _clearDeliveredDecryptBudget(msgId);
    return _applyDecryptedInbound(
      db: db,
      keys: keys,
      msgId: msgId,
      ciphertextB64: ciphertextB64,
      plainBytes: Uint8List.fromList(payload.encode()),
      payload: payload,
      senderDeviceId: sender,
      fromQuarantineReplay: false,
      senderAttested: true,
      pairwiseSessionEvidence: false,
    );
  }

  /// Route a decrypted inbound payload to storage. Shared by [_handleDelivered]'s
  /// fresh-decrypt path and its zero-loss journal-recovery path. On a durable
  /// apply the inbound-journal copy for [msgId] is dropped.
  Future<bool> _applyDecryptedInbound({
    required AppDb db,
    required KeysClient keys,
    required String msgId,
    required String ciphertextB64,
    required Uint8List plainBytes,
    required E2ePayloadV1 payload,
    required String? senderDeviceId,
    required bool fromQuarantineReplay,
    bool senderAttested = false,
    // Сырой провод комнаты (SKR1) открыт ключом комнаты и не доказывает, что
    // попарная сессия с автором цела.
    bool pairwiseSessionEvidence = true,
  }) async {
    final now = DateTime.now().millisecondsSinceEpoch;
    String? senderProfileId;
    final capsDid = (senderDeviceId ?? '').trim();
    if (payload.caps.isNotEmpty &&
        capsDid.isNotEmpty &&
        capsDid != (_deviceId ?? '').trim()) {
      await db.deviceCapsPut(deviceId: capsDid, caps: payload.caps, nowMs: now);
    }

    if (senderDeviceId != null && senderDeviceId.isNotEmpty) {
      final cached = await db.deviceProfileCached(senderDeviceId);

      // SLOW-DRAIN FIX R9 (2026-07-16): this device→profile lookup is an
      // authed NETWORK round trip (plus a Keystore identity load) and it ran
      // INLINE in the serial inbox drain — on a flaky network each hit ate up
      // to the HTTP timeout of the drain's per-message apply budget, and a
      // wedged Keystore ate all of it. Now:
      //   * cached mapping → apply proceeds IMMEDIATELY on the cache; the
      //     5-minute freshness re-verify (profile rebind detection) still
      //     happens, but as a fire-and-forget background task that heals the
      //     cache/convo bindings asynchronously (`db.rebindProfileId` there).
      //   * unknown sender → the lookup stays awaited (correct attribution
      //     beats speed for a first-contact message) but is bounded to 6s so
      //     a dead network degrades to the existing `dev:<deviceId>` convo
      //     path (merged later by `convoMerge` once the mapping is learned)
      //     instead of stalling the whole backlog.
      String? lookedUp;
      // In background mode use the cached mapping only — a first-contact network
      // lookup would block a throwaway isolate on a network that is probably why
      // the app is asleep. An unknown sender lands in dev:<deviceId>, which the
      // foreground merges into the real convo on its next wake.
      if (!_transportBlocked && !_backgroundInboundMode) {
        if (cached == null || cached.isEmpty) {
          _deviceProfileLookupAtMs[senderDeviceId] = now;
          try {
            lookedUp = await _lookupProfileForDeviceAuthed(
              senderDeviceId,
            ).timeout(const Duration(seconds: 6));
          } catch (_) {
            // ignore — degraded dev:<deviceId> path below
          }
        } else {
          final lastLookupAtMs = _deviceProfileLookupAtMs[senderDeviceId] ?? 0;
          if (now - lastLookupAtMs >= 5 * 60 * 1000) {
            _deviceProfileLookupAtMs[senderDeviceId] = now;
            unawaited(
              _reverifyDeviceProfileMappingInBackground(
                senderDeviceId: senderDeviceId,
                cachedProfileId: cached,
              ),
            );
          }
        }
      }

      // Prefer server truth when available; cached mapping can become stale
      // across server/profile changes (the cached case is re-verified in the
      // background above).
      if (lookedUp != null && lookedUp.isNotEmpty) {
        senderProfileId = lookedUp;
      } else {
        senderProfileId = cached;
      }

      final spid = senderProfileId;
      if (spid != null && spid.isNotEmpty) {
        await db.deviceProfileUpsert(deviceId: senderDeviceId, profileId: spid);
        if (spid == (_profileId ?? '').trim()) {
          _rememberOwnDeviceId(senderDeviceId);
        } else {
          // Step 3 (2026-06-12): we just received from a PEER device. If it is
          // a device we have never targeted (the peer reinstalled / made a new
          // account and rotated their device_id), our send-side device list is
          // stale and our outbound to them is going to a dead device. Learn the
          // peer's CURRENT device set now (throttled), so A->B starts working as
          // soon as B->A does — this closes the asymmetric one-direction break.
          unawaited(
            _maybeRefreshPeerDevicesOnNewSenderDevice(spid, senderDeviceId),
          );
          // FIX E (requirement #3): stamp the hot last-inbound time for the
          // silence sweep AND, if our cached bundle for this peer is stale,
          // fire ONE throttled refresh even when the sender device is already
          // known. The on-new-sender refresh above only fires for an UNKNOWN
          // device; this additionally catches a peer that ADDED a device or
          // rotated a signed prekey while an already-known device kept talking.
          _noteInboundFromPeerAndMaybeRefresh(spid);
        }

        // If we previously had to route messages into a temporary dev:<deviceId> conversation
        // (because device->profile mapping was unknown/offline), merge it into the real convo
        // as soon as we learn the profile id.
        final devConvoId = 'dev:$senderDeviceId';
        if (devConvoId != spid) {
          try {
            await db.convoMerge(fromConvoId: devConvoId, toConvoId: spid);
          } catch (_) {
            // ignore
          }
        }
      }
    }

    final result = await _handleDecryptedInboundPayload(
      db: db,
      msgId: msgId,
      ciphertextB64: ciphertextB64,
      plainBytes: plainBytes,
      payload: payload,
      senderDeviceId: senderDeviceId,
      senderProfileId: senderProfileId,
      now: now,
      senderAttested: senderAttested,
    );
    if (result) {
      // Durably applied — the zero-loss journal copy is no longer needed. The
      // TTL prune ages out any orphan left by a crash before this point.
      try {
        await db.inboundJournalDelete(msgId);
      } catch (_) {
        // best-effort
      }
      // 🔴 И ПАРКОВАННАЯ КОПИЯ ТОЖЕ (06.08.2026, полевой шторм после
      // восстановления: 11 проводов дали 106 «сбоев расшифровки» за пять минут).
      //
      // Провод, который однажды не удалось применить, паркуется в карантин,
      // подтверждается реле и помечается пройденным. Если следующая доставка
      // того же msg_id применилась — содержимое на месте, журнал стёрт строкой
      // выше, а карантинная строка ОСТАВАЛАСЬ: её удаляли только при успехе
      // ПОВТОРА. Но повтор успешным быть уже не может — ключ сообщения
      // одноразовый, а журнал, из которого шло спасение, только что удалён.
      //
      // Дальше сирота перемалывается свипом вечно: каждый заход даёт настоящий
      // MAC-сбой, а тот идёт в счётчики поломки сессии и в отрицательные
      // квитанции. То есть ЗДОРОВАЯ сессия объявляется сломанной из-за
      // сообщения, которое давно прочитано. В поле это выглядело как «смс
      // доходят очень долго и странно».
      //
      // Удалять здесь безопасно по определению: содержимое применено, парковка
      // держалась ровно до этого момента. Никакой другой признак для этого не
      // годится — `inbox_seen` ставится и при парковке (relay_client.dart:3348),
      // то есть означает «курсор реле прошёл», а не «содержимое применено».
      try {
        final hadParked = await db.inboxQuarantineDelete(msgId);
        if (hadParked) {
          DiagLog.event('inbox', 'quarantine_orphan_cleared', {
            'msg': DiagLog.pfx(msgId),
            'sender_dev': DiagLog.pfx(senderDeviceId),
          });
        }
      } catch (_) {
        // best-effort
      }
    }
    // Session-recovery hardening: a successful decrypt from this sender means
    // the ratchet with them is healthy again — re-attempt any of their
    // previously-quarantined (undecryptable) messages so nothing is lost.
    // Skipped during a replay pass itself to avoid recursion.
    if (!fromQuarantineReplay &&
        pairwiseSessionEvidence &&
        senderDeviceId != null &&
        senderDeviceId.isNotEmpty) {
      // Closes the recovery clock: this peer decrypts again.
      _noteRecoverySuccess(senderDeviceId);
      unawaited(_maybeReplayQuarantinedFromSender(senderDeviceId));
    }
    return result;
  }

  // Re-attempt decryption of messages parked in the inbox quarantine for a
  // specific sender device. Runs at most once concurrently per device. On a
  // successful re-decrypt the message is stored (via the normal pipeline) and
  // removed from quarantine; otherwise it stays parked for a later attempt.
  final Set<String> _quarantineReplayInFlight = <String>{};

  Future<void> _maybeReplayQuarantinedFromSender(String senderDeviceId) async {
    final sid = senderDeviceId.trim();
    if (sid.isEmpty) return;
    final db = _db;
    if (db == null) return;
    if (_quarantineReplayInFlight.contains(sid)) return;
    _quarantineReplayInFlight.add(sid);
    try {
      final count = await db.inboxQuarantineCountForSender(sid);
      if (count <= 0) return;
      final rows = await db.inboxQuarantineListForSender(sid, limit: 200);
      var skippedHopeless = 0;
      // Fix C (2026-07-24): the current session's handshake birth stamp — a
      // parked wire older than this is superseded (locally undecryptable
      // forever) if it still fails to decrypt below, so it can be retired.
      var sessionEpochMs = 0;
      try {
        sessionEpochMs = await db.sessionV3EpochFor(sid);
      } catch (_) {
        sessionEpochMs = 0;
      }
      var recovered = 0;
      var retiredSuperseded = 0;
      for (final row in rows) {
        // PERF(frames): ratchet decrypt is CPU-bound pure-Dart math on the UI
        // isolate — force a timer-task boundary per row so vsync frames can
        // interleave with a long replay burst instead of freezing the UI.
        await Future<void>.delayed(Duration.zero);
        final qMsgId = (row['msg_id'] as String?)?.trim() ?? '';
        final qCipher = (row['ciphertext_b64'] as String?) ?? '';
        // ИД-1 / С-1: the relay's word on the sender survives the park.
        AttestedSenders.record(qMsgId, row['attested_from_device_id']);
        if (qMsgId.isEmpty || qCipher.isEmpty) {
          if (qMsgId.isNotEmpty) await db.inboxQuarantineDelete(qMsgId);
          continue;
        }
        // 🔴 БЕЗНАДЁЖНЫЙ КОНВЕРТ ПЕРЕИГРЫВАЕМ РЕДКО (15.08.2026, замер поля).
        //
        // ОДИН конверт с утерянным ключом ратчета дал 23 лечения сессии за
        // полчаса: каждый заход переигрывал его заново, каждая неудача гнала
        // reset-ping. За сутки по всему реле это 663 конверта лечения на 738
        // сообщений — лечение почти сравнялось с полезным трафиком.
        //
        // 🔴 ВЫБРАСЫВАТЬ ЕГО НЕЛЬЗЯ, И ЛЕЧЕНИЕ ИЗ ПОВТОРА ОТКЛЮЧАТЬ НЕЛЬЗЯ:
        // без них случился инцидент 28.07 — 65 неоткрываемых конвертов, 63
        // жалобы и НОЛЬ восстановления за 28 часов. Поэтому меняется только
        // ЧАСТОТА: пробуем такой конверт раз в час, а не в каждый заход.
        // Починится сессия — он откроется на ближайшей попытке.
        if (_quarantineReplayTooSoon(row, nowMs: DateTime.now().millisecondsSinceEpoch)) {
          skippedHopeless += 1;
          // 🔴 ПАУЗА НЕ ИМЕЕТ ПРАВА ГЛУШИТЬ ЛЕКАРСТВО (ТЗ 16.08, Л-2).
          //
          // Пропуск стоит ДО _handleDelivered, а пере-NACK жил в ЕГО ветке
          // отказа — задушив вчера шторм лечения (52→9/час), пауза тем же
          // движением молча отключила существующую машину Sesame: конверт не
          // переигрывается → не проваливается → отправителя больше никто не
          // просит пере-шифровать. Инцидент 15–16.08: сутки одной галочки.
          //
          // Дорогая РАСШИФРОВКА остаётся раз в час; дешёвое «я всё ещё не могу
          // это прочитать» обязано идти. Темп держат сам клейм (срок = паузе
          // переигровки) и оконный предохранитель на устройство.
          unawaited(_nackQuarantinedWireOnce(
            qMsgId,
            sid,
            reNackAfterMs: _quarantineHopelessRetryMs,
          ));
          continue;
        }
        bool ok = false;
        try {
          ok = await _handleDelivered(
            msgId: qMsgId,
            ciphertextB64: qCipher,
            fromQuarantineReplay: true,
          );
        } catch (_) {
          ok = false;
        }
        if (ok) {
          await db.inboxQuarantineDelete(qMsgId);
          recovered++;
        } else {
          await db.inboxQuarantineMarkAttempt(
            msgId: qMsgId,
            nowMs: DateTime.now().millisecondsSinceEpoch,
          );
          // Fix C: retire a wire the current healthy session has superseded — it
          // can never decrypt locally; only the sender's re-encrypt (Part 1)
          // recovers its content, as a fresh msg_id (deduped by Part 2). This
          // stops replaying dead ciphertext and clears the sweep's storm trigger.
          final parkMs = (row['created_at_ms'] as num?)?.toInt() ?? 0;
          // 🔴 СТОЛБЕЦ НАЗЫВАЕТСЯ `attempts` (06.08.2026). `attempt_count` — это
          // столбец ИСХОДЯЩЕЙ очереди (`outbox`, app_db.dart:2801), а у парковки
          // его нет вовсе. Чтение по чужому имени молча давало null → 0, дальше
          // `attemptCount: 0 + 1` никогда не дотягивало до порога в 3 — то есть
          // отставка вытесненного провода не срабатывала НИ РАЗУ с момента
          // написания. Полевое подтверждение: за окно с 11 сиротами и 106
          // повторами ноль событий `quarantine_retired_superseded`.
          //
          // Ошибка тихая по устройству: `Map<String, Object?>` на неизвестный
          // ключ отвечает null, а `?? 0` превращает это в законный ноль. Тест
          // на предикат этого не ловит — он проверяет правило, а не то, какое
          // число в него приезжает.
          final attempts = (row['attempts'] as num?)?.toInt() ?? 0;
          if (quarantineWireSuperseded(
            sessionEpochMs: sessionEpochMs,
            wireParkedMs: parkMs,
            attemptCount: attempts + 1, // +1: the attempt just marked above
          )) {
            await db.inboxQuarantineDelete(qMsgId);
            retiredSuperseded++;
          }
        }
      }
      if (skippedHopeless > 0) {
        DiagLog.event('inbox', 'quarantine_replay_throttled', {
          'skipped': skippedHopeless,
          'sender_dev': DiagLog.pfx(sid),
        });
      }
      if (recovered > 0) {
        DiagLog.event('inbox', 'quarantine_recovered', {
          'sender_dev': DiagLog.pfx(sid),
          'count': recovered,
        });
        _changed.add(null);
      }
      if (retiredSuperseded > 0) {
        DiagLog.event('inbox', 'quarantine_retired_superseded', {
          'sender_dev': DiagLog.pfx(sid),
          'count': retiredSuperseded,
        });
      }
      await db.inboxQuarantinePrune(
        nowMs: DateTime.now().millisecondsSinceEpoch,
      );
    } catch (_) {
      // best-effort recovery pass
    } finally {
      _quarantineReplayInFlight.remove(sid);
    }
  }

  /// ZOMBIE-DB SELF-HEAL (2026-07-18, proven live on-device): sqflite's
  /// `singleInstance: true` shares ONE native handle per DB path, so a stray
  /// `close()` (re-init race / disposed controller / import flow) kills the
  /// live `_db` out from under the whole app. Symptom captured via USB syslog:
  /// every inbox pump fetched all pending rows then died with
  /// `DatabaseException(error_database_closed)` — empty chat + raw-id preview,
  /// forever, until the user manually restarted the app.
  ///
  /// This reopens the SAME database (never deletes, never resets the
  /// passphrase — the init-time keystore-mismatch recovery is deliberately NOT
  /// reachable from here), swaps `_db`, and kicks the pumps. Single-flight;
  /// bails if a concurrent flow (init / import / logout) already swapped or
  /// nulled `_db`.
  bool _dbReopenInFlight = false;

  Future<void> _recoverUnexpectedlyClosedDb(String from) async {
    final db = _db;
    if (db == null) return;
    // `db.isOpen` LIES with sqflite singleInstance: it stays true after another
    // reference closed the shared native handle, so this watchdog used to bail
    // here forever while every query threw error_database_closed (iPhone,
    // 2026-07-23). Probe with a REAL query instead. A caller that already
    // caught error_database_closed passes `from` starting with 'closed:' to
    // skip the probe — it has the proof.
    if (!from.startsWith('closed:')) {
      if (!await db.probeClosed()) return;
    }
    if (_dbReopenInFlight) return;
    _dbReopenInFlight = true;
    try {
      DiagLog.event('db', 'unexpected_closed_reopen', {'from': from});
      final secrets = SecureSecrets.create();
      // Strict: this watchdog runs on resume, when the DB certainly exists.
      // Minting a fresh passphrase here would open the real DB with a wrong
      // key — the exact path that produced `file is not a database`.
      final dbPass = await secrets.requireExistingDbPassphrase();
      final fresh = await AppDb.open(passphrase: dbPass);
      if (!identical(_db, db)) {
        // Init / import / logout replaced (or nulled) the handle while we were
        // reopening — theirs wins; drop ours.
        try {
          await fresh.close();
        } catch (_) {}
        return;
      }
      // Heal the OBJECT, not just our reference. RelayClient, both ratchet
      // session managers and the outgoing scheduler captured this AppDb at
      // construction and hold it for the life of the app; replacing only `_db`
      // left every one of them querying the closed handle. In the field that
      // meant `unexpected_closed_reopen_ok` in the log while the inbound pump
      // threw `database_closed` once a second and nothing — messages, receipts
      // or call signals — was applied until the app was killed.
      db.adoptConnectionFrom(fresh);
      _db = db;
      DiagLog.event('db', 'unexpected_closed_reopen_ok', {'from': from});
      _changed.add(null);
      // The drain that died on the closed handle dropped its buffered rows —
      // the relay still holds them (unacked), so a forced pump re-fetches and
      // applies everything immediately.
      _kickRelayInbox(force: true);
      _kickRelayOutbox();
    } catch (e) {
      // Keychain briefly unavailable / transient open failure: leave state as
      // is; the 3s watchdog retries. NEVER fall through to delete/reset.
      DiagLog.event('db', 'unexpected_closed_reopen_failed', {
        'from': from,
        'err': e.runtimeType.toString(),
      });
    } finally {
      _dbReopenInFlight = false;
    }
  }

  /// iOS NSE (2026-07-17): mirror the identity/config the Notification Service
  /// Extension needs to authenticate GET /v1/pending in the background, so it
  /// can pre-fetch the mailbox while iOS keeps the app asleep.
  Future<void> _syncNseConfig() async {
    if (!Platform.isIOS) return;
    final did = _deviceId;
    final pid = _profileId;
    if (did == null || pid == null || did.isEmpty || pid.isEmpty) return;
    try {
      final prefs = _prefs ?? await SharedPreferences.getInstance();
      final nextSeq = prefs.getInt(_prefsRelayNextSeqKey) ?? 1;
      final seedB64 = await DeviceKeys.create().loadIdentitySeedB64(
        profileId: pid,
        deviceId: did,
      );
      await NseConfigBridge.sync(
        deviceId: did,
        profileId: pid,
        baseUrl: relayHttpBaseUrl.toString(),
        identitySeedB64: seedB64,
        nextSeq: nextSeq,
      );
    } catch (_) {
      // Non-fatal — without the mirror the NSE just can't pre-fetch.
    }
  }

  /// iOS NSE (2026-07-17): import ciphertexts the NSE staged in the App Group
  /// while the app was asleep. Uses the same fetch-and-stage → quarantine →
  /// replay path as the Android background fetcher (no decrypt/ack here; the
  /// replay driver applies through the normal locked pipeline, deduped by
  /// inbox_seen). Clears the NSE badge hint after import.
  Future<void> _importStagedNseInbox() async {
    if (!Platform.isIOS) return;
    final db = _db;
    if (db == null) return;
    try {
      final staged = await NseConfigBridge.readStaged();
      if (staged.isEmpty) return;
      var imported = 0;
      for (final row in staged) {
        try {
          if (await db.inboxHasSeen(row.msgId)) continue;
          await db.inboxQuarantineUpsert(
            attestedFromDeviceId: row.fromDeviceId,
            msgId: row.msgId,
            senderDeviceId: null,
            ciphertextB64: row.ciphertextB64,
            nowMs: DateTime.now().millisecondsSinceEpoch,
          );
          imported++;
        } catch (_) {
          // best-effort; the relay still holds the row for the normal drain
        }
      }
      await NseConfigBridge.clearBadgeHint();
      if (imported > 0) {
        DiagLog.event('push', 'nse_staged_imported', {'count': imported});
        _changed.add(null);
      }
    } catch (_) {
      // ignore
    }
  }

  // Replay the entire quarantine (all senders). Used on relay (re)connect and
  // boot, when sessions may have healed while we were offline, and to cover
  // rows whose sender device id was unknown at park time.
  /// Сколько попыток подряд конверт должен провалить, чтобы считаться
  /// безнадёжным, и как редко его пробовать после этого.
  ///
  /// Три попытки — потому что первые две объясняются обычной жизнью: конверт
  /// мог прийти раньше своей сессии или во время её пересборки. Третья подряд
  /// уже говорит о потерянном ключе.
  static const int _quarantineHopelessAfterAttempts = 3;
  static const int _quarantineHopelessRetryMs = 60 * 60 * 1000;

  /// Рано ли пробовать этот конверт снова.
  ///
  /// 🔴 НЕ «ВЫБРОСИТЬ», А «РЕЖЕ». Конверт остаётся в карантине и однажды
  /// откроется, если сессия починится, — а раз в час он пробуется. Выбрасывать
  /// нельзя: карантин и есть то, что спасает сообщение от потери (23.07).
  @visibleForTesting
  static bool quarantineReplayTooSoonForRow(
    Map<String, Object?> row, {
    required int nowMs,
  }) {
    final attempts = (row['attempts'] as num?)?.toInt() ?? 0;
    if (attempts < _quarantineHopelessAfterAttempts) return false;
    final lastMs = (row['last_attempt_at_ms'] as num?)?.toInt() ?? 0;
    if (lastMs <= 0) return false;
    // Часы устройства могут прыгнуть назад — тогда пробуем, а не молчим вечно.
    final since = nowMs - lastMs;
    if (since < 0) return false;
    return since < _quarantineHopelessRetryMs;
  }

  bool _quarantineReplayTooSoon(
    Map<String, Object?> row, {
    required int nowMs,
  }) => quarantineReplayTooSoonForRow(row, nowMs: nowMs);

  bool _quarantineReplayAllInFlight = false;

  Future<void> _replayAllQuarantine() async {
    final db = _db;
    if (db == null) return;
    if (_quarantineReplayAllInFlight) return;
    _quarantineReplayAllInFlight = true;
    try {
      final count = await db.inboxQuarantineCountAll();
      if (count <= 0) return;
      final rows = await db.inboxQuarantineListAll(limit: 500);
      var recovered = 0;
      var skippedHopeless = 0;
      for (final row in rows) {
        // PERF(frames): this runs on relay (re)connect and boot — yield per
        // row so a 500-row replay cannot freeze startup/scroll (see the
        // per-sender replay loop above for the rationale).
        await Future<void>.delayed(Duration.zero);
        final qMsgId = (row['msg_id'] as String?)?.trim() ?? '';
        final qCipher = (row['ciphertext_b64'] as String?) ?? '';
        // ИД-1 / С-1: the relay's word on the sender survives the park.
        AttestedSenders.record(qMsgId, row['attested_from_device_id']);
        if (qMsgId.isEmpty || qCipher.isEmpty) {
          if (qMsgId.isNotEmpty) await db.inboxQuarantineDelete(qMsgId);
          continue;
        }
        // 🔴 ТА ЖЕ ПАУЗА, ЧТО И В ЗАХОДЕ ПО ОТПРАВИТЕЛЮ (15.08.2026, вечер).
        //
        // Пропуск здесь ЗАБЫЛИ, а счётчик и печать добавили — счётчик всегда
        // оставался нулём, `if` ниже не срабатывал ни разу, и этот заход
        // переигрывал ВСЮ парковку на каждое переподключение реле. Замер поля
        // сборки 522: `replay_reset_ping dev=baecdd9f failures=6` — шесть
        // мёртвых конвертов одним заходом и лечение следом.
        //
        // 🔴 УРОК: пропуск и его печать — ОДНА правка. Печать без пропуска
        // выглядит как работающая защита и молчит ровно так же, как молчала бы
        // защита, которой нечего пропускать.
        if (_quarantineReplayTooSoon(
          row,
          nowMs: DateTime.now().millisecondsSinceEpoch,
        )) {
          skippedHopeless += 1;
          // Л-2: тот же пере-NACK, что и в заходе по отправителю, — правка в
          // одном пути из двух уже стоила нам трёх замеров (урок 15.08).
          final rowSender =
              ((row['sender_device_id'] as String?) ?? '').trim();
          if (rowSender.isNotEmpty) {
            unawaited(_nackQuarantinedWireOnce(
              qMsgId,
              rowSender,
              reNackAfterMs: _quarantineHopelessRetryMs,
            ));
          }
          continue;
        }
        bool ok = false;
        try {
          ok = await _handleDelivered(
            msgId: qMsgId,
            ciphertextB64: qCipher,
            fromQuarantineReplay: true,
          );
        } catch (_) {
          ok = false;
        }
        if (ok) {
          await db.inboxQuarantineDelete(qMsgId);
          recovered++;
        } else {
          await db.inboxQuarantineMarkAttempt(
            msgId: qMsgId,
            nowMs: DateTime.now().millisecondsSinceEpoch,
          );
        }
      }
      if (recovered > 0) {
        DiagLog.event('inbox', 'quarantine_recovered_all', {
          'count': recovered,
        });
        _changed.add(null);
      }
      // Молчаливый пропуск неотличим от «не было чего пропускать»: без этой
      // строки нельзя проверить, что шторм лечения ушёл именно поэтому.
      if (skippedHopeless > 0) {
        DiagLog.event('inbox', 'quarantine_replay_throttled', {
          'skipped': skippedHopeless,
        });
      }
      await db.inboxQuarantinePrune(
        nowMs: DateTime.now().millisecondsSinceEpoch,
      );
      // Zero-loss inbound journal: TTL-prune orphans (applied rows self-delete
      // in _applyDecryptedInbound). Keep a generous 7-day window — matching the
      // relay's pending TTL — so a message still recoverable via redelivery is
      // never dropped early.
      await db.inboundJournalPrune(
        olderThanMs:
            DateTime.now().millisecondsSinceEpoch - 7 * 24 * 60 * 60 * 1000,
      );
      // Э-0 housekeeping. Both budgets live in `local_kv`, and past the relay's
      // 7-day mailbox TTL neither can influence anything: the wire they counted
      // is gone from the server.
      //
      // 🔴 `inboundDecryptFailurePrune` shipped with NO caller (found during the
      // Э-0 audit) — its `idf:` rows had been accumulating since 2026-07-22,
      // one per message that ever failed to decrypt. Hanging both here fixes
      // that leak and keeps the new `rsb:` rows from repeating it.
      final kvCutoffMs =
          DateTime.now().millisecondsSinceEpoch - 7 * 24 * 60 * 60 * 1000;
      await db.inboundDecryptFailurePrune(kvCutoffMs);
      await db.resendBudgetPrune(kvCutoffMs);
    } catch (_) {
      // best-effort
    } finally {
      _quarantineReplayAllInFlight = false;
    }
  }

  /// Pure gate for the quarantine recovery sweep's force-reset (Fix A / storm
  /// fix, 2026-07-24, docs/BUG_AUDIT.md "Разбор корня"). Returns null when a
  /// reset SHOULD fire for the peer, else a short decline reason for diagnostics.
  /// Extracted so the storm-breaking decision is unit-testable without a DB (see
  /// test/quarantine_sweep_reset_gate_test.dart).
  ///   - `offline`: an offline device can't heal and must not storm.
  ///   - `already_healed`: the live session was born AT/AFTER the oldest parked
  ///     wire, so it is fresher than the dead backlog — another reset would only
  ///     tear a HEALTHY session down (the storm). Only the sender's re-encrypt
  ///     can revive the parked ciphertext; it ages out via replay meanwhile.
  ///   - `sweep_floor`: a reset (from ANY path — the stamp is shared) fired for
  ///     this peer within [floorMs]; give the in-flight handshake time to land.
  @visibleForTesting
  static String? quarantineSweepResetDecline({
    required bool relayOnline,
    required int sessionEpochMs, // 0 = no live session
    required int oldestParkedMs,
    required int lastResetAtMs,
    required int nowMs,
    int floorMs = _quarantineSweepResetFloorMs,
  }) {
    if (!relayOnline) return 'offline';
    if (sessionEpochMs > 0 && sessionEpochMs >= oldestParkedMs) {
      return 'already_healed';
    }
    if (nowMs - lastResetAtMs < floorMs) return 'sweep_floor';
    return null;
  }

  /// Pure predicate for Fix C (2026-07-24, docs/BUG_AUDIT.md / TZ_UNDECRYPTABLE
  /// §Часть3): may a parked quarantine wire be RETIRED as superseded? True iff
  /// the live session ([sessionEpochMs] = its handshake birth stamp) is strictly
  /// newer than when the wire was parked ([wireParkedMs]) — so the session has
  /// moved past it and it can NEVER decrypt locally — AND it has been replayed at
  /// least [minAttempts] times (the re-NACK path already had its chance to tell
  /// the sender, whose re-encrypt is the only path that recovers the content, as
  /// a fresh msg_id). Retiring a dead wire loses nothing (it can never decrypt)
  /// and clears the quarantine-sweep's storm trigger. epoch 0 / non-positive
  /// stamps ⇒ never retire (the session may still heal forward onto it).
  @visibleForTesting
  static bool quarantineWireSuperseded({
    required int sessionEpochMs,
    required int wireParkedMs,
    required int attemptCount,
    int minAttempts = _quarantineSupersededRetireAttempts,
  }) {
    if (sessionEpochMs <= 0 || wireParkedMs <= 0) return false;
    if (sessionEpochMs <= wireParkedMs) return false;
    return attemptCount >= minAttempts;
  }

  /// FIX D — durable periodic self-healing recovery sweep.
  ///
  /// Runs every [_quarantineRecoverySweepInterval]. For each peer device that
  /// has NON-EMPTY quarantine whose OLDEST parked entry is older than
  /// [_quarantineRecoveryMinAgeMs], it (a) force-re-pings the session reset
  /// (bypassing the debounce — the earlier ping was likely lost in transit),
  /// (b) forces ONE peer device-list refresh (the peer may have rotated its
  /// device_id after a reinstall), then finally (c) replays the whole
  /// quarantine. This heals delivery WITHOUT waiting for a relay reconnect or
  /// for an (impossible, while the session is broken) successful decrypt.
  ///
  /// (Fix A, 2026-07-24: step (a) is now gated by [quarantineSweepResetDecline];
  /// step (c) retires superseded wires via [quarantineWireSuperseded].)
  ///
  /// Every step is best-effort / try-guarded — this must NEVER throw into the
  /// periodic Timer. It can never lose data: it only re-pings, refreshes, and
  /// replays; the parked ciphertext is untouched until a replay succeeds.
  Future<void> _runQuarantineRecoverySweep() async {
    if (_quarantineRecoverySweepRunning) return;
    final db = _db;
    if (db == null) return;
    _quarantineRecoverySweepRunning = true;
    try {
      // A1 ZERO-LOSS backstop: prune expired parked frames and re-apply any
      // whose sender has since become a member. Runs every sweep, independent of
      // the ciphertext-quarantine recovery below (which early-returns when the
      // quarantine is empty) — this is what guarantees a parked frame is never
      // lost regardless of which membership path eventually converged.
      try {
        await _flushAndPruneDeferredRoomInbound(db);
      } catch (_) {
        // best-effort — retried on the next sweep tick
      }
      if (!roomMissedResendEnabled) {
        // К-3 выключен: конверты с открытым текстом хранить незачем.
        try {
          await db.roomOutboundEnvelopesClear();
        } catch (_) {}
      }
      List<Map<String, Object?>> senders;
      try {
        senders = await db.inboxQuarantineSendersWithOldest();
      } catch (_) {
        return;
      }
      if (senders.isEmpty) return;
      final nowMs = DateTime.now().millisecondsSinceEpoch;
      final relayOnline = _relayOnline || _relayHttpReachable;
      var nudged = 0;
      for (final row in senders) {
        final sid = ((row['sender_device_id'] as String?) ?? '').trim();
        if (sid.isEmpty) continue;
        final oldestMs = (row['oldest_ms'] as num?)?.toInt() ?? nowMs;
        // Only act on genuinely STUCK peers — give the normal replay-on-decrypt
        // / debounced-ping fast path a grace window first.
        if (nowMs - oldestMs < _quarantineRecoveryMinAgeMs) continue;
        nudged++;
        // (a) force a fresh session-reset ping — but ONLY when it can actually
        // help. STORM FIX (2026-07-24, docs/BUG_AUDIT.md "Разбор корня"): this
        // used to force-reset EVERY 90 s unconditionally, tearing down even a
        // just-healed session, so two peers with dead parked backlog reset each
        // other forever — the backlog is the trigger and NO reset can decrypt it
        // (only the sender's re-encrypt can). Three gates, cheapest first:
        //   1. only while we are actually online (an offline device can't heal
        //      and must not storm — mirrors the silence sweep's reachability gate);
        //   2. skip if the live session was already born AT/AFTER this backlog
        //      (epoch >= oldest) — it is healed; the parked wires are just old
        //      dead ciphertext aging out via replay / sender-resend;
        //   3. otherwise bound the cadence with a per-device floor via the SHARED
        //      _sessionResetPingAtMs stamp, so this slow backstop and the
        //      reactive / escalator / convergence reset paths can never double-fire.
        if (relayOnline) {
          var epoch = 0;
          try {
            epoch = await db.sessionV3EpochFor(sid);
          } catch (_) {
            epoch = 0;
          }
          final decline = quarantineSweepResetDecline(
            relayOnline: true,
            sessionEpochMs: epoch,
            oldestParkedMs: oldestMs,
            lastResetAtMs: _sessionResetPingAtMs[sid] ?? 0,
            nowMs: nowMs,
          );
          if (decline == null) {
            try {
              _forceSessionResetPing(sid, _resetCauseQuarantineStuck);
            } catch (_) {
              // never let one peer's failure abort the sweep
            }
          } else {
            _recoveryDeclined('reset_ping', decline, deviceId: sid);
          }
        }
        // relayOnline == false → skip the reset silently (the whole sweep is
        // offline; it can't heal anything and must not storm). (b)/(c) below
        // still run — they are harmless refresh + replay.
        // (b) force ONE peer device-list refresh (throttled internally to once
        // per 30 s/peer) so outbound stops targeting a rotated/dead device.
        try {
          final pid = await _resolveProfileIdForDevice(sid);
          if (pid != null &&
              pid.isNotEmpty &&
              !pid.startsWith('group:') &&
              !pid.startsWith('dev:')) {
            await _refreshContactDevicesForVerification(pid);
          }
        } catch (_) {
          // best-effort — profile/device refresh failures heal on a later tick
        }
      }
      if (nudged > 0) {
        DiagLog.event('inbox', 'quarantine_recovery_sweep', {
          'stuck_peers': nudged,
        });
      }
      // (c) replay the whole quarantine — covers rows whose sender was unknown
      // at park time and any session that healed since the last pass.
      try {
        await _replayAllQuarantine();
      } catch (_) {
        // best-effort
      }

    } catch (_) {
      // best-effort — the sweep must never throw into the Timer
    } finally {
      _quarantineRecoverySweepRunning = false;
    }
  }

  /// Seals a room message under this sender's room key, or returns null to let
  /// the caller send it the way it always has.
  ///
  /// 🔑 FALLING BACK IS THE POINT. Whenever anything is not ready — a member
  /// still owed the key, an unresolvable device list, a rotation that overtook
  /// us — this returns null and the ordinary pairwise fanout carries the
  /// message. The feature can therefore only ever make a send cheaper, never
  /// slower and never lost. The TZ's §6.4 "queue the message" is the right rule
  /// once this is the only path; while both exist, delaying a message to wait
  /// for a key would invent a failure mode that does not exist today.
  ///
  /// The key still travels BEFORE the message it protects (§7, corrected): a
  /// member handed the key afterwards could never read what was already sent,
  /// because the chain only ratchets forward.
  /// К-2 (17.09.2026): отдать запечатанное сообщение комнаты реле ОДНИМ
  /// запросом — тем устройствам, что подтвердили сырой провод для текущего
  /// поколения. Возвращает, какие устройства каждого участника ещё ждут
  /// попарной копии (пустой список — участник обслужен целиком), или null —
  /// рассылка не применялась, и отправка идёт как раньше.
  ///
  /// Любая неудача — null: сообщение уходит обычным путём, потерь нет.
  Future<Map<String, List<String>>?> _roomRawBroadcast({
    required AppDb db,
    required String roomId,
    required List<E2eEventV1>? events,
    required List<String> recipients,
    required String? transportMetaJson,
    required String localEventId,
    int deliverAtMs = 0,
  }) async {
    if (!_rooms2Flags.rawBroadcastEnabled) return null;
    final relay = _relay;
    final myDid = (_deviceId ?? '').trim();
    if (relay == null || myDid.isEmpty || events == null || events.length != 1) {
      return null;
    }
    final sealed = events.single;
    if (sealed is! RoomMessageEventV1 || sealed.signature == null) return null;
    try {
      final ready = await db.roomKeyRawReadyDevices(
        roomId: roomId,
        epoch: sealed.epoch,
      );
      if (ready.isEmpty) return null;
      final devicesByMember = <String, List<String>>{};
      final targets = <String>{};
      for (final member in recipients) {
        final devices = (await _listRecipientDevicesForSend(
          peerProfileId: member,
          selfDeviceId: myDid,
        ))
            .where((d) => d.isNotEmpty && d != myDid)
            .toList(growable: false);
        devicesByMember[member] = devices;
        targets.addAll(devices.where(ready.contains));
      }
      if (targets.isEmpty) return null;
      final accepted = await relay.broadcastRoomWire(
        roomId: roomId,
        msgId: _uuid.v4(),
        ciphertextB64: base64Encode(RoomRawWire.encode(sealed)),
        recipients: targets.toList(growable: false),
        ttlSeconds: _outboxUserMessageTtlSeconds,
        deliverAtMs: deliverAtMs,
        transportMetaJson: transportMetaJson,
      );
      if (accepted.isEmpty) return null;
      if (deliverAtMs <= 0) {
        // Реле уже приняло: сбой записи статуса не должен превращаться в
        // попарную рассылку того же сообщения (у получателей был бы дубль).
        try {
          await db.updateEventLocalState(
            eventId: localEventId,
            localState: 'sent',
          );
        } catch (_) {}
      }
      DiagLog.event('room_key', 'raw_broadcast', {
        'room': DiagLog.pfx(roomId),
        'accepted': accepted.length,
        'of': targets.length,
      });
      return <String, List<String>>{
        for (final entry in devicesByMember.entries)
          entry.key: entry.value
              .where((d) => !accepted.contains(d))
              .toList(growable: false),
      };
    } catch (e) {
      DiagLog.event('room_key', 'raw_broadcast_failed', {
        'room': DiagLog.pfx(roomId),
        'reason': _classifyShortReason(e),
      });
      return null;
    }
  }

  Future<List<E2eEventV1>?> _sealRoomMessageForSenderKey({
    required AppDb db,
    required String roomId,
    required String controlText,
    required int createdAtMs,
    required List<String> memberProfileIds,
  }) async {
    // SEND side: this is the rollout flag. Off ⇒ null ⇒ the ordinary pairwise
    // fanout carries the message, which every build can read.
    if (!roomSenderKeySendEnabled) return null;
    final myDid = (_deviceId ?? '').trim();
    if (myDid.isEmpty) return null;

    try {
      // Every device that must be able to read this room: each member's, plus
      // my OWN other devices — otherwise I could not read myself.
      final deviceToProfile = <String, String>{};
      for (final pid in memberProfileIds) {
        final devices = await _listRecipientDevicesForSend(
          peerProfileId: pid,
          selfDeviceId: myDid,
        );
        for (final d in devices) {
          if (d.isNotEmpty && d != myDid) deviceToProfile[d] = pid;
        }
      }
      final myPid = (_profileId ?? '').trim();
      for (final d in _ownDeviceIdsForUnreadQueries()) {
        if (d.isNotEmpty && d != myDid) deviceToProfile[d] = myPid;
      }
      if (deviceToProfile.isEmpty) return null;

      final mgr = RoomKeyManager(db);
      final outcome = await mgr.prepareSend(
        roomId: roomId,
        myDeviceId: myDid,
        memberDeviceIds: deviceToProfile.keys,
        nowMs: createdAtMs,
      );

      if (outcome is RoomSendBlocked) {
        // Hand the key out now so the NEXT message can use it, and let this one
        // go the old way. Deliberately not awaited into the send path: the
        // message must not wait on key delivery.
        DiagLog.event('room_key', 'send_blocked_delivering_key', {
          'room': DiagLog.pfx(roomId),
          'owed': outcome.awaitingKey.length,
          'rotated': outcome.rotatedReason ?? '-',
        });
        unawaited(
          _deliverRoomKeyTo(
            db: db,
            roomId: roomId,
            devices: outcome.awaitingKey,
            deviceToProfile: deviceToProfile,
          ),
        );
        return null;
      }

      final slot = (outcome as RoomSendReady).slot;
      final inner = E2ePayloadV1(
        senderDeviceId: myDid,
        createdAtMs: createdAtMs,
        events: [MsgEventV1(eventId: _uuid.v4(), text: controlText)],
      );
      final box = await RoomKeyChain.encrypt(
        messageKey: slot.messageKey,
        plaintext: Uint8List.fromList(inner.encode()),
        aad: slot.aad,
      );
      final sealedNonce = base64Decode(box.nonceB64);
      final sealedCiphertext = base64Decode(box.ciphertextB64);
      // К-1 (17.09.2026): подпись автора — без неё любой участник, держащий
      // цепочку, мог бы запечатать сообщение «от меня».
      final signingSeed = slot.signingSeed;
      final signature = signingSeed == null
          ? null
          : await RoomMessageSignature.sign(
              seed: signingSeed,
              aad: slot.aad,
              nonce: sealedNonce,
              ciphertext: sealedCiphertext,
            );
      // Advance the chain BEFORE the caller sends anything, and only once the
      // ciphertext exists.
      //
      // The order is what makes a crash harmless. Committing first and dying
      // before the fanout merely WASTES a position — no member ever saw it, and
      // the receiver's skipped-key machinery walks over it. Sending first and
      // dying before the commit would REUSE the position for the next message:
      // the receiver opens whichever arrives first and can never open the
      // other, which is a silently lost message. Wasting is always the cheaper
      // mistake, so the commit stays ahead of the send.
      //
      // If a rotation overtook this slot, the position it reserved no longer
      // belongs to the live generation — drop the ciphertext and fall back
      // rather than sending something no member can open.
      if (!await mgr.commitSend(slot: slot)) {
        DiagLog.event('room_key', 'send_slot_superseded', {
          'room': DiagLog.pfx(roomId),
          'epoch': slot.epoch,
        });
        return null;
      }
      DiagLog.event('room_key', 'sealed_once', {
        'room': DiagLog.pfx(roomId),
        'epoch': slot.epoch,
        'counter': slot.counter,
        'devices': deviceToProfile.length,
      });
      return [
        RoomMessageEventV1(
          roomId: roomId,
          epoch: slot.epoch,
          counter: slot.counter,
          nonce: sealedNonce,
          ciphertext: sealedCiphertext,
          signature: signature,
        ),
      ];
    } catch (e) {
      // Any failure here means "send it the old way" — never "do not send".
      DiagLog.event('room_key', 'seal_failed', {
        'room': DiagLog.pfx(roomId),
        'reason': _classifyShortReason(e),
      });
      return null;
    }
  }

  /// Tells the key's author that we applied it (F-ROOMSK-3/4).
  ///
  /// Gated on RECEIVE, not send: acking is something a reader does for itself,
  /// and a build that never sends must still be able to prove it can read —
  /// that proof is the whole coexistence mechanism.
  Future<void> _sendRoomKeyAck({
    required String roomId,
    required String authorDeviceId,
    required String? authorProfileId,
    required int epoch,
  }) async {
    if (!roomSenderKeyReceiveEnabled) return;
    final db = _db;
    if (db == null) return;
    final pid = (authorProfileId ?? '').trim().isNotEmpty
        ? authorProfileId!.trim()
        : ((await db.deviceProfileCached(authorDeviceId))?.trim() ?? '');
    if (pid.isEmpty) {
      DiagLog.event('room_key', 'ack_no_author', {
        'room': DiagLog.pfx(roomId),
        'dev': DiagLog.pfx(authorDeviceId),
      });
      return;
    }
    try {
      await sendControlMessage(
        peerProfileId: pid,
        controlText: '',
        // К-2: this build also takes the relay-fanned raw room wire (`SKR1`).
        overrideEvents: [
          RoomKeyAckEventV1(roomId: roomId, epoch: epoch, rawV1: true),
        ],
        targetDeviceIds: <String>[authorDeviceId],
        queueIfNoDevices: true,
        // The ack is worth exactly as much as the key it confirms: until it
        // lands the author must keep the room on the pairwise path. So it gets
        // the MESSAGE ttl, not the 1-hour control ttl — an author who is offline
        // for an afternoon must still learn we are keyed.
        ttlSeconds: _outboxUserMessageTtlSeconds,
      );
      DiagLog.event('room_key', 'ack_sent', {
        'room': DiagLog.pfx(roomId),
        'to': DiagLog.pfx(authorDeviceId),
        'epoch': epoch,
      });
    } catch (e) {
      DiagLog.event('room_key', 'ack_failed', {
        'room': DiagLog.pfx(roomId),
        'reason': _classifyShortReason(e),
      });
    }
  }

  /// Asks the author to re-issue the room key — but only once the same
  /// generation has been missed [_roomKeyRequestThreshold] times in a row.
  ///
  /// A single miss means nothing: the key and the message travel over two
  /// different pairwise sessions and routinely overtake each other. Asking on
  /// the first miss would turn every ordinary race into a burst of requests
  /// across the whole room. A member who keeps missing the SAME generation is
  /// the one that is genuinely unkeyed, and they recover in seconds.
  Future<void> _maybeRequestRoomKey({
    required AppDb db,
    required String roomId,
    required String authorDeviceId,
    required String? authorProfileId,
    required int epoch,
    required int now,
  }) async {
    // RECEIVE side: asking for a key we are missing is how a reader repairs
    // itself. It must not depend on whether WE are allowed to send.
    if (!roomSenderKeyReceiveEnabled) return;

    // 🔴 DO NOT BEG FOR A KEY TO A ROOM WE LEFT (2026-07-31, field: the user
    // left AND deleted a room, and the app kept asking its author for the key
    // every few minutes).
    //
    // Deleting a room removes the conversation, but parked wires for it survive
    // in the inbox quarantine — and every replay of one re-enters this path. So
    // the client kept requesting a key it has no use for, the author kept
    // answering, and we kept acknowledging: a three-message exchange, forever,
    // about a room that no longer exists on this device. The wires themselves
    // can never open anyway (their generation moved on), so there is nothing to
    // lose by staying quiet.
    //
    // Membership, not existence: a room we are still in but whose roster is
    // momentarily empty must keep asking, or a legitimate member could silence
    // itself during a sync.
    try {
      final members = await db.groupMembersList(roomId);
      if (members.isEmpty) {
        DiagLog.event('room_key', 'request_skipped_not_a_member', {
          'room': DiagLog.pfx(roomId),
        });
        return;
      }
    } catch (_) {
      // Unknown membership ⇒ behave as before and ask; a storage hiccup must
      // not cost a member their key.
    }

    final key = '$roomId|$authorDeviceId|$epoch';
    final streak = (_roomKeyMissStreak[key] ?? 0) + 1;
    _roomKeyMissStreak[key] = streak;
    if (streak < _roomKeyRequestThreshold) return;

    final last = _roomKeyRequestedAtMs[key] ?? 0;
    if (now - last < _roomKeyRequestDebounceMs) return;
    _roomKeyRequestedAtMs[key] = now;

    final pid = (authorProfileId ?? '').trim().isNotEmpty
        ? authorProfileId!.trim()
        : ((await db.deviceProfileCached(authorDeviceId))?.trim() ?? '');
    if (pid.isEmpty) {
      DiagLog.event('room_key', 'request_no_author', {
        'room': DiagLog.pfx(roomId),
        'dev': DiagLog.pfx(authorDeviceId),
      });
      return;
    }
    try {
      await sendControlMessage(
        peerProfileId: pid,
        controlText: '',
        overrideEvents: [RoomKeyRequestEventV1(roomId: roomId, epoch: epoch)],
        targetDeviceIds: <String>[authorDeviceId],
        queueIfNoDevices: true,
      );
      DiagLog.event('room_key', 'key_request_sent', {
        'room': DiagLog.pfx(roomId),
        'to': DiagLog.pfx(authorDeviceId),
        'epoch': epoch,
        'after_misses': streak,
      });
    } catch (e) {
      DiagLog.event('room_key', 'key_request_failed', {
        'room': DiagLog.pfx(roomId),
        'reason': _classifyShortReason(e),
      });
    }
  }

  /// Hands the current room key to [devices], one pairwise envelope each, and
  /// records the delivery so it is not sent again for this generation.
  Future<void> _deliverRoomKeyTo({
    required AppDb db,
    required String roomId,
    required List<String> devices,
    required Map<String, String> deviceToProfile,
  }) async {
    final mgr = RoomKeyManager(db);
    final grant = await mgr.keyGrantFor(roomId: roomId);
    if (grant == null) return;
    final now = DateTime.now().millisecondsSinceEpoch;
    // 17.09.2026: ключ комнаты — только устройствам, заявившим `rk2`.
    // Выпущенные сборки его не получают вовсе: их приём ключа живым трафиком
    // не проверялся, а совсем старые записали бы непонятный провод пустым
    // чатом. Комната с такими устройствами остаётся на попарной рассылке.
    final capable = await db.deviceIdsWithCap(
      deviceIds: devices,
      cap: E2ePayloadV1.capRoomKeyV2,
    );
    // Grouped per profile because the send path addresses a profile and takes
    // the devices to target, and one member may have several.
    final byProfile = <String, List<String>>{};
    for (final d in devices.where(capable.contains)) {
      final pid = (deviceToProfile[d] ?? '').trim();
      if (pid.isEmpty) continue;
      byProfile.putIfAbsent(pid, () => <String>[]).add(d);
    }
    for (final entry in byProfile.entries) {
      try {
        await sendControlMessage(
          peerProfileId: entry.key,
          controlText: '',
          overrideEvents: [
            RoomKeyEventV1(
              roomId: roomId,
              epoch: grant.epoch,
              counter: grant.counter,
              chainKey: grant.chainKey,
              issuedAtMs: now,
              signingPub: grant.signingPub,
            ),
          ],
          targetDeviceIds: entry.value,
          queueIfNoDevices: true,
          // 🔴 The MESSAGE ttl (7 days), not the control ttl (1 hour). A key is
          // not chatter — it is the thing without which the room's messages do
          // not open. At the control ttl a member offline for an hour would
          // lose the key while the messages it protects sit in their mailbox
          // for a week, and the room would simply stop working for them.
          // Matches the relay's own mailbox retention, so the key lives exactly
          // as long as anything it can open.
          ttlSeconds: _outboxUserMessageTtlSeconds,
        );
        // Marked on ENQUEUE, not on acknowledgement: once it is in the outbox
        // the relay redelivers until acked, so re-sending the key on every
        // message would be pure waste. A member who genuinely never gets it
        // asks with `gkeyreq`.
        for (final d in entry.value) {
          await db.roomKeyDeliveryMark(
            roomId: roomId,
            peerDeviceId: d,
            epoch: grant.epoch,
            deliveredAtMs: now,
          );
        }
      } catch (e) {
        DiagLog.event('room_key', 'grant_send_failed', {
          'room': DiagLog.pfx(roomId),
          'peer': DiagLog.pfx(entry.key),
          'reason': _classifyShortReason(e),
        });
      }
    }
  }

  /// What happened to one room-key wire, in the only terms that matter for
  /// whether it is acknowledged or parked.
  ///
  /// Getting this backwards is expensive in both directions: acknowledging a
  /// wire we could still open loses the message permanently, while parking one
  /// we can never open replays it forever.
  static bool roomWireShouldPark(RoomWireOutcome outcome) {
    switch (outcome) {
      // Recoverable — the key may still arrive (`gkeyreq` asks for it), so keep
      // the wire.
      case RoomWireOutcome.noKeyYet:
      case RoomWireOutcome.innerNotApplied:
      case RoomWireOutcome.storeError:
        return true;
      // Unrecoverable — a replay would fail identically, so stop replaying.
      case RoomWireOutcome.tagFailed:
      case RoomWireOutcome.innerMalformed:
      case RoomWireOutcome.applied:
      case RoomWireOutcome.nested:
      case RoomWireOutcome.noSender:
        return false;
    }
  }

  /// Applies `gkey` / `gmsg` / `gkeyreq` (фаза 3). Returns true when everything in [events] was applied — false
  /// PARKS the wire for a later replay rather than acknowledging it away.
  ///
  /// The receive side ships before the send side on purpose: a client must be
  /// able to read the new format before any client emits it, or the first
  /// message of every upgrading room is lost.
  Future<bool> _handleRoomKeyWires({
    required AppDb db,
    required List<E2eEventV1> events,
    required String? senderDeviceId,
    required String? senderProfileId,
    required String msgId,
    required int now,
    required int depth,
    bool senderAttested = false,
  }) async {
    // A `gmsg` opens to an ordinary payload which we re-enter. One level is all
    // the design ever needs; anything deeper is a wire trying to make us work.
    if (depth > 0) {
      DiagLog.event('room_key', 'nested_envelope_dropped', {'depth': depth});
      return !roomWireShouldPark(RoomWireOutcome.nested);
    }
    final sdid = (senderDeviceId ?? '').trim();
    if (sdid.isEmpty) {
      DiagLog.event('room_key', 'wire_without_sender', {'msg': DiagLog.pfx(msgId)});
      return !roomWireShouldPark(RoomWireOutcome.noSender);
    }
    final mgr = RoomKeyManager(db);
    var allApplied = true;

    for (final event in events) {
      if (event is RoomKeyEventV1) {
        // A key handed to us over the pairwise channel. Idempotent: a repeat of
        // a generation we already hold is ignored, which is what makes the
        // `gkeyreq` recovery safe to fire freely.
        try {
          final accepted = await mgr.acceptKeyGrant(
            roomId: event.roomId,
            senderDeviceId: sdid,
            epoch: event.epoch,
            counter: event.counter,
            chainKey: event.chainKey,
            nowMs: now,
            signingPub: event.signingPub,
          );
          DiagLog.event('room_key', 'grant_applied', {
            'room': DiagLog.pfx(event.roomId),
            'from': DiagLog.pfx(sdid),
            'epoch': event.epoch,
            'fresh': accepted,
          });
          // Tell the author we can actually USE it (F-ROOMSK-3/4). Sent on a
          // repeat grant too, not just a fresh one: the ack is the author's
          // ONLY evidence, and if theirs was lost the repeat is exactly when
          // they need it again. Not awaited — a failed ack must never turn a
          // successfully applied key into a parked wire; the author re-issues
          // on its own schedule and we will ack that one.
          unawaited(
            _sendRoomKeyAck(
              roomId: event.roomId,
              authorDeviceId: sdid,
              authorProfileId: senderProfileId,
              epoch: event.epoch,
            ),
          );
        } catch (e) {
          DiagLog.event('room_key', 'grant_failed', {
            'room': DiagLog.pfx(event.roomId),
            'reason': _classifyShortReason(e),
          });
          allApplied = false;
        }
        continue;
      }

      if (event is RoomKeyRequestEventV1) {
        // "I cannot open your room traffic." Re-issuing is the whole cure and is
        // idempotent on their side, so this can be answered freely — debounced
        // only so a member stuck in a loop cannot make us spin.
        final key = '${event.roomId}|$sdid';
        final last = _roomKeyReissuedAtMs[key] ?? 0;
        final due = now - last >= _roomKeyReissueDebounceMs;
        DiagLog.event('room_key', 'key_requested', {
          'room': DiagLog.pfx(event.roomId),
          'from': DiagLog.pfx(sdid),
          'epoch': event.epoch,
          'answering': due,
        });
        if (due) {
          _roomKeyReissuedAtMs[key] = now;
          final pid = (senderProfileId ?? '').trim().isNotEmpty
              ? senderProfileId!.trim()
              : ((await db.deviceProfileCached(sdid))?.trim() ?? '');
          if (pid.isNotEmpty) {
            // Always the CURRENT generation, not the one they named: if we have
            // rotated since, the old one is exactly what they must not get.
            unawaited(
              _deliverRoomKeyTo(
                db: db,
                roomId: event.roomId,
                devices: <String>[sdid],
                deviceToProfile: <String, String>{sdid: pid},
              ),
            );
          }
        }
        continue;
      }

      if (event is RoomKeyAckEventV1) {
        // A member confirmed they applied our key. This is the evidence
        // `recipientsMissingKey` waits for before we may seal anything for
        // them. Scoped to a row we actually created (the UPDATE matches
        // nothing otherwise), so a peer cannot mark ITSELF as keyed.
        try {
          await db.roomKeyDeliveryConfirm(
            roomId: event.roomId,
            peerDeviceId: sdid,
            epoch: event.epoch,
            confirmedAtMs: now,
          );
          if (event.rawV1) {
            await db.roomKeyRawConfirm(
              roomId: event.roomId,
              peerDeviceId: sdid,
              epoch: event.epoch,
            );
          }
          DiagLog.event('room_key', 'grant_confirmed', {
            'room': DiagLog.pfx(event.roomId),
            'from': DiagLog.pfx(sdid),
            'epoch': event.epoch,
          });
        } catch (e) {
          DiagLog.event('room_key', 'grant_confirm_failed', {
            'room': DiagLog.pfx(event.roomId),
            'reason': _classifyShortReason(e),
          });
          allApplied = false;
        }
        continue;
      }

      if (event is RoomMessageEventV1) {
        final applied = await _applyRoomSenderKeyMessage(
          db: db,
          mgr: mgr,
          event: event,
          senderDeviceId: sdid,
          senderProfileId: senderProfileId,
          msgId: msgId,
          now: now,
          senderAttested: senderAttested,
        );
        if (!applied) allApplied = false;
        continue;
      }
    }
    return allApplied;
  }

  /// Opens one `gmsg` and hands the payload inside it to the ordinary inbound
  /// path — the room envelope within is an unchanged `E2ePayloadV1`, so every
  /// existing feature (text, attachments, reactions, replies, mentions) keeps
  /// working without knowing this format exists.
  ///
  /// Returns false to PARK: a message we cannot open yet is not a message we
  /// should acknowledge away.
  Future<bool> _applyRoomSenderKeyMessage({
    required AppDb db,
    required RoomKeyManager mgr,
    required RoomMessageEventV1 event,
    required String senderDeviceId,
    required String? senderProfileId,
    required String msgId,
    required int now,
    bool senderAttested = false,
  }) async {
    RoomRecvSlot? slot;
    try {
      slot = await mgr.openInbound(
        roomId: event.roomId,
        senderDeviceId: senderDeviceId,
        epoch: event.epoch,
        counter: event.counter,
      );
    } catch (e) {
      DiagLog.event('room_key', 'open_failed', {
        'room': DiagLog.pfx(event.roomId),
        'reason': _classifyShortReason(e),
      });
      return !roomWireShouldPark(RoomWireOutcome.storeError);
    }
    if (slot == null) {
      // Уже открытая позиция — копия прочитанного сообщения (дубль после сбоя
      // рассылки одним запросом, повтор реле). Ключа не будет никогда: не
      // паркуем и ключ не просим, иначе копия стопорит ящик и крутит gkeyreq.
      var spent = false;
      try {
        spent = await mgr.isSpentPosition(
          roomId: event.roomId,
          senderDeviceId: senderDeviceId,
          epoch: event.epoch,
          counter: event.counter,
        );
      } catch (_) {}
      if (spent) {
        DiagLog.event('room_key', 'duplicate_wire_dropped', {
          'room': DiagLog.pfx(event.roomId),
          'from': DiagLog.pfx(senderDeviceId),
          'epoch': event.epoch,
          'counter': event.counter,
        });
        return true;
      }
      // No key for this generation yet, or a position the chain already
      // consumed. The first is recoverable — ask the author — and the second is
      // a replay we must refuse. Park either way; `gkeyreq` is фаза 3b.
      DiagLog.event('room_key', 'no_key_for_wire', {
        'room': DiagLog.pfx(event.roomId),
        'from': DiagLog.pfx(senderDeviceId),
        'epoch': event.epoch,
        'counter': event.counter,
      });
      unawaited(
        _maybeRequestRoomKey(
          db: db,
          roomId: event.roomId,
          authorDeviceId: senderDeviceId,
          authorProfileId: senderProfileId,
          epoch: event.epoch,
          now: now,
        ),
      );
      return !roomWireShouldPark(RoomWireOutcome.noKeyYet);
    }

    // К-1: this generation came with a signing key, so the author signs every
    // message — an unsigned or badly signed one is a forgery by someone else
    // who holds the chain. Not a missing key: never parked, key not consumed.
    final signingPub = slot.signingPub;
    if (signingPub != null) {
      final sig = event.signature;
      final signedOk =
          sig != null &&
          await RoomMessageSignature.verify(
            publicKey: signingPub,
            signature: sig,
            aad: slot.aad,
            nonce: event.nonce,
            ciphertext: event.ciphertext,
          );
      if (!signedOk) {
        DiagLog.event('room_key', 'signature_failed', {
          'room': DiagLog.pfx(event.roomId),
          'from': DiagLog.pfx(senderDeviceId),
          'epoch': event.epoch,
          'present': sig != null,
        });
        return !roomWireShouldPark(RoomWireOutcome.tagFailed);
      }
    }

    final plain = await RoomKeyChain.decrypt(
      messageKey: slot.messageKey,
      nonceB64: base64Encode(event.nonce),
      ciphertextB64: base64Encode(event.ciphertext),
      aad: slot.aad,
    );
    if (plain == null) {
      // The tag failed: wrong room, wrong generation, wrong position or a
      // tampered wire. NOT a missing key — replaying it would fail identically,
      // so acknowledge it instead of parking it forever.
      DiagLog.event('room_key', 'tag_failed', {
        'room': DiagLog.pfx(event.roomId),
        'from': DiagLog.pfx(senderDeviceId),
        'epoch': event.epoch,
      });
      return !roomWireShouldPark(RoomWireOutcome.tagFailed);
    }

    E2ePayloadV1 inner;
    try {
      inner = E2ePayloadV1.decode(plain);
    } catch (e) {
      DiagLog.event('room_key', 'inner_payload_bad', {
        'room': DiagLog.pfx(event.roomId),
        'reason': _classifyShortReason(e),
      });
      // Consuming the key anyway: the wire is authentic (the tag verified) but
      // malformed, and no replay will make it parse.
      await mgr.commitInbound(slot: slot, nowMs: now);
      return !roomWireShouldPark(RoomWireOutcome.innerMalformed);
    }

    final applied = await _handleDecryptedInboundPayload(
      db: db,
      msgId: msgId,
      ciphertextB64: base64Encode(event.ciphertext),
      plainBytes: plain,
      payload: inner,
      now: now,
      // The AAD bound this ciphertext to its author, so the inner payload is
      // attributed to the SAME device — an inner claim cannot override it.
      senderDeviceId: senderDeviceId,
      senderProfileId: senderProfileId,
      roomKeyWireDepth: 1,
      senderAttested: senderAttested,
    );
    if (!applied) return !roomWireShouldPark(RoomWireOutcome.innerNotApplied);

    // Opening proves we are keyed for this generation, so the miss streak that
    // drives `gkeyreq` starts over. Without this a single early race would keep
    // the counter armed and the next miss, months later, would ask instantly.
    _roomKeyMissStreak.remove('${event.roomId}|$senderDeviceId|${event.epoch}');

    // Only now consume the key: committing first would destroy it for a message
    // that failed to apply, and a straggler key is single-use.
    await mgr.commitInbound(slot: slot, nowMs: now);
    return true;
  }

  Future<bool> _handleDecryptedInboundPayload({
    required AppDb db,
    required String msgId,
    required String ciphertextB64,
    required Uint8List plainBytes,
    required E2ePayloadV1 payload,
    required int now,
    String? senderDeviceId,
    String? senderProfileId,
    // Фаза 3: how deep we already are inside a room-key envelope. A `gmsg`
    // opens to an ordinary payload which we re-enter here, so this bounds that
    // recursion — a wire that nests envelopes must not be able to spin the CPU.
    int roomKeyWireDepth = 0,
    // A1 ZERO-LOSS: set when re-applying a frame from the deferred-inbound park.
    // In that mode the stale-membership branch must NEVER re-park (drop instead)
    // to avoid a park→replay→park loop.
    bool fromDeferredReplay = false,
    // ИД-1 / С-3: the relay named this sender and the name matched the wire.
    bool senderAttested = false,
  }) async {
    final crypto = _crypto;
    final did = _deviceId;
    final allEvents = payload.events;

    // С-3, режим наблюдения (17.09.2026): служебные команды «от своего
    // устройства» без подтверждения реле пока принимаются, как раньше, но
    // считаются. Когда счётчик у обновлённых сборок станет нулём, отказ
    // включается.
    final ownSenderDid = (senderDeviceId ?? '').trim();
    if (!senderAttested &&
        ownSenderDid.isNotEmpty &&
        ownSenderDid != (did ?? '').trim() &&
        isOwnDeviceId(ownSenderDid)) {
      final controls = allEvents
          .whereType<MsgEventV1>()
          .where((e) => isHiddenMessageControlText(e.text))
          .length;
      if (controls > 0) {
        DiagLog.event('inbox', 'own_cmd_unattested', {
          'sender_dev': DiagLog.pfx(ownSenderDid),
          'controls': controls,
          'replay': fromDeferredReplay,
        });
      }
    }

    // ROOM SENDER KEY (фаза 2).
    // `gkey` / `gkeyreq` / `gmsg` are room-key transport, never timeline
    // entries. The storage path near the end of this method falls back to
    // `firstEvent ??= allEvents.first`, so without this guard a key-carrying
    // payload would be stored as a conversation — a ghost chat with an empty
    // preview, in a room the user may not even see.
    //
    bool isRoomKeyWire(E2eEventV1 e) =>
        e is RoomKeyEventV1 ||
        e is RoomKeyRequestEventV1 ||
        e is RoomKeyAckEventV1 ||
        e is RoomMessageEventV1;
    if (allEvents.isNotEmpty && allEvents.every(isRoomKeyWire)) {
      // Фаза 3: real handling, behind the flag.
      //
      // Returning FALSE when we cannot apply it keeps the zero-loss journal
      // copy, so a wire this build cannot use is PARKED for replay rather than
      // acknowledged and discarded — which is what makes it safe to ship the
      // receive side before anyone sends.
      // RECEIVE side, and the whole point of the split: a build holding this
      // code opens the wire regardless of its own send setting. Reaching the
      // branch below now takes an explicit emergency override.
      if (!roomSenderKeyReceiveEnabled) {
        DiagLog.event('room_key', 'wire_disabled', {
          'sender_dev': DiagLog.pfx((senderDeviceId ?? '').trim()),
          'count': allEvents.length,
        });
        return false;
      }
      return _handleRoomKeyWires(
        db: db,
        events: allEvents,
        senderDeviceId: senderDeviceId,
        senderProfileId: senderProfileId,
        msgId: msgId,
        now: now,
        depth: roomKeyWireDepth,
        senderAttested: senderAttested,
      );
    }

    final receiptEvents = allEvents.whereType<ReceiptEventV1>().toList();
    if (receiptEvents.isNotEmpty) {
      final myPid = (_profileId ?? '').trim();
      final senderDidTrim = (senderDeviceId ?? '').trim();
      final senderPidTrim = (senderProfileId ?? '').trim();
      final receiptSenderProfileId = senderPidTrim.isNotEmpty
          ? senderPidTrim
          : (senderDidTrim.isNotEmpty
                ? ((await db.deviceProfileCached(senderDidTrim))?.trim() ?? '')
                : '');
      final receiptFromOwnDevice =
          (senderDidTrim.isNotEmpty && isOwnDeviceId(senderDidTrim)) ||
          (myPid.isNotEmpty && senderPidTrim == myPid);

      // PRESENCE-LEAK FIX (2026-07-12): only a READ receipt implies the peer is
      // genuinely present — it is enqueued solely by markChatRead when the user
      // actually opens/views the chat. A DELIVERED receipt is auto-emitted by the
      // receiving device the instant it gets the message, INCLUDING a background
      // push-drain while the app is killed and the phone is locked (no foreground
      // check on the send path). Bumping last_seen on that made a peer look
      // "online" (and advanced their "last seen X ago") merely for receiving a
      // push. Gate the presence bump on a read receipt; the delivered/read tick
      // processing below is untouched, so delivery checkmarks still work.
      final hasReadReceipt = receiptEvents.any(
        (e) =>
            MessageReceiptState.normalize(e.status) == MessageReceiptState.read,
      );
      if (hasReadReceipt &&
          senderProfileId != null &&
          senderProfileId.isNotEmpty) {
        // PRESENCE-LIE FIX R8 (2026-07-16): the read receipt proves presence
        // at the time the peer GENERATED it (payload.createdAtMs), not at the
        // time we finally applied it — a receipt drained hours later from a
        // backlog must not flip the peer to «Онлайн». Clamped to `now`
        // against peer clock skew; DB write is monotonic.
        final receiptActivityAtMs =
            (payload.createdAtMs > 0 && payload.createdAtMs < now)
            ? payload.createdAtMs
            : now;
        await db.profileMetaUpdateLastSeen(
          profileId: senderProfileId,
          lastSeenAtMs: receiptActivityAtMs,
        );
      }
      // 2026-05-20 PR-B (BUG-10): bucket the refs we successfully flipped
      // locally by status so we can fan out a single self-mirror command
      // per status at the end (instead of one cmd per receipt). Empty when
      // `receiptFromOwnDevice` short-circuits — the existing guard already
      // suppresses local flips, and we never re-broadcast a mirror anyway.
      final mirroredDelivered = <String>{};
      final mirroredRead = <String>{};
      if (!receiptFromOwnDevice) {
        for (final receiptEvent in receiptEvents) {
          final normalizedStatus = MessageReceiptState.normalize(
            receiptEvent.status,
          );
          final payloadEventId = receiptEvent.refEventId.trim();
          if (payloadEventId.isEmpty) continue;

          final convoId = await db.convoIdForPayloadEventId(payloadEventId);
          if (convoId != null &&
              convoId.startsWith('group:') &&
              receiptSenderProfileId.isNotEmpty) {
            await db.roomMessageReceiptUpsert(
              payloadEventId: payloadEventId,
              readerProfileId: receiptSenderProfileId,
              readerDeviceId: senderDidTrim.isEmpty ? null : senderDidTrim,
              status: normalizedStatus,
              updatedAtMs: now,
            );
          }

          if (normalizedStatus == MessageReceiptState.delivered) {
            await db.updateLocalStateByPayloadEventId(
              payloadEventId: payloadEventId,
              localState: MessageLocalState.delivered,
            );
            // Only mirror 1:1 receipts — group reads use a separate
            // `room_message_receipts` table that the responder side
            // already tracks per-reader, so per-row local_state isn't
            // the source of truth there.
            if (convoId != null && !convoId.startsWith('group:')) {
              mirroredDelivered.add(payloadEventId);
            }
          } else if (normalizedStatus == MessageReceiptState.read) {
            await db.updateLocalStateByPayloadEventId(
              payloadEventId: payloadEventId,
              localState: MessageLocalState.read,
            );
            if (convoId != null && !convoId.startsWith('group:')) {
              mirroredRead.add(payloadEventId);
            }
          } else if (normalizedStatus ==
                  MessageReceiptState.nackUndecryptable &&
              (receiptEvent.refKind ?? '') == 'msg_id') {
            // TZ Epic A2: the peer's device reported OUR wire undecryptable —
            // targeted rekey + resend. Never touches local_state (rank 0) and
            // never mirrors (device-local failure, not a conversation fact).
            unawaited(
              _handleNackUndecryptableReceipt(
                relayMsgId: payloadEventId,
                peerDeviceId: senderDidTrim,
                peerProfileId: receiptSenderProfileId,
              ),
            );
          }
        }
      }
      // PR-B fan-out: fire-and-forget so the receipt receive path stays
      // synchronous-fast. `_mirrorReceiptsToOwnDevices` is best-effort
      // and never throws past its own try/catch.
      if (mirroredDelivered.isNotEmpty) {
        unawaited(
          _mirrorReceiptsToOwnDevices(
            status: MessageReceiptState.delivered,
            refPayloadEventIds: mirroredDelivered,
            peerProfileId: receiptSenderProfileId.isEmpty
                ? null
                : receiptSenderProfileId,
          ),
        );
      }
      if (mirroredRead.isNotEmpty) {
        unawaited(
          _mirrorReceiptsToOwnDevices(
            status: MessageReceiptState.read,
            refPayloadEventIds: mirroredRead,
            peerProfileId: receiptSenderProfileId.isEmpty
                ? null
                : receiptSenderProfileId,
          ),
        );
      }
      if (allEvents.every((event) => event is ReceiptEventV1)) {
        _changed.add(null);
        return true;
      }
    }

    var handledCommand = await handleInboundAttachmentCommands(
      allEvents.whereType<AttachmentEventV1>(),
    );
    for (final msgEvent in allEvents.whereType<MsgEventV1>()) {
      final editCmd = parseEditMessageCommand(msgEvent.text);
      if (editCmd != null) {
        await _applyMessageEditCommand(
          command: editCmd,
          senderDeviceId: senderDeviceId,
          senderProfileId: senderProfileId,
        );
        handledCommand = true;
        continue;
      }

      // 2026-05-20 PR-B (BUG-10): receipt mirror from one of our other own
      // devices. We accept ONLY when the sender device id is known-own (or
      // the senderProfileId resolves to our own profile id) — the same
      // gate the other self-mirror branches use. Receipt mirrors are
      // terminal: we apply the state change locally and never re-broadcast.
      // Read watermark from one of our own devices ("I read this chat over
      // there"). Same own-sender gate as every other self-mirror branch, and
      // terminal for the same reason: applying it must not produce another
      // mirror, or two paired devices would answer each other forever.
      final readMirrorCmd = parseSelfMirrorReadCommand(msgEvent.text);
      if (readMirrorCmd != null) {
        final myPid = (_profileId ?? '').trim();
        final senderDid = (senderDeviceId ?? '').trim();
        final senderIsOwn =
            (senderDid.isNotEmpty && isOwnDeviceId(senderDid)) ||
            ((senderProfileId ?? '').trim() == myPid && myPid.isNotEmpty);
        DiagLog.event('selfsync', 'read_cmd_received', {
          'sender_own': senderIsOwn,
          'sender_dev': DiagLog.pfx(senderDid),
          'convo': DiagLog.pfx(readMirrorCmd.convoId),
          'up_to_ms': readMirrorCmd.readUpToMs,
        });
        if (senderIsOwn) {
          await _applySelfMirrorReadWatermark(readMirrorCmd);
        }
        // Hidden control either way: a mirror from a device that is NOT ours
        // is dropped rather than rendered.
        continue;
      }

      // Chat-folder change from one of our own devices.
      final folderCmd = parseSelfMirrorFolderCommand(msgEvent.text);
      if (folderCmd != null) {
        final myPid = (_profileId ?? '').trim();
        final senderDid = (senderDeviceId ?? '').trim();
        final senderIsOwn =
            (senderDid.isNotEmpty && isOwnDeviceId(senderDid)) ||
            ((senderProfileId ?? '').trim() == myPid && myPid.isNotEmpty);
        DiagLog.event('selfsync', 'folder_cmd_received', {
          'sender_own': senderIsOwn,
          'sender_dev': DiagLog.pfx(senderDid),
          'folder': DiagLog.pfx(folderCmd.folderId),
        });
        if (senderIsOwn) {
          await _applySelfMirrorFolder(folderCmd);
        }
        continue;
      }

      // Per-conversation state patch from one of our own devices.
      final convoStateCmd = parseSelfMirrorConvoStateCommand(msgEvent.text);
      if (convoStateCmd != null) {
        final myPid = (_profileId ?? '').trim();
        final senderDid = (senderDeviceId ?? '').trim();
        final senderIsOwn =
            (senderDid.isNotEmpty && isOwnDeviceId(senderDid)) ||
            ((senderProfileId ?? '').trim() == myPid && myPid.isNotEmpty);
        DiagLog.event('selfsync', 'convo_state_cmd_received', {
          'sender_own': senderIsOwn,
          'sender_dev': DiagLog.pfx(senderDid),
          'convo': DiagLog.pfx(convoStateCmd.convoId),
        });
        if (senderIsOwn) {
          await _applySelfMirrorConvoState(convoStateCmd);
        }
        continue;
      }

      final receiptMirrorCmd = parseSelfMirrorReceiptCommand(msgEvent.text);
      if (receiptMirrorCmd != null) {
        final myPid = (_profileId ?? '').trim();
        final senderDid = (senderDeviceId ?? '').trim();
        final senderIsOwn =
            (senderDid.isNotEmpty && isOwnDeviceId(senderDid)) ||
            ((senderProfileId ?? '').trim() == myPid && myPid.isNotEmpty);
        DiagLog.event('selfsync', 'receipt_cmd_received', {
          'sender_own': senderIsOwn,
          'sender_dev': DiagLog.pfx(senderDid),
          'sender_pid': DiagLog.pfx((senderProfileId ?? '').trim()),
          'status': receiptMirrorCmd.status,
          'count': receiptMirrorCmd.refPayloadEventIds.length,
        });
        if (senderIsOwn) {
          final normalizedStatus = MessageReceiptState.normalize(
            receiptMirrorCmd.status,
          );
          if (normalizedStatus == MessageReceiptState.delivered ||
              normalizedStatus == MessageReceiptState.read) {
            final targetLocalState =
                normalizedStatus == MessageReceiptState.read
                ? MessageLocalState.read
                : MessageLocalState.delivered;
            var applied = 0;
            for (final ref in receiptMirrorCmd.refPayloadEventIds) {
              final pidRef = ref.trim();
              if (pidRef.isEmpty) continue;
              try {
                await db.updateLocalStateByPayloadEventId(
                  payloadEventId: pidRef,
                  localState: targetLocalState,
                );
                applied += 1;
              } catch (_) {
                // ignore — receipt mirror is best-effort.
              }
            }
            if (applied > 0) {
              _changed.add(null);
              DiagLog.event('selfsync', 'receipt_applied', {
                'status': normalizedStatus,
                'applied': applied,
              });
            }
          }
          if (senderDid.isNotEmpty) {
            _rememberOwnDeviceId(senderDid);
          }
        }
        handledCommand = true;
        continue;
      }

      // ----------------------------------------------------------------------
      // PR-H bug 21: session-revocation envelope. Sent by `endDeviceSession`
      // on the requester's device, addressed to a single target deviceId.
      // Gated on `senderIsOwn` (only my own other devices can ask me to
      // wipe) AND `targetDeviceId == myDid` (so a stray envelope addressed
      // to a SIBLING device that happened to reach my inbox is ignored).
      //
      // On match we call `resetProfileAndLocalData()` which already fires
      // `restartRequested` — `DesktopProductionApp._restart()` then drops
      // every controller and returns the user to the QR/pairing flow.
      // Mobile callers receive the same effect via `_restart()` in main.
      // ----------------------------------------------------------------------
      final revokedCmd = _parseSessionRevokedCommand(msgEvent.text);
      if (revokedCmd != null) {
        final myPid = (_profileId ?? '').trim();
        final myDid = (_deviceId ?? '').trim();
        final senderDid = (senderDeviceId ?? '').trim();
        final senderIsOwn =
            (senderDid.isNotEmpty && isOwnDeviceId(senderDid)) ||
            ((senderProfileId ?? '').trim() == myPid && myPid.isNotEmpty);
        final envelopePid = (revokedCmd['profileId'] as String?)?.trim() ?? '';
        final envelopeTargetDid =
            (revokedCmd['targetDeviceId'] as String?)?.trim() ?? '';
        DiagLog.event('session_revoke', 'envelope_received', {
          'sender_own': senderIsOwn,
          'sender_dev': DiagLog.pfx(senderDid),
          'target_dev': DiagLog.pfx(envelopeTargetDid),
          'my_dev': DiagLog.pfx(myDid),
          'envelope_pid_match': envelopePid == myPid,
        });
        if (senderIsOwn &&
            myDid.isNotEmpty &&
            envelopeTargetDid == myDid &&
            envelopePid == myPid) {
          // 🔴 СТИРАНИЕ — ТОЛЬКО КОГДА СЕРВЕР ПОДТВЕРДИЛ (17.09.2026).
          //
          // «Своё устройство» здесь — слова провода: номер отправителя не
          // подписан, и чужак, знающий номер моего компьютера (его отдаёт
          // открытая связка ключей), проходил эту проверку. Конверт стирал
          // приложение сразу. Настоящее завершение сеанса удаляет регистрацию
          // этого устройства на сервере ключей через 1,5–4,5 с после отправки,
          // а удалить чужую регистрацию посторонний не может. Поэтому ждём,
          // пока сервер скажет «такого устройства нет». Не подтвердил — живём.
          // Не ждём здесь: мы на пути разбора входящих.
          _sessionRevokeConfirmation = _resetAfterServerConfirmsRevocation(
            requesterDeviceId:
                (revokedCmd['requesterDeviceId'] as String?)?.trim() ?? '',
            reason: (revokedCmd['reason'] as String?)?.trim() ?? '',
            senderDeviceId: senderDid,
          );
          unawaited(_sessionRevokeConfirmation);
        }
        handledCommand = true;
        continue;
      }

      final selfMirrorCmd = _parseSelfMirrorMessageCommand(msgEvent.text);
      if (selfMirrorCmd != null) {
        final myPid = (_profileId ?? '').trim();
        final senderDid = (senderDeviceId ?? '').trim();
        final senderIsOwn =
            (senderDid.isNotEmpty && isOwnDeviceId(senderDid)) ||
            ((senderProfileId ?? '').trim() == myPid && myPid.isNotEmpty);
        // Sprint 2 PR8 (2026-05-19): trace every mirror-text envelope so we
        // can prove on the desktop side whether the cmd arrived AND whether
        // the senderIsOwn gate accepted it. Previously only the success
        // path bumped `_changed` — a silent reject (senderDid not yet in
        // `_knownOwnDeviceIds` AND senderProfileId resolution missing)
        // looked identical to "no mirror ever sent" in logs.
        DiagLog.event('selfsync', 'text_cmd_received', {
          'sender_own': senderIsOwn,
          'sender_dev': DiagLog.pfx(senderDid),
          'sender_pid': DiagLog.pfx((senderProfileId ?? '').trim()),
          'my_pid': DiagLog.pfx(myPid),
          'crypto_ready': crypto != null,
        });
        if (senderIsOwn && crypto != null) {
          final convoId = (selfMirrorCmd['convoId'] as String?)?.trim() ?? '';
          final msgEventId =
              (selfMirrorCmd['msgEventId'] as String?)?.trim() ?? '';
          final text = (selfMirrorCmd['text'] as String?) ?? '';
          final replyToPayloadEventId =
              (selfMirrorCmd['replyToPayloadEventId'] as String?)?.trim();
          final createdAtRaw = selfMirrorCmd['createdAtMs'];
          final mirroredCreatedAt = (createdAtRaw is num)
              ? createdAtRaw.toInt()
              : now;
          if (convoId.isNotEmpty && msgEventId.isNotEmpty) {
            if (await _shouldDropConversationEventByClearCutoff(
              convoId: convoId,
              createdAtMs: mirroredCreatedAt,
            )) {
              handledCommand = true;
              continue;
            }
            final effectiveSenderDid = senderDid.isNotEmpty
                ? senderDid
                : ((payload.senderDeviceId).trim().isNotEmpty
                      ? payload.senderDeviceId.trim()
                      : 'unknown');
            final syntheticPayload = E2ePayloadV1(
              senderDeviceId: effectiveSenderDid,
              createdAtMs: mirroredCreatedAt,
              events: [
                MsgEventV1(
                  eventId: msgEventId,
                  text: text,
                  replyToEventId:
                      (replyToPayloadEventId != null &&
                          replyToPayloadEventId.isNotEmpty)
                      ? replyToPayloadEventId
                      : null,
                  linkPreview: LinkPreviewV1.fromJson(
                    selfMirrorCmd['linkPreview'],
                  ),
                ),
              ],
            );
            final localCipher = base64Encode(
              await crypto.encrypt(syntheticPayload.encode()),
            );
            final syntheticEventId = 'selfsync:$msgEventId:$effectiveSenderDid';
            final existing = await db.eventGet(syntheticEventId);
            if (existing == null) {
              await db.convoEnsure1to1(peerProfileId: convoId);
              await db.insertEvent(
                eventId: syntheticEventId,
                convoId: convoId,
                type: 'msg',
                senderDeviceId: effectiveSenderDid,
                ciphertextB64: localCipher,
                createdAtMs: mirroredCreatedAt,
                localState: 'sent',
                payloadEventId: msgEventId,
              );
              await db.convoTouch(convoId: convoId, atMs: mirroredCreatedAt);
              DiagLog.event('selfsync', 'text_applied', {
                'convo': DiagLog.pfx(convoId),
                'evt': DiagLog.pfx(msgEventId),
                'sender_dev': DiagLog.pfx(effectiveSenderDid),
              });
            } else {
              DiagLog.event('selfsync', 'text_dedup_skip', {
                'evt': DiagLog.pfx(msgEventId),
              });
            }
            _rememberOwnDeviceId(effectiveSenderDid);
            _changed.add(null);
          }
        }
        handledCommand = true;
        continue;
      }

      // ----------------------------------------------------------------------
      // Peer-to-device history sync (PR5, SPRINT2_AUDIT §17).
      //
      // The desktop ships a `PeerHistoryRequest` to us via the same self-
      // mirror gating pattern as the per-message mirror above. We respond
      // with one or more `PeerHistoryChunk`s targeted ONLY at the asking
      // device (so the user's other phones don't get a useless duplicate).
      //
      // Inverse direction (chunk landing on the desktop) is handled in the
      // sibling block below — both directions gate on `senderIsOwn` so a
      // hostile peer can't inject history into our DB or trick us into
      // shipping our archive to them.
      // ----------------------------------------------------------------------
      if (isPeerHistoryCommand(msgEvent.text)) {
        final myPid = (_profileId ?? '').trim();
        final senderDid = (senderDeviceId ?? '').trim();
        final senderIsOwn =
            (senderDid.isNotEmpty && isOwnDeviceId(senderDid)) ||
            ((senderProfileId ?? '').trim() == myPid && myPid.isNotEmpty);
        if (!senderIsOwn) {
          // Drop silently — see the security note on the protocol file.
          handledCommand = true;
          continue;
        }

        final req = parsePeerHistoryRequest(msgEvent.text);
        if (req != null) {
          // Fire-and-forget: response involves N relay round-trips and we
          // don't want the receive loop blocked behind it. Errors are
          // logged inside the helper so we don't surface them to the
          // caller (which doesn't care — the desktop will simply time out
          // and resubmit if necessary).
          unawaited(
            _respondToPeerHistoryRequest(
              request: req,
              requestingDeviceId: senderDid,
              requestingProfileId: myPid,
            ),
          );
          handledCommand = true;
          continue;
        }

        final chunk = parsePeerHistoryChunk(msgEvent.text);
        if (chunk != null) {
          await _applyPeerHistoryChunk(chunk: chunk, senderDeviceId: senderDid);
          handledCommand = true;
          continue;
        }
        // Looked like one of our prefixes but failed to parse — treat as
        // handled so the bytes don't fall into the "render as text"
        // codepath.
        handledCommand = true;
        continue;
      }

      // ----------------------------------------------------------------------
      // Sticker-pack share: a PEER taps a sticker we sent and pulls the whole
      // pack. Unlike peer-history this is NOT own-device-gated — the request
      // handler answers a contact (ownership + rate-limit gate live inside the
      // helper), and the chunk handler only accepts packs we actually asked for.
      // ----------------------------------------------------------------------
      if (isStickerPackCommand(msgEvent.text)) {
        final senderDid = (senderDeviceId ?? '').trim();
        final fromPid = (senderProfileId ?? '').trim();
        final packReq = parseStickerPackRequest(msgEvent.text);
        if (packReq != null) {
          unawaited(
            _respondToStickerPackRequest(
              request: packReq,
              requestingProfileId: fromPid,
              requestingDeviceId: senderDid,
            ),
          );
          handledCommand = true;
          continue;
        }
        final packChunk = parseStickerPackChunk(msgEvent.text);
        if (packChunk != null) {
          await _applyStickerPackChunk(
            chunk: packChunk,
            fromProfileId: fromPid,
          );
          handledCommand = true;
          continue;
        }
        handledCommand = true;
        continue;
      }

      // ----------------------------------------------------------------------
      // Self-mirror: attachment (TZ §21.1) — synthesize a local AttachmentEvent
      // so my other device's chat history shows the file I just sent from a
      // different device.
      // ----------------------------------------------------------------------
      final selfMirrorAttCmd = parseSelfMirrorAttachmentCommand(msgEvent.text);
      if (selfMirrorAttCmd != null) {
        final myPid = (_profileId ?? '').trim();
        final senderDid = (senderDeviceId ?? '').trim();
        final senderIsOwn =
            (senderDid.isNotEmpty && isOwnDeviceId(senderDid)) ||
            ((senderProfileId ?? '').trim() == myPid && myPid.isNotEmpty);
        DiagLog.event('selfsync', 'att_cmd_received', {
          'sender_own': senderIsOwn,
          'sender_dev': DiagLog.pfx(senderDid),
          'mime': selfMirrorAttCmd.mime ?? '',
          'size': selfMirrorAttCmd.sizeBytes,
        });
        if (senderIsOwn && crypto != null) {
          final convoId = selfMirrorAttCmd.convoId;
          final msgEventId = selfMirrorAttCmd.msgEventId;
          final mirroredCreatedAt = selfMirrorAttCmd.createdAtMs;
          if (convoId.isNotEmpty && msgEventId.isNotEmpty) {
            if (await _shouldDropConversationEventByClearCutoff(
              convoId: convoId,
              createdAtMs: mirroredCreatedAt,
            )) {
              handledCommand = true;
              continue;
            }
            final effectiveSenderDid = senderDid.isNotEmpty
                ? senderDid
                : ((payload.senderDeviceId).trim().isNotEmpty
                      ? payload.senderDeviceId.trim()
                      : 'unknown');
            final resolvedMime = (selfMirrorAttCmd.mime ?? '').trim();
            try {
              await db.attachmentUpsert(
                blobId: selfMirrorAttCmd.blobId,
                fileKeyB64: selfMirrorAttCmd.fileKeyB64,
                accessTokenB64: selfMirrorAttCmd.blobAccessTokenB64 ?? '',
                mime: resolvedMime.isEmpty
                    ? 'application/octet-stream'
                    : resolvedMime,
                plaintextSizeBytes: selfMirrorAttCmd.sizeBytes,
                ciphertextSizeBytes: selfMirrorAttCmd.sizeBytes,
                expiresAtMs: mirroredCreatedAt + (7 * 24 * 60 * 60 * 1000),
                createdAtMs: mirroredCreatedAt,
              );
            } catch (_) {
              // Non-fatal: insertEvent below still surfaces a placeholder.
            }
            final syntheticPayload = E2ePayloadV1(
              senderDeviceId: effectiveSenderDid,
              createdAtMs: mirroredCreatedAt,
              events: [
                AttachmentEventV1(
                  eventId: msgEventId,
                  blobId: selfMirrorAttCmd.blobId,
                  fileKeyB64: selfMirrorAttCmd.fileKeyB64,
                  blobAccessTokenB64: selfMirrorAttCmd.blobAccessTokenB64,
                  sizeBytes: selfMirrorAttCmd.sizeBytes,
                  mime: resolvedMime.isEmpty ? null : resolvedMime,
                  replyToEventId: selfMirrorAttCmd.replyToPayloadEventId,
                  mediaGroupId: selfMirrorAttCmd.mediaGroupId,
                  caption: selfMirrorAttCmd.caption,
                  filename: selfMirrorAttCmd.filename,
                  videoNote: selfMirrorAttCmd.videoNote,
                  durationMs: selfMirrorAttCmd.durationMs,
                  // Волна отличает голосовое от песни (оба — `audio/mp4`);
                  // без неё голосовое на своём втором устройстве рисовалось
                  // песней «Неизвестен» (17.09.2026).
                  waveform: selfMirrorAttCmd.waveform,
                  musicTitle: selfMirrorAttCmd.musicTitle,
                  musicArtist: selfMirrorAttCmd.musicArtist,
                ),
              ],
            );
            final localCipher = base64Encode(
              await crypto.encrypt(syntheticPayload.encode()),
            );
            final syntheticEventId =
                'selfsync:att:$msgEventId:$effectiveSenderDid';
            final existing = await db.eventGet(syntheticEventId);
            if (existing == null) {
              await db.convoEnsure1to1(peerProfileId: convoId);
              await db.insertEvent(
                eventId: syntheticEventId,
                convoId: convoId,
                type: 'att',
                senderDeviceId: effectiveSenderDid,
                ciphertextB64: localCipher,
                createdAtMs: mirroredCreatedAt,
                localState: 'sent',
                payloadEventId: msgEventId,
              );
              await db.convoTouch(convoId: convoId, atMs: mirroredCreatedAt);
            }
            _rememberOwnDeviceId(effectiveSenderDid);
            _changed.add(null);
          }
        }
        handledCommand = true;
        continue;
      }

      // ----------------------------------------------------------------------
      // Self-mirror: sticker (TZ §21.1) — synthesize a local StickerEvent on
      // my other device.
      // ----------------------------------------------------------------------
      final selfMirrorStickerCmd = parseSelfMirrorStickerCommand(msgEvent.text);
      if (selfMirrorStickerCmd != null) {
        final myPid = (_profileId ?? '').trim();
        final senderDid = (senderDeviceId ?? '').trim();
        final senderIsOwn =
            (senderDid.isNotEmpty && isOwnDeviceId(senderDid)) ||
            ((senderProfileId ?? '').trim() == myPid && myPid.isNotEmpty);
        if (senderIsOwn && crypto != null) {
          final convoId = selfMirrorStickerCmd.convoId;
          final msgEventId = selfMirrorStickerCmd.msgEventId;
          final mirroredCreatedAt = selfMirrorStickerCmd.createdAtMs;
          if (convoId.isNotEmpty && msgEventId.isNotEmpty) {
            if (await _shouldDropConversationEventByClearCutoff(
              convoId: convoId,
              createdAtMs: mirroredCreatedAt,
            )) {
              handledCommand = true;
              continue;
            }
            final effectiveSenderDid = senderDid.isNotEmpty
                ? senderDid
                : ((payload.senderDeviceId).trim().isNotEmpty
                      ? payload.senderDeviceId.trim()
                      : 'unknown');
            final syntheticPayload = E2ePayloadV1(
              senderDeviceId: effectiveSenderDid,
              createdAtMs: mirroredCreatedAt,
              events: [
                StickerEventV1(
                  eventId: msgEventId,
                  packId: selfMirrorStickerCmd.packId,
                  packVersion: selfMirrorStickerCmd.packVersion,
                  stickerId: selfMirrorStickerCmd.stickerId,
                  emojiHint: selfMirrorStickerCmd.emojiHint,
                  label: selfMirrorStickerCmd.label,
                  animated: selfMirrorStickerCmd.animated,
                  format: selfMirrorStickerCmd.format,
                  replyToEventId: selfMirrorStickerCmd.replyToPayloadEventId,
                ),
              ],
            );
            final localCipher = base64Encode(
              await crypto.encrypt(syntheticPayload.encode()),
            );
            final syntheticEventId =
                'selfsync:sticker:$msgEventId:$effectiveSenderDid';
            final existing = await db.eventGet(syntheticEventId);
            if (existing == null) {
              await db.convoEnsure1to1(peerProfileId: convoId);
              await db.insertEvent(
                eventId: syntheticEventId,
                convoId: convoId,
                type: 'sticker',
                senderDeviceId: effectiveSenderDid,
                ciphertextB64: localCipher,
                createdAtMs: mirroredCreatedAt,
                localState: 'sent',
                payloadEventId: msgEventId,
              );
              await db.convoTouch(convoId: convoId, atMs: mirroredCreatedAt);
            }
            _rememberOwnDeviceId(effectiveSenderDid);
            _changed.add(null);
          }
        }
        handledCommand = true;
        continue;
      }

      // ----------------------------------------------------------------------
      // Self-mirror: reaction (TZ §21.1) — apply my reaction add/remove on
      // my other device so its UI matches the device I reacted from.
      // ----------------------------------------------------------------------
      final selfMirrorReactionCmd = parseSelfMirrorReactionCommand(
        msgEvent.text,
      );
      if (selfMirrorReactionCmd != null) {
        final myPid = (_profileId ?? '').trim();
        final senderDid = (senderDeviceId ?? '').trim();
        final senderIsOwn =
            (senderDid.isNotEmpty && isOwnDeviceId(senderDid)) ||
            ((senderProfileId ?? '').trim() == myPid && myPid.isNotEmpty);
        if (senderIsOwn) {
          final reactionConvoId = selfMirrorReactionCmd.convoId;
          final targetEventId = selfMirrorReactionCmd.targetPayloadEventId;
          final reactionEmoji = selfMirrorReactionCmd.emoji;
          final reactionActor = (selfMirrorReactionCmd.actorProfileId ?? myPid)
              .trim();
          if (reactionConvoId.isNotEmpty &&
              targetEventId.isNotEmpty &&
              reactionEmoji.isNotEmpty &&
              reactionActor.isNotEmpty) {
            if (selfMirrorReactionCmd.removed) {
              await db.messageReactionDelete(
                eventId: targetEventId,
                profileId: reactionActor,
              );
              _changed.add(null);
            } else {
              final changed = await db.messageReactionUpsert(
                eventId: targetEventId,
                convoId: reactionConvoId,
                profileId: reactionActor,
                emoji: reactionEmoji,
                actorName: selfMirrorReactionCmd.actorName,
                actorAvatarPath: selfMirrorReactionCmd.actorAvatarPath,
              );
              if (changed) _changed.add(null);
            }
          }
          if (senderDid.isNotEmpty) _rememberOwnDeviceId(senderDid);
        }
        handledCommand = true;
        continue;
      }

      final clearHistoryCmd = _parseClearHistoryCommand(msgEvent.text);
      if (clearHistoryCmd != null) {
        final cmdConvoId =
            (clearHistoryCmd['convoId'] as String?)?.trim() ?? '';
        final cutoffCreatedAtMs =
            switch (clearHistoryCmd['cutoffCreatedAtMs']) {
              final int value => value,
              final num value => value.toInt(),
              final String value => int.tryParse(value) ?? 0,
              _ => 0,
            };
        if (cmdConvoId.isNotEmpty && cutoffCreatedAtMs > 0) {
          // 🔴 ОЧИСТКА — ТОЛЬКО СВОЕЙ ПЕРЕПИСКИ (17.09.2026). Команда стирала
          // безвозвратно ту переписку, которую НАЗВАЛА, от кого бы ни пришла:
          // любой, кто может мне написать, стирал мой чат с третьим человеком
          // или комнату, а дата из будущего глушила её навсегда.
          final clearVerdict = await _authorizedInboundClearHistoryConvoId(
            db: db,
            commandConvoId: cmdConvoId,
            senderDeviceId: senderDeviceId,
            senderProfileId: senderProfileId,
          );
          final targetConvoId = clearVerdict.convoId;
          if (targetConvoId != null) {
            await _applyConversationHistoryClear(
              convoId: targetConvoId,
              cutoffCreatedAtMs: clampInboundClearCutoffMs(
                cutoffCreatedAtMs,
                nowMs: now,
              ),
            );
          } else if (clearVerdict.deferrable && !fromDeferredReplay) {
            // Права админа ещё не дошли: команда уже расшифрована, так что
            // терять её нельзя — паркуем до сходимости состава (как сообщения).
            await _storeDeferredRoomInbound(
              db: db,
              groupId: cmdConvoId,
              senderProfile: clearVerdict.senderPid,
              senderDeviceId: senderDeviceId,
              msgEventId: msgEvent.eventId,
              commandText: msgEvent.text,
              msgId: msgId,
              ciphertextB64: ciphertextB64,
              createdAtMs: payload.createdAtMs,
            );
          }
        }
        handledCommand = true;
        continue;
      }

      final typingCmd = _parseTypingCommand(msgEvent.text);
      if (typingCmd != null) {
        final action =
            (typingCmd['action'] as String?)?.trim().toLowerCase() ?? '';
        final cmdConvoId = (typingCmd['convoId'] as String?)?.trim() ?? '';
        final senderConvoId = (senderProfileId ?? '').trim();
        var resolvedConvoId = cmdConvoId.isNotEmpty
            ? cmdConvoId
            : senderConvoId;
        if (!resolvedConvoId.startsWith('group:') && senderConvoId.isNotEmpty) {
          resolvedConvoId = senderConvoId;
        }
        if (resolvedConvoId.startsWith('dev:') && senderConvoId.isNotEmpty) {
          resolvedConvoId = senderConvoId;
        }
        resolvedConvoId = _normalizeTypingConvoId(resolvedConvoId);
        if (resolvedConvoId.isNotEmpty) {
          final isTyping = action == 'start' || action == 'typing';
          if (isTyping) {
            _setConversationTyping(
              convoId: resolvedConvoId,
              typing: true,
              expiresAtMs: now + _typingVisibleMs,
              senderProfileId: senderProfileId,
            );
          } else if (action == 'stop') {
            _setConversationTyping(convoId: resolvedConvoId, typing: false);
          }
        }
        handledCommand = true;
        continue;
      }

      final callCmd = CallSignalCommandCodec.decode(msgEvent.text);
      if (callCmd != null) {
        final action =
            (callCmd['action'] as String?)?.trim().toLowerCase() ?? '';
        final callId = (callCmd['callId'] as String?)?.trim() ?? '';
        final media =
            (callCmd['media'] as String?)?.trim().toLowerCase() ?? 'audio';
        final screenShare = callCmd['screenShare'] == true;
        final sdp = (callCmd['sdp'] as String?)?.trim();
        final candidate = (callCmd['candidate'] as String?)?.trim();
        final sdpMid = (callCmd['sdpMid'] as String?)?.trim();
        final sdpMLineIndexRaw = callCmd['sdpMLineIndex'];
        final sdpMLineIndex = sdpMLineIndexRaw is num
            ? sdpMLineIndexRaw.toInt()
            : null;
        final signalId = CallSignalCommandCodec.resolveInboundSignalId(
          callCmd,
          senderProfileId: senderProfileId,
          senderDeviceId: senderDeviceId,
        );
        final signalCallAttemptId =
            ((callCmd['callAttemptId'] as String?) ??
                    (callCmd['call_attempt_id'] as String?) ??
                    callId)
                .trim();
        // Use sender's timestamp when available; fall back to local clock.
        final senderCreatedAtMs = callCmd['createdAtMs'];
        final signalCreatedAtMs = (senderCreatedAtMs is num)
            ? senderCreatedAtMs.toInt()
            : DateTime.now().millisecondsSinceEpoch;
        if (action.isNotEmpty && callId.isNotEmpty) {
          final fromProfileId = (senderProfileId ?? '').trim();
          if (action == 'invite') {
            var declinedByPolicy = false;
            if (!_incomingCallsEnabled || !_callsEnabled) {
              declinedByPolicy = true;
            }
            if (screenShare && !_incomingScreenShareEnabled) {
              declinedByPolicy = true;
            }
            if (fromProfileId.isNotEmpty) {
              final blocked = await db.blockedProfileIsBlocked(fromProfileId);
              final contactAllowed = await isContactCallsAllowed(fromProfileId);
              final isContact = await db.contactGet(fromProfileId) != null;
              final audienceAllowed = _myAudienceAllowsCategory(
                'calls',
                isContact: isContact,
              );
              if (blocked || !contactAllowed || !audienceAllowed) {
                declinedByPolicy = true;
              }
            } else if (_selfPrivacyAudienceValue('calls') != 'everyone') {
              declinedByPolicy = true;
            }

            if (declinedByPolicy && fromProfileId.isNotEmpty) {
              await sendCallDecline(
                peerProfileId: fromProfileId,
                callId: callId,
              );
              handledCommand = true;
              continue;
            }
          }

          if (_shouldDropDuplicateInboundCallSignal(
            signalId: signalId,
            action: action,
            callId: callId,
            callAttemptId: signalCallAttemptId,
            fromProfileId: fromProfileId,
            fromDeviceId: senderDeviceId,
          )) {
            handledCommand = true;
            continue;
          }

          await _dispatchCallSignal(
            CallSignalEvent(
              action: action,
              callId: callId,
              callAttemptId: signalCallAttemptId.isEmpty
                  ? callId
                  : signalCallAttemptId,
              signalId: signalId,
              fromProfileId: fromProfileId,
              fromDeviceId: senderDeviceId,
              media: media == 'video' ? CallMedia.video : CallMedia.audio,
              screenShare: screenShare,
              sdp: (sdp == null || sdp.isEmpty) ? null : sdp,
              candidate: (candidate == null || candidate.isEmpty)
                  ? null
                  : candidate,
              sdpMid: (sdpMid == null || sdpMid.isEmpty) ? null : sdpMid,
              sdpMLineIndex: sdpMLineIndex,
              createdAtMs: signalCreatedAtMs,
            ),
          );
        }
        handledCommand = true;
        continue;
      }

      final roomMediaCmd = _parseRoomCallMediaCommand(msgEvent.text);
      if (roomMediaCmd != null) {
        final action =
            (roomMediaCmd['action'] as String?)?.trim().toLowerCase() ?? '';
        final roomId = (roomMediaCmd['roomId'] as String?)?.trim() ?? '';
        final callId = (roomMediaCmd['callId'] as String?)?.trim() ?? '';
        final sessionId = ((roomMediaCmd['sessionId'] as String?) ?? callId)
            .trim();
        final descriptorVersion = switch (roomMediaCmd['descriptorVersion']) {
          final int value => value,
          final num value => value.toInt(),
          final String value => int.tryParse(value) ?? 0,
          _ => 0,
        };
        final stateVersion = switch (roomMediaCmd['stateVersion']) {
          final int value => value,
          final num value => value.toInt(),
          final String value => int.tryParse(value) ?? 0,
          _ => 0,
        };
        final signalId = RoomCallMediaSignalCommandCodec.resolveInboundSignalId(
          roomMediaCmd,
          senderProfileId: senderProfileId,
          senderDeviceId: senderDeviceId,
        );
        final signalCreatedAtMs = switch (roomMediaCmd['createdAtMs']) {
          final int value => value,
          final num value => value.toInt(),
          final String value => int.tryParse(value) ?? 0,
          _ => DateTime.now().millisecondsSinceEpoch,
        };
        final reason =
            (roomMediaCmd['reason'] as String?)?.trim().toLowerCase() ?? '';
        final fromProfileId = (senderProfileId ?? '').trim();
        if (action == 'descriptor_updated' &&
            roomId.isNotEmpty &&
            callId.isNotEmpty) {
          if (_shouldDropDuplicateInboundRoomCallMediaSignal(
            signalId: signalId,
            action: action,
            roomId: roomId,
            callId: callId,
            sessionId: sessionId,
            fromProfileId: fromProfileId,
            fromDeviceId: senderDeviceId,
          )) {
            handledCommand = true;
            continue;
          }
          _dispatchRoomCallMediaSignal(
            RoomCallMediaSignalEvent(
              action: action,
              roomId: roomId,
              callId: callId,
              sessionId: sessionId.isEmpty ? callId : sessionId,
              signalId: signalId,
              fromProfileId: fromProfileId,
              fromDeviceId: senderDeviceId,
              descriptorVersion: descriptorVersion,
              stateVersion: stateVersion,
              reason: reason,
              createdAtMs: signalCreatedAtMs,
            ),
          );
        }
        handledCommand = true;
        continue;
      }

      final reactionCmd = _parseReactionCommand(msgEvent.text);
      if (reactionCmd != null) {
        final eventId = (reactionCmd['eventId'] as String?) ?? '';
        final convoId = (reactionCmd['convoId'] as String?) ?? '';
        final emoji = (reactionCmd['emoji'] as String?) ?? '';
        final actorProfileId = (reactionCmd['actorProfileId'] as String?) ?? '';
        final removed = reactionCmd['removed'] == true;
        // 🔴 РЕАКЦИЯ — ТОЛЬКО ОТ СВОЕГО ИМЕНИ И В СВОЕЙ ПЕРЕПИСКЕ (17.09.2026).
        // Автор и переписка брались из самой команды: участник комнаты ставил
        // и снимал реакции за других (и за меня), посторонний — в чужих чатах.
        final reactionVerdict =
            (eventId.isNotEmpty &&
                convoId.isNotEmpty &&
                actorProfileId.isNotEmpty &&
                emoji.isNotEmpty)
            ? await _authorizedInboundReactionConvoId(
                db: db,
                commandConvoId: convoId,
                eventId: eventId,
                actorProfileId: actorProfileId,
                senderDeviceId: senderDeviceId,
                senderProfileId: senderProfileId,
              )
            : null;
        final reactionConvoId = reactionVerdict?.convoId;
        if (reactionVerdict != null &&
            reactionConvoId == null &&
            reactionVerdict.deferrable &&
            !fromDeferredReplay) {
          // Новый участник, чей состав ещё не дошёл: реакцию не теряем.
          await _storeDeferredRoomInbound(
            db: db,
            groupId: convoId,
            senderProfile: reactionVerdict.senderPid,
            senderDeviceId: senderDeviceId,
            msgEventId: msgEvent.eventId,
            commandText: msgEvent.text,
            msgId: msgId,
            ciphertextB64: ciphertextB64,
            createdAtMs: payload.createdAtMs,
          );
        }
        if (reactionConvoId != null) {
          if (removed) {
            await db.messageReactionDelete(
              eventId: eventId,
              profileId: actorProfileId,
            );
            _changed.add(null);
          } else {
            final changed = await db.messageReactionUpsert(
              eventId: eventId,
              convoId: reactionConvoId,
              profileId: actorProfileId,
              emoji: emoji,
              actorName: reactionCmd['actorName'] as String?,
              actorAvatarPath: reactionCmd['actorAvatarPath'] as String?,
            );
            if (changed) {
              _changed.add(null);
            }
          }
        }
        handledCommand = true;
        continue;
      }

      final roomInviteCmd = _parseRoomInviteCommand(msgEvent.text);
      if (roomInviteCmd != null) {
        await _handleRoomInviteCommand(
          db: db,
          command: roomInviteCmd,
          senderProfileId: senderProfileId,
        );
        handledCommand = true;
        continue;
      }

      // QR pairing introduction: scanner sends this after addContact so the
      // scanned peer auto-promotes the sender to a contact instead of routing
      // the first message into the Requests inbox.
      if (isQrPairingIntroductionCommandText(msgEvent.text)) {
        final introPid = (senderProfileId ?? '').trim();
        if (introPid.isNotEmpty) {
          final existingContact = await db.contactGet(introPid);
          if (existingContact == null) {
            final introData = parseQrPairingIntroductionCommand(msgEvent.text);
            final senderName = introData?.scannerDisplayName?.trim();
            await db.contactUpsert(
              profileId: introPid,
              displayName: (senderName != null && senderName.isNotEmpty)
                  ? senderName
                  : null,
            );
            // Merge any messages that already landed in req:<pid> and create
            // the 1:1 conversation if it doesn't exist yet.
            await db.requestAccept(profileId: introPid);
            unawaited(refreshContactDevices(introPid).catchError((_) {}));
            unawaited(refreshProfileMeta(introPid).catchError((_) {}));
            DiagLog.event('request', 'qr_pair_auto_accept', {
              'peer': DiagLog.pfx(introPid),
            });
            _changed.add(null);
          }
        }
        handledCommand = true;
        continue;
      }

      final groupCmd = _parseGroupMessageCommand(msgEvent.text);
      if (groupCmd != null) {
        if (crypto == null) return false;
        final groupId = (groupCmd['groupId'] as String?) ?? '';
        final groupTitle = ((groupCmd['groupTitle'] as String?) ?? 'Group')
            .trim();
        final kind = ((groupCmd['kind'] as String?) ?? 'message')
            .trim()
            .toLowerCase();
        final msgEventId = (groupCmd['msgEventId'] as String?) ?? '';
        final bodyText = (groupCmd['text'] as String?) ?? '';
        final replyToId = groupCmd['replyToPayloadEventId'] as String?;
        final mentions = ((groupCmd['mentions'] as List?) ?? const <Object?>[])
            .map(MsgMentionV1.fromJson)
            .whereType<MsgMentionV1>()
            .toList(growable: false);
        final blobId = (groupCmd['blobId'] as String?) ?? '';
        final fileKeyB64 = (groupCmd['fileKeyB64'] as String?) ?? '';
        final blobAccessTokenB64 = (groupCmd['blobAccessTokenB64'] as String?)
            ?.trim();
        final attachmentSize = (groupCmd['sizeBytes'] as num?)?.toInt() ?? 0;
        final attachmentMime = (groupCmd['mime'] as String?)?.trim();
        final mediaGroupId = (groupCmd['mediaGroupId'] as String?)?.trim();
        final attachmentCaption = (groupCmd['caption'] as String?)?.trim();
        final attachmentFilename = (groupCmd['filename'] as String?)?.trim();
        final attachmentWidth = (groupCmd['width'] as num?)?.toInt();
        final attachmentHeight = (groupCmd['height'] as num?)?.toInt();
        final attachmentThumbB64 = (groupCmd['thumb_b64'] as String?);
        final attachmentVideoNote = groupCmd['videoNote'] == true;
        final attachmentMusicTitle = (groupCmd['musicTitle'] as String?)
            ?.trim();
        final attachmentMusicArtist = (groupCmd['musicArtist'] as String?)
            ?.trim();
        final attachmentDurationMs = switch (groupCmd['durationMs']) {
          final int value => value,
          final num value => value.toInt(),
          final String value => int.tryParse(value),
          _ => null,
        };
        final attachmentWaveform = (groupCmd['waveform'] as List?)
            ?.map((e) => (e as num).toInt().clamp(0, 100))
            .toList(growable: false);
        final messageTopicId = (groupCmd['topicId'] as String?)?.trim();
        // Карточку ссылки готовил отправитель; разбор не бросает никогда.
        final messageLinkPreview = kind == 'message'
            ? LinkPreviewV1.fromJson(groupCmd['linkPreview'])
            : null;
        final normalizedMessageTopicId =
            (messageTopicId == null || messageTopicId.isEmpty)
            ? null
            : messageTopicId;
        final memberIds = ((groupCmd['memberProfileIds'] as List?) ?? const [])
            .whereType<String>()
            .where((m) => m.trim().isNotEmpty)
            .map((m) => m.trim())
            .toList(growable: false);
        final senderProfile = (senderProfileId ?? '').trim();
        // Envelope-embedded sender profile id (the sender stamps its own pid
        // outgoing). Present even when live device→profile resolution fails, so
        // it — not the possibly-null `senderProfileId` parameter — is the
        // reliable self-echo signal for the notification guard below.
        final embeddedSenderProfileId =
            ((groupCmd['senderProfileId'] as String?) ?? '').trim();
        // 🔴 ПОДПИСЬ ИЗ КОНВЕРТА В ПРИВЯЗКУ «УСТРОЙСТВО → ПРОФИЛЬ» НЕ ПИШЕТСЯ
        // (17.09.2026). Раньше писалась всегда и ПОВЕРХ проверенной сервером:
        // один конверт от любого, кто может мне написать, привязывал его
        // устройство к чужому профилю — и к МОЕМУ. Дальше его провода шли в
        // переписку с тем человеком, а с моим профилем устройство считалось
        // «своим» (`_applyDecryptedInbound` → `_rememberOwnDeviceId`, после
        // перезапуска — `_loadKnownOwnDeviceIdsFromDb`). Проверка через пять
        // минут не спасала: `rebindProfileId` переносила переписку человека
        // на самозванца. Привязку ставит только приём (кэш или сервер ключей,
        // который отвечает и про незнакомых участников). Неузнанному автору
        // экран комнаты сам доспрашивает сервер (`warmProfileIdForDeviceSoon`);
        // снимаем задержку, чтобы тот не ждал пять минут после сбоя приёма.
        if (senderDeviceId != null &&
            senderDeviceId.trim().isNotEmpty &&
            !isOwnDeviceId(senderDeviceId)) {
          if (senderProfile.isNotEmpty) {
            if (embeddedSenderProfileId.isNotEmpty &&
                embeddedSenderProfileId != senderProfile) {
              DiagLog.event('room', 'sender_claim_mismatch', {
                'group': DiagLog.pfx(groupId),
                'sender_dev': DiagLog.pfx(senderDeviceId.trim()),
              });
            }
          } else if (!_backgroundInboundMode) {
            _deviceProfileLookupAtMs.remove(senderDeviceId.trim());
          }
        }
        final systemAction = ((groupCmd['action'] as String?) ?? '').trim();
        final actorProfileId = ((groupCmd['actorProfileId'] as String?) ?? '')
            .trim();
        final actorDisplayName =
            ((groupCmd['actorDisplayName'] as String?) ?? '').trim();
        final targetProfileId = ((groupCmd['targetProfileId'] as String?) ?? '')
            .trim();
        final targetDisplayName =
            ((groupCmd['targetDisplayName'] as String?) ?? '').trim();
        final changedKeys = ((groupCmd['changedKeys'] as List?) ?? const [])
            .whereType<String>()
            .map((value) => value.trim())
            .where((value) => value.isNotEmpty)
            .toList(growable: false);
        final stickerPackId = ((groupCmd['packId'] as String?) ?? '').trim();
        final stickerPackVersion = switch (groupCmd['packVersion']) {
          final int value => value,
          final num value => value.toInt(),
          final String value => int.tryParse(value) ?? 1,
          _ => 1,
        };
        final stickerId = ((groupCmd['stickerId'] as String?) ?? '').trim();
        final stickerEmojiHint = ((groupCmd['emojiHint'] as String?) ?? '')
            .trim();
        final stickerLabel = ((groupCmd['label'] as String?) ?? '').trim();
        final stickerAnimated = groupCmd['animated'] == true;
        final stickerFormat = ((groupCmd['format'] as String?) ?? 'png').trim();
        // User-sticker pixel handles (null for catalog stickers). blobId /
        // fileKeyB64 / blobAccessTokenB64 / sizeBytes are parsed generically
        // above (shared with attachments); these carry the rest.
        final stickerWidth = (groupCmd['stickerWidth'] as num?)?.toInt();
        final stickerHeight = (groupCmd['stickerHeight'] as num?)?.toInt();
        final stickerInlinePngB64 = (groupCmd['inlinePngB64'] as String?)?.trim();
        final stickerPackTitle = (groupCmd['packTitle'] as String?)?.trim();
        final stickerPackCount = (groupCmd['packStickerCount'] as num?)?.toInt();
        final stickerPackOriginPid = (groupCmd['packOriginPid'] as String?)
            ?.trim();
        final shouldNotifyVisibleGroupMessage =
            kind == 'message' &&
            !isDeleteForAllCommandText(bodyText) &&
            !isHiddenMessageControlText(bodyText);

        if (groupId.isNotEmpty && msgEventId.isNotEmpty) {
          final groupCreatedAtMs =
              (groupCmd['createdAtMs'] as num?)?.toInt() ?? now;
          if (await _shouldDropConversationEventByClearCutoff(
            convoId: groupId,
            createdAtMs: groupCreatedAtMs,
          )) {
            handledCommand = true;
            continue;
          }
          final settingsRow = await db.groupSettingsGet(groupId);
          final authoritativeStateVersion =
              (settingsRow?['state_version'] as num?)?.toInt() ?? 0;
          String effectiveGroupTitle = groupTitle.isEmpty
              ? 'Group'
              : groupTitle;
          Set<String> authoritativeMembers = const <String>{};
          if (authoritativeStateVersion > 0) {
            final convo = await db.convoGet(groupId);
            final existingTitle = ((convo?['title'] as String?) ?? '').trim();
            if (existingTitle.isNotEmpty) {
              effectiveGroupTitle = existingTitle;
            }
            authoritativeMembers = (await db.groupMembersList(groupId))
                .map((row) => (row['member_profile_id'] as String?) ?? '')
                .where((memberId) => memberId.isNotEmpty)
                .toSet();
            if (senderProfile.isNotEmpty &&
                !authoritativeMembers.contains(senderProfile)) {
              if (fromDeferredReplay) {
                // Safety net: re-applying an already-parked frame but the sender
                // STILL isn't a member (membership changed since the flush check)
                // — never re-park; drop to avoid a park→replay→park loop.
                handledCommand = true;
                continue;
              }
              // A1: do NOT permanently drop a message from a sender missing from
              // our local roster — that is the room-side analogue of the 1:1
              // loss fixed earlier. It is almost always a just-added member whose
              // add-snapshot lost the race (durable A5 snapshots + the relay's
              // FIFO mailbox make this rare). Reconcile authoritative membership
              // from the relay before deciding.
              final isMember = await _senderIsRoomMemberAfterRelayReconcile(
                groupId,
                senderProfile,
                settingsRow,
              );
              if (!isMember) {
                // A1 ZERO-LOSS: the relay can't (yet) confirm the sender as a
                // member — but the frame is already DECRYPTED, so dropping-and-
                // acking would lose it forever (the relay DELETEs on ack, and the
                // ratchet key is consumed so the wire can't be re-decrypted). Park
                // the decrypted frame locally and ack; it is re-applied the moment
                // membership converges (snapshot apply / periodic sweep), and
                // TTL-pruned if the sender is never confirmed.
                await _storeDeferredRoomInbound(
                  db: db,
                  groupId: groupId,
                  senderProfile: senderProfile,
                  senderDeviceId: senderDeviceId,
                  msgEventId: msgEventId,
                  commandText: msgEvent.text,
                  msgId: msgId,
                  ciphertextB64: ciphertextB64,
                  createdAtMs: groupCreatedAtMs,
                );
                handledCommand = true;
                continue;
              }
              authoritativeMembers = (await db.groupMembersList(groupId))
                  .map((row) => (row['member_profile_id'] as String?) ?? '')
                  .where((memberId) => memberId.isNotEmpty)
                  .toSet();
            }
          }
          await db.convoEnsureGroup(
            groupId: groupId,
            title: effectiveGroupTitle,
          );
          if (authoritativeStateVersion <= 0) {
            for (final memberId in memberIds) {
              await db.groupMemberEnsure(
                groupId: groupId,
                memberProfileId: memberId,
              );
            }
            if (senderProfile.isNotEmpty) {
              await db.groupMemberEnsure(
                groupId: groupId,
                memberProfileId: senderProfile,
              );
            }
          }

          final syntheticPayload =
              (kind == 'attachment' &&
                  blobId.isNotEmpty &&
                  fileKeyB64.isNotEmpty)
              ? E2ePayloadV1(
                  senderDeviceId: senderDeviceId ?? 'unknown',
                  createdAtMs: groupCreatedAtMs,
                  events: [
                    AttachmentEventV1(
                      eventId: msgEventId,
                      blobId: blobId,
                      fileKeyB64: fileKeyB64,
                      blobAccessTokenB64:
                          (blobAccessTokenB64 != null &&
                              blobAccessTokenB64.isNotEmpty)
                          ? blobAccessTokenB64
                          : null,
                      sizeBytes: attachmentSize,
                      mime:
                          (attachmentMime != null && attachmentMime.isNotEmpty)
                          ? attachmentMime
                          : null,
                      replyToEventId: replyToId,
                      mediaGroupId:
                          (mediaGroupId != null && mediaGroupId.isNotEmpty)
                          ? mediaGroupId
                          : null,
                      waveform:
                          (attachmentWaveform != null &&
                              attachmentWaveform.isNotEmpty)
                          ? attachmentWaveform
                          : null,
                      topicId: normalizedMessageTopicId,
                      caption:
                          (attachmentCaption != null &&
                              attachmentCaption.isNotEmpty)
                          ? attachmentCaption
                          : null,
                      filename:
                          (attachmentFilename != null &&
                              attachmentFilename.isNotEmpty)
                          ? attachmentFilename
                          : null,
                      videoNote: attachmentVideoNote,
                      durationMs: attachmentDurationMs,
                      musicTitle:
                          (attachmentMusicTitle == null ||
                              attachmentMusicTitle.isEmpty)
                          ? null
                          : attachmentMusicTitle,
                      musicArtist:
                          (attachmentMusicArtist == null ||
                              attachmentMusicArtist.isEmpty)
                          ? null
                          : attachmentMusicArtist,
                      width: attachmentWidth,
                      height: attachmentHeight,
                      thumbB64: attachmentThumbB64,
                    ),
                  ],
                )
              : kind == 'sticker' &&
                    stickerPackId.isNotEmpty &&
                    stickerId.isNotEmpty
              ? E2ePayloadV1(
                  senderDeviceId: senderDeviceId ?? 'unknown',
                  createdAtMs: groupCreatedAtMs,
                  events: [
                    StickerEventV1(
                      eventId: msgEventId,
                      packId: stickerPackId,
                      packVersion: stickerPackVersion,
                      stickerId: stickerId,
                      emojiHint: stickerEmojiHint,
                      label: stickerLabel,
                      animated: stickerAnimated,
                      format: stickerFormat.isEmpty ? 'png' : stickerFormat,
                      replyToEventId: replyToId,
                      topicId: normalizedMessageTopicId,
                      // USER-sticker pixels so the room recipient can download +
                      // render them (null for catalog stickers). Without these
                      // the sticker showed nothing to other room members.
                      blobId: blobId.isEmpty ? null : blobId,
                      fileKeyB64: fileKeyB64.isEmpty ? null : fileKeyB64,
                      blobAccessTokenB64:
                          (blobAccessTokenB64 == null ||
                              blobAccessTokenB64.isEmpty)
                          ? null
                          : blobAccessTokenB64,
                      sizeBytes: attachmentSize > 0 ? attachmentSize : null,
                      width: stickerWidth,
                      height: stickerHeight,
                      inlinePngB64:
                          (stickerInlinePngB64 != null &&
                              stickerInlinePngB64.isNotEmpty)
                          ? stickerInlinePngB64
                          : null,
                      packTitle:
                          (stickerPackTitle != null &&
                              stickerPackTitle.isNotEmpty)
                          ? stickerPackTitle
                          : null,
                      packStickerCount: stickerPackCount,
                      packOriginPid:
                          (stickerPackOriginPid != null &&
                              stickerPackOriginPid.isNotEmpty)
                          ? stickerPackOriginPid
                          : null,
                    ),
                  ],
                )
              : kind == 'system'
              ? E2ePayloadV1(
                  senderDeviceId: senderDeviceId ?? 'unknown',
                  createdAtMs: groupCreatedAtMs,
                  events: [
                    SystemEventV1(
                      eventId: msgEventId,
                      text: bodyText,
                      action: systemAction.isEmpty ? null : systemAction,
                      actorProfileId: actorProfileId.isEmpty
                          ? null
                          : actorProfileId,
                      actorDisplayName: actorDisplayName.isEmpty
                          ? null
                          : actorDisplayName,
                      targetProfileId: targetProfileId.isEmpty
                          ? null
                          : targetProfileId,
                      targetDisplayName: targetDisplayName.isEmpty
                          ? null
                          : targetDisplayName,
                      changedKeys: changedKeys,
                    ),
                  ],
                )
              : E2ePayloadV1(
                  senderDeviceId: senderDeviceId ?? 'unknown',
                  createdAtMs: groupCreatedAtMs,
                  events: [
                    MsgEventV1(
                      eventId: msgEventId,
                      text: bodyText,
                      replyToEventId: replyToId,
                      mentions: mentions,
                      topicId: normalizedMessageTopicId,
                      linkPreview: messageLinkPreview,
                    ),
                  ],
                );
          final localCipher = base64Encode(
            await crypto.encrypt(syntheticPayload.encode()),
          );
          final syntheticEventId =
              'grp:$msgEventId:${senderDeviceId ?? 'unknown'}';
          final exists = await db.eventGet(syntheticEventId);
          if (exists == null) {
            if (kind == 'attachment' &&
                blobId.isNotEmpty &&
                fileKeyB64.isNotEmpty) {
              final createdAt = DateTime.now().millisecondsSinceEpoch;
              await db.attachmentUpsert(
                blobId: blobId,
                fileKeyB64: fileKeyB64,
                accessTokenB64:
                    (blobAccessTokenB64 != null &&
                        blobAccessTokenB64.isNotEmpty)
                    ? blobAccessTokenB64
                    : '',
                mime: (attachmentMime != null && attachmentMime.isNotEmpty)
                    ? attachmentMime
                    : 'application/octet-stream',
                plaintextSizeBytes: attachmentSize,
                ciphertextSizeBytes: attachmentSize,
                expiresAtMs: createdAt + (7 * 24 * 60 * 60 * 1000),
                createdAtMs: createdAt,
              );
            }
            // Sprint 2 / PR3: when the inbound group envelope was emitted by
            // one of MY own devices (self-mirror fanout from
            // `_mirrorGroupControlEnvelopeToOwnDevices`), mark the local
            // event as 'sent' so chat UI treats it as my outbound message
            // instead of an incoming one. The senderDeviceId-based "is this
            // me" check in chat_screen (`isOwnDeviceId(...)`) already
            // handles bubble alignment, but `localState` drives outbox /
            // retry plumbing — keeping it 'received' for my own sends would
            // hide failed-retry affordances and confuse read-receipt logic.
            final inboundSenderDid = (senderDeviceId ?? '').trim();
            final inboundIsOwnSend =
                inboundSenderDid.isNotEmpty && isOwnDeviceId(inboundSenderDid);
            await db.insertEvent(
              eventId: syntheticEventId,
              convoId: groupId,
              type: kind == 'attachment'
                  ? 'att'
                  : kind == 'sticker'
                  ? 'sticker'
                  : kind == 'system'
                  ? 'sys'
                  : 'msg',
              senderDeviceId: senderDeviceId ?? 'unknown',
              ciphertextB64: localCipher,
              createdAtMs: groupCreatedAtMs,
              localState: inboundIsOwnSend ? 'sent' : 'received',
              payloadEventId: msgEventId,
            );
            await db.convoTouch(
              convoId: groupId,
              atMs: DateTime.now().millisecondsSinceEpoch,
            );
            // ROOM DELIVERED RECEIPT (2026-07-30). Until now a room emitted no
            // `delivered` receipt at all — only `read`, and only when the user
            // opened the room. Two things were broken by that:
            //  * the sender had NO per-member delivery evidence, so "9 of 10
            //    members never got it" was invisible to them and to every
            //    repair path;
            //  * the room convergence backstop's detectors look for exactly
            //    this evidence, so its absence proved nothing and the backstop
            //    could not be switched on without resetting sessions at healthy
            //    rooms nobody had opened yet.
            // Mirrors the 1:1 path (which has always done this). Own sends and
            // system frames are excluded: acknowledging my own message to
            // myself is noise, and a system frame is not a user message.
            if (shouldSendRoomDeliveredReceipt(
              isOwnSend: inboundIsOwnSend,
              kind: kind,
              senderDeviceId: inboundSenderDid,
              payloadEventId: msgEventId,
            )) {
              final receiptPid = embeddedSenderProfileId.isNotEmpty
                  ? embeddedSenderProfileId
                  : senderProfile;
              try {
                await db.pendingReceiptUpsert(
                  peerDeviceId: inboundSenderDid,
                  peerProfileId: receiptPid.trim().isEmpty
                      ? null
                      : receiptPid.trim(),
                  payloadEventId: msgEventId,
                  convoId: groupId,
                  status: MessageReceiptState.delivered,
                  createdAtMs: DateTime.now().millisecondsSinceEpoch,
                  updatedAtMs: DateTime.now().millisecondsSinceEpoch,
                );
                unawaited(_flushPendingReceiptsBestEffort());
              } catch (e) {
                // Never let a receipt failure cost the message itself — the
                // pending table is retried by the receipt reconcile backstop.
                DiagLog.event('read', 'room_delivered_receipt_failed', {
                  'group': DiagLog.pfx(groupId),
                  'reason': _classifyShortReason(e),
                });
              }
            }
            if (shouldNotifyVisibleGroupMessage ||
                kind == 'attachment' ||
                kind == 'sticker') {
              // For «mentions only» mute: does this message @-mention me?
              final myPidForMention = profileId.trim();
              var mentionsMe = false;
              for (final mention in mentions) {
                if (mention.isAll ||
                    (mention.isProfile &&
                        myPidForMention.isNotEmpty &&
                        mention.profileId == myPidForMention)) {
                  mentionsMe = true;
                  break;
                }
              }
              await _maybeNotifyIncomingConvo(
                convoId: groupId,
                mentionsMe: mentionsMe,
                previewText: kind == 'attachment'
                    ? null
                    : kind == 'sticker'
                    ? SecretlyStickerCatalog.previewLabel(
                        isRu: _isRussianSystemEventLocale,
                        emojiHint: stickerEmojiHint,
                        label: stickerLabel,
                      )
                    : shouldNotifyVisibleGroupMessage
                    ? (parseForwardCommand(bodyText)?.text ?? bodyText)
                    : null,
                sourceMessageId: msgId,
                sourceCreatedAtMs: groupCreatedAtMs,
                senderDeviceId: senderDeviceId,
                // У-3 (17.09.2026): автор — со слов транспорта. Конверт может
                // назвать кого угодно, поэтому его подпись берётся только
                // когда она называет МЕНЯ: так лишь гасится моё же эхо.
                senderProfileId: senderProfile.isNotEmpty
                    ? senderProfile
                    : (embeddedSenderProfileId.isNotEmpty &&
                              embeddedSenderProfileId == profileId.trim()
                          ? embeddedSenderProfileId
                          : null),
              );
            }
          }
          _changed.add(null);
          handledCommand = true;
        }
      }
    }

    if (handledCommand) {
      return true;
    }

    // For regular chat storage choose first timeline event, not receipt.
    Object? firstEvent;
    for (final event in allEvents) {
      if (event is MsgEventV1 ||
          event is AttachmentEventV1 ||
          event is StickerEventV1 ||
          event is CallEventV1) {
        firstEvent = event;
        break;
      }
    }
    // A MIXED payload (say a key riding along with a real event) reaches here.
    // The fallback must skip the room-key wires, or the preview would be built
    // from control traffic instead of the message the user actually sent.
    if (firstEvent == null) {
      for (final event in allEvents) {
        if (!isRoomKeyWire(event)) {
          firstEvent = event;
          break;
        }
      }
    }
    // Real inbound traffic ⇒ back to the fast poll immediately.
    noteInteractiveActivity();
    final inboundCreatedAtMs = payload.createdAtMs > 0
        ? payload.createdAtMs
        : now;
    final directPreviewText = firstEvent is MsgEventV1
        ? (isDeleteForAllCommandText(firstEvent.text) ||
                  isHiddenMessageControlText(firstEvent.text)
              ? null
              : (parseForwardCommand(firstEvent.text)?.text ?? firstEvent.text))
        : (firstEvent is StickerEventV1)
        ? SecretlyStickerCatalog.previewLabel(
            isRu: _isRussianSystemEventLocale,
            emojiHint: firstEvent.emojiHint,
            label: firstEvent.label,
          )
        : (firstEvent is CallEventV1)
        ? buildCallEventPreviewText(
            l10n: _appL10n,
            isRu: _isRussianSystemEventLocale,
            result: firstEvent.result,
            direction: firstEvent.direction,
            isVideo: firstEvent.hadVideo,
            durationMs: firstEvent.durationMs,
          )
        : null;

    // Unknown unblocked senders are promoted immediately into the direct chat.
    final spid = senderProfileId;
    if (spid != null && spid.isNotEmpty) {
      if (await db.blockedProfileIsBlocked(spid)) {
        return true;
      }
      final contact = await db.contactGet(spid);
      final isContact = contact != null;
      final isMessageLike =
          firstEvent is MsgEventV1 ||
          firstEvent is AttachmentEventV1 ||
          firstEvent is StickerEventV1;
      final isVoiceAttachment =
          firstEvent is AttachmentEventV1 &&
          ((firstEvent.mime ?? '').toLowerCase().startsWith('audio/'));
      if (isMessageLike &&
          !_myAudienceAllowsCategory('messages', isContact: isContact)) {
        return true;
      }
      if (isVoiceAttachment &&
          !_myAudienceAllowsCategory('voice_messages', isContact: isContact)) {
        return true;
      }
      if (contact == null) {
        final status = await db.requestStatus(spid);
        if (status == 'blocked') {
          return true;
        }
        await db.requestAccept(profileId: spid);
        unawaited(refreshContactDevices(spid).catchError((_) {}));
        unawaited(refreshProfileMeta(spid).catchError((_) {}));
        DiagLog.event('request', 'auto_accept_inbound', {
          'peer': DiagLog.pfx(spid),
        });
      }

      final directConvoId = (senderProfileId ?? '').trim();
      if (directConvoId.isNotEmpty) {
        _setConversationTyping(
          convoId: directConvoId,
          typing: false,
          notify: false,
        );
      }
    }

    final convoId = (spid != null && spid.isNotEmpty)
        ? spid
        : (senderDeviceId != null ? 'dev:$senderDeviceId' : 'unknown');

    if (await _shouldDropConversationEventByClearCutoff(
      convoId: convoId,
      createdAtMs: inboundCreatedAtMs,
    )) {
      return true;
    }

    await db.convoEnsure1to1(peerProfileId: convoId);
    String? localCiphertextB64;
    if (crypto != null) {
      try {
        localCiphertextB64 = base64Encode(await crypto.encrypt(plainBytes));
      } catch (_) {
        // ignore
      }
    }

    final payloadEventId = (firstEvent is MsgEventV1)
        ? firstEvent.eventId
        : (firstEvent is AttachmentEventV1)
        ? firstEvent.eventId
        : (firstEvent is StickerEventV1)
        ? firstEvent.eventId
        : (firstEvent is CallEventV1)
        ? firstEvent.eventId
        : null;

    // Sprint 2 PR8 (2026-05-19): mirror parity with the group path at line
    // ~28562 — if the inbound direct envelope was actually emitted by one of
    // MY own devices (e.g. a legacy raw fanout that didn't use the mirror
    // command prefix, or a backfilled history event from the same identity),
    // persist it as `sent` so UI delivery + outbox bookkeeping treat it as
    // my outbound message instead of an incoming one. Without this, multi-
    // device sync edge-cases land in the events table as `received`, and
    // the desktop chat panel shows "only my contact's messages" for own
    // sends that bypassed the self-mirror cmd path.
    final inboundDirectSenderDid = (senderDeviceId ?? '').trim();
    final inboundDirectIsOwnSend =
        (inboundDirectSenderDid.isNotEmpty &&
            isOwnDeviceId(inboundDirectSenderDid)) ||
        ((spid ?? '').trim() == (_profileId ?? '').trim() &&
            (_profileId ?? '').trim().isNotEmpty);
    // Only a real visible event (normal text / attachment / sticker / call) may
    // be stored as a message, counted unread, or notified. A non-visible or
    // future event type (the System/Unknown fall-through) or an unrecognized
    // hidden control text is classified 'sys' → never unread, never notified.
    final firstEventIsVisibleMessage =
        (firstEvent is MsgEventV1 &&
            !isHiddenMessageControlText(firstEvent.text) &&
            !isDeleteForAllCommandText(firstEvent.text)) ||
        firstEvent is AttachmentEventV1 ||
        firstEvent is StickerEventV1 ||
        firstEvent is CallEventV1;
    // Payload-id idempotency (2026-07-23, undecryptable-recovery). Apply-dedup is
    // otherwise keyed on the RELAY msg_id, so a re-sent copy of a message we
    // already applied (NEW relay msg_id, SAME payload_event_id — exactly what the
    // NACK-driven recovery mints) would append a DUPLICATE timeline row. If this
    // payload_event_id is already applied IN THIS conversation, the wire is a
    // duplicate: ACK it (return true) and stop, no second bubble. A genuinely
    // recovered message was only ever QUARANTINED, never applied, so it is not in
    // `events` and is NOT deduped here — it applies normally. Scoped to a visible
    // peer message in the same convo so cross-convo self-mirrors and hidden
    // controls/edits are untouched.
    final dedupPayloadEventId = (payloadEventId ?? '').trim();
    if (firstEventIsVisibleMessage &&
        !inboundDirectIsOwnSend &&
        dedupPayloadEventId.isNotEmpty) {
      final existingConvo = await db.convoIdForPayloadEventId(
        dedupPayloadEventId,
      );
      if (existingConvo != null && existingConvo == convoId) {
        DiagLog.event('inbox', 'apply_dedup_payload', {
          'convo': DiagLog.pfx(convoId),
          'payload': DiagLog.pfx(dedupPayloadEventId),
        });
        return true; // already applied under another relay msg_id — ACK, no dup
      }
    }
    await db.insertEvent(
      eventId: msgId,
      convoId: convoId,
      type: !firstEventIsVisibleMessage
          ? 'sys'
          : (firstEvent is AttachmentEventV1)
          ? 'att'
          : (firstEvent is StickerEventV1)
          ? 'sticker'
          : (firstEvent is CallEventV1)
          ? 'call'
          : 'msg',
      senderDeviceId: senderDeviceId ?? 'unknown',
      ciphertextB64: ciphertextB64,
      localCiphertextB64: localCiphertextB64,
      createdAtMs: inboundCreatedAtMs,
      localState: inboundDirectIsOwnSend ? 'sent' : 'received',
      // R1: my own message (matched by profile before its device id is known as
      // mine) must never count as unread for me — insert it already-read.
      readAtMs: inboundDirectIsOwnSend ? now : null,
      payloadEventId: payloadEventId,
    );
    if (inboundDirectIsOwnSend) {
      DiagLog.event('selfsync', 'direct_raw_own_persisted_sent', {
        'convo': DiagLog.pfx(convoId),
        'evt': DiagLog.pfx(msgId),
        'sender_dev': DiagLog.pfx(senderDeviceId ?? ''),
      });
    }
    // Bump the conversation's sort key + "last message" time ONLY for a
    // VISIBLE message. Non-visible payloads (stored as 'sys' above — e.g. the
    // control/service traffic a peer's device emits when it comes back online)
    // must not jump the chat to the top of the list with a "now" timestamp
    // when the peer never actually wrote anything.
    if (firstEventIsVisibleMessage) {
      await db.convoTouch(convoId: convoId, atMs: now);
      // Экран узнаёт о сообщении ЗДЕСЬ, а не в конце метода.
      //
      // К этой точке строка уже закоммичена в `events`, а порядок чатов уже
      // обновлён — то есть `loadEvents` вернёт сообщение, и показывать его
      // можно. Всё, что идёт ниже, для показа не нужно: уведомление
      // (несколько запросов, синхронные `existsSync`/`lengthSync` и четыре
      // обращения к платформенным каналам подряд, из которых первый за сеанс
      // `setAsset` особенно долгий) и отправка квитанции.
      //
      // Второй `_changed.add(null)` в конце метода намеренно оставлен: он
      // покрывает невидимые события и ранние выходы. Дубль безвреден —
      // контроллер схлопывает тики в пределах одного оборота цикла событий,
      // так что до кадра доходит один.
      _changed.add(null);
    }
    // A non-missed call-log event (CallEventV1: completed / declined / busy /
    // failed / canceled) is just the "call" chat entry both sides record after
    // a call — it must NOT raise a "new message" notification (the ring and the
    // missed-call cue come from the call subsystem, not the chat path). Only a
    // MISSED call still notifies here. Fixes the false "new message" notification
    // both sides saw right after a normal call ended.
    final suppressCallLogNotification =
        firstEvent is CallEventV1 &&
        firstEvent.result != CallRecordResult.missed;
    if (firstEventIsVisibleMessage && !suppressCallLogNotification) {
      await _maybeNotifyIncomingConvo(
        convoId: convoId,
        previewText: directPreviewText,
        sourceMessageId: msgId,
        sourceCreatedAtMs: inboundCreatedAtMs,
        senderDeviceId: senderDeviceId,
        senderProfileId: spid,
      );
    }

    // RECEIVED-MEDIA PROTECTION (2026-07-17): record each inbound attachment's
    // metadata in the `attachments` table. The 1:1 receive path decrypts the
    // blob straight from the event (token+key inline) and never upserted here,
    // so received media was ABSENT from the attachment-cache prune's protected
    // set and got silently evicted at 21 days / under cache pressure. Awaited
    // (fast insert) so the protected set is populated before any prune runs.
    await _persistInboundAttachmentMetadata(payload);

    // OFFLINE MEDIA FIX (2026-07-17): proactively fetch inbound media in the
    // background (retried) the moment the envelope is applied — so a
    // photo/video/voice/file/music sent while the recipient was offline / in
    // deep sleep is downloaded and READY, instead of relying on a lazy on-view
    // fetch that may never fire (message drained in the background, never
    // opened) or silently fail. The envelope + blob (7-day TTL) already arrive
    // reliably; this closes the last gap where the media never became visible.
    _prefetchInboundAttachmentBlobs(payload);

    // Track peer's last-seen time for online presence indicator.
    // PRESENCE-LIE FIX R8 (2026-07-16, delivery-wake audit): stamp the peer's
    // activity at the time they SENT this message (payload.createdAtMs), NOT
    // at apply time. Apply time lies for backlogs: opening the app at 09:13
    // and draining messages the peer sent at 04:40 marked them «Онлайн» while
    // their phone had been asleep for hours — exactly what misled the field
    // test ("мы оба были онлайн", while the relay logged `recipient offline`
    // on every envelope). Clamped to `now` so a skewed peer clock can never
    // pin presence into the future; the DB write is monotonic (never
    // regresses a newer stamp), so out-of-order backlog rows are harmless.
    //
    // PRESENCE-LIE FIX R8b (2026-07-17): gate on `firstEventIsVisibleMessage`.
    // The bump previously fired for ANY inbound carrying a sender profile —
    // including the control/service traffic a peer's phone auto-emits when your
    // message push-WAKES it in the background (session-heal, key sync, delivery
    // acks; see the `convoTouch` gate above). That traffic has createdAtMs≈now,
    // so it flipped the peer to «Онлайн» for 90s even though nobody touched the
    // phone ("пишу собеседнику офлайн → он светится онлайн"). Presence now
    // requires the peer to actually WRITE (visible message here) or READ (read
    // receipt path elsewhere) — background wake alone no longer counts.
    if (firstEventIsVisibleMessage && spid != null && spid.isNotEmpty) {
      final activityAtMs = (inboundCreatedAtMs > 0 && inboundCreatedAtMs < now)
          ? inboundCreatedAtMs
          : now;
      await db.profileMetaUpdateLastSeen(
        profileId: spid,
        lastSeenAtMs: activityAtMs,
      );
    }

    // Learn-on-receive: if this inbound came from a device we don't have cached
    // for this contact, the peer likely rotated/recreated their device (account
    // recreate). Refresh their device list so OUR replies/calls/receipts target
    // the LIVE device instead of the dead one — half of the root fix for the
    // one-way break (the other half is auto-adopting their new identity key).
    if (spid != null &&
        spid.isNotEmpty &&
        senderDeviceId != null &&
        senderDeviceId.isNotEmpty &&
        !isOwnDeviceId(senderDeviceId)) {
      _maybeLearnPeerDeviceOnInbound(spid, senderDeviceId);
    }

    // Send delivered receipt back to sender for any known peer (no contact check —
    // contacts table may be empty after reinstall/data-clear, which would otherwise
    // leave the sender permanently on 1 tick even after recipient reads the message).
    if (spid != null &&
        spid.isNotEmpty &&
        senderDeviceId != null &&
        senderDeviceId.isNotEmpty &&
        did != null &&
        did.isNotEmpty &&
        (firstEvent is MsgEventV1 ||
            firstEvent is AttachmentEventV1 ||
            firstEvent is StickerEventV1)) {
      final refEventId = (firstEvent is MsgEventV1)
          ? firstEvent.eventId
          : (firstEvent is AttachmentEventV1)
          ? firstEvent.eventId
          : (firstEvent is StickerEventV1)
          ? firstEvent.eventId
          : null;
      if (refEventId != null) {
        await db.pendingReceiptUpsert(
          peerDeviceId: senderDeviceId,
          peerProfileId: spid,
          payloadEventId: refEventId,
          convoId: convoId,
          status: MessageReceiptState.delivered,
          createdAtMs: now,
          updatedAtMs: now,
        );
        // 🔴 НЕ `await` — иначе пузырь ждёт отправки квитанции.
        //
        // Строка сообщения уже в `events`, `convoTouch` уже сделан, то есть
        // для показа всё готово. А `_flushPendingReceiptsBestEffort` — это
        // разрешение профиля по устройству (при промахе кэша — СЕТЕВОЙ запрос
        // к keys с таймаутом 8 с), веер до восьми устройств получателя и
        // полное шифрование ратчетом на каждое. При мёртвом `device_id` у
        // собеседника — а ради этого случая веер и сделан — это до восьми
        // последовательных таймаутов ДО появления пузыря на экране, при
        // бюджете `_deliveryApplyTimeout` в 10 с.
        //
        // В фоне цена ещё выше: бюджет прохода 12 с, и один промах съедает
        // его целиком. Защита `_backgroundInboundMode`, которая есть в
        // `_applyDecryptedInbound`, внутри слива квитанций отсутствует.
        //
        // Групповой путь в этом же файле уже сделан именно так — см.
        // `unawaited(_flushPendingReceiptsBestEffort())` рядом с
        // `pendingReceiptUpsert` для комнат.
        //
        // Пинок очереди перенесён в хвост НАМЕРЕННО: слив кладёт квитанцию в
        // outbox, и пинок до него был бы вхолостую — квитанция пролежала бы до
        // следующего тика насоса (до 15 с в глубоком простое).
        // 🔴 `catchError` ОБЯЗАТЕЛЕН, а не для порядка: у слива квитанций
        // `try { … } finally { … }` без `catch`, то есть он бросает наружу.
        // Под `await` исключение уходило вверх по стеку и роняло ПРИМЕНЕНИЕ
        // САМОГО СООБЩЕНИЯ — конверт считался непринятым и шёл на повтор из-за
        // неудачи с квитанцией. Без `catchError` та же ошибка стала бы
        // необработанной асинхронной. Теперь провал квитанции остаётся
        // провалом квитанции: её подберёт сверка `pending_receipts`.
        // 🔴 В ФОНЕ СЛИВ НЕ ЗАПУСКАЕТСЯ ВОВСЕ (02.09.2026, разбор «горит серая
        // галочка, хотя уведомление пришло»).
        //
        // Фоновый проход по пробуждению живёт двенадцать секунд и умеет только
        // ПРИНИМАТЬ: соединения с реле у него нет (`bootstrapForBackgroundInbound`
        // поднимает базу, ратчет и ключи — но не транспорт), очередь исходящих
        // он не качает. Слив там не отправит ничего, зато зашифрует квитанции
        // ратчетом — а это запись в ратчет из задачи, которую изолят вправе
        // оборвать по бюджету на любом шаге.
        //
        // Сама квитанция уже сохранена выше, под `await`, поэтому она не
        // теряется: её подберёт слив основного изолята — при открытии
        // приложения или очередным проходом сторожа.
        if (_backgroundInboundMode) {
          DiagLog.event('receipt', 'flush_deferred_background', const {});
        } else {
          unawaited(
            _flushPendingReceiptsBestEffort()
                .then((_) {
                  if (!_transportBlocked) {
                    _kickRelayOutbox(_relay);
                  }
                })
                .catchError((Object e) {
                  DiagLog.event('receipt', 'flush_after_inbound_failed', {
                    'reason': _classifyShortReason(e),
                  });
                }),
          );
        }
      }
    }

    _changed.add(null);
    return true;
  }

  /// Authed keys-service lookup of the profile that owns [deviceId]. Pure
  /// network + crypto — no DB writes; callers persist/rebind as needed.
  /// Returns null when local identity/config is unavailable; network errors
  /// propagate so callers can bound them with timeouts and degrade.
  Future<String?> _lookupProfileForDeviceAuthed(String deviceId) async {
    final keys = _keys;
    final myPid = _profileId;
    final myDid = _deviceId;
    if (keys == null ||
        myPid == null ||
        myPid.isEmpty ||
        myDid == null ||
        myDid.isEmpty) {
      return null;
    }
    final deviceKeys = DeviceKeys.create();
    final kp = await deviceKeys.loadIdentityKeyPair(
      profileId: myPid,
      deviceId: myDid,
    );
    final tsMs = ServerClock.instance.nowMs();
    final nonceB64 = AuthSigner.randomNonceB64(bytes: 16);
    final msg = AuthSigner.keysDeviceLookupMessage(
      requesterDeviceId: myDid,
      targetDeviceId: deviceId,
      tsMs: tsMs,
      nonceB64: nonceB64,
    );
    final sigB64 = await AuthSigner.signEd25519B64(
      identityKeyPair: kp,
      message: msg,
    );
    return keys.lookupProfileByDeviceAuthed(
      requesterDeviceId: myDid,
      tsMs: tsMs,
      nonceB64: nonceB64,
      signatureB64: sigB64,
      targetDeviceId: deviceId,
    );
  }

  /// SLOW-DRAIN FIX R9 (2026-07-16): background 5-minute freshness re-verify
  /// of a CACHED device→profile mapping, extracted from the inline inbox-apply
  /// path so a slow network / wedged Keystore can never stall the serial
  /// drain. Detects profile rebinds (peer reinstalled onto a new profile) and
  /// heals the cache + convo bindings asynchronously.
  Future<void> _reverifyDeviceProfileMappingInBackground({
    required String senderDeviceId,
    required String cachedProfileId,
  }) async {
    if (_backgroundInboundMode) return; // network re-verify; foreground does it
    try {
      final lookedUp = await _lookupProfileForDeviceAuthed(
        senderDeviceId,
      ).timeout(const Duration(seconds: 8));
      if (lookedUp == null || lookedUp.isEmpty) return;
      final db = _db;
      if (db == null) return;
      if (lookedUp != cachedProfileId) {
        // У-2 (17.09.2026): переписку ПРОВЕРЕННОГО контакта молча не переносим
        // на другой профиль — это то же, что подменить собеседника. Устройство
        // просто начинает писать от нового профиля отдельным чатом.
        var verifiedContact = false;
        try {
          verifiedContact = (await db.contactDevicesList(cachedProfileId)).any(
            (row) => row['verified_at_ms'] != null,
          );
        } catch (_) {
          verifiedContact = true;
        }
        if (verifiedContact) {
          DiagLog.event('devices', 'rebind_skipped_verified', {
            'dev': DiagLog.pfx(senderDeviceId),
          });
        } else {
          try {
            await db.rebindProfileId(
              oldProfileId: cachedProfileId,
              newProfileId: lookedUp,
            );
          } catch (_) {
            // ignore — the next inbound re-arms the re-verify after the throttle
          }
        }
      }
      await db.deviceProfileUpsert(
        deviceId: senderDeviceId,
        profileId: lookedUp,
      );
      _changed.add(null);
    } catch (_) {
      // ignore — best-effort freshness; the 5-min throttle re-arms naturally
    }
  }

  Future<String?> _resolveProfileIdForDevice(String senderDeviceId) async {
    final deviceId = senderDeviceId.trim();
    if (deviceId.isEmpty) return null;

    final db = _db;
    if (db == null) return null;

    final cached = await db.deviceProfileCached(deviceId);
    if (cached != null && cached.isNotEmpty) {
      return cached;
    }

    if (_transportBlocked) return null;

    try {
      final lookedUp = await _lookupProfileForDeviceAuthed(deviceId);
      if (lookedUp != null && lookedUp.isNotEmpty) {
        await db.deviceProfileUpsert(deviceId: deviceId, profileId: lookedUp);
        // 🔴 Своё устройство — сразу своё, а не со следующего запуска.
        //
        // `_knownOwnDeviceIds` собирается при старте ровно из этой таблицы
        // (`_loadKnownOwnDeviceIdsFromDb`), поэтому строчкой ниже ничего
        // нового не появляется — появляется РАНЬШЕ. Без неё сообщение,
        // отправленное с телефона, весь сеанс висит в комнате как чужое: с
        // именем, с фотографией и не на своей стороне ленты.
        if (lookedUp == (_profileId ?? '').trim()) {
          _knownOwnDeviceIds.add(deviceId);
        }
        _changed.add(null);
        return lookedUp;
      }
    } catch (_) {
      // ignore
    }

    return null;
  }

  Future<String?> _resolvePeerProfileId(String peerProfileId) async {
    final candidate = peerProfileId.trim();
    if (candidate.isEmpty) return null;
    if (!candidate.startsWith('dev:')) return candidate;

    final senderDeviceId = candidate.substring(4).trim();
    if (senderDeviceId.isEmpty) return null;

    final db = _db;
    if (db == null) return null;

    final resolved = await _resolveProfileIdForDevice(senderDeviceId);
    if (resolved != null && resolved.isNotEmpty) {
      try {
        await db.convoMerge(fromConvoId: candidate, toConvoId: resolved);
      } catch (_) {
        // ignore
      }
      await db.convoEnsure1to1(peerProfileId: resolved);
      return resolved;
    }

    return null;
  }

  Future<Uint8List> _encryptToPeerSerialized({
    required RatchetSessionManagerV3 ratchet,
    required String selfDeviceId,
    required String peerProfileId,
    required String peerDeviceId,
    required Uint8List plaintext,
    bool forceFreshPrekey = false,
    bool forceSpkOnly = false,
  }) async {
    final queueKey = '$peerProfileId::$peerDeviceId';
    final previous =
        _outboundEncryptQueueByPeerDevice[queueKey] ?? Future<void>.value();
    final gate = Completer<void>();
    final queued = previous.then<void>((_) => gate.future);
    _outboundEncryptQueueByPeerDevice[queueKey] = queued;

    await previous;
    try {
      if (forceFreshPrekey) {
        // Wipe any live session for this peer so encryptToPeer re-runs X3DH and
        // emits a fresh prekey wire. Done HERE, inside the outbound gate, so it
        // never races a concurrent normal send mid-flight; И-3 additionally
        // routes it through resetSessionForPeer so the archive+delete also
        // serialize (via _withPeerLock) against a concurrent same-peer INBOUND
        // decrypt draining on another transport. Archive first so a straggler
        // still encrypted under the old session stays recoverable.
        await ratchet.resetSessionForPeer(peerDeviceId);
      }
      return await ratchet.encryptToPeer(
        selfDeviceId: selfDeviceId,
        peerProfileId: peerProfileId,
        peerDeviceId: peerDeviceId,
        plaintext: plaintext,
        forceSpkOnly: forceSpkOnly,
        // С-2: профиль нужен, чтобы прочитать ключ личности для подписи
        // рукопожатия. Ключ читается без создания: не тот профиль — просто
        // без подписи, как до С-2.
        selfProfileId: _profileId,
      );
    } finally {
      gate.complete();
      if (identical(_outboundEncryptQueueByPeerDevice[queueKey], queued)) {
        _outboundEncryptQueueByPeerDevice.remove(queueKey);
      }
    }
  }

  /// Похоже ли, что до устройства лечение не доедет.
  ///
  /// Отвечает `false` (лечим), когда данных нет: реле не спрашивали, профиль
  /// неизвестен, отметки не пришли. Хоронить по незнанию нельзя — молчание
  /// реле не является доказательством смерти устройства.
  bool _healTargetLooksUnreachable(String peerDeviceId) {
    final all = <RelayDeviceLiveness>[
      for (final entry in _activeDevicesCacheByProfileId.values) ...entry.liveness,
    ];
    return healTargetLooksUnreachableIn(
      liveness: all,
      deviceId: peerDeviceId,
      nowMs: DateTime.now().millisecondsSinceEpoch,
    );
  }

  /// Чистое правило «до устройства лечение не доедет» — без состояния.
  @visibleForTesting
  static bool healTargetLooksUnreachableIn({
    required List<RelayDeviceLiveness> liveness,
    required String deviceId,
    required int nowMs,
  }) {
    for (final row in liveness) {
      if (row.deviceId != deviceId) continue;
      if (row.superseded) return true;
      if (row.lastSignalMs <= 0) return false;
      final silentMs = nowMs - row.lastSignalMs;
      if (silentMs < 0) return false; // часы разошлись — не судим
      return silentMs > _callTargetSilentCutoffMs;
    }
    // Данных нет — лечим, как раньше. Молчание реле не доказывает смерть.
    return false;
  }

  /// Send an empty ("session reset") ping to [peerDeviceId] so the peer
  /// receives a fresh prekey wire and reinitialises its broken ratchet state.
  /// Called after we drop an unrecoverable inbound and clear our local
  /// `sessions_v3` row — without this, the peer keeps encrypting under its
  /// stale chain and every subsequent message will also fail.
  ///
  /// Best-effort, debounced per peer device. The empty payload (events=[]) is
  /// a harmless no-op on the receiver after decrypt.
  void _scheduleSessionResetPing(String peerDeviceId, String cause) {
    if (_backgroundInboundMode) return; // foreground heals; bg has no relay
    if (peerDeviceId.isEmpty) return;
    // 🔴 НЕ ЛЕЧИМ ТО, ЧТО НЕЧЕМ РАЗБУДИТЬ (15.08.2026).
    //
    // Лечение рассылается по ВСЕМ устройствам контакта, включая копии,
    // оставшиеся от переустановки: у них нет токена пушей, они не забирают
    // почту, и конверт лечения до них не доедет НИКОГДА. Замер: копия
    // `7d1e2be2` молчит пятые сутки и продолжает получать лечение наравне с
    // живым телефоном.
    //
    // 🔴 ЭТО НЕ ИСКЛЮЧЕНИЕ ИЗ ДОСТАВКИ. Сообщения копия получает как прежде и
    // дождётся хозяина. Отсекается только лечение — оно адресовано устройству,
    // которое СЕЙЧАС должно ответить, а молчащее пятые сутки не ответит.
    //
    // Оживёт — отметка активности обновится, и лечение пойдёт снова: проверка
    // смотрит свежие данные, а не разовое решение.
    if (_healTargetLooksUnreachable(peerDeviceId)) {
      _recoveryDeclined('reset_ping', 'unreachable:$cause',
          deviceId: peerDeviceId);
      return;
    }
    final nowMs = DateTime.now().millisecondsSinceEpoch;
    final lastAt = _sessionResetPingAtMs[peerDeviceId] ?? 0;
    if (nowMs - lastAt < _sessionResetPingDebounceMs) {
      _recoveryDeclined('reset_ping', 'debounce:$cause',
          deviceId: peerDeviceId);
      return;
    }
    _sessionResetPingAtMs[peerDeviceId] = nowMs;
    // Fix D: the SMALLER device_id leads immediately; the LARGER waits a short
    // grace so the leader's reset-ping can heal us first and cancel ours (glare
    // symmetry break). A pending grace is kept (not restacked); it is cancelled
    // by _noteRecoverySuccess on heal, or by _forceSessionResetPing.
    final graceMs = resetPingInitiatorGraceMs(_deviceId ?? '', peerDeviceId);
    if (graceMs <= 0) {
      _dispatchSessionResetPing(peerDeviceId, cause);
      return;
    }
    if (_resetPingGraceTimers.containsKey(peerDeviceId)) return;
    _resetPingGraceTimers[peerDeviceId] = Timer(
      Duration(milliseconds: graceMs),
      () {
        _resetPingGraceTimers.remove(peerDeviceId);
        // Reaching here means we did NOT heal during the grace (a heal would
        // have cancelled this via _noteRecoverySuccess) → initiate anyway.
        _dispatchSessionResetPing(peerDeviceId, _resetCauseGraceExpired);
      },
    );
  }

  /// Force a session-reset ping immediately, BYPASSING the per-device debounce.
  ///
  /// Used by the self-healing recovery (FIX A / FIX D) when a peer is stuck —
  /// a reset ping was already sent within the debounce window but inbound is
  /// still failing (lost prekey), so we must re-ping even though the debounce
  /// would normally suppress it. Still stamps `_sessionResetPingAtMs` so the
  /// *normal* path keeps debouncing afterwards; the escalation ladder (FIX A) /
  /// 90 s sweep cadence (FIX D) is what bounds how often this can fire.
  void _forceSessionResetPing(String peerDeviceId, String cause) {
    if (_backgroundInboundMode) return; // foreground heals; bg has no relay
    if (peerDeviceId.isEmpty) return;
    // Fix D: dispatching immediately supersedes any pending grace-delayed ping.
    _resetPingGraceTimers.remove(peerDeviceId)?.cancel();
    _sessionResetPingAtMs[peerDeviceId] = DateTime.now().millisecondsSinceEpoch;
    _dispatchSessionResetPing(peerDeviceId, cause);
    // The reset just started a NEW outbound session generation — any "send
    // later" wire still held on the relay for this device was encrypted under
    // the one that no longer exists and will be undecryptable at release.
    // Re-encrypt them NOW rather than waiting for the periodic sweep.
    unawaited(_refreshHeldScheduledWires());
  }

  /// Pure initiator election for Fix D (2026-07-24, docs/BUG_AUDIT.md). Returns
  /// the grace (ms) the LOCAL device must wait before firing a REACTIVE
  /// reset-ping to [peerDeviceId], so two simultaneously-desynced peers don't
  /// both fire a fresh prekey and diverge (glare). The smaller device_id
  /// (lexicographic) leads with 0 grace; the larger waits [graceMs], during
  /// which the leader's reset can heal + cancel this one. Empty ids ⇒ 0 (can't
  /// compare ⇒ initiate immediately, never deadlock). Deterministic and
  /// symmetric across the pair (both compare the SAME two ids), so exactly one
  /// side leads.
  @visibleForTesting
  static int resetPingInitiatorGraceMs(
    String myDeviceId,
    String peerDeviceId, {
    int graceMs = _resetPingInitiatorGraceMs,
  }) {
    if (myDeviceId.isEmpty || peerDeviceId.isEmpty) return 0;
    return myDeviceId.compareTo(peerDeviceId) <= 0 ? 0 : graceMs;
  }

  // ── SCHEDULED RE-KEY REFRESH (2026-07-19) ─────────────────────────────────
  // A "send later" message is encrypted at SCHEDULE time but delivered at T.
  // Any session rotation in between (either side's rekey) leaves the held
  // ciphertext referencing a dead session — proven live: two wires encrypted
  // 12 s apart, the one released before a rotation decrypted, the one after it
  // did not. The recipient cannot fix that at T; only the sender can, BEFORE T.
  //
  // This sweep finds relay-held wires older than the CURRENT session to their
  // target (outbox.created_at_ms < sessions_v3.epoch — the handshake birth
  // stamp, preserved across ratchet advances), re-encrypts the same payload
  // (same app event id → receiver dedup), uploads it as a NEW transport msg
  // with the SAME deliver_at, and retracts the stale copy server-side
  // (/v1/cancel_scheduled refuses once released, so a delivered message can
  // never be unsent). Runs on the 30s watchdog tick + immediately after any
  // reset ping we initiate.
  bool _heldScheduledRefreshRunning = false;

  Future<void> _refreshHeldScheduledWires() async {
    if (_heldScheduledRefreshRunning) return;
    _heldScheduledRefreshRunning = true;
    try {
      final db = _db;
      final ratchet = _ratchetV3;
      final relay = _relay;
      final did = _deviceId;
      if (db == null || ratchet == null || relay == null || did == null) {
        return;
      }
      final now = DateTime.now().millisecondsSinceEpoch;
      List<Map<String, Object?>> rows;
      try {
        rows = await db.outboxHeldScheduledRows(nowMs: now);
      } catch (_) {
        return;
      }
      for (final row in rows) {
        final oldMsgId = ((row['msg_id'] as String?) ?? '').trim();
        final toDeviceId = ((row['to_device_id'] as String?) ?? '').trim();
        final eventIdRef = ((row['event_id_ref'] as String?) ?? '').trim();
        final convoId = ((row['convo_id'] as String?) ?? '').trim();
        final deliverAtMs = (row['deliver_at_ms'] as num?)?.toInt() ?? 0;
        final createdAtMs = (row['created_at_ms'] as num?)?.toInt() ?? 0;
        if (oldMsgId.isEmpty ||
            toDeviceId.isEmpty ||
            eventIdRef.isEmpty ||
            convoId.isEmpty) {
          continue;
        }
        // A room's held wire cannot be re-encrypted from the local copy — that
        // copy is the bare message, not the group envelope (see
        // [canReplayLocalCopyToPeer]). Today room control rows carry no convo_id
        // so they never reach here; this guard is what keeps that an accident we
        // do not depend on. Consequence, accepted and documented: a scheduled
        // ROOM message that outlives a session reset lands undecryptable, and
        // the NACK path heals the session for everything after it.
        if (!canReplayLocalCopyToPeer(convoId)) continue;
        // Too close to release: swapping now races the relay's release tick —
        // let the old copy fire; if it lands stale the NACK backstop resends.
        if (deliverAtMs - now < 3000) continue;
        int sessionEpoch;
        try {
          sessionEpoch = await db.sessionV3EpochFor(toDeviceId);
        } catch (_) {
          continue;
        }
        // No session / pre-epoch legacy: nothing to compare against — the next
        // tick after the handshake lands will judge it.
        if (sessionEpoch <= 0) continue;
        if (createdAtMs >= sessionEpoch) continue; // encrypted under CURRENT session
        Uint8List? plain;
        try {
          plain = await _decryptStoredLocalPayloadBytes(eventIdRef);
        } catch (_) {
          plain = null;
        }
        if (plain == null) continue;
        try {
          final wire = await _encryptToPeerSerialized(
            ratchet: ratchet,
            selfDeviceId: did,
            peerProfileId: convoId,
            peerDeviceId: toDeviceId,
            plaintext: plain,
          );
          final newMsgId = _uuid.v4();
          await db.outboxUpsert(
            msgId: newMsgId,
            toDeviceId: toDeviceId,
            ciphertextB64: base64Encode(wire),
            ttlSeconds: _outboxUserMessageTtlSeconds,
            state: OutboxSendState.pending,
            attemptCount: 0,
            nextRetryAtMs: now,
            createdAtMs: now,
            correlationId: (row['correlation_id'] as String?)?.trim(),
            payloadEventId: (row['payload_event_id'] as String?)?.trim(),
            convoId: convoId,
            transportMetaJson: row['transport_meta_json'] as String?,
            expiresAtMs: deliverAtMs + _outboxUserMessageTtlMs,
            eventIdRef: eventIdRef,
            deliverAtMs: deliverAtMs,
          );
          // Retract the stale copy BEFORE the fresh one is pumped: if the
          // cancel loses the race (or the network drops it) the old wire fires
          // and fails once — bounded noise the NACK backstop absorbs. The local
          // row is superseded either way; keeping it would re-trigger this very
          // sweep forever.
          final cancelled = await relay.cancelScheduled(
            toDeviceId: toDeviceId,
            msgId: oldMsgId,
          );
          await db.outboxDeleteByMsgId(oldMsgId);
          DiagLog.event('send', 'sched_reupload', {
            'to_dev': DiagLog.pfx(toDeviceId),
            'cancelled_old': cancelled,
            'deliver_in_s': ((deliverAtMs - now) / 1000).round(),
          });
        } catch (e) {
          DiagLog.event('send', 'sched_reupload_failed', {
            'to_dev': DiagLog.pfx(toDeviceId),
            'reason': _classifyShortReason(e),
          });
          continue;
        }
      }
      _kickRelayOutbox();
    } finally {
      _heldScheduledRefreshRunning = false;
    }
  }

  /// FIX (2026-07-13, sender-side session convergence — TZ §20 pillar 1).
  /// Periodic backstop (runs inside the service watchdog): when MY outbound 1:1
  /// messages are relay-ACKed but keep failing to earn an end-to-end 'delivered'
  /// receipt while the peer is provably alive, the session is silently desynced
  /// — force a crypto-clean re-key so the channel converges with NO user action.
  /// Crypto-untouched: it only READS delivery state and calls the existing
  /// [_forceSessionResetPing], which re-initiates a fresh X3DH toward the peer's
  /// CURRENT bundle — the reliable direction, where the responder still holds
  /// its own freshly-published one-time-prekey (so adoption cannot wedge on a
  /// consumed OTK, unlike waiting to adopt the peer's reset prekey). Conservative
  /// and debounced (shared [_sessionResetPingAtMs]) so it can never thrash or
  /// double-fire with the receiver-side escalator.
  /// TZ Epic A1 — RECIPIENT side: enqueue a `nack_undecryptable` receipt for a
  /// wire that exhausted its decrypt budget and got quarantined. Rides the
  /// DURABLE pending_receipts queue: if our outbound session to that peer is
  /// equally broken right now, the flush wire may itself fail to decrypt — but
  /// both sides' reset escalators exchange fresh X3DH prekey wires (I6, never
  /// ratchet-dependent), and the queued receipt re-flushes until it lands
  /// post-heal. Debounced per msg_id so redeliver re-offers don't spam.
  /// TZ Epic A reachability (2026-07-19). Emits a NACK for a wire that is
  /// ALREADY parked in quarantine and STILL refuses to decrypt.
  ///
  /// Why this exists: the NACK used to be emitted at exactly ONE moment — when
  /// a wire first entered quarantine. Everything parked before that code
  /// shipped (or parked in a session that died before the receipt flushed) was
  /// therefore invisible to the sender forever, and the periodic replay sweep
  /// retried it in silence. A device with a backlog of undecryptable wires
  /// would never heal, which is precisely the state Epic A was built to end.
  ///
  /// A wire that is quarantined AND still undecryptable is the strongest
  /// evidence we can have that the sender's session is broken, so it is the
  /// right trigger. The claim is persisted in the quarantine row, so the sweep
  /// emits at most one NACK per wire no matter how often it runs or how many
  /// times the app restarts.
  /// Records that a recovery path DECLINED to act, and which guard declined.
  ///
  /// STAGE 0 of TZ_INVARIANTS_2026-07-20. Six independent recovery mechanisms
  /// guard this codebase, each with its own rate limit. Every one is justified
  /// alone; on 2026-07-20 they composed into "never" and 18 messages hung
  /// permanently. The failure was invisible precisely because declining is
  /// silent — a guard that returns early looks identical to a guard that was
  /// never reached.
  ///
  /// Nothing here changes behaviour. It only makes the refusals countable, so
  /// the later stages can be judged by measurement instead of by feel.
  void _recoveryDeclined(String path, String reason, {String? deviceId}) {
    DiagLog.event('recovery', 'declined', {
      'path': path,
      'reason': reason,
      if (deviceId != null && deviceId.isNotEmpty) 'dev': DiagLog.pfx(deviceId),
    });
  }

  /// When this device first failed to apply an inbound wire from a peer, so a
  /// later success can report how long recovery actually took — the one number
  /// that says whether any of this is getting better.
  final Map<String, int> _recoveryFirstFailureAtMs = <String, int>{};

  void _noteRecoveryFailure(String deviceId) {
    final dev = deviceId.trim();
    if (dev.isEmpty) return;
    _recoveryFirstFailureAtMs.putIfAbsent(
      dev,
      () => DateTime.now().millisecondsSinceEpoch,
    );
  }

  void _noteRecoverySuccess(String deviceId) {
    final dev = deviceId.trim();
    if (dev.isEmpty) return;
    // Fix D: the peer healed → cancel any pending grace-delayed reset-ping (the
    // leader's reset already fixed us; ours would only cause a needless crossing).
    _resetPingGraceTimers.remove(dev)?.cancel();
    final startedAt = _recoveryFirstFailureAtMs.remove(dev);
    if (startedAt == null) return; // nothing was broken; not a recovery
    DiagLog.event('recovery', 'healed', {
      'dev': DiagLog.pfx(dev),
      'took_ms': DateTime.now().millisecondsSinceEpoch - startedAt,
    });
  }

  Future<void> _nackQuarantinedWireOnce(
    String msgId,
    String? senderDeviceId, {
    int? reNackAfterMs,
  }) async {
    if (!_nackReceiptsEnabled) return;
    final db = _db;
    final dev = (senderDeviceId ?? '').trim();
    final id = msgId.trim();
    if (db == null || id.isEmpty || dev.isEmpty) return;
    if (isOwnDeviceId(dev)) return;
    // ONE NACK per peer DEVICE per window, no matter how big the backlog is.
    // "I cannot decrypt this" is a fact about the SESSION, not about each
    // individual wire, and a single NACK already makes the sender rekey and
    // resend EVERYTHING undelivered. The replay sweep walks up to 500 parked
    // rows per run, so without this gate a 46-wire backlog would fire 46 NACKs
    // and make the sender re-run its resend sweep 46 times over — re-encrypting
    // the same messages under fresh transport ids each time. That is a traffic
    // storm, not better delivery (cf. the 2026-07-18 rekey storm).
    final now = DateTime.now().millisecondsSinceEpoch;
    // Fix 1a (2026-07-24): windowed BURST gate. Allow up to
    // _nackQuarantineBurstPerWindow DISTINCT-msg_id NACKs per device per window
    // (was one), so an offline→online backlog recovers in a single window
    // instead of one wire per 10 minutes. A slot is spent only after the wire
    // is confirmed FRESH (claim below) — the replay sweep re-walking
    // already-claimed rows must never burn the burst.
    if (!_nackQuarantineGate.hasRoom(dev, now)) {
      _recoveryDeclined('nack', 'device_gate', deviceId: dev);
      return;
    }
    try {
      final claimed = reNackAfterMs == null
          ? await db.inboxQuarantineClaimNack(msgId: id, nowMs: now)
          : await db.inboxQuarantineClaimNack(
              msgId: id,
              nowMs: now,
              reNackAfterMs: reNackAfterMs,
            );
      if (!claimed) {
        // Already claimed and inside the 24 h re-claim window.
        _recoveryDeclined('nack', 'already_claimed', deviceId: dev);
        return;
      }
      _nackQuarantineGate.consume(dev, now);
      DiagLog.event('inbox', 'nack_quarantined', {
        'msg': DiagLog.pfx(id),
        'sender_dev': DiagLog.pfx(dev),
      });
      await _emitNackUndecryptable(id, dev);
    } catch (_) {
      // Best-effort: the replay sweep must keep running regardless.
    }
  }

  Future<void> _emitNackUndecryptable(String msgId, String? senderDeviceId) async {
    if (_backgroundInboundMode) return; // NACK is an outbound wire; foreground sends it
    if (!_nackReceiptsEnabled) return;
    final db = _db;
    final dev = (senderDeviceId ?? '').trim();
    final id = msgId.trim();
    if (db == null || id.isEmpty || dev.isEmpty) return;
    if (isOwnDeviceId(dev)) return; // self-sync wires heal via restore, not NACK
    final now = DateTime.now().millisecondsSinceEpoch;
    final last = _nackEmittedAtMsByMsgId[id] ?? 0;
    if (now - last < _nackDebounceMs) return;
    _nackEmittedAtMsByMsgId[id] = now;
    if (_nackEmittedAtMsByMsgId.length > 512) {
      final cutoff = now - 10 * _nackDebounceMs;
      _nackEmittedAtMsByMsgId.removeWhere((_, ts) => ts < cutoff);
    }
    String peerProfileId = '';
    try {
      peerProfileId = (await _resolveProfileIdForDevice(dev)) ?? '';
    } catch (_) {}
    try {
      await db.pendingReceiptUpsert(
        peerDeviceId: dev,
        peerProfileId: peerProfileId.isEmpty ? null : peerProfileId,
        payloadEventId: id, // relay msg_id — flush stamps refKind='msg_id'
        convoId: null,
        status: MessageReceiptState.nackUndecryptable,
        createdAtMs: now,
        updatedAtMs: now,
      );
      DiagLog.event('receipt', 'nack_enqueued', {
        'msg': DiagLog.pfx(id),
        'dev': DiagLog.pfx(dev),
      });
      unawaited(_flushPendingReceiptsBestEffort());
      _kickRelayOutbox();
    } catch (_) {
      // best-effort — the quarantine + escalator still drive recovery.
    }
  }

  /// TZ Epic A2 — SENDER side: a peer device positively reported that our wire
  /// [relayMsgId] is undecryptable for it. React with a TARGETED heal — rekey
  /// that device (shared debounce with every other reset path) and re-send all
  /// undelivered messages to it under the fresh session — with NO peer-alive
  /// guesswork: the NACK itself is the evidence.
  Future<void> _handleNackUndecryptableReceipt({
    required String relayMsgId,
    required String peerDeviceId,
    required String peerProfileId,
  }) async {
    if (_backgroundInboundMode) return; // rekey+resend is outbound; foreground does it
    // Every early return below is LOGGED. On 2026-07-19 a peer received five
    // NACKs, silently did nothing, and it took an hour of relay-log archaeology
    // to even know the handler had been reached — a silent guard in a recovery
    // path is indistinguishable from a broken one.
    if (!_nackReceiptsEnabled) {
      DiagLog.event('inbox', 'nack_skip', const {'reason': 'disabled'});
      return;
    }
    final dev = peerDeviceId.trim();
    var pid = peerProfileId.trim();
    final id = relayMsgId.trim();
    if (id.isEmpty || dev.isEmpty || isOwnDeviceId(dev)) {
      DiagLog.event('inbox', 'nack_skip', {
        'reason': isOwnDeviceId(dev) ? 'own_device' : 'empty_ref',
        'dev': DiagLog.pfx(dev),
      });
      return;
    }
    final now = DateTime.now().millisecondsSinceEpoch;
    final last = _nackHandledAtMsByMsgId[id] ?? 0;
    if (now - last < _nackDebounceMs) return; // burst — first one already acted
    _nackHandledAtMsByMsgId[id] = now;
    if (_nackHandledAtMsByMsgId.length > 512) {
      final cutoff = now - 10 * _nackDebounceMs;
      _nackHandledAtMsByMsgId.removeWhere((_, ts) => ts < cutoff);
    }
    if (pid.isEmpty) {
      try {
        pid = (await _resolveProfileIdForDevice(dev)) ?? '';
      } catch (_) {}
    }
    if (pid.isEmpty) {
      // Can't target the resend without a profile.
      DiagLog.event('inbox', 'nack_skip', {
        'reason': 'no_profile',
        'dev': DiagLog.pfx(dev),
      });
      return;
    }
    DiagLog.event('inbox', 'nack_received', {
      'msg': DiagLog.pfx(id),
      'dev': DiagLog.pfx(dev),
    });
    // Shared debounce with the receiver escalator + convergence backstop so a
    // NACK burst can never rekey-storm (the floor is per DEVICE, and the
    // per-msg debounce above already bounds this path).
    final lastReset = _sessionResetPingAtMs[dev] ?? 0;
    if (now - lastReset >= _sessionResetPingDebounceMs) {
      _forceSessionResetPing(dev, _resetCausePeerNack);
    }
    unawaited(
      _resendUndeliveredDirect(
        peerProfileId: pid,
        peerDeviceId: dev,
        stuckBeforeMs: now,
        // Э-0: this sweep runs because the RECIPIENT said a wire is unopenable.
        // A statement outranks the timer paths' silence, so these events get a
        // little extra lifetime budget.
        grantNackBonus: true,
      ),
    );
    // 2026-07-23 (undecryptable-recovery): ALSO resend the SPECIFIC wire this
    // NACK names, regardless of its local_state. The blanket sweep above only
    // covers `local_state='sent'`; a message the peer already marked
    // delivered/read but can no longer decrypt (ratchet desync) is invisible to
    // it, and the peer's dead ciphertext can never be revived locally — only a
    // fresh re-encrypt of the ORIGINAL content reaches them. This is the exact
    // "1 of 3 arrived, no notification" loss: proven in the field with two wires
    // stuck on `secretbox auth` forever while the sweep never touched them.
    final nackDb = _db;
    if (nackDb != null) {
      unawaited(() async {
        try {
          final ref = await nackDb.outboxEventRefByMsgId(id);
          if (ref == null) {
            // We no longer hold the outbound row (TTL-pruned / never ours).
            DiagLog.event('inbox', 'nack_resend_miss', {'msg': DiagLog.pfx(id)});
            return;
          }
          await _resendOneEventReEncrypted(
            eventId: ref['event_id_ref'] ?? '',
            payloadEventId: ref['payload_event_id'] ?? '',
            peerProfileId: pid,
            peerDeviceId: dev,
          );
        } catch (_) {
          // best-effort; the blanket sweep + reset ping still ran above.
        }
      }());
    }
    // The NACK proves wires we sent this device died undecrypted — and receipt
    // wires die WITH their content (their queue rows are deleted the moment
    // they enter the outbox). The resend above restores events; this restores
    // the receipt state, or the peer reads us forever at one tick.
    unawaited(_reEmitReceiptStateFor(peerProfileId: pid, peerDeviceId: dev));
  }

  /// Re-enqueues delivered/read receipts for the recent inbound events of
  /// [peerProfileId] toward [peerDeviceId] (2026-07-19, "one tick forever").
  ///
  /// Safe to over-send: receipt application is monotonic on the receiving side
  /// (`canPromote` — read never demotes to delivered), so re-emitting state the
  /// peer already has is a no-op. Throttled per device so a NACK burst enqueues
  /// the batch once, not N times.
  Future<void> _reEmitReceiptStateFor({
    required String peerProfileId,
    required String peerDeviceId,
  }) async {
    final db = _db;
    final selfDid = _deviceId;
    if (db == null || selfDid == null) return;
    if (isOwnDeviceId(peerDeviceId)) return;
    final now = DateTime.now().millisecondsSinceEpoch;
    final last = _receiptRestateAtMsByDevice[peerDeviceId] ?? 0;
    if (now - last < _nackDebounceMs) return;
    _receiptRestateAtMsByDevice[peerDeviceId] = now;
    if (_receiptRestateAtMsByDevice.length > 256) {
      final cutoff = now - 10 * _nackDebounceMs;
      _receiptRestateAtMsByDevice.removeWhere((_, ts) => ts < cutoff);
    }
    List<Map<String, Object?>> rows;
    try {
      rows = await db.recentInboundReceiptTargets(
        convoId: peerProfileId,
        selfDeviceId: selfDid,
      );
    } catch (_) {
      return;
    }
    if (rows.isEmpty) return;
    var queued = 0;
    for (final row in rows) {
      final payloadEventId = ((row['payload_event_id'] as String?) ?? '').trim();
      if (payloadEventId.isEmpty) continue;
      final readAt = (row['read_at_ms'] as num?)?.toInt() ?? 0;
      try {
        await db.pendingReceiptUpsert(
          peerDeviceId: peerDeviceId,
          peerProfileId: peerProfileId,
          payloadEventId: payloadEventId,
          convoId: peerProfileId,
          status: readAt > 0
              ? MessageReceiptState.read
              : MessageReceiptState.delivered,
          createdAtMs: now,
          updatedAtMs: now,
        );
        queued++;
      } catch (_) {
        // best-effort per row
      }
    }
    if (queued == 0) return;
    DiagLog.event('receipt', 'restate_after_heal', {
      'dev': DiagLog.pfx(peerDeviceId),
      'count': queued,
    });
    unawaited(_flushPendingReceiptsBestEffort());
    _kickRelayOutbox();
  }

  // Reader-side read-receipt reconciliation backstop (2026-07-23). Kill-switch,
  // a single-flight guard, and a slow self-gated cadence.
  final bool _readReceiptReconcileEnabled = true;
  bool _readReceiptReconcileRunning = false;
  int _lastReadReceiptReconcileAtMs = 0;
  static const int _readReceiptReconcileCadenceMs = 5 * 60 * 1000;
  static const int _readReceiptReconcileReadWindowMs = 2 * 60 * 60 * 1000;
  static const int _readReceiptReconcilePeerActiveWindowMs = 30 * 60 * 1000;

  /// How often the SAME receipt may be re-emitted by this backstop.
  ///
  /// 🔴 FIELD WASTE (2026-07-31): the reconcile query selects everything read
  /// inside [_readReceiptReconcileReadWindowMs] and has no way to know a
  /// receipt already went out — a flushed receipt deletes its `pending_receipts`
  /// row atomically with entering the outbox, so nothing remembers. At a 5 min
  /// cadence over a 2 h window that re-sent every receipt ~24 times; the device
  /// log showed the identical set of 39 re-queued cycle after cycle, each one
  /// an encrypt + a wire + a bite out of the shared keys rate budget that the
  /// SEND path needs.
  ///
  /// This is a safety net for a receipt that died in transit, not a heartbeat.
  /// Repeating it a few times per window is the net; repeating it two dozen
  /// times is noise. Deliberately in-memory: a restart re-arms it, which costs
  /// one extra pass and keeps the net strictly stronger than the timer alone.
  static const int _readReceiptReconcileRepeatMs = 30 * 60 * 1000;

  /// Bound on [_reconciledReceiptAtMs] so a long session cannot grow it without
  /// limit. Comfortably above one window's worth of targets.
  static const int _maxReconciledReceiptKeys = 1024;

  /// `peerDeviceId|payloadEventId` → when this backstop last re-emitted it.
  final Map<String, int> _reconciledReceiptAtMs = <String, int>{};

  /// True when this backstop may re-emit [key] now; stamps it when it may.
  bool _shouldReEmitReconciledReceipt(String key, int nowMs) {
    final last = _reconciledReceiptAtMs[key] ?? 0;
    if (nowMs - last < _readReceiptReconcileRepeatMs) return false;
    if (_reconciledReceiptAtMs.length >= _maxReconciledReceiptKeys) {
      // Drop the oldest stamp; the worst case of evicting one is a single
      // redundant re-emit, which is exactly what this backstop is for.
      var oldestKey = key;
      var oldestAt = nowMs;
      for (final e in _reconciledReceiptAtMs.entries) {
        if (e.value <= oldestAt) {
          oldestAt = e.value;
          oldestKey = e.key;
        }
      }
      _reconciledReceiptAtMs.remove(oldestKey);
    }
    _reconciledReceiptAtMs[key] = nowMs;
    return true;
  }

  /// Periodic reader-side safety net for lost read receipts (2026-07-23).
  ///
  /// A read receipt is one encrypted wire PER message (confirmed in the field:
  /// `receipt.queued count=1`). When a session hiccups, some of those wires die
  /// undecryptable on the peer; the wire is consumed (relay-ACKed), so
  /// redeliver-until-ACK cannot help, and the ONLY recovery is the peer's
  /// NACK → [_reEmitReceiptStateFor], which is per-device throttled and fires
  /// once per burst. Under a burst some reads never recover, so the peer shows
  /// half our messages read and half stuck on one tick — permanently, because
  /// the sender convergence backstop heals only `local_state='sent'`
  /// (undelivered), never `'delivered'`. This closes that gap.
  ///
  /// For a peer we have READ from recently AND that is provably reachable, we
  /// re-emit READ receipts for a BOUNDED, recently-read set on a slow cadence.
  /// Application is monotonic (read never demotes to delivered), so any receipt
  /// the peer already holds is a no-op — this only rescues the stragglers, and
  /// the hard cap keeps it from ever becoming a receipt storm.
  Future<void> _runReadReceiptReconcileBackstop() async {
    if (!_readReceiptReconcileEnabled) return;
    if (_readReceiptReconcileRunning) return;
    final db = _db;
    final selfDid = _deviceId;
    if (db == null || selfDid == null || selfDid.isEmpty) return;
    final now = DateTime.now().millisecondsSinceEpoch;
    if (now - _lastReadReceiptReconcileAtMs < _readReceiptReconcileCadenceMs) {
      return;
    }
    _lastReadReceiptReconcileAtMs = now;
    _readReceiptReconcileRunning = true;
    var queued = 0;
    try {
      List<String> peers;
      try {
        peers = await db.convoIdsWithRecentInboundReads(
          selfDeviceId: selfDid,
          readAfterMs: now - _readReceiptReconcileReadWindowMs,
        );
      } catch (_) {
        return;
      }
      for (final peerProfileId in peers) {
        if (peerProfileId.isEmpty) continue;
        // Only reconcile with a provably-reachable peer. If we've heard nothing
        // recently they are simply offline — pushing wires at a dead mailbox is
        // waste, and redeliver-until-ACK covers our actual messages. An active
        // peer whose reads didn't land is exactly the stranded case we want.
        int lastInbound = 0;
        try {
          lastInbound = await db.latestInboundAtMs(peerProfileId);
        } catch (_) {}
        if (lastInbound <= 0 ||
            now - lastInbound > _readReceiptReconcilePeerActiveWindowMs) {
          continue;
        }
        List<String> targets;
        try {
          targets = await db.recentReadReceiptTargets(
            convoId: peerProfileId,
            selfDeviceId: selfDid,
            readAfterMs: now - _readReceiptReconcileReadWindowMs,
          );
        } catch (_) {
          continue;
        }
        if (targets.isEmpty) continue;
        List<Map<String, Object?>> deviceRows;
        try {
          deviceRows = await db.contactDevicesList(peerProfileId);
        } catch (_) {
          continue;
        }
        for (final row in deviceRows) {
          final deviceId = ((row['device_id'] as String?) ?? '').trim();
          if (deviceId.isEmpty || isOwnDeviceId(deviceId)) continue;
          for (final payloadEventId in targets) {
            // Skip one we re-emitted recently — see
            // _readReceiptReconcileRepeatMs. Without this the same set is
            // re-queued every cadence for the whole 2 h window.
            if (!_shouldReEmitReconciledReceipt(
              '$deviceId|$payloadEventId',
              now,
            )) {
              continue;
            }
            try {
              await db.pendingReceiptUpsert(
                peerDeviceId: deviceId,
                peerProfileId: peerProfileId,
                payloadEventId: payloadEventId,
                convoId: peerProfileId,
                status: MessageReceiptState.read,
                createdAtMs: now,
                updatedAtMs: now,
              );
              queued++;
            } catch (_) {
              // best-effort per row
            }
          }
        }
      }

      // ROOMS (2026-07-30). Previously excluded because a room has one
      // conversation and many authors, so the 1:1 shape ("peer == convo id")
      // did not fit. The consequence was that a room receipt lost to an
      // undecryptable wire had NO periodic safety net: the author stayed
      // convinced the member never received the message. That is now exactly
      // the signal the convergence backstop acts on, so leaving it unrepaired
      // would have the author re-keying a member whose only fault was one dead
      // receipt.
      List<({String roomId, String senderDeviceId, String payloadEventId})>
      roomTargets;
      try {
        roomTargets = await db.roomReadReceiptReconcileTargets(
          selfDeviceId: selfDid,
          readAfterMs: now - _readReceiptReconcileReadWindowMs,
          excludedSenderDeviceIds: _ownDeviceIdsForUnreadQueries(),
        );
      } catch (_) {
        roomTargets = const [];
      }
      final roomAuthorAliveness = <String, bool>{};
      for (final target in roomTargets) {
        final authorPid = await _resolveProfileIdForDevice(
          target.senderDeviceId,
        );
        if (authorPid == null || authorPid.trim().isEmpty) continue;
        final pid = authorPid.trim();
        // Same aliveness rule as the 1:1 loop above: pushing wires at a mailbox
        // we have heard nothing from is waste. Cached per author because a busy
        // room yields many rows from the same few people.
        final alive = roomAuthorAliveness[pid] ??= await () async {
          int lastInbound = 0;
          try {
            lastInbound = await db.latestInboundAtMs(pid);
          } catch (_) {}
          return lastInbound > 0 &&
              now - lastInbound <= _readReceiptReconcilePeerActiveWindowMs;
        }();
        if (!alive) continue;
        // Same repeat guard as the 1:1 loop above: rooms are the BIGGER source
        // of duplicates (one query, up to 64 targets across every room), so
        // leaving them unguarded would keep the storm this fix removes.
        if (!_shouldReEmitReconciledReceipt(
          '${target.senderDeviceId}|${target.payloadEventId}',
          now,
        )) {
          continue;
        }
        try {
          await db.pendingReceiptUpsert(
            peerDeviceId: target.senderDeviceId,
            peerProfileId: pid,
            payloadEventId: target.payloadEventId,
            convoId: target.roomId,
            status: MessageReceiptState.read,
            createdAtMs: now,
            updatedAtMs: now,
          );
          queued++;
        } catch (_) {
          // best-effort per row
        }
      }
    } finally {
      _readReceiptReconcileRunning = false;
      if (queued > 0) {
        DiagLog.event('receipt', 'reconcile_backstop', {'queued': queued});
        unawaited(_flushPendingReceiptsBestEffort());
      }
    }
  }

  /// Room counterpart of [_runSenderConvergenceBackstop] (фаза 1 ТЗ).
  ///
  /// Finds rooms whose messages are still `'sent'` — meaning NOBODY in the room
  /// acknowledged them — and repairs each member's session the same way the 1:1
  /// path does: re-key the device, then re-send the stuck room messages under
  /// the fresh session. The resend is told the ROOM as the conversation while
  /// the member stays the encryption target (see _resendUndeliveredDirect).
  ///
  /// Safety, all inherited from the 1:1 backstop rather than re-invented:
  ///  * only a PROVABLY reachable member is healed (aliveness window), so an
  ///    offline member is left to the relay's redeliver-until-ACK;
  ///  * the per-device reset debounce is SHARED with every other reset path, so
  ///    this can never double-fire with the receiver-driven escalator;
  ///  * the exponential streak backoff (2m→32m) bounds repeats.
  ///
  /// Known limitation, deliberate for phase 1: a member we have never heard
  /// from in their own 1:1 conversation has no aliveness evidence and is
  /// skipped. Per-member room evidence needs `room_message_receipts` and is the
  /// next step; skipping is the safe direction (no churn).
  /// К-3 (17.09.2026): повторять ли пропущенные сообщения комнаты участнику.
  ///
  /// 🔴 ВЫКЛЮЧЕНО (17.09.2026, ревью перед 601): окно повтора забивалось
  /// старыми сообщениями, новичку уходили сообщения до его вступления, копия
  /// могла уйти в сломанную сессию, а конверты с открытым текстом переживали
  /// удаление. Включать только после переделки.
  @visibleForTesting
  static bool roomMissedResendEnabled = false;

  static const int _roomMissedResendPerMember = 10;
  static const int _roomEnvelopeKeepMs = 7 * 24 * 60 * 60 * 1000;

  /// Отправитель повтора в тестах (вместо `sendControlMessage`).
  @visibleForTesting
  Future<void> Function(String memberProfileId, String envelope)?
  roomResendSenderForTesting;

  Future<void> _rememberRoomEnvelope({
    required AppDb db,
    required String roomId,
    required String controlText,
  }) async {
    if (!roomMissedResendEnabled) return;
    if (!controlText.startsWith(_groupMsgCmdPrefix)) return;
    try {
      final decoded = jsonDecode(
        utf8.decode(
          base64Url.decode(controlText.substring(_groupMsgCmdPrefix.length)),
        ),
      );
      final id = decoded is Map ? (decoded['msgEventId'] as String?) : null;
      if (id == null || id.trim().isEmpty) return;
      await db.roomOutboundEnvelopePut(
        payloadEventId: id.trim(),
        roomId: roomId,
        envelope: controlText,
        createdAtMs: DateTime.now().millisecondsSinceEpoch,
      );
    } catch (_) {
      // Без конверта не будет лишь повтора; отправка идёт своим путём.
    }
  }

  /// К-3: участник жив, квитанции шлёт, а на мои сообщения — нет. Повторяем
  /// ему именно тот конверт, что ушёл всем, по одному разу на сообщение.
  /// Получатель повтор отсекает сам (номер сообщения — ключ записи).
  Future<int> _resendMissedRoomMessages({
    required AppDb db,
    required String roomId,
    required String memberProfileId,
    required int stuckBeforeMs,
    required int nowMs,
  }) async {
    if (!roomMissedResendEnabled) return 0;
    List<Map<String, Object?>> owed;
    try {
      owed = await db.roomSendsMissingReceiptFrom(
        roomId: roomId,
        readerProfileId: memberProfileId,
        senderDeviceId: _deviceId ?? '',
        stuckBeforeMs: stuckBeforeMs,
        limit: _roomMissedResendPerMember,
      );
    } catch (_) {
      return 0;
    }
    var resent = 0;
    for (final row in owed) {
      final payloadEventId = ((row['payload_event_id'] as String?) ?? '').trim();
      if (payloadEventId.isEmpty) continue;
      if (await db.roomOutboundWasResent(
        payloadEventId: payloadEventId,
        memberProfileId: memberProfileId,
      )) {
        continue;
      }
      final envelope = await db.roomOutboundEnvelopeGet(payloadEventId);
      if (envelope == null || envelope.isEmpty) continue;
      try {
        final sender = roomResendSenderForTesting;
        if (sender != null) {
          await sender(memberProfileId, envelope);
        } else {
          await sendControlMessage(
            peerProfileId: memberProfileId,
            controlText: envelope,
            queueIfNoDevices: true,
          );
        }
        await db.roomOutboundMarkResent(
          payloadEventId: payloadEventId,
          memberProfileId: memberProfileId,
          atMs: nowMs,
        );
        resent++;
      } catch (_) {
        break;
      }
    }
    if (resent > 0) {
      DiagLog.event('room', 'missed_resent', {
        'room': DiagLog.pfx(roomId),
        'peer': DiagLog.pfx(memberProfileId),
        'count': resent,
      });
    }
    return resent;
  }

  @visibleForTesting
  Future<int> resendMissedRoomMessagesForTesting({
    required String roomId,
    required String memberProfileId,
    required int stuckBeforeMs,
  }) {
    return _resendMissedRoomMessages(
      db: _db!,
      roomId: roomId,
      memberProfileId: memberProfileId,
      stuckBeforeMs: stuckBeforeMs,
      nowMs: DateTime.now().millisecondsSinceEpoch,
    );
  }

  @visibleForTesting
  Future<void> rememberRoomEnvelopeForTesting(String roomId, String text) =>
      _rememberRoomEnvelope(db: _db!, roomId: roomId, controlText: text);

  Future<void> _runRoomConvergenceBackstop() async {
    if (!roomConvergenceBackstopEnabled) return;
    if (!_senderConvergenceBackstopEnabled) return;
    if (_roomConvergenceSweepRunning) return;
    final db = _db;
    if (db == null) return;
    final now = DateTime.now().millisecondsSinceEpoch;
    if (now - _lastRoomConvergenceSweepAtMs < _senderConvergenceSweepCadenceMs) {
      return;
    }
    _lastRoomConvergenceSweepAtMs = now;
    _roomConvergenceSweepRunning = true;
    try {
      await db.roomOutboundPrune(olderThanMs: now - _roomEnvelopeKeepMs);
      final stuckBefore = now - _senderConvergenceStuckMs;
      // Two candidate sets, deliberately different signals:
      //  * rooms whose messages NOBODY acknowledged (local_state still 'sent');
      //  * rooms this device posted to recently — checked per MEMBER, because a
      //    room reads 'delivered' as soon as ONE member acks while others may
      //    still be missing everything.
      final unackedRooms = (await db.roomIdsWithUndeliveredSends(
        stuckBeforeMs: stuckBefore,
        minCount: _senderConvergenceMinStuck,
      )).toSet();
      final roomSet = <String>{
        ...unackedRooms,
        ...await db.roomIdsWithRecentSends(
          senderDeviceId: _deviceId ?? '',
          stuckBeforeMs: stuckBefore,
          notOlderThanMs: now - _roomConvergenceLookbackMs,
        ),
      };
      final rooms = roomSet.toList(growable: false);
      final myProfileId = (_profileId ?? '').trim();
      for (final roomId in rooms) {
        if (roomId.isEmpty) continue;
        // Flagged by the "nobody acknowledged" detector? Then a member with no
        // receipt evidence is still worth repairing. Computed ONCE above — this
        // sweep runs every 30 s and must not re-query per room.
        final roomHasUnackedSends = unackedRooms.contains(roomId);
        List<Map<String, Object?>> memberRows;
        try {
          memberRows = await db.groupMembersList(roomId);
        } catch (_) {
          continue;
        }
        for (final memberRow in memberRows) {
          final memberProfileId =
              ((memberRow['member_profile_id'] as String?) ?? '').trim();
          if (memberProfileId.isEmpty || memberProfileId == myProfileId) {
            continue;
          }
          int lastInbound = 0;
          try {
            lastInbound = await db.latestInboundAtMs(memberProfileId);
          } catch (_) {}
          if (lastInbound <= 0 ||
              now - lastInbound > _senderConvergencePeerAliveWindowMs) {
            continue;
          }
          // ROLLOUT GATE. Every signal below is "this member has not
          // acknowledged", and builds before 2026-07-30 emitted NO room
          // receipts at all. For them non-acknowledgement is the norm, not a
          // fault, and acting on it would re-key every member still on an older
          // version, on a loop, forever. One acknowledgement anywhere proves
          // their build acks; until then their silence proves nothing.
          //
          // The same rule the aliveness gate applies one level up: absence of
          // evidence is not evidence of failure. Skipping costs us nothing they
          // had before — rooms had no repair at all — while acting costs every
          // old-build member a session reset every backoff period.
          var memberAcksRooms = false;
          try {
            memberAcksRooms = await db.roomReceiptEverFrom(
              readerProfileId: memberProfileId,
            );
          } catch (_) {}
          if (!memberAcksRooms) continue;

          // Does THIS member owe us receipts in THIS room? If not, there is
          // nothing to repair for them and we must not touch their session.
          var memberMissing = false;
          try {
            final owed = await db.roomSendsMissingReceiptFrom(
              roomId: roomId,
              readerProfileId: memberProfileId,
              senderDeviceId: _deviceId ?? '',
              stuckBeforeMs: stuckBefore,
              limit: 1,
            );
            memberMissing = owed.isNotEmpty;
          } catch (_) {}
          if (memberMissing) {
            await _resendMissedRoomMessages(
              db: db,
              roomId: roomId,
              memberProfileId: memberProfileId,
              stuckBeforeMs: stuckBefore,
              nowMs: now,
            );
          }
          if (!memberMissing && !roomHasUnackedSends) continue;
          List<Map<String, Object?>> deviceRows;
          try {
            deviceRows = await db.contactDevicesList(memberProfileId);
          } catch (_) {
            continue;
          }
          for (final row in deviceRows) {
            final deviceId = ((row['device_id'] as String?) ?? '').trim();
            if (deviceId.isEmpty || isOwnDeviceId(deviceId)) continue;
            final lastReset = _sessionResetPingAtMs[deviceId] ?? 0;
            var streak = _convergenceRekeyStreakByDevice[deviceId] ?? 0;
            if (streak > 0 && lastInbound > lastReset) {
              streak = 0;
              _convergenceRekeyStreakByDevice[deviceId] = 0;
            }
            final floorMs =
                _senderConvergenceResetFloorMs <<
                (streak > _senderConvergenceBackoffMaxShift
                    ? _senderConvergenceBackoffMaxShift
                    : streak);
            if (now - lastReset < floorMs) continue;

            // 🔴 WRONG-REMEDY GUARD (2026-07-31). Since the sender key shipped
            // there is a SECOND reason a member sends no receipt: their pairwise
            // session is perfectly healthy, but they do not hold the room key
            // for this generation, so they park the `gmsg` and stay silent.
            //
            // Resetting the session for that is the one repair that cannot
            // work — the missing piece is the KEY — and it destroys a healthy
            // session in the process, which is exactly the class И-4 exists to
            // stop. Worse, it repeats on the 2m→32m ladder for as long as the
            // key is missing.
            //
            // So: if this device is merely un-keyed, hand it the key and leave
            // the session alone. `gkeyreq` covers the same gap from the other
            // side; this closes it from ours, for a member too quiet to ask.
            // SEND side: handing out OUR key is only meaningful for a build
            // that seals under it. A pure receiver has no key to give.
            if (roomSenderKeySendEnabled) {
              var owedTheKey = false;
              try {
                final missing = await RoomKeyManager(
                  db,
                ).recipientsMissingKey(
                  roomId: roomId,
                  memberDeviceIds: <String>[deviceId],
                );
                owedTheKey = missing.isNotEmpty;
              } catch (_) {
                owedTheKey = false; // unknown → fall through to the old repair
              }
              if (owedTheKey) {
                DiagLog.event('room_key', 'convergence_key_instead_of_reset', {
                  'room': DiagLog.pfx(roomId),
                  'peer': DiagLog.pfx(memberProfileId),
                  'dev': DiagLog.pfx(deviceId),
                });
                unawaited(
                  _deliverRoomKeyTo(
                    db: db,
                    roomId: roomId,
                    devices: <String>[deviceId],
                    deviceToProfile: <String, String>{
                      deviceId: memberProfileId,
                    },
                  ),
                );
                // Deliberately NOT counted as a rekey attempt and NOT stamped
                // on the reset clock: nothing was reset, and the next sweep
                // must be free to escalate if the key alone did not help.
                continue;
              }
            }

            _convergenceRekeyStreakByDevice[deviceId] = streak + 1;
            DiagLog.event('inbox', 'room_convergence_rekey', {
              'room': DiagLog.pfx(roomId),
              'peer': DiagLog.pfx(memberProfileId),
              'dev': DiagLog.pfx(deviceId),
              'streak': streak + 1,
              'missing': memberMissing,
            });
            // The re-key IS the repair: it re-establishes the session, so every
            // FUTURE room message reaches this member. Content already sent
            // under the dead session is deliberately NOT replayed — a room
            // message's local copy is the bare text, not the group envelope
            // members need, so re-sending it would file the room's message into
            // a PRIVATE chat with its author. See the guard in
            // _resendUndeliveredDirect. The sender key (фаза 3) makes the room
            // wire replayable verbatim and closes this properly.
            _forceSessionResetPing(deviceId, _resetCauseRoomConvergence);
          }
        }
      }
    } catch (_) {
      // best-effort — must never throw into the watchdog.
    } finally {
      _roomConvergenceSweepRunning = false;
    }
  }

  Future<void> _runSenderConvergenceBackstop() async {
    if (!_senderConvergenceBackstopEnabled) return;
    if (_senderConvergenceSweepRunning) return;
    final db = _db;
    if (db == null) return;
    final now = DateTime.now().millisecondsSinceEpoch;
    if (now - _lastSenderConvergenceSweepAtMs <
        _senderConvergenceSweepCadenceMs) {
      return;
    }
    _lastSenderConvergenceSweepAtMs = now;
    _senderConvergenceSweepRunning = true;
    try {
      final convos = await db.convoIdsWithUndeliveredSends(
        stuckBeforeMs: now - _senderConvergenceStuckMs,
        minCount: _senderConvergenceMinStuck,
      );
      for (final peerProfileId in convos) {
        if (peerProfileId.isEmpty) continue;
        // Peer alive? If we've heard NOTHING from them recently they are most
        // likely just offline — the relay redeliver-until-ACK will land our
        // messages when they wake, so re-keying now would be wasteful and could
        // churn a perfectly good (idle) session. Only heal a PROVABLY reachable
        // peer whose messages still aren't landing.
        int lastInbound = 0;
        try {
          lastInbound = await db.latestInboundAtMs(peerProfileId);
        } catch (_) {}
        if (lastInbound <= 0 ||
            now - lastInbound > _senderConvergencePeerAliveWindowMs) {
          continue;
        }
        List<Map<String, Object?>> deviceRows;
        try {
          deviceRows = await db.contactDevicesList(peerProfileId);
        } catch (_) {
          continue;
        }
        // 🔴 П-5 (Э-0): only ever
        // re-key and re-send toward devices the peer STILL HAS.
        //
        // `contactDevicesList` is our local cache. It IS pruned — but only when
        // a roster refresh happens, and this backstop runs on its own 30 s clock
        // without ever triggering one. So a device the server evicted stayed a
        // target indefinitely. Measured on prod 2026-08-01: 298 copies piled
        // into the mailbox of a device the relay had marked superseded, with
        // fresh copies still being added three days after the eviction.
        //
        // Resolving through the ordinary send path fixes that and costs almost
        // nothing: it is TTL-cached (3 min per peer), carries the rate-limit
        // backoff that the 2026-07-31 keys-server storm taught us to respect,
        // and applies the relay's superseded-device filter. That resolver is
        // deliberately conservative — on any doubt it returns the WIDER set —
        // so this can only remove provably dead targets, never strand a live
        // one. Whatever still slips through is bounded by the Э-0 lifetime cap.
        Set<String>? liveDeviceIds;
        try {
          final live = await _listRecipientDevicesForSend(
            peerProfileId: peerProfileId,
            selfDeviceId: (_deviceId ?? '').trim(),
          );
          if (live.isNotEmpty) liveDeviceIds = live.toSet();
        } catch (_) {
          // Unresolvable roster: fall through to the cached rows unchanged — a
          // lookup hiccup must never silence a genuinely needed heal.
        }
        for (final row in deviceRows) {
          final deviceId = ((row['device_id'] as String?) ?? '').trim();
          if (deviceId.isEmpty || isOwnDeviceId(deviceId)) continue;
          if (!convergenceShouldTargetDevice(
            deviceId: deviceId,
            liveDeviceIds: liveDeviceIds,
          )) {
            DiagLog.event('send', 'converge_skip_dead_device', {
              'peer': DiagLog.pfx(peerProfileId),
              'dev': DiagLog.pfx(deviceId),
            });
            continue;
          }
          // Shared debounce with the receiver-driven escalator: never re-key a
          // device more than once per floor window, so a still-healing reset is
          // given time to land before we try again and the two paths can never
          // double-fire.
          //
          // STORM FIX (2026-07-18): the floor now GROWS exponentially with each
          // consecutive rekey fired without fresh inbound evidence (2m, 4m, 8m,
          // 16m, 32m cap). The peer speaking again after our last rekey resets
          // the streak — genuine desync (peer active, sends still unreceipted)
          // keeps healing fast; a peer that merely went offline right after a
          // chat stops being re-keyed + re-sent every 2 minutes.
          final lastReset = _sessionResetPingAtMs[deviceId] ?? 0;
          var streak = _convergenceRekeyStreakByDevice[deviceId] ?? 0;
          if (streak > 0 && lastInbound > lastReset) {
            // Heard from the peer after the last rekey → evidence is fresh.
            streak = 0;
            _convergenceRekeyStreakByDevice[deviceId] = 0;
          }
          final floorMs =
              _senderConvergenceResetFloorMs <<
              (streak > _senderConvergenceBackoffMaxShift
                  ? _senderConvergenceBackoffMaxShift
                  : streak);
          if (now - lastReset < floorMs) continue;
          _convergenceRekeyStreakByDevice[deviceId] = streak + 1;
          DiagLog.event('inbox', 'sender_convergence_rekey', {
            'peer': DiagLog.pfx(peerProfileId),
            'dev': DiagLog.pfx(deviceId),
            'streak': streak + 1,
          });
          _forceSessionResetPing(deviceId, _resetCauseSenderConvergence);
          // STAGE 2 (TZ §20 pillar 5) — auto-resend: the re-key above heals the
          // session going forward, but the messages already sent under the dead
          // session are undecryptable ciphertext the peer can never recover. Re-
          // encrypt each undelivered one under the fresh session and re-send it
          // so the lost content finally lands. Ordered AFTER the reset ping on
          // the same per-peer encrypt queue, so it rides the fresh session.
          unawaited(_resendUndeliveredDirect(
            peerProfileId: peerProfileId,
            peerDeviceId: deviceId,
            stuckBeforeMs: now - _senderConvergenceStuckMs,
          ));
        }
      }
    } catch (_) {
      // best-effort — the backstop must never throw into the watchdog.
    } finally {
      _senderConvergenceSweepRunning = false;
    }
  }

  /// Re-sends the 1:1 messages [peerDeviceId]'s owner never confirmed
  /// (relay-acked but still `local_state='sent'`), re-encrypted under the
  /// freshly re-keyed session, so content lost during a session desync actually
  /// lands. Idempotent: the wire carries the ORIGINAL payload (hence the
  /// original event id), and the receiver dedups via insertEvent's
  /// INSERT-OR-IGNORE on event_id, so re-sending one the peer already holds is a
  /// no-op. Self-terminating: once the peer decrypts + persists one, its
  /// delivered-receipt flips the row to `'delivered'` and it stops being
  /// re-sent. Per-event debounced so it re-sends at most once per window.
  /// Л-3 (ТЗ 16.08): моложе этого возраста «реле пусто» читается по-старому —
  /// молчание свежего события не доказывает недоставку (фоновый получатель без
  /// квитанций — живой случай `6abd3ab8`).
  static const int _resendHeldZeroMinAgeMs = 30 * 60 * 1000;

  /// Re-entrancy guard around [_resendUndeliveredDirectInner].
  ///
  /// Every run re-encrypts and re-enqueues the SAME undelivered events under
  /// fresh transport ids, so overlapping runs for one device multiply traffic
  /// without adding any delivery. A NACK burst (or a NACK arriving while the
  /// convergence backstop is already sweeping) would do exactly that.
  /// [convoId] defaults to [peerProfileId] — that IS the conversation id for a
  /// 1:1 chat. A ROOM passes the `group:` id here while [peerProfileId] stays
  /// the individual member being repaired: the stuck rows and the re-queued
  /// outbox belong to the room, but the ciphertext is still sealed to one
  /// member's device. Without the split the room id would be handed to the
  /// ratchet as a peer profile and nothing could be encrypted.
  /// Спрашивает реле, держит ли оно ещё наши конверты для [peerDeviceId].
  ///
  /// Возвращает `true`, если получателю ЕЩЁ ЕСТЬ что забирать — то есть лечить
  /// имеет смысл. `false` — реле не держит ничего нашего: получатель всё забрал
  /// и подтвердил, переотправлять нечего.
  ///
  /// 🔴 ОТКАЗ ТРАКТУЕТСЯ КАК «ДЕРЖИТ». Сеть легла, реле старой версии ответило
  /// 404, разбор не удался — во всех этих случаях возвращаем `true` и лечим,
  /// как лечили раньше. Обратное превратило бы сбой связи в тихую потерю смс:
  /// страховка молчала бы ровно тогда, когда она нужнее всего.
  ///
  /// ⚠️ Это ТРАНСПОРТНЫЙ факт, а не доказательство прочтения. Галочки в чате по
  /// нему не ставятся — им остаётся сквозная квитанция. Отсюда гасится только
  /// переотправка.
  Future<void> _resendUndeliveredDirect({
    required String peerProfileId,
    required String peerDeviceId,
    required int stuckBeforeMs,
    String? convoId,
    bool missingReceiptOnly = false,
    /// The recipient ASKED (a NACK named one of our wires). A statement from
    /// the far side outranks our own guessing, so it buys a little extra
    /// lifetime budget — bounded, see _resendUndeliveredMaxNackBonus.
    bool grantNackBonus = false,
  }) async {
    if (isOwnDeviceId(peerDeviceId)) return;
    // 🔴 A ROOM MESSAGE CANNOT BE REPLAYED FROM ITS LOCAL COPY (2026-07-30).
    //
    // What this method re-sends is `_decryptStoredLocalPayloadBytes(eventId)` —
    // MY OWN copy of the message. For a 1:1 chat that copy IS what the peer
    // should receive, so replaying it is exactly right. For a room it is NOT:
    // members receive a `__secretly_group_msg_v1__:` control envelope carrying
    // the room id, the roster and the sender identity, while the local copy is
    // the bare text. Replaying the local copy would hand the member a plain
    // message with no group command, `_parseGroupMessageCommand` would return
    // null, and the receive path would file it under `convoId = <sender's
    // profile id>` — the room's message would appear as a PRIVATE message from
    // its author. Wrong conversation, wrong audience, silently.
    //
    // The session re-key that precedes this call is the actual cure for a
    // diverged member and still runs: every FUTURE room message reaches them.
    // Recovering the already-lost ones needs the room WIRE, not the local copy
    // — which is precisely what the sender key gives us (one `gmsg` ciphertext,
    // replayable verbatim), so this belongs to that work, not to a rebuild of
    // the envelope from five different send shapes.
    //
    // Guarded here rather than at the call site so no future caller can walk
    // into it.
    final sourceConvo = (convoId ?? peerProfileId).trim();
    if (!canReplayLocalCopyToPeer(sourceConvo)) {
      DiagLog.event('send', 'room_resend_content_skipped', {
        'room': DiagLog.pfx(sourceConvo),
        'member': DiagLog.pfx(peerProfileId),
      });
      return;
    }
    // Re-entrancy is keyed per (conversation, device): repairing the same member
    // in two different rooms must not block itself.
    final guardKey = '${convoId ?? peerProfileId}::$peerDeviceId';
    if (!_resendUndeliveredInFlight.add(guardKey)) return;
    try {
      await _resendUndeliveredDirectInner(
        peerProfileId: peerProfileId,
        peerDeviceId: peerDeviceId,
        stuckBeforeMs: stuckBeforeMs,
        convoId: convoId,
        missingReceiptOnly: missingReceiptOnly,
        grantNackBonus: grantNackBonus,
      );
    } finally {
      _resendUndeliveredInFlight.remove(guardKey);
    }
  }

  Future<void> _resendUndeliveredDirectInner({
    required String peerProfileId,
    required String peerDeviceId,
    required int stuckBeforeMs,
    String? convoId,
    bool missingReceiptOnly = false,
    bool grantNackBonus = false,
  }) async {
    final sourceConvoId = convoId ?? peerProfileId;
    // Л-1: эпоха текущей сессии с устройством — единица учёта бюджета.
    // Нет строки сессии → 0: поведение старого ключа, недосчитать безопаснее.
    var resendEpoch = 0;
    // A room repair re-queues a ROOM message to ONE member's device: the push
    // metadata must say which conversation it belongs to (and that it is a
    // room), or the banner would be attributed to the member's 1:1 chat.
    final isRoomRepair = sourceConvoId.startsWith('group:');
    final db = _db;
    final ratchet = _ratchetV3;
    final selfDid = _deviceId;
    if (db == null || ratchet == null || selfDid == null) return;
    if (isOwnDeviceId(peerDeviceId)) return;
    try {
      resendEpoch = await db.sessionV3EpochFor(peerDeviceId);
    } catch (_) {
      resendEpoch = 0;
    }
    List<Map<String, Object?>> events;
    try {
      // Two ways a message can be owed to this peer. The default (local_state
      // still 'sent') is the 1:1 signal and the "nobody in the room got it"
      // case. `missingReceiptOnly` is the ROOM signal: the message may well read
      // 'delivered' because OTHER members acknowledged it, while this one
      // member never did — invisible to local_state, visible per reader in
      // room_message_receipts.
      events = missingReceiptOnly
          ? await db.roomSendsMissingReceiptFrom(
              roomId: sourceConvoId,
              readerProfileId: peerProfileId,
              senderDeviceId: _deviceId ?? '',
              stuckBeforeMs: stuckBeforeMs,
            )
          : await db.undeliveredDirectSentEvents(
        convoId: sourceConvoId,
        stuckBeforeMs: stuckBeforeMs,
        limit: _resendUndeliveredMaxPerPeer,
      );
    } catch (_) {
      return;
    }
    // Log the found-count even when zero: "resend ran and found nothing" and
    // "resend never ran" are indistinguishable without it (2026-07-19 lesson).
    DiagLog.event('send', 'resend_sweep', {
      'peer': DiagLog.pfx(peerProfileId),
      'to_dev': DiagLog.pfx(peerDeviceId),
      'found': events.length,
    });
    if (events.isEmpty) return;

    // 🔴 СПРОСИТЬ РЕЛЕ, ПРЕЖДЕ ЧЕМ СЛАТЬ ЗАНОВО (12.08.2026).
    //
    // Проверка стоит ЗДЕСЬ, а не выше по вызову, по горькой причине: свой
    // запрос к исходящим я сочинил, и в поле он возвращал пусто — гейт молча
    // разрешал переотправку, ни разу не обратившись к реле. Здесь же список
    // застрявших событий УЖЕ посчитан проверенным запросом (`found` выше), а
    // конверты берутся проверенным отображением. Ничего не сочиняем.
    //
    // Замер: драйвер повторов — восстановление после молчания пира (13:25:24 и
    // 13:29:54, ровно 4,5 минуты — те самые «каждые 4-6 минут»). Оно сбрасывает
    // сессию на каждое устройство, а сброс тянет за собой переотправку.
    //
    // Получатель, разобравший смс в ФОНЕ, квитанцию отправить не может (шифрует
    // — значит пишет в отправляющую цепь, что в фоне запрещено правилом И-3),
    // поэтому молчание тут НЕ доказывает недоставку. Реле знает правду:
    // подтверждение удаляет строку из ящика.
    var heldZeroRescue = false;
    if (!grantNackBonus) {
      final askIds = <String>[];
      for (final row in events) {
        final eid = ((row['event_id'] as String?) ?? '').trim();
        if (eid.isEmpty) continue;
        try {
          for (final o in await db.outboxListForEventRef(eid)) {
            if (((o['to_device_id'] as String?) ?? '').trim() != peerDeviceId) {
              continue;
            }
            final mid = ((o['msg_id'] as String?) ?? '').trim();
            if (mid.isNotEmpty) askIds.add(mid);
          }
        } catch (_) {
          // не смогли перечислить — не судим, ведём себя как раньше
        }
        if (askIds.length >= 64) break;
      }
      final held = askIds.isEmpty
          ? null
          : await _relay?.pendingCheck(
              toDeviceId: peerDeviceId,
              msgIds: askIds.take(64).toList(growable: false),
            );
      DiagLog.event('send', 'resend_relay_probe', {
        'dev': DiagLog.pfx(peerDeviceId),
        'asked': askIds.length,
        // null = спросить не вышло (нет конвертов, нет реле, сеть, старый
        // сервер). Тогда лечим, как лечили: обратное превратило бы сбой связи
        // в тихую потерю по-настоящему пропавшей смс.
        'held': held?.toString() ?? 'unknown',
      });
      // 🔴 «РЕЛЕ ПУСТО» — НЕ ДОКАЗАТЕЛЬСТВО ДОСТАВКИ (ТЗ 16.08, Л-3).
      //
      // Здесь стоял глухой `return`: проверка отвечает «ЗАБРАЛ ли получатель
      // конверты», а читалась как «ПРОЧИТАЛ ли». Класс «забрал и не смог
      // расшифровать» проваливался в дыру навсегда — инцидент 15–16.08: семь
      // проводов сутки стояли с одной галочкой при пустом реле и здоровых
      // обеих сторонах.
      //
      // Замысел `6abd3ab8` сохранён для СВЕЖИХ событий: получатель, разобравший
      // смс в фоне, квитанцию отправить не может (И-3), и молчание первых минут
      // ничего не доказывает. Но событие, которому больше получаса и у которого
      // всё ещё нет квитанции, заслуживает ОДНОЙ пере-шифровки на эпоху сессии
      // (клейм ниже в цикле) — под свежей сессией она открывается, под мёртвой
      // припаркуется и добудет NACK.
      if (held == 0) {
        final gateNow = DateTime.now().millisecondsSinceEpoch;
        events = events
            .where((r) {
              final made = (r['created_at_ms'] as num?)?.toInt() ?? 0;
              return made > 0 && gateNow - made >= _resendHeldZeroMinAgeMs;
            })
            .toList(growable: false);
        if (events.isEmpty) return;
        heldZeroRescue = true;
      }
    }

    final now = DateTime.now().millisecondsSinceEpoch;
    var resent = 0;
    for (final row in events) {
      // Trickle: cap how many we re-send this pass; the rest go on the next
      // backstop tick (their per-event debounce keeps already-sent ones out).
      if (resent >= _resendUndeliveredPerPassCap) break;
      final eventId = ((row['event_id'] as String?) ?? '').trim();
      if (eventId.isEmpty) continue;
      final payloadEventId =
          ((row['payload_event_id'] as String?) ?? '').trim();
      // Per-event debounce (keyed by device so re-keying a second device of the
      // same peer still re-sends to it).
      final resendKey = '$peerDeviceId::$eventId';
      final last = _resendUndeliveredAtMs[resendKey] ?? 0;
      if (now - last < _resendUndeliveredDebounceMs) continue;
      // 🔴 LIFETIME CAP (Э-0).
      //
      // The debounce above bounds the RATE; nothing bounded the TOTAL. And it
      // lives in memory, so an app restart reopened the gate at once. Measured
      // on prod: one message re-sent 94 times over 30 hours, 13 messages
      // becoming 504 mailbox rows, 298 copies into a device the relay had
      // already evicted. Each re-send is a new relay message, hence a new push
      // and a new banner — the "notifications for messages I already read".
      //
      // Past a handful of attempts the evidence is unambiguous: attempt 95
      // delivers nothing that attempt 5 did not. Stop, and let the session heal
      // (or the recipient's own NACK) be what moves things forward.
      if (grantNackBonus) {
        // The recipient named one of our wires as unopenable. That is FACT
        // where the timer paths only have silence, so it earns extra budget —
        // capped, so a peer looping on its own fault cannot farm us.
        await db.resendBudgetGrantBonus(
          eventId: eventId,
          deviceId: peerDeviceId,
          epoch: resendEpoch,
          maxBonus: _resendUndeliveredMaxNackBonus,
          nowMs: now,
        );
      }
      // Checked here, CONSUMED only once a wire is actually in the outbox (see
      // the enqueue below). Several `continue`s sit between the two — an
      // unreadable local payload, the dead-blob gate, an encryption failure —
      // and an attempt that never left the device must not cost budget.
      if (!await db.resendBudgetHasRoom(
        eventId: eventId,
        deviceId: peerDeviceId,
        epoch: resendEpoch,
        maxAttempts: _resendUndeliveredMaxLifetimeAttempts,
      )) {
        DiagLog.event('send', 'resend_budget_spent', {
          'event': DiagLog.pfx(eventId),
          'dev': DiagLog.pfx(peerDeviceId),
        });
        // И-Д (ТЗ 16.08, Л-4): исчерпанный в ТЕКУЩЕЙ эпохе потолок — это
        // настоящий предел шторма, и дальше автоматике хода нет. Тогда
        // недоставка обязана стать ВИДИМОЙ: пользователь два дня смотрел на
        // одну галочку, неотличимую от «собеседник просто не открыл чат».
        // Только для собеседника с одним устройством: при нескольких этот
        // счёт per-device и событие ещё может доехать через другое.
        try {
          final devs = await db.contactDevicesList(peerProfileId);
          if (devs.length <= 1 &&
              await db.eventMarkFailedIfStillSent(eventId)) {
            DiagLog.event('send', 'marked_undelivered', {
              'event': DiagLog.pfx(eventId),
              'dev': DiagLog.pfx(peerDeviceId),
            });
            _changed.add(null);
          }
        } catch (_) {}
        continue;
      }
      // Л-3: спасение при пустом реле — строго одна пере-шифровка на эпоху.
      if (heldZeroRescue &&
          !await db.resendHeldZeroClaimOnce(
            eventId: eventId,
            deviceId: peerDeviceId,
            epoch: resendEpoch,
          )) {
        continue;
      }
      Uint8List? plain;
      try {
        plain = await _decryptStoredLocalPayloadBytes(eventId);
      } catch (_) {
        plain = null;
      }
      if (plain == null || plain.isEmpty) continue;
      // Decode ONCE — both the A3 dead-blob gate and the visible-push meta
      // need the payload's first event. Undecodable → treat as opaque control
      // (no gate, silent heal meta), exactly the pre-A3 behaviour.
      E2eEventV1? firstEvent;
      try {
        final decoded = E2ePayloadV1.decode(plain);
        firstEvent = decoded.events.isEmpty ? null : decoded.events.first;
      } catch (_) {
        firstEvent = null;
      }
      // TZ Epic A3 gate: an attachment/sticker whose relay blob is already
      // gone (expired TTL / local-only id) would render a permanently-broken
      // bubble on the peer — skip it (the E4 re-share flow is the cure).
      // 6h margin so a blob about to expire mid-heal doesn't slip through.
      String? resendBlobId;
      if (firstEvent is AttachmentEventV1) {
        resendBlobId = firstEvent.blobId;
      } else if (firstEvent is StickerEventV1) {
        resendBlobId = firstEvent.blobId; // null/empty for catalog stickers
      }
      if (resendBlobId != null && resendBlobId.isNotEmpty) {
        var blobLive = false;
        if (!resendBlobId.startsWith('local:')) {
          try {
            final exp = await db.attachmentExpiresAtMs(resendBlobId);
            blobLive = exp > now + 6 * 60 * 60 * 1000;
          } catch (_) {
            blobLive = false;
          }
        }
        if (!blobLive) {
          DiagLog.event('send', 'resend_skip_dead_blob', {
            'event': DiagLog.pfx(eventId),
            'blob': DiagLog.pfx(resendBlobId),
          });
          _resendUndeliveredAtMs[resendKey] = now;
          continue;
        }
      }
      try {
        final wire = await _encryptToPeerSerialized(
          ratchet: ratchet,
          selfDeviceId: selfDid,
          peerProfileId: peerProfileId,
          peerDeviceId: peerDeviceId,
          plaintext: plain,
        );
        final msgId = _uuid.v4();
        final createdAtMs = DateTime.now().millisecondsSinceEpoch;
        // VISIBLE-PUSH FIX (2026-07-18, proven in prod logs): these are USER
        // MESSAGES the peer has NEVER seen — from their side this is a brand-new
        // incoming message, not bookkeeping. Riding the silent session-heal meta
        // meant the relay pushed wake_kind=session_heal_v1: no banner, and a
        // silent data push cannot even launch a killed iOS app — so the resent
        // content sat in the mailbox invisibly ("смс не приходят") until the
        // user happened to open the app. Rebuild the ORIGINAL chat transport
        // meta from the stored payload so the peer gets a normal message push
        // (per-conversation collapse-id keeps repeated resends to ONE banner).
        // Non-chat payloads (controls) keep the silent heal meta.
        String? resendMeta;
        try {
          final first = firstEvent;
          if (first is MsgEventV1) {
            resendMeta = _buildChatTransportMetaJson(
              convoId: sourceConvoId,
              isGroup: isRoomRepair,
              messageKind: 'text',
              payloadEventId: payloadEventId.isEmpty
                  ? first.eventId
                  : payloadEventId,
              createdAtMs: createdAtMs,
              senderProfileId: _profileId ?? '',
              senderDisplayName: myNickname,
              previewText: first.text,
            );
          } else if (first is AttachmentEventV1) {
            resendMeta = _buildChatTransportMetaJson(
              convoId: sourceConvoId,
              isGroup: isRoomRepair,
              messageKind: 'attachment',
              payloadEventId: payloadEventId.isEmpty
                  ? first.eventId
                  : payloadEventId,
              createdAtMs: createdAtMs,
              senderProfileId: _profileId ?? '',
              senderDisplayName: myNickname,
              previewText: _pushTransportPreviewForAttachment(first.mime),
            );
          }
        } catch (_) {
          resendMeta = null; // fall back to the silent heal meta
        }
        await db.outboxUpsert(
          msgId: msgId,
          toDeviceId: peerDeviceId,
          ciphertextB64: base64Encode(wire),
          ttlSeconds: _outboxUserMessageTtlSeconds,
          state: OutboxSendState.pending,
          attemptCount: 0,
          nextRetryAtMs: createdAtMs,
          createdAtMs: createdAtMs,
          correlationId: eventId,
          payloadEventId: payloadEventId.isEmpty ? null : payloadEventId,
          convoId: sourceConvoId,
          transportMetaJson: resendMeta ?? _sessionHealTransportMetaJson,
          expiresAtMs: createdAtMs + _outboxUserMessageTtlMs,
          eventIdRef: eventId,
        );
        // 🔴 БЮДЖЕТ СПИСЫВАЕТСЯ ПО ПОДТВЕРЖДЕНИЮ РЕЛЕ, А НЕ ЗДЕСЬ (15.08.2026).
        //
        // Здесь стояло списание: «кадр в очереди — значит попытка потрачена».
        // Но между очередью и реле лежит СЕТЬ. Замер прода: у владельца пять
        // попыток сгорели в яме 429, не отправив НИ ОДНОГО кадра, и сообщения
        // застряли на телефоне навсегда — при каждом следующем проходе
        // `resend_budget_spent`.
        //
        // Замысел автора («budget is for wires that were SENT, never for
        // attempts that died at home») сохранён полностью — исправлена только
        // граница: очередь это ещё дом. Потолок в 5 доставок ДО РЕЛЕ остаётся,
        // поэтому шторм с 94 копиями вернуться не может.
        await db.resendPendingMark(
          msgId: msgId,
          eventId: eventId,
          deviceId: peerDeviceId,
          epoch: resendEpoch,
        );
        _resendUndeliveredAtMs[resendKey] = now;
        resent++;
      } catch (_) {
        // best-effort per message — a transient encrypt/db error just retries
        // on the next backstop tick.
      }
    }
    if (resent > 0) {
      DiagLog.event('send', 'resend_undelivered', {
        'peer': DiagLog.pfx(peerProfileId),
        'dev': DiagLog.pfx(peerDeviceId),
        'count': resent,
      });
      _kickRelayOutbox();
    }
    // Bound the debounce map so a long-lived session can't leak it.
    if (_resendUndeliveredAtMs.length > 512) {
      final cutoff = now - 10 * _resendUndeliveredDebounceMs;
      _resendUndeliveredAtMs.removeWhere((_, ts) => ts < cutoff);
    }
  }

  /// Re-encrypt ONE named local outbound event to a peer and enqueue it as a
  /// fresh wire (2026-07-23, undecryptable-recovery). Mirrors the per-event body
  /// of [_resendUndeliveredDirectInner] but for a SINGLE, explicitly-named event
  /// — used when a peer NACKs a specific wire it cannot decrypt. Resends THAT
  /// message REGARDLESS of its local_state: the blanket sweep only covers
  /// `local_state='sent'`, so a message the peer marked delivered/read but can no
  /// longer decrypt (ratchet desync) would otherwise never be re-sent — the exact
  /// "one of three arrived" loss. New msg_id + preserved payload_event_id, so the
  /// receiver applies it (apply-dedup is keyed on relay msg_id) while the
  /// payload-id idempotency guard drops it if the peer already had it. Returns
  /// true iff a wire was enqueued. Dead-blob gate matches the sweep.
  Future<bool> _resendOneEventReEncrypted({
    required String eventId,
    required String payloadEventId,
    required String peerProfileId,
    required String peerDeviceId,
  }) async {
    final db = _db;
    final ratchet = _ratchetV3;
    final selfDid = _deviceId;
    if (db == null || ratchet == null || selfDid == null || selfDid.isEmpty) {
      return false;
    }
    if (eventId.isEmpty || peerProfileId.isEmpty || peerDeviceId.isEmpty) {
      return false;
    }
    // 🔴 A ROOM EVENT MUST NOT BE REPLAYED FROM ITS LOCAL COPY. This path is
    // reached by relay msg_id (a NACK names the wire, not the conversation), and
    // a room fanout stamps `event_id_ref = local:grp:<id>` on its outbox rows —
    // so a member NACKing a room wire lands us here with a ROOM event. What is
    // stored locally is the bare message; what members need is the
    // `__secretly_group_msg_v1__:` envelope. Replaying the local copy would file
    // the room's message into a PRIVATE chat with its author. See
    // [canReplayLocalCopyToPeer]; the session re-key fired by the NACK handler
    // is still the repair that matters.
    try {
      final row = await db.eventGet(eventId);
      final convo = ((row?['convo_id'] as String?) ?? '').trim();
      if (convo.isNotEmpty && !canReplayLocalCopyToPeer(convo)) {
        DiagLog.event('send', 'nack_resend_skip_room', {
          'event': DiagLog.pfx(eventId),
          'room': DiagLog.pfx(convo),
        });
        return false;
      }
    } catch (_) {
      // Unreadable row: fall through — the payload decrypt below fails anyway.
    }
    Uint8List? plain;
    try {
      plain = await _decryptStoredLocalPayloadBytes(eventId);
    } catch (_) {
      plain = null;
    }
    if (plain == null || plain.isEmpty) return false;
    E2eEventV1? firstEvent;
    try {
      final decoded = E2ePayloadV1.decode(plain);
      firstEvent = decoded.events.isEmpty ? null : decoded.events.first;
    } catch (_) {
      firstEvent = null;
    }
    String? resendBlobId;
    if (firstEvent is AttachmentEventV1) {
      resendBlobId = firstEvent.blobId;
    } else if (firstEvent is StickerEventV1) {
      resendBlobId = firstEvent.blobId;
    }
    if (resendBlobId != null && resendBlobId.isNotEmpty) {
      var blobLive = false;
      if (!resendBlobId.startsWith('local:')) {
        try {
          final exp = await db.attachmentExpiresAtMs(resendBlobId);
          blobLive =
              exp > DateTime.now().millisecondsSinceEpoch + 6 * 60 * 60 * 1000;
        } catch (_) {
          blobLive = false;
        }
      }
      if (!blobLive) {
        DiagLog.event('send', 'nack_resend_skip_dead_blob', {
          'event': DiagLog.pfx(eventId),
        });
        return false;
      }
    }
    try {
      final wire = await _encryptToPeerSerialized(
        ratchet: ratchet,
        selfDeviceId: selfDid,
        peerProfileId: peerProfileId,
        peerDeviceId: peerDeviceId,
        plaintext: plain,
      );
      final msgId = _uuid.v4();
      final createdAtMs = DateTime.now().millisecondsSinceEpoch;
      String? resendMeta;
      try {
        final first = firstEvent;
        if (first is MsgEventV1) {
          resendMeta = _buildChatTransportMetaJson(
            convoId: peerProfileId,
            isGroup: false,
            messageKind: 'text',
            payloadEventId: payloadEventId.isEmpty ? first.eventId : payloadEventId,
            createdAtMs: createdAtMs,
            senderProfileId: _profileId ?? '',
            senderDisplayName: myNickname,
            previewText: first.text,
          );
        } else if (first is AttachmentEventV1) {
          resendMeta = _buildChatTransportMetaJson(
            convoId: peerProfileId,
            isGroup: false,
            messageKind: 'attachment',
            payloadEventId: payloadEventId.isEmpty ? first.eventId : payloadEventId,
            createdAtMs: createdAtMs,
            senderProfileId: _profileId ?? '',
            senderDisplayName: myNickname,
            previewText: _pushTransportPreviewForAttachment(first.mime),
          );
        }
      } catch (_) {
        resendMeta = null;
      }
      await db.outboxUpsert(
        msgId: msgId,
        toDeviceId: peerDeviceId,
        ciphertextB64: base64Encode(wire),
        ttlSeconds: _outboxUserMessageTtlSeconds,
        state: OutboxSendState.pending,
        attemptCount: 0,
        nextRetryAtMs: createdAtMs,
        createdAtMs: createdAtMs,
        correlationId: eventId,
        payloadEventId: payloadEventId.isEmpty ? null : payloadEventId,
        convoId: peerProfileId,
        transportMetaJson: resendMeta ?? _sessionHealTransportMetaJson,
        expiresAtMs: createdAtMs + _outboxUserMessageTtlMs,
        eventIdRef: eventId,
      );
      DiagLog.event('send', 'nack_resend_specific', {
        'event': DiagLog.pfx(eventId),
        'dev': DiagLog.pfx(peerDeviceId),
      });
      _kickRelayOutbox();
      return true;
    } catch (_) {
      return false;
    }
  }

  /// Shared enqueue body for [_scheduleSessionResetPing] / [_forceSessionResetPing].
  /// Resolves the peer profile, encrypts an empty payload, and parks it in the
  /// outbox. Best-effort; on profile lookup failure the device is queued for a
  /// reconnect-time retry.
  ///
  /// CONVERGENCE-CRITICAL (E2EE reset semantics): a reset-ping MUST be a FRESH
  /// X3DH INITIAL (prekey) wire, never a `session` wire on the existing ratchet.
  /// Reason: the whole point of a reset is to recover when the local session is
  /// DIVERGED from the peer's. If we encrypt under the dead session, the peer —
  /// whose session is equally diverged — cannot decrypt it, quarantines it, and
  /// never adopts a new session ⇒ permanent mutual deadlock.
  ///
  /// `encryptToPeer` only emits a fresh prekey when there is NO local
  /// `sessions_v3` row (it bootstraps X3DH from the peer's bundle). Some callers
  /// (reactive decrypt-fail path) delete the row first; the recovery sweeps
  /// (stuck-outbox / silence / quarantine FIX D) historically did NOT, so their
  /// pings rode the diverged session as a `session` wire — the live deadlock.
  /// We therefore archive + delete the local session HERE, inside the per-peer
  /// encrypt gate, so the reset-ping is ALWAYS a fresh X3DH initial regardless
  /// of which path scheduled it. The archive keeps stragglers decryptable.
  void _dispatchSessionResetPing(String peerDeviceId, String cause) {
    if (peerDeviceId.isEmpty) return;
    // 🔴 СЕБЕ ПИНГ СБРОСА НЕ ШЛЁМ (23.08.2026).
    //
    // Проверялась только пустота идентификатора, и собственное устройство,
    // попав в «пиры», получало лечебный пинг от самого себя. Сессии с собой нет,
    // поэтому пинг возвращался и не расшифровывался (MAC), падал в карантин — а
    // карантин квалифицируется как «сессия разошлась» и заказывает НОВЫЙ пинг.
    // Цикл кормил сам себя: каждые ~40 с счётчик «не удалось прочитать» +1.
    //
    // Сравнение строго с СОБСТВЕННЫМ device_id: второе своё устройство —
    // полноценный пир, с ним сессия есть и лечить её нужно как обычно.
    if (peerDeviceId.trim() == (_deviceId ?? '').trim()) {
      DiagLog.event('inbox', 'reset_ping_self_skipped', {
        'peer_dev': DiagLog.pfx(peerDeviceId),
        'cause': cause,
      });
      return;
    }
    unawaited(() async {
      try {
        final db = _db;
        final selfDid = _deviceId;
        final ratchet = _ratchetV3;
        final relay = _relay;
        if (db == null || selfDid == null || ratchet == null || relay == null) {
          return;
        }
        final peerProfileId = await _resolveProfileIdForDevice(peerDeviceId);
        if (peerProfileId == null || peerProfileId.isEmpty) {
          // Profile lookup failed right now (cache miss / network issue).
          // Persist the device ID so we retry on the next relay reconnect
          // instead of silently discarding the prekey exchange.
          _enqueueSessionResetRetry(peerDeviceId);
          DiagLog.event('inbox', 'reset_ping_deferred', {
            'peer_dev': DiagLog.pfx(peerDeviceId),
            'reason': 'no_profile',
          });
          return;
        }
        final payload = E2ePayloadV1(
          senderDeviceId: selfDid,
          createdAtMs: DateTime.now().millisecondsSinceEpoch,
          events: const <E2eEventV1>[],
        );
        final wire = await _encryptToPeerSerialized(
          ratchet: ratchet,
          selfDeviceId: selfDid,
          peerProfileId: peerProfileId,
          peerDeviceId: peerDeviceId,
          plaintext: Uint8List.fromList(payload.encode()),
          // Force a fresh X3DH initial: archive then delete any live session so
          // encryptToPeer re-runs prekey bootstrap. This is what makes the
          // reset processable by a diverged receiver (see method doc above).
          forceFreshPrekey: true,
          // TZ §20 pillar 3: the reset MUST be SPK-only. If it carried a
          // one-time prekey, a diverged peer that already consumed/rotated that
          // OTK would HARD-FAIL to accept the reset (responderAccept throws
          // "missing one-time prekey") and the session would deadlock forever.
          // SPK-only X3DH is always acceptable → the heal reliably converges.
          forceSpkOnly: true,
        );
        final msgId = _uuid.v4();
        final ttlMs = 60 * 60 * 1000;
        final createdAtMs = DateTime.now().millisecondsSinceEpoch;
        await db.outboxUpsert(
          msgId: msgId,
          toDeviceId: peerDeviceId,
          ciphertextB64: base64Encode(wire),
          ttlSeconds: 60 * 60,
          state: OutboxSendState.pending,
          attemptCount: 0,
          nextRetryAtMs: createdAtMs,
          createdAtMs: createdAtMs,
          correlationId: 'session-reset:$peerDeviceId',
          convoId: peerProfileId,
          // F4: high-priority silent wake so a frozen peer heals promptly.
          transportMetaJson: _sessionHealTransportMetaJson,
          eventIdRef: null,
          expiresAtMs: createdAtMs + ttlMs,
        );
        DiagLog.event('inbox', 'reset_ping_enqueued', {
          'peer_dev': DiagLog.pfx(peerDeviceId),
          'msg': DiagLog.pfx(msgId),
          // Кто заказал. Без этого поля разбор петли 23.08 занял час.
          'cause': cause,
        });
        _sessionResetCauseCounts[cause] =
            (_sessionResetCauseCounts[cause] ?? 0) + 1;
        // Successfully queued — clear from the deferred retry set so we don't
        // resend on the next reconnect (outbox handles its own retry from here).
        _sessionResetRetryDeviceIds.remove(peerDeviceId);
        unawaited(_pruneSessionResetRetryPrefs(peerDeviceId));
        _kickRelayOutbox(relay);
        // И-4k: the reset above ran `forceFreshPrekey` — it archived+deleted the
        // old session and bootstrapped a fresh one. Any message we already SENT to
        // this peer that was never delivered was encrypted under the now-dead
        // session and is permanently undecryptable for them. Re-encrypt+resend it
        // under the fresh session NOW (the peer adopts this reset's prekey, so the
        // resent wires ride the same session it can decrypt). Parallels the held-
        // scheduled-wire refresh in _forceSessionResetPing; this covers the
        // already-sent-undelivered ones the held-wire path never touches — the
        // exact first-message-to-a-new-account orphan (the NACK-driven resend
        // can't run while the reverse session is still unformed; our OWN reset is
        // the reliable trigger). Bounded + idempotent (see the flag doc); the
        // resend's own re-entrancy guard folds any overlap with the NACK handler.
        if (i4kResendUndeliveredOnReset) {
          unawaited(
            _resendUndeliveredDirect(
              peerProfileId: peerProfileId,
              peerDeviceId: peerDeviceId,
              stuckBeforeMs: DateTime.now().millisecondsSinceEpoch,
            ),
          );
        }
      } catch (e) {
        DiagLog.event('inbox', 'reset_ping_fail', {
          'peer_dev': DiagLog.pfx(peerDeviceId),
          'err': e.toString().substring(0, math.min(80, e.toString().length)),
        });
      }
    }());
  }

  /// Send ONE debounced reciprocal confirm-ping to [peerDeviceId] after we
  /// adopted that peer's fresh X3DH prekey (they reset their ratchet toward us).
  ///
  /// CONVERGENCE-CRITICAL: unlike [_dispatchSessionResetPing] this does NOT
  /// delete/refresh the session — it deliberately sends an empty payload ON THE
  /// JUST-ADOPTED session (a normal `session` wire). That gives the peer who
  /// reset a decryptable message in the reverse direction, completing the
  /// handshake automatically. Sending a fresh prekey here instead would discard
  /// the session we just established and risk a reset ping-pong / glare.
  void _scheduleSessionConfirmPing(String peerDeviceId) {
    if (_backgroundInboundMode) return; // foreground heals; bg has no relay
    if (peerDeviceId.isEmpty) return;
    final nowMs = DateTime.now().millisecondsSinceEpoch;
    final lastAt = _sessionConfirmPingAtMs[peerDeviceId] ?? 0;
    if (nowMs - lastAt < _sessionConfirmPingDebounceMs) {
      return;
    }
    _sessionConfirmPingAtMs[peerDeviceId] = nowMs;
    unawaited(() async {
      try {
        final db = _db;
        final selfDid = _deviceId;
        final ratchet = _ratchetV3;
        final relay = _relay;
        if (db == null || selfDid == null || ratchet == null || relay == null) {
          return;
        }
        // Only confirm if we actually hold a live session now (the prekey was
        // adopted). If a glare tie-break kept our own initiator session there is
        // already a send chain and the normal path will carry the reply.
        final session = await db.sessionV3Get(peerDeviceId);
        if (session == null) return;
        final peerProfileId = await _resolveProfileIdForDevice(peerDeviceId);
        if (peerProfileId == null || peerProfileId.isEmpty) return;
        final payload = E2ePayloadV1(
          senderDeviceId: selfDid,
          createdAtMs: DateTime.now().millisecondsSinceEpoch,
          events: const <E2eEventV1>[],
        );
        // forceFreshPrekey: false — encrypt ON the adopted session.
        final wire = await _encryptToPeerSerialized(
          ratchet: ratchet,
          selfDeviceId: selfDid,
          peerProfileId: peerProfileId,
          peerDeviceId: peerDeviceId,
          plaintext: Uint8List.fromList(payload.encode()),
        );
        final msgId = _uuid.v4();
        final ttlMs = 60 * 60 * 1000;
        final createdAtMs = DateTime.now().millisecondsSinceEpoch;
        await db.outboxUpsert(
          msgId: msgId,
          toDeviceId: peerDeviceId,
          ciphertextB64: base64Encode(wire),
          ttlSeconds: 60 * 60,
          state: OutboxSendState.pending,
          attemptCount: 0,
          nextRetryAtMs: createdAtMs,
          createdAtMs: createdAtMs,
          correlationId: 'session-confirm:$peerDeviceId',
          convoId: peerProfileId,
          // F4: high-priority silent wake so a frozen peer heals promptly.
          transportMetaJson: _sessionHealTransportMetaJson,
          eventIdRef: null,
          expiresAtMs: createdAtMs + ttlMs,
        );
        DiagLog.event('inbox', 'confirm_ping_enqueued', {
          'peer_dev': DiagLog.pfx(peerDeviceId),
          'msg': DiagLog.pfx(msgId),
        });
        _kickRelayOutbox(relay);
        // И-4k: we just ADOPTED the peer's fresh X3DH prekey (they reset toward
        // us), so our SEND session to them was replaced. Anything we already sent
        // under the previous send session but that was never delivered is now
        // undecryptable for them — resend it under the just-adopted session (the
        // same one this confirm-ping rides, which the peer can decrypt). This is
        // the mirror of the reset-SEND case in _dispatchSessionResetPing: it makes
        // the pair converge no matter WHICH side initiated the reset. Non-
        // disturbing (the resend only re-encrypts on the current session; it never
        // resets/deletes it, so the delicate glare handling here is untouched).
        if (i4kResendUndeliveredOnReset) {
          unawaited(
            _resendUndeliveredDirect(
              peerProfileId: peerProfileId,
              peerDeviceId: peerDeviceId,
              stuckBeforeMs: DateTime.now().millisecondsSinceEpoch,
            ),
          );
        }
      } catch (e) {
        DiagLog.event('inbox', 'confirm_ping_fail', {
          'peer_dev': DiagLog.pfx(peerDeviceId),
          'err': e.toString().substring(0, math.min(80, e.toString().length)),
        });
      }
    }());
  }

  // ─────────────────────────────────────────────────────────────────────────
  //  Session-reset retry queue (PR-S BUG-S1 / BUG-S2)
  //
  //  When _scheduleSessionResetPing cannot resolve the peer's profile ID
  //  (e.g. device→profile cache miss, network unavailable) the device ID is
  //  persisted here so the prekey exchange is retried on the next relay
  //  reconnect — preventing the "all subsequent messages silently lost"
  //  stuck-inbox state caused by a ratchet desync after app kill.
  // ─────────────────────────────────────────────────────────────────────────

  /// Adds [peerDeviceId] to the persistent session-reset retry set.
  ///
  /// No-op if the device is already queued.  The set is drained on every
  /// relay reconnect via [_drainSessionResetRetryQueue].
  void _enqueueSessionResetRetry(String peerDeviceId) {
    if (peerDeviceId.isEmpty) return;
    if (_sessionResetRetryDeviceIds.contains(peerDeviceId)) return;
    _sessionResetRetryDeviceIds.add(peerDeviceId);
    // Persist best-effort so a process kill doesn't lose the entry.
    unawaited(() async {
      try {
        final prefs = _prefs ?? await SharedPreferences.getInstance();
        final existing = List<String>.from(
          prefs.getStringList(_prefsSessionResetPendingKey) ?? const <String>[],
        );
        if (!existing.contains(peerDeviceId)) {
          existing.add(peerDeviceId);
          await prefs.setStringList(_prefsSessionResetPendingKey, existing);
        }
      } catch (_) {
        // Best-effort — in-memory set already has the entry.
      }
    }());
  }

  /// Removes [peerDeviceId] from the persistent retry set after a successful
  /// reset-prekey dispatch.
  Future<void> _pruneSessionResetRetryPrefs(String peerDeviceId) async {
    try {
      final prefs = _prefs ?? await SharedPreferences.getInstance();
      final existing = List<String>.from(
        prefs.getStringList(_prefsSessionResetPendingKey) ?? const <String>[],
      );
      if (existing.remove(peerDeviceId)) {
        await prefs.setStringList(_prefsSessionResetPendingKey, existing);
      }
    } catch (_) {
      // Best-effort.
    }
  }

  /// Drains the deferred session-reset retry queue.
  ///
  /// Called on every relay reconnect ([_handleRelayConnectionChanged]).  Each
  /// entry in the queue represents a peer whose ratchet session was wiped after
  /// a decrypt failure but whose profile lookup failed at that moment, so the
  /// reset prekey was never sent.  Re-attempting here ensures that B receives
  /// A's fresh prekey and can rebuild the ratchet session, unblocking the
  /// B→A message direction.
  void _drainSessionResetRetryQueue() {
    if (_sessionResetRetryDeviceIds.isEmpty) return;
    // Snapshot before iterating — _scheduleSessionResetPing may mutate the
    // set (e.g. via _enqueueSessionResetRetry on a new lookup failure).
    final pending = Set<String>.from(_sessionResetRetryDeviceIds);
    DiagLog.event('inbox', 'reset_retry_drain', {'count': pending.length});
    for (final deviceId in pending) {
      _scheduleSessionResetPing(deviceId, _resetCauseRetryQueue);
    }
  }

  Future<void> dispose() async {
    _pumpTimer?.cancel();
    _mainAliveHeartbeatTimer?.cancel();
    _serviceWatchdogTimer?.cancel();
    _quarantineRecoverySweepTimer?.cancel();
    _quarantineRecoverySweepTimer = null;
    _supportBadgeTimer?.cancel();
    _supportBadgeTimer = null;
    // Fix D (2026-07-24): cancel any pending grace-delayed reset-pings.
    for (final t in _resetPingGraceTimers.values) {
      t.cancel();
    }
    _resetPingGraceTimers.clear();
    _contactSyncTimer?.cancel();
    _typingSweepTimer?.cancel();
    _iconBadgeDebounce?.cancel();
    _iconBadgeDebounce = null;
    await _iconBadgeSub?.cancel();
    _iconBadgeSub = null;
    await _securityChangedSub?.cancel();
    _securityChangedSub = null;
    await _changedCacheInvalidatorSub?.cancel();
    _changedCacheInvalidatorSub = null;
    // Отложенный сброс кэша больше некого обслуживать: без отмены таймер
    // пережил бы контроллер и дёрнул `_changed` уже после закрытия.
    _cacheInvalidateTimer?.cancel();
    _cacheInvalidateTimer = null;
    _selfTickPending = false;
    await _pushWakeOpenedConvoSub?.cancel();
    _pushWakeOpenedConvoSub = null;
    await _pushWakeMsgSub?.cancel();
    _pushWakeMsgSub = null;
    _foregroundPushPumpDebounce?.cancel();
    _foregroundPushPumpDebounce = null;
    await _nativeNotifTapSub?.cancel();
    _nativeNotifTapSub = null;
    await _nativeMsgActionsSub?.cancel();
    _nativeMsgActionsSub = null;
    await _nativeMediaActionsSub?.cancel();
    _nativeMediaActionsSub = null;
    _appNetworkReconnectDebounce?.cancel();
    _appNetworkReconnectDebounce = null;
    await _appConnectivitySub?.cancel();
    _appConnectivitySub = null;
    await _appNativeNetworkPathSub?.cancel();
    _appNativeNetworkPathSub = null;
    await _appPowerStateSub?.cancel();
    _appPowerStateSub = null;
    await _relay?.close();
    _keys?.close();
    _blob?.close();
    _stickerCatalogClient?.close();
    await _sharedAudioStateSub?.cancel();
    _sharedAudioStateSub = null;
    await _sharedAudioPositionSub?.cancel();
    _sharedAudioPositionSub = null;
    await _sharedAudioDurationSub?.cancel();
    _sharedAudioDurationSub = null;
    if (_supportsNativeMediaControls) {
      try {
        await _nativeMediaNotifChannel.invokeMethod<void>('clear');
      } catch (_) {}
    }
    await _sharedAudioPlayer.dispose();
    _sharedAudioPlayback.dispose();
    await _notificationPlayer.dispose();
    await _db?.close();
    await _callSignals.close();
    await _roomCallMediaSignals.close();
    await _relayConnectionChanges.close();
    await _inAppNotifsController.close();
    await security.dispose();
    await _changed.close();
    await _pendingUploadsChanged.close();
    await _attachmentUploadErrors.close();
    await _restartRequested.close();
  }

  bool _isRecoverableSecureStorageError(Object e) {
    if (e is! PlatformException) return false;
    final raw = '${e.code} ${e.message ?? ''} ${e.details ?? ''}'.toLowerCase();
    return raw.contains('badpadding') ||
        raw.contains('keystore') ||
        raw.contains('decrypt') ||
        raw.contains('invalidkey') ||
        raw.contains('aeadbadtag') ||
        raw.contains('failed to unwrap key');
  }

  /// И-1 (TZ_I1_IDENTITY_2026-07-21): rotates device_id after an INVOLUNTARY
  /// session-store loss, making "same id, clean sessions" unrepresentable.
  ///
  /// Runs from init() after every rescue path has declined, mobile only, and
  /// only under the verified server switch. Deliberately local-first and
  /// crash-safe, mirroring the registration-failure rotation:
  ///   1. the abandoned id goes into the durable delete ledger BEFORE anything
  ///      else — the drain later rebinds its relay mailbox to the live device
  ///      (in-flight wires surface as bounded NACK-driven resends instead of
  ///      rotting) and then deletes the zombie from the keys server;
  ///   2. its Keychain material is removed so nothing can silently re-mint
  ///      under the dead id;
  ///   3. the new uuid is persisted and the keys-published markers cleared —
  ///      the EXISTING idempotent register+publish machinery picks the new id
  ///      up later this launch (or next launch if we die here: fresh material
  ///      is minted on demand, registration retries forever).
  /// No frequency limiter by design (И-5: one path, one guard — the config
  /// switch); chronic loops must surface in i1/rotated telemetry instead of
  /// being papered over.
  Future<void> _rotateDeviceIdentityForStateLoss({
    required SharedPreferences prefs,
    required String reason,
  }) async {
    final oldDid = (_deviceId ?? '').trim();
    if (oldDid.isEmpty) return;
    final pid = (_profileId ?? prefs.getString(_prefsProfileIdKey) ?? '')
        .trim();

    if (pid.isNotEmpty && !pid.startsWith('LOCAL-')) {
      await _recordPendingDeviceDelete(profileId: pid, deviceId: oldDid);
    }
    if (pid.isNotEmpty) {
      try {
        await DeviceKeys.create().deleteMaterial(
          profileId: pid,
          deviceId: oldDid,
        );
      } catch (_) {
        // Best-effort: an unreadable keystore entry must not stop the
        // rotation that this very launch already proved necessary.
      }
    }

    _deviceId = _uuid.v4();
    await prefs.setString(_prefsDeviceIdKey, _deviceId!);
    await _failOutboxEncryptedUnderOldDevice();
    // One-shot repair grant, same as restore-as-new-device: the server does
    // not know this id yet and the missing-current-device repair must be
    // allowed to register it.
    await prefs.setBool(_prefsAllowMissingCurrentDeviceRepairOnceKey, true);
    // Force a fresh register+publish for the new id.
    final staleMarkers = prefs
        .getKeys()
        .where((k) => k.startsWith(_prefsKeysPublishedKeyPrefix))
        .toList(growable: false);
    for (final k in staleMarkers) {
      await prefs.remove(k);
    }
    // Consumed after keys setup succeeds: one E2E no-op control per recent
    // 1:1 peer so their learn-on-receive drops the dead id immediately.
    await prefs.setBool(_prefsI1AnnouncePendingKey, true);
    // Cap-eviction hint (§Д-7): the old id is dead BY CONSTRUCTION here (it
    // is this very device), so the server may evict it instead of the
    // stalest sibling. Restores never set this — their old device may live.
    await prefs.setString(_prefsI1ReplacesHintKey, oldDid);

    _startupWarning =
        'This device was re-issued after a secure-storage reset. '
        'Conversations re-secure automatically; contacts may see a new '
        'security code.';
    DiagLog.event('i1', 'rotated', {
      'reason': reason,
      'old': DiagLog.pfx(oldDid),
      'new': DiagLog.pfx(_deviceId!),
    });
  }

  /// Recovery for a desktop whose device id was removed from the account.
  ///
  /// **The hole this closes.** When the keys server no longer lists this
  /// desktop's device id, `_ensureKeysSetup` refuses — and the QR pairing flow
  /// begins by calling `_ensureKeysSetup`. So the one screen that exists to
  /// re-pair the desktop could not generate a code, and its own instruction
  /// ("sign in again from your primary device") was unfollowable: there was
  /// nothing to scan. Confirmed on a live account 08.09.2026 —
  /// `keys_setup.error msg=This desktop device was removed from your Secretly
  /// ID` fired both at boot and inside the QR path.
  ///
  /// The boot path already assumes this is impossible: see the И-1 stage-c
  /// comment, "a desktop companion that lost its store re-pairs through the QR
  /// link flow, which already mints a fresh desktop device_id". That invariant
  /// was stated but never upheld. This method upholds it.
  ///
  /// **Why a new identity rather than repairing the old one.** The controller
  /// already has a flag that would make the old id work again —
  /// `allowMissingCurrentDeviceRepair`, which
  /// [AppRuntimeLifecycleCoordinator.resolveMissingCurrentDevice] treats as
  /// unconditional permission. Using it here would let a **revoked** desktop
  /// put itself back into the account's device list with one click, and peers
  /// would resume encrypting to it — without the primary device approving
  /// anything. In a messenger, "remove this device" has to mean it.
  ///
  /// So the old id stays revoked and dead. This mints a NEW one, exactly as a
  /// fresh desktop install would have, and that new id gets nothing until the
  /// phone scans the QR and approves: keys, profile and history all arrive
  /// through that approval. Generating a code grants no access by itself,
  /// which is what makes this safe.
  ///
  /// Explicitly user-initiated by construction — it is reachable only from a
  /// button on the pairing screen, in the state that requires it.
  Future<void> resetDesktopDeviceIdentityForRepair() async {
    if (!_isDesktopOrWebPlatform) return;
    final prefs = _prefs ?? await SharedPreferences.getInstance();
    _prefs = prefs;

    final oldDid = (_deviceId ?? '').trim();
    DiagLog.event('desktop_link', 'identity_reset_begin', {
      'old': DiagLog.pfx(oldDid),
    });

    // Mints a fresh device id, grants the one-shot missing-device repair for
    // it (the server does not know the new id yet, so registering it is not
    // "un-revoking" anything), drops the stale publish markers and records the
    // old id for deletion. Deliberately NOT gated on the identity-rotation
    // server flag the mobile state-loss path checks: a recovery that a remote
    // flag can switch off is not a recovery.
    await _rotateDeviceIdentityForStateLoss(
      prefs: prefs,
      reason: 'desktop_device_removed_from_account',
    );

    // The rotation writes a warning about a secure-storage reset, which is not
    // what happened here. Say the true thing instead.
    _startupWarning =
        'This desktop was given a new device identity. Scan the QR code from '
        'your phone to finish connecting it.';

    // Leave the error state so the pairing screen can actually retry; the QR
    // flow sets its own state from here.
    _desktopDeviceRemovedFromAccount = false;
    _setAuthFlowState(AuthFlowState.unauthenticated);
    DiagLog.event('desktop_link', 'identity_reset_done', {
      'new': DiagLog.pfx(_deviceId ?? ''),
    });
    if (!_changed.isClosed) _changed.add(null);
  }

  /// И-1: resolves the rotation switch when the cached value says "dormant".
  ///
  /// A FRESH install restoring a backup has no cached flag: prefs died with
  /// the old install, and the config ride-along (entitlements refresh) only
  /// runs once a profile exists — which is exactly what the restore is about
  /// to create. The restore is already a network flow, so asking /v1/config
  /// (public, unauthenticated) right here is the honest fix. Bounded and
  /// best-effort: any failure returns false and the restore behaves like the
  /// previous build. A verified answer is cached so the post-restore restart
  /// starts armed.
  Future<bool> _resolveIdentityRotationFlagBounded() async {
    if (_identityRotationEnabledEffective) return true;
    try {
      final keys = _keys ?? KeysClient(baseUrl: keysBaseUrl);
      final config = await keys.getConfig().timeout(
        const Duration(seconds: 6),
      );
      final flags = IdentityFlags.fromConfigResponse(
        config,
        verified: await verifyIdentitySignature(config),
      );
      _identityRotationOnStateLossEnabled = flags.rotationOnStateLossEnabled;
      final prefs = _prefs;
      if (prefs != null) {
        await prefs.setBool(
          _prefsI1RotationEnabledKey,
          flags.rotationOnStateLossEnabled,
        );
      }
      DiagLog.event('i1', 'rotation_flag_resolved_for_restore', {
        'enabled': flags.rotationOnStateLossEnabled,
      });
      return flags.rotationOnStateLossEnabled;
    } catch (_) {
      return false;
    }
  }

  /// И-1: keeps the database file and the device identity in agreement.
  ///
  /// Every open stamps the current device_id into the file (local_kv). If the
  /// file already carries a DIFFERENT stamp, this is a quarantined copy
  /// resurrected after the device rotated: keep the user's history, purge the
  /// ratchet rows that belong to the dead identity. Legacy files without a
  /// stamp are left as-is (pre-И-1 behaviour). Best-effort — never blocks
  /// boot.
  Future<void> _reconcileDbIdentityStamp() async {
    final db = _db;
    final did = (_deviceId ?? '').trim();
    if (db == null || did.isEmpty) return;
    try {
      final stamped = (await db.localKvGet(_dbKvOwnDeviceIdKey) ?? '').trim();
      if (stamped.isNotEmpty && stamped != did) {
        if (_deviceIdMintedThisLaunch) {
          // We invented `did` minutes ago only because prefs read empty, and
          // the database file — which survives exactly this kind of loss — is
          // holding our real identity. Take it back rather than treating our
          // own guess as the truth and the evidence as the intruder. Purging
          // here would have deleted every session AND abandoned the mailbox
          // peers are still writing to, which is how one message of a pair
          // went missing while the next arrived.
          _deviceId = stamped;
          final prefs = _prefs ?? await SharedPreferences.getInstance();
          _prefs = prefs;
          await prefs.setString(_prefsDeviceIdKey, stamped);
          _deviceIdMintedThisLaunch = false;
          DiagLog.event('identity', 'device_id_restored_from_db', {
            'restored': DiagLog.pfx(stamped),
            'discarded': DiagLog.pfx(did),
          });
          return;
        }
        // A genuine mismatch: we had a persisted identity that disagrees with
        // the file (a quarantined copy resurrected after a real rotation).
        // Keep the history, drop the ratchet rows of the dead identity.
        await db.purgeRatchetStateForForeignIdentity();
        DiagLog.event('i1', 'foreign_ratchet_purged', {
          'stamped': DiagLog.pfx(stamped),
          'did': DiagLog.pfx(did),
        });
      }
      await db.localKvSet(_dbKvOwnDeviceIdKey, did);
    } catch (e) {
      DiagLog.event('i1', 'stamp_reconcile_failed', {
        'err': _shortErrorTag(e),
      });
    }
  }

  /// Puts a quarantined database back when the live one is empty.
  ///
  /// Runs on every launch and needs no user action. Deliberately conservative:
  /// it does nothing unless the live database has NO content, so a normal
  /// account can never be overwritten by a stale copy. When a copy exists that
  /// we cannot open (its key is genuinely gone) the user is told rather than
  /// left to guess why their history vanished.
  ///
  /// Returns true only when a quarantined copy was actually restored — И-1
  /// uses that to clear the provisional state-loss marker.
  Future<bool> _restoreQuarantinedDatabaseIfLocalIsEmpty(
    SecureSecrets secrets,
  ) async {
    try {
      final db = _db;
      if (db == null) return false;
      // A restore already in flight owns this database. Its snapshot is
      // applied a few lines later; resurrecting a quarantined copy first would
      // leave the previous account's rows underneath the restored identity.
      final prefs = _prefs ?? await SharedPreferences.getInstance();
      if ((prefs.getString(_prefsPendingSafeImportKey) ?? '').isNotEmpty) {
        return false;
      }
      if (!await AppDb.hasQuarantinedBackups()) return false;
      if (!await db.looksEmpty()) return false;

      final pass = await secrets.requireExistingDbPassphrase();
      // The handle must be closed before the files underneath it are moved.
      await db.close();
      _db = null;

      final restored = await AppDb.tryRestoreQuarantinedDatabase(
        passphrase: pass,
      );
      // On failure nothing was moved, so the same path reopens the same file.
      _db = await AppDb.open(passphrase: pass);

      if (restored) {
        _startupWarning ??= 'Your local encrypted storage has been recovered.';
        DiagLog.event('db', 'quarantine_restored', const {'from': 'empty_db'});
      } else {
        _startupWarning ??=
            'A copy of your earlier encrypted storage is kept on this device, '
            'but its key is no longer available.';
        DiagLog.event('db', 'quarantine_unopenable', const {});
      }
      return restored;
    } catch (e) {
      // Best-effort: a failure here must never block startup. The live handle
      // is restored below if we closed it.
      DiagLog.event('db', 'quarantine_restore_failed', {
        'err': _shortErrorTag(e),
      });
      if (_db == null) {
        try {
          _db = await AppDb.open(
            passphrase: await secrets.requireExistingDbPassphrase(),
          );
        } catch (_) {
          // Leave _db null; init's caller surfaces the failure and retries.
        }
      }
      return false;
    }
  }

  bool _isRecoverableDbOpenError(Object e) {
    final raw = e.toString().toLowerCase();
    return raw.contains('file is not a database') ||
        raw.contains('not a database') ||
        raw.contains('malformed') ||
        raw.contains('cipher') ||
        raw.contains('sqlcipher');
  }

  // NOTE (FIX F, 2026-06-18): the former `_isUnrecoverableDeliveredDecryptError`
  // monolithic classifier was split into [DeliveredDecryptAckPolicy] — which
  // separates GENUINE-PERMANENT failures (ack + reset) from TRANSIENT ones
  // (leave un-acked for the relay to re-offer). The ack decision now lives in
  // that pure, unit-tested helper; see `_handleDelivered`'s failure branch.

  /// Compress an exception's text to a short, human-greppable fingerprint
  /// suitable for `DiagLog`. Output stays under 20 chars and contains a `-`
  /// separator so the DiagLog sanitizer never mistakes it for base64.
  static String _shortErrorTag(Object e) {
    final raw = e.toString().toLowerCase();
    final keep = StringBuffer();
    var len = 0;
    for (final code in raw.codeUnits) {
      final ok =
          (code >= 0x61 && code <= 0x7a) || // a-z
          (code >= 0x30 && code <= 0x39); // 0-9
      if (ok) {
        keep.writeCharCode(code);
        len++;
      } else if (len > 0 && keep.toString().codeUnitAt(len - 1) != 0x2d) {
        keep.write('-');
        len++;
      }
      if (len >= 20) break;
    }
    var s = keep.toString();
    while (s.endsWith('-')) {
      s = s.substring(0, s.length - 1);
    }
    return s.isEmpty ? 'unknown' : s;
  }
}

