Map<String, Object?>? _decodeCommandPayload(String text, String prefix) {
  if (!text.startsWith(prefix)) return null;
  final raw = text.substring(prefix.length).trim();
  if (raw.isEmpty) return null;
  try {
    final decoded = utf8.decode(base64Url.decode(raw));
    final jsonObj = jsonDecode(decoded);
    if (jsonObj is Map<String, dynamic>) {
      return Map<String, Object?>.from(jsonObj);
    }
    if (jsonObj is Map) {
      return jsonObj.cast<String, Object?>();
    }
  } catch (e) {
    callLog(
      'AppCtrl',
      '_decodeCommandPayload failed (prefix=$prefix, len=${raw.length}): $e',
    );
    return null;
  }
  return null;
}

String _encodeCommandPayload(String prefix, Map<String, Object?> payload) {
  return '$prefix${base64Url.encode(utf8.encode(jsonEncode(payload)))}';
}

Map<String, Object?>? _parseReactionCommand(String text) {
  return _decodeCommandPayload(text, AppController._reactionCmdPrefix);
}

Map<String, Object?>? _parseClearHistoryCommand(String text) {
  return _decodeCommandPayload(text, AppController._clearHistoryCmdPrefix);
}

/// Номер отправителя, который НАЗЫВАЕТ сам провод (заголовок SKS2 или SKS1).
///
/// Это слова провода, а не проверенный факт: рукопожатие подписи отправителя
/// не несёт, реле отправителя не сообщает. Годится для отказа, не для доверия.
@visibleForTesting
String? claimedWireSenderDeviceId(Uint8List wireBytes) {
  try {
    final header =
        RatchetWireV3.tryDecode(wireBytes)?.header ??
        RatchetWireV1.tryDecode(wireBytes)?.header;
    final sid = (header?['sender_device_id'] as String?)?.trim();
    return (sid == null || sid.isEmpty) ? null : sid;
  } catch (_) {
    return null;
  }
}

/// Насколько дата очистки из пришедшей команды может опережать наши часы.
///
/// Часы устройств расходятся на минуты. Дата «через сто лет» глушила бы
/// переписку навсегда: всё новое в ней отбрасывается по отсечке
/// (`_shouldDropConversationEventByClearCutoff`).
const Duration kInboundClearCutoffMaxLead = Duration(minutes: 10);

@visibleForTesting
int clampInboundClearCutoffMs(int cutoffCreatedAtMs, {required int nowMs}) {
  final ceiling = nowMs + kInboundClearCutoffMaxLead.inMilliseconds;
  return cutoffCreatedAtMs > ceiling ? ceiling : cutoffCreatedAtMs;
}

/// Что сервер ключей говорит о регистрации ЭТОГО устройства.
enum OwnDeviceRegistration { present, gone, unknown }

/// Отказ проверки «чьё это устройство», когда спрашивает само устройство.
///
/// Сервер сперва ищет ключ спрашивающего; удалённое устройство получает
/// `401 unknown requester device` (`verify_device_lookup_auth`). Только этот
/// ответ значит «регистрации больше нет». Сеть, часы, подпись — «неизвестно».
/// Решение о пришедшей служебной команде (реакция, очистка истории):
/// [convoId] — куда применить, иначе отказ; [deferrable] — отказ «пока не
/// знаем» (права или отправитель ещё не дошли), его паркуют, а не теряют.
typedef _InboundCommandVerdict = ({
  String? convoId,
  String senderPid,
  bool deferrable,
});

@visibleForTesting
OwnDeviceRegistration ownDeviceRegistrationFromLookupError(Object error) {
  final text = error.toString();
  if (text.contains('failed: 401 ') &&
      text.contains('unknown requester device')) {
    return OwnDeviceRegistration.gone;
  }
  return OwnDeviceRegistration.unknown;
}

