  final String? payloadEventId;
  final String text;
  final int matchStart;
  final int matchEnd;
  final int createdAtMs;

  /// Profile id of whoever wrote this message. `null` for own (outgoing)
  /// messages or when the sender's device can't be resolved locally. Used by
  /// the results-list screen (P2) to show the author's avatar + name.
  final String? senderProfileId;

  /// True when this message was sent by one of the current user's own devices
  /// (i.e. "me"). Lets the list render the self avatar/name without a lookup.
  final bool isOutgoing;
}

enum ChatListPreviewKind { text, photo, music, voice, file, link, empty }

class ChatListPreview {
  const ChatListPreview({
    required this.kind,
    required this.text,
    this.imageBlobIds = const <String>[],
    this.senderName,
    this.senderDeviceId,
    this.senderLocalState,
    this.mentionsSelf = false,
    this.isCall = false,
  });

  const ChatListPreview.empty()
    : kind = ChatListPreviewKind.empty,
      text = null,
      imageBlobIds = const <String>[],
      senderName = null,
      senderDeviceId = null,
      senderLocalState = null,
      mentionsSelf = false,
      isCall = false;

  final ChatListPreviewKind kind;
  final String? text;
  final List<String> imageBlobIds;

  /// Display name of whoever sent the last message (for room subtitle).
  final String? senderName;

  /// Device-id of the sender (for deterministic colour).
  final String? senderDeviceId;

  /// Состояние доставки последнего сообщения (`local_state` строки события).
  ///
  /// 🔴 Добавлено ради ГАЛОЧЕК В СПИСКЕ ЧАТОВ на десктопе (макет 14.09.2026):
  /// в строке, где последнее сообщение своё, справа стоит знак доставки. Поле
  /// НЕОБЯЗАТЕЛЬНОЕ и заполняется тем же проходом по событиям, которым уже
  /// собирается превью, — второго запроса к базе не появляется.
  ///
  /// Мобильная версия поля не читает, и её вид не меняется.
  final String? senderLocalState;

  /// В последнем сообщении упомянули МЕНЯ (по профилю или «@все»).
  ///
  /// 🔴 Тоже ради десктопа: в макете у строки с упоминанием счётчик залит
  /// другим цветом. Признак считается ЗДЕСЬ, а не в окне, потому что список
  /// упоминаний лежит внутри запечатанного payload, который здесь и так уже
  /// расшифрован, — окну пришлось бы расшифровывать его второй раз.
  ///
  /// Мобильная версия поля не читает.
  final bool mentionsSelf;

  /// Последнее событие — ЗВОНОК, а не сообщение.
  ///
  /// 🔴 Отдельным признаком, а НЕ новым значением `ChatListPreviewKind`:
  /// перечисление читает выпущенный телефон, и лишнее значение в нём заставило
  /// бы править его `switch`. Признак же он просто не смотрит.
  ///
  /// Нужен десктопу, чтобы дать строке зелёный значок трубки, как в макете:
  /// текст «Входящий звонок · 01:13» отличается от сообщения только словами, а
  /// в списке из тридцати строк слова читают последними.
  final bool isCall;
}

