    required this.groupId,
    required this.slug,
    required this.createdByProfileId,
    required this.expiresAtMs,
    required this.maxUses,
    required this.useCount,
    required this.requiresApproval,
    required this.allowedRole,
    required this.revoked,
    required this.createdAtMs,
    required this.updatedAtMs,
  });

  final String linkId;
  final String groupId;
  final String slug;
  final String createdByProfileId;
  final int? expiresAtMs;
  final int? maxUses;
  final int useCount;
  final bool requiresApproval;
  final RoomMemberRole allowedRole;
  final bool revoked;
  final int createdAtMs;
  final int updatedAtMs;

  int? get remainingUses {
    final limit = maxUses;
    if (limit == null) return null;
    final remaining = limit - useCount;
    return remaining <= 0 ? 0 : remaining;
  }

  bool isExpiredAt(int nowMs) {
    final expiresAt = expiresAtMs;
    return expiresAt != null && expiresAt <= nowMs;
  }

  bool get isUsageLimitReached {
    final remaining = remainingUses;
    return remaining != null && remaining <= 0;
  }

  String get internalDeepLinkUrl => buildRoomInviteDeepLink(
    slug: slug,
    createdByProfileId: createdByProfileId,
    groupIdHint: groupId,
  );

  String get shareUrl => buildRoomInviteShareLink(
    slug: slug,
    createdByProfileId: createdByProfileId,
    groupIdHint: groupId,
  );

  String get deepLinkUrl => shareUrl;

  String get telegramStyleUrl => 't.me/+$slug';
}

