const int kPeerOnlineFreshMs = 90 * 1000;

class Conversation {
  const Conversation({
    required this.convoId,
    required this.peerProfileId,
    required this.title,
    required this.avatarPath,
    required this.lastEventAtMs,
    required this.pinnedAtMs,
    required this.muted,
    required this.archivedAtMs,
    required this.autoDeleteSeconds,
    required this.emoji,
    this.unreadCount = 0,
    this.peerLastSeenAtMs,
    this.frameId,
    this.coverId,
    this.emojiStatus,
    this.premiumBadge = false,
  });

  final String convoId;
  final String? peerProfileId;
  final String title;
  final String? avatarPath;
  final int lastEventAtMs;
  final int? pinnedAtMs;
  final bool muted;
  final int? archivedAtMs;
  final int? autoDeleteSeconds;
  final String? emoji;

  /// Premium emoji status of the peer (cosmetic, from their profile_meta) — a
  /// single emoji shown next to the name. Null for groups / none.
  final String? emojiStatus;

  /// Whether the peer has a genuine paid tier (premium_badge) — premium star.
  final bool premiumBadge;

  /// Premium animated avatar frame id of the peer (cosmetic, from their
  /// profile_meta). Null for groups / no frame.
  final String? frameId;

  /// Premium animated profile cover id of the peer (cosmetic). Null for
  /// groups / no cover.
  final String? coverId;

  /// Number of unread incoming messages in this conversation.
  final int unreadCount;

  /// Last time the peer was seen online (milliseconds since epoch), or null if unknown.
  final int? peerLastSeenAtMs;

  /// Returns true if the peer was active within the last 5 minutes.
  bool get isOnline {
    final ts = peerLastSeenAtMs;
    if (ts == null) return false;
    return DateTime.now().millisecondsSinceEpoch - ts < kPeerOnlineFreshMs;
  }
}

