String buildRoomInviteDeepLink({
  required String slug,
  required String createdByProfileId,
  String? groupIdHint,
}) {
  final cleanedSlug = slug.trim();
  final inviterProfileId = createdByProfileId.trim();
  final cleanedGroupId = (groupIdHint ?? '').trim();
  return Uri(
    scheme: 'secretly',
    host: 'room-invite',
    pathSegments: <String>[cleanedSlug],
    queryParameters: <String, String>{
      'by': inviterProfileId,
      if (cleanedGroupId.isNotEmpty) 'group': cleanedGroupId,
    },
  ).toString();
}

const String kSecretlyAppLinkHost = 'links.secretlyapp.com';
const String kSecretlyAppLinkInstallPath = '/install';
const String kSecretlyAppLinkProfilePathPrefix = '/profile';
const String kSecretlyAppLinkRoomInvitePathPrefix = '/room-invite';
const Set<String> kSecretlySupportedAppLinkHosts = <String>{
  'links.secretlyapp.com',
  'www.secretlyapp.com',
  'secretlyapp.com',
};

String buildRoomInviteShareLink({
  required String slug,
  required String createdByProfileId,
  String? groupIdHint,
}) {
  final cleanedSlug = slug.trim();
  final inviterProfileId = createdByProfileId.trim();
  if (cleanedSlug.isEmpty || inviterProfileId.isEmpty) {
    return '';
  }
  final cleanedGroupId = (groupIdHint ?? '').trim();
  return Uri.https(
    kSecretlyAppLinkHost,
    '$kSecretlyAppLinkRoomInvitePathPrefix/$cleanedSlug',
    <String, String>{
      'by': inviterProfileId,
      if (cleanedGroupId.isNotEmpty) 'group': cleanedGroupId,
    },
  ).toString();
}

String normalizeSharedProfileId(String profileId) {
  return profileId.trim();
}

String buildProfileDeepLink({required String profileId}) {
  final normalizedProfileId = normalizeSharedProfileId(profileId);
  if (normalizedProfileId.isEmpty) {
    return '';
  }
  return Uri(
    scheme: 'secretly',
    host: 'profile',
    pathSegments: <String>[normalizedProfileId],
  ).toString();
}

String buildProfileShareLink({required String profileId}) {
  final normalizedProfileId = normalizeSharedProfileId(profileId);
  if (normalizedProfileId.isEmpty) {
    return '';
  }
  return Uri.https(
    kSecretlyAppLinkHost,
    '$kSecretlyAppLinkProfilePathPrefix/$normalizedProfileId',
  ).toString();
}

String? tryParseProfileShareUri(Uri uri) {
  if (uri.scheme == 'secretly' && uri.host == 'profile') {
    return _sharedProfileIdOrNull(uri.pathSegments.firstOrNull);
  }

  final scheme = uri.scheme.toLowerCase();
  final host = uri.host.toLowerCase();
  if ((scheme != 'https' && scheme != 'http') ||
      !kSecretlySupportedAppLinkHosts.contains(host)) {
    return null;
  }

  final pathSegments = uri.pathSegments
      .map((segment) => segment.trim())
      .where((segment) => segment.isNotEmpty)
      .toList(growable: false);
  if (pathSegments.isEmpty) {
    return _sharedProfileIdFromQuery(uri);
  }

  final firstSegment = pathSegments.first.toLowerCase();
  if (pathSegments.length >= 2 &&
      (firstSegment == 'profile' ||
          firstSegment == 'profiles' ||
          firstSegment == 'p' ||
          firstSegment == 'user')) {
    return _sharedProfileIdOrNull(pathSegments[1]);
  }
  if (pathSegments.length >= 2 &&
      (firstSegment == 'install' ||
          firstSegment == 'open' ||
          firstSegment == 'app')) {
    return _sharedProfileIdOrNull(pathSegments[1]) ??
        _sharedProfileIdFromQuery(uri);
  }
  if (firstSegment == 'install' ||
      firstSegment == 'open' ||
      firstSegment == 'app') {
    return _sharedProfileIdFromQuery(uri);
  }

  return _sharedProfileIdFromQuery(uri);
}

String? _sharedProfileIdFromQuery(Uri uri) {
  for (final key in const <String>['profile', 'profileId', 'user', 'id']) {
    final value = _sharedProfileIdOrNull(uri.queryParameters[key]);
    if (value != null) {
      return value;
    }
  }
  return null;
}

String? _sharedProfileIdOrNull(String? rawProfileId) {
  final normalizedProfileId = normalizeSharedProfileId(rawProfileId ?? '');
  return normalizedProfileId.isEmpty ? null : normalizedProfileId;
}

RoomInviteTarget? tryParseRoomInviteUri(Uri uri) {
  String slug = '';
  if (uri.scheme == 'secretly' && uri.host == 'room-invite') {
    slug = uri.pathSegments.firstOrNull?.trim() ?? '';
  } else {
    final scheme = uri.scheme.toLowerCase();
    final host = uri.host.toLowerCase();
    if ((scheme != 'https' && scheme != 'http') ||
        !kSecretlySupportedAppLinkHosts.contains(host)) {
      return null;
    }
    final pathSegments = uri.pathSegments
        .map((segment) => segment.trim())
        .where((segment) => segment.isNotEmpty)
        .toList(growable: false);
    if (pathSegments.isEmpty) {
      slug = (uri.queryParameters['slug'] ?? '').trim();
    } else {
      final firstSegment = pathSegments.first.toLowerCase();
      if (pathSegments.length >= 2 &&
          (firstSegment == 'room-invite' ||
              firstSegment == 'room-invites' ||
              firstSegment == 'invite')) {
        slug = pathSegments[1].trim();
      } else if (pathSegments.length >= 3 &&
          (firstSegment == 'install' ||
              firstSegment == 'open' ||
              firstSegment == 'app') &&
          (pathSegments[1].toLowerCase() == 'room-invite' ||
              pathSegments[1].toLowerCase() == 'room-invites' ||
              pathSegments[1].toLowerCase() == 'invite')) {
        slug = pathSegments[2].trim();
      } else {
        slug = (uri.queryParameters['slug'] ?? '').trim();
      }
    }
  }
  final inviterProfileId =
      (uri.queryParameters['by'] ?? uri.queryParameters['inviter'] ?? '')
          .trim();
  if (slug.isEmpty || inviterProfileId.isEmpty) {
    return null;
  }
  final groupIdHint =
      (uri.queryParameters['group'] ?? uri.queryParameters['groupId'] ?? '')
          .trim();
  return RoomInviteTarget(
    slug: slug,
    inviterProfileId: inviterProfileId,
    groupIdHint: groupIdHint.isEmpty ? null : groupIdHint,
  );
}

