/// Полоса `epoch_ahead` у одного устройства: когда началась и когда был
/// последний отказ. Два поля, а не одно, чтобы полосу закрывала ТИШИНА, а не
/// случайный успех под старой эпохой.
class _EpochAheadStreak {
  _EpochAheadStreak({required this.sinceMs, required this.lastFailureMs});

  final int sinceMs;
  int lastFailureMs;
}

/// Часы полосы `epoch_ahead` — вынесены отдельно, чтобы их можно было
/// проверить тестом.
///
/// 🔴 ЗАЧЕМ ОТДЕЛЬНО (12.09.2026). Правило реактивного сброса было верным и
/// покрыто шестнадцатью тестами, но ВСЕ они подавали `epochAheadStuckMs`
/// числом напрямую. Ни один не проверял, откуда это число берётся, — и дефект
/// жил ровно там: часы обнулялись каждой успешной расшифровкой, порог не
/// достигался никогда. Теперь часы — самостоятельная единица со своими
/// тестами, а время подаётся снаружи.
@visibleForTesting
class EpochAheadStreakClock {
  EpochAheadStreakClock({required this.gapMs});

  /// Тишина дольше этого закрывает полосу.
  final int gapMs;

  final Map<String, _EpochAheadStreak> _streaks = <String, _EpochAheadStreak>{};

  /// Отказ `epoch_ahead`. Возвращает, сколько уже длится полоса.
  int onEpochAheadFailure(String deviceId, int nowMs) {
    final dev = deviceId.trim();
    if (dev.isEmpty) return 0;
    final cur = _streaks[dev];
    if (cur == null || nowMs - cur.lastFailureMs > gapMs) {
      _streaks[dev] = _EpochAheadStreak(sinceMs: nowMs, lastFailureMs: nowMs);
      return 0;
    }
    cur.lastFailureMs = nowMs;
    return nowMs - cur.sinceMs;
  }

  /// Успешная расшифровка. Полосу закрывает ТОЛЬКО при тишине дольше [gapMs].
  void onDecryptSuccess(String deviceId, int nowMs) {
    final dev = deviceId.trim();
    if (dev.isEmpty) return;
    final cur = _streaks[dev];
    if (cur == null) return;
    if (nowMs - cur.lastFailureMs > gapMs) _streaks.remove(dev);
  }

  /// Сброс сессии — безусловная новая точка отсчёта.
  void clear(String deviceId) {
    final dev = deviceId.trim();
    if (dev.isNotEmpty) _streaks.remove(dev);
  }

  @visibleForTesting
  bool hasStreak(String deviceId) => _streaks.containsKey(deviceId.trim());
}

class CallSignalEvent {
  const CallSignalEvent({
    required this.action,
    required this.callId,
    required this.callAttemptId,
    required this.signalId,
    required this.fromProfileId,
    required this.fromDeviceId,
    required this.media,
    required this.screenShare,
    required this.sdp,
    required this.candidate,
    required this.sdpMid,
    required this.sdpMLineIndex,
    required this.createdAtMs,
  });

  final String action;
  final String callId;
  final String callAttemptId;
  final String signalId;
  final String fromProfileId;
  final String? fromDeviceId;
  final CallMedia media;
  final bool screenShare;
  final String? sdp;
  final String? candidate;
  final String? sdpMid;
  final int? sdpMLineIndex;
  final int createdAtMs;

  /// Сериализация для очереди сигналов через границу изолята.
  ///
  /// Поля пишутся ВСЕ: предложение (`sdp`) и кандидаты соединения нужны ровно
  /// так же, как приглашение, — без них звонок покажется и не соединится.
  Map<String, Object?> toJson() => <String, Object?>{
    'action': action,
    'call_id': callId,
    'call_attempt_id': callAttemptId,
    'signal_id': signalId,
    'from_profile_id': fromProfileId,
    'from_device_id': fromDeviceId,
    'media': media == CallMedia.video ? 'video' : 'audio',
    'screen_share': screenShare,
    'sdp': sdp,
    'candidate': candidate,
    'sdp_mid': sdpMid,
    'sdp_m_line_index': sdpMLineIndex,
    'created_at_ms': createdAtMs,
  };

  static CallSignalEvent? fromJson(Map<Object?, Object?> json) {
    final action = ((json['action'] as String?) ?? '').trim();
    final callId = ((json['call_id'] as String?) ?? '').trim();
    if (action.isEmpty || callId.isEmpty) return null;
    final attemptId = ((json['call_attempt_id'] as String?) ?? '').trim();
    final rawIndex = json['sdp_m_line_index'];
    return CallSignalEvent(
      action: action,
      callId: callId,
      callAttemptId: attemptId.isEmpty ? callId : attemptId,
      signalId: ((json['signal_id'] as String?) ?? '').trim(),
      fromProfileId: ((json['from_profile_id'] as String?) ?? '').trim(),
      fromDeviceId: (json['from_device_id'] as String?)?.trim(),
      media: ((json['media'] as String?) ?? '') == 'video'
          ? CallMedia.video
          : CallMedia.audio,
      screenShare: json['screen_share'] == true,
      sdp: json['sdp'] as String?,
      candidate: json['candidate'] as String?,
      sdpMid: json['sdp_mid'] as String?,
      sdpMLineIndex: rawIndex is num ? rawIndex.toInt() : null,
      createdAtMs: (json['created_at_ms'] as num?)?.toInt() ?? 0,
    );
  }
}

class RoomCallMediaSignalEvent {
  const RoomCallMediaSignalEvent({
    required this.action,
    required this.roomId,
    required this.callId,
    required this.sessionId,
    required this.signalId,
    required this.fromProfileId,
    required this.fromDeviceId,
    required this.descriptorVersion,
    required this.stateVersion,
    required this.reason,
    required this.createdAtMs,
  });

  final String action;
  final String roomId;
  final String callId;
  final String sessionId;
  final String signalId;
  final String fromProfileId;
  final String? fromDeviceId;
  final int descriptorVersion;
  final int stateVersion;
  final String reason;
  final int createdAtMs;
}

/// Raised by the inbound-journal write hook (see `onPlaintextBeforeCommit` in
/// `RatchetSessionManagerV3.decryptFromWire`) when it cannot durably capture a
/// just-decrypted plaintext. It signals `_handleDelivered` to leave the wire
/// un-acked so it re-decrypts cleanly next time — WITHOUT quarantining or
/// resetting the session, because the ciphertext is fine and only local
/// persistence hiccuped.
class _InboundJournalWriteException implements Exception {
  _InboundJournalWriteException(this.cause);
  final Object cause;
  @override
  String toString() => '_InboundJournalWriteException($cause)';
}

/// We could not LOOK UP the recipient's devices right now — the keys server
/// rate-limited us and we hold no cached device list to fall back on.
///
/// 🔴 The distinction this type exists to make (2026-07-31, field report
/// "rate_limit каждые 2-3 смс"): this says nothing about the recipient. Their
/// devices are fine; we simply could not ask. Treating it as "no deliverable
/// target" marked the message FAILED and put an error in the user's face for a
/// condition that resolves itself in seconds.
///
/// Callers must treat it exactly like "the peer has no devices YET": queue the
/// message durably and leave it pending. A stringly-typed `StateError` used to
/// carry this and nothing could tell it apart from a real failure.
class RecipientDevicesUnavailable implements Exception {
  RecipientDevicesUnavailable(this.reason);
  final String reason;
  @override
  String toString() => 'RecipientDevicesUnavailable($reason)';
}

/// D1 kill-switch (TZ_RELIABILITY_UX_2026-07-18): `false` restores the exact
/// pre-coalescing behaviour (every `.add` emits its own tick).
const bool kCoalesceChangedTicks = true;

/// E1 kill-switch (TZ_RELIABILITY_UX_2026-07-18): `false` sends images with
/// their original metadata (pre-2026-07-18 behaviour, EXIF GPS included).
const bool kStripImageMetadataOnSend = true;

/// D1 (TZ_RELIABILITY_UX_2026-07-18): burst-coalescing wrapper around the
/// app-wide `changed` StreamController.
///
/// One inbound message emits several `_changed.add(null)` in quick succession
/// (event insert + receipt + badge + convo touch, ~271 emit sites) and EVERY
/// tick rebuilds the whole chat screen and the chats list. This wrapper
/// collapses all `.add`s of one event-loop turn (including all of its
/// microtasks — `Timer.run` fires after they drain) into a single emission, so
/// a burst costs one rebuild instead of N. Latency cost is sub-frame.
///
/// Interface-compatible with the `StreamController<void>` surface the 271
/// call sites use (`.add(null)` / `.stream` / `.isClosed` / `.close()`), so
/// their diff is zero — the declaration swap is the whole change.
///
/// INVARIANT (I10, do not break): the changeVersion++/cache-invalidator
/// subscription is registered FIRST on [stream] and still observes every
/// (coalesced) emission before any UI listener — listener ordering is a
/// property of the underlying broadcast controller and is untouched here.
/// Nothing in the codebase awaits an individual tick (verified 2026-07-18),
/// so collapsing N ticks into 1 is observationally equivalent for every
/// listener; the terminal tick of a burst is never dropped.
class _CoalescedChangedController {
  final StreamController<void> _inner = StreamController.broadcast();
  bool _flushScheduled = false;

  Stream<void> get stream => _inner.stream;
  bool get isClosed => _inner.isClosed;

  void add(void _) {
    if (_inner.isClosed) return;
    if (!kCoalesceChangedTicks) {
      _inner.add(null);
      return;
    }
    if (_flushScheduled) return;
    _flushScheduled = true;
    Timer.run(() {
      _flushScheduled = false;
      if (!_inner.isClosed) _inner.add(null);
    });
  }

  Future<void> close() => _inner.close();
}

/// Outcomes of applying one room-key wire. Named so the ack-or-park rule in
/// [AppController.roomWireShouldPark] reads as the sentence it is.
enum RoomWireOutcome {
  /// Opened and the message inside was applied.
  applied,

  /// No key for this generation yet, or a position the chain already consumed.
  noKeyYet,

  /// The tag failed: wrong room, wrong generation, wrong position, or tampered.
  tagFailed,

  /// Authentic but the payload inside does not parse.
  innerMalformed,

  /// Opened, but the ordinary inbound path could not apply what was inside.
  innerNotApplied,

  /// A room envelope nested inside a room envelope.
  nested,

  /// Nothing to attribute the wire to.
  noSender,

  /// Local storage failed while opening.
  storeError,
}
